INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1647, 'The Recruit', 'A brilliant CIA trainee must prove his worth at the Farm, the agency''s secret training grounds, where he learns to watch his back and trust no one.', '2003-01-31', 6.40, 'https://image.tmdb.org/t/p/w500/xInKytrHV3EJeCAulOpn5Q0bMxh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1648, 'Bill & Ted''s Excellent Adventure', 'Two rock-''n-rolling teens, on the verge of failing their class, set out on a quest to make the ultimate school history report after being presented with a time machine.', '1989-02-17', 6.84, 'https://image.tmdb.org/t/p/w500/tV25lGWGWGEqUe3U0xjQTBgilSx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1548, 'Ghost World', 'Two quirky, cynical, teenaged girls try to figure out what to do with their lives following high school graduation. After they play a prank on an eccentric, middle-aged record collector, one of them befriends him, which causes a rift in the girls’ friendship.', '2001-07-20', 7.10, 'https://image.tmdb.org/t/p/w500/uwKqnUPE4dSM0kKuMW0vXpURh2T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1649, 'Bill & Ted''s Bogus Journey', 'Amiable slackers Bill and Ted are once again roped into a fantastical adventure when De Nomolos, a villain from the future, sends evil robot duplicates of the two lads to terminate and replace them. The robot doubles actually succeed in killing Bill and Ted, but the two are determined to escape the afterlife, challenging the Grim Reaper to a series of games in order to return to the land of the living.', '1991-07-19', 6.30, 'https://image.tmdb.org/t/p/w500/tldtDfLnPFOtTWp758EmIP2Hbz5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1652, '00 Schneider - Jagd auf Nihil Baxter', 'The funny clown Bratislav Metulskie is found dead in circus "Apollo". The retired commissioner 00 Schneider is asked to assume control of the case. Schneider and his aged sidekick Körschgen investigate to find the murderer.', '1994-12-21', 6.40, 'https://image.tmdb.org/t/p/w500/yPmbdbFTXgxhQARyYo1w2avXk77.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
