INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1653, 'The Motorcycle Diaries', 'Based on the journals of Che Guevara, leader of the Cuban Revolution. In his memoirs, Guevara recounts adventures he and best friend Alberto Granado had while crossing South America by motorcycle in the early 1950s.', '2004-02-06', 7.41, 'https://image.tmdb.org/t/p/w500/qz2aBYT8CAiJYvX4fRZpJ5G0Oz1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1654, 'The Dirty Dozen', '12 American military prisoners in World War II are ordered to infiltrate a well-guarded enemy château and kill the Nazi officers vacationing there. The soldiers, most of whom are facing death sentences for a variety of violent crimes, agree to the mission and the possible commuting of their sentences.', '1967-06-15', 7.60, 'https://image.tmdb.org/t/p/w500/tFWWsuhp22zJ6OG6QepJIiPUfeF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1656, 'The Legend of Zorro', 'Despite trying to keep his swashbuckling to a minimum, a threat to California''s pending statehood causes the adventure-loving Don Alejandro de la Vega and his wife, Elena, to take action.', '2005-10-24', 6.12, 'https://image.tmdb.org/t/p/w500/93iEBX1QbsxAv8eSybe8lhLXY1A.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1662, 'State of Grace', 'Hell''s Kitchen, New York. Terry Noonan returns home after a ten-year absence. He soon reconnects with Jackie, a childhood friend and member of the Irish mob, and rekindles his love affair with Jackie''s sister Kathleen.', '1990-09-14', 6.95, 'https://image.tmdb.org/t/p/w500/dNMeRLY3MeY2FFeh639plHai3F1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1659, 'Texas - Doc Snyder hält die Welt in Atem', 'The dreaded Doc Snyder returns home after 30 years. After his long ride through the prairies of the wild west, his laundry is extremely dirty, and who could wash it better than his unshaven mommy? But first she sends him to the prison, from which he is to free his brother Hank, because otherwise he will be hanged. When that''s done, they both spontaneously decide to rob a bank, which goes completely wrong. Before Doc Snyder''s eyes, his beloved brother is shot by his intimate enemy, the Nose Man. Snyder initially manages to escape, but the Nose Man takes up the pursuit, and from then on many innocent people have to die - including Snyder''s mother...', '1993-11-11', 6.05, 'https://image.tmdb.org/t/p/w500/ybD59vpUjk5xjW0rRBRxcLwdjms.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1621, 'Trading Places', 'A snobbish investor and a wily street con-artist find their positions reversed as part of a bet by two callous millionaires.', '1983-06-07', 7.23, 'https://image.tmdb.org/t/p/w500/8mBuLCOcpWnmYtZc4aqtvDXslv6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1669, 'The Hunt for Red October', 'A new technologically-superior Soviet nuclear sub, the Red October, is heading for the U.S. coast under the command of Captain Marko Ramius. The American government thinks Ramius is planning to attack. Lone CIA analyst Jack Ryan has a different idea: he thinks Ramius is planning to defect, but he has only a few hours to find him and prove it - because the entire Russian naval and air commands are trying to find Ramius, too. The hunt is on!', '1990-03-02', 7.38, 'https://image.tmdb.org/t/p/w500/yVl7zidse4KiWtGMqHFtZCx4X3N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1672, 'The Professional', 'Josselin Beaumont, a French secret agent, is tasked with assassinating Njala, the president for life of Malawi in Africa. A shift in French policy means that assassinating Njala is no longer an option. But instead of recalling their agent, high-ranking officials deliberately sacrifice Beaumont by handing him over to the Malawian authorities. Arrested, tried, and imprisoned, he nevertheless manages to escape. Back in Paris after a two-year absence, he informs his superiors through Colonel Martin that he will fulfill his contract during Njala’s upcoming official visit to Paris between the 12th and 15th of this month, and that he has a few scores to settle with the D.G.S.E. The question is, should Beaumont be stopped or not?', '1981-10-21', 7.18, 'https://image.tmdb.org/t/p/w500/dhAZ8T0tTlTNw3D7Cn8wc87sk1w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1599, 'I ♥ Huckabees', 'A husband-and-wife team play detective, but not in the traditional sense. Instead, the happy duo helps others solve their existential issues, the kind that keep you up at night, wondering what it all means.', '2004-09-10', 6.29, 'https://image.tmdb.org/t/p/w500/h27ytqXyOrAB6KmRx2abOp8p2W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1624, 'Liar Liar', 'Forced by his son''s birthday wish, fast-talking attorney and habitual liar Fletcher Reede must tell the truth for the next 24 hours.', '1997-03-21', 6.71, 'https://image.tmdb.org/t/p/w500/p1habYSdC7oD3WygQ5lynU5G5rV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1618, 'Still Crazy', 'In the 1970s, Strange Fruit were it. They lived the rock lifestyle to the max, groupies, drugs, internal tension and an ex front man dead from an overdose. Even their demise was glamorous; when lightning struck the stage during an outdoor festival. Twenty years on, these former rock gods they have now sunk deep into obscurity when the idea of a reunion tour is lodged in the head of Tony, former keyboard player of the Fruits. Tony sets out to find his former bandmates with the help of former manager Karen to see if they can recapture the magic and give themselves a second chance.', '1998-10-30', 6.80, 'https://image.tmdb.org/t/p/w500/o1k991eZm7iF8JUNiVdUZU44x5c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1620, 'Hitman', 'A genetically engineered assassin with deadly aim, known only as "Agent 47" eliminates strategic targets for a top-secret organization. But when he''s double-crossed, the hunter becomes the prey as 47 finds himself in a life-or-death game of international intrigue.', '2007-11-21', 6.17, 'https://image.tmdb.org/t/p/w500/h69UJOOKlrHcvhl5H2LY74N61DQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1551, 'Flatliners', 'Five medical students experiment with "near death" experiences, until the dark consequences of past tragedies begin to jeopardize their lives.', '1990-08-10', 6.52, 'https://image.tmdb.org/t/p/w500/wda3j7p7YHXKpFIlSzoTCtP7myF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
