INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1550, 'Pieces of April', 'Quirky and rebellious April Burns lives with her boyfriend in a low-rent New York City apartment miles away from her emotionally distant family. But when she discovers that her mother has a fatal form of breast cancer, she invites the clan to her place for Thanksgiving. While her father struggles to drive her family into the city, April -- an inexperienced cook -- runs into kitchen trouble and must ask a neighbor for help.', '2003-10-17', 6.53, 'https://image.tmdb.org/t/p/w500/qm3jGZwz2UkwwEFEFzSot8T0pz1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1666, 'The Bridge', 'The Bridge is a controversial documentary that shows people jumping to their death from the Golden Gate Bridge in San Francisco - the world''s most popular suicide destination. Interviews with the victims'' loved ones describe their lives and mental health.', '2006-10-27', 6.77, 'https://image.tmdb.org/t/p/w500/oAUA3oYIiDKwzKZoZuXEkHx6zG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
