INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1691, 'Hostel: Part II', 'Three American college students studying abroad are lured to a Slovakian hostel, and discover the grim reality behind it.', '2007-06-07', 5.85, 'https://image.tmdb.org/t/p/w500/qB20aiY8Ah3pQikkBxm3j7jQVc8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
