INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1725, 'West Side Story', 'In Manhattan’s Upper West Side, rival gangs of Polish-Americans and newly arrived Puerto Ricans clash for control of the neighborhood, even as two young members from opposite sides fall dangerously in love.', '1961-12-13', 7.20, 'https://image.tmdb.org/t/p/w500/nzCMu6D5q60i2bVrIQ0DxlRSgCZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
