INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1729, 'The Forbidden Kingdom', 'An American teenager who is obsessed with Hong Kong cinema and kung-fu classics makes an extraordinary discovery in a Chinatown pawnshop: the legendary stick weapon of the Chinese sage and warrior, the Monkey King. With the lost relic in hand, the teenager unexpectedly finds himself travelling back to ancient China to join a crew of warriors from martial arts lore on a dangerous quest to free the imprisoned Monkey King.', '2008-04-17', 6.65, 'https://image.tmdb.org/t/p/w500/z8chF1Z7hyuSVqLYTgElkQZh2VB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
