INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1776, 'Jesus Camp', 'A documentary on kids who attend a summer camp hoping to become the next Billy Graham.', '2006-09-15', 7.02, 'https://image.tmdb.org/t/p/w500/6ueSRBYaicEYvR2sFHVvptKNaxI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1779, 'Roger & Me', 'A documentary about the closure of General Motors'' plant at Flint, Michigan, which resulted in the loss of 30,000 jobs. Details the attempts of filmmaker Michael Moore to get an interview with GM CEO Roger Smith.', '1989-09-01', 7.10, 'https://image.tmdb.org/t/p/w500/ePVEnKOMtrIfHZ6wQBfWihTvwqD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
