INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1792, 'Stuck on You', 'In Martha''s Vineyard, Mass., conjoined twins Walt and Bob Tenor make the best of their handicap by being the fastest grill cooks in town. While outgoing Walt hopes to one day become a famous actor, shy Bob prefers to stay out of the spotlight. When a fading Hollywood actress, Cher, decides to get her show "Honey and the Beaze" cancelled, she hires Walt -- and his brotherly appendage -- as her costars. But their addition surprisingly achieves the opposite.', '2003-12-10', 5.36, 'https://image.tmdb.org/t/p/w500/5TmPGPsOP4EgMo8X14pyywxB1j2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1682, 'Mothra vs. Godzilla', 'Journalists Ichiro Sakai and Junko cover the wreckage of a typhoon when an enormous egg is found and claimed by greedy entrepreneurs. Mothra''s fairies arrive and are aided by the journalists in a plea for its return. As their requests are denied, Godzilla arises near Nagoya and the people of Infant Island must decide if they are willing to answer Japan''s own pleas for help.', '1964-04-29', 7.00, 'https://image.tmdb.org/t/p/w500/y49vvM03gpuyhpyMc1f55VrNkP3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1677, 'Ray', 'Born on a sharecropping plantation in Northern Florida, Ray Charles went blind at seven. Inspired by a fiercely independent mom who insisted he make his own way, He found his calling and his gift behind a piano keyboard. Touring across the Southern musical circuit, the soulful singer gained a reputation and then exploded with worldwide fame when he pioneered coupling gospel and country together.', '2004-10-29', 7.45, 'https://image.tmdb.org/t/p/w500/tSPC7sO2XYNL9QcMmK88tuUALL5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
