INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1678, 'Godzilla', 'Japan is thrown into a panic after several ships are sunk near Odo Island. An expedition to the island led by Dr. Kyohei Yamane soon discover something far more devastating than imagined in the form of a 50 meter tall monster whom the natives call Gojira. Now the monster begins a rampage that threatens to destroy not only Japan, but the rest of the world as well.', '1954-11-03', 7.63, 'https://image.tmdb.org/t/p/w500/2W0Yw0qrgVMgdsSCZRKtfvaAh0i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
