INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1824, '50 First Dates', 'Henry is a player skilled at seducing women. But when this veterinarian meets Lucy, a girl with a quirky problem when it comes to total recall, he realizes it''s possible to fall in love all over again…and again, and again. That''s because the delightful Lucy has no short-term memory, so Henry must woo her day after day until he finally sweeps her off her feet.', '2004-02-13', 6.88, 'https://image.tmdb.org/t/p/w500/lzUI2Cg7OMfcUNv3f7MywYNBjs6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1825, 'Over the Top', 'Lincoln Hawk a hard-luck big-rig trucker takes us under the glaring Las Vegas lights for all the boisterous action of the World Armwrestling Championship. Relying on wits and willpower, Hawk tries to rebuild his life by capturing the first-place prize money, and the love of the son he abandoned years earlier into the keeping of his rich, ruthless father-in-law.', '1987-02-13', 6.46, 'https://image.tmdb.org/t/p/w500/a926UPf4EYbHfjdzf012M5YHiQ5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
