INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1853, 'In the Realms of the Unreal', 'In the Realms of the Unreal is a documentary about the reclusive Chicago-based artist Henry Darger. Henry Darger was so reclusive that when he died his neighbors were surprised to find a 15,145-page manuscript along with hundreds of paintings depicting The Story of the Vivian Girls, in What is Known as the Realms of the Unreal, of the Glodeco-Angelinnian War Storm, Cased by the Child Slave Rebellion.', '2004-01-15', 7.21, 'https://image.tmdb.org/t/p/w500/lKxzlejHu8ApBZohNHMfbmIGzZd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
