INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2047, 'The Real McCoy', 'Karen McCoy is released from prison with nothing but the clothes on her back. Before being incarcerated, Karen was the bank robber of her time, but now she wishes for nothing more than to settle down and start a new life. Unfortunately, between a dirty parole officer, old business partners, and an idiot ex, she will have to do the unthinkable in order to save her son.', '1993-09-10', 5.70, 'https://image.tmdb.org/t/p/w500/6sZTcKhLRNp07cVoqgcMZoK9Noo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2048, 'I, Robot', 'In 2035, where robots are commonplace and abide by the three laws of robotics, a technophobic cop investigates an apparent suicide. Suspecting that a robot may be responsible for the death, his investigation leads him to believe that humanity may be in danger.', '2004-07-15', 6.97, 'https://image.tmdb.org/t/p/w500/efwv6F2lGaghjPpBRSINHtoEiZB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
