INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2054, 'Mr. Holland''s Opus', 'In 1965, passionate musician Glenn Holland takes a day job as a high school music teacher, convinced it''s just a small obstacle on the road to his true calling: writing a historic opus. As the decades roll by with the composition unwritten but generations of students inspired through his teaching, Holland must redefine his life''s purpose.', '1995-12-29', 6.96, 'https://image.tmdb.org/t/p/w500/kBmwWeSN3ajnYHZ3dSybEobxEPI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2056, 'The Station Agent', 'When his only friend dies, a man born with dwarfism moves to rural New Jersey to live a life of solitude, only to meet a chatty hot dog vendor and a woman dealing with her own personal loss.', '2003-12-05', 7.34, 'https://image.tmdb.org/t/p/w500/kjJg6eJa9I9flfHaJG67ecEv8YX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2057, 'Original Sin', 'A young man is plunged into a life of subterfuge, deceit and mistaken identity in pursuit of a femme fatale whose heart is never quite within his grasp.', '2001-05-08', 6.13, 'https://image.tmdb.org/t/p/w500/xvTtsdvvVr1NYlVJxWZibzhaEt5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2058, 'Addicted to Love', 'Good-natured astronomer Sam is devastated when the love of his life leaves him for a suave Frenchman. He therefore does what every other normal dumpee would do — go to New York and set up home in the abandoned building opposite his ex-girlfriend''s apartment, wait until she decides to leave her current lover, and then win her back.', '1997-05-23', 6.18, 'https://image.tmdb.org/t/p/w500/sRfuSc6E9GvVaOHdPv4vG3ywfMw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2059, 'National Treasure', 'Modern treasure hunters, led by archaeologist Ben Gates, search for a chest of riches rumored to have been stashed away by George Washington, Thomas Jefferson and Benjamin Franklin during the Revolutionary War. The chest''s whereabouts may lie in secret clues embedded in the Constitution and the Declaration of Independence, and Gates is in a race to find the gold before his enemies do.', '2004-11-19', 6.65, 'https://image.tmdb.org/t/p/w500/pxL6E4GBOPUG6CdkO9cUQN5VMwI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2020, 'The Bachelor', 'Jimmie is seeing his single friends get married one by one. He isn''t too worried until his girlfriend Anne catches the bouquet at his friend Marco''s wedding. Suddenly, his wild mustang days are numbered. He finally decides to propose to her, but he sticks his foot in his mouth and botches the proposal. Being insulted by the defeatist proposal, Anne leaves town on an assignment. After she''s gone, he finds out that his recently-deceased grandfather''s will stipulates that he gets nothing of a multi-million dollar fortune unless he''s married by 6:05pm on his 30th birthday: tomorrow! Not being able to find Anne, Jimmie begins backtracking through his past girlfriends to find a wife.', '1999-11-05', 5.10, 'https://image.tmdb.org/t/p/w500/zAF7cDx3SNqx6vjqgH2FLFM9pcm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2064, 'While You Were Sleeping', 'A transit worker pulls commuter Peter off railway tracks after he''s mugged, but—while he''s in a coma—his family mistakenly thinks she''s Peter''s fiancée, and she doesn''t correct them. Things get more complicated when she falls for his brother, who''s not quite sure that she''s who she claims to be.', '1995-04-21', 7.03, 'https://image.tmdb.org/t/p/w500/qNGO3ETcNwlWqK2kNRpbJSJRlos.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
