INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2071, 'Shattered', 'Dan Merrick comes out from a shattering car accident with amnesia. He finds that he is married to Judith who is trying to help him start his life again. He keeps getting flashbacks about events and places that he can''t remember. He meets pet shop owner and part time private detective Gus Klein who has supposedly done some work for him prior to the accident. Klein helps Merrick to find out more...', '1991-10-11', 6.15, 'https://image.tmdb.org/t/p/w500/k3UaQNJ8FAUaHgDhPyT3uEiod8h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
