INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2080, 'X-Men Origins: Wolverine', 'After seeking to live a normal life after 200 years, Logan sets out to avenge a death by undergoing the mutant Weapon X program and becoming Wolverine.', '2009-04-28', 6.29, 'https://image.tmdb.org/t/p/w500/yj8LbTju1p7CUJg7US2unSBk33s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2033, 'Infinity', 'Story of the early life of genius and Nobel Prize-winning physicist Richard Feynman.', '1996-10-04', 6.60, 'https://image.tmdb.org/t/p/w500/45cU6BNyRGKhDQZKzVSll4eTgwh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2084, 'Birthday Girl', 'John is a mild-mannered banker who has never been lucky in love. Fed up with waiting for the right girl to come along, John takes a chance on a Russian mail-order bride arranged via the Internet, where he is introduced to Nadia. John''s fondness for Nadia grows... until the sudden arrival of Nadia''s gregarious cousins makes John realize that he''s in over his head.', '2001-09-06', 5.90, 'https://image.tmdb.org/t/p/w500/jrwCiqQjEm3WqxHXxvAoW4gOsUd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2082, 'Halloween', 'The early years of young Michael Myers and the events leading up to his fateful Halloween night murder rampage in the quiet town of Haddonfield, Illinois.', '2007-08-31', 6.20, 'https://image.tmdb.org/t/p/w500/cD8JrfSEI4j7WVnKM1GdiYzMoUh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2085, 'Romeo Must Die', 'Two warring gang families (one African-American, the other Chinese) maneuver for bragging rights to the Oakland, California docks. Hang Sing and Trish O''Day uncover a trail of deceit that leaves most of the warring factions dead... or worse!', '2000-03-22', 6.29, 'https://image.tmdb.org/t/p/w500/zKrnaTWW63y4Q1XLrdZQyQmcRWd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2099, 'Raw Deal', 'Mark Kaminsky is kicked out of the FBI for his rough treatment of a suspect. He winds up as the sheriff of a small town in North Carolina. FBI Chief Harry Shannon, whose son has been killed by a mobster named Patrovina, enlists Kaminsky in a personal vendetta with a promise of reinstatement into the FBI if Patrovina is taken down. To accomplish this, he must go undercover and join Patrovina''s gang.', '1986-06-06', 5.85, 'https://image.tmdb.org/t/p/w500/1Y2GgDyNJFELoSIVlRhFQSs23Uo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2105, 'American Pie', 'At a high-school party, four friends find that losing their collective virginity isn''t as easy as they had thought. But they still believe that they need to do so before college. To motivate themselves, they enter a pact to all "score" by their senior prom.', '1999-07-09', 6.62, 'https://image.tmdb.org/t/p/w500/5P68by2Thn8wHAziyWGEw2O7hco.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2107, 'L.A. Story', 'With the help of a talking freeway billboard, a "wacky weatherman" tries to win the heart of an English newspaper reporter, who is struggling to make sense of the strange world of early-90s Los Angeles.', '1991-02-08', 6.51, 'https://image.tmdb.org/t/p/w500/At97val6UZyQoQtmH1b2Pe7bWqG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1970, 'The Grudge', 'An American nurse living and working in Tokyo is exposed to a mysterious supernatural curse, one that locks a person in a powerful rage before claiming their life and spreading to another victim.', '2004-10-22', 5.94, 'https://image.tmdb.org/t/p/w500/7vPAVPKYexQVmvC578wPLn2CGCL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2026, 'Hostage', 'When a mafia accountant is taken hostage on his beat, a police officer – wracked by guilt from a prior stint as a negotiator – must negotiate the standoff, even as his own family is held captive by the mob.', '2005-03-09', 6.36, 'https://image.tmdb.org/t/p/w500/vjhLmtjO2pMQXRgkxcwZoq2Ma8n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1978, 'Stage Fright', 'A struggling actress tries to help a friend prove his innocence when he''s accused of murdering the husband of a high-society entertainer.', '1950-02-23', 6.82, 'https://image.tmdb.org/t/p/w500/l43OTqhib8do1WwXig8JI8Y68Fd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2029, 'Tanguy', 'Tanguy is 28 years old and still living with his parents. They think it''s time he moves out. He doesn''t, so they hatch a plan.', '2001-11-21', 5.97, 'https://image.tmdb.org/t/p/w500/hTSALpAPB5ANmplvBqwChgv1Hun.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2114, 'Final Fantasy: The Spirits Within', 'Led by a strange dream, scientist Aki Ross struggles to collect the eight spirits in the hope of creating a force powerful enough to protect the planet. With the aid of the Deep Eyes Squadron and her mentor, Dr. Sid, Aki must save the Earth from its darkest hate and unleash the spirits within.', '2001-07-02', 6.20, 'https://image.tmdb.org/t/p/w500/47b1EwFqqSWxYna7NtUM7iML4oT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2043, 'Along Came a Spider', 'After the harrowing death of his partner, forensic psychologist and best-selling author Alex Cross cannot forgive himself and has retreated to the peace of retirement. But when a brilliant criminal kidnaps a senator''s young daughter, he is lured back into action as the kidnapper wants to deal with Alex personally. Teamed with Jezzie Flanigan, the Secret Service agent assigned to protect the missing girl, Alex follows a serpentine trail of clues that leads him to a stunning discovery - the kidnapper wants more than just ransom.', '2001-04-06', 6.34, 'https://image.tmdb.org/t/p/w500/vipRsbIpwUNf1gjfOcVNizQ1o3c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2108, 'The Breakfast Club', 'Five high school students from different walks of life endure a Saturday detention under a power-hungry principal. The disparate group includes rebel John, princess Claire, outcast Allison, brainy Brian and Andrew, the jock. Each has a chance to tell his or her story, making the others see them a little differently -- and when the day ends, they question whether school will ever be the same.', '1985-02-15', 7.72, 'https://image.tmdb.org/t/p/w500/gp4zlj7wgbiofLMNsTPndMuO3PN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2039, 'Moonstruck', '37-year-old Italian-American widow Loretta Castorini believes she is unlucky in love, and so accepts a marriage proposal from her boyfriend Johnny, even though she doesn''t love him. When she meets his estranged younger brother Ronny, an emotional and passionate man, she finds herself drawn to him. She tries to resist, but Ronny, who blames his brother for the loss of his hand, has no scruples about aggressively pursuing her while Johnny is out of the country. As Loretta falls for Ronny, she learns that she''s not the only one in her family with a secret romance.', '1987-12-16', 6.84, 'https://image.tmdb.org/t/p/w500/2mnVWpvsHEHHnfvLn1NXYVvBGl5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1988, 'A Mighty Heart', 'Based on Mariane Pearl''s account of the terrifying and unforgettable story of her husband, Wall Street Journal reporter Danny Pearl''s life and death.', '2007-06-22', 6.39, 'https://image.tmdb.org/t/p/w500/z5f7KPg8vqqYXtaF0wUkSWryDIg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2123, 'Me, Myself & Irene', 'Rhode Island State Trooper Charlie Baileygates has a multiple personality disorder. One personality is crazy and aggressive, while the other is more friendly and laid back. Both of these personalities fall in love with the same woman named Irene after Charlie loses his medication.', '2000-06-22', 6.62, 'https://image.tmdb.org/t/p/w500/rvRrcbLbpn7UJGRH1JupgHOeJFq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1989, 'My Blueberry Nights', 'Elizabeth has just been through a particularly nasty breakup, and now she''s ready to leave her friends and memories behind as she chases her dreams across the country. In order to support herself on her journey, Elizabeth picks up a series of waitress jobs along the way. As Elizabeth crosses paths with a series of lost souls whose yearnings are even greater than her own, their emotional turmoil ultimately helps her gain a greater understanding of her own problems...', '2007-11-28', 6.40, 'https://image.tmdb.org/t/p/w500/w9w3m2IB9QRZXxi6R51ZamKv3HS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2133, 'The Perfect Storm', 'In October 1991, a confluence of weather conditions combined to form a killer storm in the North Atlantic. Caught in the storm was the sword-fishing boat Andrea Gail.', '2000-06-29', 6.49, 'https://image.tmdb.org/t/p/w500/vJPoxqgpfFNbGi0HyoNsjFeLCio.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2124, 'Color of Night', 'A color-blind psychiatrist is stalked by an unknown killer after taking over his murdered friend''s therapy group and becomes embroiled in an intense affair with a mysterious woman who may be connected to the crime.', '1994-08-19', 5.76, 'https://image.tmdb.org/t/p/w500/w1OBPkf3BxeC7543YzFwiKIwBFJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2135, 'The Time Machine', 'Hoping to alter the events of the past, a 19th-century inventor instead travels 800,000 years into the future, where he finds mankind divided into two warring races.', '2002-03-04', 6.34, 'https://image.tmdb.org/t/p/w500/iYayQahkghlbAsfOQX8b5eBzGVy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2134, 'The Time Machine', 'A Victorian Englishman travels to the far future and finds that humanity has divided into two hostile species.', '1960-05-25', 7.36, 'https://image.tmdb.org/t/p/w500/sotBnRlFJ67cPisjAUXzbPxi9kC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2110, 'Wasabi', 'Hubert is a French policeman with very sharp methods. After being forced to take 2 months off by his boss, who doesn''t share his view on working methods, he goes back to Japan, where he used to work 19 years ago, to settle the probate of his girlfriend who left him shortly after marriage without a trace.', '2001-10-31', 6.65, 'https://image.tmdb.org/t/p/w500/uo3MBDwn3o32GJzFyClm7r1ierb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2140, 'Kiss of the Dragon', 'Liu Jian, an elite Chinese police officer, comes to Paris to arrest a Chinese drug lord. When Jian is betrayed by a French officer and framed for murder, he must go into hiding and find new allies.', '2001-07-06', 6.94, 'https://image.tmdb.org/t/p/w500/1ubtSyagwfNF9Bn9s2CKITRtx1d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2142, 'Cop Land', 'Freddy Heflin is the sheriff of a place everyone calls “Cop Land” — a small and seemingly peaceful town populated by the big city police officers he’s long admired. Yet something ugly is taking place behind the town’s peaceful facade. And when Freddy uncovers a massive, deadly conspiracy among these local residents, he is forced to take action and make a dangerous choice between protecting his idols and upholding the law.', '1997-08-15', 6.81, 'https://image.tmdb.org/t/p/w500/dyOqXyPCQh8VF0KA5aelBCCQond.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2148, 'The Cotton Club', 'Harlem''s legendary Cotton Club becomes a hotbed of passion and violence as the lives and loves of entertainers and gangsters collide.', '1984-12-14', 6.47, 'https://image.tmdb.org/t/p/w500/jgCsLhIRLKlvUy1p1iImCi0nPnX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2144, 'One Night at McCool''s', 'On an ordinary night, in an ordinary part of town, a beautiful young woman walks into a bar. Her name is Jewel, and before long she is chatting to bartender Randy. The pair leave together, but he ends up getting into a tussle with her criminal boyfriend, who she then shoots dead, later persuading Randy to take the rap for her. But this isn''t the end of it, as both Randy''s cousin Carl and the detective assigned to the murder case also fall for Jewel''s charms and find themselves caught up in the ensuing events. It seems that any man who meets Jewel falls instantly in love with her, and she''s going to use this fully to her own advantage, leaving a trail of havoc in her wake. It also seems that she is going to get away with it - that is, until Randy decides to hire a hitman...', '2001-04-19', 5.87, 'https://image.tmdb.org/t/p/w500/aIJAjhdMqraB1tkSii9BWuUXd8q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2149, 'Body of Evidence', 'When an elderly millionaire is found dead with cocaine in his system, his will leaves $8 million to Rebecca Carlson, who was having an affair with him. District attorney Robert Garrett decides to prosecute Rebecca, arguing that she deliberately engaged in wild sex with the old man to overexcite him and lead to his premature death. Defense attorney Frank Dulaney defends Rebecca in court while getting sucked into a dangerous affair with her.', '1993-01-15', 4.98, 'https://image.tmdb.org/t/p/w500/rGDfwZHRMpY5R0ZkmaiHHvpYQKB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2152, 'Dixie Chicks: Shut Up and Sing', 'Shut Up and Sing is a documentary about the country band from Texas called the Dixie Chicks and how one tiny comment against President Bush dropped their number one hit off the charts and caused fans to hate them, destroy their CD’s, and protest at their concerts. A film about freedom of speech gone out of control and the three girls lives that were forever changed by a small anti-Bush comment', '2006-10-27', 6.68, 'https://image.tmdb.org/t/p/w500/7aZ8uWvCckLTbalbiqut3Vrt33c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (1990, 'Paranoid Park', 'A teenage skateboarder becomes suspected of being connected with a security guard who suffered a brutal death in a skate park called "Paranoid Park".', '2007-07-12', 6.52, 'https://image.tmdb.org/t/p/w500/qdxQ8vZJoZuLqU9MXYW2vnRwhan.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2155, 'Reindeer Games', 'After assuming his dead cellmate''s identity to get with his girlfriend, an ex-con finds himself the reluctant participant in a casino heist.', '2000-02-25', 5.71, 'https://image.tmdb.org/t/p/w500/8y1PedfYWllJVoBbkt9KWLY155v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2157, 'Lost in Space', 'The prospects for continuing life on Earth in the year 2058 are grim. So the Robinsons are launched into space to colonize Alpha Prime, the only other inhabitable planet in the galaxy. But when a stowaway sabotages the mission, the Robinsons find themselves hurtling through uncharted space.', '1998-04-03', 5.45, 'https://image.tmdb.org/t/p/w500/fCocPDUFuKswY2GxDdfYsT9BXMd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
