INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2163, 'Breakdown', 'On their cross-country drive, a married couple, Jeff and Amy Taylor, experience car trouble after their SUV breaks down. Stranded in the New Mexico desert, the two catch a break when a passing truck driver offers Amy a ride to a nearby café to call for help. Meanwhile, Jeff is able to fix the car and make his way to the café, but Amy isn''t there. He tracks down the trucker ― who tells the police he''s never seen Jeff or his wife before. Jeff then begins a desperate, frenzied search for Amy.', '1997-05-02', 6.94, 'https://image.tmdb.org/t/p/w500/m3VB59ppr1RlpxNUYRUfZTgjgU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
