INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2122, 'The Whole Ten Yards', 'Jimmy "The Tulip" Tudeski now spends his days compulsively cleaning his house and perfecting his culinary skills with his wife, Jill, a purported assassin who has yet to pull off a clean hit. Suddenly, an uninvited and unwelcome connection to their past unexpectedly shows up on Jimmy and Jill''s doorstep; it''s Oz, and he''s begging them to help him rescue his wife, Cynthia.', '2004-04-07', 5.74, 'https://image.tmdb.org/t/p/w500/4fbglyCpPqK1u40fhncLXKAF74A.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
