INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (2179, 'Tenacious D in The Pick of Destiny', 'In Venice Beach, naive Midwesterner JB bonds with local slacker KG and they form the rock band Tenacious D. Setting out to become the world''s greatest band is no easy feat, so they set out to steal what could be the answer to their prayers... a magical guitar pick housed in a rock-and-roll museum some 300 miles away.', '2006-11-22', 6.79, 'https://image.tmdb.org/t/p/w500/8baHzEIfrBvBy5b9XKe87Skl1tf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
