INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (8340, 'Turtles Can Fly', 'Turtles Can Fly tells the story of a group of young children near the Turkey-Iraq border. They clean up mines and wait for the Saddam regime to fall.', '2004-09-10', 7.75, 'https://image.tmdb.org/t/p/w500/mnJ462tp8uy2PyF1DlFjzdeQuyf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (7872, 'The Road to Guantanamo', 'Part drama, part documentary, The Road to Guantánamo focuses on the Tipton Three, a trio of British Muslims who were held in Guantanamo Bay for two years until they were released without charge.', '2006-03-09', 6.87, 'https://image.tmdb.org/t/p/w500/deM5htQLvRjcRkeIFtaOdd5TDrC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (8346, 'My Big Fat Greek Wedding', 'A young Greek woman falls in love with a non-Greek and struggles to get her family to accept him while she comes to terms with her heritage and cultural identity.', '2002-04-19', 6.50, 'https://image.tmdb.org/t/p/w500/ztc05ym0T3stnBpRHdxEs3Zwsmp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (7873, 'Harsh Times', 'Jim Davis is an ex-Army Ranger who finds himself slipping back into his old life of petty crime after a job offer from the LAPD evaporates. His best friend is pressured by his girlfriend Sylvia to find a job, but Jim is more interested in hanging out and making cash from small heists, while trying to get a law enforcement job so he can marry his Mexican girlfriend.', '2005-09-11', 6.43, 'https://image.tmdb.org/t/p/w500/raBWBnGz2X6FQ3iUwPwYQE4FrkY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (8052, 'Hard Eight', 'A stranger mentors a young Reno gambler who weds a hooker and befriends a vulgar casino regular.', '1997-02-28', 6.84, 'https://image.tmdb.org/t/p/w500/1l5UaoP25Ak8PWCKIULQz70yF03.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (8129, 'My Name Is Joe', 'Two thirtysomethings, unemployed former alcoholic Joe and community health worker Sarah, start a romantic relationship in one of the toughest Glasgow neighbourhoods.', '1998-05-15', 7.30, 'https://image.tmdb.org/t/p/w500/3qUWbQjtNQFX26QOENPIkck9KOJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (8338, 'Blindness', 'When a sudden plague of blindness devastates a city, a small group of the afflicted band together to triumphantly overcome the horrific conditions of their imposed quarantine.', '2008-05-14', 6.53, 'https://image.tmdb.org/t/p/w500/deBsx5IxyqCC217j3VY24TkkE0Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (8202, 'Æon Flux', '400 years into the future, disease has wiped out the majority of the world''s population, except one walled city, Bregna, ruled by a congress of scientists. When Æon Flux, the top operative in the underground ''Monican'' rebellion, is sent on a mission to kill a government leader, she uncovers a world of secrets.', '2005-11-30', 5.64, 'https://image.tmdb.org/t/p/w500/5958Nt4QX6aRSUdQnvNw8wqjTJQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
