INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (8388, '¡Three Amigos!', 'A trio of unemployed silent film actors are mistaken for real heroes by a small Mexican village in search of someone to stop a malevolent bandit.', '1986-12-12', 6.33, 'https://image.tmdb.org/t/p/w500/dUNRnhl2cwjFJ6TOsaPJmZeMZ0S.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (8386, 'How High', 'Jamal and Silas, two ordinary guys who smoke something magical, pass their college entrance exams with flying colors and end up at Harvard. Ivy League ways are strange but Silas and Jamal take it in a stride -- until their supply of supernatural smoke runs dry. That''s when they have to start living by their wits and rely on their natural resources to make the grade.', '2001-12-21', 6.37, 'https://image.tmdb.org/t/p/w500/qWF784YqUZE8KhbBfuqhMSzmUPs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
