INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (8391, 'When Night Is Falling', 'Camille is a professor at a Protestant college and is in a long-term relationship with Martin, a respected minister and fellow professor. When Camille meets Petra, a bold and flamboyant performer in a circus troupe, she is inexplicably drawn. Pursuing Petra, Camille throws her whole conservative life into disarray.', '1995-02-01', 6.30, 'https://image.tmdb.org/t/p/w500/6Ac5GLwJ01uli5mCXqXwquR36Y1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
