INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11517, 'Money Train', 'When a vengeful New York transit cop decides to steal a trainload of subway fares, his foster brother—a fellow cop—tries to protect him.', '1995-11-21', 5.86, 'https://image.tmdb.org/t/p/w500/jWBDz6Mf9aQVBiUS76JQsEhvoJl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11631, 'Mamma Mia!', 'A spirited young bride-to-be living with her single mother on a small Greek island secretly invites three of her mother''s ex-boyfriends in hope of finding her biological father to walk her down the aisle.', '2008-07-03', 7.00, 'https://image.tmdb.org/t/p/w500/xYLiCWmAMHJubx5jNZ7HuXKjAbV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11519, '1941', 'In the days after the attack on Pearl Harbor, panic grips California, where a military officer leads a mob chasing a Japanese sub.', '1979-12-14', 5.76, 'https://image.tmdb.org/t/p/w500/52Bn5yC6IHQuVxPUza3Q6RZCZTu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11577, 'Pat Garrett & Billy the Kid', 'Pat Garrett is hired as a lawman on behalf of a group of wealthy New Mexico cattle barons to bring down his old friend Billy the Kid.', '1973-05-23', 7.21, 'https://image.tmdb.org/t/p/w500/o0LXWfTXoDOoeYzZw0u1KmZhVIL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11637, 'Are We There Yet?', 'The fledgling romance between Nick, a playboy bachelor, and Suzanne, a divorced mother of two, is threatened by a particularly harrowing New Years Eve. When Suzanne''s work keeps her in Vancouver for the holiday, Nick offers to bring her kids to the city from Portland, Oregon. The kids, who have never liked any of the men their mom dates, are determined to turn the trip into a nightmare for Nick.', '2005-01-20', 5.72, 'https://image.tmdb.org/t/p/w500/guDkMD4wrZ1BGUO7DFFBVzaiGij.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11630, '3 Men and a Little Lady', 'Sylvia''s work increasingly takes her away from the three men who help bring up Mary, her daughter. When she decides to move to England and take Mary with her, the three men are heartbroken at losing the two most important women in their lives.', '1990-11-21', 5.85, 'https://image.tmdb.org/t/p/w500/4VWWEnhX0zddRKwZWGtIdDcV5U7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11575, 'The Great Race', 'Professional daredevil and white-suited hero, The Great Leslie, convinces turn-of-the-century auto makers that a race from New York to Paris (westward across America, the Bering Straight and Russia) will help to promote automobile sales. Leslie''s arch-rival, the mustached and black-attired Professor Fate vows to beat Leslie to the finish line in a car of Fate''s own invention.', '1965-07-01', 7.10, 'https://image.tmdb.org/t/p/w500/9rL8GWuFdO3fLXcNV9rZRHskoOn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11522, 'Pretty in Pink', 'Andie is an outcast, hanging out either with her older boss, who owns the record store where she works, or her quirky high school classmate Duckie, who has a crush on her. When one of the rich and popular kids at school, Blane, asks Andie out, it seems too good to be true. As Andie starts falling for Blane, she begins to realize that dating someone from a different social sphere is not easy.', '1986-02-28', 6.68, 'https://image.tmdb.org/t/p/w500/jeFJyzJBufJexpOuywuPp8q2tCJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11527, 'Excalibur', 'Arthur fulfills his fate by bringing together the Knights of the Round Table at Camelot and unifying the country. However, this flawed monarch faces greater tests ahead in pursuit of love, the Holy Grail, and his nation''s survival.', '1981-04-10', 6.96, 'https://image.tmdb.org/t/p/w500/cTWF6zkr5mUOnheowKODIijWYcN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11658, 'Tae Guk Gi: The Brotherhood of War', 'When two brothers are forced to fight in the Korean War, the elder decides to take the riskiest missions if it will help shield the younger from battle.', '2004-02-05', 7.99, 'https://image.tmdb.org/t/p/w500/efc2MwDwvQsYsbxLXaXtlmOJ7LZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11638, 'Guess Who', 'When a young African-American woman brings her fiancé home to meet her parents, she''s neglected to mention one tiny detail – he''s white.', '2005-03-25', 6.00, 'https://image.tmdb.org/t/p/w500/8BF6qSAANBvhEPZxQVTUiZbfiOy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11659, 'The Best of Youth', 'After a fateful encounter in the summer of 1966, the lifepaths of two brothers from a middle-class Roman family diverge, intersecting with some of the most significant events of postwar Italian history in the following decades.', '2003-06-22', 8.03, 'https://image.tmdb.org/t/p/w500/ltmcFRvTeAgBgMLUGa15KzDSQqs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11660, 'Following', 'Bill, an idle, unemployed aspiring writer, walks the crowded streets of London following randomly chosen strangers, a seemingly innocent entertainment that becomes dangerous when he crosses paths with a mysterious character.', '1999-04-02', 7.12, 'https://image.tmdb.org/t/p/w500/3bX6VVSMf0dvzk5pMT4ALG5A92d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11661, 'Joyeux Noel', 'France, 1914, during World War I. On Christmas Eve, an extraordinary event takes place in the bloody no man''s land that the French and the Scots dispute with the Germans…', '2005-11-09', 7.35, 'https://image.tmdb.org/t/p/w500/9Ka8lKCIiWjnZiMslPQeakS5UhW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11663, 'The Commitments', 'Jimmy Rabbitte, just a thick-ya out of school, gets a brilliant idea: to put a soul band together in Barrytown, his slum home in north Dublin. First he needs musicians and singers: things slowly start to click when he finds three fine-voiced females virtually in his back yard, a lead singer (Deco) at a wedding, and, responding to his ad, an aging trumpet player, Joey "The Lips" Fagan.', '1991-08-14', 7.25, 'https://image.tmdb.org/t/p/w500/iccBDq9aS1gwi6b8aJjBgPU4t2D.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11662, 'Casshern', 'Fifty years of war between the Great Eastern Federation and Europa - now merged as Eurasia - have taken their toll on planet Earth. As a result of the use of biological, chemical and nuclear weapons, much of Earth has become uninhabitable and people have become prey to new diseases. Professor Azuma''s "neo-cell" project, which is supposed to be the answer to mankind''s hardships, becomes a nightmare come true when mutants spawned from the experiment escape and declare war on the human race. Azuma''s son Tetsuya, who was killed during the previous war, is reborn into the cyborg Casshern as mankind''s last hope against the new mutant threat. This live-action sci-fi movie based on a 1973 Japanese animé of the same name.', '2004-04-24', 5.86, 'https://image.tmdb.org/t/p/w500/naIjHWfQFge69GqeehgsekwDkbl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11665, 'Get Smart', 'When members of the nefarious crime syndicate KAOS attack the U.S. spy agency Control and the identities of secret agents are compromised, the Chief has to promote hapless but eager analyst Maxwell Smart to field agent. He is partnered with veteran and capable Agent 99, the only spy whose cover remains intact. Can they work together to thwart the evil world-domination plans of KAOS and its crafty operative?', '2008-06-19', 6.22, 'https://image.tmdb.org/t/p/w500/sZUjbtUS8qxXp4mj90evnqPJqX7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11667, 'Street Fighter', 'Colonel Guile and various other martial arts heroes fight against the tyranny of dictator M. Bison and his cohorts.', '1994-12-23', 4.68, 'https://image.tmdb.org/t/p/w500/6yh95dD2Y6uWAlPfWCZZygBM1ec.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11674, '101 Dalmatians', 'An evil, high-fashion designer plots to steal Dalmatian puppies in order to make an extravagant fur coat, but instead creates an extravagant mess.', '1996-11-27', 5.95, 'https://image.tmdb.org/t/p/w500/8o2ADoAyG796UwTjwBFjPyBz0yG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11673, 'Cyrano de Bergerac', 'Famed swordsman and poet Cyrano de Bergerac is in love with his cousin Roxane. He has never expressed his love for her as he his large nose undermines his self-confidence. Then he finds a way to express his love to her, indirectly.', '1990-03-28', 7.32, 'https://image.tmdb.org/t/p/w500/80XJ5UkGuYTKDuALeG03BLk1OT1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11678, 'Vertical Limit', 'Trapped near the summit of K2, the world''s second-highest mountain, Annie Garrett radios to base camp for help. Brother Peter hears Annie''s message and assembles a team to save her and her group before they succumb to K2''s unforgiving elements. But, as Annie lays injured in an icy cavern, the rescuers face several terrifying events that could end the rescue attempt -- and their lives.', '2000-12-08', 6.02, 'https://image.tmdb.org/t/p/w500/kpqQUEi8eAyYHMDFACf6YlnPIu7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11676, 'Nothing to Lose', 'Advertising executive Nick Beame learns that his wife is sleeping with his employer. In a state of despair, he encounters a bumbling thief whose attempted carjacking goes awry when Nick takes him on an involuntary joyride. Soon the betrayed businessman and the incompetent crook strike up a partnership and develop a robbery-revenge scheme. But it turns out that some other criminals in the area don''t appreciate the competition.', '1997-07-18', 6.58, 'https://image.tmdb.org/t/p/w500/umbzQyRMeB1oHTKiymTlH591xNB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11675, 'Halloween H20: 20 Years Later', 'Two decades after surviving a massacre on October 31, 1978, former baby sitter Laurie Strode finds herself hunted by persistent knife-wielder Michael Myers. Laurie now lives in Northern California under an assumed name, where she works as the headmistress of a private school. But it''s not far enough to escape Myers, who soon discovers her whereabouts. As Halloween descends upon Laurie''s peaceful community, a feeling of dread weighs upon her -- with good reason.', '1998-08-05', 6.00, 'https://image.tmdb.org/t/p/w500/lqLXUm3oK59sGJKRH2Zjj2m3iMg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11679, 'xXx: State of the Union', 'Darius Stone''s criminal record and extreme sports obsession make him the perfect candidate to be the newest XXX agent. He must save the U.S. government from a deadly conspiracy led by five-star general and Secretary of Defense George Deckert.', '2005-04-27', 5.10, 'https://image.tmdb.org/t/p/w500/nL9J0N3HJSdZTKRsd5xcE6IzL5s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11683, 'Land of the Dead', 'The living dead have taken over the world, and the remaining humans live in a walled city to protect themselves as they cope with the situation.', '2005-06-18', 6.26, 'https://image.tmdb.org/t/p/w500/xxp0qcZ3n2YA53SIzWilDSfIaA4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11648, 'Must Love Dogs', 'Sarah Nolan is a newly divorced woman cautiously rediscovering romance with the enthusiastic but often misguided help of her well-meaning family. As she braves a series of hilarious disastrous mismatches and first dates, Sarah begins to trust her own instincts again and learns that, no matter what, it''s never a good idea to give up on love.', '2005-07-21', 5.93, 'https://image.tmdb.org/t/p/w500/252PdRj3y2S05DC4oSf2qk2vva3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11576, 'It''s a Mad, Mad, Mad, Mad World', 'A group of strangers come across a man dying after a car crash who proceeds to tell them about the $350,000 he buried in California. What follows is the madcap adventures of those strangers as each attempts to claim the prize for himself.', '1963-11-07', 6.98, 'https://image.tmdb.org/t/p/w500/j4mWzOisSHFkaqIkq34l2mm8a5K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11686, 'Love and Death', 'In czarist Russia, a neurotic soldier and his distant cousin formulate a plot to assassinate Napoleon.', '1975-06-10', 7.45, 'https://image.tmdb.org/t/p/w500/oJXFd1UHZoOQ1UtoLxbyBLGJDox.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11632, 'Vanity Fair', 'In early 19th century England, orphaned Becky Sharp defies her poverty-stricken background and ascends the social ladder alongside her best friend.', '2004-09-01', 5.78, 'https://image.tmdb.org/t/p/w500/6GCjrrd1XIl8VSwjKo8c94LTwtd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11687, 'The Visitors', 'After a wizard''s spell goes awry, 12th-century Gallic knight Godefroy de Papincourt, Count of Montmirail finds himself transported to 1993, along with his dimwitted servant, Jacquouille la Fripouille. Startled and perplexed by modern technology, the duo run amok, destroying cars and causing chaos until they meet Beatrice de Montmirail, an aristocratic descendant of the nobleman, who may be able to help them get back to 1123.', '1993-01-27', 7.13, 'https://image.tmdb.org/t/p/w500/hPCq0buG5PaXgKjzT2ktjrjlpbj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11688, 'The Emperor''s New Groove', 'When the self‑absorbed Emperor Kuzco is accidentally transformed into a llama, he must rely on a humble villager to survive the jungle and reclaim his throne.', '2000-12-15', 7.57, 'https://image.tmdb.org/t/p/w500/wwbgkXQBEKtnyIJapk6gUgWkVw8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11692, 'The Adventures of Pluto Nash', 'The year is 2087, the setting is the moon. Pluto Nash, the high-flying successful owner of the hottest nightclub in the universe, finds himself in trouble when he refuses to sell his club to lunar gangster Mogan, who just happens to be helping the mysterious Rex Crater mastermind a plan to take over the entire moon.', '2002-08-16', 4.38, 'https://image.tmdb.org/t/p/w500/96vvhLWWDosS1zRrfQ6XEGAzByL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11690, 'Bloodsport', 'An American Army Major goes AWOL to Hong Kong for an outlawed martial arts contest called the Kumite.', '1988-02-26', 7.06, 'https://image.tmdb.org/t/p/w500/kndxR9TRK0kJ5hxzDprRSS80F2W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11689, 'Crime Busters', 'An attempted robbery turns to be an unexpected recruitment when two unemployed men mistakenly break into a police office instead of a store.', '1977-04-01', 7.00, 'https://image.tmdb.org/t/p/w500/z35E0qY8wkkSPIBT5ptQAyWvr8k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11699, 'Bad Lieutenant: Port of Call New Orleans', 'Terrence McDonagh is a New Orleans Police sergeant, who receives a medal and a promotion to lieutenant for heroism during Hurricane Katrina. Due to his heroic act, McDonagh injures his back and becomes addicted to prescription pain medication. He then finds himself involved with a drug dealer who is suspected of murdering a family of African immigrants.', '2009-09-11', 6.18, 'https://image.tmdb.org/t/p/w500/zRULXsd0rb1lVfnSyQkYPi2nLcB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11703, 'Kiss of the Spider Woman', 'The story of two radically different men thrown together in a Latin American prison cell. One is Valentin, a journalist being tortured for his political beliefs. The other is Molina, a gay window-dresser who fills their lonely nights by spinning romantic fantasies drawn from memories of old movies.', '1985-07-26', 6.96, 'https://image.tmdb.org/t/p/w500/lbrn4gOjYKrLrINn3uUJRlV2NZO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11636, 'New Police Story', 'Sent into a drunken tailspin when his entire unit is killed by a gang of thrill-seeking punks, disgraced Hong Kong police inspector Wing needs help from his new rookie partner, with a troubled past of his own, to climb out of the bottle and track down the gang and its ruthless leader.', '2004-09-23', 7.16, 'https://image.tmdb.org/t/p/w500/kWUTyIao0b8DxVrO6L0LnpJVYWV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11587, 'The Exorcist III', 'On the fifteenth anniversary of the exorcism that claimed Father Damien Karras'' life, Police Lieutenant Kinderman''s world is once again shattered when a boy is found decapitated and savagely crucified.', '1990-08-17', 6.30, 'https://image.tmdb.org/t/p/w500/275gw2JA5YCk10o6n84rZdZBycM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11708, 'Chitty Chitty Bang Bang', 'A hapless inventor finally finds success with a flying car, which a dictator from a foreign government sets out to take for himself.', '1968-12-17', 6.83, 'https://image.tmdb.org/t/p/w500/wJ62FzGeCAs6PjCIK1as6xzdIY5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11652, 'Invincible', 'Inspired by the true story of Vince Papale, a man with nothing to lose who ignored the staggering odds and made his dream come true. When the coach of Papale''s beloved hometown football team hosted an unprecedented open tryout, the public consensus was that it was a waste of time – no one good enough to play professional football was going to be found this way.', '2006-08-25', 7.03, 'https://image.tmdb.org/t/p/w500/oEaUMn5POAiMLnU6hKOBKoZbDpo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11583, 'The First Great Train Robbery', 'In Victorian England, a master criminal makes elaborate plans to steal a shipment of gold from a moving train.', '1978-12-14', 6.69, 'https://image.tmdb.org/t/p/w500/4LqLUNoCwoPQNmrRuDZa0zC3hT8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11645, 'Ran', 'Shakespeare''s King Lear is reimagined as a singular historical epic set in sixteenth-century Japan where an aging warlord divides his kingdom between his three sons.', '1985-06-01', 8.01, 'https://image.tmdb.org/t/p/w500/dGgiXMWDcS5aJTBEFu7bmaQPNox.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11694, 'Cat Ballou', 'A woman seeking revenge for her murdered father hires a famous gunman, but he''s very different from what she expects.', '1965-06-24', 6.39, 'https://image.tmdb.org/t/p/w500/3WJmB1F5z4mLwt84i1FuIrSYEe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11639, 'The Dark Crystal', 'On another planet in the distant past, a Gelfling embarks on a quest to find the missing shard of a magical crystal and restore order to his world, before the grotesque race of Skeksis find and use the crystal for evil.', '1982-12-17', 7.15, 'https://image.tmdb.org/t/p/w500/fZPxRaa6gvCyGCh9Xk5kyPqz7fp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11702, 'The Replacement Killers', 'Hired assassin John Lee is asked by Chinatown crime boss Terence Wei to murder the young son of policeman Stan Zedkov. Lee has the boy in his sights, but his conscience gets the better of him, and he spares the child''s life. Afraid that Wei will take revenge on his family in China, Lee seeks out expert forger Meg Coburn to obtain the passport he needs to get out of the country, but a band of replacement killers is soon on his trail.', '1998-02-06', 6.28, 'https://image.tmdb.org/t/p/w500/6q96xjyGTQllKAKgmwyBsk5JSe5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11647, 'Infernal Affairs II', 'In this prequel to the original, a bloody power struggle among the Triads coincides with the 1997 handover of Hong Kong, setting up the events of the first film.', '2003-10-01', 7.29, 'https://image.tmdb.org/t/p/w500/q9MCjc4CMXju59slJEzYEtr7F3W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11697, 'The Man Who Shot Liberty Valance', 'Questions arise when Senator Stoddard attends the funeral of a local man named Tom Doniphon in a small Western town. Flashing back, we learn Doniphon saved Stoddard, then a lawyer, when he was roughed up by a crew of outlaws terrorizing the town, led by Liberty Valance. As the territory''s safety hung in the balance, Doniphon and Stoddard, two of the only people standing up to him, proved to be very important, but different, foes to Valance.', '1962-04-13', 7.83, 'https://image.tmdb.org/t/p/w500/4C1R0LEivLjbv3swAzJfzh0tzXl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11712, 'Sanjuro', 'In this companion piece and sequel to "Yojimbo," jaded samurai Sanjuro helps an idealistic group of young warriors weed out their clan''s evil influences, and in the process turns their image of a proper samurai on its ear.', '1962-01-01', 7.93, 'https://image.tmdb.org/t/p/w500/zW47oIH3bc3ggmmmzTvKqM4Fqjk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11777, 'I.Q.', 'Albert Einstein helps a young man who''s in love with Einstein''s niece to catch her attention by pretending temporarily to be a great physicist.', '1994-12-24', 6.02, 'https://image.tmdb.org/t/p/w500/5we3ZV6yiw13b8zGk4LuacuV8n7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11778, 'The Deer Hunter', 'Three steelworkers enlist in the army and are sent to Vietnam, one leaving behind a rushed marriage, the others a shared love. What they encounter during the war changes their lives forever.', '1978-12-08', 7.97, 'https://image.tmdb.org/t/p/w500/bbGtogDZOg09bm42KIpCXUXICkh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11779, 'Buena Vista Social Club', 'In this fascinating Oscar-nominated documentary, American guitarist Ry Cooder brings together a group of legendary Cuban folk musicians (some in their 90s) to record a Grammy-winning CD in their native city of Havana. The result is a spectacular compilation of concert footage from the group''s gigs in Amsterdam and New York City''s famed Carnegie Hall, with director Wim Wenders capturing not only the music -- but also the musicians'' life stories.', '1999-06-04', 7.49, 'https://image.tmdb.org/t/p/w500/b8psTDXSelHiab1I7L8rFdYs0IC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11644, 'Blow Out', 'While recording sound effects for a slasher flick, Jack Terry stumbles upon a real-life horror: a car careening off a bridge and into a river. Jack jumps into the water and fishes out Sally from the car, but the other passenger is already dead — a governor intending to run for president. As Jack does some investigating of his tapes, and starts a perilous romance with Sally, he enters a tangled web of conspiracy that might leave him dead.', '1981-07-24', 7.36, 'https://image.tmdb.org/t/p/w500/uFzMscVLDrTaYd6KXOXlr6dly7w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11656, 'The Virgin Spring', 'Devout Christians Töre and Märeta send their only daughter, the virginal Karin, and their foster daughter, the unrepentant Ingeri, to deliver candles to a distant church. On their way through the woods, the girls encounter a group of savage goat herders who brutally rape and murder Karin as Ingeri remains hidden. When the killers unwittingly seek refuge in the farmhouse of Töre and Märeta, Töre plots a fitting revenge.', '1960-02-08', 7.85, 'https://image.tmdb.org/t/p/w500/z70YM3Y4pNYZATMhFMKonngaeMC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11780, 'Rob Roy', 'In the highlands of Scotland in the 1700s, Rob Roy tries to lead his small town to a better future, by borrowing money from the local nobility to buy cattle to herd to market. When the money is stolen, Rob is forced into a Robin Hood lifestyle to defend his family and honour.', '1995-04-13', 6.72, 'https://image.tmdb.org/t/p/w500/kWI2rF6RAnRtEjfBlZgsXumgOm5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11782, 'Hard Boiled', 'A cop who loses his partner in a shoot-out with gun smugglers goes on a mission to catch them. In order to get closer to the leaders of the ring he joins forces with an undercover cop who''s working as a gangster hitman. They use all means of excessive force to find them.', '1992-04-16', 7.53, 'https://image.tmdb.org/t/p/w500/oMqr4CGGqVlfI8DdrSelK1e9aFM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11704, 'The Secret of NIMH', 'A widowed field mouse must move her family -- including an ailing son -- to escape a farmer''s plow. Aided by a crow and a pack of superintelligent, escaped lab rats, the brave mother struggles to transplant her home to firmer ground.', '1982-06-17', 7.44, 'https://image.tmdb.org/t/p/w500/prNrnOKlkV9wl5Sl3zwHu1f3t2z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11787, 'Harvey', 'The story of Elwood P. Dowd who makes friends with a spirit taking the form of a human-sized rabbit named Harvey that only he sees (and a few privileged others on occasion also.) After his sister tries to commit him to a mental institution, a comedy of errors ensues. Elwood and Harvey become the catalysts for a family mending its wounds and for romance blossoming in unexpected places.', '1950-12-04', 7.67, 'https://image.tmdb.org/t/p/w500/dgd82hYmpiXDM1G867HqNaWe8wj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11790, 'Peter''s Friends', 'After inheriting a large country estate from his late father, Peter invites his friends from college: married couple Roger and Mary, the lonely Maggie, fashionable Sarah, and writer Andrew, who brings his American TV star wife, Carol. Sarah''s new boyfriend, Brian, also attends. It has been 10 years since college, and they find their lives are very different.', '1992-09-18', 6.60, 'https://image.tmdb.org/t/p/w500/8ly4EB83JlOkjBD6wOTU0ReXMQN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11795, 'Guyver: Dark Hero', 'Sean Barker became the unwilling host to an alien bio-armor known as the Guyver. A year ago he destroyed the Kronos Corporation, an organization of mutants who want the Guyver. Now he is trying to find why the Guyver unit forces him to fight and kill evil.', '1994-04-20', 5.68, 'https://image.tmdb.org/t/p/w500/2vbtLS0rdMty6SA1MOCUIqhfWbm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11698, 'Stroszek', 'Bruno Stroszek is released from prison and warned to stop drinking. He has few skills and fewer expectations: with a glockenspiel and an accordion, he ekes out a living as a street musician. He befriends Eva, a prostitute down on her luck and they join his neighbor, Scheitz, an elderly eccentric, when he leaves Germany to live in Wisconsin.', '1977-05-20', 7.32, 'https://image.tmdb.org/t/p/w500/wDq9ytRxoVpICRcx1BvagmXhd4t.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11586, 'Exorcist II: The Heretic', 'Bizarre nightmares plague Regan MacNeil four years after her possession and exorcism. Has the demon returned? And if so, can the combined faith and knowledge of a Vatican investigator and a research specialist free her from its grasp?', '1977-06-17', 4.54, 'https://image.tmdb.org/t/p/w500/g9i3LTMYLRHvCYSKimZEfd1Vqy7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11796, 'The Hairdresser''s Husband', 'Antoine has always been fascinated by a hairdresser''s delicate touch, the beguiling perfume, and the enticing figure of a woman with an opulent bosom. After all, he had always known he would marry one, completing his idealized love fantasy.', '1990-10-03', 6.81, 'https://image.tmdb.org/t/p/w500/d0CCZOP1VILxL33O6OiVzUYVNPT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11713, 'Fist of Fury', 'During the Japanese occupation of Shanghai, Chen Zhen, the star pupil of a recently-deceased martial arts teacher battles a Japanese dojo which seeks the demise of his fighting school.', '1972-03-22', 7.22, 'https://image.tmdb.org/t/p/w500/dlcipCOa9hlfBBz7kCAyjsf3q0E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11797, 'Fright Night', 'Charley Brewster, a high school student, accidentally discovers the true and creepy nature of Jerry Dandrige, his dashing and enigmatic new neighbor; but no one seems willing to believe him.', '1985-08-02', 7.05, 'https://image.tmdb.org/t/p/w500/euIh75MwNDrYkTEVSkw7VXWGXoE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11804, 'White Noise', 'An architect''s desire to speak with his wife from beyond the grave using EVP (Electronic Voice Phenomenon), becomes an obsession with supernatural repercussions.', '2005-01-07', 5.61, 'https://image.tmdb.org/t/p/w500/ncB9SvOclmXYALlcAsF1jRIuISl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11806, 'Beethoven', 'The Newton family live in their comfortable home, but there seems to something missing. This "hole" is filled by a small puppy, who walks into their home and their lives. Beethoven, as he is named, grows into a giant of a dog... a St Bernard. Doctor Varnick, the local vet has a secret and horrible sideline, which requires lots of dogs for experiments. Beethoven is on the bad doctor''s list.', '1992-04-03', 5.83, 'https://image.tmdb.org/t/p/w500/aSZYXOmQ9SW27gLdHU02PJQGBMH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11706, 'War and Peace', 'The love story of young Countess Natasha Rostova and Count Pierre Bezukhov is interwoven with the Great Patriotic War of 1812 against Napoleon''s invading army.', '1956-08-21', 6.63, 'https://image.tmdb.org/t/p/w500/f3a1MyH12PSl3LFDahnooGy6mv8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11798, 'This Is England', 'A story about a troubled boy growing up in England, set in 1983. He comes across a few skinheads on his way home from school, after a fight. They become his new best friends, even like family. Based on experiences of director Shane Meadows.', '2007-04-27', 7.47, 'https://image.tmdb.org/t/p/w500/6ZVx7wLrlgSKxkYC2CRg6Zek0fG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11808, 'U.S. Marshals', 'U.S. Marshal Sam Gerard is accompanying a plane load of convicts from Chicago to New York. The plane crashes spectacularly, and Mark Sheridan escapes. But when Diplomatic Security Agent John Royce is assigned to help Gerard recapture Sheridan, it becomes clear that Sheridan is more than just another murderer.', '1998-03-06', 6.55, 'https://image.tmdb.org/t/p/w500/5ST0BydDSXtW5AtfDDhTVS13pTt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11811, 'Leprechaun', 'A demonic leprechaun terrorizes a group of young people whom he believes stole his gold.', '1993-01-08', 5.58, 'https://image.tmdb.org/t/p/w500/9i6HjU4CZJytN37LKQUDrNguQg7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11814, 'Weird Science', 'Two unpopular teenagers, Gary and Wyatt, fail at all attempts to be accepted by their peers. Their desperation to be liked leads them to "create" a woman via their computer. Their living and breathing creation is a gorgeous woman, Lisa, whose purpose is to boost their confidence level by putting them into situations which require Gary and Wyatt to act like men.', '1985-08-01', 6.54, 'https://image.tmdb.org/t/p/w500/AsFxOHwUlK7mTOkC5p6SySsdEjz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11812, 'The Sweetest Thing', 'Christina''s love life is stuck in neutral. After years of avoiding the hazards of a meaningful relationship, one night while club-hopping with her girlfriends, she meets Peter, her perfect match. Fed up with playing games, she finally gets the courage to let her guard down and follow her heart, only to discover that Peter has suddenly left town. Accompanied by Courtney, she sets out to capture the one that got away.', '2002-04-12', 5.62, 'https://image.tmdb.org/t/p/w500/qLysz4B5YmiDq52Op0zq4eD75LC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11815, 'The Fly', 'Industrialist François Delambre is called late at night by his sister-in-law, Helene, who tells him that she has just killed her husband. Reluctant at first, she eventually explains to the police that he invented a matter transportation apparatus and, while experimenting on himself, a fly entered the chamber.', '1958-07-16', 7.04, 'https://image.tmdb.org/t/p/w500/kXdBcDh2EbgSIf4Oo1dxKapZM2f.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11820, 'Mona Lisa Smile', 'Katherine Watson is a recent UCLA graduate hired to teach art history at the prestigious all-female Wellesley College, in 1953. Determined to confront the outdated mores of society and the institution that embraces them, Katherine inspires her traditional students, including Betty and Joan, to challenge the lives they are expected to lead.', '2003-12-19', 6.91, 'https://image.tmdb.org/t/p/w500/bg0VKsXnLjIZ0cHmZHZLs9gzrvm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11821, 'Doc Hollywood', 'After leaving Washington D.C. hospital, plastic surgeon Ben Stone heads for California, where a lucrative practice in Beverly Hills awaits. After a car accident, he''s sentenced to perform as the community''s general practitioner.', '1991-08-02', 6.36, 'https://image.tmdb.org/t/p/w500/36yGVgFWg7PvDdZ10Csg1uHpcZd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11823, 'Wimbledon', 'Britain’s Peter Colt has never quite lived up to his dreams of tennis stardom. Once ranked as high as number 11 in the world, the journeyman veteran has watched his number slip to 119 as his confidence on the court slowly ebbs away.  Now, on the eve of his leaving the world of professional tennis, he’s granted a wild card, allowing him to play his final Wimbledon tournament…make that his final tournament ever.', '2004-09-13', 6.23, 'https://image.tmdb.org/t/p/w500/agiItFfsvNsjpinLGwjfpYOhLaX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11816, 'On Golden Pond', 'For Norman and Ethel Thayer, this summer on golden pond is filled with conflict and resolution. When their daughter Chelsea arrives, the family is forced to renew the bonds of love and overcome the generational friction that has existed for years.', '1981-12-04', 7.26, 'https://image.tmdb.org/t/p/w500/ic4f03J6pnf9cpQmVDABFhUpbCU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11817, 'Bulletproof Monk', 'A mysterious and immortal Tibetan kung fu master, who has spent the last 60 years traveling around the world protecting the ancient Scroll of the Ultimate, mentors a selfish street kid in the ancient intricacies of kung fu.', '2003-03-28', 5.51, 'https://image.tmdb.org/t/p/w500/kHWv16c4uDmiEujICSBdQ52TH55.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11826, 'Sexy Beast', 'Ex-safecracker Gal Dove has served his time behind bars and is blissfully retired to a Spanish villa paradise with a wife he adores. The idyll is shattered by the arrival of his nemesis Don Logan, intent on persuading Gal to return to London for one last big job.', '2001-01-12', 7.00, 'https://image.tmdb.org/t/p/w500/xTfCZTzhgHNAR1pf5D49WH4buI5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11646, 'Gallipoli', 'Two Australian sprinters face the brutal realities of war when they are sent to fight in the Gallipoli campaign in the Ottoman Empire during World War I.', '1981-08-13', 7.06, 'https://image.tmdb.org/t/p/w500/un7VCqTmjrq3u75mQ204a8tofD4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11707, 'Tightrope', 'Wes Block is a detective who''s put on the case of a serial killer whose victims are young and pretty women. The murders are getting personal when the killer chooses victims who are acquaintances of Block. Even his daughters are threatened.', '1984-08-17', 6.16, 'https://image.tmdb.org/t/p/w500/5WEGUQIFpwUh4T4ZMMdzECsvXNS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11770, 'Shaolin Soccer', 'A young Shaolin follower reunites with his discouraged brothers to form a soccer team using their martial art skills to their advantage.', '2001-07-05', 7.21, 'https://image.tmdb.org/t/p/w500/z6ZQqwoxWy9muIxwUP4K2zWw7BU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11834, 'Jabberwocky', 'After the death of his father, young Dennis Cooper goes to town where he has to pass several adventures. The town and the whole kingdom is threatened by a terrible monster called ''Jabberwocky''. Will Dennis make his fortune? Is anyone brave enough to defeat the monster?', '1977-03-28', 6.03, 'https://image.tmdb.org/t/p/w500/kprcqmFxWPU45L1ZnMXO5yPPMVA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11825, 'Police Academy 5: Assignment Miami Beach', 'The Police Academy misfits travel to Miami Beach for Commandant Lassard to be honored with a prestigious lifetime award pending his retirement. Things take a turn when Lassard unknowingly ends up in possession of stolen diamonds from a jewel heist.', '1988-03-17', 5.22, 'https://image.tmdb.org/t/p/w500/4m1qfTiVxdEDv0fgUf0FI7CA9Fe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11824, 'Teen Wolf', 'When a shy teenager''s new-found powers help him score at basketball - and with the popular girls - he has some pretty hairy decisions to make.', '1985-08-23', 6.21, 'https://image.tmdb.org/t/p/w500/bv9rY9eoue2Hat6tcvrKVQ0ow8v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11718, 'Who''s Harry Crumb?', 'Harry Crumb is a bumbling and inept private investigator who is hired to solve the kidnapping of a young heiress which he''s not expected to solve because his employer is the mastermind behind the kidnapping.', '1989-02-03', 5.96, 'https://image.tmdb.org/t/p/w500/6iUoyyaMklULVoGJDyHcN4nGgSX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11654, 'The Hunger', 'Five-thousand-year-old vampire Miriam promises her lovers the gift of eternal life. When John, her cellist companion for centuries, discovers that he has suddenly begun growing old, he attempts to seek out the help of Dr. Sarah Roberts, a researcher on the mechanisms of aging.', '1983-04-29', 6.65, 'https://image.tmdb.org/t/p/w500/lFTDtRtK8J55A1LTpwigV7QGQg7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11774, 'Lemony Snicket''s A Series of Unfortunate Events', 'Three wealthy children''s parents are killed in a fire. When they are sent to a distant relative, they find out that he is plotting to kill them and seize their fortune.', '2004-12-16', 6.82, 'https://image.tmdb.org/t/p/w500/76Xi8z7Whv5WFIdfzzvC5tKSicd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11830, 'Tampopo', 'In this humorous paean to the joys of food, a pair of truck drivers happen onto a decrepit roadside shop selling ramen noodles. The widowed owner, Tampopo, begs them to help her turn her establishment into a paragon of the "art of noodle-soup making". Interspersed are satirical vignettes about the importance of food to different aspects of human life.', '1985-11-23', 7.79, 'https://image.tmdb.org/t/p/w500/ArYdSuX3zY9fMsE4LqmBl7xJq5R.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11848, 'Animal Farm', 'Animals on a farm lead a revolution against the farmers to put their destiny in their own hands. However this revolution eats their own children and they cannot avoid corruption.', '1954-12-28', 7.07, 'https://image.tmdb.org/t/p/w500/lhLp9a0jBIPLMAdUFNlYjCuS72Q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11849, 'Dungeons & Dragons', 'The Empire of Izmer is a divided land: elite magicians called “mages” rule while lowly commoners are powerless. When Empress Savina vows to bring equality and prosperity to her land, the evil mage Profion plots to depose her.', '2000-12-08', 4.40, 'https://image.tmdb.org/t/p/w500/tLCsyHLHhTbzKzsL3IcBNyDKlZm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11649, 'Masters of the Universe', 'When the evil Skeletor finds a mysterious power called the Cosmic Key, he becomes nearly invincible, seizing Castle Grayskull and the surrounding city. The Sorceress is now Skeletor''s prisoner and he begins to drain her life-force as he waits for the moon of Eternia to align with the Great Eye of the Universe which will bestow god-like power upon him. However, courageous warrior He-Man locates the locksmith inventor Gwildor, who created the Key and has another version of it. During a battle, one of the Keys is transported to Earth, where it is found by teenagers Julie and Kevin. Now, both He-Man and Skeletor''s forces arrive on Earth searching for the potent weapon.', '1987-08-07', 5.91, 'https://image.tmdb.org/t/p/w500/gaUecXFd31V68yOTJPJYaB9YhAf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11850, 'Invasion of the Body Snatchers', 'The residents of San Francisco are becoming drone-like shadows of their former selves, and as the phenomenon spreads, two Department of Health workers uncover the horrifying truth.', '1978-12-20', 7.22, 'https://image.tmdb.org/t/p/w500/skS02wdeH2C0nrbCQP3qKwJdZtZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11828, 'Erik the Viking', 'Erik the Viking gathers warriors from his village and sets out on a dangerous journey to Valhalla, to ask the gods to end the Age of Ragnorok and allow his people to see sunlight again. A Pythonesque satire of Viking life.', '1989-09-01', 5.93, 'https://image.tmdb.org/t/p/w500/tRaNvLehJf0OVsBexo4u4NRKLJ4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11851, 'The Presidio', 'Jay Austin is now a civilian police detective. Colonel Caldwell was his commanding officer years before when he left the military police over a disagreement over the handling of a drunk driver. Now a series of murders that cross jurisdictions force them to work together again. That Austin is now dating Caldwell''s daughter is not helping their relationship.', '1988-06-10', 5.82, 'https://image.tmdb.org/t/p/w500/pHYtq4wFaUy5Rfa8lRi24QMUwRY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11852, 'The Hot Chick', 'Not only is Jessica Spencer the most popular girl in school -- she is also the meanest. But things change for the attractive teen when a freak accident involving a cursed pair of earrings and a chance encounter at a gas station causes her to switch bodies with Clive, a sleazy crook. Jessica, in the form of the repulsive Clive, struggles to adjust to this radical alteration and sets out to get her own body back before the upcoming prom.', '2002-12-13', 6.36, 'https://image.tmdb.org/t/p/w500/lnnGE4TKa05t20SZ2batuAhXCp4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11773, 'Village of the Damned', 'In a small English village everyone suddenly falls unconscious. When they awake every woman of child bearing age is pregnant. The resulting children have the same strange blond hair, eyes and a strong connection to each other.', '1960-06-16', 7.18, 'https://image.tmdb.org/t/p/w500/qcpXud1UjQzlSe9A062w8Wqgira.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11855, 'Pecker', 'A Baltimore teenager who picks up a second-hand camera starts snapping his way to stardom, soon turning into a nationwide sensation, with a fateful choice between his life and his art.', '1998-09-25', 6.06, 'https://image.tmdb.org/t/p/w500/ox6Myr2r36zr7aqnisQGZp2EW33.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11853, 'Bad Girls', 'Four former harlots try to leave the wild west (Colorado, to be exact) and head north to make a better life for themselves. Unfortunately someone from Cody''s past won''t let it happen that easily.', '1994-04-22', 5.30, 'https://image.tmdb.org/t/p/w500/cXY79luLXt2dzUP2Tx601zpZFzK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11835, 'Death Sentence', 'Nick Hume is a mild-mannered executive with a perfect life, until one gruesome night he witnesses something that changes him forever. Transformed by grief, Hume eventually comes to the disturbing conclusion that no length is too great when protecting his family.', '2007-08-31', 6.80, 'https://image.tmdb.org/t/p/w500/3rdEAMh4a3pc7GO6fSkJwpt7BWX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11772, 'The Haunting', 'Dr. John Markway recruits three strangers for a sleep-disorder study at the eerie and isolated Hill House. It soon becomes clear his real interest lies in the mansion itself and its sinister history, as they are forced to confront the nature of its horror…', '1963-03-28', 7.10, 'https://image.tmdb.org/t/p/w500/fmpTnUKTcrpuxLSY23gQMUf9qu7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11857, 'Orange County', 'Shaun Brumder is a local surfer kid from Orange County who dreams of going to Stanford to become a writer and to get away from his dysfunctional family household. Except Shaun runs into one complication after another, starting when his application is rejected after his dim-witted guidance counselor sends in the wrong form.', '2002-01-11', 6.01, 'https://image.tmdb.org/t/p/w500/pkyi0FYFVxymhqGNttYtDOHXjBM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11856, 'Air America', 'Air America was the CIA''s private airline operating in Laos during the Vietnam War, running anything and everything from soldiers to foodstuffs for local villagers. After losing his pilot''s license, Billy Covington is recruited, and ends up in the middle of a bunch of lunatic pilots, gun-running by his friend Gene Ryack, and opium smuggling by his own superiors.', '1990-08-10', 5.83, 'https://image.tmdb.org/t/p/w500/2cVANiDU7AdSLGgs4T7dpgyU2SK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11858, 'Renaissance Man', 'An advertising man is slowly sliding downhill. When he is fired from his job in Detroit, he signs up for unemployment. One day they find him a job: teaching thinking skills to Army recruits. He arrives on base to find that there is no structure set up for the class.', '1994-06-03', 6.11, 'https://image.tmdb.org/t/p/w500/iPRtaSfN8gNWFclgrcg5oD3V41i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11862, 'Father of the Bride Part II', 'Just when George Banks has recovered from his daughter''s wedding, he receives the news that she''s pregnant ... and that George''s wife is expecting too. He was planning on selling their home, but that''s a plan that—like George—will have to change with the arrival of both a grandchild and a kid of his own.', '1995-12-08', 6.27, 'https://image.tmdb.org/t/p/w500/rj4LBtwQ0uGrpBnCELr716Qo3mw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11860, 'Sabrina', 'After her return from school in Paris, a playboy finally takes notice of his family''s chauffeur''s daughter Sabrina, who''s long had a crush on him, but he questions his more serious brother''s motives when he warns against getting involved with her.', '1995-12-15', 6.21, 'https://image.tmdb.org/t/p/w500/i8PbLJDPU7vCwwscWD625oHbJy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11861, 'How to Make an American Quilt', 'Soon-to-be-wed graduate student Finn Dodd develops cold feet when she suspects her fiancé is cheating on her. In order to clear her head, Finn visits her grandmother, Hy, and great aunt, Glady Joe Cleary, in Grasse, Calif. There, Finn learns that Hy and Glady Joe are members of a group of passionate quilters, and over the course of her visit she is regaled with tales of love and life by women who have collected rich experiences and much wisdom.', '1995-10-06', 6.40, 'https://image.tmdb.org/t/p/w500/pI9UAemlWgdrnjRgYJsbTk8BSJc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11859, 'Fair Game', 'Max Kirkpatrick is a cop who protects Kate McQuean, a civil law attorney, from a renegade KGB team out to terminate her', '1995-11-03', 5.20, 'https://image.tmdb.org/t/p/w500/qcxsWOzBaF7MZNNThtRQWQ9Wrdk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11866, 'Flight of the Phoenix', 'When an oil rig in the Gobi Desert of Mongolia proves unproductive, an aircraft crew are sent to shut the operation down and fly them out. On the flight out over the desert on the way to Beijing, Capt. Frank Towns and co-pilot A.J. are unable to keep their cargo plane, a C-119 Flying Boxcar, in the air when a violent sandstorm strikes. Crash-landing in a remote uncharted part of the desert, the two pilots and their passengers -- a crew of oil workers and a drifter -- must work together to survive by rebuilding the aircraft. Soon, low supplies and a band of merciless smugglers add even greater urgency to their task.', '2004-12-17', 6.00, 'https://image.tmdb.org/t/p/w500/pcj6unMsKCw0ogWFlUXmbc9gKap.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11864, 'Enemy Mine', 'A soldier from Earth crashlands on an alien world after sustaining battle damage. Eventually he encounters another survivor, but from the enemy species he was fighting; they band together to survive on this hostile world. In the end the human finds himself caring for his enemy in a completely unexpected way.', '1985-12-12', 6.98, 'https://image.tmdb.org/t/p/w500/a3dr9L8VIjhEvivzQ2M12VQDere.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11863, 'Jade', 'When a prominent art dealer is found murdered, the man''s death leads to an intriguing investigation steeped in sex, corruption and crime. District Attorney David Corelli gets assigned to the case and discovers that a key suspect is his ex-lover Katrina Gavin, a beautiful psychologist who has settled down with his old friend and peer. As Corelli gets deeper into the case, he uncovers dark secrets with far-reaching implications.', '1995-10-11', 5.50, 'https://image.tmdb.org/t/p/w500/8KWiZKDYpAgh8n27lanvTuDquyX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11867, 'Barb Wire', 'A sexy nightclub owner, Barb Wire moonlights as a mercenary in Steel Harbor, one of the last free zones in the now fascist United States. When scientist Cora Devonshire wanders into Barb''s establishment, she gets roped into a top-secret government plot involving biological weapons. Soon Barb is reunited with her old flame Axel Hood, who is now Cora''s husband and a guerrilla fighter, resulting in plenty of tense action.', '1996-05-02', 4.12, 'https://image.tmdb.org/t/p/w500/eACq1joafhQTD12gGXNS13J06B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11868, 'Dracula', 'After Jonathan Harker attacks Dracula at his castle, the vampire travels to a nearby city, where he preys on the family of Harker''s fiancée. The only one who may be able to protect them is Dr. van Helsing, Harker''s friend and fellow-student of vampires, who is determined to destroy Dracula, whatever the cost.', '1958-04-21', 7.26, 'https://image.tmdb.org/t/p/w500/9UHOATvzXQWbElSGygOY1ar3vpp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11870, 'Big Fat Liar', 'After one of his class papers is stolen and turned into a movie, a young student and his best friend exact a hilarious, slapstick revenge on the Hollywood hot shot who has taken credit!', '2002-02-08', 5.90, 'https://image.tmdb.org/t/p/w500/3EjpQeyOpH8VIaWqIq6SpCQrCks.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11873, 'The Color of Money', 'Former pool hustler "Fast Eddie" Felson decides he wants to return to the game by taking a pupil. He meets talented but green Vincent Lauria and proposes a partnership. As they tour pool halls, Eddie teaches Vincent the tricks of scamming, but he eventually grows frustrated with Vincent''s showboat antics, leading to an argument and a falling-out. Eddie takes up playing again and soon crosses paths with Vincent as an opponent.', '1986-10-17', 6.85, 'https://image.tmdb.org/t/p/w500/dVdnHmdQu3JtLAAksjTmTEF76gD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11878, 'Yojimbo', 'A nameless ronin, or samurai with no master, enters a small village in feudal Japan where two rival businessmen are struggling for control of the local gambling trade. Taking the name Sanjuro Kuwabatake, the ronin convinces both silk merchant Tazaemon and sake merchant Tokuemon to hire him as a personal bodyguard, then artfully sets in motion a full-scale gang war between the two ambitious and unscrupulous men.', '1961-04-25', 8.08, 'https://image.tmdb.org/t/p/w500/tN7kYPjRhDolpui9sc9Eq9n5b2O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11879, 'Near Dark', 'A farm boy reluctantly becomes a member of the undead when a girl he meets turns out to be part of a band of vampires who roam the highways in stolen cars.', '1987-10-02', 6.80, 'https://image.tmdb.org/t/p/w500/hVhFNn3IQxxARvnpLIKMx8ZfTtG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11880, 'Dog Soldiers', 'A band of soldiers is dispatched to war games deep in the woods. When they stumble across a rival team slaughtered in camp, they realize they''re not alone.', '2002-05-10', 6.72, 'https://image.tmdb.org/t/p/w500/ydqx6Q30hloZPDBNSBOylD8D520.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11886, 'Robin Hood', 'With King Richard off to the Crusades, Prince John and his slithering minion, Sir Hiss, set about taxing Nottingham''s citizens with support from the corrupt sheriff - and staunch opposition by the wily Robin Hood and his band of merry men.', '1973-11-08', 7.31, 'https://image.tmdb.org/t/p/w500/x9AvkYek0bGdxQSZ8W3lAjGrREm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11884, 'The Last Starfighter', 'Video game expert Alex Rogan finds himself transported to another planet after conquering the video game The Last Starfighter, only to find out it was just a test. He was recruited to join the team of best Starfighters to defend their world from the attack.', '1984-07-13', 6.60, 'https://image.tmdb.org/t/p/w500/A7oAHTjtYnIEQjJs62IONRufooq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11888, 'Snow Dogs', 'When a Miami dentist inherits a team of sled dogs, he''s got to learn the trade or lose his pack to a crusty mountain man.', '2002-01-18', 5.60, 'https://image.tmdb.org/t/p/w500/8DDC6z1XyLSiNLzKw1pXcYeAOJ3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11881, 'Miracle on 34th Street', 'Kris Kringle, seemingly the embodiment of Santa Claus, is asked to portray the jolly old fellow at Macy''s following his performance in the Thanksgiving Day parade. His portrayal is so complete that many begin to question if he truly is Santa Claus, while others question his sanity.', '1947-06-04', 7.36, 'https://image.tmdb.org/t/p/w500/vehuIm3y6BeMI7mYjxzaA1H8M0k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11889, 'Iris', 'True story of the lifelong romance between novelist Iris Murdoch and her husband John Bayley, from their student days through her battle with Alzheimer''s disease.', '2001-12-14', 6.40, 'https://image.tmdb.org/t/p/w500/sm1ve46SuxDVywnvVEg2XvhvlK8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11891, 'Kung Pow: Enter the Fist', 'A movie within a movie, created to spoof the martial arts genre. Writer/director Steve Oedekerk uses contemporary characters and splices them into a 1970s kung-fu film, weaving the new and old together.  As the main character, The Chosen One, Oedekerk sets off to avenge the deaths of his parents at the hands of kung-fu legend Master Pain. Along the way he encounters some strange characters.', '2002-01-25', 6.52, 'https://image.tmdb.org/t/p/w500/gVsZ1hsJ9g11oCCav4N8ccp9bRw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11890, 'Oscar', 'Angelo "Snaps" Provolone made his dying father a promise on his deathbed: he would leave the world of crime and become an honest businessman. Despite having no experience in making money in a legal fashion, Snaps sets about to keep his promise.', '1991-04-26', 6.35, 'https://image.tmdb.org/t/p/w500/rGJOzUwHlkx8MKy2oR2qEiT7g4G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11892, 'Murder by Numbers', 'Tenacious homicide detective Cassie Mayweather and her still-green partner are working a murder case, attempting to profile two malevolently brilliant young men: cold, calculating killers whose dark secrets might explain their crimes.', '2002-04-19', 6.17, 'https://image.tmdb.org/t/p/w500/plH3TujSUVttiIikToKfwdCorJI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11876, 'The Horseman on the Roof', 'In a time of war and disease, a young officer gallantly tries to help a young woman find her husband.', '1995-09-20', 6.55, 'https://image.tmdb.org/t/p/w500/tsmwnxi8hGXQTNVqBRCAVsfeGON.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11895, 'Police Academy 6: City Under Siege', 'Our favourite police men are called together to deal with a gang who rob banks and jewelers. Using their various talents as well as their extraordinary luck, the crooks stand no chance against our men and women in blue.', '1989-03-09', 5.14, 'https://image.tmdb.org/t/p/w500/gRFJ3xLewH1rwEplZBfKS4vGpFV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11896, 'Throw Momma from the Train', 'Larry Donner, an author with a cruel ex-wife, teaches a writing workshop in which one of his students, Owen, is fed up with his domineering mother. When Owen watches a Hitchcock classic that seems to mirror his own life, he decides to put the movie''s plot into action and offers to kill Larry''s ex-wife, if Larry promises to murder his mom. Before Larry gets a chance to react to the plan, it seems that Owen has already set things in motion.', '1987-12-11', 6.16, 'https://image.tmdb.org/t/p/w500/fwcIsCwTwF8AXNxvNkrZ5dZlGPz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11894, 'Curly Sue', 'Bill is a penniless drifter who scams strangers out of just enough money to feed himself and his partner in crime, an orphan girl known as Curly Sue. Bill and Curly Sue target Grey, a yuppie lawyer, but their con takes an unexpected turn when the successful woman begins to like the ramshackle duo. But there''s one problem—Grey''s jealous, conniving boyfriend, Walker.', '1991-10-25', 6.35, 'https://image.tmdb.org/t/p/w500/cndkzlP5frVWxng5HLd4JvA2g2y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11899, 'The Muppets Take Manhattan', 'When the Muppets graduate from Danhurst College, they take their song-filled senior revue to New York City, only to learn that it isn''t easy to find a producer who''s willing to back a show starring a frog and a pig. Of course, Kermit the Frog and Miss Piggy won''t take no for an answer, launching a search for someone to take them to Broadway.', '1984-06-27', 6.61, 'https://image.tmdb.org/t/p/w500/nMPm9TNoW8zwNibTFJAePryXUgT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11898, 'Kind Hearts and Coronets', 'When his mother eloped with an Italian opera singer, Louis Mazzini was cut off from her aristocratic family. After the family refuses to let her be buried in the family mausoleum, Louis avenges his mother''s death by attempting to murder every family member who stands between himself and the family fortune. But when he finds himself torn between his longtime love and the widow of one of his victims, his plans go awry.', '1949-06-23', 7.62, 'https://image.tmdb.org/t/p/w500/eBvpyRjD3DcCsWgdV6Y9oqPS7dO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11831, 'Amistad', 'In 1839, the slave ship Amistad set sail from Cuba to America. During the long trip, Cinque leads the slaves in an unprecedented uprising. They are then held prisoner in Connecticut, and their release becomes the subject of heated debate. Freed slave Theodore Joadson wants Cinque and the others exonerated and recruits property lawyer Roger Baldwin to help his case. Eventually, John Quincy Adams also becomes an ally.', '1997-12-10', 7.01, 'https://image.tmdb.org/t/p/w500/6QqNyIHKow0jngiQgTNBOBrLILM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11901, 'High Plains Drifter', 'A gunfighting stranger comes to the small settlement of Lago. After gunning down three gunmen who tried to kill him, the townsfolk decide to hire the Stranger to hold off three outlaws who are on their way.', '1973-04-19', 7.32, 'https://image.tmdb.org/t/p/w500/AjkJCFkqanK1OZqiHxc6Kl2wPQO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11902, 'Underground', 'Black marketeers Marko and Blacky manufacture and sell weapons to the Communist resistance in WWII Belgrade, living the good life along the way. Marko''s surreal duplicity propels him up the ranks of the Communist Party, and he eventually abandons Blacky and steals his girlfriend. After a lengthy stay in a below-ground shelter, the couple reemerges during the Yugoslav Civil War of the 1990s as Marko sees the opportunity to exploit the situation.', '1995-10-25', 7.71, 'https://image.tmdb.org/t/p/w500/h8N6y13t4VusrDdH5PzTkwvBvgN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11657, 'Le Cercle Rouge', 'When French criminal Corey gets released from prison, he resolves to never return. He is quickly pulled back into the underworld, however, after a chance encounter with escaped murderer Vogel. Along with former policeman and current alcoholic Jansen, they plot an intricate jewel heist. All the while, quirky Police Commissioner Mattei, who was the one to lose custody of Vogel, is determined to find him.', '1970-10-19', 7.60, 'https://image.tmdb.org/t/p/w500/w56La43IJnGpLepgqfGCAZsbQPp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11905, 'The Company of Wolves', 'An adaptation of Angela Carter''s fairy tales. Young Rosaleen dreams of a village in the dark woods, where Granny tells her cautionary tales in which innocent maidens are tempted by wolves who are hairy on the inside. As Rosaleen grows into womanhood, will the wolves come for her too?', '1984-09-21', 6.29, 'https://image.tmdb.org/t/p/w500/2g2YPws1MiEWTodUE8u3qOf78XS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11893, 'Runaway Train', 'A hardened convict and a younger prisoner escape from a brutal prison in the middle of winter only to find themselves on an out-of-control train with a female railway worker while being pursued by the vengeful head of security.', '1985-11-15', 7.00, 'https://image.tmdb.org/t/p/w500/yEvMuhIdwPhhEtikAihxUTM1u75.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11827, 'Heavy Metal', 'The embodiment of ultimate evil, a glowing orb terrorizes a young girl with bizarre stories of dark fantasy, eroticism and horror.', '1981-08-07', 6.52, 'https://image.tmdb.org/t/p/w500/atUtWrDlLzT1yeVK2EoYtvbS963.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11832, 'Babette''s Feast', 'A French housekeeper with a mysterious past brings quiet revolution in the form of one exquisite meal to a circle of starkly pious villagers in late 19th century Denmark.', '1987-08-11', 7.20, 'https://image.tmdb.org/t/p/w500/3ibptSbnAHd0SUBnOKapNZQBpCl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11836, 'The SpongeBob SquarePants Movie', 'There''s trouble brewing in Bikini Bottom. Someone has stolen King Neptune''s crown, and it looks like Mr. Krab, SpongeBob''s boss, is the culprit. Though he''s just been passed over for the promotion of his dreams, SpongeBob stands by his boss, and along with his best pal Patrick, sets out on a treacherous mission to Shell City to reclaim the crown and save Mr. Krab''s life.', '2004-11-19', 7.10, 'https://image.tmdb.org/t/p/w500/1rvzKV1d18EbDVaEd4VDzK3cgnY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11775, 'Intolerable Cruelty', 'A revenge-seeking gold digger marries a womanizing Beverly Hills lawyer with the intention of making a killing in the divorce.', '2003-10-10', 5.96, 'https://image.tmdb.org/t/p/w500/7K8hDwOWsZv0MluyrB8nWlhJOgB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11839, 'The Court Jester', 'A hapless carnival performer masquerades as the court jester as part of a plot against a usurper who has overthrown the rightful king of England.', '1955-12-24', 7.25, 'https://image.tmdb.org/t/p/w500/pPCOAipDP0sm8SLChpTMBPdCiqB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11846, 'Father of the Bride', 'George Banks is an ordinary, middle-class man whose 22 year-old daughter Annie has decided to marry a man from an upper-class family, but George can''t think of what life would be like without his daughter. His wife tries to make him happy for Annie, but when the wedding takes place at their home and a foreign wedding planner takes over the ceremony, he becomes slightly insane.', '1991-12-20', 6.47, 'https://image.tmdb.org/t/p/w500/bU7HzJbJpY5OiLdqWhKSqGPtYii.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11837, 'Watership Down', 'When the warren belonging to a community of rabbits is threatened, a brave group led by Fiver, Bigwig, Blackberry and Hazel leave their homeland in a search of a safe new haven.', '1978-10-14', 7.19, 'https://image.tmdb.org/t/p/w500/q9ZcNxfquJbMTd6UfhAlJbmLBts.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11934, 'The Hudsucker Proxy', 'A naive business graduate is installed as president of a manufacturing company as part of a stock scam.', '1994-03-11', 7.07, 'https://image.tmdb.org/t/p/w500/xBQBr6Q1OTivouBK66oFgy86n03.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11936, 'City of Women', 'The charismatic Snaporaz encounters an alluring woman on a train and pursues her through a forest. He ends up at a hotel populated by women gathered for a feminist conference, where he is an unwanted presence. Snaporaz soon discovers he’s entered a phantasmagoric world where women have taken power.', '1980-03-28', 6.96, 'https://image.tmdb.org/t/p/w500/hSX2YnpQebGlw5ljNlr1jnNSt5q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11937, 'The Gods Must Be Crazy II', 'Xixo is back again. This time, his children accidentally stow away on a fast-moving poachers'' truck, unable to get off, and Xixo sets out to rescue them. Along the way, he encounters a couple of soldiers trying to capture each other and a pilot and passenger of a small plane, who are each having a few problems of their own.', '1989-07-01', 7.07, 'https://image.tmdb.org/t/p/w500/sxPpBTB2Rd5PHs97E2zn0t9GCSp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11938, 'Clockwise', 'School headmaster Brian Stimpson is obsessed with timeliness, order, and discipline. Brian misses his train after meticulously preparing a speech for an education conference. With no one else to turn to, he asks young former student Laura Wisely for a ride. Laura, upset over a break-up, agrees to drive him in her parents'' car - which alarms her mother and father, who worry that she has run away with a married man and subsequently alert the police.', '1986-03-01', 6.24, 'https://image.tmdb.org/t/p/w500/uRetBG6n8ScyIdtkJNGngTqX75c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11838, 'Ju-on: The Grudge', 'When a social worker is sent to check on a traumatized elderly woman whose family have moved in at the site of a notorious murder case, she unwittingly unleashes a cycle of terror that transmits via its victims.', '2002-10-18', 6.80, 'https://image.tmdb.org/t/p/w500/6q1hlBC6rudc3mHwXsbMBR2xAT6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11939, 'A Day at the Races', 'Doctor Hugo Hackenbush, Tony, and Stuffy try and save Judy''s sanitarium by winning a big race with a finicky horse owned by Judy''s boyfriend Gil. There are a few problems. Hackenbush, who was recently put in charge of the sanitarium, isn''t really a doctor, he''s a veterinarian.', '1937-06-11', 7.13, 'https://image.tmdb.org/t/p/w500/2TYWSyAMbaFN3p3ewwmzweDUSLC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11940, 'Sinbad and the Eye of the Tiger', 'Princess Farah refuses to marry Sinbad until Prince Kassim, her brother, is able to give his consent. However, the Prince''s wicked stepmother, Queen Zenobia, has changed Kassim into a baboon in order to have her own son crowned as caliph. Sinbad, his crew, the Princess and the transformed Prince travel to a distant land, fighting every obstacle Zenobia places in their path, to seek the advice of a legendary wise man who can possibly tell how to end the spell.', '1977-05-25', 6.56, 'https://image.tmdb.org/t/p/w500/kMP5bg26ac1FmNCamOC5WZece6N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11942, 'Bring Me the Head of Alfredo Garcia', 'An American bartender and his prostitute girlfriend go on a road trip through the Mexican underworld to collect a $1 million bounty on the head of a dead gigolo.', '1974-08-01', 7.09, 'https://image.tmdb.org/t/p/w500/gRWVf3InNlIlFT3WB9MnFdOwcYQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11907, 'Nobody Loves Me', 'On the brink of her 30th birthday, Fanny feels the door to marital happiness closing on her. She is obsessed with death and even visits evening classes on dying, so it seems fitting that she encounters a skeleton in the malfunctioning elevator of her apartment building. The skeleton is her neighbour Orfeo, a Black, gay, self-declared psychic, who convinces her that she is about to meet "him". But is it really Lothar, the new yuppie apartment manager ...?', '1994-11-07', 6.37, 'https://image.tmdb.org/t/p/w500/vBDJPkoTOKT9F1zx0y9tT7G62vF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11904, 'Young Sherlock Holmes', 'Sherlock Holmes and Dr. Watson meet as boys in an English Boarding school. Holmes is known for his deductive ability even as a youth, amazing his classmates with his abilities. When they discover a plot to murder a series of British business men by an Egyptian cult, they move to stop it.', '1985-12-04', 6.76, 'https://image.tmdb.org/t/p/w500/aOxVYvQoAfNSns4hW5Ah55GBzgq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11943, 'Jeremiah Johnson', 'A mountain man who wishes to live the life of a hermit becomes the unwilling object of a long vendetta by Indians when he proves to be the match of their warriors in one-on-one combat on the early frontier.', '1972-09-10', 7.31, 'https://image.tmdb.org/t/p/w500/fANj1S3UmBB51wnKxYRKtw8LMBn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11950, 'Cannonball Run II', 'When a wealthy sheikh puts up $1 million in prize money for a cross-country car race, there is one person crazy enough to hit the road hard with wheels spinning fast. Legendary driver J.J. McClure enters the competition along with his friend Victor and together they set off across the American landscape in a madcap action-adventure destined to test their wits and automobile skills.', '1984-06-29', 5.41, 'https://image.tmdb.org/t/p/w500/sdXjbUcdESA5CKCyez6A29c2vq3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11949, 'Monty Python Live at the Hollywood Bowl', 'Monty Python perform many of their greatest sketches at the Hollywood Bowl, including several from pre-Python days.', '1982-06-25', 7.35, 'https://image.tmdb.org/t/p/w500/7sQPWnIUVswWtIl35Lj3VKW3Pz0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11916, 'Two Mules for Sister Sara', 'When a wandering mercenary named Hogan rescues a nun called Sister Sara from the unwanted attentions of a band of rogues on the Mexican plains, he has no idea what he has let himself in for. Their chance encounter results in the blowing up of a train and a French garrison, as well as igniting a spark between them that survives a shocking discovery.', '1970-03-02', 6.95, 'https://image.tmdb.org/t/p/w500/2G9eM8UAM57TanLBhuPmz3jaNZG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11909, 'Bullet in the Head', 'Three childhood friends from the slums of Hong Kong flee to war-time Saigon after accidentally murdering a gang leader, but their troubles only escalate.', '1990-08-17', 7.56, 'https://image.tmdb.org/t/p/w500/zsLcRua8Jt5RtD8l8NAq1voXDfg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11953, 'Kagemusha', 'Akira Kurosawa''s lauded feudal epic presents the tale of a petty thief who is recruited to impersonate Shingen, an aging warlord, in order to avoid attacks by competing clans. When Shingen dies, his generals reluctantly agree to have the impostor take over as the powerful ruler. He soon begins to appreciate life as Shingen, but his commitment to the role is tested when he must lead his troops into battle against the forces of a rival warlord.', '1980-04-26', 7.81, 'https://image.tmdb.org/t/p/w500/fJgqj9s8HNZz9zwX6femVJn8HEB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11918, 'Superhero Movie', 'Rick Riker is a nerdy teen imbued with superpowers by a radioactive dragonfly. And because every hero needs a nemesis, enter Lou Landers, aka the villainously goofy Hourglass.', '2008-03-28', 5.32, 'https://image.tmdb.org/t/p/w500/nAzo5OOmoE9SXOv4mHTuiu58QXA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11955, 'Iron Eagle II', 'Chappy Sinclair is called to gather together a mixed Soviet/U.S. strike force that will perform a surgical strike on a massively defended nuclear missile site in the Middle East. Chappy finds that getting the Soviet and U.S. Pilots to cooperate is only the most minor of his problems as he discovers someone in the Pentagon is actively sabotaging his mission.', '1988-11-11', 4.53, 'https://image.tmdb.org/t/p/w500/yQNq0zbInR0Vx6nWJCEBN4d0pPI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11954, 'Lifeforce', 'A race of space vampires arrives in London and infects the populace, commencing an apocalyptic descent into chaos.', '1985-06-21', 6.21, 'https://image.tmdb.org/t/p/w500/AeLmyhJNQd2BMFGER36ctAeDhIp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11962, 'Joe''s Apartment', 'A nice guy has just moved to New York and discovers that he must share his run-down apartment with a couple thousand singing, dancing cockroaches.', '1996-07-26', 5.84, 'https://image.tmdb.org/t/p/w500/a06jrMRurcq7sYdhFK2LNs8bRt8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11970, 'Hercules', 'Bestowed with superhuman strength, a young mortal named Hercules sets out to prove himself a hero in the eyes of his father, the great god Zeus. Along with his friends Pegasus, a flying horse, and Phil, a personal trainer, Hercules is tricked by the hilarious, hotheaded villain Hades, who''s plotting to take over Mount Olympus!', '1997-06-13', 7.50, 'https://image.tmdb.org/t/p/w500/dK9rNoC97tgX3xXg5zdxFisdfcp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11847, 'The Accidental Spy', 'A fun-filled story about an ordinary guy about to kick into an action-packed adventure. Jackie Chan plays a bored and unsuccessful salesman who never thought his life would amount to anything. All that changes one day when he becomes an instant hero by foiling an attempted bank robbery.', '2001-01-18', 5.99, 'https://image.tmdb.org/t/p/w500/fPW4Qn9wm82uOexHMB3TC8x6lRU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11971, 'Much Ado About Nothing', 'In this Shakespearean farce, Hero and her groom-to-be, Claudio, team up with Claudio''s commanding officer, Don Pedro, the week before their wedding to hatch a matchmaking scheme. Their targets are sharp-witted duo Benedick and Beatrice -- a tough task indeed, considering their corresponding distaste for love and each other. Meanwhile, meddling Don John plots to ruin the wedding.', '1993-05-07', 6.95, 'https://image.tmdb.org/t/p/w500/tvltGP6vYOkHdURag0jPSjhPUAV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11910, 'Hogfather', 'It''s the night before Hogswatch, usually a time of joy on Discworld, but there are suspicious going-on and the criminal underworld is abuzz. The beloved Hogfather - the jolly bearer of glee and pork-related gifts for children everywhere - has vanished. Suddenly, Discworld''s entire mythical system is under threat. The fate of this magical time rests in the hands of a very motley group: A band of wizards headed up by a mystical university president named Mustrum Ridcully (Joss Ackland), a loyal manservant called Albert (David Jason), a level-headed governess called Susan Sto Heilt (Michelle Dockery), and her grandfather, who happens to be - Death (Marnix van den Broeke).', '2007-10-12', 6.83, 'https://image.tmdb.org/t/p/w500/t6HqXGne1LkRShTot23Hhlm3z5e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11956, 'When the Cat''s Away', 'When Chloe, a young Parisian, decides to take a long-overdue vacation, she has to find someone to look after Gris-Gris, her beloved cat. Everyone, including her gay male roommate, refuses to help her, but she finally makes an arrangement with the elderly Madame Renée, who often watches over other peoples'' cats and dogs. However, when Chloe comes back, Madame Renée tells her that unfortunately the cat has been lost, and the unlucky owner goes on a search for her dear animal friend. While looking for the cat, she meets many colorful characters who populate the neighborhood.', '1996-04-03', 6.23, 'https://image.tmdb.org/t/p/w500/vZjHfDpE74EmbknicrTg4n5YOLr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11843, 'The Return of the Pink Panther', 'The famous Pink Panther jewel has once again been stolen and Inspector Clouseau is called in to catch the thief. The Inspector is convinced that ''The Phantom'' has returned and utilises all of his resources – himself and his Asian manservant – to reveal the identity of ''The Phantom''.', '1975-05-21', 6.80, 'https://image.tmdb.org/t/p/w500/cDi6lHXmY12SxtjcP6IdK7mB3W1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11975, 'The Rainmaker', 'Fresh out of law school and desperate for work, idealistic rookie Rudy Baylor takes on a powerful insurance company accused of denying a dying boy’s claim. Teaming up with a scrappy, unlicensed paralegal, he finds himself in a David-versus-Goliath courtroom battle that tests his ethics, courage, and belief in justice.', '1997-11-18', 7.02, 'https://image.tmdb.org/t/p/w500/twLGHXPjQtS8UyVGp5GXmhJiTM7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11908, 'Hatchet', 'When a group of tourists on a New Orleans haunted swamp tour find themselves stranded in the wilderness, their evening of fun and spooks turns into a horrific nightmare.', '2006-04-27', 5.75, 'https://image.tmdb.org/t/p/w500/lkh3Fwruds78feXfP1Zb9kBLydL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11978, 'Men of Honor', 'Against formidable odds -- and an old-school diving instructor embittered by the U.S. Navy''s new, less prejudicial policies -- Carl Brashear sets his sights on becoming the Navy''s first African-American master diver in this uplifting true story. Their relationship starts out on the rocks, but fate ultimately conspires to bring the men together into a setting of mutual respect, triumph and honor.', '2000-09-13', 7.49, 'https://image.tmdb.org/t/p/w500/wNUAnXV1mzOOfvnVBIYsalkk078.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11959, 'UHF', 'The eccentric new manager of a UHF television channel tries to save the station from financial ruin with an odd array of programming.', '1989-07-21', 6.70, 'https://image.tmdb.org/t/p/w500/wxx5YQLKVH1WMSRXQAUnC76r4iY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11928, 'Tetro', 'In Buenos Aires, 17-year-old Bennie seeks out his estranged brother Tetro, a once-promising writer haunted by their family’s past. As Bennie uncovers Tetro’s hidden manuscript, old secrets and rivalries resurface, forcing both men to confront the truth about their father and the tangled legacy that tore their family apart.', '2009-06-11', 6.78, 'https://image.tmdb.org/t/p/w500/t2FKTAf9aQoRgU0Z5KTJJwBfDCF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11974, 'The ''Burbs', 'When secretive new neighbors move in next door, suburbanite Ray Peterson and his friends let their paranoia get the best of them as they start to suspect the newcomers of evildoings and commence an investigation. But it''s hardly how Ray, who much prefers drinking beer, reading his newspaper and watching a ball game on the tube expected to spend his vacation.', '1989-02-17', 6.75, 'https://image.tmdb.org/t/p/w500/jwYKzJS0C3A711hmg1G4ptI0InF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11980, 'The Prophecy', 'The angel Gabriel comes to Earth to collect a soul which will end the stalemated war in Heaven. However, it is hidden inside of a Native American girl and only a former priest and a schoolteacher can stop him.', '1995-08-05', 6.51, 'https://image.tmdb.org/t/p/w500/4ZWFhQipzBHJze2llzCzhrSIZsn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11982, 'Look Who''s Talking Now!', 'When high-powered executive Samantha LeBon hatches a scheme to spend a romantic Christmas with her new employee – the unsuspecting, blithesome James – his wife, their kids and their two dogs, Rocks and Daphne, must rescue him before he makes a terrible mistake.', '1993-11-05', 5.37, 'https://image.tmdb.org/t/p/w500/73JahFiizkMVsrrslXInmNK54nC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11983, 'Proof of Life', 'When Peter Bowman, an American engineer working in a South American country, is captured by anti-government forces, the rebels learn his identity and demand $5 million for his safe return. However, his US employer is on the verge of insolvency and will not provide the ransom. Peter''s wife Alice is forced to deal with the matter on her own and she retains the services of freelance professional hostage negotiator Terry Thorne.', '2000-12-08', 6.15, 'https://image.tmdb.org/t/p/w500/yw8x2i3vaHZZzpvqvF75E8q2N6M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12079, 'Spun', 'Over the course of three days Ross, a college dropout addicted to crystal-meth, encounters a variety of oddball folks - including a stripper named Nikki and her boyfriend, the local meth producer, The Cook - but all he really wants to do is hook up with his old girlfriend, Amy.', '2003-02-07', 6.55, 'https://image.tmdb.org/t/p/w500/jiwNobUsd29ooowQyTeh0cvPBFL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12088, 'Fortress', 'In the future, the inmates of a private underground prison are computer-controlled with cameras, dream readers, and devices that can cause pain or death. John and his illegally pregnant wife Karen are locked inside "The Fortress" but are determined to escape before the birth of their baby.', '1992-12-18', 6.08, 'https://image.tmdb.org/t/p/w500/evjpqWPUY4VpOdyLpeRfkGU8DiR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12090, 'Just Married', 'Although Tom Leezak and Sarah McNerney come from different worlds, they are both unexpectedly swept off their feet after their first meeting. They quickly fall in love and plan to get married, despite opposition from Sarah''s uptight, rich family. After their wedding, the happy couple sets off - with the highest of hopes and ideals about love and marriage - on what they expect will be the perfect honeymoon in Italy. Thanks to a relentless string of bad luck with one disaster after another, and an impromptu visit from Sarah''s wealthy one-time ex-lover Peter Prentiss, the newlyweds experience the honeymoon from hell that tests the limits of their young love.  Is it worth throwing away their love and marriage?', '2003-01-08', 5.76, 'https://image.tmdb.org/t/p/w500/FRqnYDjbstsCgLSJJ3SifOh2ca.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12092, 'Alice in Wonderland', 'On a golden afternoon, wildly curious young Alice tumbles into the burrow and enters the merry, madcap world of Wonderland full of whimsical escapades.', '1951-08-09', 7.19, 'https://image.tmdb.org/t/p/w500/20cvfwfaFqNbe9Fc3VEHJuPRxmn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12093, 'Lilya 4-ever', 'In a struggling post-Soviet community, Lilya a teenage girl is abandoned when her mother moves to the United States with her boyfriend. Facing neglect and poverty, she meets Andrei, who offers her a job in Sweden, giving her hope for a better life — and a journey that will change everything.', '2002-08-23', 7.60, 'https://image.tmdb.org/t/p/w500/5i1uhvcdv2Iogx0Bb1znvUmkCvN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12095, 'From Dusk Till Dawn 2: Texas Blood Money', 'A bank-robbing gang of misfits heads to Mexico with the blueprints for the perfect million-dollar heist, but when one of the crooks wanders into the wrong bar, the thieving cohorts develop a thirst for blood.', '1999-03-16', 4.62, 'https://image.tmdb.org/t/p/w500/wX129q3nFVTQVaJSHqFnTVfoIG9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12094, 'Jackass Number Two', 'Jackass Number Two is a compilation of various stunts, pranks and skits, and essentially has no plot. Chris Pontius, Johnny Knoxville, Steve-O, Bam Margera, and the whole crew return to the screen to raise the stakes higher than ever before.', '2006-09-22', 6.60, 'https://image.tmdb.org/t/p/w500/u73V8dMqUwjtPL6gWesCE7ji9GU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12100, 'Windtalkers', 'Joe Enders is a gung-ho Marine assigned to protect a "windtalker" - one of several Navajo Indians who were used to relay messages during World War II because their spoken language was indecipherable to Japanese code breakers.', '2002-06-07', 6.36, 'https://image.tmdb.org/t/p/w500/547q4HXlvEcS06lujfb2yzsTP3H.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12096, 'The Pink Panther', 'When the coach of the France football team is killed by a poisoned dart in the stadium at the end of a game, and his huge, expensive ring with the Pink Panther diamond  disappears, the ambitious Chief Inspector Dreyfus assigns the worst police inspector – Jacques Clouseau – to the case.', '2006-02-10', 5.87, 'https://image.tmdb.org/t/p/w500/57ViRkdsddHLK32W8Nf3ZPLSAu4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12101, 'Soylent Green', 'In the year 2022, overcrowding, pollution,  and resource depletion have reduced society’s leaders to finding food for the teeming masses. The answer is Soylent Green.', '1973-04-18', 6.92, 'https://image.tmdb.org/t/p/w500/5nbkShkOEXUoKVhaX0XG41wyBkq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12102, 'Kramer vs. Kramer', 'Ted Kramer is a career man for whom his work comes before his family. His wife Joanna cannot take this anymore, so she decides to leave him. Ted is now faced with the tasks of housekeeping and taking care of himself and their young son Billy.', '1979-12-07', 7.57, 'https://image.tmdb.org/t/p/w500/3CUP5V5SWfHSK4qvkZF7lMNyugY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12103, 'Don''t Say a Word', 'When the daughter of a psychiatrist is kidnapped, he is horrified to discover that the abductors'' demand is that he break through to a young woman, suffering from PTSD, who knows a secret six digit code number.', '2001-09-28', 6.27, 'https://image.tmdb.org/t/p/w500/mDawnZWQnePqQbiisEWZaY9e4UI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12104, 'Pink Floyd: The Wall', 'A troubled rock star descends into madness in the midst of his physical and social isolation from everyone.', '1982-07-14', 7.95, 'https://image.tmdb.org/t/p/w500/aElHyIdF5jmctFGhlhhaPFsbBJC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12106, 'The Quick and the Dead', 'A mysterious woman comes to compete in a quick-draw elimination tournament, in a town taken over by a notorious gunman.', '1995-02-09', 6.54, 'https://image.tmdb.org/t/p/w500/jhEmrXJpP6F3cqwyLjvgBgxxxFA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12105, 'Yellow Submarine', 'The wicked Blue Meanies take over Pepperland, eliminating all color and music. As the only survivor, the Lord Admiral escapes in the yellow submarine and journeys to Liverpool to enlist the help of the Beatles.', '1968-07-17', 7.20, 'https://image.tmdb.org/t/p/w500/1pmeLKaLFNggcsAk5FiouIvo3ST.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11929, 'Dolores Claiborne', 'Dolores Claiborne was accused of killing her abusive husband twenty years ago, but the court''s findings were inconclusive and she was allowed to walk free. Now she has been accused of killing her employer, Vera Donovan, and this time there is a witness who can place her at the scene of the crime. Things look bad for Dolores when her daughter Selena, a successful Manhattan magazine writer, returns to cover the story.', '1995-03-24', 7.26, 'https://image.tmdb.org/t/p/w500/yqY5h9kI456xXRWv6u9t0Axn9CS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12107, 'Nutty Professor II: The Klumps', 'The hilarity begins when professor Sherman Klump finds romance with fellow DNA specialist, Denise Gaines, and discovers a brilliant formula that reverses aging. But Sherman''s thin and obnoxious alter ego, Buddy Love, wants out...and a big piece of the action. And when Buddy gets loose, things get seriously nutty.', '2000-07-27', 5.01, 'https://image.tmdb.org/t/p/w500/v8gI95Eio7kAjixyqYHxNKmJTmm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11963, 'Three Days of the Condor', 'When bookish CIA researcher Joe Turner finds all his co-workers dead, he, together with a woman he has kidnapped, must work together to outwit those responsible until he determines who he can really trust.', '1975-09-24', 7.27, 'https://image.tmdb.org/t/p/w500/zinwtZqdb7gnc4zMu8dfkK1fMN3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12112, 'He Loves Me… He Loves Me Not', 'A talented art student named Angélique is passionately in love with Dr. Loïc Le Garrec, a handsome married man whom she believes will leave his wife. When he eventually decides to stay in his marriage, it causes Angélique to spiral. However, as the story shifts from Angélique''s perspective to Loïc''s, the surprising truth about their relationship is revealed.', '2002-03-27', 6.71, 'https://image.tmdb.org/t/p/w500/dW5txTgCQADtHSyl2iRIc05iANX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12113, 'Body of Lies', 'The CIA’s hunt is on for the mastermind of a wave of terrorist attacks. Roger Ferris is the agency’s man on the ground, moving from place to place, scrambling to stay ahead of ever-shifting events. An eye in the sky – a satellite link – watches Ferris.  At the other end of that real-time link is the CIA’s Ed Hoffman, strategizing events from thousands of miles away. And as Ferris nears the target, he discovers trust can be just as dangerous as it is necessary for survival.', '2008-10-09', 6.63, 'https://image.tmdb.org/t/p/w500/sLjVDPPfNQfAma9XyOqHPClQb2V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12110, 'Dracula: Dead and Loving It', 'When a lawyer shows up at the vampire''s doorstep, he falls prey to his charms and joins him in his search for fresh blood. Enter Professor Van Helsing, who may be the only one able to vanquish the Count.', '1995-12-22', 6.07, 'https://image.tmdb.org/t/p/w500/4rRfZz8YnHNRr16t3CFcJrPdXHi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12117, 'Instinct', 'In a prison for the criminally insane, deranged anthropologist Ethan Powell is set to be examined by a bright young psychiatrist, Theo Caulder. Driven by ambition and a hunger for the truth, Caulder will eventually risk everything—even put his very life on the line—in a harrowing attempt to understand the bizarre actions of this madman.', '1999-06-04', 6.50, 'https://image.tmdb.org/t/p/w500/8EKmzia6awjsqFxgBk5a82aTmb6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12118, 'Police Academy 3: Back in Training', 'When police funding is cut, the Governor announces he must close one of the academies. To make it fair, the two police academies must compete against each other to stay in operation. Mauser persuades two officers in Lassard''s academy to better his odds, but things don''t quite turn out as expected...', '1986-03-20', 5.82, 'https://image.tmdb.org/t/p/w500/pBxGgWSR0CMaCVMA2kQS5MWU1z3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11906, 'Suspiria', 'An American newcomer to a prestigious German ballet academy comes to realize that the school is a front for something sinister amid a series of grisly murders.', '1977-02-01', 7.46, 'https://image.tmdb.org/t/p/w500/sEcvc9h1X3hYZdFgtiiKMm6RB3f.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11911, 'Mephisto', 'A German stage actor finds unexpected success and mixed blessings in the popularity of his performance in a Faustian play as the Nazis take power in pre-WWII Germany. As his associates and friends flee or are ground under by the Nazi terror, the popularity of his character supercedes his own existence until he finds that his best performance is keeping up appearances for his Nazi patrons.', '1981-02-11', 7.29, 'https://image.tmdb.org/t/p/w500/SNJoUTU8PSxQlj3RkrwYGOQPyj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11979, 'Queen of the Damned', 'Vampire Lestat awakens from his slumber and becomes a rock star. But chaos strikes when his music awakens Akasha, the vampire queen, who may not rest until she makes Lestat her new king.', '2002-02-10', 6.12, 'https://image.tmdb.org/t/p/w500/zkw9xEirdADjaUBuaBvVuGvlHPv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11917, 'Saw V', 'Following Jigsaw''s grisly demise, Detective Mark Hoffman is commended as a hero, but Agent Strahm is suspicious, and delves into Hoffman''s past. Meanwhile, another group of people are put through a series of gruesome tests.', '2008-10-23', 6.17, 'https://image.tmdb.org/t/p/w500/rKl79KqLXg60KFyKsLe4wSSjQ08.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11968, 'Into the Blue', 'When they take some friends on an extreme sport adventure, the last thing Jared and Sam expect to see below the shark-infested waters is a legendary pirate ship rumored to contain millions of dollars in gold. But their good fortune is short-lived, as a ruthless gang of criminals gets word of what they have uncovered.', '2005-09-30', 5.90, 'https://image.tmdb.org/t/p/w500/h5oXcjRu0EOiAxSxYuGq58897tu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11931, 'In Her Shoes', 'Irresponsible party girl Maggie is kicked out of her father''s and stepmother''s home—where she lives for free—and is taken in by her hard-working sister, Philadelphia lawyer Rose. After Maggie''s disruptive ways ruin her sister''s love life, Rose turns her out as well. But when their grandmother, who they never knew existed, comes into their lives, the sisters face some complicated truths about themselves and their family.', '2005-10-07', 6.22, 'https://image.tmdb.org/t/p/w500/gmd2n3TuXewrbINp8Jfhwd5Jw6S.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12109, 'It''s All Gone Pete Tong', 'A comedy following the tragic life of the legendary Frankie Wilde. The story takes us through Frankie''s life from being one of the best DJs alive, through a subsequent battle with a hearing disorder, culminating in his mysterious disappearance from the scene.', '2004-09-12', 6.55, 'https://image.tmdb.org/t/p/w500/4AvbVwbejmSMKGEdLmVYDLAss1i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11967, 'Young Guns', 'A group of young gunmen, led by Billy the Kid, become deputies to avenge the murder of the rancher who became their benefactor. But when Billy takes their authority too far, they become the hunted.', '1988-08-12', 6.69, 'https://image.tmdb.org/t/p/w500/3AgCq7xY1rHRAAn0iVcnNr2OWL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12120, 'My Stepmother Is an Alien', 'Trying to rescue her home planet from destruction, a gorgeous extraterrestrial named Celeste arrives on Earth and begins her scientific research. She woos quirky scientist Dr. Steve Mills, a widower with a young daughter. Before long, Celeste finds herself in love with Steve and her new life on Earth, where she experiences true intimacy for the first time. But when she loses sight of her mission, she begins to question where she belongs.', '1988-12-09', 5.81, 'https://image.tmdb.org/t/p/w500/SIt5FbgvoxlZr8ay3cfi79pV6z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11932, 'Bride of Chucky', 'For ten years, the tortured soul of serial killer Charles Lee Ray has been imprisoned inside a child''s doll. Chucky is reborn when his old flame, Tiffany, rescues his battered doll parts from a police impound. But Chucky wants his new playmate cut down to size, so he transforms his blushing bride into a stunning little terror. Chucky and Tiffany can''t wait to start their own homicidal honeymoon. When this demonic duo hits the road and hooks up with a pair of unsuspecting newlyweds, they leave a trail of murder and mayhem behind them. Chucky''s back!', '1998-10-15', 6.10, 'https://image.tmdb.org/t/p/w500/yaIPNOcC7ZRuwH3maNwP9qzIo5G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12122, 'Village of the Damned', 'An American village is visited by some unknown life form which leaves the women of the village pregnant. Nine months later, the babies are born, and they all look normal, but it doesn''t take the "parents" long to realize that the kids are not human or humane.', '1995-04-28', 6.10, 'https://image.tmdb.org/t/p/w500/hDNZHzYy62mOAsby0PTadKQh7so.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12129, 'Herbie Goes Bananas', 'The adorable little VW helps its owners break up a counterfeiting ring in Mexico.', '1980-06-25', 5.38, 'https://image.tmdb.org/t/p/w500/7cBOYLDhHMA351ndLthSxBCwO5N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12150, 'Sea of Love', 'Seen-it-all New York detective Frank Keller is unsettled - he has done twenty years on the force and could retire, and he hasn''t come to terms with his wife leaving him for a colleague. Joining up with an officer from another part of town to investigate a series of murders linked by the lonely hearts columns he finds he is getting seriously and possibly dangerously involved with Helen, one of the main suspects.', '1989-09-15', 6.60, 'https://image.tmdb.org/t/p/w500/vJ88WmJ12eAK9CRb3cggn9CJthH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12121, 'Made in America', 'A young black woman discovers that her father was a sperm donor, and if that wasn''t bad enough, he''s white.', '1993-01-06', 5.54, 'https://image.tmdb.org/t/p/w500/1NLhOZN4AcTSvEPMI3HCjTVSfvy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12151, 'Ruthless People', 'Sam Stone hates his wife Barbara so much that he wants her dead. He''s ecstatic when she''s taken by a duo of kidnappers who want $500,000 ransom in exchange for her life. Fully intending to ignore every one of the kidnappers'' demands in the hopes that they do him a favor and murder her for him, the two confused kidnappers have to figure out how they''re going get their money, and what they''re going to do with the overbearing Barbara.', '1986-06-26', 6.58, 'https://image.tmdb.org/t/p/w500/fA3f8bsXoVbIALq4EdiAwptF1ws.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12153, 'White Chicks', 'Two FBI agent brothers, Marcus and Kevin Copeland, accidentally foil a drug bust. To avoid being fired they accept a mission escorting a pair of socialites to the Hamptons--but when the girls are disfigured in a car accident, they refuse to go. Left without options, Marcus and Kevin decide to pose as the sisters, transforming themselves from black men into rich European-American women.', '2004-06-23', 6.96, 'https://image.tmdb.org/t/p/w500/aHTUpo45qy9QYIOnVITGGqLoVcA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11966, 'Short Circuit 2', 'Robot Johnny 5 moves to the city to help his friend Ben Jahrvi with his toy manufacturing enterprise, only to be manipulated by criminals who want to use him for their own nefarious purposes.', '1988-07-06', 6.22, 'https://image.tmdb.org/t/p/w500/vXzkNsPEA59EON5PMVXsURe8o67.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12154, '3 Men and a Baby', 'Three bachelors find themselves forced to take care of a baby left by one of the guy''s girlfriends.', '1987-11-27', 6.18, 'https://image.tmdb.org/t/p/w500/oYetboAljWR2N5A7MU3i63DvUtd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12157, 'Green Card', 'Urban horticulturalist Brontë Mitchell has her eye on a gorgeous apartment, but the building''s board will rent it only to a married couple. Georges Fauré, a waiter from France whose visa is expiring, needs to marry an American woman to stay in the country. Their marriage of convenience turns into a burden when they must live together to allay the suspicions of the immigration service, as the polar opposites grate on each other''s nerves.', '1990-12-23', 6.13, 'https://image.tmdb.org/t/p/w500/9UweLsv3pCORu25Uq72m2IBkKaK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12155, 'Alice in Wonderland', 'Alice, now 19 years old, returns to the whimsical world she first entered as a child and embarks on a journey to discover her true destiny.', '2010-03-03', 6.64, 'https://image.tmdb.org/t/p/w500/o0kre9wRCZz3jjSjaru7QU0UtFz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12158, 'Vampire in Brooklyn', 'Detective Rita Veder is assigned to a baffling serial murder case. After examining the crime scene — a corpse-filled ship found adrift at sea — she meets Maximilian, a smooth-talking Caribbean playboy determined to romance her.', '1995-10-26', 5.09, 'https://image.tmdb.org/t/p/w500/fodPA5x3REtOwColG17CucreZqM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11933, 'Nothing but Trouble', 'While attempting to seduce gorgeous lawyer Diane Lightson, wealthy gadabout Chris Thorne agrees to drive her to Atlantic City, N.J. But, when some reckless driving draws the attention of a deeply critical cop, they and the flamboyant "Brazillionaires" who tagged along end up in the court of a grotesque and vengeful judge, who has a special vendetta against the wealthy and erudite.', '1991-02-15', 5.30, 'https://image.tmdb.org/t/p/w500/Apk5Hbby70diyeMHd2VhxUSHNW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12159, 'What Dreams May Come', 'Chris Nielsen dies to find himself in a heaven more amazing than he could have ever dreamed of. There is one thing missing: his wife. After he died, his wife Annie killed herself and went to hell. Chris decides to risk eternity in Hades for the small chance that he will be able to bring her back to heaven.', '1998-10-02', 7.24, 'https://image.tmdb.org/t/p/w500/78wCdphUzeb528wLZw2W0fn7yGB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12160, 'Wyatt Earp', 'From Wichita to Dodge City, to the O.K. Corral in Tombstone, Wyatt Earp is taught that nothing matters more than family and the law. Joined by his brothers and Doc Holliday, Earp wages war on the dreaded Clanton and McLaury gangs.', '1994-06-24', 6.80, 'https://image.tmdb.org/t/p/w500/51LItgyecu2KMAtIchYogEykCIu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12163, 'The Wrestler', 'Aging wrestler Randy "The Ram" Robinson is long past his prime but still ready and rarin'' to go on the pro-wrestling circuit. After a particularly brutal beating, however, Randy hangs up his tights, pursues a serious relationship with a long-in-the-tooth stripper, and tries to reconnect with his estranged daughter. But he can''t resist the lure of the ring and readies himself for a comeback.', '2008-12-17', 7.54, 'https://image.tmdb.org/t/p/w500/7QH5p5BF582k6qHufCKjftfkqWH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12162, 'The Hurt Locker', 'During the Iraq War, a Sergeant recently assigned to an army bomb squad is put at odds with his squad mates due to his maverick way of handling his work.', '2008-10-10', 7.25, 'https://image.tmdb.org/t/p/w500/io2dfBJhasvGbgkCX9cCGVOiA99.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12171, 'The Deaths of Ian Stone', 'Deaths tells the story of an all-American guy who is murdered each day by horrifying pursuers, only to wake up in slightly different lives to experience the terror of being murdered again.', '2008-07-18', 5.58, 'https://image.tmdb.org/t/p/w500/guhprfoix4DCKnbPeVQXuF08rHt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12180, 'Star Wars: The Clone Wars', 'As the Clone Wars sweep through the galaxy, Anakin Skywalker and his new Padawan learner Ahsoka Tano plunge into a dangerous mission to rescue the kidnapped son of crime lord Jabba the Hutt.', '2008-08-05', 6.15, 'https://image.tmdb.org/t/p/w500/iJQfixW818LUdSXlCDL3JZm0S0g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12172, 'Encounters at the End of the World', 'Acclaimed filmmaker Werner Herzog travels to Antarctica, where he finds a desolate, beautiful landscape, largely untouched by human hands, and a group of truly unique people who risk their lives to study it. Centered at McMurdo Station, the United States'' largest Antarctic research center, Herzog explores the minds of the scientists willing to abandon civilization and endure volatile conditions to learn more about the continent''s wildlife and awe-inspiring natural wonders.', '2007-09-01', 7.47, 'https://image.tmdb.org/t/p/w500/gZVQoVCCFhqWoeskAcMtPHjTbro.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12138, '3000 Miles to Graceland', 'It was an ingenious enough plan: rob the Riviera Casino''s count room during an Elvis impersonator convention. But Thomas Murphy decided to keep all the money for himself and shot all his partners, including recently-freed ex-con Michael Zane. With $3.2 million at stake, the Marshals Service closing in, Michael must track down Murphy.', '2001-02-23', 5.88, 'https://image.tmdb.org/t/p/w500/nJgr5sGoXnsgZ0EVt80i6X9dQiA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12182, 'Nick and Norah''s Infinite Playlist', 'Nick cannot stop obsessing over his ex-girlfriend, Tris, until Tris'' friend Norah suddenly shows interest in him at a club. Thus begins an odd night filled with ups and downs as the two keep running into Tris and her new boyfriend while searching for Norah''s drunken friend, Caroline, with help from Nick''s band mates. As the night winds down, the two have to figure out what they want from each other.', '2008-10-03', 6.44, 'https://image.tmdb.org/t/p/w500/cndxWgZEHnSUtytrMjal97ye34E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12177, 'The Love Guru', 'Born in America and raised in an Indian ashram, Pitka returns to his native land to seek his fortune as a spiritualist and self-help expert. His skills are put to the test when he must get a brokenhearted hockey player''s marriage back on track in time for the man to help his team win the Stanley Cup.', '2008-06-20', 4.06, 'https://image.tmdb.org/t/p/w500/sp8AV64ftAZCT9uWfgbCb3olGDW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12184, 'The Other Boleyn Girl', 'A sumptuous and sensual tale of intrigue, romance and betrayal set against the backdrop of a defining moment in European history: two beautiful sisters, Anne and Mary Boleyn, driven by their family''s blind ambition, compete for the love of the handsome and passionate King Henry VIII.', '2008-02-28', 6.71, 'https://image.tmdb.org/t/p/w500/q2lgC8mmAltWTkbqPM8n5EYF4XL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12185, 'Heaven Can Wait', 'Joe Pendleton is a quarterback preparing to lead his team to the superbowl when he is almost killed in an accident. An overanxious angel plucks him to heaven only to discover that he wasn''t ready to die, and that his body has been cremated. A new body must be found, and that of a recently-murdered millionaire is chosen. His wife and accountant—the murderers—are confused by this development, as he buys the L.A. Rams in order to once again quarterback them into the Superbowl.', '1978-06-28', 6.65, 'https://image.tmdb.org/t/p/w500/h1yOiO9cow6gwmGxSAWvPdY4lhJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12186, 'Defending Your Life', 'Is there love after death? After he dies suddenly, the hapless advertising executive Daniel Miller finds himself in Judgment City, a gleaming way station where the newly deceased must prove they lived a life of sufficient courage to advance in their journey through the universe. As the self-doubting Daniel struggles to make his case, a budding relationship with the uninhibited Julia offers him a chance to finally feel alive.', '1991-03-22', 6.92, 'https://image.tmdb.org/t/p/w500/flXJ4AnKYq8DH1f1TmQ4QrqSwsB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12192, 'Pathology', 'Medical student Ted Grey graduates at the top of his class and quickly joins an elite pathology program, whose top students invite him into their circle. There he uncovers a gruesome secret: They play a game in which one tries to commit the perfect, undetectable murder, then the others compete to determine the victim''s cause of death.', '2008-04-11', 5.71, 'https://image.tmdb.org/t/p/w500/tK9DvIwAuX5AExgEZqLCnf7qy5k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12187, 'Heart and Souls', 'A fateful night in 1959, four people die when the bus they are riding crashes. They continue as ghosts; their souls become eternally entwined to the life of a child born at the moment of their deaths as his guardians. Baby Thomas grows up to be a businessman who has memories of his playmates, but assumes they are products of his youthful imagination. When the ghosts realize they need Thomas'' help to move on to the afterlife, they decide to make an appearance once more.', '1993-08-13', 6.98, 'https://image.tmdb.org/t/p/w500/jnMBqMSUwa0Lzh9X1Fwo4f8AMl6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12208, 'Casino Royale', 'Sir James Bond is called back out of retirement to stop SMERSH. In order to trick SMERSH, James thinks up the ultimate plan - that every agent will be named ''James Bond''. One of the Bonds, whose real name is Evelyn Tremble is sent to take on Le Chiffre in a game of baccarat, but all the Bonds get more than they can handle.', '1967-04-18', 5.25, 'https://image.tmdb.org/t/p/w500/9wdw5H018bgIM8bK2HuDvh8BwOh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12211, 'Highlander: Endgame', 'Immortals Connor and Duncan Macleod join forces against a man from Connor''s distant past in the highlands of Scotland, Kell, an immensely powerful immortal who leads an army of equally powerful and deadly immortal swordsmen and assassins. No immortal alive has been able to defeat Kell yet, and neither Connor nor Duncan are skilled enough themselves to take him on and live. The two of them eventually come to one inevitable conclusion; one of them must die so that the combined power of both the Highlanders can bring down Kell for good. There can be only one... the question is, who will it be?', '2000-09-01', 4.79, 'https://image.tmdb.org/t/p/w500/u7kIXMyagqcek2SaS9svfPTTGVT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11972, 'The Little World of Don Camillo', 'In a village of the Po valley where the earth is hard and life miserly, the priest and the communist mayor are always fighting to be the head of the community. If in secret, they admired and liked each other, politics still divided them as it is dividing the country. And when the mayor wants his "People''s House"; the priest wants his "Garden City" for the poor. Division exist between the richest and the poorest, the pious and the atheists and even between lovers. But if the people are hard as the country, they are good in the bottom of there heart.', '1952-03-28', 7.56, 'https://image.tmdb.org/t/p/w500/bDbzuBgsgZ5VVljMHNni3gJK9Qx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12212, 'Urban Legends: Final Cut', 'The making of a horror movie takes on a terrifying reality for students at the most prestigious film school in the country. At Alpine University, someone is determined to win the best film award at any cost - even if it means eliminating the competition. No one is safe and everyone is a suspect.', '2000-09-22', 4.92, 'https://image.tmdb.org/t/p/w500/9kjGrnhMz37RYEd5BFcrU1qkPkl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11969, 'Tombstone', 'Legendary marshal Wyatt Earp, now a weary gunfighter, joins his brothers Morgan and Virgil to pursue their collective fortune in the thriving mining town of Tombstone. But Earp is forced to don a badge again and get help from his notorious pal Doc Holliday when a gang of renegade brigands and rustlers begins terrorizing the town.', '1993-12-25', 7.58, 'https://image.tmdb.org/t/p/w500/wGFCvylul8iEQhJOKfwZGGvXMzA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12139, 'Dennis the Menace', 'Mr. Wilson''s ever-present annoyance comes in the form of one mischievous kid named Dennis. But he''ll need Dennis''s tricks to uncover a collection of gold coins that go missing when a shady drifter named Switchblade Sam comes to town.', '1993-06-09', 5.88, 'https://image.tmdb.org/t/p/w500/t642WwGifbQ2fEuKTJRgpPzsgtX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12123, 'Chain Reaction', 'At the University of Chicago, a research team that includes brilliant student machinist Eddie Kasalivich experiences a breakthrough: a stable form of fusion that may lead to a waste-free energy source. However, a private company wants to exploit the technology, so Kasalivich and physicist Dr. Lily Sinclair are framed for murder, and the fusion device is stolen. On the run from the FBI, they must recover the technology and exonerate themselves.', '1996-08-02', 5.81, 'https://image.tmdb.org/t/p/w500/4ahjVHwXXsq5zK57ds8FwWY73MS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12140, 'Ghost in the Shell 2: Innocence', 'Cyborg detective Batou is assigned to investigate a series of murders committed by gynoids—doll-like cyborgs, which all malfunctioned, killed, then self-destructed afterwards. The brains of the gynoids initialize in order to protect their manufacturer''s software, but in one gynoid, which Batou himself neutralized, one file remains: a voice speaking the phrase "Help me."', '2004-03-06', 7.35, 'https://image.tmdb.org/t/p/w500/1ZJRbLDVr90KLtKdmTT4WZhT26E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12193, 'Four Christmases', 'Brad and Kate have made something of an art form out of avoiding their families during the holidays, but this year their foolproof plan is about go bust -- big time. Stuck at the city airport after all departing flights are canceled, the couple is embarrassed to see their ruse exposed to the world by an overzealous television reporter. Now, Brad and Kate are left with precious little choice other than to swallow their pride and suffer the rounds.', '2008-11-26', 5.82, 'https://image.tmdb.org/t/p/w500/zixj44TC7rwzpxtJAG5OzFJnEqe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12219, '12 Angry Men', 'During the trial of a man accused of his father''s murder, a lone juror takes a stand against the guilty verdict handed down by the others as a result of their preconceptions and prejudices.', '1997-08-17', 7.70, 'https://image.tmdb.org/t/p/w500/whDdYx3lh1LHTN0VlPFt51fX29g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11973, 'Thirteen Days', 'The story of the Cuban Missile Crisis in 1962—the nuclear standoff with the USSR sparked by the discovery by the Americans of missile bases established on the Soviet-allied island of Cuba.', '2000-12-25', 6.99, 'https://image.tmdb.org/t/p/w500/aLx9UXH9fK2v6NDMvMyW4X88K3u.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11976, 'Legend', 'Set in a timeless mythical forest inhabited by fairies, goblins, unicorns and mortals, this fantastic story follows a mystical forest dweller, chosen by fate, to undertake a heroic quest. He must save the beautiful Princess  Lili and defeat the demonic Lord of Darkness, or the world will be plunged into a never-ending ice age.', '1985-08-28', 6.25, 'https://image.tmdb.org/t/p/w500/6n3PQSYpZRK5YPk2w8JEwED7AZk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12143, 'Bad Lieutenant', 'While investigating a young nun''s rape, a corrupt New York City police detective, with a serious drug and gambling addiction, tries to change his ways and find forgiveness.', '1992-11-20', 6.99, 'https://image.tmdb.org/t/p/w500/mVJ2mXykqq3t2v1nuouf1P10g0d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12142, 'Alone in the Dark', 'Edward Carnby is a private investigator specializing in unexplainable supernatural phenomena. His cases delve into the dark corners of the world, searching for truth in the occult remnants of ancient civilizations. Now, the greatest mystery of his past is about to become the most dangerous case he has ever faced.', '2005-01-28', 3.31, 'https://image.tmdb.org/t/p/w500/bSxrbVCyWW077zhtpuYlo3zgyug.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (11977, 'Caddyshack', 'At an exclusive country club, an ambitious young caddy, Danny Noonan, eagerly pursues a caddy scholarship in hopes of attending college and, in turn, avoiding a job at the lumber yard. In order to succeed, he must first win the favour of the elitist Judge Smails, and then the caddy golf tournament which Smails sponsors.', '1980-07-25', 6.58, 'https://image.tmdb.org/t/p/w500/lXnNz7zOXCsftMDVoU3VSo0Eioi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12133, 'Step Brothers', 'Brennan Huff and Dale Doback might be grown men. But that doesn''t stop them from living at home and turning into jealous, competitive stepbrothers when their single parents marry. Brennan''s constant competition with Dale strains his mom''s marriage to Dale''s dad, leaving everyone to wonder whether they''ll ever see eye to eye.', '2008-07-25', 6.56, 'https://image.tmdb.org/t/p/w500/nvggBbEraUTAVR6ffP3AaBUWSHs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12220, 'The Story of Us', 'After 15 years of marriage, Katie and her husband, Ben, have grown apart. While they keep up the facade of having a contented marriage, mostly to not worry their children, they aren''t happy together and argue frequently. While the kids are away at camp, Katie and Ben decide to separate and try to reassess their relationship to see if they should stay together or split up for good.', '1999-10-14', 6.14, 'https://image.tmdb.org/t/p/w500/8rm0CZpHW1D7pIv8OguJNHF93LV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12242, 'Mulan II', 'Fa Mulan gets the surprise of her young life when her love, Captain Li Shang asks for her hand in marriage. Before the two can have their happily ever after, the Emperor assigns them a secret mission, to escort three princesses to Chang''an, China. Mushu is determined to drive a wedge between the couple after he learns that he will lose his guardian job if Mulan marries into the Li family.', '2004-11-03', 6.53, 'https://image.tmdb.org/t/p/w500/mIHE3BKyAKG8ocRAoZuCQN1NTv9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12238, 'The Night Flier', 'For cynical tabloid journo Richard Dees, facts are always stranger than fiction. Every headline is a dead-line. Serial killers, UFO abductions, tales of molestation, mayhem and murder. To some the tales are mere sleazy fantasy – but his faithful readers believe. And now there''s a new story: The Night Flier. What is it that travels by night in a dark-winged Cessna, lands at secluded airfields and murders local residents? Dees begins to track the unknown killer in a Cessna of his own, uncovering clues that reveal a pilot more terrifying than he could have ever imagined.', '1997-04-30', 5.98, 'https://image.tmdb.org/t/p/w500/3bMb6CzdKfpw0pZWVW2RbQRneIC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12205, 'Dark Water', 'A woman in the midst of an unpleasant divorce moves to an eerie apartment building with her young daughter. The ceiling of their apartment has a dark and active leak.', '2002-01-19', 6.83, 'https://image.tmdb.org/t/p/w500/iSq6J55RFLfwcceDKxYtMjOr1sz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12144, 'The Land Before Time', 'An orphaned brontosaurus named Littlefoot sets off in search of the legendary Great Valley. A land of lush vegetation where the dinosaurs can thrive and live in peace. Along the way he meets four other young dinosaurs, each one a different species, and they encounter several obstacles as they learn to work together in order to survive.', '1988-11-18', 7.16, 'https://image.tmdb.org/t/p/w500/7phV1ETZnQrLsEeuk4hNeceEl25.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12244, '9', 'When 9 first comes to life, he finds himself in a post-apocalyptic world. All humans are gone, and it is only by chance that he discovers a small community of others like him taking refuge from fearsome machines that roam the earth intent on their extinction. Despite being the neophyte of the group, 9 convinces the others that hiding will do them no good.', '2009-08-19', 6.96, 'https://image.tmdb.org/t/p/w500/3uqXGOH4BQ2CLJWkDJZ0PzbUzOn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12246, 'Mongol: The Rise of Genghis Khan', 'The story recounts the early life of Genghis Khan, a slave who went on to conquer half the world in the 11th century.', '2007-09-20', 6.79, 'https://image.tmdb.org/t/p/w500/8hlyJVMKFJNJb8QRtdfjage2tGF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12247, 'Shotgun Stories', 'Shotgun Stories tracks a feud that erupts between two sets of half brothers following the death of their father. Set against the cotton fields and back roads of Southeast Arkansas, these brothers discover the lengths to which each will go to protect their family.', '2007-10-01', 6.92, 'https://image.tmdb.org/t/p/w500/aeIlHt28Z8KmHcKEgl4oLHpwZ8M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12251, 'Mo'' Money', 'Trying to get his act together, a con artist gets a job in a credit card company. He falls in love with a fellow employee, he steals a couple of cards, everything is going great. But soon, the chief of security drags him into the big leagues of criminals...', '1992-07-24', 5.57, 'https://image.tmdb.org/t/p/w500/tLbKMopp46m5i3hukmFkQdCzfDR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12253, 'Biker Boyz', 'A mythic motorcycle tale of father and son, this is the story of Manuel Galloway, also known as "the King of Cali", the president of a motorcycle club whose members are all African-American men, mostly white-collar workers who exchange their suits and ties at night and on weekends for leather outfits and motorcycle helmets.', '2003-01-31', 6.36, 'https://image.tmdb.org/t/p/w500/frb2Tk7DTBshZ61Or0D3M1kslWL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12254, 'Emma', 'Emma Woodhouse is a congenial young lady who delights in meddling in other people’s affairs. She is perpetually trying to unite men and women who are utterly wrong for each other. Despite her interest in romance, Emma is clueless about her own feelings, and her relationship with gentle Mr. Knightley.', '1996-10-02', 6.61, 'https://image.tmdb.org/t/p/w500/oBs9SdyQZXe4E9D1Na8iAA7qvLD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12257, 'Home Fries', 'Dorian and Angus chase down their womanizing stepfather with a helicopter, frightening him to death. In his effort to cover their tracks, Dorian begins investigating his stepfather''s mistress, Sally. She works at a fast-food drive-through, she''s pregnant and Dorian quickly falls in love with her. Unfortunately, his scheming mother wants Sally dead. And Sally isn''t sure she wants Dorian to be her child''s father and also his brother.', '1998-11-25', 5.15, 'https://image.tmdb.org/t/p/w500/rXEpaJIPlBqKq7QepB8uowmeAT2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12268, 'The Pink Panther Strikes Again', 'Charles Dreyfus, who has finally cracked over inspector Clouseau''s antics, escapes from a mental institution and launches an elaborate plan to get rid of Clouseau once and for all.', '1976-09-16', 6.90, 'https://image.tmdb.org/t/p/w500/GGCch9LNAKwp4ZADAcNz1hd1dn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12276, 'The Road Home', 'Prompted by the death of his father and the grief of his mother, a man recalls the story of how they met in flashback.', '1999-10-16', 7.45, 'https://image.tmdb.org/t/p/w500/AbUmBTtVZDpchPA4Yfq4OpIs46X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12262, 'The Hills Have Eyes', 'Taking an ill-advised detour en-route to California, the Carter family soon run into trouble when their RV breaks down in the middle of the desert. Stranded, they find themselves at the mercy of monstrous cannibals lurking in the surrounding hills.', '1977-07-22', 6.16, 'https://image.tmdb.org/t/p/w500/1G2DBIEkoS0JdCiOFIeR3mD8ROE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12222, 'Horton Hears a Who!', 'An imaginative elephant named Horton hears a faint cry for help coming from a tiny speck of dust floating through the air. Horton suspects there may be life on that speck and despite a surrounding community, who thinks he has lost his mind, he is determined to save the tiny particle.', '2008-03-03', 6.53, 'https://image.tmdb.org/t/p/w500/6k47Z3A5zI2rxubTMwiLyIqQLLr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12271, 'Factory Girl', 'In the mid-1960s, wealthy debutant Edie Sedgwick meets artist Andy Warhol. She joins Warhol''s famous Factory and becomes his muse. Although she seems to have it all, Edie cannot have the love she craves from Andy, and she has an affair with a charismatic musician, who pushes her to seek independence from the artist and the milieu.', '2006-12-29', 6.00, 'https://image.tmdb.org/t/p/w500/A5Sq71054VptVUQYGdIjjim4hFn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12277, 'Undercover Brother', 'An Afro-American organization, the B.R.O.T.H.E.R.H.O.O.D., is in permanent fight against a white organization "The Man" defending the values of the black people in North America. When the Afro-American candidate Gen. Warren Boutwell behaves strangely in his presidential campaign, Undercover Brother is hired to work undercover for "The Man" and find what happened with the potential candidate.', '2002-05-31', 5.94, 'https://image.tmdb.org/t/p/w500/vkPm29sqtEjoekOhXbqxTcgpJ4y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12278, 'Soul Man', 'A white prospective grad student''s affluent family won''t pay his way through law school, so he takes tanning pills to darken his skin in order to qualify for an African-American scholarship at Harvard. He soon gets more than he bargained for, as he begins to learn what life is really like for blacks in America.', '1986-10-24', 5.25, 'https://image.tmdb.org/t/p/w500/d6jh6qiowC4QHePBgpy7Zrytbba.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12279, 'Spy Kids 3-D: Game Over', 'Carmen''s caught in a virtual reality game designed by the Kids'' new nemesis, the Toymaker. It''s up to Juni to save his sister, and ultimately the world.', '2003-07-25', 5.13, 'https://image.tmdb.org/t/p/w500/buA8dN4zLNr0dYBeKfHfMnEfdLE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12280, 'The Paper', 'Henry Hackett is the workaholic editor of a New York City tabloid. He loves his job, but the long hours and low pay are leading to discontent. Also, publisher Bernie White faces financial straits, and has hatchet-man Alicia Clark—Henry''s nemesis—impose unpopular cutbacks.', '1994-03-18', 6.56, 'https://image.tmdb.org/t/p/w500/pGPrFbucRLwVtCKCeinwAklAl0l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12281, 'Mean Creek', 'Teenagers living in small-town Oregon take a boat trip for a birthday celebration. When they get an idea to play a mean trick on the town bully, it suddenly goes too far. Soon they''re forced to deal with the unexpected consequences of their actions.', '2004-08-20', 6.83, 'https://image.tmdb.org/t/p/w500/nlU3SJzt5focTIkhLcO0ggnvbpW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12289, 'Red Cliff', 'In 208 A.D., in the final days of the Han Dynasty, shrewd Prime Minster Cao convinced the fickle Emperor Han the only way to unite all of China was to declare war on the kingdoms of Xu in the west and East Wu in the south. Thus began a military campaign of unprecedented scale. Left with no other hope for survival, the kingdoms of Xu and East Wu formed an unlikely alliance.', '2008-07-10', 7.11, 'https://image.tmdb.org/t/p/w500/eEelFTjUYJJDlwqd53VfSA8xMfj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12308, 'The Last Kiss', 'Giulia and Carlo have been happy together for three years, but Giulia''s announcement that she is pregnant sends him into a secret panic. Terrified at his imminent entry into the adult world of irreversible responsibilities, Carlo finds himself tempted by a bewitching 18-year-old girl, Francesca, whom he meets by chance at a wedding. The possibility of one last youthful crazy fling before the impending prison of parenthood proves to be too attractive to resist.', '2001-02-01', 6.35, 'https://image.tmdb.org/t/p/w500/mPrhgVQfvopYaZVCowf4Tqm4UPC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12310, 'The Four Musketeers', 'The Four Musketeers defend the queen and her dressmaker from Cardinal Richelieu and Milady de Winter.', '1974-10-31', 6.46, 'https://image.tmdb.org/t/p/w500/dm0ArEYWrrfyOkMUbKOE8ZnCc92.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12309, 'Bachelor Party', 'On the eve of his wedding to his longtime girlfriend, unassuming nice guy Rick is dragged out for a night of debauchery by his friends.', '1984-06-29', 6.31, 'https://image.tmdb.org/t/p/w500/dZf3UpPZDvJYTODSUJQy7wYEop.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12206, 'The Testament of Dr. Mabuse', 'After a detective is assaulted by thugs and placed in an asylum run by Professor Baum, he observes the professor''s preoccupation with another patient, the criminal genius Dr. Mabuse the hypnotist. When Mabuse''s notes are found to be connected with a rash of recent crimes, Commissioner Lohmann must determine how Mabuse is communicating with the criminals, despite conflicting reports on the doctor''s whereabouts, and capture him for good.', '1933-04-21', 7.58, 'https://image.tmdb.org/t/p/w500/tc2ET7j6X066VCjdHblSwLr8sEz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12311, 'Mutiny on the Bounty', 'Fletcher Christian successfully leads a revolt against the ruthless Captain Bligh on the HMS Bounty. However, Bligh returns one year later, hell bent on revenge.', '1935-11-22', 7.38, 'https://image.tmdb.org/t/p/w500/GD98ozz6F6tSu8BWGulpseEKhv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12312, 'Joe Somebody', 'When underappreciated video specialist Joe Scheffer is brutally humiliated by office bully Mark McKinney in front of his daughter, Joe begins a quest for personal redemption. He proceeds by enduring a personal makeover and takes martial arts lessons from a B-action star. As news spreads of his rematch with Mark, Joe suddenly finds himself the center of attention, ascending the corporate ladder and growing in popularity.', '2001-12-21', 5.67, 'https://image.tmdb.org/t/p/w500/9AJvAour6cslSMy9Q0WLd0jIJh1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12400, 'Redbelt', 'Martial artist Mike Terry lives by a strict code of no competitions, for he feels that such contests weaken fighters. After saving a famous action star from a brutal attack, Mike takes a job in the film industry. He soon finds his personal beliefs and integrity on the line as circumstances force him to participate in a prize fight.', '2008-04-07', 6.42, 'https://image.tmdb.org/t/p/w500/tjLKe0QCGgSrvEd41Z4q2QpSoJF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12335, 'Bedknobs and Broomsticks', 'Three children evacuated from London during World War II are forced to stay with an eccentric spinster. The children''s initial fears disappear when they find out she is in fact a trainee witch.', '1971-10-07', 7.04, 'https://image.tmdb.org/t/p/w500/1BBzsThIZ06UmjZ3rChYGZhJtFQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12411, 'Disgrace', 'Disgrace is the story of a South African professor of English who loses everything: his reputation, his job, his peace of mind, his good looks, his dreams of artistic success, and finally even his ability to protect his cherished daughter. After having an affair with a student, he moves to the Eastern Cape, where he gets caught up in a mess of post-apartheid politics.', '2008-09-06', 6.24, 'https://image.tmdb.org/t/p/w500/xCM4H72gaXGXvJKcocAx8LKxaQC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12403, 'A Perfect Getaway', 'For their honeymoon, newlyweds Cliff and Cydney head to the tropical islands of Hawaii. While journeying through the paradisaical countryside the couple encounters Kale and Cleo, two disgruntled hitchhikers and Nick and Gina, two wild but well-meaning spirits who help guide them through the lush jungles. The picturesque waterfalls and scenic mountainsides quickly give way to terror when Cliff and Cydney learn of a grisly murder that occurred nearby and realize that they''re being followed by chance acquaintances that suspiciously fit the description of the killers.', '2009-06-08', 6.33, 'https://image.tmdb.org/t/p/w500/ncuGG0hIlA03dQBJmdoT2LWgodG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12429, 'Ponyo', 'When Sosuke, a young boy who lives on a clifftop overlooking the sea, rescues a stranded goldfish named Ponyo, he discovers more than he bargained for. Ponyo is a curious, energetic young creature who yearns to be human, but even as she causes chaos around the house, her father, a powerful sorcerer, schemes to return Ponyo to the sea.', '2008-07-19', 7.76, 'https://image.tmdb.org/t/p/w500/yp8vEZflGynlEylxEesbYasc06i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12405, 'Slumdog Millionaire', 'A teenager reflects on his life after being accused of cheating on the Indian version of "Who Wants to be a Millionaire?".', '2008-11-12', 7.73, 'https://image.tmdb.org/t/p/w500/5leCCi7ZF0CawAfM5Qo2ECKPprc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12472, 'The Incredible Shrinking Woman', 'After being exposed to a bizarre mixture of household chemicals, Pat Kramer begins to shrink. This baffles scientists, makes parenting difficult, warms the hearts of Americans, and captures the attention of a group of people who want to take over the world. This evil group plots to kidnap Pat and perform experiments on her so that they can eventually shrink everyone.', '1981-01-30', 5.40, 'https://image.tmdb.org/t/p/w500/cyVWzXAGbj5b76k8XYOB4mZzUMn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12145, 'Fierce Creatures', 'Ex-policeman Rollo Lee is sent to run Marwood Zoo, the newly acquired business of a New Zealand tycoon. In order to meet high profit targets and keep the zoo open, Rollo enforces a new ''fierce creatures'' policy, whereby only the most impressive and dangerous animals are allowed to remain in the zoo. However, the keepers are less enthusiastic about complying with these demands.', '1997-01-23', 6.17, 'https://image.tmdb.org/t/p/w500/1Wl0zSEngmsTXjQMVE0GD5s85cM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12146, 'The Missing', 'When rancher and single mother of two Maggie Gilkeson sees her teenage daughter, Lily, kidnapped by Apache rebels, she reluctantly accepts the help of her estranged father, Samuel, in tracking down the kidnappers. Along the way, the two must learn to reconcile the past and work together if they are going to have any hope of getting Lily back before she is taken over the border and forced to become a prostitute.', '2003-11-26', 6.30, 'https://image.tmdb.org/t/p/w500/86s5nw5F1G8lJtEowO0LBB4hoBW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12475, 'In the Army Now', 'Bones Conway and Jack Kaufman, two misguided youths, join the reserves to make some easy money for their entrepreneurial dreams. Unfortunately, no sooner than they finish basic training they find themselves at war as part of the water purification team.', '1994-08-12', 5.08, 'https://image.tmdb.org/t/p/w500/cNIIDaJM9nsDP9tTmAN6sjKpeiN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12232, 'The Thief of Bagdad', 'When Prince Ahmad is blinded and cast out of Bagdad by the nefarious Jaffar, he joins forces with the scrappy thief Abu to win back his royal place, as well as the heart of a beautiful princess.', '1940-02-19', 7.12, 'https://image.tmdb.org/t/p/w500/8Fs29JYTOkDluTXgbvLRIaps6PO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12223, 'The Stepford Wives', 'Joanna Eberhart comes to the town of Stepford, Connecticut with her family, but soon discovers there lies a sinister truth in the all too perfect behavior of the female residents.', '1975-02-12', 6.69, 'https://image.tmdb.org/t/p/w500/5z1ogJJmQkCoU62VJmut4nnc2qs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12207, 'The Legend of Drunken Master', 'Returning home with his father after a shopping expedition, Wong Fei-Hong is unwittingly caught up in the battle between foreigners who wish to export ancient Chinese artifacts and loyalists who don''t want the pieces to leave the country. Fei-Hong must fight against the foreigners using his Drunken Boxing style, and overcome his father''s antagonism as well.', '1994-02-03', 7.46, 'https://image.tmdb.org/t/p/w500/xqUBrSBtPYLvCtfqHF5sapU6Div.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12435, 'The Nanny Diaries', 'A college graduate goes to work as a nanny for a rich New York family. Ensconced in their home, she has to juggle their dysfunction, a new romance, and the spoiled brat in her charge.', '2007-08-24', 6.38, 'https://image.tmdb.org/t/p/w500/8hX6rcxnCidaqegPCyeFm9PODBn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12485, 'Candyman: Day of the Dead', 'As the Day of the Dead celebration approaches the barrio of East Los Angeles, Caroline is challenged to control the horrifying legend of her ancestor, the "Candyman".', '1999-07-09', 4.60, 'https://image.tmdb.org/t/p/w500/sqr0imYSvDu8Q5nZLNjgAXppVSt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12487, 'Gozu', 'Minami mistakenly kills a gangster associate of his named Brother. Almost as soon as the murder takes place, the body of the deceased man is gone, prompting Minami to conduct a search. While looking, he finds a mysterious isolated hotel where he decides to take a rest. Not only are the front desk clerks a bit strange, but even the ambiance feels unusual. Minami soon realizes he may have gotten more than he bargained for.', '2003-07-11', 6.78, 'https://image.tmdb.org/t/p/w500/mo5L0XzMYmLhdsvgA40qlYiHhAF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12235, 'Jagged Edge', 'After a wealthy heiress is murdered in her beach house, her devastated husband becomes the prime suspect. He hires a lawyer who hasn’t taken a criminal case in years, and as they work together, a complicated romance develops amidst the trial.', '1985-10-04', 6.25, 'https://image.tmdb.org/t/p/w500/wHYjo3NLc293ZEXVSGhRIUr3Iqi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12149, 'Frailty', 'A mysterious man arrives at the offices of an FBI agent and recounts his childhood: how his religious fanatic father received visions telling him to kill people who were in fact "demons."', '2002-04-12', 6.95, 'https://image.tmdb.org/t/p/w500/jid7dyfHa6ApZSTweC3T3nllWjh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12437, 'Underworld: Rise of the Lycans', 'A prequel to the first two Underworld films, this fantasy explains the origins of the feud between the Vampires and the Lycans. Aided by his secret love, Sonja, courageous Lucian leads the Lycans in battle against brutal Vampire king Viktor. Determined to break the king''s enslavement of his people, Lucian faces off against the Death Dealer army in a bid for Lycan independence.', '2009-01-22', 6.54, 'https://image.tmdb.org/t/p/w500/yW9gF7rGn8EoV8B8rxOx1xjxVZf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12227, 'White Fang', 'Jack London''s classic adventure story about the friendship developed between a Yukon gold hunter and the mixed dog-wolf he rescues from the hands of a man who mistreats him.', '1991-01-18', 6.75, 'https://image.tmdb.org/t/p/w500/27wg0rVZW8hX7nWeHCwTf9DygGc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12445, 'Harry Potter and the Deathly Hallows: Part 2', 'Harry, Ron and Hermione continue their quest to vanquish the evil Voldemort once and for all. Just as things begin to look hopeless for the young wizards, Harry discovers a trio of magical objects that endow him with powers to rival Voldemort''s formidable skills.', '2011-07-12', 8.08, 'https://image.tmdb.org/t/p/w500/c54HpQmuwXjHq2C9wmoACjxoom3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12499, 'Fathers'' Day', 'A woman cons two old boyfriends into searching for her runaway son by convincing both that they are the boy''s father.', '1997-05-09', 5.47, 'https://image.tmdb.org/t/p/w500/834wRxQRbbctFupf8AES7CCeTSM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12493, 'High and Low', 'A Yokohama shoe executive faces a wrenching choice when kidnappers mistakenly seize his chauffeur’s son but demand the ransom anyway.', '1963-03-01', 8.38, 'https://image.tmdb.org/t/p/w500/tgNjemQPG96uIezpiUiXFcer5ga.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12500, 'American Ninja', 'Joe Armstrong, an orphaned drifter with little respect for much other than martial arts, finds himself on an American Army base in the Philippines after a judge gives him a choice of enlistment or prison. On one of his first missions driving a convoy, his platoon is attacked by a group of rebels who try to steal the weapons the platoon is transporting and kidnap the base colonel''s daughter.', '1985-08-30', 5.98, 'https://image.tmdb.org/t/p/w500/oH8eKi4Bt50tyXQIsYaM2KJqXd3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12501, 'The Big Country', 'Retired wealthy sea captain Jim McKay arrives in the Old West, where he becomes embroiled in a feud between his future father-in-law, Major Terrill, and the rough and lawless Hannasseys over a valuable patch of land.', '1958-08-13', 7.58, 'https://image.tmdb.org/t/p/w500/aTjIUBmo7qbiu5FuvSoBA0UONWk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12237, 'Faces of Death', 'A collection of death scenes, ranging from TV material to homemade super 8 movies.', '1978-11-10', 4.60, 'https://image.tmdb.org/t/p/w500/fhHzqDrdHLqjawXLXoV3w4FDOUd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12225, 'Cashback', 'After a painful breakup, Ben develops insomnia. To kill time, he starts working the late night shift at the local supermarket, where his artistic imagination runs wild.', '2007-01-17', 6.96, 'https://image.tmdb.org/t/p/w500/iXJKrcjHXrL148OfmovdGPBvnSw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12502, 'Silkwood', 'Like most of the people in her town, Karen Silkwood works at the local nuclear plant producing highly radioactive plutonium. Exposed one day to a lethal dose of radiation, Karen faces the blank walls of corporate indifference and denial. As her illness increases, her protest grows louder and she becomes an obvious danger to the powers that be.', '1983-12-14', 6.95, 'https://image.tmdb.org/t/p/w500/sGB81v70nnZqPMKFasvCpOmPcfq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12508, 'Rock Star', 'A wannabe rock star who fronts a Pennsylvania-based tribute band is devastated when his bandmates kick him out of the group he founded. Things begin to look up for Izzy when he is asked to join Steel Dragon, the heavy metal rockers he had been imitating for so long. This film is loosely based on the true story of the band Judas Priest.', '2001-09-04', 6.72, 'https://image.tmdb.org/t/p/w500/8pRMweo9WA1MvYOLsD2hWyFpZ1V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12516, 'Dreams', 'Eight visually rich vignettes drawn from Kurosawa’s own dreams—fox weddings and vanished orchards, a soldier’s ghosts, a walk through Van Gogh’s canvases, nuclear nightmares, and a water-mill utopia—meditate on childhood, art, mortality, and humanity’s uneasy bond with nature.', '1990-05-11', 7.74, 'https://image.tmdb.org/t/p/w500/ua17wrOrUjyqxuYmnUrmOVBMf4G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12518, 'Honeymoon in Vegas', 'On her deathbed, a mother makes her son promise never to get married, which scars him with psychological blocks to a commitment with his girlfriend. They finally decide to tie the knot in Vegas, but a wealthy gambler arranges for the man to lose $65K in a poker game and offers to clear the debt for a weekend with his fiancée.', '1992-08-28', 5.67, 'https://image.tmdb.org/t/p/w500/qZPay0VF5Bq2PiUvC09WwM5blmj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12505, 'Little Nikita', 'An FBI agent works to uncover an all-American family as Soviet sleeper agents, and gets caught up in friendship with their oblivious teenage son.', '1988-03-17', 6.05, 'https://image.tmdb.org/t/p/w500/9MpQxu1T0gRAvhv07xupOZPnqcJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12509, 'Pollock', 'In August of 1949, Life Magazine ran a banner headline that begged the question: "Jackson Pollock: Is he the greatest living painter in the United States?" The film is a look back into the life of an extraordinary man, a man who has fittingly been called "an artist dedicated to concealment, a celebrity who nobody knew." As he struggled with self-doubt, engaging in a lonely tug-of-war between needing to express himself and wanting to shut the world out, Pollock began a downward spiral.', '2000-09-06', 6.66, 'https://image.tmdb.org/t/p/w500/azsBSw2zw2uNHiCjTnbe9TJVEDB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12519, 'Sirens', 'In 1930s Australia, Anglican clergyman Anthony Campion and his prim wife, Estella, are asked to visit noted painter Norman Lindsay, whose planned contribution to an international art exhibit is considered blasphemous. While Campion and Lindsay debate, Estella finds herself drawn to the three beautiful models sitting for the painter''s current work, freethinking Sheela, sensual Pru and virginal Giddy.', '1994-03-04', 5.59, 'https://image.tmdb.org/t/p/w500/bOUDHgOlxANs1KsYZEsLSjZBTkd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12520, 'The Last Supper', 'A group of idealistic but frustrated liberals succumb to the temptation of murdering right-wing pundits for their political beliefs.', '1995-09-08', 6.52, 'https://image.tmdb.org/t/p/w500/oIgPiiM0qD1mCo1SYG3Sd0vmKTa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12524, 'Titus', 'Titus Andronicus returns from the wars and sees his sons and daughters taken from him, one by one. Shakespeare''s goriest and earliest tragedy.', '1999-12-25', 6.42, 'https://image.tmdb.org/t/p/w500/82mCeQoeT2C7h7vR6Ot9MQotE1R.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12526, 'Bug', 'In Oklahoma, Agnes, a lonely waitress living in an isolated and dilapidated roadside motel, meets Peter, a quiet and mysterious man with whom she establishes a peculiar relationship.', '2007-02-21', 6.12, 'https://image.tmdb.org/t/p/w500/yjTmmAngldFoyDhHxNM8fHblk3O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12527, 'Strawberry and Chocolate', 'In 1979 Cuba, flamboyant gay artist Diego attempts to seduce  straitlaced David, an idealistic young communist, and fails dismally. But David conspires to be "friends" with Diego so he can monitor the artist''s subversive life for the state. As Diego and David discuss politics, individuality and personal expression in Castro''s Cuba, a genuine friendship develops between the two.', '1993-12-01', 7.00, 'https://image.tmdb.org/t/p/w500/8riS2hGneWg78MHuhP7NqvLERRy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12530, 'Avanti!', 'A successful businessman travels to Italy to arrange for the return of his tycoon father''s body, only to learn that dear old dad died with his longtime mistress.', '1972-12-17', 6.90, 'https://image.tmdb.org/t/p/w500/dxhQzsBIjWMRu7rqprX4I2WzyEo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12531, 'The Apartment', 'Max is a former playboy who has decided to settle down by marrying his current love, Muriel. However, when Max catches a glimpse of the great lost love of his life, he becomes obsessed with rekindling their relationship.', '1996-07-27', 6.82, 'https://image.tmdb.org/t/p/w500/8EWKKGnAQPdTXhr2aRde1aLwPQn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12535, 'High Anxiety', 'A psychiatrist with intense acrophobia (fear of heights) goes to work for a mental institution run by doctors who appear to be crazier than their patients, and have secrets that they are willing to commit murder to keep.', '1977-12-25', 6.44, 'https://image.tmdb.org/t/p/w500/qVuSJaGnomSPon8x3mIYywFGgD8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12537, 'The French Lieutenant''s Woman', 'In this story-within-a-story, Anna is an actress starring opposite Mike in a period piece about the forbidden love between their respective characters, Sarah and Charles. Both actors are involved in serious relationships, but the passionate nature of the script leads to an off-camera love affair as well. While attempting to maintain their composure and professionalism, Anna and Mike struggle to come to terms with their infidelity.', '1981-08-28', 6.50, 'https://image.tmdb.org/t/p/w500/zqpeqPjziAH3VXMqwQ0Ds3Ffx9b.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12540, 'Bring It On Again', 'When new students can''t get onto their college cheerleading team, they form their own squad and prepare for a cheer off.', '2004-01-13', 5.95, 'https://image.tmdb.org/t/p/w500/slevjvJcGRvFZ3vwfbDdRfdLHG1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12545, 'Jesus Christ Superstar', 'As played out by a theatre troupe, the last days of Jesus Christ are depicted from the perspective of Judas Iscariot, his betrayer. As Jesus'' following increases, Judas begins to worry that Jesus is falling for his own hype, forgetting the principles of his teachings and growing too close to the prostitute Mary Magdalene.', '1973-08-15', 7.10, 'https://image.tmdb.org/t/p/w500/2NQgIjHxYyMJZWeUFH5cuKhN4nh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12555, 'I Served the King of England', 'Prague, Czechoslovakia, during the inter-war period. Jan Dítě, a young and clever waiter who wants to become a millionaire, comes to the conclusion that to achieve his ambitious goal he must be diligent, listen and observe as much as he can, be always discreet and use what he learns to his own advantage; but the turbulent tides of history will continually stand in his way.', '2007-01-11', 6.84, 'https://image.tmdb.org/t/p/w500/mwuabUjZMSg8ngHScjcKCmFO0jA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12230, 'One Hundred and One Dalmatians', 'When a litter of dalmatian puppies are abducted by the minions of Cruella De Vil, the parents must find them before she uses them for a diabolical fashion statement.', '1961-01-25', 7.18, 'https://image.tmdb.org/t/p/w500/kSlYq6FrBUviGSEh8v4L9nrSnBT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12229, 'The Acid House', 'A surreal triptych adapted by "Trainspotting" author Irvine Welsh from his acclaimed collection of short stories. Combining a vicious sense of humor with hard-talking drama, the film reaches into the hearts and minds of the chemical generation, casting a dark and unholy light into the hidden corners of the human psyche.', '1998-12-31', 6.22, 'https://image.tmdb.org/t/p/w500/o0KvKCgxMFccx3SzDI3p2218921.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12476, 'The Hidden', 'When average, law-abiding citizens suddenly turn to a life of hedonistic behavior and violent crime, Detective Tom Beck is tasked with helping young FBI agent Lloyd Gallagher determine the cause.', '1987-10-30', 6.89, 'https://image.tmdb.org/t/p/w500/pCoFtULUIebq13EU9glcZjfdC1a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12560, 'The Big Chill', 'Seven old college friends gather for a weekend reunion after the funeral of one of their own.', '1983-09-30', 6.83, 'https://image.tmdb.org/t/p/w500/rU8kjMEL5Mn0EWm3gOShPHBEZ4l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12569, 'Extract', 'The owner of a factory that produces flavor extracts, Joel Reynold seems to have it all, but really doesn''t. What''s missing is sexual attention from his wife, Suzie. Joel hatches a convoluted plan to get Suzie to cheat on him, thereby clearing the way for Joel to have an affair with Cindy, an employee. But what Joel doesn''t know is that Cindy is a sociopathic con artist, and a freak workplace accident clears the way for her to ruin Joel forever.', '2009-09-03', 5.85, 'https://image.tmdb.org/t/p/w500/cjen0vxjybwItQPH3NNCJuME2MY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12538, 'Senseless', 'A student gets his senses enhanced by an experimental drug. But abuse is not an option.', '1998-02-20', 6.21, 'https://image.tmdb.org/t/p/w500/rqy7OFHWy1NMjmgjyI8XYcl0VU5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12233, 'Oliver & Company', 'Putting its own ''twist'' on the story of Oliver Twist, the orange runt of a litter of kittens must fight for survival on the rough streets on New York City, finding unlikely friends in the dogs owned by a down-on-his luck man named Fagin. Soon, Oliver and his new band of comrades must fight for survival when Fagin is unable to pay his debts.', '1988-11-18', 6.74, 'https://image.tmdb.org/t/p/w500/dgaSqUHjm4CLOdiiJJJstVdreEe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12548, 'I Vitelloni', 'Five young men dream of success as they drift lazily through life in a small Italian village. Fausto, the group''s leader, is a womanizer; Riccardo craves fame; Alberto is a hopeless dreamer; Moraldo fantasizes about life in the city; and Leopoldo is an aspiring playwright. As Fausto chases a string of women, to the horror of his pregnant wife, the other four blunder their way from one uneventful experience to the next.', '1953-09-17', 7.65, 'https://image.tmdb.org/t/p/w500/boqcM6bhQICnNue4pkgmauj9JN3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12554, 'Citizen X', 'Based on the true story of a Russian serial killer who, over many years, claimed victim to over 50 people. His victims were mostly under the age of 17. In what was then a communists state, the police investigations were hampered by bureaucracy, incompetence and those in power. The story is told from the viewpoint of the detective in charge of the case.', '1995-02-25', 7.20, 'https://image.tmdb.org/t/p/w500/mr3lIjSRhXGVP2o9HY3P9PX2KsH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12478, 'Skin Deep', 'Hard-drinking novelist Zach Hutton spirals out of control after his wife and mistress both leave him. Alone and crippled by a bad case of writer''s block, Zach slips in and out of casual relationships and one-night stands, while his drinking becomes more and more severe. With the help of a bartender and his therapist, Zach confronts his demons — women and alcohol.', '1989-03-03', 6.18, 'https://image.tmdb.org/t/p/w500/mNFq1Bk9oXD774hVyvdPlNCtwPt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12584, 'The Shootist', 'Afflicted with a terminal illness John Bernard Books, the last of the legendary gunfighters, quietly returns to Carson City for medical attention from his old friend Dr. Hostetler. Aware that his days are numbered, the troubled man seeks solace and peace in a boarding house run by a widow and her son. However, it is not Books'' fate to die in peace, as he becomes embroiled in one last valiant battle.', '1976-07-21', 7.10, 'https://image.tmdb.org/t/p/w500/ygz2Pux61NY3yP4yCxRhgmFQp5z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12586, 'Bella', 'An international soccer star is on his way to sign a multimillion dollar contract when something happens that brings his career to an abrupt end. A beautiful waitress, struggling to make it in New York City, discovers something about herself that she''s unprepared for. In one irreversible moment, their lives are turned upside down.', '2006-09-09', 6.30, 'https://image.tmdb.org/t/p/w500/bNMzx71jw8OU9indcV5Hc7eE53w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12589, 'Jimmy Neutron: Boy Genius', 'Jimmy Neutron is a boy genius and way ahead of his friends, but when it comes to being cool, he''s a little behind. All until one day when his parents, and parents all over Earth are kidnapped by aliens, it''s up to him to lead all the children of the world to rescue their parents.', '2001-12-14', 6.11, 'https://image.tmdb.org/t/p/w500/pUwdquA6Bf3Gq8yT5iQL1Yq0jkl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12544, 'Respiro', 'Grazia is a free-spirited mother-of-three married to shy fisherman Pietro and living on the idyllic but isolated island of Lampedusa in the Mediterranean Sea. She shows signs of manic depressive behavior — one moment she''s laughing wildly and swimming half-naked in the sea, while the next she''s curled in a ball on her bed. Out of her earshot, the adult members of her extended family vaguely discuss sending her to a facility of some sort in Northern Italy.', '2002-05-18', 6.62, 'https://image.tmdb.org/t/p/w500/3DUXqmOpHZBQSQOHQcAdK6GVlKg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12590, 'Below', 'In the dark silence of the sea during World War II, the submarine USS Tiger Shark prowls on what should be a routine rescue mission. But for the shell-shocked crew, trapped together in the sub''s narrow corridors and constricted spaces, this is about to become a journey into the sensory delusions, mental deceptions and runaway fears that lurk just below the surface of the ocean.', '2002-08-11', 6.04, 'https://image.tmdb.org/t/p/w500/4tsaLD98DcXh4ltOn9wEWhsUkSc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12596, 'Pushing Tin', 'Two air traffic controllers who thrive on living dangerously compete to outdo each other on several levels.', '1999-04-23', 5.88, 'https://image.tmdb.org/t/p/w500/61FWajJNKeS27DO4KgvS5LUgcHh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12599, 'Pokémon the Movie 2000', 'When Lawrence III''s scheme to capture the Legendary Pokémon Lugia upsets the balance of nature, it is up to Ash Ketchum and his friends to save the world.', '1999-07-17', 6.74, 'https://image.tmdb.org/t/p/w500/6u65C8aG4krAVyHsTjAMF7ucTDH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12481, 'The Big Boss', 'Cheng is a young Chinese mainlander who moves in with his expatriate cousins to work at an ice factory in Thailand. He does this with a family promise never to get involved in any fights. However, when members of his family begin disappearing after meeting the management of the factory, the resulting mystery and pressures force him to break that vow and take on the villainy of the Big Boss.', '1971-10-23', 7.06, 'https://image.tmdb.org/t/p/w500/9VFYDWYnAhXAgyqgs94lwNmMBbk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12600, 'Pokémon 4Ever', 'In order to escape a greedy Pokémon hunter, Celebi must use the last of its energy to travel through time to the present day. Celebi brings along Sammy, a boy who had been trying to protect it. Along with Ash, Pikachu, and the rest of the gang, Sammy and Celebi must encounter an enemy far more advanced than the hunter, with the fate of the forest hanging in the balance.', '2001-07-07', 6.49, 'https://image.tmdb.org/t/p/w500/thz83PS9twtVBEEAM59J1bh75nU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12556, 'Ghosts of Girlfriends Past', 'Celebrity photographer Connor Mead lives life in the fast lane, committed to lifelong bachelorhood and simultaneous relationships with multiple women. On the eve of his younger brother Paul''s wedding, Connor''s mockery of love proves a real buzz-kill for everyone - including his childhood crush, Jenny, the one woman who always seemed immune to his considerable charms. Later that night, he gets a wake-up call from the ghost of his late Uncle Wayne, the hard-partying, legendary ladies'' man who was Connor''s mentor. Uncle Wayne has an urgent message which he delivers through three ghosts who guide Connor on an eye-opening tour of his romantic past, present and future. Along the way, they attempt to discern whether he will ever be able to change his ways -- and if there is any hope of him finding true love.', '2009-05-01', 5.96, 'https://image.tmdb.org/t/p/w500/azzg0lv5vpQRoOrZfNVkJn04f1M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12606, 'A Very Brady Sequel', 'A man claiming to be Carol Brady''s long-lost first husband, Roy Martin, shows up at the suburban Brady residence one evening. An impostor, the man is actually determined to steal the Bradys'' familiar horse statue, a $20-million ancient Asian artifact.', '1996-08-23', 5.80, 'https://image.tmdb.org/t/p/w500/7xqOkzAQvXCLkDtmlWU6HZnOhru.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12611, 'The Fury', 'When a devious plot separates CIA agent Peter Sandza from his son, Robin, the distraught father manages to see through the ruse. Taken because of his psychic abilities, Robin is being held by Ben Childress, who is studying people with supernatural powers in hopes of developing their talents as weapons. Soon Peter pairs up with Gillian, a teen who has telekinesis, to find and rescue Robin.', '1978-03-10', 6.28, 'https://image.tmdb.org/t/p/w500/uez7cenZAh9JORKyPq1AblMbe26.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12610, 'Osmosis Jones', 'A white blood cell policeman, with the help of a cold pill, must stop a deadly virus from destroying the human they live in, Frank.', '2001-08-10', 6.50, 'https://image.tmdb.org/t/p/w500/foZpSG88IQUCEBJE3unc5QzO6bQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12613, 'Street Fighter II: The Animated Movie', 'Bison, the ruthless leader of the international terrorist organization Shadowlaw, has been desperately searching for the greatest fighter on the planet for years. He finds it in Ryu, a young wanderer who never stays in one place long enough for Bison to find him. He does, however, get a fix on Ken Masters, an American martial arts champion who studied with Ryu as a child under the same master. Meanwhile, Major Guile of the United States Army is forced to team up with Chun Li from China in hopes of apprehending Bison and putting a stop his international ring of crime.', '1994-08-06', 7.14, 'https://image.tmdb.org/t/p/w500/dZ1rqmE4eIhPbUCr7sn2Pw2wwGW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12559, 'First Kid', 'Some say that to be the leader of a country is one of the loneliest jobs in the world. But being the child of a world leader can be doubly so. Constantly surrounded by security officers, restricted in movements and having almost every waking moment carefully monitored makes normalcy an impossibility. No one knows this better than young Luke Davenport, the son of U.S. President Davenport. He vents his loneliness, frustration and feelings of isolation from family and friends by being a brat to his private Secret Service agent. When the agent snaps from the strain in front of the First Lady, a new agent is assigned to Luke. He turns out to be the enormous Sam Simms, a bit of a rogue who managed to rise through the ranks by sheer determination rather than strict adherence to Secret-Service protocol. At first, Luke tries all his old tricks upon Sam. But instead of getting angry, Sam seems to actually understand.', '1996-08-30', 5.75, 'https://image.tmdb.org/t/p/w500/t7yTkuXQpnougXmRIqgfT32axZi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12615, 'Death of a Salesman', 'Willy Loman, an aging, failing salesman, struggles to accept reality and his failure to achieve the American Dream.', '1985-08-16', 6.91, 'https://image.tmdb.org/t/p/w500/tIRmjfaLmVHjGFaIcNGD3hggvbO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12618, 'Random Hearts', 'After losing their spouses in a plane crash, an internal affairs cop and a congresswoman find each other''s keys in each other''s loved ones'' possessions and discover that the two were having an affair.', '1999-10-08', 5.57, 'https://image.tmdb.org/t/p/w500/k7LoKDWDesvYD7DXDh9Ewlxtcx8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12614, 'Victor/Victoria', 'A struggling female soprano finds work playing a male female impersonator, but it complicates her personal life.', '1982-04-25', 7.27, 'https://image.tmdb.org/t/p/w500/mCjXcPRM3Rc7gOCGeVrBdPvF2bk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12620, 'The House Bunny', 'Shelley is living a carefree life until a rival gets her tossed out of the Playboy Mansion. With nowhere to go, fate delivers her to the sorority girls from Zeta Alpha Zeta. Unless they can sign a new pledge class, the seven socially clueless women will lose their house to the scheming girls of Phi Iota Mu. In order to accomplish their goal, they need Shelley to teach them the ways of makeup and men; at the same time, Shelley needs some of what the Zetas have - a sense of individuality. The combination leads all the girls to learn how to stop pretending and start being themselves.', '2008-08-22', 5.68, 'https://image.tmdb.org/t/p/w500/4oGGJ824vqIqDtyMvMuK44pDEmx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12621, 'Hamlet 2', 'Failed actor-turned-worse-high-school-drama-teacher Dana Marschz rallies his Tucson students as he conceives and stages a politically incorrect musical sequel to Shakespeare''s Hamlet.', '2008-01-21', 5.86, 'https://image.tmdb.org/t/p/w500/ljdmxGNwhuWZBsCgANlZrruFkJj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12626, 'Broadcast News', 'A high-strung news producer finds herself in a love triangle between a talented but self-doubting reporter and a charming news anchor who embodies the growing trivialization of news that she is determined to fight against.', '1987-12-16', 6.78, 'https://image.tmdb.org/t/p/w500/kQNR1Lc0qAF5xuBySpDn481KVjb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12628, 'Playing God', 'Stripped of his medical license after performing an operation while high on amphetamines, famed LA surgeon Dr Eugene Sands abandons his former life only to find himself crossing paths with Raymond Blossom, an infamous counterfeiter. Employed as a "gun-shot doctor" when Raymond''s associates cannot risk visiting a hospital, Eugene is lured deep into the criminal world and becomes entangled with his boss''s girlfriend.', '1997-10-17', 5.55, 'https://image.tmdb.org/t/p/w500/faYRZjtBMNygM7spt72yrs72hC8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12629, 'Live Wire', 'Danny O''Neill is a bomb disposal expert assigned to a case where terrorists have developed an "invisible" liquid explosive which is activated within the human body.', '1992-09-03', 5.24, 'https://image.tmdb.org/t/p/w500/xQbj9KgXqw9yjZfDO99jFyw1pzg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12632, 'Kaspar Hauser', 'In May 1828, a feral boy aged around 16 was found in Nuremberg. Kaspar Hauser, as he is called, can only speak a few indistinct words and knows nothing about his origins or family. The film depicts the - presumed - circumstances under which Hauser was held captive in complete isolation in a hiding place from infancy onwards. From this emerges the picture of an intrigue involving high circles of aristocratic society. Five years after his liberation, in December 1833, Kaspar Hauser died as a result of a stab wound inflicted by an unknown perpetrator.', '1993-09-11', 6.19, 'https://image.tmdb.org/t/p/w500/7gA2f8X9bim0905iC5NMXCJh7OS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12635, 'Backbeat', 'Chronicles the early days of The Beatles in Hamburg, Germany. The film focuses primarily on the relationship between Stuart Sutcliffe, John Lennon, and Sutcliffe''s girlfriend Astrid Kirchherr.', '1994-04-01', 6.10, 'https://image.tmdb.org/t/p/w500/1BuFx7P8veAUUZDXqdMNhtdCUSM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12649, 'The Mouse That Roared', 'The Duchy of Grand Fenwick decides that the only way to get out of their economic woes is to declare war on the United States, lose and accept foreign aid. They send an invasion force (in chain mail, armed with bows and arrows) to New York and they arrive during a nuclear drill that has cleared the streets.', '1959-07-17', 6.37, 'https://image.tmdb.org/t/p/w500/dHSIXGVmLHsPeWdfyVe8J1eZCFS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12444, 'Harry Potter and the Deathly Hallows: Part 1', 'Harry, Ron and Hermione walk away from their last year at Hogwarts to find and destroy the remaining Horcruxes, putting an end to Voldemort''s bid for immortality. But with Harry''s beloved Dumbledore dead and Voldemort''s unscrupulous Death Eaters on the loose, the world is more dangerous than ever.', '2010-11-17', 7.73, 'https://image.tmdb.org/t/p/w500/iGoXIpQb7Pot00EEdwpwPajheZ5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12651, 'Memphis Belle', 'The "Memphis Belle" is a World War II bomber, piloted by a young crew on dangerous bombing raids into Europe. The crew only have to make one more bombing raid before they have finished their duty and can go home. In the briefing before their last flight, the crew discover that the target for the day is Bremen.', '1990-09-07', 6.75, 'https://image.tmdb.org/t/p/w500/epsraI4swsSu9Fyefj7vPPhsOHK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12655, 'I Went Down', 'Fresh out of prison, Git rescues a former best friend (now living with Git''s girlfriend) from a beating at the hands of loan sharks. He''s now in trouble with the mob boss, Tom French, who sends Git to Cork with another debtor, Bunny Kelly, to find a guy named Frank Grogan, and take him to a man with a friendly face at a shack across a bog. It''s a tougher assignment than it seems: Git''s a novice, Bunny''s prone to rash acts, Frank doesn''t want to be found (and once he''s found, he has no money), and maybe Tom''s planning to murder Frank, which puts Git in a moral dilemma. Then, there''s the long-ago disappearance of Sonny Mulligan. What''s a decent and stand-up lad to do?', '1997-10-03', 6.00, 'https://image.tmdb.org/t/p/w500/2rApWxlYkiwNZBSC3KJ7WFWWq1T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12656, 'Feeling Minnesota', 'Sam Clayton''s marriage to ex-stripper Freddie comes about when she''s strong-armed into the match by Red, a club proprietor who once did her a favor. But Freddie falls in love with Jjaks, Sam''s brother, and the pair tries to escape the situation together. It isn''t long before both Sam and Red catch up with them, resulting in threats against the two of them -- although tension also starts to build between Sam and Red.', '1996-09-13', 5.40, 'https://image.tmdb.org/t/p/w500/fCJ5eUZw6mGS53spQxGUu7rzFm1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12454, 'All or Nothing', 'Penny works at a supermarket and Phil is a gentle taxi-driver. Penny’s love for Phil has run dry and they lead joyless lives with their two children, Rachel, a cleaner, and Rory, who is unemployed and aggressive.', '2002-10-18', 7.06, 'https://image.tmdb.org/t/p/w500/5VRYeJ8DI3GkVzO7MUlug8v2BZO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12658, 'Someone Like You...', 'Jane Goodale has everything going for her. She''s a producer on a popular daytime talk show, and is in a hot romance with the show''s dashing executive producer Ray. But when the relationship goes terribly awry, Jane begins an extensive study of the male animal, including her womanizing roommate Eddie. Jane puts her studies and romantic misadventure to use as a pseudonymous sex columnist -- and becomes a sensation.', '2001-03-30', 6.00, 'https://image.tmdb.org/t/p/w500/9cMkJSl2TI4xe8lKNFduinafKpe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12473, 'The Visitor', 'A college professor travels to New York City to attend a conference and finds a young couple living in his apartment.', '2008-02-21', 7.12, 'https://image.tmdb.org/t/p/w500/9XRRSD7swlYrGBhZ8vOR2yngIKZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12660, 'Charlotte Gray', 'This is a drama set in Nazi-occupied France at the height of World War II. Charlotte Gray tells the compelling story of a young Scottish woman working with the French Resistance in the hope of rescuing her lover, a missing RAF pilot. Based on the best-selling novel by Sebastian Faulks.', '2001-12-28', 6.10, 'https://image.tmdb.org/t/p/w500/6RnRclsipl3cZKnDfsu0MrqWCwI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12572, 'New York, I Love You', 'New York, I Love You delves into the intimate lives of New Yorkers as they grapple with, delight in and search for love. Journey from the Diamond District in the heart of Manhattan, through Chinatown and the Upper East Side, towards the Village, into Tribeca, and Brooklyn as lovers of all ages try to find romance in the Big Apple.', '2008-09-06', 5.95, 'https://image.tmdb.org/t/p/w500/85pnbEkyGi211Rq9DmnqbNX18aK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12488, 'The Gingerbread Man', 'A successful Savannah defense attorney gets romantically involved with a sexy, mysterious waitress troubled by psychopaths and dark family secrets.', '1998-01-23', 5.56, 'https://image.tmdb.org/t/p/w500/9914ih3TvooyVU0GA9BqtaJ4TbE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12477, 'Grave of the Fireflies', 'In the final months of World War II, 14-year-old Seita and his sister Setsuko are orphaned when their mother is killed during an air raid in Kobe, Japan. After a falling out with their aunt, they move into an abandoned bomb shelter. With no surviving relatives and their emergency rations depleted, Seita and Setsuko struggle to survive.', '1988-04-16', 8.45, 'https://image.tmdb.org/t/p/w500/k9tv1rXZbOhH7eiCk378x61kNQ1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12498, 'Sling Blade', 'Karl Childers, a mentally disabled man, has been in the custody of the state mental hospital since the age of 12 for killing his mother and her lover. Although thoroughly institutionalized, he is deemed fit to be released into the outside world.', '1996-08-30', 7.54, 'https://image.tmdb.org/t/p/w500/rioWUWXPFNSjwm9NO2aau9x0wlP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12490, 'Ordinary Decent Criminal', 'Michael Lynch is a notorious criminal with two wives and a flair for showmanship. He''s also a huge embarrassment to the local police, who are determined to bring him down once and for all.', '2000-01-07', 6.17, 'https://image.tmdb.org/t/p/w500/jZiORaxALVDGoMUBau85E4CWB0d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12647, 'Billy Bathgate', 'In the year 1935, a teen named Billy Bathgate finds first love while becoming the protégé of fledgling gangster Dutch Schultz.', '1991-11-01', 5.79, 'https://image.tmdb.org/t/p/w500/zDC0bY6IvGIf1SrDipLZJxR0Z2d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12684, 'Sabotage', 'Karl Anton Verloc and his wife own a small cinema in a quiet London suburb where they live seemingly happily. But Mrs. Verloc does not know that her husband has a secret that will affect their relationship and threaten her teenage brother''s life.', '1937-01-08', 6.70, 'https://image.tmdb.org/t/p/w500/A6cyOt9mhmvWA2uHcVsGkcCaHCz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12489, 'Gridlock''d', 'After a friend overdoses, Spoon and Stretch decide to kick their drug habits and attempt to enroll in a government detox program. Their efforts are hampered by seemingly endless red tape, as they are shuffled from one office to another while being chased by drug dealers and the police.', '1997-01-29', 6.62, 'https://image.tmdb.org/t/p/w500/jlOL8fLsG0tGBtkj9qzHgqcHPVV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12574, 'Cop & ½', 'When a pint-sized 8-year-old kid witnesses a murder he offers to help the police, if they make him a cop, too. Saddled with this streetwise sidekick, a hardboiled cop is forced to take his new partner seriously as they race the clock to bring the bad guys to justice.', '1993-04-02', 4.59, 'https://image.tmdb.org/t/p/w500/2z2AcI1VyPnRtHrvfpk1YDItdmB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12573, 'A Serious Man', 'It is 1967, and Larry Gopnik, a physics professor at a quiet Midwestern university, has just been informed by his wife Judith that she is leaving him. She has fallen in love with one of his more pompous acquaintances Sy Ableman.', '2009-10-02', 6.69, 'https://image.tmdb.org/t/p/w500/5gGxDS8WmrebPlMHexVS8EVehiP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12652, 'Nelly and Monsieur Arnaud', 'Nelly leaves her lazy, unemployed husband to work for retired judge Mr Arnaud, forty years her senior, after he offers to clear her bills for her. While she types his memoirs the two develop a close friendship, but Arnaud becomes jealous when Nelly begins dating his good-looking young publisher.', '1995-10-18', 7.01, 'https://image.tmdb.org/t/p/w500/87kKTPi9r7YIVrlo9Z42NwTXBVi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12703, 'The Brown Bunny', 'Bud Clay races motorcycles in the 250cc Formula II class of road racing. After a race in New Hampshire, he has five days to get to his next race in California. During his road trip, he is haunted by memories of the last time he saw Daisy, his true love.', '2003-11-14', 5.37, 'https://image.tmdb.org/t/p/w500/bGzU4TgdqmMjIfPIgf2MjDW6H7c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12704, 'Ishtar', 'Two terrible lounge singers get booked to play a gig in a Moroccan hotel but somehow become pawns in an international power play between the CIA, the Emir of Ishtar, and the rebels trying to overthrow his regime.', '1987-05-15', 4.56, 'https://image.tmdb.org/t/p/w500/2n6cDGd84I1KvCeYlTju7MBC9sN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12496, 'The Twilight Samurai', 'Seibei Iguchi leads a difficult life as a low ranking samurai at the turn of the nineteenth century. A widower with a meager income, Seibei struggles to take care of his two daughters and senile mother. New prospects seem to open up when the beautiful Tomoe, a childhood friend, comes back into he and his daughters'' life, but as the Japanese feudal system unravels, Seibei is still bound by the code of honor of the samurai and by his own sense of social precedence. How can he find a way to do what is best for those he loves?', '2002-11-02', 7.78, 'https://image.tmdb.org/t/p/w500/bB2M8UF8wc9flfGWkcgkTTf8Mzr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12705, 'Smokey and the Bandit II', 'The Bandit goes on another cross-country run, transporting an elephant from Florida to Texas. And, once again, Sheriff Buford T. Justice is on his tail.', '1980-08-15', 5.55, 'https://image.tmdb.org/t/p/w500/cYNZM1xdhOH6NybMcX9E1LPOl3l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12706, 'Croupier', 'Jack Manfred is an aspiring writer who to make ends meet, takes a job as a croupier. Jack remains an observer, knowing that everything in life is a gamble and that gamblers are born to lose. Inevitably, he gets sucked into the world of the casino which takes its toll on his relationships and the novel he is writing.', '1998-06-25', 6.73, 'https://image.tmdb.org/t/p/w500/bLLa74hdq9qsJpcVqLSwm3fKzJn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12707, 'Orca', 'After witnessing the killing of his mate and offspring at the hands of a reckless Irish captain, a vengeful killer whale rampages through the fisherman''s Newfoundland harbor. Under pressure from the villagers, the captain, a female marine biologist, and an Indigenous tribalist venture after the great beast, who will meet them on its own turf.', '1977-07-22', 6.18, 'https://image.tmdb.org/t/p/w500/uSascD0pN3n5d6BlyFdce0hRVzz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12708, 'That Touch of Mink', 'Cathy Timberlake is en route to a job interview when a car transporting businessman Philip Shayne covers her in mud. He sends his assistant, Roger, to apologize, but upon meeting Cathy, Roger knows that she would be a suitable match for his boss. Despite their mutual attraction, Cathy and Philip want different things. Philip wants a fling, while Cathy wants a marriage. As they travel to exotic locales, their differing motivations are put to the test.', '1962-06-14', 6.47, 'https://image.tmdb.org/t/p/w500/eEG29x9cljGKL2GPmRK9IByyL9e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12582, 'Without a Clue', 'Sherlock Holmes is as dashing as ever, but with a little secret: Dr. Watson is the brains behind the operation. When Reginald Kincaid, the actor he has hired to play Holmes becomes insufferable, Watson fires him and tries to go out on his own, but finds that he has done too good a job building Holmes up in the public''s mind.', '1988-05-05', 6.70, 'https://image.tmdb.org/t/p/w500/uZmoKYDfF965UAgPrUSz0FbavsE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12709, 'Ridicule', 'To get royal backing on a needed drainage project, a poor French lord must learn to play the delicate games of wit at court at Versailles.', '1996-05-09', 6.94, 'https://image.tmdb.org/t/p/w500/j78rRskAapKtILalcxAmdskGtzb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12710, 'Big Business', 'In the 1940s in the small town of Jupiter Hollow, two sets of identical twins are born in the same hospital on the same night. One set to a poor local family and the other to a rich family just passing through. The dizzy nurse on duty accidentally mixes the twins unbeknown to the parents. Our story flashes forward to the 1980s where the mismatched sets of twins are about to cross paths.', '1988-06-10', 6.38, 'https://image.tmdb.org/t/p/w500/dxbXbR1P44caMUKtBdq7sX6aSgw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12714, 'She''s Having a Baby', 'Jake and Kristy Briggs are newlyweds. Being young, they are perhaps a bit unprepared for the full reality of marriage and all that it (and their parents) expect from them. Do they want babies? Their parents certainly want them to. Is married life all that there is? Things certainly aren''t helped by Jake''s friend Davis, who always seems to turn up just in time to put a spanner in the works.', '1988-02-05', 5.95, 'https://image.tmdb.org/t/p/w500/7arFsU8I5mE7nmxff05Gpib3ZBL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12715, 'Firewalker', 'A pair of adventurers try to track down an ancient Aztec/Mayan/Egyptian/Apache horde of gold.', '1986-11-21', 5.37, 'https://image.tmdb.org/t/p/w500/qFUBCOH0HxI9qRcjoG9xChfwEsk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12716, 'My Father''s Glory', 'Raised by his science teacher father, Joseph Pagnol, and seamstress mother Augustine, young Marcel grows up during the turn of the century in awe of his rationalist dad. When the family takes a summer vacation in the countryside, Marcel becomes friends with Lili, who teaches him about rural life.', '1990-08-29', 7.30, 'https://image.tmdb.org/t/p/w500/4zwgcaKqIJ5GB6kCPpyMLZuNyoi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12717, 'My Mother''s Castle', 'To his chagrin, young Marcel Pagnol and his family move back to their home in Marseille, France, far from their pastoral holiday cottage in the hills. Determined, Marcel makes the long voyage back to the cottage on foot and lands himself in trouble. One day Marcel''s father discovers a shortcut to the cottage, but it requires trespassing. Despite their trepidations, Marcel and his family begin using the secret trail to reach their cottage.', '1990-10-26', 7.17, 'https://image.tmdb.org/t/p/w500/hw8Ec4jFuxSNCMUZiUpBKOMl65G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12719, 'Flashback', 'A hippie radical, Huey Walker has been a fugitive for decades, accused of a crime that he may not have committed. Finally apprehended, Walker is escorted to trial by uptight 20-something FBI agent John Buckner. While the two seem to be polar opposites, it turns out that Buckner may have more in common with Walker than is initially apparent, a point that is driven home when the pair faces off against a sinister small-town sheriff.', '1990-02-02', 6.37, 'https://image.tmdb.org/t/p/w500/zHJbL26SdgeWbKFJVKNfEI4LJwS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12720, 'Suicide Club', 'When the bizarre mass suicide of 54 high school girls throwing themselves in front of a subway train appears to instigate a string of suicides around the country, Detective Kuroda strives to find the answer, which isn''t as simple as he had hoped.', '2001-10-29', 6.47, 'https://image.tmdb.org/t/p/w500/oMjWlKHzR9cwhf3oCUy9j57o67O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12723, 'Inventing the Abbotts', 'In the 1950s, brothers Jacey and Doug Holt, who come from the poorer side of their sleepy Midwestern town, vie for the affections of the wealthy, lovely Abbott sisters. Lady-killer Jacey alternates between Eleanor and Alice, wanting simply to break the hearts of rich young women. But sensitive Doug has a real romance with Pamela, which Jacey and the Abbott patriarch, Lloyd, both frown upon.', '1997-04-04', 6.30, 'https://image.tmdb.org/t/p/w500/ysfD96fF56BEzpktyDWChC8Epgs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12761, 'Autumn Sonata', 'After a seven-year absence, Charlotte Andergast travels to Sweden to reunite with her daughter Eva. The pair have a troubled relationship: Charlotte sacrificed the responsibilities of motherhood for a career as a classical pianist. Over an emotional night, the pair reopen the wounds of the past. Charlotte gets another shock when she finds out that her mentally impaired daughter, Helena, is out of the asylum and living with Eva.', '1978-10-08', 8.00, 'https://image.tmdb.org/t/p/w500/6beNbtCXv3GkzHkxkGYf38ib7v8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12657, 'Soul Plane', 'Following a ridiculously awful flight that leads to his pet''s death, Nashawn Wade files a lawsuit against the airline, and wins a multimillion-dollar settlement. Determined to create a better flying experience, Nashawn starts his own airline, one that caters to an African-American clientele. Going into business with a tricked-out plane piloted by the smooth Capt. Mack, the airline hits a snag when it has to deal with the family of Elvis Hunkee.', '2004-05-28', 5.50, 'https://image.tmdb.org/t/p/w500/b5Rzb5JUwPinllWGYUYER3OV14F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12763, 'Take the Lead', 'A former professional dancer volunteers to teach dance in the New York public school system and, while his background first clashes with his students'' tastes, together they create a completely new style of dance. Based on the story of ballroom dancer, Pierre Dulane.', '2006-03-17', 6.86, 'https://image.tmdb.org/t/p/w500/vkGSs0eeOOISEe9jddBZnRSkn46.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12762, 'Broadway Danny Rose', 'A hapless talent manager named Danny Rose, by helping a client, gets dragged into a love triangle involving the mob. His story is told in flashback, an anecdote shared amongst a group of comedians over lunch at New York''s Carnegie Deli. Rose''s one-man talent agency represents countless incompetent entertainers, including a one-legged tap dancer, and one slightly talented one: washed-up lounge singer Lou Canova, whose career is on the rebound.', '1984-01-27', 7.14, 'https://image.tmdb.org/t/p/w500/oUgolImcg0PRiT33UNjK409aQoJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12767, 'Cold Creek Manor', 'A family moves from New York into an old mansion in the countryside, still filled with the previous owner''s things. As they begin to make it their own, a series of events begin to occur that makes them believe that the former inhabitants are not yet gone.', '2003-09-19', 5.36, 'https://image.tmdb.org/t/p/w500/2AKitfwCoCmHU4PTtC5oF6LImlG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12771, 'Serving Sara', 'When Sara is served divorce papers while she is in New York, she is stunned. Not about to lose the fortune she amassed with her self-serving Texan husband, she makes an offer to her process server, Joe, that sets them off on a wild trip across the country.', '2002-08-23', 5.36, 'https://image.tmdb.org/t/p/w500/zi8uGxsyhxo0Uzg09ImxLzBDSK3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12770, 'Stealing Harvard', 'John and his girlfriend have vowed to marry once they save $30,000 for their dream house. But the minute they achieve their financial goal, John finds out his niece has been accepted at Harvard, and he''s reminded of his promise to pay for her tuition (nearly $30,000). John''s friend Duff convinces him to turn to petty crime to make the payment … but Duff''s hare-brained schemes spin quickly out of control.', '2002-09-13', 4.80, 'https://image.tmdb.org/t/p/w500/iCHAn0eVAXwybuzoQO598aKMVJD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12579, 'The Woman Next Door', 'Two ex-lovers wind up living next door to each other with their respective spouses. Forbidden passions ensue.', '1981-09-30', 7.06, 'https://image.tmdb.org/t/p/w500/nxBf3Y7Q9XVuKvUl0df8MW2IsQ7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12634, 'The Big Bounce', 'A small-time con artist and a Hawaiian real estate developer''s mischievous, enterprising mistress team up for a potential $200,000 score.', '2004-01-30', 4.97, 'https://image.tmdb.org/t/p/w500/l6tzLXXGubnC6TbFgg8acfcvGRO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12659, 'Beijing Bicycle', 'A seventeen-year-old country boy working in Beijing as a courier has his bicycle stolen, and finds it with a schoolboy his age.', '2001-02-17', 6.87, 'https://image.tmdb.org/t/p/w500/mkOBUHcJFfVWLJmWNvE0qZuzAW0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12637, 'New York, New York', 'An egotistical saxophone player and a young singer meet on V-J Day and embark upon a strained and rocky romance, even as their careers begin a long uphill climb.', '1977-06-21', 6.53, 'https://image.tmdb.org/t/p/w500/1nD40aUcPAxYdE1WxERrTjZuFGe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12583, 'Ginger Snaps Back: The Beginning', 'Set in 19th Century Canada, Brigitte and her sister Ginger take refuge in a Traders'' Fort which later becomes under siege by some savage werewolves. But when one of the girls is bitten, they have no one to turn to but themselves.', '2004-07-10', 6.10, 'https://image.tmdb.org/t/p/w500/tQ17krYhctcHnnslqq90zzGkhg7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12783, 'The Duchess', 'A chronicle of the life of 18th century aristocrat Georgiana, Duchess of Devonshire, who was reviled for her extravagant political and personal life.', '2008-09-05', 6.98, 'https://image.tmdb.org/t/p/w500/77ckyYrWmR12kl3qToqmDySnuwv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12764, 'Missing in Action 2: The Beginning', 'Prequel to the first Missing In Action, set in the early 1980s it shows the capture of Colonel Braddock during the Vietnam war in the 1970s, and his captivity with other American POWs in a brutal prison camp, and his plans to escape.', '1985-03-01', 5.80, 'https://image.tmdb.org/t/p/w500/vOgiL2KQYyTHJ225lT5QB5B9kO0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12778, 'Greedy', 'Meet the McTeagues. They''ve come to stake a claim in their wealthy uncle''s will… only he''s not dead yet!', '1994-03-04', 6.15, 'https://image.tmdb.org/t/p/w500/5OpvMU6CTXe4pRAQUVWcVJeZCSS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12645, 'Inhale', 'A couple goes to dangerous lengths to find a lung donor for their daughter.', '2010-08-27', 6.04, 'https://image.tmdb.org/t/p/w500/x1JpxURGHRkaGM819kVipNdtgR0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12806, 'Nico and Dani', 'While his parents are away for the summer, 16-year-old Dani invites his best friend, the irrepressible Nico, to stay for the holidays. Jealously rears its head when Nico appears more interested in the local girls than in Dani. Hot summer nights and too many  joints lead to experimentation which neither boy can talk about, a situation complicated by the appearance of the older and openly gay Julián, a published writer and old friend of Dani’s father.', '2000-05-18', 5.93, 'https://image.tmdb.org/t/p/w500/iw5BLbL1rSmya9I6puP1q5dUn81.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12808, 'Nina''s Heavenly Delights', 'A feisty young woman returns to Glasgow to run her deceased father''s curry house.', '2006-09-28', 6.70, 'https://image.tmdb.org/t/p/w500/tK6S01DNg0C1ObAXgb7vtwVZ5Tr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12834, 'Leaves of Grass', 'An Ivy League professor returns home, where his pot-growing twin brother has concocted a plan to take down a local drug lord.', '2009-09-13', 6.00, 'https://image.tmdb.org/t/p/w500/dkIfBUewNDrJYL0UlNsKRUKZJYp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12837, 'The Secret Life of Bees', 'Set in South Carolina in 1964, this is the tale of Lily Owens a 14 year-old girl who is haunted by the memory of her late mother. To escape her lonely life and troubled relationship with her father, Lily flees with Rosaleen, her caregiver and only friend, to a South Carolina town that holds the secret to her mother''s past.', '2008-09-17', 7.48, 'https://image.tmdb.org/t/p/w500/m1LGEeoYfc6crbfG8WmTKg9SVqL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12877, 'Dead Man''s Shoes', 'A soldier returns to his small town and exacts a deadly revenge on the thugs who tormented his disabled brother while he was away.', '2004-09-29', 7.11, 'https://image.tmdb.org/t/p/w500/sCbXlGHmonE3QEOeM7I2PRkG8y6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12664, 'The Snapper', 'Sharon Curley is a 20-year-old living with her parents and many brothers and sisters in Dublin. When she gets pregnant and refuses to name the father, she becomes the talk of the town.', '1993-08-06', 6.47, 'https://image.tmdb.org/t/p/w500/t5sgHOd9NmfyGPWDbv6MoT0f9qM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12888, 'Belly', 'Tommy Bundy and Sincere are best friends as well as infamous and ruthless criminals and shot-callers in the hood. Respected by many but feared by all.  As the police are closing in on them and new players are looking for a come up, will their reign last?', '1998-11-04', 6.32, 'https://image.tmdb.org/t/p/w500/i4QhjdZXxdOpKOhc9kh4qqWjRWr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12889, 'Futurama: The Beast with a Billion Backs', 'Fresh off ripping space-time a new one at the end of "Bender''s Big Score," the Planet Express crew is back to mend the tear in reality, or (hopefully) at least not make it worse.  Beyond the tear, though, lurks a being of inconceivable...tentacularity.  What will become of Earth, and indeed, our universe, when faced with the Beast with a Billion Backs?', '2008-06-24', 6.98, 'https://image.tmdb.org/t/p/w500/2BW6JAW4wo7t5wD3WVfoijzosvt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12901, 'No End in Sight', 'Chronological look at the fiasco in Iraq, especially decisions made in the spring of 2003 - and the backgrounds of those making decisions - immediately following the overthrow of Saddam: no occupation plan, an inadequate team to run the country, insufficient troops to keep order, and three edicts from the White House announced by Bremmer when he took over.', '2007-07-27', 7.70, 'https://image.tmdb.org/t/p/w500/vNLK1fRPHTHFfWfy63NJFDwX7MQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12772, 'Leap of Faith', 'Jonas Nightengale is a fraudulent Christian faith healer who makes a living travelling around America holding revival meetings and conducting ''miracles'' with the help of his friend and manager, Jane, and their entourage.', '1992-12-18', 5.83, 'https://image.tmdb.org/t/p/w500/iqIKuwQYdvoKKGFjjEPdXlUKYvk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12795, 'Another Gay Movie', 'Andy is your typical All-American eighteen-year-old gay virgin. Like everyone else, he''s dying to have sex. Totally out of the closet and mad-crazy horny, this naïve high school senior is caught in that awkward vortex between child and adult. Much to the dismay of his mom (who wonders why all her carrots and cucumbers keep disappearing), Andy spends much of his private time practicing for the big moment when he''ll finally take the plunge.', '2006-04-28', 5.97, 'https://image.tmdb.org/t/p/w500/yKdilPwtuoZRhw9A63qzduRkSbG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12890, 'Smart People', 'Professor Lawrence Wetherhold might be imperiously brilliant, monumentally self-possessed and an intellectual giant -- but when it comes to solving the conundrums of love and family, he''s as downright flummoxed as the next guy.', '2008-04-11', 5.84, 'https://image.tmdb.org/t/p/w500/igIl4RKxOEYvhQGKCvM6vCRMiVm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12902, 'Scooby-Doo! and the Loch Ness Monster', 'While the gang travel to Scotland to visit Daphne''s cousin and witness the annual Highland Games, they find themselves terrorized by the legendary Loch Ness Monster.', '2004-05-20', 7.30, 'https://image.tmdb.org/t/p/w500/hmeJnofknkSnczzN3J7Wvfn7OGI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12912, 'Chaos Theory', 'Frank Allen, a professional speaker who lectures on time management has a perfectly ordered and scheduled life, down to the minute. When his wife sets his clock forward 10 minutes as a joke, his day is thrown off. Deciding that his strictly ordered life has done him little good, he begins to make multiple choice index cards, choosing one at random and doing what is written on the card.', '2008-04-11', 6.40, 'https://image.tmdb.org/t/p/w500/iP4DJqTeMMQJ3J0eyt2RjRH6NZH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12914, 'Stargate: Continuum', 'Ba''al travels back in time and prevents the Stargate program from being started. SG-1 must somehow restore history.', '2008-07-29', 7.14, 'https://image.tmdb.org/t/p/w500/1rQUvblJHU8766FatqTtCMiRhph.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12920, 'Dreamer: Inspired By a True Story', 'Ben Crane believes that a severely injured racehorse deserves another chance. He and his daughter Cale adopt the mare and save it from being sacrificed by the owner.', '2005-09-10', 7.05, 'https://image.tmdb.org/t/p/w500/7Z5FuLTrP5myJ2Dl9VzDRa6q0CG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12919, 'Can''t Buy Me Love', 'Nerdy high schooler Ronald Miller rescues cheerleader Cindy Mancini from parental punishment after she accidentally destroys her mother''s designer clothes. Ronald agrees to pay for the $1,000 outfit on one condition: that she will act as though they''re a couple for an entire month. As the days pass, however, Cindy grows fond of Ronald, making him popular. But when Ronald''s former best friend gets left behind, he realizes that social success isn''t everything.', '1987-08-14', 6.88, 'https://image.tmdb.org/t/p/w500/qK3yiqo84U3twOOKOx81c407Hpr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12921, 'Strange Brew', 'Something is rotten at the Elsinore Brewery. Bob and Doug McKenzie (as seen on SCTV) help the orphan Pam regain the brewery founded by her recently-deceased father. But to do so, they must confront the suspicious Brewmeister Smith and two teams of vicious hockey players.', '1983-08-26', 6.02, 'https://image.tmdb.org/t/p/w500/rScplcvRHX7o7XK88SFb5mddo8y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12994, 'The Nines', 'A troubled actor, a television show runner, and an acclaimed videogame designer find their lives intertwining in mysterious and unsettling ways.', '2007-01-21', 5.97, 'https://image.tmdb.org/t/p/w500/AkIyPzbxBnR815XNCKH5D9T4RaE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13003, 'Gonzo: The Life and Work of Dr. Hunter S. Thompson', 'Fueled by a raging libido, Wild Turkey, and superhuman doses of drugs, Thompson was a true "free lance, " goring sacred cows with impunity, hilarity, and a steel-eyed conviction for writing wrongs. Focusing on the good doctor''s heyday, 1965 to 1975, the film includes clips of never-before-seen (nor heard) home movies, audiotapes, and passages from unpublished manuscripts.', '2008-07-18', 6.92, 'https://image.tmdb.org/t/p/w500/a8cRVJTTofxF7TgCGEvC5Yr4GnC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13007, 'Religulous', 'Commentator-comic Bill Maher plays devil''s advocate with religion as he talks to believers about their faith. Traveling around the world, Maher examines the tenets of Christianity, Judaism and Islam and raises questions about homosexuality, proof of Christ''s existence, Jewish Sabbath laws, violent Muslim extremists.', '2008-10-01', 7.03, 'https://image.tmdb.org/t/p/w500/hBv5LCbWxPB8iU77dwurSGMVZ3N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13009, 'Zombie Strippers!', 'In the not too distant future a secret government re-animation chemo-virus gets released into conservative Sartre, Nebraska and lands in an underground strip club. As the virus begins to spread, turning the strippers into "Super Zombie Strippers" the girls struggle with whether or not to conform to the new "fad" even if it means there''s no turning back.', '2008-04-18', 4.84, 'https://image.tmdb.org/t/p/w500/iQcOzXCpewM9pbEwLoIrHLjpMvB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13012, 'Felon', 'A family man convicted of killing an intruder must cope with life afterward in the violent penal system.', '2008-07-17', 7.10, 'https://image.tmdb.org/t/p/w500/1eYGh6DETJFXQt5PWjV8lp8YZvx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13015, 'George Carlin: Life Is Worth Losing', 'Carlin returns to the stage in his 13th live comedy stand-up special, performed at the Beacon Theatre in New York City for HBO®. His spot-on observations on the deterioration of human behavior include Americans’ obsession with their two favorite addictions - shopping and eating; his creative idea for The All-Suicide Channel, a new reality TV network; and the glorious rebirth of the planet to its original pristine condition - once the fires and floods destroy life as we know it.', '2005-11-05', 7.50, 'https://image.tmdb.org/t/p/w500/djoek5ZJA1J7E6vD0jAoUN5Mqjb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13016, 'Zeitgeist: The Movie', 'A documentary examining possible historical and modern conspiracies surrounding Christianity, the 9/11 terrorist attacks, and the Federal Reserve bank.', '2007-06-01', 6.97, 'https://image.tmdb.org/t/p/w500/4eJQJ3tvnNO7CdxXT5awnd9ovGX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13019, 'Young People Fucking', 'On a Tuesday night, five couples have separate sexual adventures. Matt and Kris, friends for years, want to have an only-once, no-strings good time. Abby and Andrew, married, celebrate his birthday, but it''s marred by angst and miscommunication. Mia and Eric are exes, making sure they are over each other. Jaime and Ken work together and this is a first date. Inez and Gord invite his roommate, Dave, to join them. By the time each couple has gone through a prelude, foreplay, sex, an interlude, orgasm, and afterglow, they''ve answered basic questions: can sex be anonymous, are we bored, is our marriage really finished, does anyone tell the truth, and how do we make someone happy?', '2007-09-05', 5.80, 'https://image.tmdb.org/t/p/w500/g5LhutkdYsKyDePtqrRw7c3OTce.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12662, 'Psycho III', 'When Maureen Coyle, a suicidal nun who resembles Norman''s former victim, Marion Crane, arrives at the motel, all bets are off and "Mother" is less than happy.', '1986-04-02', 5.70, 'https://image.tmdb.org/t/p/w500/tgV4eeW0X7os7p3SYbNwDI0NYGa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13020, 'Enron: The Smartest Guys in the Room', 'A documentary about the Enron corporation, its faulty and corrupt business practices, and how they led to its fall.', '2005-04-22', 7.16, 'https://image.tmdb.org/t/p/w500/zezeOElCxlPui9SFGj5ToZ4W1Nh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12774, 'Last Exit to Brooklyn', 'A gallery of characters in Brooklyn in the 1950s are crushed by their surroundings and selves: a union strike leader discovers he is gay; a prostitute falls in love with one of her clients; a family cannot cope with the fact that their daughter is illegitimately pregnant.', '1989-07-26', 6.45, 'https://image.tmdb.org/t/p/w500/89Lg30XE7gwVZpJUk0RKqV8CtND.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12661, 'Undercover Blues', 'When fun-loving American agents Jeff and Jane Blue are called back from maternity leave for a special assignment in New Orleans, the spy parents decide to skip the sitter and give their bouncing baby girl the adventure of a lifetime.', '1993-09-10', 6.01, 'https://image.tmdb.org/t/p/w500/r9yKccGLLzpPwRCyfCMjG2oNcbF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12780, 'Iron Monkey', 'In this Hong Kong variation of Robin Hood, corrupt officials of a Chinese village are robbed by a masked bandit known as "Iron Monkey", named after a benevolent deity. When all else fails, the Governor forces a traveling physician into finding the bandit.', '1993-09-03', 7.42, 'https://image.tmdb.org/t/p/w500/qXYISomt08V5PUqCzYRLVSQZmWP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12775, 'Flesh + Blood', 'A band of medieval mercenaries take revenge on a noble Lord who cheated them by kidnapping his son''s fiancée. As the plague and warfare cut a swathe of destruction throughout the land, the mercenaries hole up in a castle and await their fate.', '1985-08-30', 6.56, 'https://image.tmdb.org/t/p/w500/bjUYC4uC82oASTMPkb6iGCYOO2e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13022, 'Rogue', 'When a group of tourists stumble into the remote Australian river territory of an enormous crocodile, the deadly creature traps them on a tiny mud island with the tide quickly rising and darkness descending. As the hungry predator closes in, they must fight for survival against all odds.', '2007-11-08', 6.30, 'https://image.tmdb.org/t/p/w500/abFDVe71e7UE5MpAqjZvUYT2U7M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13059, 'The Signal', 'A horror film told in three parts, from three perspectives, in which a mysterious transmission that turns people into killers invades every cell phone, radio, and television.', '2007-07-13', 5.93, 'https://image.tmdb.org/t/p/w500/qRs8osQJZLItwQER2bzuuK9A0sp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12665, 'Powder', 'Harassed by classmates who won''t accept his shocking appearance, a shy young man known as "Powder" struggles to fit in. But the cruel taunts stop when Powder displays a mysterious power that allows him to do incredible things. This phenomenon changes the lives of all those around him in ways they never could have imagined.', '1995-10-27', 7.10, 'https://image.tmdb.org/t/p/w500/zwVmkbrRdbNceK4drB0imFszGxl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12776, 'Johnny Stecchino', 'Good hearted but not very wordly-wise, Dante is happy driving the school bus for a group of mentally handicapped children, while feeling he is somehow missing out on life and love. So he is very excited when after nearly being knocked down by her car he meets Maria, who seems immediately enamoured of him. He is soon invited to her sumptuous Palermo villa, little suspecting that this is part of a plot. He bears an amazing likeness to Maria''s stool-pigeon gangster husband and it would be convenient for them if the mobster, in the shape of Dante, was seen to be dead and buried.', '1991-10-24', 7.33, 'https://image.tmdb.org/t/p/w500/5scWsRsH5MUJEgXB52w0fM6I2gM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12683, 'Alone in the Dark 2', 'When the night falls, and the creatures of the dark are crawling out of the shadows, there is only one man who stands between us and evil: Edward Carnby.', '2008-09-01', 3.53, 'https://image.tmdb.org/t/p/w500/dGKQoqyYnleFrz3DIBANG00QccO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12689, 'Angus, Thongs and Perfect Snogging', 'Georgia Nicolson is fourteen, lives with nosey parents who don''t understand her, an annoying three year old sister and has to wear a beret to school. She would, however, rather be blonde, have a smaller nose and a boyfriend. Revolving around her hilarious journal entries, prepare to be engulfed in the world of the soaring joys and bottomless angst of being a teenager.', '2008-07-25', 6.50, 'https://image.tmdb.org/t/p/w500/3WLMr49X84qGiFn1pkCyhS5SEBZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12698, 'The Fog of War', 'Using archival footage, cabinet conversation recordings, and an interview of the 85-year-old Robert McNamara, The Fog of War depicts his life, from working as a WWII whiz-kid military officer, to being the Ford Motor Company''s president, to managing the Vietnam War as defense secretary for presidents Kennedy and Johnson.', '2003-10-26', 7.72, 'https://image.tmdb.org/t/p/w500/m1dEnkrdJGBSLeAyJepuGrU9sNI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12690, 'Appaloosa', 'Two friends hired to police a small town that is suffering under the rule of a rancher find their job complicated by the arrival of a young widow.', '2008-09-19', 6.57, 'https://image.tmdb.org/t/p/w500/kQB0uxR3RDS2tGTZtBuFow9SF1T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13075, 'Sherrybaby', 'After serving time in prison, former drug addict Sherry Swanson returns home to reclaim her young daughter from family members who have been raising the child. Sherry''s family, especially her sister-in-law, doubt Sherry''s ability to be a good mother, and Sherry finds her resolve to stay clean slowly weakening.', '2006-09-08', 6.14, 'https://image.tmdb.org/t/p/w500/wvMd4qGoSdrgW046DTvmwPyt6TV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13090, 'Sunshine Cleaning', 'A single mother and her slacker sister find an unexpected way to turn their lives around in this off-beat dramatic comedy. In order to raise the tuition to send her young son to private school the mom starts an unusual business – a biohazard removal/crime scene clean-up service.', '2008-01-18', 6.59, 'https://image.tmdb.org/t/p/w500/xwtJyfme086wcz9MXpP0i5Hrgxy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13092, 'How to Lose Friends & Alienate People', 'Sidney Young is a down-on-his-luck journalist. Thanks to a stint involving a pig and a glitzy awards ceremony, Sidney turns his fortunes around, attracting the attention of Clayton Harding, editor of New York-based glossy magazine ''Sharps'', and landing the holy grail of journalism jobs. The Brit jets off to the Big Apple and moves from one blunder to the next.', '2008-10-02', 6.02, 'https://image.tmdb.org/t/p/w500/8Xd1mO861aK2OirTbxZrODNhihW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13094, 'Dance of the Dead', 'With Prom only hours away, the usual suspects of Cosa High (Cheerleaders, geeks, bad boys and the happy-go-lucky student council alike) are preoccupied with the annual rituals of teendom. On the night of the big dance when the dead unexpectedly rise to eat the living, polar opposite groups will be forced to unite in their final chance to save the town from the zombies.', '2008-10-14', 5.72, 'https://image.tmdb.org/t/p/w500/oUyLXz372Wd0r4xURDsYqX2m98w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13005, 'Where the Buffalo Roam', 'Semi-biographical film based on the experiences of gonzo journalist Hunter S. Thompson.', '1980-04-25', 5.94, 'https://image.tmdb.org/t/p/w500/8XgXvVmb5SdxWu4Enxh9ntbyate.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13098, 'Paid in Full', 'Ace is an impressionable young man working for a dry cleaning business. His friend, drug dealer Mitch, goes to prison. In an unrelated incident, he finds some cocaine in a pants pocket. Soon, Ace finds himself dealing cocaine for Lulu. Via lucky breaks and solid interpersonal skills, Ace moves to the top of the Harlem drug world. Of course, unfaithful employees and/or rivals conspire to bring about Ace''s fall.', '2002-10-25', 6.87, 'https://image.tmdb.org/t/p/w500/oiG5BObjENJjEacFdWw1KfK3TFx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13099, 'Gen-X Cops', 'Four young officers of the Hong Kong Police are joined together to fight against organised crime using all possible means, even if this would lead them to break the law… Their first assignment is to eliminate a gang of criminals who have stolen a shipload of explosives.', '1999-06-18', 5.39, 'https://image.tmdb.org/t/p/w500/2URAvYZ67Wwo7iceIfTHl050luM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13041, 'El Topo', 'El Topo decides to confront warrior Masters on a trans-formative desert journey he begins with his 6 year old son, who must bury his childhood totems to become a man.', '1970-12-18', 7.06, 'https://image.tmdb.org/t/p/w500/fKoNBTATc94rUYLq8VyypS24LUw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13105, 'Mr. Mom', 'Jack and Caroline are a couple making a decent living when Jack suddenly loses his job. They agree that he should stay at home and look after the house while Caroline works. It''s just that he''s never done it before, and really doesn''t have a clue...', '1983-07-22', 6.56, 'https://image.tmdb.org/t/p/w500/QuTlgKKykL7j0PnZZd3LNFVhCX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13107, 'Henry Poole Is Here', 'Henry Poole abandons his fiancée and family business to spend what he believes are his remaining days alone. The discovery of a ''miracle'' by a nosy neighbor ruptures his solitude and restores his faith in life.', '2008-08-15', 5.90, 'https://image.tmdb.org/t/p/w500/jUDrRxSuA7ZSHsIVd1MnFRtwLOf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13121, 'Teeth', 'Dawn is an active member of her high-school chastity club but, when she meets Tobey, nature takes its course, and the pair answer the call. They suddenly learn she is a living example of the vagina dentata myth, when the encounter takes a grisly turn.', '2008-01-18', 5.39, 'https://image.tmdb.org/t/p/w500/p7OIPkN2LOBprQxQx7EZBa6m6W4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13122, 'The People Under the Stairs', 'Trapped inside a fortified home owned by a mysterious couple, a young boy quickly learns the true nature of the homicidal inhabitants, and secret creatures hidden deep within the walls.', '1991-11-01', 6.55, 'https://image.tmdb.org/t/p/w500/8OWDBVmGdM7HwaDtbDsdn6Rlzqj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13132, 'All the Real Girls', 'In a sleepy little mill town in North Carolina, Paul is the town Romeo. But when his best friend''s sister returns home from boarding school, he finds himself falling for her innocent charm. In spite of her lack of experience and the violent protests of her brother, the two find themselves in a sweet, dreamy and all-consuming love.', '2003-02-14', 6.00, 'https://image.tmdb.org/t/p/w500/sQ6dMkwPIFucYSmFQcr38WBYzs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13125, 'Karate Bullfighter', 'Sonny Chiba plays  Kyokushin Karate founder Masutatsu Oyama, who unexpectedly arrives at a karate tournament in rags, but wins the tournament. After turning down the chance to fight at future tournaments he returns to his simple village life. He reluctantly returns to karate for a final showdown against the students of a rival school.', '1975-08-09', 6.70, 'https://image.tmdb.org/t/p/w500/qXl5qrodbgYuYIyzFH5ML7AOnWO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13141, 'Strangers with Candy', 'A prequel to the critically acclaimed series featuring Jerri Blank, a 46 year old ex-junkie, ex-con who returns to high school in a bid to start her life over.', '2006-06-28', 5.69, 'https://image.tmdb.org/t/p/w500/hPx4aELIbpf6ZRdHPmBH5h5Qs95.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13150, 'Pride and Glory', 'A saga centered on the Tierneys, a multi-generational family of New York City Police officers. The family''s moral codes are tested when Ray Tierney investigates a case that reveals an incendiary police corruption scandal involving his own brother-in-law. For Ray, the truth is revelatory, a Pandora''s Box that threatens to upend not only the Tierney legacy but the entire NYPD.', '2008-09-09', 6.33, 'https://image.tmdb.org/t/p/w500/8VZ1ABbtXqwPcc06yXbf3gj3anG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13153, 'Rapid Fire', 'College student Jake Lo is pursued by smugglers, mobsters and crooked federal agents after he witnesses a murder by a Mafia kingpin.', '1992-08-21', 6.43, 'https://image.tmdb.org/t/p/w500/sjZ3eS5Cvi7aS6nf4qwcTL2NS6P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13155, 'Return to Oz', 'Dorothy, saved from a psychiatric experiment by a mysterious girl, finds herself back in the land of her dreams, and makes delightful new friends, and dangerous new enemies.', '1985-06-21', 6.71, 'https://image.tmdb.org/t/p/w500/dyMwaXA9nVhPiA5wYHsvfUAnbaB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12700, 'Dominion: Prequel to The Exorcist', 'Father Merrin takes a sabbatical from the Church to devote himself to history and archaeology as he struggles with his shattered faith.', '2005-05-20', 5.34, 'https://image.tmdb.org/t/p/w500/nEkB6Y7DdEvWNCKWsHis76XYciR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12701, 'Revolution', 'New York trapper Tom Dobb becomes an unwilling participant in the American Revolution after his son Ned is drafted into the Army by the villainous Sergeant Major Peasy. Tom attempts to find his son, and eventually becomes convinced that he must take a stand and fight for the freedom of the Colonies, alongside the aristocratic rebel Daisy McConnahay. As Tom undergoes his change of heart, the events of the war unfold in large-scale grandeur.', '1985-12-25', 5.39, 'https://image.tmdb.org/t/p/w500/m4LPxSJ8G8KVtySaleJhlTJqKBF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13156, 'Secondhand Lions', 'The comedic adventures of an introverted boy left on the doorstep of a pair of reluctant, eccentric great-uncles, whose exotic remembrances stir the boy''s spirit and re-ignite the men''s lives.', '2003-09-19', 7.23, 'https://image.tmdb.org/t/p/w500/mYIMMAma7DCACRfiGhHAybPAdKa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12779, 'Swept Away', 'Stranded and alone on a desert island during a cruise, a spoiled rich woman and a deckhand fall in love and make a date to reunite after their rescue.', '2002-10-11', 4.70, 'https://image.tmdb.org/t/p/w500/rAa3nTeDpwgLX6XxnT3wR86C5WE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13166, 'Freddy Got Fingered', 'Unemployed cartoonist Gord Brody moves back in with his parents Jim and Julie and younger brother Freddy. When his parents demand he leave, he retaliates by spreading rumors that Jim is sexually abusing Freddy.', '2001-04-20', 4.73, 'https://image.tmdb.org/t/p/w500/gVmSZgxiT7ynyRLsEgg8Xs8ZVWX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13169, 'The Baxter', 'Mild mannered tax accountant Elliot Sherman is what he calls a "Baxter": the kind of calm, unexciting fellow who "wears sock garters" and "enjoys raking leaves." Loved by bosses and parents, Elliot is a perfectly nice guy. And that''s his problem.', '2005-08-26', 6.05, 'https://image.tmdb.org/t/p/w500/9V1ASfnxMZxrkqIvVQYySE5qSwd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13161, 'Big Stan', 'A weak con man panics when he learns he''s going to prison for fraud. He hires a mysterious martial arts guru who helps transform him into a martial arts expert who can fight off inmates who want to hurt or love him.', '2007-11-03', 6.66, 'https://image.tmdb.org/t/p/w500/zS1uUwKEFcd8ak0NTXxw97DlbAa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13158, 'Aqua Teen Hunger Force Colon Movie Film for Theaters', 'An action epic that explores the origins of the Aqua Teen Hunger Force (better known as Master Shake, Frylock, and Meatwad,) who somehow become pitted in a battle over an immortal piece of exercise equipment.', '2007-04-13', 6.44, 'https://image.tmdb.org/t/p/w500/q3Ln4x4rv4nJsBBfukjvH2wiU28.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13171, 'The Ex', 'When his lawyer wife, Sofia, becomes pregnant, chronic underachiever Tom Reilly must take a job at his father-in-law''s advertising firm. Tom has to adjust to the demands of a very high-powered job, and he finds himself in an increasingly hostile office rivalry with Chip, Sofia''s paraplegic former lover.', '2006-12-01', 5.28, 'https://image.tmdb.org/t/p/w500/qpWQMCkLK8ocyUCKUibUfy6yFaq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13173, 'The Ten', 'Ten stories, each inspired by one of the ten commandments.', '2007-08-03', 4.76, 'https://image.tmdb.org/t/p/w500/byhpbEcL1tuoNhU3x5vYF45QM8X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13177, 'Battle in Seattle', 'Thousands of activists arrive in Seattle, Washington in masses to protest the WTO Ministerial Conference of 1999 (World Trade Organization). Although it began as a peaceful protest with a goal of stopping the WTO talks, it escalated into a full-scale riot and eventually, a State of Emergency that pitted protesters against the Seattle Police Department and the National Guard.', '2007-09-07', 6.31, 'https://image.tmdb.org/t/p/w500/jO8tKM4mCMXpLVd5GnmlfJByghF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13180, 'Zeitgeist: Addendum', 'Director Peter Joseph examines examples of economic subjugation and offers solutions based on alignment with nature.', '2008-10-02', 7.22, 'https://image.tmdb.org/t/p/w500/5zlBxoyWRyzPOHO7QmmAC1WG9bK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13025, 'Diary of the Dead', 'A group of young filmmakers encounter real zombies while filming a horror movie of their own.', '2007-05-26', 5.54, 'https://image.tmdb.org/t/p/w500/tGktSJW5dPf8QIjmcqum4KOEZPZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13067, 'In the Land of Women', 'After a bad breakup with his girlfriend leaves him heartbroken, Carter Webb moves to Michigan to take care of his ailing grandmother. Once there, he gets mixed up in the lives of the mother and daughters who live across the street.', '2007-04-20', 5.89, 'https://image.tmdb.org/t/p/w500/qbfVeY8sE3luiRXYZTPT9rjV6p1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13042, 'Presto', 'Dignity. Poise. Mystery. We expect nothing less from the great turn-of-the-century magician, Presto. But when Presto neglects to feed his rabbit one too many times, the magician finds he isn''t the only one with a few tricks up his sleeve!', '2008-06-27', 7.79, 'https://image.tmdb.org/t/p/w500/aKDwLqR0JWoLX7dgwje42vCwhBd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13051, 'Max Payne', 'A DEA agent whose family was slain as part of a conspiracy, and an assassin out to avenge her sister''s death, join forces to solve a series of murders in New York City.', '2008-10-15', 5.42, 'https://image.tmdb.org/t/p/w500/dxy17rpjiWVmhaGvMlScZj96i8h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13184, 'Bangkok Dangerous', 'When carrying out a hit, assassin Joe always makes use of the knowledge of the local population. On arriving in Bangkok, Joe meets street kid Kong and he becomes his primary aide. But when Kong is nearly killed, he asks Joe to train him up in the deadly arts and unwittingly becomes a target of a band of killers.', '2008-08-21', 5.31, 'https://image.tmdb.org/t/p/w500/iTRftxHW8i4H7ONaOiCIwEXjNDJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13194, 'Highlander: The Search for Vengeance', 'Colin MacLeod hunts for the man responsible for the death of his love. He chases the immortal Marcus Octavius across centuries as his quest threatens to take over his life and heart. In his quest, he meets a woman who reminds him of his slain beauty. But it''s his final battle with Marcus that will decide not only his fate, but also the fate of everyone in the world.', '2007-06-05', 7.20, 'https://image.tmdb.org/t/p/w500/f4htbMf2LORgMjKn0litcUFWuWY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13027, 'Eagle Eye', 'Jerry Shaw and Rachel Holloman are two strangers whose lives are suddenly thrown into turmoil by a mysterious woman they have never met. Threatening their lives and family, the unseen caller uses everyday technology to control their actions and push them into increasing danger. As events escalate, Jerry and Rachel become the country''s most-wanted fugitives and must figure out what is happening to them.', '2008-09-25', 6.50, 'https://image.tmdb.org/t/p/w500/9KCOv0hL37IN3tWG3j86eZg3xDH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13186, 'Wrong Turn 2: Dead End', 'Retired military commander Colonel Dale Murphy hosts the simulated post-apocalyptic reality show where participants are challenged to survive a remote West Virginia wasteland. But the show turns into a nightmarish showdown when each realizes they are being hunted by an inbred family of cannibals determined to make them all dinner!', '2007-08-25', 6.18, 'https://image.tmdb.org/t/p/w500/ow3IMhTVLryZuCEoQznVTTmFYuu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13188, 'Scrooge', 'Ebenezer Scrooge malcontentedly shuffles through life as a cruel, miserly businessman, until he is visited by three spirits on Christmas Eve who show him how his unhappy childhood and adult behavior has left him a selfish, lonely old man.', '1951-11-30', 7.44, 'https://image.tmdb.org/t/p/w500/sxLRt2u5xgUgkrIAPyE0KiiSVnX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13054, 'Rise of the Footsoldier', 'Carlton Leach rises from one of the most feared generals of the football terraces to becoming a member of a notorious gang of criminals who rampaged their way through London and Essex in the late ''80s and early ''90s.', '2007-09-07', 6.34, 'https://image.tmdb.org/t/p/w500/k8lbsM0Nl0c1Qp7NnARWjS6TTRA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (12797, 'Ghost Town', 'Bertram Pincus, a cranky, people-hating Manhattan dentist, develops the unwelcome ability to see dead people. Really annoying dead people. Even worse, they all want something from him, particularly Frank Herlihy, a smooth-talking ghost, who pesters him into a romantic scheme involving his widow Gwen. They are soon entangled in a hilarious predicament between the now and the hereafter!', '2008-09-19', 6.50, 'https://image.tmdb.org/t/p/w500/b8VS14DwpLlugTxVWSllYU0Gjn5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13053, 'Bolt', 'Bolt is the star of the biggest show in Hollywood. The only problem is, he thinks it''s real. After he''s accidentally shipped to New York City and separated from Penny, his beloved co-star and owner, Bolt must harness all his "super powers" to find a way home.', '2008-11-21', 6.55, 'https://image.tmdb.org/t/p/w500/v5aC4nrzXFGJDWY4JO1eengXzqk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13199, 'American Me', 'During his 18 years in Folsom Prison, street-gang leader Santana rules over all the drug-and-murder activities behind bars. Upon his release, Santana goes back to his old neighborhood, intending to lead a peaceful, crime-free life. But his old gang buddies force him back into his old habits.', '1992-03-13', 7.41, 'https://image.tmdb.org/t/p/w500/mrcdh66L6K1Nb5xPORuZufvE9aE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13225, 'FernGully: The Last Rainforest', 'When a sprite named Crysta shrinks a human boy, Zak, down to her size, he vows to help the magical fairy folk stop a greedy logging company from destroying their home: the pristine rainforest known as FernGully. Zak and his new friends fight to defend FernGully from lumberjacks — and the vengeful spirit they accidentally unleash after chopping down a magic tree.', '1992-04-10', 6.41, 'https://image.tmdb.org/t/p/w500/xkJxdeaibcrcsi1XHvT0IuOjdzB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13245, 'Atanarjuat: The Fast Runner', 'Based on a local legend and set in an unknown era, it deals with universal themes of love, possessiveness, family, jealousy and power. Beautifully shot, and acted by Inuit people, it portrays a time when people fought duels by taking turns to punch each other until one was unconscious, made love on the way to the caribou hunt, ate walrus meat and lit their igloos with seal-oil lamps.', '2002-02-01', 6.79, 'https://image.tmdb.org/t/p/w500/jSGiFOTwosoiAAXLTLHtzMUCVUN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13251, 'The Walker', 'Carter Page III, a middle-aged gay man in Washington, D. C., is a "walker", a single man who escorts other men''s wives to social events so the husbands do not have to. One of the women he escorts, Lynn Lockner, is the wife of a United States senator and is carrying on an affair with a lobbyist. When she finds the lobbyist murdered, she embroils Carter in an investigation that leads to the highest levels of the federal government.', '2007-02-13', 5.28, 'https://image.tmdb.org/t/p/w500/iPt75oLdldVWjeq6Omnn1Es4EuF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13253, 'Futurama: Bender''s Game', 'When Leela is insulted by a group of space-rednecks (like regular rednecks, but in space), she enters the Planet Express ship in a demolition derby. Leela emerges victorious, but when she brings the damaged ship home, and the Professor sees the fuel gauge, he''s enraged by the hit he''s going to take at the Dark Matter pump.  Now the crew have to find a way to break Mom''s stranglehold on starship fuel, even if they have to wade through a Lord of the Rings-inspired fantasy-land to do it!', '2008-11-03', 6.89, 'https://image.tmdb.org/t/p/w500/bx8OVOBn5WP9TJJuOpRzyMCdzzb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13192, 'Moonwalker', 'This fantastical movie inspired by the music of Michael Jackson features imaginative interpretations of hit tracks from the iconic 1987 album “Bad”.', '1988-10-29', 7.11, 'https://image.tmdb.org/t/p/w500/3GwTPQkAcgDeAirRpEuJG8HDdRz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13256, 'Mutant Chronicles', 'It''s the year 2707. Earth''s natural resources have all but been exhausted by mankind. Battles rage for the remainder between the competing Corporations. During one such battle the seal is broken and awakens an ancient and deadly machine that was once defeated thousands of years ago. The order that awaited its return must now lead a small group of soldiers to destroy it once and for all.', '2008-08-07', 5.31, 'https://image.tmdb.org/t/p/w500/vHH9VnQZYdhWE9PMMKUpYrG1Z0Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13257, 'Mr. Woodcock', 'Taken aback by his mother''s wedding announcement, a young man returns home in an effort to stop her from marrying his old high school gym teacher, a man who made high school hell for generations of students.', '2007-09-14', 5.07, 'https://image.tmdb.org/t/p/w500/tNOovj6N2C5scr0KgND0aKT2kkd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13258, 'Son of Rambow', 'Will is looking for an escape from his family when he encounters Lee, the school bully. Armed with a video camera and a copy of Rambo, Lee plans to make his own action-packed video epic.', '2007-01-22', 6.73, 'https://image.tmdb.org/t/p/w500/hOCdlpTs91eDohj5LhCGQF4bxqe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13260, 'Semi-Pro', 'Jackie Moon is the owner, promoter, coach, and star player of the Flint Michigan Tropics of the American Basketball Association (ABA), the worst team in the league. In 1976 before the ABA collapses, the NBA plans to merge with the best teams of the ABA at the end of the season. Only the top four teams will make the move and the worst teams will fold. If the Tropics want to make it to the NBA, Jackie Moon must rally his team and start winning.', '2008-02-28', 5.62, 'https://image.tmdb.org/t/p/w500/7KJrvJf96UpkXsWVOjzCo1IbnW6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13275, 'Annapolis', 'Jake Huard, from a shipbuilders family, promised his dying mother he''ld make it to Anapolis Naval Academy. Thanks to tenaciously bugging a Congressman, he''s selected despite dubious grades. Once inside, Jake soon proves sub-standard academically. Constantly challenged to his limits, repeatedly made the ''over-cocky'' reason for the entire class to suffer, Jake nearly quits, but after facing his utterly un-supportive father''s gloating returns just in time. Stubborn Jake finds support withs mates as well as Senor Ali, his lover-to-be, and a discipline he may excel in: the ''brigade'' boxing tournament, open to all ranks.', '2006-01-27', 6.89, 'https://image.tmdb.org/t/p/w500/hH6YeqFcihbZsz7iWl6MzQVzL8O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13279, 'Lakeview Terrace', 'A young interracial couple has just moved into their California dream home when they become the target of their next-door neighbor, who disapproves of their relationship. A tightly wound LAPD officer has appointed himself the watchdog of the neighborhood. His nightly foot patrols and overly watchful eyes bring comfort to some, but he becomes increasingly aggressive to the newlyweds. These persistent intrusions into their lives cause the couple to fight back.', '2008-09-19', 5.97, 'https://image.tmdb.org/t/p/w500/A1kqp2hALf8Gd03vDACnR0EtFWo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13280, 'Kickin'' It Old Skool', 'In 1986, a young breakdancer falls into a coma after hitting his head in a talent show. 20 years later, he awakens and attempts to revive his dance team''s short-lived career in order to support his parents'' failing yogurt shop.', '2007-04-27', 4.80, 'https://image.tmdb.org/t/p/w500/yigEC20RnNqaXPeItmEO3RpdFdB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13282, 'Death Race 2000', 'In a boorish future, the government sponsors a popular, but bloody, cross-country race in which points are scored by mowing down pedestrians. Five teams, each comprised of a male and female, compete using cars equipped with deadly weapons. Frankenstein, the mysterious returning champion, has become America''s hero, but this time he has a passenger from the underground resistance.', '1975-04-30', 6.16, 'https://image.tmdb.org/t/p/w500/kwM8kkNGtv62gfPWVhD6qFxjDzg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13291, 'Traitor', 'When straight arrow FBI agent Roy Clayton heads up the investigation into a dangerous international conspiracy, all clues seem to lead back to former U.S. Special Operations officer Samir Horn.', '2008-08-23', 6.65, 'https://image.tmdb.org/t/p/w500/va4Uo7L2b4d96JTdRMclO9L2hY0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13300, 'Hell Ride', 'Two rival bikers gangs, the Victors and the Six-Six-Six''s, refuel their decades-old rivalry.', '2008-08-08', 5.22, 'https://image.tmdb.org/t/p/w500/rZcKg8Zai9J4vFq1fAbbtGOOqix.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13310, 'Let the Right One In', 'When Oskar, a sensitive, bullied 12-year-old boy, meets his new neighbor, the mysterious and moody Eli, they strike up a friendship. Initially reserved with each other, Oskar and Eli slowly form a close bond, but it soon becomes apparent that she is no ordinary young girl.', '2008-10-24', 7.55, 'https://image.tmdb.org/t/p/w500/7IG4WjaAOVDlLvLUkh513HSwhW8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13187, 'A Charlie Brown Christmas', 'When Charlie Brown complains about the overwhelming materialism that he sees amongst everyone during the Christmas season, Lucy suggests that he become director of the school Christmas pageant. Charlie Brown accepts, but it is a frustrating struggle. When an attempt to restore the proper spirit with a forlorn little fir Christmas tree fails, he needs Linus'' help to learn the meaning of Christmas.', '1965-12-09', 7.69, 'https://image.tmdb.org/t/p/w500/vtaufTzJBMJAeziQA1eP4BLU24C.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13312, 'Inside', 'Months after a tragic accident, Sarah, a young pregnant woman, must spend Christmas Eve alone in her house before giving birth the next day. But in the middle of the night, a creepy visitor knocks at her door willing to do anything to get what they want, setting off a night of pure terror.', '2007-06-13', 6.73, 'https://image.tmdb.org/t/p/w500/7gPOYKxoBzhfC8cLNMU3CKgURcm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13320, 'Funny Face', 'A shy Greenwich Village book clerk is discovered by a fashion photographer and whisked off to Paris where she becomes a reluctant model.', '1957-02-13', 6.98, 'https://image.tmdb.org/t/p/w500/tzTjalpIz6NyFrWPPlOBFoBjb7z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13313, 'Beauty and the Beast: The Enchanted Christmas', 'Astonished to find the Beast has a deep-seated hatred for the Christmas season, Belle endeavors to change his mind on the matter.', '1997-11-11', 6.23, 'https://image.tmdb.org/t/p/w500/l1Tb0fvnj9wnCgm5qnTRoO6OxDT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13333, 'Game of Death', 'A martial arts movie star must fake his death to find the people who are trying to kill him.', '1978-03-23', 6.37, 'https://image.tmdb.org/t/p/w500/c6jgLHaQpdIPH1rC94KkjAqgE7O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13321, 'Lifeboat', 'During World War II, a small group of survivors is stranded in a lifeboat together after the ship they were traveling on is destroyed by a German U-boat.', '1944-01-28', 7.36, 'https://image.tmdb.org/t/p/w500/2QXpzBMJJtmH7JvVf0ZzENvgc1o.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13335, 'Harold & Kumar Escape from Guantanamo Bay', 'Having satisfied their urge for White Castle, Harold and Kumar jump on a plane to catch up with Harold''s love interest, who''s headed for the Netherlands. But the pair must change their plans when Kumar is accused of being a terrorist. Rob Corddry also stars in this wild comedy sequel that follows the hapless stoners'' misadventures as they try to avoid being captured by the Department of Homeland Security.', '2008-04-25', 6.32, 'https://image.tmdb.org/t/p/w500/gmXKlm8c8O7JEISYP4WiWq2x3We.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13339, 'Three O''Clock High', 'Nerdy high schooler Jerry Mitchell is assigned to write an article for the school paper about the infamous new delinquent transfer student, Buddy Revell. When Jerry accidentally invades Buddy''s personal space and touches him, Buddy challenges Jerry to an afterschool fight in the parking lot, which Jerry tries to avoid at all costs.', '1987-10-09', 6.80, 'https://image.tmdb.org/t/p/w500/8IKEBJdaFWVBxPmsmUx5eICRwKf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13341, 'Bad News Bears', 'Morris Buttermaker is a burned-out minor league baseball player who loves to drink and can''t keep his hands to himself. His long-suffering lawyer arranges for him to manage a local Little League team, and Buttermaker soon finds himself the head of a rag-tag group of misfit players. Through unconventional team-building exercises and his offbeat coaching style, Buttermaker helps his hapless Bears prepare to meet their rivals, the Yankees.', '2005-07-22', 5.83, 'https://image.tmdb.org/t/p/w500/ja1yrgfYAGmwnridioMY3MV0GDm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13346, 'Lucas', 'A brilliant but socially inept 14-year-old experiences heartbreak for the first time when his two best friends – Cappie, an older-brother figure, and Maggie, the new girl with whom he is in love – fall for each other.', '1986-03-28', 6.75, 'https://image.tmdb.org/t/p/w500/7qq4sxYj59Aq6wmnnIlot5iXaux.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13056, 'Punisher: War Zone', 'Waging his one-man war on the world of organized crime, ruthless vigilante-hero Frank Castle sets his sights on overeager mob boss Billy Russoti. After Russoti is left horribly disfigured by Castle, he sets out for vengeance under his new alias: Jigsaw. With the "Punisher Task Force" hot on his trail and the FBI unable to take Jigsaw in, Frank must stand up to the formidable army that Jigsaw has recruited before more of his evil deeds go unpunished.', '2008-12-05', 5.88, 'https://image.tmdb.org/t/p/w500/oOvKJgYUIpfswGHAdW6159bPbvM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13183, 'Watchmen', 'In a gritty and alternate 1985, the glory days of costumed vigilantes have been brought to a close by a government crackdown. But after one of the masked veterans is brutally murdered, an investigation into the killer is initiated. The reunited heroes set out to prevent their own destruction, but in doing so they uncover a sinister plot that puts all of humanity in grave danger.', '2009-03-04', 7.36, 'https://image.tmdb.org/t/p/w500/aVURelN3pM56lFM7Dgfs5TixcIf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13198, 'Wristcutters: A Love Story', 'Zia, distraught over breaking up with his girlfriend, decides to end it all. Unfortunately, he discovers that there is no real ending, only a run-down afterlife that is strikingly similar to his old one, just a bit worse. Discovering that his ex-girlfriend has also "offed" herself, he sets out on a road trip to find her.', '2007-10-19', 6.97, 'https://image.tmdb.org/t/p/w500/qModiIR60IMLP28ruGZluQOtsOj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13068, 'Rocket Science', 'Hal is a 15-year-old high-school student with a minor yet socially alienating (and painful) disability: he stutters uncontrollably. Determined to work through the problem, Hal opts for an extreme route – he joins the school debating team, which sends him on a headfirst plunge into breakneck speech competitions and offers a much-needed boost toward correcting the problem.', '2007-01-19', 6.24, 'https://image.tmdb.org/t/p/w500/d5MfQznQKNtTsLFhw4wVXoqfk5y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13193, 'Saved!', 'Mary is a good Christian girl who goes to a good Christian high school where she has good Christian friends and a perfect Christian boyfriend. Her life seems perfect, until the day that she finds out that her boyfriend may be gay — and that she’s pregnant.', '2004-06-11', 6.42, 'https://image.tmdb.org/t/p/w500/nmf2tFTcRJZVEQ9e3mgLH5gAQYs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13348, 'Helvetica', 'Helvetica is a feature-length independent film about typography, graphic design and global visual culture. It looks at the proliferation of one typeface (which will celebrate its 50th birthday in 2007) as part of a larger conversation about the way type affects our lives. The film is an exploration of urban spaces in major cities and the type that inhabits them, and a fluid discussion with renowned designers about their work, the creative process, and the choices and aesthetics behind their use of type.', '2007-09-12', 7.18, 'https://image.tmdb.org/t/p/w500/s47TOnvnwfSnAflQvsBxJbOLnmP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13342, 'Fast Times at Ridgemont High', 'A group of Southern-California high school students ignore their studies in favor of indulging in their teenage distractions.', '1982-08-13', 6.79, 'https://image.tmdb.org/t/p/w500/e15rmfjf0m6EGLe4MnNhwD3Dd1W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13073, 'Palindromes', 'Aviva is thirteen, awkward and sensitive. Her mother Joyce is warm and loving, as is her father, Steve, a regular guy who does have a fierce temper from time to time. The film revolves around her family, friends and neighbors.', '2005-03-09', 6.24, 'https://image.tmdb.org/t/p/w500/yqcNYtm3F7GhCgAnTcQslKzMFOf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13064, 'Airborne', 'Good-natured teen surfer Mitchell Goosen finds himself staying with his aunt and uncle in Cincinnati, Ohio when his parents head to Australia for work. There he meets his cousin, Wiley, and together they try to navigate the perils of high school—avoid the bullies, get the girl, and win a little respect.', '1993-09-17', 6.02, 'https://image.tmdb.org/t/p/w500/4TPCzvOoQmmParPjgHCiqqiVYIJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13203, 'Son in Law', 'Country girl Rebecca has spent most of her life on a farm in South Dakota, and, when she goes away to college in Los Angeles, Rebecca immediately feels out of place in the daunting urban setting. She is befriended by a savvy party animal named Crawl, who convinces the ambivalent Rebecca to stay in the city. When Thanksgiving break rolls around, Rebecca, no longer an innocent farm girl, invites Crawl back to South Dakota, where he pretends to be her fiancé.', '1993-07-02', 6.03, 'https://image.tmdb.org/t/p/w500/gj4afHL9bMQ18opZzMp77tlPkAq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13060, 'Lifted', 'When an overconfident teen alien gets behind the controls of a spaceship, he must attempt to abduct a slumbering farmer under the watchful eye of a critical instructor. But abducting humans requires precision and a gentle touch, and within a few missteps it''s painfully clear why more humans don''t go missing every year.', '2006-12-28', 7.46, 'https://image.tmdb.org/t/p/w500/iwI3R8ZR3MQ5dnTx9tHSiS81i4W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13197, '10th & Wolf', 'A former street thug returns to his Philadelphia home after a stint in the military. Back on his home turf, he once again finds himself tangling with the mob boss who was instrumental in his going off to be a soldier.', '2006-02-19', 5.87, 'https://image.tmdb.org/t/p/w500/2OBZth9rnSyMzZR8M0WwGj8ivDG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13372, 'Outfoxed: Rupert Murdoch''s War on Journalism', 'This film examines how media empires, led by Rupert Murdoch''s Fox News, have been running a "race to the bottom" in television news, and provides an in-depth look at Fox News and the dangerous impact on society when a broad swath of media is controlled by one person.  Media experts, including Jeff Cohen (FAIR) Bob McChesney (Free Press), Chellie Pingree (Common Cause), Jeff Chester (Center for Digital Democracy) and David Brock (Media Matters) provide context and guidance for the story of Fox News and its effect on society.  This documentary also reveals the secrets of Former Fox news producers, reporters, bookers and writers who expose what it''s like to work for Fox News.  These former Fox employees talk about how they were forced to push a "right-wing" point of view or risk their jobs. Some have even chosen to remain anonymous in order to protect their current livelihoods. As one employee said "There''s no sense of integrity as far as having a line that can''t be crossed."', '2004-07-14', 7.00, 'https://image.tmdb.org/t/p/w500/5SodI4NHGIHghH6HGfqryiNlMSA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13373, 'Millions', 'Two boys, still grieving the death of their mother, find themselves the unwitting benefactors of a bag of bank robbery loot in the week before the United Kingdom switches its official currency to the Euro. What''s a kid to do?', '2005-04-08', 6.39, 'https://image.tmdb.org/t/p/w500/rypaIocIovS3ICLKKakMvHDDQ0T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13376, 'Eight Crazy Nights', 'Davey Stone, a 33-year old party animal, finds himself in trouble with the law after his wild ways go too far.', '2002-11-27', 5.23, 'https://image.tmdb.org/t/p/w500/p8yiNFvs7q7ymxVAkym3WuYygrn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13374, 'Ice Princess', 'With the help of her coach, her mom, and the boy who drives the Zamboni, nothing can stop Casey Carlyle from realizing her dream to be a champion figure skater.', '2005-03-17', 6.40, 'https://image.tmdb.org/t/p/w500/ptOO4Or8KyB4k3BRyyUvAPJCfYe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13377, 'How the Grinch Stole Christmas!', 'Bitter and hateful, the Grinch is irritated at the thought of a nearby village having a happy time celebrating Christmas. Disguised as Santa Claus, with his dog made to look like a reindeer, he decides to raid the village to steal all the Christmas things.', '1966-12-18', 7.51, 'https://image.tmdb.org/t/p/w500/7ir0iRuPK9OEuH569cp0nF5CJce.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13382, 'Rudolph the Red-Nosed Reindeer', 'Sam the snowman tells us the story of a young red-nosed reindeer who, after being ousted from the reindeer games because of his glowing nose, teams up with Hermey, an elf who wants to be a dentist, and Yukon Cornelius, the prospector. They run into the Abominable Snowman and find a whole island of misfit toys. Rudolph vows to see if he can get Santa to help the toys, and he goes back to the North Pole on Christmas Eve. But Santa''s sleigh is fogged in. But when Santa looks over Rudolph, he gets a very bright idea...', '1964-12-06', 7.42, 'https://image.tmdb.org/t/p/w500/xjAElUhXuc7zFJPj3qUHjcySNsE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13386, 'I''m Starting from Three', 'Gaetano, a young Neapolitan, decides to leave home, work and friends, to look for other moments of life and meet other people.', '1981-03-05', 7.62, 'https://image.tmdb.org/t/p/w500/lS0X9KScgkUbhiu6lOHBya8z9R2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13387, 'Transporter 3', 'Frank Martin puts the driving gloves on to deliver Valentina, the kidnapped daughter of a Ukrainian government official, from Marseilles to Odessa on the Black Sea. En route, he has to contend with thugs who want to intercept Valentina''s safe delivery and not let his personal feelings get in the way of his dangerous objective.', '2008-11-26', 6.17, 'https://image.tmdb.org/t/p/w500/o4w9VF3GRZuXe9NHHvZ07pJespl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13389, 'Righteous Kill', 'Two veteran New York City detectives work to identify the possible connection between a recent murder and a case they believe they solved years ago; is there a serial killer on the loose, and did they perhaps put the wrong person behind bars?', '2008-09-11', 5.87, 'https://image.tmdb.org/t/p/w500/wKL5pzUfGOqOFjf0VN47nXlZOAL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13393, 'My Father and My Son', 'A left-wing journalist whose wife died while giving birth to his son during a military coup returns to his family''s farm. Estranged from his father for turning his back on the family and wasting his life with political activism instead, he tries to reconnect with him so that his son will have a place to live as his health is deteriorating due to the extensive torture he had to endure.', '2005-11-18', 7.39, 'https://image.tmdb.org/t/p/w500/ephCcqJYZFUnkQC7Oudah2qUL6O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13394, 'Shrek the Halls', 'The Christmas tree isn''t the only thing green in this new holiday classic. Shrek is back and trying to get into the spirit of the season. After promising Fiona and the kids a Christmas they''ll remember, he is forced to take a crash course in the holiday. But just when he thinks he has everything for their quiet family Christmas just right, there is a knock at the door.', '2007-11-28', 6.38, 'https://image.tmdb.org/t/p/w500/zeqUbXA0JPSlyAHdRTgxoYgK24n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13352, 'It''s a Very Merry Muppet Christmas Movie', 'The owner of a bank (Miss Bitterman) wants to own the Muppet Theatre so she can build a nightclub over it. After she tricks Pepe into giving her the only copy of the contract between her father and the Muppets, she changes it so the Muppets have very little time to pay a debt they owe. Meanwhile, the Muppets are trying to put on a Christmas show. After the Muppets are confronted by Bitterman, they make a lot of sacrifices to save up so they can keep the Theatre.', '2002-11-29', 6.03, 'https://image.tmdb.org/t/p/w500/j5O65ITSvFGalNI2wRHHAPymO5R.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13398, 'Tokyo Godfathers', 'On Christmas Eve, three homeless people living on the streets of Tokyo discover a newborn baby among the trash and set out to find its parents.', '2003-12-05', 7.93, 'https://image.tmdb.org/t/p/w500/sPC66btzQlzuRdPKiSDYZ5Hvxgc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13396, 'The Snowman', 'A young boy makes a snowman one Christmas Eve, which comes to life at midnight and takes him on a magical adventure to the North Pole to meet Santa Claus.', '1982-12-26', 7.58, 'https://image.tmdb.org/t/p/w500/b3CMolkeXrPaVvd5vTsssMKfZZo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13403, 'Hedwig and the Angry Inch', 'Raised a boy in East Berlin, Hedwig undergoes a personal transformation in order to emigrate to the U.S., where she reinvents herself as an ''internationally ignored'' but divinely talented rock diva, inhabiting a ''beautiful gender of one''.', '2001-07-20', 7.40, 'https://image.tmdb.org/t/p/w500/jafIFAW8sHQkzWPGoMDR4892dFI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13405, 'The Children of Huang Shi', 'About young British journalist, George Hogg, who with the assistance of a courageous Australian nurse, saves a group of orphaned children during the Japanese occupation of China in 1937.', '2008-04-03', 6.64, 'https://image.tmdb.org/t/p/w500/qjmo26BnSimVjhCE97cH8VCtEUV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13411, 'Malibu''s Most Wanted', 'A senator arranges for his son, a rich white kid who fancies himself black, to be kidnapped by a couple of black actors pretending to be murderers to try and shock him out of his plans to become a rapper.', '2003-04-10', 5.39, 'https://image.tmdb.org/t/p/w500/bjYuoz2S8S1AED5QIMvmAi21drc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13413, 'BURN·E', 'What lengths will a robot undergo to do his job? BURN·E is a dedicated hard working robot who finds himself locked out of his ship. BURN·E quickly learns that completing a simple task can often be a very difficult endeavor.', '2008-11-17', 7.51, 'https://image.tmdb.org/t/p/w500/1wOReJq1vArLBSejND2Jbw0KeKh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13409, 'State Property: Blood on the Streets', 'Three gangsters vie for control of the streets of Philadelphia.', '2005-04-13', 6.12, 'https://image.tmdb.org/t/p/w500/plp9AHFlFghfmMESJyPmsJnhQao.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13416, 'Friday Night Lights', 'A small, turbulent town in Texas obsesses over their high school football team to an unhealthy degree. When the star tailback, Boobie Miles, is seriously injured during the first game of the season, all hope is lost, and the town''s dormant social problems begin to flare up. It is left to the inspiring abilities of new coach Gary Gaines to instill in the other team members -- and, by proxy, the town itself -- a sense of self-respect and honor.', '2004-10-08', 6.90, 'https://image.tmdb.org/t/p/w500/8HIqpOgqShRc3TAleabnYispDl1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13353, 'It''s the Great Pumpkin, Charlie Brown', 'Join the Peanuts gang for a timeless adventure as Charlie Brown preps for a party, Snoopy sets his sights on the Red Baron, and Linus patiently awaits a pumpkin patch miracle.', '1966-10-27', 7.50, 'https://image.tmdb.org/t/p/w500/59wp9OWexYsxlSPHYmVLsl5xlFt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13417, 'Kronk''s New Groove', 'After his adventures with Kuzco, Kronk opens his own diner, but struggling business and the impending visit from his father push him to hatch a risky plan for success. When the scheme explodes—literally—Kronk must rely on his many personalities to rediscover that true happiness comes from staying true to himself.', '2005-12-05', 6.41, 'https://image.tmdb.org/t/p/w500/kyMrt0RPVC8LDpdMrk1DjN6Gqdu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13433, 'Japanese Story', 'Sandy, a geologist, finds herself stuck on a field trip to the Pilbara desert with a Japanese man she finds inscrutable, annoying and decidedly arrogant. Hiromitsu''s view of her is not much better. Things go from bad to worse when they become stranded in one of the most remote regions on Earth.', '2003-08-30', 6.30, 'https://image.tmdb.org/t/p/w500/bgazOSULGJSF2DNnyfWkOWn74ei.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13435, 'Antwone Fisher', 'A sailor prone to violent outbursts is sent to a naval psychiatrist for help. Refusing at first to open up, the young man eventually breaks down and reveals a horrific childhood. Through the guidance of his doctor, he confronts his painful past and begins a quest to find the family he never knew.', '2002-12-19', 6.94, 'https://image.tmdb.org/t/p/w500/j9lCK1aFXqMO3hzhGiqCNU8coIX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13438, 'Marooned in Iraq', 'During the war between Iran and Iraq, a group of Iranian Kurd musicians set off on an almost impossible mission. They will try to find Hanareh, a singer with a magic voice who crossed the border and may now be in danger in the Iraqi Kurdistan. As in his previous films, this Kurdish director is again focusing on the oppression of his people.', '2002-10-09', 6.96, 'https://image.tmdb.org/t/p/w500/mzWqK0U0APFiXKofG1qzl1OEYgW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13448, 'Angels & Demons', 'Harvard symbologist Robert Langdon is recruited by the Vatican to investigate the apparent return of the Illuminati – a secret, underground organization – after four cardinals are kidnapped on the night of the papal conclave.', '2009-04-20', 6.72, 'https://image.tmdb.org/t/p/w500/tFZQAuulEOtFTp0gHbVdEXwGrYe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13358, 'A Dennis the Menace Christmas', 'A Dennis The Menace version of A Christmas Carol where Mr. Wilson plays his own version of Scrooge. While Dennis has problems of his own with the neighborhood bully, he does his best to try and give Mr. Wilson the Christmas Spirit. Dennis causes his usual damage and Mr. Wilson ends up breaking Dennis'' spirit. An Angel of Christmas Past Present and Future steps in to help save Christmas for the Mitchells, the Wilsons, and everyone else.', '2007-11-13', 5.50, 'https://image.tmdb.org/t/p/w500/cgjyUL2STLzjOGb3mXePXpNNC1O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13368, 'White Christmas', 'Two talented song-and-dance men team up after the war to become one of the hottest acts in show business. In time they befriend and become romantically involved with the beautiful Haynes sisters who comprise a sister act.', '1954-10-14', 7.18, 'https://image.tmdb.org/t/p/w500/A5kBQsHKbIptxJyELEpHQJROCRj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13207, 'Friday the 13th', 'A group of young adults visit a boarded up campsite named Crystal Lake where they soon encounter the mysterious Jason Voorhees and his deadly intentions.', '2009-02-11', 5.77, 'https://image.tmdb.org/t/p/w500/88wlJ4teYlck4hJ2bnlxBrAVh0m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13363, 'The Man from Earth', 'A departing professor gathers his closest colleagues for an intimate farewell, but the night takes an unexpected turn when he shares a stunning secret about his past. As the conversation unfolds, skepticism and curiosity collide, challenging everything they thought they knew about history, science, and belief.', '2007-06-10', 7.62, 'https://image.tmdb.org/t/p/w500/V086R82gNgWrotaXZFO4JhdgB1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13201, 'Deuces Wild', 'In 1950s New York City, a bad and bloody gang war is about to erupt on the dysfunctional streets of Brooklyn between the Deuces and the vicious Vipers.', '2002-05-03', 5.49, 'https://image.tmdb.org/t/p/w500/nyr9WT4mLYZHFRINuyWCQExV9ku.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13359, 'Expelled: No Intelligence Allowed', 'Pro-intelligent design scholars and scientists are often chastised, fired or denied tenured positions by those who believe in Darwin''s theory of evolution.', '2008-04-18', 3.88, 'https://image.tmdb.org/t/p/w500/fQgNm7DK6DxfBuSfhQSjtGZYALf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13455, 'Push', 'After his father, an assassin, is brutally murdered, Nick Gant vows revenge on Division, the covert government agency that dabbles in psychic warfare and experimental drugs. Hiding in Hong Kong''s underworld, Nick assembles a band of rogue psychics dedicated to destroying Division. Together with Cassie, a teenage clairvoyant, Nick goes in search of a missing girl and a stolen suitcase that could be the key to accomplishing their mutual goal.', '2009-02-04', 6.14, 'https://image.tmdb.org/t/p/w500/fHStfRjQGstuqtUz4Q22lbFU58M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13460, 'Doomsday', 'The lethal Reaper virus spreads throughout Britain—infecting millions and killing hundreds of thousands. Authorities brutally and successfully quarantine the country but, three decades later, the virus resurfaces in a major city. An elite group of specialists is urgently dispatched into the still-quarantined country to retrieve a cure by any means necessary. Shut off from the rest of the world, the unit must battle through a landscape that has become a waking nightmare.', '2008-03-14', 5.94, 'https://image.tmdb.org/t/p/w500/cKUmTyXgmhv8cMRCY9RYTKcAeTn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13210, 'The Dam Busters', 'The story of the conception of a new British weapon for smashing the German dams in the Ruhr industrial complex and the execution of the raid by 617 Squadron ''The Dam Busters''.', '1955-05-16', 6.91, 'https://image.tmdb.org/t/p/w500/bZKmBxzy5O5PjguhfMYgSaUxUmi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13440, 'The Truth About Charlie', 'Regina meets charming Joshua while vacationing in Martinique, as she contemplates ending her whirlwind marriage to enigmatic Charlie. Upon her return to Paris, she finds that both her apartment and her bank account have been emptied, and her husband has been murdered. Stuck in ever-increasing danger and with four men pursuing her, another stranger offers assistance - but who can she trust?', '2002-10-25', 4.86, 'https://image.tmdb.org/t/p/w500/kQ6SdbWStviMhTFt5tatjpGvRGV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13441, 'Roger Dodger', 'A smooth-talking ad executive attributes his remarkable success with women to his ability to manipulate their emotions from the moment he first meets them. When his teenage nephew drops in for a visit, he soon learns that his approach isn''t as foolproof as he thought when he attempts to teach the boy how to pick up women.', '2002-05-09', 6.11, 'https://image.tmdb.org/t/p/w500/cGfo8maMxoI1W9qA8KcYA7sw10s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13362, 'Taxi to the Dark Side', 'An in-depth look at the torture practices of the United States in Afghanistan, Iraq and Guantanamo Bay, focusing on an innocent taxi driver in Afghanistan who was tortured and killed in 2002.', '2008-01-18', 6.93, 'https://image.tmdb.org/t/p/w500/ttCOk1fQGvFJvPIJS7D8J2jOjpo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13493, 'College Road Trip', 'When an overachieving high school student decides to travel around the country to choose the perfect college, her overprotective cop father also decides to accompany her in order to keep her on the straight and narrow.', '2008-03-07', 5.42, 'https://image.tmdb.org/t/p/w500/8kcBMzhqW2eo058SmIKvbTbakYr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13476, 'Win a Date with Tad Hamilton!', 'A small-town girl wins a date with a Hollywood star through a contest. When the date goes better than expected, a love triangle forms between the girl, the celebrity, and the girl''s best friend.', '2004-01-23', 5.72, 'https://image.tmdb.org/t/p/w500/5kXxbKlIEgMv0t8hLtZ3hfKLmG7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13223, 'Gran Torino', 'Disgruntled Korean War veteran Walt Kowalski sets out to reform his neighbor, Thao Lor, a Hmong teenager who tried to steal Kowalski''s prized possession: a 1972 Gran Torino.', '2008-12-12', 7.99, 'https://image.tmdb.org/t/p/w500/zUybYvxWdAJy5hhYovsXtHSWI1l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13496, 'American Outlaws', 'When a Midwest town learns that a corrupt railroad baron has captured the deeds to their homesteads without their knowledge, a group of young ranchers join forces to take back what is rightfully theirs. They will become the object of the biggest manhunt in the history of the Old West and, as their fame grows, so will the legend of their leader, a young outlaw by the name of Jesse James.', '2001-08-17', 5.91, 'https://image.tmdb.org/t/p/w500/ov9PIn56yrwvrwOfvVTKplmV0S6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13497, 'Drumline', 'A talented street drummer from Harlem enrolls in a Southern university, expecting to lead its marching band''s drumline to victory. He initially flounders in his new world, before realizing that it takes more than talent to reach the top.', '2002-12-13', 6.95, 'https://image.tmdb.org/t/p/w500/zl7gdxYqKdFCioPT3DAkZR5DDUP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13220, 'Splinter', 'When their plans for a nature trip go awry, Polly and boyfriend Seth decide to check into a motel. On their way, they''re carjacked and kidnapped by low-rent crooks Dennis and Lacey, who take the victims and their SUV to a nearby gas station. Along the way, they encounter an increasingly terrifying horde of parasites, and if any of them intend to survive, they''ll have to outsmart the deadly organisms.', '2008-10-31', 6.19, 'https://image.tmdb.org/t/p/w500/tFNReQlU92jmN7uuR1HHLiFkEua.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13499, 'Yours, Mine & Ours', 'Admiral Frank Beardsley returns to New London to run the Coast Guard Academy, his last stop before a probable promotion to head the Guard. A widower with eight children, he runs a loving but tight ship, with charts and salutes. The kids long for a permanent home. Helen North is a free spirit, a designer whose ten children live in loving chaos, with occasional group hugs. Helen and Frank, high school sweethearts, reconnect at a reunion, and it''s love at first re-sighting. They marry on the spot. Then the problems start as two sets of kids, the free spirits and the disciplined preppies, must live together. The warring factions agree to work together to end the marriage.', '2005-11-23', 6.19, 'https://image.tmdb.org/t/p/w500/1SfsoUYXRRrfL31br8q4DlTYvKK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13503, 'Texas Rangers', 'Ten years after the Civil War has ended, the Governor of Texas asks Leander McNelly to form a company of Rangers to help uphold the law along the Mexican border. With a few veterans of the war, most of the recruits are young men who have little or no experience with guns or policing crime.', '2001-11-30', 5.94, 'https://image.tmdb.org/t/p/w500/69tMHlxiCYlYKGZm1aPH1u7hY88.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13498, 'Man of the House', 'Texas Ranger Roland Sharp is assigned to protect the only witnesses to the murder of a key figure in the prosecution of a drug kingpin -- a group of University of Texas cheerleaders. Sharp must now go undercover as an assistant cheerleading coach and move in with the young women.', '2005-02-25', 5.80, 'https://image.tmdb.org/t/p/w500/anBhlqCABytNvybE2Xr3tvsCOTp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13465, 'The Adventures of Ichabod and Mr. Toad', 'The Wind in the Willows: Concise version of Kenneth Grahame''s story of the same name. J. Thaddeus Toad, owner of Toad Hall, is prone to fads, such as the newfangled motor car. This desire for the very latest lands him in much trouble with the wrong crowd, and it is up to his friends, Mole, Rat and Badger to save him from himself. - The Legend of Sleepy Hollow: Retelling of Washington Irving''s story set in a tiny New England town. Ichabod Crane, the new schoolmaster, falls for the town beauty, Katrina Van Tassel, and the town Bully Brom Bones decides that he is a little too successful and needs "convincing" that Katrina is not for him.', '1949-10-05', 6.51, 'https://image.tmdb.org/t/p/w500/o6GfVkgPaaHJnXNywDLpHJII2tW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13505, 'The Perfect Score', 'Six high school seniors decide to break into the Princeton Testing Center so they can steal the answers to their upcoming SAT tests and all get perfect scores.', '2004-01-30', 5.84, 'https://image.tmdb.org/t/p/w500/xflTliVBvCztaLzTJx9luHnSqwD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13508, 'Who Killed the Electric Car?', 'In 1996, electric cars began to appear on roads all over California. They were quiet and fast, produced no exhaust, and ran without gasoline... Ten years later, these cars were destroyed.', '2006-08-04', 7.25, 'https://image.tmdb.org/t/p/w500/uMamC9o5zNU9wn8fyuAo2gUCMiD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13222, 'The Devil and Daniel Johnston', 'This 2005 documentary film chronicles the life of Daniel Johnston, a manic-depressive genius singer/songwriter/artist, from childhood up to the present, with an emphasis on his mental illness and how it manifested itself in demonic self-obsession.', '2006-03-31', 7.67, 'https://image.tmdb.org/t/p/w500/7c5FUlodgZl52tMlpw2G64kqttt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13510, 'Eden Lake', 'When a young couple goes to a remote wooded lake for a romantic getaway, their quiet weekend is shattered by an aggressive group of local kids. Rowdiness quickly turns to rage as the teens terrorize the couple in unimaginable ways, and a weekend outing becomes a bloody battle for survival.', '2008-09-12', 6.83, 'https://image.tmdb.org/t/p/w500/tOg6ElTe1mJwaCFN0172U4oso22.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13509, 'The Monster Squad', 'Count Dracula returns to the world of humans accompanied by Frankenstein''s Monster, the Wolfman, the Mummy, and the Gillman. The uglies are in search of a powerful amulet that will grant them the ability to rule the world. A group of horror-loving heroes are the only ones daring to stand in their way.', '1987-08-14', 6.72, 'https://image.tmdb.org/t/p/w500/8EVuqCcqFzQvc7X8E3fx3w4B5Td.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13511, 'Rawhead Rex', 'Ireland will never be the same after Rawhead Rex, a particularly nasty demon, is released from his underground prison by an unwitting farmer. The film follows Rex''s cross country rampage, while a man struggles to stop it.', '1986-10-01', 5.29, 'https://image.tmdb.org/t/p/w500/vIEaIVlV5XRIUVoaptsymIexaL2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13514, 'Last Hurrah for Chivalry', 'Kao has purchased a new wife, but an enemy has paid her more money to kill him. Kao must recruit a pair of swordsmen to help defend himself and his family from his ruthless enemy. But Kao has his dark side as well.', '1979-11-22', 7.06, 'https://image.tmdb.org/t/p/w500/uv8gmLKluvZBEnKI4cRnQ7r4iKs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13517, 'The Ugly Duckling and Me!', 'The Hans Christian Anderson tale gets a new treatment, this time with a rat trying to exploit the talents of a little ugly duckling for profit.', '2006-09-10', 5.46, 'https://image.tmdb.org/t/p/w500/RVAn63xJZARpMy8wGAA2LSF8DH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13515, 'Mirrors', 'An ex-cop and his family are the target of an evil force that is using mirrors as a gateway into their home.', '2008-08-14', 6.31, 'https://image.tmdb.org/t/p/w500/bt5a4ThyLpLTsia2e2ZTLzQjXO0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13523, 'Sex Drive', 'A high school senior drives cross-country with his best friends to hook up with a babe he met online.', '2008-10-16', 6.40, 'https://image.tmdb.org/t/p/w500/aO4swvDjqW635lesjYbytrEhBsn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13528, 'Gaslight', 'A newlywed fears she''s going mad when strange things start happening at the family mansion.', '1944-05-04', 7.50, 'https://image.tmdb.org/t/p/w500/gXKszCl5Q1KrgWRWpPcqn94CP58.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13446, 'Withnail & I', 'Two out-of-work actors -- the anxious, luckless Marwood and his acerbic, alcoholic friend, Withnail -- spend their days drifting between their squalid flat, the unemployment office and the pub. When they take a holiday "by mistake" at the country house of Withnail''s flamboyantly gay uncle, Monty, they encounter the unpleasant side of the English countryside: tedium, terrifying locals and torrential rain.', '1987-06-19', 7.22, 'https://image.tmdb.org/t/p/w500/i18cIp8A10A2JgByrfA9oIC9299.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13529, 'Electroma', 'Two robots embark on a quest to become human.', '2006-05-21', 6.73, 'https://image.tmdb.org/t/p/w500/m60OOcOVzniybIuVxzsMORMZNME.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13531, 'Empire Records', 'The employees of an independent music store learn about each other as they try to stop the store from being absorbed by a large chain.', '1995-09-22', 6.63, 'https://image.tmdb.org/t/p/w500/qKP7hVdjAAvRvbF3GBCbzi5LzMf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13533, 'Free Enterprise', 'Young filmmakers trying to hawk a movie titled "Bradykillers" about a serial killer who goes after victims Marcia, Jan, and Cindy meet their screen idol, William Shatner. The two young men, who idolize him and in their fantasies have seen him as a shadowy fairy godfather figure, are alarmed at the reality of the middle-aged non-Captain Kirk man that they meet.', '1998-06-04', 5.74, 'https://image.tmdb.org/t/p/w500/tBkKj6pUgxIW8DvNJEjsbnWgifP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13532, 'Fanboys', 'In 1999, Star Wars fanatics take a cross-country trip to George Lucas'' Skywalker Ranch so their dying friend can see a screening of The Phantom Menace before its release.', '2009-02-06', 6.14, 'https://image.tmdb.org/t/p/w500/fitksX4J3xfBjT38YgDUXOlBkHk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13537, 'Shattered Glass', 'Stephen Glass is a staff writer for the respected current events and policy magazine The New Republic and a freelance feature writer for publications such as Rolling Stone, Harper''s and George. By the mid-90s, Glass'' articles had turned him into one of the most sought-after young journalists in Washington, but a bizarre chain of events - chronicled in Buzz Bissinger''s September 1998 Vanity Fair article - suddenly stopped his career in its tracks.', '2003-11-14', 6.98, 'https://image.tmdb.org/t/p/w500/bIFJ49tk79hiFr9Z6bF6QapTg66.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13536, 'City by the Sea', 'Vincent LaMarca is a dedicated and well-respected New York City police detective who has gone to great lengths to distance himself from his past, but then makes the terrible discovery that his own son has fallen into a life of crime.', '2002-09-06', 5.80, 'https://image.tmdb.org/t/p/w500/vpjKtnE5SGTfmdw4YtJsnrfFJs0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13539, 'Here on Earth', 'Three lives of three young people intersect over the course of one summer. A rich student and a young working-class man accidentally destroy a diner when their impromptu road race takes a disastrous turn. Ordered by a judge to spend the summer repairing the building, they find themselves becoming rivals for the affections of the owner''s daughter.', '2000-03-24', 5.90, 'https://image.tmdb.org/t/p/w500/shvubL3pIrCyEK22ZHrx00oNtCY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13549, 'Burnt Offerings', 'A family moves into a large old mansion in the countryside which seems to have a mysterious and sinister power over its new residents.', '1976-10-18', 6.48, 'https://image.tmdb.org/t/p/w500/2ipG69lXOjGMX7F7qxJQzUoiUsd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13552, 'The Doom Generation', 'Jordan White and Amy Blue, two troubled teens, pick up an adolescent drifter, Xavier Red. Together, the threesome embarks on a sex- and violence-filled journey through a United States of psychos and quickie marts.', '1995-10-20', 6.51, 'https://image.tmdb.org/t/p/w500/tLfp9fHjydH6wzxukch5PWclga.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13550, 'The Changeling', 'After a tragic event happens, composer John Russell moves to Seattle to try to overcome it and build a new and peaceful life in a lonely big house that has been uninhabited for many years. But, soon after, the obscure history of such an old mansion and his own past begin to haunt him.', '1980-03-28', 6.98, 'https://image.tmdb.org/t/p/w500/z4nTYj3JZ5jWAhDgrmEhW2GRAzb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13554, 'Eight Men Out', 'Buck Weaver and Hap Felsch are young idealistic players on the Chicago White Sox, a pennant-winning team owned by Charles Comiskey -  a penny-pinching, hands-on manager who underpays his players and treats them with disdain. And when gamblers and hustlers discover that Comiskey''s demoralized players are ripe for a money-making scheme, one by one the team members agree to throw the World Series. But when the White Sox are defeated, a couple of sports writers smell a fix and a national scandal explodes, ripping the cover off America''s favorite pastime.', '1988-09-02', 6.83, 'https://image.tmdb.org/t/p/w500/9nh0w2C9h9KfJb0OsVg65O65b5s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13562, 'My Man Godfrey', 'Fifth Avenue socialite Irene Bullock needs a "forgotten man" to win a scavenger hunt, and no one is more forgotten than Godfrey Park, who resides in a dump by the East River. Irene hires Godfrey as a servant for her riotously unhinged family, to the chagrin of her spoiled sister, Cornelia, who tries her best to get Godfrey fired. As Irene falls for her new butler, Godfrey turns the tables and teaches the frivolous Bullocks a lesson or two.', '1936-09-02', 7.59, 'https://image.tmdb.org/t/p/w500/wtfOW7fIxBZWY78rvUoPpWhMSiR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13567, 'Sleepaway Camp', 'Years after a terrible boating accident, Angela is sent to Camp Arawak where a series of bizarre and violent "accidents" begin to claim the lives of various campers.', '1983-11-18', 6.29, 'https://image.tmdb.org/t/p/w500/icRAuGsmXl62Ns0qrTuo9uiP6U1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13560, 'Max', 'In 1918, a young, disillusioned Adolf Hitler strikes up a friendship with a Jewish art dealer while weighing a life of passion for art vs. talent at politics', '2002-09-10', 6.15, 'https://image.tmdb.org/t/p/w500/a2zqJWEAqSyPS7VZP0biBdJIpHn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13572, 'Twisted', 'Recently promoted and transferred to the homicide division, Inspector Jessica Shepard feels pressure to prove herself -- and what better way than by solving San Francisco''s latest murder? However, as Shepard and her partner, Mike Delmarco, soon discover, the victim shared a romantic connection to her. As more of Shepard''s ex-lovers turn up dead, her mind starts to become unstable, and she begins to wonder if she could be the very killer she''s trying to track down.', '2004-02-27', 5.58, 'https://image.tmdb.org/t/p/w500/nfdfU9tYsEnjlFGoY2HabFMdHLi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13580, 'The Spy Who Came In from the Cold', 'British agent Alec Leamas refuses to come in from the Cold War during the 1960s, choosing to face another mission, which may prove to be his final one.', '1965-12-16', 7.10, 'https://image.tmdb.org/t/p/w500/lN3PWv6cW22mqXDcgGZgK1Aa2gh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13573, 'The United States of Leland', 'A withdrawn young man, Leland Fitzgerald is imprisoned for the murder of a mentally disabled boy, who also happened to be the brother of his girlfriend, Becky. As the community struggles to deal with the killing, Pearl Madison, a teacher at the prison, decides to write about Leland''s case. Meanwhile, others affected by the murder, including Becky and her sister, Julie, must contend with their own problems.', '2003-05-15', 6.50, 'https://image.tmdb.org/t/p/w500/60B0kXNSy3isCSZtM3vl2GWeKdE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13581, 'Dead of Night', 'An architect, visiting an English country house, realizes the other guests are familiar from his recurring nightmare. When they share their tales of the supernatural, he is filled with a growing dread.', '1945-09-09', 7.20, 'https://image.tmdb.org/t/p/w500/6bpPtLRMbfSkH0k6sLdJRIcEeq3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13555, 'The Funhouse', 'Rebellious teen Amy defies her parents by going to a trashy carnival that has pulled into town. In tow are her boyfriend, Buzz, and their friends Liz  and Richie. Thinking it would be fun to spend the night in the campy "Funhouse" horror ride, the teens witness a murder by a deformed worker wearing a mask. Locked in, Amy and her friends must evade the murderous carnival workers and escape before it leaves town the next day.', '1981-03-13', 5.84, 'https://image.tmdb.org/t/p/w500/9eFgNrkTbXk1TBPuzxdOEjutNoC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13589, 'Eddie Izzard: Dress to Kill', 'Eddie Izzard takes her show to San Francisco to give a brief history of pagan and Christian religions, the building of Stonehenge, the birth of the Church of England and of Western empires, and the need for a European dream.', '1999-06-13', 7.80, 'https://image.tmdb.org/t/p/w500/mwvsA31Ei0vYaOPRjF8FBL9For7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13477, 'When in Rome', 'Disillusioned with romance, Beth, an ambitious New Yorker, travels to Rome for her sister''s wedding, where she plucks magic coins from a special fountain of love. The coins attract unwanted attention from an assortment of odd yet ardent suitors:  a sausage merchant, a street magician, an artist, and a male model. But when the best man from the wedding, persistent reporter Nick, throws his hat in the ring, Beth wonders if his love is the real thing.', '2010-01-29', 5.91, 'https://image.tmdb.org/t/p/w500/pteIGpJpgh2aUh3jMqZnomB1rw1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13466, 'October Sky', 'The true story of Homer Hickam, a coal miner''s son who was inspired by the first Sputnik launch to take up rocketry against his father''s wishes.', '1999-02-19', 7.67, 'https://image.tmdb.org/t/p/w500/umWrXCIWdcYPf764ruvMRCpG3cA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13481, 'The Five Venoms', 'A dying master sends his last student to check up on five former pupils, who each know a special style of kung-fu.', '1978-08-12', 6.56, 'https://image.tmdb.org/t/p/w500/z446TqbbOb7emtN1S8iOrwTHz7Y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13364, 'Deliver Us from Evil', 'Documentary filmmaker Amy Berg investigates the life of 30-year pedophile Father Oliver O''Grady and exposes the corruption inside the Catholic Church that allowed him to abuse countless children. Victims'' stories and a disturbing interview with O''Grady offer a view into the troubled mind of the spiritual leader who moved from parish to parish gaining trust ... all the while betraying so many.', '2006-06-24', 7.14, 'https://image.tmdb.org/t/p/w500/4FSBT712p6OwawSqLCkloNSqMaM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13482, 'The Milagro Beanfield War', 'The accidental breakdown of an irrigation valve launches a hot confrontation between the mainly Latino farmers in a tiny New Mexico town and the real estate developers and politicians determined to acquire their land for a golf resort.', '1988-03-18', 6.58, 'https://image.tmdb.org/t/p/w500/rVLZuiNfKua7C2x3rGUiAR8wGEc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13475, 'Star Trek', 'The fate of the galaxy rests in the hands of bitter rivals. One, James Kirk, is a delinquent, thrill-seeking Iowa farm boy. The other, Spock, a Vulcan, was raised in a logic-based society that rejects all emotion. As fiery instinct clashes with calm reason, their unlikely but powerful partnership is the only thing capable of leading their crew through unimaginable danger, boldly going where no one has gone before. The human adventure has begun again.', '2009-05-06', 7.44, 'https://image.tmdb.org/t/p/w500/9vaRPXj44Q2meHgt3VVfQufiHOJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13485, 'Holiday Inn', 'Lovely Linda Mason has crooner Jim Hardy head over heels, but suave stepper Ted Hanover wants her for his new dance partner after fickle Lila Dixon gives him the brush. Jim''s supper club, Holiday Inn, is the setting for the chase by Hanover and his manager.', '1942-07-10', 7.06, 'https://image.tmdb.org/t/p/w500/7eZzwqLM1w1Mljg60rzB1zr27lu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13590, 'Eddie Izzard: Glorious', 'Eddie Izzard''s routine has a loose trajectory from the beginning of the Old Testament and the creation of the world in seven days to Revelations. Along the way, we learn of the search for a career, bad giraffes, Prince Philip''s gaffes, toilets in French campsites, the mysteries of hopscotch, becoming one''s Dad and tranny bashing.', '1997-11-17', 7.35, 'https://image.tmdb.org/t/p/w500/tSiyjmGJEWprHWPR8Eop1ML82gB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13365, '49 Up', '49 Up is the seventh film in a series of landmark documentaries that began 42 years ago when UK-based Granada''s World in Action team, inspired by the Jesuit maxim "Give me the child until he is seven and I will give you the man," interviewed a diverse group of seven-year-old children from all over England, asking them about their lives and their dreams for the future. Michael Apted, a researcher for the original film, has returned to interview the "children" every seven years since, at ages 14, 21, 28, 35, 42 and now again at age 49.In this latest chapter, more life-changing decisions are revealed, more shocking announcements made and more of the original group take part than ever before, speaking out on a variety of subjects including love, marriage, career, class and prejudice.', '2006-10-06', 7.40, 'https://image.tmdb.org/t/p/w500/AuS78iQMLMKRLKKVahtm8MnTTMh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13369, 'Empire', 'Big time drug dealer Victor Rosa is looking to get out of the game and sees his chance with a big deal with a new friend who happens to be a Wall St. stockbroker. Thinking this will be his chance to go out on top, Victor soon finds out that he''s been double crossed and his last option is to get revenge.', '2002-12-06', 6.21, 'https://image.tmdb.org/t/p/w500/m6XxaRLltWox4C9pykjUILrlGp9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13492, 'Frontier(s)', 'A gang of young thieves flee Paris during the violent aftermath of a political election, only to hole up at an Inn run by neo-Nazis.', '2007-07-01', 6.19, 'https://image.tmdb.org/t/p/w500/6GISAjE0XiSucmzXIhb1tdnV2yC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13666, 'The Wolf Man', 'After his brother''s death, Larry Talbot returns home to his father and the family estate. Events soon take a turn for the worse when Larry is bitten by a werewolf.', '1941-12-09', 7.00, 'https://image.tmdb.org/t/p/w500/vG8fu5syTtQLzK1hQXyi3ugOPNF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13667, 'Better Off Dead...', 'High school student Lane Meyer sinks into suicidal depression when his girlfriend dumps him for jock Roy Stalin, the high school ski racing champion. Meanwhile, he has to deal with his eccentric family, a tenacious paperboy and an obnoxious neighbor whose mother is hosting a beautiful French exchange student named Monique.', '1985-08-23', 6.59, 'https://image.tmdb.org/t/p/w500/pHmbSkpxdB7jXozrovEfacArtW0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13668, 'Catch and Release', 'For a grieving fiancée, learning to love again requires the help of her late love''s three best friends.', '2006-10-20', 5.93, 'https://image.tmdb.org/t/p/w500/mcGvcb65JdftAHxyhxd2dxCPNOa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13671, 'The Music Man', 'Traveling con artist Harold Hill targets the naïve residents of a small town in 1910s Iowa by posing as a boys'' bandleader to raise money before he can skip town.', '1962-06-19', 7.11, 'https://image.tmdb.org/t/p/w500/4yo6qaqVF1IThXMapo4yW9BRWjV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13672, 'JCVD', 'Between his tax problems and his legal battle with his wife for the custody of his daughter, these are hard times for the action movie star who finds that even Steven Seagal has pinched a role from him! This fictionalized version of Jean-Claude Van Damme returns to the country of his birth to seek the peace and tranquility he can no longer enjoy in the United States, but inadvertently gets involved in a bank robbery with hostages.', '2008-06-04', 6.59, 'https://image.tmdb.org/t/p/w500/hTvdsXH0jYmQgIbs1eJFM8DnOQg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13673, 'Christmas with the Kranks', 'When their only daughter Blair leaves the family nest, Luther and Nora Krank decide to book an island cruise to beat the yuletide blues and just skip the holidays. But their decision to boycott tradition has the whole neighborhood in an uproar, and when Blair calls on Christmas Eve to announce a surprise visit with her new fiancée, the Kranks have just twelve hours to perform a miracle and pull themselves and their neighbors together to throw the best celebration ever!', '2004-11-24', 6.16, 'https://image.tmdb.org/t/p/w500/q866vL3KhAjbkZH1enT7AoxmRHx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13675, 'Frosty the Snowman', 'A discarded silk top-hat becomes the focus of a struggle between a washed-up stage magician and a group of schoolchildren, after it magically brings a snowman to life. Realizing that newly-living Frosty will melt in spring unless he takes refuge in a colder climate, the magic snowman and Karen, a young girl whom he befriends, stow away on a freight train headed for the North Pole. Little do they know that the magician is following them, and he wants his hat back!', '1969-12-07', 6.94, 'https://image.tmdb.org/t/p/w500/gw7ie4W3iW8nefnZ4kuw8dgYNM2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13680, 'The Game Plan', 'Bachelor football star Joe Kingman seems to have it all. He is wealthy and carefree, and his team is on the way to capturing a championship. Suddenly, he is tackled by some unexpected news: He has a young daughter, the result of a last fling with his ex-wife. Joe must learn to balance his personal and professional lives with the needs of his child.', '2007-09-28', 6.51, 'https://image.tmdb.org/t/p/w500/fcLFvIqCUrhY96mkSmr3okxaMEw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13681, 'Places in the Heart', 'In 1935 rural Texas, recently widowed Edna Spaulding struggles to survive with two small children, a farm to run, and very little money in the bank - not to mention a deadly tornado and the unwelcome presence of the Ku Klux Klan. Edna is aided by her beautician sister, Margaret; a blind boarder, Mr. Will; and a would-be thief, Moze, who decides to teach Edna how to plant and harvest cotton.', '1984-09-11', 7.20, 'https://image.tmdb.org/t/p/w500/bmWg3uVn700inqOiadxeFTmiqmV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13370, 'A Mighty Wind', 'Three eclectic, never-quite-famous folk bands come together for the first time in decades following the death of their manager to put on an reunion concert in his honor, at the request of his son.', '2003-04-16', 6.78, 'https://image.tmdb.org/t/p/w500/5wUYwAD75BxtJ0Mp4da6XzHIFex.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13689, 'Peaceful Warrior', 'A chance encounter with a stranger changes the life of a college gymnast.', '2006-03-30', 7.50, 'https://image.tmdb.org/t/p/w500/r4VQCZe3aSo7TmmsxcyLqaoMR1l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13691, 'Piglet''s Big Movie', 'When the gang from the Hundred Acre Wood begin a honey harvest, young Piglet is excluded and told that he is too small to help. Feeling inferior, Piglet disappears and his pals Eeyore, Rabbit, Tigger, Roo and Winnie the Pooh must use Piglet''s scrapbook as a map to find him. In the process they discover that this very small animal has been a big hero in a lot of ways.', '2003-03-16', 6.68, 'https://image.tmdb.org/t/p/w500/cytspPjtacOInHroA6h2dIekDrp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13597, 'Labyrinth', 'Frustrated with babysitting on yet another weekend night, Sarah, a teenager with an active imagination, summons the Goblins to take her baby stepbrother away. When little Toby actually disappears, Sarah must follow him into a fantastical world to rescue him from the Goblin King. Guarding his castle is the labyrinth itself, a twisted maze of deception, populated with outrageous characters and unknown dangers.', '1986-06-27', 7.29, 'https://image.tmdb.org/t/p/w500/pejayhTVBEL4w8YKSfrhOjjWVlH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13696, 'Angels with Dirty Faces', 'Childhood chums Rocky Sullivan and Jerry Connelly grow up on opposite sides of the fence: Rocky matures into a prominent gangster, while Jerry becomes a priest, tending to the needs of his old tenement neighborhood.', '1938-11-26', 7.53, 'https://image.tmdb.org/t/p/w500/k23E4UAcow8eczLRmVCMdukL4Mx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13697, 'Grand Canyon', 'Grand Canyon revolved around six residents from different backgrounds whose lives intertwine in modern-day Los Angeles. At the center of the film is the unlikely friendship of two men from different races and classes brought together when one finds himself in jeopardy in the other''s rough neighborhood.', '1991-12-25', 6.40, 'https://image.tmdb.org/t/p/w500/gpqLukoUXAXkyMZ0jPSuAbWf5Nx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13483, 'Awake', 'While undergoing heart surgery, a man experiences a phenomenon called ‘anesthetic awareness’, which leaves him awake but paralyzed throughout the operation. As various obstacles present themselves, his wife must make life-altering decisions while wrestling with her own personal drama.', '2007-11-28', 6.59, 'https://image.tmdb.org/t/p/w500/xqooV6lR1Kdx4Q52Sim0aGbDTYP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13698, 'Gung Ho', 'When a western Pennsylvania auto plant is acquired by a Japanese company, brokering auto worker Hunt Stevenson faces the tricky challenge of mediating the assimilation of two clashing corporate cultures. At one end is the Japanese plant manager and the sycophant who is angling for his position. At the other, a number of disgruntled long-time union members struggle with the new exigencies of Japanese quality control.', '1986-03-14', 6.09, 'https://image.tmdb.org/t/p/w500/sxnlQEb8dugTFK2KyFrq3iv3bHn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13701, 'Immortal Beloved', 'A chronicle of the life of infamous classical composer Ludwig van Beethoven and his painful struggle with hearing loss. Following Beethoven''s death in 1827, his assistant, Schindler, searches for an elusive woman referred to in the composer''s love letters as "immortal beloved." As Schindler solves the mystery, a series of flashbacks reveal Beethoven''s transformation from passionate young man to troubled musical genius.', '1994-12-16', 7.11, 'https://image.tmdb.org/t/p/w500/lkqz2R5pjXeDaiIjR3Z6JTGjtg6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13704, 'License to Drive', 'Teenager Les Anderson thinks his life can''t get any worse after he flunks his driver''s exam, but he''s wrong. Even though he didn''t receive his license, Les refuses to break his date with the cool Mercedes Lane, and he decides to lift his family''s prize luxury car for the occasion. Unfortunately, Mercedes sneaks some booze along and passes out drunk, and a confused Les makes the bad decision of enlisting his rebellious friend, Dean, to help.', '1988-07-06', 6.65, 'https://image.tmdb.org/t/p/w500/cSGV9uXOKxu8j9mj6NmTix4GLFa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13751, 'Akeelah and the Bee', '11-year-old Akeelah Anderson has a way with words. After winning her schoolwide spelling bee, she decides to enter the competition, despite her classmates'' derision and the antipathy of her mother Tanya. Thanks to the efforts of her teacher Dr. Larabee, she reaches the finals. As she gets to know her fellow competitors, Akeelah realizes that coming first isn''t everything in life.', '2006-04-28', 7.02, 'https://image.tmdb.org/t/p/w500/tLejxaLJu8Qh5F2VKacWniMSZ3v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13596, 'My Best Friend''s Girl', 'Lovestruck Dustin is dating Alexis, his ideal girlfriend, but when she dumps him for coming on too strong, Dustin takes drastic measures to win her back. He asks his best friend Tank to take her on the worst rebound date imaginable - his side job - so that she will come running back to him, and Tank reluctantly agrees. However, Alexis is more than a match for Tank''s shock tactics and he begins to really fall for her, leaving him torn between loyalty to Dustin and his growing attraction toward Alexis.', '2008-09-19', 5.64, 'https://image.tmdb.org/t/p/w500/4Zn149rIsfIwBZZwIwuryRzVbon.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13703, 'Less Than Zero', 'A college freshman returns to Los Angeles for Christmas at his ex-girlfriend''s request, but discovers that his former best friend has an out-of-control drug habit.', '1987-11-06', 6.41, 'https://image.tmdb.org/t/p/w500/8pFMuyJJwJLqOJ3Ljq3M5BFGbTF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13632, 'MacGyver: Trail to Doomsday', 'A close friend of MacGyver is murdered. In searching for a reason for this assassination MacGyver discovers a secret nuclear weapons plant right in the center of Britain.', '1994-11-24', 6.00, 'https://image.tmdb.org/t/p/w500/goM1nyiXVHIyRwFyM7uXMzmrr0v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13752, 'Max Manus: Man of War', 'Max Manus is a Norwegian 2008 biographic war film based on the real events of the life of resistance fighter Max Manus (1914–96), after his contribution in the Winter War against the Soviet Union. The story follows Manus through the outbreak of World War II in Norway until peacetime in 1945.', '2008-12-18', 7.10, 'https://image.tmdb.org/t/p/w500/v9Z7CUGW1Q5L8GdGH3rY5SkU72L.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13600, 'City of Ember', 'For generations, the people of the City of Ember have flourished in an amazing world of glittering lights. But Ember''s once powerful generator is failing and the great lamps that illuminate the city are starting to flicker. Now, two teenagers, in a race against time, must search Ember for clues that will unlock the ancient mystery of the city''s existence, before the the lights go out forever.', '2008-10-07', 6.38, 'https://image.tmdb.org/t/p/w500/xHYxFNsl8KuT4tHai8d1Y5gJI0F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13595, 'Airheads', 'The Lone Rangers have heavy-metal dreams and a single demo tape they can''t get anyone to play. The solution: Hijack an FM rock radio station and hold the deejays hostage until they agree to broadcast the band''s tape.', '1994-08-05', 6.21, 'https://image.tmdb.org/t/p/w500/4xPG8pPMyeoec48gKWbbC85EC8j.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13715, 'At Close Range', 'Brad Whitewood Jr. lives in rural Pennsylvania and has few prospects. Against his mother''s wishes, he seeks out his estranged father, the head of a gang of thieves in a nearby town. Though his new girlfriend supports his criminal ambitions, Brad Jr. soon learns that his father is a dangerous man.', '1986-04-18', 6.81, 'https://image.tmdb.org/t/p/w500/bOkXqMmLowHBZY9lptWi3ljOXx4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13636, 'Bigger Stronger Faster*', 'In America, we define ourselves in the superlative: we are the biggest, strongest, fastest country in the world. Is it any wonder that so many of our heroes are on performance enhancing drugs? Director Christopher Bell explores America''s win-at-all-cost culture by examining how his two brothers became members of the steroid-subculture in an effort to realize their American dream.', '2008-05-30', 6.80, 'https://image.tmdb.org/t/p/w500/4sZNQ7OQgkJj7kLFx4su21yEHTB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13766, 'SpaceCamp', 'Andie Bergstrom, an astronaut eagerly awaiting her first trip to space, runs a summer camp for teenagers with her NASA-employed husband, Zach. One night during an engine test, Andie and four teenage campers are accidentally shot into space. Together, the group -- which includes Kathryn, a pilot-in-training, and Tish, a ditz with a perfect memory -- must work together to operate the spacecraft and return home.', '1986-06-06', 5.90, 'https://image.tmdb.org/t/p/w500/wWw2yJHQxqATtXw4roPDVuoE9Xs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13767, 'The Santa Clause 3: The Escape Clause', 'Now that Santa and Mrs. Claus have the North Pole running smoothly, the Counsel of Legendary Figures has called an emergency meeting on Christmas Eve! The evil Jack Frost has been making trouble, looking to take over the holiday! So he launches a plan to sabotage the toy factory and compel Scott to invoke the little-known Escape Clause and wish he''d never become Santa.', '2006-11-02', 5.57, 'https://image.tmdb.org/t/p/w500/pvaWMSRzRwtcxyHKNLX6phiQp8d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13768, 'Tuck Everlasting', 'Teenager Winnie Foster is growing up in a small rural town in 1914 with her loving but overprotective parents, but Winnie longs for a life of greater freedom and adventure.', '2002-10-11', 6.69, 'https://image.tmdb.org/t/p/w500/9BXAC4uTHuD37hpiGOmhetqNgnO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13754, 'Tekkonkinkreet', 'Two penniless orphans, Black and White, struggle to survive on the mean streets of Treasure Town. When a megacorporation threatens to tear down the town to build an amusement park, Black and White engage in the fight of their life.', '2006-12-23', 7.38, 'https://image.tmdb.org/t/p/w500/e2x1YDuZPpQiaQS25Ego7xMZYOI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13771, 'Venus', 'Maurice is an aging veteran actor who becomes taken with Jessie, the grandniece of his closest friend. When Maurice tries to soften the petulant and provincial young girl with the benefit of his wisdom and London culture, their give-and-take surprises both Maurice and Jessie as they discover what they don''t know about themselves.', '2006-09-02', 6.64, 'https://image.tmdb.org/t/p/w500/pY1B5ipgUkxtBN3fkJWuKAeFL2G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13776, 'Diner', 'Set in 1959, Diner shows how five young men resist their adulthood and seek refuge in their beloved Diner. The mundane, childish, and titillating details of their lives are shared. But the golden moments pass, and the men shoulder their responsibilities, leaving the Diner behind.', '1982-03-05', 6.83, 'https://image.tmdb.org/t/p/w500/2vKIdZ6JkFIzcQeaHg3xtdvOyRO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13778, 'Dickie Roberts: Former Child Star', 'TV child star of the ''70s, Dickie Roberts is now 35 and parking cars. Craving to regain the spotlight, he auditions for a role of a normal guy, but the director quickly sees he is anything but normal. Desperate to win the part, Dickie hires a family to help him replay his childhood and assume the identity of an average, everyday loser.', '2003-09-04', 5.12, 'https://image.tmdb.org/t/p/w500/eyn1WbZmUUIXU8QoorKWJTQ1iLg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13785, 'Best in Show', 'The tension is palpable, the excitement is mounting and the heady scent of competition is in the air as hundreds of eager contestants from across America prepare to take part in what is undoubtedly one of the greatest events of their lives -- the Mayflower Dog Show. The canine contestants and their owners are as wondrously diverse as the great country that has bred them.', '2000-09-29', 6.88, 'https://image.tmdb.org/t/p/w500/2SqHjWWqfJjQE6zLCbQR9HMla4Q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13783, 'Breaker Morant', 'During the Boer War, three Australian lieutenants are on trial for shooting Boer prisoners. Though they acted under orders, they are being used as scapegoats by the General Staff, who hopes to distance themselves from the irregular practices of the war. The trial does not progress as smoothly as expected by the General Staff, as the defence puts up a strong fight in the courtroom.', '1980-06-11', 7.10, 'https://image.tmdb.org/t/p/w500/Nr46BDNjBtz3s0wRvm84eK3PXl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13787, 'Holy Smoke', 'While on a journey of discovery in exotic India, beautiful young Ruth Barron falls under the influence of a charismatic religious guru. Her desperate parents then hire PJ Waters, a macho cult de-programmer who confronts Ruth in a remote desert hideaway. But PJ quickly learns that he''s met his match in the sexy, intelligent and iron-willed Ruth.', '1999-09-04', 5.69, 'https://image.tmdb.org/t/p/w500/xcovgjKOnNsJTz8uADbCVF98wS1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13791, 'How to Kill Your Neighbor''s Dog', 'The story of Peter McGowan, a chain-smoking, impotent, insomniac playwright who lives in Los Angeles. Once very successful, he is now in the tenth year of a decade-long string of production failures. He finds himself bonding with a new neighbor''s lonely young daughter who has mild cerebral palsy; and during one of his middle-of-the-night strolls, he encounters his oddball doppelgänger.', '2002-02-22', 5.90, 'https://image.tmdb.org/t/p/w500/6SnhJrYar2gedIdyIqlLwagBmCr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13794, 'Africa: The Serengeti', 'Africa the Serengeti takes you on an extraordinary journey to view a spectacle few humans have ever witnessed: The Great Migration. Journey with more than two million wildebeests, zebras and antelopes as in their annual 500 mile trek across the Serengeti plains.', '1994-03-31', 7.00, 'https://image.tmdb.org/t/p/w500/cVcLCA0ZUMaVzRn7qwxrLXyurI1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13795, 'Alaska: Spirit of the Wild', 'Alaska... Here, in this vast and spectacularly beautiful land teeming with abundant wildlife, discover the "Spirit of the Wild." Experience it in the explosive calving of glaciers, the celestial fires of the Aurora Borealis. Witness it in the thundering stampede of caribou, the beauty of the polar bear and the stealthful, deadly hunt of the wolf pack.', '1998-09-03', 6.83, 'https://image.tmdb.org/t/p/w500/bVvmVUDs2rJgJ46j7Ja66CDQD5j.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13804, 'Fast & Furious', 'When a crime brings them back to L.A., fugitive ex-con Dom Toretto reignites his feud with agent Brian O''Conner. But as they are forced to confront a shared enemy, Dom and Brian must give in to an uncertain new trust if they hope to outmaneuver him. And the two men will find the best way to get revenge: push the limits of what''s possible behind the wheel.', '2009-04-02', 6.69, 'https://image.tmdb.org/t/p/w500/lUtVoRukW7WNtUySwd8hWlByBds.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13808, 'Strictly Sexual', 'Two successful women, sick and tired of dating and relationships, decide to keep two young men in their pool house for strictly sexual purposes.', '2008-12-02', 6.12, 'https://image.tmdb.org/t/p/w500/niIJVD4CPvGg05AWNbLFoAcQSp4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13811, 'Knowing', 'A teacher opens a time capsule that has been dug up at his son''s elementary school; in it are some chilling predictions -- some that have already occurred and others that are about to -- that lead him to believe his family plays a role in the events that are about to unfold.', '2009-03-19', 6.26, 'https://image.tmdb.org/t/p/w500/OG0mxQt4YaNIWiz8EKJSHe9lPh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13813, 'Defiance', 'Based on a true story, during World War II, four Jewish brothers escape their Nazi-occupied homeland of West Belarus in Poland and join the Soviet partisans to combat the Nazis. The brothers begin the rescue of roughly 1,200 Jews still trapped in the ghettos of Poland.', '2008-12-31', 6.84, 'https://image.tmdb.org/t/p/w500/kEF847cC9yAkgoeEZPQwnF08p6p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13635, 'Mesrine: Killer Instinct', 'Jacques Mesrine, a loyal son and dedicated soldier, is back home and living with his parents after serving in the Algerian War. Soon he is seduced by the neon glamour of sixties Paris and the easy money it presents. Mentored by Guido, Mesrine turns his back on middle class law-abiding and soon moves swiftly up the criminal ladder.', '2008-10-22', 7.30, 'https://image.tmdb.org/t/p/w500/zCyuiyIhbhgEOZde81qTgXbO0pw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13815, 'Fresh', 'Death and violence anger twelve year old drug courier Fresh, who sets his rival employers against each other.', '1994-06-15', 7.18, 'https://image.tmdb.org/t/p/w500/uXRIIUzjDZZdWR2cUzPJ9eAqaHv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13640, 'Superman: Doomsday', 'When LexCorp accidentally unleashes a murderous creature, Superman meets his greatest challenge as a champion. Based on the "The Death of Superman" storyline that appeared in DC Comics'' publications in the 1990s.', '2007-09-18', 6.73, 'https://image.tmdb.org/t/p/w500/itvuWm7DFWWzWgW0xgiaKzzWszP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13816, 'Idlewild', 'A reticent piano player Percival, along with Rooster, his flamboyant lead performer and manager, struggle to keep their speakeasy, in the Prohibition-era South, out of the hands of gangsters who want to take it over.', '2006-08-25', 5.60, 'https://image.tmdb.org/t/p/w500/d1KW3hrGAJCsvs2GC2MCkYebD2u.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13819, 'Laurel Canyon', 'When an uptight young man and his fiancée move into his libertine mother''s house, the resulting clash of life attitudes shakes everyone up.', '2003-03-07', 5.95, 'https://image.tmdb.org/t/p/w500/z7knajZv3nxqN0o2Jq8kIOkpgu6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13821, 'The Boys', 'Brett Sprague is a violent and psychopathic man, who is released on parole after serving a sentence for assault. As he returns to his family house and we watch him and his brothers, Stevie and Glenn, for the next 24 hours, it becomes clear this day will not end well.', '1998-05-07', 6.57, 'https://image.tmdb.org/t/p/w500/jLyfVrwm5028RPhx5oXmJv01uSr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13641, 'The Air I Breathe', 'A gambler’s bet spiraling into chaos, a gangster''s prophetic visions, a pop star’s dark entanglement, a doctor’s desperate race against time to rescue his beloved... Four interconnected stories reveal life unfolding through four emotional pillars — joy, passion, grief, and love.', '2007-02-07', 6.29, 'https://image.tmdb.org/t/p/w500/hx89b5sinoXmkMNyK1PUgwjWQX4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13685, 'Bottle Rocket', 'Upon his release from a mental hospital following a nervous breakdown, the directionless Anthony joins his friend Dignan, who seems far less sane than the former. Dignan has hatched a harebrained scheme for an as-yet-unspecified crime spree that somehow involves his former boss, the (supposedly) legendary Mr. Henry.', '1996-02-21', 6.70, 'https://image.tmdb.org/t/p/w500/6E7mJ5wpzTFbYFbJvTzzZ8Til9C.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13824, 'Superstar', 'Orphan Mary Katherine Gallagher, an ugly duckling at St. Monica High School, has a dream: to be kissed soulfully. She decides she can realize this dream if she becomes a superstar, so her prayers, her fantasies and her conversations with her only friend focus on achieving super-stardom.', '1999-10-08', 5.29, 'https://image.tmdb.org/t/p/w500/vfBUCPe6wgt3SwNP7dKlqh8xeyO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13836, 'Race to Witch Mountain', 'A taxi driver gets more than he bargained for when he picks up two teen runaways. Not only does the pair possess supernatural powers, but they''re also trying desperately to escape people who have made them their targets.', '2009-03-13', 5.79, 'https://image.tmdb.org/t/p/w500/5RBZsOKMMxnp8L6UmOiylKOw4yo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13848, 'Stuck', 'A young woman commits a hit-and-run, then finds her fate tied to her victim.', '2007-05-21', 6.19, 'https://image.tmdb.org/t/p/w500/dEJCk1vTOaldD8hzOYY96AdFdr6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13849, 'The Cottage', 'In a remote part of the countryside, a bungled kidnapping turns into a living nightmare for four central characters when they cross paths with a psychopathic farmer and all hell breaks loose.', '2008-02-07', 5.94, 'https://image.tmdb.org/t/p/w500/fFmU7cQAWVAeBpSfDRRauKgtKDD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13762, 'The Private Eyes', 'The lord and lady of a capacious manor are killed, and the lord''s ghost seems to have returned to knock off the staff one by one, causing Inspector Winship and Dr. Tart to investigate the wacky house and its inhabitants.', '1980-04-17', 6.10, 'https://image.tmdb.org/t/p/w500/sIG0xrld1OW1HavH03KACNTxz0w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13637, 'Sukiyaki Western Django', 'A nameless gunfighter arrives in a town ripped apart by rival gangs and, though courted by both to join, chooses his own path.', '2007-09-15', 6.17, 'https://image.tmdb.org/t/p/w500/tnB7lpBknu510z9ATWbfpamPKZa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13805, 'Disaster Movie', 'Over the course of one evening, an unsuspecting group of twenty-somethings find themselves bombarded by a series of natural disasters and catastrophic events.', '2008-08-29', 3.19, 'https://image.tmdb.org/t/p/w500/3J8XKUfhJiNzwobUZVtizXYPe8b.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13647, 'The Invincible Iron Man', 'When a cocky industrialist''s efforts to raise an ancient Chinese temple leads him to be seriously wounded and captured by enemy forces, he must use his ideas for a revolutionary power armor in order to fight back as a superhero.', '2007-01-23', 6.13, 'https://image.tmdb.org/t/p/w500/eebNTSRa5Hh5skPKGdGJIJpo9Ls.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13643, 'George Carlin: It''s Bad for Ya!', 'It''s Bad For Ya, Carlin''s Emmy nominated 14th and final HBO special from March of 2008 features Carlin''s noted irreverent and unapologetic observations on topics ranging from death, religion, bureaucracy, patriotism, overprotected children and big business to the pungent examinations of modern language and the decrepit state of the American culture.', '2008-03-01', 7.89, 'https://image.tmdb.org/t/p/w500/m9fIvowFHpVjGn5OzFKudp2XJLD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13809, 'RocknRolla', 'When a Russian mobster sets up a real estate scam that generates millions of pounds, various members of London''s criminal underworld pursue their share of the fortune. Various shady characters, including Mr One-Two, Stella the accountant, and Johnny Quid, a druggie rock-star, try to claim their slice.', '2008-09-04', 6.95, 'https://image.tmdb.org/t/p/w500/6mLXG2f7LBRpbZZgxsOFO5scgzd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13763, 'Purple Rain', 'A victim of his own anger, the Kid is a Minneapolis musician on the rise with his band, the Revolution, escaping a tumultuous home life through music. While trying to avoid making the same mistakes as his truculent father, the Kid navigates the club scene and a rocky relationship with a captivating singer, Apollonia. But another musician, Morris, looks to steal the Kid''s spotlight -- and his girl.', '1984-07-27', 6.70, 'https://image.tmdb.org/t/p/w500/vkQmzaSuDj8QyXmwNhCceCAmwUe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13649, 'High School Musical 2', 'The East High Wildcats are gearing up for big fun as they land the coolest summer jobs imaginable. Troy, Gabriella, Chad, and Taylor have scored sweet gigs at the Lava Springs Country Club owned by Sharpay and Ryan''s family. Sharpay''s first rule of business: Get Troy. As Troy experiences a life of privilege he''s never known, will he give up the Wildcats and Gabriella to rise to the top?', '2007-08-17', 6.50, 'https://image.tmdb.org/t/p/w500/kqImEYXsDIlzPpu0KxyTXIx7smW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13894, 'Sharkwater', 'Driven by passion fed from a life-long fascination with sharks, Rob Stewart debunks historical stereotypes and media depictions of sharks as bloodthirsty, man-eating monsters and reveals the reality of sharks as pillars in the evolution of the seas.', '2006-09-11', 7.60, 'https://image.tmdb.org/t/p/w500/kLsTIdlsnJnPioWGiCsLFQzLdzP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13898, 'The Circle', 'Various women struggle to function in the oppressively sexist society of contemporary Iran.', '2000-09-09', 6.97, 'https://image.tmdb.org/t/p/w500/dUsPp5vacr3zZqsiquu5TTaApDr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13899, 'Dead or Alive 2: Birds', 'Two contract killers cross paths in the middle of the same job and realize they are childhood friends. Together they take a break from killing and visit the small island they once called home. After reflecting on their past lives they decided to team up and use their talents in killing for good... much to the upset of the crime syndicates.', '2000-12-02', 6.83, 'https://image.tmdb.org/t/p/w500/hEi5PhfgInQPL9Z0r3jijuYN8Im.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13654, '101 Dalmatians II: Patch''s London Adventure', 'Being one of 101 takes its toll on Patch, who doesn''t feel unique. When he''s accidentally left behind on moving day, he meets his idol, Thunderbolt, who enlists him on a publicity campaign.', '2003-03-02', 6.02, 'https://image.tmdb.org/t/p/w500/uB0DQU4Cog8tYrkiOEVTmDw6Qnn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13907, 'Kurt & Courtney', 'After rocker Kurt Cobain''s death, ruled a suicide, a film crew arrives in Seattle to make a documentary. Director Nick Broomfield talks to lots of people. Portraits emerge: a shy, slight Kurt, weary of touring, embarrassed by fame, hooked on heroin; an out-going Courtney, dramatic, controlling, moving from groupie to star.', '1998-02-27', 6.02, 'https://image.tmdb.org/t/p/w500/m60KpD60vXOXjJXRjb4veX88Y8q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13851, 'Batman: Gotham Knight', 'Six interlocking stories reveal Bruce Wayne''s earliest adventures as Batman and the steps he took to become the grim avenger of Gotham City.', '2008-07-08', 6.72, 'https://image.tmdb.org/t/p/w500/3i1o0sHBP0VUpuSVmkdCRKYoDBC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13655, 'Camp Rock', 'When Mitchie gets a chance to attend Camp Rock, her life takes an unpredictable twist, and she learns just how important it is to be true to yourself.', '2008-06-20', 6.39, 'https://image.tmdb.org/t/p/w500/7IXMqZnwccogptThay3togKIFWw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13817, 'Head On', 'Nineteen-year-old Ari confronts both his sexuality and his Greek family. Ari despises his once-beloved parents, former radical activists, for having entombed themselves in insular tradition. Ari is obsessed with gay sex, although he does make an unenthusiastic attempt to satisfy the sister of one of his best friends. While all of this is going on, he''s facing problems with his traditional Greek parents, who have no clue about his sexual activities.', '1998-08-13', 6.24, 'https://image.tmdb.org/t/p/w500/7kOpfb9oCiDP7LUWbthZhzjnh1J.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13908, 'The Master of Disguise', 'After the patriarch of the Disguisey family is kidnapped by Devlin Bowman in an attempt to steal the most precious treasures from around the world, Italian waiter Pistachio Disguisey utilizes his supernatural ability to disguise himself in an attempt to stop him.', '2002-08-02', 4.00, 'https://image.tmdb.org/t/p/w500/JFKuKJeHHFFVb0ubpkPIXmkIOg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13909, 'She Wore a Yellow Ribbon', 'On the eve of retirement, Captain Nathan Brittles takes out a last patrol to stop an impending massive Indian attack. Encumbered by women who must be evacuated, Brittles finds his mission imperiled.', '1949-10-22', 6.92, 'https://image.tmdb.org/t/p/w500/2IXtuwkTVcDsaa09AiQnlkfxe7I.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13761, 'Pocahontas II: Journey to a New World', 'When news of John Smith''s death reaches America, Pocahontas is devastated. She sets off to London with John Rolfe, to meet with the King of England on a diplomatic mission: to create peace and respect between the two great lands. However, Governor Ratcliffe is still around; he wants to return to Jamestown and take over. He will stop at nothing to discredit the young princess.', '1998-08-04', 5.56, 'https://image.tmdb.org/t/p/w500/sUvNHmUGJP3RkYpE65i7ZF0v0nE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13665, 'Arthur', 'Arthur is a 30-year-old child who will inherit $750 million if he complies with his family''s demands and marries the woman of their choosing.', '1981-07-17', 6.50, 'https://image.tmdb.org/t/p/w500/m8yOFRDVZPxtsr4D2hVdzls6q6t.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13912, 'Horse Feathers', 'Quincy Adams Wagstaff, the new president of Huxley U, hires bumblers Baravelli and Pinky to help his school win the big football game against rival Darwin U.', '1932-08-19', 6.88, 'https://image.tmdb.org/t/p/w500/sndzhGYShAcSf3AaYGfiwl4YbgS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13920, 'Radio', 'In the racially divided town of Anderson, South Carolina in 1976, football coach Harold Jones spots a mentally disabled African-American young man nicknamed Radio near his practice field and is inspired to befriend him. Soon, Radio is Jones'' loyal assistant, and he becomes a student at T.L. Hanna High School. But things start to sour when Coach Jones begins taking guff from parents and fans who feel that his devotion to Radio is getting in the way of the team''s quest for a championship.', '2003-10-24', 7.30, 'https://image.tmdb.org/t/p/w500/uQ6ci4iFHhB6TWB2f4wftR7AEly.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13919, 'The Chumscrubber', 'The Chumscrubber is a dark comedy about the lives of people who live in upper-class suburbia. It all begins when Dean Stiffle finds the body of his friend, Troy. He doesn''t bother telling any of the adults because he knows they won''t care. Everyone in town is too self consumed to worry about anything else than themselves. And everybody is on some form of drug just to get through their days.', '2005-06-08', 6.51, 'https://image.tmdb.org/t/p/w500/uMb26IjDgdq8p4H3XNO1CAsjT4m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13885, 'Sweeney Todd: The Demon Barber of Fleet Street', 'The infamous story of Benjamin Barker, a.k.a Sweeney Todd, who sets up a barber shop down in London which is the basis for a sinister partnership with his fellow tenant, Mrs. Lovett. Based on the hit Broadway musical.', '2007-12-21', 7.18, 'https://image.tmdb.org/t/p/w500/gAW4J1bkRjZKmFsJsIiOBASeoAp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13922, 'The Great Raid', 'As World War II rages, the elite Sixth Ranger Battalion is given a mission of heroic proportions: push 30 miles behind enemy lines and liberate over 500 American prisoners of war.', '2005-08-12', 6.53, 'https://image.tmdb.org/t/p/w500/k5Q76tzV2T4RtDdYwNj64c1qQ16.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13925, 'Luxo Jr.', 'A baby lamp finds a ball to play with and it''s all fun and games until the ball bursts. Just when the elder Luxo thinks his kid will settle down for a bit, Luxo Jr. finds a ball ten times bigger.', '1986-08-17', 7.05, 'https://image.tmdb.org/t/p/w500/as8xF0wOawngZ1G3qg5gs0VQea3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13913, 'Animal Crackers', 'The well-known explorer and hunter Captain Spaulding has just returned from Africa, and is being welcomed home with a lavish party at the estate of influential society matron Mrs. Rittenhouse when a valuable painting goes missing. The intrepid Captain Spaulding attempts to solve the crime with the help of his silly secretary Horatio Jamison, while sparring with the anarchic Signor Emanuel Ravelli and his nutty sidekick The Professor.', '1930-08-08', 6.91, 'https://image.tmdb.org/t/p/w500/qj7owFXzCtIbZC51O8NwLe4Kde4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13915, 'Waydowntown', 'Four young office workers have a bet going to see who can last the longest without going outside. In the maze that is the downtown core of a large city, glass skywalks connect apartment buildings, office towers and shopping malls. Its day 28 of the bet and over the lunch hour, as the office prepares for the company founder''s retirement party, things start to seriously unravel.', '2002-01-25', 5.78, 'https://image.tmdb.org/t/p/w500/k2gFxNSAYZEqXXzT2chV7ezrl0Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13929, 'Geri''s Game', 'An aging codger named Geri plays a daylong game of chess in the park against himself. Somehow, he begins losing to his livelier opponent. But just when the game''s nearly over, Geri manages to turn the tables.', '1997-11-24', 7.63, 'https://image.tmdb.org/t/p/w500/8PdCk3T9EkcKniUviDogWFCXx28.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13931, 'Mike''s New Car', 'Mike discovers that being the top-ranking laugh collector at Monsters, Inc. has its benefits – in particular, earning enough money to buy a six-wheel-drive car that''s loaded with gadgets. That new-car smell doesn''t last long enough, however, as Sulley jump-starts an ill-fated road test that teaches Mike the true meaning of buyer''s remorse.', '2002-05-24', 6.90, 'https://image.tmdb.org/t/p/w500/mOnNx05XOPFeQhOqpbPI0lwEf4N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13930, 'For the Birds', 'One by one, a flock of small birds perches on a telephone wire. Sitting close together has problems enough, and then comes along a large dopey bird that tries to join them. The birds of a feather can''t help but make fun of him - and their clique mentality proves embarrassing in the end.', '2000-11-02', 7.49, 'https://image.tmdb.org/t/p/w500/7GogfWZYkZh802fnaMoDBnu8cfV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13932, 'Jack-Jack Attack', 'The Parrs'' baby Jack-Jack is thought to be normal, not having any super-powers like his parents or siblings. But when an outsider is hired to watch him, Jack-Jack shows his true potential.', '2005-03-15', 7.30, 'https://image.tmdb.org/t/p/w500/uKMYT8aAJS9LA8IM1juMqbXTtqU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13933, 'One Man Band', 'With one coin to make a wish at the piazza fountain, a peasant girl encounters two competing street performers who''d prefer the coin find its way into their tip jars. The little girl, Tippy, is caught in the middle as a musical duel ensues between the one-man-bands.', '2005-06-21', 7.26, 'https://image.tmdb.org/t/p/w500/zF0YT9g3fmjLB6kQrjmpWNqpoe4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13937, 'Raising Cain', 'Child psychologist Carter Nix is a loving and caring family man, but under this appearance lies a dark and troubled past. Grappling with the consequences of this past on his own psyche and the influence of his returning father and violent brother Cain, Carter becomes involved in a series of murders and kidnappings. Meanwhile, his wife Jenny rekindles an old love affair, placing herself in the crosshairs of her increasingly unstable husband.', '1992-08-07', 6.04, 'https://image.tmdb.org/t/p/w500/5vRn138vnZeUNFe32qTuPGKkVLR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13936, 'Oklahoma!', 'There''s a box social coming up, and Curly asks Laurey if she''ll be his date. Trouble is, Laurey thinks he''s waited too long, and in a fit of pique accepts an offer from the boorish ranch hand Jud instead. Meanwhile, Laurey''s friend Ado Annie is also torn between two men: cowboy Will and foreign peddler Ali Hakim. Both women struggle to know their own hearts before it''s too late.', '1955-10-10', 6.63, 'https://image.tmdb.org/t/p/w500/ztqT5GmJVI2o8vShGWRVVqykQqA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13765, 'Scrooge', 'A musical adaptation of Charles Dickens'' classic ghost tale starring Albert Finney.', '1970-11-05', 6.80, 'https://image.tmdb.org/t/p/w500/eadjJGFdbZdhXSjtokmay7NjVHi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13938, 'The Last Dragon', 'A young man searches for the "master" to obtain the final level of martial arts mastery known as the glow. Along the way he must fight an evil martial arts expert and rescue a beautiful singer from an obsessed music promoter.', '1985-03-22', 6.54, 'https://image.tmdb.org/t/p/w500/r5QnLY30gXlZ8luiJE3quDs1WNF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13939, 'Death Wish', 'After his wife is murdered by street punks, a pacifistic New York City architect becomes a one-man vigilante squad, prowling the streets for would-be muggers after dark.', '1974-07-24', 6.93, 'https://image.tmdb.org/t/p/w500/rNksI6UiuTgLtBy69WvKT1PrG0R.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13958, 'The King of Kong: A Fistful of Quarters', 'In this hilarious arcade showdown, a humble novice goes head-to-head against the reigning Donkey Kong champ in a confrontation that rocks the gaming world to its processors! For over 20 years, Billy Mitchell has owned the throne of the Donkey Kong world. No one could beat his top score until now. Newcomer Steve Wiebe claims to have beaten the unbeatable, but Mitchell isn''t ready to relinquish his crown without a fight. Go behind the barrels as the two battle it out in a vicious war to earn the title of the true King of Kong.', '2007-03-25', 7.73, 'https://image.tmdb.org/t/p/w500/wACtXGiO08EBbJhqsD2nUzPsrKe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13964, 'The Machine Girl', 'The life of a young, Japanese schoolgirl is destroyed when her family is killed by a Ninja-Yakuza family. Her hand cut off, she replaces it with various machines-of-death, and seeks revenge.', '2008-01-02', 6.01, 'https://image.tmdb.org/t/p/w500/ln2ld7e5BwNqcBgUO7lqaBtAsuh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13948, 'An American Carol', 'A cynical anti-American Hollywood filmmaker sets out on a crusade to abolish the 4th of July holiday. He is visited by three spirits who take him on a hilarious journey in an attempt to show him the true meaning of America.', '2008-10-03', 4.21, 'https://image.tmdb.org/t/p/w500/uEDdzt1ZTB1BRo95gMkBytl0NqM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13967, 'Miss Potter', 'Beatrix Potter, the author of the beloved children''s book "The Tale of Peter Rabbit", struggles for love, happiness and success.', '2006-12-03', 6.70, 'https://image.tmdb.org/t/p/w500/fecGKwGABfZdMbiH1WQN9zMcOkS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13853, 'The Clan of the Cave Bear', 'Natural changes have the clans moving. Iza, medicine woman of the "Clan of the Cave Bear" finds little Ayla from the "others"'' clan - tradition would have the clan kill Ayla immediately, but Iza insists on keeping her. When the little one finds a most needed new cave, she''s allowed to stay - and thrive.', '1986-01-17', 5.29, 'https://image.tmdb.org/t/p/w500/jbftdduVujKeoib5fwDBbEMamdj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13888, 'Return to the Blue Lagoon', 'In this sequel to the 1980 classic, two children are stranded on a beautiful island in the South Pacific. With no adults to guide them, the two make a simple life together and eventually become tanned teenagers in love.', '1991-08-02', 6.17, 'https://image.tmdb.org/t/p/w500/jhUTLuPgc3Qcvr5xtji8oiWSfYy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13818, 'Heartburn', 'She''s a magazine writer who gives up her career for love and family. He''s a playboy newspaper columnist who can''t quite give up his old tricks. And if that combination doesn''t give a relationship heartburn, nothing will.', '1986-07-25', 6.00, 'https://image.tmdb.org/t/p/w500/pF1uPAi9TWRSRLf9SHfIDQle2NK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13764, 'Santa Claus: The Movie', 'In ancient times, a man named Claus, who delivers toys in his small village, fulfils his destiny to become Santa Claus after meeting an expert toy-making elf, Patch, in the North Pole. In the present day, Santa Claus has become overwhelmed by his workload, and the disgruntled Patch flees the workshop to New York City. There, Patch unknowingly threatens the fate of Christmas by taking a job at a failing toy company run by a scheming businessman.', '1985-10-29', 6.35, 'https://image.tmdb.org/t/p/w500/tZvGQF2623FD0MZgvOy18J5d7x5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13949, 'Persuasion', 'Anne Elliot was once in love with Frederick Wentworth, a commander in the Royal Navy who was rejected by her snobby parents eight years ago. When the family hits hard times and are forced to rent out their mansion to his brother-in-law, Frederick returns as a captain - but will he remember Anne?', '2007-04-01', 7.24, 'https://image.tmdb.org/t/p/w500/rDv38jqf3t0n4F9wGkQXBLx7wN9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13820, 'Repo Man', 'A down and out young punk gets a job working with a seasoned repo man, but what awaits him in his new career is a series of outlandish adventures revolving around aliens, the CIA, and a most wanted ''64 Chevy.', '1984-03-02', 6.66, 'https://image.tmdb.org/t/p/w500/bjuu5UceuVUNUjnOC2fBzL3hZKC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13982, '8 Heads in a Duffel Bag', 'Mafia hitman Tommy Spinelli is flying to San Diego with a bag that holds eight severed heads, which he''s bringing to his superiors to prove that some troublesome rival mobsters are permanently out of the picture. When his bag gets accidentally switched at the airport, Tommy must track down his duffel bag and the 8 heads it contains.', '1997-04-18', 5.03, 'https://image.tmdb.org/t/p/w500/dbjS5UH7JvsQwSLMYMY5GQOSwv1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13856, 'Special', 'A lonely metermaid has a psychotic reaction to his medication and becomes convinced he''s a superhero. A very select group of people in life are truly gifted. Special is a movie about everyone else.', '2006-11-17', 6.30, 'https://image.tmdb.org/t/p/w500/5oGxZ9Itu8buWnB15p6sri3zh9n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13823, 'The Power of One', 'PK, an English orphan terrorized for his family''s political beliefs in Africa, turns to his only friend, a kindly world-wise prisoner, Geel Piet. Geel teaches him how to box with the motto “fight with your fists and lead with your heart”. As he grows to manhood, PK uses these words to take on the system and the injustices he sees around him - and finds that one person really can make a difference.', '1992-03-27', 7.48, 'https://image.tmdb.org/t/p/w500/xOVPMNaQvMNHt68vijC1gvy81my.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13986, 'Dil To Pagal Hai', 'Rahul, the director of a successful dance troupe, considers Nisha his best friend, though secretly, she is madly in love with him. He then falls for Pooja, who is engaged to Ajay.', '1997-10-30', 6.90, 'https://image.tmdb.org/t/p/w500/HKUrZZbXnwCM4129fPlgHEg0eG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13950, 'All About the Benjamins', 'Bounty hunter Bucum Jackson teams with the small-time con artist, Reggie Wright, that he is pursuing, in an attempt to locate a missing stash of diamonds and a lottery ticket worth millions of dollars. Bucum and Reggie find themselves in a race to the finish as they embark on an unlikely partnership that should -- when all is said and done -- prove beneficial to them both.', '2002-03-08', 5.88, 'https://image.tmdb.org/t/p/w500/sO7IpJHjZBGLevi8Ozj9EsAUw5h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13995, 'Captain America', 'During World War II, a brave, patriotic American Soldier undergoes experiments to become a new supersoldier, "Captain America". Racing to Germany to sabotage the rockets of Nazi baddie "Red Skull", Captain America winds up frozen until the 1990s. He reawakens to find that the Red Skull has changed identities and is now planning to kidnap the President of the United States.', '1990-12-14', 4.52, 'https://image.tmdb.org/t/p/w500/vdHrLFfHcJX9nlvUfG3LK2a2hq4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13997, 'Black Sheep', 'When dignified Albert Donnelly runs for Governor, his team moves to keep his slow-witted and klutzy younger brother, Mike, out of the eye of the media. To baby-sit Mike, the campaign assigns sarcastic Steve, who gets the experience of a lifetime when he tries to take Mike out of town during the election.', '1996-02-02', 6.06, 'https://image.tmdb.org/t/p/w500/bqIW5oE4WeHAvk1nh2Y6rfOLGrF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13998, 'Margot at the Wedding', 'Margot Zeller is a short story writer with a sharp wit and an even sharper tongue. On the eve of her estranged sister Pauline''s wedding to unemployed musician/artist/depressive Malcolm at the family seaside home, Margot shows up unexpectedly to rekindle the sisterly bond and offer her own brand of support. What ensues is a nakedly honest and subversively funny look at family dynamics.', '2007-11-16', 5.79, 'https://image.tmdb.org/t/p/w500/g92DyjiMKhuWLxF8qkXOxZwvWMf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14001, 'Dead Silence', 'Jamie returns to his hometown in search of answers to his wife''s murder, which occurred after receiving a weird package containing a ventriloquist dummy named Billy, which may be linked to the legend of ventriloquist Mary Shaw. Destined to find out the truth, Jamie goes to the town of Raven''s Fair, where Shaw used to perform and is buried. But Jamie is in for more than he expected.', '2007-03-16', 6.45, 'https://image.tmdb.org/t/p/w500/rvcUVdATIHKZt7BSSttUkKbeBXN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14002, 'Baraka', 'A paralysingly beautiful documentary with a global vision—an odyssey through landscape and time—that attempts to capture the essence of life.', '1992-09-15', 8.23, 'https://image.tmdb.org/t/p/w500/ldEuJQ4z7zEvL7iXraESWBUfQcz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14003, 'Fullmetal Alchemist the Movie: Conqueror of Shamballa', 'Munich, Germany, 1923. Two years have passed since Edward Elric was dragged from his own world to ours, leaving behind his country, his friends and his younger brother, Alphonse. Stripped of his alchemical powers, he has been all this time researching rocketry together with Alphonse Heiderich, a young man who resembles his own brother, hoping to one day find a way back home. His efforts so far had proven fruitless, but after lending a hand to a troubled gipsy girl, Edward is thrown in a series of events that can wreak havoc in both worlds. Meanwhile, at his own world, Alphonse Elric ventures deeper into the mysteries of alchemy in search for a way to reunite with his older brother.', '2005-07-21', 7.30, 'https://image.tmdb.org/t/p/w500/kdovrjrKighUFEh9ZRQul0Evx6L.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13891, 'Citizen Ruth', '"Citizen Ruth" is the story of Ruth Stoops, a woman who nobody even noticed -- until she got pregnant. Now, everyone wants a piece of her. The film is a comedy about one woman caught in the ultimate tug-of-war: a clash of wild, noisy, ridiculous people that rapidly dissolves into a media circus.', '1996-11-21', 6.60, 'https://image.tmdb.org/t/p/w500/ncDIFOY7Mcan2gunAivLjIx3Kj1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14011, 'Justice League: The New Frontier', 'The human race is threatened by a powerful creature, and only the combined power of Superman, Batman, Wonder Woman, Green Lantern, Martian Manhunter and The Flash can stop it. But can they overcome their differences to thwart this enemy using the combined strength of their newly formed Justice League?', '2008-02-26', 6.82, 'https://image.tmdb.org/t/p/w500/bj25ueeYNkz4e5t8oMMaAOWmwOc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14013, 'BASEketball', 'Two losers from Milwaukee, Coop and Remer, invent a new game combining basketball with the rules of baseball. When the game becomes a huge success, they, along with a billionaire''s help, form the Professional Baseketball League where everyone gets the same pay and no team can change cities. When a rival owner wants to institute major rule changes, Coop and Remer''s team is the only one standing in the way.', '1998-07-28', 6.10, 'https://image.tmdb.org/t/p/w500/oKZdAUV9XSLp091f0GmtQEu0UZy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14022, 'Slacker', 'Austin, Texas, is an Eden for the young and unambitious, from the enthusiastically eccentric to the dangerously apathetic. Here, the nobly lazy can eschew responsibility in favor of nursing their esoteric obsessions. The locals include a backseat philosopher who passionately expounds on his dream theories to a seemingly comatose cabbie, a young woman who tries to hawk Madonna''s Pap test to anyone who will listen and a kindly old anarchist looking for recruits.', '1990-07-27', 6.74, 'https://image.tmdb.org/t/p/w500/f7Iov2nd0XX9bp2laQEPYPEhisc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14019, 'Ex Drummer', 'Three musicians form a band. But they''re not just any musicians: each has a disability that makes them particularly unsuitable for their instrument. The guitarist is deaf, the singer is tone deaf, and the bassist has a stiff arm. They lack a drummer, and to respect the group''s uniqueness, they turn to a famous writer who has never played the drums. He accepts, but begins a manipulation that will wreak further havoc on the already largely dysfunctional band.', '2007-01-31', 6.84, 'https://image.tmdb.org/t/p/w500/7VxXp2h9UtJP6XbeuQGqqbQzoE1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14024, 'Raise Your Voice', 'A coming-of-age story centered around a small-town singer brokenhearted by the death of her brother in a car crash, who had secretly submitted her for a summer session at a performing arts academy in Los Angeles. In the academy, she experiences a whole new way of life in the big city, far from the small town lifestyle she''s used to.', '2004-08-10', 6.60, 'https://image.tmdb.org/t/p/w500/89sfBkVOsgFRPs6uKaBtSMCDSv3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14030, 'Hello, Dolly!', 'Dolly Levi is a strong-willed matchmaker who travels to Yonkers, New York in order to see the miserly "well-known unmarried half-a-millionaire" Horace Vandergelder. In doing so, she convinces his niece, his niece''s intended, and Horace''s two clerks to travel to New York City.', '1969-12-12', 7.00, 'https://image.tmdb.org/t/p/w500/aPZOt9BR3gnk1RyX924ySq81S4P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14035, 'Meatballs', 'Tripper is the head counselor at a budget summer camp called Camp Northstar. In truth, he''s young at heart and only marginally more mature than the campers themselves. Tripper befriends Rudy, a loner camper who has trouble fitting in. As Tripper inspires his young charges to defeat rival Camp Mohawk in the annual Olympiad competition, Rudy plays matchmaker between Tripper and Roxanne, a female counselor at Northstar.', '1979-06-28', 5.82, 'https://image.tmdb.org/t/p/w500/9YA2erSNcca9NWd0xePC9ArFWnx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14040, 'American Flyers', 'When Dr. Marcus Sommers realizes that he and his troubled, estranged brother David may be prone a fatal brain disease that runs in their family, he decides to make peace with his sibling, and invites him on a trip to the Rockies. There, the brothers bond over their shared enthusiasm for cycling and decide to enter a grueling bike race through the mountains. However, Marcus'' health soon begins to fail, and David must compete without his brother at his side.', '1985-08-16', 6.17, 'https://image.tmdb.org/t/p/w500/sa8otETzs4ZJ77s7LypCmD0zzQe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14043, 'Nancy Drew', 'Intrepid teenage private eye Nancy Drew heads to Tinseltown with her father to investigate the unsolved murder of a movie star in this old-fashioned whodunit based on Carolyn Keene''s popular series of books for young adults. But can the small-town girl cut through the Hollywood hype to solve the case?', '2007-06-15', 6.06, 'https://image.tmdb.org/t/p/w500/a1aAZolyLFRwKhs0IWhFyTa8Z2Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13962, 'Blank Check', 'Bullied by his siblings and nagged by his parents, 11-year-old Preston Waters is fed up with his family — especially their frugality. But he gets his chance to teach them a lesson when a money-laundering criminal nearly bulldozes Preston with his car and compensates the boy with a blank check. Preston makes the check out for $1 million and goes on a spending spree he''ll never forget.', '1994-02-11', 5.97, 'https://image.tmdb.org/t/p/w500/qhsH1BGqeCDHoogt5ebxOgERJGb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14044, 'Assembly', 'Follows a soldier trying to gain recognition for comrades who died in 1948, at a turning point in the civil war between the communists and the nationalist forces of the Kuomintang.', '2007-10-09', 6.94, 'https://image.tmdb.org/t/p/w500/pv04qa9RxD41XLnJGECq1f4cr9I.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14052, 'Revenge of the Nerds', 'At Adams College, the jocks rule from their house on high, the Alpha Beta fraternity. So when a group of socially-challenged misfits try to go Greek, they''re instantly rejected by every house on campus. Deciding to start their own frat to protect their outcast brothers, the nerds soon find themselves in a battle royale as the Alpha Betas try to crush their new rivals.', '1984-07-20', 6.46, 'https://image.tmdb.org/t/p/w500/v8aETLufi4WIinhQ994oWkehtaC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14050, 'Recount', 'In 2000, the election of the U.S. Presidential boiled down to a few precious votes in the state of Florida — and a recount that would add "hanging chad" to every American''s vocabulary.', '2008-05-25', 6.80, 'https://image.tmdb.org/t/p/w500/7I3WMof3AJuLkildBxpGZkuvQwj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14048, 'Man on Wire', 'On August 7th 1974, French tightrope walker Philippe Petit stepped out on a high wire, illegally rigged between New York''s World Trade Center twin towers, then the world''s tallest buildings. After nearly an hour of performing on the wire, 1,350 feet above the sidewalks of Manhattan, he was arrested. This fun and spellbinding documentary chronicles Philippe Petit''s "highest" achievement.', '2008-08-01', 7.40, 'https://image.tmdb.org/t/p/w500/1mS4rhIgHZcHIvf1beP9Av0Ui33.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14055, 'Starter for 10', 'In 1985, against the backdrop of Thatcherism, Brian Jackson enrolls in the University of Bristol, a scholarship boy from seaside Essex with a love of knowledge for its own sake and a childhood spent watching University Challenge, a college quiz show. At Bristol he tries out for the Challenge team and falls under the spell of Alice, a lovely blond with an extensive sexual past.', '2006-09-13', 6.39, 'https://image.tmdb.org/t/p/w500/m0NU3kgn87iNffUUDeItUXZKUKl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14069, 'The Girl Who Leapt Through Time', 'When 17-year-old Makoto Konno gains the ability to ''leap'' backwards through time, she immediately sets about improving her grades and preventing personal mishaps. However, she soon realises that changing the past isn''t as simple as it seems, and eventually, will have to rely on her new powers to shape the future of herself and her friends.', '2006-07-15', 7.77, 'https://image.tmdb.org/t/p/w500/fmK92C7HGu6sK0axItlQ0YsO9qR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14108, 'The Weather Underground', 'The remarkable story of The Weather Underground, radical activists of the 1970s, and of radical politics at its best and most disastrous.', '2002-11-17', 6.57, 'https://image.tmdb.org/t/p/w500/fuTAf8DJkj2vljaprE5upLP3nWA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14112, 'Auto Focus', 'A successful TV star during the 1960s, former "Hogan''s Heroes" actor Bob Crane projects a wholesome family-man image, but this front masks his persona as a sex addict who records and photographs his many encounters with women, often with the help of his seedy friend, John Henry Carpenter. This biographical drama reveals how Crane''s double life takes its toll on him and his family, and ultimately contributes to his death.', '2002-10-18', 6.40, 'https://image.tmdb.org/t/p/w500/71CQUn4vtpDQtAPXtaLP7IGH0Sg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13965, 'The Man From Snowy River II', 'After a few years trying to earn money to marry Jessica Harrison, Jim Craig returns to Snowy River. But he finds that a lot of things have changed.', '1988-03-24', 6.76, 'https://image.tmdb.org/t/p/w500/6I94myoMi28trV8lxDq2DWhzLFe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13990, 'The Wackness', 'Set in New York City in the sweltering summer, The Wackness tells the story of a troubled teenage drug dealer, who trades pot for therapy sessions with a drug-addled psychiatrist. Things get more complicated when he falls for one of his classmates, who just happens to be the doctor''s daughter. This is a coming-of-age story about sex, drugs, music and what it takes to be a man.', '2008-07-03', 6.41, 'https://image.tmdb.org/t/p/w500/gmtlqHZs8YBXcpMw4BgA3SGJfg8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14114, 'You Got Served', 'At Mr. Rad''s Warehouse, the best hip-hop crews in Los Angeles compete for money and respect. But when a suburban crew crashes the party, stealing their dancers — and their moves — two warring friends have to pull together to represent the street.', '2004-01-30', 6.38, 'https://image.tmdb.org/t/p/w500/nFwT3QisWFQa3Wlfnw1gC458xJn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13850, 'Song of the South', 'Uncle Remus draws upon his tales of Br''er Rabbit to help little Johnny deal with his confusion over his parents'' separation as well as his new life on the plantation.', '1946-11-20', 6.48, 'https://image.tmdb.org/t/p/w500/lFlWpfcw8TCmZ88jw6e943vEbtu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13969, 'First Daughter', 'Samantha MacKenzie, the daughter of the president of the United States, arrives at college with a group of Secret Service agents. Samantha, however, resents their presence and decides she wants to attend school just like a normal student.', '2004-09-24', 6.18, 'https://image.tmdb.org/t/p/w500/iUZ3hDMo8SGY2IoujCKwVt8ukm9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13963, 'The Last Waltz', 'Martin Scorsese''s documentary intertwines footage from The Band''s incredible farewell tour with probing backstage interviews and featured performances by Eric Clapton, Bob Dylan, Joni Mitchell, Van Morrison, and other rock legends.', '1978-04-26', 7.66, 'https://image.tmdb.org/t/p/w500/2K7CFH0AIHnGrA4yQjPCoIB5CmQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13852, 'The Castle', 'The quirky Kerrigan family lives together in a makeshift home they built themselves – with great pride and a bizarre attention to detail – a few yards from the edge of Melbourne, Australia''s busy Tullamarine Airport. When a building inspector condemns the building and reveals that the government plans to use their land for an airport expansion, Darryl Kerrigan and his brood recruit hack attorney Dennis Denuto and prepare themselves for the fight of their lives.', '1997-04-10', 7.07, 'https://image.tmdb.org/t/p/w500/3QKTPz9gpIIt9Po091LfG0CASfk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13966, 'Maybe Baby', 'Sam and Lucie Bell are a married couple who seem to have it all: good looks, successful careers, matching motorbikes, and an enthusiastic love life. The only thing they lack is the one thing they want more—a baby.', '2000-06-02', 5.43, 'https://image.tmdb.org/t/p/w500/4PLm3BZiOXhDIbbqH8ipVyPVA1M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14061, 'The Edge of Love', 'When the Welsh poet Dylan Thomas and his flirtatious wife Caitlin sweep into war-torn London, the last thing they expect is to bump into Dylan''s childhood sweetheart Vera. Despite her joy at seeing Dylan after so many years, Vera is swept off her feet by a dashing officer, William Killick, and finds herself torn between the open adoration of her new found beau and the wily charms of the exotic Welshman.', '2008-06-20', 6.20, 'https://image.tmdb.org/t/p/w500/uo7ZDvipL2OZu6G44hDP0sjDZ9n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14141, 'Balls Out: Gary the Tennis Coach', 'An overenthusiastic high-school maintenance man attempts to lead an unlikely group of misfits to the Nebraska state tennis championship in Balls Out: The Gary Houseman Story? director Danny Leiner''s underdog sports comedy. American Pie star Seann William Scott stars as the ambitious janitor who believes he has what it takes to coach the winning team.', '2009-01-13', 5.08, 'https://image.tmdb.org/t/p/w500/s8LMr71B3ByCm2E1U33d9uynudY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13855, 'The Chaser', 'Joong-ho is a dirty detective turned pimp, who''s in financial trouble as several of his girls have recently disappeared without clearing their debts. While trying to track them down, he finds a clue that the vanished girls were all called up by the same client, whom one of his girls is meeting with right now.', '2008-02-14', 7.78, 'https://image.tmdb.org/t/p/w500/hy49xJiKN1nakkN1ZmKuOf6vQYR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14158, 'Jackass 2.5', 'The crew have now set off to finish what as left over from Jackass 2.0, and in this version they have Wee Man use a ''pee'' gun on themselves, having a mini motor bike fracas in the grocery mall, a sperm test, a portly crew member disguised as King Kong, as well as include three episodes of their hilarious adventures in India.', '2007-12-18', 6.13, 'https://image.tmdb.org/t/p/w500/nFCSqC4bjK3Rn6gXHTZGpOUiJ1C.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13968, 'Jump In!', 'A young boxer, Izzy Daniels, trains to follow in his father''s footsteps by winning the Golden Glove. But when his friend, Mary asks him to substitute for a team member in a Double Dutch tournament, the young man discovers a hidden passion for jump roping, all while finding love with Mary and navigating conflict with himself and his father about boxing.', '2007-01-12', 6.37, 'https://image.tmdb.org/t/p/w500/bC15nPOGIOXohhqzC2GTg0DlqIy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14160, 'Up', 'Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.', '2009-05-28', 8.00, 'https://image.tmdb.org/t/p/w500/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14135, 'Bad Boy Bubby', 'Bad Boy Bubby is just that: a bad boy. So bad, in fact, that his mother has kept him locked in their house for his entire thirty years, convincing him that the air outside is poisonous. After a visit from his estranged father, circumstances force Bubby into the waiting world, a place which is just as unusual to him as he is to the world.', '1993-09-01', 6.90, 'https://image.tmdb.org/t/p/w500/fERbcofifizJmDt892lFcrIYhFh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14054, 'Snow Angels', 'Waitress Annie has separated from her suicidal alcoholic husband, Glenn. Glenn has become an evangelical Christian, but his erratic attempts at getting back into Annie''s life have alarmed her. High school student Arthur works at Annie''s restaurant, growing closer to a new kid in town, Lila, after class. When Glenn and Annie''s daughter goes missing, the whole town searches for her, as he increasingly spirals out of control.', '2007-03-07', 6.48, 'https://image.tmdb.org/t/p/w500/hKtht1ezc31mH1cBIHoDPmScnk9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14161, '2012', 'Dr. Adrian Helmsley, part of a worldwide geophysical team investigating the effect on the earth of radiation from unprecedented solar storms, learns that the earth''s core is heating up. He warns U.S. President Thomas Wilson that the crust of the earth is becoming unstable and that without proper preparations for saving a fraction of the world''s population, the entire race is doomed. Meanwhile, writer Jackson Curtis stumbles on the same information. While the world''s leaders race to build "arks" to escape the impending cataclysm, Curtis struggles to find a way to save his family. Meanwhile, volcanic eruptions and earthquakes of unprecedented strength wreak havoc around the world.', '2009-10-10', 5.89, 'https://image.tmdb.org/t/p/w500/zaqam2RNscH5ooYFWInV6hjx6y5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14170, 'Funny Farm', 'Sportswriter Andy Farmer moves with his schoolteacher wife Elizabeth to the country in order to write a novel in relative seclusion. Of course, seclusion is the last thing the Farmers find in the small, eccentric town, where disaster awaits them at every turn.', '1988-06-03', 6.17, 'https://image.tmdb.org/t/p/w500/i4ExIbPuAe0rAjpYcteiFx4QEfY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14175, 'Valiant', 'Set in 1944, Valiant is a woodland pigeon who wants to become a great hero someday. When he hears they are hiring recruits for the Royal Homing Pigeon Service, he immediately sets out for London. On the way, he meets a smelly but friendly pigeon named Bugsy, who joins him, mainly to get away from clients he cheated in a game of find-the pebble, and helps him sign up for the war.', '2005-03-25', 5.65, 'https://image.tmdb.org/t/p/w500/tSRO8wukDlGMlrkmRpqL2nWhgPs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14168, '3:10 to Yuma', 'Dan Evans, a small time farmer, is hired to escort Ben Wade, a dangerous outlaw, to Yuma. As Evans and Wade wait for the 3:10 train to Yuma, Wade''s gang is racing to free him.', '1957-08-07', 7.29, 'https://image.tmdb.org/t/p/w500/emYeJVZrpl2WfndJlhbls1e7lzQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14166, 'Pretty Persuasion', 'A 15-year-old girl incites chaos among her friends and a media frenzy when she accuses her drama teacher of sexual harassment.', '2005-01-22', 5.80, 'https://image.tmdb.org/t/p/w500/oTbmRS9OBqACIlgRkTqHIc1n6lO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14181, 'Boiler Room', 'A college dropout gets a job as a broker for a suburban investment firm and is on the fast track to success—but the job might not be as legitimate as it sounds.', '2000-02-18', 6.71, 'https://image.tmdb.org/t/p/w500/jFB5uvCZ3HXF00liAEAuOruCPs6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14177, 'Beauty Shop', 'Far from Chicago, hairdresser Gina Norris has relocated to Atlanta with her daughter and has quickly established herself as a rare talent in her profession. But after repeatedly butting heads with her shady, over-the-top boss, Jorge, Norris sets out to create her own salon -- even snagging a few of Jorge''s employees and clients. Now, Jorge will do anything to shut her down.', '2005-04-22', 6.33, 'https://image.tmdb.org/t/p/w500/3y5I9WKlfeNnSQbOvS4l3mVPqri.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14191, 'Aquamarine', 'Two teenage girls discover that mermaids really do exist after a violent storm washes one ashore. The mermaid, a sassy creature named Aquamarine, is determined to prove to her father that real love exists, and enlists the girls'' help in winning the heart of a handsome lifeguard.', '2006-03-03', 6.47, 'https://image.tmdb.org/t/p/w500/8mioUyXqn60cwSoLrRCaO5ZAsCV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14195, 'Cecil B. Demented', 'A young lunatic director and his devoted cult of cinema terrorists kidnap a Hollywood movie goddess and force her to star in their radical underground movie.', '2000-08-02', 6.42, 'https://image.tmdb.org/t/p/w500/gCXUA9BUOSDmOFVfkVBF4v15Td6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14199, 'The Adventures of Sharkboy and Lavagirl', 'Everyone always knew that Max had a wild imagination, but no one believed that his wildest creations -- a boy raised by watchful great white sharks and a girl with the force of a volcano -- were real. Now, these two pint-sized action masters will show Max that even an ordinary kid has what it takes to be extraordinary.', '2005-06-10', 5.20, 'https://image.tmdb.org/t/p/w500/xpFbHSkRgOxOoutKqXob9T8iBPA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14201, 'The U.S. vs. John Lennon', 'A documentary on the life of John Lennon, with a focus on the time in his life when he transformed from a musician into an antiwar activist.', '2006-09-15', 6.60, 'https://image.tmdb.org/t/p/w500/rdzIiZmJ4lCSO48cNt3rViWk3CH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14202, 'The Painted Veil', 'A British medical doctor fights a cholera outbreak in a small Chinese village, while also being trapped at home in a loveless marriage to an unfaithful wife.', '2006-12-09', 7.26, 'https://image.tmdb.org/t/p/w500/k41IvHDLgZO2ae7RuU77wQjScIj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14137, 'Beer League', 'An unemployed slacker inspires his softball teammates to improve their game to avoid getting kicked out of the local league.', '2006-09-15', 5.15, 'https://image.tmdb.org/t/p/w500/yoB3G8yGNLHdbr4TSKZqRp7UJ72.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14208, 'The Librarian: Return to King Solomon''s Mines', 'After retrieving the Crystal Skull in Utah, Flynn Carsen receives a map in the mail with the secret location of King Solomon''s Mines. When the scroll is stolen, Judson explains the power of the Key of Solomon''s book and assigns Flynn to retrieve the map. The map is useless without the legend piece to decipher it, which is located in Volubilis near the Roman ruins in Morocco. Flynn heads to Casablanca to the ruins where he is chased by a group of mercenaries leaded by General Samir. They too want to find the location of King Solomon''s mines. Flynn teams-up with Professor Emily Davenport working in the dig and they escape from General Samir and his men. While traveling to Gedi, they save the local Jomo from death and the trio faces a dangerous journey through the wild Africa.', '2006-09-09', 6.26, 'https://image.tmdb.org/t/p/w500/4UxUdJUCLwirPdYzAsYg8ayKhGN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14239, 'Cool World', 'While incarcerated for murder, cartoonist Jack Deebs found escape by creating Cool World, a series featuring a voluptuous femme fatale named Holli Would. But the artist becomes a prisoner of his own fantasies when Holli transports Jack into Cool World with a scheme to seduce him and bring herself to life. Hard-boiled detective Frank Harris – the only other human in Cool World – cautions Jack with the law: Noids (humans) don''t have sex with doodles (cartoons). However, flesh proves weaker than ink as Holli takes human form in Las Vegas, staring in a trans-universal chase that threatens the destruction of both worlds.', '1992-07-10', 5.66, 'https://image.tmdb.org/t/p/w500/mqzRUHNtFwmgJCmSnvq3JnX0xgZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14220, 'Strange Wilderness', 'With the ratings dropping for a wilderness-themed TV show, two animal fans go to the Andes in search of Bigfoot.', '2008-02-01', 4.86, 'https://image.tmdb.org/t/p/w500/6tamhOw4dSgn4lonjZyhEhIt9Wm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14207, 'The Librarian: Quest for the Spear', 'When a magical artifact is lifted from his library, a meek librarian sets out to ensure its safe return.', '2004-07-12', 6.30, 'https://image.tmdb.org/t/p/w500/wRwbSr0imj632D0qxaHQig4WYf3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14241, '7 Faces of Dr. Lao', 'An old Chinese man rides into the town of Abalone, Arizona and changes it forever, as the citizens see themselves reflected in the mirror of Lao''s mysterious circus of mythical beasts.', '1964-03-18', 6.92, 'https://image.tmdb.org/t/p/w500/dwUTdtGUDmCb3Tiz6iTzBuONGTQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14242, 'American Movie', 'American Movie documents the story of filmmaker Mark Borchardt, his mission, and his dream. Spanning over two years of intense struggle with his film, his family, financial decline, and spiritual crisis, American Movie is a portrayal of ambition, obsession, excess, and one man''s quest for the American Dream.', '1999-11-05', 7.54, 'https://image.tmdb.org/t/p/w500/y8dJgWr1HeW0RRxwANDWvgIXdsF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14249, 'Revenge', 'Michael ‘Jay’ Cochran has just left the Navy after 12 years and he''s not quite sure what he''s going to do, except that he knows he wants a holiday. He decides to visit Tiburon Mendez, a powerful but shady Mexican businessman who he once flew to Alaska for a hunting trip. Arriving at the Mendez mansion in Mexico, he is immediately surprised by the beauty and youth of Mendez’s wife, Miryea.', '1990-02-16', 6.48, 'https://image.tmdb.org/t/p/w500/83diOZcg6ZiY8voNy2k4BX9TsMf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13976, 'Dylan Moran: Monster', 'Irish comedian Dylan Moran live at Vicar Street, Dublin.', '2004-11-15', 7.77, 'https://image.tmdb.org/t/p/w500/pivw76Oclu3lWdLf3FjwHANXMdD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14092, 'Ghost in the Shell 2.0', 'In the year 2029, Section 9, a group of cybernetically enhanced cops, are called in to investigate and stop a highly-wanted hacker known as ''The Puppetmaster''.', '2008-07-12', 7.37, 'https://image.tmdb.org/t/p/w500/5ngIhoA0b4aGBoPFPURAbDwCKT7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14262, 'Desperate Living', 'After killing her husband, Peggy Gravel and her murderous maid Grizelda wind up in the crazy town of Mortville, where Queen Carlotta presides over a sleazy collection of misfits.', '1977-05-27', 6.40, 'https://image.tmdb.org/t/p/w500/kqEZ1CbxtrXtpAT1jeYfo52um3s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13980, 'Sword of the Stranger', 'Pursued by formidable Chinese assassins, young Kotaro and his dog run into No Name, a mysterious stranger who gets pulled into the chase. The unlikely companions form a bond over saving the dog from a poison attack, but chaos erupts when the assassins find Kotaro, and No Name must face his past before a horrible fate is met again.', '2007-09-29', 7.59, 'https://image.tmdb.org/t/p/w500/lMsUYZq5ITW3rAqF3tB7v74KEnH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13971, 'Wild Child', 'Sixteen-year-old Poppy has everything her unlimited credit cards can buy, and a spoiled attitude to match. After a final thoughtless prank, her exasperated father ships her off to boarding school in England. There, Poppy meets her match in a stern headmistress and a class full of girls who will not tolerate her selfishness.', '2008-08-15', 6.70, 'https://image.tmdb.org/t/p/w500/xwbFEPubG4wroLDZdmTWRGNnnWf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14269, 'Polyester', 'Blessed with a keen sense of smell and cursed with a philandering pornographer husband, a parasitic mother, and a pair of delinquent children, the long-suffering Francine Fishpaw turns to the bottle as her life falls apart -- until deliverance appears in the form of a hunk named Todd Tomorrow. Originally screened with "Odorama" scratch and sniff cards so the audience could (at their own risk) smell along with the film.', '1981-05-29', 7.02, 'https://image.tmdb.org/t/p/w500/14RfMqOe8eF17bUajPsy4HtRsVC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13973, 'Choke', 'A sex-addicted con-man pays for his mother''s hospital bills by playing on the sympathies of those who rescue him from choking to death.', '2008-09-26', 6.10, 'https://image.tmdb.org/t/p/w500/7osy71os3YLiFpNYn567koOnAKZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14111, 'Battle for Haditha', 'An investigation of the massacre of 24 men, women and children in Haditha, Iraq allegedly shot by 4 U.S. Marines in retaliation for the death of a U.S. Marine killed by a roadside bomb. The movie follows the story of the Marines of Kilo Company, an Iraqi family, and the insurgents who plant the roadside bomb.', '2007-09-11', 6.20, 'https://image.tmdb.org/t/p/w500/jHyRWich4t0CQtgHiN7nnrbcEVv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14236, 'Super High Me', 'Determined to find out the true effects of marijuana on the human body, stand-up comedian and former Stoner of the Year Doug Benson documents his experience avoiding pot for 30 days and then consuming massive amounts of the drug for 30 days. More than just an amusing story of one man''s quest to get superhigh, this documentary also examines the hotly contested debate over medical marijuana use.', '2007-10-13', 5.74, 'https://image.tmdb.org/t/p/w500/80Y1Te0aZwBoImgFo7D2PgUzQna.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14251, 'Weirdsville', 'Dexter and Royce, two stoners in the small town of Weedsville, attempt to cover up the overdose of Royce''s girlfriend Matilda. What leads from an old drive-in being perfect place to ditch her turns into the accidental discovery of a Satanic cult, who brings Mattie back from the dead after their ritual is botched. Along with the two''s dealer Omar on their tail, how will these buddies and their slightly-off lady-on-board deal with the dangers of drug debt and demon-worshipping magic?', '2007-10-12', 5.90, 'https://image.tmdb.org/t/p/w500/mudmowQm0Xle2AHhKngUXTb8QsV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13975, 'In the Electric Mist', 'Lt. Dave Robicheaux, a detective in New Iberia, Louisiana, is trying to link the murder of a local hooker to New Orleans mobster Julie ''Baby Feet'' Balboni, who is co-producer of a Civil War film. When the star of the film,  Elrod Sykes, reports finding another corpse in the Atchafalaya Swamp near the movie set, Robicheaux starts another investigation, believing the corpse to be the remains of a black man whose murder he witnessed 35 years earlier.', '2009-04-15', 6.06, 'https://image.tmdb.org/t/p/w500/gsyUJovik2t5vzPyXL5tq5VWLym.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (13984, 'Fubar', 'Terry and Dean are lifelong friends who have grown-up together: shotgunning their first beers, forming their first garage band, and growing the great Canadian mullet known as "hockey hair". Now the lives of these Alberta everymen are brought to the big screen by documentarian Ferral Mitchener in an exploration of the depths of friendship, the fragility of life, growing up gracefully and the art and science of drinking beer like a man.', '2002-05-24', 6.30, 'https://image.tmdb.org/t/p/w500/95f3BiuBTKhemHLVe7Nyh8AhuEa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14254, 'The Uninvited', 'Anna returns home after spending time in a psychiatric facility following her mother''s tragic death and discovers that her mother''s former nurse, Rachel, has moved into their house and become engaged to her father. Soon after she learns this shocking news, Anna is visited by her mother''s ghost, who warns her that Rachel has evil intentions.', '2009-01-30', 6.47, 'https://image.tmdb.org/t/p/w500/1xQlzKUDLuCe3SUGIGL6K1PtldH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14283, 'The Red Violin', '300 years of a remarkable musical instrument. Crafted by the Italian master Bussotti (Cecchi) in 1681, the red violin has traveled through Austria, England, China, and Canada, leaving both beauty and tragedy in its wake. In Montreal, Samuel L Jackson plays an appraiser going over its complex history.', '1998-11-13', 7.34, 'https://image.tmdb.org/t/p/w500/uPjq8PaNDhFQTzOu4Ce91f6BFgZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14285, 'The Thin Blue Line', 'An unorthodox investigation into the wrongful conviction of Randall Dale Adams for the 1976 murder of Dallas police officer Robert Wood. Using stylized reenactments and interviews with key figures, conflicting testimonies and evidence are presented to argue that Adams was framed by a corrupt justice system, ultimately leading to his exoneration.', '1988-08-28', 7.66, 'https://image.tmdb.org/t/p/w500/4w4BJk3l8y9gYwPPLRs6uPHOmGL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14113, 'Zoom', 'Jack Shepard is an out-of-shape auto shop owner, far removed from the man who once protected the world''s freedom. Reluctantly called back into action by the government, Jack is tasked with turning a ragtag group of kids with special powers into a new generation of superheroes to save the world from certain destruction.', '2006-08-11', 5.27, 'https://image.tmdb.org/t/p/w500/v4rSFmiy0v9D7qmKkaUVJn5UhZ1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14286, 'Why We Fight', 'Is American foreign policy dominated by the idea of military supremacy? Has the military become too important in American life? Jarecki''s shrewd and intelligent polemic would seem to give an affirmative answer to each of these questions.', '2005-01-20', 7.51, 'https://image.tmdb.org/t/p/w500/kfOmnlwt1rrhxmxc05X3i9mHSOs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14289, 'Fire Down Below', 'When an EPA representative is murdered in a small Appalachian community, EPA undercover agent Jack Taggart is sent in—posing as a handyman working with a Christian relief agency—to determine what happened.', '1997-09-05', 5.76, 'https://image.tmdb.org/t/p/w500/nflONy2WMEui7uCGCAtkD1r9vnl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14240, 'Maniac Cop', 'A killer dressed in a police uniform begins murdering innocent people on the streets of New York City.', '1988-05-13', 6.11, 'https://image.tmdb.org/t/p/w500/YS4Q7xHZLjZ5HvffqVDmJLjxce.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14290, 'Better Luck Tomorrow', 'A group of over-achieving Asian-American high school seniors enjoy a power trip when they dip into extra-curricular criminal activities.', '2003-04-11', 6.21, 'https://image.tmdb.org/t/p/w500/alJULQQnuiYXjgVmj2EYgwXOcIn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14291, 'Searching for Bobby Fischer', 'A seven-year-old chess prodigy refuses to harden himself in order to become a champion like the famous but unlikable Bobby Fischer.', '1993-08-13', 7.07, 'https://image.tmdb.org/t/p/w500/oAJpHkMpfXiFY9F3HocIz9fhHLc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14292, 'Miracle', 'When college coach Herb Brooks is hired to helm the 1980 U.S. men''s Olympic hockey team, he brings a unique and brash style to the ice. After assembling a team of hot-headed college all-stars, who are humiliated in an early match, Brooks unites his squad against a common foe: the heavily-favored Soviet team.', '2004-02-06', 7.12, 'https://image.tmdb.org/t/p/w500/mxtej2th8t8x0ufVBTyhsO6Htxj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14293, 'Poolhall Junkies', 'A retired pool hustler is forced to pick up the stick again when his brother starts a game he can''t finish.', '2002-06-30', 6.35, 'https://image.tmdb.org/t/p/w500/3MAGLk0AtuPi24PBwy3o4ILO0CV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14298, 'Somers Town', 'Two teenagers, both newcomers to London, forge an unlikely friendship over the course of a hot summer. Tomo is a runaway from Nottingham; Marek lives in the district of Somers Town, between King''s Cross and Euston stations, where his dad is working on a new rail link.', '2008-08-22', 6.82, 'https://image.tmdb.org/t/p/w500/kr5B00hkWbdMTOe43coJZ1yVhI2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14295, 'You Can Count on Me', 'A single mother''s life is thrown into turmoil after her struggling, rarely-seen younger brother returns to town.', '2000-03-03', 6.87, 'https://image.tmdb.org/t/p/w500/7mGFmij1FZD5eUnNwvUjmpqrDl6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14306, 'Marley & Me', 'A newly married couple, in the process of starting a family, learn many of life''s important lessons from their trouble-loving retriever, Marley. Packed with plenty of laughs to lighten the load, the film explores the highs and lows of marriage, maturity and confronting one''s own mortality, as seen through the lens of family life with a dog.', '2008-12-25', 7.17, 'https://image.tmdb.org/t/p/w500/pnB6hjTKylb0Ve2nUWt16gzkErr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14308, 'I Am Trying to Break Your Heart: A Film About Wilco', 'A documentary by photographer Sam Jones documenting American rock band Wilco recording their fourth album Yankee Hotel Foxtrot. Originally intended as a showcase of the band''s creative process, the film crew catches unexpected complications between the band and its record label and problems among the band members themselves.', '2002-06-21', 7.50, 'https://image.tmdb.org/t/p/w500/fM4eEtfq0Nsvz6gi6t8UpC4Xdhq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14320, 'Great Expectations', 'In this Dickens adaptation, orphan Pip discovers through lawyer Mr. Jaggers that a mysterious benefactor wishes to ensure that he becomes a gentleman. Reunited with his childhood patron, Miss Havisham, and his first love, the beautiful but emotionally cold Estella, he discovers that the elderly spinster has gone mad from having been left at the altar as a young woman, and has made her charge into a warped, unfeeling heartbreaker.', '1946-12-26', 7.29, 'https://image.tmdb.org/t/p/w500/ynaFuVvW2jaG06pMV67dOhzMYfJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14328, 'The Paper Chase', 'A first-year law student struggles with balancing his coursework and his relationship with the daughter of a stern professor.', '1973-10-16', 6.80, 'https://image.tmdb.org/t/p/w500/9LU6tK5S9RIZq8mN7xXZY7HtGAK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14325, 'The Express', 'Follow the inspirational life of college football hero Ernie Davis, the first African-American to win the Heisman Trophy.', '2008-10-10', 7.15, 'https://image.tmdb.org/t/p/w500/l4bOPaxwx1WebQXTeqXzXwf9n3M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14334, 'The Secret of Roan Inish', 'Ten-year-old Fiona is sent to live with her grandparents in a small fishing village in Donegal, Ireland. She soon learns the local legend that an ancestor of hers married a Selkie – a seal who can turn into a human. Years earlier, her baby brother was washed out to sea and never seen again, so when Fiona spies a naked little boy on the abandoned Isle of Roan Inish, she is compelled to investigate.', '1994-05-14', 6.71, 'https://image.tmdb.org/t/p/w500/2FFcEEMMrnXh3CFz3aON92sLkXP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14337, 'Primer', 'A group of fledgling inventors discover a complex method to manipulate reality. At first, they successfully game the stock market with it, but the consequences of the invention start to catch up with them.', '2004-10-08', 6.75, 'https://image.tmdb.org/t/p/w500/xEoq2WmDzpzxhkHEsmOYOg6BPg6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14347, 'Blame It on Rio', 'Matthew Hollis is man on holiday in Rio with his best friend. Both men have teenage daughters with them. When Matthew falls for his best friend''s amorous daughter named Jennifer, they embark on a secret, if slightly one-sided relationship. Jennifer''s father is furious when he finds out about the ''older man'' in his daughter''s life, and sets out to hunt him down with the aid of Matthew!', '1984-02-17', 5.75, 'https://image.tmdb.org/t/p/w500/yzNtmqL6HUFC7FZl9DnGmhnCQUL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14248, 'Igor', 'A cliché hunchbacked evil scientist''s assistant aspires to become a scientist himself, much to the displeasure of the rest of the evil science community.', '2008-09-19', 6.07, 'https://image.tmdb.org/t/p/w500/mI4SPs0bZQm7bGVZKToC8KUsTd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14359, 'Doubt', 'In 1964 Bronx, two Catholic school nuns question the new priest''s ambiguous relationship with a troubled African-American student.', '2008-12-12', 7.21, 'https://image.tmdb.org/t/p/w500/9lypT2ghNuUPYVJf66oe4fKvUqI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14361, 'Captain Ron', 'When mild-mannered Martin Harvey finds out that he has inherited a vintage yacht, he decides to take his family on a Caribbean vacation to retrieve the vessel. Upon arriving on a small island and realizing that the ship is in rough shape, Martin and his family end up with more than they bargained for as the roguish Captain Ron signs on to sail the boat to Miami. It doesn''t take long before Ron''s anything-goes antics get the Harveys into plenty of trouble.', '1992-09-18', 5.59, 'https://image.tmdb.org/t/p/w500/otnKFXvqFH2swlrNf2sNiXpnIsR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14367, 'Adventures in Babysitting', 'When plans with her boyfriend fall through, high school senior Chris Parker ends up babysitting the Anderson kids, Brad and Sara. What should be a quiet night in, however, turns into a series of ridiculous exploits, starting when they leave the house to pick up Chris'' friend Brenda. Soon, Brad''s buddy Daryl is involved, and the group must contend with car thieves, blues musicians and much more.', '1987-07-01', 6.86, 'https://image.tmdb.org/t/p/w500/8QiAj0Xw2UMeZMIIfZKeNoIsszs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14271, 'Beyond the Mat', 'A heartfelt documentary focusing on the day-to-day lives of professional wrestlers, some on the rise, some on the wane, and others fighting for their lives.', '1999-10-22', 7.30, 'https://image.tmdb.org/t/p/w500/48AfKc79mpRcavpA5Hc7UW9Qqq6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14117, 'Calamity Jane', 'Sharpshooter Calamity Jane takes it upon herself to recruit a famous actress and bring her back to the local saloon, but jealousy soon gets in the way.', '1953-11-04', 7.00, 'https://image.tmdb.org/t/p/w500/bYeTi8t6Gtbck861Pm9XtE3BdpS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14118, 'Dedication', 'A modern love story in which a misanthropic, emotionally complex author of a hit children''s book is forced to team with a beautiful illustrator after his best friend and collaborator passes away. As Henry struggles with letting go of the ghosts of love and life, he discovers that sometimes you have to take a gamble at life to find love.', '2007-08-24', 6.38, 'https://image.tmdb.org/t/p/w500/w0kzH6zMTOtvEDY9LVYAQxwZx7l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14365, 'Killing Me Softly', 'A woman grows suspicious of her controlling husband after she discovers secrets about the women in his past.', '2002-05-10', 5.60, 'https://image.tmdb.org/t/p/w500/pgfFJw7mqAmJdZizrJ6oOK0ejOZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14256, 'Winter Passing', 'Actress Reese Holden has been offered a small fortune by a book editor if she can secure for publication the love letters that her father, a reclusive novelist, wrote to her mother, who has since passed away. Returning to Michigan, Reese finds that an ex-grad student and a would-be musician have moved in with her father, who cares more about his new friends than he does about his own health and well-being.', '2006-02-07', 6.04, 'https://image.tmdb.org/t/p/w500/uNAiNCHd7015BzeNggoRiTT4abf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14267, 'Female Trouble', 'Teenage delinquent Dawn Davenport, incensed after her parents do not give her the cha-cha heels she wanted for Christmas, runs away from home. After an illegitimate child and hairstylist husband bring her more misery, she''s enticed into a life of crime when the owners of her husband''s salon promise her fame and fortune.', '1976-02-15', 6.91, 'https://image.tmdb.org/t/p/w500/cqhIufhoORDMuFKEinV1IIYUBxD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14275, 'Hoop Dreams', 'Every school day, African-American teenagers William Gates and Arthur Agee travel 90 minutes each way from inner-city Chicago to St. Joseph High School in Westchester, Illinois, a predominately white suburban school well-known for the excellence of its basketball program. Gates and Agee dream of NBA stardom, and with the support of their close-knit families, they battle the social and physical obstacles that stand in their way. This acclaimed documentary was shot over the course of five years.', '1994-09-12', 7.59, 'https://image.tmdb.org/t/p/w500/gLzHl2XBtVwycl8DxdOXRHPm8G3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14410, 'Notorious', '"Notorious" is the story of Christopher Wallace. Through raw talent and sheer determination, Wallace transforms himself from Brooklyn street hustler (once selling crack to pregnant women) to one of the greatest rappers of all time: The Notorious B.I.G. Follow his meteoric rise to fame and his refusal to succumb to expectations - redefining our notion of "The American Dream."', '2009-01-16', 6.96, 'https://image.tmdb.org/t/p/w500/62NsZPgueSiE8y7dqtU3FSLFwYw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14136, 'The Love Bug', 'Down-on-his-luck race car driver Jim Douglas teams up with a little VW Bug that has a mind of its own, not realizing Herbie''s worth until a sneaky rival plots to steal him.', '1968-12-23', 6.57, 'https://image.tmdb.org/t/p/w500/9Lc1efdYZUZia2zsRWcUkiD1KdN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14342, 'Almost Heroes', 'Two hapless explorers lead an ill-fated 1804 expedition through the Pacific Northwest in a hopeless, doomed effort to reach the Pacific Ocean before Lewis and Clark.', '1998-05-29', 5.46, 'https://image.tmdb.org/t/p/w500/kwZoIxl1RlsM0utYGt04CM20Kk9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14423, 'First Sunday', 'Durell and LeeJohn are best friends and bumbling petty criminals. When told they have one week to pay a $17,000 debt or Durell will lose his son, they come up with a desperate scheme to rob their neighborhood church. Instead, they end up spending the night in the presence of the Lord and are forced to deal with much more than they bargained for.', '2008-01-11', 5.62, 'https://image.tmdb.org/t/p/w500/9l0sdc7ohLe6TdFsYyCTBnVn1F8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14369, 'Out Cold', 'Rick Rambis and his friends are having the time of their lives on Bull Mountain—until the legendary Papa Muntz'' son decides to sell the mountain to a sleazy land developer, have the staff fired and turn Bull Mountain into ''Yuppieville''.', '2001-11-21', 5.88, 'https://image.tmdb.org/t/p/w500/2aBepBnMXRs3hmde9Je3rn5bseJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14429, 'Drive Me Crazy', 'Nicole and Chase live next door to each other but are worlds apart. However, they plot a scheme to date each other in order to attract the interest and jealousy of their respective romantic prey. But in the mist of planning a gala centennial celebration, Nicole and Chase find that the one they always wanted was closer than they ever thought.', '1999-10-01', 6.60, 'https://image.tmdb.org/t/p/w500/qq2jbAOw5yWTaSPJIRHxvTf0bND.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14140, 'Herbie Goes to Monte Carlo', 'Herbie, the Volkswagen Beetle with a mind of its own, is racing in the Monte Carlo Rally. But thieves have hidden a cache of stolen diamonds in Herbie''s gas tank, and are now trying to get them back.', '1977-06-24', 5.92, 'https://image.tmdb.org/t/p/w500/4gMplOTJWAj1oNrv0QJG6SGhBNQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14430, 'Herod''s Law', 'In the 1940s, a small Mexican town has seen its last three mayors assassinated in rapid succession. A naive janitor is recruited to become the new mayor, and he believes he will modernize the little town and usher in a reign of peace. But the system corrupts him very quickly, and he takes to abusing his power while associating with an unscrupulous assortment of opportunists, hypocrites and criminals.', '1999-11-09', 7.97, 'https://image.tmdb.org/t/p/w500/653dXbr6dXffXG0oN8OfZGShFRP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14139, 'Timecrimes', 'A man accidentally gets into a time machine and travels back in time nearly an hour. Finding himself will be the first of a series of disasters of unforeseeable consequences.', '2007-11-01', 7.02, 'https://image.tmdb.org/t/p/w500/zdxQRP7mzczMJBwKnv8MCPRq7rQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14433, 'Zulu', 'In 1879, during the Anglo-Zulu War, man-of-the-people Lt. Chard and snooty Lt. Bromhead are in charge of defending the isolated and vastly outnumbered Natal outpost of Rorke''s Drift from tribal hordes.', '1964-01-22', 7.40, 'https://image.tmdb.org/t/p/w500/9V7tl1kIb67ZPRRNlUdy3JvqEiA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14434, 'I Think I Love My Wife', 'Richard Cooper is a married man and father of two who is just plain bored with married life. Not getting any sex from his wife, he resorts to ogling random women on the street to the point that he takes lunch late to look at them. When old crush Nikki Tru visits his office to get a reference letter, she becomes obsessed with Cooper and they begin a complicated relationship.', '2007-03-07', 5.33, 'https://image.tmdb.org/t/p/w500/lJHg7ExSTszC8ItsufcmSPeN0vW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14435, 'My Bloody Valentine', 'Ten years after a Valentine''s Day tragedy claimed the lives of five miners, Harry Warden returns for a vengeful massacre among teen sweethearts gearing up for another party.', '2009-01-16', 5.57, 'https://image.tmdb.org/t/p/w500/9biIVOMTdvv4aj4a5HClmrK5EHB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14438, 'Fireproof', 'A heroic fire captain values dedication and service to others above all else, but the most important partnership in his life, his marriage, is about to go up in smoke.', '2008-09-26', 7.69, 'https://image.tmdb.org/t/p/w500/hfoCG75j1YaNyfZGPg0rWy3nFmU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14444, 'The Rugrats Movie', 'The Pickles family welcome a new arrival, Dil, whose constant crying and need for attention quickly exhaust the other toddlers. Seeking to return the "broken" baby to the hospital, the gang embarks on a journey in a Reptar Wagon that inadvertently veers off course, leaving them stranded in a vast, dangerous forest. While facing off against escaped circus monkeys and a predatory wolf, Tommy must overcome his own resentment to protect his brother and make it back home.', '1998-11-20', 6.26, 'https://image.tmdb.org/t/p/w500/uZejGKCSd6nwfMx8U0Td37U2fTc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14442, 'Ella Enchanted', 'Ella lives in a magical world in which each child, at the moment of their birth, is given a virtuous "gift" from a fairy godmother. Ella''s so-called gift, however, is obedience. This birthright proves itself to be quite the curse once Ella finds herself in the hands of several unscrupulous characters whom she quite literally cannot disobey. Determined to gain control of her life and decisions, Ella sets off on a journey to find her fairy godmother who she hopes will lift the curse. The path, however, isn''t easy -- Ella must outwit a slew of unpleasant obstacles including ogres, giants, wicked stepsisters, elves and Prince Charmont''s evil uncle, who wants to take over the crown and rule the kingdom.', '2004-04-09', 6.48, 'https://image.tmdb.org/t/p/w500/7AyNzwSEpJEG1gBdgwRfXi1cjs8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14447, 'A Matter of Loaf and Death', 'Wallace and Gromit open a bakery, accidentally getting tied up with a murder mystery in the process. But when Wallace falls in love, Gromit is left to solve the case by himself.', '2008-12-26', 7.35, 'https://image.tmdb.org/t/p/w500/aCRoffkRpWRlArR7dAkxabaimLr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14451, 'Dead Snow', 'Eight medical students on a ski trip to Norway discover that Hitler''s horrors live on when they come face to face with a battalion of zombie Nazi soldiers intent on devouring anyone unfortunate enough to wander into the remote mountains where they were once sent to die.', '2009-01-09', 5.97, 'https://image.tmdb.org/t/p/w500/sfwVo5cZJtO8VyDWTILDt4f69IT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14456, 'Shrooms', 'A group of American teens comes to Ireland to visit a friend who takes them on a camping trip in search of the local, fabled magic mushrooms. When the psychedelics start taking hold, the panicked friends are attacked by ghostly creatures; but how can they determine whether what they are experiencing is reality or hallucination?', '2007-08-16', 4.88, 'https://image.tmdb.org/t/p/w500/pU4lcKfjf0U8pM036FHyoVGLev7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14458, 'Altered', 'Fifteen years ago, five men were abducted by aliens. Only four returned. Now, these same four men have managed to capture one of the creatures who killed their friend and ruined their lives.', '2006-12-19', 5.46, 'https://image.tmdb.org/t/p/w500/dhUA9wCbuZAdl1Nhq4bkwyZKst5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14462, 'The Manchurian Candidate', 'Years after his squad was ambushed during the Gulf War, Major Ben Marco finds himself having terrible nightmares. He begins to doubt that his fellow squad-mate Sergeant Raymond Shaw, now a vice-presidential candidate, is the hero he remembers him being. As Marco''s doubts deepen, Shaw''s political power grows, and, when Marco finds a mysterious implant embedded in his back, the memory of what really happened begins to return.', '2004-07-30', 6.49, 'https://image.tmdb.org/t/p/w500/4xEWtEbKK2EXMZ8UPff8hDCSiVW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14460, 'Battle Beyond the Stars', 'A young farmer assembles a band of diverse mercenaries to defend his peaceful planet from an evil tyrant.', '1980-09-08', 5.40, 'https://image.tmdb.org/t/p/w500/2PKjoWF8Y46lYjPDS2ARgNAnzC0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14144, 'Daddy Day Camp', 'Seeking to offer his son the satisfying summer camp experience that eluded him as a child, the operator of a neighborhood daycare center opens his own camp, only to face financial hardship and stiff competition from a rival camp.', '2007-08-08', 4.89, 'https://image.tmdb.org/t/p/w500/fhuhSVb3j8SShe6FhnVUAfSRg6h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14474, 'The Oh in Ohio', 'Frustrated with their relationship, Priscilla and Jack decide to take a break. While Jack moves into a new place of his own and starts dating a student, Priscilla discovers the joys of self-pleasuring and finds an unusual bedmate.', '2006-03-30', 5.28, 'https://image.tmdb.org/t/p/w500/4R2wqT72RApomtBnfYG4BUpyoGh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14484, 'Body Shots', 'The Los Angeles club scene is a place of booze-fueled decadence and debauchery. In a night full of possibilities, eight 20-somethings take to the clubs seeking good times, companionship and maybe a little sex. But in the harsh light of the morning after, their worlds are thrown into a spin of confusion when hungover Sara accuses hard-partying Mike of date rape. Loyalties are tested as each among them is forced to take sides.', '1999-10-07', 4.91, 'https://image.tmdb.org/t/p/w500/1YihuAszdbPMPxK7k46UYLdP1mz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14510, 'From Beyond', 'The Resonator, a powerful machine that can control the sixth sense, has killed its creator and sent his associate into an insane asylum. When a psychiatrist becomes determined to continue the experiment, she unwittingly opens the door to a hostile parallel universe.', '1986-10-24', 6.48, 'https://image.tmdb.org/t/p/w500/zwmyxaKzIRLD4iUqZAQW940omdm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14517, 'MirrorMask', 'In a fantasy world of opposing kingdoms, a 15-year old girl must find the fabled MirrorMask in order to save the kingdom and get home.', '2005-01-25', 6.44, 'https://image.tmdb.org/t/p/w500/itIJU3NKbdgScA1WPIxXzOlm0Uj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14268, 'Startup.com', 'Friends since high school, 20-somethings Kaleil Isaza Tuzman and Tom Herman have an idea: a Web site for people to conduct business with municipal governments. This documentary tracks the rise and fall of govWorks.com from May of 1999 to December of 2000, and the trials the business brings to the relationship of these best friends. Kaleil raises the money, Tom''s the technical chief. A third partner wants a buy out; girlfriends come and go; Tom''s daughter needs attention. And always the need for cash and for improving the site. Venture capital comes in by the millions. Kaleil is on C-SPAN, CNN, and magazine covers. Will the business or the friendship crash first?', '2001-01-21', 6.71, 'https://image.tmdb.org/t/p/w500/ognPQebXUCRfKwAyRodR0j0xLjd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14522, 'Black Beauty', 'The fates of horses, and the people who own and command them, are revealed as Black Beauty narrates the circle of his life.', '1994-07-29', 6.72, 'https://image.tmdb.org/t/p/w500/5uH60FBDPQoyAnc4uvU0fIB8JXv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14279, 'My Kid Could Paint That', 'A look at the work and surprising success of a four-year-old girl whose paintings have been compared to the likes of Picasso and has raked in hundreds of thousands of dollars.', '2007-10-05', 6.97, 'https://image.tmdb.org/t/p/w500/wJiYxHp3aqFbq3LOSLK8qM6EIp8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14537, 'Harakiri', 'Down-on-his-luck veteran Tsugumo Hanshirō enters the courtyard of the prosperous House of Iyi. Unemployed, and with no family, he hopes to find a place to commit seppuku—and a worthy second to deliver the coup de grâce in his suicide ritual. The senior counselor for the Iyi clan questions the ronin’s resolve and integrity, suspecting Hanshirō of seeking charity rather than an honorable end. What follows is a pair of interlocking stories which lay bare the difference between honor and respect, and promises to examine the legendary foundations of the Samurai code.', '1962-09-15', 8.50, 'https://image.tmdb.org/t/p/w500/zK7HsOC7QxW1ldKIeFG8YJ5F2Eb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14358, 'Mad Hot Ballroom', 'Eleven-year-old New York City public school kids journey into the world of ballroom dancing and reveal pieces of themselves and their world along the way. Told from their candid, sometimes humorous perspectives, these kids are transformed, from reluctant participants to determined competitors, from typical urban kids to "ladies and gentlemen," on their way to try to compete in the final citywide competition.', '2005-05-13', 6.72, 'https://image.tmdb.org/t/p/w500/1wDU19PTEdR30QdnLFw93scXto7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14544, 'Roll Bounce', 'In the summer of 1978, a teenager and his group of friends face new challenges when their neighborhood roller-skating rink closes, forcing them to visit a different rink.', '2005-09-23', 6.79, 'https://image.tmdb.org/t/p/w500/lStFr3EHTNbnyOdOk2QDCqYGnlR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14551, 'Winchester ''73', 'Lin McAdam rides into town on the trail of Dutch Henry Brown, only to find himself in a shooting competition against him. McAdam wins the prize, a one-in-a-thousand Winchester rifle, but Dutch steals it and leaves town. McAdam follows, intent on settling his old quarrel, while the rifle keeps changing hands and touching a number of lives.', '1950-07-06', 7.29, 'https://image.tmdb.org/t/p/w500/rqRgjWqSmK9oI6duvigPmn49aVG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14554, 'Bad Day at Black Rock', 'One-armed war veteran John J. Macreedy steps off a train at the sleepy little town of Black Rock.  Once there, he begins to unravel a web of lies, secrecy, and murder.', '1955-01-13', 7.29, 'https://image.tmdb.org/t/p/w500/8EnhHjU0DyCckmZRtn46s3WXeEf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14556, 'Anything for Her', 'Lisa and Julien are married and lead a happy uneventful life with their son Oscar. But their life radically changes one morning, when the police comes to arrest Lisa on murder charges. She''s sentenced to 20 years of prison. Convinced of his wife''s innocence, Julien decides to act. How far will he be willing to go for her?', '2008-12-03', 6.96, 'https://image.tmdb.org/t/p/w500/jYqFLb9d2dfJjIix7PCKoDqdbw6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14373, 'Death Wish II', 'Paul Kersey is again a vigilante trying to find five punks who murdered his housekeeper and daughter in Los Angeles.', '1982-02-20', 6.24, 'https://image.tmdb.org/t/p/w500/lt91fEbThol6K8JDW6jFgPgxCjN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14273, 'Dark Days', 'A cinematic portrait of the homeless population who live permanently in the underground tunnels of New York City.', '2000-08-30', 7.30, 'https://image.tmdb.org/t/p/w500/vBUU6cphXFQqGq9fgk1VZ4dfnZX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14282, 'Ninja Scroll', 'Jubei is a masterless ninja who travels the land alone, lending his services to those with gold—or a worthy cause. His fearsome abilities have served him well, but a plot to overthrow the government threatens to end his wandering ways—and possibly his life.', '1993-06-05', 7.79, 'https://image.tmdb.org/t/p/w500/qzZEnaXwv4wss2QalEo4Uf9BAwh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14280, 'Never Cry Wolf', 'A scientific researcher, sent on a government study: The Lupus Project, must investigate the possible "menace" of wolves in the north. To do so, he must survive in the wilderness for six months on his own. In the course of these events, he learns about the true beneficial and positive nature of the wolf species.', '1983-10-07', 6.99, 'https://image.tmdb.org/t/p/w500/e61tGxVtobTQuFPmAC7xWwdC4O1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14506, 'The Adventures of Baron Munchausen', 'An account of Baron Munchausen''s supposed travels and fantastical experiences with his band of misfits.', '1988-12-07', 6.99, 'https://image.tmdb.org/t/p/w500/oiOwGRqwrKpg1EMUlPgRjVC49bn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14370, 'Real Genius', 'When teenage geniuses Mitch Taylor and Chris Knight, working on an advanced laser project, learn that the military wants to use it as a weapon, they decide to thwart the plan.', '1985-08-07', 6.67, 'https://image.tmdb.org/t/p/w500/8az0Tr8hEGDmrUH9WlFz1QIKsMy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14577, 'Dirty Work', 'Unemployed and recently dumped, Mitch and his buddy Sam start a revenge-for-hire business to raise the $50,000 that Sam''s father needs to get a heart transplant.', '1998-06-12', 6.21, 'https://image.tmdb.org/t/p/w500/r6OcS6TQCHal2wHooJhHWSlFzfd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14389, 'Danny Deckchair', 'An unappreciated laborer''s patience reaches breaking point when his girlfriend cancels a romantic holiday. Making light of the situation, he decides to tie hundreds of helium balloons to a chair in an outlandish bid to float to a new life.', '2003-05-16', 6.08, 'https://image.tmdb.org/t/p/w500/7rL1WDYxTIPouUFDbdtcyqTyywu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14557, 'Dead Man on Campus', 'Two college roommates venture out to identify a fellow student, who is most likely to commit suicide as it will help them pass the semester.', '1998-08-21', 5.52, 'https://image.tmdb.org/t/p/w500/mTr7ARy7lj8ggvg6snLWDo3CnEu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14278, 'Murderball', 'Quadriplegics, who play full-contact rugby in wheelchairs, overcome unimaginable obstacles to compete in the Paralympic Games in Athens, Greece.', '2005-07-22', 7.08, 'https://image.tmdb.org/t/p/w500/qxaXzZnGsHaAJpSaF72nDhhL58n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14585, 'In the Company of Men', 'Two business executives--one an avowed misogynist, the other recently emotionally wounded by his love interest--set out to exact revenge on the female gender by seeking out the most innocent, uncorrupted girl they can find and ruining her life.', '1997-03-28', 6.73, 'https://image.tmdb.org/t/p/w500/1gPJ4H4TbGAiuEA6pFalFtqA0eL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
