INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14588, 'After the Thin Man', 'Nick and Nora Charles investigate when Nora''s cousin reports her disreputable husband is missing, and find themselves in a mystery involving the shady owners of a popular nightclub, a singer and her dark brother, the cousin''s forsaken true love, and Nora''s bombastic and controlling aunt.', '1936-12-25', 7.33, 'https://image.tmdb.org/t/p/w500/1fkCHOffEkPOY0UwSrvzG6YKDVp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14589, 'Another Thin Man', 'Not even the joys of parenthood can stop married sleuths Nick and Nora Charles from investigating a murder on a Long Island estate.', '1939-11-17', 7.12, 'https://image.tmdb.org/t/p/w500/zmOjn9qg9Cun7P9YAKr5ajNZBcK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14590, 'Shadow of the Thin Man', 'High society sleuths Nick and Nora Charles run into a variety of shady characters while investigating a race-track murder.', '1941-11-21', 6.98, 'https://image.tmdb.org/t/p/w500/sYiasULoMJj84A5zheNyChGuhHY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14407, 'Guy X', 'A black comedy set in 1979, about a soldier mistakenly posted to an Arctic military base.', '2005-06-06', 4.68, 'https://image.tmdb.org/t/p/w500/kAruqIkf1GxYyWS03pq7NKdp6dC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14594, 'The Thin Man Goes Home', 'On a trip to visit his parents, detective Nick Charles gets mixed up in a murder investigation.', '1944-12-24', 7.09, 'https://image.tmdb.org/t/p/w500/xKnTU1LOeRU8AubY2LO5lGRiPpv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14595, 'Song of the Thin Man', 'Society sleuths Nick and Nora Charles investigate a murder in a jazz club.', '1947-08-28', 6.73, 'https://image.tmdb.org/t/p/w500/wlj6IQrYRtHAQdIY08gicGOBp49.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14603, 'Kuffs', 'George Kuffs didn''t finish high-school, just lost his job, and his college-age girlfriend is pregnant. To top it off, George''s brother Brad is killed and George inherits Brad''s "patrol special" privatized police district and all the problems that come with it.', '1992-01-10', 5.76, 'https://image.tmdb.org/t/p/w500/mF0eKbtnPxMVTPiLeKquUziMW06.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14609, 'Ultimate Avengers: The Movie', 'When a nuclear missile was fired at Washington in 1945, Captain America managed to detonate it in the upper atmosphere. But then he fell miles into the icy depths of the North Atlantic, where he remained lost for over sixty years. But now, with the world facing the very same evil, Captain America must rise again as our last hope for survival.', '2006-02-21', 6.87, 'https://image.tmdb.org/t/p/w500/iMCkGHVrYRdqKROPRPmVaJVSlg3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14521, 'The Cup', 'While the World Cup is being played in France, two young Tibetan refugees arrive at a monastery in India. The atmosphere of serene contemplation is soon disrupted by soccer fever, as the two students desperately seek a TV to watch the final.', '1999-10-28', 6.56, 'https://image.tmdb.org/t/p/w500/8yh2Pj4o92sF4ceTvzB5qP9szUy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14398, 'Gang Related', 'After murdering an undercover DEA agent, two corrupt cops scramble to cover up what they''ve done.', '1997-10-08', 6.38, 'https://image.tmdb.org/t/p/w500/zvl4RYK5OHo2d9V1aUkHkxhh9Zv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14611, 'Ultimate Avengers 2', 'Mysterious Wakanda lies in the darkest heart of Africa, unknown to most of the world. An isolated land hidden behind closed borders, fiercely protected by its young king: Black Panther. But when brutal alien invaders attack, the threat leaves Black Panther with no option but to go against the sacred decrees of his people and ask for help from outsiders.', '2006-08-08', 6.81, 'https://image.tmdb.org/t/p/w500/sMFyYZR9krqcQC99G6jnb10Zv4P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14612, 'Candleshoe', 'When ex-con artist Harry claims that a secret treasure is hidden inside Candleshoe, an English estate, he creates an elaborate plan to find and steal the prize. By convincing a girl named Casey to impersonate the estate owner''s long-lost granddaughter, Harry hopes to uncover the treasure''s location. But when Casey has a change of heart, she must follow the clues and find the treasure, in order to save Candleshoe and stop Harry before it is too late.', '1977-12-16', 6.86, 'https://image.tmdb.org/t/p/w500/6Rq9u5fnS6PzWz9dgPQmBhgDvRJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14615, 'Fury', 'Joe, who owns a gas station along with his brothers and is about to marry Katherine, travels to the small town where she lives to visit her, but is wrongly mistaken for a wanted kidnapper and arrested.', '1936-06-05', 7.50, 'https://image.tmdb.org/t/p/w500/u1kjLTUqmqjDMlRxcwCqWagjf6r.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14623, 'Thunderbirds', 'Dangerous missions are the bread and butter of the Thunderbirds, a high-tech secret force employed by the government. Led by Jeff Tracy (Bill Paxton), the Thunderbirds are at the top of their game, but their nemesis, The Hood (Ben Kingsley), has landed on their island and is attempting a coup by using the team''s rescue vehicles. He''ll soon discover that the Thunderbirds won''t go down.', '2004-07-23', 5.04, 'https://image.tmdb.org/t/p/w500/1jH0vADEIvuRlkvJzLUW5nVO96d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14621, 'Lean On Me', 'When principal Joe Clark takes over decaying Eastside High School, he''s faced with students wearing gang colors and graffiti-covered walls. Determined to do anything he must to turn the school around, he expels suspected drug dealers, padlocks doors and demands effort and results from students, staff and parents. Autocratic to a fault, this real-life educator put it all on the line.', '1989-03-03', 7.30, 'https://image.tmdb.org/t/p/w500/7xOyz2NlaoqZ6xIjJh0Goptm0tP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14628, 'Fletch Lives', 'Fletch is a fish out of water in small-town Louisiana, where he''s checking out a tumbledown mansion he''s inherited. When a woman he flirts with turns up dead, he becomes a suspect and must find the killer and clear his name.', '1989-03-17', 6.01, 'https://image.tmdb.org/t/p/w500/A30iCFQVKXvQzGHEE4hyVC0QtrD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14635, 'The Rookie', 'Jim Morris never made it out of the minor leagues before a shoulder injury ended his pitching career twelve years ago. Now a married-with-children high-school chemistry teacher and baseball coach in Texas, Jim''s team makes a deal with him: if they win the district championship, Jim will try out with a major-league organization. The bet proves incentive enough for the team, and they go from worst to first, making it to state for the first time in the history of the school. Jim, forced to live up to his end of the deal, is nearly laughed off the try-out field--until he gets onto the mound, where he confounds the scouts (and himself) by clocking successive 98 mph fastballs, good enough for a minor-league contract with the Tampa Bay Devil Rays. Jim''s still got a lot of pitches to throw before he makes it to The Show, but with his big-league dreams revived, there''s no telling where he could go.', '2002-03-25', 6.81, 'https://image.tmdb.org/t/p/w500/gNmLsseIs6thkBKne91iQZDGyBT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14638, 'The Killers', 'Two hit men walk into a diner asking for a man called "the Swede". When the killers find the Swede, he''s expecting them and doesn''t put up a fight. Since the Swede had a life insurance policy, an investigator, on a hunch, decides to look into the murder. As the Swede''s past is laid bare, it comes to light that he was in love with a beautiful woman who may have lured him into pulling off a bank robbery overseen by another man.', '1946-08-30', 7.37, 'https://image.tmdb.org/t/p/w500/uXnuc6pW01s1MDwb6QwBWg2JQeX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14645, 'Santa Claus Is a Stinker', 'Two neurotics, working for a suicide hotline on the night of Christmas Eve, get caught up in a catastrophe when a pregnant woman, her abusive boyfriend, and a cross-dresser visit their office.', '1982-08-25', 7.32, 'https://image.tmdb.org/t/p/w500/z86yqhtqmNxQN214OK4PUDbpBOq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14629, 'Woman on Top', 'Set to the intoxicating rhythms of Brazil, "Woman on Top" is a spicy, sexy comedy about the magic of food, love and music. Meet Isabella, a sultry enchantress born with the special gift of melting the palates and hearts of men everywhere. When she decides to break free from her rocky marriage and the stifling kitchen of her husband''s restaurant in Brazil, she spirits off to San Francisco in pursuit of her dreams of a real culinary career.', '2000-09-22', 6.06, 'https://image.tmdb.org/t/p/w500/eYHvcMeVjWPwATYI0VCdecMy2n3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14662, 'Slums of Beverly Hills', 'In 1976, a teenage girl struggles to cope while living with her neurotic lower-middle-class family of nomads on the outskirts of Beverly Hills.', '1998-08-14', 6.31, 'https://image.tmdb.org/t/p/w500/bTY6I0Mju4vTRHGoTZrNtxtAlAO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14651, 'My Wife Is an Actress', 'A "normal" guy who is married to a hot actress gets worried that she is involved with her costar. This worry turns into jealousy and causes problems in their relationship. This is a story about trust and a comedy about the actions between men and women.', '2001-11-14', 6.10, 'https://image.tmdb.org/t/p/w500/1PdxR0RXVKs7PVzaTpxnBJV3Ijv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14578, 'Outside Providence', 'In this coming-of-age comedy, Tim Dunphy is leading a go-nowhere existence, spending his days smoking pot and hanging out with his best friend, Drugs Delaney. But Tim''s lazy days of getting high are jettisoned after a brush with the law convinces his blue-collar dad to send him to a Connecticut prep school. The one saving grace of the new school is Jane, a fellow student Tim falls for immediately.', '1999-09-01', 5.89, 'https://image.tmdb.org/t/p/w500/xSqewkFWR0zs7OkXLOd10VnxFPN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14670, '''Round Midnight', 'Inside the Blue Note nightclub one night in 1959 Paris, an aged, ailing jazzman coaxes an eloquent wail from his tenor sax. Outside, a young Parisian too broke to buy a glass of wine strains to hear those notes. Soon they will form a friendship that sparks a final burst of genius.', '1986-09-23', 7.05, 'https://image.tmdb.org/t/p/w500/8aNGnEsvLBldNvaBkfYkGGgZDhe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14560, 'Paul Blart: Mall Cop', 'When a shopping mall is taken over by a gang of organized crooks, it''s up to a mild-mannered security guard to save the day.', '2009-01-15', 5.45, 'https://image.tmdb.org/t/p/w500/A4zZv0Q1VKURFZFEl2vwjaE2q0g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14675, 'The Awful Truth', 'Unfounded suspicions lead a married couple to begin divorce proceedings, whereupon they start undermining each other''s attempts to find new romance.', '1937-10-21', 7.21, 'https://image.tmdb.org/t/p/w500/2VtsJoxvjpcMpwh0gweS8IMfHxO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14405, 'Beverly Hills Chihuahua', 'A pampered Beverly Hills chihuahua named Chloe who, while on vacation in Mexico with her owner Viv''s niece, Rachel, gets lost and must rely on her friends to help her get back home before she is caught by a dognapper who wants to ransom her.', '2008-10-03', 5.38, 'https://image.tmdb.org/t/p/w500/2aRvqtLoE06hTjG93lASvO7r1as.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14698, 'Suddenly, Last Summer', 'The only son of wealthy widow Violet Venable dies while on vacation with his cousin Catherine. What the girl saw was so horrible that she went insane; now Mrs. Venable wants Catherine lobotomized to cover up the truth.', '1959-12-22', 7.30, 'https://image.tmdb.org/t/p/w500/igma0zn9J5srRvOMDRnxyUDQXJL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14533, 'Gia', 'Gia Carangi meteorically rises to modeling fame in the late 1970s but becomes overconsumed by persistent loneliness and drug addiction.', '1998-09-22', 7.10, 'https://image.tmdb.org/t/p/w500/oFi5OIvBf59W1KFaN0cuiMEEbs1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14703, 'The Night of the Iguana', 'A defrocked Episcopal clergyman leads a bus-load of middle-aged Baptist women on a tour of the Mexican coast and comes to terms with the failure haunting his life.', '1964-08-06', 7.16, 'https://image.tmdb.org/t/p/w500/3HY8MSeoj4s0uSWGW135Jlh7eSI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14411, 'Sinbad: Legend of the Seven Seas', 'The sailor of legend is framed by the goddess Eris for the theft of the Book of Peace, and must travel to her realm at the end of the world to retrieve it and save the life of his childhood friend Prince Proteus.', '2003-07-02', 7.06, 'https://image.tmdb.org/t/p/w500/yiW2L1fDiBT7AeWXrykhTNtPrr8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14571, 'Patlabor: The Movie', 'A mysterious suicide and a series of unmanned robot run-aways sparks off a Police investigation into the suspicious software on-board thousands of industrial robots around Tokyo.', '1989-07-15', 6.94, 'https://image.tmdb.org/t/p/w500/dp3CNNo7Oj704cQKiwM4MJqlW0I.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14534, 'Rudy', 'Rudy grew up in a steel mill town where most people ended up working, but wanted to play football at Notre Dame instead. There were only a couple of problems. His grades were a little low, his athletic skills were poor, and he was only half the size of the other players. But he had the drive and the spirit of 5 people and has set his sights upon joining the team.', '1993-09-17', 7.34, 'https://image.tmdb.org/t/p/w500/fAbfTCRpjHe2rprXBly55KL1dL9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14412, 'Body Heat', 'During an extreme heatwave, a beautiful Florida woman and a seedy lawyer engage in an affair while plotting the murder of her rich husband.', '1981-08-28', 6.98, 'https://image.tmdb.org/t/p/w500/5LipPcaW1J9IjAP7TOTesw8OcMS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14667, 'Dogfight', 'In the fall of 1963, Eddie Birdlace is an 18-year-old Marine Corps volunteer who is about to ship out with three of his buddies for a tour of duty in Vietnam. Planning a massive blowout for their last night in San Francisco, Eddie, his buddies, and a number of other Marines set up a contest they call a "dogfight”.', '1991-10-04', 6.90, 'https://image.tmdb.org/t/p/w500/1sEJy723hW629jzzX8H5k5MTVMq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14550, 'The Dream Team', 'Four mental patients on a field trip in New York City must save their caring chaperone, who ends up being taken to a hospital in a coma after accidentally witnessing a murder, before the killers can find him and finish the job.', '1989-04-07', 6.13, 'https://image.tmdb.org/t/p/w500/lBVjTP8Cb66GBabUBQaBUtV6OqD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14748, 'Boy A', 'Freed after a lengthy term in a juvenile detention center, convicted child killer Jack Burridge finds work as a deliveryman and begins dating co-worker Michelle. While out on the road one day, Jack notices a distressed child, and, after reuniting the girl with her family, becomes a local celebrity. But when a local newspaper unearths his past, Jack must cope with the anger of citizens who fear for the safety of their children.', '2008-07-23', 7.09, 'https://image.tmdb.org/t/p/w500/wrQQUjeiHFPvTfaaB3vtNLLZ8kv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14574, 'The Boy in the Striped Pyjamas', 'When his family moves from their home in Berlin to a strange new house in Poland, young Bruno befriends Shmuel, a boy who lives on the other side of the fence where everyone seems to be wearing striped pajamas. Unaware of Shmuel''s fate as a Jewish prisoner or the role his own Nazi father plays in his imprisonment, Bruno embarks on a dangerous journey inside the camp''s walls.', '2008-05-07', 7.82, 'https://image.tmdb.org/t/p/w500/2C8QCXdMlojTxZjfBlINr4FWcb6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14749, 'Space Buddies', 'B-Dawg, Mudbud, Budderball, and all the rest of the Buddies are back, but this time, they''re setting their sights even higher -- as in, the moon! With the help of their new pals Spudnick and Gravity, these pooches are go for launch. But to pull off their moon landing and make it home safely, our canine heroes will have to summon all their bravery and imagination...', '2009-02-02', 5.86, 'https://image.tmdb.org/t/p/w500/8C0u4EuisSRBa3Htr9kWUStkDnW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14750, 'Mischief', '1956: The shy Jonathan''s luck with girls changes when he wins the rebellious Gene as a friend in his last year of high school. Gene is adored by many girls and manages to teach Jonathan a few lessons. Gene himself would rather just be with one girl: his girlfriend Bunny. But since his father is poor, her parents don''t accept him.', '1985-02-08', 6.65, 'https://image.tmdb.org/t/p/w500/ejZ2AUQKnKiSoLegCQXT2Rdjm7r.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14756, 'Ip Man', 'A semi-biographical account of Yip Man, the first martial arts master to teach the Chinese martial art of Wing Chun. The film focuses on events surrounding Ip that took place in the city of Foshan between the 1930s to 1940s during the Second Sino-Japanese War. Directed by Wilson Yip, the film stars Donnie Yen in the lead role, and features fight choreography by Sammo Hung.', '2008-12-12', 7.76, 'https://image.tmdb.org/t/p/w500/9bUIrDKnesNbBL1nAl1nt7gtocE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14425, 'PCU', 'Nervous high school senior Tom Lawrence visits Port Chester University, where he gets a taste of politically correct college life when he''s guided by fraternity wild man Droz and his housemates at The Pit. But Droz and his pals have rivals in nasty preppy Rand McPherson and the school''s steely president. With their house threatened with expulsion, Droz and company decide to throw a raging party where the various factions will collide.', '1994-04-29', 6.03, 'https://image.tmdb.org/t/p/w500/xTToUzy9Im9nu2W8fz7TPWoDWN5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14757, 'Osama', 'After the rise of the Taliban in Afghanistan and the restriction of women in public life, a preteen girl is forced to masquerade as a boy in order to find work to support her mother and grandmother.', '2004-03-24', 7.00, 'https://image.tmdb.org/t/p/w500/pOKz4zpccIjdib2pfDRkg69Ojej.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14671, 'Summer School', 'A high-school gym teacher has big plans for the summer, but is forced to cancel them to teach a "bonehead" English class for misfit goof-off students. Fortunately, his unconventional brand of teaching fun field trips begins to connect with them, and even inspires ardor in some.', '1987-07-22', 6.40, 'https://image.tmdb.org/t/p/w500/s1Ad6q0XnVS6u1yoaYghHw5dskv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14774, 'Cheech & Chong''s The Corsican Brothers', 'Two brothers who can feel each others'' pain and pleasure mess up the French revolution.', '1984-07-27', 4.90, 'https://image.tmdb.org/t/p/w500/vB186e2eiUaKLVlZwvKv4dIJ9GS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14761, 'Cocaine Cowboys', 'In the 1980s, ruthless Colombian cocaine barons invaded Miami with a brand of violence unseen in this country since Prohibition-era Chicago - and it put the city on the map. "Cocaine Cowboys" is the true story of how Miami became the drug, murder and cash capital of the United States, told by the people who made it all happen.', '2006-11-03', 7.29, 'https://image.tmdb.org/t/p/w500/gxGis0HgcLJv2MS3l01a0wuhCAI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14771, 'The Onion Movie', 'Venerable newscaster Norm Archer reports the latest news in politics, health, culture and entertainment - such as an automotive recall of decapitation-inducing "Neckbelts" and a study finding that "depression hits losers hardest". This compilation of bogus news stories, celebrity profiles, movie trailers and skits come courtesy of the ace satirists at The Onion.', '2008-05-31', 6.14, 'https://image.tmdb.org/t/p/w500/AikMOGbaKpCzHnupsdBzyacsKC2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14776, 'How to Get Ahead in Advertising', 'Pressure from his boss and a skin-cream client produces a talking boil on a British adman''s neck.', '1989-05-05', 6.28, 'https://image.tmdb.org/t/p/w500/8T1UacG5YV063PDbaHH2RaqA6Wc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14778, 'Last Orders', 'Jack Dodd was a London butcher who enjoyed a pint with his mates for over 50 years. When he died, he died as he lived, with a smile on his face watching a horse race on which he had bet, with borrowed money. But before he died he had a final request, ''Last Orders'', that his ashes be scattered in the sea at Margate. The movie follows his mates, Ray, Lenny and Vic and his foster son Vince as they journey to the sea with the ashes. Along the way, the threads of their lives, their loves and their disappointments are woven together in their memories of Jack and his wife Amy', '2001-09-10', 6.00, 'https://image.tmdb.org/t/p/w500/rcc3eL3wcydEUmXpX1tW9ro8NR9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14786, 'Gotti', 'John Gotti, the head of a small New York mafia crew breaks a few of the old family rules. He rises to become the head of the Gambino family and the most well-known mafia boss in America. Life is good, but suspicion creeps in, and greed, rule-breaking and his high public profile all threaten to topple him.', '1996-08-17', 6.55, 'https://image.tmdb.org/t/p/w500/4ZeKN0jnXHlyloMFba1Xe4C1ell.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14793, 'Heima', 'Ethereal post-rock pioneers Sigur Rós play a string of impromptu gigs in their native Iceland after finishing a world tour in 2006. As they travel through the country, the band visits a wide variety of venues, from a large outdoor festival to a coffee shop.', '2007-09-27', 7.69, 'https://image.tmdb.org/t/p/w500/hopfH0rWbTTNYJmEb8R07f3ZUzc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14784, 'The Fall', 'In a hospital on the outskirts of 1920s Los Angeles, an injured stuntman begins to tell a fellow patient, a little girl with a broken arm, a fantastic story about 5 mythical heroes. Thanks to his fractured state of mind and her vivid imagination, the line between fiction and reality starts to blur as the tale advances.', '2006-09-09', 7.63, 'https://image.tmdb.org/t/p/w500/ez7xavvDr5yDz4sSvI55xDp0BoU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14797, 'Warriors of Heaven and Earth', 'A Chinese emissary is sent to the Gobi desert to execute a renegade soldier. When a caravan transporting a Buddhist monk and a valuable treasure is threatened by thieves, however, the two warriors might unite to protect the travelers.', '2003-09-23', 6.20, 'https://image.tmdb.org/t/p/w500/gvf2IHzIpiAMEv09pdlsniFpsm0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14687, 'Eichmann', 'Based upon the final confession of Adolf Eichmann, made before his execution in Israel, of his role in Hitler''s plan for the final solution.', '2007-09-22', 5.99, 'https://image.tmdb.org/t/p/w500/zoxl3RaZiCBmZIk3fmmw61rOV69.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14805, 'Bait', 'Landing in jail for a petty theft crime, Alvin finds himself sharing a cell with John Jaster, the incarcerated half of the pair of high-tech thieves responsible for the missing gold. His partner, Bristol, is still at large. Alvin wants only to get out of prison and start fresh with his girlfriend, Lisa, and when the Feds, led by U.S. Treasury investigator Clenteen, set him loose on a sketchy deal, he thinks his luck has changed. Alvin has his freedom and the Feds have found their bait.', '2000-09-15', 5.72, 'https://image.tmdb.org/t/p/w500/jon5ux36iUn6GnntxkZaNtB6AZT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14811, 'Fiddler on the Roof', 'In a pre-revolutionary Russia, a poor Jewish milkman struggles with the challenges of a changing world as his daughters fall in love and antisemitism grows.', '1971-11-03', 7.73, 'https://image.tmdb.org/t/p/w500/v65PHx7Q6Jx0anyNeUOX07SJic9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14807, 'The Long Good Friday', 'In the late 1970s, Cockney crime boss Harold Shand, a gangster trying to become a legitimate property mogul, has big plans to get the American Mafia to bankroll his transformation of a derelict area of London into the possible venue for a future Olympic Games. However, a series of bombings targets his empire on the very weekend the Americans are in town. Shand is convinced there is a traitor in his organization, and sets out to eliminate the rat in typically ruthless fashion.', '1980-11-01', 7.19, 'https://image.tmdb.org/t/p/w500/pXS667me5Jfoj1b0xuxgjEMKunF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14799, 'For Your Consideration', 'The possibility of Oscar gold holds the cast and crew of an independent film in its grip after the performance of its virtually unknown, veteran star generates awards buzz.', '2006-11-17', 5.75, 'https://image.tmdb.org/t/p/w500/fvXClgY4ZJ7dBxalFuxPgb4nJ9s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14815, 'The Wind and the Lion', 'At the beginning of the 20th century an American woman is abducted in Morocco by Berbers, and the attempts to free her range from diplomatic pressure to military intervention.', '1975-05-22', 6.48, 'https://image.tmdb.org/t/p/w500/3QLqEZL1kBBfKjVz3nAm5vJruRZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14817, 'Good Burger', 'Two L.A. teens with summer jobs at Good Burger try to save their small restaurant when a corporate giant burger franchise moves in across the street.', '1997-07-25', 6.21, 'https://image.tmdb.org/t/p/w500/imFLUF2TYkm13GpFYTKYF7T27sP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14819, 'Heavyweights', 'Camp Hope is a summer retreat for overweight boys run by a kindly couple who make the campers feel comfortable with their extra pounds. But when tyrannical fitness guru Tony buys the camp, he puts the kids on a cruel regimen that goes too far. Sick of the endless weeks of "all work and no play," the kids stage a coup and reclaim their summer of fun.', '1995-02-17', 6.18, 'https://image.tmdb.org/t/p/w500/uN65XQzyPknLZs2R6koZ2Cu6eGC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14822, 'Return from Witch Mountain', 'Tony and Tia are other-worldly twins endowed with telekinesis. When their Uncle Bene drops them off in Los Angeles for an earthbound vacation, a display of their supernatural skill catches the eye of the nefarious Dr. Gannon and his partner in crime, Letha, who see rich possibilities in harnessing the children''s gifts. They kidnap Tony, and Tia gives chase only to find Gannon is using her brother''s powers against her.', '1978-03-10', 5.87, 'https://image.tmdb.org/t/p/w500/2bnmbL5YkqfR3OkQRzgoCf3vs4V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14831, 'Help!', 'An obscure Eastern cult that practices human sacrifice pursues Ringo after he unknowingly puts on a ceremonial ring (that, of course, won''t come off). On top of that, a pair of mad scientists, members of Scotland Yard, and a beautiful but dead-eyed assassin all have their own plans for the Fab Four.', '1965-07-29', 6.90, 'https://image.tmdb.org/t/p/w500/nLvgIB3bVb8jyhls5W6B74Xt4Ei.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14832, 'The Cement Garden', 'After the death of her husband, the mother of Julie, Jack, Sue and Tom begins to suffer from a mysterious illness. Aware that she is going to have to go into hospital she opens a bank account for the children, so that they can be financially self-sufficient and will be able to avoid being taken into care by the authorities. Unfortunately she also dies and Julie and Jack (the older, teenage children) decide to hide her body in the basement so that they can have free reign of their household. Soon Tom has taken to dressing as a girl whilst Sue has become increasingly reticent, confiding only to her diary, meanwhile Jack and Julie sense an attraction developing for each other. However Julie''s new beau, Derek, threatens to unearth the many dark secrets within this family as he becomes increasingly suspicious of Jack.', '1993-02-20', 6.73, 'https://image.tmdb.org/t/p/w500/dnEoE3tHBStCXZx2i9qsUYkwucu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14684, 'School Ties', 'When David Greene receives a football scholarship to a prestigious prep school in the 1950s, he feels pressure to hide the fact that he is Jewish from his classmates and teachers, fearing that they may be anti-Semitic. He quickly becomes the big man on campus thanks to his football skills, but when his Jewish background is discovered, his worst fears are realized and his friends turn on him with violent threats and public ridicule.', '1992-09-18', 6.50, 'https://image.tmdb.org/t/p/w500/h9u6VSyEPlF5L69QSzOh1eo4F5q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14821, 'Escape to Witch Mountain', 'Tia and Tony are two orphaned youngsters with extraordinary powers. Lucas Deranian poses as their uncle in order to get the kids into the clutches of Deranian''s megalomaniacal boss, evil millionaire Aristotle Bolt, who wants to exploit them. Jason, a cynical widower, helps Tia and Tony escape to witch mountain, while at the same time Tia and Tony help Jason escape the pain of the loss of his wife.', '1975-03-21', 6.40, 'https://image.tmdb.org/t/p/w500/cXicoCiCfO6FDfv6ozwcfQCnhVW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14844, 'Chasing Liberty', 'The President''s daughter, unable to experience life like a normal 18 year-old, escapes from her entourage of Secret Service agents while traveling in Europe. She falls in love with a handsome British stranger, who also happens to be working undercover for her father.', '2004-01-09', 6.22, 'https://image.tmdb.org/t/p/w500/aGh5zpJSuxcx4lzFFbZ2QyY8wQP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14846, 'Little Black Book', 'Determined to learn about her boyfriend''s past relationships, Stacy -- who works for a talk show -- becomes a bona fide snoop. With her colleague, Barb, Stacy gets the names of Derek''s ex-lovers and interviews them, supposedly for an upcoming show. But what she learns only adds to her confusion, and her plans begin to unravel when she befriends one of the women.', '2004-08-06', 5.35, 'https://image.tmdb.org/t/p/w500/c6TD54dLIryqhQAOdGExy8Lie1l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14863, 'Anaconda 3: Offspring', 'A mercenary-for-hire accepts a mission from a billionaire to capture a dangerous snake that could possibly help cure a terminal illness.', '2008-10-23', 4.60, 'https://image.tmdb.org/t/p/w500/3PI6dXS0UlNlB6IXnngfEtufFxm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14862, 'Killer Movie', 'A reality TV director copes with a spoiled celebutante and a show gone haywire when a masked killer starts bumping off the crew in this slasher-movie satire.', '2008-04-24', 5.58, 'https://image.tmdb.org/t/p/w500/fhZNX8SCvtrrTfh8NV5EgtZC9d0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14849, 'Dead Like Me: Life After Death', 'When George and her colleagues get a new boss whose focus is on moving souls quickly and enjoying life without consequences, the team begins to break the strict reaper rules. While her friends fall victim to their desires for money, success, and fame, George breaks another rule by revealing her true identity to her living family.', '2009-02-17', 6.37, 'https://image.tmdb.org/t/p/w500/ekzGiwleJbx0ei1R3s0ylowFKT9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14864, 'The Hot Spot', 'Upon arriving to a small town, a drifter quickly gets into trouble with the local authorities — and the local women — after he robs a bank.', '1990-10-12', 6.30, 'https://image.tmdb.org/t/p/w500/iQCP69183K1QZo8bb23nkcLap3W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14869, 'G.I. Joe: The Rise of Cobra', 'From the Egyptian desert to deep below the polar ice caps, the elite G.I. JOE team uses the latest in next-generation spy and military equipment to fight the corrupt arms dealer Destro and the growing threat of the mysterious Cobra organization to prevent them from plunging the world into chaos.', '2009-08-03', 5.78, 'https://image.tmdb.org/t/p/w500/mc9b25IAprHfsaOz0wTshOwGHcY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14873, 'The Jungle Book 2', 'Mowgli has been living in the man-village with his little stepbrother Ranjan and his best friend Shanti. But the man-cub still has that jungle rhythm in his heart, and he misses his old buddies Baloo and Bagheera. When Mowgli wanders back to the wild for some swingin'' fun, he soon finds the man-eating tiger Shere Khan is lurking in the shadows and planning his revenge.', '2003-02-07', 5.90, 'https://image.tmdb.org/t/p/w500/21GanxizOIL1CN0HLx7j3je8k87.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14886, 'The Last Detail', 'Two Navy men are ordered to bring a young offender to prison, but decide to show him one last good time along the way.', '1973-12-11', 7.02, 'https://image.tmdb.org/t/p/w500/zQoNkO99qfaBjh5aoA0pKau1prp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14892, 'The Big Empty', 'Struggling actor John Person agrees to drive a blue suitcase from Los Angeles to the small town of Baker, Calif., and hand it over to a mysterious cowboy in return for having his credit card debt of $27,000 paid off. Upon his arrival, John can''t find the cowboy but receives an ominously head-shaped package he''s supposed to hang onto. While waiting, John gets close to Ruthie, whose psychotic boyfriend, Randy, keeps threatening to kill him.', '2003-05-16', 6.08, 'https://image.tmdb.org/t/p/w500/d6q6Sy1HoeBiRPuVNXIDYLz30Wa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14902, '1776', 'Colonial representatives gather in Philadelphia with the aim of establishing a set of governmental rules for the burgeoning United States. Benjamin Franklin and John Adams charge Thomas Jefferson with the task of writing a statement announcing the new country''s emancipation from British rule.', '1972-11-09', 6.92, 'https://image.tmdb.org/t/p/w500/o50REDExdajGxTWczsmC3qcawGr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14904, 'Proof', 'Martin, a young blind photographer, is divided between his friendship with restaurant worker Andy and the exclusive love that Celia—who is terribly jealous of this new friendship—has for him.', '1991-08-15', 6.66, 'https://image.tmdb.org/t/p/w500/sDWGe24TVQOHy0ZBQ8yek4P8fZn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14900, 'The Great Muppet Caper', 'Kermit and Fozzie are newspaper reporters sent to London to interview Lady Holiday, a wealthy fashion designer whose priceless diamond necklace is stolen. Kermit meets and falls in love with her secretary, Miss Piggy. The jewel thieves strike again, and this time frame Miss Piggy. It''s up to Kermit and the rest of the Muppets to bring the real culprits to justice.', '1981-06-26', 6.94, 'https://image.tmdb.org/t/p/w500/lnJc4B4njeyNHWqG00ozuUIhtu5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14553, 'Stealing Beauty', 'Lucy Harmon, an American teenager is arriving in the lush Tuscan countryside to be sculpted by a family friend who lives in a beautiful villa. Lucy visited there four years earlier and exchanged a kiss with an Italian boy with whom she hopes to become reacquainted.', '1996-03-29', 6.70, 'https://image.tmdb.org/t/p/w500/5ugxnyVmBK952bwOcE4M0szNimx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14583, 'Deceiver', 'The gruesome death of a prostitute brings suspicion on one of her clients, James Wayland, a brilliant, self-destructive and epileptic heir to a textile fortune. So detectives Braxton and Kennesaw take Wayland in for questioning, thinking they can break the man. But despite his troubles, Wayland is a master of manipulation, and during the interrogation, he begins to turn the tables on the investigators, forcing them to reveal their own sinister sides.', '1997-08-31', 5.96, 'https://image.tmdb.org/t/p/w500/1bxBZV0KsUolu7MddTXZ0Prac3Q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14694, 'The Snow Walker', 'A bush pilot in nothern Canada who with the aid of modernity thinks he can handle it all & knows it all. After reluctantly agreeing to transport a local indian girl to a medical facility his light plane crashes & they have to survive whilst finding their way back to civilization. Along the journey the man finds a new respect for the native ways as they battle to survive the elements.', '2003-09-11', 7.00, 'https://image.tmdb.org/t/p/w500/1UlHIWfqjkizc2qem0IPZBG6nn5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14695, 'Havoc', 'A wealthy Los Angeles teen and her superficial friends wants to break out of suburbia and experience Southern California''s "gangsta" lifestyle. But problems arise when the preppies get in over their heads and provoke the wrath of a violent Latino gang. Suddenly, their role-playing seems a little too real.', '2005-10-16', 5.26, 'https://image.tmdb.org/t/p/w500/xY4c4bHPCRrwIvkxJ6qRLoyxQVo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14696, 'Ugetsu', 'In 16th century Japan, peasants Genjuro and Tobei sell their earthenware pots to a group of soldiers in a nearby village, in defiance of a local sage''s warning against seeking to profit from warfare. Genjuro''s pursuit of both riches and the mysterious Lady Wakasa, as well as Tobei''s desire to become a samurai, run the risk of destroying both themselves and their wives, Miyagi and Ohama.', '1953-03-26', 8.02, 'https://image.tmdb.org/t/p/w500/r8RiuKTIYIJBjczBVsfeP5C00CJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14709, 'Varsity Blues', 'In small-town Texas, high school football is a religion, 17-year-old schoolboys carry the hopes of an entire community onto the gridiron every Friday night. When star quarterback Lance Harbor suffers an injury, the Coyotes are forced to regroup under the questionable leadership of John Moxon, a second-string quarterback with a slightly irreverent approach to the game.', '1999-01-15', 6.14, 'https://image.tmdb.org/t/p/w500/g2jX2Xmx7drbc6J9MLJEBghR7Mg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14919, 'Batman: Mask of the Phantasm', 'Andrea Beaumont leaves her father to return to Gotham, rekindling an old romance with Bruce Wayne. At the same time, a mysterious figure begins to hunt down Gotham''s criminals, wrongly implicating Batman in the murders. Now on the run from the law, Batman must find and stop the culprit, while also navigating his relationship with Andrea.', '1993-12-25', 7.50, 'https://image.tmdb.org/t/p/w500/hT4ehUteagUrhUOHAtmYiY7mp5l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14584, 'The Cheap Detective', 'A spoof of the entire 1940s detective genre. San Francisco private detective, Lou Pekinpaugh is accused of murdering his partner at the instigation of his mistress—his partner''s wife.', '1978-06-23', 6.34, 'https://image.tmdb.org/t/p/w500/7poVN0zQuxCIorAR9N6JDJN0dGG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14572, 'Patlabor 2: The Movie', 'A Japanese police unit who use giant anthropomorphic robots (called Labors) is caught up in a political struggle between the civilian authorities and the military when a terrorist act is blamed on an Air Force jet. With the aid of a government agent, the team gets close to a terrorist leader to stop things from going out of control when after the military is impelled to impose martial law.', '1993-08-14', 7.42, 'https://image.tmdb.org/t/p/w500/aB7HCqsA3d2TkAoTkiy7sioJZJ9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14711, 'Afro Samurai: Resurrection', 'Afro Samurai avenged his father and found a life of peace. But the legendary master is forced back into the game by a beautiful and deadly woman from his past. The sparks of violence dropped along Afro’s bloody path now burn out of control – and nowhere are the flames of hatred more intense than in the eyes of Sio.', '2009-04-24', 6.87, 'https://image.tmdb.org/t/p/w500/6snrLj3Ydmbu5L9giAYtiSNwE0U.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15044, 'Einstein and Eddington', 'Brilliant physicist Albert Einstein, and English scientist Arthur Eddington form an unlikely friendship during World War I, which leads to the creation of the relativity theory.', '2008-11-29', 6.82, 'https://image.tmdb.org/t/p/w500/atbER263nDEMBQEb0dnfikN4mgX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15045, 'Fat Albert', 'Animated character Fat Albert emerges from his TV universe into the real world, accompanied by his friends Rudy, Mushmouth, Old Weird Harold and Dumb Donald. Though the gang is flabbergasted by the modern world, they make new friends, and Albert attempts to help young Doris become popular. But things get complicated when Albert falls for her older sister, Lauri, and must turn to creator Bill Cosby for advice.', '2004-12-25', 5.14, 'https://image.tmdb.org/t/p/w500/biA3teAO8xZQfdBfLIK9ATdfOkJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15050, 'Brainstorm', 'Two brilliant research scientists have invented a device capable of recording and playing back sensory experiences only to have devastating results when one of them records their own death.', '1983-09-30', 6.24, 'https://image.tmdb.org/t/p/w500/afiRgLXIfH12NemvtthCkrwNtAu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15059, 'The Loss of Sexual Innocence', 'The story of the sexual development of a filmmaker through three stages of his life.', '1999-04-29', 5.63, 'https://image.tmdb.org/t/p/w500/eVg5oHFnzEE51cZ8Tq1qe8iWMZk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15060, 'Futurama: Into the Wild Green Yonder', 'Leela becomes an outlaw when she and a group of ecologically-minded feminists attempt to save an asteroid of primitive life forms and the Violet Dwarf star from being destroyed, while Fry joins a secret society and attempts to stop a mysterious species known as the "Dark Ones" from destroying all life in the universe.', '2009-02-06', 7.07, 'https://image.tmdb.org/t/p/w500/oL6SymcxQE6TN9KrrbdyhlulnEG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15067, 'The Good, the Bad, the Weird', 'The story of three Korean outlaws in 1930s Manchuria and their dealings with the Japanese army and Chinese and Russian bandits. The Good (a bounty hunter), the Bad (a hitman), and the Weird (a thief) battle the army and the bandits in a race to use a treasure map to uncover the riches of legend.', '2008-07-16', 7.15, 'https://image.tmdb.org/t/p/w500/lbPZ0aNoF0cHisg6DubFO2eS8so.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14931, 'Miami Blues', 'After Junior is released from prison, he plans on starting a new life in Miami. But when he kills a man in the airport, he flees the scene and finds Susie, a mild-mannered prostitute searching for stability. The two opposites become romantically involved, and Junior steals a badge and gun from a veteran detective. Using the officer''s identity, Junior embarks on a crime spree and convinces Susie that he is the perfect man.', '1990-04-20', 6.00, 'https://image.tmdb.org/t/p/w500/eOqOf2qG0sjsfhFdYp6SbZuorSF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15070, 'Undisputed', 'Monroe Hutchens is the heavyweight champion of Sweetwater, a maximum security prison. He was convicted to a life sentence due to a passionate crime. Iceman Chambers is the heavyweight champion, who lost his title due to a rape conviction to ten years in Sweetwater. When these two giants collide in the same prison, they fight against each other disputing who is the real champion.', '2002-07-17', 6.52, 'https://image.tmdb.org/t/p/w500/2mnzlMhRfKzsezMeYPKqAzysZFJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15074, 'Extreme Ops', 'While filming an advertisement, some extreme sports enthusiasts unwittingly stop a group of terrorists.', '2002-11-27', 4.79, 'https://image.tmdb.org/t/p/w500/984tq1bRL2uzR0wHrNzZVYTR0Al.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15092, 'Crank: High Voltage', 'Chelios faces a Chinese mobster who has stolen his nearly indestructible heart and replaced it with a battery-powered ticker that requires regular jolts of electricity to keep working.', '2009-04-16', 6.09, 'https://image.tmdb.org/t/p/w500/tzTC4EEvF0OPL63frEiogxL2T8M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15097, 'Fear City: A Family-Style Comedy', 'A second-class horror movie has to be shown at Cannes Film Festival, but, before each screening, the projectionist is killed by a mysterious fellow, with hammer and sickle, just as it happens in the film to be shown.', '1994-03-09', 7.46, 'https://image.tmdb.org/t/p/w500/7RFbGblTn679rjPo88MPSbtbJx9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15096, '20 Million Miles to Earth', 'When the first manned flight to Venus returns to Earth, the rocket crash-lands in the Mediterranean near a small Italian fishing village. The locals manage to save one of the astronauts Colonel Calder, the mission commander. A young boy also recovers what turns out to be a specimen of an alien creature. Growing at a fantastic rate, it manages to escape and eventually threatens the city of Rome.', '1957-06-01', 6.30, 'https://image.tmdb.org/t/p/w500/wozerDO9kpVBN63sq3wiM5zYmSo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15080, 'Only Yesterday', 'In lyrical switches between the present and the past, Taeko contemplates the arc of her life, and wonders if she has been true to the dreams of her childhood self.', '1991-07-20', 7.40, 'https://image.tmdb.org/t/p/w500/tOSnFE9e82iH3ZAzSTtuOkBsabJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15098, 'Manic', 'Follows the fate of Lyle, a violent adolescent who, in lieu of prison, is placed in a juvenile mental institution, where he encounters a group of equally troubled teens. This motley crew—abused, sexually confused, violent, and yet hanging on by their grit and anger—becomes Lyle''s last lifeline as he fights to find meaning in a world that seems to defy understanding.', '2002-11-22', 6.81, 'https://image.tmdb.org/t/p/w500/af9Ym0HQuChr7e5N34PN9OSfYhu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15102, 'Endgame', 'The time is the late ''80s, a crucial period in the history of South Africa. President P.W. Botha is hanging on to power by a thread as the African National Congress (ANC) takes up arms against  apartheid and the country tumbles toward insurrection. A British mining concern is convinced that their interests would be better served in a stable South Africa and they quietly dispatch Michael Young, their head of public affairs, to open an unofficial dialogue between the bitter rivals.  Assembling a reluctant yet brilliant team to pave the way to reconciliation by confronting obstacles that initially seem insurmountable, Young places his trust in ANC leader Thabo Mbeki and Afrikaner philosophy professor Willie Esterhuyse. It is their empathy that will ultimately serve as the catalyst for change by proving more powerful than the terrorist bombs that threaten to disrupt the peaceful dialogue.', '2009-01-18', 5.86, 'https://image.tmdb.org/t/p/w500/b8WzwCABwVRVdw14OcE6pmezJjK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15104, 'Tortilla Soup', 'A Mexican-American master chef and father to three daughters has lost his taste for food but not for life.', '2001-08-24', 6.40, 'https://image.tmdb.org/t/p/w500/2JTgaodnScJHIyRrQTtaawOd949.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15119, 'Shogun Assassin', 'A Shogun who grew paranoid as he became senile sent his ninjas to kill his samurai. They failed but did kill the samurai’s wife. The samurai swore to avenge the death of his wife and roams the countryside with his toddler son in search of vengeance.', '1980-11-11', 6.87, 'https://image.tmdb.org/t/p/w500/t376p5q8zvhyQ2FOroytJsRvlL8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15120, 'Smokey and the Bandit Part 3', 'The Enos duo convince Cletus, aka The Bandit, to come out of hiding and help them promote their new restaurant. With a little coaxing, he agrees, producing an almost-creaky Trigger as his mode of transport. But his nemesis, Sheriff Buford T. Justice, is on the hunt, forcing Cletus and Trigger to hit the road. Can they steer clear of the vengeful sheriff?', '1983-08-12', 4.37, 'https://image.tmdb.org/t/p/w500/ec6qP3Mn2u2XUqHnkxoZYbM33iF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15121, 'The Sound of Music', 'In the years before World War II, a tomboyish postulant at an Austrian abbey is hired as a governess in the home of a widowed naval captain with seven children and brings a new love of life and music into the home.', '1965-03-29', 7.73, 'https://image.tmdb.org/t/p/w500/c6CrUZypAsBCaRWX0M3RVRDbhNS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15128, 'Speechless', 'In the midst of election season in New Mexico, political speechwriters Julia Mann and Kevin Vallick begin a romance, unaware they are working for candidates on opposite sides.', '1994-12-16', 5.90, 'https://image.tmdb.org/t/p/w500/bremBHwg2cAvFIGIRwlRtPMkgfL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14728, 'The Librarian: The Curse of the Judas Chalice', 'While on a dangerous mission to recover the historic Judas Chalice, Flynn is saved by Simone. But when double-crossed by a respected professor and ambushed by a ruthless gang, Flynn realizes Simone''s secret, his true mission and a shocking discovery are all lying within a decaying New Orleans crypt.', '2008-10-25', 6.26, 'https://image.tmdb.org/t/p/w500/qzpTcjPdhmKmEYx9oJO8y4ZZLU6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15137, 'Evangelion: 1.0 You Are (Not) Alone', 'After the Second Impact, Tokyo-3 is being attacked by giant monsters called Angels that seek to eradicate humankind. The child Shinji’s objective is to fight the Angels by piloting one of the mysterious Evangelion mecha units. A remake of the first six episodes of GAINAX’s famous 1996 anime series. The film was retitled “Evangelion: 1.01” for its DVD release and “Evangelion: 1.11” for a release with additional scenes.', '2007-09-01', 7.60, 'https://image.tmdb.org/t/p/w500/pETU4GurpeEjBOM8oytMH0yNBHx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14742, 'Night Shift', 'A nebbish of a morgue attendant gets shunted back to the night shift where he is shackled with an obnoxious neophyte partner who dreams of the "one great idea" for success. His life takes a bizarre turn when a prostitute neighbor complains about the loss of her pimp. His partner, upon hearing the situation, suggests that they fill that opening themselves using the morgue at night.', '1982-07-30', 6.07, 'https://image.tmdb.org/t/p/w500/iS78MFtMDwWDP748juZQBK57C9o.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14911, 'Bat★21', 'Lt. Col. Iceal "Ham" Hambleton is a weapons countermeasures expert and when his aircraft is shot over enemy territory the Air Force very much wants to get him back. Hambleton knows the area he''s in is going to be carpet-bombed but a temporary shortage of helicopters causes a delay. Working with an Air Force reconnaissance pilot, Capt. Bartholomew Clark, he maps out an escape route.', '1988-07-21', 6.30, 'https://image.tmdb.org/t/p/w500/tiwhsOX3zm9QGfdFK4IfrGvZWJj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14976, 'Rachel Getting Married', 'A young woman who has been in and out from rehab for the past 10 years returns home for the weekend for her sister''s wedding.', '2008-10-03', 6.30, 'https://image.tmdb.org/t/p/w500/bumaq3lqe4YSsq6LlYoge7e9ABk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15157, 'Another Cinderella Story', 'A guy who danced with what could be the girl of his dreams at a costume ball only has one hint at her identity: the Zune she left behind as she rushed home in order to make her curfew. And with a once-in-a-lifetime opportunity in front of him, he sets out to find his masked beauty.', '2008-09-16', 7.33, 'https://image.tmdb.org/t/p/w500/bW957WNXiiUvIGFaUVL7wMeD776.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15159, 'The Pink Panther 2', 'When legendary treasures from around the world are stolen, including the priceless Pink Panther Diamond, Chief Inspector Dreyfus is forced to assign Inspector Clouseau to a team of international detectives and experts charged with catching the thief and retrieving the stolen artifacts.', '2009-02-06', 5.71, 'https://image.tmdb.org/t/p/w500/aPg6iZjnBUlsmnCSGHX85T82AJ4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14736, 'Love & Basketball', 'Monica Wright and Quincy McCall grew up in the same neighborhood and have known each other since childhood. As they grow into adulthood, they fall in love, but they also share another all-consuming passion: basketball.  As Quincy and Monica struggle to make their relationship work, they follow separate career paths though high school and college basketball and, they hope, into stardom in big-league professional ball.', '2000-04-21', 7.35, 'https://image.tmdb.org/t/p/w500/zNZWNX19FZ5QyedprVM0ldsXFiP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14905, 'Welcome to Sarajevo', 'Follow a group of international journalists into the heart of the once cosmopolitan city of Sarajevo—now a danger zone of sniper and mortar attacks where residents still live. While reporting on an American aid worker who’s trying to get children out of the country, a British correspondent decides to take an orphaned girl home to London.', '1997-05-09', 6.45, 'https://image.tmdb.org/t/p/w500/bGdDqsFCF0v9M5mB77fAF8vJMsy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15138, 'Little Monsters', 'A young boy is scared of the monster under his bed. He asks his 6th grade brother to swap rooms for the night as a bet that the monster really exists. Soon the brother becomes friends with the monster and discovers a whole new world of fun and games under his bed where pulling pranks on kids and other monsters is the main attraction.', '1989-08-25', 5.83, 'https://image.tmdb.org/t/p/w500/ynQT9NA4SBfoswIRkyrwqHe4aBz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15144, 'Sixteen Candles', 'With the occasion all but overshadowed by her sister''s upcoming wedding, angst-ridden Samantha faces her 16th birthday with typical adolescent dread. Samantha pines for studly older boy Jake, but worries that her chastity will be a turnoff for the popular senior. Meanwhile, she must constantly rebuff the affections of nerdy Ted, who is unfortunately the only boy in school who seems to take an interest in her.', '1984-05-04', 6.70, 'https://image.tmdb.org/t/p/w500/A3WGCAgJF33kZdlxUdyXHYdbYax.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14741, 'The Goodbye Girl', 'After being dumped by her live-in boyfriend, an unemployed dancer and her 10-year-old daughter are reluctantly forced to live with a struggling off-Broadway actor.', '1977-11-27', 6.90, 'https://image.tmdb.org/t/p/w500/xdaPFRARLPJuSdQIfxKVJSCOsmD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15037, 'Can''t Hardly Wait', 'It''s graduation day at Huntington Hills High, and you know what that means - time to party. And not just any party, either. This one will be a night to remember, as the nerds become studs, the jocks are humiliated, and freshman crushes blossom into grown-up romance.', '1998-06-12', 6.25, 'https://image.tmdb.org/t/p/w500/r3a5gGWfS0SDS9nriNrJzSSrErf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15196, 'Clue', 'Clue finds six colorful dinner guests gathered at the mansion of their host, Mr. Boddy -- who turns up dead after his secret is exposed: He was blackmailing all of them. With the killer among them, the guests and Boddy''s chatty butler must suss out the culprit before the body count rises.', '1985-12-13', 7.20, 'https://image.tmdb.org/t/p/w500/aRxbYOYHS8T73nzR8hsLousoplR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14924, 'Sid and Nancy', 'January 1978. After their success in England, the punk rock band Sex Pistols venture out on their tour of the southern United States. Temperamental bassist Sid Vicious is forced by his band mates to travel without his troubled girlfriend, Nancy Spungen, who will meet him in New York. When the band breaks up and Sid begins his solo career in a hostile city, the turbulent couple definitely falls into the depths of drug addiction.', '1986-09-12', 6.73, 'https://image.tmdb.org/t/p/w500/wHzCbMCfipDJ38GW5IyBTWDflMz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15198, 'Mystery, Alaska', 'In Mystery, Alaska, life revolves around the legendary Saturday hockey game at the local pond. But everything changes when the hometown team unexpectedly gets booked in an exhibition match against the New York Rangers. When quirky small-towners, slick promoters and millionaire athletes come together.', '1999-10-01', 6.30, 'https://image.tmdb.org/t/p/w500/bmg4sjOQswcrP5mPL9YzNom9cXx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15237, 'De-Lovely', 'From Paris to Venice to Broadway to Hollywood, the lives of Cole Porter and his wife, Linda Lee Thomas were never less than glamorous and wildly unconventional. And though Cole''s thirst for life strained their marriage, Linda never stopped being his muse, inspiring some of the greatest songs of the twentieth century.', '2004-07-02', 6.13, 'https://image.tmdb.org/t/p/w500/QBqiBQW7MGqlDSyvid4fKzS0Xz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15139, 'The Pagemaster', 'Rich knows a lot about accidents. So much so, he is scared to do anything that might endanger him, like riding his bike, or climbing into his treehouse. While in an old library, he is mystically transported into the unknown world of books, and he has to try and get home again.', '1994-11-23', 6.40, 'https://image.tmdb.org/t/p/w500/iIWUuCjN8VND7BDugvf45LveA6p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15239, 'The Toxic Avenger', 'A gang of thugs devise a cruel hoax that goes horribly wrong as Melvin, a nerdy emaciated janitor at the local health club, is cast through a third story window into a vat of hazardous toxic waste.', '1984-05-15', 6.23, 'https://image.tmdb.org/t/p/w500/vuxRW5GKuCnKvdYlUAYNxlicm54.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15251, 'Eddie Murphy: Delirious', 'Taped live and in concert at Constitution Hall in Washington, D.C. in August, 1983, Eddie Murphy: Delirious captures Eddie Murphy''s wild and outrageous stand-up comedy act, which he performed in New York and eighteen other cities across the U.S. to standing-room-only audiences. Eddie''s comedy was groundbreaking, completely new, razor sharp and definitely funny.Eddie Murphy pontificates in his own vulgarly hilarious fashion on everything from bizarre sexual fantasies to reliving the family barbecue, and is peppered with Eddie''s one-of-a-kind wit. Laugh along as Eddie reminiscences of hot childhood days and the ice cream man intermixed with classic vocal parodies of top American entertainers.Experience Eddie Murphy at his best, live and red hot! Delirious! Uncensored and Uncut!', '1983-10-15', 7.62, 'https://image.tmdb.org/t/p/w500/qnNXoflFXeUg692kulMKVJVRzYf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15244, 'A Man Escaped', 'A captured French Resistance fighter during World War II engineers a daunting escape from prison.', '1956-11-11', 7.90, 'https://image.tmdb.org/t/p/w500/gkoZ8fFib24zhB2DKpjQ09SK9FU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15247, 'The Ipcress File', 'Sly and dry intelligence agent Harry Palmer is tasked with investigating British Intelligence security, and is soon enmeshed in a world of double-dealing, kidnap and murder when he finds a traitor operating at the heart of the secret service.', '1965-03-18', 6.80, 'https://image.tmdb.org/t/p/w500/iCNRK7NVhBvNpiyMRmCpTBFNoLO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15255, 'Undisputed II: Last Man Standing', 'Heavyweight Champ George "Iceman" Chambers is sent to a Russian jail on trumped-up drug charges. In order to win his freedom he must fight against the jailhouse fighting champ Uri Boyka in a battle to the death. This time he is not fighting for a title, he is fighting for his life!', '2006-04-11', 7.40, 'https://image.tmdb.org/t/p/w500/2gMCokqpIJoh6u5o06LlOZWsI3k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15256, '200 Cigarettes', 'In 1981 New York City, a collection of twentysomethings try to cope with relationships, loneliness, desire and their individual neuroses on New Years Eve.', '1999-02-26', 5.80, 'https://image.tmdb.org/t/p/w500/ssbx2Mk5ZCJWpXALuP2AdG0GFIT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15257, 'Hulk vs. Wolverine', 'Department H sends in Wolverine to track down a mysterious beast known by the US Military as the Hulk, who is rampaging across the Canadian wilderness. Surveying the extent of the damage to a destroyed town, Wolverine notices a toxic scent as well as the smell of gunpowder. He is then deployed to the wilderness to resume tracking the creature.', '2009-01-27', 7.10, 'https://image.tmdb.org/t/p/w500/p8PZfkrCuXanfYr3k6xAS6WzN8Y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14943, 'Crows Zero', 'The students of Suzuran High compete for the King of School title. An ex-graduate yakuza is sent to kill the son of a criminal group, but he can''t make himself do it as he reminds him of his youth.', '2007-10-26', 7.09, 'https://image.tmdb.org/t/p/w500/so1E9wUAXJi9hqGRNPgoVQd7HaX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15259, 'Breakin''', 'A struggling young dancer joins forces with two breakdancers and together they become a street sensation.', '1984-05-04', 6.71, 'https://image.tmdb.org/t/p/w500/kwIqaI4yXKDlRurc9zTrgavMrFF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15258, 'The Aristocrats', 'One hundred superstar comedians tell the same very, VERY dirty, filthy joke--one shared privately by comics since Vaudeville.', '2005-07-29', 5.90, 'https://image.tmdb.org/t/p/w500/Ag25aONVwWspQAuEPwNKmwUOvce.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15261, 'Bring It On: In It to Win It', 'Fourth ''Bring It On'' movie is set at a cheerleader camp in Florida with a ''West Side Story'' musical feel has the female captain of the West Side Sharks meeting and romancing a male member of the East Coast Jets amid their different team rivalries.', '2007-10-29', 6.43, 'https://image.tmdb.org/t/p/w500/hMRjQuTZQ8bZNrwqkKhBgbh8MkF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15158, 'Phantasm II', 'Mike, after his release from a psychiatric hospital, teams up with his old pal Reggie to hunt down the Tall Man, who is at it again. A mysterious, beautiful girl has also become part of Mike''s dreams, and they must find her before the Tall Man does.', '1988-07-08', 6.22, 'https://image.tmdb.org/t/p/w500/cZ5mPtOXcvmg224oBM2k1db5Fnn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15267, 'The Beast of War', 'During the war in Afghanistan a Soviet tank crew commanded by a tyrannical officer find themselves lost and in a struggle against a band of Mujahadeen guerrillas in the mountains.', '1988-09-14', 7.10, 'https://image.tmdb.org/t/p/w500/fMymKHTtCikQEx1HVQeahc2wiNU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15278, 'CB4', 'A "rockumentary", covering the rise to fame of MC Gusto, Stab Master Arson, and Dead Mike: members of the rap group "CB4". We soon learn that these three are not what they seem and don''t appear to know as much about rap music as they claim... but a lack of musical ability in an artist never hurts sales, does it? You''ve just got to play the part of a rap star...', '1993-03-12', 6.09, 'https://image.tmdb.org/t/p/w500/7bP66TCKWPTsiER72xgyKUsjg82.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15265, 'The Red Balloon', 'A young boy discovers a stray balloon, which seems to have a mind of its own, on the streets of Paris. The two become inseparable, yet the world’s harsh realities finally interfere.', '1956-08-24', 7.71, 'https://image.tmdb.org/t/p/w500/5i9qweJTrkyIhg7lrSHRAUtpeA4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15289, 'Babylon 5: The Lost Tales - Voices in the Dark', 'This instalment of Babylon 5 is in two parts: the first is about an entity that has possessed a worker.  Colonel Lochley prevents a priest from performing an exorcism. The host is returned to Earth. The second has Galen trying to dupe President Sheridan into assassinating the future Centauri emperor to stop him from attacking Earth in around 30 years time.', '2007-09-03', 6.46, 'https://image.tmdb.org/t/p/w500/vJfaGrtbugADGYdlmtI6xfWxfpB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15292, 'Step Into Liquid', 'No special effects. No stuntmen. No stereotypes. No other feeling comes close. Surfers and secret spots from around the world are profiled in this documentary.', '2003-08-05', 7.19, 'https://image.tmdb.org/t/p/w500/gF352z3G8wnk5GDKzn7RcIDstwh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15300, 'Newsies', 'A week in the life of the exploited, child newspaper sellers in turn-of-the-century New York. When their publisher, Joseph Pulitzer, tries to squeeze a little more profit out of their labours, they organize a strike, only to be confronted with the Pulitzer''s hard-ball tactics.', '1992-04-10', 6.71, 'https://image.tmdb.org/t/p/w500/8ykmCMHzkRSuJucPYeqGA2ampbp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15301, 'Twilight Zone: The Movie', 'An anthology film presenting remakes of three episodes from the "Twilight Zone" TV series—"Kick the Can", "It''s a Good Life" and "Nightmare at 20,000 Feet"—and one original story, "Time Out."', '1983-06-24', 6.48, 'https://image.tmdb.org/t/p/w500/sDWARc5aYTUKE8Y2FIGVgWXuI4K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15314, 'Mini''s First Time', 'Desperate to be free from her drunken, unloving mother Diane, the beautiful, scheming young Mini seduces her stepfather Martin and soon convinces him to join her in a sadistic scheme to have Diane declared insane. But their conspiracy soon escalates to murder and when John Garson, a young detective starts investigating, Martin and Mini begin to turn on each other.', '2006-07-14', 5.54, 'https://image.tmdb.org/t/p/w500/8LSbj1iwkxM7AZRTKxCxfdmE4Lt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15356, 'The Girl Next Door', 'In a quiet suburban town in the summer of 1958, two recently orphaned sisters are placed in the care of their mentally unstable Aunt Ruth. But Ruth''s depraved sense of discipline will soon lead to unspeakable acts of abuse and torture that involve her young sons, the neighborhood children, and one 12-year-old boy whose life will be changed forever.', '2007-07-19', 6.65, 'https://image.tmdb.org/t/p/w500/dXjLp7k7ILyg22T0s9VvpPKc9jn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14908, 'McHale''s Navy', 'Retired Lieutenant Commander Quinton McHale spends his days puttering around the Caribbean in the old PT-73 selling homebrew, ice cream, and swimsuit calendars. He''s brought out of retirement when his old nemesis turned the second best terrorist in the world, Major Vladikov, takes over the island of San Moreno and starts building a nuclear launch silo on it. With help from his old crew and hindrances from Captain Wallace B. Binghampton, who sank a cruise liner a while back, McHale tries to put Vladikov out of business.', '1997-04-18', 4.46, 'https://image.tmdb.org/t/p/w500/tg9qzqF349j526pNZnjPB4p2UED.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15142, 'Dream a Little Dream', 'Bobby Kellar has a crush on Lainie Diamond, girlfriend of school jerk Joel. Coleman is working on an experiment which will help him move into a place where Dreams are reality. When an accident occurs Coleman finds himself in Bobby''s body and can only contact Bobby in his dreams.', '1989-03-03', 5.79, 'https://image.tmdb.org/t/p/w500/h73heOhdqIV45m3t4vwV92pZXDP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14922, 'Happy Endings', 'Filmmaker Nicky offers to track down the son that Mamie gave up for adoption nearly two decades before. Meanwhile, Mamie''s stepbrother (and the father of her child), Charley, along with his boyfriend, Gil, try to find out what became of the sperm Gil donated to a lesbian couple. Finally, singer Jude becomes entangled in a love triangle with androgynous drummer Otis and his conservative father.', '2005-01-20', 5.60, 'https://image.tmdb.org/t/p/w500/76Hq3Buq6SIOe5Z7f5APwh1s7vU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14968, 'Welcome to Dongmakgol', 'Based on the long running play by Jang Jin, the story is set in Korea during the Korean War in 1950. Soldiers from both the North and South, as well as an American pilot, find themselves in a secluded and naively idealistic village, its residents unaware of the outside world, including the war.', '2005-08-04', 7.44, 'https://image.tmdb.org/t/p/w500/3FQ8p7kXTqdHJ2EIvQ5Y9TDTSw0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (14926, 'Uptown Girls', 'Molly Gunn, the freewheeling daughter of a deceased rock legend, is forced to get a job when her manager steals her money. As nanny to Ray - the precocious, oft-ignored daughter of a music executive - she learns what it means to be an adult while teaching Ray how to be a child.', '2003-08-15', 7.00, 'https://image.tmdb.org/t/p/w500/liazMoopc2fhWq1YlfwasQcvWu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15371, 'The Castle of Cagliostro', 'After a successful robbery leaves famed thief Lupin the Third and his partner Jigen with nothing but a large amount of expertly crafted counterfeit bills, he decides to track down the forgers responsible—and steal any other treasures he may find in the Castle of Cagliostro, including the ''damsel in distress'' he finds imprisoned there.', '1979-07-06', 7.50, 'https://image.tmdb.org/t/p/w500/p7xL3WYeclgtGCLrWfBrXKdBV7d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15283, 'Pom Poko', 'The Raccoons of the Tama Hills are being forced from their homes by the rapid development of houses and shopping malls. As it becomes harder to find food and shelter, they decide to band together and fight back. The Raccoons practice and perfect the ancient art of transformation until they are even able to appear as humans in hilarious circumstances.', '1994-07-16', 7.20, 'https://image.tmdb.org/t/p/w500/gyoJmFf24MOUc4TTu97sd0cHIQF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15143, 'Some Kind of Wonderful', 'Keith Nelson, an artsy high school outcast, tries to land a date with popular girl Amanda Jones with some help from his tomboy best friend, Watts. However, Watts realizes she likes Keith as more than just a friend and tries to convince him to stop pursuing Amanda. Matters are further complicated when Keith''s invitation draws the ire of Amanda''s rich yet snobby ex-boyfriend, Hardy Jenns, who makes plans to get even.', '1987-02-27', 6.85, 'https://image.tmdb.org/t/p/w500/6z6ZUrwbAJl9Nq43OY77O7iY80x.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15379, 'Missing in Action', 'American servicemen are still being held captive in Vietnam and it''s up to one man to bring them home in this blistering, fast-paced action/adventure starring martial arts superstar Chuck Norris. Following a daring escape from a Vietnamese POW camp, Special Forces Colonel James Braddock (Norris) is on a mission to locate and save remaining MIAs.', '1984-11-16', 5.89, 'https://image.tmdb.org/t/p/w500/nBrDcnNQca88ed1gRwZ1Q5cjNxE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15170, 'Buddy', 'An eccentric socialite raises a gorilla as her son.', '1997-06-06', 4.97, 'https://image.tmdb.org/t/p/w500/88l3mMtQcHE5JW8gJmQJm9fmpAH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15035, 'Fire and Ice', 'The villainous Nekron and his mother, Queen Juliana, plot against the human race from their frigid fortress. Creating mass destruction with huge glaciers, mother and son incur the wrath of Larn, a warrior whose entire village was destroyed by ice. When Nekron''s underlings kidnap the beautiful Princess Teegra, Larn sets out to rescue her, assisted by the fierce and enigmatic Darkwolf.', '1983-03-25', 6.69, 'https://image.tmdb.org/t/p/w500/v0fi9KgmdsUsGtopxxRzbtQ5NIX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15171, 'Charlotte''s Web', 'Wilbur the pig is scared of the end of the season, because he knows that come that time, he will end up on the dinner table. He hatches a plan with Charlotte, a spider that lives in his pen, to ensure that this will never happen.', '1973-03-01', 6.89, 'https://image.tmdb.org/t/p/w500/eLq5bed09bkNVjUfknlbSil2cfR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15028, 'Clockstoppers', 'Until now, Zak Gibbs'' greatest challenge has been to find a way to buy a car. But when he discovers an odd wristwatch amidst his father''s various inventions and slips it on -- something very strange happens. The world around him seems to come to a stop, everything and everybody frozen in time. Zak quickly learns how to manipulate the device and he and his quick-witted and beautiful new friend, Francesca, start to have some real fun.', '2002-03-29', 5.31, 'https://image.tmdb.org/t/p/w500/6XZJ58gStdLZV8uJyTRcA5bGNyi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15394, 'Owning Mahowny', 'Dan Mahowny was a rising star at the Canadian Imperial Bank of Commerce. At twenty-four he was assistant manager of a major branch in the heart of Toronto''s financial district. To his colleagues he was a workaholic. To his customers, he was astute, decisive and helpful. To his friends, he was a quiet, but humorous man who enjoyed watching sports on television. To his girlfriend, he was shy but engaging. None of them knew the other side of Dan Mahowny--the side that executed the largest single-handed bank fraud in Canadian history, grossing over $10 million in eighteen months to feed his gambling obsession.', '2003-05-02', 6.78, 'https://image.tmdb.org/t/p/w500/xQYKqpN6fD7Dc7Vu8xnShHPKDwe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15395, 'Love Liza', 'Following the unexplained suicide of his wife Liza, website designer Wilson Joel turns to huffing gasoline fumes and remote control gaming while avoiding an inevitable conflict with his mother-in-law.', '2002-12-30', 6.42, 'https://image.tmdb.org/t/p/w500/dAjQy6CpYMTZ4ClrcaeJcoT3UHa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15397, 'I Am David', 'A 12-year-old boy manages to flee a Communist concentration camp on his own, through sheer will and determination. All he has in his possession is a loaf of bread, a letter to deliver to someone in Denmark, and a compass to help get him there.', '2003-12-03', 6.84, 'https://image.tmdb.org/t/p/w500/cPoiPR15ylyBCNIr9zmUAzEb1Jm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15400, 'Mickey''s Once Upon a Christmas', 'Mickey, Minnie, and their famous friends Goofy, Donald, Daisy and Pluto gather together to reminisce about the love, magic and surprises in three wonder-filled stories of Christmas past.', '1999-10-31', 7.14, 'https://image.tmdb.org/t/p/w500/jHl15NgLPBdUsXgIZzrgBB1QJcc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15402, 'The Notorious Bettie Page', 'Bettie Page grew up in a conservative religious family in Tennessee and became a photo model sensation in 1950s New York. Bettie''s legendary pin-up photos made her the target of a Senate investigation into pornography, and transformed her into an erotic icon who continues to enthrall fans to this day.', '2006-04-14', 6.28, 'https://image.tmdb.org/t/p/w500/jRzcb9O8WdGmJdz8EESEaBEuZZJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15413, 'Don''t Tell Mom the Babysitter''s Dead', 'Sue Ellen Crandell is a teenager eagerly awaiting her mother''s summer-long absence. While the babysitter looks after her rambunctious younger siblings, Sue Ellen can party and have fun. But then the babysitter abruptly dies, leaving the Crandells short on cash. Sue Ellen finds a sweet job in fashion by lying about her age and experience on her résumé. But, while her siblings run wild, she discovers the downside of adulthood', '1991-06-07', 6.17, 'https://image.tmdb.org/t/p/w500/wIYhjykSq0yumZWBisKlAa83bUe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15320, 'I.O.U.S.A.', 'With the country''s debt growing out of control, Americans by and large are unaware of the looming financial crisis. This documentary examines several of the ways America can get its economy back on the right track. In addition to looking at the federal deficit and trade deficit, the film also closely explores the challenges of funding national entitlement programs such as Social Security, Medicare and Medicaid.', '2008-01-19', 7.01, 'https://image.tmdb.org/t/p/w500/8M8TjVNxo9Y9cEizJjtIVI3YL3T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15417, 'Every Which Way but Loose', 'Philo Beddoe is your regular, easygoing, truck-driving guy. He''s also the best bar-room brawler west of the Rockies. And he lives with a 165-pound orangutan named Clyde. Like other guys, Philo finally falls in love - with a flighty singer who leads him on a screwball chase across the American Southwest. Nothing''s in the way except a motorcycle gang, some cops, and legendary brawler Tank Murdock.', '1978-12-16', 6.12, 'https://image.tmdb.org/t/p/w500/vcSfAskDGCgInfJAXwLLORPQLAO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15423, 'Snoop Dogg''s Hood of Horror', 'A hip hop horror anthology of three tales of terror told by the Hound of Hell (Snoop Dogg) that revolve around the residents of an inner-city neighborhood whose actions determine where they will go in the afterlife.', '2006-06-27', 4.80, 'https://image.tmdb.org/t/p/w500/98abrZgWTnGP0noaY2Cli7SNhVb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15383, 'Army of Shadows', 'Betrayed by an informant, Philippe Gerbier finds himself trapped in a torturous Nazi prison camp. Though Gerbier escapes to rejoin the Resistance in occupied Marseilles, France, and exacts his revenge on the informant, he must continue a quiet, seemingly endless battle against the Nazis in an atmosphere of tension, paranoia and distrust.', '1969-09-10', 7.89, 'https://image.tmdb.org/t/p/w500/aqNZWM9bspt8zaDvVRIRiWxRVJ7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15462, 'Car Wash', 'This day-in-the-life cult comedy focuses on a group of friends working at Sully Boyar''s Car Wash in the Los Angeles ghetto. The team meets dozens of eccentric customers -- including a smooth-talking preacher, a wacky cab driver and an ex-convict -- while cracking politically incorrect jokes to a constant soundtrack of disco and funk. Some of the workers find romance as the day moves along, but most are just happy to get through another shift.', '1976-10-22', 6.00, 'https://image.tmdb.org/t/p/w500/bty0IdXh4l2BmoQNVeAH5PYKrMK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15472, 'The Girl with the Dragon Tattoo', 'Swedish thriller based on Stieg Larsson''s novel about a male journalist and a young female hacker. In the opening of the movie, Mikael Blomkvist, a middle-aged publisher for the magazine Millennium, loses a libel case brought by corrupt Swedish industrialist Hans-Erik Wennerström. Nevertheless, he is hired by Henrik Vanger in order to solve a cold case, the disappearance of Vanger''s niece', '2009-02-27', 7.54, 'https://image.tmdb.org/t/p/w500/r2pFUXKK20KD9RE3yybpQsNynRE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15163, 'Amazing Grace', 'The true story of William Wilberforce and his courageous quest to end the British slave trade. Along the way, Wilberforce meets intense opposition, but his minister urges him to see the cause through.', '2006-09-16', 6.89, 'https://image.tmdb.org/t/p/w500/zr48JEuwxcYM03NcdJU6qWMHPtq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15477, 'Love and a .45', 'Small-time criminal Watty Watts attempts to rob a convenience store with his drug-addict buddy, Billy Mack Black. The robbery, however, leads to murder, and soon Watty leaves Billy behind and goes on the run with his beloved girlfriend, Starlene. Heading toward Mexico, the fugitive couple gets plenty of media coverage, until there are even more people on their trail. Can Watty and Starlene make it south of the border without getting caught?', '1994-11-23', 5.73, 'https://image.tmdb.org/t/p/w500/xz7rXuL1lkc6tkt1rS0N05rxtRX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15487, 'The Greatest Game Ever Played', 'A biopic of 20-year-old Francis Ouimet who defeated his golfing idol and 1900 US Open Champion, Harry Vardon.', '2005-09-30', 7.31, 'https://image.tmdb.org/t/p/w500/kh4vd6wKa6j9xVFzxhQrsT0p2YN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15173, 'Jonah: A VeggieTales Movie', 'Get ready as Bob the Tomato, Larry the Cucumber and the rest of the Veggies set sail on a whale of an adventure in Big Idea''s first full-length, 3-D animated feature film. This is the story of Jonah and the Whale as you''ve never seen it before - a story where we learn that one of the best gifts you can give - or get - is a second chance.', '2002-10-04', 6.24, 'https://image.tmdb.org/t/p/w500/xJ6ImpQIqZxBh4eE2813ljQ0TQ3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15512, 'Monsters vs Aliens', 'When Susan Murphy is unwittingly clobbered by a meteor full of outer space gunk on her wedding day, she mysteriously grows to 49-feet-11-inches. The military jumps into action and captures Susan, secreting her away to a covert government compound. She is renamed Ginormica and placed in confinement with a ragtag group of Monsters...', '2009-03-19', 6.26, 'https://image.tmdb.org/t/p/w500/hpHarddVj34j53T7NsoUGdKj4mP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15489, 'Snow Day', 'When an entire town in upstate New York is closed down by an unexpected snowfall, a "snow day" begins when a group of elementary school kids, led by Natalie Brandston, try to ensure that the schools stay closed by stopping a mechanical snowplow driver by trying to hijack his plow truck. Meanwhile, Natalie''s big brother Hal is using this day to try to win the affections of Claire Bonner, the most popular girl in his high school, while Hal and Natalie''s father Tom, a TV meteorologist, faces off against a rival meteorologist for weather coverage of the day''s events.', '2000-02-11', 5.11, 'https://image.tmdb.org/t/p/w500/myTnHKy178rrd1oUG3GkEvc641G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15497, 'Twelve O''Clock High', 'In the early days of daylight bombing raids over Germany, General Frank Savage must take command of a ''hard luck'' bomber group. Much of the story deals with his struggle to whip his group into a disciplined fighting unit in spite of heavy losses, and withering attacks by German fighters over their targets.', '1949-12-21', 7.17, 'https://image.tmdb.org/t/p/w500/g9VeQUobhofLwxSIbKM4ia5biAX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15392, 'Crossroads', 'A wanna-be blues guitar virtuoso seeks a long-lost song by legendary musician, Robert Johnson.', '1986-03-14', 7.33, 'https://image.tmdb.org/t/p/w500/2sMo7gwZ8L7KttiW210T0ueJ2eX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15516, 'The Last House on the Left', 'On the eve of her 17th birthday, Mari and friend Phyllis set off from her family home to attend a rock concert in the city. Attempting to score some drugs on the way, the pair run afoul of a group of vicious crooks, headed up by the sadistic Krug.', '1972-08-30', 6.03, 'https://image.tmdb.org/t/p/w500/qyTqXz1C7kPgWmxcD5otQ7xlrJP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15515, 'The 7th Voyage of Sinbad', 'When a princess is shrunken by an evil wizard, Sinbad must undertake a quest to an island of monsters to cure her and prevent a war.', '1958-12-05', 6.90, 'https://image.tmdb.org/t/p/w500/wZKfMySjut6QxLNTyMkzrCBZyxP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15347, 'Born Free', 'At a national park in Kenya, English game warden George Adamson and his wife, Joy, care for three orphaned lion cubs. After the two larger lions are shipped off to a zoo in the Netherlands, the smallest of the three, Elsa, stays with the couple. When Elsa is blamed for causing an elephant stampede in the nearby village, head warden John Kendall demands the young lion either be trained to survive in the wilds of the Serengeti or be sent to a zoo.', '1966-03-14', 6.76, 'https://image.tmdb.org/t/p/w500/xI5BkObQm7UtYEFTw7ZmiDGF7gT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15556, 'At First Sight', 'A blind man has an operation to regain his sight at the urging of his girlfriend and must deal with the changes to his life.', '1999-01-15', 6.00, 'https://image.tmdb.org/t/p/w500/9nylrKj8zWxTor9BCy3umv6WHZe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15567, 'Stitch! The Movie', 'The continuing adventures of Lilo, a little Hawaiian girl, and Stitch, the galaxy''s most-wanted extraterrestrial. Stitch, Pleakley, and Dr. Jumba are all part of the household now, but what Lilo and Stitch don''t know is that Dr. Jumba brought his other alien "experiments" to Hawaiʻi as well.', '2003-09-10', 6.44, 'https://image.tmdb.org/t/p/w500/flwMGZcOO80lqsnZ6lIwsKja5N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15566, 'Surviving Christmas', 'A wealthy executive, Drew Latham (Ben Affleck) has no close relationships and becomes nostalgic for his childhood home as Christmas approaches. When he visits the house and finds another family living there, he offers the residents, Tom Valco (James Gandolfini) and his wife, Christine (Catherine O''Hara), a large sum of money to pretend they are his parents. Soon Drew tests the couple''s patience, and, when their daughter, Alicia (Christina Applegate), arrives, things get increasingly tense.', '2004-09-21', 5.72, 'https://image.tmdb.org/t/p/w500/8jHtvFpCOOqp2U2qwI3L3h10cUv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15596, 'Back to School', 'Self-made millionaire Thornton Melon decides to get a better education and enrolls at his son Jason''s college. While Jason tries to fit in with his fellow students, Thornton struggles to gain his son''s respect, giving way to hilarious antics.', '1986-06-13', 6.34, 'https://image.tmdb.org/t/p/w500/nspYnZ6QwqAQXaCLjbGKfEA83tf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15389, 'Metropolitan', 'A radical student is adopted by a group of young New Yorkers, serves as a catalyst to alter his and their lives. Gathering in a Manhattan apartment, the group of friends meet to discuss social mobility, Fourier''s socialism and play bridge in their cocoon of upper-class society - until they are joined by a man with a critical view of their way of life.', '1990-08-03', 7.00, 'https://image.tmdb.org/t/p/w500/852ZwTRj9tRxkGOT0Pu0Ep8yimk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15192, 'The Grey Zone', 'The story of Auschwitz''s twelfth Sonderkommando — one of the thirteen consecutive "Special Squads" of Jewish prisoners placed by the Nazis in the excruciating moral dilemma of assisting in the extermination of fellow Jews in exchange for a few more months of life.', '2001-09-13', 6.58, 'https://image.tmdb.org/t/p/w500/8jRsWnpciWHRy0MC7K5eMDKKqPw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15584, 'Dear Zachary: A Letter to a Son About His Father', 'In 2001, Andrew Bagby, a medical resident, is murdered not long after breaking up with his girlfriend. Soon after, when she announces she''s pregnant, one of Andrew''s many close friends, Kurt Kuenne, begins this film, a gift to the child.', '2008-10-31', 8.05, 'https://image.tmdb.org/t/p/w500/yYVHGe7U55Ojx11y5A82phPpCHv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15647, 'Kissing Jessica Stein', 'Jessica, a Jewish copy editor living and working in New York City, is plagued by failed blind dates with men, and decides to answer a newspaper''s personal advertisement. The advertisement has been placed by ''lesbian-curious'' Helen Cooper, a thirtysomething art gallerist.', '2002-03-13', 6.00, 'https://image.tmdb.org/t/p/w500/8b2g8QZRLTJMYyzc3HirTSRQpLW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15357, 'District 13: Ultimatum', 'Damien and Leito return to District 13 on a mission to bring peace to the troubled sector that is controlled by five different gang bosses, before the city’s secret services take drastic measures to solve the problem.', '2009-02-18', 6.40, 'https://image.tmdb.org/t/p/w500/qhadETc2y1ImTQ51all8tOd45aw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15179, 'Patrik, Age 1.5', 'Göran and Sven have been cleared for adoption and they have a possibility to adopt a swedish orphan, Patrik 1,5. But when Patrik arrives he turns out to be someone else, not the little boy they were expecting. A comma had been misplaced, and in comes a 15-year-old homophobic with a criminal past.', '2008-09-12', 6.77, 'https://image.tmdb.org/t/p/w500/zFHcajKXeiPVOArumZOqjFYDx1T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15648, 'The Perfect Man', 'Holly is tired of moving every time her mom Jean breaks up with yet another second-rate guy. To distract her mother from her latest bad choice, Holly conceives the perfect plan for the perfect man, an imaginary secret admirer who will romance Jean and boost her self-esteem.', '2005-06-17', 6.15, 'https://image.tmdb.org/t/p/w500/sT4sCDXcqQBjAqyDaofkRmP0er5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15655, 'The Tigger Movie', 'Winnie the Pooh, Piglet, Owl, Kanga, Roo, and Rabbit are preparing a suitable winter home for Eeyore, the perennially dejected donkey, but Tigger''s continual bouncing interrupts their efforts. Rabbit suggests that Tigger go find others of his kind to bounce with, but Tigger thinks "the most wonderful thing about tiggers is" he''s "the only one!" Just in case though, the joyously jouncy feline sets out to see if he can find relatives.', '2000-02-11', 6.69, 'https://image.tmdb.org/t/p/w500/9OdZKUdGfaBAUwRLbtWpFWKbILO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15359, 'Wonder Woman', 'On the mystical island of Themyscira, a proud and fierce warrior race of Amazons have raised a daughter of untold beauty, grace and strength: Princess Diana. When an Army fighter pilot, Steve Trevor, crash-lands on the island, the rebellious and headstrong Diana defies Amazonian law by accompanying Trevor back to civilization.', '2009-03-03', 7.20, 'https://image.tmdb.org/t/p/w500/u6sI0yLJXkmrbSJzVRCmmfa4nhx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15577, 'Crossing Over', 'Immigrants from around the world enter Los Angeles every day, with hopeful visions of a better life, but little notion of what that life may cost. Their desperate scenarios test the humanity of immigration enforcement officers. In Crossing Over, writer-director Wayne Kramer explores the allure of the American dream, and the reality that immigrants find – and create -- in 21st century L.A.', '2009-02-10', 6.10, 'https://image.tmdb.org/t/p/w500/6A4WdvbWHJoIN4Y9Q5HXG8R1VYV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15598, 'Alfie', 'A young man leads a promiscuous lifestyle until several life reversals make him rethink his purposes and goals in life.', '1966-03-29', 6.52, 'https://image.tmdb.org/t/p/w500/tPUqgfGMkZazRZ1UO41j2Fiib5C.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15592, 'Beaches', 'A privileged rich debutante and a cynical struggling entertainer share a turbulent, but strong childhood friendship over the years.', '1988-12-21', 6.69, 'https://image.tmdb.org/t/p/w500/vol5TCGHDbi8r0yo0TrIGFiGxJ7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15600, 'Missing', 'Based on the real-life experiences of Ed Horman. A conservative American businessman travels to Chile to investigate the sudden disappearance of his son after a military takeover. Accompanied by his son''s wife he uncovers a trail of cover-ups that implicate the US State department which supports the dictatorship.', '1982-02-12', 7.25, 'https://image.tmdb.org/t/p/w500/fAAhC4RkpXu7SJgIESWQwVxcelo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15602, 'Grumpier Old Men', 'A family wedding reignites the ancient feud between next-door neighbors and fishing buddies John and Max. Meanwhile, a sultry Italian divorcée opens a restaurant at the local bait shop, alarming the locals who worry she''ll scare the fish away. But she''s less interested in seafood than she is in cooking up a hot time with Max.', '1995-12-22', 6.46, 'https://image.tmdb.org/t/p/w500/1FSXpj5e8l4KH6nVFO5SPUeraOt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15689, 'Dead Meat', 'A couple''s vacation to Ireland transforms into a nightmare as a virus spreads from slaughtered animals to humans, causing the dead to rise and feast on the living.', '2004-10-01', 4.79, 'https://image.tmdb.org/t/p/w500/5PAu5iX2M0ddpkgQt3mzURhQWe2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15698, 'Running Scared', 'Two street-wise Chicago cops have to shake off some rust after returning from a Key West vacation to pursue a drug dealer that nearly killed them in the past.', '1986-06-27', 6.09, 'https://image.tmdb.org/t/p/w500/nSiRjhc7aTVPonXAhmTZAPqd2jT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15708, 'Latter Days', 'Christian, a hunky, 20-something, West Hollywood party boy gets more than he bargains for when he tries to seduce Aaron, a sexually confused Mormon missionary who moves into his apartment complex.', '2004-01-30', 6.87, 'https://image.tmdb.org/t/p/w500/uwzJL11Xp6h8stocOz6E8e2LWtB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15720, 'The Man from Elysian Fields', 'A failed novelist''s inability to pay the bills strains relations with his wife and leads him to work at an escort service, where he becomes entwined with a wealthy woman whose husband is a successful writer.', '2001-09-13', 5.90, 'https://image.tmdb.org/t/p/w500/mCUzyYDMHNdihZVTVH1g3KvTo8p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15361, 'Shanghai Kiss', 'Liam Liu unwittingly gets involved with a high school girl. He suddenly has to go to China after learning from his father that he has inherited his grandmother''s home in Shanghai. He''s not very appreciative of his Chinese roots, and at first, only wants to sell the house and get back to the U.S. as fast as possible. He gets a taste of the Chinese culture and ends up having some big decisions to make.', '2007-03-17', 5.90, 'https://image.tmdb.org/t/p/w500/yMXs40GxPhVSqzGudmqg8Yx5LDR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15723, 'The Big Kahuna', 'Three salesmen working for a firm that makes industrial lubricants are waiting in the company''s "hospitality suite" at a manufacturers'' convention for a "big kahuna" named Dick Fuller to show up, in hopes they can persuade him to place an order that could salvage the company''s flagging sales.', '1999-11-17', 6.77, 'https://image.tmdb.org/t/p/w500/sMhWWdW6V3HXFanELFA1oHdvboS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15658, 'Flowers in the Attic', 'After the death of her husband, a mother takes her kids off to live with their grandparents in a huge, decrepit old mansion. However, the kids are kept hidden in a room just below the attic, visited only by their mother who becomes less and less concerned about them and their failing health, and more concerned about herself and the inheritence she plans to win back from her dying father.', '1987-11-20', 6.31, 'https://image.tmdb.org/t/p/w500/upcJxm5AquYh9lTPaJEQ6tgoVbg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15734, 'Girls! Girls! Girls!', 'When he learns that his boss is retiring to Arizona, sailor Ross Carpenter has to find a way to buy the Westwind, a boat that he and his father built. Meanwhile, he''s also caught between two women: insensitive club singer Robin and sweet Laurel.', '1962-11-21', 5.40, 'https://image.tmdb.org/t/p/w500/41NoayYsUD4LPv586apJxl0iNzf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15730, 'Love & Human Remains', 'In a Canadian metropolis, failed actor David shares a place with the bookish Candy, whom he dated before coming out as gay. While David, who now waits tables, pursues an aimless romance with a younger coworker, Candy dabbles in both same-sex and heterosexual affairs. As David and Candy''s odd assortment of friends — including a telepathic sex worker and an ill-tempered yuppie — pass in and out of their beds, a serial murder stalks the city''s women.', '1994-07-22', 5.76, 'https://image.tmdb.org/t/p/w500/9QVw6cPXfsjr4PncE1TeWudeLmh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15739, 'Annie', 'An orphan in a facility run by the mean Miss Hannigan, Annie believes that her parents left her there by mistake. When a rich man named Oliver "Daddy" Warbucks decides to let an orphan live at his home to promote his image, Annie is selected. While Annie gets accustomed to living in Warbucks'' mansion, she still longs to meet her parents. So Warbucks announces a search for them and a reward, which brings out many frauds.', '1982-05-21', 6.50, 'https://image.tmdb.org/t/p/w500/xopqD99S1GqQOG8UAeSElsX9MeP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15745, 'Made', 'Two aspiring boxers and lifelong friends get involved in a money-laundering scheme through a low-level organized crime group.', '2001-07-13', 5.81, 'https://image.tmdb.org/t/p/w500/4HC6ieptXO2gjqbSEsfkOwsGubN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15762, 'Night of the Creeps', 'In 1959, an alien experiment crashes to earth and infects a fraternity member. They freeze the body, but in the modern day, two geeks pledging a fraternity accidentally thaw the corpse, which proceeds to infect the campus with parasites that transform their hosts into killer zombies.', '1986-08-21', 6.76, 'https://image.tmdb.org/t/p/w500/A3s2tQGNb6mhlr1hPZeE5F8IUwp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15764, 'Sophie''s Choice', 'Stingo, a young writer, moves to Brooklyn in 1947 to begin work on his first novel. As he becomes friendly with Sophie and her lover Nathan, he learns that she is a Holocaust survivor. Flashbacks reveal her harrowing story, from pre-war prosperity to Auschwitz. In the present, Sophie and Nathan''s relationship increasingly unravels as Stingo grows closer to Sophie and Nathan''s fragile mental state becomes ever more apparent.', '1982-12-08', 7.30, 'https://image.tmdb.org/t/p/w500/rZDPbPTFwuKgr5b9jixGFNYkGYt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15765, 'What''s Love Got to Do with It', 'Singer Tina Turner rises to stardom while mustering the courage to break free from her abusive husband Ike.', '1993-06-09', 7.05, 'https://image.tmdb.org/t/p/w500/btC4819GhihmkCELqO3qgepNGos.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15767, 'Godzilla: Final Wars', 'Humanity finally rids themselves of Godzilla, imprisoning him in an icy tomb in the South Pole. All is peaceful until various monsters emerge to lay waste to Earth''s cities. Overwhelmed, humanity is seemingly saved by a race of benevolent aliens known as Xiliens. But not all is what it seems with these bizarre visitors. If humanity wishes to survive, they must reluctantly resurrect their most hated enemy, Godzilla.', '2004-12-04', 7.11, 'https://image.tmdb.org/t/p/w500/21lWA4YyYppVnwAPOiBkGrt2FGr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15785, 'Cherry 2000', 'When successful businessman Sam Treadwell finds that his android wife, Cherry model 2000 has blown a fuse, he hires sexy renegade tracker E. Johnson to find her exact duplicate. But as their journey to replace his perfect mate leads them into the treacherous and lawless region of ''The Zone'', Treadwell learns the hard way that the perfect woman is made not of computer chips and diodes.', '1987-11-10', 5.94, 'https://image.tmdb.org/t/p/w500/t3uds00MHLsibhKLCL0BbCEGxXb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15789, 'A Goofy Movie', 'Goofy’s teenage son Max is desperate to impress his crush and fit in at school. After well-meaning but ignorant Goofy suddenly whisks him away on a cross-country road trip—messing up Max’s first date plans in the process—Goofy’s old-school parenting and Max’s desire for independence lead to a vacation of hilarious mishaps, as they both learn to see eye to eye and listen to each other.', '1995-04-05', 7.04, 'https://image.tmdb.org/t/p/w500/bycmMhO3iIoEDzP768sUjq2RV4T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15771, 'Class Action', 'A liberal activist lawyer alienated his daughter Maggie years ago when she discovered his many affairs. Now a conservative corporate lawyer, Maggie agrees to go up against her father in court. To gain promotion, she must defend an auto manufacturer against charges that their explosion-prone station wagons are unsafe. As her mother begs for peace, Maggie takes on her dad in a trial that turns increasingly personal and nasty.', '1991-03-15', 6.31, 'https://image.tmdb.org/t/p/w500/9BOsvZL2DuE2JFGYOssynTjs8K6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15794, 'White Heat', 'A psychopathic criminal with a mother complex makes a daring break from prison and then leads his old gang in a chemical plant payroll heist. After the heist, events take a crazy turn.', '1949-09-02', 7.65, 'https://image.tmdb.org/t/p/w500/v7cPOHKKZI9qChi7HDUxNIhEcLR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15797, 'Only the Strong', 'Former Green Beret Louis Stevens returns to his hometown of Miami after completing military service in Brazil, only to learn that his old high school has become a haven for gangs and drug dealers. After Stevens uses his capoeira skills to kick several drug dealers off of the school property, Kerrigan, one of Stevens'' old teachers, sees the impact that Stevens has on the students. Kerrigan gives him the task of teaching Capoeira to a handful of the worst at-risk students at the school.', '1993-08-27', 6.93, 'https://image.tmdb.org/t/p/w500/pPWV5rBhCgzlzhwkpdRG7a7UZqt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15802, 'Tokyo Decadence', 'A submissive hooker goes about her trade, suffering abuse at the hands of Japanese salarymen and Yakuza types. She''s unhappy about her work, and is apparently trying to find some sort of appeasement for the fact that her lover has married.', '1992-01-06', 6.00, 'https://image.tmdb.org/t/p/w500/ya3HsnwavmtQYMxnGS5T5RV6do0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15800, 'Trekkies', 'Denise Crosby takes a first look at the huge fans of "Star Trek" from around America and how the series has affected and shaped their lives.', '1997-10-18', 6.34, 'https://image.tmdb.org/t/p/w500/o6MYZAcI2A7VfJkcIvCDbFPISLP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15813, 'Dark Blue World', 'Lt. Franta Slama is a top pilot in the Czech Air Force who is assigned to train a promising young flier, Karel Vojtisek, and they soon become friends. When Nazi Germany invades Czechoslovakia in 1939, they both reject the authority of their new leaders and escape to England where they join other Czech exiles in the RAF. While flying a mission over England, Karel crash lands and happens upon the farmhouse of Susan, a young woman whose husband is in the Navy. Karel soon falls head over heels for Susan but, while they enjoy a brief fling, in time Susan decides she prefers the company of the older and more worldly Franta. As Franta and Karel struggle to maintain their friendship despite their romantic rivalry.', '2001-05-17', 6.90, 'https://image.tmdb.org/t/p/w500/9vu152xTO89l9UWDcqmE9zVD5xK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15362, 'Mesrine: Public Enemy #1', 'After nearly two decades of legendary criminal feats, making him France''s most notorious criminal while simultaneously feeding his desire for media attention and public adoration, Mesrine becomes increasingly paranoid and isolated, leading to a dramatic confrontation with the law that ultimately seals his fate as the nation''s most infamous public enemy.', '2008-11-19', 7.28, 'https://image.tmdb.org/t/p/w500/k9lhZ0PhY78nzwG034rNpsLXlpW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15865, 'The Zone', 'Residents of an enclosed neighborhood in the middle of Mexico DF are shocked by a violent crime, and for one resident in particular, young Alejandro, the drama is ratcheted up when he encounters the lone kid who escaped the event and is hiding out within the neighborhood''s borders.', '2007-09-01', 6.34, 'https://image.tmdb.org/t/p/w500/tAnUU7OB6QdnmYEd0R9veXVCXBr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15363, 'Something New', 'Kenya McQueen thought she had it all: a successful career, good friends and family. There was just one thing she didn''t have under control: her love life. All that changes when she meets sexy, free-spirited Brian Kelly. But when her ideal man arrives on the scene, Kenya must decide between the relationship everyone expects and the romance no one expected.', '2006-01-29', 6.45, 'https://image.tmdb.org/t/p/w500/lcwB60GqQaWUgUw1CCE5gm5XHI1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15873, 'The Bridge at Remagen', 'In March of 1945, as the War in Europe is coming to a close, fighting erupts between German and American troops at the last remaining bridgehead across the Rhine.', '1969-06-25', 6.74, 'https://image.tmdb.org/t/p/w500/dIdzAPIYfDbjFP7yyKXbo8wOwLW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15613, 'Fire in the Sky', 'After clearing brush for the government, a group of men return to town claiming their friend was abducted. Despite no apparent motive or evidence of foul play, no-one believes their story and his disappearance is treated as murder.', '1993-03-12', 6.70, 'https://image.tmdb.org/t/p/w500/rTFrjAp1YV49DSTUGCyKSkaEHC8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15660, 'Mommie Dearest', 'Renowned film star Joan Crawford''s abuse towards Christina, her adopted daughter, intensifies as her professional and romantic relationships turn sour.', '1981-09-16', 6.36, 'https://image.tmdb.org/t/p/w500/3Amv5uQfadEonn7SmYLfNnoeOSu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15624, 'Conversations with Other Women', 'Reunited at a wedding after many years, former lovers again feel the pull of a mutual attraction neither is willing to admit. Escaping the reception for the privacy of a hotel room, the unnamed pair explore the choices of the past that led them to the present.', '2006-06-07', 6.33, 'https://image.tmdb.org/t/p/w500/5iA72q3avmveCiOtx1Uaj22pgXI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
