INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15373, 'Role Models', 'Two salesmen trash a company truck on an energy drink-fueled bender. Upon their arrest, the court gives them a choice: do hard time or spend 150 service hours with a mentorship program. After one day with the kids, however, jail doesn''t look half bad.', '2008-11-07', 6.48, 'https://image.tmdb.org/t/p/w500/ki79dSjh6Rr51xrsz4dT04UGxSU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
