INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15618, 'Robot Jox', '50 years after a nuclear war, the two superpowers handle territorial disputes in a different way. Each fields a giant robot to fight one-on-one battles in official matches, each piloted by a man inside, known as robot jockeys or jox. The contest for possession of Alaska will be fought by two of the best. The conscientious Achilles fights for the Americans. Opposing him is a Russian, Alexander.', '1990-11-21', 5.51, 'https://image.tmdb.org/t/p/w500/j8JgIZkmbpJ80HdR5mBT7fFpRSP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15384, 'Red Cliff II', 'The battle of Red Cliff continues and the alliance between Xu and East Wu is fracturing.  With Cao Cao''s massive forces on their doorstep, will the kingdoms of Xu and East Wu survive?', '2009-01-07', 7.28, 'https://image.tmdb.org/t/p/w500/4sZc0Fx5ECBDwDswKA0zsmh7o1n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15846, 'The Burrowers', 'It is 1879 in the Dakota Territories, a band of men who set out to find and recover a family of settlers that has mysteriously vanished from their home. Expecting the offenders to be a band of fierce natives, but they soon discover that the real enemy stalks them from below.', '2008-09-09', 5.90, 'https://image.tmdb.org/t/p/w500/usdEYNShCQi6IcQh2mMnnALTRhT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15867, 'Interiors', 'When Eve, an interior designer, is deserted by her husband of many years, Arthur, the emotionally glacial relationships of the three grown-up daughters are laid bare. Twisted by jealousy, insecurity and resentment, Renata, a successful writer; Joey, a woman crippled by indecision; and Flyn, a budding actress; struggle to communicate for the sake of their shattered mother. But when their father unexpectedly falls for another woman, his decision to remarry sets in motion a terrible twist of fate…', '1978-08-02', 6.80, 'https://image.tmdb.org/t/p/w500/sTPy6Kfa1FRED1eaZdVex8b2MdB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15667, 'The Last Winter', 'In the Arctic region of Northern Alaska, an oil company''s advance team struggles to establish a drilling base that will forever alter the pristine land. After one team member is found dead, a disorientation slowly claims the sanity of the others as each of them succumbs to a mysterious fear.', '2006-09-11', 5.38, 'https://image.tmdb.org/t/p/w500/uDHwjlPWcyNEkfgOVwIz3IaUNXC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15849, 'The Mummy', 'An ancient Egyptian priest named Imhotep is revived when a British archaeological expedition finds his mummy and one of the researchers accidentally reads an ancient life-giving spell. Imhotep escapes from the field site and searches for the reincarnation of the soul of his lover.', '1932-12-22', 6.75, 'https://image.tmdb.org/t/p/w500/vSKpbZVvzqQcw6htiyEinbCY9vq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
