INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16018, 'American Hardcore', 'Inspired by Steven Blush''s book "American Hardcore: A tribal history" Paul Rachman''s feature documentary debut is a chronicle of the underground hardcore punk years from 1979 to 1986. Interviews and rare live footage from artists such as Black Flag, Bad Brains, Minor Threat, SS Decontrol and the Dead Kennedys.', '2006-09-22', 6.89, 'https://image.tmdb.org/t/p/w500/v0nxzzUYHrudMn32WVIYdKnxe2M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
