INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16023, 'South Park: Imaginationland', 'Some of the boys from South Park Elementary find themselves on a balloon ride to an imaginary land. Upon their arrival they''re faced with an unimaginable threat.', '2008-03-11', 7.89, 'https://image.tmdb.org/t/p/w500/eENI0WN2AAuQWfPmQupzMD6G4gV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16052, 'Selena', 'In this biographical drama, Selena Quintanilla is born into a musical Mexican-American family in Texas. Her father, Abraham, realizes that his young daughter is talented and begins performing with her at small venues. She finds success and falls for her guitarist, Chris Perez, who draws the ire of her father. Seeking mainstream stardom, Selena begins recording an English-language album which, tragically, she would never complete.', '1997-03-21', 7.72, 'https://image.tmdb.org/t/p/w500/j8xX3yBAFOayfSaImgLZPnAcdWz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16028, 'They', 'A psychology student who experienced night terrors as a child must face the chilling realization that her nightmares were not all in her head.', '2002-11-01', 5.03, 'https://image.tmdb.org/t/p/w500/6i3ixJTacgdEAypVes6uUmsJr64.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15901, 'Faces of Death III', 'Gory real-life footage of blood and guts on the German Autobahn, drug smugglers getting blown away, a parachutist landing in a crocodile pit, torture and murder in El Salvador, a PCP addict getting stoned, a videotaped rape/murder, a car thief getting ripped apart by two junkyard dogs, and much more.', '1985-03-10', 3.73, 'https://image.tmdb.org/t/p/w500/xsESeofFGmzpOdE74mBoN2kUxYK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15659, 'Foul Play', 'A shy San Francisco librarian and a bumbling cop fall in love as they solve a crime involving albinos, dwarves, and the Catholic Church.', '1978-07-14', 6.30, 'https://image.tmdb.org/t/p/w500/mk3enoeLNRXRnYGxKcvPXYY1xci.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16068, 'Babylon 5: The Legend of the Rangers - To Live and Die in Starlight', 'After being punished for retreat from combat, Ranger David Martel is given command of the Liandra, a haunted 20-year old Minbari fighting ship. He''s escorting ambassadors to a secret archaeological site, the oldest city on record and a clue to a dangerous ancient race.', '2002-04-30', 6.00, 'https://image.tmdb.org/t/p/w500/bIhOn8xKsOQGjiNCQ8sKoQyYmNa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16070, 'This Film Is Not Yet Rated', 'Kirby Dick''s provocative documentary investigates the secretive and inconsistent process by which the Motion Picture Association of America (MPAA) rates films, revealing the organization''s underhanded efforts to control culture. Dick questions whether certain studios get preferential treatment and exposes the discrepancies in how the MPAA views sex and violence.', '2006-09-01', 7.06, 'https://image.tmdb.org/t/p/w500/nXo26FkBBdiEaEDzOPkrSFZC7zO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
