INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16082, 'White Nights', 'After his plane crashes in Siberia, a Russian dancer, who defected to the West, is held prisoner in the Soviet Union. The KGB keeps him under watch and tries to convince him to become a dancer for the Kirov Academy of Ballet again. Determined to escape, he befriends a black American expatriate and his pregnant Russian wife, who agree to help him escape to the American Embassy.', '1985-11-22', 6.71, 'https://image.tmdb.org/t/p/w500/ampweVzwwWQHSwFvz2YTyRIrJza.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
