INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16084, 'Freaky Friday', 'School girl Annabel is hassled by her mother, and Mrs. Andrews is annoyed with her daughter, Annabel. They both think that the other has an easy life. On a normal Friday morning, both complain about each other and wish they could have the easy life of their daughter/mother for just one day and their wishes come true as a bit of magic puts Annabel in Mrs. Andrews'' body and vice versa. They both have a Freaky Friday.', '1976-12-17', 6.11, 'https://image.tmdb.org/t/p/w500/8kHZmN4Ao70LTgaiUti23Zl7fFq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
