INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16096, 'House Party 2', 'Kid''N''Play leave their neighborhood and enter the world of adulthood and higher education. Play attempts to get rich quick in the music business while Kid faces the challenges of college.', '1991-10-23', 5.45, 'https://image.tmdb.org/t/p/w500/4iKDkzUZtS6vzINfbwYHAb1bNbA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16093, 'Carnival of Souls', 'Mary Henry ends up the sole survivor of a fatal car accident through mysterious circumstances. Trying to put the incident behind her, she moves to Utah and takes a job as a church organist. But her fresh start is interrupted by visions of a fiendish man. As the visions begin to occur more frequently, Mary finds herself drawn to the deserted carnival on the outskirts of town. The strangely alluring carnival may hold the secret to her tragic past.', '1962-11-02', 6.94, 'https://image.tmdb.org/t/p/w500/AdbQsFB8pS090l0NO3uBtLZy2zw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16094, 'House Party', 'Young Kid has been invited to a party at his friend Play''s house. But after a fight at school, Kid''s father grounds him. None the less, Kid sneaks out when his father falls asleep. But Kid doesn''t know that three of the thugs at school have decided to give him a lesson in behavior.', '1990-01-20', 6.39, 'https://image.tmdb.org/t/p/w500/hmUsEUI7RdgvTznkLCNSOHnjU4O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
