INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16113, 'The Delta Force', 'A 707 aircraft jetliner, en route from Athens to Rome and then to New York City, is hijacked by Lebanese terrorists, who demand that the pilot take them to Beirut. What the terrorists don''t realize is that an elite team of commandos have been called in to eliminate all terrorists on the jetliner.', '1986-02-14', 6.01, 'https://image.tmdb.org/t/p/w500/jBx4an9yU7FFbXv4tWc1HRJomGJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
