INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16148, 'Zero Effect', 'Daryl Zero is a private investigator and—along with his assistant, Steve Arlo—he solves impossible crimes and puzzles. Although Daryl''s a master investigator, he doesn''t know what to do with himself when he''s not working; he has no social skills, writes bad music and drives Steve crazy.', '1998-01-30', 6.27, 'https://image.tmdb.org/t/p/w500/yFALvZFwqnh5ESarNoVd5KtizCo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
