INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16156, 'Sarah Silverman: Jesus Is Magic', 'Sarah Silverman appears before an audience in Los Angeles with several sketches, taped outside the theater, intercut into the stand-up performance. Themes include race, sex, and religion. Her comic persona is a self-centered hipster, brash and clueless about her political incorrectness. A handful of musical numbers punctuate the performance.', '2005-02-11', 6.39, 'https://image.tmdb.org/t/p/w500/uKuAGLz9eUWw3tnuXPRChpK7lYI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
