INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15651, 'For the Bible Tells Me So', 'An exploration of the intersection between religion and homosexuality in the U.S. and how the religious right has used its interpretation of the Bible to stigmatize the gay community.', '2007-10-05', 6.94, 'https://image.tmdb.org/t/p/w500/sz7ucLIEpu1KPmrBW2eB5fyqv4E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15916, 'Angel''s Egg', 'In the ruins of a strange city, a young girl takes care of a large egg she holds carefully in her arms. She bonds with a boy who is searching for a bird he saw in a dream.', '1985-12-22', 7.70, 'https://image.tmdb.org/t/p/w500/dcEUGvckbePFzPKhGXnS9T3kZMG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15665, 'The Eyes of Tammy Faye', 'A documentary look, mostly through the eyes of Tammy Faye Bakker Messner, at her rise and fall as a popular televangelist with husband Jim Bakker.', '2000-01-25', 6.26, 'https://image.tmdb.org/t/p/w500/r84Qve8mVeDXBKnSnBSQIS2OaD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16150, 'Darkon', 'Darkon is an award-winning feature-length documentary film that follows the real-life adventures of the Darkon Wargaming Club in Baltimore, Maryland, a group of fantasy live-action role-playing (LARP) gamers.', '2006-09-12', 6.88, 'https://image.tmdb.org/t/p/w500/kXyS0tsKssgECta1HeQCqIho1QH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16153, 'Alice Doesn''t Live Here Anymore', 'After her husband dies, Alice and her son, Tommy, leave their small New Mexico town for California, where Alice hopes to make a new life for herself as a singer. Money problems force them to settle in Arizona instead, where Alice takes a job as waitress in a small diner.', '1974-12-09', 6.97, 'https://image.tmdb.org/t/p/w500/A99yzz1W3NCG6zR2HXSwn2kWlse.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16186, 'Diary of a Mad Black Woman', 'Charles, an attorney, and Helen, his devoted wife, seem to have everything – money, a beautiful mansion – the American Dream. However, as Helen prepares to celebrate their 18th wedding anniversary, her life takes an unexpected twist when she comes home to find her clothes packed up in a U-Haul van parked in the driveway. Charles is divorcing her and kicks her out. Helen moves in with her grandmother Madea, an old woman who doesn''t take any lip from anyone. Madea helps Helen through these tough times by showing her what is really important in life. Helen is forced to rediscover love, life, and religion in her pursuit for happiness.', '2005-02-25', 6.51, 'https://image.tmdb.org/t/p/w500/4w36ckDhsWFPD9XaHOOJb1ru7JZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16222, 'Whatever It Takes', 'A nerdy teen, Ryan Woodman is smitten with the popular and gorgeous Ashley Grant, who apparently has no interest in him. Meanwhile, dim star athlete Chris Campbell has his eye on Ryan''s brainy and beautiful friend, Maggie Carter. The two agree to help each other in their romantic quests, but, as they come closer to their goals, both Ryan and Chris suspect that they might be pursuing the wrong girls.', '2000-03-31', 5.76, 'https://image.tmdb.org/t/p/w500/u9UtZNMj2m7dtOP6RcMAeRfqmnF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16225, 'Heavy Metal 2000', 'Upon discovery of a shard of what could be the Loc-Nar, a miner named Tyler becomes possessed with an insatiable hunger for power and a thirst for immortality. On his way to the planet of youth, Tyler wipes out most of a space colony and kidnaps a beautiful young woman. His only mistake is that he doesn''t kill her sister, Julie, who then sets out on a mission of rescue and revenge.', '2000-04-19', 6.04, 'https://image.tmdb.org/t/p/w500/dCggUkmi3Fyc1HrSnyaSxKPrG4n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16227, 'Dark Passage', 'A man convicted of murdering his wife escapes from prison and works with a woman to try and prove his innocence.', '1947-09-05', 7.29, 'https://image.tmdb.org/t/p/w500/dvwmiD6qQ05gojrFQRaFbdhbNDF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15920, 'Autumn Spring', 'A bittersweet comedy starring the great Vlastimil Brodský as Fanda, an old man who refuses to grow up. Despite pleas from his exasperated wife who wants him to make serious decisions about the future, Fanda ignores the nagging and spends his days seeking amusement and adventure.', '2001-09-27', 6.95, 'https://image.tmdb.org/t/p/w500/A1RHlp8q0QxI4SREgSvUEe3asDk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16229, 'Prozac Nation', 'When talented young writer Elizabeth Wurtzel earns a scholarship to Harvard, she sees it as her chance to escape the pressures of her working-class background and concentrate on her true talent. But what starts out so promising leads to self-destructive behavior and paralyzing depression that reflects an entire generation''s struggle to navigate the effects of divorce, drugs, sex, and high expectations.', '2003-06-13', 6.36, 'https://image.tmdb.org/t/p/w500/4QB1h6mxlmQVM8BtYMybTwL2foc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15919, 'Marty', 'Marty, a butcher who lives in the Bronx with his mother, is unmarried at 34. Good-natured but socially awkward, he faces constant badgering from family and friends to get married but has reluctantly resigned himself to bachelorhood. He then meets Clara, an unattractive school teacher. Realising their emotional connection, Marty promises to call, but family and friends try to convince him not to.', '1955-04-11', 7.46, 'https://image.tmdb.org/t/p/w500/8tnGO5VoAQII4DbE3hozWKhV4BY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16232, 'Mr. 3000', 'Aging baseball star who goes by the nickname, Mr. 3000, finds out many years after retirement that he didn''t quite reach 3,000 hits. Now at age 47 he''s back to try and reach that goal.', '2004-06-15', 5.29, 'https://image.tmdb.org/t/p/w500/g7CNkytZsZzQ8ZEr8F4SmrhjI5y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16234, 'Batman Beyond: Return of the Joker', 'The Joker is back with a vengeance, and Neo-Gotham''s Dark Knight, Terry McGinnis, needs answers as he stands alone to face the old Gotham''s most infamous Clown Prince of Crime.', '2000-12-12', 7.30, 'https://image.tmdb.org/t/p/w500/cH8wZs5vzL6YwbZpC5qWEpEacQN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16235, 'Amityville II: The Possession', 'Anthony and Dolores Montelli, along with their four children, move into their dream house in Amityville and are immediately plagued by a string of paranormal experiences. When the abusive Anthony wrongly places the blame on the children, Dolores recruits a local Catholic priest to exorcise the house.', '1982-09-24', 5.73, 'https://image.tmdb.org/t/p/w500/xx9K2m2Arr5EZUQtmggKtEK1f2a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16241, 'The Boys from Brazil', 'Nazi hunter Ezra Lieberman discovers a sinister and bizarre plot, masterminded by Dr. Josef Mengele, to rekindle the Third Reich.', '1978-10-05', 6.73, 'https://image.tmdb.org/t/p/w500/w7IZT1HJNmWcEj3Axwlwhya02OX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16246, 'Gone in 60 Seconds', 'Insurance investigator Maindrian Pace and his team lead double-lives as unstoppable car thieves. When a South American drug lord pays Pace to steal 48 cars for him, all but one, a 1973 Ford Mustang, are in the bag. As Pace prepares to rip-off the fastback, codenamed "Eleanor", in Long Beach, he is unaware that his boss has tipped off the police after a business dispute.', '1974-07-28', 6.20, 'https://image.tmdb.org/t/p/w500/qYyeAodAOe4nHuzkHdN35ValzLT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16240, 'Breakfast with Scot', 'The lives of Eric, an ex hockey player, and his partner Sam, are thrown into turmoil when they are forced to take in Scot, a flamboyant 11-year-old.', '2007-11-16', 6.10, 'https://image.tmdb.org/t/p/w500/4Awq2OLMA56LNvs7wMhOdkpyqiy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16249, 'Blackbeard''s Ghost', 'The eponymous wraith returns to Earth to aid his descendant, elderly Emily Stowecroft. The villains want to kick Emily and her friends out of their group home so that they can build a crooked casino. Good guy Steve Walker gets caught in the middle of the squabble after evoking Blackbeard''s ghost.', '1968-02-08', 6.72, 'https://image.tmdb.org/t/p/w500/bEMEjagTsdkUi7Jzxe0lQsquD7J.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16248, 'D.A.R.Y.L.', 'Daryl is a normal 10-year-old boy in many ways. However, unbeknown to his foster parents and friends, Daryl is actually a government-created robot with superhuman reflexes and mental abilities. Even his name has a hidden meaning -- it''s actually an acronym for Data Analyzing Robot Youth Life-form. When the organization that created him deems the "super soldier" experiment a failure and schedules Daryl to be disassembled, it is up to a few rogue scientists to help him escape.', '1985-06-14', 6.41, 'https://image.tmdb.org/t/p/w500/87huhTOQijJy0pLhusZfest1MoZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15677, '84 Charing Cross Road', 'When a humorous script-reader in her New York apartment sees an ad in the Saturday Review of Literature for a bookstore in London that does mail order, she begins a very special correspondence and friendship with Frank Doel, the bookseller who works at Marks & Co., 84 Charing Cross Road.', '1987-02-13', 7.20, 'https://image.tmdb.org/t/p/w500/sbImaHsRP9TpCNIi4xMizaphZhk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16258, 'The Butterfly Effect 3: Revelations', 'The story revolves around a man trying to uncover the mysterious death of his girlfriend and save an innocent man from the death chamber in the process, by using his unique power to time travel. However in attempting to do this, he also frees a spiteful serial-killer.', '2009-01-09', 5.50, 'https://image.tmdb.org/t/p/w500/7utgDyfae053YExAuUKcwkzUKMs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16263, 'Girls Just Want to Have Fun', 'Janey is new in town. She soon meets Lynne, a classmate who shares her passion for the local show ''Dance TV''. When a competition is announced to find new Dance TV performers, Janey and Lynne are determined to audition. The only problem is that Janey''s father doesn''t approve of that kind of thing.', '1985-04-12', 6.13, 'https://image.tmdb.org/t/p/w500/yhbuTnTA6wu5hOXL5uc3rRFLnCl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16270, 'Career Opportunities', 'Josie, the daughter of the town''s wealthiest businessman, faces problems at home and wishes to leave town but is disoriented. Her decision is finalized after she falls asleep in a Target dressing room. She awakens to find herself locked in the store overnight with the janitor, Jim, the town "no hoper" and liar.', '1991-03-29', 6.90, 'https://image.tmdb.org/t/p/w500/xi0fBIBDZQqJ8U0hUvwhpxFd4jM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16274, 'Holiday', 'Johnny Case, a freethinking financier, has finally found the girl of his dreams — Julia Seton, the spoiled daughter of a socially prominent millionaire — and she''s agreed to marry him. But when Johnny plans a holiday for the two to enjoy life while they are still young, his fiancée has other plans & that is for Johnny to work in her father''s bank!', '1938-05-26', 7.30, 'https://image.tmdb.org/t/p/w500/vTswoixIge9o84NLlWGaWl5lrHO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16275, 'Dave Chappelle: Killin'' Them Softly', 'Dave Chappelle returns for a stand-up to D.C. and riffs on politics, police, race relations, drugs, Sesame Street and more.', '2000-07-26', 8.08, 'https://image.tmdb.org/t/p/w500/xQAwaRVkaYtgEbFzsUrYzduJsOd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16279, 'The Great Buck Howard', 'When a law school dropout answers an advertisement to be a personal assistant he unknowingly signs on to work for a belligerent has-been magician struggling to resurrect his career. This leads to a journey across the country staging the comeback of a lifetime.', '2008-01-18', 6.01, 'https://image.tmdb.org/t/p/w500/iglKvmA7sq6Pnd6KWFnT6WW9Vpn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16281, 'Creepshow', 'Five grisly tales from a 1950s-style comic, including a murdered father rising from beyond, a bizarre meteor, a vengeful husband, a mysterious crate''s occupant, and a plague of cockroaches.', '1982-11-10', 6.89, 'https://image.tmdb.org/t/p/w500/4SoyTCEpsgLjX6yAyMsx3AsAyRQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16290, 'Jackass 3D', 'Johnny Knoxville, Bam Margera, Steve-O, Wee Man and the rest of their fearless and foolhardy friends take part in another round of outrageous pranks and stunts. In addition to standing in the path of a charging bull, launching themselves into the air and crashing through various objects, the guys perform in segments such as "Sweatsuit Cocktail," "Beehive Tetherball" and "Lamborghini Tooth Pull."', '2010-10-15', 6.64, 'https://image.tmdb.org/t/p/w500/uPirN07su7LFixyZyLrNMMQ9u1E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16295, 'Higher Learning', 'African-American student Malik is on a track scholarship; academics are not his strong suit, and he goes in thinking that his athletic abilities will earn him a free ride through college. Fudge, a "professional student" who has been at Columbus for six years so far, becomes friendly with Malik and challenges his views about race and politics in America.', '1995-01-11', 6.30, 'https://image.tmdb.org/t/p/w500/tuud1Blsdwo1KQRdz5UVwjlLAWQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16296, 'Killer Klowns from Outer Space', 'Aliens disguised as clowns crash land on Earth in a rural town to capture unsuspecting victims in cotton candy cocoons for later consumption.', '1988-05-27', 6.65, 'https://image.tmdb.org/t/p/w500/lHdAk5T42ofyi3NTjmrdyR7xPmY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16288, 'Creepshow 2', 'Three macabre tales from the latest issue of a boy''s favorite comic book, dealing with a vengeful wooden Native American, a monstrous blob in a lake, and an undying hitchhiker.', '1987-05-01', 6.24, 'https://image.tmdb.org/t/p/w500/bbanIymLuTYmQGis9nlCkFlT1eg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16297, 'With Honors', 'Convinced he''ll graduate with honors because of his thesis paper, a stuffy Harvard student finds his paper being held hostage by a homeless man, who might be the guy to school the young man in life.', '1994-04-29', 6.70, 'https://image.tmdb.org/t/p/w500/eWJ2Y7CRvlv1KVfAJGRcH95i1pY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16305, 'Sullivan''s Travels', 'Successful movie director John L. Sullivan, convinced he won''t be able to film his ambitious masterpiece until he has suffered, dons a hobo disguise and sets off on a journey, aiming to "know trouble" first-hand. When all he finds is a train ride back to Hollywood and a beautiful blonde companion, he redoubles his efforts, managing to land himself in more trouble than he bargained for when he loses his memory and ends up a prisoner on a chain gang.', '1941-11-30', 7.40, 'https://image.tmdb.org/t/p/w500/z5cqIM0ysVjkCmaDfyTQnlozdIp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16314, '3 Ninjas', 'Each year, three brothers Samuel, Jeffrey and Michael Douglas visits their Japanese grandfather, Mori Shintaro whom the boys affectionately refer to as Grandpa, for the summer. Mori is a highly skilled in the fields of Martial arts and Ninjutsu, and for years he has trained the boys in his techniques. After an organized crime ring proves to be too much for the FBI, it''s time for the 3 brother NINJAS! To use their martial arts skills, they team up to battle the crime ring and outwit some very persistent kidnappers!', '1992-08-07', 5.75, 'https://image.tmdb.org/t/p/w500/fhGyCrKke6KImUQtprqsICYHnkX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16172, 'Simply Irresistible', 'After her mother''s death, mediocre chef Amanda Shelton is having trouble attracting customers to her family''s restaurant. While shopping for ingredients, she is given a magical crab by mysterious Gene O''Reilly. Afterward, Amanda''s dishes suddenly become excellent, inducing strong emotional reactions in everyone who eats them. Tom Bartlett, who is preparing to open his own eatery, tries her cooking and falls in love.', '1999-02-05', 5.46, 'https://image.tmdb.org/t/p/w500/zFsqqPQUz69wPaLBqQeiGbGiW7J.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15927, 'A Passage to India', 'Cultural mistrust and false accusations doom a friendship in British colonial India between an Indian doctor, an Englishwoman engaged to marry a city magistrate, and an English educator.', '1984-12-14', 6.83, 'https://image.tmdb.org/t/p/w500/rvBWlGRKte2U6qElHV13h6JvmSe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15940, 'Beautiful Creatures', 'When Petula and Dorothy cover up the accidental murder of one jerk boyfriend, they hatch a hilarious scheme to collect a huge ransom.', '2000-08-23', 5.60, 'https://image.tmdb.org/t/p/w500/v9mWi816aq6OZaIc9ICAWQcxQC1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16335, 'Walled In', 'Having finally secured her first assignment from her family''s demolition business, Sam Walczak is sent to supervise the destruction of an apartment house, only to discover a group of tenants still living in the condemned building. One such tenant, Jimmy, tells Sam an urban legend about a serial murderer who used to live in the building and entomb his victims in the walls. What''s worse, the dead are believed to still harass the residents to this day.', '2009-02-20', 4.90, 'https://image.tmdb.org/t/p/w500/cWDZAGHjsIk2Aezakk783cBIas5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16219, 'Gladiator', 'Tommy Riley has moved with his dad to Chicago from a ''nice place''. He keeps to himself, goes to school. However, after a street fight, he''s noticed and quickly falls into the world of illegal underground boxing — where punches can kill.', '1992-03-06', 7.62, 'https://image.tmdb.org/t/p/w500/w0YjBWVfu689txEXZG3xa4Aev3i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16139, 'Phantasm III: Lord of the Dead', 'The Tall Man, that imposing menace from Morningside Mortuary, is back and once again haunting the thoughts of the now-adult Mike and his friend, ex-Ice Cream vendor Reggie. The two continue their hunt for the mysterious figure and in his path of destruction encounter a variety of dangerous situations, friends and enemies.', '1994-05-06', 5.80, 'https://image.tmdb.org/t/p/w500/uFv3H39YgyL568PTse5jGB6Ll8a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15943, 'The Shaggy D.A.', 'Wilby Daniels, a successful lawyer running for District Attorney, suddenly finds himself being transformed into an English sheepdog. Somehow he has to keep his change a secret and find just what is causing it, all the while eluding the local dog catcher.', '1976-12-17', 5.76, 'https://image.tmdb.org/t/p/w500/cSVu5gGSelx2QOykeEG5lEuzD1L.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15944, 'The Shaggy Dog', 'Through an ancient spell, a boy changes into a sheepdog and back again. It seems to happen at inopportune times and the spell can only be broken by an act of bravery....', '1959-03-19', 6.25, 'https://image.tmdb.org/t/p/w500/x0fTvnnRIZNyTne2BrcS8I5X20e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16307, 'The Wicker Man', 'Police sergeant Neil Howie is called to an island village in search of a missing girl whom the locals claim never existed. The investigation is further complicated as Howie’s religious views clash with those of the island’s residents.', '1973-12-06', 7.33, 'https://image.tmdb.org/t/p/w500/wwtrXRL8SiOWxhwLEvw7iBgYh0g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16306, 'Fantastic Planet', 'On the planet Ygam, the Draags, extremely technologically and spiritually advanced blue humanoids, consider the tiny Oms, human beings descendants of Terra''s inhabitants, as ignorant animals. Those who live in slavery are treated as simple pets and used to entertain Draag children; those who live hidden in the hostile wilderness of the planet are periodically hunted and ruthlessly slaughtered as if they were vermin.', '1973-12-01', 7.63, 'https://image.tmdb.org/t/p/w500/prq0j1S0K07UjwLZLF6oMGflRUI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16220, 'Wizards', 'After the death of his mother, evil mutant wizard Blackwolf discovers long-lost military technologies. Full of ego and ambition, Blackwolf claims his mother''s throne, assembles an army, and sets out to brainwash and conquer Earth. Meanwhile, Blackwolf''s gentle twin brother, the bearded sage Avatar, calls upon his own magical abilities to foil Blackwolf''s plans for world domination — even if it means eliminating his own flesh and blood.', '1977-02-09', 6.17, 'https://image.tmdb.org/t/p/w500/jeAxoYepnVirGe0H7pmwviSZYul.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16146, 'Phantasm IV: Oblivion', 'Taking off immediately where the last one ended, Mike travels across dimensions and time,  fleeing from the Tall Man while trying to find the origins of his enemy and what really happened the night that his brother died. Meanwhile, Reggie battles spheres and the undead in a quest to find Mike before the Tall Man can complete his transformation.', '1998-07-31', 5.20, 'https://image.tmdb.org/t/p/w500/412lNlGrB8eHBOKlNhOgxI9bCtL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16367, 'Kinky Boots', 'Charles Price may have grown up with his father in the family shoe business in Northampton, central England, but he never thought that he would take his father''s place. Charles has a chance encounter with the flamboyant drag queen cabaret singer Lola and everything changes.', '2005-08-30', 6.70, 'https://image.tmdb.org/t/p/w500/8EzwkItfERGB05BOKNJTJFo93Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (15947, 'The Three Caballeros', 'For Donald''s birthday he receives a box with three gifts inside. The gifts, a movie projector, a pop-up book, and a pinata, each take Donald on wild adventures through Mexico and South America.', '1944-12-21', 6.28, 'https://image.tmdb.org/t/p/w500/nMfScRxw9wVLoO7LiEjziFAKLSK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16370, 'Aspen Extreme', 'T.J. and his friend Dexter quit their jobs in Detroit to become ski-instructors in Aspen. While T.J. advances to the most popular instructor of the school during the season, he has to take care for Dexter, who''s future is less bright and who''s eventually thinking about jobbing as drug courier - bringing their friendship to a test. Meanwhile the rich business woman Brice supports T.J. in his writing ambitions and invites him to live at her home. But in her absence he falls in love with the stunningly beautiful blond radio moderator Robin.', '1993-01-22', 5.91, 'https://image.tmdb.org/t/p/w500/kbXb9XvMZW6GmLJoFf7gkoLBvUR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16372, 'The Innocents', 'In a mid-19th century Essex country house, a young governess for two children becomes convinced that the house and grounds are haunted by ghosts and that the children are being possessed.', '1961-11-24', 7.50, 'https://image.tmdb.org/t/p/w500/idqvLBmlEHUITMnQ0EJ6Yb5TpVw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16375, 'Schizopolis', 'A man works for the unpleasant guru of a Scientology-like movement.', '1997-04-02', 6.23, 'https://image.tmdb.org/t/p/w500/9ASmg9EvWkt90dwW9YKO3NXQk8d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16320, 'Serenity', 'A group of rebels travel the outskirts of space evading the sinister Alliance regime. Their lives of smuggling and cargo-running are interrupted by a psychic passenger who harbours a dangerous secret. Soon, the crew find themselves being pursued by an Alliance agent who will stop at nothing to find them.', '2005-09-25', 7.36, 'https://image.tmdb.org/t/p/w500/4sqUOaPFoP2W81mq1UYqZqf5WzA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16379, 'The Mod Squad', 'Three youthful delinquents escape conviction for their crimes by teaming with the LAPD.', '1999-03-26', 4.41, 'https://image.tmdb.org/t/p/w500/7c20VEblNKkDiBuA6bE6kbeHqHa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16380, 'When Worlds Collide', 'When a group of astronomers calculate a star is on a course to slam into Earth, a few days before, it''s accompanying planet will first pass close enough to the Earth to cause havoc on land and sea. They set about building a rocket so a few selected individuals can escape to the planet.', '1951-09-14', 6.40, 'https://image.tmdb.org/t/p/w500/zVBEXGxtnD83t0PfKm9uZbnpDbA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16384, 'My Blue Heaven', 'FBI agent Barney Coopersmith is assigned to protect former Mafia figure turned informant Vincent Antonelli. In the witness protection program one is supposed to keep a low profile, but that is something that Antonelli has trouble doing. Coopersmith certainly has his hands full keeping Antonelli away from the Mafia hitmen who want to stop him testifying, not to mention the nightclubs...', '1990-08-17', 6.10, 'https://image.tmdb.org/t/p/w500/ggk34Nr1e8LOeAdVncuYz6pyYDe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16388, 'The Brothers McMullen', 'Deals with the lives of the three Irish Catholic McMullen brothers from Long Island, New York, over three months, as they grapple with basic ideas and values — love, sex, marriage, religion and family — in the 1990s.', '1995-08-11', 6.09, 'https://image.tmdb.org/t/p/w500/6oWsOJP0ed5gs8n2UywcailoxFN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16385, 'Pride', 'Coach Jim Ellis shocks the community and changes lives when, aided by a local janitor, he sets out to form Philadelphia''s first black swim team. But the odds are against them as they battle rigid rules, racism and more.', '2007-03-23', 6.73, 'https://image.tmdb.org/t/p/w500/lBMqdt52wgU9soSD9Asq1eNx6iX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16391, 'Black Narcissus', 'A group of Anglican nuns, led by Sister Clodagh, are sent to a mountain in the Himalayas. The climate in the region is hostile and the nuns are housed in an odd old palace. They work to establish a school and a hospital, but slowly their focus shifts. Sister Ruth falls for a government worker, Mr. Dean, and begins to question her vow of celibacy. As Sister Ruth obsesses over Mr. Dean, Sister Clodagh becomes immersed in her own memories of love.', '1947-05-26', 7.50, 'https://image.tmdb.org/t/p/w500/jSbFWWbkUq5N5ikewJHNATcWnxS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16390, 'Scooby-Doo! and the Samurai Sword', 'The Mystery Inc. gang takes a trip to Japan and finds themselves circling Asia and the Pacific in a treasure hunt, racing against the vengeful Black Samurai and his Ninja warriors to find the legendary Sword of Fate, an ancientblade fabled to possess extraordinary supernaturalpowers.', '2009-04-07', 7.62, 'https://image.tmdb.org/t/p/w500/qJ0UlWWrBn2fnAg4SifTJbDUuaf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16395, 'Inferno', 'A young man returns from Rome to his sister''s satanic New York apartment house.', '1980-02-07', 6.64, 'https://image.tmdb.org/t/p/w500/A92SmwJ4w2GSF6Mp2m8xE9GbG39.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16406, 'Dick', 'Two high school girls wander off during a class trip to the White House and meet President Richard Nixon. They become the official dog walkers for Nixon''s dog Checkers, and become his secret advisors during the Watergate scandal.', '1999-08-04', 5.96, 'https://image.tmdb.org/t/p/w500/aBG4XoK5xkujl4crloPs6bStl4m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16405, 'Dust', 'Two parallel tales of redemption, a century apart. In the New York storyline, Edge hunts for Angela''s gold to pay back a debt, and gradually grows closer to her. In the Macedonian story, the brothers end up fighting for opposite sides of a revolution, with the religious Elijah taking up sides with the Ottoman sultan and gunslinger Luke joining "the Teacher" , a Macedonian rebel.', '2001-08-29', 5.47, 'https://image.tmdb.org/t/p/w500/qhNlFTwlrte13wX3ntMQJSO7azG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16403, 'Tears for Sale', 'Story of two sisters that grew up in a small Serbian village in the beginning of the 1930s. The village is torn up by wars and years long blood oath. There are no men left in the village. Our heroines, Ognjenka and Mala Boginja decide to go to the city, kidnap men and return life to their village. The lights of the metropolis dazzle them and there starts this little amusing and sentimental adventure.', '2008-01-30', 6.22, 'https://image.tmdb.org/t/p/w500/90dWmvkiNDEgIhy4cC8HbKAsiLk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16342, 'The Children', 'A relaxing Christmas vacation turns into a terrifying fight for survival as the children begin to turn on their parents.', '2008-12-05', 6.07, 'https://image.tmdb.org/t/p/w500/vTyc2ahe0qq7BVBlPD3L4zAl7WU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16420, 'Othello', 'The evil Iago pretends to be friend of Othello in order to manipulate him to serve his own end in the film version of this Shakespeare classic.', '1995-12-15', 6.36, 'https://image.tmdb.org/t/p/w500/kyevuYzW36wKadiE8lftLac5VwQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16425, 'Assassination Tango', 'John J. is a seasoned hit man sent on a job to Argentina. When the General he''s sent to kill delays his return to the country, John passes the time with Manuela, a beautiful dancer who becomes his teacher and guide into Argentina''s sensual world of the tango.', '2003-03-08', 5.50, 'https://image.tmdb.org/t/p/w500/3muiZ9yF1RpKfzn9eqAxqA1YFWG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16407, 'Dragon Lord', 'Dragon and his madcap pal Cowboy spend their days getting into mischief, frustrating the elders, chasing girls, and competing in the village sport. When Dragon overhears a fiendish plot by smugglers to sell China''s national treasures overseas, the pair leap into action. Also, Cowboy''s wealthy father is kidnapped by the villainous and lethal Big Boss, and the scene is set for a furious martial arts showdown.', '1982-01-21', 6.50, 'https://image.tmdb.org/t/p/w500/qjQhm2jwV4DSTauOydFJVhVyMS3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16428, 'Breakin'' All the Rules', 'After being dumped by his model girlfriend, aspiring writer Quincy Watson quits his job and is inspired to pen the ultimate how-to book on breaking up. When it becomes a smash bestseller, he starts giving his player cousin, Evan, choice tips on how to win the battle of the sexes. But when Evan''s beautiful girlfriend Nikki gets wind of the plan, it''s these players that end up getting played.', '2004-05-14', 6.00, 'https://image.tmdb.org/t/p/w500/piEqcDe7CTbxxPUSwswrsoKWzMw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16440, 'Tales of the Black Freighter', 'A mariner survives an attack from the dreaded pirates of the Black Freighter, but his struggle to return home to warn it has a horrific cost.', '2009-03-24', 6.64, 'https://image.tmdb.org/t/p/w500/vpZNACLrZC7EeZc0iCpnCsewZEO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16442, 'Sergeant York', 'Alvin York a hillbilly sharpshooter transforms himself from ruffian to religious pacifist. He is then called to serve his country and despite deep religious and moral objections to fighting becomes one of the most celebrated American heroes of WWI.', '1941-09-27', 7.20, 'https://image.tmdb.org/t/p/w500/54LTgyRHSixyeeFhLtCFj0SMAQ3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16441, 'The Beastmaster', 'Dar, the son of a king, is hunted by a priest after his birth and grows up in another family. When he becomes a grown man, his new father is murdered by savages and he discovers that he has the ability to communicate with animals, which leads him on a quest for revenge against his father''s killers.', '1982-08-16', 6.31, 'https://image.tmdb.org/t/p/w500/ytaKNYpHdQnClTbWL2m19Xv6PXZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16161, 'Baby Boy', 'The story of Jody, a misguided, 20-year-old African-American who is really just a baby boy finally forced-kicking and screaming to face the commitments of real life. Streetwise and jobless, he has not only fathered two children by two different women-Yvette and Peanut but still lives with his own mother. He can''t seem to strike a balance or find direction in his chaotic life.', '2001-06-27', 7.10, 'https://image.tmdb.org/t/p/w500/9dcic3zV5Gq6BQ1Et696qBtp9Xg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16471, 'Modern Problems', 'Jealous, harried air traffic controller Max Fielder, recently dumped by his girlfriend, comes into contact with nuclear waste and is granted the power of telekinesis, which he uses to not only win her back, but to gain a little revenge.', '1981-12-25', 5.41, 'https://image.tmdb.org/t/p/w500/aH21h3sMMN3r6d9I8VSBw28fW7V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16487, 'The Spirit of Christmas: Jesus vs. Santa', 'Four carolling children meet Jesus and Santa Claus and learn the true meaning of Christmas.', '1995-12-25', 6.58, 'https://image.tmdb.org/t/p/w500/1ZjjFcUZpoWOuVjYcUuiF2oEmNj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16162, 'The Best Man', 'After writing a soon-to-be bestselling novel, writer and committed bachelor Harper attempts to hide the fact that his saucy new book is loosely based on the lives and loves of his tight-knit group of friends. Harper is set to be best man at his friend Lance''s wedding, and all his friends will be in attendance. When an advance copy of the book makes its way into the hands of his ex-flame, Jordan, Harper attempts to keep it under wraps.', '1999-10-22', 6.62, 'https://image.tmdb.org/t/p/w500/ub2Njdn4kq49ndyg7QglnE8PUqT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16300, 'Down to Earth', 'Struggling comic Lance Barton knows what it''s like to die on stage. But when his life takes an unexpected turn - straight to heaven - Lance is sure there''s been a mistake. Miraculously, he''s right! An angel tells Lance he was taken prematurely but assures him he can be returned to Earth - in the aged body of a ruthless white billionaire. In this improbable reincarnation, Lance begins a hilarious quest to realize his showbiz dream...and, along the way, discovers the person he never imagined he could be.', '2001-02-16', 5.56, 'https://image.tmdb.org/t/p/w500/w2XM4YCfBOOWEL4a0abQji7QxwI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16344, 'Luck by Chance', 'Not wanting the same fate as befell her sisters, Sona Mishra re-locates to Mumbai to try to make a living making movies, but she soon finds that the path she has chosen is not an easy one.', '2009-01-30', 6.55, 'https://image.tmdb.org/t/p/w500/19Qh3fEXsqB0pBl5DRnCBsgj7Ot.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16180, 'The Legend of Hell House', 'A team consisting of a physicist, his wife, a young female psychic, and the only survivor of the previous visit are sent to the notorious Hell House to prove or disprove survival after death. Previous visitors have either been killed or gone mad, and it is up to the team to survive a full week in isolation, and solve the mystery of the Hell House.', '1973-06-15', 6.70, 'https://image.tmdb.org/t/p/w500/zfTWQD3UWJNlv44VLljjLcU3hWA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16325, 'Echelon Conspiracy', 'Mysterious cell phone messages promise a young American engineer untold wealth - then make him the target of a deadly international plot. Dangerous security operatives chase the engineer across the globe, while a powerful government official pursues a mysterious agenda that threatens the stability of the entire world.', '2009-02-27', 6.14, 'https://image.tmdb.org/t/p/w500/eQgT8kdjWJots3dX5Xy11le2vHk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16448, 'Waiting for Guffman', 'Aspiring director Corky St. Clair and the marginally talented amateur cast of his hokey small-town musical production go overboard when they learn that Broadway theater agent Mort Guffman will be in attendance.', '1997-01-31', 7.00, 'https://image.tmdb.org/t/p/w500/zuArI6EBpV6mExrvfnyidoOtzdf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16184, 'The Happiness of the Katakuris', 'The Katakuri family has just opened their guest house in the mountains. Unfortunately their first guest commits suicide and in order to avoid trouble they decide to bury him in the backyard. Things get way more complicated when their second guest, a famous sumo wrestler, dies while having sex with his underage girlfriend and the grave behind the house starts to fill up more and more.', '2002-02-23', 6.92, 'https://image.tmdb.org/t/p/w500/8iIei17w5DVEz4P9OjxIM10f7Jh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16351, 'Ararat', 'Interrogated by a customs officer, a young man recounts how his life was changed during the making of a film about the Armenian genocide.', '2002-05-20', 6.15, 'https://image.tmdb.org/t/p/w500/kQkn715VQYLIs2nddAUf19Bz5Wj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16433, 'Grand Theft Parsons', 'There are times when it''s right and proper to simply bury the dead. This is not one of those times... Gram Parsons was one of the most influential musicians of his time; a bitter, brilliant, genius who knew Elvis, tripped with the Stones and fatally overdosed on morphine and tequila in 1973. And from his dying came a story. A story from deep within folklore; a story of friendship, honour and adventure; a story so extraordinary that if it didn''t really happen, no one would believe it. Two men, a hearse, a dead rock star, five gallons of petrol, and a promise. And the most extraordinary chase of modern times.', '2004-06-18', 6.01, 'https://image.tmdb.org/t/p/w500/5sWWj5tlTDyAi2yiEjQZUmJCoKr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16299, 'The Stupids', 'An incredibly dull-witted family unknowingly stumble upon an illegal weapons deal while on the trail of their "stolen" garbage.', '1996-08-08', 4.84, 'https://image.tmdb.org/t/p/w500/uR0EPkE66y2DU21NOZAu6xtfpQL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16515, 'Captains Courageous', 'Harvey, the arrogant and spoiled son of an indulgent absentee-father, falls overboard from a transatlantic steamship and is rescued by a fishing vessel on the Grand Banks. Harvey fails to persuade them to take him ashore, nor convince the crew of his wealth. The captain offers him a low-paid job, until they return to port, as part of the crew that turns him into a mature, considerate young man.', '1937-06-25', 7.43, 'https://image.tmdb.org/t/p/w500/qhJNHLwIcMqDKBwsr9uMDOumO33.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16315, 'Campfire Tales', 'Anthology of famous, scary urban legends done with a modern twist.', '1997-02-28', 5.90, 'https://image.tmdb.org/t/p/w500/wcYwgCJioHteh7g0RaZ9Y8sEhvY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16337, 'The Texas Chainsaw Massacre 2', 'A radio host is victimised by the notorious cannibal family while a former Texas Marshal hunts them.', '1986-08-22', 5.67, 'https://image.tmdb.org/t/p/w500/cO1Dvg7k87lHSPOdumn3ddJEKdX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16209, 'Jesus Christ Vampire Hunter', 'The second coming is upon us, and Jesus has returned to earth. But before he can get down to the serious business of judging the living and the dead, he has to contend with an army of vampires that can walk in the daylight.', '2001-06-10', 4.91, 'https://image.tmdb.org/t/p/w500/iYAiPgkzaCAlMwQ7hyAr0h3D2uF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16520, 'The King and I', 'Widowed Welsh mother Anna Leonowens becomes a governess and English tutor to the wives and many children of the stubborn King Mongkut of Siam. Anna and the King have a clash of personalities as she works to teach the royal family about the English language, customs and etiquette, and rushes to prepare a party for a group of European diplomats who must change their opinions about the King.', '1956-06-29', 7.07, 'https://image.tmdb.org/t/p/w500/wUfaP0lLaMpZzp5CrHyII5Vd7cp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16620, 'La Bamba', 'Los Angeles teenager Ritchie Valens becomes an overnight rock ''n'' roll success in 1958, thanks to a love ballad called "Donna" that he wrote for his girlfriend. But as his star rises, Valens has conflicts with his jealous brother, Bob, and becomes haunted by a recurring nightmare of a plane crash just as he begins his first national tour alongside Buddy Holly.', '1987-07-24', 7.28, 'https://image.tmdb.org/t/p/w500/6Znulqtc7cdqlUC69HGf26Ef5fi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16456, 'The Crow: Wicked Prayer', 'After ex-con Jimmy and his girlfriend are brutally murdered by a biker gang, he is resurrected by the power of The Crow to avenge their deaths and reunite with her in the afterlife.', '2005-05-04', 3.80, 'https://image.tmdb.org/t/p/w500/l6TfZVVzvrlGjxDlZK3CoHwaccc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16358, 'Eulogy', 'A black comedy that follows three generations of a family, who come together for the funeral of the patriarch - unveiling a litany of family secrets and covert relationships.', '2004-10-15', 6.43, 'https://image.tmdb.org/t/p/w500/u56l2hEhbiVHT4wcjBapcVtAtY6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16633, 'Somewhere in Time', 'Young writer Richard Collier is met on the opening night of his first play by an old lady who begs him to "Come back to me". Mystified, he tries to find out about her, and learns that she is a famous stage actress from the early twentieth century. Becoming more and more obsessed with her, by self-hypnosis he manages to travel back in time—where he meets her.', '1980-10-02', 7.51, 'https://image.tmdb.org/t/p/w500/hmdegiSwVYUNvEfihaE3HRM3Sos.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16636, 'Spellbound', 'This documentary follows 8 teens and pre-teens as they work their way toward the finals of the Scripps Howard national spelling bee championship in Washington D.C.', '2002-11-13', 7.30, 'https://image.tmdb.org/t/p/w500/whPFGfqZayYOU5f5mx0GdXZOgpi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16638, 'El Cid', 'Epic film of the legendary Spanish hero, Rodrigo Diaz ("El Cid" to his followers), who, without compromising his strict sense of honour, still succeeds in taking the initiative and driving the Moors from Spain.', '1961-10-24', 6.80, 'https://image.tmdb.org/t/p/w500/a6DY3LDlXFUDuXm47zXTOfiisxP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16642, 'Days of Heaven', 'In 1916, a Chicago steel worker accidentally kills his supervisor and flees to the Texas panhandle with his girlfriend and little sister to work harvesting wheat in the fields of a stoic farmer.', '1978-09-13', 7.48, 'https://image.tmdb.org/t/p/w500/rwxTYjOZmX2rGhz7avLe1qsjNqe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16643, 'Life or Something Like It', 'A reporter Lanie Kerrigan interviews a psychic homeless man for a fluff piece about a football game''s score. Instead he tells her that her life has no meaning and is going to end in just a few days, which sparks her to action, trying to change the pattern of her life...', '2002-04-24', 5.71, 'https://image.tmdb.org/t/p/w500/b9lUSfCjv8jjNRSsmk65HEV1Pv3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16664, 'All About Lily Chou-Chou', 'Charts the troubled teenage years of students Yūichi Hasumi and Shūsuke Hoshino, exploring the shifting and complex power dynamics of their relationship against the backdrop of Yūichi''s love for the dreamy and abstract music of pop star Lily Chou-Chou.', '2001-10-06', 7.44, 'https://image.tmdb.org/t/p/w500/pLBNmJUH9JYRCRsh349PJ22WpkS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16508, 'Doug''s 1st Movie', 'Doug and his pal Skeeter set''s out to find the monster of Lucky Duck Lake. Though things get really out of hand when some one blurts out that the monster is real.', '1999-03-26', 5.59, 'https://image.tmdb.org/t/p/w500/hZduJdSSWCkmvnBpNyRaIszubVm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16666, 'War Dance', 'Three children living in a displacement camp in northern Uganda compete in their country''s national music and dance festival.', '2007-02-15', 7.16, 'https://image.tmdb.org/t/p/w500/mZxKlZSaL0VvBfmiZX3dv3BKVH5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16703, 'This Gun for Hire', 'Sadistic killer-for-hire Philip Raven becomes enraged when his latest job is paid off in marked bills. Vowing to track down his double-crossing boss, nightclub executive Gates, Raven sits beside Gates'' lovely new employee, Ellen, on a train out of town. Although Ellen is engaged to marry the police lieutenant who''s hunting down Raven, she decides to try and set the misguided hit man straight as he hides from the cops and plots his revenge.', '1942-04-24', 6.96, 'https://image.tmdb.org/t/p/w500/wfbRnfY1PQTRlDxZ0XEAw5zSeKn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16690, 'Return to Never Land', 'In 1940, the world is besieged by World War II. Wendy, all grown up, has two children; including Jane, who does not believe Wendy''s stories about Peter Pan.', '2002-02-14', 6.47, 'https://image.tmdb.org/t/p/w500/wB3r2b8sxUZspqNyr8copMlt7se.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16672, 'Woman in the Dunes', 'A vacationing entomologist suffers extreme physical and psychological trauma after being taken captive by the residents of a poor seaside village and made to live with a woman whose life task is shoveling sand for them.', '1964-02-15', 8.20, 'https://image.tmdb.org/t/p/w500/xiBr3bIT2xpbuIKo5bLK7ebP4O1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16716, 'A Christmas Carol', 'Miser Ebenezer Scrooge is awakened on Christmas Eve by spirits who reveal to him his own miserable existence, what opportunities he wasted in his youth, his current cruelties, and the dire fate that awaits him if he does not change his ways. Scrooge is faced with his own story of growing bitterness and meanness, and must decide what his own future will hold: death or redemption.', '1999-12-05', 6.94, 'https://image.tmdb.org/t/p/w500/oi1NcVDXlFEsdpLp37BJmFbVlg9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16725, 'The Tracey Fragments', 'Tracey Berkowitz, 15, a self-described normal girl, loses her 9-year old brother, Sonny. In flashbacks and fragments, we meet her overbearing parents and the sweet, clueless Sonny. We watch Tracey navigate high school, friendless, picked on and teased. She develops a thing for Billy Zero, a new student, imagining he''s her boyfriend. We see the day she loses Sonny and we watch her try to find him.', '2007-09-12', 5.92, 'https://image.tmdb.org/t/p/w500/9a99MNftmHNTLIYHfKXtGdAV6oF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16727, 'The Namesake', 'The American-born son of Indian immigrants strives to fit in among his fellow New Yorkers despite his family''s unwillingness to let go of their traditional ways.', '2006-09-02', 6.81, 'https://image.tmdb.org/t/p/w500/hxrf7HDwh0nIX4xXE06BdpEKW1V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16723, 'Sugar & Spice', 'When Jack and Diane find themselves in an unexpected adult situation, the A-Squad comes to their rescue. In order to help their friend Diane, the A-Squad goes where no cheerleader has gone before: taking on a little after-school project known as bank robbery. But the A-Squad does things their way -- with sugar and spice -- forever changing their friendship, their future and the nation''s notion of teen spirit.', '2001-01-24', 6.40, 'https://image.tmdb.org/t/p/w500/fN3xeuVsPaiEKYm65uHSO9JVmeb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16729, 'Don''t Move', 'While waiting for the brain surgery of his daughter Angela, victim of a motorcycle accident, the surgeon Timoteo recalls his torrid affair with and passion for Italia, a simple woman from slums in the periphery of the big city where he lives. The ghost of the beloved and sexual object of desire Italia chases him in his memories.', '2004-03-12', 6.99, 'https://image.tmdb.org/t/p/w500/o5kErZoLG5eAQ5IqZxUoIzNmlJ1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16523, 'Where the Wild Things Are', 'Max imagines running away from his mom and sailing to a far-off land where large talking beasts—Ira, Carol, Douglas, the Bull, Judith and Alexander—crown him as their king, play rumpus, build forts and discover secret hideaways.', '2009-10-16', 6.50, 'https://image.tmdb.org/t/p/w500/pzVqDpSzOg32IpXghHGSGAAArl6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16767, 'Spriggan', 'An elite superhuman agent must stop a foreign military unit from seizing control of an ancient artifact that holds the key to ultimate power.', '1998-09-05', 6.00, 'https://image.tmdb.org/t/p/w500/glGbrKRq0cqhqUcM9s2LE1Fxfq6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16771, 'Barcelona', 'During the 1980s, uptight Ted Boynton is a salesman working in the Barcelona office of a Chicago-based company. He receives an unexpected visit from his cousin Fred, a naval officer who has come to Spain on a public relations mission for a U.S. fleet. Not exactly friends in the past, Ted and Fred strike up relationships with women in the Spanish city and experience conflicts -- Ted with his employer, and Fred with the Barcelona community.', '1994-07-29', 6.25, 'https://image.tmdb.org/t/p/w500/7dgX3naR9EsFMvQhwHY8My6r5FR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16769, 'Coal Miner''s Daughter', 'Biography of Loretta Lynn, a country and western singer that came from poverty to fame.', '1980-03-07', 7.23, 'https://image.tmdb.org/t/p/w500/bzHFDAdUad4QcHPi2UOqvaQKNWA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16780, 'The Return of the Texas Chainsaw Massacre', 'A group of teenagers get into a car crash in the Texas woods on prom night, and then wander into an old farmhouse that is home to Leatherface and his insane family of cannibalistic psychopaths.', '1995-09-22', 4.58, 'https://image.tmdb.org/t/p/w500/e1ikqofvLBddrZJ73IjmJWhUYus.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16784, 'Welcome to Mooseport', 'A US president who has retired after two terms in office returns to his hometown of Mooseport, Maine and decides to run for Mayor against another local candidate.', '2004-02-24', 5.08, 'https://image.tmdb.org/t/p/w500/xesXaNCtdGUO5FsMDYooPQAMHxQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16768, 'An Evening with Kevin Smith 2: Evening Harder', 'In this second Q&amp;A with Kevin Smith he now enters the homes of some of his fans in Toronto and London.', '2006-10-25', 7.11, 'https://image.tmdb.org/t/p/w500/zpZBBYMepcCExBhAX08XfgkXdQE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16858, 'All That Jazz', 'Joe Gideon is at the top of the heap, one of the most successful directors and choreographers in musical theater. But he can feel his world slowly collapsing around him - his obsession with work has almost destroyed his personal life, and only his bottles of pills keep him going.', '1979-12-16', 7.51, 'https://image.tmdb.org/t/p/w500/culCEdj4srLljefgn4XKd6k3C5t.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16347, 'Auntie Mame', 'Mame Dennis, a progressive and independent woman of the 1920s, is left to care for her nephew Patrick after his wealthy father dies. Conflict ensues when the executor of the father''s estate objects to the aunt''s lifestyle and tries to force her to send Patrick to prep school.', '1958-12-04', 7.05, 'https://image.tmdb.org/t/p/w500/uH810rwkYEbUaV6IlwTaAExbXUm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16535, 'Titanic', 'Unhappily married, Julia Sturges decides to go to America with her two children on the Titanic. Her husband, Richard also arranges passage on the luxury liner so as to have custody of their two children. All this fades to insignificance once the ship hits an iceberg.', '1953-04-11', 6.64, 'https://image.tmdb.org/t/p/w500/rEPzO9I6LCk6Mxg1X4BsBk6oA3V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16558, 'Duplicity', 'Two romantically involved government operatives Claire Stenwick and Ray Koval team up to manipulate a race between opposing corporations to corner the market on a medical innovation that will reap huge profits and allow them to lead an extravagant lifestyle together. They find themselves on opposing sides as corporate spies; however, as they each try to outdo the other, neither one can decide how far to trust the other in this high-stakes game of cat-and-mouse.', '2009-03-18', 5.89, 'https://image.tmdb.org/t/p/w500/vpWQs3CjwG6Er3DgZlv4L3NFjXg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16871, 'Drag Me to Hell', 'After denying a woman the extension she needs to keep her home, loan officer Christine Brown sees her once-promising life take a startling turn for the worse. Christine is convinced she''s been cursed by a Gypsy, but her boyfriend is skeptical. Her only hope seems to lie in a psychic who claims he can help her lift the curse and keep her soul from being dragged straight to hell.', '2009-05-27', 6.49, 'https://image.tmdb.org/t/p/w500/fdyejM5Zd6dsa0YyWa02ZAKwQzK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16340, 'Rugrats in Paris: The Movie', 'A group of rambunctious toddlers travel a trip to Paris. As they journey from the Eiffel Tower to Notre Dame, they learn new lessons about trust, loyalty and love.', '2000-11-17', 6.70, 'https://image.tmdb.org/t/p/w500/grIL8mvfLznaWsv7EEEPhCpkH81.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16804, 'Departures', 'Daigo, a cellist, is laid off from his orchestra and moves with his wife back to his small hometown where the living is cheaper. Thinking he’s applying for a job at a travel agency he finds he’s being interviewed for work with departures of a more permanent nature – as an undertaker’s assistant.', '2008-09-13', 7.85, 'https://image.tmdb.org/t/p/w500/2RkoGK7RcDoWdXm2pCJ1B9dXcTg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16538, 'I Love You, Man', 'Peter Klaven is a successful real estate agent who, upon getting engaged to the woman of his dreams, Zooey, discovers, to his dismay and chagrin, that he has no male friend close enough to serve as his Best Man. Peter immediately sets out to rectify the situation, embarking on a series of bizarre and awkward "man-dates."', '2009-03-20', 6.60, 'https://image.tmdb.org/t/p/w500/xr4zAYsvgTzvMMiWu6qCAP9WBer.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
