INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16939, 'Last Holiday', 'George Bird is a salesman of agricultural machinery who finds out that he hasn''t long to live. On his doctor''s advice, he goes to an exclusive seaside resort to spend his savings on one last holiday.', '1950-05-15', 7.10, 'https://image.tmdb.org/t/p/w500/2rUFvSmkPvMMIhf02uFOfH1TDDA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16608, 'The Proposition', 'In 1880s Australia, a lawman offers renegade Charlie Burns a difficult choice. In order to save his younger brother from the gallows, Charlie must hunt down and kill his older brother, who is wanted for rape and murder. Venturing into one of the Outback''s most inhospitable regions, Charlie faces a terrible moral dilemma that can end only in violence.', '2005-10-06', 7.00, 'https://image.tmdb.org/t/p/w500/bbSHSJuO5XjrIKMh6QXXLTg3Yzr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16941, 'Intermission', 'A raucous story of the interweaving lives and loves of small-town delinquents, shady cops, pretty good girls and very bad boys. With Irish guts and grit, lives collide, preconceptions shatter and romance is tested to the extreme. An ill-timed and poorly executed couple''s break-up sets off a chain of events affecting everyone in town.', '2003-08-29', 6.16, 'https://image.tmdb.org/t/p/w500/hQdFebtqcbwKELQHKf1hcjIHD0D.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16958, 'The Asphalt Jungle', 'Recently paroled from prison, legendary burglar "Doc" Riedenschneider, with funding from Alonzo Emmerich, a crooked lawyer, gathers a small group of veteran criminals together in the Midwest for a big jewel heist.', '1950-05-12', 7.50, 'https://image.tmdb.org/t/p/w500/8xsUnT0P2fJWQv9jGDhs3i9Zx2l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16820, 'F/X2', 'F/X man Rollie Tyler is now a toymaker. Mike, the ex-husband of his girlfriend Kim, is a cop. He asks Rollie to help catch a killer. The operation goes well until some unknown man kills both the killer and Mike. Mike''s boss, Silak says it was the killer who killed Mike but Rollie knows it wasn''t. Obviously, Silak is involved with Mike''s death, so he calls on Leo McCarthy, the cop from the last movie, who is now a P.I., for help and they discover it''s not just Silak they have to worry about.', '1991-04-16', 6.32, 'https://image.tmdb.org/t/p/w500/dxfR8JnfabPi7YUg4PFsuAa7geW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16969, 'City Heat', 'Set in Kansas City in 1933, Eastwood plays a police lieutenant known simply by his last name, Speer. Reynolds plays a former cop turned private eye named Mike Murphy. Both Speer and Murphy served on the force together and were once good friends, but are now bitter enemies. When Murphy''s partner is slain they team up again to fight the mob.', '1984-12-07', 5.53, 'https://image.tmdb.org/t/p/w500/gESRbXstISpeELPpYQYiTM3nRF1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
