INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16991, 'Observe and Report', 'Mall security guard Ronnie Barnhardt is called into action to stop a flasher from turning shopper''s paradise into his personal peep show. But when Barnhardt can''t bring the culprit to justice, a surly police detective is recruited to close the case.', '2009-04-10', 5.41, 'https://image.tmdb.org/t/p/w500/zHuouWUKlRK0SeIjzTlmtoPLrFA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16992, 'The Boxer', 'Nineteen-year-old Danny Flynn is imprisoned for his involvement with the I.R.A. in Belfast. He leaves behind his family and his sixteen-year-old girlfriend, Maggie Hamill. Fourteen years later, Danny is released from prison and returns to his old working class neighborhood to resume his life as a boxer.', '1997-12-31', 6.71, 'https://image.tmdb.org/t/p/w500/wsbNQWMQV4HwwqXtvQUoBfiBzK8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16993, 'Fat City', 'The story of two men, a veteran boxer who is down and out, and a young man who is just starting his life and boxing career. Their fighting careers cross paths as their lives and fortunes head in opposite directions. Director John Huston tells their stories with a level, unsentimental honesty and makes it into one of his best films.', '1972-07-26', 7.08, 'https://image.tmdb.org/t/p/w500/7ag7BOMnAuDKwNyI0wc8jTeimRb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16876, 'Bang Bang You''re Dead', 'A troubled and bullied high school student fights against judgement from his community after threatening to bomb the football team.', '2003-06-11', 7.11, 'https://image.tmdb.org/t/p/w500/647kfvUPkDBXtIHQEhInJR2LUyX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16995, 'State of Play', 'When a congressional aide is killed, a Washington, D.C. journalist starts investigating the case involving the Representative, his old college friend.', '2009-04-17', 6.81, 'https://image.tmdb.org/t/p/w500/mWsfeSFUM3NxWa62UrA9IIn240B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16996, '17 Again', 'On the brink of a midlife crisis, 30-something Mike O''Donnell wishes he could have a "do-over." And that''s exactly what he gets when he wakes up one morning to find he''s 17 years old again. With his adult mind stuck inside the body of a teenager, Mike actually has the chance to reverse some decisions he wishes he''d never made. But maybe they weren''t so bad after all.', '2009-03-11', 6.32, 'https://image.tmdb.org/t/p/w500/yEcfFXEWpuXcfsR9nKESVCFneqV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16889, 'Revenge of the Nerds II: Nerds in Paradise', 'The members of Lambda Lambda Lambda travel to Fort Lauderdale for a fraternity conference. They''ll have to fend off the attacks of their rival frat, the Alphas, if they want to maintain their self-respect — and, of course, if they want to get anywhere with the pretty girls!', '1987-07-10', 5.58, 'https://image.tmdb.org/t/p/w500/cza5sS7AzexM4rLQSvfGzGX8a3N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16999, 'Fire and Ice: The Dragon Chronicles', 'Princess Luisa and knight Gabriel must face a dragon to save their kingdom.', '2008-09-18', 5.09, 'https://image.tmdb.org/t/p/w500/rIctEnkOra3vjZP1I31fepIgUjF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16998, 'The Moustache', 'One day, on a whim, Marc decides to shave off the moustache he''s worn all of his adult life. He waits patiently for his wife''s reaction, but neither she nor his friends seem to notice. Stranger still, when he finally tells them, they all insist he never had a moustache. Is Marc going mad? Is he the victim of some elaborate conspiracy? Or has something in the world''s order gone terribly awry?', '2005-06-09', 6.11, 'https://image.tmdb.org/t/p/w500/4xTwprpMi7KpMukbGl21CMCz4sk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17006, 'I''m Gonna Git You Sucka', 'Jack Spade returns from the army in his old ghetto neighbourhood when his brother, June Bug, dies. Jack declares war on Mr. Big, powerful local crimelord. His army is led by John Slade, his childhood idol who used to fight bad guys in the 70s.', '1988-11-10', 6.38, 'https://image.tmdb.org/t/p/w500/s92HcoJmUHGvZ6o5RvIQjemzMap.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17009, 'Jetsons: The Movie', 'George Jetson is forced to uproot his family when Mr. Spacely promotes him to take charge of a new factory on a distant planet.', '1990-06-06', 6.15, 'https://image.tmdb.org/t/p/w500/u7MciwvfyYrvZEua22wz48Puu7O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17015, 'Persuasion', 'In early 19th-century England, dire financial straits reacquaint the aristocratic Anne Elliot with her wealthy ex-fiance Frederick Wentworth. The two must choose between either putting the past behind them or listening to their hearts.', '1995-05-01', 7.20, 'https://image.tmdb.org/t/p/w500/10hycdhFLq3M3y0ONxIMSiY8Mrs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17037, 'I''ll Be Home for Christmas', 'Estranged from his father, college student Jake is lured home to New York for Christmas with the promise of receiving a classic Porsche as a gift. When the bullying football team dumps him in the desert in a Santa suit, Jake is left without identification or money to help him make the journey. Meanwhile, his girlfriend, Allie, does not know where he is, and accepts a cross-country ride from Jake''s rival, Eddie.', '1998-11-13', 5.96, 'https://image.tmdb.org/t/p/w500/9hTYFvEDnajUIbpdfc3fO6bZq2Y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16555, 'Daddy''s Little Girls', 'Monty is a mechanic struggling to make ends meet as he raises his three young daughters. When the court awards custody of his daughters to his shady ex-wife, Monty desperately tries to win them back with the help of Julia, a beautiful, Ivy League-educated attorney. Monty and Julia couldn''t be less alike, but a flame is ignited... touching off a firestorm of love and conflict.', '2007-02-14', 6.90, 'https://image.tmdb.org/t/p/w500/c2AOyqAbfJ9dKJBOgYEzNnXrbcb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17043, 'The Crocodile Hunter: Collision Course', 'Steve Irwin, AKA The Crocodile Hunter, has avoided the death-roll and saved a croc from poachers. But what he doesn''t know is that the crocodile has swallowed a top secret U.S. satellite beacon, and the poachers are actually American special agents sent to retrieve it.', '2002-07-26', 5.39, 'https://image.tmdb.org/t/p/w500/8JyI97jCN1BIzdTjWfIxV4GKlyw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17047, 'Agent Cody Banks 2: Destination London', 'With all-new gadgets, high-flying action, exciting chases and a wisecracking new handler, Derek (Anthony Anderson), Cody has to retrieve the device before the world''s leaders fall under the evil control of a diabolical villain.', '2004-03-12', 5.62, 'https://image.tmdb.org/t/p/w500/zlAltvp84rYVTYs3kdemqHBaiat.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16857, 'The Dangerous Lives of Altar Boys', 'A group of Catholic school friends, after being caught drawing an obscene comic book, plan a heist that will outdo their previous prank and make them local legends.', '2002-06-14', 6.67, 'https://image.tmdb.org/t/p/w500/4uTWXZ2Rvizl3ycMHtODfRjks4W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17057, 'In a Lonely Place', 'A violent screenwriter and a female neighbor fall in love after she clears him of murder, but she begins to have second thoughts.', '1950-05-17', 7.62, 'https://image.tmdb.org/t/p/w500/vbdgtwzLOpE6MppZlyYChMagvQq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16614, 'Adventureland', 'It''s the summer of 1987, and recent college grad James Brennan can''t wait to begin his long-anticipated dream trip to Europe. Unfortunately, James'' plans come to a screeching halt when his parents announce that they are unable to subsidize his trip. Forced to take a job at the local amusement park, James prepares for the worst summer ever, until he finds love with a captivating co-worker named Em.', '2009-04-03', 6.40, 'https://image.tmdb.org/t/p/w500/eeSJNAR1aWcgANq26KWIHm3cbyB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17078, 'The Color of Paradise', 'Mohammad joyfully returns to his tiny village on summer vacation from the Institute for the Blind, unaware of his widowed father''s intentions to disown him in order to win the hand—and dowry—of a local woman. With the wedding swiftly approaching, Mohammad''s future hangs precariously in the balance as his father struggles against his destiny, unable to see the wonder of life and love that''s so clear to his son.', '1999-02-08', 7.58, 'https://image.tmdb.org/t/p/w500/rQ1t23NAGJDv9oNfHEAsxhuiAOG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17127, 'The Object of My Affection', 'A pregnant New York social worker begins to develop romantic feelings for her gay best friend, and decides she''d rather raise her child with him, much to the dismay of her overbearing boyfriend.', '1998-04-17', 5.83, 'https://image.tmdb.org/t/p/w500/2mA6QEdzhsftNIFV11SGsQLJvJR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17130, 'Crossroads', 'After eight years apart, three childhood friends - Lucy, Kit, and Mimi - rediscover their friendship on a cross-country trip. With barely a plan, practically no money but plenty of dreams, the girls catch a lift with Mimi''s handsome friend Ben in his convertible. Along the way they not only gather experiences that will change their lives, but they also discover how important it is to hold onto their hearts'' desires.', '2002-02-15', 5.20, 'https://image.tmdb.org/t/p/w500/prdFY9Bc28frBhhWl7mPSr7JmFp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16559, 'The Picture of Dorian Gray', 'A corrupt young man somehow keeps his youthful beauty, but a special painting gradually reveals his inner ugliness to all.', '1945-03-03', 7.14, 'https://image.tmdb.org/t/p/w500/mfvcsmAzdie8YuWI0JpO2u1uzfF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16885, 'The General', 'The real-life story of Dublin folk hero and criminal Martin Cahill, who pulled off two daring robberies in Ireland with his team, but attracted unwanted attention from the police, the I.R.A., the U.V.F., and members of his own team.', '1998-05-01', 6.72, 'https://image.tmdb.org/t/p/w500/3UUR2Evm2JtC2odd2UMYgs9Yi1x.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16619, 'Ordinary People', 'Beth, Calvin, and their son Conrad are living in the aftermath of the death of the other son. Conrad is overcome by grief and misplaced guilt to the extent of a suicide attempt. He is in therapy. Beth had always preferred his brother and is having difficulty being supportive to Conrad. Calvin is trapped between the two trying to hold the family together.', '1980-09-19', 7.44, 'https://image.tmdb.org/t/p/w500/tJVETEDAKgD3fEh88SHOvMvOQue.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17132, 'Savannah Smiles', 'The young daughter of a politician runs away due to lack of attention. She hides in the car of two not too bright crooks who are slowly converted into parent figures as the police web closes down on the supposed kidnappers.', '1982-04-09', 6.53, 'https://image.tmdb.org/t/p/w500/xSR2Qss4bpcpeKq1JXov9C7mpp9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16866, 'Planet 51', 'When Earth astronaut Capt. Chuck Baker arrives on Planet 51 -- a world reminiscent of American suburbia circa 1950 -- he tries to avoid capture, recover his spaceship and make it home safely, all with the help of an empathetic little green being.', '2009-11-19', 5.92, 'https://image.tmdb.org/t/p/w500/x7Itcg3ZdExKwdKguy73WPEqosW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17074, 'The Batman/Superman Movie: World''s Finest', 'As the Joker visits Metropolis with a plan to kill Superman for Lex Luthor, Batman pursues the clown to Superman''s turf.', '1997-10-04', 7.35, 'https://image.tmdb.org/t/p/w500/dQxwNGQ6pQLCUE5vaI9PwIZK6UC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16905, 'Captain Blood', 'Dr. Peter Blood, unjustly convicted of treason and exiled from England, becomes a notorious pirate.', '1935-12-26', 7.25, 'https://image.tmdb.org/t/p/w500/Ae0ltppMl66pAH1odgDU1C4H1iq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17134, '12 Rounds', 'When New Orleans Police Detective Danny Fisher stops a brilliant thief from getting away with a multimillion-dollar heist, the thief''s girlfriend is accidentally killed. After escaping from prison, the criminal mastermind enacts his revenge, taunting Danny with 12 rounds of near-impossible puzzles and tasks that he must somehow complete to save the life of the woman he loves.', '2009-03-19', 5.89, 'https://image.tmdb.org/t/p/w500/7k7qhrO57sVoBLrNo5HYoTp24sT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16563, 'Seven Brides for Seven Brothers', 'In 1850 Oregon, when a backwoodsman brings a wife home to his farm, his six brothers decide that they want to get married too.', '1954-07-22', 7.11, 'https://image.tmdb.org/t/p/w500/hysjTnPNuO6OHWGjEorYSwwusbk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17133, 'Homegrown', 'Three laborers on a Northern California marijuana plantation become increasingly paranoid when they learn that their boss has been murdered. They know enough to run, taking with them enough of the crop to pay them for services rendered. Hooking up with go-between Lucy in the next town, they plot their next move.', '1998-04-17', 5.61, 'https://image.tmdb.org/t/p/w500/feQeYHriKLCjzkUEjg4D81ggyYs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17208, 'Paradise Lost 2: Revelations', 'Revisiting the 1994 Arkansas murder of three 8-year-old boys and the three teenagers convicted of the crime. A follow up to Paradise Lost, Revelations features new interviews with the convicted men, as well as with the original judge and police investigators.', '2000-07-28', 7.20, 'https://image.tmdb.org/t/p/w500/18ixOKgqZGmfALD5080MdZN4dxi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17139, 'Character', 'In pre-WWII Holland, the penniless, illegitimate son of a powerful bailiff sets out to become a lawyer as he spends a lifetime struggling to prove his worth to his relentlessly spiteful father.', '1997-04-17', 7.34, 'https://image.tmdb.org/t/p/w500/v7TWGTZ6fNkY72IyoiVIcnlwniU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17264, 'The Black Stallion', 'While traveling with his father, young Alec becomes fascinated by a mysterious Arabian stallion that is brought on board and stabled in the ship he is sailing on. When it tragically sinks both he and the horse survive only to be stranded on a deserted island. He befriends it, so when finally rescued both return to his home where they soon meet Henry Dailey, a once successful trainer. Together they begin training the horse to race against the fastest ones in the world.', '1979-10-13', 7.05, 'https://image.tmdb.org/t/p/w500/uZtNc31LR5Ik3ZVo2jxwOvhkNRC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17281, 'Gigi', 'A home, a motorcar, servants, the latest fashions: the most eligible and most finicky bachelor in Paris offers them all to Gigi. But she, who''s gone from girlish gawkishness to cultured glamour before our eyes, yearns for that wonderful something money can''t buy.', '1958-05-15', 6.23, 'https://image.tmdb.org/t/p/w500/3GSuecnDr4N5ZaqTrwElSzt6eC2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17113, 'The Ballad of Jack and Rose', 'Jack Slavin is an environmentalist with a heart condition who lives with his daughter, Rose, on an isolated island. While Jack fights against developers who wish to build in the area, he also craves more contact with other people. When he invites his girlfriend, Kathleen, and her sons, Rodney and Thaddius, to move in, Rose is upset. The complicated family dynamics makes things difficult for everyone in the house.', '2005-02-25', 6.11, 'https://image.tmdb.org/t/p/w500/jhID43WmWf3HeH3M3tBCPTSeBOi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17282, 'Rage of Honor', 'A Japanese cop, Shiro, and his partner Ray are after a bunch of drug dealers. But they are betrayed by an insider and Ray is killed. Shiro follows the murderer, a sadistic drug lord, up to Argentina', '1987-02-01', 5.73, 'https://image.tmdb.org/t/p/w500/j5oRakY1PoEd4c56LtpyuBVek5e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17295, 'The Battle of Algiers', 'Paratrooper commander Colonel Mathieu, a former French Resistance fighter during World War II, is sent to Algeria to reinforce efforts to squelch the uprisings of the Algerian War. There he faces Ali la Pointe, a former petty criminal who, as the leader of the Algerian Front de Liberation Nationale, directs terror strategies against the colonial French government occupation. As each side resorts to ever-increasing brutality, no violent act is too unthinkable.', '1966-09-08', 7.90, 'https://image.tmdb.org/t/p/w500/2p3AFtOHFvP6OeVMqlnL1zLKOqL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17320, 'The TV Set', 'As a writer named Mike struggles to shepherd his semi-autobiographical sitcom into development, his vision is slowly eroded by a domineering network executive named Lenny who favors trashy reality programming. The irony, of course, is that every crass suggestion Lenny makes improves the show''s response from test audiences and brings the show a step closer to getting on the air.', '2007-04-06', 6.05, 'https://image.tmdb.org/t/p/w500/djR3SWD7ZEs5lcrjUifaWVCG7eY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17332, 'The Soloist', 'A Los Angeles journalist befriends a homeless Juilliard-trained musician, while looking for a new article for the paper.', '2009-04-24', 6.67, 'https://image.tmdb.org/t/p/w500/6GnFN9OTkaoeKNzd2Fbp3ZyJjKi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17335, 'Obsessed', 'Things couldn''t be better for Derek Charles. He''s just received a big promotion at work, and has a wonderful marriage with his beautiful wife, Sharon. However, into this idyllic world steps Lisa, a temporary worker at Derek''s office. Lisa begins to stalk Derek, jeopardizing all he holds dear.', '2009-02-26', 5.75, 'https://image.tmdb.org/t/p/w500/x98L6eO7MsvNmXFy8TNza9UdsFI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16617, 'Mindhunters', 'Trainees in the FBI''s psychological profiling program must put their training into practice when they discover a killer in their midst.  Based very loosely on Agatha Christie''s And Then There Were None.', '2004-05-07', 6.45, 'https://image.tmdb.org/t/p/w500/uTTGRvnqCI9ZC7WkyP9u7XRiOaA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17339, 'Force 10 from Navarone', 'World War II, 1943. Mallory and Miller, the heroes who destroyed the guns of Navarone, are sent to Yugoslavia in search of a ghost from the past.', '1978-08-16', 6.24, 'https://image.tmdb.org/t/p/w500/3bFRwivCZuXx7fHWt4SpYaiHkNL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16909, 'Webmaster', 'J.B. (Lars Bom) - an ultra-talented Webmaster of an illicit cyber-domain known for massive amounts of illegal money transfers is captured and is put under suspicion by the cyber-domain boss named Stoiss (Jørgen Kiil) when an intruder hacks into the system and steals the Stoiss’s money. Stoiss sticks a heart controller device on J.B. and gives him 35 hours to find who took his money or he dies.', '1998-08-28', 5.88, 'https://image.tmdb.org/t/p/w500/hLf42osBftIxFf7AwYcoqjJWjpl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17346, 'Grey Gardens', 'Edie Bouvier Beale and her mother, Edith, two aging, eccentric relatives of Jackie Kennedy Onassis, are the sole inhabitants of a Long Island estate. The women reveal themselves to be misfits with outsized, engaging personalities. Much of the conversation is centered on their pasts, as mother and daughter now rarely leave home.', '1976-02-19', 7.26, 'https://image.tmdb.org/t/p/w500/jb6o66HE1duy0L7MJzEZXvrrsux.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17350, 'The Brice Man', 'A wannabe surfer parties on the French Riviera while awaiting the perfect wave.', '2005-03-30', 5.50, 'https://image.tmdb.org/t/p/w500/1bxno5lAD6PzulewOT9joMfGPsU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17360, 'Escape to Victory', 'A group of POWs in a German prison camp during World War II play the German National Soccer Team in this powerful film depicting the role of prisoners during wartime.', '1981-06-17', 6.88, 'https://image.tmdb.org/t/p/w500/3j6H0dnbvjNXLK1l9nKguXw5vvO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17352, 'South Pacific', 'Can a girl from Little Rock find happiness with a mature French planter she got to know one enchanted evening away from the military hospital where she is a nurse? Or should she just wash that man out of her hair? Bloody Mary is the philosopher of the island and it''s hard to believe she could be the mother of Liat who has captured the heart of Lt. Joseph Cable USMC. While waiting for action in the war in the South Pacific, sailors and nurses put on a musical comedy show. The war gets closer and the saga of Nellie Forbush and Emile de Becque becomes serious drama.', '1958-03-19', 6.13, 'https://image.tmdb.org/t/p/w500/nYNltu2clFoRQGBz9BtZUTcCbUm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17365, 'The Parallax View', 'An ambitious reporter gets in trouble while investigating a senator''s assassination which leads to a vast conspiracy involving a multinational corporation behind every event in the world''s headlines.', '1974-06-14', 6.84, 'https://image.tmdb.org/t/p/w500/5ClPRox438lwK2Eze7X5xySDaYC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17362, 'Loverboy', 'Randy Bodek works as a pizza delivery boy at Señor Pizza to make a few extra bucks. Some customers are special, though: When the order is for a pizza with extra anchovies, it means the female customers are looking for some loving. But, as Randy soon learns, life as a professional gigolo can get pretty complicated.', '1989-04-28', 6.10, 'https://image.tmdb.org/t/p/w500/qqg2U5Jk4jnQUWDXZjq489V2D0A.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17379, 'Last Holiday', 'The discovery that she has a terminal illness prompts introverted department store saleswoman Georgia Byrd to reflect on what she realizes has been an overly cautious life. With weeks to live, she withdraws her life savings, sells all her possessions and jets off to Europe where she lives it up at a posh hotel. Upbeat and passionate, Georgia charms everybody she meets, including renowned Chef Didier. The only one missing from her new life is her longtime crush Sean Williams.', '2006-01-13', 7.30, 'https://image.tmdb.org/t/p/w500/2SkM1AHIgCQgdOboER6euPKTxGF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17135, 'Omega Doom', 'After earth is taken over by an army of robots, the small number of humans left are forced into hiding. In the nuclear winter, only droids walk the face of the earth, in fear of the rumored human resurgence, and in search of a hidden cache of weapons. One robot, his evil circuits destroyed, enters a small town where a robot civil war is taking place.', '1996-10-21', 4.49, 'https://image.tmdb.org/t/p/w500/j8gSAdGQRxf4eGOSueff1LjZREW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17381, 'BMX Bandits', 'Teens P.J. and Goose get their thrills on BMX bikes, performing hair-raising tricks all across Sydney, Australia. Along with their new friend Judy, they discover a box of walkie-talkies -- and find out that a gang of criminals intends to use them to monitor police signals during a bank robbery. When the young trio snatches the devices, it propels them on a hair-raising adventure in which their pedaling skills might just save their necks.', '1983-12-29', 5.54, 'https://image.tmdb.org/t/p/w500/4WdK6WHPRncDiE8ngspO4EE8fH9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17402, 'Miami Rhapsody', 'Even though Gwyn Marcus is engaged to her boyfriend, Matt, she is still afraid of commitment. While she admires her parents'' loving relationship, she discovers that her family has not always been faithful in marriage, making it harder than ever to settle down. As her mother pressures her to get married, and plenty of attractive men appear in her life, Gwyn learns that she must balance her career, relationships and marriage to be truly happy.', '1995-01-27', 5.32, 'https://image.tmdb.org/t/p/w500/joturqaJfAJ8XHPadT8kibgSpS4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17414, 'Dunston Checks In', 'Hotel manager Robert Grant is forced by his boss to postpone his family vacation when a hotel critic checks in. Trouble is, the critic is really a villainous jewel thief with an orangutan assistant named Dunston. When Dunston gets loose and tries to escape a life of crime -- aided by Robert''s sons -- havoc, hijinks and lots of laughs abound!', '1996-01-12', 5.42, 'https://image.tmdb.org/t/p/w500/xR2cWC04kWNr7TBeXNOf4uOqn00.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17421, 'G.I. Joe: The Movie', 'G.I. Joe faces a new enemy as an ancient society of snake people known as Cobra-La try to forcefully take back the earth from those who drove them underground eons ago.', '1987-06-19', 6.57, 'https://image.tmdb.org/t/p/w500/gADRX5uks0nIsgEzwNpkCIHukBN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16869, 'Inglourious Basterds', 'In Nazi-occupied France during World War II, a group of Jewish-American soldiers known as "The Basterds" are chosen specifically to spread fear throughout the Third Reich by scalping and brutally killing Nazis. The Basterds, lead by Lt. Aldo Raine soon cross paths with a French-Jewish teenage girl who runs a movie theater in Paris which is targeted by the soldiers.', '2009-08-02', 8.22, 'https://image.tmdb.org/t/p/w500/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17403, 'How to Deal', 'For teenager Halley, love seems like an alien concept. Her mother is divorcing her father, who is dating a younger woman Halley can''t stand. Her sister is about to get married and doesn''t realize that her fiancé is not the man of her dreams. And her best friend has fallen madly in love for the first time, leaving Halley to feel even more alone. But, when she meets edgy Macon, she learns what love is really all about.', '2003-07-18', 5.50, 'https://image.tmdb.org/t/p/w500/pD87iTm4MP7JNcxIUssAbpri8nF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17431, 'Moon', 'With only three weeks left in his three-year contract, Sam Bell is eager to return to Earth. Stationed alone at a Moon-based facility with his computer assistant GERTY, an unexpected accident sets off a series of unsettling events that shake his isolation.', '2009-06-12', 7.56, 'https://image.tmdb.org/t/p/w500/35IU0Mq0zFsN1mYwDGts5mKc77n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17435, 'El Norte', 'Brother and sister Enrique and Rosa flee persecution at home in Guatemala and journey north, through Mexico and on to the United States, with the dream of starting a new life.', '1983-10-11', 7.13, 'https://image.tmdb.org/t/p/w500/bgpz7gTpWmmBb26CcjVtiPE7Kfo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17159, 'Eddie Murphy Raw', 'Eddie Murphy delights, shocks and entertains with dead-on celebrity impersonations, observations on ''80s love, sex and marriage, a remembrance of Mom''s hamburgers and much more.', '1987-11-25', 7.25, 'https://image.tmdb.org/t/p/w500/irVU3PHIdg36Rh8tSKnKCdmHLEO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16888, 'The Ladies Man', 'Because of his salacious language, late-night radio advice-show host Leon Phelps, along with his sweet and loyal producer Julie, is fired from his Chicago gig. Leon gets a letter from a former lover promising a life of wealth, but he doesn''t know who she is. Can Leon find his secret sugar-mama? What about Julie?', '2000-10-13', 5.36, 'https://image.tmdb.org/t/p/w500/kKMhGSwydCVjrOWwggDlSvcgzCl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17169, 'Any Which Way You Can', 'Philo takes part in a bare knuckle fight – as he does – to make more money than he can earn from his car repair business. He decides to retire, but when the Mafia come along and arrange another fight, he''s pushed into it. A motorcycle gang and an orangutan called Clyde all add to the ''fun''.', '1980-12-17', 5.81, 'https://image.tmdb.org/t/p/w500/cjqS8TXTy0GvqPBfdB4CAbFCYW6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16934, 'The Young Poisoner''s Handbook', 'Graham Young is a teenage misfit living in suburban London in the 1960s. He hates his stepmother but loves chemistry, and the two impulses unite in a wicked plot to slowly poison her. After she dies, he''s found guilty and sent to a psychiatric hospital, where an idealistic doctor thinks he can be cured.', '1995-01-20', 6.60, 'https://image.tmdb.org/t/p/w500/d3Lakfy0K1eRHUbay9kMeWdt7y6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17443, '...And Justice for All', 'An ethical Baltimore defense lawyer disgusted with rampant legal corruption is forced to defend a judge he despises in a rape trial under the threat of being disbarred.', '1979-10-19', 7.10, 'https://image.tmdb.org/t/p/w500/fGFkpJUsouxxBGWfYqeuJfH210T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17464, 'Breakin'' 2: Electric Boogaloo', 'The dance crew from "Breakin''" bands together to save a community center from a greedy developer bent on building a shopping center in its place.', '1984-12-21', 5.37, 'https://image.tmdb.org/t/p/w500/3RV0NNZ8p3XcdVnrr8bLILuH1x9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17170, 'Bright Lights, Big City', 'A disillusioned young writer living in New York City turns to drugs and drinking to block out the memories of his dead mother and estranged wife.', '1988-04-01', 5.70, 'https://image.tmdb.org/t/p/w500/pimtITTxB2cJftgRhso2Xm195Co.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17445, 'Green Lantern: First Flight', 'Test pilot Hal Jordan finds himself recruited as the newest member of the intergalactic police force, The Green Lantern Corps.', '2009-07-28', 6.90, 'https://image.tmdb.org/t/p/w500/ii48ohKJrDPyrGGOBVJ8XSxr5Xk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17447, 'Jeffrey', 'Jeffrey, a gay man living in New York City with an overwhelming fear of contracting AIDS, concludes that being celibate is the only option to protect himself. As fate would have it, shortly after his declaration of a sex-free existence, he meets the handsome Steve Howard, his dream man -- except for his HIV-positive status. Facing this dilemma, Jeffrey turns to his best friend and an outrageous priest for guidance.', '1995-08-18', 6.27, 'https://image.tmdb.org/t/p/w500/cacIqtIkUaD5xYqUUN1J7qJjciQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17589, 'Mrs Brown', 'When Queen Victoria''s husband Prince Albert dies, she finds solace in her trusted servant, Mr. John Brown. But their relationship also brings scandal and turmoil to the monarchy.', '1997-07-18', 6.77, 'https://image.tmdb.org/t/p/w500/swVtcQj7AW2SaIcgThgw2i4fXN9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17474, 'The Man in the Moon', 'Maureen Trant and her younger sibling Dani share a strong connection, but local boy Court Foster threatens to throw their bond off balance. Dani and Court meet first and have a flirtatious rapport -- but when he meets Maureen, he falls hard and they begin a passionate affair. The new couple try to keep their love hidden from Dani, but she soon learns the truth, disavowing her sister. But a heartbreaking accident later reunites the girls.', '1991-09-30', 7.42, 'https://image.tmdb.org/t/p/w500/57r0TXlqV5GIn4h0Htgh81OZou9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17180, 'The Princess Blade', 'Raised by assassins, Yuki is the last of the Takemikazuchi royal bloodline. A deadly weapon in her own right, she learns the gruesome truth about the death of her beloved mother and joins forces with a mysterious rebel leader.', '2001-12-15', 5.60, 'https://image.tmdb.org/t/p/w500/qZNxgBOfi6SaAevgYkkeW68vqZK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17590, 'Deathtrap', 'A Broadway playwright puts murder in his plan to take credit for a student''s script.', '1982-03-19', 6.68, 'https://image.tmdb.org/t/p/w500/fwrqCTcu5rAkU2dL2YqG6jjrLPn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17592, 'The Wild Parrots of Telegraph Hill', 'A homeless musician finds meaning in his life when he starts a friendship with dozens of parrots.', '2003-10-09', 7.17, 'https://image.tmdb.org/t/p/w500/kBLgd1Ep3oUItLHj23s6vGHAO80.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17600, 'Spanking the Monkey', 'Bright young student Raymond Aibelli is forced to sidetrack an important medical internship because his mother, Susan, is recovering from a broken leg. When he isn''t tasked with the most mundane aspects of Susan''s recuperation, Raymond finds distraction in a neighborhood girl, Toni Peck. But, as Susan begins relying on her son for both physical and emotional needs, Raymond starts developing disturbing and unwanted new yearnings.', '1994-01-15', 5.70, 'https://image.tmdb.org/t/p/w500/fuID31Ft8nWLcFRSQ7qZRlu49o7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17473, 'The Room', 'Johnny is a successful banker with great respect for and dedication to the people in his life, especially his future wife Lisa. The happy-go-lucky guy sees his world being torn apart when his friends begin to betray him one-by-one.', '2003-06-27', 4.00, 'https://image.tmdb.org/t/p/w500/9QscHN4pXj6Ja1k7e1ZT4vWDGnr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17609, 'Antichrist', 'A grieving couple retreats to their cabin ''Eden'' in the woods, hoping to repair their broken hearts and troubled marriage. But nature takes its course and things go from bad to worse.', '2009-05-20', 6.62, 'https://image.tmdb.org/t/p/w500/ge7zbYvpfsDP3luKi0iSpzOgncM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17610, 'Year One', 'When a couple of lazy hunter-gatherers are banished from their primitive village, they set off on an epic journey through the ancient world.', '2009-06-18', 4.99, 'https://image.tmdb.org/t/p/w500/qF573jdJYwtCbXVXPDn4xu8nW2a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (16933, 'They Drive by Night', 'Joe and Paul Fabrini are Wildcat, or independent, truck drivers who have their own small one-truck business. The Fabrini boys constantly battle distributors, rivals and loan collectors, while trying to make a success of their transport company.', '1940-07-26', 6.93, 'https://image.tmdb.org/t/p/w500/uF0X3IMhPIFgbwzlbayUsj4I6Tc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17612, 'Lost and Delirious', 'After starting at an upmarket boarding school, a teenage girl forms close friendships with her two older roommates. However, when she discovers that her new friends are lovers she finds herself caught in a complicated situation.', '2001-01-21', 6.81, 'https://image.tmdb.org/t/p/w500/3Cu95A09arsfTsOJfygVwhJe5qc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17628, 'I Am a Sex Addict', 'Just moments before his third wedding, Zahedi relates with utter sincerity and astonishing candor his obsession with prostitutes. He retraces his romantic and sexual history, including his ideological commitment to open relationships, that led to two disastrous marriages and several very pissed off ex-girlfriends.', '2006-04-12', 5.52, 'https://image.tmdb.org/t/p/w500/D9pZcSfKvUQij7x83DeIlDic1P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17641, 'National Velvet', 'Mi Taylor is a young wanderer and opportunist who finds himself in the quiet English countryside home of the Brown family. The youngest daughter, Velvet, has a passion for horses and when she wins the spirited steed Pie in a town lottery, Mi is encouraged to train the horse.', '1945-01-26', 7.20, 'https://image.tmdb.org/t/p/w500/iUQfP3s967V3SIAbyomNT8z8MIf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17644, 'Barney''s Great Adventure', 'Mom and dad dump son Cody, daughter Abby, her best friend Marcella and a baby on the farm with Grandpa and Grandma. Purple dinosaur Barney soon appears to entertain the kids, and when a large colorful egg deposited on a farm by a shooting star is accidentally carted off, Barney and the kids start their chase for it.', '1998-04-03', 5.00, 'https://image.tmdb.org/t/p/w500/tSadXiI88soRyS4mcSr7PsKWaqN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17653, 'The Legend', 'The secret Red Lotus Flower Society is committed to the overthrow of the evil Manchu Emperor and his minions. One of his Governors is sent on a mission to retrieve a list of members of that secret society. Meanwhile, Canton kung fu practitioner Fong Sai-Yuk falls in love with the beautiful daughter of a rich merchant.', '1993-03-04', 6.98, 'https://image.tmdb.org/t/p/w500/hdAqW3qn0Y9jNMjDob5ae0NRa0F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17661, 'Going My Way', 'Youthful Father Chuck O''Malley led a colorful life of sports, song, and romance before joining the Roman Catholic clergy. After being appointed to a run-down New York parish, O''Malley''s worldly knowledge helps him connect with a gang of boys looking for direction, eventually winning over the aging, conventional Parish priest.', '1944-01-01', 6.68, 'https://image.tmdb.org/t/p/w500/838yNJnOk6iZj5YK1MoKiN2n1hw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17663, 'Anne of Green Gables', 'At the turn of the century on Prince Edward Island, Matthew Cuthbert and his sister Marilla decide to take on an orphan boy as help for their farm. But they get an unexpected jolt when they''re mistakenly sent a girl instead: Anne Shirley.', '1985-12-01', 8.10, 'https://image.tmdb.org/t/p/w500/z1owlDzKO3DQpFKNFBnuQlPF891.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17654, 'District 9', 'Thirty years ago, aliens arrive on Earth. Not to conquer or give aid, but to find refuge from their dying planet. Separated from humans in a South African area called District 9, the aliens are managed by Multi-National United, which is unconcerned with the aliens'' welfare but will do anything to master their advanced technology. When a company field agent contracts a mysterious virus that begins to alter his DNA, there is only one place he can hide: District 9.', '2009-08-05', 7.48, 'https://image.tmdb.org/t/p/w500/tuGlQkqLxnodDSk6mp5c2wvxUEd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17664, 'The Horse Soldiers', 'A Union Cavalry outfit is sent behind confederate lines in strength to destroy a rail supply center. Along with them is sent a doctor who causes instant antipathy between him and the commander. The secret plan for the mission is overheard by a southern belle who must be taken along to assure her silence.', '1959-06-11', 6.94, 'https://image.tmdb.org/t/p/w500/kLBwk5ppNsA0DizEocXClTi1Lmx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17667, 'Beat Street', 'An aspiring DJ, from the South Bronx, and his best friend, a promoter, try to get into show business by exposing people to hip-hop music and culture.', '1984-06-08', 6.85, 'https://image.tmdb.org/t/p/w500/cn0gXtGgQXT7EVVXKJRhK4E1nOc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17684, 'Chouchou', 'Choukri, alias Chouchou, a transvestite Maghrebi with clear eyes, comes illegally to Paris to find his nephew. Hired as an assistant by a psychotherapist, known for his good mood, he also work as a waiter in a transvestite cabaret of Clichy where he meets Stanislas.', '2003-03-19', 5.26, 'https://image.tmdb.org/t/p/w500/74Bv2j3LVWxArUqoN2EZwS0Hr7x.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17685, 'King of Hearts', 'An ornithologist mistaken for an explosives expert is sent alone into a small French town during WWI to investigate a garbled report from the resistance about a bomb which the departing Germans have set to blow up a weapons cache.', '1966-12-21', 6.95, 'https://image.tmdb.org/t/p/w500/7RekNiu247cWDPfSqMyX77Yoez4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17687, 'The Public Enemy', 'Two young Chicago hoodlums, Tom Powers and Matt Doyle, rise up from their poverty-stricken slum life to become petty thieves, bootleggers and cold-blooded killers. But with street notoriety and newfound wealth, the duo feels the heat from the cops and rival gangsters both. Despite his ruthless criminal reputation, Tom tries to remain connected to his family, however, gang warfare and the need for revenge eventually pull him away.', '1931-04-23', 7.25, 'https://image.tmdb.org/t/p/w500/vVxdaRMprQO2DM4AFyJ6C4qZSFO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17689, 'The Gauntlet', 'Phoenix cop Ben Shockley is well on his way to becoming a derelict when he is assigned to transport a witness from Las Vegas. The witness turns out to be a belligerent prostitute with mob ties—and incriminating information regarding a high-ranking official.', '1977-12-17', 6.54, 'https://image.tmdb.org/t/p/w500/hYXkHixmH2W4hXA0qVJpT4ONPt1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17692, 'Jaws 3-D', 'A giant thirty-five-foot shark becomes trapped in a SeaWorld theme park and it''s up to the sons of police chief Brody to rescue everyone.', '1983-07-22', 4.47, 'https://image.tmdb.org/t/p/w500/kqDXj53F9paqVGJLGfHtz7giJ3s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17204, 'Paradise Lost: The Child Murders at Robin Hood Hills', 'A horrific triple child murder leads to an indictment and trial of three nonconformist boys based on questionable evidence.', '1996-12-03', 7.59, 'https://image.tmdb.org/t/p/w500/h65fwEQTv9zRNyEuExE1wAk5CQ2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17707, 'Brokedown Palace', 'Best friends Alice and Darlene take a trip to Thailand after graduating high school. In Thailand, they meet a captivating Australian man, who calls himself Nick Parks. Darlene is particularly smitten with Nick and convinces Alice to take Nick up on his offer to treat the two of them to what amounts to a day trip to Hong Kong. In the airport, the girls are seized by the police and shocked to discover that one of their bags contains heroin.', '1999-08-13', 6.45, 'https://image.tmdb.org/t/p/w500/pWxoggA0KCS5oMPDOjIDYZYzryE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17467, 'Riki-Oh: The Story of Ricky', 'In 2001, where all correctional facilities have been privatized, martial artist Ricky finds himself victim to the corrupt system, found "guilty" of the manslaughter of an infamous crime boss.', '1991-10-05', 6.87, 'https://image.tmdb.org/t/p/w500/dzG0PAbBDLbJSYuv2SM2Mjxw2MH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17710, 'Hey Arnold! The Movie', 'Arnold and his friends must recover a stolen document in order to prevent the neighborhood from being bulldozed.', '2002-06-28', 6.50, 'https://image.tmdb.org/t/p/w500/etxcq4qiFNi5p0q71APw8MNzPPT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17711, 'The Adventures of Rocky & Bullwinkle', 'Rocky and Bullwinkle have been living off the finances made from the reruns of their cartoon show. Boris and Natasha somehow manage to crossover into reality and team up with Fearless Leader, an evil criminal turned media mogul with some evil plans up his sleeve. Rocky and Bullwinkle must stop the three of them before they wreak havoc.', '2000-06-30', 4.31, 'https://image.tmdb.org/t/p/w500/xCFSsftt2rglC81I6QLWcZSTCBM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17182, 'Eye for an Eye', 'It''s fire and brimstone time as grieving mother Karen McCann takes justice into her own hands when a kangaroo court in Los Angeles fails to convict Robert Doob, the monster who raped and murdered her 17-year-old daughter.', '1996-01-12', 6.27, 'https://image.tmdb.org/t/p/w500/y2lZSdJ1o0VvLegTw3ad6KFtxra.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17465, 'Youngblood', 'A skilled young hockey prospect hoping to attract the attention of professional scouts is pressured to show that he can fight if challenged during his stay in a Canadian minor hockey town. His on-ice activities are complicated by his relationship with the coach''s daughter.', '1986-01-31', 6.19, 'https://image.tmdb.org/t/p/w500/SLQRH3AlTJHXk6ZuW0yMAelMlj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17494, 'Unlawful Entry', 'When Michael and Karen Carr’s home is robbed, the couple strike up a friendship with duty officer Pete Davis. But the disturbed cop develops an intense fixation on Karen, and his idea of friendship soon turns into a dangerous obsession, making him the Carrs’ worst nightmare.', '1992-06-26', 6.26, 'https://image.tmdb.org/t/p/w500/qt1pESASA3w4xOOPwZS3YRlcYhL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17571, 'Battle Planet', 'In the not-so-distant future, Captain Jordan Strider, a Special Forces Officer in the New World Alliance, is chosen for a top-secret mission. Sent to a desolate planet, Terra 219, to arrest possible traitors to the Alliance, Strider must survive with only a government issued experimental suit as protection. He quickly learns of a plan to end all humanity.', '2008-11-02', 4.10, 'https://image.tmdb.org/t/p/w500/rhDQ8jgr75S7Pit4JQXx8cYbsmV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17729, 'The Glenn Miller Story', 'A vibrant tribute to one of America''s legendary bandleaders, charting Glenn Miller''s rise from obscurity and poverty to fame and wealth in the early 1940s.', '1954-01-04', 7.01, 'https://image.tmdb.org/t/p/w500/eEuwIMj7jKYaUt0ZG6aVpYxlkrC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17185, 'Advise & Consent', 'Proposed by the President of the United States to fill the post of Secretary of State, Robert Leffingwell appears before a Senate committee, chaired by the idealistic Senator Brig Anderson, which must decide whether he is the right person for the job.', '1962-06-06', 7.19, 'https://image.tmdb.org/t/p/w500/hdLQlarvUmZVtrbME6y4t6Km9ZC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17736, 'Where the Day Takes You', 'King is a young man, but he''s already a veteran of life on the streets of Los Angeles. The de facto leader of a group of teenage runaways, King acts as a mentor to troubled kids such as gay hustler Little J and junkie Greg. When Heather, a beautiful girl from Chicago, starts hanging out with King and his crew, it changes the dynamic of the gang. However, it seems as though nothing will alter their dangerous lifestyle.', '1992-09-11', 6.07, 'https://image.tmdb.org/t/p/w500/6W7pwB1o601kN8zySjHNz5X3QDK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17483, 'Shelter', 'Forced to give up his dreams of art school, Zach works dead-end jobs to support his sister and her son. Questioning his life, he paints, surfs and hangs out with his best friend, Gabe. When Gabe''s older brother returns home for the summer, Zach suddenly finds himself drawn into a relationship he didn''t expect.', '2007-06-16', 7.80, 'https://image.tmdb.org/t/p/w500/eYA8KiSnIAbxtoIgg4lpZjB0dfz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17708, 'Corky Romano', 'Corky Romano is a bumbling, simpleton, veterinarian and the youngest, outcast son of an aging gangster, named Pops Romano, who calls upon Corky to infiltrate the local FBI and retrieve and destroy evidence being used to incriminate Pops for racketeering charges.', '2001-10-12', 4.45, 'https://image.tmdb.org/t/p/w500/aLgzSIgHTyWggrP7ieDVYE3PB8g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17496, 'Urban Cowboy', 'After moving to Pasadena, Texas, country boy Bud Davis starts hanging around a bar called Gilley''s, where he falls in love with Sissy, a cowgirl who believes the sexes are equal. They eventually marry, but their relationship is turbulent due to Bud''s traditional view of gender roles. Jealousy over his rival leads to their separation, but Bud attempts to win Sissy back by triumphing at Gilley''s mechanical bull-riding competition.', '1980-06-06', 6.48, 'https://image.tmdb.org/t/p/w500/2uKWi1Hb6yqkmOixRgKVwrzxljA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17187, 'The Emperor''s Club', 'William Hundert is a passionate and principled Classics professor who finds his tightly-controlled world shaken and inexorably altered when a new student, Sedgewick Bell, walks into his classroom. What begins as a fierce battle of wills gives way to a close student-teacher relationship, but results in a life lesson for Hundert that will still haunt him a quarter of a century later.', '2002-11-22', 7.12, 'https://image.tmdb.org/t/p/w500/s7BRKAq0DNcXe8Bphm6Wd5KnvlF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17190, 'Gross Anatomy', 'Joe Slovak is a brilliant first-year med student whose casual, nonconforming approach to life gets tested when he enrolls in Gross Anatomy, the toughest course in med school.', '1989-10-20', 5.67, 'https://image.tmdb.org/t/p/w500/nYP7HFuHfy3QchskZiywbJAQ8a0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17813, 'Alex & Emma', 'Writer Alex Sheldon must finish his novel within a month. If he doesn''t, he won''t get paid. And, if that happens, angry Mafia types to whom he owes money will come looking for him. In order to expedite things, Alex hires typist Emma Dinsmore and begins dictating his novel. The book is about a doomed love affair between a character similar to Alex and a character named Polina Delacroix. But, as Alex falls for Emma, his work takes a different turn.', '2003-06-20', 5.19, 'https://image.tmdb.org/t/p/w500/1CVw4MMqeBdkUs3DfCDWkaP6O3U.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17814, 'Assault on Precinct 13', 'A highway patrol officer, two criminals, and a station secretary form an unlikely alliance to defend a defunct Los Angeles precinct against a siege by a bloodthirsty street gang.', '1976-10-08', 7.26, 'https://image.tmdb.org/t/p/w500/RtGDEmXbSxE8NThCCY1SXFXLLw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17207, 'Houseguest', 'In hot water with the mob over an unpaid debt, a con man poses as a family friend in an affluent Pennsylvania suburb.', '1995-01-06', 5.53, 'https://image.tmdb.org/t/p/w500/cdiHlZho11EEqD3aPanYe1rEYRB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17819, 'Her Alibi', 'A writer of BAD detective novels is in full writers'' block. He pretends to be the alibi of a beautiful woman who was arrested for murder at first thinking her innocent, but as she shows more and more interesting abilities (such as knife throwing) he begins to doubt his first assessment.', '1989-02-03', 5.40, 'https://image.tmdb.org/t/p/w500/zPewmxWwDOMucFnaXXH26tfAv7m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17820, 'Show Boat', 'A dashing Mississippi river gambler wins the affections of the daughter of the owner of the Show Boat.', '1951-07-19', 6.20, 'https://image.tmdb.org/t/p/w500/sk7s574pI9QAi6uVqbTg0bnLEUC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17824, 'Private Resort', 'Chasing women for the weekend at a luxurious Miami resort, teen buddies Ben and Jack get more than they bargained for after crossing paths with a crafty criminal.', '1985-05-03', 5.71, 'https://image.tmdb.org/t/p/w500/temhAEeniTralG3G9NyjPmTgzIe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17832, 'Kull the Conqueror', 'A barbarian named Kull becomes ruler after defeating the old king in battle. In an effort to regain the throne, the former king''s heirs resurrect Akivasha, a witch queen. However, Akivasha has plans of her own for the throne, and only Kull stands in the way.', '1997-08-29', 5.01, 'https://image.tmdb.org/t/p/w500/cgKK2eCdb5LLaQBDQZbmR312q1O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17831, 'A Tale of Two Cities', 'Set against the conditions leading up to the French Revolution and the Reign of Terror, French doctor Alexandre Manette serves an 18-year imprisonment in the Bastille in Paris, followed by his release to live in London with the daughter he has never met.', '1935-12-25', 6.80, 'https://image.tmdb.org/t/p/w500/mO8ezngn6ZYqpCQuhXUSEtDDwos.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17740, 'Powder Blue', 'On the gritty streets of LA, the destinies of four people desperate for connection and redemption are about to collide.', '2009-05-08', 6.10, 'https://image.tmdb.org/t/p/w500/o1wQcqOoQQF7tt1HijnmQRLjTo4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17834, 'A Simple Wish', 'Murray is a male fairy godmother, and he is trying to help 8-year-old Anabel to fulfil her "simple wish" - that her father Oliver, who is a cab driver, would win the leading role in a Broadway musical. Unfortunately, Murray''s magic wand is broken and the fairies convention is threatened by evil witches Claudia and Boots.', '1997-07-11', 5.51, 'https://image.tmdb.org/t/p/w500/cfyJ7yIvNTlz2ooH8iU6r0pxAMj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17880, 'Because of Winn-Dixie', 'A girl, abandoned by her mother when she was three, moves to a small town in Florida with her father. There, she adopts an orphaned dog she names Winn-Dixie. The bond between the girl and her special companion brings together the people in a small Florida town and heals her own troubled relationship with her father.', '2005-02-18', 6.50, 'https://image.tmdb.org/t/p/w500/oMUFS7HmIyTeui5xuoIEkPYTWC8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17870, 'Chris Rock: Bigger & Blacker', 'Chris Rock brings his critically acclaimed brand of social commentary-themed humour to this HBO Special, extolling his razor-sharp wit and wisdom on such topics as gun control, President Clinton, homophobia, racism, black leaders and relationships.', '1999-07-10', 7.42, 'https://image.tmdb.org/t/p/w500/b5T4xRePE7VckU5xAFZh6jUEgD0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17887, 'Barefoot in the Park', 'In this film based on a Neil Simon play, newlyweds Corie, a free spirit, and Paul Bratter, an uptight lawyer, share a sixth-floor apartment in Greenwich Village. Soon after their marriage, Corie tries to find a companion for mother, Ethel, who is now alone, and sets up Ethel with neighbor Victor. Inappropriate behavior on a double date causes conflict, and the young couple considers divorce.', '1967-05-25', 7.14, 'https://image.tmdb.org/t/p/w500/qh64tAOmbQNoYMLTETkhmBQgSbu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17796, 'Freaked', 'A vain actor, his best friend, and an activist end up at a mutant freak farm run by a weirdo scientist.', '1993-10-01', 6.20, 'https://image.tmdb.org/t/p/w500/enQ9FBLo4bd7AHX78geP6qRSl9U.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17889, 'Anchors Aweigh', 'Two sailors on shore leave head out for four days of partying – only to become involved in the affairs of an aspiring singer and her precocious nephew.', '1945-08-13', 6.84, 'https://image.tmdb.org/t/p/w500/fPa79qA8qaikB0wiloKnfSm9NiJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17578, 'The Adventures of Tintin', 'Intrepid young reporter, Tintin, and his loyal dog, Snowy, are thrust into a world of high adventure when they discover a ship carrying an explosive secret. As Tintin is drawn into a centuries-old mystery, Ivan Ivanovitch Sakharine suspects him of stealing a priceless treasure. Tintin and Snowy, with the help of salty, cantankerous Captain Haddock and bumbling detectives, Thompson and Thomson, travel half the world, one step ahead of their enemies, as Tintin endeavors to find the Unicorn, a sunken ship that may hold a vast fortune, but also an ancient curse.', '2011-10-24', 6.93, 'https://image.tmdb.org/t/p/w500/fQZ3sLR1Fi63NMsNRbjm9q5qODJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17894, 'The Beautician and the Beast', 'A New York City beautician is mistakenly hired as the school teacher for the children of the president of a small Eastern European country.', '1997-02-07', 6.72, 'https://image.tmdb.org/t/p/w500/s2RaTrqoPvD4eYEaZCyF0zFbbpV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17897, 'The Golden Voyage of Sinbad', 'Sinbad and his crew intercept a homunculus carrying a golden tablet. Koura, the creator of the homunculus and practitioner of evil magic, wants the tablet back and pursues Sinbad. Meanwhile, Sinbad meets the Vizier who has another part of the interlocking golden map, and they mount a quest across the seas to solve the riddle of the map.', '1973-12-20', 6.72, 'https://image.tmdb.org/t/p/w500/2DQPnuAjD7H4ae6BeBAVhu9RLWa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17898, 'Silver Bullet', 'The small city of Tarker''s Mills is startled by a series of sadistic murders. The population fears the work of a maniac, but sightings of a mysterious, hairy creature soon spread. People lock themselves up at night, but there''s one boy who''s still outside…', '1985-10-10', 6.67, 'https://image.tmdb.org/t/p/w500/52CvWYuJyWcMTPvsfcmsxaVHi7f.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17905, 'Branded to Kill', 'After botching his latest assignment, a third-ranked Japanese hit man becomes the target of another assassin.', '1967-06-15', 7.20, 'https://image.tmdb.org/t/p/w500/asiSCq1SFrCV4gy7PJzw8c3m0yL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17906, 'Dummy', 'An ex-office worker becomes a ventriloquist, leading to a date with his unemployment counselor; but his quirky family and a gauche female friend may thwart his new career and love life.', '2002-09-12', 5.90, 'https://image.tmdb.org/t/p/w500/ii8h0p26vhp4G6x5Hw86ka3ys45.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17908, 'My Dog Skip', 'A shy boy is unable to make friends in Yazoo City, Mississippi in 1942, until his parents give him a terrier puppy for his ninth birthday. The dog, which he names Skip, becomes well known and loved throughout the community and enriches the life of the boy, Willie, as he grows into manhood.', '2000-01-12', 6.71, 'https://image.tmdb.org/t/p/w500/nnPv7RuSn6UaPjZussIFljZdWS8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17917, 'Oliver!', 'Musical adaptation of Charles Dickens'' Oliver Twist, a classic tale of an orphan who runs away from the workhouse and joins up with a group of boys headed by the Artful Dodger and trained to be pickpockets by master thief Fagin.', '1968-09-26', 7.00, 'https://image.tmdb.org/t/p/w500/1XJgoaOWKrqxkKeBKWLKSigqG8c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17920, 'I Capture the Castle', 'In 1930s England, 17-year-old Cassandra Mortmain and her eccentric family struggle to survive in a decaying English castle.', '2003-05-09', 6.71, 'https://image.tmdb.org/t/p/w500/fGV45q9gyysfp9SdoqrrReVxC9a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17918, 'Swamp Thing', 'Mutated by his own secret formula, Dr. Alec Holland becomes Swamp Thing, a half-human, half-plant superhero who will stop at nothing to rescue government agent Alice Cable and defeat his evil arch nemesis...even if it costs him his life.', '1982-02-19', 5.41, 'https://image.tmdb.org/t/p/w500/7BGaE9A7UeyxH29aeFbQfzEmIi0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17927, 'Fired Up!', 'Popular high schoolers and best friends Shawn and Nick decide to ditch football camp for cheerleader camp. For the girls and for the glory.', '2009-02-20', 6.10, 'https://image.tmdb.org/t/p/w500/d289eHSH77NfM7ndiE6XOHav6fz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17922, 'Golgo 13: The Professional', 'Indestructible to his enemies and irresistible to women, the professional assassin codenamed Golgo 13 is shrouded in mystery and anonymity. If you''re on his hit list, you''re already dead. Always hired on his reputation alone, Golgo never breaks a contract. Can he survive the combined forces of the FBI, CIA, the Pentagon and the U.S. Army? Has the nameless agent finally met his match against the superhuman powers of the Snake and the twin evils of the psychopathic mercenaries, Gold and Silver?', '1983-05-28', 6.25, 'https://image.tmdb.org/t/p/w500/nOTFmar2FyhDEDFNIMQL97K5Pcg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17941, 'Hush', 'Jackson and Helen are in love and about to have their first child when they move in with Jackson''s mother, Martha, in order to take care of the family estate. But all is not well in this household. Martha is jealous of her son''s affection for Helen, and, despite her Southern smile, she''s starting to act strangely. As Helen tries to create a happy home life, Martha attempts to divide the family so that Jackson will become hers alone.', '1998-03-06', 5.72, 'https://image.tmdb.org/t/p/w500/muUx7SqlYE9kb1W4xzK7AaJueeN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17956, 'He Said, She Said', 'Womanising, right-wing Dan Hanson and quiet, liberal Lorie Bryer work for the Baltimore Sun. Rivals for the job of new writer of a vacant column, the paper ends up instead printing their very different opinions alongside each other, which leads to a similarly combative local TV show. At the same time their initial indifference to each other looks like it may evolve into something more romantic.', '1991-02-22', 5.86, 'https://image.tmdb.org/t/p/w500/5uYv11zTTa83WMWwI3B6EOZtI0Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17949, 'The Pest', 'Fast-talking Latino con artist Pestario "Pest" Vargas is the target of Scottish mobsters to whom he owes a considerable debt. Willing to do anything to raise money and avoid severe injury or death, Vargas agrees to a very unusual job -- he will be transported to a remote island and hunted by Gustav Shank, a racist German executive. If he can survive a full day and night, Vargas gets $50,000 and will be set free. Is he wily enough to elude Shank?', '1997-02-07', 4.73, 'https://image.tmdb.org/t/p/w500/rmxgXwRgWJ3Ds9VQX7SDRIGJYvk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17529, 'True Grit', 'The murder of her father sends a teenage tomboy on a mission of ''justice'', which involves avenging her father''s death. She recruits a tough old marshal, ''Rooster'' Cogburn because he has ''true grit'', and a reputation of getting the job done.', '1969-06-11', 7.33, 'https://image.tmdb.org/t/p/w500/lmexRC57l39elaIcnxhaHpcaIW2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17709, 'Dudley Do-Right', 'Royal Canadian Mountie Dudley Do-right is busy keeping the peace in his small mountain town when his old rival, Snidely Whiplash, comes up with a plot to buy all the property in town, then start a phony gold rush by seeding the river with gold nuggets.', '1999-08-27', 4.13, 'https://image.tmdb.org/t/p/w500/4LP5BieqdFNlCFjxsvaA3d6hGGd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17734, 'Thirteen Conversations About One Thing', 'In New York City, the lives of a lawyer, an actuary, a house-cleaner, a professor, and the people around them intersect as they ponder order and happiness in the face of life''s cold unpredictability.', '2001-09-02', 6.25, 'https://image.tmdb.org/t/p/w500/mb3mEfzAudrPpQIxRzpLM12aiMV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17585, 'Surviving the Game', 'A homeless man is hired as a survival guide for a group of wealthy businessmen on a hunting trip in the mountains, unaware that they are killers who hunt humans for sport, and that he is their new prey.', '1994-04-15', 6.17, 'https://image.tmdb.org/t/p/w500/wRtpJFGney5gqHmMb3JjT5WN3FH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17962, 'After Life', 'On a cold Monday morning, a group of counselors clock in at an old-fashioned social services office. Their task is to interview the recently deceased, record their personal details, then, over the course of the week, assist them in choosing a single memory to keep for eternity.', '1999-04-17', 7.20, 'https://image.tmdb.org/t/p/w500/bs2M1hqAQl5LeAOPPRV4drwouZS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17741, 'Stoned', 'A chronicle of the sordid life and suspicious death of Rolling Stones co-founder Brian Jones, who was found in the bottom of his swimming pool weeks after being let go from the band.', '2005-11-18', 5.25, 'https://image.tmdb.org/t/p/w500/xfgAKZRJz4QIflwtpY4PCeG6oon.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17774, 'Derailed', 'NATO operative Jacques Kristoff (Jean-Claude Van Damme) is summoned into action—on his birthday, no less—to track down Galina Konstantin (Laura Harring), who has stolen an extremely valuable and dangerous top-secret container from the Slovakian Government.  Finding Galina doesn''t take long, and Jacques must wrap up the mission by returning Galina and the contraband to his superiors by train.  Things seem to be going smoothly as Jacques and Galina board the train posing as a couple, but soon all hell breaks loose.', '2002-05-19', 5.21, 'https://image.tmdb.org/t/p/w500/ot5eFU2sWOEG9IbWydNpwggBiIg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17745, 'Camp Nowhere', 'Morris "Mud" Himmel has a problem. His parents desperately want to send him away to summer camp. He hates going to summer camp, and would do anything to get out of it. Talking to his friends, he realizes that they are all facing the same sentence: a boring summer camp. Together with his friends, he hatches a plan to trick all the parents into sending them to a camp of their own design.', '1994-08-26', 5.90, 'https://image.tmdb.org/t/p/w500/5DmempuEgWyHCu5lMVyICTRgZUp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17985, 'Bleeder', 'Two stories for the price of one: a video store clerk tries to get acquainted with a waitress; a man beats his pregnant wife, unaware that her brother is a violent racist.', '1999-08-06', 6.71, 'https://image.tmdb.org/t/p/w500/lNF10v7Db2zq53kBcwKGlVcd8Er.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18080, 'Out to Sea', 'Care-free Charlie cons his widower brother-in-law Herb into an expenses-paid luxury cruise in search of rich, lonely ladies. The catch is that they are required to be dance hosts! With a tyrannical cruise director, and the luscious Liz and lovely Vivian, our heroes have lots of mis-adventures before they finally return to port.', '1997-07-02', 5.82, 'https://image.tmdb.org/t/p/w500/de3GHQy3TJAVhgF6ys1aWpe5jWK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18086, 'Fright Night Part 2', 'After three years of therapy Charley Brewster, now a college student, is convinced that Jerry Dandridge was a serial killer posing as a vampire. But when Regine, a mysterious actress and her entourage move into Peter Vincent''s apartment block, the nightmare starts again - and this time it''s personal!', '1988-04-07', 6.40, 'https://image.tmdb.org/t/p/w500/yd7UgJ0MP9O3XIoirrK2T5CdN5n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18009, 'Leprechaun 2', 'A thousand years ago, the Leprechaun left a bloody trail when he ripped through the countryside in search of his stolen gold. Now he''s back in the big city using all of his deadly tricks to snare the girl of his nightmares. His bloody quest becomes more deadly when her boyfriend steals one of the Leprechaun''s gold coins. The town soon discovers two dead bodies and a trail of gold dust leads them to the Leprechaun''s lair.', '1994-04-08', 5.45, 'https://image.tmdb.org/t/p/w500/fnCLZ3rpy3enYSHrzcBxnx3fozK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18088, 'Late Night Shopping', 'Four friends Sean, Vincent, Lenny and Jody find themselves at something of a deadend. Trapped in a twilight world of permanent night shift work, they hang out together in the local cafe, drinking coffee and entertaining themselves by observing Vincent''s unwavering success in pulling women. There seems to be little prospect of change...until Vincent accidentally sleeps with Sean''s girlfriend.', '2001-06-22', 6.33, 'https://image.tmdb.org/t/p/w500/3aRREJVPJFQGCv2PqNeeANnspjk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18093, 'Northanger Abbey', 'A young woman''s penchant for sensational Gothic novels leads to misunderstandings in the matters of the heart.', '2007-10-24', 6.80, 'https://image.tmdb.org/t/p/w500/gEuCp3fiWp3SBy2gnLR4HH2iAVQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18094, 'Anvil! The Story of Anvil', 'At 14, best friends Robb Reiner and Lips made a pact to rock together forever. Their band, Anvil, hailed as the "demi-gods of Canadian metal" influenced a musical generation that includes Metallica, Slayer, and Anthrax. Following a calamitous European tour, Lips and Robb, now in their fifties, set off to record their 13th album in one last attempt to fulfill their boyhood dreams.', '2008-01-14', 7.58, 'https://image.tmdb.org/t/p/w500/rDrMuFaWBKwjwEnw4C06Sm97huY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18095, 'Dragon Ball GT: A Hero''s Legacy', 'Son Goku Jr. is the great-great-grandson of the legendary martial artist Son Goku. However, unlike his predecessor he''s not a brave fighter. He''s constantly picked on by school bullies, his grandmother Pan sees this and she''s worried, but even though Goku Jr. is not a strong and powerful Saiyan, he has a kind heart, and Pan loves him. When Pan gets sick Goku Jr. realizes he must do something if he doesn''t want to lose Pan. Then he will remember about the legends of the Dragon Balls. It was told they granted a wish to the bearer, Goku Jr. needs a magical wish more than ever.', '1997-03-26', 6.80, 'https://image.tmdb.org/t/p/w500/reNPMjkPg9f6wgf6kHSSkKjBarL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18118, 'Mackenna''s Gold', 'A bandit kidnaps a Marshal who has seen a map showing a gold vein on Indian lands, but other groups are looking for it too, while the Apache try to keep the secret location undisturbed.', '1969-03-18', 6.57, 'https://image.tmdb.org/t/p/w500/uChjCbOKpoREb3yZrG1p8L3GyC7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18111, 'Bride of Re-Animator', 'Unperturbed by the disastrous outcome of his previous meddling with the dead, Dr. West continues his research into the phenomenon of re-animation; only this time, he plans to create life – starting with the heart of his young protégé Dan''s dearly deceased Meg Halsey.', '1990-09-01', 6.45, 'https://image.tmdb.org/t/p/w500/7t9PmI65umna8yq0BPU9YoKn62I.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18126, 'Hannah Montana: The Movie', 'When Miley Stewart (aka pop-star Hannah Montana) gets too caught up in the superstar celebrity lifestyle, her dad decides it''s time for a total change of scenery. But sweet niblets! Miley must trade in all the glitz and glamour of Hollywood for some ol'' blue jeans on the family farm in Tennessee, and question if she can be both Miley Stewart and Hannah Montana.', '2009-04-10', 6.58, 'https://image.tmdb.org/t/p/w500/nZUKhfpUCFfTy24LGBHdDlK5RLx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18129, 'The Grifters', 'A small-time conman has his loyalties torn between his estranged mother and his new girlfriend, both of whom are high-stakes grifters with their own angles to play.', '1990-08-08', 6.51, 'https://image.tmdb.org/t/p/w500/zMpGfkiDIdg5bB7WGcAT3Fdrfpt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18133, 'The Program', 'Several players from different backgrounds try to cope with the pressures of playing football at a major university. Each deals with the pressure differently, some turn to drinking, others to drugs, and some to studying.', '1993-09-24', 6.47, 'https://image.tmdb.org/t/p/w500/4pdbutHc9SLEPmdLKtlVffiLByP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18148, 'Tokyo Story', 'The elderly Shukishi and his wife, Tomi, take the long journey from their small seaside village to visit their adult children in Tokyo. Their elder son, Koichi, a doctor, and their daughter, Shige, a hairdresser, don''t have much time to spend with their aged parents, and so it falls to Noriko, the widow of their younger son who was killed in the war, to keep her in-laws company.', '1953-11-03', 8.15, 'https://image.tmdb.org/t/p/w500/g2YbTYKpY7N2yDSk7BfXZ18I5QV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18158, 'Earth vs. the Flying Saucers', 'Test space rockets exploding at liftoff and increased reporting of UFO sightings culminate in a direct attempt by alien survivors of a dead, extra-galactic civilization to invade Earth from impervious flying saucers, using ray-weapons of mass destruction.', '1956-06-13', 6.10, 'https://image.tmdb.org/t/p/w500/qCOLglZvQgQAyWMCZodBo3wmgqp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17768, 'A Funny Thing Happened on the Way to the Forum', 'A wily slave must unite a virgin courtesan and his young smitten master to earn his freedom.', '1966-10-16', 6.09, 'https://image.tmdb.org/t/p/w500/85GetJipw1F2tAGUEwbdD16VFLO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18162, 'Land of the Lost', 'On his latest expedition, has-been scientist Dr. Rick Marshall is sucked into a space-time vortex alongside his crack-smart research assistant Holly and redneck survivalist Will into a world populated by marauding dinosaurs and painfully slow creatures called Sleestaks. With no weapons, few skills and questionable smarts, the trio must rely on their only ally, a primate named Chaka, to try to survive long enough to figure out a way back home.', '2009-06-05', 5.46, 'https://image.tmdb.org/t/p/w500/hVCJzmK9l5FD01LFYAB1zcmmw7s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17965, 'The Abominable Dr. Phibes', 'After a team of surgeons botches his beloved wife''s operation, the distraught Dr. Phibes unleashes a score of Old-Testament atrocities on his enemies.', '1971-04-01', 6.96, 'https://image.tmdb.org/t/p/w500/4853HMKlJl1RozE6OyHBKQemCE0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18161, 'U2: Rattle and Hum', 'A concert movie on an unprecedented scale, Rattle And Hum captures U2 - on and off the stage - during their triumphant Joshua Tree tour. From the giant technicolour stadium celebrations to the black-and-white intensity of the indoor shows, this is U2 at their best. Follow the group across America, exploring new influences, playing with the legendary B.B. King from Dublin to Graceland.', '1988-11-03', 7.10, 'https://image.tmdb.org/t/p/w500/h78np6cU2cZCs9YPpvP5vz0SA7f.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18168, 'About Adam', 'A waitress falls for a handsome customer who seduces her, her two sisters, her brother, and her brother''s girlfriend.', '2001-01-19', 5.27, 'https://image.tmdb.org/t/p/w500/e4EkKwF0MTcG6lfysals7Nxeq0z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17979, 'A Christmas Carol', 'Miser Ebenezer Scrooge is awakened on Christmas Eve by spirits who reveal to him his own miserable existence, what opportunities he wasted in his youth, his current cruelties, and the dire fate that awaits him if he does not change his ways. Scrooge is faced with his own story of growing bitterness and meanness, and must decide what his own future will hold: death or redemption.', '2009-11-04', 6.91, 'https://image.tmdb.org/t/p/w500/xNwlAIdx1Ln28GRiQttUP9Gojy2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18176, 'Assassination of a High School President', 'After the theft of copies of SAT exams from a principal''s office, teenage reporter Bobby Funke sets out to unmask the thief.', '2008-01-17', 5.77, 'https://image.tmdb.org/t/p/w500/vHpyczADOGI0OXLliT4k4A1stFd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18191, 'Edmond', 'Seemingly mild-mannered businessman Edmond Burke visits a fortuneteller and hears a remark that spurs him to leave his wife abruptly and seek what is missing from his life. Encounters with strangers and unsavory people weaken the barriers encompassing his long-suppressed rage, until Edmond explodes in violence.', '2006-07-14', 5.95, 'https://image.tmdb.org/t/p/w500/2VFdGJDrl5n9WoC7d4I07hN3v5c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18183, 'Like Water for Chocolate', 'Tita is passionately in love with Pedro, but her controlling mother forbids her from marrying him. When Pedro marries her sister, Tita throws herself into her cooking and discovers she can transfer her emotions through the food she prepares, infecting all who eat it with her intense heartbreak.', '1992-04-16', 7.28, 'https://image.tmdb.org/t/p/w500/itwUdMqLmPfhtGJ44hiDxkqZhiq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18192, 'Focus', 'In the waning months of World War II, a man and his wife are mistakenly identified as Jews by their anti-Semitic Brooklyn neighbors. Suddenly the victims of religious and racial persecution, they find themselves aligned with a local Jewish immigrant in a struggle for dignity and survival.', '2001-10-19', 6.50, 'https://image.tmdb.org/t/p/w500/x0VybfDiQ8U62kqdf4BzDebrCQV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18197, 'Running on Empty', 'The Popes are a family who haven''t been able to use their real identity for years. In the late sixties, the parents set a weapons lab afire in an effort to hinder the government''s Vietnam war campaign. Ever since then, the Popes have been on the run with the authorities never far behind. Their survival is threatened when their eldest son falls in love with a girl, and announces his wish to live his life on his own terms.', '1988-09-09', 7.50, 'https://image.tmdb.org/t/p/w500/kzhyruFxY4Z5Ert8M9tuM2MV8dd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17808, 'Painted Skin', 'Painted Skin is based on one of Pu Songling''s classic short stories in Strange Stories from a Chinese Studio. Zhou Xun stars as Xiao Wei, a fox spirit that feasts on human hearts in order to maintain her lovely, youthful appearance. When General Wang Sheng (Chen Kun) ''rescues'' her from a band of bandits and brings her home, trouble brews as the demon falls in love with the general.', '2008-09-25', 6.00, 'https://image.tmdb.org/t/p/w500/5F7FS2brRyRp2lSLEsuvuRBSsrt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18212, 'Better Than Chocolate', 'Not long after moving into her own place, Maggie finds herself with two unsolicited roommates: her recently divorced mother, Lila, and her young brother. The timing is especially bad, considering Maggie has fallen hard for an attractive woman, Kim, only hours before they move in. What could be a nonissue becomes increasingly complicated -- since Maggie''s family is unaware of her sexual orientation, and Maggie is not open to sharing that information.', '1999-07-08', 6.00, 'https://image.tmdb.org/t/p/w500/7FC2UK7MyEwlmbJGCIIFg4U7VPU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18030, 'Kiss Me Deadly', 'One evening, Hammer gives a ride to Christina, an attractive hitchhiker on a lonely country road, who has escaped from the nearby lunatic asylum. Thugs waylay them and force his car to crash. When Hammer returns to semi-consciousness, he hears Christina being tortured until she dies. Hammer, both for vengeance and in hopes that "something big" is behind it all, decides to pursue the case.', '1955-04-28', 7.22, 'https://image.tmdb.org/t/p/w500/z7me91nrpWLHY1mZOB2v20cK0zY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
