INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17984, 'The Absent-Minded Professor', 'Bumbling professor Ned Brainard accidentally invents flying rubber, or "Flubber", an incredible material that gains energy every time it strikes a hard surface. It allows for the invention of shoes that can allow jumps of amazing heights and enables a modified Model-T to fly. Unfortunately, no one is interested in the material except for Alonzo Hawk, a corrupt businessman who wants to steal the material for himself.', '1961-01-20', 6.60, 'https://image.tmdb.org/t/p/w500/gCnuDDqoyaBdeeItQ4BjKtYpzF6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17770, 'Trial and Error', 'When lawyer Charlie is sent to a small Nevada town to file a continuance request for a client, his actor friend Richard turns up to throw a surprise bachelor party celebrating his upcoming marriage to the boss''s daughter. When Charlie is too hung-over to make it to court for the hearing, Richard fills in, inadvertently committing felony fraud, and Charlie is left with no choice but to coach the clueless Richard through the whole trial.', '1997-05-30', 5.42, 'https://image.tmdb.org/t/p/w500/menUTMx04eYe8EYKhJnGYA4gK6Q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
