INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17809, 'Fist of Legend', 'Chen returns to his school when he finds out that his martial arts teacher has died. When he learns that his school students are harassed by some hooligans, he gears himself up to save them.', '1994-12-22', 7.50, 'https://image.tmdb.org/t/p/w500/Aqa1Yuog2OFrduwSffxZc2w4Tnk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
