INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18172, 'All the Right Moves', 'Sensitive study of a headstrong high school football star who dreams of getting out of his small Western Pennsylvania steel town with a football scholarship. His equally ambitious coach aims at a college position, resulting in a clash which could crush the player''s dreams.', '1983-10-21', 5.76, 'https://image.tmdb.org/t/p/w500/y8OSutSNEi84ROcqyV7Tu7p8xYg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
