INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18250, 'Dr. Phibes Rises Again', 'The eminent Dr. Phibes awakens from a decade of suspended animation and heads to Egypt with the corpse of his dead wife, which he intends to resurrect by murdering people in strange and heinous ways.', '1972-07-01', 6.27, 'https://image.tmdb.org/t/p/w500/g0YtuuuMpBHN11qDhQvQnmVGESy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17801, 'The Letter', 'After a woman shoots a man to death, a damning letter she wrote raises suspicions.', '1940-11-21', 7.28, 'https://image.tmdb.org/t/p/w500/fe43qXp2sRAZbPDKX1puKGEwOon.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18317, 'Truly Madly Deeply', 'Nina is totally heartbroken at the death of her boyfriend Jamie, but is even more unprepared for his return as a ghost. At first it''s almost as good as it used to be – hey, even the rats that infested her house have disappeared. But Jamie starts bringing ghostly friends home and behaving more and more oddly.', '1991-05-03', 6.90, 'https://image.tmdb.org/t/p/w500/jjLEXLTXfJPYtl31knRS8bjclf0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18256, 'Castle Freak', 'John Reilly discovers that his family''s newly inherited castle in Italy is haunted by a relentless, bloodthirsty creature.', '1996-04-20', 6.11, 'https://image.tmdb.org/t/p/w500/rZv3aUkNngyZeiCgAjOEF5n0tve.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18320, 'The Young Victoria', 'As the only legitimate heir of England''s King William, teenage Victoria gets caught up in the political machinations of her own family. Victoria''s mother wants her to sign a regency order, while her Belgian uncle schemes to arrange a marriage between the future monarch and Prince Albert, the man who will become the love of her life.', '2009-03-04', 7.16, 'https://image.tmdb.org/t/p/w500/iGyuReyij3bPCtzJdSjTR8PR0pa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18329, 'Happy Together', 'A couple travels from Hong Kong to Argentina to revive their relationship but experience turbulence when both men''s lives drift in separate directions.', '1997-05-30', 7.60, 'https://image.tmdb.org/t/p/w500/kO4KjUkQOfWSBw06Bdl7m6AlEP7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18331, 'The Nutty Professor', 'A timid, nearsighted chemistry teacher discovers a magical potion that can transform him into a suave and handsome Romeo. The Jekyll and Hyde game works well enough until the concoction starts to wear off at the most embarrassing times.', '1963-06-04', 6.50, 'https://image.tmdb.org/t/p/w500/a3lzU19j7WGfyXVDfPMdh8DAkru.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18333, 'Hour of the Wolf', 'While vacationing on a remote German island with his younger pregnant wife, an artist has an emotional breakdown while confronting his repressed desires.', '1968-02-19', 7.44, 'https://image.tmdb.org/t/p/w500/jSqTnEP1x1OcOglqrInYvGSF1tL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18074, 'Duets', 'Duets is a road-trip comedy which revolves around the little known world of karaoke and the whimsical characters who inhabit it. All roads lead to Omaha, site of a national karaoke competition where this motley group of singers and stars come together for a blow-out sing-off.', '2000-09-09', 5.73, 'https://image.tmdb.org/t/p/w500/isxHRG54S1bz1A1CAlPaAAoh65k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18360, 'Night at the Museum: Battle of the Smithsonian', 'Hapless museum night watchman Larry Daley must help his living, breathing exhibit friends out of a pickle now that they''ve been transferred to the archives at the Smithsonian Institution. Larry''s (mis)adventures this time include close encounters with Amelia Earhart, Abe Lincoln and Ivan the Terrible.', '2009-05-20', 6.16, 'https://image.tmdb.org/t/p/w500/l9yAQn6TyrA3gv5xZZkiMMoZsiw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18355, 'The Assignment', 'Jack Shaw has experienced the terror first-hand. He''s a top CIA agent who''s tracked international killer-for-hire Carlos "The Jackal" Sanchez for over twenty years and barely survived Carlos'' devastating bombing of a Parisian cafe. Now, he finally gets a break when he discovers Carlos'' dead ringer: American naval officer and dedicated family man Annibal Ramirez.', '1997-09-28', 6.36, 'https://image.tmdb.org/t/p/w500/lhuV5cvxFhUrB6F4smVZGmdSwbT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18385, 'Together', 'When a violin prodigy Xiaochun and his father head to Beijing seeking fame and fortune, they soon discover a fierce world of cutthroat ambition. But when Xiaochun is "adopted" by a famous music tutor, success finally seems within reach - until a shocking discovery begins to unravel his entire world, and the boy must make the most difficult choice of his life. Can he achieve the fame his father had always hoped for without losing the extraordinary passion that sets him apart?', '2002-09-10', 6.91, 'https://image.tmdb.org/t/p/w500/yG67qljsdR06NzwdWM9wBQ5EkyY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18387, 'Big Wednesday', 'Three 1960s California surfers fool around, drift apart and reunite years later to ride epic waves.', '1978-05-26', 6.94, 'https://image.tmdb.org/t/p/w500/zMOZoNszmmlf3jUivDUEFgCrReo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18391, 'Easy Money', 'To inherit his mother-in-law''s colossal fortune, a hard living gambling addict must change his unhealthy ways before it gets the best of him.', '1983-08-19', 6.01, 'https://image.tmdb.org/t/p/w500/nREZhCfkUgl6XqMZAvd6DCbVj2c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18398, 'Suddenly', 'The tranquility of a small town is marred only by sheriff Tod Shaw''s unsuccessful courtship of widow Ellen Benson, a pacifist who can''t abide guns and those who use them. But violence descends on Ellen''s household willy-nilly when the U.S. President passes through town... and slightly psycho hired assassin John Baron finds the Benson home ideal for an ambush.', '1954-09-17', 6.40, 'https://image.tmdb.org/t/p/w500/v0eQfRMVJtvEkaJjBsSrd6ri1UI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18395, 'Exit to Eden', 'Photographer Elliot Slater has inadvertently snapped the only existing photos of elusive jewel thief Omar. When Elliot leaves for a private vacation on an S&M island, he is followed by Omar, Omar''s partner, Nina, and undercover police officers Fred and Sheila. Unaware of the number of people chasing him, Elliot enjoys his stay at the resort, and finds himself falling in love with head dominatrix Lisa.', '1994-10-14', 4.22, 'https://image.tmdb.org/t/p/w500/dUtpplO9K03uYCA71Vqj9ZRkVyA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18402, 'Something to Talk About', 'Grace King Bichon, who is managing her father''s riding-stable, discovers that her husband Eddie is deceiving her with another woman. After confronting him in the middle of the night on the streets of their small home town, she decides to stay at her sister Emma Rae''s house for a while to make up her mind. Breaking out of her everyday life, she starts to question the authority of everyone.', '1995-08-04', 5.62, 'https://image.tmdb.org/t/p/w500/a52KpsmvLNdTdmDzw1fUrJONpfH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18408, 'Cherish', 'After a martini-induced rampage, a fantasy-prone young woman is placed under house arrest.', '2002-01-17', 6.05, 'https://image.tmdb.org/t/p/w500/hTNAKGnqi8v4FRPEjm9Wl5S5yMz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18410, 'Project X', 'A young inductee into the military is given the task of looking after some chimpanzees used in the mysterious ''Project X''. Getting to know the chimps fairly well, he begins to suspect there is more to the secret project than he is being told.', '1987-04-17', 6.30, 'https://image.tmdb.org/t/p/w500/odUw1Th64wqGF8hQLyNJoKWbAXX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18209, 'Bedazzled', 'A hapless loser sells his soul to the Devil in exchange for seven wishes, but has trouble winning over the girl of his dreams.', '1967-10-30', 6.20, 'https://image.tmdb.org/t/p/w500/4POWJtOXt19PWfO18rHpw5GIQc6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18414, 'Kids in the Hall: Brain Candy', 'A pharmaceutical scientist creates a pill that makes people remember their happiest memory, and although it''s successful, it has unfortunate side effects.', '1996-04-02', 6.25, 'https://image.tmdb.org/t/p/w500/j7LYkIa2KC98ZqZmFIjEmtvlv87.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
