INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18417, 'The Other Sister', 'A mentally challenged girl proves herself to be every bit as capable as her "perfect" sister when she moves into an apartment and begins going to college.', '1999-02-26', 6.42, 'https://image.tmdb.org/t/p/w500/4rBrYRkB7btGex5Bs0yOpqBZgsR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18438, 'Castaway on the Moon', 'Mr. Kim is jobless, lost in debt and has been dumped by his girlfriend. He decides to end it all by jumping into the Han River – only to find himself washed up on a small, mid-river island. He soon abandons thoughts of suicide or rescue and begins a new life as a castaway. His antics catch the attention of a young woman whose apartment overlooks the river. Her discovery changes both their lives.', '2009-05-14', 7.91, 'https://image.tmdb.org/t/p/w500/gGzovvmOEyNVUu4WEHtw9wfDsqI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18435, 'Crush', 'Three 40-something women in a small English town meet weekly for a ritual of gin, cigarettes, and sweets -- and swapped stories arguing which of them has the most pathetic love life. Kate is headmistress at the local school; her best friends are the town''s police chief and a cynical, thrice-divorced doctor.', '2002-06-07', 5.64, 'https://image.tmdb.org/t/p/w500/1ZEWDLOhlOymdcitI31kwulUJ6G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18423, 'B.A.P.S', 'Two wannabe Black American princesses aim to marry rich men, who will pay for their world''s first combination hair salon and soul food restaurant.', '1997-03-28', 5.36, 'https://image.tmdb.org/t/p/w500/yi40NrDfdv8vX0aoWvis3CnCVWj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18444, 'Swiss Family Robinson', 'After being shipwrecked, the Robinson family is marooned on an island inhabited only by an impressive array of wildlife. In true pioneer spirit, they quickly make themselves at home but soon face a danger even greater than nature: dastardly pirates.', '1960-12-21', 6.84, 'https://image.tmdb.org/t/p/w500/3ZItm1RcdwNuPnCaaqEFGrbVlcO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (17993, 'Henry & June', 'While traveling in Paris, author Henry Miller and his wife, June, meet Anais Nin, and sexual sparks fly as Nin starts an affair with the openly bisexual June. When June is forced to return to the U.S., she gives Nin her blessing to sleep with her husband. Then, when June returns to France, an unexpected, and sometimes contentious, threesome forms.', '1990-09-28', 6.00, 'https://image.tmdb.org/t/p/w500/cDMQLwT5LpdbA4dc4Twn43sbGRw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18069, '8 Seconds', 'This film chronicles the life of Lane Frost, 1987 PRCA Bull Riding World Champion, his marriage and his friendships with Tuff Hedeman (three-time World Champion) and Cody Lambert.', '1994-02-25', 7.10, 'https://image.tmdb.org/t/p/w500/wqKVkOveZrK6zwfrptGLVPmnMpR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18254, 'Reds', 'An account of the revolutionary years of the legendary American journalist John Reed, who shared his adventurous professional life with his radical commitment to the socialist revolution in Russia, his dream of spreading its principles among the members of the American working class, and his troubled romantic relationship with the writer Louise Bryant.', '1981-12-25', 6.87, 'https://image.tmdb.org/t/p/w500/AeiKdVVM93fwfQG1m3N0cgVZgHl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18283, 'Brigadoon', 'Americans Jeff and Tommy, hunting in Scotland, stumble upon a village - Brigadoon. They soon learn that the town appears once every 100 years in order to preserve its peace and special beauty. The citizens go to bed at night and when they wake up, it''s 100 years later. Tommy falls in love with a beautiful young woman, Fiona, and is torn between staying or going back to his hectic life in New York.', '1954-09-08', 6.53, 'https://image.tmdb.org/t/p/w500/va3DcpyZDnnWdRB0FTPKzObo3Uz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18203, 'Big Night', 'Primo and Secondo, two immigrant brothers, pin their hopes on a banquet honoring Louis Prima to save their struggling restaurant.', '1996-09-20', 6.99, 'https://image.tmdb.org/t/p/w500/8AJGSDyrj3Dz2B57n1ZB4qNPbmJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18462, 'Night of the Comet', 'After a comet wipes out most of life on Earth, two Valley Girls find themselves fighting against cannibal zombies and a sinister group of scientists.', '1984-11-16', 6.20, 'https://image.tmdb.org/t/p/w500/xNXnLXu73LotJ9APaJZZXflBelQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18533, 'Bronson', 'A young man who was sentenced to 7 years in prison for robbing a post office ends up spending 30 years in solitary confinement. During this time, his own personality is supplanted by his alter ego, Charles Bronson.', '2009-03-13', 6.94, 'https://image.tmdb.org/t/p/w500/6diyyGIbBNiANsdIaCGtyv4IofR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18543, 'Revenge of the Nerds III: The Next Generation', 'The nerds are now in control of the university, as a result of Lewis Skolnick and the rest''s actions in the two previous movies. A new generation of sportsmen arrive, however, determined on winning the school back. The principle, himself an ex-nerd fighter, helps them, and the nerds return to suppression. Harold Skolnick needs help from his uncle Lewis, the hero of the first two movies. Lewis, however, are not too proud of his nerd past, and won''t reveal any of it, much less help his nephew. However, his wife makes him change his mind, and with help from his friends from the first two movies, they start the fight to win the school back, using classic nerd tricks.', '1992-07-13', 4.57, 'https://image.tmdb.org/t/p/w500/ql88TgCS7cA6gxts2LOKIqeQ1Ug.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18451, 'The Whole Wide World', 'In 1930s Texas, pulp fiction master Robert E. Howard is introduced to Novalyne Price, a teacher with aspirations of becoming an author herself, and they begin a unique relationship filled with conversation and imagination. Although the possibility exists for romance, Howard''s obsession with his work and dedication to his sick mother leads Price to look elsewhere for love, leaving Howard feeling betrayed and alone.', '1996-09-08', 6.60, 'https://image.tmdb.org/t/p/w500/ajMk4ueXcOCbxwJjJecltiGhYrn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18292, 'George Washington', 'During an innocent game in an abandoned amusement park, a member of the group dies. Narrated by one of the children, the film follows the kids as they struggle to balance their own ambitions and relationships against a tragic lie.', '2000-10-27', 6.71, 'https://image.tmdb.org/t/p/w500/g9nZi8u5LqSrVKEpSm199EM4hk5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18282, 'One Crazy Summer', 'An aspiring teenage cartoonist and his friends come to the aid of a singer trying to save her family property from developers.', '1986-08-08', 6.02, 'https://image.tmdb.org/t/p/w500/hwrMVPwGFB3fouqD5PhhmbafB7G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18487, 'The Taking of Pelham 1 2 3', 'Armed men hijack a New York City subway train, holding the passengers hostage in return for a ransom, and turning an ordinary day''s work for dispatcher Walter Garber into a face-off with the mastermind behind the crime.', '2009-06-10', 6.36, 'https://image.tmdb.org/t/p/w500/rEnyQiBu6goqJfvQXpUZQjpoHVp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
