INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18467, 'Spiral', 'A reclusive telemarketer has only one semblance of a friend: His telecommuter boss. But the telemarketer''s social circle seems to improve greatly when a whimsical co-worker enters his life. Only, as he begins to sketch his new friend''s portrait, disturbing "voices" from the phone man''s past threaten to lead him into a network of destruction.', '2007-01-27', 6.11, 'https://image.tmdb.org/t/p/w500/cyzyZ8HA2zqL9C3QrpHI7QqGr0r.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18588, '52 Pick-Up', 'Harry Mitchell is a successful Los Angeles manufacturer whose wife is running for city council. His life is turned upside down when three blackmailers confront him with a videotape of him with his young mistress and demand $100,000. Fearing that the story will hurt his wife''s political campaign if he goes to the police, Harry pretends that he will pay the men, but does not follow through.', '1986-11-07', 6.06, 'https://image.tmdb.org/t/p/w500/ru8dtoh6tNi7kKAbLgbaE9J5SGf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18079, 'Nine Queens', 'Two con artists try to swindle a stamp collector by selling him a sheet of counterfeit rare stamps, the "nine queens".', '2000-08-31', 7.79, 'https://image.tmdb.org/t/p/w500/u2L4Foderu7SCPci5c3jsUfEJPP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18595, 'Garage', 'Due to a learning disability, Josie''s life in a tiny town revolves around a menial job taking care of a garage that could close at any day. Things start to change, however, when David, the son of his boss'' girlfriend, comes to work with him. Josie hangs out with David and his teenage friends, bringing them beer, and despite being a grown man himself, finds that the new company lifts his spirits. But his simple-mindedness blinds him to some potential legal dangers.', '2007-10-05', 6.59, 'https://image.tmdb.org/t/p/w500/kXAgwhwMNZk49KGLF0zJO8cMZiH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
