INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18240, 'The Proposal', 'When she learns she''s in danger of losing her visa status and being deported, overbearing book editor Margaret Tate forces her put-upon assistant, Andrew Paxton, to marry her.', '2009-06-02', 7.18, 'https://image.tmdb.org/t/p/w500/6stnAm1wSek8ZrislwK4xGTyCnt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
