INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18615, 'Fur: An Imaginary Portrait of Diane Arbus', 'In 1958 New York Diane Arbus is a housewife and mother who works as an assistant to her husband, a photographer employed by her wealthy parents. Respectable though her life is, she cannot help but feel uncomfortable in her privileged world. One night, a new neighbor catches Diane''s eye, and the enigmatic man inspires her to set forth on the path to discovering her own artistry.', '2006-08-30', 6.13, 'https://image.tmdb.org/t/p/w500/62Owq5NVXvhgEqTklu1oMwTWQUL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
