INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18646, 'Royal Wedding', 'A brother and sister dance act encounter challenges and romance when booked in London during the Royal Wedding.', '1951-03-08', 6.45, 'https://image.tmdb.org/t/p/w500/5hOyBgsmSApFl10ZfaYxUTQu5Ze.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18647, 'One-Eyed Jacks', 'Running from the law after a bank robbery in Mexico, Dad Longworth finds an opportunity to take the stolen gold and leave his partner Rio to be captured. Years later, Rio escapes from the prison where he has been since, and hunts down Dad for revenge. Dad is now a respectable sheriff in California, and has been living in fear of Rio''s return.', '1961-03-30', 6.80, 'https://image.tmdb.org/t/p/w500/xal47bRKVIxErB7h2CScY3GBnoT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18658, 'Clean Slate', 'Pogue is a private eye with a problem: every morning when he wakes up, he has total amnesia, waking up with a ''blank slate''. Since he is in the middle of a hot investigation and has a developing romance, this is less than convenient.', '1994-05-06', 5.80, 'https://image.tmdb.org/t/p/w500/kAYsvQvBVshLHGTIDGHcj9jTJq0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18660, 'The Apple Dumpling Gang', 'A roving bachelor gets saddled with three children and a wealth of trouble when the youngsters stumble upon a huge gold nugget. They join forces with two bumbling outlaws to fend off the greedy townspeople and soon find themselves facing a surly gang of sharpshooters.', '1975-07-01', 6.57, 'https://image.tmdb.org/t/p/w500/cSbRtW2rSpz6AxS4BwtunpFHma.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18681, 'Eye of the Beholder', 'A reclusive surveillance expert is hired to spy on a mysterious blackmailer, who just may be a serial killer.', '1999-11-24', 4.95, 'https://image.tmdb.org/t/p/w500/4eB1Gw5r3Etbe4su6PhOo6OAN9E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18691, 'Frankie and Johnny', 'Johnny is a riverboat entertainer with a big gambling problem. After a psychic tells Johnny how he can change his luck, the appearance of a new ''lady luck'' soon causes a catfight with Johnny''s girlfriend, Frankie.', '1966-03-31', 5.60, 'https://image.tmdb.org/t/p/w500/p0FXqTJ8fNASnJRxW8PYE5lfM6L.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18701, 'Being Julia', 'Julia Lambert is a true diva: beautiful, talented, weathly and famous.  She has it all - including a devoted husband who has mastermined her brilliant career - but after years of shining in the spotlight she begins to suffer from a severe case of boredom and longs for something new and exciting to put the twinkle back in her eye.  Julia finds exactly what she''s looking for in a handsome young American fan, but it isn''t long before the novelty fling adds a few more sparks than she was hoping for.  Fortuately for her, this surprise twist in the plot will thrust her back into the greatest role of her life.', '2004-09-03', 6.36, 'https://image.tmdb.org/t/p/w500/wiJp4pN2bYgtWQqZYZhGNLeFmx8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18480, 'Brüno', 'Flamboyantly gay Austrian television reporter Bruno stirs up trouble with unsuspecting guests and large crowds through brutally frank interviews and painfully hilarious public displays of homosexuality.', '2009-07-08', 5.63, 'https://image.tmdb.org/t/p/w500/wcUc7TYtsb72dHVb51sYaGIvQsr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18712, 'Sands of Iwo Jima', 'Haunted by personal demons, Marine Sgt. John Stryker is hated and feared by his men, who see him as a cold-hearted sadist. But when their boots hit the beaches, they begin to understand the reason for Stryker''s rigid form of discipline.', '1950-01-01', 6.37, 'https://image.tmdb.org/t/p/w500/utpy9JLuyhsxpw2E3yExw23f3eS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18706, 'Sherlock Holmes and the Secret Weapon', 'In the midst of World War II, Sherlock Holmes rescues the Swiss inventor of a new bomb-sight from the Gestapo and brings him to England, where he quickly falls into the clutches of the evil Professor Moriarty.', '1942-12-25', 6.42, 'https://image.tmdb.org/t/p/w500/50qLIyhdWrDxcZE0bmHhUaxb2FP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18551, 'Flesh and Bone', 'Haunted by memories of his father murdering a family, Arlis Sweeney prefers to keep to himself, focusing his energy on his work. One day, the traumatic past that eats away at him returns when he meets Kay Davies, a woman connected to the bloody event. Against all odds, Arlis and Kay fall in love; however, when his father, Roy, reappears in his life -- with the coldhearted Ginnie in tow -- Arlis must deal with his past demons.', '1993-11-05', 5.96, 'https://image.tmdb.org/t/p/w500/gNaZSODlVRiQltGWjS8vQZEYJTq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18713, 'The Jerky Boys', 'When two unemployed telephone pranksters decide to use their vocal "talents" to impersonate a Chicago mob boss and curry favor with organized crime in New York, the trouble begins. It isn''t long before Johnny and Kamal (the "Jerky Boys" of crank call fame) are wanted by the local mafia, the police, and their neighbor.', '1995-02-03', 4.40, 'https://image.tmdb.org/t/p/w500/yUbdqyZaeaoNKBQmnmtim1IIAf1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18722, 'Mr. Baseball', 'Jack Elliot, a one-time MVP for the New York Yankees is now on the down side of his baseball career. With a falling batting average, does he have one good year left and can the manager of the Chunichi Dragons, a Japanese Central baseball league find it in him?', '1992-10-01', 5.90, 'https://image.tmdb.org/t/p/w500/6J56wP2ZKJcyfQ1sa4Dm3jSbXzo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18724, 'Attack of the 50 Foot Woman', 'When an abused wife grows to giant size because of an alien encounter and an aborted murder attempt, she goes after her cheating husband with revenge on her mind.', '1958-05-18', 4.80, 'https://image.tmdb.org/t/p/w500/y661j8lD78zuV2sDGF5uc6nU7KF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18489, 'The Yes Men Fix the World', 'THE YES MEN FIX THE WORLD is a screwball true story about two gonzo political activists who, posing as top executives of giant corporations, lie their way into big business conferences and pull off the world''s most outrageous pranks.', '2009-01-18', 7.10, 'https://image.tmdb.org/t/p/w500/6eVleb6nkqjxUfLPRS5GwSKlA9J.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18734, 'L.I.E.', 'With his mother dead and his father busy at work, Howie feels adrift in his New York suburb. He and his friend Gary spend their time burglarizing their neighbors'' homes — until they make the mistake of robbing the house of Big John, a macho former Marine who is also an unrepentant pedophile. He propositions Howie, who declines, but the two eventually develop an unlikely and dangerous friendship.', '2001-09-07', 6.75, 'https://image.tmdb.org/t/p/w500/ck5Tkq17M6khEN7JQlQznoYl37L.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18762, 'Blue Juice', 'JC is the hero of the Cornish surfing community. Staring thirty hard in the face, he fears that the wave that has carried him through a prolonged adolescence is heading for the rocks as his girlfriend pressures him for commitment and his friends contemplate growing up.', '1995-09-15', 4.11, 'https://image.tmdb.org/t/p/w500/9cGEpHyiPk1qRuY1Kv57RGkyesr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18764, 'Twin Dragons', 'Identical twins are separated at birth, one becoming a streetwise mechanic, and the other an acclaimed classical concert conductor. Finally meeting in adulthood, they''re mistaken for the other and entangled in each other''s worlds.', '1992-01-15', 6.88, 'https://image.tmdb.org/t/p/w500/tm153lMrHy6HykEYwoP0EI3dQ8k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18781, 'The Haunting in Connecticut', 'When the Campbell family moves to upstate Connecticut, they soon learn that their charming Victorian home has a disturbing history: not only was the house a transformed funeral parlor where inconceivable acts occurred, but the owner''s clairvoyant son Jonah served as a demonic messenger, providing a gateway for spiritual entities to crossover.', '2009-03-27', 6.17, 'https://image.tmdb.org/t/p/w500/dTfL0YbTa7S59vZYmWbk6UofHkI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18299, 'Love in the Afternoon', 'A middle-aged playboy becomes fascinated by the daughter of a private detective who has been hired to entrap him with a client''s wife.', '1957-05-29', 7.02, 'https://image.tmdb.org/t/p/w500/jCHVviBhRQ7OkJFQfziO2N2ZJmh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18561, 'Oxygen', 'When housewife Frances Hannon is abducted and buried alive, detective Madeline Foster is brought in. With only 24 hours before Frances'' oxygen runs out, Madeline pursues the trail laid by a killer calling himself Harry Houdini. After capturing him, Madeline brings Harry back to the police station, but is unable to get him to confess where Frances is buried. As time runs down, Harry gets inside the head of unstable, alcoholic Madeline.', '1999-11-12', 6.09, 'https://image.tmdb.org/t/p/w500/9qejeCJ2lUevfwRdwdGADuoFX0X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18311, 'Days of Being Wild', 'Yuddy, a Hong Kong playboy known for breaking girls'' hearts, tries to find solace and truth after discovering the woman who raised him isn''t his mother.', '1990-12-15', 7.28, 'https://image.tmdb.org/t/p/w500/g0nbZt1eFlL8FqG8r524iXnpoQV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18252, 'My Science Project', 'His high school teacher issues an ultimatum: turn in a science project or flunk. So Mike Harlan scavenges a military base''s junk pile for a suitable gizmo. He finds one... and unwittingly unleashes the awesome power and energy of the unknown. Twisted dimensions. Time warps. A fantastic realm where the past, present, and future collide in a whirling vortex of startling adventure and superlative special effects.', '1985-08-09', 6.27, 'https://image.tmdb.org/t/p/w500/1fbVPx5VVEsgJ7M9sTzvbDjhgks.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18841, 'The Lost Skeleton of Cadavra', 'A dedicated scientist, aided by his clueless wife, rolls up his shirt sleeves and tries to save the world from a radioactive monster, curious space aliens, an evil scientist and a crabby skeleton.', '2001-09-12', 6.28, 'https://image.tmdb.org/t/p/w500/nGUjqu7DotLx6yfakAeqaj8D1FO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18857, 'Crime Story', 'A special agent is assigned to protect a wealthy business magnate. However, when the businessman is kidnapped in a daring ambush, he teams up with a seasoned detective to crack the case. But soon he discovers the case isn''t that simple.', '1993-06-24', 6.77, 'https://image.tmdb.org/t/p/w500/1LzBLlptRC7ogT8OPi8cb0NrDQb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18499, 'The Decline of the American Empire', 'Four very different Montreal university teachers gather at a rambling country house to prepare a dinner. Remy (married), Claude (a homosexual), Pierre (involved with a girlfriend) and Alain (a bachelor) discuss sex, the female body and their affairs with them. Meanwhile, their four female guests, Louise (Remy''s wife of 15 years), Dominique (a spinster), Diane (a divorcée) and Danielle (Pierre''s girlfriend) are spending the time at a downtown health gym. They also discuss sex, the female body and, naturally, men. Later in the evening, they finally meet at the country house and have dinner. A ninth guest, named Mario, who used to know Diane, drops in on the group for some talk and has a surprise of his own.', '1986-06-19', 6.71, 'https://image.tmdb.org/t/p/w500/j5Bi5lr7Z2tr9fEJI0YuS0AS2iG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18736, 'The Lizzie McGuire Movie', 'Lizzie McGuire has graduated from middle school and takes a trip to Rome, Italy with her class. And what was supposed to be only a normal trip, becomes a teenager''s dream come true.', '2003-05-02', 6.33, 'https://image.tmdb.org/t/p/w500/pLi6nOT95LHgCBicakNagC41uFM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18491, 'Neon Genesis Evangelion: The End of Evangelion', 'SEELE orders an all-out attack on NERV, aiming to destroy the Evas before Gendo can advance his own plans for the Human Instrumentality Project. Shinji is pushed to the limits of his sanity as he is forced to decide the fate of humanity.', '1997-07-19', 8.30, 'https://image.tmdb.org/t/p/w500/j6G24dqI4WgUtChhWjfnI4lnmiK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18501, 'Gamer', 'Mind-control technology has taken society by a storm, a multiplayer on-line game called "Slayers" allows players to control human prisoners in mass-scale. Simon controls Kable, the online champion of the game. Kable''s ultimate challenge becomes regaining his identity and independence by defeating the game''s mastermind.', '2009-09-03', 5.69, 'https://image.tmdb.org/t/p/w500/d5BTNmr87p7EvguTFW72vlL9l9H.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18784, 'Run Silent, Run Deep', 'The captain of a submarine sunk by the Japanese during WWII is finally given a chance to skipper another sub after a year of working a desk job. His singleminded determination for revenge against the destroyer that sunk his previous vessel puts his new crew in unneccessary danger.', '1958-03-27', 7.00, 'https://image.tmdb.org/t/p/w500/gIoao6u9DiTSyXWk4PFD0MX6PXx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18509, 'Caddyshack II', 'When a crass new-money tycoon''s membership application is turned down at a snooty country club, he retaliates by buying the club and turning it into a tacky amusement park.', '1988-07-22', 4.18, 'https://image.tmdb.org/t/p/w500/iHvCXCjiLN6bLf39CnKdDzGbku2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18862, 'House Arrest', 'High-schooler Grover Beindorf and his younger sister Stacy decide that their parents, Janet and Ned, are acting childishly when they decide to divorce after 18 years of marriage, so they lock them up in the basement until they''ll sort out their problems.', '1996-08-14', 5.35, 'https://image.tmdb.org/t/p/w500/mpQg8IgbmrMY0skgpTXBA9EhiWy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18303, 'If I Were a Rich Man', 'Between Alice, a hospital nurse and Aldo, a shampoo sales representative, things have turned sour of late. Alice blames her husband for lacking ambition and contemplates divorce.One day Aldo wins the ten million euro lotto prize. But, unwilling to share the bonanza, he keeps mum about it, all the more as he finds out Alice has an affair with Gérard, Aldo''s former friend and ... new boss. However, Aldo, leading a double life, starts spending his money ...', '2002-11-27', 5.80, 'https://image.tmdb.org/t/p/w500/wK8P91PlbLqXi75AlzaxErd1e8q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18900, 'In Cold Blood', 'After a botched robbery results in the brutal murder of a rural family, two drifters elude police, in the end coming to terms with their own mortality and the repercussions of their vile atrocity.', '1967-12-15', 7.53, 'https://image.tmdb.org/t/p/w500/sPEvsif5Y70mfVvtU39iOyrVJdF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18823, 'Clash of the Titans', 'Born of a god but raised as a man, Perseus is helpless to save his family from Hades, vengeful god of the underworld. With nothing to lose, Perseus volunteers to lead a dangerous mission to defeat Hades before he can seize power from Zeus and unleash hell on earth. Battling unholy demons and fearsome beasts, Perseus and his warriors will only survive if Perseus accepts his power as a god, defies fate and creates his own destiny.', '2010-03-26', 5.92, 'https://image.tmdb.org/t/p/w500/6iHYLipwEyZUPNO8MM3l1yHDaFE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18904, 'A Summer Place', 'A self-made businessman rekindles a romance with a former flame while their two teenage children begin a romance of their own with drastic consequences for both couples.', '1959-11-18', 6.60, 'https://image.tmdb.org/t/p/w500/escHRIldvNphvBnxMcn6ybaJId0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18905, 'Caveman', 'Disgraced and cast out of his tribe for lusting after Lana, the mate of the tribe''s head muscle man, Atouk stumbles along gathering other misfits and learning a bit about the world outside of his cave. Eventually he and friends Lar and Tala learn the secrets of fire, cooked meat, and how to defend themselves from the brutal, yet very stupid dinosaurs.', '1981-04-17', 6.70, 'https://image.tmdb.org/t/p/w500/cfZfl3wxO8QxHKJsiWUHZg1D62B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18912, 'Angst', 'A killer is released from prison and breaks into a remote home to kill a woman, her handicapped son and her pretty daughter.', '1983-01-01', 7.07, 'https://image.tmdb.org/t/p/w500/nSYdWrPPwvcs5t5hG67XqDbwncG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
