INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18913, 'Betsy''s Wedding', 'Offbeat fashion student Betsy Hopper and her straight-laced investment-banker fiancé Jake Lovell just want an intimate little wedding reception, but Betsy''s father Eddie, a Long Island construction contractor, feels so threatened by Jake''s rich WASP parents that he blows the ceremony up into a bank-breaking showpiece, sending his wife Lola into a financial panic.', '1990-06-22', 5.71, 'https://image.tmdb.org/t/p/w500/qV2J2Fprk73ivclpL6JXPsBaCA5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18305, 'A Better Tomorrow II', 'A restauranteur teams up with a police officer and his ex-con brother to avenge the death of a friend''s daughter.', '1987-12-17', 7.10, 'https://image.tmdb.org/t/p/w500/e8352Dw1SeM4rNAGYDZVkQ0aenz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18923, 'A Home at the End of the World', 'Three friends form a bond over the year, Johnathan is gay, Clare is straight and Bobby is neither, instead he loves the people he loves. As their lives go on there is tension and tears which culminate in a strong yet fragile friendship between the three.', '2004-07-23', 6.41, 'https://image.tmdb.org/t/p/w500/o1YC1V30LR0LJzGR6JtbzpDSTYy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18919, 'Faust', 'A very free adaptation of Marlowe''s "Doctor Faustus", Goethe''s "Faust" and various other treatments of the old legend of the man who sold his soul to the devil. A nondescript man is lured by a strange map into a sinister puppet theatre, where he finds himself immersed in an indescribably weird version of the play, blending live actors, clay animation and giant puppets.', '1994-09-10', 7.42, 'https://image.tmdb.org/t/p/w500/pyCHHLEdRJPx0BD22n9Cs7B78Wp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18917, 'Alice', 'A quiet young English girl named Alice finds herself in an alternate version of her own reality after chasing a white rabbit. She becomes surrounded by living inanimate objects and stuffed dead animals, and must find a way out of this nightmare - no matter how twisted or odd that way must be.', '1988-08-03', 7.40, 'https://image.tmdb.org/t/p/w500/8o460rJZt7GY3j7QmLPeJrQWNwD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
