INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18835, 'Private School', 'Private-school student Christine loves Jim. But her classmate, Jordan, is also vying for Jim''s attention and trying to end his relationship with Christine. Meanwhile, Jim''s friend Bubba embarks on a series of sexual escapades, including dressing up as a woman to access the girls'' locker room. Despite Jim and Christine''s efforts to spend some time alone, various shenanigans and schemes interfere.', '1983-06-29', 5.67, 'https://image.tmdb.org/t/p/w500/hZLpmALf3LRUnCb0JI2ZRa9IR1F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
