INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18937, 'Quest for Camelot', 'During the times of King Arthur, Kayley is a brave girl who dreams of following her late father as a Knight of the Round Table. The evil Ruber wants to invade Camelot and take the throne of King Arthur, and Kayley has to stop him.', '1998-05-15', 6.84, 'https://image.tmdb.org/t/p/w500/pLfFEQ9HTw0HRvBkW3nI9RUze03.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18935, 'Ernest Goes to Camp', 'Ernest, a lovable loser who works as a summer camp handyman and dreams of becoming a guidance counselor, must find a way to inspire a group of juvenile delinquents while stopping a shady strip mining company from closing the camp as well.', '1987-05-22', 5.28, 'https://image.tmdb.org/t/p/w500/14GzgM3U2ABJ3h4ixhOkWpoQJAj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18947, 'The Boat That Rocked', 'When a group of rebellious deejays decides to defy the ban on government-censored music, they take to the seas to broadcast music and mayhem to millions of adoring fans.', '2009-04-01', 7.22, 'https://image.tmdb.org/t/p/w500/l7CBRLAXUnHi0kp2krhLtlJvtWI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18966, 'Love at First Bite', 'Dracula and Renfield relocate to ''70s era New York in search of Cindy Sondheim, the reincarnation of Dracula''s one true love, Mina Harker. "Trouble adjusting" is a wild understatement for the Count as he battles Cindy''s psychiatrist, Jeffrey Rosenberg, a descendant of Van Helsing, who may be in love with Cindy too.', '1979-04-26', 5.99, 'https://image.tmdb.org/t/p/w500/e4RDjX46zJ0sfh5wZW1rrKkezXJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18971, 'Rosencrantz & Guildenstern Are Dead', 'Rosencrantz and Guildenstern, minor characters from the play ''Hamlet'', find themselves on the road to Elsinore Castle at the behest of the King of Denmark. The duo encounter a band of players before arriving to find that they are needed to try to discern what troubles the prince Hamlet. Meanwhile, they ponder the meaning of their existence.', '1991-02-08', 6.89, 'https://image.tmdb.org/t/p/w500/6RI9sYpRxIdqlmsF6kBOiF7Bxug.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18978, 'Camelot', 'The plot of his illegitimate son Mordred to gain the throne, and Guinevere''s growing attachment to Sir Lancelot, threatens to topple King Arthur and destroy his "round table" of knights.', '1967-10-25', 6.23, 'https://image.tmdb.org/t/p/w500/1ohPMbfmQVg0Zzy9wkySm1w8Kr7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18975, 'The Adventures of Pinocchio', 'One of puppet-maker Geppetto''s creations comes magically to life. This puppet, Pinocchio, has one major desire and that is to become a real boy someday. In order to accomplish this goal he has to learn to act responsibly. This film shows you the adventures on which he learns valuable lessons.', '1996-07-26', 5.31, 'https://image.tmdb.org/t/p/w500/rGPFPkUmPam6arT22ey8jWpKzL2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18983, 'Godzilla, King of the Monsters!', 'During an assignment, foreign correspondent Steve Martin spends a layover in Tokyo and is caught amid the rampage of an unstoppable prehistoric monster the Japanese call ''Godzilla''. The only hope for both Japan and the world lies on a secret weapon, which may prove more destructive than the monster itself.', '1956-04-27', 6.50, 'https://image.tmdb.org/t/p/w500/19RDmhX6LtzMxv0KXXAU1IBIvvA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18984, 'Scratch', 'A feature-length documentary film about hip-hop DJing, otherwise known as turntablism. From the South Bronx in the 1970s to San Francisco now, the world''s best scratchers, beat-diggers, party-rockers, and producers wax poetic on beats, breaks, battles, and the infinite possibilities of vinyl.', '2001-11-07', 7.78, 'https://image.tmdb.org/t/p/w500/vXVou6iXTfxS8gbmQj8xNPcKefV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18987, 'The Hunchback of Notre Dame', 'In 15th century France, a gypsy girl is framed for murder by the infatuated Chief Justice, and only the deformed bellringer of Notre Dame Cathedral can save her.', '1923-09-06', 6.55, 'https://image.tmdb.org/t/p/w500/3oheTQrTuqS1jPUW6GOc65ZbM5u.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18988, 'The Lion in Winter', 'Christmas 1183, Angevin Empire: King Henry II plans to announce his successor to the throne. Jockeying for the crown, though, is complex. Henry has three sons and wants his boy Prince John to take over. Henry''s wife, Queen Eleanor, believes their son Prince Richard should be king. As family and various schemers gather for the holiday, each tries to make the indecisive king choose their option.', '1968-08-20', 7.37, 'https://image.tmdb.org/t/p/w500/yMgJnZADJObzfjA70ygXJkjnrFX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18995, 'D.O.A.', 'Frank Bigelow is about to die, and he knows it. The accountant has been poisoned and has only 24 hours before the lethal concoction kills him. Determined to find out who his murderer is, Frank, with the help of his assistant and girlfriend, Paula, begins to trace back over his last steps. As he frantically tries to unravel the mystery behind his own impending demise, his sleuthing leads him to a group of crooked businessmen and another murder.', '1949-12-23', 6.85, 'https://image.tmdb.org/t/p/w500/m7wZXWOt9XQKJT8r9pbAFo7jB46.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18998, 'Darkman II: The Return of Durant', 'Darkman and Durant return and they hate each other as much as ever. This time, Durant has plans to take over the city''s drug trade using high-tech weaponry. Darkman must step in and try to stop Durant once and for all.', '1995-07-11', 5.61, 'https://image.tmdb.org/t/p/w500/kEQ6FWjvDnIl6sK88LCDcTwwjWr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18555, 'Foxfire', 'The story of five teenage girls who form an unlikely bond after beating up a teacher who has sexually harassed them. They build a solid friendship but their wild ways begin to get out of control.', '1996-08-23', 6.00, 'https://image.tmdb.org/t/p/w500/ywrSScJT43HerqWPlMu8nigLFzg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18550, 'Fled', 'During a routine prison work detail, convict Piper is chained to Dodge, a cyberhacker, when gunfire breaks out. Apparently, the attack is related to stolen money that the Mafia is after, and some computer files that somebody wants desperately to bury. The pair, who don''t exactly enjoy each other''s company, escape and must work together if they are to reach Atlanta alive. Luckily, they meet a woman who may be willing to help them.', '1996-07-19', 5.73, 'https://image.tmdb.org/t/p/w500/5oGdTgWXCOKerrfdBxJrOlFyifL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18785, 'The Hangover', 'When three friends finally come to after a raucous night of bachelor-party revelry, they find a baby in the closet and a tiger in the bathroom. But they can''t seem to locate their best friend, Doug – who''s supposed to be tying the knot. Launching a frantic search for Doug, the trio perseveres through a nasty hangover to try to make it to the church on time.', '2009-06-02', 7.34, 'https://image.tmdb.org/t/p/w500/A0uS9rHR56FeBtpjVki16M5xxSW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18885, '3 Ninjas Kick Back', 'During a championship baseball match, the three brothers hear that their grandfather in Japan is in trouble, and head out to help him, conceding the match. When they arrive in Japan, they must use all their powers to defend him against his ancient enemy, who has returned to exact revenge.', '1994-02-25', 5.64, 'https://image.tmdb.org/t/p/w500/kXuh3c0DyvqSGo0DBatoemBwEtz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19067, 'The Duellists', 'In 1800, as Napoleon Bonaparte rises to power in France, a rivalry erupts between Armand and Gabriel, two lieutenants in the French Army, over a perceived insult. For over a decade, they engage in a series of duels amidst larger conflicts, including the failed French invasion of Russia in 1812, and shifts in the political and social systems of Europe.', '1977-08-31', 7.25, 'https://image.tmdb.org/t/p/w500/nqjMYlUXnmmO8Jqucow4nj9alE5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18839, 'Ghost in the Shell: Stand Alone Complex - The Laughing Man', 'The year is 2030 and six years have passed since a criminal known only as "The Laughing Man" swept through top medical nanotechnology firms committing acts of cyber-terrorism, kidnapping, and espionage leaving no known suspects. New information is revealed, as Section 9 enters the hunt for a suspect capable of unfathomable actions in this compilation of Stand Alone Complex content.', '2005-09-23', 7.67, 'https://image.tmdb.org/t/p/w500/vUWRz8C7mgMMxI1dZhwgumcVFjB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18890, 'We''re Back! A Dinosaur''s Story', 'Captain New Eyes travels back in time and feeds dinosaurs his Brain Grain cereal, which makes them intelligent and non-violent. They agree to go to the "Middle Future" in order to grant the wishes of children in New York City. They are to meet Dr. Bleeb of the Museum of Natural History, but get sidetracked with their new children friends and run into the Captain''s evil brother, Professor Screweyes.', '1993-11-24', 6.10, 'https://image.tmdb.org/t/p/w500/iyFmhYlioe3PDZjSKWtcIhu5R02.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18989, 'Moll Flanders', 'The daughter of a thief, young Moll is placed in the care of a nunnery after the execution of her mother. However, the actions of an abusive priest lead Moll to rebel as a teenager, escaping to the dangerous streets of London. Further misfortunes drive her to accept a job as a prostitute from the conniving Mrs. Allworthy. It is there that Moll first meets Hibble, who is working as Allworthy''s servant but takes a special interest in the young woman''s well-being. With his help, she retains hope for the future, ultimately falling in love with an unconventional artist who promises the possibility of romantic happiness.', '1996-06-14', 6.10, 'https://image.tmdb.org/t/p/w500/lHVpzsvjLU7qSCB8UWFqIAavSRu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19049, 'The Yearling', 'Jody convinces his parents to allow him to adopt a young deer, but what will happen if the deer misbehaves?', '1946-12-18', 6.67, 'https://image.tmdb.org/t/p/w500/4N8oYLpY82ev7waXz7zwu7Ph1o1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18570, 'Food, Inc.', 'Documentary filmmaker Robert Kenner examines how mammoth corporations have taken over all aspects of the food chain in the United States, from the farms where our food is grown to the chain restaurants and supermarkets where it''s sold. Narrated by author and activist Eric Schlosser, the film features interviews with average Americans about their dietary habits, commentary from food experts like Michael Pollan and unsettling footage shot inside large-scale animal processing plants.', '2008-09-07', 7.36, 'https://image.tmdb.org/t/p/w500/zdwN4o7OGAZGJw9T64lRAGTEP8b.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18990, 'The Mummy', 'One by one the archaeologists who discover the 4,000-year-old tomb of Princess Ananka are brutally murdered. Kharis, high priest in Egypt 40 centuries ago, has been brought to life by the power of the ancient gods and his sole purpose is to destroy those responsible for the desecration of the sacred tomb. But Isobel, wife of one of the explorers, resembles the beautiful princess, forcing the speechless and tormented monster to defy commands and abduct Isobel to an unknown fate.', '1959-08-01', 6.70, 'https://image.tmdb.org/t/p/w500/w3XEtgi8W9tuPQnLVFCPVxtweyC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18846, 'The Little Drummer Boy', 'After being kidnapped and escaping, young drummer boy Aaron searches for his camel and finds him in the Nativity of the Baby Jesus. Aaron gives Baby Jesus the only gift he has, a song on his drum.', '1968-12-19', 6.57, 'https://image.tmdb.org/t/p/w500/oqnVoHW2aCOIFVHUCSxcm1XWeh9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19103, 'As You Like It', 'Witty, playful and utterly magical, the story is a compelling romantic adventure in which Rosalind and Orlando''s celebrated courtship is played out against a backdrop of political rivalry, banishment and exile in the Forest of Arden - set in 19th-century Japan.', '2006-09-01', 5.80, 'https://image.tmdb.org/t/p/w500/628YkM5wHmunTdXANWgJEJYbFdf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19118, 'Let It Ride', 'An average kind of guy who has a slight problem with gambling goes to the track, and mystically, it seems as though he can''t lose, no matter how he bets; and he has an incredible day.', '1989-08-18', 6.31, 'https://image.tmdb.org/t/p/w500/t5sJfj99wACezWFz2jtHQplQkUM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19087, 'Ladybugs', 'To climb the corporate ladder to success, a businessman agrees to coach his company''s all-girl soccer team with the help of his secret weapon: his fiancee''s son.', '1992-03-27', 5.64, 'https://image.tmdb.org/t/p/w500/gC0DmdJu7rHaqYjyXeo8GLLJ2Oa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19120, 'Juliet of the Spirits', 'Middle-aged Giulietta grows suspicious of her husband, Giorgio, when his behavior grows increasingly questionable. One night when Giorgio initiates a seance amongst his friends, Giulietta gets in touch with spirits and learns more about herself and her painful past. Slightly skeptical, but intrigued, she visits a mystic who gives her more information -- and nudges her toward the realization that her husband is indeed a philanderer.', '1965-10-22', 7.21, 'https://image.tmdb.org/t/p/w500/NbN10moPWQiiIKDJsC7A3j4Mcy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19124, 'Blind Fury', 'A blind Vietnam vet, trained as a swordfighter, comes to America and helps to rescue the son of a fellow soldier.', '1989-08-17', 6.51, 'https://image.tmdb.org/t/p/w500/ufbA7v7b2xt85Cf1tocr69cwuCO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18573, 'House of Wax', 'A sculptor opens a wax museum to showcase the likenesses of famous historical figures, but quickly runs into trouble when his business partner demands the exhibits become more extreme in order to increase profits.', '1953-04-16', 6.90, 'https://image.tmdb.org/t/p/w500/5Di30K5NzAtYMjBSAABwgZHV0Ro.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18874, 'Ghost in the Shell: Stand Alone Complex - Solid State Society', 'The story takes place in the year 2034, two years after the events in Ghost in the Shell: S.A.C. 2nd GIG. Female cyborg Major Motoko Kusanagi has left Public Security Section 9, an elite counter-terrorist and anti-crime unit specializing in cyber-warfare, which has expanded to a team of 20 field operatives with Togusa acting as the field lead.', '2007-09-01', 7.48, 'https://image.tmdb.org/t/p/w500/tExdDYmxqv30rtf2dMkTAVpzORf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19042, 'All Dogs Go to Heaven 2', 'Charlie and Itchy return to Earth to find Gabriel''s Horn, but along the way meet up with a young boy named David, who ran away from home.', '1996-03-29', 6.03, 'https://image.tmdb.org/t/p/w500/kNmIJILOW9qF2F1Z0qOXkadaS50.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19133, 'The Big Bus', 'A nuclear-powered bus is making its maiden non-stop trip from New York to Denver. The journey is plagued by disasters due to the machinations of a mysterious group allied with the oil lobby. Will the down-on-his-luck driver, with a reputation for eating his passengers, be able to complete the journey?', '1976-06-23', 5.34, 'https://image.tmdb.org/t/p/w500/rcwW5YBEGvWPx8NBN5PxdvoYc0F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19137, 'After the Fox', 'A criminal mastermind sets up a phony film production as part of a plan to smuggle stolen gold.', '1966-09-08', 6.12, 'https://image.tmdb.org/t/p/w500/aw4jMLBfDU9NfFxb4GvbHrupQoS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19140, 'The Pride of the Yankees', 'The story of the life and career of the baseball hall of famer, Lou Gehrig.', '1942-07-14', 7.33, 'https://image.tmdb.org/t/p/w500/tbSMm0IAa5WgTcyoeUn7AKAViVY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19155, 'Before the Rain', 'The circularity of violence seen in a story that circles on itself. In Macedonia, during the war in Bosnia, Christians hunt an ethnic Albanian girl who may have murdered one of their own. A young monk who''s taken a vow of silence offers her protection. In London, a photographic editor who''s pregnant needs to talk it out with her estranged husband and chooses a toney restaurant.', '1994-06-09', 7.40, 'https://image.tmdb.org/t/p/w500/e8DEVsL3tm0llRESDJfkRRktino.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19150, 'The Crew', 'Four retired mobsters plan one last crime to save their retirement home.', '2000-08-21', 5.41, 'https://image.tmdb.org/t/p/w500/kdQOz5enVVz113zZQcuoqh3oACy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19176, 'The Cowboy Way', 'Two championship rodeo partners travel to New York to find their missing friend, Nacho Salazar who went missing there.', '1994-06-03', 5.70, 'https://image.tmdb.org/t/p/w500/5oBVSzbWD85zRCKIWm0KvhypUZU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19053, 'Valley Girl', 'Julie, a girl from the valley, meets Randy, a punk from the city. They are from different worlds and find love. Somehow they need to stay together in spite of her trendy, shallow friends.', '1983-04-08', 6.00, 'https://image.tmdb.org/t/p/w500/mQSrU9jerYSIOWeLBqFA1gcUU59.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19184, 'The Last Battle', 'The plot explores the devastation of civilization and issues of brutality, hostility and isolation. Pierre Jolivet stars as the main character (identified only as "The Man" in the end credits) who is menaced by "The Brute" (played by Jean Reno) on his journey through a world filled by people rendered nearly mute by some unknown incident.', '1983-04-06', 6.40, 'https://image.tmdb.org/t/p/w500/Ag3cM67YCiOIyc0MLVNnDZ0avf4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19185, 'Night of the Living Dead', 'A ragtag group barricade themselves in an old Pennsylvania farmhouse to remain safe from a horde of flesh-eating ghouls ravaging the Northeast.', '1990-10-19', 6.87, 'https://image.tmdb.org/t/p/w500/7WkSCClUvcAq8JNEp4pM4A9hiDU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19200, 'Shadows and Fog', 'With a serial strangler on the loose, a bookkeeper wanders around town searching for the vigilante group intent on catching the killer.', '1991-12-05', 6.71, 'https://image.tmdb.org/t/p/w500/6Ybi2u1TSOTpAocZAGJl2WThq11.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19209, 'White Water Summer', 'When the experienced guide Vic accompanies the city boy Alan and his three friends on their first wilderness experience, he not only hopes to teach the four boys lessons about the wilderness, but about themselves. Vic pushes them to the limit. Soon after alienating the boys, Vic finds himself in desperate need of help and must rely on his students in order to survive.', '1987-07-10', 6.16, 'https://image.tmdb.org/t/p/w500/jvoxMkXms4O490OlCNuJk4y7ZB4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19223, 'A Pure Formality', 'Famous writer Onoff is now a recluse. The Inspector is suspicious when Onoff is brought into the station one night, disoriented and suffering a kind of amnesia. In an isolated, rural police station, the Inspector tries to establish the events surrounding a killing, to reach a startling resolution.', '1994-05-15', 7.40, 'https://image.tmdb.org/t/p/w500/bAd56dYln4cgoJBa1r60cb9S5xR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19236, 'Santa Sangre', 'A former circus artist escapes from a mental hospital to rejoin his armless, cult leader mother, and is forced to enact brutal murders in her name.', '1989-11-24', 7.17, 'https://image.tmdb.org/t/p/w500/6VTra0NR4ygRnq3bD922I4rU0Mq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19186, 'The Parent Trap', 'Two identical twin sisters, separated at birth by their parents'' divorce, are reunited years later at a summer camp, where they scheme to bring their parents back together. The girls, one of whom has been living with their mother and the other with their father, switch places after camp and go to work on their plan, the first objective being to scare off a gold-digger pursuing their father.', '1961-05-13', 7.04, 'https://image.tmdb.org/t/p/w500/jaZFWy6ZAvQoMW2mo9xP5gx4URo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19254, 'Carry On Cabby', 'Speedee Taxis is a great success, which means its workaholic owner Charlie starts neglecting Peggy, his wife. Suddenly a fleet of rival taxis appears from nowhere and start pinching all the fares. The rivals are Glamcabs, and they have a secret weapon. All their drivers are very attractive women! Who''s behind Glamcabs? It''s open warfare and only one fleet can survive!', '1963-06-01', 6.42, 'https://image.tmdb.org/t/p/w500/3S9fkzkl3kqgnlZUvBF1SqYKVm0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19255, 'Away We Go', 'Verona and Burt have moved to Colorado to be close to Burt''s parents but, with Verona expecting their first child, Burt''s parents inexplicably decide to move to Belgium, now leaving them in a place they hate and without a support structure in place. They set off on a whirlwind tour of of disparate locations where they have friends or relatives, sampling not only different cities and climates but also different families. Along the way they realize that the journey is less about discovering where they want to live and more about figuring out what type of parents they want to be.', '2009-06-05', 6.67, 'https://image.tmdb.org/t/p/w500/zWxjopWXpnC1vSbnO7mw2URna22.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19259, 'Volunteers', 'After graduating from Yale in 1962, womanizing Lawrence flees a gambling debt that his rich dad won''t pay and takes his roomie''s place as a Peace Corps Volunteer in the Thai Golden Triangle with two other PCVs. Will he survive two years?', '1985-08-16', 5.55, 'https://image.tmdb.org/t/p/w500/tua28Wyv9uGBtPTBGCP7GsN3Znu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19265, 'Whatever Works', 'Whatever Works explores the relationship between a crotchety misanthrope, Boris and a naïve, impressionable young runaway from the south, Melody. When Melody''s uptight parents arrive in New York to rescue her, they are quickly drawn into wildly unexpected romantic entanglements. Everyone discovers that finding love is just a combination of lucky chance and appreciating the value of "whatever works."', '2009-06-19', 7.07, 'https://image.tmdb.org/t/p/w500/upIYOZbiutCBnvejGYaZlJxxKcs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19277, 'In Hell', 'A man must survive a prison where hardened criminals battle to the death for the warden''s entertainment.', '2003-11-24', 6.66, 'https://image.tmdb.org/t/p/w500/vE2fYcP07fbIHoouATNErRQuNrw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18889, 'Control Room', 'A chronicle which provides a rare window into the international perception of the Iraq War, courtesy of Al Jazeera, the Arab world''s most popular news outlet. Roundly criticized by Cabinet members and Pentagon officials for reporting with a pro-Iraqi bias, and strongly condemned for frequently airing civilian causalities as well as footage of American POWs, the station has revealed (and continues to show the world) everything about the Iraq War that the Bush administration did not want it to see.', '2004-01-22', 7.35, 'https://image.tmdb.org/t/p/w500/pm6Tvrh3XC2mOwwCB8AQWcpBg1K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19004, 'The Land Before Time III: The Time of the Great Giving', 'A huge meteorite has plunged into the Great Valley, cutting off the water supply and causing tension among the once-peaceful dinosaurs.  While the adults argue and turn against one another, Littlefoot and his friends venture out to find a new source of water, only to be constantly bullied by a trio of older dinosaurs. The journey becomes a fight for survival when the group is cornered by a pack of Velociraptors and trapped by a sudden wildfire.', '1995-03-16', 6.20, 'https://image.tmdb.org/t/p/w500/abcJUBDHi6hxibSgm2bxYK1wAZK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19064, 'Once Bitten', 'Mark wants to lose his virginity, but his girlfriend wants to wait. Unfortunately for both of them, a 400-year-old vampire Countess needs to turn a virgin into a vampire before Halloween in order to preserve her own youthful appearance, and when she finds Mark, she turns his life upside-down.', '1985-11-15', 5.80, 'https://image.tmdb.org/t/p/w500/eK3dxRrMQGpZ1kLD9wdyOI8urFZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19092, 'Above the Rim', 'Story of a promising high school basketball star and his relationships with two brothers, one a drug dealer and the other a former basketball star fallen on hard times and now employed as a security guard.', '1994-03-23', 7.07, 'https://image.tmdb.org/t/p/w500/56NFHuZXdgZbVxvCyYw92E5uLQa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18867, 'Half a Loaf of Kung Fu', 'A young daydreamer  assumes the identity of a dead martial arts hero and quickly finds himself caught up in a plot by several clans to steal famous martial arts artifacts being transported by an escort company.', '1978-06-30', 6.19, 'https://image.tmdb.org/t/p/w500/lH11m3LC8itFSTWzkS4xVYL6nB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19357, 'Summer Rental', 'Jack Chester, an overworked air traffic controller, takes his family on vacation to the beach. Things immediately start to go wrong for the Chesters, and steadily get worse. Jack ends up in a feud with a local yachtsman, and has to race him to regain his pride and family''s respect.', '1985-08-09', 6.11, 'https://image.tmdb.org/t/p/w500/kNkDCXB2JXGnaG3KwvzAAjmZiV8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19348, 'Girlfight', 'Diana Guzman, a troubled Brooklyn teenager, decides to channel her aggression by training to become a boxer, all while keeping it a secret from her father.', '2000-05-01', 6.54, 'https://image.tmdb.org/t/p/w500/ydHUoYtpZdkwxdroK1rWyEpJrLZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18892, 'Jawbreaker', 'When an exclusive clique of teenage socialites accidentally murder their best friend on the morning of her birthday, the three girls responsible conspire to hide the truth.', '1999-01-30', 6.40, 'https://image.tmdb.org/t/p/w500/7YrxXoG25hVCK4nYDHQv9YIk3Ye.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19100, 'Those Happy Days', 'Set in 1992, a manager Vincent has to run a children''s holiday camp for three weeks and to face the unexpected concerning the place, his colleagues, various problems linked to children about the rooms, trips, their belongings...', '2006-06-28', 7.35, 'https://image.tmdb.org/t/p/w500/hCBcTQPqNY0HzzCcnoem8NNgI6W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19051, 'The New Adventures of Pippi Longstocking', 'After her father''s ship is carried off by a sudden storm, the spunky Pippi Longstocking is stranded with her horse, Alfonso,and her pet monkey, Mr. Neilson, and takes up residence in the old family home, which is thought by neighborhood children to be haunted. Soon, two children, Tommy and his sister Anika, venture into the house only to meet up with Pippi. The three soon become friends and get into various adventures together, including cleaning the floor with scrubbing shoes, dodging the "splunks", going down a waterfall in barrels, and helping Pippi with the problem of having to go to an orphanage. Older children will probably get the most out of this movie.', '1988-03-01', 5.90, 'https://image.tmdb.org/t/p/w500/a9o3WEzGjr36YjqTnzuikxHvyET.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19286, 'Leprechaun 3', 'It was a normal night in Las Vegas, Nevada, all the lights were flashing brightly, until a man with one hand, one eye, and one leg walks into a pawn shop with a statue of a hideous looking Leprechaun. The owner claims it''s a good luck charm. The statue also wore a medallion around it''s neck. The careless pawn shop owner took off the medallion setting the Leprechaun free...', '1995-06-27', 5.83, 'https://image.tmdb.org/t/p/w500/z9NT2smK66pYOjBtmZuKFFTZ478.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19267, 'The Big Brawl', 'A young Asian American martial artist is forced to participate in a brutal formal street-fight competition.', '1980-08-18', 5.91, 'https://image.tmdb.org/t/p/w500/jFl2hmGWFX9mw0NvOOn08Zr8bn5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19076, 'The Affair of the Necklace', 'In pre-Revolutionary France, a young aristocratic woman left penniless by the political unrest in the country, must avenge her family''s fall from grace by scheming to steal a priceless necklace.', '2001-11-30', 5.62, 'https://image.tmdb.org/t/p/w500/uPgXAA5PzMCCWXYA3PsihgNkwht.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19382, 'Biloxi Blues', 'A Jewish teenager sets three goals: lose his virginity, become a writer, and survive World War II.', '1988-03-25', 6.27, 'https://image.tmdb.org/t/p/w500/vAhQegSNb0OYwBN2KbSr8GRSUsI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19082, 'No Direction Home: Bob Dylan', 'A chronicle of Bob Dylan''s strange evolution between 1961 and 1966 from folk singer to protest singer to "voice of a generation" to rock star.', '2005-07-21', 7.75, 'https://image.tmdb.org/t/p/w500/lqOo4nyRS56Goi8InZqLFKGEJR5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (18887, 'Darby O''Gill and the Little People', 'A wily old codger matches wits with the King of the Leprechauns and helps play matchmaker for his daughter and the strapping lad who has replaced him as caretaker.', '1959-06-24', 6.67, 'https://image.tmdb.org/t/p/w500/fvdCK9sIgbKHQJjpjhtF9Ev8ysj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19075, 'A Midsummer Night''s Dream', 'Four young people escape Athens to a forest where the king and queen of the fairies are quarreling, while meanwhile, a troupe of amateur actors rehearses a play. When the fairy Puck uses a magic flower to make people fall in love, the whole thing becomes a little bit confused...', '1935-10-09', 6.40, 'https://image.tmdb.org/t/p/w500/jIdjacF7a1KTSWcheNEo6qFEY8K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19324, 'Born in East L.A.', 'Rudy, an American of Hispanic descent, whose south-of-the-border looks show him no mercy during an immigration raid in a migrant worker factory. As his luck goes, he is caught with neither money nor his ID and is deported to Mexico - without speaking a word of Spanish!', '1987-08-21', 5.80, 'https://image.tmdb.org/t/p/w500/fkRqsMOCkSu7l3F3JIcgyqV69lW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19426, 'Nights of Cabiria', 'Rome, 1957. A woman, Cabiria, is robbed and left to drown by her boyfriend, Giorgio. Rescued, she resumes her life and tries her best to find happiness in a cynical world. Even when she thinks her struggles are over and she has found happiness and contentment, things may not be what they seem.', '1957-10-03', 7.96, 'https://image.tmdb.org/t/p/w500/xF4oCG3PLNbcrtPZbqB3BtkIbKg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19429, 'Absence of Malice', 'Megan Carter is a reporter duped into running an untrue story on Michael Gallagher, a suspected racketeer. He has an alibi for the time his crime was allegedly committed—but it involves an innocent party. When he tells Carter the truth and the newspaper runs it, tragedy follows, forcing Carter to face up to the responsibilities of her job when she is confronted by Gallagher.', '1981-11-19', 6.64, 'https://image.tmdb.org/t/p/w500/sEmQFj17MUEWyqU1xa6yQ0VW5CA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19433, 'Revolution OS', 'REVOLUTION OS tells the inside story of the hackers who rebelled against the proprietary software model and Microsoft to create GNU/Linux and the Open Source movement.', '2001-03-09', 6.97, 'https://image.tmdb.org/t/p/w500/h7oBhsEsiHUgZ1uflyqBafB6SoB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19457, 'The Yards', 'In the rail yards of Queens, contractors repair and rebuild the city''s subway cars. These contracts are lucrative, so graft and corruption are rife. When Leo Handler gets out of prison, he finds his aunt married to Frank Olchin, one of the big contractors; he''s battling with a minority-owned firm for contracts.', '2000-04-27', 6.24, 'https://image.tmdb.org/t/p/w500/AtwXtU8CDWvVADgOwRkOSRZFPWI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19460, 'Son of the Bride', 'At age 42, Rafael Belvedere is having a crisis. He lives in the shadow of his father, he feels guilty about rarely visiting his aging mother, his ex-wife says he doesn''t spend enough time with their daughter and he has yet to make a commitment to his girlfriend. At his lowest point, a minor heart attack reunites him with Juan Carlos, a childhood friend, who helps Rafael to reconstruct his past.', '2001-08-16', 7.49, 'https://image.tmdb.org/t/p/w500/zXInKuQ8FW18Ko8CtY9V30qhz1P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19483, 'It Came from Outer Space', 'Author and amateur astronomer John Putnam and schoolteacher Ellen Fields witness an enormous meteorite come down near a small town in Arizona. Putnam becomes a local object of scorn when, after examining the object up close, he announces that it is a spacecraft, and that it is inhabited...', '1953-06-05', 6.30, 'https://image.tmdb.org/t/p/w500/zPXff8iRma28YQFApfzuWadZXzP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19326, 'Jury Duty', 'When jobless Tommy Collins discovers that sequestered jurors earn free room and board as well as $5-a-day, he gets himself assigned to a jury in a murder trial. Once there, he does everything he can to prolong the trial and deliberations and make the sequestration more comfortable for himself.', '1995-04-12', 4.38, 'https://image.tmdb.org/t/p/w500/DbKQDPqBE4kCaePj4CHu6r3ZAb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19490, 'The Bishop''s Wife', 'An Episcopal Bishop, Henry Brougham, has been working for months on the plans for an elaborate new cathedral which he hopes will be paid for primarily by a wealthy, stubborn widow. He is losing sight of his family and of why he became a churchman in the first place. Enter Dudley, an angel sent to help him. Dudley does help everyone he meets, but not necessarily in the way they would have preferred. With the exception of Henry, everyone loves him, but Henry begins to believe that Dudley is there to replace him, both at work and in his family''s affections, as Christmas approaches.', '1947-12-25', 7.09, 'https://image.tmdb.org/t/p/w500/2sMpffmvoJlW7WBcvyHTPR9DEsj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19494, 'Nine to Five', 'Three female employees of a sexist, egotistical, lying, hypocritical bigot find a way to turn the tables on him.', '1980-12-18', 6.90, 'https://image.tmdb.org/t/p/w500/anGHRo1tAAVoa7juvAuxldAE4lL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19508, 'Garfield''s Pet Force', 'Nothing in the world can make Garfield get involved in anything besides eating, until the muscular super cat Garzooka comes crashing into Cartoon World from the Comic Book universe with terrifying news. Garfield summons up the willpower to join his superhero Garzooka in a fight to save their worlds.', '2009-09-11', 5.50, 'https://image.tmdb.org/t/p/w500/ylbBsF1WKI0RrxfX89QFqrBPYKu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19507, 'Neighbors', 'One man''s quiet suburban life takes a sickening lurch for the worse when a young couple move into the deserted house next door. From the word go it is obvious these are not the quiet professional types who *should* be living in such a nice street. As more and more unbelievable events unfold, our hero starts to question his own sanity... and those of his family.', '1981-12-18', 5.60, 'https://image.tmdb.org/t/p/w500/eJ9AU7JY4lbda7EeXA0ONncV5Dm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19513, 'Series 7', 'A reality TV program selects six contestants to participate in a free-for-all, no holds barred deathmatch, where they must skillfully outwit and kill each other in order to be the last person alive.', '2001-01-20', 6.30, 'https://image.tmdb.org/t/p/w500/85tuJxQdjQcec3DTMc9dxwlYYfi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19542, 'The Red Shoes', 'A fledgling ballerina falls in love with a brilliant composer, but the jealous head of the ballet company plots to drive them apart.', '1948-09-06', 7.98, 'https://image.tmdb.org/t/p/w500/vPvpBWFWDvEXuQBkoYgA6A89GVp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19552, 'The Scent of Green Papaya', '1950s Saigon through the eyes of Mui, a Vietnamese servant girl. At 10 years-old, Mui leaves her village to work for an affluent, troubled family. As she comes of age, Mui finds work in the household of a pianist she has admired since childhood, and finds their relationship growing in complexity.', '1993-06-08', 7.00, 'https://image.tmdb.org/t/p/w500/4Pqvx6cuzF2XQrHUrIPUBVXugc3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19274, 'Fearless Hyena', 'Lung is a talented fighter but prefers to spend his time loafing around and picking fights, despite orders from his grandfather not to fight. Unknown to him, a brutal general has been slaughtering all the people from his grandfather’s clan. When the general recognizes Lung’s style of kung fu during one of his street fights, he hunts down Lung’s grandfather and kills him.', '1979-02-17', 6.70, 'https://image.tmdb.org/t/p/w500/bmQR6gtoBJHUkgALLb1eGruKPll.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19556, 'Miss March', 'A young man awakens from a four-year coma to hear that his once virginal high-school sweetheart has since become a centerfold in one of the world''s most famous men''s magazines. He and his sex-crazed best friend decide to take a cross-country road trip in order to crash a party at the magazine''s legendary mansion headquarters and win back the girl.', '2009-03-13', 5.57, 'https://image.tmdb.org/t/p/w500/rJovsKIjVsSMuwURASoTZJB6jvI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19316, 'Saving Face', 'A Chinese-American lesbian and her traditionalist mother are reluctant to go public with secret loves that clash against cultural expectations.', '2004-09-12', 7.22, 'https://image.tmdb.org/t/p/w500/7XbbgkKi4nEMOu9iwiANXpjKKhe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19585, 'G-Force', 'A team of trained secret agent animals, guinea pigs Darwin, Hurley, Juarez, Blaster, mole Speckles, and fly Mooch takes on a mission for the US government to stop evil Leonard Saber, who plans to destroy the world with household appliances. But the government shuts them down and they are sentenced to a pet shop. Can they escape to defeat the villain and save the world?', '2009-07-24', 5.49, 'https://image.tmdb.org/t/p/w500/9Tly3ZXTTsQKM26fis8v9LR4GxG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19601, 'Bent', 'Max is a handsome young man who, after a fateful tryst with a German soldier, is forced to run for his life. Eventually Max is placed in a concentration camp where he pretends to be Jewish because in the eyes of the Nazis, gays are the lowest form of human being. But it takes a relationship with an openly gay prisoner to teach Max that without the love of another, life is not worth living.', '1997-11-26', 6.85, 'https://image.tmdb.org/t/p/w500/mTRIVPmRK01rgLlE6XJPGbbRdXb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19600, 'Bossa Nova', 'After a chance encounter on the elevator, the lives of Mary Ann, a widowed English teacher, and Pedro, a recently divorced man, intersect against the hot backdrop of Rio de Janeiro.', '2000-02-18', 5.50, 'https://image.tmdb.org/t/p/w500/zNOEUXsb3LMdBLDafaWYziLCQbO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19670, 'Golmaal – Fun Unlimited', 'Four runaway cons take shelter in a bungalow owned by an old blind couple.', '2006-07-14', 6.75, 'https://image.tmdb.org/t/p/w500/3ubefqLk26Gy0lXCfGIu8hQrBak.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19636, 'Garam Masala', 'Photographer and serial womaniser, Mac devises a scheme to keep three airhostesses, who are unaware of each other, as  his live-in partners. Everything works fine as long as they only come home every third day. But changing schedules, a jealous friend and his fiancé might just break apart his elaborately structured life of deceit.', '2005-11-03', 6.03, 'https://image.tmdb.org/t/p/w500/puk8ca4bL9HG1R8BwORif8bHGqY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19698, 'Porky''s II: The Next Day', 'When the students of Angel Beach High decide to stage "An Evening With Shakespeare," their efforts are threatened by Miss Balbricker, who views the works of Shakespeare as obscene. She enlists the help of Reverend Bubba Flavel, a religious fanatic who brings along his flock of followers to pressure the school into shutting down the production.', '1983-06-24', 5.68, 'https://image.tmdb.org/t/p/w500/rZjSlaXM8Ez91ZV39frILApGuKg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19414, 'Please Don''t Eat the Daisies', 'Drama critic Larry Mackay, his wife Kate and their four sons move from their crowded Manhattan apartment to an old house in the country. While housewife Kate settles into suburban life, Larry continues to enjoy the theater and party scene of New York.', '1960-03-31', 6.16, 'https://image.tmdb.org/t/p/w500/neSCV9m8R1ykTqicd53fdwQgQnJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19724, 'Imagine That', 'A financial executive who can''t stop his career downspiral is invited into his daughter''s imaginary world, where solutions to his problems await.', '2009-06-19', 5.97, 'https://image.tmdb.org/t/p/w500/lyCTP5C3raH46hJNS9WfBSnWHsG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19736, 'Baby: Secret of the Lost Legend', 'A paleontologist and her husband discover a mother and baby brontosaurus in Africa, and try to protect them from hunters who want to capture them.', '1985-03-29', 5.22, 'https://image.tmdb.org/t/p/w500/AvIT5XHXrxeNHxTHmyRalm7tfSM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19753, 'Start the Revolution Without Me', 'Two sets of identical twins are accidentally switched at birth. One pair, Phillipe and Pierre DeSisi, are aristocratic and haughty, while the other, Charles and Claude Coupé, are poor and dim-witted. On the eve of the French Revolution, both sets find themselves entangled in palace intrigue.', '1970-02-04', 6.00, 'https://image.tmdb.org/t/p/w500/z4gspFa639yUWLSyefP5yCxKgRi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19086, 'Delta Force 2: The Colombian Connection', 'When DEA agents are taken captive by a ruthless South American kingpin, the Delta Force is reunited to rescue them in this sequel to the 1986 film.', '1990-08-24', 5.63, 'https://image.tmdb.org/t/p/w500/9rBVHD1gYSx5bOwCgqSdljUXKY8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19345, 'Black Widow', 'Federal agent Alexandra Barnes believes that Catherine Petersen is a serial killer who marries rich men and then murders them for their money. But since Catherine is seemingly a master of disguise and has multiple identities, Alexandra can''t prove anything with conventional detective work. With no other option, she goes undercover, pursuing the same man as Catherine, and hoping that Catherine will slip up and reveal her true identity.', '1987-02-06', 6.18, 'https://image.tmdb.org/t/p/w500/iAlUN6XFuvSz1it58aH2cuEITrt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19287, 'Leprechaun 4: In Space', 'On a planet in a distant galaxy, a power hungry Leprechaun, holds a beautiful alien princess hostage in order to marry her for her royal title. With her title and his beloved gold, he''ll be able to rule the universe. While making his maniacal plans, what he doesn''t count on is an invading platoon of marines from Earth, to save the princess and foil his plans. An accomplished trickster, the Leprechaun stows himself away on the orbiting spaceship and wreaks havoc on the crew in an attempt to recapture his bride.', '1997-02-25', 4.59, 'https://image.tmdb.org/t/p/w500/2nt0095grCSepz6xU24a5yP5mwc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19625, 'Munna Bhai M.B.B.S.', 'A gangster sets out to fulfill his father''s dream of becoming a doctor.', '2003-12-19', 7.17, 'https://image.tmdb.org/t/p/w500/OjJ2eZFMr0InHxjYCQXwxDoo4v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19101, 'A Little Princess', 'When her father enlists to fight for the British in WWI, young Sara Crewe goes to New York to attend the same boarding school her late mother attended. She soon clashes with the severe headmistress, Miss Minchin, who attempts to stifle Sara''s creativity and sense of self-worth.', '1995-05-10', 7.63, 'https://image.tmdb.org/t/p/w500/9V4bAVEskSNbEqjVI0YmeuB0n8I.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19761, 'Saturn 3', 'In the future, Earth is overcrowded and the population relies on distant bases to be fed. In the Saturn 3 station, Major Adam and the scientist Alex, who is also his lover and has never been on Earth, have been researching hydroponics for three years in the base alone with their dog Sally.  Captain Benson arrives Saturn 3 with Hector, incapable to controlling his emotions he transfers his homicidal tendency and insanity to Hector.  Now Major Adam and Alex are trapped in the station with a dangerous psychopath robot.', '1980-02-15', 5.28, 'https://image.tmdb.org/t/p/w500/zAoLR1azwd8QbglnjWpOwJ4PI6C.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19760, 'Two If by Sea', 'Frank O''Brien, a petty thief, and his 7-year-long girlfriend Roz want to put an end to their unsteady lifestyle and just do that last job, which involves stealing a valuable painting. Frank takes Roz to an island on the coast of New England, where he wants to sell the painting and also hopes that their sagging relationship will get a positive push back up. Not everything goes as planned.', '1996-01-12', 5.01, 'https://image.tmdb.org/t/p/w500/xSfqAMYqrTtDeAjPtYo0S8nc5Zz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19662, 'The World of Henry Orient', 'A mischievous, adventuresome fourteen-year-old girl and her best friend begin following an eccentric concert pianist around New York City after she develops a crush on him.', '1964-03-19', 5.90, 'https://image.tmdb.org/t/p/w500/9FWPyQuLy1wsQfDwudM2tHamzBg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19366, 'Josie and the Pussycats', 'Josie, Melody and Val are three small-town girl musicians determined to take their rock band out of their garage and straight to the top, while remaining true to their look, style and sound. They get a record deal which brings fame and fortune but soon realize they are pawns of two people who want to control the youth of America. They must clear their names, even if it means losing fame and fortune.', '2001-04-06', 5.81, 'https://image.tmdb.org/t/p/w500/mHOix87RdBO3YQuyvFFZAZxpt5P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19762, 'Son of Flubber', 'Beleaguered professor Ned Brainard has already run into a pile of misfortunes with his discovery of the super-elastic substance "Flubber." Now he hopes to have better luck with a gravity-busting derivative he''s dubbed "Flubbergas." Ned''s experiments, constantly hampered by government obstruction, earn the consternation of his wife, Betsy. But a game-winning modification to a football uniform may help Ned make the case for his fantastic new invention.', '1963-01-16', 6.06, 'https://image.tmdb.org/t/p/w500/nP2V3il0SCAwu12SypdcTQggUBA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19901, 'Daybreakers', 'In the year 2019, a plague has transformed almost every human into a vampire. Faced with a dwindling blood supply, the fractured dominant race plots their survival; meanwhile, a researcher works with a covert band of vampires on a way to save humankind.', '2010-01-06', 6.28, 'https://image.tmdb.org/t/p/w500/xFZH2l9UOyIclk2ZFWNHQ38B2RP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19905, 'The Goods: Live Hard, Sell Hard', 'Don Ready is many things, but he is best-known as an extraordinary salesman. When a car dealership in Temecula teeters on the brink of bankruptcy, he and his ragtag team dive in to save the day. But what Ready doesn''t count on is falling in love and finding his soul.', '2009-05-29', 5.37, 'https://image.tmdb.org/t/p/w500/1nEd4aLuRlAPFqUdcCYekAAjWsn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19908, 'Zombieland', 'Columbus has made a habit of running from what scares him. Tallahassee doesn''t have fears. If he did, he''d kick their ever-living ass. In a world overrun by zombies, these two are perfectly evolved survivors. But now, they''re about to stare down the most terrifying prospect of all: each other.', '2009-10-02', 7.26, 'https://image.tmdb.org/t/p/w500/dUkAmAyPVqubSBNRjRqCgHggZcK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19912, 'The Final Destination', 'A horrifying premonition saves a young man and his friends from death during a racetrack accident but terrible fates await them nonetheless.', '2009-08-26', 5.61, 'https://image.tmdb.org/t/p/w500/5vxXrr1MqGsT4NNeRITpfDnl4Rq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19913, '(500) Days of Summer', 'Tom, greeting-card writer and hopeless romantic, is caught completely off-guard when his girlfriend, Summer, suddenly dumps him. He reflects on their 500 days together to try to figure out where their love affair went sour, and in doing so, Tom rediscovers his true passions in life.', '2009-07-17', 7.30, 'https://image.tmdb.org/t/p/w500/qXAuQ9hF30sQRsXf40OfRVl0MJZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19918, 'Spread', 'A gigolo must contend with the prospect that he has found true love.', '2009-01-16', 5.57, 'https://image.tmdb.org/t/p/w500/27iaV68VjKWQabPhnklWD1kCqb1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19833, 'In the Loop', 'The US President and the UK Prime Minister are planning on launching a war in the Middle East, but—behind the scenes—government officials and advisers are either promoting the war or are trying to prevent it.', '2009-01-22', 7.02, 'https://image.tmdb.org/t/p/w500/jL6txnziFSeEifQkqnPBtaPaiXU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19929, '9to5: Days in Porn', '9to5 - Days in Porn focuses on the people behind a controversial and multi-billion dollar industry "The Adult Entertainment industry". It depicts their stories, each one different, unadorned and authentic, without glorification or prejudice. It delivers deep insight into their personal lives - from glamorous to grotesque - strange, fascinating, offensive, absurd and sometimes funny moments all at once.', '2008-08-24', 5.79, 'https://image.tmdb.org/t/p/w500/vCcXRri6Rrb2nZ0eDXPU3JKrpaS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19931, 'The Joy Luck Club', 'Through a series of flashbacks, four Chinese women born in America and their respective mothers born in feudal China explore their pasts.', '1993-09-08', 7.16, 'https://image.tmdb.org/t/p/w500/s1Sk0hhVARNs7i9wqRHqbCriu8n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19933, 'The Brave Little Toaster', 'A group of dated appliances, finding themselves stranded in a summer home that their family had just sold, decide to seek out their eight year old ''master''.', '1987-07-09', 6.90, 'https://image.tmdb.org/t/p/w500/mEZcPMNRqTcotOZSttN5MtmJbu1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19375, 'Were the World Mine', 'If you had a love-potion, who would you make fall madly in love with you? Timothy, prone to escaping his dismal high school reality through dazzling musical daydreams, gets to answer that question in a very real way. After his eccentric teacher casts him as Puck in A Midsummer Night''s Dream, he stumbles upon a recipe hidden within the script to create the play''s magical, purple love-pansy.', '2008-06-24', 6.30, 'https://image.tmdb.org/t/p/w500/g59ynRRLSyBNpLul3pqd9o7WHWm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19946, 'A Man Called Blade', 'Maurizio Merli stars as a hatchet-wielding bounty hunter with a dark past and an even more desperate future. But when he disrupts the balance of power in a corrupt mining town, he unleashes a firestorm of brutality, betrayal and cold-blooded murder. Now, one man stalks a savage land where justice walks a razor and no bullets slice deeper than vengeance. He is A MAN CALLED BLADE.', '1977-08-13', 6.60, 'https://image.tmdb.org/t/p/w500/9hX2IlU9trlVThCV5fe0n3fBvcU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19952, 'Best Men', 'Four tuxedo clad men show up at a penitentiary to meet a friend who has just been released after three years in prison and is going straight from the jail to marry his girlfriend. En route to the wedding, one of the men asks to stop by a bank to pick up some cash. As it turns out, he is a wanted bank robber who uses Shakespeare passages during his robberies and thus has become known as "Hamlet". Soon all five men are caught up in the bank and involved in the robbery as they end up in a hostage situation. The hostage negotiator shows up who turns out to be Hamlet''s father.', '1997-10-17', 5.28, 'https://image.tmdb.org/t/p/w500/dDutboDhQeIGZ0VOMI8RkM7MWm3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19666, 'Lagaan: Once Upon a Time in India', 'The year is 1893 and India is under British occupation. In a small village, the tyrannical Captain Russell has imposed an unprecedented land tax on its citizens. Outraged, Bhuvan, a rebellious farmer, rallies the villagers to publicly oppose the tax. Russell offers a novel way to settle the dispute: he challenges Bhuvan and his men to a game of cricket, a sport completely foreign to India. If Bhuvan and his men can defeat Russell''s team, the tax will be repealed.', '2001-06-15', 7.27, 'https://image.tmdb.org/t/p/w500/yNX9lFRAFeNLNRIXdqZK9gYrYKa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19953, 'The Incredible Mr. Limpet', 'Milquetoast Henry Limpet experiences his fondest wish and is transformed into a fish. As a talking fish he assists the US Navy in hunting German submarines during World War II.', '1964-03-28', 6.20, 'https://image.tmdb.org/t/p/w500/j2xkRT5peEPQRocgtoUEpUtoin2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19955, 'I Do', 'Life is easy for 43-year-old Luis, a happy single guy, fulfilled in his job of star nose with a perfume creation company, cosseted by his mother and five sisters. It could have lasted for a whole life, but fed up with mollycoddling and helping him, his mother and sisters decide it''s time he got married, and the sooner the better!', '2006-11-01', 6.36, 'https://image.tmdb.org/t/p/w500/jfeJwdtZpsAR6ap9kSrBg7c3bSL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19958, 'The Year My Voice Broke', 'Set in 1962, a young prepubescent boy in rural Australia watches painfully as his best friend and first love blossoms into womanhood and falls for a thuggish rugby player, changing the lives of everyone involved.', '1987-10-15', 7.09, 'https://image.tmdb.org/t/p/w500/eThAKG78ypcpyZSysue7exgMuZS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19959, 'Surrogates', 'Set in a futuristic world where humans live in isolation and interact through surrogate robots, a cop is forced to leave his home for the first time in years in order to investigate the murders of others'' surrogates.', '2009-09-24', 6.16, 'https://image.tmdb.org/t/p/w500/v3Z0Hbl0oe57njrrIPh0fJPFoo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19962, 'Mike Bassett: England Manager', 'After England''s football (soccer) manager has a heart attack, Mike Bassett is hired as the new manager and promptly announces the team will win the World Cup.', '2001-09-28', 6.99, 'https://image.tmdb.org/t/p/w500/vfbWbgkF5jFOqytHIVnq2eH3Gy5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19963, 'Bernie', 'Bernie, a 30 years old orphan, decides to leave his orphanage and find his parents. After an investigation, he meets Marion, a young heroin addict and falls in love with her. He believes that his family was victim of a plot and this is why they deserted him.', '1996-11-27', 6.77, 'https://image.tmdb.org/t/p/w500/c5jNOFSbUttQZl4CesnpAe1LrPR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19971, 'The Little Girl Who Lives Down the Lane', '13-year-old Rynn Jacobs lives in a New England beach town. Whenever the landlady inquires after Rynn''s father, she claims that he''s not available. But when the landlady''s son, Frank, won''t leave Rynn alone, she teams up with a neighbor Mario to maintain the dark family secret that she''s been keeping to herself.', '1976-12-25', 7.02, 'https://image.tmdb.org/t/p/w500/qlH7atDoN2iOmq6pNsoFIlebhgA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19973, 'Comedian', 'A look at the work of two stand-up comics, Jerry Seinfeld and a lesser-known newcomer, detailing the effort and frustration behind putting together a successful act and career while living a life on the road.', '2002-10-11', 6.65, 'https://image.tmdb.org/t/p/w500/tktajWQ91P09zTV7HdefzeVw1UV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19975, 'Care Bears Movie II: A New Generation', 'True Heart Bear and Noble Heart Horse touch down on Earth to boost the spirits of some unhappy kids at summer camp. But the evil Dark Heart has other plans, and convinces one of the campers to help him capture the Care Bears.', '1986-03-21', 6.30, 'https://image.tmdb.org/t/p/w500/tFUCGJnLy1Idj8JKMQAsvZpL5a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20006, 'Pink Cadillac', 'A skip tracer helps out a bail-jumper after her child is kidnapped by a group of ethno-nationalist thugs, of which her husband is a member, going by the name of Birthright. The baby is taken as leverage because, although initially oblivious, she has their money!', '1989-05-26', 5.47, 'https://image.tmdb.org/t/p/w500/akIQcT3IErdrvK3r7JIktucXQsy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19997, 'Niagara', 'Rose Loomis and her older, gloomier husband, George, are vacationing at a cabin in Niagara Falls. The couple befriend Polly and Ray Cutler, who are honeymooning in the area. Polly begins to suspect that something is amiss between Rose and George, and her suspicions grow when she sees Rose in the arms of another man. While Ray initially thinks Polly is overreacting, things between George and Rose soon take a shockingly dark turn.', '1953-01-29', 6.80, 'https://image.tmdb.org/t/p/w500/wb9OBAiO3aUpY4UBkE07KscXSkA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20009, 'Slackers', 'Dave, Sam and Jeff are about to graduate from Holden University with honors in lying, cheating and scheming. The three roommates have proudly scammed their way through the last four years of college and now, during final exams, these big-men-on-campus are about to be busted by the most unlikely dude in school. Self-dubbed Cool Ethan, an ambitious nerd with a bad crush, enters their lives one day and everything begins to unravel.', '2002-02-01', 5.20, 'https://image.tmdb.org/t/p/w500/g3xn7tRnGxVwwKc2tge7nPssywQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20051, 'Dad''s Army', 'Dad''s Army was a 1971 feature film based on the BBC television sitcom Dad''s Army. Directed by Norman Cohen, it was filmed between series three and four and was based upon material from the early episodes of the television series. The film told the story of the Home Guard platoon''s formation and their subsequent endeavours at a training exercise.', '1971-03-12', 4.97, 'https://image.tmdb.org/t/p/w500/3vc6GWhFciyrL7JyAULko1nUdSu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19378, 'The Cat from Outer Space', 'A UFO is stranded on earth and impounded by the US government. Its pilot, a cat with a collar that gives it special powers, including the ability to communicate with humans, has eluded the authorities and seeks the help of a scientist in order to reclaim and repair his ship and get back home.', '1978-06-09', 5.96, 'https://image.tmdb.org/t/p/w500/jspJBPlYGuMlwLbSSo0hdgfbnY0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19819, 'Blue Chips', 'Pete Bell, a college basketball coach is under a lot of pressure. His team isn''t winning and he cannot attract new players. The stars of the future are secretly being paid by boosters. This practice is forbidden in the college game, but Pete is desperate and has pressures from all around.', '1994-02-18', 6.10, 'https://image.tmdb.org/t/p/w500/tO71i4Ob64tchCRBB5MoqonPKAF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19371, 'Mr. Nanny', 'A former pro-wrestler is hired to be the bodyguard/nanny for a couple of bratty kids whose inventor father is being stalked by a rival.', '1993-04-02', 5.14, 'https://image.tmdb.org/t/p/w500/gSRSvh9kSEgCOsPR7yrH0ueh4lC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19840, 'I Love You, Beth Cooper', 'A valedictorian''s declaration of love for a high-school cheerleader launches a night of revelry, reflection and romance for a group of graduating seniors.', '2009-07-10', 6.01, 'https://image.tmdb.org/t/p/w500/mUi6nEbo04DR1YwflbZX1RR7UwS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19765, 'Zelary', 'A nurse and her surgeon-lover are part of a resistance movement in 1940s Czechoslovakia. When they are discovered, her lover flees and she must find a place to hide. A patient whose life she saved, a man from a remote mountain village where time stopped 150 years ago, agrees to hide her as his wife.', '2003-09-04', 6.98, 'https://image.tmdb.org/t/p/w500/s4jFr3bnf8d5WYCSrf0N3e7G9ez.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19994, 'Jennifer''s Body', 'Jennifer, a gorgeous, seductive cheerleader takes evil to a whole new level after she''s possessed by a sinister demon. Now it''s up to her best friend to stop Jennifer''s reign of terror before it''s too late.', '2009-09-18', 6.00, 'https://image.tmdb.org/t/p/w500/wrkjsGcFJxcQqR56kJUYAEKKg2T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20043, 'Royal Space Force - The Wings of Honneamise', 'On a future Earth, war between the Kingdom of Honneamise and its rival, The Republic, is inevitable. As evolving technology creates new ways to wage war, a small group seeks to propel mankind into space in their world’s first spaceflight program. For astronaut candidate Shirotsugh Lhadatt, it’s a personal odyssey as he grows from an aimless young man into a leader willing to put everything on the line in order to move the human race forward and away from the brink of Armageddon.', '1987-03-14', 6.88, 'https://image.tmdb.org/t/p/w500/h5naABij9ghj6CLcpBYBkxMGYGX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19855, 'The War', 'The son of a Vietnam War Veteran must deal with neighborhood bullies as well as his dad''s post-traumatic stress disorder while growing up in the deep south in the 1970''s.', '1994-11-04', 6.65, 'https://image.tmdb.org/t/p/w500/eMJYqr5zs7rz54oZhiX4ez1BI5E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19380, 'White Sands', 'A small southwestern town sheriff finds a body in the desert with a suitcase and $500,000. He impersonates the man and stumbles into an FBI investigation.', '1992-04-24', 5.87, 'https://image.tmdb.org/t/p/w500/jeOkfby3MMawUbZqBj7el4UePno.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19848, 'The Players Club', 'Single mother Diana struggles to provide for her child and pay for her college education. When she meets two dancers from a nearby gentlemen''s club, Diana''s convinced there''s fast money to be made stripping.', '1998-04-08', 6.40, 'https://image.tmdb.org/t/p/w500/8Y0ipbrZ6oiXffZkI1D9eahVsZ1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19379, 'Condorman', 'Comic artist and writer Woody performs a simple courier operation for his friend Harry who works for the CIA. But when he successfully fends off hostile agents, he earns the respect of the beautiful Natalia, who requests his assistance for her defection. Woody uses this request as leverage to use the CIA''s resources to bring his comic book creation, Condorman, to life to battle the evil Krokov.', '1981-07-02', 5.51, 'https://image.tmdb.org/t/p/w500/wRe9kAvjN5IGAjPd0oCKhjyQDt0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19381, 'Strike!', 'In 1963 New England, a group of friends at an all-girls academy learn that they''re going to be combined with a nearby all-boys institution. They concoct a plan to save their school while dealing with everyday problems along the way.', '1998-08-21', 6.40, 'https://image.tmdb.org/t/p/w500/cCr8mLqIVkbjBNs1uaZPvkXYnWA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20096, 'The Butcher''s Wife', 'A clairvoyant woman thinks that she''s met her future husband because she''s seen him in a dream. They marry and he takes her back to his butcher shop in New York city, where her powers tend to influence everyone she meets while working in the shop. Through her advice, she helps others and eventually finds the true man of her dreams.', '1991-10-25', 5.68, 'https://image.tmdb.org/t/p/w500/oKwvnb2bypMyXD2UraWdXxUoqLY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20178, 'World''s Greatest Dad', 'In the wake of a freak accident, Lance suffers the worst tragedy and the greatest opportunity of his life. He is suddenly faced with the possibility of fame, fortune and popularity, if he can only live with the knowledge of how he got there.', '2009-08-20', 6.60, 'https://image.tmdb.org/t/p/w500/1ESsZLvZPIvbCPCh7CPCSnF4EeH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20173, 'The Barefoot Executive', 'In the great Disney tradition of wild family fun, a young Kurt Russell stars as Steven Post - an ambitious mailroom clerk at a second-rate TV network. With his eye on the boardroom, and getting nowhere with the studio''s top dog, he makes a career-changing discovery. His girlfriend''s lovable pet chimp can pick a hit show every time! His secret for success turns into a madcap monkey business when he makes vice president and jealous rivals want in on the act. Ride along with narrow escapes and a classic cast featuring Joe Flynn and Harry Morgan in a comedic climb up the corporate ladder that will leave you howling for more!', '1971-03-17', 5.55, 'https://image.tmdb.org/t/p/w500/l80GlJCOFM6rE2uwiW0EMD6jAPd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20210, 'Grind', 'Four skaters follow their idol on his summer tour in an attempt to get noticed, get sponsored, and become stars themselves.', '2003-08-15', 6.00, 'https://image.tmdb.org/t/p/w500/3ijvfbWQYLaFQ2PaX6hywnMW3Hv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20211, 'Robin Williams: Live on Broadway', '2002 HBO Stand-up Special starring Robin Williams. Recorded and broadcast live from New York City''s Broadway Theater at the culmination of his historic 2002 sold-out tour, this special finds the Oscar-winning actor/writer/comedian returning after 16 years to his stand-up roots to deliver what the Washington Post calls "...in its madcap way, a seminal cultural event."', '2002-07-14', 7.80, 'https://image.tmdb.org/t/p/w500/omCkeQubfAtjJetFV2edOC3yhRB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20239, 'Fear of a Black Hat', 'Chronicling the controversial career of bad boys N.W.H. (Niggaz With Hats), this uproarious ''mockumentary'' lampoons all of hardcore rap''s hot-button issues. This underground laugh riot recounts the rise, fall and resurrection of a clueless bunch of would-be rappers, Ice Cold, Tone-Def & Tasty Taste performing as N.W.H.', '1994-06-03', 6.10, 'https://image.tmdb.org/t/p/w500/4goFB3XTrh4sKumpXkvbdlZZAo8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20242, 'Outrageous Fortune', 'Refined actress Lauren Ames finally has a chance to study with the great theatre professor Stanislav Korzenowski. Sandy Brozinsky, a brash, loud actress, decides through happenstance to also study with Korzenowski. The two women end up dating the same man (who turns out to be a double agent) and follow him across the country to force him to choose between them.', '1987-01-30', 6.04, 'https://image.tmdb.org/t/p/w500/bZdQaa9HymxGfjBo3mFhhpWXVeG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20246, 'The Stranger', 'An investigator from the War Crimes Commission travels to Connecticut to find an infamous Nazi, who may be hiding out in a small town in the guise of a distinguished professor engaged to the Supreme Court Justice’s daughter.', '1946-06-02', 7.21, 'https://image.tmdb.org/t/p/w500/bzjoPScBLUWpSu10m3GbSbSwVhS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20271, 'Divorce Italian Style', 'Ferdinando Cefalù is desperate to marry his cousin, Angela, but he is married to Rosalia and divorce is illegal in Italy. To get around the law, he tries to trick his wife into having an affair so he can catch her and murder her, as he knows he would be given a light sentence for killing an adulterous woman. He persuades a painter to lure his wife into an affair, but Rosalia proves to be more faithful than he expected.', '1961-12-20', 7.88, 'https://image.tmdb.org/t/p/w500/vZbdSpUFyFiDBBTY0AiSrN9f303.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19419, 'Screwed', 'A chauffeur kidnaps his rich boss''s dog to hold it for ransom, but when she accidentally gets the dog back, she thinks that it''s the chauffeur who''s been kidnapped.', '2000-05-12', 5.47, 'https://image.tmdb.org/t/p/w500/m6FfMbH1ga1Kp5QI9Nm0ETOIG64.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20283, 'Breaking Away', 'Dave, nineteen, has just graduated high school, with his three friends: the comical Cyril, the warm hearted but short-tempered Moocher, and the athletic, spiteful but good-hearted Mike. Now, Dave enjoys racing bikes and hopes to race the Italians one day, and even takes up the Italian culture, much to his friends'' and parents'' annoyance.', '1979-05-24', 7.15, 'https://image.tmdb.org/t/p/w500/k7b5GsVJK1hfdwoYqcczN9pBba6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20289, 'Rush', 'Undercover cop Jim Raynor is a seasoned veteran. His partner, Kristen Cates, is lacking in experience, but he thinks she''s tough enough to work his next case with him: a deep cover assignment to bring down the notoriously hard-to-capture drug lord Gaines. While their relationship turns romantic during the assignment, they also turn into junkies, and will have to battle their own addictions if they want to bring down Gaines once and for all.', '1991-12-22', 6.63, 'https://image.tmdb.org/t/p/w500/mYRGsAFhvPmH8umMhsO8EJmhLQX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20304, 'Never Die Alone', 'A drug kingpin''s rise and tragic fall is witnessed vicariously by a reporter who uses the criminal''s diary as the basis for his new book.', '2004-03-26', 5.49, 'https://image.tmdb.org/t/p/w500/nLN6zs2ySlekfdXS7mZ6uujTSBi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20303, 'Life and Debt', 'Life and Debt is a 2001 American documentary film that examines the economic and social situation in Jamaica, and specifically how the International Monetary Fund and the World Bank''s structural adjustment policies have impacted the island.', '2001-04-22', 7.32, 'https://image.tmdb.org/t/p/w500/5IYvqrrDRtEUiGS8M6w1GxGDdrM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20306, 'Swimming with Sharks', 'Guy is a young film executive who''s willing to do whatever it takes to make it in Hollywood. He begins working for famed producer Buddy Ackerman, a domineering, manipulative, coldhearted boss. When Guy also finds out that his cynical girlfriend, Dawn, has been using sex as a career move, he reaches his limit. Guy decides to exact revenge on Buddy by kidnapping him and subjecting him to cruel and unusual punishment.', '1994-09-10', 6.62, 'https://image.tmdb.org/t/p/w500/eMRiIJIEyMLjWjktIqjNfzs9jGX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20309, 'Say It Isn''t So', 'Boy meets girl; boy falls in love (and had wild, non-stop sex) with girl; boy loses girl... when they discover they are brother and sister! But when he learns that he''s the victim of the ultimate case of mistaken identity, the lovesick young man -- whom everyone still thinks is after some taboo thrills -- must race across the country to stop her from marrying another man.', '2001-03-10', 4.74, 'https://image.tmdb.org/t/p/w500/gHEI41EWj9dEscfEiKgw6a2uUez.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20024, 'The End of the Affair', 'On a rainy London night in 1946, novelist Maurice Bendrix has a chance meeting with Henry Miles, husband of his ex-mistress Sarah, who abruptly ended their affair two years before. Bendrix''s obsession with Sarah is rekindled; he succumbs to his own jealousy and arranges to have her followed.', '1999-12-03', 6.57, 'https://image.tmdb.org/t/p/w500/xTp5cyp6qG0YTdI4AEz4ytjODOQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20312, 'Interstate 60', 'An aspiring painter meets various characters and learns valuable lessons while traveling across America.', '2002-04-13', 7.39, 'https://image.tmdb.org/t/p/w500/zZQt29qBWLoVVOo8HEFzFYRAgYQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20318, 'Mother Night', 'An American spy behind the lines during WWII serves as a Nazi propagandist, a role he cannot escape in his future life as he can never reveal his real role in the war.', '1996-11-01', 6.64, 'https://image.tmdb.org/t/p/w500/cJtOHLb96rcLjgLS4FM9fqEKcd6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20324, 'The Importance of Being Earnest', 'Two young gentlemen living in 1890s England use the same pseudonym (''Ernest'') on the sly, which is fine until they both fall in love with women using that name, which leads to a comedy of mistaken identities.', '1952-06-02', 7.21, 'https://image.tmdb.org/t/p/w500/ahHp1nOjLTWBdLCofxjLYMVqqgs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20325, 'Swing Time', 'Lucky is tricked into missing his own wedding to Margaret and has to make $25,000 so her father will allow him to marry her. He and business partner Pop go to New York where they run into dancing instructor Penny. She and Lucky form a successful dance partnership, but romance is blighted by his old attachment to Margaret and hers for Ricky.', '1936-08-28', 6.85, 'https://image.tmdb.org/t/p/w500/3iukS0hzUAmhwHdqWrgQuKwMnJY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20334, 'The Shop Around the Corner', 'Two employees at a gift shop can barely stand one another, without realising that they are falling in love through the post as each other''s anonymous pen pal.', '1940-01-12', 8.05, 'https://image.tmdb.org/t/p/w500/dZ1aEzGYRiqJwPfjS6VL7wUkHmF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20337, 'Martin Lawrence Live: Runteldat', 'The controversial bad-boy of comedy delivers a piercing look at his life, lifting the metaphorical smokescreen that he feels has clouded the public view, commenting on everything from the dangers of smoking to the trials of relationships, and unleashing a nonstop litany of raucous anecdotes, stinging social commentary and very personal reflections about life.', '2002-08-02', 5.29, 'https://image.tmdb.org/t/p/w500/fRpS1sr1GFPgQobsXoNm5lxatcy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20345, 'The Bird with the Crystal Plumage', 'An American writer living in Rome witnesses an attempted murder that is connected to an ongoing killing spree in the city and conducts his own investigation, despite him and his girlfriend being targeted by the killer.', '1970-02-27', 7.14, 'https://image.tmdb.org/t/p/w500/dpALRkwodEIT7TGX9SqTgwVNn0i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20348, 'Fandango', 'In 1971, five college buddies from the University of Texas embark on a final road trip odyssey across the Mexican border before facing up to uncertain futures, in Vietnam and otherwise.', '1985-01-25', 6.69, 'https://image.tmdb.org/t/p/w500/7hdQUp17uXp8tZJWB8eWh25DWbc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20352, 'Despicable Me', 'Determined to prove he''s the world''s greatest supervillain, Gru hatches an audacious plan to steal the Moon. To pull it off, he adopts three orphaned girls—Margo, Edith, and Agnes—intending to use them as pawns in his scheme. But the unexpected bond they form forces him to question the criminal life he''s always known.', '2010-07-08', 7.26, 'https://image.tmdb.org/t/p/w500/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19405, 'Recess: School''s Out', 'The school year is finally ending, and T.J. Detweiler is looking forward to summer. But boredom quickly sets in when his friends leave for camp — until T.J. uncovers an evil plot to do away with summer vacation! A crazy former principal, Dr. Benedict, is planning to use a laser beam to alter the weather and create permanent winter. Faced with the dire threat of year-round school, T.J. rounds up the RECESS gang and bands together with some unexpected allies — Miss Finster and Principal Prickly — in a nonstop adventure to save everyone''s summer break.', '2001-02-16', 6.58, 'https://image.tmdb.org/t/p/w500/qsUCoeTwCNIrvDrUiWlTCgyRFZy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20359, 'Phir Hera Pheri', 'Raju,  Shyam and Baburao are living happily after having risen from rags to riches. However, they lose it all after falling victim to a chit fund scam due to their greed for more money. Soon, they find themselves in new mess and encounter eccentric and dangerous characters in their quest for a shortcut to riches again.', '2006-06-09', 6.91, 'https://image.tmdb.org/t/p/w500/c1Mvyd983ZyrU5Vf2aKEe6WncSq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20367, 'Detour', 'The life of Al Roberts, a pianist in a New York nightclub, turns into a nightmare when he decides to hitchhike to Los Angeles to visit his girlfriend.', '1945-11-30', 7.22, 'https://image.tmdb.org/t/p/w500/gJb9HRAs1V4bA0VKsWpT6mhv2RT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20408, 'Terror by Night', 'Holmes and Watson board a passenger train bound from London to Edinburgh, to guard the Star of Rhodesia, an enormous diamond worth a fortune belonging to an elderly woman of wealth; but within the first hour of the trip, the woman''s son is murdered and the diamond stolen and any of the passengers in their car could be the killer thief.', '1946-02-01', 6.58, 'https://image.tmdb.org/t/p/w500/cjGgLJ2GViKy0bla8OfaAhOBAJw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20417, 'Dressed to Kill', 'A convicted thief in Dartmoor prison hides the location of the stolen Bank of England printing plates inside three music boxes. When the innocent purchasers of the boxes start to be murdered, Holmes and Watson investigate.', '1946-05-24', 6.60, 'https://image.tmdb.org/t/p/w500/oD4z3ON2ciLMv6obEH2K8tGThWG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20048, 'Confessions of a Shopaholic', 'In the glamorous world of New York City, Rebecca Bloomwood is a fun-loving girl who is really good at shopping – a little too good, perhaps. She dreams of working for her favorite fashion magazine, but can''t quite get her foot in the door – until ironically, she snags a job as an advice columnist for a financial magazine published by the same company.', '2009-02-05', 6.49, 'https://image.tmdb.org/t/p/w500/r17R9OIC0pKDqqsNore6atYLCVZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19884, 'The Sword of Doom', 'Ryunosuke, a gifted swordsman plying his trade during the turbulent final days of Shogunate rule, has no moral code and kills without remorse. It’s a way of life that leads to madness.', '1966-02-25', 7.75, 'https://image.tmdb.org/t/p/w500/yjHbIihqpuAXlZVoPbWdqaukllB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19898, 'Pandorum', 'Two crew members wake up on an abandoned spacecraft with no idea who they are, how long they''ve been asleep, or what their mission is. The two soon discover they''re actually not alone – and the reality of their situation is more horrifying than they could have imagined.', '2009-09-08', 6.61, 'https://image.tmdb.org/t/p/w500/mNMfa6r3pl0EzFIKEkVcxyr6Rc7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20107, 'Bart Got a Room', 'High school loser Danny Stein needs a prom date. As a cause of anxiety for Danny, Bart Beeber, the nerdiest guy in school, has already found a date. At the same time, Danny''s divorced parents are both seeking relationships again.', '2008-04-25', 5.66, 'https://image.tmdb.org/t/p/w500/ihPJgIvFxPiDfNdTj7kNhroT8Db.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (19899, 'Couples Retreat', 'Four couples, all friends, descend on a tropical island resort. Though one husband and wife are there to work on their marriage, the others just want to enjoy some fun in the sun. They soon find, however, that paradise comes at a price: Participation in couples therapy sessions is mandatory. What started out as a cut-rate vacation turns into an examination of the common problems many face.', '2009-09-19', 5.56, 'https://image.tmdb.org/t/p/w500/igXVSRZsNX3TZsKrQqSyEJvzHRF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20108, 'Au Hasard Balthazar', 'The story of a donkey Balthazar as he is passed from owner to owner, some kind and some cruel but all with motivations beyond his understanding. Balthazar, whose life parallels that of his first keeper, Marie, is truly a beast of burden, suffering the sins of humankind. But despite his powerlessness, he accepts his fate nobly.', '1966-05-25', 7.55, 'https://image.tmdb.org/t/p/w500/lkLO1HDzzaXpTXtAgnGpVqIQkvF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20120, 'Bill Cosby: Himself', 'A 1983 stand-up comedy film featuring the comedy of Bill Cosby. Filmed before a live audience at the Hamilton Place Theatre, in Hamilton, Ontario. Cosby gives his comedic views on people who drink too much and take drugs, going to the dentist, marriage and parenthood.', '1983-05-20', 7.59, 'https://image.tmdb.org/t/p/w500/t685Vbw4q2PxgnrlBFpgZO607D0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20067, 'Things You Can Tell Just by Looking at Her', 'In California, a group of women struggle with personal problems as their paths intertwine in unexpected ways. Dr. Elaine Keener, the sole caretaker for her aging mother, turns to tarot card reader Christine for spiritual aid. Christine grapples with her own angst due to her lover''s debilitating illness. Meanwhile, a bank manager deals with an unwanted pregnancy, two sisters pursue romantic interests and a housewife gets back into the dating game.', '2000-05-27', 5.81, 'https://image.tmdb.org/t/p/w500/vTeEzAj0Uv8ySwdh894tEGvSh4s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20115, 'Opera', 'A young opera singer is stalked by a deranged fan bent on killing the people associated with her to claim her for himself.', '1987-12-19', 6.75, 'https://image.tmdb.org/t/p/w500/v5VBvSVu2sWLAmyQhKQwBV5aPJA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20455, 'Digimon: The Movie', 'When a powerful new Internet Digimon hatches and begins to consume data at an alarming rate, the Digidestined - kids chosen to save the digital world - must put an end to the destruction before the damage becomes irreversible and worldwide communication halts forever. As computer-based missiles are launched, and a wayward Digimon kidnaps the Digidestined, only the combined efforts of a worldwide network of kids and a new group of "Digidestined" can rescue the others and stop global disaster.', '2000-10-06', 6.49, 'https://image.tmdb.org/t/p/w500/tiH1muonzAWzlLjPhjAcAYVAjzm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20391, 'Paint Your Wagon', 'A Michigan farmer and a prospector form a partnership in the California gold country. Their adventures include buying and sharing a wife, hijacking a stage, kidnapping six prostitutes, and turning their mining camp into a boom town. Along the way there is plenty of drinking, gambling, and singing. They even find time to do some creative gold mining.', '1969-10-15', 6.31, 'https://image.tmdb.org/t/p/w500/fwnYGuba3ZSM2bXwBZZs4DqqKTl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20421, 'Rock-A-Doodle', 'Chanticleer is a foolhardy farm rooster who believes his crows can actually make the sun come up and shine. When the sun rises one morning without Chanticleer''s crow, he leaves the farm in disgrace and runs off to become a rock ''n'' roll singer. But in his absence, a sinister, sunshine-hating owl prepares to take over.', '1991-08-02', 6.21, 'https://image.tmdb.org/t/p/w500/q5xSS8MNmrwR3em6VB6OC3992d6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20423, 'For All Mankind', 'A testament to NASA''s Apollo program of the 1960s and ''70s. Composed of actual NASA footage of the missions and astronaut interviews, the documentary offers the viewpoint of the individuals who braved the remarkable journey to the moon and back.', '1989-11-01', 7.78, 'https://image.tmdb.org/t/p/w500/7k8ylisWiEGxdRSlAf6v4PWiAjH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20536, '61*', 'In 1961, Roger Maris and Mickey Mantle played for the New York Yankees. One, Mantle, was universally loved, while the other, Maris, was universally hated. Both men started off with a bang, and both were nearing Babe Ruth''s 60 home run record. Which man would reach it?', '2001-04-28', 6.97, 'https://image.tmdb.org/t/p/w500/hAbxkPCC8pWYZy4kcftS3H3oku7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20539, 'The Crucible', 'A Salem resident attempts to frame her ex-lover''s wife for being a witch in the middle of the 1692 witchcraft trials.', '1996-11-27', 6.57, 'https://image.tmdb.org/t/p/w500/zv69Rev43me5gQ68x7fk1mQzhHn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20123, 'Time of the Gypsies', 'Perhan is a gypsy teenager with telekinetic powers. A wealthy gypsy, Ahmed, visits the village and promises to get Perhan''s sister the medical treatment she needs if they join him to Italy. Perhan soon discovers that Ahmed''s business activities are in fact quite shady and he is soon lured into the elder''s corrupt surroundings.', '1988-12-21', 7.63, 'https://image.tmdb.org/t/p/w500/fF9kWNMjiXC6f4YrdVFA0ScnWgQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20553, '21 Up', 'After another 7 year wait, director Michael Apted revisits the same group of British-born children from Seven Up! and 7 Plus Seven. The subjects are interviewed as to the changes that have occurred in their lives during the last seven years.', '1977-05-09', 7.40, 'https://image.tmdb.org/t/p/w500/2T8mH3V4X428zCipN928ZsRkK7N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20540, 'The Pawnbroker', 'A Jewish pawnbroker, a victim of Nazi persecution, loses all faith in his fellow man until he realizes too late the tragedy of his actions.', '1965-04-20', 7.12, 'https://image.tmdb.org/t/p/w500/o4CT5WPqmOLF2QfodAuGT7jQNn1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20457, 'The Matchmaker', 'Marcy, a worker in the reelection campaign of bumbling Senator John McGlory, is sent to Ireland on a quest to find the Irish ancestry of Sen. McGlory, to help him win the Irish vote. But when Marcy arrives in the small village of Ballinagra, she finds herself in the middle of a matchmaking festival, and the local matchmaker is determined to pair her off with one of the local bachelors.', '1997-10-03', 6.13, 'https://image.tmdb.org/t/p/w500/3TlW75w0Lo4uT6l8WRf3pdxbHHs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20561, '28 Up', 'Just two years away from turning 30, participants in Michael Apted''s documentary series are facing serious questions of identity and purpose, wondering whether they''ve found their place in the world.', '1984-11-20', 7.50, 'https://image.tmdb.org/t/p/w500/1MR6M5bX9r9HNf5SCWP9MRrEm8P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
