INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20595, 'The Last Days', 'This Oscar-winning documentary recounts the harrowing stories of five Hungarian Jews who endured the horrors of the Holocaust and Hitler''s reign.', '1998-10-23', 7.42, 'https://image.tmdb.org/t/p/w500/kWr6QDDcO2HHKqvJvgsJ1hQz4Gs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20604, 'Metal: A Headbanger''s Journey', 'The film discusses the traits and originators of some of metal''s many subgenres, including the New Wave of British Heavy Metal, power metal, Nu metal, glam metal, thrash metal, black metal, and death metal. Dunn uses a family-tree-type flowchart to document some of the most popular metal subgenres. The film also explores various aspects of heavy metal culture.', '2005-09-14', 7.59, 'https://image.tmdb.org/t/p/w500/8e1q6wP5XVcjh3yLVU1WNdZnppm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20616, 'Swimfan', 'Ben Cronin has it all: the admiration of his many friends, a terrific girlfriend, and he''s on the fast-track to an athletic scholarship. Ben''s rock-solid, promising future and romance are turned upside-down with the arrival of Madison Bell. Madison, the new girl in town, quickly sets her sights on the impressionable Ben. While their first few meetings are innocent enough, the obsessive and seductive Madison wants more ... much more.', '2002-09-06', 5.25, 'https://image.tmdb.org/t/p/w500/mOAiqOivdVecMu0yhumN6pzDWmo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
