INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20625, 'The Cocoanuts', 'During the Florida land boom, the Marx Brothers run a hotel, auction off some land and thwart a jewel robbery.', '1929-05-23', 6.47, 'https://image.tmdb.org/t/p/w500/xfiyCaWDfftKHzft2MKxAFFwHYL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20637, 'Panic', 'Alex is going through a midlife crisis and it has become a very difficult time for him. His marriage is struggling, he''s worried about his son, and his job of killing people for his family has become the most stressful part of his life. He seeks the help of a therapist and meets a woman in the waiting room that he connects with.', '2000-12-01', 6.21, 'https://image.tmdb.org/t/p/w500/gCaWBW6qQ0otWliRi0Gs4bAzgDX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
