INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20126, 'Deep Red', 'An English pianist living in Rome witnesses the brutal murder of his psychic neighbor. With the help of a tenacious young reporter, he tries to discover the killer using very unconventional methods. The two are soon drawn into a shocking web of dementia and violence.', '1975-03-07', 7.72, 'https://image.tmdb.org/t/p/w500/wq7RxV5gMvgO0EKeWpNhegnpJBh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20720, 'Gabriel Iglesias: Hot and Fluffy', 'Gabriel Iglesias is one of the fastest-rising comics today! With his unique brand of humor, lovable stage presence and wide range of voices and impressions, it''s no wonder that he already has a huge fan following. Now you can see Comedy Central''s "Comic of the Year" in his sold-out performance at the historic Fox Theatre in Bakersfield, California!', '2007-08-04', 7.52, 'https://image.tmdb.org/t/p/w500/hYYiubXgtEmWvsaKVp3ssAzUr9l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
