INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20504, 'The Book of Eli', 'A post-apocalyptic tale, in which a lone man fights his way across America in order to protect a sacred book that holds the secrets to saving humankind.', '2010-01-14', 6.81, 'https://image.tmdb.org/t/p/w500/1H1y9ZiqNFaLgQiRDDZLA55PviW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20438, 'The Tao of Steve', 'In college, Dex was the big man on campus. Ten years later, now an overweight kindergarten teacher, Dex is immune to the shocked stares of the women who were once his conquests. While trying to pick up the bartender, he is struck by the gorgeous Syd. Through a series of circumstances, Syd and Dex are thrown together and he soon finds himself questioning his belief in all things Steve.', '2000-08-04', 6.14, 'https://image.tmdb.org/t/p/w500/u9z4Qg0KGomhBUerbUzQXeO1ODs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20439, 'The Anarchist Cookbook', 'A movie about a young honors student-turned-anarchist, Puck, and his group of anarchist friends living peacefully in a Dallas commune until a nihilist, Johnny Black, appears with The Anarchist Cookbook and completely destroys their way of life.', '2002-07-18', 4.91, 'https://image.tmdb.org/t/p/w500/q9BwYsUoLP6rdEY5dU0nWQKOmj5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20678, 'Blankman', 'Darryl is a childlike man with a genius for inventing various gadgets out of junk. When he stumbles on a method to make his clothes bulletproof, he decides to use his skills to be the lowest budgeted superhero of all.', '1994-08-19', 5.37, 'https://image.tmdb.org/t/p/w500/9b1zje1Yp3kaJOn8pJqaQ1WLmoj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (20713, 'Farewell to the King', 'An American soldier who escapes the execution of his comrades by Japanese soldiers in Borneo during WWII becomes the leader of a personal empire among the headhunters in this war story told in the style of Joseph Conrad and Rudyard Kipling. The American is reluctant to rejoin the fight against the Japanese on the urging of a British commando team but conducts a war of vengeance when the Japanese attack his adopted people.', '1989-03-03', 6.00, 'https://image.tmdb.org/t/p/w500/TflAOAoV7C0XPqNyIhjhOelr8F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
