INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26648, 'The Night Porter', 'A concentration camp survivor discovers her former torturer and lover working as a porter at a hotel in postwar Vienna. When the couple attempt to re-create their sadomasochistic relationship, his former SS comrades begin to stalk them.', '1974-04-03', 6.70, 'https://image.tmdb.org/t/p/w500/zTUYhMdh2Jwk5s9jbrU4mCH3CY4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
