INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26719, 'House of Games', 'A psychiatrist comes to the aid of a compulsive gambler and is led by a smooth-talking grifter into the shadowy but compelling world of stings, scams, and con men.', '1987-10-11', 6.83, 'https://image.tmdb.org/t/p/w500/4i27Ut4cIoLbcNpW7aeuUQErEPE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26736, 'Wizards of Waverly Place: The Movie', 'A young wizard accidentally conjures a spell that puts her family in jeopardy.', '2009-08-28', 7.31, 'https://image.tmdb.org/t/p/w500/vrjLcGBLurVem5lXN8237qz4tyE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26748, 'Lone Star', 'When the skeleton of his murdered predecessor is found, Sheriff Sam Deeds unearths many other long-buried secrets in his Texas border town.', '1996-06-21', 7.05, 'https://image.tmdb.org/t/p/w500/lBxY8znsRoqa9Dy2NCe8I6GPsRm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26755, 'Brother''s Keeper', 'This documentary by Joe Berlinger and Bruce Sinofsky details the murder trial of Delbert Ward. Delbert was a member of a family of four elderly brothers, working as semi-literate farmers and living together in isolation from the rest of society until William''s death.', '1992-09-09', 7.11, 'https://image.tmdb.org/t/p/w500/AjumCYR6VPXGDKlYekGkx5jMdfi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26763, 'Burma VJ: Reporting from a Closed Country', 'Going beyond the occasional news clip from Burma, the acclaimed filmmaker, Anders Østergaard, brings us close to the video journalists who deliver the footage. Though risking torture and life in jail, courageous young citizens of Burma live the essence of journalism as they insist on keeping up the flow of news from their closed country.', '2008-11-12', 7.28, 'https://image.tmdb.org/t/p/w500/cAld4WLIUOP2rxt79UlDqhS9HlM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26766, 'Slasher', 'A documentary on a stereotypically shady used car salesman, one who convinces customers to buy vehicles that others have deemed unfit for sale.', '2004-03-15', 6.89, 'https://image.tmdb.org/t/p/w500/ger5wIjr4HLymG9FaAvifOC6wAO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (25944, 'Blood for Dracula', 'Deathly ill Count Dracula and his slimy underling, Anton, travel to Italy in search of a virgin''s blood. They''re welcomed at the crumbling estate of indebted Marchese Di Fiore, who''s desperate to marry off his daughters to rich suitors. But there, instead of pure women, the count encounters incestuous lesbians with vile blood and Marxist manservant Mario, who''s suspicious of the aristocratic Dracula.', '1974-08-13', 5.68, 'https://image.tmdb.org/t/p/w500/cLyCHzPT5kLBEPn4DMcqgNbjwke.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26791, 'Brigham City', 'Wes Clayton is a lawman and a bishop in a Mormon community called Brigham. The town is shaken when a woman from California is found murdered. Clayton and his young deputy work with an FBI agent sent to investigate. As a civil and spiritual leader in the frightened town, Clayton must uncover the town''s deepest secrets, find the murderer and keep Brigham from ripping itself apart.', '2001-03-30', 6.46, 'https://image.tmdb.org/t/p/w500/8CM2YIX0qLcqDY7d6iVb4uRXGG8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26789, 'No Mercy', 'An unconventional undercover Chicago cop and his partner are recruited to commit the murder of a New Orleans criminal kingpin.', '1986-12-19', 5.80, 'https://image.tmdb.org/t/p/w500/e3GLsfBLy7fdM3dJKAkzQlTIqII.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26811, 'Dr. Terror''s House of Horrors', 'Five train passengers are joined by a mysterious fortuneteller who offers to read Tarot. A quintet of stories unfold: an architect returns to his ancestral home to find a vengeful werewolf; a doctor suspects his new wife is a vampire; an intelligent vine takes over a house; a jazz musician plagiarises music from a voodoo ceremony; and a pompous art critic is pursued by a disembodied hand.', '1965-02-23', 6.47, 'https://image.tmdb.org/t/p/w500/ccQtFSAGievlTYpuS88PCTHzLu7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26797, 'Denis Leary: No Cure for Cancer', 'Ticked off comic Denis Leary talks honestly about subjects ranging from smoking, red meat, drugs, his family, rehab, and yes, cancer.', '1993-02-20', 6.96, 'https://image.tmdb.org/t/p/w500/bjybZeS8uPK0nezEz1CEZpZcbpa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26813, 'Himalaya', 'As the denizens of a Tibetan village prepare for their arduous annual trek to exchange salt for grain, the community''s allegiances are split between aging chieftain Tinle and rebellious young Karma. Tinle tries to maintain his clout and preserve obedience to ancient customs when Karma challenges the old man''s power.', '1999-09-13', 7.40, 'https://image.tmdb.org/t/p/w500/zppCfYBl0kRTpD9T0KTlZG5ZpWw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26815, 'Rocket Singh: Salesman of the Year', 'Rocket Singh: Salesman of the Year is the sometimes thoughtless, sometimes thoughtful story of a fresh graduate trying to find a balance between the maddening demands of the ''professional'' way, and the way of his heart - and stumbling upon a crazy way which turned his world upside down, and his career right side up. Welcome to the world of sales boss!', '2009-12-11', 6.90, 'https://image.tmdb.org/t/p/w500/3Z8lLFzPOBfOO4w3CykRaCeh9h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26810, 'A Common Thread', 'French drama, the debut film from writer-director Eléonore Faucher. Teenager Claire (Lola Naymark) discovers she is pregnant and decides to keep it a secret. Abandoning her dead-end supermarket job, she is taken on as an apprentice by couturiere Madame Mélikian (Ariane Ascaride), who is grieving over the death of her own child. As the two women work together, they soon develop a supportive and fam', '2004-05-14', 6.40, 'https://image.tmdb.org/t/p/w500/j9mUn7MfTUWdM4VthTcTPQE4Bdo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26827, 'Who''s That Girl', 'An uptight New York City tax lawyer gets his life turned upside down one day when he''s asked to escort a feisty free-spirited ex-convict who asks him to help prove her innocence of her crime.', '1987-08-07', 5.51, 'https://image.tmdb.org/t/p/w500/2Yu6ciKKgSWIZAzUg4IrrifO23z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26851, 'The Atomic Cafe', 'A disturbing collection of 1940s and 1950s United States government-issued propaganda films designed to reassure Americans that the atomic bomb was not a threat to their safety.', '1982-03-17', 7.33, 'https://image.tmdb.org/t/p/w500/9kTkv6o25fuWVSRu1AgOsF0cwz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26889, 'The Brother from Another Planet', 'A mute alien with the appearance of a black human is chased by outer-space bounty hunters through the streets of Harlem.', '1984-09-07', 6.68, 'https://image.tmdb.org/t/p/w500/jsIKSThUHCjWXzLCp7YV3LZAzZN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26535, 'Billy Liar', 'A young Englishman dreams of escaping from his working class family and dead-end job as an undertaker''s assistant. A number of indiscretions cause him to lie in order to avoid the penalties. His life turns into a mess and he has an opportunity to run away and leave it all behind.', '1963-08-15', 6.84, 'https://image.tmdb.org/t/p/w500/gphAIMqyO6Jqg8m7aINCguHVwmq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26890, 'I Shot Andy Warhol', 'The story of Valerie Solanas, a ''60s radical who preached misandry in her "SCUM" manifesto. She wrote a screenplay for a film that she wanted Andy Warhol to produce, but he repeatedly ignored her. So she shot him.', '1996-05-01', 6.16, 'https://image.tmdb.org/t/p/w500/8BLETXcQDxooKo8NubmmJ1psIhb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26912, 'Quatermass and the Pit', 'A mysterious artifact unearthed below a London Underground station proves to have powerful psychic effects on the people around.', '1967-11-09', 6.70, 'https://image.tmdb.org/t/p/w500/AvruSt4xRIbXO8gVxPzHupbf5A2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26899, 'The Mudge Boy', 'Chronicling the troubled existence of Duncan Mudge, a 14-year-old misfit who—while vying for the attention of his vacant father—struggles to fill the void brought on by his mother''s sudden death.', '2003-01-17', 6.61, 'https://image.tmdb.org/t/p/w500/daxDdN3vBBqx8KuOXNHBtu9QcbQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26933, 'Wild Reeds', 'As the Algerian War draws to a close, a teenager with a girlfriend starts feeling homosexual urges for two of his classmates: a country boy, and a French-Algerian intellectual.', '1994-06-01', 7.03, 'https://image.tmdb.org/t/p/w500/yTBEcAsD8OoIs8thYXl7FZuUXN3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26564, 'Crumb', 'This movie chronicles the life and times of R. Crumb. Robert Crumb is the cartoonist/artist who drew Keep On Truckin'', Fritz the Cat, and played a major pioneering role in the genesis of underground comix. Through interviews with his mother, two brothers, wife, ex-wife and ex-girlfriends, as well as selections from his vast quantity of graphic art, we are treated to a darkly comic ride through one man''s subconscious mind.', '1995-04-28', 7.54, 'https://image.tmdb.org/t/p/w500/9ocTHdBCJdwJ65Tubg3lYlfMxEY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26317, 'Man with a Movie Camera', 'A cameraman wanders around with a camera slung over his shoulder, documenting urban life with dazzling inventiveness.', '1929-05-12', 7.84, 'https://image.tmdb.org/t/p/w500/vJgAdgJWX54v0oXfIvhwjlZnmgn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26320, 'Taking Woodstock', 'The story of Elliot Tiber and his family, who inadvertently played a pivotal role in making the famed Woodstock Music and Arts Festival into the happening that it was. When Elliot hears that a neighboring town has pulled the permit on a hippie music festival, he calls the producers thinking he could drum up some much-needed business for his parents'' run-down motel. Three weeks later, half a million people are on their way to his neighbor’s farm in White Lake, New York, and Elliot finds himself swept up in a generation-defining experience that would change his life–and American culture–forever.', '2009-08-26', 6.20, 'https://image.tmdb.org/t/p/w500/wIdyAJCvIj3QUoNmmDdnhXpCMpp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26555, 'Club Paradise', 'When Chicago firefighter Jack Moniker retires and moves to a small Caribbean island, he is befriended by the owner of a run-down resort. Together they renovate the resort and lure tourists to Club Paradise in an effort to fight off corrupt officials and businessmen who want to claim the resort as their own.', '1986-07-11', 5.19, 'https://image.tmdb.org/t/p/w500/y79MRJPUH5zV8doA9uunDV0G9PU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26941, 'Afterglow', 'Lucky Mann is a builder equally handy at repairs and seduction. The latest housewife to succumb to his charms is Marianne, unhappily married to corporate exec Jeffrey. When Jeffrey becomes enraptured by Lucky’s wife Phyllis, the four get caught in a love quadrangle that reignites their marriages.', '1997-12-26', 5.91, 'https://image.tmdb.org/t/p/w500/c13Luo9O09ah6nMPrsr3zqlLyF9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26914, 'Troll 2', 'When young Joshua learns that he will be going on vacation with his family to a small town called Nilbog, he protests adamantly. He is warned by the spirit of his deceased grandfather that goblins populate the town. His parents, Michael and Diana, dismiss his apprehensions, but soon learn to appreciate their son''s warnings. Guided by his grandfather''s ghost, will Joshua and his family stand a chance in fighting off these evil beings?', '1990-10-12', 3.90, 'https://image.tmdb.org/t/p/w500/eFth6zw4PEInzr2Y64mYVN1zbBi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26602, 'Summer Catch', 'Local boy Ryan Dunne, now a pitcher for Boston College, meets Tenley Parrish, the daughter of a wealthy couple who summer on the Cape. Ryan and Tenley fall in love, much to the chagrin of their families, while Ryan clings to one last hope of being discovered and signed to a pro baseball contract.', '2001-08-22', 5.41, 'https://image.tmdb.org/t/p/w500/hMp5Iev56BUu3xJGpAeCCPC1ZwY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26560, 'Continental Divide', 'A hard-nosed Chicago journalist has an unlikely love affair with an eagle researcher.', '1981-09-18', 6.10, 'https://image.tmdb.org/t/p/w500/jwLFNA10RJBcQ4Fe0SoySkSFr0V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26942, 'Amy''s Orgasm', 'Amy is a single 29 year old Jewish woman. She wrote a successful self-help book about how women can''t truly be in love and experience "mental orgasm." Her parents and acquaintances always try to give her advice. Eventually, she breaks her celibacy and starts dating a radio shock jock, who is known for hitting on his bimbo guests. Of all men, will she find in him the true love she never believed in', '2001-03-08', 5.11, 'https://image.tmdb.org/t/p/w500/hsqw2fdGb13VryEo7kKMr1F3GJz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26949, 'In Love and War', 'After teenage ambulance driver Ernest Hemingway takes shrapnel in the leg during World War I, he falls in love with Agnes von Kurowsky, a beautiful older nurse at the hospital where he''s sent to recover. Their affair slowly blossoms, until Hemingway boldly asks Agnes to be his wife and journey to America with him.', '1996-12-18', 5.90, 'https://image.tmdb.org/t/p/w500/rjRu7HOjXNVflUrR40eMKhvmQps.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26554, 'Class of Nuke ''Em High', 'The pupils at a high school next to a nuclear power plant start acting and looking strange after buying contaminated drugs from a plant worker.', '1986-12-12', 5.56, 'https://image.tmdb.org/t/p/w500/2AljZDgKhzFaKO6i9tgmcytEA2b.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27031, 'Samurai Rebellion', 'The mother of a feudal lord''s only heir is kidnapped by the lord. Her husband and his samurai father must decide whether to accept the unjust decision, or risk death to rescue her.', '1967-05-27', 8.28, 'https://image.tmdb.org/t/p/w500/bKySGFUTgsZyn5i7s5htMVy4Xd2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26946, 'Attack of the Crab Monsters', 'A group of scientists travel to a remote island to study the effects of nuclear weapons tests, only to get stranded when their airplane mysteriously explodes. The team soon discovers that the tests have given rise to crabs mutated into intelligent, impervious, telepathic giants intent on increasing their numbers by breeding, then travelling to populated areas to feed, and which do not intend to be stopped by their discoverers.', '1957-02-10', 5.17, 'https://image.tmdb.org/t/p/w500/pDaJt3Jv41mOvND7HaDnmiGsD5V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27033, 'The Strange Love of Martha Ivers', 'Three childhood friends, Martha, Walter and Sam, share a terrible secret. Over time, the ambitious Martha and the pusillanimous Walter have married. She is a cold businesswoman; he is the district attorney: a perfect combination to dominate the corrupt city of Iverstown at will. But the unexpected return of Sam, after years of absence, deeply disturbs the life of the odd couple.', '1946-08-19', 7.07, 'https://image.tmdb.org/t/p/w500/iUAq0UYHglCsnHVbBLcJvZ6KQN9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27036, 'Too Late for Tears', 'Through a fluke circumstance, a ruthless woman stumbles across a suitcase filled with $60,000, and is determined to hold onto it even if it means murder.', '1949-07-17', 6.81, 'https://image.tmdb.org/t/p/w500/7lCWILDGzk8EjFILNO9Xy96DsKT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26955, 'Oasis', 'A young man released from prison visits the widow of the man he killed drunk-driving and becomes infatuated with his cerebral palsy-stricken daughter.', '2002-08-09', 7.74, 'https://image.tmdb.org/t/p/w500/aaajiBpeBVbVwovpSQKaMfKRGKw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27040, 'Meshes of the Afternoon', 'A woman returning home falls asleep and has vivid dreams that may or may not be happening in reality. Through repetitive images and complete mismatching of the objective view of time and space, her dark inner desires play out on-screen.', '1943-01-01', 7.57, 'https://image.tmdb.org/t/p/w500/yHjEjRU81RcxKFNU5hhiPYMzlsu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27070, 'Chopper Chicks in Zombietown', 'Riding around on their motorbikes, a gang of tough women bikers are the only thing that stands between a crowd of zombies, which have been accidentally let out of their secure cave, and those still alive in the town.', '1989-04-05', 4.70, 'https://image.tmdb.org/t/p/w500/2iViC9lCEmmrDHir1sBLcPV690U.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27103, 'My Life in Pink', 'Ludovic is waiting for a miracle. With six-year-old certainty, she believes she was meant to be a little girl -- and that the mistake will soon be corrected. But where she expects the miraculous, Ludo finds only rejection, isolation, and guilt -- as the intense reactions of family, friends, and neighbors strip away every innocent lace and bauble.', '1997-05-28', 6.86, 'https://image.tmdb.org/t/p/w500/4SwZaSDy1DR80QXKdvp6iSTawK2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26618, 'Clay Pigeons', 'Clay is a young man in a small town who witnesses his friend, Earl, kill himself because of the ongoing affair that Clay was having with the man''s wife, Amanda. Feeling guilty, Clay now resists the widow when she presses him to continue with the affair. Clay unknowingly befriends a serial killer named Lester Long who murders the widow in an attempt to "help" his "fishing buddy."', '1998-09-25', 6.17, 'https://image.tmdb.org/t/p/w500/6cxoftMuiwcQ9xzXfvGWAQfWUmK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27085, 'The Land That Time Forgot', 'During World War I, a German U-boat sinks a British passenger ship and takes the survivors aboard. After getting lost in fog, the submarine surfaces near the unknown island of Caprona, a lost world where they find dinosaurs and Neanderthals.', '1974-08-13', 5.68, 'https://image.tmdb.org/t/p/w500/2Jtm4aP4kj4vHimFfnLqjnm8LqF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27094, 'Lenny', 'The story of acerbic 1960s comic Lenny Bruce, whose groundbreaking, no-holds-barred style and social commentary was often deemed by the establishment as too obscene for the public.', '1974-11-10', 7.30, 'https://image.tmdb.org/t/p/w500/Avhk4pGdz3YQrzqLU65icjnE6vn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27104, 'Steam: The Turkish Bath', 'Francesco and Marta run a husband-and-wife design company in Rome. When Francesco''s aunt dies in Istanbul he travels there to sort out the hamam Turkish steam bath that she left him. He finds a love and warmth in his relatives'' Istanbul home that is missing from his life in Italy.', '1997-05-09', 6.60, 'https://image.tmdb.org/t/p/w500/a1c3p8qvTXf3Eue9QNzq1kVG5MM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27130, 'I Walked with a Zombie', 'A nurse in the Caribbean turns to voodoo in hopes of curing her patient, a mindless woman whose husband she''s fallen in love with.', '1943-04-21', 6.80, 'https://image.tmdb.org/t/p/w500/uoyBR8XNxPQRojujtczfG1qJezY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27134, 'Boy Eats Girl', 'A boy declares his love for his girlfriend, only to die the same night. He is brought back to life by his mother as a flesh-craving zombie, who sires more teen undead while trying to control his, er, appetite for his beloved.', '2005-08-02', 4.93, 'https://image.tmdb.org/t/p/w500/kMWuWQeysCuO4L9Ry235VsXAZZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27141, 'Liberty Heights', 'This semi-autobiographical film by Barry Levinson follows various members of the Kurtzman clan, a Jewish family living in suburban Baltimore during the 1950s. As teenaged Ben completes high school, he falls for Sylvia, a black classmate, creating inevitable tensions. Meanwhile, Ben''s brother, Van, attends college and becomes smitten with a mysterious woman while their father tries to maintain his burlesque business.', '1999-11-17', 6.66, 'https://image.tmdb.org/t/p/w500/pFcUURqmwvvyq0eFzvDun8daPMX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27171, 'The Lonely Guy', 'A writer for a greeting card company learns the true meaning of loneliness when he comes home to find his girlfriend in bed with another man.', '1984-01-27', 6.21, 'https://image.tmdb.org/t/p/w500/y6HWtKt6m41SMZuUeFcs94nWfHs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27190, 'A Muppets Christmas: Letters to Santa', 'When Gonzo forgets to mail three letters to Santa, he convinces Kermit and the gang to help him deliver the notes to the North Pole. Along the way, they discover that Christmas is the time to be with those you care about most, as they dash home to make a friends Christmas wish come true.', '2008-12-17', 5.95, 'https://image.tmdb.org/t/p/w500/zDxpOQi7kkokDLxZkVQhejp2VHu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27260, 'Brave New World', 'In a futuristic totalitarian utopian society, babies are created through genetic engineering, everyone has a predestined place in society and their minds are conditioned to follow the rules. A tragic outsider jeopardizes the status quo.', '1998-04-19', 5.51, 'https://image.tmdb.org/t/p/w500/6fQP7c3TPOvi84onjU5XMbOcbeP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27223, 'Lost in America', 'David and Linda Howard are successful yuppies from LA. When he gets a job disappointment, David convinces Linda that they should quit their jobs, liquidate their assets, and emulate the movie Easy Rider, spending the rest of their lives traveling around America...in a Winnebago.', '1985-02-08', 6.90, 'https://image.tmdb.org/t/p/w500/j7QiwUekGiYOmjKratNORIr35zg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27265, 'Mother', 'A neurotic, twice-divorced sci-fi writer moves back in with his mother to solve his personal problems.', '1996-12-25', 6.86, 'https://image.tmdb.org/t/p/w500/mxJJ0IEOOdvMo5yO7rcJBqyZ11n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27214, 'Amityville 3-D', 'To debunk the Amityville house''s infamous reputation and take advantage of a rock-bottom asking price, skeptical journalist John Baxter buys the place and settles in to write his first novel.', '1983-11-18', 4.60, 'https://image.tmdb.org/t/p/w500/gYvFL6REedBvjTSzVAhyk5imJgq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27281, 'Operation Dumbo Drop', 'Five Green Berets stationed in Vietnam in 1968 grudgingly undertake the mission of a lifetime -- to secretly transport an 8,000-pound elephant through 200 miles of rough jungle terrain. High jinks prevail when Capt. Sam Cahill promises the Montagnard villagers of Dak Nhe that he''ll replace their prized elephant in time for an important ritual. But for Capt. T.C. Doyle, the mission becomes a jumbo-sized headache!', '1995-07-28', 5.19, 'https://image.tmdb.org/t/p/w500/qIJlpbMCKg9O1C7gaiyDFaUWf9b.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27286, 'Beautiful Losers', 'This documentary follows the lives and careers of a collective group of do-it-yourself artists and designers who inadvertently affected the art world.', '2008-04-01', 6.47, 'https://image.tmdb.org/t/p/w500/9gllAA4UnQWQVkpe2RVXTOMr90P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27303, 'Hideaway', 'Hatch Harrison, his wife, Lindsey, and their daughter, Regina, are enjoying a pleasant drive when a car crash leaves wife and daughter unharmed but kills Hatch. However, an ingenious doctor, Jonas Nyebern, manages to revive Hatch after two lifeless hours. But Hatch does not come back unchanged. He begins to suffer horrible visions of murder -- only to find out the visions are the sights of a serial killer.', '1995-03-03', 5.20, 'https://image.tmdb.org/t/p/w500/cYWjgxgIJrak0BTemkij3gOCbMa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27295, 'Mom and Dad Save the World', 'Emperor Spengo sees Marge Nelson and using a giant magnet, kidnaps her and her husband Dick, hoping to make Marge his before blowing up the Earth. The Emperor and other inhabitants of his planet are somewhat less than bright, and Dick begins reliving episodes of Flash Gordon and Buck Rogers in order to rescue Marge, save the Earth, and restore the rightful emperor to the throne.', '1992-07-24', 4.87, 'https://image.tmdb.org/t/p/w500/grRXYyHbkp5ckh1zyQztgXbRIJX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27322, 'Love Jones', 'Darius Lovehall is a young black poet in Chicago who starts dating Nina Moseley, a beautiful and talented photographer. While trying to figure out if they''ve got a "love thing" or are just "kicking it," they hang out with their friends, talking about love and sex. Then Nina tests the strength of Darius'' feelings and sets a chain of romantic complications into motion.', '1997-03-14', 7.40, 'https://image.tmdb.org/t/p/w500/iuwimPkDm7kfptKm5zlK0pIzqXM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27327, 'Phantom of the Paradise', 'Singer-songwriter Winslow Leach seeks revenge on the nefarious music producer Swan, who steals both Winslow''s music and his favorite singer for the grand opening of Swan''s new rock palace, the Paradise.', '1974-10-31', 7.48, 'https://image.tmdb.org/t/p/w500/qDOtGWeSQNwB3dG7Amt1K0JW0az.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26623, 'Generation X', 'A group of young mutants--humans with a genetic variation that gives them superpowers and makes them feared by the population at large--begin training at a school for heroes. Their studies are interrupted when they must rescue one of their number from a mad scientist who can enter others'' dreams.', '1996-02-20', 4.30, 'https://image.tmdb.org/t/p/w500/wqkTCfznNXtYO9UnnxComqhhHRP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26953, 'Puppetmaster', 'After being contacted by their mysterious former colleague, four psychics arrive at a secluded hotel where they are stalked by a group of murderous puppets.', '1989-10-12', 5.86, 'https://image.tmdb.org/t/p/w500/6bcRspKbsM21HqLcxIBANbts3X7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26561, 'Enchanted April', 'When married British women Rose Arbuthnot and Lottie Wilkins decide to take a break from their respective spouses, they stay at a castle in Italy for a quiet holiday. Joining the ladies is Caroline Dester, a young socialite, and Mrs. Fisher, an older aristocrat. Liberated from their daily routines, the four women ease into life in rural Italy, and each finds herself transformed by the experience.', '1991-11-27', 6.80, 'https://image.tmdb.org/t/p/w500/b4Jrg23Q3y7p8GS7aMnPdFiEcnP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26573, 'Dr. Goldfoot and the Bikini Machine', 'Mad scientist Dr. Goldfoot has invented an army of bikini-clad robots programmed to seek out wealthy men and charm them into signing over their assets. Secret agent Craig Gamble and millionaire Todd Armstrong set out to foil his fiendish plot.', '1965-11-06', 5.20, 'https://image.tmdb.org/t/p/w500/v1NPmkAgQ85fTJAD7cmZ2EcFCvh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26580, '4 Little Girls', 'On September 15, 1963, a bomb destroyed a black church in Birmingham, Alabama, killing four young girls who were there for Sunday school. It was a crime that shocked the nation--and a defining moment in the history of the civil-rights movement. Spike Lee re-examines the full story of the bombing, including a revealing interview with former Alabama Governor George Wallace.', '1997-07-09', 7.10, 'https://image.tmdb.org/t/p/w500/7kbV3fDjuy9dQmcuZuT9NKNAEix.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26954, 'Puppet Master II', 'A new team of paranormal researchers has come to the hotel to investigate its murder-soaked past; the puppets -- led by a new member, Torch -- shed some light on the matter, as they tunnel, burn, strangle and hook to survive.', '1990-02-07', 6.00, 'https://image.tmdb.org/t/p/w500/dy5tzZFWFTjbNyG4KNP6yMjZ6l9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26610, 'Insomnia', 'Detectives Jonas and Erik are called to the midnight sun country of northern Norway to investigate a recent homicide, but their plan to arrest the killer goes awry, and Jonas mistakenly shoots Erik. The suspect escapes, and a frightened Jonas pins Erik''s death on the fugitive. Jonas continues to pursue the killer as he seeks to protect himself; however, his mounting guilt and the omnipresent sun plague him with an insomnia that affects his sanity.', '1997-03-14', 7.01, 'https://image.tmdb.org/t/p/w500/k0inzQmt7kATmAGns0wdfjiFxSu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26956, 'Puppet Master III: Toulon''s Revenge', 'After hearing that mystical toymaker Andre Toulon has managed to create a troupe of sentient, living puppets, Nazi underling Dr. Hess sets his sights on exploiting Toulon''s powers for the glory of the Reich.', '1992-05-01', 6.38, 'https://image.tmdb.org/t/p/w500/rRzjn3XTt98bhrbAtSSGjV4MgM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26958, 'Puppet Master 5', 'Sutekh, the dark pharaoh from another dimension, sends his own puppet, Totem, to continue his quest to kill Rick and steal the magic which animates the puppets.', '1994-09-21', 5.10, 'https://image.tmdb.org/t/p/w500/cqA1w7IwFCwA4fAD9R8vwOm1w5l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27360, 'King''s Ransom', 'Hoping to foil his own gold-digging wife''s plan, a loathsome businessman arranges his own kidnapping, only to realize that there are plenty of other people interested in his wealth as well.', '2005-04-22', 4.93, 'https://image.tmdb.org/t/p/w500/lH8Nugl7DnMaMHfOChEFNXXQ3zX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26976, 'Wit', 'A renowned professor is forced to reassess her life when she is diagnosed with terminal ovarian cancer.', '2001-02-09', 7.26, 'https://image.tmdb.org/t/p/w500/1ONOsIo5gby9hABPdknL7OAYBLm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26626, 'Glory Daze', 'Jack, a soon-to-be graduate, finds he''s having a difficult time letting go of the college life -- and decides maybe he doesn''t have to. Also questioning whether there''s life after college are Jack''s roommates: Rob, who fears domestication; comic-strip artist Mickey, who''s shy around girls; intellectual party animal Slosh; and perpetual student Dennis.', '1995-10-01', 5.19, 'https://image.tmdb.org/t/p/w500/mosH3RnC5wjcThd0DZq4ZqWkTPQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27431, 'The Cat o'' Nine Tails', 'A newsman works with a blind puzzle-solver to uncover a deadly conspiracy linked to a genetic research facility.', '1971-02-12', 6.68, 'https://image.tmdb.org/t/p/w500/vVfylUKX9Lz3Idpu0J3ds7vGXoF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27317, 'Patton Oswalt: My Weakness Is Strong', 'The critically-acclaimed comedian, actor, writer, and voice of Remy the Rat (the Oscar®-winning Ratatouille) takes time out from his many film and television outings to return to the comedy stage for his fourth stand-up special.', '2009-08-25', 7.17, 'https://image.tmdb.org/t/p/w500/fk7grnwQtt1W9PkJj0Gc2sc300N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26963, 'The Secret of Kells', 'Adventure awaits 12 year old Brendan who must fight Vikings and a serpent god to find a crystal and complete the legendary Book of Kells. In order to finish Brother Aiden''s book, Brendan must overcome his deepest fears on a secret quest that will take him beyond the abbey walls and into the enchanted forest where dangerous mythical creatures hide. Will Brendan succeed in his quest?', '2009-02-09', 7.38, 'https://image.tmdb.org/t/p/w500/vBymyj7QsXiW4TICD2JC5pAuBHO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27451, 'Harvard Man', 'College has always been a time for experimentation, sexual, cultural and otherwise. "Harvard Man" plays out against a background of love, sex, basketball, crime and experimentation. Action and philosophy in young people''s quest to discover their true identity.', '2001-08-01', 4.70, 'https://image.tmdb.org/t/p/w500/vxZG1UXh8gA3nYmrPNUWCHGGBFn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27367, 'Mrs. Miniver', 'Middle-class housewife Kay Miniver deals with petty problems. She and her husband Clem watch her Oxford-educated son Vin court Carol Beldon, the charming granddaughter of the local nobility as represented by Lady Beldon. Then the war comes and Vin joins the RAF.', '1942-07-03', 7.08, 'https://image.tmdb.org/t/p/w500/fjPjx6FTaoTussbqoLj6OYTtUyi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27452, 'The Spiral Staircase', 'On a stormy night, the mute servant to an ailing matriarch is stalked by a serial killer.', '1946-01-26', 7.00, 'https://image.tmdb.org/t/p/w500/4k0k9f59g901GWzw0gfFT7f5in.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27458, 'Little Darlings', 'Two 15-year-old girls from different sides of the tracks compete to see who will be first to lose their virginity while at camp.', '1980-03-21', 6.50, 'https://image.tmdb.org/t/p/w500/mMRPB4IvMw7c3zIHIEfaOGv0V5h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27459, 'Little Murders', 'A young nihilistic New Yorker copes with pervasive urban violence, obscene phone calls, rusty water pipes, electrical blackouts, paranoia, and ethnic-racial conflict during a typical summer of the 1970s.', '1971-02-09', 6.79, 'https://image.tmdb.org/t/p/w500/i2QOxh6pwgy1MUF4bBYDVdPwbWa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26957, 'Puppet Master 4', 'Blade, Tunneler, and Pinhead go toe-to-toe with a team of terrifying, gremlin-like creatures known as "Totems" that are sent by the Egyptian demon Sutekh to recapture the magic stolen by Toulon.', '1993-11-24', 5.60, 'https://image.tmdb.org/t/p/w500/fRIpNpZVL73MGJ7E2ZYt03tggeX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27460, 'Nick Fury: Agent of S.H.I.E.L.D.', 'Marvel''s hard-boiled hero is brought back to fight the menace of Hydra after exiling himself in the Yukon since the end of the Cold War. The children of the former Hydra head, Baron Von Stucker, have taken charge of the terrorist organization. Under the lead of his vicious daughter, Viper, Hydra has seized a deadly virus and threatens the destruction of America.', '1998-05-26', 4.63, 'https://image.tmdb.org/t/p/w500/4T0YjvnBaMASZkkRKxMIe6IoWO0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27461, 'Fat Man and Little Boy', 'Assigned to oversee the development of the atomic bomb, Gen. Leslie Groves is a stern military man determined to have the project go according to plan. He selects J. Robert Oppenheimer as the key scientist on the top-secret operation, but the two men clash fiercely on a number of issues. Despite their frequent conflicts, Groves and Oppenheimer ultimately push ahead with two bomb designs — the bigger "Fat Man" and the more streamlined "Little Boy."', '1989-10-20', 6.16, 'https://image.tmdb.org/t/p/w500/4CLeeHTMUesP8MCFt5phmdPSS5k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27472, 'The Odd Couple II', 'Brucey, the son of Oscar, calls his father to invite him to his wedding to Felix''s daughter next Sunday in California. Oscar and Felix meet again at Los Angeles International Airport and rent a car in order to go to San Malina for the wedding.', '1998-04-09', 6.30, 'https://image.tmdb.org/t/p/w500/aTajf9LOrL1pok7KnzoHKFJJyWD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27475, 'The Slumber Party Massacre', 'Trish invites her high school basketball teammates over for a night they''ll never forget when an unexpected guest crashes the party: an escaped psychopath with a portable power drill.', '1982-09-10', 5.56, 'https://image.tmdb.org/t/p/w500/rh65oDy8CNJoEAOf7oudhIt3DM6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27526, 'The Crossing Guard', 'Unable to move on from the loss of his daughter, Freddy, now a shell of the person he was before, swears to kill the man responsible for her death.', '1995-01-26', 6.01, 'https://image.tmdb.org/t/p/w500/kogaCIIylHmWQo2gJrrdq8Br8b8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27545, 'The Wasp Woman', 'The head of a major cosmetics company experiments on herself with a youth formula made from royal jelly extracted from wasps, but the formula''s side effects have deadly consequences.', '1959-10-30', 4.50, 'https://image.tmdb.org/t/p/w500/6yU5PuyeXX7EHG5d1AdWMforNfn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27573, 'The Bounty Hunter', 'Milo Boyd, a down-on-his-luck bounty hunter, thinks he''s seeing an upswing in fortune when he gets a call to bring in his bail-jumping ex-wife, a reporter named Nicole. Milo considers the job an easy payday, but Nicole quickly escapes to chase a lead on a murder case. The former spouses play an escalating game of one-upmanship, until they suddenly find themselves on the run for their lives.', '2010-03-16', 5.85, 'https://image.tmdb.org/t/p/w500/fJPKar0jnAsS09l3xfP6LL8sUkX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27576, 'Salt', 'As a CIA officer, Evelyn Salt swore an oath to duty, honor, and country. Her loyalty will be tested when a Russian defector accuses her of being a Russian sleeper spy. She goes on the run, using all her skills and years of experience as a covert operative to elude capture, protect her husband, and stay one step ahead of her colleagues at the CIA. Her efforts to prove her innocence only serve to cast doubt on her motives, as the hunt to uncover the truth behind her identity continues and the question remains: "Who is Salt?"', '2010-07-21', 6.42, 'https://image.tmdb.org/t/p/w500/ppXyhOe8UCEOrBRSYqE3SkHwrcR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27578, 'The Expendables', 'Barney Ross leads a band of highly skilled mercenaries including knife enthusiast Lee Christmas, a martial arts expert Yin Yang, heavy weapons specialist Hale Caesar, demolitionist Toll Road, and a loose-cannon sniper Gunner Jensen. When the group is commissioned by the mysterious Mr. Church to assassinate the dictator of a small South American island, Barney and Lee visit the remote locale to scout out their opposition and discover the true nature of the conflict engulfing the city.', '2010-08-07', 6.25, 'https://image.tmdb.org/t/p/w500/j09ZkH6R4JWVylBcDai1laCmGw7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27581, 'The Other Guys', 'Unlike their heroic counterparts on the force, desk-bound NYPD detectives Gamble and Hoitz garner no headlines as they work day to day. When a seemingly minor case turns out to be a big deal, the two cops get the opportunity to finally prove to their comrades that they have the right stuff.', '2010-08-06', 6.33, 'https://image.tmdb.org/t/p/w500/wNEHNqo3MgHmj3BUiPSqqq5czcm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27579, 'The American', 'Dispatched to a small Italian town to await further orders, assassin Jack embarks on a double life that may be more relaxing than is good for him.', '2010-08-31', 6.00, 'https://image.tmdb.org/t/p/w500/5OEOsRaBsSxD0qBtAhus0iKDzr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27583, 'Greenberg', 'Roger Greenberg, a failed musician now making a living as a carpenter in New York, returns to Los Angeles to house-sit for his brother. He''s stranded there—since he doesn''t drive—until his brother''s assistant, Florence, comes to his rescue. She''s as much a lost soul as he is, and the pair form a significant connection—giving Roger a much-needed reason to be happy.', '2010-03-26', 5.88, 'https://image.tmdb.org/t/p/w500/jAsN4vPpycVxC89QlA6NYBXRuK7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27582, 'The Mechanic', 'Arthur Bishop is a ''mechanic'' - an elite assassin with a strict code requiring professional perfection and total detachment. One of an elite group of assassins, Bishop may be the best in the business - with a unique talent for cleanly eliminating targets. When Harry McKenna, his close friend and mentor, is murdered, Harry''s son comes to him with vengeance in his heart and a desire to learn Bishop''s trade, signaling the birth of a deadly partnership.', '2011-01-13', 6.55, 'https://image.tmdb.org/t/p/w500/k37axEHszFP9WOVvbozxF0r7X7g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27584, 'High School', 'A high school valedictorian who gets baked with the local stoner finds himself the subject of a drug test. The situation causes him to concoct an ambitious plan to get his entire graduating class to face the same fate, and fail.', '2010-06-03', 5.63, 'https://image.tmdb.org/t/p/w500/3pZzS9R1r6qHvstMxmGq54JkFDR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27585, 'Rabbit Hole', 'Life for a happy couple is turned upside down after their young son dies in an accident.', '2010-12-16', 6.64, 'https://image.tmdb.org/t/p/w500/zTUQXwMn4ndt5AAcDvJCi14ZY2B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27586, 'The Runaways', 'Joan Jett and Cherie Currie, two rebellious teenagers from Southern California, become the frontwomen for The Runaways -- the now-legendary group that paved the way for future generations of female rockers. Under the Svengali-like influence of impresario Kim Fowley, the band becomes a huge success.', '2010-03-19', 6.50, 'https://image.tmdb.org/t/p/w500/byeTXKg9paqiFQbtfI28FOIhebg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
