INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27591, 'The People That Time Forgot', 'Major Ben McBride organizes a mission to the Antarctic wastes to search for his friend who has been missing in the region for several years. McBride''s party find themselves in a world populated by primitive warriors and terrifying prehistoric creatures, all of whom they must evade in order to get back safely', '1977-07-06', 5.30, 'https://image.tmdb.org/t/p/w500/8IIrlm2CjGCY5UV94lMCNb9HC94.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27593, 'Scotland, PA', 'In a modernized retelling of "MacBeth" set in 1970s suburban Pennsylvania, Joe McBeth, an unambitious hamburger stand employee, is driven to success by his scheming wife.', '2001-03-15', 6.00, 'https://image.tmdb.org/t/p/w500/phyNpVgqHmxn9tTXbljeyodTeVH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27324, 'Pulse', 'In the immense city of Tokyo, the darkness of the afterlife lures some of its inhabitants desperately trying to escape the sadness and isolation of the modern world.', '2001-02-03', 6.71, 'https://image.tmdb.org/t/p/w500/c3zEimDraIyMSasPMGDaNOrhnzn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27725, 'High Sierra', 'Given a pardon from jail, Roy Earle gets back into the swing of things as he robs a swanky resort.', '1941-01-23', 7.09, 'https://image.tmdb.org/t/p/w500/fkP6yy25Wja6Sn3AIlZ4F1BWsy0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27745, 'The Filth and the Fury', 'Julien Temple''s second documentary profiling punk rock pioneers the Sex Pistols is an enlightening, entertaining trip back to a time when the punk movement was just discovering itself. Featuring archival footage, never-before-seen performances, rehearsals, and recording sessions as well as interviews with group members who lived to tell the tale--including the one and only John Lydon (aka Johnny Rotten).', '2000-03-29', 6.93, 'https://image.tmdb.org/t/p/w500/kdNkiqmMeJfaD8ybjiV6bVOrcQ8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27437, 'The Bachelor and the Bobby-Soxer', 'Teenager Susan Turner, with a severe crush on playboy artist Richard Nugent, sneaks into his apartment to model for him and is found there by her sister Judge Margaret Turner. Threatened with jail, Nugent agrees to date Susan until the crush abates.', '1947-09-01', 6.91, 'https://image.tmdb.org/t/p/w500/eeBn5yhOBMBq2qQ9x2xQHyP1ZJk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27767, 'Slumber Party Massacre III', 'After a hard day of volleyball at the beach, a teen whose parents are away decides to have a slumber party with her girlfriends. Their boyfriends predictably show up to scare them, but a stranger from the beach is also seen lurking around the house. Soon the group begins experiencing an attrition problem.', '1990-09-07', 4.96, 'https://image.tmdb.org/t/p/w500/rtwbZi9dIs9pcTi2pQFtLxUUonB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (26978, 'Spacehunter: Adventures in the Forbidden Zone', 'On a distant planet inhabited by mutants, two bounty hunters race to rescue three Earth female captives from the clutches of an evil warlord.', '1983-05-20', 5.37, 'https://image.tmdb.org/t/p/w500/hXIis8l0rqCThFHlhvELf31pSXz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27390, 'Sorority Babes in the Slimeball Bowl-O-Rama', 'Out to steal a trophy from a local bowling alley, a group of college students accidentally unleash the imp -- a sadistic little spirit that creates demons and loves sexy women.', '1988-01-29', 4.77, 'https://image.tmdb.org/t/p/w500/2I7yv8T9rX1C1cBtJOrdOxoh7W3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27329, 'The Legend of Suriyothai', 'During the 16th century, as Thailand contends with both a civil war and Burmese invasion, a beautiful princess rises up to help protect the glory of the Kingdom of Ayothaya. Based on the life of Queen Suriyothai.', '2001-08-17', 5.85, 'https://image.tmdb.org/t/p/w500/t7dh4Ex3xBJ1nwiPpRGxgCTUa3Y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27719, 'The Peacekeeper', 'When a terrorist group steals the US President''s personal communications computer for launching the US arsenal in case of war, only a heroic Major has the key to prevent a Presidential assassination or a nuclear holocaust.', '1997-08-22', 4.78, 'https://image.tmdb.org/t/p/w500/6QBjzPscdNshlskkzw2fDXfLC1q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27022, 'The Sorcerer''s Apprentice', 'Balthazar Blake is a master sorcerer in modern-day Manhattan trying to defend the city from his arch-nemesis, Maxim Horvath. Balthazar can''t do it alone, so he recruits Dave Stutler, a seemingly average guy who demonstrates hidden potential, as his reluctant protégé. The sorcerer gives his unwilling accomplice a crash course in the art and science of magic, and together, these unlikely partners work to stop the forces of darkness.', '2010-07-13', 6.14, 'https://image.tmdb.org/t/p/w500/b5pIUsGll0418NyfNA5eYCI9aoK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27331, 'Charley Varrick', 'Charley Varrick robs a bank in a small town with his friends, but instead of obtaining a small amount of money, they discover they stole a very large amount of money belonging to the mob. Charley must now come up with a plan to not only evade the police but the mob as well.', '1973-09-19', 7.37, 'https://image.tmdb.org/t/p/w500/qPG2VPNA72he1Kczm2yFmslPNZN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27412, 'Hollywood Chainsaw Hookers', 'Los Angeles private eye Jack Chandler is hired by a worried mother to find her missing runaway daughter, Samantha. As Chandler searches for her whereabouts, he uncovers an evil cult that worships an Egyptian god, whose followers commit human sacrifices with chainsaws to appease their deity. He soon learns that Samantha has revenge in store for the cult leader and his bevy of blood-thirsty, chainsaw-wielding hookers.', '1988-03-01', 5.70, 'https://image.tmdb.org/t/p/w500/2IRG18T8Jt6H8oa0dNM01Ikxc5e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27723, 'Psycho Beach Party', 'Chicklet is a sixteen-year old tomboy who''s desperate to be part of the in-crowd of Malibu beach surfers. She''s the typical American girl - except for one little problem: her personality is split into more slices than a pepperoni pizza.', '2000-08-06', 5.71, 'https://image.tmdb.org/t/p/w500/28mzKFDyVzMVx9nhDrJQ3G2H7It.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27768, 'Some Folks Call It a Sling Blade', '25 years after committing a double murder, Karl Childers is going to be released from an institution for the criminally insane. A local reporter comes to talk to him, and listens in horror about his life leading up to the crime. This is the short film that inspired the full-length "Sling Blade".', '1994-03-26', 6.67, 'https://image.tmdb.org/t/p/w500/fRK5Mro9hBpwIlm0d0K6dC0vC0n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27791, 'Strangeland', 'A pierced and tattooed sadist, Captain Howdy, trolls the Internet for naive teens, luring them to his home to torture and defile them. When Howdy kidnaps and tortures the daughter of police Detective Mike Gage, he is caught. Deemed insane, he is sent to an asylum but is released soon after, seemingly better. However, Gage knows it is only a matter of time before Howdy strikes again, and he''s ready to unleash his own form of retribution when the time comes.', '1998-10-02', 5.05, 'https://image.tmdb.org/t/p/w500/AhQh5rtPymR1J8daZc0FNXiSkU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27861, 'Mimino', 'Local Georgian pilot Mimino dreams of flying airplanes for major international airlines. To realize his aspirations, he goes to Moscow where he encounters a fellow comrade from the Caucasus, the Armenian Rubik. Many misadventures ensue.', '1977-06-06', 7.55, 'https://image.tmdb.org/t/p/w500/61reasUU2uxRFQhxfKdvVHHMOsl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27332, 'Tex', 'After their mother dies and their father leaves them, teenage brothers Tex and Mason McCormick struggle to make it on their own.', '1982-07-30', 6.07, 'https://image.tmdb.org/t/p/w500/j9p9IHzjRNoswTPqWpUiOisHuEs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27866, 'Kevin Hart: I''m a Grown Little Man', 'Fresh off the heels of appearing in movies like Superhero Movie and The 40 Year-Old Virgin, fast-talking comedian Kevin Hart stars in this live stand-up performance where he makes fun of everything and everybody - especially himself.', '2009-02-03', 7.33, 'https://image.tmdb.org/t/p/w500/xixDPGXhg9Kz93HspsDo1iHf5PO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27899, 'Little Caesar', 'A small-time hood shoots his way to the top, but how long can he stay there?', '1931-01-25', 6.87, 'https://image.tmdb.org/t/p/w500/1K3Q1tAHHA5Sdtja2pPALBQevA7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27924, 'Autumn Marathon', 'Andrey Pavlovich Buzykin, who makes a living by teaching at an institute and translating English literature, is cheating on his wife. Buzykin''s main problem is that he''s a kind man with a weak character. The lies he is telling his wife all the time are inconvincing, but he never has the courage to tell her the truth. His lover, Alla, is aware of his family life, but gets offended when, for example, he cannot meet her so that he doesn''t come home late, or when he doesn''t want to go home in a new jacket she gives him to avoid having to explain to his wife. Alla and Nina, Andrei''s wife, both leave him, forgive him, and return to him at the same time, and Andrei continues with this kind of life, full of suffering and deceit. Finally, both women are so fed up with his lies that they don''t believe him even when he is telling the truth...', '1979-06-06', 7.10, 'https://image.tmdb.org/t/p/w500/vAAkpQ1Z9hpVO9j7lfJWZNeU6Tz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27764, 'Slumber Party Massacre II', 'Courtney is tormented by dreams of the infamous Driller Killer returning to wreak havoc... only to find that the murderous monster is reincarnated as an evil rocker.', '1987-10-16', 5.12, 'https://image.tmdb.org/t/p/w500/n1j7gCi3g2puzqyn7A2rPntHqjx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27932, 'Airport 1975', 'When an in-flight collision incapacitates the pilots of an airplane bound for Los Angeles, stewardess Nancy Pryor is forced to take over the controls. From the ground, her boyfriend Alan Murdock, a retired test pilot, tries to talk her through piloting and landing the 747 aircraft. Worse yet, the anxious passengers — among which are a noisy nun and a cranky man — are aggravating the already tense atmosphere.', '1974-10-18', 5.79, 'https://image.tmdb.org/t/p/w500/etfUuwVCvywq8mGspT94CBeLpSz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27930, 'Rude Boy', 'Rude Boy is a semi-documentary, part character study, part ''rockumentary'', featuring a British punk band, The Clash. The script includes the story of a fictional fan juxtposed with actual public events of the day, including political demonstrations and Clash concerts.', '1980-07-25', 6.41, 'https://image.tmdb.org/t/p/w500/46tzKLP9Huzjf1L09qEEdvNAdx0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27936, 'Micmacs', 'While standing in the doorway of the video shop where he works, Bazil is inadvertently shot in the head. Now homeless and jobless, he is taken in by a troupe of misfits who live in a giant mound of trash. There Bazil begins his quest for revenge against the people who produced the gun that shot him.', '2009-10-28', 6.65, 'https://image.tmdb.org/t/p/w500/yiqooJWNDEVsp8lbdTrTBvLAk0m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27935, 'Ordinary Miracle', 'A wizard invents characters who all come to life and start to arrive at his house: a King, his servants, a princes, a bear trapped in a man''s body - the usual lot. The Plot mainly rotates around the bear, who the wizard had turned into a man. The Bear, who wishes to be a bear once again, can turn into his old self if he were to kiss a princess. It gets complicated when he falls in love with that princess, that arrived at the wizard''s house. For how can they be together, if a single kiss will destroy their love?', '1978-10-02', 7.35, 'https://image.tmdb.org/t/p/w500/htvbPwc21Ey2yk4RDv69JM7ivRw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27937, 'The Very Same Munchhausen', 'A philosophical and poetic portrait of the famous (or maybe infamous?) Baron Munchhausen. His crazy, yet very merriment, stories, views and behavior is what sets him apart from others. He becomes alienated from the society that failed to grasp his brilliance. In fact, his brilliance is what underlines the faults with the society itself. It''s a beautiful yet tragic story that is filled with dense and intellectual dialogue.', '1979-12-31', 7.65, 'https://image.tmdb.org/t/p/w500/ofW7l89csAAe9XpVINFCjlQIpiv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27418, 'Next of Kin', 'Truman Gates, a Chicago cop, sets out to find his brother''s killer. Meanwhile, another of his brothers, Briar (a hillbilly) decides to find the killer himself.', '1989-10-20', 5.93, 'https://image.tmdb.org/t/p/w500/ieM9upg9O4agtodEvlZIiuNKZsN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27940, 'Formula of Love', 'A young aristocrat, Aleksei Fedyashev, is languishing in his family''s country estate, spending his days reading poetry and confessing his love... to a statue. Upon hearing that famous Count Cagliostro is touring Russia and has created quite a buzz in high society with his "magic", he decides to ask the Count to bring the statue to life...', '1984-12-30', 7.46, 'https://image.tmdb.org/t/p/w500/yAgBjMZMKG9rn0aKZBZ6Prx83T5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27655, 'Tales of Manhattan', 'Ten screenwriters collaborated on this series of tales concerning the effect a tailcoat cursed by its tailor has on those who wear it. The video release features a W.C. Fields segment not included in the original theatrical release.', '1942-08-05', 6.44, 'https://image.tmdb.org/t/p/w500/oKH3Vfx9cPmhD74iAaKLdGdk32w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27972, 'Dark Victory', 'Socialite Judith Traherne lives a lavish but emotionally empty life. Riding horses is one of her few joys, and her stable master is secretly in love with her. Told she has a brain tumor by her doctor, Frederick Steele, Judith becomes distraught. After she decides to have surgery to remove the tumor, Judith realizes she is in love with Dr. Steele, but more troubling medical news may sabotage her new relationship, and her second chance at life.', '1939-04-20', 6.94, 'https://image.tmdb.org/t/p/w500/fbbzkhKJAxaA6lpHbcJqQIBaI1d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27983, 'Yours, Mine and Ours', 'When a widower with ten children marries a widow with eight, can the twenty of them ever come together as one big happy family?', '1968-04-24', 6.90, 'https://image.tmdb.org/t/p/w500/ejbrAFkAHP5W5mzI8wA0zUTcDdg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27945, 'Hombre', 'John Russell, disdained by his "respectable" fellow stagecoach passengers because he was raised by Indians, becomes their only hope for survival when they are set upon by outlaws.', '1967-03-21', 7.10, 'https://image.tmdb.org/t/p/w500/puqgDLxdIZSnodDJ6Q0KxofOebo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27993, 'National Lampoon''s Senior Trip', 'While on detention, a group of misfits and slackers have to write a letter to the President explaining what is wrong with the education system. There is only one problem, the President loves it! Hence, the group must travel to Washington to meet the Main Man.', '1995-09-08', 5.49, 'https://image.tmdb.org/t/p/w500/3QpB4KpMKRnZnsJOsemOZHDoQKw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27995, 'She''s Gotta Have It', 'The story of Nola Darling''s simultaneous sexual relationships with three different men is told by her and by her partners and other friends. All three men wanted her to commit solely to them; Nola resists being "owned" by a single partner.', '1986-08-08', 6.60, 'https://image.tmdb.org/t/p/w500/qiJuXvPONqTSSnzhbCBqE7EotV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27985, 'Far from Home: The Adventures of Yellow Dog', 'Teenager Angus adopts a stray dog and names him Yellow. Several days later, while travelling along the coast of British Columbia with Angus''s father, John, the boy and dog become stranded when turbulent waters capsize their boat. Angus''s parents relentlessly badger rescue teams. Angus, schooled by his father in wilderness survival skills, and assisted by the intelligent Yellow Dog, tries to attract rescuers.', '1995-01-13', 6.21, 'https://image.tmdb.org/t/p/w500/bHtNHOiSmfX1KlJwc9Jvc8sYcjB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28005, 'Kama Sutra: A Tale of Love', 'Tara and Maya are inseparable, with the same tastes, habits, and hobbies. Years later, the two have matured but have maintained their friendship. Tara marries local prince Raj Singh, who succeeds the throne as the sole heir. After the marriage, Raj seeks another female to satisfy his sexual desires, with his sights settling on Maya, putting a perhaps unforgivable strain on a longtime friendship.', '1997-02-28', 5.72, 'https://image.tmdb.org/t/p/w500/kUaWgLrI7HqpPqPxgR54wSGokCV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28026, 'Prey for Rock & Roll', 'In late 1980s Los Angeles, Jacki and her all-girl punk rock band, Clam Dandy, are trying to make it big. On the verge of turning 40, Jacki decides that if the band''s one last shot at the big time is unsuccessful, she will give up her dreams of stardom.', '2003-09-26', 4.85, 'https://image.tmdb.org/t/p/w500/qXXAJjWHcXbfwdlq96nHSTxCVHv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28029, 'A Walk on the Moon', 'The world of a young housewife is turned upside down when she has an affair with a free-spirited blouse salesman.', '1999-01-29', 6.05, 'https://image.tmdb.org/t/p/w500/6aNMyAP82sDoVFmopFzGDWeVVne.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28030, 'Genghis Blues', 'Blind blues musician Paul Pena is perhaps best known for his song "Jet Airliner". In 1993, Pena heard Tuvan throat singing over his shortwave radio and subsequently taught himself how to reproduce these extraordinary sounds. This documentary follows him to Tuva, where he takes part in a throat singing competition.  Languages featured in the film include English, Russian and Tuvan.', '1999-07-19', 7.08, 'https://image.tmdb.org/t/p/w500/tEwdvxK2ntu6LGBPqCNFkXnwO1B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28031, 'If These Walls Could Talk 2', 'The stories of three lesbian couples -- who live in the same house at different periods of time -- who are at a crossroads in their lives. In 1961, Edith loses her lover, Abby, to a stroke. Linda and Amy struggle with feminist issues in 1972. And, in 2000, Kal and Fran try to have a baby with the help of sperm donor.', '2000-03-05', 6.50, 'https://image.tmdb.org/t/p/w500/1bwmJfLJVoxmj96qKVuE9oSmEUS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28033, 'Stuart Saves His Family', 'A self-help advocate struggles to put his dysfunctional family in its place.', '1995-04-12', 5.18, 'https://image.tmdb.org/t/p/w500/80YaWpUokDoPynsJi0ittpts3J0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28039, 'The New One-Armed Swordsman', 'Lei Li lost his right-arm in a sword duel with the master of a martial arts school, long ago. Now, he is able to defend himself well with just his left arm, and kung fu techniques. That he proves with just the help of his friend Chung-Chieng, when he crosses his path with a beautiful girl in need, Pao Chiao. Even against impossible odds, he will prove a great warrior.', '1971-02-07', 6.90, 'https://image.tmdb.org/t/p/w500/80wyNgKIPJCMTb8lzaG9rbezV10.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27352, 'Braddock: Missing in Action III', 'When Colonel James Braddock is told that his Asian wife and 12-year-old son are still alive in Communist Vietnam, he mounts a one-man assault to free them. Armed with the latest high-tech firepower, Braddock fights his way into the heart of the country and ends up battling his way out with several dozen abused Amerasian children in tow! Struggling to keep them alive while outmaneuvering a sadistic Vietnamese officer, Braddock ignites the jungle in a blazing cross-country race for freedom.', '1988-01-22', 5.74, 'https://image.tmdb.org/t/p/w500/y8Gp0TAQr8Z2Cy4ROSYzvOiMEMf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27678, 'Barbarians at the Gate', 'F. Ross Johnson decides to buyout his own tobacco firm RJR Nabisco after the plans of the launch of his new product, a smokeless cigarette Premier, fail on account of market rumours.', '1993-03-20', 6.87, 'https://image.tmdb.org/t/p/w500/v8StvvS5thbpsidFFPUth6vMziS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27362, 'Drowning by Numbers', 'Cissie Colpitts drowns her cheating husband and,  in the ensuing cover-up, enlists the help of lonely coroner Henry Madgett, an old friend with a longstanding weakness for her charms. But when Cissie''s daughter and granddaughter—both also named Cissie Colpitts—decide to resort to the same methods for solving conflicts with their own frustrating husbands, the women and their repeated appeals for help begin to wear on Madgett''s conscience.', '1988-09-02', 7.04, 'https://image.tmdb.org/t/p/w500/7VSvsr87TazqEvxqTDTWMDCbjwt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27813, 'Basket Case', 'A young man carrying a big basket that contains his extremely deformed, formerly conjoined twin brother seeks vengeance on the doctors who separated them against their will.', '1982-04-02', 6.21, 'https://image.tmdb.org/t/p/w500/ciyzEBzJ1TnafkgGXr6DqEVh1wk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27793, 'The NeverEnding Story III', 'A young boy must restore order when a group of bullies steal the magical book that acts as a portal between Earth and the imaginary world of Fantasia.', '1994-10-26', 4.47, 'https://image.tmdb.org/t/p/w500/o75HHfr23sgeqIeUPwjKY0V9Ppi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27430, 'Touchez Pas au Grisbi', 'Gentleman gangster Max and his partner, Riton, pull off their last, most successful heist and find themselves comfortable enough to retire in the style they enjoy. However, Max confides the details of the theft to his younger mistress, Josey -- who has secretly taken up with ambitious young rival gangster Angelo. Angelo then has Riton kidnapped and demands the stash of gold as ransom, which threatens Max''s dreams of the perfect retirement.', '1954-03-17', 7.16, 'https://image.tmdb.org/t/p/w500/svG2UuJ3SPrCp8O0RGPaKbECilq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28032, 'Thumbelina', 'Born of a flower and growing to only a couple of inches tall, poor Thumbelina is worried she''ll never meet someone her own size, until she happens to catch the eye of Prince Cornelius of the Fairies. Just as soon as she finds love, however, it''s torn away when she''s kidnapped by Ms. Toad. Now Thumbelina has to escape Ms. Toad''s grasp and search for Prince Cornelius. Luckily, there''s a whole city of animals willing to help.', '1994-03-30', 6.46, 'https://image.tmdb.org/t/p/w500/eBvSSfwAKgcjF4eyaeNSzTCpfaF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27444, 'Better Than Sex', 'After a one-night stand a couple is faced with the terrifying possibility of what they really want.', '2000-11-09', 5.90, 'https://image.tmdb.org/t/p/w500/zUD6Dc88R7gieprJ1oz8bNyi0uf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27397, 'Crossing Delancey', 'Thirty-something Isabelle spends her time going from her tiny, solitary West Side apartment to that of her grandmother on the Lower East Side. While her grandmother plots to find her a romantic match, Isabelle is courted by a married, worldly author, Anton, yet can''t seem to shake the down-to-earth appeal of Sam, a pickle vendor.', '1988-08-17', 5.93, 'https://image.tmdb.org/t/p/w500/62GF6vgxIvEpSPrH0WXHtCHm3zB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27414, 'Silent Night, Deadly Night', 'After a man dressed as Santa Claus brutally murders Billy Chapman''s parents, little Billy then endures the cruelty of a sadistic nun at his orphanage. Years later, when adult Billy has to fill in for an absent in-store Santa, his childhood trauma brings him to the breaking point.', '1984-11-09', 5.90, 'https://image.tmdb.org/t/p/w500/ypj2JwAN4vWcc4zSqFCTgUwMbJV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27804, 'The Thing Called Love', 'A group of newcomers to the country music business seek love and stardom.', '1993-08-27', 6.10, 'https://image.tmdb.org/t/p/w500/xsxkXRFDYeGGMGkdvotCIhMJFPl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28043, 'Black Sabbath', 'Three tales of supernatural horror include a woman plagued by threatening phone calls, a family targeted by vampiric monsters, and a deceased medium who wreaks havoc upon the living.', '1963-08-17', 7.16, 'https://image.tmdb.org/t/p/w500/vrMcn6CKrLjWAtHHMFL7cj8A5au.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27834, 'CQ', 'A young filmmaker in 1960s Paris juggles directing a cheesy sci-fi debacle, directing his own personal art film, coping with his crumbling relationship with his girlfriend, and a new-found infatuation with the sci-fi film''s starlet.', '2001-05-12', 5.80, 'https://image.tmdb.org/t/p/w500/qembyZYP4BSGoh9djmh8ga2nVfG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28059, 'SubUrbia', 'A group of suburban teenagers try to support each other through the difficult task of becoming adults.', '1997-02-07', 6.21, 'https://image.tmdb.org/t/p/w500/7PdRbG09K9JHYyOwwCSn3OdJb0N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28053, 'City Island', 'The Rizzos, a family who doesn''t share their habits, aspirations, and careers with one another, find their delicate web of lies disturbed by the arrival of a young ex-con brought home by Vince, the patriarch of the family, who is a corrections officer in real life, and a hopeful actor in private.', '2009-03-06', 6.94, 'https://image.tmdb.org/t/p/w500/t7LJY2LCcGRLP9E4QbwBkLpZ2W7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28089, 'The Messenger', 'Will Montgomery, a U.S. Army Staff Sergeant who has returned home from Iraq, is assigned to the Army’s Casualty Notification service. Montgomery is partnered with Captain Tony Stone, to give notice to the families of fallen soldiers. The Sergeant is drawn to Olivia Pitterson, to whom he has delivered news of her husband’s death.', '2009-11-13', 6.74, 'https://image.tmdb.org/t/p/w500/p4fJyH7mMbasiFYwiw2nE7D6pMY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27845, 'Trees Lounge', 'Tommy has lost his job, his love and his life. He lives in a small apartment above the Trees Lounge, a bar which he frequents along with a few other regulars without lives. He gets a job driving an ice cream truck and ends up getting involved with the seventeen-year-old niece of his ex-girlfriend. This gets him into serious trouble with her father.', '1996-05-11', 6.89, 'https://image.tmdb.org/t/p/w500/2DtoVhI9RkArGbzkvctGxY578QN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27841, 'They Might Be Giants', 'After the death of his wife, retired judge Justin Playfair creates a fantasy world for himself in which he is the legendary detective Sherlock Holmes, even dressing like the character. Out of concern for Justin''s money more than his health, his brother Blevins puts him under the care of psychiatrist Dr. Mildred Watson. As Dr. Watson grows fond of Justin, she begins to play along with his theories, eventually becoming an assistant in his investigations.', '1971-06-09', 7.00, 'https://image.tmdb.org/t/p/w500/yzv8J2Vu63AQyEw5D9ckyBgn9Fo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28200, 'Sylvia', 'Story of the relationship between the poets Ted Hughes and Sylvia Plath.', '2003-10-17', 5.70, 'https://image.tmdb.org/t/p/w500/fEhrg0uQqhmHUDRqODxxvRPipfB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28205, 'The Class', 'An average guy of an Estonian high-school decides to defend his bullied classmate. This starts a war between him and the informal leader of the class.', '2007-03-16', 7.46, 'https://image.tmdb.org/t/p/w500/AogHMwGObAqXgXoqtj2Zg90fX5K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28120, 'Crossfire', 'A man is murdered, apparently by one of a group of soldiers just out of the army. But which one? And why?', '1947-08-15', 6.65, 'https://image.tmdb.org/t/p/w500/s3EFBiCsc4Ckc1tntoHAEnhZtSO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28216, 'Mr. Death: The Rise and Fall of Fred A. Leuchter, Jr.', 'Documentary filmmaker Errol Morris investigates the case of a man who became an authority on capital punishment, but was discredited when he got involved on the wrong side of a court case. Leuchter, a meek man whose appearance belies his grim expertise, develops what he says is a more effective electric chair. Before long he''s in demand from officials who want his opinions on other kinds of execution. But when called to aid the case of an accused Holocaust denier, Leuchter''s problems begin.', '1999-12-29', 7.00, 'https://image.tmdb.org/t/p/w500/buoMN4p95mvB2JgyglMb5gKxurV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28219, 'Baadasssss!', 'Director Mario Van Peebles chronicles the complicated production of his father Melvin''s classic 1971 film, "Sweet Sweetback''s Baadasssss Song." Playing his father in the film, Van Peebles offers an unapologetic account of Melvin''s brash and sometimes deceptive conduct on the set of the film, including questionable antics like writing bad checks, tricking a local fire department and allowing his son, Mario, to shoot racy sex scenes at the age of 11.', '2004-05-28', 6.47, 'https://image.tmdb.org/t/p/w500/mMFWMlNMFPSPDbYvKpBH7baDzjp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28257, 'The Maltese Falcon', 'A lovely dame with dangerous lies employs the services of a private detective, who is quickly caught up in the mystery and intrigue of a statuette known as the Maltese Falcon.', '1931-05-23', 6.41, 'https://image.tmdb.org/t/p/w500/zpE6gucVjusGXSS4lcSjqIWCeAj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28285, 'The Three Faces of Eve', 'A doctor treats a woman suffering from multiple personality disorder.', '1957-12-19', 7.25, 'https://image.tmdb.org/t/p/w500/jqfTPqaGYlz1ZR7YHjz5RTgPa8U.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28288, 'The Gay Divorcee', 'Seeking a divorce from her absentee husband, Mimi Glossop travels to an English seaside resort. There she falls in love with dancer Guy Holden, whom she later mistakes for the corespondent her lawyer hired.', '1934-10-12', 6.89, 'https://image.tmdb.org/t/p/w500/xD6oUOAa0Q6PppaOnY6dy6sWPLG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28293, 'Flying Down to Rio', 'An American bandleader woos a Brazilian beauty  who is already engaged to his employer.  His friends try to help him, while learning the local dance, The Carioca.  The first pairing of Fred Astaire & Ginger Rogers, and their only pre-Code film.', '1933-12-22', 6.31, 'https://image.tmdb.org/t/p/w500/zKBXy84eN6tgwXaYsiFSCgq0GBc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28292, 'Follow the Fleet', 'When the US Navy fleet docks at San Francisco, sailor Bake Baker tries to rekindle the flame with his old dancing partner, Sherry Martin, while Bake''s buddy Bilge Smith romances Sherry''s sister, Connie. But it''s not all smooth sailing—Bake has a habit of losing Sherry''s jobs for her and, despite Connie''s dreams, Bilge is not ready to settle down.', '1936-02-20', 6.88, 'https://image.tmdb.org/t/p/w500/8crR3tx6JapNwH4WcrxDkOaDkRE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28295, 'I Saw What You Did', 'Teenage friends Kit and Libby make prank phone calls for fun but then find themselves involved in a brutal double murder committed by one of their targets.', '1965-07-21', 6.21, 'https://image.tmdb.org/t/p/w500/mliHs2Ii393vF0A3i73F6jAysdh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28345, 'Heidi', 'Heidi is orphaned and her uncaring maternal Aunt Dete takes her to the mountains to live with her reclusive, grumpy paternal grandfather, Adolph Kramer. Heidi brings her grandfather back into mountain society through her sweet ways and sheer love. When Dete later returns and steals Heidi away to become the companion of a rich man''s wheelchair-bound daughter, the grandfather is heartsick to discover his little girl missing and immediately sets out to get her back.', '1937-10-15', 6.91, 'https://image.tmdb.org/t/p/w500/rIfA5X4pYJOHyFPZFqWLOu7yfiZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28313, 'Losing Isaiah', 'Khaila Richards, a crack-addicted single mother, accidentally leaves her baby in a dumpster while high and returns the next day in a panic to find he is missing. In reality, the baby has been adopted by a warm-hearted social worker, Margaret Lewin, and her husband, Charles. Years later, Khaila has gone through rehab and holds a steady job. After learning that her child is still alive, she challenges Margaret for the custody.', '1995-03-17', 6.50, 'https://image.tmdb.org/t/p/w500/oHALKuPewtqIn2BcluZsGvcEG1P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28070, 'Surf Nazis Must Die', 'When a Black oil well worker is killed by a band of California neo-Nazis, his gun-wielding grandmother busts out of her retirement home to avenge him.', '1987-07-03', 3.88, 'https://image.tmdb.org/t/p/w500/gVECT5DHulQJyo9oqS1tdDSGowI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28349, 'The Dead Hate the Living!', 'When a renegade band of young filmmakers break into an abandoned hospital to make their horror epic, they stumble upon a real dead body and decide to use it in their movie. They accidentally bring it back to life, open a portal to a dead world that releases dozens of other zombies, then struggle for their lives in a desperate attempt to flee from the creatures who apparently have them hopelessly trapped in the hospital.', '2000-02-08', 4.82, 'https://image.tmdb.org/t/p/w500/shhtF3ceZOHuJvh07f4UTsZ6JzK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28368, 'Gardens of Stone', 'At Arlington National Cemetery during the Vietnam era, veteran sergeant Clell Hazard trains young soldiers while mourning those lost in combat. Unable to return to war himself, he mentors Jackie Willow—the idealistic son of a fallen comrade—hoping to prepare him for the realities of Vietnam and the cost of duty.', '1987-05-05', 6.15, 'https://image.tmdb.org/t/p/w500/bptiOG8kCoq1WUpWEwMyAIaMED4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28370, 'Date with an Angel', 'Aspiring composer Jim Sanders is engaged to spoiled rich girl Patty. But the morning after his bachelor party, Jim wakes up to discover a beautiful, broken-winged angel in his pool. When everyone finds out about his heavenly houseguest, Jim must cope with a dangerously jealous fiancée, an exploitive future father-in-law and a group of buddies with an outrageous business plan!', '1987-11-20', 6.75, 'https://image.tmdb.org/t/p/w500/g9CjIIyZdCybuCRkn4Ad8uWBclu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28355, 'Case 39', 'In her many years as a social worker, Emily Jenkins believes she has seen it all, until she meets 10-year-old Lilith and the girl''s cruel parents. Emily''s worst fears are confirmed when the parents try to harm the child, and so Emily assumes custody of Lilith while she looks for a foster family. However, Emily soon finds that dark forces surround the seemingly innocent girl, and the more she tries to protect Lilith, the more horrors she encounters.', '2009-08-13', 6.32, 'https://image.tmdb.org/t/p/w500/b16EjFeHd2AwoYXWUne7DA346pU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28377, 'Hell Night', 'As an initiation rite into Alpha Sigma Rho fraternity, four pledges must spend a night in Garth Manor, twelve years to the day after the previous resident murdered his entire family.', '1981-08-28', 5.50, 'https://image.tmdb.org/t/p/w500/2IqqzSQmZFAon2C1lQZeZCUUx8K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28384, 'Husbands and Wives', 'When their best friends announce that they''re separating, a professor and his wife discover the faults in their own marriage.', '1992-09-18', 7.00, 'https://image.tmdb.org/t/p/w500/mb6Hmns0PP2Me9TYpLE9M3GHt7v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28387, 'Kicking and Screaming', 'After college graduation, Grover''s girlfriend Jane tells him she''s moving to Prague to study writing. Grover declines to accompany her, deciding instead to move in with several friends, all of whom can''t quite work up the inertia to escape their university''s pull. Nobody wants to make any big decisions that would radically alter his life, yet none of them wants to end up like Chet, the professional student who tends bar and is in his tenth year of university studies.', '1995-10-06', 6.19, 'https://image.tmdb.org/t/p/w500/ynAtSpTou7snNOq32djzILw9VCA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28421, 'The Invisible Man Returns', 'The owner of a coal mining operation, falsely imprisoned for fratricide, takes a drug to make him invisible, despite its side effect: gradual madness.', '1940-01-12', 6.28, 'https://image.tmdb.org/t/p/w500/hJmmgKnY0NaJKVP7Glb4ciAzXWr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28448, 'Walker', 'William Walker and his mercenary corps enter Nicaragua in the middle of the 19th century in order to install a new government by a coup d''etat.', '1987-12-04', 6.43, 'https://image.tmdb.org/t/p/w500/1C0oYAeNjIBLuj7CVWz3HTIUdeP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28117, 'Delirious', 'A soap opera writer gets hit on the head and wakes up as a character in his own show.', '1991-08-09', 5.67, 'https://image.tmdb.org/t/p/w500/Irafvzuw1lkJfBrsPv7ahYOPq9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28469, 'Der Herr Karl', 'The antihero "Mr. Karl" tells a "young person", the viewer, his life story while he sits at work in the warehouse of a delicatessen. The narrator increasingly turns out to be an opportunistic follower from the petty-bourgeois milieu, who maneuvered his way through life in the changing course of Austrian history from the end of the First World War to the end of the occupation in the 1950s.', '1967-01-01', 8.25, 'https://image.tmdb.org/t/p/w500/gwycJX3BZvLpS33OtoJl5kjnXLk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28476, 'The Phantom Tollbooth', 'A young boy named Milo unexpectedly receives a magic tollbooth and, out of boredom, drives through it and enters a fantastical, animated kingdom in turmoil following the loss of its princesses, Rhyme and Reason.', '1970-11-07', 6.92, 'https://image.tmdb.org/t/p/w500/totkDxL4QApB4xFr7gc1EdGkz7J.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28090, 'Maniac Cop 2', 'Undead cop Matt Cordell rises from the grave, and is after the criminals who murdered him in prison.', '1990-07-18', 5.93, 'https://image.tmdb.org/t/p/w500/NWeLUBpxn7lcMpCPvnTGmtHwmj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28528, 'The Harder They Fall', 'Jobless sportswriter Eddie Willis is hired by corrupt fight promoter Nick Benko to promote his current protégé, an unknown Argentinian boxer named Toro Moreno. Although Moreno is a hulking giant, his chances for success are hampered by a powder-puff punch and a glass jaw. Exploiting Willis'' reputation for integrity and standing in the boxing community, Benko arranges a series of fixed fights that propel the unsophisticated Moreno to #1 contender for the championship. The reigning champ, the sadistic Buddy Brannen, harbors resentment at the publicity Toro has been receiving and vows to viciously punish him in the ring. Eddie must now decide whether or not to tell the naive Toro the truth.', '1956-05-08', 7.17, 'https://image.tmdb.org/t/p/w500/93pUA2kAOeVlyvO1EeW8YmYIapt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28121, 'A Thin Line Between Love and Hate', 'Nightclub manager Darnell Wright is a perpetual playboy who is almost as devoted to his job as he is to the pursuit of beautiful women. After he sets his sights on the ultra-classy Brandi Web, he launches an all-out assault to win her heart. Ultimately, charm, lust and passion prevail, but Darnell learns the hard way that when you play, you pay. Brandi is much harder to get rid of than she was to get--especially when she realizes that she has a rival vying for Darnell''s affection. When he finally decides to call it quits, Brandi becomes an obsessed femme fatale stalking the new love of her life.', '1996-04-04', 5.70, 'https://image.tmdb.org/t/p/w500/wo9AGi5LlFXZUj8MDPq3eKCUMpd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27854, 'For Whom the Bell Tolls', 'Spain in the 1930s is the place to be for a man of action like Robert Jordan. There is a civil war going on and Jordan—who has joined up on the side that appeals most to idealists of that era—has been given a high-risk assignment up in the mountains. He awaits the right time to blow up a crucial bridge in order to halt the enemy''s progress.', '1943-07-12', 6.53, 'https://image.tmdb.org/t/p/w500/uoNTHrpeOgIuWsC5Eucx5Sp483D.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (27850, 'Halloweentown', 'On her 13th birthday, Marnie learns she''s a witch, discovers a secret portal, and is transported to Halloweentown — a magical place where ghosts and ghouls, witches and werewolves live apart from the human world. But she soon finds herself battling wicked warlocks, evil curses, and endless surprises.', '1998-11-10', 6.82, 'https://image.tmdb.org/t/p/w500/y9RJCxJMbWqhXjkBgC0VXETmHj6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28500, 'Walking with Monsters', 'Many people think of the dinosaurs as the first inhabitants of the earth, but this prequel to the acclaimed "Walking with Dinosaurs" puts viewers in the midst of a host of strange creatures that inhabited the earth millions of years before the dinosaurs ever existed.Starting from the Cambrian Period (530 MYA) and ending at the Early Triassic Period (248 MYA), Walking With Monsters shows the life and death struggles of the fantastic creatures that existed before the dinosaurs.', '2005-11-05', 7.33, 'https://image.tmdb.org/t/p/w500/aZoIWwA8Am0E4gjpcRRdoZVRLdJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28134, 'The Impostors', 'Wrongly accused of physically abusing a fellow actor, starving thespians Arthur and Maurice find themselves pursued by the law aboard a cruise ship.', '1998-10-02', 5.96, 'https://image.tmdb.org/t/p/w500/pnL8MvYje9DOZTuTnF04k8RUkSL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28422, 'Love Exposure', 'The story of a teenage boy called Yu, who falls for Yoko, a girl he runs into while operating for the sake of sin as an upskirt photographer in an offshoot of the porn industry. His attempts to woo her are complicated by a spot of cross-dressing - which convinces Yoko that she is lesbian - dalliances with kung-fu and crime, and a constant struggle with the guilt that''s a legacy of his Catholic upbringing.', '2008-11-29', 7.90, 'https://image.tmdb.org/t/p/w500/iCjpPMQRh1jcMQl7CZ5P2fR8aXN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28463, 'East/West', 'June 1946: Stalin invites Russian emigres to return to the motherland. It''s a trap: when a ship-load from France arrives in Odessa, only a physician and his family are spared execution or prison. He and his French wife (her passport ripped up) are sent to Kiev. She wants to return to France immediately; he knows that they are captives and must watch every step.', '1999-09-01', 6.44, 'https://image.tmdb.org/t/p/w500/c1Uf4HC5WEcssVoOm48Bfzn7Wmk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28156, 'The Baby', 'A social worker who recently lost her husband investigates the strange Wadsworth family. The Wadsworths might not seem too unusual to hear about them at first - consisting of the mother, two grown daughters and the diaper-clad, bottle-sucking baby. The problem is, the baby is twenty-one years old.', '1973-03-01', 6.00, 'https://image.tmdb.org/t/p/w500/ovk7WxoO5Bu970qGCQuF6DgrwZw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28124, 'Seems Like Old Times', 'After being falsely accused of robbing a bank, a writer seeks the help of his lawyer ex-wife to clear his name. However, hilarity ensues when he must hide from her husband, who’s throwing a party for law enforcement officials.', '1980-12-19', 6.30, 'https://image.tmdb.org/t/p/w500/5gslMsppM01WafyogPpHevrMeGg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28609, 'Dragon Ball Z: Dead Zone', 'In order to wish for immortality and avenge his father, Garlic Jr. collects the dragon balls, kidnapping Goku''s son Gohan in the process. Goku, Kami, Piccolo, and Krillin unite to rescue Gohan and save the world from being sucked into a dead zone.', '1989-07-15', 6.80, 'https://image.tmdb.org/t/p/w500/ywtyEDTM2YO7qod7USNNwhrAfvA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28638, 'The Bird People in China', 'Wada, a salary man, is enlisted to venture off to China to investigate a potential Jade mine. After his arrival, Wada encounters a violent, yet sentimental, yakuza, who takes the liberty of joining his adventure through China. Led on their long and disastrous journey to the mine by Shen, the three men come across something even more magical and enticing.', '1998-06-10', 7.21, 'https://image.tmdb.org/t/p/w500/civu1OxSYyxywfEOeMyCZoAOt7H.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
