INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29380, 'Easter Parade', 'On the day before Easter in 1911, Don Hewes is crushed when his dancing partner (and object of affection) Nadine Hale refuses to start a new contract with him. To prove Nadine''s not important to him, Don acquires innocent new protege Hannah Brown, vowing to make her a star in time for next year''s Easter parade.', '1948-07-08', 7.00, 'https://image.tmdb.org/t/p/w500/aLgvafQvb6D6at4khC0b7kn0h8f.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29228, 'The Computer Wore Tennis Shoes', 'Some college students manage to persuade the town''s big businessman, A. J. Arno, to donate a computer to their college. When the problem- student, Dexter Riley, tries to fix the computer, he gets an electric shock and his brain turns to a computer; now he remembers everything he reads. Unfortunately, he also remembers information which was in the computer''s memory, like Arno''s illegal businesses..', '1969-12-29', 6.00, 'https://image.tmdb.org/t/p/w500/vXfUKvAHTIifAU7IP17kl1ZBGh6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29398, 'Project X', 'A spy is brought back from cryogenic suspension after being almost killed in a plane crash returning from a mission to learn about a deadly new weapon being developed in the East. But the vital memories are being suppressed, so the authorities use ultra-advanced technologies to try to uncover the secret.', '1968-05-01', 5.70, 'https://image.tmdb.org/t/p/w500/9beJl9aNrqKi8RFfhQ2MoWTKIJz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29425, 'The Crazies', 'The military attempts to contain a manmade virus causing death and permanent insanity in those infected, as it overtakes a small Pennsylvania town.', '1973-03-16', 6.07, 'https://image.tmdb.org/t/p/w500/xSNgBJL9WKMHwl42gZXeRsQXFa1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29419, 'Carnival Magic', 'A magician in a carnival--who actually can read minds and levitate people and objects--works with a superintelligent chimp named Alex, who can also talk. The magician and the chimp soon become the stars of the carnival, drawing in big crowds. However, the wild-animal trainer, who has been displaced by the team as the carnival''s top act, decides to kidnap Alex and sell him to a medical laboratory for experimentation, thereby getting rid of his competition.', '1983-03-04', 2.90, 'https://image.tmdb.org/t/p/w500/2UEBhca8be67AMKVeW7C1Pa0TKO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28176, 'Tucker: The Man and His Dream', 'Ypsilanti, Michigan, 1945. Engineer Preston Tucker dreams of designing the car of future, but his innovative envision will be repeatedly sabotaged by his own unrealistic expectations and the Detroit automobile industry tycoons.', '1988-08-12', 6.74, 'https://image.tmdb.org/t/p/w500/uph7wz8WASLHwHyC5SYfQgqaoV7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29427, 'The Crazies', 'Four friends find themselves trapped in their small hometown after they discover their friends and neighbors going quickly and horrifically insane.', '2010-02-26', 6.30, 'https://image.tmdb.org/t/p/w500/ggtG9DZELyTtM2Y0DRJDOJa5iP8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29444, 'S.F.W.', 'An alienated and misanthropic teenager gains sudden and unwanted celebrity status after he''s taken hostage by terrorists where his indifference to their threats to kill him makes news headlines.', '1995-01-20', 5.93, 'https://image.tmdb.org/t/p/w500/3bq91jWCReRrqlPn81alSoxeXoP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28172, 'Blood Feast', 'In the sleepy suburbs of Miami, seemingly normal Egyptian immigrant Fuad Ramses runs a successful catering business. He also murders young women and plans to use their body parts to revive the goddess Ishtar. The insane Ramses hypnotizes a socialite in order to land a job catering a party for her debutante daughter, Suzette Fremont, and turns the event into an evening of gruesome deaths, bloody dismemberment and ritual sacrifice.', '1963-07-06', 4.78, 'https://image.tmdb.org/t/p/w500/u6mWxgOrNAF3AaevaGEE4NqCwcQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29193, 'The Spanish Prisoner', 'An inventor of a secret process suddenly finds himself alone as both his friends and the corporation he works for turn against him.', '1997-12-03', 6.82, 'https://image.tmdb.org/t/p/w500/cwkWlWfFrvH6WW6ovX5gfGHo7ks.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29455, 'Winter Light', 'A Swedish pastor fails a loving woman, a suicidal fisherman and God.', '1963-02-11', 7.88, 'https://image.tmdb.org/t/p/w500/wDxrEssdjFWYwIZLbr06RQNcg1q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29461, 'Soul Food', 'Traditional Sunday dinners at Mama Joe''s turn sour when sisters Teri, Bird and Maxine start bringing their problems to the dinner table in this ensemble comedy. When tragedy strikes, it''s up to grandson Ahmad to pull the family together and put the soul back into the family''s weekly gatherings.', '1997-09-26', 6.28, 'https://image.tmdb.org/t/p/w500/97t6YjxjTpwQ439MJcPiPDrMAg0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29478, 'A Raisin in the Sun', 'Walter Lee Younger is a young man struggling with his station in life. Sharing a tiny apartment with his wife, son, sister and mother, he seems like an imprisoned man. Until, that is, the family gets an unexpected financial windfall.', '1961-05-28', 7.70, 'https://image.tmdb.org/t/p/w500/fxGAJFfryAgdi4ONkVyrBWKDBbI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29453, 'The Magician', 'A traveling magician and his troupe arrive in a Swedish town in the 1840s, where their act is scrutinized by local authorities and a skeptical medical official. Their stay leads to a series of confrontations that test the boundaries between performance, belief, and deception.', '1958-12-26', 7.30, 'https://image.tmdb.org/t/p/w500/46DEYkr96MxzUmdwgmj2U7gWokZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29492, 'Reform School Girls', 'Jenny is sent to a women''s reform school. It is run by evil warden Sutter and her henchwoman Edna. Jenny will stop at nothing to escape but she also has to deal with Charlie the bully.', '1986-08-22', 5.68, 'https://image.tmdb.org/t/p/w500/vcAnrOJgGsXDCas67P4VPLVVBkA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29515, 'The Mack', 'A recently-released convict becomes the most powerful pimp in Oakland, but tragedy ensues when his activities draw the ire of two corrupt cops and the crime lord he once worked for.', '1973-04-04', 6.40, 'https://image.tmdb.org/t/p/w500/xcS9bxWGFzC3cA7qAOjcIjKajSf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29572, 'The Man Who Cried', 'A young refugee travels from Russia to America in search of her lost father and falls in love with a gypsy horseman.', '2000-08-29', 6.11, 'https://image.tmdb.org/t/p/w500/vCwee9sPHD2lxgo1ISlHve384oc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29578, 'The Seven-Per-Cent Solution', 'Concerned about his friend''s cocaine use, Dr. Watson tricks Sherlock Holmes into travelling to Vienna, where Holmes enters the care of Sigmund Freud. Freud attempts to solve the mysteries of Holmes'' subconscious, while Holmes devotes himself to solving a mystery involving the kidnapping of Lola Deveraux.', '1976-10-24', 6.20, 'https://image.tmdb.org/t/p/w500/wvrFj27OmsrTC04n57huYciFFPT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29592, 'Lust for Life', 'An intense and imaginative artist, revered Dutch painter Vincent van Gogh possesses undeniable talent, but he is plagued by mental problems and frustrations with failure. Supported by his brother, Theo, the tormented Van Gogh eventually leaves Holland for France, where he meets volatile fellow painter Paul Gauguin and struggles to find greater inspiration.', '1956-09-15', 7.20, 'https://image.tmdb.org/t/p/w500/rlK3LG3W41eF3N1tk0SEM7Dln2x.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29595, 'Wal-Mart: The High Cost of Low Price', 'This documentary takes the viewer on a deeply personal journey into the everyday lives of families struggling to fight Goliath. From a family business owner in the Midwest to a preacher in California, from workers in Florida to a poet in Mexico, dozens of film crews on three continents bring the intensely personal stories of an assault on families and American values.', '2005-11-04', 6.24, 'https://image.tmdb.org/t/p/w500/6PYx4HEbczd9QUCex5Wspkhjef5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29621, 'Solo', 'An android fighting-machine is charged with destroying a small brigade of rebels in a Latin American war who are fighting to maintain their freedom and protect their village. Contrary to his programming, Peebles decides to stay and assist the rebels in their plight. Having gained this information, his "creators" develop a more powerful android to try and defeat him.', '1996-08-23', 4.96, 'https://image.tmdb.org/t/p/w500/9qqdpyYVnU5zY5KsTKCIp5gpZoV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29587, 'Style Wars', 'Tony Silver and Henry Chalfant''s PBS documentary tracks the rise and fall of subway graffiti in New York in the late 1970s and early 1980s.', '1984-01-23', 7.54, 'https://image.tmdb.org/t/p/w500/vgW7eMrK8Y8u91vG9R9iff4tsIP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29649, 'Sunset Park', 'A white teacher takes over a talented, but undisciplined Black high school basketball team and turns them into winners.', '1996-04-26', 6.48, 'https://image.tmdb.org/t/p/w500/rkt8cYfOV6vcqlDbut7jak9qaPh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29702, 'Tenebre', 'A razor-wielding serial killer is on the loose, murdering those around Peter Neal, an American mystery author in Italy to promote his newest novel.', '1982-10-28', 6.79, 'https://image.tmdb.org/t/p/w500/uWNCyUX9sjtnhleqyw2W5ECijlP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28178, 'Hachi: A Dog''s Tale', 'Professor Wilson discovers a lost Akita puppy on his way home. Despite objections from his wife, Hachi endears himself to the family and grows to be Parker''s loyal companion. As their bond grows deeper, a beautiful relationship unfolds.', '2009-06-08', 8.01, 'https://image.tmdb.org/t/p/w500/lsy3aEsEfYIHdLRk4dontZ4s85h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29715, 'Major Dundee', 'During the last winter of the Civil War, cavalry officer Amos Dundee leads a contentious troop of Army regulars, Confederate prisoners and scouts on an expedition into Mexico to destroy a band of Apaches who have been raiding U.S. bases in Texas.', '1965-03-15', 6.70, 'https://image.tmdb.org/t/p/w500/afdhdupMyfn3tDoL3XosgQF82gX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29740, 'I Am a Fugitive from a Chain Gang', 'A World War I veteran’s dreams of becoming a master architect evaporate in the cold light of economic realities. Things get even worse when he’s falsely convicted of a crime and sent to work on a chain gang.', '1932-11-09', 7.78, 'https://image.tmdb.org/t/p/w500/jer6lim61i8V6a5HOZq2i07UQQf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29743, 'Attila Scourge of God', 'The misadventures of Attila and his band of barbarians as they take up arms against the Roman Empire in their native Milano', '1982-12-22', 6.00, 'https://image.tmdb.org/t/p/w500/ecizJo3j1PPvLBMhl3thYk82rXK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29786, 'North Dallas Forty', 'A semi-fictional account of life as a professional football player. Loosely based on the Dallas Cowboys team of the early 1970s.', '1979-08-03', 6.65, 'https://image.tmdb.org/t/p/w500/v5TjfmQT81YTJYs398ZbKWWoEKV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29756, '13 Ghosts', 'The reclusive Dr. Zorba has died and left his sprawling mansion to his nephew Cyrus and his family. They will need to search the house to find the doctor''s fortune, but along with the property itself, they have also inherited the occultist''s collection of thirteen ghosts.', '1960-05-16', 5.80, 'https://image.tmdb.org/t/p/w500/8CyQj2VIfmGzjvdoLwYLyT8h4YS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29794, 'Howling II: Stirba - Werewolf Bitch', 'When a young journalist dies in violent circumstances, her brother soon learns, by way of the mysterious Stefan Crosscoe, that his sister has succumbed to the werewolf curse.', '1985-08-28', 4.91, 'https://image.tmdb.org/t/p/w500/zeVbDQ4FuyiKRZWOLubRuFiGkqV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29787, 'Monkey Shines', 'A quadriplegic man is given a trained monkey help him with every day activities, until the little monkey begins to develop feelings, and rage, against its new master and those who get too close to him.', '1988-07-29', 6.31, 'https://image.tmdb.org/t/p/w500/zbxrAWN2Ss5RXK1uDvMW82xFh0n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29825, 'The Real Blonde', 'An aspiring actor and his girlfriend handle life''s frustrations, while his friend seeks fulfillment with a blonde.', '1998-02-27', 5.33, 'https://image.tmdb.org/t/p/w500/kJucBNGwwTT4n4pSHU1b44nyju4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29911, 'FairyTale: A True Story', 'In 1917, two children take a photograph, which is soon believed by some to be the first scientific evidence of the existence of fairies. Based on the true story of the Cottingley Fairies.', '1997-10-24', 6.38, 'https://image.tmdb.org/t/p/w500/5H86i0qE8zCAbg0vTBKG7S7I2Vi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29845, 'A Woman Under the Influence', 'Mabel Longhetti, desperate and lonely, is married to a Los Angeles municipal construction worker, Nick. Increasingly unstable, especially in the company of others, she craves happiness, but her extremely volatile behavior convinces Nick that she poses a danger to their family and decides to commit her to an institution for six months. Alone with a trio of kids to raise on his own, he awaits her return, which holds more than a few surprises.', '1974-11-18', 7.80, 'https://image.tmdb.org/t/p/w500/6EJ4JoTxnH1QmGTE9pPzgtW1cLW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29917, 'Exam', 'Eight talented candidates have reached the final stage of selection to join the ranks of a mysterious and powerful corporation. Entering a windowless room, where an armed guard keeps watch, they are given 80 minutes to answer one simple question.', '2009-06-19', 6.68, 'https://image.tmdb.org/t/p/w500/i1J2zBCyOQJKsQipqJ0qXERC1Ma.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29918, 'Lassie', 'On their way to start a new life at a sheep farm in rural Virginia, the Turner family are halted by a wreck on the highway that has claimed the life of a truck driver. Spotting the trucker''s now-abandoned collie on the side of the road, they take pity on the dog and adopt her. As the city family copes with the change to rural life, including a feud with a neighboring farm family who resent the city interlopers, the ever-loyal Lassie helps them adjust to their new surroundings.', '1994-07-22', 6.13, 'https://image.tmdb.org/t/p/w500/mz8nOwwuOntjoBuIxNXePLzjZ32.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29963, 'Bright Star', 'In 1818, high-spirited young Fanny Brawne finds herself increasingly intrigued by the handsome but aloof poet John Keats, who lives next door to her family friends the Dilkes. After reading a book of his poetry, she finds herself even more drawn to the taciturn Keats. Although he agrees to teach her about poetry, Keats cannot act on his reciprocated feelings for Fanny, since as a struggling poet he has no money to support a wife.', '2009-09-18', 6.62, 'https://image.tmdb.org/t/p/w500/csN6y4nq2kaBiegHaGw0DGp4plf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29946, 'The Golden Bowl', 'Wealthy American widower Adam Verver and his daughter Maggie live a refined life in Europe, surrounded by art. Maggie marries impoverished Italian Prince Amerigo, while Adam marries Maggie''s friend Charlotte Stant. The Prince and Charlotte are having an affair, which Maggie discovers and navigates through a silent, psychological battle of wills, ultimately using her cunning to preserve her marriage and protect her father.', '2000-05-14', 5.96, 'https://image.tmdb.org/t/p/w500/xgUcUWu7lirlZbMPz21qo8RhK57.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29937, 'Divided We Fall', 'In 1943, a childless couple, the Čížeks, decide to hide a Jewish refugee, David Wiener, the son of Čížek''s former employer, in the secret pantry of their apartment. Čížek is aware of the danger into which he has brought his household and his neighbours, but he takes helping his fellow man in need for granted. But at the same time, as a largely unheroic hero, he is dying of fear. His personal situation is greatly complicated by the approaching end of the war, when he faces danger from both the Germans and his "honest" fellow Czechs...', '2000-03-15', 7.20, 'https://image.tmdb.org/t/p/w500/6mKiT1zyUHHSCUm1hfZVe4RUhjV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29973, 'Cobb', 'Al Stump is a famous sports-writer chosen by Ty Cobb to co-write his official, authorized ''autobiography'' before his death. Cobb, widely feared and despised, feels misunderstood and wants to set the record straight about ''the greatest ball-player ever,'' in his words.', '1994-12-02', 5.67, 'https://image.tmdb.org/t/p/w500/clOqh9is8vWZvX6AUjF4HtLdQMj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29968, 'Nothing in Common', 'A successful advertising executive finds his freewheeling life crashing to a halt when his parents end their longtime marriage.', '1986-07-29', 5.87, 'https://image.tmdb.org/t/p/w500/m2G6Idl1CKJwOt8aFsnJk08sfDP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29251, 'On Any Sunday', 'Documentary on motorcycle racing featuring stars of the sport, including film star Steve McQueen, a racer in his own right.', '1971-07-28', 6.90, 'https://image.tmdb.org/t/p/w500/pIzXpUuVRXxW2KdczbI6C5vZFeq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29987, 'Facing Windows', 'Overburdened and stuck in a greying marriage, Giovanna takes to caring for a Jewish Holocaust survivor her husband brings home. As she begins to reflect on her life, she turns to the man who lives across from her.', '2003-02-27', 6.95, 'https://image.tmdb.org/t/p/w500/1yeh5uQ6KgvxnInUYE0SYSUWd22.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30018, 'Mother', 'A mother lives quietly with her son. One day, a girl is brutally killed, and the boy is charged with the murder. Now, it''s his mother''s mission to prove him innocent.', '2009-05-28', 7.70, 'https://image.tmdb.org/t/p/w500/8oBnSkZE6GDVugAbLPO6uJd4GcS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30020, 'Taste of Cherry', 'A middle-aged Tehranian man, Mr. Badii is intent on killing himself and seeks someone to bury him after his demise. Driving around the city, the seemingly well-to-do Badii meets with numerous people, including a Muslim student, asking them to take on the job, but initially he has little luck. Eventually, Badii finds a man who is up for the task because he needs the money, but his new associate soon tries to talk him out of committing suicide.', '1997-09-28', 7.71, 'https://image.tmdb.org/t/p/w500/vgPwjgbSdbYWrS1ty8TIZtmi6Tn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (28586, 'Tormented', 'A jazz pianist is haunted by his dead ex-lover''s crawling hand and floating head.', '1960-09-22', 4.92, 'https://image.tmdb.org/t/p/w500/8sGHAZVgizrAO2ixNliGVLDgZwg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29136, 'Flowers for Algernon', 'Charlie Gordon is mentally handicapped and all he wants in life is to be a genius. When he gets picked for experimental surgery it looks like his dream may finally come true. But the surgery has side effects that could could kill Charlie. Can Charlie survive being just plain old "Charlie Gordon" and will his newfound romance survive this test of character?', '2000-02-20', 5.67, 'https://image.tmdb.org/t/p/w500/20dVWa6Ujpsx6nQxaSp0cEhX3Tu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29259, 'Le Trou', 'Four prison inmates have been hatching a plan to literally dig out of jail when another prisoner, Claude Gaspard, is moved into their cell. They take a risk and share their plan with the newcomer. Over the course of three days, the prisoners and friends break through the concrete floor using a bed post and begin to make their way through the sewer system – yet their escape is anything but assured.', '1960-03-18', 8.20, 'https://image.tmdb.org/t/p/w500/xyZhiOz5NHVBUKlpioxjwajy7pm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29146, 'Charly', 'An experiment on a simpleton turns him into a genius. When he discovers what has been done to him he struggles with whether or not what was done to him was right.', '1968-09-23', 6.46, 'https://image.tmdb.org/t/p/w500/uxGt80D4hxEEwGwdOJ5tdVvjXEC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30180, 'Hype!', 'This documentary examines the Seattle scene as it became the focus of a merging of punk rock, heavy metal, and innovation. Building from the grass roots, self-promoted and self-recorded until break-out success of bands like Nirvana brought the record industry to the Pacific Northwest, a phenomenon was born.', '1996-11-08', 7.42, 'https://image.tmdb.org/t/p/w500/vfR9veCwZMZXfpCF5QlnaLFoSr1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30192, 'Standing in the Shadows of Motown', 'In 1959, Berry Gordy Jr. gathered the best musicians from Detroit''s thriving jazz and blues scene to begin cutting songs for his new record company. Over a fourteen year period they were the heartbeat on every hit from Motown''s Detroit era. By the end of their phenomenal run, this unheralded group of musicians had played on more number ones hits than the Beach Boys, the Rolling Stones, Elvis and the Beatles combined - which makes them the greatest hit machine in the history of popular music. They called themselves the Funk Brothers. Forty-one years after they played their first note on a Motown record and three decades since they were all together, the Funk Brothers reunited back in Detroit to play their music and tell their unforgettable story, with the help of archival footage, still photos, narration, interviews, re-creation scenes, 20 Motown master tracks, and twelve new live performances of Motown classics with the Brothers backing up contemporary performers.', '2002-09-11', 7.00, 'https://image.tmdb.org/t/p/w500/rsOTrPTRhBgw5eWAgJISBMiIg5m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30194, 'The Manhattan Project', 'A gifted high school student steals plutonium from the secret nuclear weapons facility in his home town in order to construct his own nuclear bomb, win a national science fair, and expose the government''s secrets.', '1986-06-13', 6.21, 'https://image.tmdb.org/t/p/w500/65RDHC5fLwuvQG1LmKRoQugBqLl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30197, 'The Producers', 'A conniving Broadway producer and his meek accountant plan to profit from charming wealthy old biddies to invest in an overbudget production, and then put on a sure-fire disaster, so nobody will ask for their money back — and what''s more disastrous than a tasteless musical celebrating Adolf Hitler.', '1968-03-18', 7.10, 'https://image.tmdb.org/t/p/w500/9qCIkNWGuRj5lMyeOXwJs8z9nRz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30202, 'Children of the Damned', 'Six children are found spread through out the world that not only have enormous intelligence, but identical intelligence and have a strange bond to each other.', '1964-01-10', 6.14, 'https://image.tmdb.org/t/p/w500/l8zpr1tq03YPqdOz6aAmnSpD7o6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29154, 'Stand and Deliver', 'Jaime Escalante is a mathematics teacher in a school in a hispanic neighbourhood. Convinced that his students have potential, he adopts unconventional teaching methods to try and turn gang members and no-hopers into some of the country''s top algebra and calculus students.', '1988-03-11', 7.75, 'https://image.tmdb.org/t/p/w500/A9pfzwk02iNl6i9wyk8lNcBkvc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30237, 'Onegin', 'A virtuous and passionate girl falls in love with a cynical but a dashing aristocrat.', '1999-12-22', 6.10, 'https://image.tmdb.org/t/p/w500/nG5c0Jwy8vxFXZcDMMcrbSCEsrp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30238, 'Earthlings', 'Using hidden cameras and never-before-seen footage, Earthlings chronicles the day-to-day practices of the largest industries in the world, all of which rely entirely on animals for profit.', '2005-09-24', 8.13, 'https://image.tmdb.org/t/p/w500/fcRUYYyDWLJPlX7D6RPtQwdU7G2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30265, 'Chinese Box', 'The story of Hong Kong, from New Year''s Day to June 30th, 1997, when the British left their colony and turned it over to the People''s Republic of China.', '1997-11-14', 5.80, 'https://image.tmdb.org/t/p/w500/e7qXWE5Qbhr55BrjOBi7JG5rI4B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30266, '20,000 Leagues Under the Sea', 'Captain Nemo has built a fantastic submarine for his mission of revenge. He has traveled over 20,000 leagues in search of Charles Denver - a man who caused the death of Princess Daaker. Seeing what he had done, Denver took the daughter to his yacht and sailed away.', '1916-12-24', 6.10, 'https://image.tmdb.org/t/p/w500/edY5eDCC08OUKjS0k7zWUxYM9BB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30062, 'Eaten Alive', 'A psychotic redneck owns a dilapidated hotel in rural East Texas, where he murders those who upset him or his business, and then feeds their remains to his pet crocodile in the swamp beside his hotel.', '1976-12-25', 5.53, 'https://image.tmdb.org/t/p/w500/5RVbWSY0Zo3ggQBVheEfqlpad8h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30295, 'Father Goose', 'During World War II, South Sea beachcomber Walter Eckland is persuaded to spy on planes passing over his island. He gets more than he bargained for as schoolteacher Catherine Frenau arrives on the run from the Japanese with her pupils in tow!', '1964-12-10', 7.05, 'https://image.tmdb.org/t/p/w500/Tp4vSQef0qsI78M90SsZZLJzPE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30296, 'The Malibu Bikini Shop', 'After inheriting a failing bikini shop, two recent grads decide to make a go of it. One, in the hopes of building it into a successful business, the other, in the hopes of getting to look at lots of women in (and out) of swimsuits. As they try more and more outrageous ways of drumming up business, their antics begin attracting some unwanted attention.', '1986-11-01', 4.20, 'https://image.tmdb.org/t/p/w500/qD0Q7Q9K6LSKFtug1heQdjAllvG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30304, 'Picture Bride', 'Riyo, an orphaned 17-year old, sails from Yokohama to Hawaii in 1918 to marry Matsuji, a man she has never met. Hoping to escape a troubled past and start anew, Riyo is bitterly disappointed upon her arrival: her husband is twice her age. The miserable girl finds solace with her new friend Kana, a young mother who helps Riyo accept her new life.', '1995-05-05', 6.50, 'https://image.tmdb.org/t/p/w500/s1lUr4NWgOi4ftXLrUWGI49IvKK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29339, 'Nicholas Nickleby', 'Nicholas Nickleby, a young boy in search of a better life, struggles to save his family and friends from the abusive exploitation of his coldheartedly grasping uncle.', '2002-12-27', 6.84, 'https://image.tmdb.org/t/p/w500/uLilCY2We3Ore9Ke7CdafntHvmT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30309, 'Real Women Have Curves', 'In East Los Angeles, an 18-year-old struggles between her ambitions of going to college and the desires of her domineering mother for her to get married, have children, and oversee the small, rundown family-owned textile factory.', '2002-10-18', 6.09, 'https://image.tmdb.org/t/p/w500/ziemD3ATULYKt399FkO1ZhAwrOH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30330, 'The Late Shift', 'David Letterman vies with Jay Leno and his manager to succeed Johnny Carson, retiring from "The Tonight Show."', '1996-02-24', 6.37, 'https://image.tmdb.org/t/p/w500/8qDU1GxN5jOkA0s4rwgaMu9hfNs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30341, 'Villain', 'In 1970s London, Scotland Yard orchestrates the downfall of mob boss Vic Dakin after he crosses the line by blackmailing Members of Parliament.', '1971-05-26', 6.10, 'https://image.tmdb.org/t/p/w500/45iFu2qhIDrRHfwEPRUsZUaqJlz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30346, 'The Body Snatcher', 'Edinburgh, 1831. Among those who undertake the illegal trade of grave robbery is Gray, ostensibly a cab driver. Formerly a medical student convicted of grave robbery, Gray holds a grudge against Dr. MacFarlane who had escaped detection and punishment.', '1945-05-25', 6.97, 'https://image.tmdb.org/t/p/w500/1dOCP2ahMVlA95SivxhEdVvcXZE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30352, 'Disorganized Crime', 'Lou Diamond Phillips and Fred Gwynne team up with a gang of professional criminals who have everything it takes to rob a bank. The only things they do have going for them are a cop and his partner, who are dumber than they are! By the time the gang hits the bank vault, it''s a safe bet there''s going to be organized insanity and disorganized crime!', '1989-04-14', 5.37, 'https://image.tmdb.org/t/p/w500/rQHt9X3Q4NhDe6LotqUDiZme2l8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30365, 'An Unreasonable Man', 'An Unreasonable Man is a 2006 documentary film that traces the life and career of political activist Ralph Nader, the founder of modern consumer protection. The film examines Nader''s advocacy for auto safety features, such as federally mandated seat belts and air bags, as well as his rise to national prominence following an invasion of privacy lawsuit against General Motors.', '2007-01-31', 7.85, 'https://image.tmdb.org/t/p/w500/g1u0Aelw5r7sJeKrF9ssz7uBeJD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30368, 'Stray Dog', 'A bad day gets worse for young detective Murakami when a pickpocket steals his gun on a hot, crowded bus. Desperate to right the wrong, he goes undercover, scavenging Tokyo’s sweltering streets for the stray dog whose desperation has led him to a life of crime. With each step, cop and criminal’s lives become more intertwined and the investigation becomes an examination of Murakami’s own dark side.', '1949-10-17', 7.59, 'https://image.tmdb.org/t/p/w500/riBzUgeYawBDi2q9PjARjHrQM7Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30416, 'Stanley Kubrick: A Life in Pictures', 'With commentary from Hollywood stars, outtakes from his movies and footage from his youth, this documentary looks at Stanley Kubrick''s life and films. Director Jan Harlan, Kubrick''s brother-in-law and sometime collaborator, interviews heavyweights like Jack Nicholson, Woody Allen and Sydney Pollack, who explain the influence of Kubrick classics like "Dr. Strangelove" and "2001: A Space Odyssey," and how he absorbed visual clues from disposable culture such as television commercials.', '2001-02-17', 7.40, 'https://image.tmdb.org/t/p/w500/yGrzFNyc9ztyAJejneh9734Y9Uj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30459, 'Who''s Afraid of Dracula?', 'Fracchia is desperate: he has to sell a house with at least five bathrooms within three days or his boss will fire him. Incredibly, he and his pal Filini manage to find the perfect house, a castle in Transylvania owned by some count Vlad... things get even worse when they meet the Count and his sister, who has a crush on Fracchia and decides to marry him!', '1985-12-20', 6.11, 'https://image.tmdb.org/t/p/w500/929UzpnRMgolTdyvhr11BpSXTeX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30421, 'A Chinese Ghost Story', 'A naïve young tax collector for the imperial government winds up spending the night in a haunted temple. There he falls in love with a beautiful woman who, unfortunately, is dead. With the aid of a powerful Daoist Swordsman, he must defeat undead hordes, overcome a sinister Tree Demoness, and descend to the pits of hell, to fight for the spirit he loves.', '1987-07-18', 7.31, 'https://image.tmdb.org/t/p/w500/oZitiEjIm1jjsB4bTIEZkawhMpx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30500, 'To Gillian on Her 37th Birthday', 'David loves his wife, Gillian. Unfortunately, she died two years ago. David deals with his grief by continuing his romance with Gillian during walks with her "ghost" on the beach at night. While David lives in the past, other family problems crop up in the present in the real world....', '1996-10-25', 5.50, 'https://image.tmdb.org/t/p/w500/7HGWS6WlsPzBsB7NG5JM4P8NrIv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29161, 'Phenomena', 'A young girl, with an amazing ability to communicate with insects, is transferred to an exclusive Swiss boarding school, where her unusual capability might help solve a string of murders.', '1985-01-25', 6.78, 'https://image.tmdb.org/t/p/w500/dhk14s8ogQkbf6re3HLKV2UBHjx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29204, 'American Pop', 'The history of American popular music runs parallel with the history of a Russian Jewish immigrant family, with each male descendant possessing different musical abilities.', '1981-02-13', 6.89, 'https://image.tmdb.org/t/p/w500/svrATPrggBUauEhCyhiF7K175T9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30140, 'Rivers and Tides', 'Portrait of Andy Goldsworthy, an artist whose specialty is ephemeral sculptures made from elements of nature.', '2001-02-13', 7.28, 'https://image.tmdb.org/t/p/w500/6KmRx9auUqQ2bHCPGi32TS5VSYh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29263, 'The Official Story', 'Buenos Aires, Argentina, 1983. In the last and turbulent days of the military dictatorship, Alicia, a high school history teacher, begins to ask uncomfortable questions about the dark origins of Gaby, her adopted daughter.', '1985-04-03', 7.50, 'https://image.tmdb.org/t/p/w500/kkeUKaETggOrR0eW9nzPOIoZkZH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30506, 'The Princess and the Pirate', 'Princess Margaret is travelling incognito to elope with her true love instead of marrying the man her father has betrothed her to. On the high seas, her ship is attacked by pirates who know her identity and plan to kidnap her and hold her for a king''s ransom.', '1944-11-17', 6.93, 'https://image.tmdb.org/t/p/w500/foAqdD4Xov5q09rLkj4AzRxs9aQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (29264, 'The Exterminating Angel', 'After a lavish dinner party, the guests find themselves unable to depart... and, over the next few days, all of their elaborate societal pretenses and façades deteriorate as they are reduced to living like animals.', '1962-05-16', 7.91, 'https://image.tmdb.org/t/p/w500/qqZXHvBFxUpo8Pfbyvgh4SYMiWm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30497, 'The Texas Chain Saw Massacre', 'Five friends head out to rural Texas to visit the grave of a grandfather. On the way, they stumble across what appears to be a deserted house, only to discover something sinister within. Something armed with a chainsaw.', '1974-10-11', 7.29, 'https://image.tmdb.org/t/p/w500/mpgkRPH1GNkMCgdPk2OMyHzAks7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30685, 'Blood Creek', 'A man and his brother on a mission of revenge become trapped in a harrowing occult experiment dating back to the Third Reich.', '2009-10-09', 5.32, 'https://image.tmdb.org/t/p/w500/3qlC48rdEac3w5STSLayC5X8rhP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30709, '...All the Marbles', 'A two-bit promoter tries to take a women''s wrestling team to the top.', '1981-03-01', 6.10, 'https://image.tmdb.org/t/p/w500/qv0WuNiP93ahEEYDFwC5DcjJmOS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30114, 'Wagons East!', 'After the 1860s Wild West, a group of misfit settlers - including ex-doctor Phil Taylor, prostitute Belle, and homosexual bookseller Julian - decide they cannot live in their current situation in the west. They hire a grizzled alcoholic wagon master by the name of James Harlow to take them on a journey back to their hometowns in the East.', '1994-08-16', 4.87, 'https://image.tmdb.org/t/p/w500/xRYheMiWnjdvUFuXmb1IzjbO9kz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30765, 'The Amazing Panda Adventure', 'Far from home in the lush bamboo forests of China, ten-year-old Ryan Tyler, with the help of a young girl, goes on a wonderful journey to rescue a baby panda taken by poachers.', '1995-08-25', 5.60, 'https://image.tmdb.org/t/p/w500/tIK40vCE9i8g4VhyJ3LLr5y1ROJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30789, 'Venom', 'International terrorists attempt to kidnap a wealthy couple''s child. Their plan comes unstuck, however, when a deadly Black Mamba, sent by mistake instead of a harmless snake, escapes and terrorizes both them and their hostages.', '1981-11-28', 5.69, 'https://image.tmdb.org/t/p/w500/v44VNoH2suoaCPnUj2YyXcvgGfn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30718, 'Last of the Dogmen', 'A Montana bounty hunter is sent into the wilderness to track three escaped prisoners. Instead he sees something that puzzles him. Later with a female Native Indian history professor, he returns to find some answers.', '1995-09-08', 6.78, 'https://image.tmdb.org/t/p/w500/7GkP9w87TAFSXLzJdqxTt0ymbJE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30815, 'Mortal Thoughts', 'A loathsome man ends up dead, but it''s not clear who''s to blame. If ever a person got what he deserved, it''s James Urbanksi, an abusive drunk who steals from his wife, Joyce, and promises her close friend Cynthia Kellogg that she''ll be the next target of his rage. At a group outing, James bleeds to death after someone cuts his throat. But because he''s such a terrible human being, police aren''t sure which of his acquaintances decided to kill him.', '1991-04-19', 5.67, 'https://image.tmdb.org/t/p/w500/3Py7bFBsRjMVdOI5IlNSz6aa385.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30856, 'Gunner Palace', 'American soldiers of the 2/3 Field Artillery, a group known as the "Gunners," tell of their experiences in Baghdad during the Iraq War. Holed up in a bombed out pleasure palace built by Sadaam Hussein, the soldiers endured hostile situations some four months after President George W. Bush declared the end of major combat operations in the country.', '2004-09-11', 6.30, 'https://image.tmdb.org/t/p/w500/tImyhiczrnlmNVbONZiOXDieF4Y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30863, 'Mutant Aliens', 'An unlikely crew – an astronaut, his intrepid daughter, and a quintet of sympathetic, albeit violent, alien creatures – seek revenge against a space industry baron.', '2002-06-14', 6.18, 'https://image.tmdb.org/t/p/w500/f6doYuJsaciPllLKy2VGWGLWXaV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30890, 'Radio Days', 'The Narrator tells us how the radio influenced his childhood in the days before TV. In the New York City of the late 1930s to the New Year''s Eve 1944, this coming-of-age tale mixes the narrator''s experiences with contemporary anecdotes and urban legends of the radio stars.', '1987-01-30', 7.04, 'https://image.tmdb.org/t/p/w500/ljZ3yyYznAiq1vF6nHITdJn6qXB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30892, 'The Ruling Class', 'When the Earl of Gurney dies in a cross-dressing accident, his schizophrenic son, Jack, inherits the Gurney estate. Jack is not the average nobleman; he sings and dances across the estate and thinks he is Jesus reincarnated. Believing that Jack is mentally unfit to own the estate, the Gurney family plots to steal Jack''s inheritance. As their outrageous schemes fail, the family strives to cure Jack of his bizarre behavior, with disastrous results.', '1972-05-24', 6.40, 'https://image.tmdb.org/t/p/w500/29EZjwr3jDFWtdj9Lpq2BtCvKga.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30924, 'Motel Hell', 'Farmer Vincent Smith and his sister Ida run a motel attached to a farm where they capture unsuspecting travelers, bury them alive, fatten them up and then harvest their bodies as ingredients for his famous brand of "smoked meats."', '1980-08-14', 5.78, 'https://image.tmdb.org/t/p/w500/sb63i9ZDqin0Mh37B5sLiZSQY6A.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30943, 'The Deep End of the Ocean', 'A three-year-old boy disappears during his mother''s high school reunion. Nine years later, by chance, he turns up in the town in which the family has just relocated.', '1999-03-12', 6.55, 'https://image.tmdb.org/t/p/w500/4Q8g9CfW7EiwxRCpLSDpOmcaEZb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30948, 'Bloodmoon', 'Ken O''Hara is a "Mindhunter" - a serial killer specialist enlisted to find the mass murderer intent on killing the strongest fighters in New York City. Trying to catch this cunning and clever killer is the hardest assignment Ken has ever had. Now, the moon is rising again and he must use all of his resources to hunt down the murderer....or he may be the next to die.', '1997-06-20', 6.85, 'https://image.tmdb.org/t/p/w500/5cKPA3IyvSJtsMZxxOoSgdrCIoH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30502, 'Big Top Pee-wee', 'Paul Reubens stars as Pee-wee Herman in his second full-length film about a farmer who joins the circus after a storm drops a big tent in his front yard. Pee-wee, along with an outlandish cast of animals and circus performers, puts on the best show ever.', '1988-07-22', 4.98, 'https://image.tmdb.org/t/p/w500/t9AiFl6kt5vMhXzMHTZ6651TECl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30949, 'Palmetto', 'After being released from prison on a bum charge, Harry Barber is out for payback to regain his lost two years. He''s hired by Mrs. Malroux to fake the kidnapping of her stepdaughter (the daughter of a dying millionaire). He discovers that he is being set up on multiple levels and will soon face a longer sentence if he doesn''t prove the truth.', '1998-02-20', 6.00, 'https://image.tmdb.org/t/p/w500/3R8At5ll1ZyCJT7FWbLmCjVqFlp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30950, 'Metroland', 'In late-1970s suburban London, Chris and Marion have settled into a comfortable yet all-too-predictable middle-class existence. Chris receives an unexpected visit from his free-spirited friend Toni, a reunion that reminds him of a more carefree time in 1960s Paris. Now, with lingering doubts about his marriage bubbling up, Chris must make the choice between revisiting his youthful abandon with Toni or facing the here and now with Marion.', '1998-08-21', 5.79, 'https://image.tmdb.org/t/p/w500/qUFYBfOY3Ec2S6PR6apgFwfR6je.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30547, 'The Champ', 'Billy used to be a great boxer, but he''s settled into a hardscrabble life that revolves around drinking, training horses, and the one bright spot in his existence — his young son, T.J. Although Billy has had custody of T.J. since his wife, Annie, left the family years ago, her return prompts a new struggle for the former fighter. Determined to hold on to his son, Billy gets back into the ring to try and recapture his past success.', '1979-07-07', 7.02, 'https://image.tmdb.org/t/p/w500/8GyHL4TftI4SKVA8Jj9JpthhIu6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30963, 'Class Act', 'Duncan is a genius straight A student, Blade is ajuvenile delinquent. But because of a mix up with their school records, everyone thinks each is the other one. Now, Duncan kind of likes the attention from being thought of as a real bad dude, if only the school bully would stop trying to rough him up. And Blade definitely likes being thought of as important instead of as trouble.', '1992-06-05', 6.26, 'https://image.tmdb.org/t/p/w500/bjXz1WkcaOMVZr70GIVqbQ2clWG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30959, 'Kwaidan', 'Taking its title from an archaic Japanese word meaning "ghost story," this anthology adapts four folk tales. A penniless samurai marries for money with tragic results. A man stranded in a blizzard is saved by Yuki the Snow Maiden, but his rescue comes at a cost. Blind musician Hoichi is forced to perform for an audience of ghosts. An author relates the story of a samurai who sees another warrior''s reflection in his teacup.', '1965-01-06', 7.72, 'https://image.tmdb.org/t/p/w500/t9UMfViYl47SdZZatKQ1JKjjCgs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30969, 'Louis C.K.: Chewed Up', 'Profane, vulgar and obscenely funny, Louis C.K. insists on telling the truth, whether you like it or not! Join the Emmy Award-winning stand-up comic and TV star (Lucky Louie) as he shares his thoughts on the stuff everyone thinks about -- male bodily fluids, the joys of being white, the difference between women and girls -- but never has the nerve to say. It''s Louis C.K. at his risk-taking best: fearless, honest and totally outrageous! Nominated for the 2009 Emmy for Outstanding Writing for a Variety, Music or Comedy Special', '2008-10-01', 7.82, 'https://image.tmdb.org/t/p/w500/jJpTrCHb4ETP2zzjA5RQgJHBxed.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30159, 'I Confess', 'When a priest hears a murderer’s confession, he becomes bound by his vow of silence—even as circumstantial evidence turns suspicion toward him. Torn between faith and self-preservation, he faces public scandal and trial for a crime he cannot reveal the truth about.', '1953-02-12', 7.07, 'https://image.tmdb.org/t/p/w500/5IYyJetEctAypFYIffqx55PXTPT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31005, 'Moonlight Mile', 'As he copes with the death of his fiancee along with her parents, a young man must figure out what he wants out of life.', '2002-09-09', 6.31, 'https://image.tmdb.org/t/p/w500/jKDnCPUkL4QsgeqKCtyNMPL2XUU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31000, 'Amos & Andrew', 'When Andrew Sterling, a successful black urbanite writer, buys a vacation home on a resort in New England the police mistake him for a burglar. After surrounding his home with armed men, Chief Tolliver realizes his mistake and to avoid the bad publicity offers a thief in his jail, Amos Odell a deal.', '1993-03-05', 5.45, 'https://image.tmdb.org/t/p/w500/zD2fem9pVsODpUQUgWgoEfdNZyD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31011, 'Mr. Nobody', 'Nemo Nobody leads an ordinary existence with his wife and 3 children; one day, he wakes up as a mortal centenarian in the year 2092.', '2009-11-06', 7.79, 'https://image.tmdb.org/t/p/w500/qNkIONc4Rgmzo23ph7qWp9QfVnW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31037, 'MacArthur', 'The film portrays MacArthur''s life from 1942, before the Battle of Bataan, to 1952, when he was removed from his Korean War command by President Truman for insubordination, and is recounted in flashback as he visits West Point.', '1977-07-15', 6.20, 'https://image.tmdb.org/t/p/w500/i0bcDA4uU3CKMhp715UwWEYG7Tf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31023, 'Butterfly', 'The film centres on Moncho and his coming-of-age experience in Galicia in 1936. Moncho develops a close relationship with his teacher Don Gregorio who introduces the boy to different things in the world. While the story centres on Moncho''s ordinary coming-of-age experiences, tensions related to the looming Spanish Civil War periodically interrupt Moncho''s personal growth and daily life.', '1999-09-24', 7.33, 'https://image.tmdb.org/t/p/w500/iSyRibFKtZL0tvjh6tCxTb6o74s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31016, 'Sidewalks of New York', 'The film follows the marital and dating lives of three men and three women who unknowingly form a tangled web of relationships. Interspersing "man on the street" interviews with scenes from the six characters'' lives, the film weaves a humorous and biting commentary on the game of love -- easy to start, hard to finish.', '2001-11-23', 6.02, 'https://image.tmdb.org/t/p/w500/oJuZGjMUKsYJXSkLXdOZ9CePJhg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31044, 'My Favorite Year', 'Fledgling comic Benjy Stone can''t believe his luck when his childhood hero, the swashbuckling matinee idol Alan Swann, gets booked to appear on the variety show he writes for. But when Swann arrives, he fails to live up to his silver screen image. Instead, he''s a drunken womanizer who suffers from stage fright. Benjy is assigned to look after him before the show, and it''s all he can do to keep his former idol from going completely off the rails.', '1982-10-01', 6.63, 'https://image.tmdb.org/t/p/w500/xksAhZJx1WmHM03OaePNe9IiEBt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31052, 'The Accidental Tourist', 'After the death of his son, travel writer Macon Leary seems to be sleep walking through life. Macon''s wife is having similar problems. They separate, and Macon meets a strange, outgoing woman who brings him ''back down to earth'', but his wife soon thinks their marriage is still worth another try.', '1988-12-23', 6.26, 'https://image.tmdb.org/t/p/w500/dyk2BqPajLRBpVQ6jsSJJdgfuXe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30072, 'Possession', 'Maud Bailey, a brilliant English academic, is researching the life and work of poet Christabel La Motte. Roland Michell is an American scholar in London to study Randolph Henry Ash, now best-known for a collection of poems dedicated to his wife. When Maud and Roland discover a cache of love letters that appear to be from Ash to La Motte, they follow a trail of clues across England, echoing the journey of the couple over a century earlier.', '2002-08-16', 5.98, 'https://image.tmdb.org/t/p/w500/12z5oCy4s3GBOUrNCWvcKYBK4eI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30068, 'Devil''s Playground', 'The Devil''s Playground is a fascinating and moving documentary about a little-known aspect of Amish life. Amish are not permitted to join the church until their late teens, and have to do so of their own volition. The film explores Rumspringa, wherein young Amish are given the opportunity to explore the "English" way of life.', '2002-01-11', 6.58, 'https://image.tmdb.org/t/p/w500/5bOMMSTIDv2YiWP7v3yOr3hHWzx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30080, 'Ship of Fools', 'A varied group of passengers boarding a ship bound for pre-WWII Germany represents a microcosm of early-1930s society.', '1965-07-29', 6.60, 'https://image.tmdb.org/t/p/w500/2LOe4Hu6Gxw6k76hLWhS8JVVILa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30588, 'Monsieur Verdoux', 'The film is about an unemployed banker, Henri Verdoux, and his sociopathic methods of attaining income. While being both loyal and competent in his work, Verdoux has been laid-off. To make money for his wife and child, he marries wealthy widows and then murders them. His crime spree eventually works against him when two particular widows break his normal routine.', '1947-08-27', 7.70, 'https://image.tmdb.org/t/p/w500/mUPXIinTQsBdLlDaWiSl7GwQXVs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30508, 'Berlin Calling', 'A man tours clubs around the globe with his manager and girlfriend. On the eve of their largest album release he is admitted to a psychiatric clinic after overdosing at a gig.', '2008-10-01', 6.82, 'https://image.tmdb.org/t/p/w500/oxEZwuBATJbAdS2JVrALQDnP0Cu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30157, 'Amateur', 'A man wakes up in an alley, bleeding and with no memory of who he is. He stumbles into a coffee shop and is befriended by a charitable ex-nun who is failing in her attempts to write marketable pornography.', '1994-08-05', 6.18, 'https://image.tmdb.org/t/p/w500/n0lFhpnoctfsPo5GXvuvQSgv9Fj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30061, 'Justice League: Crisis on Two Earths', 'A heroic version of Lex Luthor from an alternate universe appears to recruit the Justice League to help save his Earth from the Crime Syndicate, an evil version of the League. What ensues is the ultimate battle of good versus evil in a war that threatens both planets and, through a devious plan launched by Batman''s counterpart Owlman, puts the balance of all existence in peril.', '2010-02-23', 7.31, 'https://image.tmdb.org/t/p/w500/tN2lodc5g7Fkkus6I6Ch2tNTgb5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30055, 'Gigantic (A Tale of Two Johns)', 'John Flansburgh & John Linnell met in the 1970s as junior high students in Lincoln, Massachusetts. A decade later, their band—They Might Be Giants—would stand at the forefront of a burgeoning East Village NYC performance art scene as well as the college music revolution of the late 1980s. Filmed in 2001, ‘Gigantic (A Tale of Two Johns)’ is the acclaimed true story, tracing their independent and sometimes hilarious path through two decades in the pop music wilderness. From their legendary Dial-a-Song answering machine, to their Grammy Award-winning theme song for ‘Malcolm in the Middle’, fans and friends gather to tell the oral history of Brooklyn''s finest alternative rock band.', '2003-05-23', 8.40, 'https://image.tmdb.org/t/p/w500/wUeGidITxUr4lm4q2MgooXft8s3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31063, 'The Calcium Kid', 'When milkman Jimmy Connelly accidentally puts Britain''s contender for the World title out of action, he is propelled from amateur boxer to the world stage and announced as the replacement contender for the championship fight.', '2004-04-30', 5.48, 'https://image.tmdb.org/t/p/w500/eug0h5nFQZTClWpmuf3E3xovsgS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31056, 'A Short Film About Love', '19-year-old Tomek whiles away his lonely life by spying on his opposite neighbour Magda through binoculars. She''s an artist in her mid-thirties, and appears to have everything - not least a constant stream of men at her beck and call. But when the two finally meet, they discover that they have a lot more in common than appeared at first sight...', '1988-08-21', 7.80, 'https://image.tmdb.org/t/p/w500/kLAMz50Or2So1aEzHYv0R8iXo46.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30163, 'The Fugitives', 'Coming out from jail, Lucas has decided to change his life and behave like a good citizen. But when he is taken hostage in a bank by a hare-brained robber, no cops can believe he is not part of the action.', '1986-12-17', 6.80, 'https://image.tmdb.org/t/p/w500/dmrVlsTFOW6RRUpEANVpiOytHFK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30527, 'Shake Hands with the Devil', 'In 1993, Canadian Lieutenant General Roméo Dallaire was sent by the United Nations to Rwanda as commander of the United Nations Assistance Mission for Rwanda (UNAMIR). Its mission, to ensure the ceasefire, is underfunded, excessively bureaucratized and made up of military units which come from dozens of countries and which each have a very different program... These are Lt Gen Dallaire''s efforts to stop the madness of the Rwandan Genocide, despite the complete indifference of his superiors.', '2007-09-28', 7.21, 'https://image.tmdb.org/t/p/w500/5PUO6gBb2w1GIjEvX3nWnvhTXfJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31064, 'The Business of Strangers', 'A dark thriller about a successful businesswoman and her young assistant who toy with a slow-witted businessman while stuck at an airport hotel.', '2001-09-13', 5.60, 'https://image.tmdb.org/t/p/w500/5iVwXnV2fraxy6NYzxZ07jMWW0u.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31094, 'Taking Sides', 'One of the most spectacular and renowned conductors of the 1930s, Wilhelm Furtwangler''s reputation rivaled that of Toscanini''s. After the war, he was investigated as part of the Allies'' de-Nazification programme. In the bombed-out Berlin of the immediate post-war period, the Allies slowly bring law and order to bear on an occupied Germany. An American major is given the Furtwangler file, and is told to find everything he can and to prosecute the man ruthlessly. Tough and hard-nosed, Major Steve Arnold sets out to investigate a world of which he knows nothing.', '2002-03-07', 6.30, 'https://image.tmdb.org/t/p/w500/lRkyqGbJC7omaeKgMid8LQcKsLt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30168, 'It Came from Hollywood', 'Dan Aykroyd, John Candy, Gilda Radner and Cheech and Chong present this compilation of classic bad films from the 50''s, 60''s and 70''s. Special features on gorilla pictures, anti-marijuana films and a special tribute to the worst film maker of all-time, Ed Wood.', '1982-10-29', 5.29, 'https://image.tmdb.org/t/p/w500/jf65NC2N5JsKj5h8iM8bXRnVdI5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30178, 'Stuart Little 3: Call of the Wild', 'With school out for the summer,  The Littles are vacationing in a cabin by the lake, and Stuart is so excited he could burst! But when Snowbell the cat is captured by a mean-spirited creature known simply as the Beast, it''s up to Stuart and a skunk named Reeko to rescue him and a few other friends.', '2005-07-14', 5.24, 'https://image.tmdb.org/t/p/w500/zImw7IVg8dxPkqMfT0L33sdsIHC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31361, 'Bustin'' Loose', 'After ex-con Joe Braxton violates his probation, he is given a second chance. All he has to do is drive a group of special kids across the country.', '1981-05-22', 6.20, 'https://image.tmdb.org/t/p/w500/dOs3shYBvRjXG0XSdyKfh47iyYQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31397, 'Alien from L.A.', 'When her archaeologist father disappears on an expedition, Wanda sets out to look for him. What she finds is a secret underground world, where no one believes in life on the surface and where she and her father are taken for spies.', '1988-02-26', 3.50, 'https://image.tmdb.org/t/p/w500/Al8v2ASozhufxTiA7HVL7GAxi3y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31407, 'Teddy Bear', 'En route to London, Bear discovers at the border checkpoint that his passport is missing a few pages, which may prevent him from traveling to the city with the sports team he manages.', '1981-05-04', 7.78, 'https://image.tmdb.org/t/p/w500/mvPR52hepNXBNBezFeLtEorbruo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31102, 'Pollyanna', 'A young girl comes to an embittered town and confronts its attitude with her determination to see the best in life.', '1960-05-19', 6.96, 'https://image.tmdb.org/t/p/w500/9lWkRXg35SjUZXLr10ez8DERvRv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31417, 'Eyes Without a Face', 'Dr. Génessier is riddled with guilt after an accident that he caused disfigures the face of his daughter, the once beautiful Christiane, who outsiders believe is dead. Dr. Génessier, along with accomplice and laboratory assistant Louise, kidnaps young women and brings them to the Génessier mansion. After rendering his victims unconscious, Dr. Génessier removes their faces and attempts to graft them on to Christiane''s.', '1960-01-11', 7.60, 'https://image.tmdb.org/t/p/w500/8y7Z9Gvcq52uOlJlUWyn2epGGRd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31121, 'Shampoo', 'On Election Day, 1968, irresponsible hairdresser and ladies'' man George Roundy is too busy cutting hair and dealing with his girlfriends and mistress Felicia Karpf, whose husband Lester is having an affair with his ex-girlfriend Jackie.', '1975-02-11', 6.05, 'https://image.tmdb.org/t/p/w500/6jmFvXPV6OhtX3AkAVnH7rwdeUJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31139, 'Office Romance', 'Anatoly Novoseltsev is a mousy single father and office stumblebum working at a statistics bureau in Moscow. In the hopes of being promoted, he is coaxed into charming his disagreeable and seemingly unfeeling boss, Ludmila Kalugina, or "Meany" as she''s otherwise known by her subordinates. Helped by his colleagues Olya and Yura, Anatoly attempts to ease the yoke of Ms. Kalugina, and what follows in the wake of his graceless manoeuvres is completely unforeseen, as he awakens a side to her not yet known, even to herself..', '1977-10-26', 7.83, 'https://image.tmdb.org/t/p/w500/21TgZRiA5gDlyCwQEyYqZcqwMgN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31439, 'To Live', 'Married couple Fugui and Jiazhen endure tumultuous events in mid-20th century mainland China as their personal fortunes move from wealthy landownership to peasantry.', '1994-05-18', 8.07, 'https://image.tmdb.org/t/p/w500/bv0qREWTw8TPAtgt22ELp1UlKVl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31442, 'Ivan''s Childhood', 'In WW2, twelve year old Soviet orphan Ivan Bondarev works for the Soviet army as a scout behind the German lines and strikes a friendship with three sympathetic Soviet officers.', '1962-05-09', 7.83, 'https://image.tmdb.org/t/p/w500/trY9ADhXgSExH3DLlFhV5C8aDtw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31459, 'It Runs in the Family', 'This is the story of a dysfunctional New York family, and their attempts to reconcile', '2003-04-25', 5.98, 'https://image.tmdb.org/t/p/w500/xmnZQwgNoTuzPr65QwLAEpFu9UP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31503, 'My Boyfriend''s Back', 'Missy McCloud is the most beautiful girl in school and Johnny Dingle has been in love with her for years. One night, as Johnny tries to stop an armed robbery and save Missy from danger, he''s killed, but resurrected as a zombie not long after. Now, with the help of his mentor, self-proclaimed Zombie Expert Maggie, Johnny must control his flesh-eating urges while trying to win the heart of Missy.', '1993-08-06', 5.70, 'https://image.tmdb.org/t/p/w500/euXyMbBT2QaxiYZf1jJrsa5yGon.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31504, 'Little Big League', 'When the owner of the Minnesota Twins passes away, he bequeaths the team to his preteen grandson. The newly minted head honcho quickly appoints himself manager, causing unrest in an organization that struggles to take orders from a 12-year-old.', '1994-06-29', 5.94, 'https://image.tmdb.org/t/p/w500/ps0GapKs4vuV38XX6VUbTZm8QS6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31510, 'Ben-Hur: A Tale of the Christ', 'Erstwhile childhood friends, Judah Ben-Hur and Messala meet again as adults, this time with Roman officer Messala as conqueror and Judah as a wealthy, though conquered, Israelite. A slip of a brick during a Roman parade causes Judah to be sent off as a galley slave, his property confiscated and his mother and sister imprisoned. Years later, as a result of his determination to stay alive and his willingness to aid his Roman master, Judah returns to his homeland an exalted and wealthy Roman athlete. Unable to find his mother and sister, and believing them dead, he can think of nothing else than revenge against Messala.', '1925-12-25', 7.30, 'https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31511, 'Gold Diggers of 1933', 'When all Broadway shows are shut down during the Depression, a trio of desperate showgirls scheme to bilk a repugnant high society man of his money to keep their show going.', '1933-05-27', 7.21, 'https://image.tmdb.org/t/p/w500/sXsUJsW9fcVT15hfBu9LyU22qmG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31514, 'À Nous la Liberté', 'In this classic French satire, Louis, a convict, escapes from prison and takes on legitimate work, making his way up in the business world. Eventually becoming the head of a successful factory, Louis opts to modernize his company with mechanical innovations. But when his friend Émile finally leaves jail years later and reunites with Louis, the past catches up with them. The two, worried about being apprehended by police, long to flee the confines of industry.', '1931-12-18', 7.00, 'https://image.tmdb.org/t/p/w500/z6XdIxE1CRqSgfOJxX1nGik6CGm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31516, 'On the Town', 'Three sailors wreak havoc as they search for love during a whirlwind 24-hour leave in New York City.', '1949-12-08', 7.00, 'https://image.tmdb.org/t/p/w500/lEU8QQmIayAtPZrCDf2czQgTjQ1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31522, 'A Woman Is a Woman', 'Longing for a baby, a stripper pursues another man in order to make her boyfriend jealous.', '1961-09-06', 7.30, 'https://image.tmdb.org/t/p/w500/xrZu21hriGJQY3qY8nifh2smVHu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31530, 'Shall We Dance', 'Ballet star Petrov arranges to cross the Atlantic aboard the same ship as the dancer and musical star he''s fallen for but barely knows. By the time the ocean liner reaches New York, a little white lie has churned through the rumour mill and turned into a hot gossip item—that the two celebrities are secretly married.', '1937-05-07', 7.29, 'https://image.tmdb.org/t/p/w500/6anwn2NxTw7NwVEEU4qhVwN3Exi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (30618, 'Bunraku', 'In a world with no guns, a mysterious drifter, a bartender and a young samurai plot revenge against a ruthless leader and his army of thugs, headed by nine diverse and deadly assassins.', '2010-09-01', 5.82, 'https://image.tmdb.org/t/p/w500/6VG9XFig4djqZEEot3PGGWeIpkf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31535, 'Chairman of the Board', 'Surfer Edison isn''t able to make ends meet with his inventions or his lifestyle. But then he meets billionaire Armand McMillian, who takes a shine to the young bum — so much so that he leaves his invention company to him upon his death. Unfortunately, Armand''s nephew, Bradford, only gets a surfboard. While Edison manages to run the company successfully, with the help of pretty Natalie, Bradford conspires to take him down.', '1998-03-13', 3.60, 'https://image.tmdb.org/t/p/w500/1eGB1EjaUjGbiuPBAqndlO3khyn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31582, 'Flawless', 'An ultraconservative police officer suffers a debilitating stroke and is assigned to a rehabilitative program that includes singing lessons - with the drag queen next door.', '1999-11-26', 6.14, 'https://image.tmdb.org/t/p/w500/fkwkkUnaTmhaWt2OGBRepYr7yB5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31546, 'American Buffalo', 'Three inner-city losers plan a robbery of a valuable coin in a seedy second-hand junk shop.', '1996-09-13', 5.36, 'https://image.tmdb.org/t/p/w500/tkIMquxwzMzZUrnAv43e3w0eX0F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31586, 'North', 'Eleven-year-old North has had it with his parents. They are always busy with their careers and don''t give North the attention he needs, so he files a lawsuit against them. The judge rules that North should either find new parents or return to his own parents within two months. Thus North starts off on a journey around the world to find parents that really care about him.', '1994-07-22', 5.04, 'https://image.tmdb.org/t/p/w500/e4JEG7dstmurXMUPOW9Jy6UDR9F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31593, 'Cutter''s Way', 'Alex Cutter is a boozy, belligerent and deeply cynical Vietnam veteran whose encounter with a landmine during the war has left him minus an eye, a leg and an arm. When his drifter playboy friend Richard Bone is falsely accused of murder, Cutter sets out for revenge in his own inimitable style.', '1981-03-19', 6.46, 'https://image.tmdb.org/t/p/w500/7IhITThoRNFmJe3fwwx1q6h6k5L.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31606, 'The Package', 'Experienced Green Beret sergeant Johnny Gallagher is escorting a prisoner, Airborne Ranger Thomas Boyette, back to the US, but Boyette escapes and Gallagher must risk life and limb to catch him.', '1989-08-25', 6.08, 'https://image.tmdb.org/t/p/w500/pInBodZ7xrX8JL7KPL4G9kM5gRW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31615, 'The Tale of the Bunny Picnic', 'As they get ready for their annual Bunny Picnic, Bean, a young, imaginative bunny eager to help, is told he''s too little. Hurt, he wanders off into the lettuce patch where he comes face to face with the grumpy old farmer''s junk yard dog! Bean runs and warns the others but no one believes him. Undaunted, little Bean helps the Muppet Bunnies in a big, big way!', '1986-03-26', 7.43, 'https://image.tmdb.org/t/p/w500/dZP2d1R9xCPaFMARWBhvDnmkava.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31165, 'Inside I''m Dancing', 'Michael is a 24-year-old who has cerebral palsy and long-term resident of the Carrigmore Residential Home for the Disabled, run by the formidable Eileen. His life is transformed when the maverick Rory O''Shea moves in.', '2004-10-15', 7.43, 'https://image.tmdb.org/t/p/w500/2umd8KCnjamgEk9RpSUDQ9TltbW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31174, 'Richard III', 'Having helped his brother King Edward IV take the throne of England, the jealous hunchback Richard, Duke of Gloucester, plots to seize power for himself. Masterfully deceiving and plotting against nearly everyone in the royal court, including his eventual wife, Lady Anne, and his brother George, Duke of Clarence, Richard orchestrates a bloody rise to power before finding all his gains jeopardized by those he betrayed.', '1995-12-29', 6.78, 'https://image.tmdb.org/t/p/w500/cBg1AMH1ucPsDlNMfcHlrreQXQX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31206, 'The Jolson Story', 'At the turn of the 20th century, young Asa Yoelson decides to go against the wishes of his cantor father and pursue a career in show business. Gradually working his way up through the vaudeville ranks, Asa — now calling himself Al Jolson — joins a blackface minstrel troupe and soon builds a reputation as a consummate performer. But as his career grows in size, so does his ego, resulting in battles in business as well as in his personal life.', '1946-10-10', 6.75, 'https://image.tmdb.org/t/p/w500/TA8OqACOphikMD16HLeohJqPk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31646, 'Piranha II: The Spawning', 'A scuba diving instructor, her biochemist boyfriend, and her police chief ex-husband try to link a series of bizarre deaths to a mutant strain of piranha fish whose lair is a sunken freighter ship off a Caribbean island resort.', '1982-07-13', 4.28, 'https://image.tmdb.org/t/p/w500/rbcbLYbhc8ZmQmNHAt8E8knij88.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31611, 'White Man''s Burden', 'The story takes place in alternative America where the blacks are members of social elite, and whites are inhabitants of inner city ghettos. Louis Pinnock is a white worker in a chocolate factory, loving husband and father of two children. While delivering a package for black CEO Thaddeus Thomas, he is mistaken for a voyeur and, as a result, loses his job, gets beaten by black cops and his family gets evicted from their home. Desperate Pinnock takes a gun and kidnaps Thomas, demanding justice.', '1995-12-01', 5.08, 'https://image.tmdb.org/t/p/w500/5MPatVYJXPYEGrd9RQiwldBBQvJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31650, 'Someone to Watch Over Me', 'Claire Gregory, an upper class New York personality, witnesses a murder in a luxurious nightclub. Detective Mike Keegan, recently promoted, is assigned to protect her.', '1987-10-09', 5.85, 'https://image.tmdb.org/t/p/w500/7Vqw29y8pkoHaVtwkQcQhBK9oTY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31618, 'Betrayed', 'An FBI agent posing as a combine driver becomes romantically involved with a Midwest farmer who lives a double life as a white supremacist.', '1988-08-26', 6.07, 'https://image.tmdb.org/t/p/w500/eilzKLdafTPGZTq9BhHlsjM70JG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31216, 'I Can''t Think Straight', 'Tala, a London-based Palestinian, is preparing for her elaborate Middle Eastern wedding when she meets Leyla, a young British Indian woman who is dating her best friend. Spirited Christian Tala and shy Muslim Leyla could not be more different from each other, but the attraction is immediate and goes deeper than friendship. But Tala is not ready to accept the implications of the choice her heart has made for her and escapes back to Jordan, while Leyla tries to move on with her new-found life, to the shock of her tradition-loving parents. As Tala''s wedding day approaches, simmering tensions come to boiling point and the pressure mounts for Tala to be true to herself.', '2008-06-01', 7.50, 'https://image.tmdb.org/t/p/w500/ePbH29RdMlz8mDEQyUkxRVcsB73.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31657, 'Coming Home', 'In 1968 California, a Marine officer''s wife falls in love with a former high school classmate who suffered a paralyzing combat injury in the war.', '1978-02-15', 7.01, 'https://image.tmdb.org/t/p/w500/jBsYWNBYNEi5EhT1hC8iexcTsWT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31662, 'Affliction', 'A small town policeman must investigate a suspicious hunting accident. The investigation and other events result in him slowly disintegrating mentally.', '1998-02-12', 6.31, 'https://image.tmdb.org/t/p/w500/hNu8ePwoRyXDQxhLY4iurCVXAQs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31246, 'From Justin to Kelly', 'A waitress from Texas and a college student from Pennsylvania meet during spring break in Fort Lauderdale, Florida and come together through their shared love of singing.', '2003-06-20', 3.25, 'https://image.tmdb.org/t/p/w500/bLLlgQ6nZPGxvAjp0qjTX1wD2hl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31667, 'The Paradine Case', 'In London, barrister Anthony Keane takes the case of Maddalena Paradine, a beautiful woman accused of poisoning her blind husband. Though happily married, Keane becomes infatuated with his enigmatic client and convinced of her innocence. His obsession clouds his judgment as he builds a defense implicating her servant, André Latour—an act that leads to devastating consequences both in court and at home.', '1947-12-29', 6.25, 'https://image.tmdb.org/t/p/w500/faUkygLOpVA8roEYNYyQTX3llnJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31674, 'Cousins', 'When Larry and Maria learn that their respective spouses are cheating on them, they try to turn the tables on them by pretending to have an affair. However, they soon find themselves falling in love.', '1989-02-10', 5.96, 'https://image.tmdb.org/t/p/w500/d8dgW6b17JGaBYC9vzQ3Em0f6Kx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31218, 'The Firm', 'Set in the 1980s, Dom is a teenager who finds himself drawn into the charismatic world of football ''casuals,influenced by the firm''s top boy, Bex. Accepted by the gang for his fast mouth and sense of humor, Dom soon becomes one the boys. But as Bex and his gang clash with rival firms across the country and the violence spirals out of control, Dom realizes he wants out - until he learns it''s not that easy to simply walk away.', '2009-09-18', 5.70, 'https://image.tmdb.org/t/p/w500/1fuJJrud26pZ5zoNvkTbV4DOgpQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31679, 'Eyewitness', 'NYC custodian Daryll Deever is a big fan of local news reporter Tony Sokolow, so he is intrigued when she shows up to cover a story at his workplace. There''s been a murder in the office building, and Tony suspects that Daryll may have insight into the crime, a notion that he furthers to stay close to her. However, when those behind the killing begin to think that he really knows something, they target the pair to keep their secrets hidden.', '1981-02-13', 5.60, 'https://image.tmdb.org/t/p/w500/dxMbBWegmjtPfZNmw6HHJjgZkQt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31681, 'Hell in the Pacific', 'During World War II, a shot-down American pilot and a marooned Japanese navy captain find themselves stranded on the same small uninhabited island in the Pacific Ocean.', '1968-12-19', 7.01, 'https://image.tmdb.org/t/p/w500/kEiJRrDP6m0o96v7n2UMtad4sAF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31608, 'Three Fugitives', 'On his first day after being released from jail for 14 armed bank robberies, Lucas finds himself caught up in someone else''s robbery. Perry has decided to hold up the local bank to raise money so that he can keep his daughter, Meg, and get her the treatment she needs. Dugan, a detective, assumes Lucas helped plan the robbery, and hence Lucas, Perry and Meg become three fugitives.', '1989-01-27', 6.65, 'https://image.tmdb.org/t/p/w500/qUNgtb0LEkRcHGanKHO0B3JWsw9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31685, 'The Hunchback of Notre Dame', 'Paris, France, 1482. Frollo, Chief Justice of benevolent King Louis XI, gets infatuated by the beauty of Esmeralda, a young Romani girl. The hunchback Quasimodo, Frollo''s protege and bell-ringer of Notre Dame, lives in peace among the bells in the heights of the immense cathedral until he is involved by the twisted magistrate in his malicious plans to free himself from Esmeralda''s alleged spell, which he believes to be the devil''s work.', '1939-08-31', 7.33, 'https://image.tmdb.org/t/p/w500/m6fsyHeqSQs4tktk9q3awgo7IzF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31682, 'The Incredible Shrinking Man', 'A dangerous combination of radiation and insecticide causes the unfortunate Scott Carey to shrink, slowly but surely, until he is only a few inches tall. His home becomes a wilderness where he must survive everything from spiders living in the cellar to his beloved cat.', '1957-02-22', 7.48, 'https://image.tmdb.org/t/p/w500/vI7IdqfvsyoQAjAzRWS2fYvUoOu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31692, 'The Public Eye', 'A crime photographer gets involved in a conspiracy.', '1992-10-16', 6.23, 'https://image.tmdb.org/t/p/w500/oiKWmtkGVOHR9Z49qZkkDkCeKyO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31701, 'Cop', 'An obsessive, insubordinate homicide cop is convinced a serial killer is loose in the Hollywood area and disobeys orders in order to catch him.', '1988-02-05', 6.34, 'https://image.tmdb.org/t/p/w500/gvk4Q4Txjegmup4A1QVyQm2Lb6d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31773, 'Libeled Lady', 'When a major newspaper accuses wealthy socialite Connie Allenbury of being a home-wrecker, and she files a multi-million-dollar libel lawsuit, the publication''s frazzled head editor, Warren Haggerty, must find a way to turn the tables on her. Soon Haggerty''s harried fiancée, Gladys Benton, and his dashing friend Bill Chandler are in on a scheme that aims to discredit Connie, with amusing and unexpected results.', '1936-10-09', 7.28, 'https://image.tmdb.org/t/p/w500/mu2zGdHZJ9IASvnQktjGLZ4kU13.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31776, 'Where the Money Is', 'Henry Manning has come up with a new way to break out of prison: fake a stroke and get transferred to a nursing home. It''s a perfect plan, except for one thing: the woman assigned to take care of him at the nursing home, Carol Ann McKay, has a plan of her own.', '2000-04-14', 5.96, 'https://image.tmdb.org/t/p/w500/s6FODEWgJ9XDwKunGLWEmexguUs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31798, 'Roberta', 'Football player John Kent tags along as Huck Haines and the Wabash Indianians travel to an engagement in Paris, only to lose it immediately. John and company visit his aunt, owner of a posh fashion house run by her assistant, Stephanie. There they meet the singer Scharwenka (alias Huck''s old friend Lizzie), who gets the band a job. Meanwhile, Madame Roberta passes away and leaves the business to John and he goes into partnership with Stephanie.', '1935-03-07', 7.08, 'https://image.tmdb.org/t/p/w500/i4apYC87andlqfn5IhbxZN3b8Up.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31805, 'Road to Morocco', 'Two carefree castaways on a desert shore find an Arabian Nights city, where they compete for the luscious Princess Shalmar.', '1942-11-10', 6.89, 'https://image.tmdb.org/t/p/w500/nECM25OC4iJHV1AHPa4CHnzYgyk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31723, 'Women in Trouble', 'Several women (and one girl) in L.A. are hiding something from someone else, or discovering something hidden from them. Maxine, a therapist, discovers her husband cheating on her with the mother of Charlotte, a 13-year old patient. Addy (the other woman) and her sister Doris have withheld from the girl the truth of her parentage. Holly, an adult film actor, isn''t telling her friend Bambi how she feels about her, and another actor, Elektra, who discovers she''s pregnant, hasn''t told the baby''s father that she loves him. A stuck elevator, a car crash, mid-air turbulence, a flight attendant, a shotgun-wielding bartender, and her roommate, who''s a masseuse, help these women communicate.', '2009-11-13', 5.12, 'https://image.tmdb.org/t/p/w500/iY1L1QuJS4PFiw3Kc5fiVBD0gJ0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31835, 'Twentieth Century', 'A temperamental Broadway producer trains an untutored actress, but when she becomes a star, she proves a match for him.', '1934-05-11', 6.80, 'https://image.tmdb.org/t/p/w500/lHZcuD5pEoyoNHqeTEUEyDEDVKi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31867, 'Repo Men', 'In the future, medical technology has advanced to the point where people can buy artificial organs to extend their lives. But if they default on payments, an organization known as the Union sends agents to repossess the organs. Remy is one of the best agents in the business, but when he becomes the recipient of an artificial heart, he finds himself in the same dire straits as his many victims.', '2010-03-18', 6.34, 'https://image.tmdb.org/t/p/w500/1ZA5kEKuA6HgbyzZXXlyU4piNI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31894, 'The Tuskegee Airmen', 'During the Second World War, a special project is begun by the US Army Air Corps to integrate African American pilots into the Fighter Pilot Program. Known as the "Tuskegee Airman" for the name of the airbase at which they were trained, these men were forced to constantly endure harassement, prejudice, and much behind the scenes politics until at last they were able to prove themselves in combat.', '1995-08-25', 7.09, 'https://image.tmdb.org/t/p/w500/jcLTwnisDFnH6VT57NEHVq959PN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31908, 'Ghosts of Mississippi', 'A Mississippi district attorney and the widow of Medgar Evers struggle to bring a white supremacist to justice for the 1963 murder of the civil rights leader.', '1996-12-20', 6.59, 'https://image.tmdb.org/t/p/w500/gu81MbuLTPbw95xWuDuM7ddcCir.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31911, 'Mr. Wonderful', 'Electrician Gus gets the chance to fulfil a childhood dream by buying an old bowling-alley with some of his friends, but first he must find his ex-wife a new husband so he can stop paying alimony.', '1993-10-15', 5.60, 'https://image.tmdb.org/t/p/w500/AtUjyMEXPR41JWZzGfHEzgmrrHq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31924, 'The Morning After', 'Failed actress Alex Sternbergen wakes up hungover one morning in an apartment she does not recognize, unable to remember the previous evening -- and with a dead body in bed next to her. As she tries to piece together the events of the night, Alex cannot totally rely on friends or her estranged husband, Joaquin, for assistance. Only a single ally, loner ex-policeman Turner Kendall, can help her escape her predicament and find the true killer.', '1986-12-25', 5.96, 'https://image.tmdb.org/t/p/w500/kxuR1RpAUWRHKzCwbjg2bw6RTGI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31918, 'The Russians Are Coming! The Russians Are Coming!', 'When a Soviet submarine gets stuck on a sandbar off the coast of a New England island, its commander orders his second-in-command, Lieutenant Rozanov, to get them moving again before there is an international incident. Rozanov seeks assistance from the island locals, including the police chief and a vacationing television writer, while trying to allay their fears of a Communist invasion by claiming he and his crew are Norwegian sailors.', '1966-05-25', 6.50, 'https://image.tmdb.org/t/p/w500/rRGeIp9MOAfFHH3Exr5Ago7hEuq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31965, 'Witchfinder General', 'England, 1645. The cruel civil war between Royalists and Parliamentarians that is ravaging the country causes an era of chaos and legal arbitrariness that allows unscrupulous men to profit by exploiting the absurd superstitions of the peasants; like Matthew Hopkins, a monster disguised as a man who wanders from town to town offering his services as a witch hunter.', '1968-05-17', 6.50, 'https://image.tmdb.org/t/p/w500/5QuF8YbNtOpLbcTlEFSAokUv5sp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31962, 'Shining Through', 'Spirited New Yorker Linda Voss goes to work for international lawyer and secret Office of Strategic Services operative Ed Leland just before World War II. As they fall in love, the United States enters the fight against Hitler, and Linda volunteers to work for Ed spying undercover behind Nazi lines. Assigned to uncover information about a German bomb, Linda also has personal motives to fulfill: discovering the fate of her Jewish family members in Berlin.', '1992-01-31', 6.50, 'https://image.tmdb.org/t/p/w500/wAnvljbemUQluLjCcjgTZs0PXW1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31967, 'Dante''s Inferno: An Animated Epic', 'Dante journeys through the nine circles of Hell -- limbo, lust, gluttony, greed, anger, heresy, violence, fraud and treachery -- in search of his true love, Beatrice. An animated version of the video game of the same name.', '2010-02-09', 6.97, 'https://image.tmdb.org/t/p/w500/nAEGEYTjbli3JoFgyrLn3blxDqi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31634, 'The Amazing Transparent Man', 'An ex-major forces a scientist to develop a invisibility formula, with which he plans to create an invisible army and sell it to the highest bidder. However there are side effects to the formula.', '1960-02-01', 3.99, 'https://image.tmdb.org/t/p/w500/aOME46GMTef0rkseEi4phAo4gRf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31941, 'Who''ll Stop the Rain', 'John, a disillusioned Vietnam War journalist, turns to heroin smuggling. He cons Ray, an equally burnt out veteran into delivering the drugs stateside to his wife. Everything soon falls apart and Ray ends up on the run with John''s wife trying to evade crooked narcotics agents.', '1978-08-02', 6.45, 'https://image.tmdb.org/t/p/w500/rnJepCsvb2adCmEmCSDBqhTV2Wy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31947, 'King Kong Lives', 'After falling from the Twin Towers, Kong lies in a coma for ten years. When his heart begins to fail, scientists engineer an artificial heart, and a giant female ape is captured to serve as a source for a blood transfusion. When Kong awakens following his heart transplant, he senses the nearby presence of the female ape and the two escape to wreak havoc together.', '1986-12-16', 5.21, 'https://image.tmdb.org/t/p/w500/gI37vg2otF348OHxsx97hWCVvNI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31981, 'Jim Jefferies: I Swear to God', 'Jim Jefferies: I Swear to God: The easily offended might do best to avoid Jim Jefferies’ raunchy, rude humor (or at least imbibe the two-drink minimum beforehand), but the Australian-born comedian provides plenty of laughs for everyone else in this HBO special. In I Swear to God, Jefferies continues his patented brand of comedy that once got him punched by an audience member, discussing the idiocy of no-smoking signs, sluts vs. studs, and his father’s Holocaust jokes.', '2009-05-16', 7.31, 'https://image.tmdb.org/t/p/w500/8GyTQCTnXE5JExI9Z8lncyRCpoO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31995, 'Jamaica Inn', 'In early 19th-century Cornwall, young Mary Yellan travels to live with her aunt and uncle at the remote Jamaica Inn, where she discovers the inn is a front for a violent gang of wreckers who lure ships to their doom along the coast. As she becomes entangled in their crimes, Mary must fight to survive and uncover the truth behind the terror that haunts the moors.', '1939-05-11', 6.13, 'https://image.tmdb.org/t/p/w500/qgeBF25h9MYoxJmKvlUj60IGDNz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31997, 'Saboteur', 'Aircraft factory worker Barry Kane flees across the United States after he is wrongly accused of starting the fire that killed his best friend.', '1942-04-22', 6.86, 'https://image.tmdb.org/t/p/w500/iDKOOTymUZg0WAWPcbdP6nPZEFF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32030, 'Hopscotch', 'When CIA operative Miles Kendig deliberately lets KGB agent Yaskov get away, his boss threatens to retire him. Kendig beats him to it, however, destroying his own records and traveling to Austria where he begins work on a memoir that will expose all his former agency''s covert practices. The CIA catches wind of the book and sends other agents after him, initiating a frenetic game of cat and mouse that spans the globe.', '1980-09-26', 7.01, 'https://image.tmdb.org/t/p/w500/7ZTasNoTehrypra0X97zh8Amk3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32044, 'California Split', 'Carefree single guy Charlie Waters rooms with two lovely prostitutes, Barbara Miller and Susan Peters, and lives to gamble. Along with his glum betting buddy, Bill Denny, Charlie sets out on a gambling streak in search of the ever-elusive big payday. While Charlie and Bill have some lucky moments, they also have to contend with serious setbacks that threaten to derail their hedonistic betting binge.', '1974-08-07', 6.55, 'https://image.tmdb.org/t/p/w500/sohTpACV6S7Af07XKkRUUvLNf4k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32043, 'The Guardian', 'Phil and Kate select the winsome young Camilla as a live-in nanny for their newborn child, but the seemingly lovely Camilla is not what she appears to be...', '1990-04-27', 5.68, 'https://image.tmdb.org/t/p/w500/yIVqiwhkWos3C9gt34ZeEQ0c3xm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32076, 'The Believers', 'Mourning the accidental death of his wife and having just moved to New York with his young son, laconic police psychologist Cal Jamison is reluctantly drawn into a series of grisly, ritualistic murders involving the immolation of two youths.', '1987-06-09', 5.89, 'https://image.tmdb.org/t/p/w500/wMDOgjHoDdKKj3UNZzjP8AW0wxR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31278, 'Pumaman', 'Thousands of years ago, aliens visited Earth and fathered the Pumaman, a man-god with supernatural powers entrusted by a gold mask with the ability to control people''s minds, which in present-day London, falls into the wrong hands.', '1980-02-14', 2.90, 'https://image.tmdb.org/t/p/w500/1cmJeLWhqezudWa168KKy4REFbp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31220, 'Krippendorf''s Tribe', 'After squandering his grant money, despondent and recently widowed anthropologist James Krippendorf must produce hard evidence of the existence of a heretofore undiscovered New Guinea tribe. Grass skirts, makeup, and staged rituals transform his three troubled children into the Shelmikedmu, a primitive culture whose habits enthrall scholars. But when a spiteful rival threatens to blow the whistle on Krippendorf''s ruse, he gets into the act as well.', '1998-02-27', 4.62, 'https://image.tmdb.org/t/p/w500/5mmGI4O1gWYrwpPQ22hgHu9PkIv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31217, 'The Human Condition I: No Greater Love', 'After handing in a report on the treatment of Chinese colonial labor, Kaji is offered the post of labour chief at a large mining operation in Manchuria, which also grants him exemption from military service. He accepts and moves with his newlywed wife Michiko, but when he tries to put his ideas of more humane treatment into practice, he finds himself at odds with scheming officials, cruel foremen, and the military police.', '1959-01-15', 8.10, 'https://image.tmdb.org/t/p/w500/q7godavx5XEbeVxEeqi4pmiOKdI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31640, 'Blood and Wine', 'A man who has failed as a father and husband commits a heist to make money for his fledging business, but things become complicated when his wife interferes.', '1996-10-03', 5.71, 'https://image.tmdb.org/t/p/w500/diFSUAvHZE6rkKqfP3J3qf19Z2X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31638, 'Beyond the Poseidon Adventure', 'After "The Poseidon Adventure", in which the ship got flipped over by a tidal wave, the ship drifts bottom-up in the sea. While the passengers are still on board waiting to be rescued, two rivaling salvage parties enter the ship on search for money, gold and a small amount of plutonium.', '1979-05-18', 5.00, 'https://image.tmdb.org/t/p/w500/wJOIXW4bjsXBPGzqojBV8laiLKM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31225, 'Paris Is Burning', 'Where does voguing come from, and what, exactly, is throwing shade? This landmark documentary provides a vibrant snapshot of the 1980s through the eyes of New York City''s African American and Latinx Harlem drag-ball scene. Made over seven years, PARIS IS BURNING offers an intimate portrait of rival fashion "houses," from fierce contests for trophies to house mothers offering sustenance in a world rampant with homophobia, transphobia, racism, AIDS, and poverty. Featuring legendary voguers, drag queens, and trans women — including Willi Ninja, Pepper LaBeija, Dorian Corey, and Venus Xtravaganza.', '1991-03-13', 8.03, 'https://image.tmdb.org/t/p/w500/90rCWH41mj9hjHUEy2SOHfuAOl3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31306, 'Crazy in Alabama', 'An abused wife heads to California to become a movie star while her nephew back in Alabama has to deal with a racially-motivated murder involving a corrupt sheriff.', '1999-10-22', 6.04, 'https://image.tmdb.org/t/p/w500/bAlevqRg9KG9y725tt4YkNajLrk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32081, 'The Pope of Greenwich Village', 'Charlie and his troublesome cousin Paulie decide to steal $150,000 in order to back a "sure thing" race horse that Paulie has inside information on. The aftermath of the robbery gets them into serious trouble with the local Mafia boss and the corrupt New York City police department.', '1984-06-22', 6.33, 'https://image.tmdb.org/t/p/w500/5U0HNeGoJVK3xic7hK9lz89Ki9i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31337, 'Contact High', 'Gangster boss Carlos orders the dodgy Viennese junkyard owner Harry to bring him a bag from Poland. Harry passes the order on to his "best man" Schorsch. Schorsch, not exactly the brightest, is currently without a driver''s license and completely fixated on the 24-hour car race of Le Mans. So he gives the order to Mao and sends in their place the takeaway lessees Hans and Max to Poland. Their journey leads to a seemingly endless drug trip full of extraordinary phenomena.', '2009-03-19', 6.63, 'https://image.tmdb.org/t/p/w500/uDV8vKdnYb6XJtzZqu4Lqt6m7Yh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31643, 'Jimmy Hollywood', 'Jimmy Alto is an actor wannabe who stumbles into the role of a lifetime. He becomes a vigilante crime-fighter, aided by his sidekick William, who has suffered a head wound and has problems with short-term memory. Jimmy''s vigilante alter ego soon becomes a media wonder--but Jimmy remains a total unknown and his long-suffering girl friend Lorraine is getting fed up with the whole situation.', '1994-03-30', 5.15, 'https://image.tmdb.org/t/p/w500/o066KgKkw32T4ShvgYO7qHDzZt0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31299, 'Little Ashes', 'About the young life and loves of artist Salvador Dalí, filmmaker Luis Buñuel and writer Federico García Lorca.', '2008-10-06', 5.85, 'https://image.tmdb.org/t/p/w500/kXl85gEU0Cs4MrSBbcyZkJQgdGT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32119, 'The Boys of St. Vincent', 'The true story of boys being sexually abused at their orphanage, run by a religious community in Newfoundland.', '1994-06-03', 7.11, 'https://image.tmdb.org/t/p/w500/cam0cG0UWdUVtQRvFHJXmNtL1hY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32294, 'Mr. Blandings Builds His Dream House', 'An advertising executive dreams of getting out of the city and building a perfect home in the country, only to find the transition fraught with problems.', '1948-03-25', 6.96, 'https://image.tmdb.org/t/p/w500/smKM575W3FLvWHna5YaWWeN5po8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31342, 'The Love Letter', 'In the sleepy New England town of Loblolly By The Sea, a letter has arrived that is going to wake things up. It is a love letter - ardent, sensual... and unsigned. As the letter falls into different hands, residents of the small town to eye one another with renewed interest - wondering who it''s for and who it''s from. Determined to find the letter''s author, Helen MacFarquhar begins a quest that will open her life to a new chapter involving two decidedly different men: George, an old friend from her past, and Johnny, a young man very much in her present. Unexpectedly, one mysterious love note has the power to unlock some startling secrets, leaving a trail of wonderful surprises as it turns an entire town upside down.', '1999-05-21', 5.20, 'https://image.tmdb.org/t/p/w500/7w8QCvKDFn1cJ3sW3RGWcwlitgX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32302, '3 Ninjas: High Noon at Mega Mountain', 'Three young boys, Rocky, Colt and Tum Tum together with their neighbor girl, computer whiz Amanda are visiting Mega Mountain amusement park when it is invaded by an army of ninjas led by evil Medusa, who wants to take over the park and hold the owners for ransom. Kids and retired TV star Dave Dragon, who made his farewell appearance at the park at the time the ninjas appeared, have to break Medusa''s vicious plans.', '1998-03-26', 4.84, 'https://image.tmdb.org/t/p/w500/7jKefCfhcXLd1qVnmc1zBhSgPjh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32303, 'Mitchell', 'A tough-guy cop pursues two drug runners across the city to bust a large syndicate.  Very much an anti-hero, Mitchell often ignores the orders of his superiors and demonstrates disdain for by-the-book development work as well as normal social graces.', '1975-09-10', 3.25, 'https://image.tmdb.org/t/p/w500/14Afu2In8RPbdhTacNJl5kRechp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32305, 'Simon Sez', 'A tattooed Interpol agent helps an old classmate find the kidnapped daughter of a computer software tycoon.', '1999-09-24', 2.85, 'https://image.tmdb.org/t/p/w500/uJG7oSRQxacXC2GvzPF2nDoWXIW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32308, 'Ed', 'Jack Cooper could be a world-class baseball pitcher if he didn''t keep buckling under the pressure. He tries to keep his spirits up after he''s traded to a minor league team but loses all hope when he discovers that Ed, one of his teammates, is a chimp. Ed used to be the team mascot, but was promoted to third base when the owners realized he had a talent for baseball. As Jack struggles to get used to his new surroundings, Ed helps him regain his confidence on and off the field.', '1996-03-15', 4.14, 'https://image.tmdb.org/t/p/w500/oSNX3zyTpRMN0ExtOobt7eaJfPD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32326, 'The Cruise', 'Affectionate portrait of Timothy "Speed" Levitch, a tour guide for Manhattan''s Gray Line double-decker buses.', '1998-10-23', 6.93, 'https://image.tmdb.org/t/p/w500/aTPN6ttUQqkqV6ZT762Ihc8hwKi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32318, 'The Navigator', 'The wealthy and impulsive Rollo Treadway decides to propose to his beautiful socialite neighbor, Betsy O''Brien. Although Betsy turns Rollo down, he still opts to go on the cruise that he intended as their honeymoon. When circumstances find both Rollo and Betsy on the wrong ship, they end up having adventures on the high seas.', '1924-09-28', 7.10, 'https://image.tmdb.org/t/p/w500/eFIbnDnBnIi1qnz15UUiMFmjRmL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32325, 'Mi Vida Loca', 'Two Indigenous Latina bestfriends, Mousie and Sad Girl live in a contemporary Los Angeles poor Indigenous Hispanic American neighborhood. But when Sad Girl becomes pregnant by Mousie''s boyfriend, a drug dealer named Ernesto, the two become bitter enemies. While their dispute escalates towards violence, the violence of the world around them soon also impacts their lives.', '1994-06-08', 6.60, 'https://image.tmdb.org/t/p/w500/gtKIaHUqkNqdgVnMFosyVJXvKMC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31648, '12 Chairs', 'A former aristocrat Ippolit Vorobyaninov leads a miserable life in Soviet Russia. His mother-in-law reveals a secret to him - she hid family diamonds in one of the twelve chairs they once had. Vorobyaninov in cooperation with a young con artist Ostap Bender start a long search for the diamonds.', '1971-06-21', 7.66, 'https://image.tmdb.org/t/p/w500/fVzfgLPgrEOti2svUqwyLCtIeML.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32331, 'Stealing Home', 'Billy Wyatt, a former high school and minor-league baseball player, receives a telephone call from his mother revealing that his former child-sitter, and later in his teens, his first love, Katie Chandler, has died. Wyatt returns home to deal with this tragedy, reminiscing over his childhood growing up with his father, Katie, and best friend Alan Appleby.', '1988-08-26', 6.31, 'https://image.tmdb.org/t/p/w500/pwl2DNSO4nnOYUTMubBC2DpMpOQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32334, 'Love and Pigeons', 'In a remote Siberian village, a work injury sends Vasily Kuziakin on a paid trip to a Black Sea resort as compensation. There, he meets femme fatale Raisa Zaharovna and decides to stay with her. Such is the beginning of a new life for him, exciting and strange, but lacking his home, his wife and children, and his pigeons.', '1984-01-07', 7.56, 'https://image.tmdb.org/t/p/w500/njP3HZQpCyI9vDyVAHjYqMKdYNC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32430, 'The Bells of St. Mary''s', 'Father O''Malley is sent to St. Mary''s, a run-down parochial school on the verge of condemnation. He and Sister Benedict work together in an attempt to save the school, though their differing methods often lead to good-natured disagreements.', '1945-12-27', 6.80, 'https://image.tmdb.org/t/p/w500/e2REwGOzsD21acHSRcXcXzkQmUi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32488, 'Days of Wine and Roses', 'An alcoholic falls in love with and gets married to a young woman, whom he systematically addicts to booze so they can share his "passion" together.', '1963-02-04', 7.50, 'https://image.tmdb.org/t/p/w500/cRVl1BR3x3P2NqUv61eveJNJ0ip.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32489, 'Thoroughly Modern Millie', 'Millie Dillmount, a fearless young lady fresh from Salina, Kansas, determined to experience Life, sets out to see the world in the rip-roaring Twenties. With high spirits and wearing one of those new high hemlines, she arrives in New York to test the "modern" ideas she had been reading about back in Kansas: "I''ve taken the girl out of Kansas. Now I have to take Kansas out of the girl!"', '1967-03-22', 6.80, 'https://image.tmdb.org/t/p/w500/ce8rBGFR0naGsp6mKy9CNKn9iSa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32456, 'Two Girls and a Guy', 'Two women confront their boyfriend, a two-timing actor who professed eternal love to each.', '1998-04-24', 5.21, 'https://image.tmdb.org/t/p/w500/9Hj90OgXLBReJCAGqOOzzxjZfCh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32458, 'Forgotten Silver', 'The life story of Colin McKenzie, a forgotten pioneer of international cinema who was born in rural New Zealand in 1888.', '1997-09-11', 7.20, 'https://image.tmdb.org/t/p/w500/gSLluaJR2fxmsGOtmfSKQJ9RCly.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (31357, 'Waiting to Exhale', 'Cheated on, mistreated and stepped on, the women are holding their breath, waiting for the elusive "good man" to break a string of less-than-stellar lovers. Friends and confidants Vannah, Bernie, Glo and Robin talk it all out, determined to find a better way to breathe.', '1995-12-22', 6.21, 'https://image.tmdb.org/t/p/w500/4wjGMwPsdlvi025ZqR4rXnFDvBz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32499, 'The Bad and the Beautiful', 'Told in flashback form, the film traces the rise and fall of a tough, ambitious Hollywood producer, Jonathan Shields, as seen through the eyes of various acquaintances, including a writer, James Lee Bartlow; a star, Georgia Lorrison; and a director, Fred Amiel. He is a hard-driving, ambitious man who ruthlessly uses everyone on the way to becoming one of Hollywood''s top movie makers.', '1952-12-25', 7.27, 'https://image.tmdb.org/t/p/w500/ajAXzTiPkL7JxeCRw5lQBqrKNGx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32513, 'Cold Comfort Farm', 'In this adaptation of the satirical British novel, Flora Poste, a plucky London society girl orphaned at age 19, finds a new home with some rough relatives, the Starkadders of Cold Comfort Farm. With a take-charge attitude and some encouragement from her mischievous friend, Mary, Flora changes the Starkadders'' lives forever when she settles into their rustic estate, bringing the backward clan up to date and finding inspiration for her novel in the process.', '1995-01-01', 6.80, 'https://image.tmdb.org/t/p/w500/fkPm7MQhn3YqcRDM9qFDKNHiw7D.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32519, 'Kiss Me, Guido', 'When he discovers his girlfriend having sex with his brother, Frankie decides to head to Manhattan, leaving his Bronx pizza shop forever for the fame and fortune of show business. But before stardom, he needs a place to stay. Looking in the personals, he notices GWM. And thinking it "Guy with Money," he heads to the Village and the apartment of gay actor Warren, who''s in desperate need of this month''s rent.', '1997-07-18', 5.02, 'https://image.tmdb.org/t/p/w500/3aFhsB4ez8ViUofXMaSI9k7bT1m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32567, 'The Endurance', 'Documentary on the Shackleton Antartic expedition. A retelling of Sir Ernest Shackleton''s ill-fated expedition to Antarctica in and the crew of his vessel ''The Endurance'', which was trapped in the ice floes and frigid open ocean of the Antarctic in 1914. Shackleton decided, with many of his crew injured and weak from exposure and starvation, to take a team of his fittest men and attempt to find help. Setting out in appalling conditions with hopelessly inadequate equipment, they endured all weather and terrain and finally reached safety. Persuading a local team of his confidence that the abandoned team would still be alive, he set out again to find them. After almost 2 years trapped on the ice, all members of the crew were finally rescued.', '2000-09-02', 6.97, 'https://image.tmdb.org/t/p/w500/7zWvRlfnDTbmcGw8F28PEx7KX2k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32588, 'Uncle Nino', 'A distant, slightly dysfunctional family is brought closer together when the father''s long-estranged Uncle Nino comes from Italy to Chicago for a surprise visit.', '2003-12-05', 7.50, 'https://image.tmdb.org/t/p/w500/pDFuadX5kpzzUnwiPCB178AF03j.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32611, 'Babes in Toyland', 'All roads lead to magical, merry Toyland as Mary Contrary and Tom Piper prepare for their wedding! But villainous Barnaby wants Mary for himself, so he kidnaps Tom, setting off a series of comic chases, searches, and double-crosses! The "March Of The Wooden Soldiers" helps put Barnaby in his place, and ensures a "happily ever after" for Tom and Mary!', '1961-12-14', 5.87, 'https://image.tmdb.org/t/p/w500/pPNVXVQTCgdUiIiyxxYlTTqkgiZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32562, 'The Celluloid Closet', 'Exuberant, eye-opening movie that serves up a dazzling hundred-year history of the role of gay men and lesbians have had on the silver screen. Film contains fabulous footage from 120 films showing the changing face of cinema sexuality, from cruel stereotypes to covert love to the activist triumphs of the 1990s.', '1996-03-15', 7.24, 'https://image.tmdb.org/t/p/w500/x0DSh3uMeQk6EG1DHjGJUywN7C0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32031, 'Let''s Get Harry', 'Harry Burck has been kidnapped by South American terrorists, and when the US Government refuses to intervene, Harry''s friends decide to take matters into their own hands!', '1986-10-31', 6.20, 'https://image.tmdb.org/t/p/w500/qyKxAZbcnzmn24oATeUX7DqQ7aB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32590, 'The Center of the World', 'A couple checks into a suite in Las Vegas. In flashbacks we see that he''s a computer whiz on the verge of becoming a dot.com millionaire, she''s a lap dancer at a club. He''s depressed, withdrawing from work, missing meetings with investors. He wants a connection, so he offers her $10,000 to spend three nights with him in Vegas, and she accepts with conditions. Is mutual attraction stirring?', '2001-04-19', 5.22, 'https://image.tmdb.org/t/p/w500/lmcabkCsSQ08yll4dIVclWc2RSX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32058, 'Making Mr. Right', 'When image consultant Frankie Stone is hired by a tech company to teach a scientist’s “Ulysses Robot” how to be a man, she winds up developing very real feelings for the faux human.', '1987-04-03', 5.19, 'https://image.tmdb.org/t/p/w500/qsJFNUQz1ObK85kRk06ahyW5dKr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32643, 'The Love Bug', 'The inimitable VW Beetle is losing all his races and destined for the scrap heap until mechanic Hank takes him over and gives him a new lease of life. Soon, Herbie is winning again, to the fury of his previous owner, who builds a menacing black bug to challenge Herbie to the ultimate race.', '1997-11-29', 5.71, 'https://image.tmdb.org/t/p/w500/2V6aoZvvcjZcvT9050zuLa38jxW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32059, 'The January Man', 'Nick and Frank Starkey were both policemen. A scandal forced Nick to leave the force, now a serial killer has driven the police to take him back. A web that includes Frank''s wife, bribery, and corruption all are in the background as Nick tries to uncover the secret of where the killer will strike next, and finally must lay a trap without the police.', '1989-01-13', 5.03, 'https://image.tmdb.org/t/p/w500/5CZznrNvFLacr0mb4CYmlpJ4Tsw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32568, 'The Man in the White Suit', 'The unassuming, nebbishy inventor Sidney Stratton creates a miraculous fabric that will never be dirty or worn out. Clearly he can make a fortune selling clothes made of the material, but may cause a crisis in the process. After all, once someone buys one of his suits they won''t ever have to fix them or buy another one, and the clothing industry will collapse overnight. Nevertheless, Sidney is determined to put his invention on the market, forcing the clothing factory bigwigs to resort to more desperate measures...', '1951-08-07', 6.90, 'https://image.tmdb.org/t/p/w500/laTLoNZB7Ar3ZDoQmspBDVa5mbC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32657, 'Percy Jackson & the Olympians: The Lightning Thief', 'Accident prone teenager, Percy discovers he''s actually a demi-God, the son of Poseidon, and he is needed when Zeus'' lightning is stolen. Percy must master his new found skills in order to prevent a war between the Gods that could devastate the entire world.', '2010-02-01', 6.21, 'https://image.tmdb.org/t/p/w500/brzpTyZ5bnM7s53C1KSk1TmrMO6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32669, 'The Two Jakes', 'Real estate developer Jake Berman hires private investigator and war veteran Jake Gittes for some run-of-the-mill matrimonial work. After Berman shoots his wife''s lover, who happens to be his business partner, Gittes is drawn into a web of conspiracy and deceit involving the oil reserves beneath Los Angeles. While investigating, Gittes hears a voice from his past that causes him to revisit a traumatic case in Chinatown.', '1990-08-10', 5.97, 'https://image.tmdb.org/t/p/w500/49DSKcjPUdLjzyMpf8OIKep0cLN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32685, 'Ernest Scared Stupid', 'Well-intentioned, eternally bumbling Ernest P. Worrell accidentally releases an evil demon from its sacred tomb. As the demon flexes its power and goes on a ruinous rampage, good-guy Ernest tries to step in to save the town from mass destruction. Trouble is, a 200-year-old curse has scared Ernest stupid, and that means hilarity all around! So, kick back and let the laugh-ridden adventures begin.', '1991-10-11', 5.35, 'https://image.tmdb.org/t/p/w500/qnMtX8eKFFrJVEPZijFZqzDbckK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32686, 'Gray''s Anatomy', 'The film documents, in an often dramatic and humorous fashion, Gray''s investigations into alternative medicine for an eye condition (Macular pucker) he had developed.', '1996-09-11', 6.50, 'https://image.tmdb.org/t/p/w500/w9oYXUfwezTBqcLE8qTWSZ3p8KL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32688, 'Mondo Cane', 'A documentary consisting of a series of travelogue vignettes providing glimpses into cultural practices throughout the world intended to shock or surprise, including an insect banquet and a memorable look at a practicing South Pacific cargo cult.', '1962-03-30', 6.24, 'https://image.tmdb.org/t/p/w500/kw8MBBknqE0GO7JuP7F3QDIHLt9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32823, 'Get Him to the Greek', 'Pinnacle records has the perfect plan to get their sinking company back on track: a comeback concert in LA featuring Aldous Snow, a fading rockstar who has dropped off the radar in recent years. Record company intern Aaron Green is faced with the monumental task of bringing his idol, out of control rock star Aldous Snow, back to LA for his comeback show.', '2010-06-03', 5.96, 'https://image.tmdb.org/t/p/w500/6g0li87w8LIK77QRUtOkQkM6bD7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32847, 'Now, Voyager', 'A woman suffers a nervous breakdown and from an oppressive mother before being freed by the love of a man she meets on a cruise.', '1942-10-22', 7.40, 'https://image.tmdb.org/t/p/w500/kWtJ1C98fQB1fUDSfqb1NGBPPK8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32068, 'The Scalphunters', 'Forced to trade his valuable furs for a well-educated escaped slave, a rugged trapper vows to recover the pelts from the Indians and later the renegades that killed them.', '1968-02-29', 6.41, 'https://image.tmdb.org/t/p/w500/m82aMr1Pcqt5t0cpSCwq5REdajY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32836, 'Bill Burr: Why Do I Do This?', 'One of America''s fastest-rising comedians, Bill Burr wields his razor-sharp wit with rare skill. In this brand-new stand-up performance, Bill takes aim at the stuff that drives us crazy, political correctness gone haywire, and girlfriends, or as he calls them: relentless psycho robots. A keenly observant social commentator, Bill Burr is also one of the funniest voices in comedy today.', '2008-08-23', 7.70, 'https://image.tmdb.org/t/p/w500/iKycji2aWSOS8at0W4VIEm2cmec.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32574, 'Meet John Doe', 'As a parting shot, fired reporter Ann Mitchell prints a fake letter from unemployed "John Doe," who threatens suicide in protest of social ills. The paper is forced to rehire Ann and hires John Willoughby to impersonate "Doe." Ann and her bosses cynically milk the story for all it''s worth, until the made-up "John Doe" philosophy starts a whole political movement.', '1941-03-14', 7.31, 'https://image.tmdb.org/t/p/w500/dnBZbFE2OGlTGNGBVTn6t83tJtd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32872, '''Til There Was You', 'Two strangers, whose paths are always crossing, finally meet when fate steps in. It took them twenty years to fall in love at first sight.', '1997-05-30', 4.01, 'https://image.tmdb.org/t/p/w500/ndbW89bKquf5gMXgncY2fCkrIa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32891, 'The Severed Heads', 'A short mime adaptation of a Thomas Mann story about a Parisian urchin who makes her living selling human heads.', '1957-03-31', 6.14, 'https://image.tmdb.org/t/p/w500/dKJFtBGBCVr4t1PXG5JvjKNQ4od.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32856, 'Valentine''s Day', 'Intertwining couples and singles in Los Angeles break-up and make-up based on the pressures and expectations of Valentine''s Day.', '2010-02-10', 5.93, 'https://image.tmdb.org/t/p/w500/qOTcfD2DdnOTmhH0r1TOE09VvNh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32911, 'Wide Awake', 'The tale of a ten-year-old boy in a Catholic school who, following the death of his beloved grandfather, embarks on a quest to discover the meaning of life.', '1998-03-20', 5.51, 'https://image.tmdb.org/t/p/w500/xnqLUL2l71KVSaqiz9fbFpXtEFe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32961, 'The Lavender Hill Mob', 'A meek bank clerk who oversees the shipments of bullion joins with an eccentric neighbor to steal gold bars and smuggle them out of the country.', '1951-06-28', 7.19, 'https://image.tmdb.org/t/p/w500/u4mZyim3CwXHu0zVhXjfK8fqoN7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32916, 'Scooby-Doo! Abracadabra-Doo', 'The gang goes on a trip to check on Velma''s younger sister, Madelyn. She''s been studying stage magic at the Whirlen Merlin Magic Academy, where apparently there have been sightings of a giant griffin. The gang decides to investigate.', '2010-02-16', 7.66, 'https://image.tmdb.org/t/p/w500/1cKL7mZW5shP9r9TlTNQX4doMQN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32631, 'The Hunted', 'Paul Racine, a high-powered American business executive in Japan, is catapulted into a maze of danger and intrigue after he and his sexy companion are the targets of assassins hired by the ruthless Kinjo.  To survive, Racine must join forces with a powerful samurai and together they will fight the force of evil in an awesome battle rooted in centuries of brutal conflict.', '1995-02-24', 5.71, 'https://image.tmdb.org/t/p/w500/luCVuKiRBcQjr9MuY9mRCTehjpY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33003, 'Maxed Out', 'Maxed Out takes us on a journey deep inside the American debt-style, where everything seems okay as long as the minimum monthly payment arrives on time. Sure, most of us may have that sinking feeling that something isn''t quite right, but we''re told not to worry. After all, there''s always more credit!', '2006-03-10', 6.84, 'https://image.tmdb.org/t/p/w500/xiZqlsKTPscUCxUzGiAEC2oimnY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33065, 'Alesha Popovich and Tugarin the Dragon', 'Alesha Popovich has to catch Tugarin Zmey and bring back the stolen money with the help of a talking Horse (which talks all the time and has an opinion on everything), a wise granny, a donkey and a beauty Lyubava.', '2004-12-23', 6.85, 'https://image.tmdb.org/t/p/w500/6TbmALbiJNDsEGAmse0Yzp4PDjF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33108, 'The Bremen Town Musicians', 'The adventures of the wandering musicians from Bremen such as Troubadour, Donkey, Dog, Cat and Rooster. In one of the towns Troubadour falls in love with a Princess and makes up a plan how to get the King''s confidence.', '1969-10-10', 7.10, 'https://image.tmdb.org/t/p/w500/93qr4F5vlULIoxINtINuK3Bgcuf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32060, 'Brighton Beach Memoirs', 'Eugene, a young teenage Jewish boy, recalls his memoirs of his time as an adolescent youth. He lives with his parents, his aunt, two cousins, and his brother, Stanley, whom he looks up to and admires. He goes through the hardships of puberty, sexual fantasy, and living the life of a poor boy in a crowded house.', '1986-12-26', 6.60, 'https://image.tmdb.org/t/p/w500/gbvxPS3xCvihxGNLB2xabGnsAoZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32093, 'The Mark of Zorro', 'In 1820 Spain, the son of a California nobleman comes home to find his native land under a villainous dictatorship. On one hand, he plays the useless fop, while on the other, he is the masked avenger Zorro.', '1940-11-08', 7.15, 'https://image.tmdb.org/t/p/w500/bJDonmAPnDV8jDv9jLlsejAdAoL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32625, 'Personal Velocity', 'In a series of three vignettes, three women in turn struggle to free themselves from the men who restrict their personal freedom.', '2002-01-12', 5.89, 'https://image.tmdb.org/t/p/w500/2Jkt0PQBU2lmSm4zQcyJBWvRGpv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32054, 'Hope and Glory', 'A middle-aged man recalls his childhood growing up in and around London during World War II.', '1987-09-03', 6.89, 'https://image.tmdb.org/t/p/w500/4xE9oW222uiaJwMWqAdGQw4puOX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33135, 'Fun', 'Hillary and Bonnie meet one morning by the side of the road. They become fast friends, share their secrets, and, on a rising wave of frenzy, later that afternoon, murder an old woman. They did it, they say later, for fun.', '1994-10-12', 5.66, 'https://image.tmdb.org/t/p/w500/aUjxc8vFItbrBLPgYh0NPNOfCfv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33078, 'A Zed & Two Noughts', 'Identical twin zoologists lose their wives in a car crash caused by a white swan. They become obsessed with the death and decay of animals, and develop a strange and unusual relationship with the driver of the car, a woman who is now an amputee.', '1985-10-04', 7.03, 'https://image.tmdb.org/t/p/w500/55eiU0JNfNRqWbpabsf6NukntI2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32235, 'Northfork', 'The year is 1955, and a great flood is coming to Northfork, Montana. A new hydroelectric dam is about to be installed in the mountains above the town, ready to submerge the valley in the name of progress. It is the responsibility of a six-man Evacuation Committee to relocate the townsfolk to higher ground. Most have duly departed, but a few stubborn stragglers remain – among them a priest caring for a sickly orphan, a boy whose fevered visions are leading him to believe he is a member of a roaming band of lost angels desperately searching for a way home.', '2003-07-11', 5.99, 'https://image.tmdb.org/t/p/w500/jb3qheP75UgVibpnfubotrBDY5v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33258, 'More American Graffiti', 'College graduates deal with Vietnam and other issues of the late ''60s.', '1979-08-03', 5.20, 'https://image.tmdb.org/t/p/w500/dnHmQgxeHqgc1A78hE3AdzhlJsW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32146, 'Body Parts', 'A criminal psychologist loses his arm in a car crash, and becomes one of three patients to have their missing limbs replaced by those belonging to an executed serial killer. One of them dies violently, and disturbing occurrences start happening to the surviving two.', '1991-08-02', 5.85, 'https://image.tmdb.org/t/p/w500/8hFSFiLMy0wnyVaaJ4EHFlPD1yf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33320, 'Millennium Actress', 'Documentary filmmaker Genya Tachibana has tracked down the legendary actress Chiyoko Fujiwara, who mysteriously vanished at the height of her career. When he presents her with a key she had lost and thought was gone forever, the filmmaker could not have imagined that it would not only unlock the long-held secrets of Chiyoko’s life... but also his own.', '2002-09-14', 7.85, 'https://image.tmdb.org/t/p/w500/p44UXOFBCY5xbpCKEsWpi4filCD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32255, 'The Palm Beach Story', 'A New York inventor, Tom Jeffers, needs cash to develop his big idea, so his adoring wife, Gerry, decides to raise it by divorcing him and marrying an eccentric Florida millionaire, J. D. Hackensacker III.', '1942-08-28', 7.00, 'https://image.tmdb.org/t/p/w500/vl3MVnrUsCa0wRsFTVU0ohbtWy6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33324, 'Harlan County U.S.A.', 'This film documents the coal miners'' strike against the Brookside Mine of the Eastover Mining Company in Harlan County, Kentucky in June, 1973. Eastover''s refusal to sign a contract (when the miners joined with the United Mine Workers of America) led to the strike, which lasted more than a year and included violent battles between gun-toting company thugs/scabs and the picketing miners and their supportive women-folk. Director Barbara Kopple puts the strike into perspective by giving us some background on the historical plight of the miners and some history of the UMWA.  Preserved by the Academy Film Archive in partnership with New York Women in Film & Television in 2004.', '1977-01-23', 7.50, 'https://image.tmdb.org/t/p/w500/p0cyMNsoP5ap0omfhakhImBWTRw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32250, 'Ju-on: The Curse', 'When elementary school teacher Kobayashi investigates the absence of one of his young pupils from the classroom, he finds himself at the doorstep of an anonymous suburban house that harbours a horrible secret, and into which all who enter are doomed.', '2000-02-11', 6.81, 'https://image.tmdb.org/t/p/w500/d5B5mXNPOtsrZWDMjyleqi1gFAr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33339, 'Camp', 'Misfits in their lives back home, a group of young people live it up at musical-theater camp. While the sports counselor is completely ignored, the kids'' spend all their time in rehearsal for a grueling schedule that involves a new show every two weeks. Several personal stories come to the fore.', '2003-09-05', 5.54, 'https://image.tmdb.org/t/p/w500/7aOOZisCXvI26i7wgMqBaWQxTY3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33115, 'Unfaithfully Yours', 'Before he left for a brief European visit, symphony conductor Sir Alfred De Carter casually asked his staid brother-in-law August to look out for his young wife, Daphne, during his absence. August has hired a private detective to keep tabs on her. But when the private eye''s report suggests Daphne might have been canoodling with his secretary, Sir Alfred begins to imagine how he might take his revenge.', '1948-11-05', 7.24, 'https://image.tmdb.org/t/p/w500/kJ5lV3SuD1yHgBPOfKQaJcoR09z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33138, 'The Times of Harvey Milk', 'Harvey Milk was an outspoken human rights activist and one of the first openly gay U.S. politicians elected to public office; even after his assassination in 1978, he continues to inspire disenfranchised people around the world.', '1984-10-07', 7.30, 'https://image.tmdb.org/t/p/w500/icHnX0RALT9Mn8CVhtqBl04jqXi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32284, 'Dream for an Insomniac', 'A girl with insomnia who works in a coffee house has impossibly high standards for her love and fears she will never meet a worthy man. Then in walks a new employee and they click - until she discovers he has a girlfriend. Undaunted, she moves to L.A. with a friend sure that he will dump the girlfriend and follow her. She puts all her faith in fate and hopes for the best.', '1996-04-18', 5.09, 'https://image.tmdb.org/t/p/w500/1hGRcEPnpmgAmfLObym3olCk6tM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32274, 'Cradle Will Rock', 'A true story of politics and art in the 1930s USA, centered around a leftist musical drama and attempts to stop its production.', '1999-12-10', 6.50, 'https://image.tmdb.org/t/p/w500/d8LJWY8kaAIlfMiQLOGglL8VqVT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32275, 'Duel in the Sun', 'Beautiful half-breed Pearl Chavez becomes the ward of her dead father''s first love and finds herself torn between her sons, one good and the other bad.', '1946-12-31', 6.41, 'https://image.tmdb.org/t/p/w500/dW479xuDWrcuFuxr7yfoReztlzF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32636, 'Vanya on 42nd Street', 'An uninterrupted rehearsal of Chekhov''s ''Uncle Vanya'' plays out by a company of actors. The setting: their run-down theater with an unusable stage and crumbling ceiling. The play is shown act by act with the briefest of breaks to move props or for refreshments. The lack of costumes, real props and scenery is soon forgotten.', '1994-10-19', 6.64, 'https://image.tmdb.org/t/p/w500/sYkkHsqXyUcFoLbXt4WNwnRRpT1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32285, 'Cornered!', 'During their nightly poker game a group of lowlifes are terrorized in their own convenience store by a masked killer.', '2009-11-22', 4.30, 'https://image.tmdb.org/t/p/w500/i5abuNGk5ocEZNN8K7SByhZT1Gt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33430, 'Twin Falls Idaho', 'Francis and Blake Falls are Siamese twins who live in a neat little room in a rundown hotel. While sharing some organs, Blake is always fit and Francis is very sickly. Into their world comes a young lady, who turns their world upside down. She gets involved with Blake, and convinces the two to attend a Halloween party, where they can pass themselves off as wearing a costume. Eventually Francis becomes really ill, and they have to be separated. They then face the physical and mental strains that come from their proposed separation.', '1999-07-30', 6.91, 'https://image.tmdb.org/t/p/w500/boBbVY67YhGC4PWuqyQFysP3mN4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33436, 'The Brain', 'Arthur and Anatole are two little robbers. They want to rob money, money that will travel in a special train from Paris to Bruxelles. They don''t know that other people have planned to do the same thing.', '1969-03-07', 7.26, 'https://image.tmdb.org/t/p/w500/wCtaWDaOiGPVEoo7tiPBSH7sQx9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33441, 'Robot Carnival', 'An anthology of various tales told in various styles with robots being the one common element among them.', '1987-07-21', 6.66, 'https://image.tmdb.org/t/p/w500/2DTREQNErBYtZd1isRqdqNbbXA8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33454, 'Scaramouche', 'In 18th-century France, a young man masquerades as an actor to avenge his friend''s murder.', '1952-05-08', 7.00, 'https://image.tmdb.org/t/p/w500/yALSC7jqOsmMtfSPp6ThCuNGjiR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33468, 'The Brain That Wouldn''t Die', 'Dr. Bill Cortner and his fiancée, Jan Compton, are driving to his lab when they get into a horrible car accident. Compton is decapitated. But Cortner is not fazed by this seemingly insurmountable hurdle. His expertise is in transplants, and he is excited to perform the first head transplant. Keeping Compton''s head alive in his lab, Cortner plans the groundbreaking yet unorthodox surgery. First, however, he needs a body.', '1962-02-25', 4.68, 'https://image.tmdb.org/t/p/w500/npg6NH4maZ4NTTWzA71KNCTvQNG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33516, 'Gothic', 'Living on an estate on the shores of Lake Geneva, Lord Byron is visited by Percy and Mary Shelley. Together with Byron''s lover Claire Clairmont, and aided by hallucinogenic substances, they devise an evening of ghoulish tales. However, when confronted by horrors, ostensibly of their own creation, it becomes difficult to tell apparition from reality.', '1987-02-27', 5.70, 'https://image.tmdb.org/t/p/w500/xGXj6wpJimmWkQMahZryM7xB9EX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33506, 'Indian Summer', 'A group of childhood friends, now in their thirties, reunite at Camp Tamakwa. Only a few of the original campers show up, but they still have a good time reminiscing. The people share experiences and grow while at the camp. They are dismayed to discover that the camp''s owner, Unca Lou, is going to close the camp down.', '1993-04-23', 6.27, 'https://image.tmdb.org/t/p/w500/A1gUvZbQ25wsnj7HD8bDwTxOSWy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33517, 'Beyond the Clouds', 'Four tales, each centered on a woman, journey inward to explore the enigmatic reality of their lives, connecting through a single narrative thread.', '1995-10-27', 6.17, 'https://image.tmdb.org/t/p/w500/dFvjnu8NxaGlJUuNHTsaw4Ng5ee.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33518, 'Alligator', 'A baby alligator is flushed down a toilet and survives by eating discarded lab animals that have been injected with growth hormones. The now gigantic animal escapes the city sewers and goes on a rampage, pursued by a cop and a big-game hunter.', '1980-11-14', 6.05, 'https://image.tmdb.org/t/p/w500/bWANAIIeNPzwEmrYUvZFECTbBX6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33519, 'Amityville: A New Generation', 'Keyes, a successful photographer who lives at the border of Skid Row, notices a homeless man with a strange old mirror. Immediately struck by it for reasons he cannot explain, he convinces the man to sell it to him, soon behaving in increasingly erratic and unhinged ways.', '1993-08-01', 4.30, 'https://image.tmdb.org/t/p/w500/9GVRTWFXlPOu5vsM5zD9hUwlVFi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33521, 'Dracula', 'In 1913, charming, seductive, and sinister Count Dracula travels to England seeking an immortal bride.', '1979-07-20', 6.38, 'https://image.tmdb.org/t/p/w500/gU0BMydJQV9HES5fRAEAPs2qw2M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33542, 'Rumble in the Bronx', 'Keong comes from Hong Kong to visit New York for his uncle''s wedding. His uncle runs a market in the Bronx and Keong offers to help out while Uncle is on his honeymoon. During his stay in the Bronx, Keong befriends a neighbor kid and beats up some neighborhood thugs who cause problems at the market. One of those petty thugs in the local gang stumbles into a criminal situation way over his head.', '1995-01-21', 6.86, 'https://image.tmdb.org/t/p/w500/1nAfchiXHQB3iyhK8fCJJEnNs5A.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33525, 'Morons from Outer Space', 'The story begins on a small spaceship docking with a refueling station. On board are a group of four aliens, Bernard, Sandra, Desmond, and Julian. During a particularly tedious period of their stay at the station, the other three begin playing with the ship’s controls while Bernard is outside playing spaceball. They accidentally disconnect his part of the ship, leaving him stranded while they crash into a large blue planet close by...', '1985-03-29', 4.85, 'https://image.tmdb.org/t/p/w500/2C7h2FMGBeMVZNO8IHXd2XjDAx6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33575, 'Pat and Mike', 'Pat Pemberton is a brilliant athlete, except when her domineering fiancé is around. The ladies golf championship is in her reach until she gets flustered by his presence at the final holes. He wants them to get married and forget the whole thing, but she cannot give up on herself that easily. She enlists the help of Mike Conovan, a slightly shady sports promoter. Together they face mobsters, a jealous boxer, and a growing mutual attraction.', '1952-06-13', 6.41, 'https://image.tmdb.org/t/p/w500/6hSJWY1ygsOVAtPEz9Nb5q5FeyA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33602, 'Temple Grandin', 'A biopic of Temple Grandin, an autistic American who has become one of the leading scientists in humane livestock handling.', '2010-02-06', 7.87, 'https://image.tmdb.org/t/p/w500/gQhQ6yEkUkDDo1zugpq46PJN8xZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33152, 'Who Is Cletis Tout?', 'With a hitman’s gun aimed at him, Finch tells the story of how he broke out of jail, fell in love, and took the identity of a man wanted by the Mafia.', '2001-09-12', 5.90, 'https://image.tmdb.org/t/p/w500/udHRTgyZa1Fh2ryrUbInDviJl6T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33613, 'The Girl Who Kicked the Hornet''s Nest', 'After taking a bullet to the head, Salander is under close supervision in a hospital and is set to face trial for attempted murder on her eventual release. With the help of journalist Mikael Blomkvist and his researchers at Millennium magazine, Salander must prove her innocence. In doing this she plays against powerful enemies and her own past.', '2009-11-27', 7.07, 'https://image.tmdb.org/t/p/w500/92byRQBuuiLcfKnBi5NOuipSgV8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33632, 'Sweet Bird of Youth', 'Gigolo and drifter Chance Wayne returns to his hometown as the companion of a faded movie star, Alexandra Del Lago, whom he hopes to use to help him break into the movies. Chance runs into trouble when he finds his ex-girlfriend, the daughter of the local politician Tom "Boss" Finley, who more or less forced him to leave his daughter and the town many years ago.', '1962-03-21', 6.73, 'https://image.tmdb.org/t/p/w500/uA9tl4o8P1hNB3lDBhHKHcNGdtr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32640, 'Wonderland', 'Living in working-class London, Bill, Eileen, and their three grown daughters navigate quiet lives of loneliness: cafe waitress Nadia searches for love through personal ads, hairdresser and single mother Debbie balances casual romance with co-parenting alongside her volatile ex, and expectant mother Molly copes with a partner overwhelmed by impending fatherhood.', '1999-05-13', 6.50, 'https://image.tmdb.org/t/p/w500/xNhql30OzIPJc190czt7qLmpuBd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33667, 'Gentleman''s Agreement', 'A magazine writer poses as a Jew to expose anti-Semitism.', '1947-11-11', 7.00, 'https://image.tmdb.org/t/p/w500/aCCRbcmigPk00f34hpJuWZuvABo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33676, 'Losin'' It', 'In 1965, four Los Angeles school friends -- Woody, Dave, Spider and Wendell -- go on a series of misadventures when they head to Tijuana, Mexico, for a night of cruisin'', causing trouble, and to lose their virginity.', '1983-04-08', 4.90, 'https://image.tmdb.org/t/p/w500/7BQP8GzBW4ZZxqcc5tDH68yNeAI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33668, 'Designing Woman', 'A sportswriter who marries a fashion designer discovers that their mutual interests are few, although each has an intriguing past which makes the other jealous.', '1957-05-16', 6.70, 'https://image.tmdb.org/t/p/w500/5iKj0fkip6j67iwejogjTGmkLZd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33660, 'Shiloh', 'An abused beagle runs away from his owner. On the road, he meets young Marty Preston and follows him home. The boy immediately forms a bond with the dog and names him Shiloh. His stern father won''t let him keep the dog because it belongs to Judd Travers, a local hunter. After Shiloh is mistreated again, he runs away and returns to Marty. Knowing his father will once again make him bring Shiloh back to Judd, he makes a home for the dog in an old shed up the hill from the Prestons'' house and hides him from his family. His secret is soon discovered when a stray attacks the dog one night and he must turn to his father for help.', '1996-11-30', 5.76, 'https://image.tmdb.org/t/p/w500/wRB0cTPBIWHEq4FmWuX6voagePf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33680, 'Grand Hotel', 'Guests at a posh Berlin hotel struggle through worry, scandal, and heartache.', '1932-09-11', 6.97, 'https://image.tmdb.org/t/p/w500/g8xrpXJWzz91R4jL8ybMKMValB2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33723, 'The Eye 3: Infinity', 'Ted, his cousin May, her best friend April and April''s boyfriend, Kofei take a vacation to Thailand to visit their Thai buddy, Chongkwai, who shows them a book of ten ways to see ghosts. And the game begins.', '2005-03-24', 5.13, 'https://image.tmdb.org/t/p/w500/kyGFZeCOMylgpEC4LelxAL86Eeo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33217, 'Diary of a Wimpy Kid', 'Greg Heffley is headed for big things, but first he has to survive the scariest, most humiliating experience of any kid’s life – middle school! That won’t be easy, considering he’s surrounded by hairy-freckled morons, wedgie-loving bullies and a moldy slice of cheese with nuclear cooties!', '2010-03-19', 6.28, 'https://image.tmdb.org/t/p/w500/iLAGiPnSuODt9cn332bkFElrRig.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33740, 'That''s Entertainment!', 'Various MGM stars from yesterday present their favorite musical moments from the studio''s 50 year history.', '1974-06-21', 7.37, 'https://image.tmdb.org/t/p/w500/uao9fRNFxBXC6mqA8WyO01RU4dJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33250, 'Real Life', 'A pushy, narcissistic filmmaker persuades a Phoenix family to let him and his crew film their everyday lives, in the manner of the ground-breaking PBS series "An American Family".', '1979-03-02', 6.60, 'https://image.tmdb.org/t/p/w500/ihN6hpMI8IUGgUvivU5HUT2M16c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33728, 'Captain Newman, M.D.', 'In 1944, Capt. Josiah J. Newman is the doctor in charge of Ward 7, the neuropsychiatric ward, at an Army Air Corps hospital in Arizona. The hospital is under-resourced and Newman scrounges what he needs with the help of his inventive staff, especially Cpl. Jake Leibowitz. The military in general is only just coming to accept psychiatric disorders as legitimate and Newman generally has 6 weeks to cure them or send them on to another facility. There are many patients in the ward and his latest include Colonel Norville Bliss who has dissociated from his past; Capt. Paul Winston who is nearly catatonic after spending 13 months hiding in a cellar behind enemy lines; and 20 year-old Cpl. Jim Tompkins who is severely traumatized after his aircraft was shot down. Others come and go, including Italian prisoners of war, but Newman and team all realize that their success means the men will return to their units.', '1963-12-25', 6.71, 'https://image.tmdb.org/t/p/w500/ovXBWbk3YjOZB5cmiTvdNaDYGKu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (32646, 'Safe', 'Carol White, a Los Angeles housewife in the late 1980s, comes down with a debilitating illness with no clear diagnosis.', '1995-06-23', 6.90, 'https://image.tmdb.org/t/p/w500/2O71QsBkbqdLqQdx2yuNpJ4pFPq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33273, 'Cell 211', 'The story of two men on different sides of a prison riot -- the inmate leading the rebellion and the young guard trapped in the revolt, who poses as a prisoner in a desperate attempt to survive the ordeal.', '2009-11-06', 7.40, 'https://image.tmdb.org/t/p/w500/koap5B3bQHQi3yaZ39vpWR66TGP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33644, 'How Stella Got Her Groove Back', 'Through good times and bad, Stella and Delilah have always had each other. Now, Stella''s so busy building a life that she''s forgotten how to really live. But Delilah is about to change all that. What starts as a quick trip to Jamaica, ends as an exhilarating voyage of self discovery as Stella learns to open her heart and find love – even if it''s with a man 20 years her junior.', '1998-08-14', 5.81, 'https://image.tmdb.org/t/p/w500/ygmuaJDLYxWJo8eNhq0A63hagrQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33222, 'The Revolution Will Not Be Televised', 'Hugo Chavez was a colourful, unpredictable folk hero who was beloved by his nation’s working class. He was elected president of Venezuela in 1998, and proved to be a tough, quixotic opponent to the power structure that wanted to depose him. When he was forcibly removed from office on 11 April 2002, two independent filmmakers were inside the presidential palace.', '2003-03-07', 7.75, 'https://image.tmdb.org/t/p/w500/6OeVe8oGS7vccKjsiuIGTwBlAFk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33689, 'It Takes Two', 'Identical 9-year-olds from very different backgrounds: orphaned Amanda and wealthy Alyssa meet at summer camp and decide to switch places -- and play matchmaker between Alyssa''s dad, Roger, and the kind social worker who cares for Amanda.', '1995-11-17', 6.50, 'https://image.tmdb.org/t/p/w500/4CptjFLiIJXtjc3dykS7vkEHMbw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33743, 'The 5,000 Fingers of Dr. T.', 'Young Bart Collins lives with his widowed mother Heloise. The major blight on Bart''s existence is the hated piano lessons he is forced to endure under the tutelage of the autocratic Dr. Terwilliker. Bart feels that his mother has fallen under Terwilliker''s sinister influence, and gripes to visiting plumber August Zabladowski, without much result. While grimly hammering away at his lessons, Bart dozes off and enters a fantastical musical dream.', '1953-06-19', 6.21, 'https://image.tmdb.org/t/p/w500/5sAxThhLhsQSf4mjrIGHqfKlaAy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33875, 'Pokémon Heroes', 'Ash, Pikachu and the gang try and stop a pair of thieves hiding out in the canals and alleyways of Altomare, the age-old water capital. Joining the adventure are two new legendary Pokémon, a pair of siblings named Latias and Latios, who serve as peacekeepers and protectors of the Soul Dew — a priceless treasure with a mysterious power.', '2002-07-13', 6.73, 'https://image.tmdb.org/t/p/w500/eySv5rdYLW1k6LxepxCNl8ND26R.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33245, 'It''s My Party', 'Nick, a gay, HIV-positive architect, begins to display severe symptoms of AIDS and makes preparations to kill himself before he is unable to function normally. He arranges a party to reconnect and say goodbye to his closest friends and his confused parents. But when his ex-partner, Brandon, a television director who left Nick when he was diagnosed with HIV, shows up, what was supposed to be a celebratory event becomes much more difficult for everyone.', '1996-03-22', 6.33, 'https://image.tmdb.org/t/p/w500/ltrjg99gc3bA3P5E6WaIbGMxWHS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33908, 'Three... Extremes', 'Features an anthology centred on the experiences of a witch doctor, a film-maker and a disgruntled extra determined to take revenge on him, and a novelist as well as her twin sister.', '2004-08-20', 6.79, 'https://image.tmdb.org/t/p/w500/r0UzUF15suxLatzvNK3TQKxp10h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33278, 'Deadly Friend', 'When tragedy strikes his remarkable robot and the beautiful girl next door, lonely teenage genius Paul tries to save them by pushing technology beyond its known limits into a terrifying new realm.', '1986-10-10', 6.17, 'https://image.tmdb.org/t/p/w500/24X1pdzeU9x2QCVDu957tpUA0kp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33909, 'Wall Street: Money Never Sleeps', 'As the global economy teeters on the brink of disaster, a young Wall Street trader partners with disgraced former Wall Street corporate raider Gordon Gekko on a two tiered mission: To alert the financial community to the coming doom, and to find out who was responsible for the death of the young trader''s mentor.', '2010-09-20', 6.09, 'https://image.tmdb.org/t/p/w500/gtonVdZZMWES6GyhasAX0xhUdrF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33954, 'The Hawks and the Sparrows', 'A man and his son take an allegorical stroll through life with a talking bird that spouts social and political philosophy.', '1966-05-04', 7.20, 'https://image.tmdb.org/t/p/w500/4IUw0b8k6vHpuCaAqOSELJwaB7p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34003, 'Turtles Forever', 'Whoa, dude! Worlds collide when the Turtles from one dimension meet the Turtles from another dimension! What the shell is going on? The two Turtle teams must work together to find the Technodrome and undo this multi-dimensional mess!', '2009-11-21', 7.28, 'https://image.tmdb.org/t/p/w500/7PRI4GFIbuLHaYvw1AZEt19riIO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34014, 'Moon Over Parador', 'Underappreciated actor Jack Noah is on location in Parador at the time the dictator dies. The dictator''s right-hand man makes Jack an offer he cannot refuse... to play the dictator. Jack''s acting skills fool the masses but not close friends and employees of the dictator.', '1988-09-09', 5.85, 'https://image.tmdb.org/t/p/w500/3qVL6RqJTr6uQxV4O72H0j9tv0K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34044, 'Waco: The Rules of Engagement', 'In one of the most tragic face-offs in the history of law enforcement, the deadly debacle at Waco pitted the Branch Davidian sect against the FBI in an all-out war. This documentary makes the most of footage and recordings to examine how the events that led to the tragedy of April 19, 1993, unfolded, and how the FBI''s unrelenting approach made what was already a bad situation much worse.', '1997-09-19', 7.61, 'https://image.tmdb.org/t/p/w500/wJkMYVedNcwK7tzWL7k7Jp6tUPr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34016, 'She''s Out of My League', 'When he starts dating drop-dead gorgeous Molly, insecure airport security agent Kirk can''t believe it. As his friends and family share their doubts about the relationship lasting, Kirk does everything he can to avoid losing Molly forever.', '2010-03-11', 6.49, 'https://image.tmdb.org/t/p/w500/mpYHjyPX0DAxbsnWKmSK5jZ1s4T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34045, 'One Day in September', 'The full story of the 1972 Munich Olympics Massacre and the Israeli revenge operation ''Wrath of God.'' The 1972 Munich Olympics were interrupted by Palestinian terrorists taking Israeli athletes hostage. Besides footage taken at the time, we see interviews with the surviving terrorist, Jamal Al Gashey, and various officials detailing exactly how the police, lacking an anti-terrorist squad and turning down help from the Israelis, botched the operation.', '1999-10-22', 7.29, 'https://image.tmdb.org/t/p/w500/vsxtkcidi7flgxWERBSnwtyH1JJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34069, 'Cargo', 'The story of CARGO takes place on rusty space-freighter KASSANDRA on its way to Station 42. The young medic LAURA is the only one awake on board while the rest of the crew lies frozen in hibernation sleep. In 4 months will Laura''s shift be over.', '2009-09-24', 5.91, 'https://image.tmdb.org/t/p/w500/5CFTLlGbRMtNI0ZyfRL4YC1qD4f.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34070, 'Songs from the Second Floor', 'A monumental traffic jam serves as the backdrop for the lives of the inhabitants of a Swedish city.', '2000-10-06', 7.06, 'https://image.tmdb.org/t/p/w500/xMZieoxiQ1hb5zraZlhzcvU7MGN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34086, 'Spaced Invaders', 'A crew of Martians overhears a radio broadcast of Orson Welles'' "War of the Worlds" coming from Earth, and, thinking the Martian fleet is attacking Earth, they land their broken-down ship in a backwater mid-American town. As luck would have it, they land on Halloween and get mistaken for trick-or-treaters. Comedy ensues as the Martians try to get taken seriously.', '1990-04-27', 4.76, 'https://image.tmdb.org/t/p/w500/vchyoV7mnaUd46meVO81yolXH2D.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33806, 'The Misfortunates', '13-year-old Gunther Strobbe grows up surrounded by alcohol, trash and his completely useless father and uncles. Slowly but surely, he''s being prepared for the same hapless life. Can he defy his destiny?', '2009-10-07', 7.16, 'https://image.tmdb.org/t/p/w500/9RjVHr752QAaoQ1SHCx0JwnZwtY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34101, 'Hollywood Shuffle', 'Aspiring actor and hot-dog stand employee Bobby Taylor catches the ire of his grandmother for auditioning for a role in the regrettably titled exploitation film "Jivetime Jimmy''s Revenge." When Tinseltown Studios casts Taylor in the title role, he has a series of conflicted dreams satirizing African-American stereotypes in Hollywood, and must reconcile his career goals with his desire to remain a positive role model for his little brother.', '1987-03-20', 6.51, 'https://image.tmdb.org/t/p/w500/xidkzvrJfBeZ6wVcVOxobZruiR7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34148, 'Imitation of Life', 'In 1940s New York, a white widow who dreams of being on Broadway has a chance encounter with a black single mother, who becomes her maid.', '1959-04-09', 7.40, 'https://image.tmdb.org/t/p/w500/xt3cUn7lsjpaGuB279A4v8zAYRn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34106, 'You Can''t Take It with You', 'Alice, the only relatively normal member of the eccentric Sycamore family, falls in love with Tony Kirby, but his wealthy banker father and snobbish mother strongly disapprove of the match. When the Kirbys are invited to dinner to become better acquainted with their future in-laws, things don''t turn out the way Alice had hoped.', '1938-09-01', 7.48, 'https://image.tmdb.org/t/p/w500/9JltqbDyWstYW6gnvqDO6L5bOrx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34151, 'Blame It on the Bellboy', 'Mike Lawton, Maurice Horton, and Melvin Orton are three men who come to Venice. One of them is a hit man sent to take out a mobster. Another is a lech looking for a little action with a woman he never met, whom he was set up with. And one of them was sent by his employer to inspect a property his boss wants to buy. All three men stay at the same hotel. But when the bellboy gets their names mixed up and gives info meant for someone else. So one of them meets a Realtor who will whatever she has to, to close the sale. And another follows a woman looking for romance. And another goes to the home of the mobster who thinks he''s sent there to kill him.', '1992-01-24', 5.37, 'https://image.tmdb.org/t/p/w500/aGyu2UhON2s0J0YdTWsTUvsFJ4g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34170, 'Larger Than Life', 'Motivational Speaker Jack Corcoran is determined to get his career off the ground, but the biggest gigs he can get are the ones nobody wants. One day, he receives a telegram that his circus clown father has passed away and left a "huge" inheritance: an elephant that was his father''s pride and joy. His main intention to sell the pachyderm off, Jack must choose between loud and rude zookeeper Mo or attractive animal show owner Terry. As the two trek through the country Jack and the elephant develop a bond, and it changes his approach to life for the better.', '1996-07-26', 5.54, 'https://image.tmdb.org/t/p/w500/jdpEVxE5IUQv1qEBxWcQM49qDF9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33762, 'Band of the Hand', 'An Indian Vietnam veteran trains five street punks in the Everglades to fight vice in Miami.', '1986-04-11', 6.22, 'https://image.tmdb.org/t/p/w500/ypfbaT6qB8cUfeflK7PO9F4hvsm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34220, 'The Purple Sea', 'Nothing - not her father, not the church - can stop unruly Angela from being with her childhood best friend turned great love, Sara. Based on a true story, Viola di Mare, presents a uniquely engaging portrait of family, community and gender roles in a 19th century Italian village.', '2009-10-15', 6.57, 'https://image.tmdb.org/t/p/w500/rU5fHzO1WqjZlJp6A5CWJDF96Rg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34280, 'Money Money Money', 'When they realize the times are changing, five crooks decide to switch from bank robberies to personality abductions.', '1972-05-04', 6.70, 'https://image.tmdb.org/t/p/w500/w4UYJt7etFBmWBR5UhNcG6ttHZw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34283, 'The Pervert''s Guide to Cinema', 'A hilarious introduction, using as examples some of the best films ever made, to some of Slovenian philosopher and psychoanalyst Slavoj Žižek''s most exciting ideas on personal subjectivity, fantasy and reality, desire and sexuality.', '2006-10-06', 7.34, 'https://image.tmdb.org/t/p/w500/9AAxgfwAnpBmQCspuwlMITekcsW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34299, 'Beautiful', 'Headstrong Mona Hubbard is fiercely driven to capture the coveted Miss American Miss beauty award, but an unusual circumstance teams her with a soccer-playing, deep-dimpled little girl named Vanessa.', '2000-09-29', 5.80, 'https://image.tmdb.org/t/p/w500/aTjJFrADfQhyp9gDgY71YSxf2Ks.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34314, 'Turbulence', 'On a flight transporting dangerous convicts, murderer Ryan Weaver manages to break free and cause complete chaos throughout the plane. As various people on board fall victim to Weaver, it is ultimately down to flight attendant Teri Halloran to keep the aircraft from crashing, with on-ground support from an air traffic controller. While Halloran struggles to pilot the plane, Weaver continues to terrorize the surviving members of the crew.', '1997-01-09', 5.37, 'https://image.tmdb.org/t/p/w500/8N63NGWIErS7jUvR5NeVWDZEeZJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33364, 'A Patch of Blue', 'A blind, uneducated white girl is befriended by a black man, who becomes determined to help her escape her impoverished and abusive home life.', '1965-12-10', 7.56, 'https://image.tmdb.org/t/p/w500/9eFULnzgoLpO7lvg6FMutGRuNFg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33255, 'Stoked: The Rise and Fall of Gator', 'A documentary exploring the rise and fall of 80s skateboard legend Mark "Gator" Rogowski.', '2003-08-22', 6.06, 'https://image.tmdb.org/t/p/w500/j86fTZtXLGEYhOtBLLyfRonYJ5Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33813, 'Born to Kill', 'A calculating divorcée risks her chances at wealth and security with a man she doesn''t love by getting involved with a hotheaded murderer.', '1947-04-30', 6.70, 'https://image.tmdb.org/t/p/w500/fFq23ToiVg8sWiMnD4f3Fj37UHD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34376, 'Mannequin Two: On the Move', 'Although Jason works as a department store clerk, he is also a reincarnated prince. Long ago, his beloved Jessie was snatched away from him by an evil wizard who used his powers to transform her into wooden statue. Now Jessie is in Jason''s department store as a mannequin. When he encounters her, she awakens from her thousand-year sleep. They quickly revive their romance, but the evil wizard has been reincarnated as well, and he''s up to no good.', '1991-05-17', 5.80, 'https://image.tmdb.org/t/p/w500/3OOpLGW4Nz113XVyUCes6wm8M7E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33796, 'Mountains of the Moon', 'The story of Captain Richard Francis Burton''s and Lt. John Hanning Speke''s expedition to find the source of the Nile river in the name of Queen Victoria''s British Empire.', '1990-02-16', 6.54, 'https://image.tmdb.org/t/p/w500/4xjKTherAouW0LQy9O6neBUPYqk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33766, 'Smooth Talk', 'Connie, the fifteen-year-old black sheep of her family, finds her summertime idyll of beach trips, mall hangouts, and innocent flirtations shattered by an encounter with a mysterious stranger.', '1985-11-17', 6.20, 'https://image.tmdb.org/t/p/w500/tPfGFKRXD0sVOGhwjxPHadTa8Y1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33374, 'Class Reunion', 'Lizzie Borden High''s class of ''72 are going through the motions at their tenth-year reunion, until deranged alum Walter Baylor, driven insane by a sadistic senior-year prank, escapes from the mental institution and crashes the party. When guests start getting bumped off, the other alumni, including snooty yacht salesman Bob Spinnaker, class tease Bunny Packard, and class zero Gary Nash, spring into action to uncover the culprit.', '1982-10-29', 5.00, 'https://image.tmdb.org/t/p/w500/9Ci3ywt4fbrN6TP5iknNcQ1FHDf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34300, 'Ernest Rides Again', 'Buffoonish Ernest and his dimwitted pal Abner unearth a huge cannon reputed to contain the crown jewels of England.', '1993-11-12', 4.35, 'https://image.tmdb.org/t/p/w500/lv9xbTZSafdFAXLpcbfJ779nnOG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34152, 'Crooklyn', 'From Spike Lee comes this vibrant semi-autobiographical portrait of a school-teacher, her stubborn jazz-musician husband and their five kids living in ''70s Brooklyn.', '1994-05-13', 6.79, 'https://image.tmdb.org/t/p/w500/iFqe07F78SO0SIBzWcK4I5MwNvP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34509, 'George Carlin: Back in Town', 'Back in Town is George Carlin''s ninth HBO special. It was also released on CD on September 17, 1996. This was also his first of many performances at the Beacon Theater in New York City. He rants about Abortion, The death penalty, prison farms, fart jokes, free floating hostility and words.', '1996-03-30', 7.71, 'https://image.tmdb.org/t/p/w500/fXa1iidyPpspNBp3tgPTNa8ghhS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33344, 'The House of Yes', 'Jackie-O is anxiously awaiting the visit of her brother home for Thanksgiving, but isn''t expecting him to bring a friend — and she''s even more shocked to learn that this friend is his fiance. It soon becomes clear that her obsession with Jackie Kennedy is nothing compared to her obsession with her brother, and she isn''t the only member of the family with problems.', '1997-10-10', 6.20, 'https://image.tmdb.org/t/p/w500/vgXLG6BRBKPwkoJOwjaLDMLK9cQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34322, 'Murphy''s Romance', 'Emma, a divorced single mother seeking to start her life over, moves to a small town in Arizona. She befriends Murphy, the older local pharmacist, but things turn complicated when her ex-husband shows up.', '1985-12-25', 6.17, 'https://image.tmdb.org/t/p/w500/hCl1X4Fh8LTQV283AJ5sKUanxV7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33379, 'Greenfingers', 'Prison inmate Colin Briggs is introduced to gardening, and when his thriving prison garden attracts the attention of flamboyant gardening expert Georgina Woodhouse, she offers to sponsor the inmates in an upcoming flower show. At the Hampton Court Flower Show, Colin meets Georgina''s daughter and romance is in bloom.', '2001-07-27', 6.29, 'https://image.tmdb.org/t/p/w500/qk1KSFLOzY6VAt5SRCHUAoqBA5h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34513, 'George Carlin: You Are All Diseased', 'Legendary comic Carlin comes back to the Beacon theater to angrily rant about airport security, germs, cigars, angels, children and parents, men, names, religion, god, advertising, Bill Jeff and minorities.', '1999-02-06', 7.80, 'https://image.tmdb.org/t/p/w500/6dyDMkaU61ZPDadfsiNqgu6VQvi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33783, 'It''s Pat: The Movie', 'Pat Riley, an obnoxious busybody of indeterminable sex, meets and falls in love with Chris, a sensitive, caring person also of indeterminable sex. Their relationship suffers because Pat''s a lout, and cannot decide on a direction for their life. Meanwhile, Pat''s neighbor Kyle falls further and further into obsession with Pat, fascinated by their indeterminate sexuality.', '1994-08-26', 3.09, 'https://image.tmdb.org/t/p/w500/tydslMVgc6DpEvwYT0MWW9byL1a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34560, 'Halloweentown High', 'Marnie puts her magic on the line to get several Halloweentown teenagers transferred to her high school in the mortal world. But soon, Marnie and her new friends are in trouble and out of luck when the evil Knight Of The Iron Dagger appears. He''s determined to destroy all things magical, and it''s up to Marnie to save her high school, the human world and her magic.', '2004-10-08', 6.55, 'https://image.tmdb.org/t/p/w500/dJsmptwkTWbxk1NwLAKeoYtcTuJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34561, 'Purple Butterfly', 'Ding Hui is a member of Purple Butterfly, a powerful resistance group in Japanese occupied Shanghai. An unexpected encounter reunites her with Itami, an ex-lover and officer with a secret police unit tasked with dismantling Purple Butterfly.', '2003-07-04', 6.70, 'https://image.tmdb.org/t/p/w500/hAc6iJYzfq6aI56k5K7cclgGzVp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34563, 'Our Family Wedding', 'The weeks leading up to a young couple''s wedding is comic and stressful, especially as their respective fathers try to lay to rest their feud.', '2010-03-12', 5.60, 'https://image.tmdb.org/t/p/w500/zvRn8aM9lmuBbbJVJgxZl41zarB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33409, 'The Stoning of Soraya M.', 'In 1986 Iran, Sahebjam, whose car breaks down in a remote village, enters into a conversation with Zahra, who relays to him the story about her niece, Soraya, whose arranged marriage to an abusive tyrant ended in tragedy.', '2009-06-26', 7.69, 'https://image.tmdb.org/t/p/w500/m4CfYBh1ZnYqZbt7ziYjHf53P4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34574, 'Nadja', 'In a contemporary New York City, members of a dysfunctional family of vampires are trying to come to terms with each other, in the wake of their father''s death. Meanwhile, they are being hunted by Dr. Van Helsing and his hapless nephew. As in all good vampire movies, forces of love are pitted against forces of destruction.', '1995-09-01', 5.66, 'https://image.tmdb.org/t/p/w500/uwo3iDfPNdZoSNGAgQDXEM7xMu8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33408, 'The Crush', 'A precocious and obsessive teenager develops a crush on a naive writer with harrowing consequences.', '1993-04-02', 6.68, 'https://image.tmdb.org/t/p/w500/4B0eHFjUYYZlkE1fthC29KVC4CS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33377, 'Bush''s Brain', 'An examination of political consultant Karl Rove''s influence on George W. Bush''s candidacy.', '2004-03-13', 6.60, 'https://image.tmdb.org/t/p/w500/zNtFRhDmQfe2Fnl5YmiCndXaFOu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34584, 'The NeverEnding Story', 'While hiding from bullies in his school''s attic, a young boy discovers the extraordinary land of Fantasia, through a magical book called The Neverending Story. The book tells the tale of Atreyu, a young warrior who, with the help of a luck dragon named Falkor, must save Fantasia from the destruction of The Nothing.', '1984-04-06', 7.22, 'https://image.tmdb.org/t/p/w500/ddYCa91iDXfJCxaqSYzwi2fjfnl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34626, 'Merantau', 'In Minangkabau, West Sumatera, Yuda a skilled practitioner of Silat Harimau is in the final preparations to begin his "Merantau" a century''s old rites-of-passage to be carried out by the community''s young men that will see him leave the comforts of his idyllic farming village and make a name for himself in the bustling city of Jakarta.', '2009-08-06', 6.48, 'https://image.tmdb.org/t/p/w500/60Vd3zovl6XeRH8GQOsM9fwMHRO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34615, 'Cry, the Beloved Country', 'A South-African preacher goes to search for his wayward son who has committed a crime in the big city.', '1995-12-15', 6.80, 'https://image.tmdb.org/t/p/w500/96TZr6o4kuiIEryC5jkzaQoP6m5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34636, 'The NeverEnding Story II: The Next Chapter', 'Once again, Bastian is transported to the world of Fantasia which he recently managed to save from destruction. However, the land is now being destroyed by an evil sorceress, Xayide, so he must join up with Atreyu and face the Emptiness once more.', '1990-10-25', 5.78, 'https://image.tmdb.org/t/p/w500/5QfUCbgKzWzjHO5X4ANsDmuTxNQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34653, 'A Single Man', 'Set in Los Angeles in 1962, at the height of the Cuban missile crisis, is the story of a British college professor who dwells on the past and cannot see his future. We follow him through a single day, where a series of events and encounters ultimately lead him to decide if there is a meaning to life after the death of his long time partner, Jim.', '2009-12-11', 7.27, 'https://image.tmdb.org/t/p/w500/oN20MLvoLv14whAss05V3ETBu0p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34647, 'Enter the Void', 'This psychedelic tour of life after death is seen entirely from the point of view of Oscar, a young American drug dealer and addict living in Tokyo with his prostitute sister, Linda. When Oscar is killed by police during a bust gone bad, his spirit journeys from the past -- where he sees his parents before their deaths -- to the present -- where he witnesses his own autopsy -- and then to the future, where he looks out for his sister from beyond the grave.', '2010-05-05', 7.28, 'https://image.tmdb.org/t/p/w500/krKnsfvSJM1PL40tLicRhVQ6kuG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34689, 'The Barefoot Contessa', 'A washed-up filmmaker gets a second chance at stardom when he discovers stunning peasant Maria Vargas dancing in a Madrid nightclub. Goaded by his producer, the director convinces Maria to screen test for, and then star in, his next big picture. But as the producer''s possessive nature and the realities of stardom weigh on Maria, she seeks a genuine lover with whom she can escape.', '1954-09-29', 6.75, 'https://image.tmdb.org/t/p/w500/dn0zbrO4gW4isuBSpwWUgOBF8cR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34723, 'The Adventures of Huck Finn', 'Mischievous Huck Finn is unnerved when his father, reemerging after years away, kidnaps him in an attempt to take away a $600 inheritance from his late mother. Fearing for his life, Huck fakes his own death and escapes. He soon runs into his friend, Jim, a slave fleeing his master. Together, the pair embarks on a raft journey down the Mississippi River, staying ahead of pursuers who blame the slave for Huck''s alleged murder.', '1993-04-02', 6.18, 'https://image.tmdb.org/t/p/w500/8VpQZ43hdaTUmkMoe2CnED1Y2fS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33810, 'A Chump at Oxford', 'The boys get jobs as a butler and maid-- Stan in drag-- for a dinner party. When that ends in disaster, they resort to sweeping streets and accidentally capture a bank robber. The grateful bank president sends them to Oxford, at their request, and higher-education hijinks ensue.', '1940-01-25', 6.87, 'https://image.tmdb.org/t/p/w500/m88sC2iclgDCyJR4EKgoWQ3ujob.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34326, 'Battles Without Honor and Humanity', 'In the teeming black markets of postwar Japan, Shozo Hirono and his buddies find themselves in a new war between factious and ambitious yakuza.', '1973-01-13', 7.31, 'https://image.tmdb.org/t/p/w500/qQmEEj5B3bTQI8Dq8u4zq80Z7JL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34729, 'Our Lips Are Sealed', 'Mary-Kate and Ashley star in this Down Under adventure filled with nonstop Aussie intrigue, laughs and romance. After running afoul of a notorious gangster, Mary-Kate and Ashley take refuge in the FBI Witness Protection Program. Unfortunately, the girls are uncontrollable blabbermouths and they blow their cover in town after town until there''s only one hiding place left - Australia.', '2000-05-18', 6.04, 'https://image.tmdb.org/t/p/w500/40gZ2WhqpZVv8woW0fCH8bMFzx8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34746, 'Death Wish V: The Face of Death', 'Paul Kersey is back at working vigilante justice when his fiancée, Olivia, has her business threatened by mobsters.', '1994-01-14', 5.58, 'https://image.tmdb.org/t/p/w500/1fm57LcUKMd7hQNyjXZycDAALMp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34760, '''night, Mother', 'A mother and daughter spend a night together after the daughter reveals that she will kill herself by the end of it.', '1986-09-12', 7.40, 'https://image.tmdb.org/t/p/w500/qMUD4HGqjH1I8LBZI9kcT6Dxmyh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34774, 'In Search of the Castaways', 'Two teenagers, Mary (Hayley Mills) and Robert (Keith Hamshere) are lead by Professor Paganel (Maurice Chevalier) on a search expedition for the children''s shipwrecked sea captain father. This Disney film was based upon Jules Verne''s 1868 adventure novel Captain Grant''s Children.', '1962-12-01', 6.49, 'https://image.tmdb.org/t/p/w500/27hbGwIAmvcB9X9FdXSwvU05frt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34803, 'Death at a Funeral', 'Aaron''s father''s funeral is today at the family home, and everything goes wrong: the funeral home delivers the wrong body, his cousin accidentally drugs her fiancé, and Aaron''s successful younger brother, Ryan, flies in from New York, broke but arrogant. To top it all off, a mysterious stranger wants a word with Aaron.', '2010-04-15', 5.88, 'https://image.tmdb.org/t/p/w500/oBCQYMJTqV3qLjrvZ5sTZUCBky7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34806, 'The Back-Up Plan', 'When Zoe tires of looking for Mr. Right, she decides to have a baby on her own. But on the day she''s artificially inseminated, she meets Stan, who seems to be just who she''s been searching for all her life. Now, Zoe has to figure out how to make her two life''s dreams fit with each other.', '2010-04-23', 6.12, 'https://image.tmdb.org/t/p/w500/fB6PxwdydGzdq5jSWrxwSMEqSFs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34812, 'H.G. Wells'' War of the Worlds', 'In this modern retelling of H.G. Wells'' classic sci-fi horror, civilization is laid to ruin when a super race of aliens invades Earth. In a blink of an eye, massive "walkers" cover the planet, annihilating all in their path. As cities crumble and human flesh is ripped from the bone, one man struggles to find the one weapon that will turn the tide for mankind.', '2005-06-28', 5.24, 'https://image.tmdb.org/t/p/w500/tPhCFmtnHUwKtzVY7SglwioOnGW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34847, 'College', 'A bookish college student dismissive of athletics is compelled to try out sports to win the affection of the girl he loves.', '1927-09-10', 6.69, 'https://image.tmdb.org/t/p/w500/dUwk8qNkXb243JViqdVqOvUmiMt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34813, 'The Losers', 'On a mission deep in the Bolivian jungle, a team of elite commandos finds itself on the receiving end of a lethal betrayal. Now presumed dead, the men join forces with a mysterious operative named Aisha to hunt down their enemy and even the score.', '2010-04-23', 6.26, 'https://image.tmdb.org/t/p/w500/e5oD3fuQpjZ8Po6WNW0VkUJmW52.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34857, 'Kiss Me Kate', 'A pair of divorced actors are brought together to participate in a musical version of The Taming of the Shrew. Of course, the couple seem to act a great deal like the characters they play, and they must work together when mistaken identities get them mixed up with the mafia.', '1953-11-26', 6.50, 'https://image.tmdb.org/t/p/w500/phJTfsjxxi0a6ibYQ7SCACoTXDC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34851, 'Predators', 'A group of cold-blooded killers find themselves trapped on an alien planet to be hunted by extraterrestrial Predators.', '2010-07-07', 6.30, 'https://image.tmdb.org/t/p/w500/wdniP8NDaJIydi1hMxhpbJMUfr6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34996, 'The Addiction', 'A vampiric doctoral student tries to follow the philosophy of a nocturnal comrade and control her thirst for blood.', '1995-10-06', 6.49, 'https://image.tmdb.org/t/p/w500/1Yy8H2tKQ16mffLFRfxcBHKBdyF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34935, 'Tenchi Muyo! In Love', 'The demonic space criminal Kain has escaped from prison and destroyed the Galaxy Police headquarters. To ensure that the Jurai will not stop him, Kain travels back to 1970 to eliminate Tenchi''s mother before he is even born. Now, Tenchi and the gang must travel to the past to stop him before he ceases to exist.', '1996-04-20', 6.02, 'https://image.tmdb.org/t/p/w500/YR0MeIbbinhc0qLr2vg3Zmqbw6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35056, 'Date Night', 'Phil and Claire Foster fear that their mild-mannered relationship may be falling into a stale rut. During their weekly date night, their dinner reservation leads to their being mistaken for a couple of thieves—and now a number of unsavoury characters want Phil and Claire killed.', '2010-04-08', 6.12, 'https://image.tmdb.org/t/p/w500/9ftaHHJW2IrtnGbazdn5SP8V7Cf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34327, 'The Woman in Green', 'Sherlock Holmes investigates when young women around London turn up murdered, each with a finger severed. Scotland Yard suspects a madman, but Holmes believes the killings to be part of a diabolical plot.', '1945-06-15', 6.50, 'https://image.tmdb.org/t/p/w500/rWcMZ8IZWeYZDcW6Acoiz1gG3tn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33823, 'Paper Clips', 'Whitwell, TN is a small, rural community of less than two thousand people nestled in the mountains of Tennessee. Its citizens are almost exclusively white and Christian. In 1998, the children of Whitwell Middle School took on an inspiring project, launched out of their principal''s desire to help her students open their eyes to diversity in the world and the horrors and enormity of the holocaust.', '2004-09-08', 6.97, 'https://image.tmdb.org/t/p/w500/62E1tAw370MbsXWeTR10bg5VX5N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34328, 'Monster in a Box', 'Monologuist Spalding Gray talks about the great difficulties he experienced while attempting to write his first novel, a nearly 2,000-page autobiographical tome concerning the death of his mother. Among his many asides, Gray discusses his problems in dealing with the Hollywood film industry, recounts the trips he took around the world in order to avoid dealing with his writer''s block and describes his ambivalence about acting as stage manager for a Broadway production of "Our Town."', '1992-05-15', 6.36, 'https://image.tmdb.org/t/p/w500/tbF26J1sqfkZ5HaNhkRrrNbwjDD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34528, 'The Human Condition II: Road to Eternity', 'Kaji, sent to the Japanese army labeled Red, witnesses cruelties in the army and revolts against the abusive treatment against a fellow recruit. He also sees his friend Shinjô defecting to the Russian border, and he ends in the front to fight a lost battle against the Russian tanks division.', '1959-11-20', 8.22, 'https://image.tmdb.org/t/p/w500/7jfv1C4t06VGenQxf3HbmLVmUHZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34379, 'No Man''s Land', 'A rookie cop goes undercover to infiltrate a gang of car thieves led by smooth and charming Ted. The rookie becomes too involved and starts to enjoy the thrill and lifestyle of the game, and becomes romanticly involved with the leaders sister.', '1987-10-23', 5.99, 'https://image.tmdb.org/t/p/w500/h3F9Pm9Tav6aQolv3DqQ0DVvIYs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35265, 'The Embalmer', 'Peppino, a diminutive taxidermist with a reputation for sleaziness, meets Valerio, a handsome if artless much younger man fascinated by the trade. Peppino offers him a large salary to be his assistant—the job burgeoning into a budding friendship he mistakes for something more. When Valerio gets a girlfriend, their fledgling romance will be threatened by an insanely jealous third wheel.', '2002-09-06', 7.20, 'https://image.tmdb.org/t/p/w500/pT9Maaop1epDYWiXEO11NcuR25R.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35292, 'Funny Bones', 'Tommy Fawkes wants to be a successful comedian. After his Las Vegas debut is a failure, he returns to Blackpool where his father—also a comedian—started, and where he spent the summers of his childhood.', '1995-09-20', 6.59, 'https://image.tmdb.org/t/p/w500/yGY053q9WlgaZzji50ZHK3p8VIy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (33839, 'Cheaper by the Dozen', '"Cheaper by the Dozen", based on the real-life story of the Gilbreth family, follows them from Providence, Rhode Island, to Montclair, New Jersey, and details the amusing anecdotes found in large families.', '1950-03-31', 6.40, 'https://image.tmdb.org/t/p/w500/sGj9auC0z18y25NObFbvWLt8gtX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35080, 'The Cat''s Meow', 'Semi-true story of the Hollywood murder that occurred at a star-studded gathering aboard William Randolph Hearst''s yacht in 1924.', '2002-04-12', 5.80, 'https://image.tmdb.org/t/p/w500/zEVZa9EuApL5AQl2mE9NNAeCUix.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34341, 'Men with Brooms', 'A decade ago, curler Chris Cutter disappeared suddenly on the verge of stardom, dropping his curling stones to the bottom of a lake and leaving his fiancée, Julie Foley, at the altar. But when his former coach dies, Cutter returns home for the funeral and attempts to fulfill the man''s last wishes. The team is reunited under Cutter''s estranged dad, Gordon — himself a former curling star — for a final attempt at glory.', '2002-09-20', 5.24, 'https://image.tmdb.org/t/p/w500/qWWvljKlmYwf1XtlJ0vu0u66xpi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34423, 'The Slammin'' Salmon', 'The brutal former heavyweight boxing champion Cleon "Slammin''" Salmon (Duncan), now owner of a Miami restaurant, institutes a competition to see which waiter can earn the most money in one night: the winner stands to gain $10,000, while the loser will endure a beating at the hands of the champ.', '2009-12-11', 5.82, 'https://image.tmdb.org/t/p/w500/yX9skMoAc1JAimJFtczEif4f1jS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34544, 'The A-Team', 'A man who loves when a plan comes together, Col. Hannibal Smith leads a close-knit team of elite operatives and Iraq War veterans. Framed for a crime they didn''t commit, Smith and his men, Capt. H.M. ‘Howling Mad’ Murdock , Sgt. Bosco ‘B.A.’ Baracus, and Lt. Templeton ‘Faceman’ Peck, break out and go rogue, using their special talents to clear their names and find the perpetrator. Hot on their trail is Capt. Charissa Sosa, who was once involved with a member of Smith''s team and has sworn to capture them, no matter what it takes.', '2010-06-09', 6.42, 'https://image.tmdb.org/t/p/w500/bkAWEx5g5tvRPjtDQyvIZ7LRxQm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35555, 'Unknown White Male', 'The true story of Doug Bruce who woke up on Coney Island with total amnesia. This documentary follows him as he rediscovers himself and the world around him.', '2005-06-01', 6.70, 'https://image.tmdb.org/t/p/w500/hsFJ2DACY37jwb2huAvyQ9BFVj4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35138, 'Little Big Soldier', 'The story of a farmer forced into conscription, who has been looking to get out of the army ever since. His great chance arrives when he stumbles upon a wounded general from an enemy state, and he kidnaps him, intending to claim credit for the capture, which includes five acres of land, and most importantly, honorable discharge from the army.', '2010-02-14', 6.90, 'https://image.tmdb.org/t/p/w500/uCSQnopQPIw58RKTfzoRYxq9It5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35588, 'Geronimo: An American Legend', 'The Apache Indians have reluctantly agreed to settle on a US Government approved reservation. Not all the Apaches are able to adapt to the life of corn farmers. One in particular, Geronimo, is restless. Pushed over the edge by broken promises and necessary actions by the government, Geronimo and thirty or so other warriors form an attack team which humiliates the government by evading capture, while reclaiming what is rightfully theirs.', '1993-12-10', 6.29, 'https://image.tmdb.org/t/p/w500/9FNuwnhHngkblD6eVRXnmJN8kQq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35612, 'New Waterford Girl', 'A gifted teenager, dreaming of life beyond her small town, becomes inspired when a 15-year-old girl from New York moves in next door.', '1999-09-12', 6.68, 'https://image.tmdb.org/t/p/w500/1YMPN6GNY9jnzZpONPpmFiF1TSl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35144, 'The Journey of Natty Gann', 'America is in the depths of the Great Depression. Families drift apart when faraway jobs beckon. A courageous young girl confronts overwhelming odds when she embarks on a cross-country search for her father. During her odyssey, she forms a close bond with two diverse traveling companions: a magnificent, protective wolf, and a hardened drifter.', '1985-09-27', 6.81, 'https://image.tmdb.org/t/p/w500/z2eHb3ih4k9zannMKn3wmVvYAis.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35651, 'Time Out', 'An unemployed man finds his life sinking more and more into trouble as he hides his situation from his family and friends.', '2001-09-10', 6.71, 'https://image.tmdb.org/t/p/w500/t3BBQPRKszYbSRIOSjQcVZIVp26.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35680, 'Madeline', 'Horrified at the prospect of her beloved school being sold, a young French girl named Madeline uses her wit and craftiness to attempt to save it, making an unlikely new friend in the process.', '1998-07-10', 6.22, 'https://image.tmdb.org/t/p/w500/nAGRLwJC0jv7QlfJR6y32xRZqcF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35650, 'Maelström', 'A young woman''s life spirals into chaos after she is involved in a hit-and-run accident. Then she encounters a mysterious man named Evian who offers her an opportunity for redemption. Narrated by a fish.', '2000-09-15', 6.24, 'https://image.tmdb.org/t/p/w500/knhWhSDOEPcWed5ljKcJVnXbH7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35690, 'The Last Song', 'A drama centered on a rebellious girl who is sent to a Southern beach town for the summer to stay with her father. Through their mutual love of music, the estranged duo learn to reconnect.', '2010-03-31', 7.23, 'https://image.tmdb.org/t/p/w500/76twEOHXAM2oKnvZYBI5bP6GeDu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35791, 'Resident Evil: Afterlife', 'In a world ravaged by a virus infection, turning its victims into the Undead, Alice continues on her journey to find survivors and lead them to safety. Her deadly battle with the Umbrella Corporation reaches new heights, but Alice gets some unexpected help from an old friend. A new lead that promises a safe haven from the Undead takes them to Los Angeles, but when they arrive the city is overrun by thousands of Undead - and Alice and her comrades are about to step into a deadly trap.', '2010-09-01', 6.06, 'https://image.tmdb.org/t/p/w500/qZHDnt8bnsD2cSJfIbjWbCkIq3G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35696, 'Juwanna Mann', 'A basketball star is booted out of the NBA when his on-court antics go too far, so he poses as a woman and joins the WUBA.', '2002-06-21', 5.11, 'https://image.tmdb.org/t/p/w500/1m5sbTbifesBhCrkE0gJncwMGXw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35936, 'Sarafina!', 'A Soweto schoolgirl named Sarafina is galvanized to protest apartheid after her teacher is arrested for her activism, leading her to join the student resistance movement.', '1992-09-18', 6.15, 'https://image.tmdb.org/t/p/w500/jAbU0p1hQErFIErJPmUG3n91xgn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35987, 'Lola Montès', 'Lola Montes, previously a great adventuress, is reduced to being the attraction of a circus after having been the lover of various important men.', '1955-12-23', 6.91, 'https://image.tmdb.org/t/p/w500/ycePcddfSvqaalyPxMvFYT5D8wV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35337, 'The Triumph of Love', 'A princess is determined to restore her homeland''s throne to its rightful heir, a young prince with whom she falls in love.', '2001-09-07', 6.14, 'https://image.tmdb.org/t/p/w500/mLgC2GDegvwIucpQpn6rDR3ltiv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36040, 'Walkabout', 'Under the pretense of having a picnic, a geologist takes his teenage daughter and 6-year-old son into the Australian outback and attempts to shoot them. When he fails, he turns the gun on himself, and the two city-bred children must contend with harsh wilderness alone. They are saved by a chance encounter with an Aboriginal boy who shows them how to survive, and in the process underscores the disharmony between nature and modern life.', '1971-07-01', 7.30, 'https://image.tmdb.org/t/p/w500/24vooYt5StgtgcQObVr1GHuM5gy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35944, 'Lucky Break', 'Half-way through his 12-year prison sentence for an incompetent armed robbery, Jimmy Hands gets a lucky break: he''s transferred to a prison from which he can probably escape. He convinces the governor to stage a musical in an old chapel next to the prison''s outer wall. He rounds up volunteer actors and puts his escape plan into production. Two other barriers, besides the wall, confront him: the arrival of a nasty inmate, John Toombes, who insists on joining the escape, and Jimmy''s feelings of attraction for Anabel, a social worker who agrees to appear in the play. Opening night approaches: is this Jimmy''s breakout performance?', '2001-08-24', 6.24, 'https://image.tmdb.org/t/p/w500/63JHVXD2bkPBdIFgprqXKu3k8bw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36047, 'The In Crowd', 'A mentally disturbed young woman takes a job at a posh country club and falls in with a clique of wealthy college kids where she''s taken under the wing of the clique''s twisted leader, who harbors some dark secrets too terrifying to tell.', '2000-07-19', 4.65, 'https://image.tmdb.org/t/p/w500/j77l405846qiLb8RGb1egu7ON3r.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34444, 'Even Cowgirls Get the Blues', 'A girl born with enormous thumbs in the repressive era of the 1950s learns to turn her quirks into assets.', '1994-05-13', 4.35, 'https://image.tmdb.org/t/p/w500/20x8nm0nPXkYv04COAHFA2AHyAl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36094, 'Stanley & Iris', 'An illiterate cook at a company cafeteria tries for the attention of a newly widowed woman. As they get to know one another, she discovers his inability to read. When he is fired, she takes on trying to teach him to read in her kitchen each night.', '1990-02-09', 6.48, 'https://image.tmdb.org/t/p/w500/ydDNS3aCnBWOT9jQiEVmN56rk2i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36056, 'The Ring', 'Both Jack Sander and Bob Corby are boxers in love with Mabel. Jack and Mabel wed, but their marriage is flat. The young wife looks to Bob for comfort.', '1927-09-28', 5.88, 'https://image.tmdb.org/t/p/w500/VeNRpyspVlJzkrNAyszdGtmy9e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36095, 'Cure', 'A frustrated detective deals with the case of several gruesome murders committed by people who have no recollection of what they''ve done.', '1997-12-27', 7.57, 'https://image.tmdb.org/t/p/w500/xNVJr9q6AtSbjosS6Ed9YirOkSo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36129, 'Hedgehog in the Fog', 'A little hedgehog, on the way to visit his friend the bear, gets lost in thick fog, where horses, dogs and even falling leaves take on a terrifying new aspect...', '1975-10-23', 7.46, 'https://image.tmdb.org/t/p/w500/4sMh4bpyy5zhOS7G48WOsOBIhIH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36107, 'More', 'A factory worker in a dark, gray world assembles devices that promise happiness. In his spare time he tinkers to create something better, and finally succeeds in perfecting his invention, which allows people to see life through rose-colored glasses, but he has to pay a price for his success.', '1998-09-01', 7.66, 'https://image.tmdb.org/t/p/w500/802hVxtGoC4uIYMhM6eeXKeK17l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36161, 'Winnie-the-Pooh', 'According to Winnie-the-Pooh himself, bears love honey very much. That''s why it always runs out very quickly. And you can''t do without honey, so Winnie, along with Piglet, sets off for a tall tree with a beehive hanging from it.  Winnie fearlessly climbs up to the beehive on a balloon, singing a song about a little cloud.', '1969-07-19', 7.36, 'https://image.tmdb.org/t/p/w500/jSzuXChK281KUVFAZApTDJshHrZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36141, 'The Underneath', 'A recovering gambling addict attempts to reconcile with his family and friends but finds trouble and temptation when caught between feelings for his ex-wife and her dangerous hoodlum boyfriend.', '1995-04-28', 5.68, 'https://image.tmdb.org/t/p/w500/a8jn5ML3vRT4nnMMBmFGXRaRhqO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36162, 'Winnie-the-Pooh and a Busy Day', 'Another Soviet Winnie-the-Pooh story. This time the donkey, known from the Pooh stories as Eeyore, is sad because he has no tail. Pooh goes in search of one and finds it attached to a bell that hangs from the treehouse of one Owl.', '1972-08-06', 7.48, 'https://image.tmdb.org/t/p/w500/zOnnIpNwDMxGSScB0MjLi2GeMoQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35428, 'What Men Talk About', 'Four old friends - Kamil, Lesha, Sasha and Slava - all well-to-do professionals in their late 30s embarking on a two days road trip from Moscow to Odessa. They wish to escape the metropolis and the everyday routine of work, family and girlfriends to relax in a nightclub run by Slava''s friend and to see the popular band B-2 show.', '2010-03-04', 7.20, 'https://image.tmdb.org/t/p/w500/kprgQJtu9I5ZWaDHeTTufDIGgaa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36163, 'Winnie-the-Pooh Goes Visiting', 'The second of the Soviet Winnie-the-Pooh series. This one had Pooh and Piglet visiting Rabbit for a meal with honey.', '1971-07-10', 7.46, 'https://image.tmdb.org/t/p/w500/dHXgv9GGgmoaWN6VAfLICvS6c2C.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36206, 'Ride the High Country', 'An ex-lawman is hired to transport gold from a mining community through dangerous territory. But what he doesn''t realize is that his partner and old friend is plotting to double-cross him.', '1962-05-09', 7.06, 'https://image.tmdb.org/t/p/w500/oBdJliz2o88ZLPulL5KLdbRsQuf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36210, 'Not One Less', 'Set in the People''s Republic of China during the 1990s, the film centers on a 13-year-old substitute teacher, Wei Minzhi, in the Chinese countryside. Called in to substitute for a village teacher for one month, Wei is told not to lose any students.', '1999-10-30', 7.53, 'https://image.tmdb.org/t/p/w500/eERKaWCIRh3a8rPjUu1z34OYZD8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35072, 'Atragon', 'The legendary empire of the lost continent of Mu reappears to threaten the world with domination. While countries unite to resist, an isolated World War II Captain has created the greatest warship ever seen, and possibly the surface world''s only defense.', '1963-12-22', 6.59, 'https://image.tmdb.org/t/p/w500/u5fD2mfsovtW1Pn2Umtl2G3280w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34433, 'Dragon Ball Z: Broly - The Legendary Super Saiyan', 'While the Saiyan Paragus persuades Vegeta to rule a new planet, King Kai alerts Goku of the South Galaxy''s destruction by an unknown Super Saiyan.', '1993-03-06', 7.26, 'https://image.tmdb.org/t/p/w500/6iO8TJCyLI4BiPYOvdwzPV2bhoV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34530, 'The Human Condition III: A Soldier''s Prayer', 'After the Japanese defeat to the Russians, Kaji leads the last remaining men through Manchuria. Intent on returning to his old life, he faces great odds in a variety of different harrowing circumstances as he and his men sneak behind enemy lines.', '1961-01-28', 8.41, 'https://image.tmdb.org/t/p/w500/pag7gyxSFe7vTl6riHfZ5Xci6q7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36246, 'Monday', 'A simple funeral turns a man''s world Topsy turvy. He wakes up in a posh hotel room, totally clueless about how he got there. Slowly, he recalls what happened a day before.', '2000-04-29', 7.02, 'https://image.tmdb.org/t/p/w500/ha06SfVtGPaRdMuBxe9IcPo8SzY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36222, 'Dead or Alive: Final', 'In post-apocalyptic Yokohama, a hard-boiled cop and a mellowed out drifter hook up with a gang of rebels. When the gang kidnap the cop''s son, the wheels are set in motion for an inevitable showdown.', '2002-01-12', 5.60, 'https://image.tmdb.org/t/p/w500/7wHsgK1dvFdp6pv3ok3BHDY33Op.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35463, 'Fatal Beauty', 'Detective Rita Rizzoli is accustomed to donning costumes and going undercover to nail crooks. But she''ll be required to use all of her get-ups and more when a major cocaine ring is suspected of turning out a potent new strain of the drug, called "Fatal Beauty." With the help of her partner and a former bodyguard for a local cartel, Rita will do whatever it takes to find out who''s dealing Fatal Beauty and stop them.', '1987-10-30', 5.56, 'https://image.tmdb.org/t/p/w500/hm6wUVyFm1iRlvkQXBugDPItUec.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35115, 'Davy Crockett, King of the Wild Frontier', 'Legends (and myths) from the life of famed American frontiersman Davy Crockett are depicted in this feature film edited from television episodes. Crockett and his friend George Russel fight in the Creek Indian War. Then Crockett is elected to Congress and brings his rough-hewn ways to the House of Representatives. Finally, Crockett and Russell journey to Texas and the last stand at the Alamo.', '1955-05-25', 6.44, 'https://image.tmdb.org/t/p/w500/7IFRrsQdaaUJaemg2z35fshzswd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (34549, 'Max Keeble''s Big Move', 'Max Keeble, the victim of his 7th grade class, plots revenge when he learns he''s moving; it backfires when he doesn''t move after all.', '2001-10-05', 5.83, 'https://image.tmdb.org/t/p/w500/eJ4olY0dZMC1MfMhRkLOWisWYtu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35151, 'Hello Again', 'A suburban housewife chokes to death and is brought back to life by a spell cast by her wacky sister.', '1987-11-06', 5.75, 'https://image.tmdb.org/t/p/w500/mbNJ7Qe33XtN2aenO0ildCOpG0y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36196, 'Party Girl', 'Although Mary has little income, she still finds ways to spend her nights at clubs. After being arrested for throwing an illegal rave, she asks her aunt Judy for bail money. Judy then finds Mary a job at her library so that Mary can repay her. Initially, Mary finds the job as a clerk boring and stifling, and prefers to get to know a street food vendor whom she likes. However, Mary must refocus her life once she loses her job and apartment.', '1995-06-09', 6.50, 'https://image.tmdb.org/t/p/w500/cfGEUftQVjvJHTTc3OKbzfsBamT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35196, 'Restoration', 'An aspiring young physician, Robert Merivel found himself in the service of King Charles II and saves the life of someone close to the King. Merivel joins the King''s court and lives the high life provided to someone of his position. Merivel is ordered to marry his King''s mistress in order to divert the queens suspicions. He is given one order by the king and that is not to fall in love. The situation worsens when Merivel finds himself in love with his new wife. Eventually, the King finds out and relieves Merivel of his position and wealth. His fall from grace leaves Merivel where he first started. And through his travels and reunions with an old friend, he rediscovers his love for true medicine and what it really means to be a physician.', '1995-12-29', 6.10, 'https://image.tmdb.org/t/p/w500/glOCWK6AMl6FVHxLikl5OD8xw2B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35119, 'Evil Angels', 'Based on the true story of Lindy Chamberlain who, during a family camping trip to Ayers Rock in central Australia, claimed she witnessed a dingo take her baby daughter, Azaria, from their tent. Azaria''s body was never found and, after investigations and two public inquests, she is charged with murder.', '1988-11-03', 6.80, 'https://image.tmdb.org/t/p/w500/auyoK8OZh1sZldjJfy9RGzS6crV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36234, 'Timecode', 'A production company begins casting for its next feature, and an up-and-coming actress named Rose tries to manipulate her filmmaker boyfriend, Alex, into giving her a screen test. Alex''s wife, Emma, knows about the affair and is considering divorce, while Rose''s girlfriend secretly spies on her and attempts to sabotage the relationship. The four storylines in the film were each shot in one take and are shown simultaneously, each taking up a quarter of the screen.', '2000-04-28', 5.55, 'https://image.tmdb.org/t/p/w500/xQWlEjYAJTC8aBHjUzPmFLjZPSp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36259, 'Theodore Rex', 'In an alternate futuristic society, a tough female police detective is paired with a talking dinosaur to find the killer of dinosaurs and other prehistoric animals leading them to a mad scientist bent on creating a new Armageddon.', '1995-12-14', 3.64, 'https://image.tmdb.org/t/p/w500/fUUbOE91SK4GCpiyftEY5USjCh1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36557, 'Casino Royale', 'Le Chiffre, a banker to the world''s terrorists, is scheduled to participate in a high-stakes poker game in Montenegro, where he intends to use his winnings to establish his financial grip on the terrorist market. M sends Bond—on his maiden mission as a 00 Agent—to attend this game and prevent Le Chiffre from winning. With the help of Vesper Lynd and Felix Leiter, Bond enters the most important poker game in his already dangerous career.', '2006-11-14', 7.58, 'https://image.tmdb.org/t/p/w500/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36568, 'Paulie', 'Paulie, a talking parrot, recounts his travels looking for his original owner to a Russian janitor who helps him to the end of his journey.', '1998-04-17', 6.99, 'https://image.tmdb.org/t/p/w500/aiW8TWjIuFveTcA5BCU7KMjPaaW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36586, 'Blade II', 'Blade forms an uneasy alliance with the vampire council in order to combat the Reapers, who are feeding on vampires.', '2002-03-22', 6.57, 'https://image.tmdb.org/t/p/w500/yDHwo3eWcMiy5LnnEnlGV9iLu9k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36599, 'Prom Night', 'At a high school senior prom, a masked killer stalks four teenagers who were responsible for the accidental death of a classmate six years prior.', '1980-07-18', 5.71, 'https://image.tmdb.org/t/p/w500/r2Ew7wUP96PsePEZseK6JqcPWY9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36593, 'Naked Gun 33⅓: The Final Insult', 'Frank Drebin is persuaded out of retirement to go undercover in a state prison. There he has to find out what top terrorist, Rocco, has planned for when he escapes. Adding to his problems, Frank''s wife, Jane, is desperate for a baby.', '1994-03-18', 6.52, 'https://image.tmdb.org/t/p/w500/p0AYsdgkudR9P5fNV5AjzbwQt8W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35552, 'The Extraordinary Adventures of Adèle Blanc-Sec', 'An adventure set in the early part of the 20th century, focused on a popular novelist and her dealings with would-be suitors, the cops, monsters, and other distractions.', '2010-04-09', 6.27, 'https://image.tmdb.org/t/p/w500/1nYv7H0XJFgrJ5LewGlyNDvjqdq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36614, 'The Sum of Us', 'A widowed father has to deal with two complex issues: while he is searching for "Miss Right," his son, who is in his 20s and gay, is searching for "Mr. Right."', '1994-07-28', 6.75, 'https://image.tmdb.org/t/p/w500/4rBI4KISTuMCsWGb0kurWxKjqPQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36616, 'Bebe''s Kids', 'When Robin meets the lovely Jamika he thinks he''s in heaven. But when he meets her friend Bebe''s children, whom she is looking after, he knows he''s in hell.', '1992-07-31', 6.08, 'https://image.tmdb.org/t/p/w500/uuUHtdsxLqr79QlCCnJNwPkOTTB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36629, 'Comic Book Villains', 'When word hits the street that a nearby elderly gentleman has a cache of old, rare, and very valuable mint condition comic books, rival comic book shop owners Raymond McGillicuddy (Donal Logue) and Norman Link (Michael Rapaport) both set out to be the first to buy them. But when the old man declines to sell, the former friends turn into enemies, and a friendly rivalry becomes tainted with greed and turns to murder.', '2002-09-03', 5.20, 'https://image.tmdb.org/t/p/w500/4yK0mEONadsXSdeoZQAGn92ZrKp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36643, 'The World Is Not Enough', 'Greed, revenge, world dominance and high-tech terrorism – it''s all in a day''s work for Bond, who''s on a mission to protect a beautiful oil heiress from a notorious terrorist. In a race against time that culminates in a dramatic submarine showdown, Bond works to defuse the international power struggle that has the world''s oil supply hanging in the balance.', '1999-11-17', 6.29, 'https://image.tmdb.org/t/p/w500/wCb2msgoZPK01WIqry24M4xsM73.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36647, 'Blade', 'The Daywalker known as "Blade" - a half-vampire, half-mortal man - becomes the protector of humanity against an underground army of vampires.', '1998-08-21', 6.80, 'https://image.tmdb.org/t/p/w500/oWT70TvbsmQaqyphCZpsnQR7R32.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36648, 'Blade: Trinity', 'For years, Blade has fought against the vampires in the cover of the night. But now, after falling into the crosshairs of the FBI, he is forced out into the daylight, where he is driven to join forces with a clan of human vampire hunters he never knew existed—The Nightstalkers. Together with Abigail and Hannibal, two deftly trained Nightstalkers, Blade follows a trail of blood to the ancient creature that is also hunting him—the original vampire, Dracula.', '2004-12-08', 5.86, 'https://image.tmdb.org/t/p/w500/6f7iXvPOnf83MaLB1JmPzUor1rr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36652, 'The Good Earth', 'China, during the rule of the Qing Dynasty. The arranged marriage between Wang Lung, a humble farmer, and O-Lan, a domestic slave, will endure the many hardships of life over the years; but the temptations of a fragile prosperity will endanger their love and the survival of their entire family.', '1937-06-02', 6.34, 'https://image.tmdb.org/t/p/w500/bPJe6d8etqVPyPYrNtE5rRNts9T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36657, 'X-Men', 'Two mutants, Rogue and Wolverine, come to a private academy for their kind whose resident superhero team, the X-Men, must oppose a terrorist organization with similar powers.', '2000-07-13', 7.02, 'https://image.tmdb.org/t/p/w500/bRDAc4GogyS9ci3ow7UnInOcriN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36658, 'X2', 'Professor Charles Xavier and his team of genetically gifted superheroes face a rising tide of anti-mutant sentiment led by Col. William Stryker. Storm, Wolverine and Jean Grey must join Magneto and Mystique to unhinge Stryker''s scheme to exterminate all mutants.', '2003-04-27', 7.00, 'https://image.tmdb.org/t/p/w500/bst4alFUXCxISwdRUKSMhhkrX1M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36669, 'Die Another Day', 'James Bond is sent to investigate the connection between a North Korean terrorist and a diamond mogul, who is funding the development of an international space weapon.', '2002-11-17', 5.99, 'https://image.tmdb.org/t/p/w500/bZmGqOhMhaLn8AoFMvFDct4tbrL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36668, 'X-Men: The Last Stand', 'When a cure is found to treat mutations, lines are drawn amongst the X-Men led by Professor Charles Xavier, and Magneto''s Brotherhood of Mutants.', '2006-05-24', 6.43, 'https://image.tmdb.org/t/p/w500/a2xicU8DpKtRizOHjQLC1JyCSRS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36670, 'Never Say Never Again', 'James Bond returns as the secret agent 007 to battle the evil organization SPECTRE. Bond must defeat Largo, who has stolen two atomic warheads for nuclear blackmail. But Bond has an ally in Largo''s girlfriend, the willowy Domino, who falls for Bond and seeks revenge.', '1983-10-07', 6.08, 'https://image.tmdb.org/t/p/w500/zhoAL4o1STGgLbLxJ9r1ijfyHC9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36676, 'Jonestown: The Life and Death of Peoples Temple', 'Featuring never-before-seen footage, this documentary delivers a startling new look at the Peoples Temple, headed by preacher Jim Jones who, in 1978, led more than 900 members to Guyana, where he orchestrated a mass suicide via tainted punch.', '2006-04-26', 7.00, 'https://image.tmdb.org/t/p/w500/5c9aoJ1LbcAYp6cWF3rZCVtrQ1W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35199, 'Wordplay', 'From the masters who create the mind-bending diversions to the tense competition at the American Crossword Puzzle Tournament, Patrick Creadon''s documentary reveals a fascinating look at a decidedly addictive pastime. Creadon captures New York Times editor Will Shortz at work, talks to celebrity solvers -- including Bill Clinton and Ken Burns -- and presents an intimate look at the national tournament and its competitors.', '2006-06-26', 7.00, 'https://image.tmdb.org/t/p/w500/8AY7EkxJwB8Ow5iPe41GOJesxzn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36685, 'The Rocky Horror Picture Show', 'After getting a flat tire in the middle of nowhere, newly engaged couple Brad and Janet encounter the eerie mansion of the flamboyant, seductive Dr Frank-N-Furter and a variety of eccentric characters. Through elaborate dance and rock music, the mad scientist unveils his latest creation: a perfect, muscular man.', '1975-08-14', 7.44, 'https://image.tmdb.org/t/p/w500/3pyE6ZqDbuJi7zrNzzQzcKTWdmN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36692, 'Bloodsport III', 'Bloodsport III brings us back to the world of Alex Cardo. This time he must battle in a fight to end all fights - The Kumite, the most vicious warrior alive - Beast. He must not only battle for his own honor, but also avenge the death of Sun, his mentor, teacher, and spiritual "father", when Sun is spitefully killed by crime boss Duvalier. In order to defeat Beast, destroy Duvalier, and avenge Sun''s death, Alex turns to Leung to whom he was indebted in Bloodsport II. Leung directs him to the great shaman, Makato "the Judge", to whom Alex must turn for guidance. The judge teaches him to fully channel the energy in his mind and body in order to rout the Beast in the Kumite...', '1996-12-05', 5.44, 'https://image.tmdb.org/t/p/w500/xgr8VRMyNrw8RooFuwrIxGnITVg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36693, 'Bloodsport: The Dark Kumite', 'Agent John Keller goes undercover into the tough prison known as Fuego Penal to find out about the corpses of prisoners disappearing without a trace. There he gets involved in a dangerous tournament arranged by a man named Justin Caesar, where the prisoners are forced fight to death.', '1999-03-30', 4.80, 'https://image.tmdb.org/t/p/w500/8fesxO5RKl3Hd6XIUohr66jlMdK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36724, 'The Decline of Western Civilization Part II: The Metal Years', 'An exploration of the heavy metal scene in Los Angeles, with particular emphasis on glam metal. It features concert footage and interviews of legendary heavy metal and hard rock bands and artists such as Aerosmith, Alice Cooper, Kiss, Megadeth, Motörhead, Ozzy Osbourne and W.A.S.P..', '1988-06-17', 6.82, 'https://image.tmdb.org/t/p/w500/obJGzd7ExOdc9Y7PFskra36nKpI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36739, 'School Daze', 'Fraternity and sorority members clash with other students at a historically black college during homecoming weekend.', '1988-02-12', 5.70, 'https://image.tmdb.org/t/p/w500/vnfjKHcmah7ReMxLNF18JMXFgSZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36786, 'While the City Sleeps', 'Newspaper men compete against each other to find a serial killer dubbed "The Lipstick Killer".', '1956-04-19', 6.90, 'https://image.tmdb.org/t/p/w500/yxcHaWVdHXf6FbI0TYa43nnQeVo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36223, 'Zebraman', 'A down-and-out schoolteacher receives the calling to become the real life personification of an old television superhero, Zebraman.', '2004-01-30', 6.29, 'https://image.tmdb.org/t/p/w500/3kBangW2OBBNkqYyp48blW9cwE5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36273, 'The City of Lost Souls', 'Brazilian-Japanese gangster Mario rescues his Chinese girlfriend Kei as she''s about to be deported from Japan. Desperate to escape, he hides in Tokyo''s booming Japanese-Portuguese community and seeks passage from the country from a Russian mobster. To meet his price, they hold up a bigtime drug deal between the Chinese Mafia and the local Yakuza.', '2000-09-15', 6.17, 'https://image.tmdb.org/t/p/w500/2TajLnUCAWlAgl47qcmg28rAaZf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35412, 'On the Beach', 'In 1964, atomic war wipes out humanity in the northern hemisphere; one American submarine finds temporary safe haven in Australia, where life-as-usual covers growing despair. In denial about the loss of his wife and children in the holocaust, American Captain Towers meets careworn but gorgeous Moira Davidson, who begins to fall for him. The sub returns after reconnaissance a month (or less) before the end; will Towers and Moira find comfort with each other?', '1959-12-17', 6.70, 'https://image.tmdb.org/t/p/w500/lTDuj5zalrI0fpQel7UfPHTexTK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36245, 'Diary of a Chambermaid', 'Celestine has a new job as a chambermaid for the quirky M. Monteil, his wife and her father. When the father dies, Celestine decides to quit her job and leave, but when a young girl is raped and murdered, Celestine believes that the Monteils'' groundskeeper, Joseph, is guilty, and stays on in order to prove it. She uses her sexuality and the promise of marriage to get Joseph to confess -- but things do not go as planned.', '1964-03-04', 7.07, 'https://image.tmdb.org/t/p/w500/epCJe5dzAn21mQ9L1fQ2FjIF13T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35203, 'If These Walls Could Talk', 'A powerful, intimate portrait of three women living in the same house during different eras who all face unplanned pregnancies. The vignettes follow a recently widowed nurse struggling to take control of her life in the early 50s, a mother of four balancing raising a family and maintaining a career in the 70s, and a student making a difficult decision with the help of one woman that will change the course of both their lives in the 90s.', '1996-09-11', 6.67, 'https://image.tmdb.org/t/p/w500/5foda9jN8pAM9zvKP5iFdITepWj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36819, 'Time Bandits', 'Young history buff Kevin can scarcely believe it when six dwarfs emerge from his closet one night. Former employees of the Supreme Being, they''ve purloined a map charting all of the holes in the fabric of time and are using it to steal treasures from different historical eras. Taking Kevin with them, they variously drop in on Napoleon, Robin Hood and King Agamemnon before the Supreme Being catches up with them.', '1981-07-13', 6.63, 'https://image.tmdb.org/t/p/w500/4VZtpwdhHQSa4LUkvujyGAHb1hG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36274, 'Deadly Outlaw: Rekka', 'After Kunisada''s Yakuza leader and father figure is brutally murdered, he and his best friend go on a two-man mission to avenge his death, killing other Yakuza leaders leading to a final confrontation by the old man''s killers.', '2002-09-21', 6.59, 'https://image.tmdb.org/t/p/w500/2r4WNCpwAQzekbaZwoCcOv1GJuO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36872, 'When a Woman Ascends the Stairs', 'Keiko, whom everyone calls Mama, narrates her story: she''s a hostess on the Ginza, 30, a widow. She describes life''s vicious cycle: acting cheerful around drunks, dressing and living well to convey confidence, needing money for these expenses and for her demanding mother and brother, and knowing she''s growing older.', '1960-01-15', 7.96, 'https://image.tmdb.org/t/p/w500/miGb5TwM8SIK5URe0mPMOYZqr3g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (35233, 'The Scout', 'When his star recruit botches a Major League Baseball debut, humiliated talent scout Al Percolo gets banished to rural Mexico, where he finds a potential gold mine in the arm of young phenom Steve Nebraska. Soon, the New York Yankees put a $55 million contract on the table—provided a psychiatrist can affirm Nebraska''s mental stability.', '1994-09-30', 5.24, 'https://image.tmdb.org/t/p/w500/a5b1k4wmZShLu1Fo19SzcOJKRlD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36355, 'Flipper', 'Sandy Ricks is sent by his mom to Coral Key, a rustic island in the Florida keys, to spend the summer with his uncle Porter Ricks. Sandy dislikes everything about his new environment until a new friend comes into his life, a dolphin named Flipper, that brings uncle and nephew together and leads Sandy on the summer adventure of a lifetime.', '1996-05-17', 5.56, 'https://image.tmdb.org/t/p/w500/c3KEzecZ5oE6CpSrWX6wCLrBJbf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36344, 'Alaska', 'Jake Barnes and his two kids, Sean and Jessie, have moved to Alaska after his wife died. He is a former airline pilot now delivering toilet paper across the mountains. During an emergency delivery in a storm his plane goes down somewhere in the mountains. Annoyed that the authorities aren''t doing enough, Jessie and Sean set out on an adventure to find their father with the help of a polar bear which they have saved from a ferocious poacher. Conflict ensues.', '1996-08-14', 5.80, 'https://image.tmdb.org/t/p/w500/qInhNnU2siIX4vJudzm0fwzS99O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36791, 'In This World', 'Torn straight from the headlines, Michael Winterbottom''s compelling and prescient ''In This World'' follows young Afghan Jamal and his older cousin Enayat as they embark on a hazardous overland trip from their refugee camp at Peshawar, north-west Pakistan. Entering Turkey on foot through a snowy, Kurdish-controlled pass, the pair again take their lives into their hands and face suffocation when they are locked in a freight container on a ship bound for Italy. From there they plan to travel on to Paris, the Sangatte refuge centre and ultimately asylum in London.', '2003-03-28', 6.24, 'https://image.tmdb.org/t/p/w500/denzE2tZc3TZ95vQNK3rKo0iDHn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36947, 'Manufacturing Consent: Noam Chomsky and the Media', 'A film about the noted American linguist/political dissident and his warning about corporate media''s role in modern propaganda.', '1992-11-06', 7.61, 'https://image.tmdb.org/t/p/w500/2Izpz5pgB5ScVrXkIxK4TXDxZLn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36955, 'True Lies', 'A fearless, globe-trotting, terrorist-battling secret agent has his life turned upside down when he discovers his wife might be having an affair with a used car salesman while terrorists smuggle nuclear war heads into the United States.', '1994-07-15', 7.10, 'https://image.tmdb.org/t/p/w500/pqdvCBDThAOjlA0XBzbNm7GvwpU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36968, 'Life-Size', 'Sad and lonely after the death of her mother, Casey would do anything to see her again. But when a series of mystic mishaps mistakenly brings her fashion doll “Eve” to life instead, it changes Casey’s world forever!', '2000-03-05', 6.54, 'https://image.tmdb.org/t/p/w500/kS91p5rwK0A0VGmBISVWK6O3So5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36970, 'Oceans', 'An ecological drama/documentary, filmed throughout the globe. Part thriller, part meditation on the vanishing wonders of the sub-aquatic world.', '2010-01-22', 7.46, 'https://image.tmdb.org/t/p/w500/kIT3G7QoV1vatMCL8TAA3xnkO2V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36797, 'RocketMan', 'An accident-prone and obnoxious geek joins a NASA space mission to Mars. During the flight, he manages to put himself and the entire crew in jeopardy, but is in danger of emerging as a hero when his new colleagues need him to save them from the unforgiving surface of the red planet.', '1997-10-10', 5.22, 'https://image.tmdb.org/t/p/w500/6ejazTl7f8lWY3quZhenIOyOfED.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36972, 'Scooby Goes Hollywood', 'Shaggy and Scooby-Doo quit their Saturday morning TV series in pursuit of Hollywood stardom.', '1979-12-23', 7.46, 'https://image.tmdb.org/t/p/w500/t0DDWZVOyRjrpotc2qOvcFsRryp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36915, 'Heaven''s Prisoners', 'A hardened New Orleans cop, Dave Robicheaux, finally tosses in the badge and settles into life on the bayou with his wife. But a bizarre plane crash draws him back into the fray when his family is viciously threatened.', '1996-05-17', 5.33, 'https://image.tmdb.org/t/p/w500/yUWVNHA3dVc1CmxNIcXZWqbqWc8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36983, 'Tornado!', 'An accountant sent to produce an evaluation of a tornado research project, and the scientist running the project pursue tornadoes and each other.', '1996-05-06', 5.65, 'https://image.tmdb.org/t/p/w500/kzQNHyfqdbUdpJqHyqtZSQYxq5F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36998, 'The Eighth Day', 'An unusual and wonderful friendship develops between a busy but unhappy salesman and a resident of a mental asylum.', '1996-05-22', 7.30, 'https://image.tmdb.org/t/p/w500/cgpJTvFcd0NJyJRTKYaBoLMuqdW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37022, 'Saved By the Bell: Hawaiian Style', 'Kelly''s grandpa invites the whole gang to his little hotel "The Hideaway" in Hawaii for summer vacation. They expect a marvelous time at the beach - without Belding. Upon arriving, they quickly learn that not only is Belding there, but they also have to help Kelly''s grandpa from losing his hotel. Meanwhile Zack meets (again) the love of his life, Jessie and Slater bet with Lisa that they won''t fight, and Screech gets kidnapped by the Pupuku clan.', '1992-11-27', 6.27, 'https://image.tmdb.org/t/p/w500/jpUVeuVpeX2cNrA7GL0j2jxL9xC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37056, 'Letters to Juliet', 'An American girl on vacation in Italy finds an unanswered "letter to Juliet" -- one of thousands of missives left at the fictional lover''s Verona courtyard, which are typically answered by the "secretaries of Juliet" -- and she goes on a quest to find the lovers referenced in the letter.', '2010-05-13', 7.00, 'https://image.tmdb.org/t/p/w500/y9DdvY1IRNS2hWLq161hmP2gXn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37058, 'I''m Here', 'A library assistant plods through an ordinary life in LA until a chance meeting opens his eyes to the power of creativity and ultimately, love. When this new life and love begin to fall apart, he discovers he has a lot to give. This short film proves that ordinary is no place to be.', '2010-03-01', 7.20, 'https://image.tmdb.org/t/p/w500/1jq9zUwPIFGid3BMrLLcm3YY2nY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37088, 'Aileen: Life and Death of a Serial Killer', 'British documentarian Nick Broomfield creates a follow-up piece to his 1992 documentary of the serial killer Aileen Wuornos, a highway prostitute who was convicted of killing six men in Florida between 1989 and 1990. Interviewing an increasingly mentally unstable Wuornos, Broomfield captures the distorted mind of a murderer whom the state of Florida deems of sound mind -- and therefore fit to execute. Throughout the film, Broomfield includes footage of his testimony at Wuornos'' trial.', '2003-11-21', 6.72, 'https://image.tmdb.org/t/p/w500/6MJpX3xlQicN2zIBhPsjpyyIWH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37094, 'Falling Down', 'An ordinary man frustrated with the various flaws he sees in society begins to psychotically and violently lash out against them.', '1993-02-26', 7.40, 'https://image.tmdb.org/t/p/w500/7ujqyF96Zg3rfrsh9M0cEF0Yzqj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36758, 'The Portrait of a Lady', 'Ms. Isabel Archer isn''t afraid to challenge societal norms. Impressed by her free spirit, her kindhearted cousin writes her into his fatally ill father''s will. Suddenly rich and independent, Isabelle ventures into the world, along the way befriending a cynical intellectual and romancing an art enthusiast. However, the advantage of her affluence is called into question when she realizes the extent to which her money colors her relationships.', '1996-10-17', 5.95, 'https://image.tmdb.org/t/p/w500/yoUuMtWTQXzfARYE0nF7Nn7gRuS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37129, 'Only Old Men Are Going to Battle', 'Alexey Titarenko is very talented pilot and brave leader of "Singing group". He also must look after some new cadets and fight together with them against German Luftwaffe planes. Close to Alexey always are his friends, they are all from different parts of the country, but they all became real brothers.', '1974-08-12', 7.89, 'https://image.tmdb.org/t/p/w500/4TE8gM826e1OU62AErJ5LS4F1os.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36540, 'Winnie the Pooh and the Honey Tree', 'Christopher Robin''s bear attempts to raid a beehive in a tall tree.', '1966-02-04', 7.63, 'https://image.tmdb.org/t/p/w500/7Y0F2gWQwbEmh0d3TGIAMguIv4S.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37133, 'Volga - Volga', 'Widely claimed to be Joseph Stalin''s favorite movie, this classic musical comedy is a must-see. The action takes place on a steamboat on the iconic Volga River, as two groups of performers travel to Moscow to perform in the Moscow Musical Olympiad.', '1938-04-24', 6.90, 'https://image.tmdb.org/t/p/w500/yDunXhmYjX7yjG4q3exMewj6zZw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37108, 'A Kid in King Arthur''s Court', 'A Southern California kid named Calvin Fuller is magically transported to the medieval kingdom of Camelot through a crack in the ground caused by an earthquake. Once there, he learns he was summoned by the wizard Merlin, who needs Calvin to save Camelot. Using dazzling modern inventions, can Calvin help King Arthur retain his crown and thwart the evil Lord Belasco?', '1995-08-11', 4.95, 'https://image.tmdb.org/t/p/w500/q7A67rr8f3hESsr4MYb4CEOzF7v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37135, 'Tarzan', 'Tarzan was a small orphan who was raised by an ape named Kala since he was a child. He believed that this was his family, but on an expedition Jane Porter is rescued by Tarzan. He then finds out that he''s human. Now Tarzan must make the decision as to which family he should belong to...', '1999-06-17', 7.41, 'https://image.tmdb.org/t/p/w500/bTvHlcqiOjGa3lFtbrTLTM3zasY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37137, 'The Naked Gun 2½: The Smell of Fear', 'Bumbling lieutenant Frank Drebin is out to foil the big boys in the energy industry, who intend to suppress technology that will put them out of business.', '1991-06-28', 6.82, 'https://image.tmdb.org/t/p/w500/v9niLQWVzVPB1cP1ThNdEaLZG1Q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37141, 'The Babysitter', 'Jennifer is a lovely teen who has been hired to baby-sit the kids of Harry Tucker and his wife, Dolly. The Tuckers go to a party and proceed to get inebriated, with Mr. Tucker fantasizing about his beautiful baby sitter. Meanwhile, Jack, her boyfriend, and Mark, another guy interested in her, decide to spy on Jennifer at the Tucker house, with each young man also fixated on her.', '1995-10-17', 5.13, 'https://image.tmdb.org/t/p/w500/wOv6HKiKTcDiyZRXPOsjm2JhVZV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37144, 'True Crime', 'Mary Giordano is a bright, intelligent student who goes to a catholic school. She also has an addiction to mystery novels and detective magazines, which inspire her to do her own detective work. When she starts snooping around on the case of a murderer of teenage girls, it gets her in hot water with her mentor Detective Jerry Gunn. But it also starts a team up with police cadet Tony Campbell. The two work together to find the murderer. But the closer Mary gets to solving the murder, the more danger she puts herself in of being the next victim.', '1995-12-01', 5.70, 'https://image.tmdb.org/t/p/w500/nPYe83tWVSwVFRyWa6f5aaE7bbu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37146, 'Penn & Teller Get Killed', 'The "bad boys of magic" go over the edge in this mind-blowing, role-switching comedy murder mystery set in the dizzying world of Atlantic City casinos. In a TV interview, Penn mentions his idea of a fun practical joke: "I wish someone were trying to kill me. It would give focus to my life, excitement. I''d be like James Bond." Twenty million people hear him. One decides to deliver a punchline he''ll never forget. Made by people who thought Psycho was a comedy, Penn & Teller Get Killed (they also wrote the piece) features Caitlin Clarke as the femme fatale and David Patrick Kelly as the Edgar Allan Poe-esque nutcase with a new mission. Arthur Penn, known for hip masterpieces like Bonnie and Clyde, Alice''s Restaurant and Little Big Man, directs with roller-coaster pacing and subversive intelligence.', '1989-09-22', 5.58, 'https://image.tmdb.org/t/p/w500/UAa8AVZfNiISv3K8eKfyuzSAxI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36362, 'King of Kings', 'Who is Jesus, and why does he impact all he meets? He is respected and reviled, emulated and accused, beloved, betrayed, and finally crucified. Yet that terrible fate would not be the end of the story.', '1961-10-11', 7.14, 'https://image.tmdb.org/t/p/w500/fp1Nx4FASTGldFuQyGXN0HF6Jgk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37136, 'The Naked Gun: From the Files of Police Squad!', 'When the bumbling Lieutenant Frank Drebin investigates events following the shooting of his partner, he stumbles upon an attempt to assassinate Queen Elizabeth II.', '1988-12-02', 7.28, 'https://image.tmdb.org/t/p/w500/zT0mhZqZQJE1gSY5Eg9qcGP4NYo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37169, 'The Human Centipede (First Sequence)', 'During a stopover in Germany in the middle of a carefree road trip through Europe, two American girls find themselves alone at night when their car breaks down in the woods. Searching for help at a nearby villa, they are wooed into the clutches of a deranged retired surgeon, who has a very disturbed vision.', '2009-10-31', 5.17, 'https://image.tmdb.org/t/p/w500/gMtjxIkEi0hnTV5lPHbgeZ4ZpUZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37191, 'I, the Jury', 'Jack Williams was the best friend of Vietnam veteran and detective Mike Hammer. When Jack is murdered, Mike makes it his business to solve the crime. He is helped by his secretary Velda, and partly helped, partly hindered by the Chief of Police, Pat Chambers. On the trail of the killer, Mike discovers government conspiracies, and plots used by the CIA and the Mafia.', '1982-04-22', 5.71, 'https://image.tmdb.org/t/p/w500/11UUzdaxwPjX8Mfw1ZIpMTY3y6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37244, 'Leave It to Beaver', 'The Cleavers are an all-American family living in Ohio – wise father Ward, loving mother June, teenage son Wally, and 8-year-old Theodore, better known as ''Beaver''. Beaver hopes to get a bike as a gift from his father and to please him tries out for his school football team and he makes it, only to be embarrassed. The bike he gets is quickly stolen. Meanwhile, Wally is trying to help his friend Eddie Haskell to get the heart of pretty classmate Karen, but Karen seems to like Wally more, and that leads to tensions between the friends.', '1997-08-22', 5.43, 'https://image.tmdb.org/t/p/w500/zBe7rCrImp9XxSGWTWAmYlPEXeN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36357, 'Rent-a-Kid', 'Harry Habert, owner of a rental company, has an original idea—to rent baby''s from a nearby orphanage to local families. He rents the Ward siblings, 2 boys and a girl, to his first customers.', '1995-01-01', 5.59, 'https://image.tmdb.org/t/p/w500/hnL5TxGumlBy68D4HovSlndEIkz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36773, 'The Third Miracle', 'The Vatican sends a priest to verify some miracles, performed by a woman who has been nominated for sainthood...', '1999-11-18', 5.88, 'https://image.tmdb.org/t/p/w500/lkxqF5lQSVoLk9ikALSByJgBPoN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36555, 'Best of the Best 3: No Turning Back', 'A martial arts instructor comes to the defense of a schoolteacher who has taken a stand against a local white supremacist organization.', '1995-05-17', 5.61, 'https://image.tmdb.org/t/p/w500/kUZ2Hbj2Gjpou5uQVzgqh2ELZiK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36940, 'The First Beautiful Thing', 'The film tells the story of the Michelucci family, from the nineteen-seventies to the present day: the central character is the stunningly beautiful Anna, the lively, frivolous and sometimes embarrassing mother of Bruno and Valeria. Everything begins in the Summer of 1971, at the annual Summer beauty pageant held at Livorno’s most popular bathing establishment. Anna is unexpectedly crowned “Most Beautiful Mother”, unwittingly stirring the violent jealousy of her husband. From then on, chaos strikes the family and for Anna, Bruno and his sister Valeria, it is the start of an adventure that will only end thirty years later.', '2010-01-15', 7.24, 'https://image.tmdb.org/t/p/w500/7h4BbIGigxaECJFQWEaQ9ih3INp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36492, 'Carnal Knowledge', 'Two lifelong friends navigate complex sexual encounters and emotional entanglements, wrestling with societal norms and personal desires.', '1971-06-30', 6.56, 'https://image.tmdb.org/t/p/w500/l7e1qP8Mq97W1Wg14FNnbz1OxmG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37165, 'The Truman Show', 'In a picture-perfect seaside town, an insurance salesman begins to realize that his entire existence may be staged and observed by a vast unseen audience as part of a long-running real-time reality TV show.', '1998-06-04', 8.16, 'https://image.tmdb.org/t/p/w500/vuza0WqY239yBXOadKlGwJsZJFE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37239, 'Antonio Gaudí', 'Catalan architect Antonio Gaudí (1852-1926) designed some of the world''s most astonishing buildings, interiors, and parks; Japanese director Hiroshi Teshigahara constructed some of the most aesthetically audacious films ever made. With camera work as bold and sensual as the curves of his subject''s organic structures, Teshigahara immortalizes Gaudí on film.', '1984-05-25', 7.11, 'https://image.tmdb.org/t/p/w500/5avrBzIW7mXrUmUAz8gNz8KxXhB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36443, 'The Union: The Business Behind Getting High', 'Filmmaker Adam Scorgie explores the illegal marijuana industry in British Columbia, revealing how the international business is most likely more profitable than it would be if it was lawful in this enlightening documentary. Marijuana growers, law enforcement officials, physicians, politicians, criminologists, economists and celebrities—including comedian Tommy Chong—shed light on this topical subject in a series of compelling interviews.', '2007-05-08', 7.34, 'https://image.tmdb.org/t/p/w500/6szDJcCbjyAilGVaqUbT9k5bD7G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37272, 'A Cool, Dry Place', 'Russell, a single father, balances his work as a lawyer with the care of his five-year-old son after his wife abandoned them. When she reappears creating turmoil, he must deal with his new love interest and the job opportunity of a lifetime.', '1998-04-03', 5.86, 'https://image.tmdb.org/t/p/w500/c1pyoTbc3xkLTIhPnj153CVUsRn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36807, 'The 6th Man', 'A college athlete returns from the dead to help his brother''s basketball team win the NCAA title.', '1997-03-28', 6.10, 'https://image.tmdb.org/t/p/w500/c08PAB0kWE38zrOGl376D9qqdEc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36800, 'Metropia', 'In the near future, oil reserves are nearly depleted and Europe is connected by series of underground tunnels. While navigating these tunnels, Roger hears voices, one in particular. Seeking a way to rid himself of the voice only leads Roger deeper into a bizarre conspiracy of control - mind and body.', '2009-10-21', 6.09, 'https://image.tmdb.org/t/p/w500/oo9IJvDKUrhYS7zDimuoSJUPG79.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37258, 'Equus', 'A psychiatrist, Martin Dysart, investigates the savage blinding of six horses with a metal spike in a stable in Hampshire, England. The atrocity was committed by an unassuming seventeen-year-old stable boy named Alan Strang, the only son of an opinionated but inwardly-timid father and a genteel, religious mother. As Dysart exposes the truths behind the boy''s demons, he finds himself face-to-face with his own.', '1977-10-16', 6.99, 'https://image.tmdb.org/t/p/w500/tGjbZqTaq73jcOrcYD3j0trMRKG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37233, 'The Firm', 'Mitch McDeere is a young man with a promising future in Law. About to sit his Bar exam, he is approached by ''The Firm'' and made an offer he doesn''t refuse. Seduced by the money and gifts showered on him, he is totally oblivious to the more sinister side of his company. Then, two Associates are murdered. The FBI contact him, asking him for information and suddenly his life is ruined. He has a choice - work with the FBI, or stay with the Firm. Either way he will lose his life as he knows it. Mitch figures the only way out is to follow his own plan...', '1993-06-30', 6.74, 'https://image.tmdb.org/t/p/w500/kFexXCzidkm4LwlgZqxsJsDQB5v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36834, 'Total Eclipse', 'Young, wild poet Arthur Rimbaud and his mentor Paul Verlaine engage in a fierce, forbidden romance while feeling the effects of a hellish artistic lifestyle.', '1995-11-03', 6.42, 'https://image.tmdb.org/t/p/w500/9ihmgsX9aDXZmwjvgrzJgH8FxNa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37495, 'Four Lions', 'Four Lions tells the story of a group of British jihadists who push their abstract dreams of glory to the breaking point. As the wheels fly off, and their competing ideologies clash, what emerges is an emotionally engaging (and entirely plausible) farce.', '2010-05-07', 6.95, 'https://image.tmdb.org/t/p/w500/x4JzaRPXBs9wiHCe3e3ymXWuwfd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37498, 'Knock Off', 'A fashion designer and his CIA agent business partner must join forces to stop a group of terrorists from smuggling explosives in counterfeit jeans during the handover of Hong Kong.', '1998-09-04', 5.36, 'https://image.tmdb.org/t/p/w500/hK7hKDA51FCbtFCuXZNiQ6gPq3S.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37511, 'Stingray Sam', 'A dangerous mission reunites Stingray Sam with his long lost accomplice, The Quasar Kid. Follow these two space-convicts as they earn their freedom in exchange for the rescue of a young girl who is being held captive by the genetically designed figurehead of a very wealthy planet.', '2009-01-20', 6.97, 'https://image.tmdb.org/t/p/w500/luXQBRpFdaQF9E9YEq9GaopzqiK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37527, 'Dr. Giggles', 'In 1957, Evan Rendell flees after his father is lynched for killing multiple patients in his effort to find a replacement heart for his ailing wife. After 35 years, Evan escapes from a mental institution and returns to town for revenge, killing off residents one by one. When Jennifer and her friends break into the Rendell house out of morbid curiosity, Evan notices Jennifer has a heart condition similar to his mother and decides to make her his final victim.', '1992-10-23', 5.54, 'https://image.tmdb.org/t/p/w500/xd2gbzKxJSdKgNDMHYehfl4xt8j.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37247, 'The Graduate', 'A disillusioned college graduate finds himself torn between his older lover and her daughter.', '1967-12-21', 7.60, 'https://image.tmdb.org/t/p/w500/8XaDpF0COV1MLsDirJMnxmYc1Wp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37530, 'House II: The Second Story', 'Jesse moves into an old family property where his parents were mysteriously murdered years before. He soon finds himself with unexpected guests in the form of his mummified great-great grandfather, a mystical crystal skull, and a zombie cowboy.', '1987-05-14', 5.55, 'https://image.tmdb.org/t/p/w500/o58So9NfjKPITUQhQdpCUdTi9Vn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36914, 'Like Father Like Son', 'Dr. Jack Hammond has best chances to become medical superintendent in the clinic. So he''s completely absorbed in his work and has no understanding for his teenage son Chris'' problems with school. By accident one of them drinks a brain-exchanging serum, and it switches their identities. This leads of course to extraordinary complications in school and at work, but also to insight in the problems and feelings of each other.', '1987-10-02', 5.73, 'https://image.tmdb.org/t/p/w500/68OY9pYmKc3F2G6yxaXhxhnnFcU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37557, 'Shanghai Triad', 'Shanghai, China, 1930. When young Shuisheng arrives from the countryside, his uncle Liushu puts him at the service of Bijou, the mistress of Laoda, supreme boss of the Tang Triad, constantly threatened by his enemies, both those he knows and those lurking in the shadows.', '1995-09-14', 6.77, 'https://image.tmdb.org/t/p/w500/tzG1UxUSfPACREjgBrsPDRUvneH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36801, 'Cemetery Junction', 'In 1970s England, three blue-collar friends spend their days joking, drinking, fighting and chasing girls. Freddie wants to leave their working-class world but cool, charismatic Bruce and lovable loser Snork are happy with life the way it is. When Freddie gets a new job as a door-to-door salesman and bumps into his old school sweetheart Julie, the gang are forced to make choices that will change their lives for ever.', '2010-04-14', 6.51, 'https://image.tmdb.org/t/p/w500/9fyzMdRX1kWd9UnceWc2Duh4eFt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37565, 'St Trinian''s 2: The Legend of Fritton''s Gold', 'After a wealthy philanthropist expresses an unusual interest in a ring found by her niece Annabelle, Miss Fritton explains that she''s descended from a pirate who, in 1598, stole treasure from another: the philanthropist''s ancestor. This discovery sends the racuous girls of St. Trinians on the hunt for buried treasure.', '2009-12-18', 5.60, 'https://image.tmdb.org/t/p/w500/pkLP6uusA3RlgKHUZZ1uWVwbucc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37567, 'Fall', 'For Michael Shiver, life as an easy-going cab driver in New York suddenly changes when he picks up supermodel Sarah Easton and falls head over heels in love. But Sarah has more than just passion on her mind; she also has a husband and a glamorous lifestyle that she can''t seem to leave behind. Torn between her feelings for Michael and the security of her marriage, Sarah is forced to make a realistic decision about the sacrifices that must be made to be truly and totally in love.', '1997-06-20', 6.23, 'https://image.tmdb.org/t/p/w500/4nRzyiVckWoqE9Vpm35yZTrfkJM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37588, 'Bruce Lee: A Warrior''s Journey', 'Documentary on the legendary martial artist Bruce Lee, with a focus on the production of his unfinished film Game of Death. Using interviews and behind-the-scenes footage, Lee aficionado John Little paints a portrait of the world''s most famous action hero, concluding with a new cut of Game of Death''s action finale, reconstructed from Lee''s notes and recently-recovered footage.', '2000-10-22', 7.30, 'https://image.tmdb.org/t/p/w500/oSJhm6X4FOAmBSEfTe2OvqGuBN0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37606, 'Valmont', 'Set in Baroque France, a scheming widow and her lover make a bet regarding the corruption of a recently married woman. The lover, Valmont, bets that he can seduce her, even though she is an honorable woman. If he wins, he can have his lover to do as he will. However, in the process of seducing the married woman, Valmont falls in love.', '1989-11-17', 6.72, 'https://image.tmdb.org/t/p/w500/AuCnhQII6ZNgRDrr2N5KyDCnhnj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37563, 'A Summer''s Tale', 'Awaiting his girlfriend Léna’s arrival at the Breton seaside resort of Dinard, Gaspard befriends — and flirts heavily with — two other women, the companionable ethnology student Margot and the sensual townie Solène, making for a rather complicated situation when Léna finally arrives.', '1996-06-05', 7.30, 'https://image.tmdb.org/t/p/w500/l3syqgYqqfqPVheINI5jOBN5hXL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37616, 'Palookaville', 'Jerry and his two pals, Russ and Syd, are just looking for some easy money to help them break out of their nowhere lives in their nowhere town. Despite a bungled jewelry store heist which exposes their incompetence as criminals, a fateful event (and an old black-and-white film) convinces them that they can pull off an armored-truck robbery. While they are busy plotting their caper, their dysfunctional families spin out of control, all around them.', '1996-10-25', 5.91, 'https://image.tmdb.org/t/p/w500/vmlO5CbUKmqvn5BVtEprxAmNOkp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37618, 'The Asphyx', 'Hugo is a brilliant turn-of-the-century scientist, loved and respected by his family and friends, admired by his colleagues. But he is a man quickly becoming obsessed with a curious and frightening question...What is the mysterious apparition found in the photographs of his dying subjects?', '1972-12-05', 6.02, 'https://image.tmdb.org/t/p/w500/grAI6PofWfdW41bNUY5uKRiLn4z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36815, 'The Agony and the Ecstasy', 'During the Italian Renaissance, Pope Julius II contracts the influential artist Michelangelo to sculpt 40 statues for his tomb. When the pope changes his mind and asks the sculptor to paint a mural in the Sistine Chapel, Michelangelo doubts his painting skills and abandons the project. Divine inspiration returns Michelangelo to the mural, but his artistic vision clashes with the pope''s demanding personality and threatens the success of the historic painting.', '1965-09-16', 7.10, 'https://image.tmdb.org/t/p/w500/4ZiwyXtyxYDmMnNiVemCPgxY8X6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37296, 'Protocol', 'A Washington waitress saves the Emir of Ohtar''s life, launching her diplomatic career and a scandal.', '1984-12-21', 5.48, 'https://image.tmdb.org/t/p/w500/7iCRH6gcLhYCQBpiJisKNKuTqwE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37257, 'Witness for the Prosecution', 'An ailing barrister is thrust back into the courtroom in what becomes one of the most unusual and eventful murder cases of the lawyer''s career when he finds himself defending a man being tried for the murder of a socialite.', '1957-12-17', 8.20, 'https://image.tmdb.org/t/p/w500/bCj4EfuehAlgBwVd3diyWyhuuau.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37632, 'The Order', 'When Rudy, an artifacts smuggler, goes to Jerusalem to rescue his kidnapped archeologist father, he faces deportation by a scheming police chief. Now, to find his dad and recover a sacred scroll, he''ll have to outwit officials and a ruthless sect. With the help of a beautiful Israeli cop, Rudy battles a faction of religious zealots determined to see a holy war at all costs.', '2001-05-05', 5.11, 'https://image.tmdb.org/t/p/w500/xcs2taqwgKu2tDrcXd2k7XbtmLq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37659, 'When You''re Strange', 'The creative chemistry of four brilliant artists —drummer John Densmore, guitarist Robby Kreiger, keyboardist Ray Manzarek and singer Jim Morrison— made The Doors one of America''s most iconic and influential rock bands. Using footage shot between their formation in 1965 and Morrison''s death in 1971, it follows the band from the corridors of UCLA''s film school, where Manzarek and Morrison met, to the stages of sold-out arenas.', '2010-04-09', 7.30, 'https://image.tmdb.org/t/p/w500/yd5X8f1mt13ETAWLI7dp0MEEZLL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37662, 'The Railway Children', 'At the dawn of the 20th century, following their father''s arrest on suspicion of betraying state secrets, the three Waterbury children—Bobbie, Phyllis and Peter—move with their mother to Yorkshire, where they find themselves involved in unexpected dramas along the railway by their new home.', '1970-12-21', 6.74, 'https://image.tmdb.org/t/p/w500/kusEIHfdngzcypY36yjWJVWMShj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37691, 'Bread and Roses', 'Quick-witted young Maya comes over the Mexican border without papers and makes her way to the LA home of her older sister Rosa. Rosa gets Maya a job as a janitor: a non-union janitorial service has the contract, the profane supervisor can fire workers on a whim, and the service-workers'' union has assigned organiser Sam Shapiro to bring its ''justice for janitors'' campaign to the building. Sam finds Maya a willing listener, she''s also attracted to him. Rosa resists, she has an ailing husband to consider. The workers try for public support; management intimidates workers to divide and conquer. Rosa and Maya as well as workers and management may be set to collide.', '2000-09-14', 6.30, 'https://image.tmdb.org/t/p/w500/aNk0yx0xRcs66OdByiy2pJaFhI6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37696, 'Fear X', 'When his wife is killed in a seemingly random incident, Harry, prompted by mysterious visions, journeys to discover the true circumstances surrounding her murder.', '2003-04-04', 5.84, 'https://image.tmdb.org/t/p/w500/jOOfGiaZUMyrB9cZafFKjXErtoK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37686, 'Super 8', 'In late 1970s Ohio, a group of friends filming a homemade zombie movie witness a devastating train derailment. Soon after, their quiet town is gripped by unexplained disappearances, strange phenomena, and a growing sense of fear, as they uncover that something terrifying has been set loose.', '2011-06-09', 6.78, 'https://image.tmdb.org/t/p/w500/pUWIjaMMYJjeBm5bJyE3mIXdQ62.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37698, 'The Roaring Twenties', 'After World War I, Armistice Lloyd Hart goes back to practice law, former saloon keeper George Hally turns to bootlegging, and out-of-work Eddie Bartlett becomes a cab driver. Eddie builds a fleet of cabs through delivery of bootleg liquor and hires Lloyd as his lawyer. George becomes Eddie''s partner and the rackets flourish until love and rivalry interfere.', '1939-10-28', 7.55, 'https://image.tmdb.org/t/p/w500/nkymdElqwJBm2bl3F6hJp4xJggD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37710, 'The Tourist', 'American tourist Frank meets mysterious British woman Elise on the train to Venice. Romance seems to bud, but there''s more to her than meets the eye.', '2010-12-08', 6.18, 'https://image.tmdb.org/t/p/w500/qwfUH9gnvaXwvVRsgbL4L2jpLUz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37345, 'Princess Caraboo', 'Bristol, England, early 19th century. A beautiful young stranger who speaks a weird language is tried for the crime of begging. But when a man claims that he can translate her dialect, it is understood that the woman is a princess from a far away land. She is then welcomed by a family of haughty aristocrats that only wants to heighten their prestige. However, the local reporter is not at all convinced she is what she claims to be and investigates. Is Caraboo really a princess?', '1994-09-16', 5.53, 'https://image.tmdb.org/t/p/w500/a3Fw33tSGdO2eV8SULQigOITzH4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37735, 'Easy A', 'Olive, an average high school student, sees her below-the-radar existence turn around overnight once she decides to use the school''s gossip grapevine to advance her social standing. Now her classmates are turning against her and the school board is becoming concerned, including her favorite teacher and the distracted guidance counselor. With the support of her hilariously idiosyncratic parents and a little help from a long-time crush, Olive attempts to take on her notorious new identity and crush the rumor mill once and for all.', '2010-09-16', 6.80, 'https://image.tmdb.org/t/p/w500/v5f1qO6NJnxWgONgkYg21TW39DT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (36929, 'Big Bully', 'A writer returns to his hometown where he faces the childhood nemesis whose life he ultimately ruined, only the bully wants to relive their painful past by torturing him once again.', '1996-01-26', 4.69, 'https://image.tmdb.org/t/p/w500/dws3JR4Yi325Tz33XnuXEB6XjGr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37748, '800 Bullets', 'Almería, Tabernas desert, Spain, 2002. Texas Hollywood is a dilapidated and dusty town where Western movies have not been shot for decades. Julián Torralba and his partners, veteran film stuntmen, survive there, recreating pathetic action scenes for the pleasure of the few foreign tourists who visit the isolated region.', '2002-10-18', 5.83, 'https://image.tmdb.org/t/p/w500/f8tqwtxk0xUJA8fHaKqxZ0G8ey4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37658, 'Anthony Adverse', 'Based on the novel by Hervey Allen, this expansive drama follows the many adventures of the eponymous hero, Anthony Adverse. Abandoned at a convent by his heartless nobleman father, Don Luis, Anthony is later mentored by his kind grandfather, John Bonnyfeather, and falls for the beautiful Angela Giuseppe. When circumstances separate Anthony and Angela and he embarks on a long journey, he must find his way back to her, no matter what the cost.', '1936-08-26', 5.69, 'https://image.tmdb.org/t/p/w500/9SPjkq5z86t80Q7XBw8AG2si2vQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37433, 'Neo Tokyo', 'A trilogy of separate stories. In "Labyrinth labyrinthos", a girl and her cat enter a strange world. In "Running Man", a racer takes on the ultimate opponent. In "Construction Cancellation Order", a man must shut down worker robots.', '1989-04-15', 6.76, 'https://image.tmdb.org/t/p/w500/3tQqkfhE2v03OXK4ocxKQ4rnkaC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37291, 'Trust', 'After being thrown away from home, pregnant high school dropout Maria meets Matthew, a highly educated and extremely moody electronics repairman. The two begin an unusual romance built on their sense of mutual admiration and trust.', '1990-09-09', 6.81, 'https://image.tmdb.org/t/p/w500/9wE7LuIkvuPfr4Ye6fMqPXHqaiE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37719, 'A Night at the Opera', 'The Marx Brothers take on high society and the opera world to bring two lovers together. A sly business manager and two wacky friends of two opera singers help them achieve success while humiliating their stuffy and snobbish enemies.', '1935-11-15', 7.39, 'https://image.tmdb.org/t/p/w500/A4YDGfJwaG7aMxDVrVJsOHJ7ufK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37302, 'Left Behind', 'After learning that millions have completely vanished, an airline pilot, a journalist, and others work together to unravel the mystery of those left behind.', '2000-10-30', 4.22, 'https://image.tmdb.org/t/p/w500/5kT3kifA8Xwkjm1YmSubTw1GwK0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37636, 'High Art', 'When Syd, a young editor at an influential art magazine,  becomes involved with her neighbor, a drug-addicted lesbian photographer, both seek to exploit each other for their respective careers while slowly falling in love with each other.', '1998-06-12', 6.19, 'https://image.tmdb.org/t/p/w500/lMXSGQIKTaM4bDkshmEHXHtfa7l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37834, 'Knight and Day', 'A fugitive couple goes on a glamorous and sometimes deadly adventure where nothing and no one – even themselves – are what they seem. Amid shifting alliances and unexpected betrayals, they race across the globe, with their survival ultimately hinging on the battle of truth vs. trust.', '2010-06-15', 6.24, 'https://image.tmdb.org/t/p/w500/phhp52CZZJiGYmiOTp9ZBDkGHB3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37718, 'The Muse', 'With his career on the skids, a Hollywood screenwriter enlists the aid of a modern-day muse, who proves to test his patience.', '1999-08-27', 5.22, 'https://image.tmdb.org/t/p/w500/hmtvDW52V3EuFmbhTOLjaGMYCDx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37843, 'Blood Beach', 'Something or someone is attacking people one by one on the beach. Some of them are mutilated, but most of them are sucked into the sand, disappearing without a trace. What is the creature responsible? Where does it live, and where did it come from? And is there any chance of it reproducing? Meanwhile, David Huffman and Mariana Hill are once-almost-married old friends, reunited over the death of her mother on the beach, and searching for clues in the abandoned buildings where they used to play when they were young.', '1980-09-01', 4.85, 'https://image.tmdb.org/t/p/w500/3BfSQmwTm8LGv2KZKcDJnFuBbIC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37853, 'Mister Roberts', 'Mr. Roberts is a Navy officer who''s yearning for battle but is stuck in the backwaters of World War II on a non-commissioned ship run by the bullying Captain Morton.', '1955-07-10', 7.04, 'https://image.tmdb.org/t/p/w500/5B8Gc1N2S3CDWHBzm0VxaMPTyzJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37292, 'Broken Arrow', 'Indian scout Tom Jeffords is sent out to stem the war between the American settlers and Apaches in the late 1870s Arizona. He learns that the Indians kill only to protect themselves, or out of retaliation for white atrocities.', '1950-07-21', 6.70, 'https://image.tmdb.org/t/p/w500/n061xgOTAvJ2l06latNDF4s13FV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37861, 'Valhalla Rising', 'Scandinavia, 1,000 AD. For years, One Eye, a mute warrior of supernatural strength, has been held prisoner by the Norse chieftain Barde. Aided by Are, a boy slave, One Eye slays his captor and together he and Are escape, beginning a journey into the heart of darkness. On their flight, One Eye and Are board a Viking vessel, but the ship is soon engulfed by an endless fog that clears only as the crew sights an unknown land. As the new world reveals its secrets and the Vikings confront their terrible and bloody fate, One Eye discovers his true self.', '2009-09-04', 6.10, 'https://image.tmdb.org/t/p/w500/7LBMcAx6XHwEduIsBYipvUke9n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37905, 'The Horde', 'A bunch of crooked cops raid a ruined building located in an impoverished suburb of Paris, determined to furiously avenge the death of one of them, murdered by the ruthless criminal gang hidden on top of the dark labyrinth that will become a deathly trap when the living, unexpectedly turned into the undead by a mysterious plague, begin to devour the world.', '2010-02-10', 6.00, 'https://image.tmdb.org/t/p/w500/c3sYdfCg1vz6DG4XlQRpu8baxvM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37891, 'Andrew Dice Clay: Dice Rules', 'Outrageous, misogynistic and vulgar-to-the-max comedian Andrew Dice Clay does his stuff in this combination stand-up concert video and series of comedy sketches. The sketches, demonstrating that The Dice Man used to be a klutzy wimp, begin the film which then jumps into a filled-to-capacity performance at Madison Square Gardens. The film contains strong profanity, blatant racist remarks, graphic references to sex and other "adult" subjects.', '1991-05-17', 7.10, 'https://image.tmdb.org/t/p/w500/yXmkQVETaCr8BHITkLeJe6x1GdA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37903, 'The White Ribbon', 'An aged tailor recalls his life as the schoolteacher of a small village in Northern Germany that was struck by a series of strange events in the year leading up to WWI.', '2009-09-24', 7.47, 'https://image.tmdb.org/t/p/w500/54dlnGDexrwAFlDb8HWKfmmX4LB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37467, 'The Atomic Submarine', 'Ships disappear on route across the Arctic Sea, and a special submarine is sent to investigate.', '1959-11-29', 5.30, 'https://image.tmdb.org/t/p/w500/vnofOvxhhG7gwAgSR0XJ9Y6JSMp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37910, 'Voices of a Distant Star', 'It is 2046 when a mysterious alien force begins their annihilation of the human race. Leaving behind the one person she loves, Mikako joins the interstellar battle as a pilot. And so - while Mikako risks her life to save mankind - Noboru waits. The two lovers, worlds apart, desperately strive to remain connected as the gap between them widens at a frightening pace.', '2002-02-02', 6.53, 'https://image.tmdb.org/t/p/w500/mvRqW2z4iBws3CDkCNmojksyr4V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37931, 'MacGruber', 'Ex-special operative MacGruber is called back into action to take down his archenemy, Dieter Von Cunth, who''s in possession of a nuclear warhead and bent on destroying Washington, DC.', '2010-05-21', 5.42, 'https://image.tmdb.org/t/p/w500/9cO8JD7aaQzI4q8lBS8MYXH8LrJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37916, 'Swept Away', 'A wealthy woman''s yachting holiday with friends in the Mediterranean Sea takes an unexpected turn when she and one of the boat''s crew are stranded on a desert island. Her capitalist beliefs and his communist convictions clash, but during their struggle to survive, social roles are reversed and heated passions come alive.', '1974-12-18', 7.38, 'https://image.tmdb.org/t/p/w500/8bkEUeQWVFBk3HE4qhluDarTMDj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37924, 'Sweeney Todd', 'A BBC adaptation of the Victorian "penny dreadful" tale of 19th century "demon barber" Sweeney Todd, of Fleet Street, who cuts the throats of unsuspecting clients in his London shop.', '2006-01-03', 6.35, 'https://image.tmdb.org/t/p/w500/40ntPvTqjqEJlME1AtBEzwVUPHC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37936, 'Happy Birthday to Me', 'Virginia is proud that she belongs to a clique. The best students at a private school. But before her 18th birthday, a gruesome set of murders take place and her friends are the ones who are falling prey. Could it be her? She suffers from blackouts due to a freak accident one year earlier. We soon learn the truth behind her accident and what is going on.', '1981-05-15', 6.00, 'https://image.tmdb.org/t/p/w500/8s8Z58Xah3VSe4kfKZFTUJTT33g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37707, 'Splice', 'Elsa and Clive, two young rebellious scientists, defy legal and ethical boundaries and forge ahead with a dangerous experiment: splicing together human and animal DNA to create a new organism. Named "Dren", the creature rapidly develops from a deformed female infant into a beautiful but dangerous winged human-chimera, who forges a bond with both of her creators - only to have that bond turn deadly.', '2010-06-03', 5.88, 'https://image.tmdb.org/t/p/w500/4oqaWnO3dKYAt3vZWAD4oLfOXOC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37964, 'Brown Sugar', 'Sidney and Dre can attribute their lifelong friendship and the launch of their careers to one single childhood instant... witnessing the birth of hip-hop on a New York street corner. Now some 15 years later, she is a revered music critic at a national magazine and he is a successful, though unfulfilled, hip-hop record company executive. Both come to realize that their true life passions will only be fulfilled by remembering what they learned that day on the corner.', '2002-10-05', 6.63, 'https://image.tmdb.org/t/p/w500/n9SnhQk29094VoLfyiYM4viyCrU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
