INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37786, 'Sex and the City 2', 'Carrie, Charlotte, and Miranda are all married now, but they''re still up for a little fun in the sun. When Samantha gets the chance to visit one of the most extravagant vacation destinations on the planet and offers to bring them all along, they surmise that a women-only retreat may be the perfect excuse to eschew their responsibilities and remember what life was like before they decided to settle down.', '2010-05-26', 6.04, 'https://image.tmdb.org/t/p/w500/iHSRxhZsPaVuLCivvV6WEkMVGWU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38019, 'Sunflower', 'Sunflower is the story of the Zhang family in Beijing father, mother and son across three decades, centering on the tensions and misunderstandings between father and son. Nine-year-old Xiangyang is having the time of his life, free of adult supervision until the day he meets the father he can hardly remember. Having spent years away, he returns with strong ideas about his son learning to draw. But Xiangyang chafes under his father''s constant rules and soon stages his own revolution against the lessons enforced.', '2005-09-10', 6.06, 'https://image.tmdb.org/t/p/w500/d7NsjHTppTK8KfFBJRk6J4Su6ct.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38073, 'Going the Distance', 'Erin and Garrett are very much in love. When Erin moves to San Francisco to finish her journalism degree and Garrett stays behind in New York to work in the music industry, they gamely keep the romance alive with webcams and frequent-flyer miles. But just when it seems the lovers will soon be reunited, they each score a big break that could separate them for good.', '2010-08-27', 6.10, 'https://image.tmdb.org/t/p/w500/tTllmSew3nsizpzWNWKUkOuANhm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
