INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38142, '5 Centimeters per Second', 'Three moments in Takaki''s life: his relationship with Akari and their forced separation; his friendship with Kanae, who is secretly in love with him; the demands and disappointments of adulthood, an unhappy life in a cold city.', '2007-03-03', 7.30, 'https://image.tmdb.org/t/p/w500/dFipUR6W0y3PPkuVS8gjFd929m2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37305, 'Pork Chop Hill', 'Korean War, April 1953. Lieutenant Clemons, leader of the King company of the United States Infantry, is ordered to recapture Pork Chop Hill, occupied by a powerful Chinese Army force, while, just seventy miles away, at nearby the village of Panmunjom, a tense cease-fire conference is celebrated.', '1959-05-29', 6.71, 'https://image.tmdb.org/t/p/w500/88LF3thfIx1BDqa5aErseoFXz58.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38148, 'Oh, God! You Devil', 'George Burns is back as God, but oops, here he is as Satan, too. A young rock star is ready to sell his soul to Satan, and Satan is all too happy to oblige. Oops! Seems the fellow was watched over by God as a baby, so now the almighty and his nemesis have to duke it out over the soul.', '1984-11-07', 5.62, 'https://image.tmdb.org/t/p/w500/c5h3BXUQfOPPaKMaq3nsOi5H1Bl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
