INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37725, 'It''s a Boy Girl Thing', 'A visit to a natural history museum proves catastrophic for two high school rivals, an overachiever and a jock, when an ancient Aztec statue casts a spell that causes them to switch bodies and see exactly what it''s like to walk in the other''s shoes.', '2006-07-15', 6.54, 'https://image.tmdb.org/t/p/w500/uA4ZJdlILmIGSqBjfM4mkWvtcTt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37799, 'The Social Network', 'In 2003, Harvard undergrad and computer programmer Mark Zuckerberg begins work on a new concept that eventually turns into the global social network known as Facebook. Six years later, Mark is one of the youngest billionaires ever, but his unprecedented success leads to both personal and legal complications when he ends up on the receiving end of two lawsuits, one involving his former friend.', '2010-10-01', 7.38, 'https://image.tmdb.org/t/p/w500/n0ybibhJtQ5icDqTp8eRytcIHJx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38234, 'Undisputed III: Redemption', 'Russian inmate Boyka, now severely hobbled by the knee injury suffered at the end of Undisputed 2. No longer the feared prison fighter he was, he has declined so far that he is now good only for cleaning toilets. But when a new prison fight tournament begins - an international affair, matching the best fighters from prisons around the globe, enticing them with the promise of freedom for the winner - Boyka must reclaim his dignity and fight for his position in the tournament.', '2010-04-17', 7.59, 'https://image.tmdb.org/t/p/w500/g8KB77SPA7SyU8eid6TAEpt9skU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38031, 'You Will Meet a Tall Dark Stranger', 'Two married couples find only trouble and heartache as their complicated lives unfold. After 40 years of marriage, Alfie leaves his wife to pursue what he thinks is happiness with a call girl. His wife, Helena, reeling from abandonment, decides to follow the advice of a psychic. Sally, the daughter of Alfie and Helena, is unhappy in her marriage and develops a crush on her boss, while her husband, Roy, falls for a woman engaged to be married.', '2010-09-22', 5.92, 'https://image.tmdb.org/t/p/w500/oBhnI8UZQzTkAH1LMEtrBUmfpjS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38251, 'Mediterraneo', 'Greek Sea, World War II. An Italian ship leaves a handful of soldiers in a little island; their mission is to spot enemy ships and to hold the island in case of attack. The village of the island seems abandoned and there isn''t a single enemy in sight, so the soldiers begin to relax a little. Things change when their ship is hit and destroyed by the enemy, and the soldiers find themselves abandoned there.', '1991-02-02', 7.60, 'https://image.tmdb.org/t/p/w500/omFU47TZSR7xAAZcDHKM48SmVwe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37472, 'Ip Man 2', 'Having defeated the best fighters of the Imperial Japanese army in occupied Shanghai, Ip Man and his family settle in post-war Hong Kong. Struggling to make a living, Master Ip opens a kung fu school to bring his celebrated art of Wing Chun to the troubled youth of Hong Kong. His growing reputation soon brings challenges from powerful enemies, including pre-eminent Hung Gar master, Hung Quan.', '2010-04-29', 7.46, 'https://image.tmdb.org/t/p/w500/wMcyFfKcJneVgcHxWYiQNUNHUsq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38225, 'Wild America', 'Three brothers - Marshall, Marty and Mark dream of becoming naturalists and portraying animal life of America. One summer their dream comes true, they travel through America, filming alligators, bears and moose.', '1997-07-02', 6.13, 'https://image.tmdb.org/t/p/w500/m9VIy9qtq49EDwgYFg07ganUYg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38223, 'Harriet the Spy', 'Harriet may only be in the sixth grade, but she''s already found her calling: to be a spy. In a private journal she takes everywhere, Harriet records suspicious activity and keeps a running list of observations on virtually everyone she knows. It seems harmless enough until, one day, someone finds the journal and exposes Harriet''s critical thoughts about her classmates. Suddenly, even her best friends are against her, and Harriet resolves to take revenge.', '1996-07-10', 6.10, 'https://image.tmdb.org/t/p/w500/spTUUMgIVm4gOdWL35IoYWEuZQl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38317, 'Zookeeper', 'Kindhearted Griffin Keyes is one of the best-loved caretakers at the Franklin Park Zoo, but he''s more comfortable with the animals than with females of his own species as proven by his failed marriage proposal to the self-absorbed Stephanie several years ago. The animals have listened to Griffin pine over her for years and, after she reappears in his life, they decide to help Griffin rekindle the relationship and become the alpha male she wants him to be. They inadvertently reveal their secret ability to talk and, after Griffin''s initial shock, teach him the rules of courtship, animal-style. Surprisingly, the animals'' advice really works and Griffin is about to get everything he''s ever dreamed of--or is he?', '2011-07-06', 5.45, 'https://image.tmdb.org/t/p/w500/y3b4AYw8dr4hIKTfEAjxUxx0z8G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38303, 'You Again', 'History -- make that high school -- may repeat itself when Marni learns that Joanna, the mean girl from her past, is set to be her sister-in-law. Before the wedding bells toll, Marni must show her brother that a tiger doesn''t change its stripes. On Marni''s side is her mother, while Joanna''s backed by her wealthy aunt.', '2010-09-23', 6.27, 'https://image.tmdb.org/t/p/w500/9qI5JE6yjmtakTankuDOMZ1vgEx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37818, 'The Allnighter', 'Molly, Val and Gina are graduating college, but on their final night, frustrations are aired. Molly is still looking for real love and Val is beginning to doubt if that is what she has found. Gina is too busy videotaping everything to really notice. When the final party at Pacifica College kicks off, things do not go exactly as planned.', '1987-05-01', 4.65, 'https://image.tmdb.org/t/p/w500/wyXiYgMpV7gHmsWuness6Q1dRUb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38319, 'Your Highness', 'A fantasy movie about an arrogant, lazy prince and his more heroic brother who must complete a quest in order to save their father''s kingdom.', '2011-04-08', 5.31, 'https://image.tmdb.org/t/p/w500/zw1tEKhR1ncGGtuYkkf30GYlvYQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38321, 'Priest', 'In an alternate world, humanity and vampires have warred for centuries. After the last Vampire War, the veteran Warrior Priest lives in obscurity with other humans inside one of the Church''s walled cities. When the Priest''s niece is kidnapped by vampires, the Priest breaks his vows to hunt them down. He is accompanied by the niece''s boyfriend, who is a wasteland sheriff, and a former Warrior Priestess.', '2011-05-05', 5.91, 'https://image.tmdb.org/t/p/w500/fYHiA7LPGl9DG7m3DUs0Td1VMcO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38295, 'She''s So Lovely', 'After being released from a psychiatric institution, a man tries to redeem himself in the eyes of his now-ex wife from the events that led up to his incarceration.', '1997-08-20', 5.90, 'https://image.tmdb.org/t/p/w500/oZISQ7Cnmezs5NgBaL6uHUkDMFZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38291, 'Educating Rita', 'Rita, a witty 26-year-old hairdresser, wants to ''discover'' herself, so she joins the Open University where she meets the disillusioned professor of literature, Dr. Frank Bryant. His marriage has failed, his new girlfriend is having an affair with his best friend and he can''t get through the day without downing a bottle or two of whisky. What Frank needs is a challenge... and along comes Rita.', '1983-06-16', 6.87, 'https://image.tmdb.org/t/p/w500/xwxgiRzw2zxzWNIYp98faJ0rUy5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38322, 'Big Mommas: Like Father, Like Son', 'FBI agent Malcolm Turner and his 17-year-old son Trent go undercover at an all-girls performing arts school after Trent witnesses a murder. Posing as Big Momma and Charmaine, they must find the murderer before he finds them.', '2011-02-16', 5.54, 'https://image.tmdb.org/t/p/w500/n1GSxFcDaZ6lMVf21M0KloPfuhu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38357, 'Morning Glory', 'A young and devoted morning television producer is hired as an executive producer on a  long-running morning show at a once-prominent but currently failing station in New York City. Eager to keep the show on air, she recruits a former news journalist and anchor who disapproves of co-hosting a show that does not deal with real news stories.', '2010-11-10', 6.37, 'https://image.tmdb.org/t/p/w500/aFRXEoB3QkeHNHYmVGC3uzFSol8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38344, 'On a Clear Day', 'After decades of laboring as a Glasgow shipbuilder, Frank Redmond, a no-nonsense 55-year-old working-class man, suddenly finds himself laid off. For the first time in his life, he is without a job or a sense of direction, and he''s too proud to ask for guidance. His best mates - rascally Danny, timid Norman and cynical Eddie - are there for him, but Frank still feels desperately alone. An offhand remark from Danny inspires Frank to challenge himself. Already contemplating the state of his relationships with loving wife Joan and all-but-estranged son Rob, Frank is determined to shore up his own self-confidence. He will attempt the near impossible - swimming the English Channel.', '2005-08-18', 6.40, 'https://image.tmdb.org/t/p/w500/gE2TRj270Z4KJ5tjSnhpROBwxIH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38356, 'Transformers: Dark of the Moon', 'The Autobots continue to work for NEST, now no longer in secret. But after discovering a strange artifact during a mission in Chernobyl, it becomes apparent to Optimus Prime that the United States government has been less than forthright with them.', '2011-06-28', 6.24, 'https://image.tmdb.org/t/p/w500/28YlCLrFhONteYSs9hKjD1Km0Cj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38358, 'The Last Exorcism', 'After years of performing “exorcisms” and taking believers’ money, Reverend Marcus travels to rural Louisiana with a film crew so he can dispel what he believes is the myth of demonic possession. The dynamic reverend is certain that this will be another routine “exorcism” on a disturbed religious fanatic but instead comes upon the blood-soaked farm of the Sweetzer family and a true evil he would have never thought imaginable.', '2010-08-27', 5.69, 'https://image.tmdb.org/t/p/w500/eOo9tgGjxdsQEgqc6g7E1NL8460.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38360, 'The Cranes Are Flying', 'Veronika and Boris come together in Moscow shortly before World War II. Walking along the river, they watch cranes fly overhead, and promise to rendezvous before Boris leaves to fight. Boris misses the meeting and is off to the front lines, while Veronika waits patiently, sending letters faithfully. After her house is bombed, Veronika moves in with Boris'' family, into the company of a cousin with his own intentions.', '1957-10-12', 7.92, 'https://image.tmdb.org/t/p/w500/foXYOdXEJ0rvtTDo4LLnsUnvPLB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38336, 'Hipsters', 'In this hit Russian musical, a group of friends flaunts Soviet authority in 1950s Moscow by embracing jazz. When Communist Mels falls for Polly, a free-spirited jazz fan, he risks losing his party membership by associating with her rebellious crew.', '2008-12-25', 6.53, 'https://image.tmdb.org/t/p/w500/ongsJQScENi8QPrt8hXIjh0PKR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38150, 'Heartless', 'Jamie Morgan is a troubled young man with a facial birthmark, which has left him isolated and fearful, hiding from the world outside. He lives in the East End, notorious for its violent hooded gangs. According to news reports, the gangs are now wearing demon masks. But, one night, after the murder of his mother, Jamie discovers the terrifying truth.', '2010-05-21', 5.85, 'https://image.tmdb.org/t/p/w500/pk6cnJFCZ5mmDKOKESVeXM0j71T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38365, 'Grown Ups', 'After their high school basketball coach passes away, five good friends and former teammates reunite for a Fourth of July holiday weekend.', '2010-06-24', 6.43, 'https://image.tmdb.org/t/p/w500/cQGM5k1NtU85n4TUlrOrwijSCcm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37776, 'Dead Fury', 'Animated parody of such horror classics as "Evil Dead" and "The Hills Have Eyes".', '2008-08-05', 4.40, 'https://image.tmdb.org/t/p/w500/1WEfdfwVCtfA9Ov1IZudjqOl4gW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38408, 'Life As We Know It', 'After a disastrous first date for caterer Holly and network sports director Messer, all they have in common is a dislike for each other and their love for their goddaughter Sophie. But when they suddenly become all Sophie has in this world, Holly and Messer must set their differences aside. Juggling careers and social calendars, they''ll have to find common ground while living under the same roof.', '2010-10-02', 6.89, 'https://image.tmdb.org/t/p/w500/zLzS2aOqKsS0QvEaY6SfBw4VBqh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38509, 'Polish Wedding', 'The film centers on a big Polish family. Jadzia is the mother and the ruler of the Pzoniak family (she has five children). Though she''s happily married to Bolek, she is also having a long-time affair with Roman. Her young daughter Hala is having an affair with neighbour cop Russell and becomes pregnant by him. Russell is pressed hard to marry Hala.', '1998-01-16', 5.07, 'https://image.tmdb.org/t/p/w500/36De1BxBBzXyJ1eYVQlIoTUIwQm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38523, 'Ponette', 'After losing her mother in a car accident that leaves her with a broken arm, 4-year-old Ponette struggles with anguish and fear. Left by her father with a caring aunt and her children, Ponette grieves, secretly hoping her mother will somehow come back. Confused by the religious explanations provided by adults, and challenged by the cruel taunts of a few children at school, little Ponette must make her way through her emotional turmoil.', '1996-09-25', 7.40, 'https://image.tmdb.org/t/p/w500/p6ZlnYATJvYZtcQr6RDmzplq3hX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38557, 'The River', 'Tom and Mae Garvey are a Tennessee farming couple battling violent floods to save their land. In addition to natural disasters, the Garveys fight to stop a selfish land developer and a local corporation from foreclosing on their farm. While Mae stays at home to care for their children and tend to the crops, Tom finds work as a scab at a steel mill to preserve his family''s property.', '1984-12-01', 6.35, 'https://image.tmdb.org/t/p/w500/bXIlE2QVIarVug9wpyPIz2xiWxf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38548, 'Margaret Cho: I''m the One That I Want', 'November, 1999, Margaret Cho is home in San Francisco at the Warfield Theater. Cho structures her monologue loosely on her professional life''s trajectory: doing stand-up, cast in an ABC-TV sitcom, losing 30 pounds in two weeks for the part, the show''s cancellation, a descent into booze, pills, and self-loathing, and a resurrection into her own voice, her own shape, and being the one she wants.', '2000-07-01', 7.89, 'https://image.tmdb.org/t/p/w500/7pFwrqCnjycoAvFnXVP6dexO3aC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38554, 'Dear God', 'A judge gives con-man Tom Turner a choice—a jail sentence, or a year of honest work. But when he gets a job in the U.S. Post Office''s dead letter office, he starts a Good Samaritan con by answering letters written to God. His seemingly virtuous work inspires his co-workers to do the same, but their good deeds are frowned upon by the postmaster general—and the cops.', '1996-11-01', 5.40, 'https://image.tmdb.org/t/p/w500/mHc6hY6Rv7S7kS50vW2vVdHWG79.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38568, 'Howl', 'It''s San Francisco in 1957, and an American masterpiece is put on trial. Howl, the film, recounts this dark moment using three interwoven threads: the tumultuous life events that led a young Allen Ginsberg to find his true voice as an artist, society''s reaction (the obscenity trial), and mind-expanding animation that echoes the startling originality of the poem itself. All three coalesce in a genre-bending hybrid that brilliantly captures a pivotal moment-the birth of a counterculture.', '2010-08-26', 6.46, 'https://image.tmdb.org/t/p/w500/4gy0rUIaaao1nx6pr1Dj1WpslcO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38167, 'Eat Pray Love', 'A married woman realizes how unhappy her marriage really is, and that her life needs to go in a different direction. After a painful divorce, she takes off on a round-the-world journey to "find herself".', '2010-08-12', 6.25, 'https://image.tmdb.org/t/p/w500/gjR5zUeMGV6UNqtI0OuzqrLQcjU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38050, 'The Adjustment Bureau', 'A man glimpses the future Fate has planned for him – and chooses to fight for his own destiny. Battling the powerful Adjustment Bureau across, under and through the streets of New York, he risks his destined greatness to be with the only woman he''s ever loved.', '2011-03-03', 6.79, 'https://image.tmdb.org/t/p/w500/5ZzeR8iz1nEFLp94OBnbakLZawo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37821, 'Killers', 'When an elite assassin marries a beautiful computer whiz after a whirlwind romance, he gives up the gun and settles down with his new bride. That is, until he learns that someone from his past has put a contract out on his life.', '2010-06-04', 5.96, 'https://image.tmdb.org/t/p/w500/9VB8vGV4Aznf6GUc9C7a1EzGHLz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38055, 'Megamind', 'After Megamind, a highly intelligent alien supervillain, defeats his long-time nemesis Metro Man, Megamind creates a new hero to fight, but must act to save the city when his "creation" becomes an even worse villain than he was.', '2010-10-28', 7.04, 'https://image.tmdb.org/t/p/w500/uZ9ytt3sPTx62XTfN56ILSuYWRe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38575, 'The Karate Kid', '12-year-old Dre Parker could''ve been the most popular kid in Detroit, but his mother''s latest career move has landed him in China. Dre immediately falls for his classmate Mei Ying but the cultural differences make such a friendship impossible. Even worse, Dre''s feelings make him an enemy of the class bully, Cheng. With no friends in a strange land, Dre has nowhere to turn but maintenance man Mr. Han, who is a kung fu master. As Han teaches Dre that kung fu is not about punches and parries, but maturity and calm, Dre realizes that facing down the bullies will be the fight of his life.', '2010-06-10', 6.57, 'https://image.tmdb.org/t/p/w500/b1RBy3l297N0c7PHjlz35cClWju.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37797, 'Whisper of the Heart', 'Shizuku lives a simple life, dominated by her love for stories and writing. One day she notices that all the library books she has have been previously checked out by the same person: "Seiji Amasawa."', '1995-07-15', 7.90, 'https://image.tmdb.org/t/p/w500/5FROLD8zpWFs9ja7aYho1uOMJHg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38153, 'Shadow Conspiracy', 'Bobby Bishop is a special assistant to the President of the United States. Accidentally, he meets his friend professor Pochenko on the street. Pochenko has time to tell Bishop about some conspiracy in the White House but then immediately gets killed by an assassin. Now bad guys are after Bobby as the only man who knows about a plot. Bishop must now not only survive, but to stop the conspirators from achieving their goal. And he doesn''t know whom to trust.', '1997-01-25', 4.94, 'https://image.tmdb.org/t/p/w500/m8dgxxCrpLhKjkjH2DPxkz0inoJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38582, 'Godzilla vs. Mechagodzilla', 'An Okinawan prophecy that foretells the destruction of the Earth is seeming fulfilled when Godzilla emerges to return to his destructive roots. But not all is what it seems after Godzilla breaks his ally Anguirus''s jaw. Matters are further complicated when a second Godzilla emerges, revealing the doppelgänger as a mechanical weapon.', '1974-03-21', 6.97, 'https://image.tmdb.org/t/p/w500/ai92jga3nzkeWdPIeZBo6vyhUj5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38618, 'Tarzan and the Lost City', 'Tarzan returns to his homeland of Africa to save his home from destruction.', '1998-04-24', 4.29, 'https://image.tmdb.org/t/p/w500/kp4gfmC7O10lAuBCDn1cbnPdudU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38643, 'Los Angeles Plays Itself', 'From its distinctive neighborhoods to its architectural homes, Los Angeles has been the backdrop to countless movies. In this dazzling work, Andersen takes viewers on a whirlwind tour through the metropolis'' real and cinematic history, investigating the myriad stories and legends that have come to define it, and meticulously, judiciously revealing the real city that lives beneath.', '2004-07-28', 7.62, 'https://image.tmdb.org/t/p/w500/wmzGSQktsLf2JvfkhBaLSdG4G3Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (37833, 'Tell Your Children', 'High-school principal Dr. Alfred Carroll relates to an audience of parents that marijuana can have devastating effects on teens: a drug supplier entices several restless teens, Mary and Jimmy Lane, sister and brother, and Bill, Mary''s boyfriend, into frequenting a reefer house. Gradually, Bill and Jimmy are drawn into smoking dope, which affects their family lives.', '1938-06-15', 4.37, 'https://image.tmdb.org/t/p/w500/pLEy5EpJ09ilda44HDxkrGOQsKl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38720, 'Walk Don''t Run', 'During the housing shortage of the 1964 Summer Olympic Games, two men and a woman share a small apartment in Tokyo, and the older man soon starts playing Cupid to the younger pair.', '1966-06-29', 6.45, 'https://image.tmdb.org/t/p/w500/cdgTjp6blLr4AR48a6fT2q3dN2e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38117, 'Beastly', 'A modern-day take on the "Beauty and the Beast" tale where a New York teen is transformed into a hideous monster in order to find true love.', '2011-01-21', 6.30, 'https://image.tmdb.org/t/p/w500/uSAXWZsSD0pE4HYVUiDgusnEyyl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38842, 'Middle Men', 'Chronicles Jack Harris, one of the pioneers of internet commerce, as he wrestles with his morals and struggles not to drown in a sea of conmen, mobsters, drug addicts, and pornstars.', '2009-05-17', 6.49, 'https://image.tmdb.org/t/p/w500/l56cv8FczzEk4pe3W8BHiRNCC05.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38805, 'Lilies of the Field', 'An unemployed construction worker heading out west stops at a remote farm in the desert to get water when his car overheats. The farm is being worked by a group of East European Catholic nuns, headed by the strict mother superior, who believes the man has been sent by God to build a much needed church in the desert.', '1963-06-04', 7.22, 'https://image.tmdb.org/t/p/w500/gYoVx2m8NP2hTWnEpwNeROIWrQ4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38843, 'Ramona and Beezus', 'Ramona is a little girl with a very big imagination and a nose for mischief. Her playful antics keep everyone in her loving family on their toes, including her older sister Beezus, who''s just trying to survive her first year of high school. Through all the ups and downs of childhood, Ramona and Beezus learn that anything''s possible when you believe in yourself and rely on each other.', '2010-07-23', 6.59, 'https://image.tmdb.org/t/p/w500/bW1YWFyocIY8DDgwOUroZG2FYNe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38849, 'Android', 'Eccentric scientist Dr. Daniel and his shy assistant Max lead a quiet life on their space station, carrying out illegal research on androids, until they receive an unwelcome visit from three fugitives one of whom is female. Both Dr. Daniel and Max show an interest in her, but one of the other visitors has more sinister intentions.', '1982-10-15', 5.42, 'https://image.tmdb.org/t/p/w500/2exixpei6yaOBrnKgYun1fybsoM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38171, 'Anastasia', 'Russian exiles in Paris plot to collect ten million pounds from the Bank of England by grooming a destitute, suicidal girl to pose as heir to the Russian throne. While Bounin is coaching her, he comes to believe that she is really Anastasia. In the end, the Empress must decide her claim.', '1956-12-13', 6.80, 'https://image.tmdb.org/t/p/w500/26wHOXNt4XNn2lYT8i8pWx1JOP0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38867, 'Delta of Venus', 'A struggling American writer and a fellow American expatriate begin a sordid affair among the chaos and discord of 1940 Paris, France on the brink of World War II.', '1995-06-09', 4.40, 'https://image.tmdb.org/t/p/w500/j43W5XkXR7u7uVAvfniEXiQ3Bpv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38745, 'Gulliver''s Travels', 'Travel writer Lemuel Gulliver takes an assignment in Bermuda, but ends up on the island of Liliput, where he towers over its tiny citizens.', '2010-12-23', 5.22, 'https://image.tmdb.org/t/p/w500/6NoEtuTwZ04luk5H2DpT5ivW7Mg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38868, 'A Decade Under the Influence', 'A documentary examining the decade of the 1970s as a turning point in American cinema. Some of today''s best filmmakers interview the influential directors of that time.', '2003-04-25', 7.92, 'https://image.tmdb.org/t/p/w500/uzt9AkMIxm84IStnjU1hB4o3bWG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38884, 'Land and Freedom', 'Summer 1936: young unemployed communist David Carr leaves Liverpool to join the fight against fascism in Spain. He joins an international group of Militia-men and women, the POUM (Partido Obrero de Unificación Marxista). After being wounded, he goes to Barcelona, where he joins another group of fighters.', '1995-04-07', 7.34, 'https://image.tmdb.org/t/p/w500/u5QRqW0vFYMHFzeQJ4oFgJtu5Xp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38880, 'Promises', 'Documentarians Justine Shapiro and B.Z. Goldberg traveled to Israel to interview Palestinian and Israeli kids ages 11 to 13, assembling their views on living in a society afflicted with violence, separatism and religious and political extremism. This 2002 Oscar nominee for Best Feature Documentary culminates in an astonishing day in which two Israeli children meet Palestinian youngsters at a refugee camp.', '2001-07-06', 7.54, 'https://image.tmdb.org/t/p/w500/yWjOPkUjgOpSaBJu1eAJiXmM16s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38147, 'Oh, God! Book II', 'God appears before 11-year-old Tracy Richards to ask for her help to spread his word and influence over the world which she suggests the slogan ''Think God.'' Naturaly, Tracy''s divorced parents think Tracy''s crazy, and plot to halt her ''heaven-sent'' mission to spread God''s word.', '1980-10-03', 5.42, 'https://image.tmdb.org/t/p/w500/9gH1Ip7zxdgNg6M8EID8oS5oiTM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38904, 'Mrs. Dalloway', 'Clarissa Dalloway looks back on her youth as she readies for a gathering at her house. The wife of a legislator and a doyenne of London''s upper-crust party scene, Clarissa finds that the plight of ailing war veteran Septimus Warren Smith reminds her of a past romance with Peter Walsh. In flashbacks, young Clarissa explores her possibilities with Peter.', '1997-09-01', 5.67, 'https://image.tmdb.org/t/p/w500/kJURxFCyfqjTss7vTVMuUobHcye.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38199, 'Unthinkable', 'The government gets wind of a plot to destroy America involving a trio of nuclear weapons for which the whereabouts are unknown. It''s up to a seasoned interrogator and an FBI agent to find out exactly where the nukes are.', '2010-05-26', 6.81, 'https://image.tmdb.org/t/p/w500/6yQqguytl10FhImngDHV90Aqewa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38925, 'The Lords of Flatbush', 'Set in 1958, the coming of age story follows four lower middle-class Brooklyn teenagers known as The Lords of Flatbush. The Lords chase girls, steal cars, shoot pool, get into street fights, and hang out at a local malt shop.', '1974-05-01', 5.79, 'https://image.tmdb.org/t/p/w500/zmXNjWFK4zlkStngN2qdVZ9Vprh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38718, 'Reversal of Fortune', 'Wealthy Sunny von Bülow lies brain-dead, husband Claus guilty of attempted murder; but he says he''s innocent and hires Alan Dershowitz for his appeal.', '1990-10-19', 6.65, 'https://image.tmdb.org/t/p/w500/jEmFeHPsoyHk6RRZslKzC5NVFad.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38965, '18 Again!', '81-year-old millionaire Jack Watson switches bodies with his 18-year-old grandson David, leading the two to experience life on opposite ends of the age spectrum. But when David, trapped in Jack''s aged body, ends up in a coma, his grandfather must use his meager knowledge of the youth to prevent his family from pulling the plug.', '1988-04-08', 5.57, 'https://image.tmdb.org/t/p/w500/kDMgcjSNadUBmpkbMuX3u48qgI4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38918, 'Kiss me Kismet', 'Götz, the owner of an record shop in Berlin, Kreuzberg, is in love with Aylin.But Aylin is espoused to an turkey doctor named Tarkan. Götz and Aylin are fallin in love and they want to get married. Their Plans first get strong restistance from the turkish parents-in-law and also from the mother of Götz named Helena. Götz converting to the Islam and tries to get a true turk to marry Aylin at the end. After serveral problems and twists they get finally married.', '2006-03-30', 5.86, 'https://image.tmdb.org/t/p/w500/sAQPWUoDmbY01KqZrqg4VRbnqeA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38955, 'Supercop 2', 'As a crime wave sweeps through Hong Kong, the police call Jessica Yang, a rising star in the ranks, to help stop a notorious gang of thieves! What Jessica doesn''t realize is that her boyfriend – recently discharged from the force – is the leader of this ruthless crime ring!', '1993-10-21', 5.70, 'https://image.tmdb.org/t/p/w500/wYGXe2BRIyNX2z7Y6UdQoiw8yfk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38921, 'Burglar', 'Bernice "Bernie" Rhodenbarr is a burglar by trade, and she runs a bookstore as well. Her friend Carl Hefler is a dog groomer. After a successful burglary, it''s discovered that a dead body was in the house she burgled. As she''s the only one who can be placed at the scene of the crime, she has to use her criminal skills to clear her name of the murder AND avoid getting charged with the burglary.', '1987-03-20', 5.18, 'https://image.tmdb.org/t/p/w500/t3cRLXAdjsWQbXsiACosuTwrwmm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38914, 'Here Comes Mr. Jordan', 'Boxer Joe Pendleton, flying to his next fight, crashes...because a Heavenly Messenger, new on the job, snatched Joe''s spirit prematurely from his body. Before the matter can be rectified, Joe''s body is cremated; so the celestial Mr. Jordan grants him the use of the body of wealthy Bruce Farnsworth, who''s just been murdered by his wife. Joe tries to remake Farnsworth''s unworthy life in his own clean-cut image, but then falls in love; and what about that murderous wife?', '1941-08-07', 7.02, 'https://image.tmdb.org/t/p/w500/k6gmIV3hTSCG2JBh2zPMLogZ5y3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38966, 'The Night Before', 'A popular beauty surprisingly asks a nerd to take her to the prom. He wakes up hours later in a sleazy alley. She''s missing but he remembers nothing about it.', '1988-04-15', 6.20, 'https://image.tmdb.org/t/p/w500/o3GOrWh7ytlKsdOGI77WFauZORr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39013, 'Winter''s Bone', 'After discovering her father put their house up for his bail bond and then disappeared, 17-year-old Ree Dolly must confront the local criminal underworld and the harsh Ozark wilderness in order to to track down her father and save her family.', '2010-06-11', 6.78, 'https://image.tmdb.org/t/p/w500/a0qhPkNlxLfsf5B2jFyI1Pp04XV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39029, 'Kill!', 'A pair of down-on-their-luck swordsmen arrive in a dusty, windblown town, where they become involved in a local clan dispute. One, previously a farmer, longs to become a noble samurai. The other, a former samurai haunted by his past, prefers living anonymously with gangsters. But when both men discover the wrongdoings of the nefarious clan leader, they side with a band of rebels who are under siege at a remote mountain cabin.', '1968-06-22', 7.01, 'https://image.tmdb.org/t/p/w500/wAmeXWsKTZrb1mQpEBvGfBpNM43.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39002, 'No Holds Barred', 'Rip is the World Wrestling Federation champion who is faithful to his fans and the network he wrestles for, but Brell, the new head of the World Television Network, wants Rip to wrestle for his network.', '1989-06-02', 4.74, 'https://image.tmdb.org/t/p/w500/6BmhGmMF53mIsJuUYSwyLfCaTfu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39101, 'Dragon Ball Z: The Tree of Might', 'Goku and friends must stop a band of space pirates from consuming fruit from the Tree of Might before it''s destructive powers drain Earth''s energy.', '1990-06-07', 6.50, 'https://image.tmdb.org/t/p/w500/fDX4Dp8IKvjBAaEb5MOJrGkxWX0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39100, 'Dragon Ball Z: The World''s Strongest', 'The evil Dr. Kochin uses the dragon balls to resurrect his mentor, Dr. Wheelo, in an effort to take over the world. Dr. Wheelo, his body having been destroyed by the avalanche that killed him fifty years before, desires the body of the strongest fighter in the world as his new vessel. Believing Roshi to be the world''s strongest warrior, Dr. Kochin abducts Bulma and forces Roshi to surrender himself to save her. When Goku hears of their abduction, he goes to their rescue.', '1990-03-10', 6.60, 'https://image.tmdb.org/t/p/w500/5elbm3iLgGQ6nA5vqUmi9vIojbF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38674, 'Trailer Park Boys', 'After a psychic predicts his death, a small-time hoodlum named Julian hires a cheap documentary film crew to document the last few days of his mis-spent life. This is the film that pioneered the show of the same name.', '1999-07-15', 7.13, 'https://image.tmdb.org/t/p/w500/sB2JGcgznErnf9lCm8cZjhV2W4W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39105, 'Dragon Ball Z: Bojack Unbound', 'Mr. Money is holding another World Martial Arts Tournament and Mr. Satan invites everyone in the world to join in. Little does he know that Bojack, an ancient villain who has escaped his prison, is competing. Since Goku is currently dead, it is up to Gohan, Vegeta, and Trunks to defeat Bojack and his henchman.', '1993-07-10', 7.20, 'https://image.tmdb.org/t/p/w500/iihTK9Af8G1ZzBjkIIAV4qQMkzF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
