INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39113, 'Bikini Beach', 'A millionaire sets out to prove his theory that his pet chimpanzee is as intelligent as the teenagers who hang out on the local beach, where he is intending to build a retirement home.', '1964-07-22', 5.58, 'https://image.tmdb.org/t/p/w500/oGlBaAR2FZbmOaAuZ7cznVkKDGh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
