INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38684, 'Jane Eyre', 'After a bleak childhood, Jane Eyre goes out into the world to become a governess. As she lives happily in her new position at Thornfield Hall, she meets the dark, cold, and abrupt master of the house, Edward Rochester. Jane and her employer grow close in friendship and she soon finds herself falling in love with him. Happiness seems to have found Jane at last, but could Rochester''s terrible secret be about to destroy it forever?', '2011-03-11', 7.20, 'https://image.tmdb.org/t/p/w500/3Cn7D0wEaxnvm8kTta1osNu3QJv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
