INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39177, 'Artemisia', 'The story of Artemisia Gentileschi (1593-1653), one of the first well-known female painters, including her youth, when she was guided and protected by her father, the painter Orazio Gentileschi.', '1997-09-10', 6.06, 'https://image.tmdb.org/t/p/w500/5mMzt0Cw99wNk0xTT7YOdRxaqZp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38757, 'Tangled', 'Feisty teenager Rapunzel, who has long and magical hair, wants to go and see sky lanterns on her eighteenth birthday, but she''s bound to a tower by her overprotective mother. She strikes a deal with Flynn Rider, a charming wanted thief, and the duo set off on an action-packed escapade.', '2010-11-24', 7.60, 'https://image.tmdb.org/t/p/w500/ym7Kst6a4uodryxqbGOxmewF235.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38722, 'My Family', 'Traces over three generations an immigrant family''s trials, tribulations, tragedies, and triumphs. Maria and Jose, the first generation, come to Los Angeles, meet, marry, face deportation all in the 1930s. They establish their family in East L.A., and their children Chucho, Paco, Memo, Irene, Toni, and Jimmy deal with youth culture and the L.A. police in the ''50s. As the second generation become adults in the ''60s, the focus shifts to Jimmy, his marriage to Isabel (a Salvadorian refugee), their son, and Jimmy''s journey to becoming a responsible parent.', '1995-05-03', 7.44, 'https://image.tmdb.org/t/p/w500/i6t6QF5QyUd3UAQ8JM8eVU1169D.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38970, 'Remember Me, My Love', 'A middle-class Italian family is tore apart when the father meets an old flame, the mother—a frustrated onetime actress—auditions for a play, their insecure son tries to make friends through drugs, and their underaged daughter—who has already figured out how to use sex to her advantage—does what she does best to appear on TV.', '2003-02-11', 5.83, 'https://image.tmdb.org/t/p/w500/3GcAGqAtaSfD8V2ULGV1v6CROPj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39104, 'Dragon Ball Z: Super Android 13!', 'Dr. Gero''s Androids #13, #14, and #15 are awakened by the laboratory computers and immediately head to the mall where Goku is shopping. After Goku, Trunks, and Vegeta defeat #14 and #15, #13 absorbs their inner computers and becomes a super being greater than the original three separately were. Now it is up to Goku to stop him.', '1992-07-11', 6.94, 'https://image.tmdb.org/t/p/w500/uVJqC187rKxQ1sJsWlKjNfAzeTk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39106, 'Dragon Ball Z: Bio-Broly', 'Jaga Bada, Mr. Satan''s old sparring partner, has invited Satan to his personal island to hold a grudge match. Trunks and Goten decide to come for the adventure and Android #18 is following Satan for the money he owes her. Little do they know that Jaga Bada''s scientist have found a way to resurrect Broly, the legendary Super Saiyan.', '1994-07-09', 5.80, 'https://image.tmdb.org/t/p/w500/A0VKJ6eRIubW6wH4eAwcpQfjoRD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39053, 'Cyrus', 'With John''s social life at a standstill and his ex-wife about to get remarried, a down on his luck divorcée finally meets the woman of his dreams, only to discover she has another man in her life - her son. Before long, the two are locked in a battle of wits for the woman they both love-and it appears only one man can be left standing when it''s over.', '2010-06-18', 5.92, 'https://image.tmdb.org/t/p/w500/qkJ0rB1qf62TJ6thxEVRT7Eccqn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
