INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39283, 'Carnosaur', 'After being driven to extinction, great bloodthirsty dinosaurs come back to life with the assistance of a demented genetic scientist. She plans to replace the human race with a super-race of dinosaurs who will not pollute the planet.', '1993-05-21', 4.20, 'https://image.tmdb.org/t/p/w500/dOkM4ljCDBfy9FJHmqbd3xJNgeK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39310, 'New Jersey Drive', 'Jason and Midget are two young, black teenagers living in Newark, New Jersey, the unofficial car theft capital of the world. Their favourite pastime is that of everybody in their neighbourhood: stealing cars and joyriding. The trouble starts when they steal a police car and the cops launch a violent offensive that involves beating and even shooting suspects.', '1995-04-19', 6.23, 'https://image.tmdb.org/t/p/w500/lXJWJT6lfAg2NEqEueJcI4ESWSG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39210, 'Somewhere', 'After withdrawing to the Chateau Marmont, a passionless Hollywood actor reexamines his life when his eleven-year-old daughter surprises him with a visit.', '2010-09-03', 6.08, 'https://image.tmdb.org/t/p/w500/zOf1sdfF4eH3CVRCpmRO5ugVGdo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39323, 'Dragon Ball Z: Bardock - The Father of Goku', 'Bardock, Son Goku''s father, is a low-ranking Saiyan soldier who was given the power to see into the future by the last remaining alien on a planet he just destroyed. He witnesses the destruction of his race and must now do his best to stop Frieza''s impending massacre.', '1990-10-17', 7.60, 'https://image.tmdb.org/t/p/w500/docwOsWZuwJKQdwcYJtQPBcg6bm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39314, 'Mighty Joe Young', 'A young woman, Jill Young, grew up on her father''s ranch in Africa, raising a large gorilla named Joe from an infant. Years later, she brings him to Hollywood to become a star.', '1949-07-13', 6.40, 'https://image.tmdb.org/t/p/w500/bCfiB4xlXyAWwgq30QZ44xbe5xm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39312, 'Restrepo', 'Directors Hetherington and Junger spend a year with the 2nd Battalion of the United States Army located in one of Afghanistan''s most dangerous valleys. The documentary provides insight and empathy on how to win the battle through hard work, deadly gunfights and mutual friendships while the unit must push back the Taliban.', '2010-06-25', 7.24, 'https://image.tmdb.org/t/p/w500/62DCMBMJU1ZVezVEawyatpFoJwI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39324, 'Dragon Ball Z: The History of Trunks', 'It has been thirteen years since the Androids began their killing rampage and Son Gohan is the only person fighting back. He takes Bulma''s son Trunks as a student and even gives his own life to save Trunks''s. Now Trunks must figure out a way to change this apocalyptic future', '1993-02-24', 7.60, 'https://image.tmdb.org/t/p/w500/AfUkiiR0UKeiPXPgTx9bRO4snTB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39345, 'Casper Meets Wendy', 'When a warlock threatens Wendy the Good Little Witch, she and her aunts hide out at a resort where Casper the Ghost is vacationing with his uncles. Although Casper and Wendy are told ghosts and witches don''t get along, the two are kindred spirits! This spooky family-friendly adventure finds Casper and Wendy bridging the ghost-witch divide to battle the warlock who is intent on destroying Wendy.', '1998-09-10', 5.92, 'https://image.tmdb.org/t/p/w500/zYJWQvee9CN6nc9En2KUWewHGHr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39356, 'Boy', 'Boy, an 11-year-old child and devout Michael Jackson fan who lives on the east coast of New Zealand in 1984, gets a chance to know his absentee criminal father, who has returned to find a bag of money he buried years ago.', '2010-03-25', 7.28, 'https://image.tmdb.org/t/p/w500/jOcwOnCwTbCvJm7jAbeSo4Jgv0H.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39349, 'Sugar Hill', 'In the Harlem neighborhood of New York City, the Mafia steps in when a drug dealer quits his partner and brother to lead a straight life with his girlfriend.', '1994-02-25', 5.62, 'https://image.tmdb.org/t/p/w500/6bnYhhJS7vuDMRPVSplWaXdK49g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39385, 'Would I Lie to You?', 'Jobless loner Eddie Vuibert gets a lucky break when a rich Jewish entrepreneur mistakes him for a Jew and gives him a sweet job in the Parisian fashion district.', '1997-04-01', 6.27, 'https://image.tmdb.org/t/p/w500/z1JRKYnac2SvvQsCbHaVM2E5x0v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39391, 'Gypsy', 'Gypsy''s mother Rose dreams of a life in show business for her daughters, but Louise becomes a huge burlesque star. Stage musical loosely based on the memoirs of Gypsy Rose Lee.', '1962-11-01', 6.35, 'https://image.tmdb.org/t/p/w500/qmeyhwe7pHJ30n6uLq8swyW1Juz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39410, 'Mothra', 'Shipwreck survivors found on the presumably uninhabited Infant Island leads to a scientific expedition that discovers a surviving native population along with the Shobijin, tiny twin fairy priestesses of the island''s mythical deity called Mothra. After the fairies are kidnapped by an exploitative businessman named Clark Nelson, Mothra sets out to rescue them.', '1961-07-30', 7.17, 'https://image.tmdb.org/t/p/w500/87hiAyyGFHPuuJ3iXHK8xZSMcRP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38785, 'The Boys of Baraka', 'Four 12-year-old black boys from one of the most violent ghettos in Baltimore, Maryland, are taken 10,000 miles away to an experimental boarding school in rural Kenya, to try to take advantage of the educational opportunities they can''t get in their own country.', '2005-03-11', 7.25, 'https://image.tmdb.org/t/p/w500/pLSl9EzNvvtS3skxdYqztjSSS6h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39413, 'My Afternoons with Margueritte', 'An illiterate and lonely man bonds with an older and well-read woman.', '2010-06-02', 6.96, 'https://image.tmdb.org/t/p/w500/fWd8uTsMmbjFUXAjTTHwMHZglXq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39414, 'Paper Man', 'A coming-of-middle-age comedy that chronicles the unlikely friendship between failed author Richard Dunne and a Long Island teen who teaches him a thing or two about growing up, all under the disapproving eye of his long-suffering wife and his imaginary Superhero friend.', '2009-06-15', 6.32, 'https://image.tmdb.org/t/p/w500/wneK8G9E26FUqYo4KjPlsD0TIII.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39424, 'Music from Another Room', 'Music From Another Room is a romantic comedy that follows the exploits of Danny, a young man who grew up believing he was destined to marry the girl he helped deliver as a five year old boy when his neighbor went into emergency labor. Twenty-five years later, Danny returns to his hometown and finds the irresistible Anna Swann but she finds it easy to resist him since she is already engaged to dreamboat Eric, a very practical match. In pursuit of Anna, Danny finds himself entangled with each of the eccentric Swanns including blind, sheltered Nina, cynical sister Karen, big brother Bill and dramatic mother Grace as he fights to prove that fate should never be messed with and passion should never be practical.', '1998-04-24', 5.60, 'https://image.tmdb.org/t/p/w500/zamhRB4bKVeRUW568lVSFeEbqVg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39434, 'The Stendhal Syndrome', 'A young policewoman slowly goes insane while tracking down an elusive serial rapist/killer through Italy when she herself becomes a victim of the brutal man''s obsession.', '1996-01-26', 5.40, 'https://image.tmdb.org/t/p/w500/ttgMlgv76nbh3vwRl91P4JkgroA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39437, 'Beloved', 'After Paul D. finds his old slave friend Sethe in Ohio and moves in with her and her daughter Denver, a strange girl comes along by the name of "Beloved". Sethe and Denver take her in and then strange things start to happen...', '1998-10-16', 5.83, 'https://image.tmdb.org/t/p/w500/jIoT0J2fNXXCYZst6OkKStQIPw9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39440, 'Waiting for "Superman"', 'Gripping, heartbreaking, and ultimately hopeful, Waiting for Superman is an impassioned indictment of the American school system from An Inconvenient Truth director Davis Guggenheim.', '2010-09-24', 6.90, 'https://image.tmdb.org/t/p/w500/l7mRlEi4VCEH7sfgaXX1b6LzsXn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39452, 'Exit Through the Gift Shop', 'Banksy is a graffiti artist with a global reputation whose work can be seen on walls from post-hurricane New Orleans to the separation barrier on the Palestinian West Bank. Fiercely guarding his anonymity to avoid prosecution, Banksy has so far resisted all attempts to be captured on film. Exit Through the Gift Shop tells the incredible true story of how an eccentric French shop keeper turned documentary maker attempted to locate and befriend Banksy, only to have the artist turn the camera back on its owner.', '2010-03-05', 7.54, 'https://image.tmdb.org/t/p/w500/ruM5ehUQlHC1Kx3SF18d6klfrAx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39472, 'Man Trouble', 'A sleazy but affable guard dog trainer is blackmailed to steal a manuscript for a tell-all book from one of his clients.', '1992-07-17', 4.87, 'https://image.tmdb.org/t/p/w500/3hpxleh58Ln1jLcF9hczRTWxtP9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39130, 'Dinner at Eight', 'An ambitious New York socialite plans an extravagant dinner party as her businessman husband, Oliver, contends with financial woes, causing a lot of tension between the couple. Meanwhile, their high-society friends and associates, including the gruff Dan Packard and his sultry spouse, Kitty, contend with their own entanglements, leading to revelations at the much-anticipated dinner.', '1933-12-22', 6.78, 'https://image.tmdb.org/t/p/w500/p9V2dIMqC1g1S9bDgvxqUOJDfp6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39541, 'Stolen Summer', 'Pete, an eight-year-old Catholic boy growing up in the suburbs of Chicago in the mid-1970s, attends Catholic school, where as classes let out for the summer, he''s admonished by a nun to follow the path of the Lord, and not that of the Devil. Perhaps taking this message a bit too seriously, Pete decides it''s his goal for the summer to help someone get into heaven - by  trying to convert a Jew to Catholicism.', '2002-03-22', 6.27, 'https://image.tmdb.org/t/p/w500/marKnaLfvEnQ1DK3U2SLKYRGVdh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39543, 'My American Uncle', 'Professor Henri Laborit uses three people''s stories to discuss behaviourist theories of survival, combat, rewards and punishment, and anxiety: René is a technical manager at a textile factory and must face the anxiety caused by corporate downsizing; Janine is a self-educated actress/stylist who learns that the wife of her lover is dying and must decide to let them reunite; and Jean is a controversial career-climbing writer/politician at a crossroads in life.', '1980-05-21', 6.98, 'https://image.tmdb.org/t/p/w500/e9gbeslzPIav8ELEPRrKB1EzonF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39545, 'TiMER', 'When implanted in a person''s wrist, a TiMER counts down to the day the wearer finds true love. But Oona O''Leary faces the rare dilemma of a blank TiMER. Her soul mate - whoever and wherever he is - has yet to have a TiMER implanted. Staring down the barrel of thirty and tired of waiting for her would-be life partner to get off the dime, Oona breaks her own rules and falls for Mikey, a charming and inappropriately young supermarket clerk with a countdown of four months.', '2009-05-14', 6.29, 'https://image.tmdb.org/t/p/w500/i9QHzVqko9YxNCGdH8vnruy78nK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38778, 'Dinner for Schmucks', 'Rising executive Tim Conrad works for a boss who hosts a monthly dinner in which the guest who brings the biggest buffoon gets a career-boost. Tim plans on not attending until he meets Barry, a man who builds dioramas using stuffed mice. Barry''s blundering but good intentions send Tim''s life into a downward spiral, threatening a major business deal and possibly scuttling Tim''s engagement to his fiancee.', '2010-07-30', 5.72, 'https://image.tmdb.org/t/p/w500/eqCyt9ILsInMYPa2iveiINeVOJD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38772, 'Melvin and Howard', 'The story of hard-luck Melvin Dummar, who claimed to have received a will naming him an heir to the fortune of Howard Hughes. Inspired by real events.', '1980-09-19', 6.47, 'https://image.tmdb.org/t/p/w500/23HqZIaW5Hg3yIOge4BMOdniLjo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39513, 'Paul', 'For the past 60 years, a space-traveling smart-ass named Paul has been locked up in a top-secret military base, advising world leaders about his kind. But when he worries he’s outlived his usefulness and the dissection table is drawing uncomfortably close, Paul escapes on the first RV that passes by his compound in Area 51. Fortunately, it contains the two earthlings who are most likely to rescue and harbor an alien on the run.', '2011-02-14', 6.75, 'https://image.tmdb.org/t/p/w500/dKhexH8nS08lVlSmwSs00cHFxbY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39145, 'Dragon Ball: Sleeping Princess in Devil''s Castle', 'Goku and Kuririn are given an assignment by Kame-Sen''nin: "Retrieve the sleeping princess from Lucifer and I will take you as my students." But the mission proves to be more perilous than originally thought.', '1987-07-18', 6.66, 'https://image.tmdb.org/t/p/w500/9BMFoAqU4DadJajmL3BX0CgJXfe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39141, 'Tadpole', 'Beautiful, sophisticated women are all over Oscar Grubman. He is sensitive and compassionate, speaks French fluently, is passionate about Voltaire, and thinks the feature that tells the most about a woman is her hands. On the train home from Chauncey Academy for the Thanksgiving weekend, Oscar confides in his best friend that he has plans for this vacation--he will win the heart of his true love. But there is one major problem--Oscar''s true love is his stepmother Eve.', '2002-07-19', 5.66, 'https://image.tmdb.org/t/p/w500/r7wCSE5Hj82GHywm2evC1ERmK0E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39451, 'Little Fockers', 'It has taken 10 years, two little Fockers with wife Pam and countless hurdles for Greg to finally get in with his tightly wound father-in-law, Jack. After the cash-strapped dad takes a job moonlighting for a drug company, Jack''s suspicions about his favorite male nurse come roaring back. When Greg and Pam''s entire clan descends for the twins'' birthday party, Greg must prove to the skeptical Jack that he''s fully capable as the man of the house.', '2010-12-21', 5.66, 'https://image.tmdb.org/t/p/w500/90mwPRNMmX9RUGVgKMJMJNQnYX8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39144, 'Dragon Ball: Curse of the Blood Rubies', 'The great King Gurumes is searching for the Dragon Balls in order to put a stop to his endless hunger. A young girl named Pansy who lives in the nearby village has had enough of the treachery and decides to seek Muten Rōshi for assistance. Can our heroes save the village and put a stop to the Gurumes Army?', '1986-12-20', 6.90, 'https://image.tmdb.org/t/p/w500/dZCWRFJnwyxYOhzAhf7Xyru4moB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38802, 'For the Love of Benji', 'Benji gets lost after a flight overseas and becomes a stray in Athens, Greece. He then tries everyday to reunite with his family while mysterious people pursue him, in a race to get a code which was secretly tattooed on his paw at the airport. But who are the bad guys and who are the agents that can be trusted? Will Benji and his kids and their nanny ever get to enjoy their vacation?', '1977-06-10', 5.78, 'https://image.tmdb.org/t/p/w500/iqB2iwZnteFdWH9rL50objGwmNk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (38783, 'Trilogy of Terror', 'A horror anthology containing three stories: a female college professor is aggressively pursued by one of her students; a prudish brunette determines that her free-spirited blonde sister is evil; and a woman''s night turns upside down after she purchases an ancient Zuni fetish doll.', '1975-03-04', 6.25, 'https://image.tmdb.org/t/p/w500/nE4ih0nzpqz0x154Vig0QJUc6Sr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39780, 'Oscar and Lucinda', 'After a childhood of abuse by his evangelistic father, misfit Oscar Hopkins becomes an Anglican minister and develops a divine obsession with gambling. Lucinda Leplastrier is a rich Australian heiress shopping in London for materials for her newly acquired glass factory back home. Deciding to travel to Australia as a missionary, Oscar meets Lucinda aboard ship, and a mutual obsession blossoms. They make a wager that will alter each of their destinies.', '1997-12-31', 6.38, 'https://image.tmdb.org/t/p/w500/9naDX3u4hsRM8jZ0Y7k5e2HAKmY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39486, 'Secretariat', 'Housewife and mother Penny Chenery agrees to take over her ailing father''s Virginia-based Meadow Stables, despite her lack of horse-racing knowledge. Against all odds, Chenery - with the help of veteran trainer Lucien Laurin - manages to navigate the male-dominated business, ultimately fostering the first Triple Crown winner in 25 years.', '2010-08-20', 7.41, 'https://image.tmdb.org/t/p/w500/6YJ39NqRJ0ljUQohizHmE2hB6Wh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39946, 'The Browning Version', 'Andrew Crocker-Harris has been forced from his position as the classics master at an English public school due to poor health. As he winds up his final term, he discovers not only that his wife, Millie, has been unfaithful to him with one of his fellow schoolmasters, but that the school''s students and faculty have long disdained him. However, an unexpected act of kindness causes Crocker-Harris to re-evaluate his life''s work.', '1951-04-06', 7.60, 'https://image.tmdb.org/t/p/w500/fRlXkYgQc6QfwYMAlv2neKhRswl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39953, 'Boys Life', 'Each of the three short films in this collection presents a young gay man at the threshold of adulthood. In "Pool Days," Justin is a 17-year old Bethesda lad, hired as the evening life guard at a fitness center. In the course of the summer, he realizes and embraces that he''s gay. In "A Friend of Dorothy," Winston arrives from upstate for his freshman year at NYU. He has to figure out, with some help from Anne, a hometown friend, how to build a social life as a young gay man in the city. In "The Disco Years," Tom looks back on 1978, the year in high school that he came out of the closet after one joyful and several painful encounters', '1994-09-30', 5.00, 'https://image.tmdb.org/t/p/w500/jXKecGbSp36C486myi1pbe6EKAI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39768, 'Beware of the Car!', 'An insurance agent who moonlights as a car thief steals cars various crooks and never from the common people. He sells the stolen cars and gives the money to charity. His best friend, a cop, is assigned to bring in this modern Robin Hood.', '1966-05-22', 7.50, 'https://image.tmdb.org/t/p/w500/pxf7dGhwpwxe8b1itqxkkjFQac8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39964, 'Lost & Found', 'In order to impress his beautiful French neighbor, Dylan Ramsey dognaps her pet pooch so he can return him and become a hero.', '1999-04-23', 5.03, 'https://image.tmdb.org/t/p/w500/jaylLo7TsJrJriNVGf72Asen1Fr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39154, 'The Giant Spider Invasion', 'A black hole hits North Wisconsin and opens a door to other dimensions. Giant 15 meter spiders emerge from it, who have an appetite for human flesh! Two NASA scientists try to save the world.', '1975-10-16', 4.10, 'https://image.tmdb.org/t/p/w500/jUaJOZlnrmSRTny7ProiupczO42.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40001, 'Mrs. Winterbourne', 'Connie Doyle is eighteen, pregnant and alone. She accidentally ends up on a train where she meets Hugh Winterbourne and his wife pregnant Patricia. The train wrecks and she wakes up in the hospital to find out that it''s been assumed that she''s Patricia. Hugh''s mother takes her in and she falls in love with Hugh''s brother Bill. Just when she thinks everything is going her way, her ex-boyfriend shows up.', '1996-04-19', 7.20, 'https://image.tmdb.org/t/p/w500/ppHqVo9uAFZYMvRm9x0XUtnyQPR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40016, 'Birdemic: Shock and Terror', 'A platoon of eagles and vultures attacks the residents of a small town. Many people die. It''s not known what caused the flying menace to attack. Two people manage to fight back, but will they survive Birdemic?', '2010-02-27', 2.19, 'https://image.tmdb.org/t/p/w500/gqmcAVNNUosB55RliecFYnkWT4M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39148, 'Dragon Ball: The Path to Power', 'A retelling of Dragon Ball''s origin with a different take on the meeting of Goku, Bulma, and Kame-Sen''nin. It also retells the Red Ribbon Army story; but this time they find Goku rather than Goku finding them.', '1996-03-04', 7.40, 'https://image.tmdb.org/t/p/w500/wPkoqtFhDoIbzt61oOYwmLOZdAg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40085, 'The Long, Hot Summer', 'Accused barn burner and conman Ben Quick arrives in a small Mississippi town and quickly ingratiates himself with its richest family, the Varners.', '1958-05-17', 7.00, 'https://image.tmdb.org/t/p/w500/nWQddN7kfkVqSimb4SQc35gNUnP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40082, 'The Mambo Kings', 'The Mambo Kings tells the story of César and Nestor Castillo, brothers and aspiring musicians who flee from Cuba to America in search of the American Dream.', '1992-02-28', 6.38, 'https://image.tmdb.org/t/p/w500/yAMYoODA6FzHPwycrBwwrjKv1A4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40081, 'Crippled Avengers', 'A group of martial artists seek revenge after being crippled by Tu Tin-To, a martial arts master, and his son.', '1978-12-21', 6.82, 'https://image.tmdb.org/t/p/w500/eKdvNCKtiuUFvwCXtpwISw8jqZ5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40092, 'The Secret Life of Walter Mitty', 'Walter Mitty, a daydreaming writer with an overprotective mother, likes to imagine that he is a hero who experiences fantastic adventures. His dream becomes reality when he accidentally meets a mysterious woman who hands him a little black book. According to her, it contains the locations of the Dutch crown jewels hidden since World War II. Soon, Mitty finds himself in the middle of a confusing conspiracy, where he has difficulty differentiating between fact and fiction.', '1947-09-01', 6.80, 'https://image.tmdb.org/t/p/w500/cctKBFz6VoDDW56PbuWiq4F9Nmr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40123, 'Genius Party', 'The seven short films making up GENIUS PARTY couldn’t be more diverse, linked only by a high standard of quality and inspiration. Atsuko Fukushima’s intro piece is a fantastic abstraction to soak up with the eyes. Masaaki Yuasa, of MIND GAME and CAT SOUP fame, brings his distinctive and deceptively simple graphic style and dream-state logic to the table with “Happy Machine,” his spin on a child’s earliest year. Shinji Kimura’s spookier “Deathtic 4,” meanwhile, seems to tap into the creepier corners of a child’s imagination and open up a toybox full of dark delights. Hideki Futamura’s “Limit Cycle” conjures up a vision of virtual reality, while Yuji Fukuyama’s "Doorbell" and "Baby Blue" by Shinichiro Watanabe use understated realism for very surreal purposes. And Shoji Kawamori, with “Shanghai Dragon,” takes the tropes and conventions of traditional anime out for very fun joyride.', '2007-07-07', 6.51, 'https://image.tmdb.org/t/p/w500/e0jqLkjEOtfRhugXs84tfZtT9i8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40095, 'Dead Heat', 'Detective Roger Mortis is killed in action while investigating a string of mysterious robberies: until he''s brought back from the dead with a chemical company''s secret re-animation technology. Now he has twelve hours to solve the case of his own death before he dies: And stays dead.', '1988-05-06', 6.20, 'https://image.tmdb.org/t/p/w500/7jBtDMQrXpHlyuJImTAs6Oexv7H.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40154, 'In the Bleak Midwinter', 'Out of work actor Joe volunteers to help try and save his sister''s local church for the community by putting on a Christmas production of Hamlet, somewhat against the advice of his agent Margaretta. As the cast he assembles are still available even at Christmas and are prepared to do it on a ''profit sharing'' basis (that is, they may not get paid anything) he cannot expect - and does not get - the cream of the cream. But although they all bring their own problems and foibles along, something bigger starts to emerge in the perhaps aptly named village of Hope.', '1995-09-29', 7.10, 'https://image.tmdb.org/t/p/w500/eUrv3E65orbuPnFikjpjso4TVBN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39514, 'RED', 'After surviving an assault from a squad of hit men, retired CIA black ops agent Frank Moses reassembles his old team for an all-out war. Frank reunites with old Joe, crazy Marvin and wily Victoria to uncover a massive conspiracy that threatens their lives. Only their expert training will allow them to survive a near-impossible mission -- breaking into CIA headquarters.', '2010-10-13', 6.71, 'https://image.tmdb.org/t/p/w500/8eeK3OB5PeSRQD7BpZcGZKkehG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40156, 'Priest', 'The deeply held religious convictions of an idealistic young priest are challenged when he must face extraordinary events within his own congregation.', '1995-03-24', 6.31, 'https://image.tmdb.org/t/p/w500/yCZ2eGJb78HzaYthNwVF8R0G6BG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40160, 'Meteor', 'After a collision with a comet, a nearly 8km wide piece of the asteroid "Orpheus" is heading towards Earth. If it hits, it will cause an incredible catastrophe that will probably extinguish mankind. To stop the meteor, NASA wants to use the illegal nuclear weapon satellite "Hercules," but discovers soon that it doesn''t have enough firepower. Their only chance to save the world is to join forces with the USSR, which has also launched such an illegal satellite. But will both governments agree?', '1979-10-19', 5.20, 'https://image.tmdb.org/t/p/w500/xMUuS1KFHRTFSf3PAY2tsbBdqkL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40161, 'The Decoy Bride', 'A local woman is hired to draw paparazzi away from a Hollywood actress who has come to Scotland to get married.', '2011-06-06', 5.97, 'https://image.tmdb.org/t/p/w500/cLFecF4VfzuVXjQBnoo9sCDuTqW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39176, 'The Awakening', 'When a British archaeologist violates an Egyptian queen''s tomb, her evil spirit enters his daughter.', '1980-07-09', 5.44, 'https://image.tmdb.org/t/p/w500/3nHKBehsbgWMff79ICGtVpO7TJt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40206, 'The Inspector General', 'An illiterate stooge in a traveling medicine show wanders into a strange town and is picked up on a vagrancy charge. The town''s corrupt officials mistake him for the inspector general whom they think is traveling in disguise. Fearing he will discover they''ve been pocketing tax money, they make several bungled attempts to kill him.', '1949-12-31', 6.60, 'https://image.tmdb.org/t/p/w500/pEseNGrq1lSdomjayEflNn0xjaZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40219, 'The Beast Within', 'A horrified teen mutates into a crazed cannibalistic swamp creature, and must uncover the terrifying secret identity of his father before his nasty natural tendencies force him to make jambalaya out of the locals.', '1982-02-12', 5.47, 'https://image.tmdb.org/t/p/w500/4ZYbhYQflIF1FV2cmOfQHBUtiQe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40247, 'Please Give', 'In New York City, a husband and wife butt heads with the granddaughters of the elderly woman who lives in the apartment the couple owns.', '2010-04-30', 6.21, 'https://image.tmdb.org/t/p/w500/kft7oy2SoImjDUXgeFbUxhICdc2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40220, 'The Boogey Man', 'A young girl witnesses the brutal murder of her stepfather at the hands of her brother, by mirror reflection. Years later, when the mirror is accidentally shattered, a dark and vengeful curse is unleashed on the family, and anyone unlucky enough to come into contact with its shards falls victim to heinous murder.', '1980-11-07', 4.92, 'https://image.tmdb.org/t/p/w500/bhEJ6lOAtdTGyupOSL0Snzv8qj7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40427, 'Crimson Gold', 'Pizza man Hussein is a daily witnesses to the unjust distribution of wealth in his native Iran. One day, he finds a purse filled with shockingly expensive receipts from an upscale jewelry store. He attempts to bring the purse back to the store, but because of his working-class attire, he''s not allowed inside. Then, during a delivery, a rich man invites Hussein into his extravagant mansion – an event that spurs Hussein to make a desperate bid for wealth.', '2003-09-12', 6.94, 'https://image.tmdb.org/t/p/w500/o8MFZIqtcCyo2J1cCnpVfGa6i66.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40480, 'Bad Company', 'CIA operative Nelson Crowe is tasked with a deadly assignment: infiltrate a highly secret industrial espionage firm. Once inside, he teams with Margaret Wells, a master spy and seductive manipulator, in a plot to overthrow the organization''s sinister president, which leads them into a darkly mysterious web of intrigue -- and shocking murder!', '1995-01-20', 4.95, 'https://image.tmdb.org/t/p/w500/5q5r3cpaTDByz4qko9ZWHlK3gMF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39781, 'The Kids Are All Right', 'Two women, Nic and Jules, brought a son and daughter into the world through artificial insemination. When one of their children reaches age, both kids go behind their mothers'' backs to meet with the donor. Life becomes so much more interesting when the father, two mothers and children start to become attached to each other.', '2010-07-09', 6.59, 'https://image.tmdb.org/t/p/w500/xQ5XqZc82dDCcGjxY7voRKjhaKQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40508, '3 Ninjas Knuckle Up', 'Rocky, Colt and TumTum must battle an evil wealthy toxic waste dumper in order to save a local Indian tribe and their friend Joe. The 3 Ninjas must help find Joe''s father and find a secret disk that contains evidence that could stop the toxic landfill that is destroying the Indian community. However the town is owned by the rich man and he controls the police and even the mayor. They must fight a motorcycle gang and renegade cowboys in this non-stop ninja adventure.', '1995-04-07', 5.17, 'https://image.tmdb.org/t/p/w500/A2664BFz1Xmxyprh9DoxXIEldhb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40555, 'Full Moon in Blue Water', 'Floyd, the owner of a bar on the Texas coast, has been depressed for a year after his wife disappeared in a swimming accident. He lives with his senile father-in-law "The General" and is helped by Jimmy, a former asylum inmate, and the good-natured Louise. The bar is rapidly losing money and Charlie wants to buy it cheaply before it becomes publicly known that a nearby bridge is to be built. Louise offers her savings to go into partnership with Floyd, but Floyd decides to sell when he is forced to pay his back taxes.', '1988-11-23', 6.11, 'https://image.tmdb.org/t/p/w500/3QsmmSgBvfK83j6EDtJZjBcsC5h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39871, 'The Major and the Minor', 'Low on funds, working-class girl Susan Applegate disguises herself as a youngster in order to pay half fare home. But little ''Sue Sue'' finds herself in a whole heap of grownup trouble when she hides out in a compartment with handsome Major Philip Kirby.', '1942-09-16', 7.10, 'https://image.tmdb.org/t/p/w500/e6ZWWdyWkqiMq8g6KmXibtmSiVK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39225, 'With Six You Get Eggroll', 'Abby McClure, a widow with three sons, and Jake Iverson, a widower with a teenage daughter, begin dating and eventually decide to get married. But they''re not prepared for the hostile reactions from their children, who are not very excited about the new union between the two families.', '1968-08-07', 6.36, 'https://image.tmdb.org/t/p/w500/lftVCP4BmMvikPBJ40391htsyUS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39538, 'Contagion', 'As an epidemic of a lethal airborne virus - that kills within days - rapidly grows, the worldwide medical community races to find a cure and control the panic that spreads faster than the virus itself.', '2011-09-08', 6.65, 'https://image.tmdb.org/t/p/w500/qL0IooP0bjXy0KXl9KEyPo22ll0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40694, 'Bedrooms and Hallways', 'At the suggestion of a straight friend, gay man Leo joins a men’s group, where he causes some upsets by declaring his attraction to one of its members.', '1998-08-01', 6.04, 'https://image.tmdb.org/t/p/w500/tH02iMSE2qSmkl6i0x4sbhfS58M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39874, 'My Bloody Valentine', 'Twenty years after a Valentine''s Day tragedy claimed the lives of five miners, Harry Warden returns for a vengeful massacre among teen sweethearts gearing up for another party.', '1981-02-11', 6.40, 'https://image.tmdb.org/t/p/w500/kl3mewFceFtYIavvGts2atzB0e0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39254, 'Real Steel', 'Charlie Kenton is a washed-up fighter who retired from the ring when robots took over the sport. After his robot is trashed, he reluctantly teams up with his estranged son to rebuild and train an unlikely contender.', '2011-09-28', 7.14, 'https://image.tmdb.org/t/p/w500/4GIeI5K5YdDUkR3mNQBoScpSFEf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40490, 'Man of the House', 'Ben Archer is not happy. His mother, Sandy, has just met a man, and it looks like things are pretty serious. Driven by a fear of abandonment, Ben tries anything and everything to ruin the "love bubble" which surrounds his mom. However, after Ben and Jack''s experiences in the Indian Guides, the two become much closer.', '1995-03-03', 5.41, 'https://image.tmdb.org/t/p/w500/6bnOhhrrrq6RZhMgz4aGyqbJ9Wf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39916, 'Contamination', 'A former astronaut helps a government agent and a police detective track the source of mysterious alien pod spores, filled with lethal flesh-dissolving acid, to a South American coffee plantation controlled by alien pod clones.', '1980-08-02', 5.23, 'https://image.tmdb.org/t/p/w500/eCUSieEikP6vt0dBbIKnEGpyEK2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40423, 'Black Orpheus', 'Young lovers Orfeu and Eurydice run through the favelas of Rio during Carnaval, on the lam from a hitman dressed like Death and Orfeu''s vengeful fiancée Mira and passing between moments of fantasy and stark reality. This impressionistic retelling of the Greek legend of Orpheus and Eurydice introduced bossa nova to the world with its soundtrack by young Brazilian composers Luiz Bonfá and Antonio Carlos Jobim.', '1959-06-12', 7.00, 'https://image.tmdb.org/t/p/w500/fJWzdNRnfjcJuaZiKqaSURFV6Lg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39256, 'Godzilla 1985', 'Originally released in Japan as "The Return of Godzilla"  in 1984, this is the heavily re-edited, re-titled "Godzilla 1985".  Adding in new footage of Raymond Burr, this 16th Godzilla film ignores all previous sequels and serves as a direct follow-up to the 1956 "Godzilla King of the Monsters", which also featured scenes with Burr edited into 1954''s "Godzilla". This film restores the darker tone of the original, as we witness the nuclear destruction of giant lizard terrorizing Japan.', '1985-08-23', 6.80, 'https://image.tmdb.org/t/p/w500/blKtf1L6LA3mFW8aVJzxnaI8CLn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39833, 'Love Me Tender', 'After the Civil War, Confederate soldiers Clint and Vance Reno steal a Union payroll, leading to conflict when the younger marries the woman his older brother loves.', '1956-11-15', 6.20, 'https://image.tmdb.org/t/p/w500/4PdRIIrBN4q8H7f8yGbd0ScpTjh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40771, 'Meatballs: Part II', 'Camp Sasquatch will be bought out and closed unless owner Coach Giddy wins the boxing competition scheduled for the end of the summer. Tough city punk Flash, who''s performing his community service time at the camp, is the coach''s best hope. Flash reluctantly offers to help and so must use his raw sparring talents to get a motley group of adolescent misfits into fighting shape, while also trying to win the heart of pretty Cheryl.', '1984-07-27', 3.94, 'https://image.tmdb.org/t/p/w500/uMhPQ6Nzt6TwqMvaBwRJz2b4t1a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40724, 'Anne of Green Gables: The Sequel', 'Anne Shirley, now a schoolteacher, has begun writing stories and collecting rejection slips. She acts as Diana''s maid of honor, develops a relationship with Gilbert Blythe, and finds herself at Kingsport Ladies'' College. But while Anne enjoys the battles and the friends she makes, she finds herself returning to Avonlea.', '1987-05-19', 7.90, 'https://image.tmdb.org/t/p/w500/2n8qhm9SQph1s7njjO1kq3c6Imk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39260, 'RoboGeisha', 'Sisters Yoshie and Kikue are two Geisha who are abducted by a mysterious organization to be transformed into murderous cyborg assassins.', '2009-10-03', 5.40, 'https://image.tmdb.org/t/p/w500/7fN1ZDG7sumIgndF8KfzEAvzkL8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40772, 'Meatballs III: Summer Job', 'The ghost of a dead porn star comes to Earth to help a nerd with his sex life.', '1986-10-27', 4.14, 'https://image.tmdb.org/t/p/w500/2N9rjuNg5vgQhKGrQJQLEDX7s70.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40446, 'Sorority House Massacre II', 'Five college women buy the old Hokstedter place for their new sorority house. They got it cheap because of the bloody incidents from five years before. They decide to stay in it for the night so they can meet the movers in the morning, but begin to get the creeps when the weird neighbor Orville Ketchum starts poking around. Shortly after the women take showers and consult a Ouija board they begin experiencing an attrition problem.', '1990-10-05', 5.35, 'https://image.tmdb.org/t/p/w500/oxNLpMybAZkxBD1WQsIFdbmplnx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40773, 'Meatballs 4: To the Rescue', 'Ricky is the hottest water-ski instructor around and has just been rehired by his former employer/camp to whip up attendance. Unfortunately, the camp is in serious financial trouble. The owner of a rival, more popular camp wants to buy them out. Therefore they will have to engage in a mean, winner-takes-all competition that will settle the score once and for all.', '1992-03-06', 4.45, 'https://image.tmdb.org/t/p/w500/8dcYDKcf8PJLqjzKBEthrzFYk8s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40805, 'The Green Hornet', 'Britt Reid, the heir to the largest newspaper fortune in Los Angeles, is a spoiled playboy who has been, thus far, happy to lead an aimless life. After his father dies, Britt meets Kato, a resourceful company employee. Realizing that they have the talent and resources to make something of their lives, Britt and Kato join forces as costumed crime-fighters to bring down the city''s most-powerful criminal, Chudnofsky.', '2011-01-12', 5.59, 'https://image.tmdb.org/t/p/w500/pecyADOvb3Ksey7KYU6V1enEOEc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40807, '50/50', 'Inspired by a true story, a comedy centered on a 27-year-old guy who learns of his cancer diagnosis and his subsequent struggle to beat the disease.', '2011-09-30', 7.19, 'https://image.tmdb.org/t/p/w500/8f9tM9JVB4ETBhxlQcXIjLckArl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40819, 'Best Worst Movie', 'A look at the making of the film Troll 2 (1990) and its journey from being crowned the "worst film of all time" to a cherished cult classic.', '2009-03-14', 7.08, 'https://image.tmdb.org/t/p/w500/4LQ6kdvVJW9y0B9O4qDTsazNzER.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40820, 'Punchline', 'Lilah Krytsick is a mother and housewife who''s always believed she could be a stand-up comedian. Steven Gold is an experienced stand-up seemingly on the cusp of success. When the two meet, they form an unlikely friendship, and Steven tries to help the untried Lilah develop her stage act. Despite the objections of her family and some very wobbly beginnings, Lilah improves, and soon she finds herself competing with Steven for a coveted television spot.', '1988-10-07', 5.55, 'https://image.tmdb.org/t/p/w500/dgbLnnEJIGldXOMt6OWy3X1l0AC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40842, 'Norma Rae', 'Norma Rae is a southern textile worker employed in a factory with intolerable working conditions. This concern about the situation gives her the gumption to be the key associate to a visiting labor union organizer. Together, they undertake the difficult, and possibly dangerous, struggle to unionize her factory.', '1979-03-02', 7.16, 'https://image.tmdb.org/t/p/w500/6au7WBVYoKhV1jORyFSIRszb46S.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40860, 'Drained', 'A pawn shop proprietor buys used goods from desperate locals – as much to play perverse power games as for his own livelihood, but when the perfect rump and a backed-up toilet enter his life, he loses all control.', '2006-09-27', 7.00, 'https://image.tmdb.org/t/p/w500/hsimQm7sD4ezSPhcMrVAc5cEDn3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40850, 'Cherrybomb', 'Teenagers Luke, Malachy, and Michelle embark on a wild weekend of drink, drugs, shop-lifting and stealing cars. But what starts out as a game turns deadly serious when the three discover that they can''t get off the wild ride they''ve set in motion.', '2009-02-08', 5.48, 'https://image.tmdb.org/t/p/w500/q3NdckfHKjXyrsRNoZyAidMf9em.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40619, 'Day & Night', 'When Day, a sunny fellow, encounters Night, a stranger of distinctly darker moods, sparks fly! Day and Night are frightened and suspicious of each other at first, and quickly get off on the wrong foot. But as they discover each other''s unique qualities--and come to realize that each of them offers a different window onto the same world-the friendship helps both to gain a new perspective.', '2010-06-17', 7.70, 'https://image.tmdb.org/t/p/w500/hn2tOtidoYZ0D56jR4yknpdP1mU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40867, 'The Pajama Game', 'An Iowa pajama factory worker falls in love with an affable superintendent who had been hired by the factory''s boss to help oppose the workers'' demand for a pay raise.', '1957-08-29', 6.26, 'https://image.tmdb.org/t/p/w500/71Q9f7byPqH8trF4BvZOlXnhO2D.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40876, 'Down to the Bone', 'A woman stuck in a stale marriage struggles to raise her children and manage her secret drug habit. But when winter comes to her small town, her balancing act begins to come crashing down.', '2004-01-14', 6.50, 'https://image.tmdb.org/t/p/w500/x5A0RdsKe8qnX9ntPXL4dsPGvMl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40894, 'Lover Come Back', 'Jerry Webster and Carol Templeton are rival Madison Avenue advertising executives who each dislike each other’s methods. After he steals a client out from under her cute little nose, revenge prompts her to infiltrate his secret "VIP" campaign in order to persuade the mystery product’s scientist to switch to her firm.', '1961-12-20', 7.00, 'https://image.tmdb.org/t/p/w500/uY5MvhzoH25LMTgEjRR2XtGLdMi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40926, 'Frisk', 'A first person narrative of the exploits of a gay serial killer in deeply disturbing, controversial drama about violence, sexuality, and the imagination. Dennis, the main character, whose lead we follow on this path between what is real and what we can only hope is surreal. His friends attempt to determine if he''s truly a psychopath.', '1996-03-22', 4.18, 'https://image.tmdb.org/t/p/w500/2BsmfL2wr4sAjrsBFePewmslnXO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40866, 'The Devil and Max Devlin', 'When Max dies in an accident, he goes straight to Hell. But the Devil Barney makes him an offer: if he manages to get three innocent youths to sell him their souls in the next two months, he may stay on Earth. Max accepts, and returns to Earth, equipped with special powers. However, his task is harder than expected, especially when seven year old Tobi demands that he marry his mother.', '1981-03-06', 5.82, 'https://image.tmdb.org/t/p/w500/b5XOONi82ThL4r5K20BKsWIhmi6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39850, 'Eros', 'A three-part anthology about love and sexuality: a menage-a-trois between a couple and a young woman on the coast of Tuscany; an advertising executive under enormous pressure at work, who, during visits to his psychiatrist, is pulled to delve into the possible reasons why his stress seems to manifest itself in a recurring erotic dream; a story of unrequited love about a beautiful, 1960s high-end call girl in an impossible affair with her young tailor.', '2004-12-03', 5.70, 'https://image.tmdb.org/t/p/w500/bz8pWVNsbg1MMKCgp2VX6wFOXJX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
