INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41058, 'I Shot Jesse James', 'Bob Ford murders his best friend Jesse James in order to obtain a pardon that will free him to marry his girlfriend Cynthy. The guilt-stricken Ford soon finds himself greeted with derision and open mockery throughout town. He travels to Colorado to try his hand at prospecting in hopes that marriage with Cynthy is still in the cards.', '1949-02-26', 6.24, 'https://image.tmdb.org/t/p/w500/8NiIpXBImEW1vacQS4LyinVGqa4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41059, 'Make Way for Tomorrow', 'An elderly couple are forced to separate themselves from each other after their children refuse to take both into one house.', '1937-05-09', 7.49, 'https://image.tmdb.org/t/p/w500/zPl6TfnIIJzdPXk9g6QPwFwTIt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41090, 'Wisdom', 'Unable to find work after a past felony, graduate John Wisdom and his girlfriend embark on a cross-country bank-robbing spree in order to aid American farmers.', '1986-12-31', 6.06, 'https://image.tmdb.org/t/p/w500/jJiKZG7vauFCeax5Aj5fahrcKUO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40897, 'Zatoichi and the Chest of Gold', 'Ichi travels to the village of Itakura to pay his respects at the grave of Kichizo, a man he killed two years ago. When some tax money is stolen while in transit to the governor he is accused and sets out to find the money and clear his name.', '1964-03-14', 6.95, 'https://image.tmdb.org/t/p/w500/7AJD46hbaU47ScV5Oe8hX5OmEw7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41153, 'I Bought a Vampire Motorcycle', 'When a motorbike gang kills an occultist, the evil spirit he was summoning inhabits a damaged bike. The bike is then bought and restored, but reveals its true nature when it tries to exact vengance on the gang, and anyone else who gets in its way.', '1990-07-06', 5.32, 'https://image.tmdb.org/t/p/w500/dCbFIzq64uUo5ZR4W3vLFhaJenk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41154, 'Men in Black 3', 'Agents J and K are back...in time. J has seen some inexplicable things in his 15 years with the Men in Black, but nothing, not even aliens, perplexes him as much as his wry, reticent partner. But when K''s life and the fate of the planet are put at stake, Agent J will have to travel back in time to put things right. J discovers that there are secrets to the universe that K never told him - secrets that will reveal themselves as he teams up with the young Agent K to save his partner, the agency, and the future of humankind.', '2012-05-23', 6.55, 'https://image.tmdb.org/t/p/w500/90DdoEStzeObs96fsYf4GG544iN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41201, 'The Illusionist', 'A French illusionist travels to Scotland to work. He meets a young woman in a small village. Their ensuing adventure in Edinburgh changes both their lives forever.', '2010-06-16', 7.25, 'https://image.tmdb.org/t/p/w500/Ac2tNYW9sRaOhmtMJQuhf2mvo00.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41164, 'Talent for the Game', 'Virgil Sweet is on the verge of losing his job as a talent scout with the California Angels when he discovers Sammy Bodeen, a country boy with no pro ball experience, but with a pitching arm no one has seen the like of.', '1991-04-26', 7.00, 'https://image.tmdb.org/t/p/w500/eiF9tLx5Q5GN967hRI6wPkFTnUF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41210, 'The Switch', 'Kassie is a smart, fun-loving single woman who, despite her neurotic best friend Wally’s objections, decides it’s time to have a baby – even if it means doing it herself… with a little help from a charming sperm donor. But, unbeknownst to her, Kassie’s plans go awry because of a last-minute switch that isn’t discovered until seven years later… when Wally gets acquainted with Kassie’s cute, though slightly neurotic, son.', '2010-08-20', 6.23, 'https://image.tmdb.org/t/p/w500/oJdMT6RGtbvQ26Tk7EHGfG8xZ6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41206, 'A Double Life', 'A Shakespearian actor starring as Othello opposite his wife finds the character''s jealous rage taking over his mind off-stage.', '1947-12-25', 6.40, 'https://image.tmdb.org/t/p/w500/rYa7JZN5PnpxXpR4oXAcefP9YXa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
