INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41240, 'Bastard Out of Carolina', 'A poor, struggling South Carolinian mother and daughter face painful choices with their resolve and pride. Bone, the eldest daughter, and Anney her tired mother, grow both closer and farther apart: Anney sees Glen as her last chance.', '1996-12-15', 7.10, 'https://image.tmdb.org/t/p/w500/jYFwFOkHwWxaStR21UIgdb96Gzh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41212, 'Titicut Follies', 'A stark and graphic portrayal of the conditions that existed at the State Prison for the Criminally Insane at Bridgewater, Massachusetts, and documents the various ways the inmates are treated by the guards, social workers, and psychiatrists.', '1967-10-03', 7.28, 'https://image.tmdb.org/t/p/w500/hAJOSqWB4FeVV7yi0fRSYFoCwvM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41225, 'Spirits of the Dead', 'Anthology film from three European directors based on stories by Edgar Allan Poe: a cruel countess haunted by a ghostly horse, a sadistic young man haunted by his double, and an alcoholic actor haunted by the Devil.', '1968-05-16', 6.24, 'https://image.tmdb.org/t/p/w500/9HmCwfPG7URPSXSrmEAFN65VoWE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
