INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41282, 'Skipped Parts', 'A woman and her son must leave a small South Carolina town because of her wild behavior.', '2000-06-06', 6.07, 'https://image.tmdb.org/t/p/w500/fnlTjsdjQysQ46IE3OMWeJtvP6e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41277, 'Seducing Doctor Lewis', 'A much-needed boost, in the form of a new factory, is promised to the residents of the tiny fishing village St. Marie-La-Mauderne, provided they can lure a doctor to take up full-time residency on the island. Inspired, the villagers devise a scheme to make Dr. Christopher Lewis a local.', '2003-05-20', 6.89, 'https://image.tmdb.org/t/p/w500/s81LmEGSec8XcUfRmlCYL1ZAjP4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40454, 'Follow Me, Boys!', 'Lem Siddons is part of a traveling band who has a dream of becoming a lawyer. Deciding to settle down, he finds a job as a stockboy in the general store of a small town. Trying to fit in, he volunteers to become scoutmaster of the newly formed Troop 1. Becoming more and more involved with the scout troop, he finds his plans to become a lawyer being put on the back burner, until he realizes that his life has been fulfilled helping the youth of the small town.', '1966-12-01', 6.68, 'https://image.tmdb.org/t/p/w500/f9K6Opys2zr5B64EbfsnuxPmbRh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
