INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40658, 'Starsuckers', 'Starsuckers is the most controversial documentary of the year, and was released in British cinemas in November 2009 to critical acclaim. It''s a darkly humourous and shocking exposé of the celebrity obsessed media, that uncovers the real reasons behind our addiction to fame and blows the lid on the corporations and individuals who profit from it.', '2009-09-30', 6.67, 'https://image.tmdb.org/t/p/w500/1z05uhHmSdXV8LGM8DPnBkf86DU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
