INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (39939, 'Super Troopers', 'Five bored, occasionally high and always ineffective Vermont state troopers must prove their worth to the governor or lose their jobs. After stumbling on a drug ring, they plan to make a bust, but a rival police force is out to steal the glory.', '2001-02-15', 6.54, 'https://image.tmdb.org/t/p/w500/yJyxPItcLNVfYr7idOphQTmQ9hK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
