INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41579, 'Getting Even with Dad', 'Con man Ray is going after one last heist – a stash of rare coins – when his estranged son Timmy unexpectedly shows up. Ray is too preoccupied with his robbery to spend time with his son, so Timmy blackmails him into acting like a father, hiding the coins and promises to return them only after Ray takes him to amusement parks and baseball games.', '1994-06-17', 5.33, 'https://image.tmdb.org/t/p/w500/txsmdQqbgSz5Zu3rgd9fglMqKA4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41580, 'Colonel Chabert', 'When Colonel Chabert returns from the war, he discovers that he has lost everything.', '1994-09-21', 6.65, 'https://image.tmdb.org/t/p/w500/Usaduh828gtYe6jw9DosnPJ7I9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41582, 'Monkey Trouble', 'Dodger, a criminal monkey, belongs to a crooked street performer but escapes his life of crime only to end up in the arms of Eva, an innocent little girl whose mother has no idea that her daughter is harboring a fugitive.', '1994-03-18', 5.71, 'https://image.tmdb.org/t/p/w500/XnEXrR8SKWQmmvjtjRoAXROEj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40722, 'How to Make Love to a Woman', 'When Andy hears his girlfriend Lauren sigh after sex, he panics. But even with the help of his friends, porn stars and tantric experts, he continues to stumble in the bedroom, finally realizing that in order to give Lauren the ''O'' word, he first needs to say the ''L'' word. Starring Josh Meyers, Krysten Ritter, Ian Somerhalder, Jenna Jameson and Ken Jeong.', '2010-07-13', 4.34, 'https://image.tmdb.org/t/p/w500/A3LppVfwslUokTyETpclKwGAXSM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41602, 'Charlie Countryman', 'A young American falls hard for a Romanian cellist whose father has recently died -- and whose violent past could bring about his own demise.', '2013-02-09', 6.39, 'https://image.tmdb.org/t/p/w500/7BbrgKfnRfEFIePqdRcWzuHs3KI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41609, 'The Three Musketeers', 'In 17th century France, young D''Artagnan wants to join the King''s Musketeers, but instead befriends three legendary musketeers—Athos, Porthos, and Aramis—and together, they become embroiled in the political intrigue surrounding King Louis XIII and his adversaries, particularly the powerful Cardinal Richelieu.', '1948-10-20', 6.80, 'https://image.tmdb.org/t/p/w500/jOkXsC1NjkNOxNyooRhTIf1nxsn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41630, 'No Strings Attached', 'Emma is a busy doctor who sets up a seemingly perfect arrangement when she offers her best friend Adam a relationship with one rule: No strings attached. But when a fling becomes a thing, can sex friends stay best friends?', '2011-01-21', 6.29, 'https://image.tmdb.org/t/p/w500/9C09L1U9S13J4Ut029Qhu0oLcTQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41647, 'The Wonderful Horrible Life of Leni Riefenstahl', 'This documentary recounts the life and work of one of most famous, and yet reviled, German film directors in history, Leni Riefenstahl. The film recounts the rise of her career from a dancer, to a movie actor to the most important film director in Nazi Germany who directed such famous propaganda films as Triumph of the Will and Olympiad. The film also explores her later activities after Nazi Germany''s defeat in 1945 and her disgrace for being so associated with it which includes her amazingly active life over the age of 90.', '1993-09-11', 7.21, 'https://image.tmdb.org/t/p/w500/pZnBH4ZJnHcVFgeuK81w2tcHvRD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41659, 'My Life', 'It seems that Bob Jones has everything a man could want, namely a fulfilling job and a beautiful, pregnant wife, Gail. But Bob''s life is turned upside-down when he is diagnosed with cancer and given four months to live -- not even enough time to see his first child''s birth. To cleanse himself of demons in his remaining days, Bob makes a video diary, hoping to pass along some wisdom to his future child. Along the way, he discovers a lot about himself.', '1993-11-12', 6.70, 'https://image.tmdb.org/t/p/w500/eF8wNMMqY3kukUTTAVXLLx94UhB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41662, '3 Women', 'Two co-workers, one a vain woman and the other an awkward teenager, share an increasingly bizarre relationship after becoming roommates.', '1977-04-29', 7.10, 'https://image.tmdb.org/t/p/w500/uL5Yg8MEgHGXymTaJBYXn9g0xsH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41671, 'Amityville 1992: It''s About Time', 'A hot-shot architect returns home from his latest business trip with a surprise: an ornate old clock rescued out of a soon-to-be-demolished mansion in Amityville, New York, that brings about a seemingly unstoppable demonic force.', '1992-07-16', 4.78, 'https://image.tmdb.org/t/p/w500/qDuFg30RHtOoB0sWUWkMMI7zxC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41733, 'Due Date', 'Peter Highman must scramble across the US in five days to be present for the birth of his first child. He gets off to a bad start when his wallet and luggage are stolen, and put on the ''no-fly'' list. Peter embarks on a terrifying journey when he accepts a ride from an actor.', '2010-11-03', 6.39, 'https://image.tmdb.org/t/p/w500/sBxWS09pOOyXZ0dcnqfqqCAQGan.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41682, 'Christopher Columbus: The Discovery', 'Genoan navigator Christopher Columbus has a dream to find an alternative route to sail to the Indies, by traveling west instead of east, across the unchartered Ocean sea. After failing to find backing from the Portugese, he goes to the Spanish court to ask Queen Isabella and King Ferdinand for help. After surviving a grilling from the Head of the Spanish Inquisition Tomas de Torquemada, he eventually gets the blessing from Queen Isabella and sets sail in three ships to travel into the unknown. Along the way he must deal with sabotage from Portugese spies and mutiny from a rebellious crew.', '1992-08-20', 4.80, 'https://image.tmdb.org/t/p/w500/2VUr81cOU0jsZtzBs2EoVHcDJDW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41768, 'Passion Fish', 'After an accident leaves her a paraplegic, a former soap opera star struggles to recover both emotionally and mentally, until she meets her newest nurse, who has struggles of her own.', '1992-12-11', 7.03, 'https://image.tmdb.org/t/p/w500/g60GELLr2oGnlJX5Yidkl9ufFYv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41769, 'Prom Night IV: Deliver Us from Evil', 'Thirty years after slashing a Hamilton High couple on Prom Night 1957, psychotic priest Father Jonas gets loose from the chapel basement where the other church fathers had been secretly keeping him locked up and drugged.', '1992-02-14', 4.80, 'https://image.tmdb.org/t/p/w500/tjq1iWClSBCfi3SjpVJblOU6q4F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41759, 'Man''s Best Friend', 'A genetic research facility worker exposes animal abuses there to a local TV reporter, who frees and takes in a genetically altered dog from the lab, unaware that he has a violent streak.', '1993-11-19', 5.95, 'https://image.tmdb.org/t/p/w500/dRDOrszc2X9bWsE2LhJuJ6WbVEp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41779, 'Used People', 'At her husband''s funeral, Pearl, Jewish mother of two divorced and antagonistic daughters, meets an old Italian friend of her husband, whose advice years previously had stopped the husband leaving home. For 23 years he, now a widower, has secretly loved Pearl.', '1992-12-16', 5.80, 'https://image.tmdb.org/t/p/w500/8h5tBiUXTHQyBBB5bdRVzbOrDtE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41778, 'Visions of Light', 'Cameramen and women discuss the craft and art of cinematography and of the "DP" (the director of photography), illustrating their points with clips from 100 films, from Birth of a Nation to Do the Right Thing. Themes: the DP tells people where to look; changes in movies (the arrival of sound, color, and wide screens) required creative responses from DPs; and, these artisans constantly invent new equipment and try new things, with wonderful results. The narration takes us through the identifiable studio styles of the 30s, the emergence of noir, the New York look, and the impact of Europeans. Citizen Kane, The Conformist, and Gordon Willis get special attention.', '1992-09-17', 7.05, 'https://image.tmdb.org/t/p/w500/62ry0lNv4gQRuusC1EkUkOmTuUY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41791, 'Mississippi Masala', 'Years after her Indian family was forced to flee their Uganda home, twentysomething Mina finds herself co-operating a motel in the faraway land of Mississippi. Her passionate romance with charming Black carpet cleaner Demetrius challenges the prejudices of their conservative families and exposes the rifts between the region''s Indian and African-American communities.', '1991-09-18', 6.38, 'https://image.tmdb.org/t/p/w500/b2Gks4Stt98FRI5isaL6Wu1luhh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41784, 'Black Robe', 'Missionary Father LaForgue travels to the New World in hopes of converting Algonquin Indians to Catholicism. Accepted, though warily, by the Indians, LaForgue travels with the Indians using his strict Catholic rules and ideals to try and impose his religion.', '1991-10-04', 6.47, 'https://image.tmdb.org/t/p/w500/kaogaZD8WkwfRJnr7zvktiY5E2p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41316, 'Unprecedented: The 2000 Presidential Election', 'Unprecedented: The 2000 Presidential Election is the riveting story about the battle for the presidency in Florida and the undermining of democracy in America. Filmmakers Richard Ray Perez and Joan Sekler examine modern America’s most controversial political contest: the 2000 election of George W. Bush. What emerges is a disturbing picture of an election marred by suspicious irregularities, electoral injustices, and sinister voter purges in a state governed by the winning candidate’s brother. This 2004 Campaign Edition features new commentary by Danny Glover and a new segment on the dangers of electronic voting machines.', '2002-09-17', 7.33, 'https://image.tmdb.org/t/p/w500/gsQDE2q03eFNHPESb8ZRy87vLFY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41801, 'Female Perversions', 'An ambitious female attorney wallows in excess and meaningless sex with both male and female partners, while dealing with her personal life problems including helping her kleptomaniac sister.', '1996-11-21', 5.09, 'https://image.tmdb.org/t/p/w500/5vqRaOZBqBL1YXukRv6zI6Y4pxC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41805, 'V.I. Warshawski', 'Victoria "V.I" Warshawski is a Chicago based private detective who agrees to babysit for her new boyfriend; then he is murdered. Being the detective type, she makes the murder her next case. In doing so she befriends the victim''s daughter, Kat, and together they set out to crack the case.', '1991-07-26', 4.80, 'https://image.tmdb.org/t/p/w500/w0ykwLLDB8v1wT50wDpYaPnyac7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41823, 'Mo'' Better Blues', 'Talented but self-centered trumpeter Bleek Gilliam is obsessed with his music and indecisiveness about his girlfriends Indigo and Clarke. But when he is forced to come to the aid of his manager and childhood friend, Bleek finds his world more fragile than he ever imagined.', '1990-08-03', 6.50, 'https://image.tmdb.org/t/p/w500/sEa6m5RjfrqfTzY1eHkC85shiUF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41821, 'Ju Dou', 'Tianqing falls in love with Ju Dou, his uncle''s wife who is tortured for being childless. However, after they have an affair, they discover that his uncle is impotent and try to conceal the truth.', '1990-04-21', 7.21, 'https://image.tmdb.org/t/p/w500/ejvX1lukPZZ10jatUWmKaXbhjGI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41845, 'Heaven and Earth', 'Warlords Kagetora and Takeda each wish to prevent the other from gaining hegemony in feudal Japan. The two samurai leaders pursue one another across the countryside, engaging in massive battles of cavalry and infantry. Younger and less brutal, Kagetora must find the strength to be as brutal as his opponent, but at what cost?', '1990-11-24', 6.17, 'https://image.tmdb.org/t/p/w500/qp9OdVRSzol2kFo4I8VDzQnfBCn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41513, 'The Smurfs', 'When the evil wizard Gargamel chases the tiny blue Smurfs out of their village, they tumble from their magical world and into ours -- in fact, smack dab in the middle of Central Park. Just three apples high and stuck in the Big Apple, the Smurfs must find a way to get back to their village before Gargamel tracks them down.', '2011-07-29', 5.75, 'https://image.tmdb.org/t/p/w500/vRhnslP2gW0QDym7BsMeSuioUfK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41391, 'Day of Wrath', 'In a Danish village in the early 1600s, a young woman named Anne, whose mother was thought to be a witch, develops sympathy toward an old woman, Marte, who is accused of witchcraft. The intervention of Anne''s older but kindly husband, Pastor Absalon saved her mother -- but now, urged on by his overbearing mother, he refuses to help Marte. When Absalon''s son returns home and is attracted to Anne, it''s a matter of time before her family destiny catches up with her.', '1943-11-13', 7.99, 'https://image.tmdb.org/t/p/w500/jEOqbGLFo8fxHHgYoZVTMVYMoQG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40760, 'Sorority House Massacre', 'Upon joining a sorority, Beth is plagued by nightmares of a knife-wielding killer, when her past comes back to haunt her.', '1986-10-10', 4.61, 'https://image.tmdb.org/t/p/w500/oU2i9iabbzBbDdKxv1PqQjoqSbw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (40770, 'Spirit Camp', 'When a street smart "goth girl", Nikki,  is forced to attend cheerleader camp as part of her rehabilitation from a juvenile correction facility, she clashes with the "popular girls," and finds herself embroiled in a bitter rivalry with the bitchy ringleader Rachel . But when members of the spirit squad start turning up dead, the girls must put aside their differences and struggle to survive the murderous rage of a crazed psycho-killer lurking among them!', '2009-09-25', 4.45, 'https://image.tmdb.org/t/p/w500/wUEKxqSUv7dZwCwfCceCKkcgE0u.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41937, 'The Icicle Thief', 'Director Maurizio Nichetti is invited on TV to introduce a screening of his neo-realist classic ''The Icicle Thief''. He is horrified to discover that his black-and-white tale of life in poverty is constantly interrupted by garish color commercials, and even more horrified when a power cut in the studio causes film and commercials to mix up – a glamorous model finds herself in the arms of an unemployed pauper, while his wife finds herself in consumers'' heaven. Nichetti has to break into the film to try to sort everything out.', '1989-02-16', 7.37, 'https://image.tmdb.org/t/p/w500/pvv62lACM2AVxFg56FAlNSpFnEV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41817, 'Heart Condition', 'Racist police officer Jack Moony has a vendetta against Napoleon Stone, a charismatic black lawyer who is sleeping with Jack''s old flame Crystal Gerrity. Jack has a heart attack, but his life is saved when he receives Stone''s heart, since Stone died mysteriously the same night as Jack was stricken. Stone is not completely gone, however, and as a ghost he is all too happy to give Jack advice on how he should do his job and live his life.', '1990-02-02', 5.68, 'https://image.tmdb.org/t/p/w500/2ApuvU24UEBlWeBiQGRyyOYFeqe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41951, 'Chocolat', 'On her way to visit her childhood home in a colonial outpost in Northern Cameroon, a young French woman recalls her childhood, her memories concentrating on her family''s houseboy.', '1988-05-18', 6.90, 'https://image.tmdb.org/t/p/w500/opJnIodpg8HPu9UiNXkKX8UXFsw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41946, 'The Return of the Musketeers', 'It''s 1649: Mazarin hires the impoverished D''Artagnan to find the other musketeers: Cromwell has overthrown the English king, so Mazarin fears revolt, particularly from the popular Beaufort. Porthos, bored with riches and wanting a title, signs on, but Aramis, an abbé, and Athos, a brawler raising an intellectual son, assist Beaufort in secret. When they fail to halt Beaufort''s escape from prison, the musketeers are expendable, and Mazarin sends them to London to rescue Charles I. They are also pursued by Justine, the avenging daughter of Milady de Winter, their enemy 20 years ago. They must escape England, avoid Justine, serve the Queen, and secure Beauford''s political reforms.', '1989-04-12', 6.20, 'https://image.tmdb.org/t/p/w500/5KP0TNYT2yH1yo7sfV5hQWQ4qWA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41556, 'The Romantics', 'Alliances are tested when seven college pals reunite to watch two of their own say “I do” at a seaside wedding. But the maid of honor and the groom share a passionate history, and the bride isn’t the only one who’s wondering if it’s all in the past.', '2010-09-10', 4.92, 'https://image.tmdb.org/t/p/w500/pKXGDEgtqbXZBvwcZiZeWydqIEH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41963, 'Masquerade', 'A recently orphaned heiress meets a young racing yacht captain on Long Island. He shows interest in her and, being heiress to $200,000,000, love may not be the reason.', '1988-03-11', 5.67, 'https://image.tmdb.org/t/p/w500/vf2fZMZ0s44STAjF6kE7wVcKiw1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41965, 'Paperhouse', 'A young girl lost in the loneliness and boredom of reality finds solace in an ill boy, whom she can visit in a surreal dream world that she drew in her school composition book.', '1988-09-10', 6.50, 'https://image.tmdb.org/t/p/w500/ZblvybDhNSbEheAF9h8i0iUrdl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41975, 'Story of Women', 'France, World War II. In order to somehow make ends meet, the mother of two children, Marie Latour, does underground abortions and rents a room to a familiar prostitute. She doesn''t pay any attention to her husband, who returned from the war because of his injury, and lives her own life. Abortions gradually begin to bring a good income, and boredom can be easily dispelled by starting up with a young lover.', '1988-09-14', 7.30, 'https://image.tmdb.org/t/p/w500/gIBOAemklR8MVYP0Vn5RE0MYYWT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41999, 'The Art of the Steal', 'A gripping tale of intrigue and mystery in the art world, this film traces the history of a collection of Post-Impressionist paintings - worth billions - which became the subject of a power struggle after the death of its owner. Dr. Albert Barnes.', '2010-02-26', 6.90, 'https://image.tmdb.org/t/p/w500/1zK8dAd8cP92AMAHXoIvewwX7BI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42000, 'The Great Yokai War', 'A young boy with a troubled home life becomes "chosen," and he stumbles into the middle of a great war of yōkai (a class of mythological creatures), where he meets a group of friendly yōkai who become his companions through his journey. Now he must fight to protect his friends and free the world of the yōkai from oppression.', '2005-08-06', 6.29, 'https://image.tmdb.org/t/p/w500/xk96VmT0IC2nvWJG9iRWJrzEpmB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41852, 'A Family Thing', 'Earl Pilcher Jr. runs an equipment rental outfit in Arkansas, lives with his wife and kids and parents, and rarely takes off his gimme cap. His mother dies, leaving a letter explaining he''s not her natural son, but the son of a Black woman who died in childbirth; plus, he has a half brother Ray, in Chicago, she wants him to visit. Earl makes the trip, initially receiving a cold welcome from Ray and Ray''s son, Virgil. His birth mother''s sister, Aunt T., an aged and blind matriarch, takes Earl in tow and insists that the family open up to him.', '1996-03-29', 6.56, 'https://image.tmdb.org/t/p/w500/1IHxwmguaeytGo6m0wZaS0s3fP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42006, 'Red Sorghum', 'An old leper who owned a remote sorghum winery dies. Jiu''er, the wife bought by the leper, and her lover, identified only as "my Grandpa" by the narrator, take over the winery and set up an idealized quasi-matriarchal community headed by Jiu''er. When the Japanese invaders subject the area to their rule and cut down the sorghum to make way for a road, the community rises up and resists as the sorghum grows anew.', '1988-10-10', 7.17, 'https://image.tmdb.org/t/p/w500/2CP2eazEBKJ3njm4HM63pMfs5tW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42010, 'Made in Heaven', 'Deceased drifter Mike arrives in Heaven and quickly falls for newborn soul Annie, soon to start her assignment on Earth. When Annie leaves, Mike follows.', '1987-11-06', 6.50, 'https://image.tmdb.org/t/p/w500/zJ6LiVvnIL9Nuiskrf1swGJ2fwE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42045, 'Sweet Dreams', 'The story of Patsy Cline, the velvet-voiced country music singer who died in a tragic plane crash at the height of her fame.', '1985-10-02', 6.42, 'https://image.tmdb.org/t/p/w500/3BuTH2W1s2AQTZAfiLoUMTx1PmM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42113, 'The Ballad of Narayama', 'In a small village in a valley everyone who reaches the age of 70 must leave the village and go to a certain mountain top to die. If anyone should refuse they would disgrace their family. Old Orin is 69. This winter it is her turn to go to the mountain. But first she must make sure that her eldest son Tatsuhei finds a wife.', '1983-04-29', 7.50, 'https://image.tmdb.org/t/p/w500/h3iNimtw6HsFTtAvEDF3XYZ4Y5T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42121, 'Tender Mercies', 'Alcoholic former country singer Mac Sledge makes friends with a young widow and her son. The friendship enables him to find inspiration to resume his career.', '1983-03-04', 6.79, 'https://image.tmdb.org/t/p/w500/fBP6uK0K4EnV8dtt4SJQrMdX0wb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42122, 'The Dresser', 'In a touring Shakespearean theater group, a backstage hand - the dresser - is devoted to the brilliant but tyrannical head of the company. He struggles to support the deteriorating star as the company struggles to carry on during the London Blitz. The pathos of his backstage efforts rival the pathos in the story of Lear and the Fool that is being presented on-stage, as the situation comes to a crisis.', '1983-12-06', 6.81, 'https://image.tmdb.org/t/p/w500/o3IBu0gk7yEZ57BD8MAloP1cGeS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42124, 'Burden of Dreams', 'The Amazon rain forest, 1979. The crew of Fitzcarraldo (1982), a film directed by German director Werner Herzog, soon finds itself with problems related to casting, tribal struggles and accidents, among many other setbacks; but nothing compared to dragging a huge steamboat up a mountain, while Herzog embraces the path of a certain madness to make his vision come true.', '1982-10-01', 7.56, 'https://image.tmdb.org/t/p/w500/qJuD9yZ7Mn9QCVqKO9WarNNYo4R.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42130, 'The Night of the Shooting Stars', 'The Night of San Lorenzo, the night of the shooting stars, is the night when dreams come true in Italian folklore. In 1944, a group of Italians flee their town after hearing rumours that the Nazis plan to blow it up and that the Americans are about to arrive to liberate them.', '1982-09-16', 7.13, 'https://image.tmdb.org/t/p/w500/u9QgkfHj90rr33KhjLlk5tr7bVg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42151, 'Down Terrace', 'After serving jail time for a mysterious crime, Bill and Karl get out of jail and become preoccupied with figuring out who turned them in to the police. On top of that, the "family business" is on the rocks, and the motley crew of criminals who operate out of Down Terrace aren''t feeling terribly trusting of one another. It might look like an ordinary house, but at Down Terrace, the walls are closing in..', '2010-07-30', 6.14, 'https://image.tmdb.org/t/p/w500/2WMwkZ4Qmsi3X6WvfjvBsC1er6F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41841, 'Tall Tale: The Unbelievable Adventure', 'A young boy draws on the inspiration of legendary western characters to find the strength to fight an evil land baron in the old west who wants to steal his family''s farm and destroy their idyllic community. When Daniel Hackett sees his father Jonas gravely wounded by the villainous Stiles, his first urge is for his family to flee the danger, and give up their life on a farm which Daniel has come to despise anyway. Going alone to a lake to try to decide what to do, he falls asleep on a boat and wakes to find himself in the wild west, in the company of such "tall tale" legends as Pecos Bill, Paul Bunyan, John Henry and Calamity Jane. Together, they battle the same villains Daniel is facing in his "real" world, ending with a heroic confrontation in which the boy stands up to Stiles and his henchmen, and rallies his neighbors to fight back against land grabbers who want to destroy their town.', '1995-03-24', 6.21, 'https://image.tmdb.org/t/p/w500/di43EvahPBbdTgZrBxx8yZjvFu8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42159, 'The Idolmaker', 'Based on the life of rock promoter/producer Bob Marucci, who discovered, among others, Frankie Avalon and Fabian.', '1980-11-14', 5.59, 'https://image.tmdb.org/t/p/w500/sQoGkwIMsfIhfC0ukouBvWOTIpK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42158, 'The Competition', 'The movie centers on a piano competition whose winner is assured of success. It is Paul''s last chance to compete, but newcomer Heidi may be a better pianist. Can romance be far away? Will she take a dive despite the pressure to win from her teacher, Greta, or will she condemn Paul to obscurity?', '1980-12-03', 6.10, 'https://image.tmdb.org/t/p/w500/14iMtdJY3HjwrmqPUZ55F4LzuCd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42160, 'The Stunt Man', 'A fugitive stumbles onto a movie set just when they need a new stunt man, takes the job as a way to hide out and falls for the leading lady while facing off with his manipulative director.', '1980-11-03', 6.61, 'https://image.tmdb.org/t/p/w500/yk7sVvXxAOO2oncDkjaon4C7ErX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41428, 'Tetsuo: The Iron Man', 'A "metal fetishist", driven mad by the maggots wriggling in the wound he''s made to embed metal into his flesh, runs out into the night and is accidentally run down by a Japanese businessman and his girlfriend. The pair dispose of the corpse in hopes of quietly moving on with their lives. However, the businessman soon finds that he is now plagued by a vicious curse that transforms his flesh into iron.', '1989-07-01', 6.97, 'https://image.tmdb.org/t/p/w500/lARc59hUAKW3ziWddftUnZ99R8c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41402, 'Let Me In', 'A bullied young boy befriends a young female vampire who lives in secrecy with her guardian.  A remake of the movie “Let The Right One In” which was an adaptation of a book.', '2010-10-01', 6.79, 'https://image.tmdb.org/t/p/w500/rgNb9nwPKwV45c5PTvFqFmpzGt0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42222, 'Julia', 'At the behest of an old and dear friend, playwright Lillian Hellman undertakes a dangerous mission to smuggle funds into Nazi Germany.', '1977-10-01', 6.52, 'https://image.tmdb.org/t/p/w500/qHtPzs9eVCilp88c1arq73gH6xk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42229, 'A Special Day', 'Two neighbours — a persecuted journalist and a resigned housewife — forge a strong bond on the day of Adolf Hitler''s historic 1938 visit to Rome.', '1977-08-11', 8.06, 'https://image.tmdb.org/t/p/w500/jzRn7N1mFowkQ5IkUkfWoxXJtYU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42236, 'Fellini''s Casanova', 'Imprisoned for practicing black magic, writer and adventurer Giacomo Casanova escapes and wanders Europe, using his fluid sexuality to find his place in life amid a variety of eccentric and strange characters.', '1976-12-10', 6.89, 'https://image.tmdb.org/t/p/w500/ygTsnjWEUY8fbXzFWIh07eEHf3w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42237, 'Jonah Who Will Be 25 in the Year 2000', 'A look at the lives of several men and women in their 30s as they confront the slim gains of the "revolutionary" sixties. Max, a dissatisfied copy editor; Myriam, a redhead into tantric sex; and Marie, a supermarket checker who gives unauthorized discounts to the elderly, search for renewed meaning on a communal farm. The title character, a six-year-old child, is the carrier of their hopes for the future.', '1976-12-01', 6.80, 'https://image.tmdb.org/t/p/w500/zwqnEiUygCOGRZJvbzaTRF6tbsC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41283, 'Faster', 'After 10 years in prison, Driver is now a free man with a single focus - hunting down the people responsible for brutally murdering his brother.', '2010-11-23', 6.35, 'https://image.tmdb.org/t/p/w500/AsUeaXrhw4oscCSjUZ6heh1pVvd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41439, 'Saw 3D', 'As a deadly battle rages over Jigsaw''s brutal legacy, a group of Jigsaw survivors gathers to seek the support of self-help guru and fellow survivor Bobby Dagen, a man whose own dark secrets unleash a new wave of terror.', '2010-10-22', 5.97, 'https://image.tmdb.org/t/p/w500/qHCZ6LjtmqWDfXXN28TlIC9OppK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41446, 'Scream 4', 'Fifteen years after the original Woodsboro murders, Sidney Prescott returns home to promote her new book about surviving trauma, only for a new Ghostface killer to emerge, targeting a new group of teens.', '2011-04-13', 6.50, 'https://image.tmdb.org/t/p/w500/3cf8p2qw9qnsaaFWc64AG6U05eT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41436, 'Paranormal Activity 2', 'Just as Daniel and Kristi welcome a newborn baby into their home, a demonic presence begins terrorizing them, tearing apart their perfect world and turning it into an inescapable nightmare.', '2010-10-20', 5.80, 'https://image.tmdb.org/t/p/w500/gfdrkBZAyUUXJJ2iLQe03SAYRD3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41848, 'The Amityville Curse', 'After purchasing a property in Amityville, New York, Debbie and her husband invite three of their closest friends to help renovate. Immediately uneasy in her new surroundings, she begins experiencing shockingly vivid nightmares.', '1990-05-07', 4.00, 'https://image.tmdb.org/t/p/w500/bGTF4uusklWxN0kBBe3msPKPCrb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41878, 'Savage Nights', 'Jean is young, gay, and promiscuous. Only after he meets one or two women, including Laura, does he come to realize his bisexuality. Jean has to overcome a personal crisis and a tough choice between Laura and his male lover Samy.', '1992-10-21', 6.48, 'https://image.tmdb.org/t/p/w500/wPzs0G2LV6shi0zpxdYOVZcuBDP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42164, 'Camera Buff', 'Filip buys an 8mm movie camera when his first child is born. Because it''s the first camera in town, he''s named official photographer by the local Party boss. His horizons widen when he is sent to regional film festivals with his first works but his focus on movie making also leads to domestic strife and philosophical dilemmas.', '1979-11-16', 7.54, 'https://image.tmdb.org/t/p/w500/l4n9LXUanIKdlKTCfRqrhwQbtVe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41463, 'My Favorite Wife', 'Years after her ship disappeared, a presumably dead woman returns home. To her shock, she finds her husband has remarried.', '1940-05-17', 7.01, 'https://image.tmdb.org/t/p/w500/zOeDeZnjqYcvRnMBcfb7omgH15v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42196, 'The Bad Seed', 'Air Force Colonel Kenneth Penmark and his wife, Christine, adore their daughter Rhoda, despite her secret tendency for selfishness. Christine keeps her knowledge of her daughter''s darker side to herself, but when a schoolmate of Rhoda''s dies mysteriously, her self-deception unravels.', '1956-09-12', 7.13, 'https://image.tmdb.org/t/p/w500/iAgSkpZslQ2s3onL9TaHbyWygtC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41515, 'Yogi Bear', 'A documentary filmmaker travels to Jellystone Park to shoot a project and soon crosses paths with Yogi Bear, his sidekick Boo-Boo, and Ranger Smith.', '2010-12-17', 5.56, 'https://image.tmdb.org/t/p/w500/5u6kGhqKVorNwcvz6zETWUPRmus.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41469, 'Next Stop Wonderland', 'Dumped by her loser boyfriend, Erin''s love life hits rock bottom when her overbearing mother places an embarrassing ad in the "personals" section of a local newspaper on her behalf. Erin''s disgust turns to curiosity as she searches for the right guy in a hilarious series of disastrous dates. Meanwhile, a lonely ex-plumber named Alan clumsily searches for his dream job while narrowly missing one chance meeting with Erin after another.', '1998-08-21', 5.97, 'https://image.tmdb.org/t/p/w500/cygwoUJ1LqXkYT451E7W3dHtfHZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42275, 'It Can''t Be!', 'The film includes three short stories based on the stories of Mikhail Zoshchenko: "Crime and Punishment", "Fun Adventure", and "Wedding Event" about the negative phenomena of the provincial life of the young country of the Soviets: stupidity, drunkenness, money-grubbing, lack of spirituality.', '1975-10-23', 7.30, 'https://image.tmdb.org/t/p/w500/rmxoa3hYcQxweULdO34BRoViqss.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42188, 'Never Let Me Go', 'As children, Kathy, Ruth, and Tommy spend their childhood at an idyllic and secluded English boarding school. As they grow into adults, they must come to terms with the complexity and strength of their love for one another while also preparing for the haunting reality awaiting them.', '2010-03-18', 6.85, 'https://image.tmdb.org/t/p/w500/8F0r5ng9Fp60OhzQfR5v33fppq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41876, 'The Damned', 'In the early days of Nazi Germany, a powerful noble family must adjust to life under the new dictatorship regime.', '1969-10-30', 7.31, 'https://image.tmdb.org/t/p/w500/ncrB07xLfGzbw10JE1vjQ7gQIT8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41465, 'Life with Father', 'A straitlaced turn-of-the-century father presides over a family of boys and the mother who really rules the roost.', '1947-09-13', 6.68, 'https://image.tmdb.org/t/p/w500/6b7xRttshmonGW6xzSCDMrHMTjA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41479, 'The Joneses', 'A seemingly perfect family moves into a suburban neighborhood, but when it comes to the truth as to why they''re living there, they don''t exactly come clean with their neighbors.', '2010-04-16', 6.20, 'https://image.tmdb.org/t/p/w500/5YINGouZK9pmPdMPAHv158eQf3o.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42602, 'The Passion of Anna', 'A recently divorced man and an emotionally devastated widow begin a love affair.', '1969-11-10', 7.40, 'https://image.tmdb.org/t/p/w500/cr01316AyxUZyZrdLwzz3AXrgJc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42618, 'Sweet Charity', 'Taxi dancer Charity continues to have faith in the human race despite apparently endless disappointments at its hands, and hope that she will finally meet the nice young man to romance her away from her sleazy life. Maybe, just maybe, handsome Oscar will be the one to do it.', '1969-02-25', 6.93, 'https://image.tmdb.org/t/p/w500/brwDwtckSCp2t4Hz3JU3vwCv83h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42279, 'Bootleggers', 'This is the second silent (save for a song) slapstick comedy short about adventures of Worldly, Coward, and Fool. In a small hunting lodge three friends are making illegal moonshine. Bottled "product" fills shelves quickly. Life is good. But their dog Barbos doesn''t understand that bringing a moonshine condenser coil to a police station is a bad idea...', '1961-01-08', 7.30, 'https://image.tmdb.org/t/p/w500/fZi6LHEs2BmuthHs5IyWYWj2DA5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42632, 'Monterey Pop', 'Featuring performances by popular artists of the 1960s, this concert film highlights the music of the 1967 California festival. Although not all musicians who performed at the Monterey Pop Festival are on film, some of the notable acts include the Mamas and the Papas, Simon & Garfunkel, Jefferson Airplane, the Who, Otis Redding, and the Jimi Hendrix Experience. Hendrix''s post-performance antics -- lighting a guitar on fire, breaking it and tossing a part into the audience -- are captured.', '1968-12-26', 7.30, 'https://image.tmdb.org/t/p/w500/wEB3c5Y5spAHOQaFWcsfFky3SWb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42684, 'Skyline', 'When strange lights descend on the city of Los Angeles, people are drawn outside like moths to a flame where an extraterrestrial force threatens to swallow the entire human population off the face of the Earth. Now the band of survivors must fight for their lives as the world unravels around them.', '2010-11-11', 5.07, 'https://image.tmdb.org/t/p/w500/7pdUFPw76zGwDKbNpXxJknh0YWB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
