INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42699, 'Yongary, Monster from the Deep', 'Earthquakes in central Korea turn out to be the work of Yongary, a prehistoric gasoline-eating reptile that soon goes on a rampage through Seoul.', '1967-08-13', 4.80, 'https://image.tmdb.org/t/p/w500/8o0ZwBHqueNvlynd2VX4xySRrFM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42719, 'Georgy Girl', 'A homely but vivacious young woman dodges the amorous attentions of her father''s middle-aged employer while attempting to please her glamorously stuck-up roommate Meredith.', '1966-08-04', 6.23, 'https://image.tmdb.org/t/p/w500/2v6ezHOqJM2HpSHiGWqLj0Mqs78.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42726, 'A Man and a Woman', 'A man and a woman meet by accident on a Sunday evening at their childrens'' boarding school. Slowly, they reveal themselves to each other, finding that they have something deeply in common.', '1966-05-27', 7.30, 'https://image.tmdb.org/t/p/w500/boDZQiubhyhksN8fcgM4sXZ2btW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (41495, 'Johnny Eager', 'A charming racketeer seduces the DA''s stepdaughter for revenge, then falls in love.', '1941-12-09', 6.20, 'https://image.tmdb.org/t/p/w500/eT56vNkYEHo1rv4xhtI3aJLKuUp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42731, 'A Thousand Clowns', 'Twelve-year-old Nick lives with his Uncle Murray, a Mr.Micawber-like Dickensian character who keeps hoping something won''t turn up. What turns up is a social worker, who falls in love with Murray and a bit in love with Nick. As the child welfare people try to force Murray to become a conventional man (as the price they demand for allowing him to keep Nick), the nephew, who until now has gloried in his Uncle''s iconoclastic approach to life, tries to play mediator. But when he succeeds, he is alarmed by the uncle''s willingness to cave in to society in order to save the relationship.', '1965-12-13', 6.89, 'https://image.tmdb.org/t/p/w500/tXPsmtVy3T5Whz20LwiscprCdCT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42738, 'Scorpio', 'Cross is an old hand at the CIA who often teams up with Frenchman Jean “Scorpio” Laurier, a gifted freelance operative. After their last mission together, the CIA orders Scorpio to eliminate Cross, leaving him no choice but to obey.', '1973-04-11', 6.20, 'https://image.tmdb.org/t/p/w500/zqz1tkIEXP0gfm1ePRUDtVi6bu2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42739, 'The War Zone', 'An alienated teenager, saddened that he has moved away from London, must find a way to deal with a dark family secret.', '1999-06-11', 6.79, 'https://image.tmdb.org/t/p/w500/ziw5h70xBbr1eyNaMX0ONT2GBl6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42740, 'The Collector', 'A man kidnaps a woman and holds her hostage just for the pleasure of having her there.', '1965-06-17', 7.35, 'https://image.tmdb.org/t/p/w500/iMiih5FGHwpUCAaJAIkYKl5Hffi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42293, 'The Hairdresser', 'When a salon refuses to hire her because of her plump figure, irrepressible hair stylist Kathi plots revenge by opening her own beauty parlor next door. But when she faces a cash-flow problem, Kathi resorts to some creative means of raising capital.', '2010-02-14', 6.10, 'https://image.tmdb.org/t/p/w500/i7iS8HgmMprSdVQHYgVMYAI9l1A.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42791, 'The Americanization of Emily', 'American sailor Charlie Madison falls for a pretty Englishwoman while trying to avoid a senseless and dangerous D-Day mission concocted by a deranged admiral.', '1964-10-27', 6.70, 'https://image.tmdb.org/t/p/w500/zA9254usF2X0m0P5CeEXft7uzSe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42797, 'The Unsinkable Molly Brown', 'The buoyant Molly Brown has survived the first crisis of her life—a flood. Sixteen years later she sets out to make her way in the world. She assures the Leadville saloon keeper that she can sing and play the piano, and learns quickly. Soon she marries Johnny Brown, who in a few years will be able to replace the original cigar wrapper wedding ring with a replica in gold and gemstones. The Browns head for Europe and bring a few crowned heads back to Denver for a party that turns into a ballroom brawl. Molly goes to Europe alone, returning on the Titanic. She didn''t survive a flood as a baby for the story to end here.', '1964-06-11', 5.70, 'https://image.tmdb.org/t/p/w500/gMFUWB1BHqLtiB2t1pstE6FpT7F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42801, 'Yesterday, Today and Tomorrow', 'Three tales of very different women using their sexuality as a means to getting what they want.', '1963-12-21', 7.42, 'https://image.tmdb.org/t/p/w500/uRJuHGtdNES7OgCoBpTXkOTO9IL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42807, 'The Newton Boys', 'The story of the Newton gang, the most successful bank robbers in history, owing to their good planning and minimal violence.', '1998-03-26', 6.06, 'https://image.tmdb.org/t/p/w500/v3VuDClmFZNjfI6YLTkeinae9HK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42750, 'Return of the Secaucus Seven', 'Seven former college friends, along with a few new friends, gather for a weekend reunion at a summer house in New Hampshire to reminisce about the good old days, when they got arrested on the way to a protest in Washington, D.C.', '1980-04-11', 6.50, 'https://image.tmdb.org/t/p/w500/bBo5W9RcFZepBDU6NZL0z8ycNyt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42814, 'The Front Page', 'Hildy Johnson is an investigative reporter looking for a bigger paycheck. When an accused murderer escapes from custody, Hildy sees an opportunity for the story of a lifetime. But when he finds the criminal, he learns that the man may not be guilty. With the help of his editor, Hildy attempts to hide the convict, uncover the conspiracy and write the scoop of his career.', '1931-04-04', 6.48, 'https://image.tmdb.org/t/p/w500/1ZVA6L4a5HKIdvfpNcxDU38BHYd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42852, 'Goodbye, Mr. Chips', 'Throughout the late 19th-century and early 20th-century, Mr Arthur Chipping rises from a shy, nervous teacher to the beloved, revered headmaster of Brookfield School, with his life and career shaped by his love for his wife and his unwavering dedication to his students.', '1939-07-28', 7.40, 'https://image.tmdb.org/t/p/w500/1M8yXsSglaW3CdUSX7uAxurwLtp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42812, 'Anna Christie', 'Old sailor Chris Christofferson eagerly awaits the arrival of his grown daughter Anna, whom he sent at five years old to live with relatives in Minnesota. He has not seen her since, but believes her to be a decent and respectably employed young woman. When Anna arrives, however, it is clear that she has lived a hard life in the dregs of society, and that much of spirit has been extinguished. She falls in love with a young sailor rescued at sea by her father, but dreads to reveal to him the truth of her past. Both father and young man are deluded about her background, yet Anna cannot quite bring herself to allow them to remain deluded.', '1930-02-21', 6.03, 'https://image.tmdb.org/t/p/w500/zHsjA95g42xeBEPcWdF4s1BA53L.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42861, 'Cimarron', 'When the government opens up the Oklahoma territory for settlement, restless Yancey Cravat claims a plot of the free land for himself and moves his family there from Wichita. A newspaperman, lawyer, and just about everything else, Cravat soon becomes a leading citizen of the boom town of Osage. Once the town is established, however, he begins to feel confined once again, and heads for the Cherokee Strip, leaving his family behind. During this and other absences, his wife Sabra must learn to take care of herself and soon becomes prominent in her own right.', '1931-01-26', 5.52, 'https://image.tmdb.org/t/p/w500/cqvfhi9s1VsTgXcV1B7vX0Cb1qA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42879, 'The Miracle of Morgan''s Creek', 'A small-town girl with a soft spot for American soldiers wakes up the morning after a wild farewell party for the troops to find that she married someone she can''t remember.', '1944-09-18', 6.83, 'https://image.tmdb.org/t/p/w500/rf2OgScEs3zsJL0Gp4ZMsR2ScdN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42296, 'Catfish', 'Nev, a 24-year-old New York-based photographer, has no idea what he''s in for when Abby, an eight-year-old girl from rural Michigan, contacts him on Facebook, seeking permission to paint one of his photographs. When he receives her remarkable painting, Nev begins a friendship and correspondence with Abby''s family. But things really get interesting when he develops a cyber-romance with Abby''s attractive older sister, Megan, a musician and model. Prompted by some startling revelations about Megan, Nev and his buddies embark on a road trip in search of the truth.', '2010-09-17', 6.81, 'https://image.tmdb.org/t/p/w500/mXNxee2ix6Ke0bSIqFST0UhbVLR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42881, 'Julien Donkey-Boy', 'Undiagnosed, untreated and generally untethered schizophrenic Julien lives with his pregnant younger sister, anorexic aspiring wrestler brother, sympathetic grandmother, and severely depressed and abusive German father.', '1999-10-15', 6.96, 'https://image.tmdb.org/t/p/w500/mK8pJA05Sdp3Hc4KWHMqhaMEbVW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42884, 'Cinderella', 'Cinderella chafes under the cruelty of her wicked stepmother and her evil stepsisters, until her Fairy Godmother steps in to change her life for one unforgettable night. At the ball, she falls for handsome Prince Christopher, whose parents, King Maximillian and Queen Constantina, are anxious for him to find a suitable paramour.', '1997-11-02', 6.59, 'https://image.tmdb.org/t/p/w500/54awQrtekrsI11bKg2NwQrBHLIe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42989, 'The Wrong Arm of the Law', 'The crooks in London know how it works. No one carries guns and no one resists the police. Then a new gang appears that go one better. They dress as police and steal from the crooks. This upsets the natural order of the police/criminal relationship and the police and the crooks join forces to catch the IPOs (Impersonating Police Officers), including an armoured car robbery in which the police must help the gangs to set a trap.', '1963-03-17', 6.70, 'https://image.tmdb.org/t/p/w500/8OjnowuacvM0n7sItBw3xNflPfS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43096, 'Gidget', 'Due to an accident while swimming in the sea, Francis meets the surfer Moondoggie. She''s fascinated with his sport and starts to hang out with his clique. Although they make fun of her at first, they teach her to surf and soon she''s accepted and given the nickname "Gidget". But it''s hard work to become more than a friend to Moondoggie.', '1959-04-09', 6.00, 'https://image.tmdb.org/t/p/w500/i4aRCd5sRzYLb3TLm8iiUN0iJTr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42314, 'Looking for Richard', 'Al Pacino''s deeply-felt rumination on Shakespeare''s significance and relevance to the modern world through interviews and an in-depth analysis of "Richard III."', '1996-10-11', 6.81, 'https://image.tmdb.org/t/p/w500/2iEgEoMP1S2YWKkYkwm8cgg2bBN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43109, 'The Killer Shrews', 'Trapped on a remote island by a hurricane, a group discover a doctor has been experimenting on creating half sized humans. Unfortunately, his experiments have also created giant shrews, who when they have run out of small animals to eat, turn on the humans.', '1959-06-25', 4.48, 'https://image.tmdb.org/t/p/w500/2agTmqPg2we1gd4Fr1p2UNAMORI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42297, 'Burlesque', 'Ali leaves behind a troubled life and follows her dreams to Los Angeles, where she lands a job as a cocktail waitress at the Burlesque Lounge, a once-majestic theater that houses an inspired musical revue. Vowing to perform there, she makes the leap from bar to stage, helping restore the club''s former glory.', '2010-11-23', 7.21, 'https://image.tmdb.org/t/p/w500/3U9zBIibERQZqYKM3N1a4MYgBsN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42994, 'Memories', 'Three back-to-back anime films by three different directors make up this sci-fi trilogy three years in the making.', '1995-12-23', 7.49, 'https://image.tmdb.org/t/p/w500/e0HIBRiKS5dWmXkxWvEh6JQZcc2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43137, 'Teacher''s Pet', 'The rugged editor of a city newspaper poses as a journalism student and flirts with the professor.', '1958-04-01', 6.84, 'https://image.tmdb.org/t/p/w500/nScpsAfMBj0ehlisTOuwivnulH5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42390, 'Boys Town', 'Devout but iron-willed Father Flanagan leads a community called Boys Town, a different sort of juvenile detention facility where, instead of being treated as underage criminals, the boys are shepherded into making themselves better people. But hard-nosed petty thief and pool shark Whitey Marsh, the impulsive and violent younger brother of an imprisoned murderer, might be too much for the good father''s tough-love system.', '1938-09-08', 6.79, 'https://image.tmdb.org/t/p/w500/jGwKOZvPItNSocHFAg1USbhKR6c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42371, 'Take This Job and Shove It', 'A junior executive is ordered to boost output in the hometown brewery where his old friends work.', '1981-04-24', 5.36, 'https://image.tmdb.org/t/p/w500/rAlLrcOr1ZSjXXIP1yY3FcXyLBZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42359, 'The Freshman', 'An unathletic college freshman ridiculed by his peers for his mannerisms strives to become popular by making the football team.', '1925-09-20', 6.96, 'https://image.tmdb.org/t/p/w500/3531lJNSMhrpcNWXrDIYYoYH6Rp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43002, 'Lonely are the Brave', 'A fiercely independent cowboy arranges to have himself locked up in jail in order to then escape with an old friend who has been sentenced to the penitentiary.', '1962-04-26', 7.38, 'https://image.tmdb.org/t/p/w500/g6wKfhwGPsKgPI77ZiLhL6argMQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42420, 'The Keys to the House', 'Meeting his handicapped son for the first time, a young father attempts to forge a relationship with the teenager.', '2004-09-10', 6.49, 'https://image.tmdb.org/t/p/w500/vQJtW76ln4tbOYlhkwoV1LkPy7m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43307, 'Mr. Skeffington', 'A beautiful but vain woman who rejects the love of her older husband must face the loss of her youth and beauty.', '1944-05-25', 6.81, 'https://image.tmdb.org/t/p/w500/7qqEkoPqC9ImQzPoVdVhI6NFGti.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43316, 'All That Heaven Allows', 'Two different social classes collide when Cary Scott, a wealthy upper-class widow, falls in love with her much younger and down-to-earth gardener, prompting disapproval and criticism from her children and country club friends.', '1955-08-25', 7.33, 'https://image.tmdb.org/t/p/w500/wlSmIk6iQ8yQhBG795UOOBUs4gF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43313, 'The Teahouse of the August Moon', 'In post-WWII Japan, an American captain is brought in to help build a school, but the locals want a teahouse instead.', '1957-01-14', 6.24, 'https://image.tmdb.org/t/p/w500/v2G1Vh14X9NslrHR9zGlGoV1i4M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43336, 'Executive Suite', 'When the head of a large manufacturing firm dies suddenly from a stroke, his vice-presidents vie to see who will replace him.', '1954-04-30', 7.07, 'https://image.tmdb.org/t/p/w500/dQ5LdPOkRwlTTl3ocObuNGKB1of.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43347, 'Love & Other Drugs', 'Maggie is an alluring free spirit who won''t let anyone – or anything – tie her down. But she meets her match in Jamie, whose relentless and nearly infallible charm serves him well with the ladies and the cutthroat world of pharmaceutical sales. Maggie and Jamie''s evolving relationship takes them both by surprise, as they find themselves under the influence of the ultimate drug: love.', '2010-11-22', 7.04, 'https://image.tmdb.org/t/p/w500/wZLM2uKJRYNchLmiCIjosX0rXy8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43376, 'Diary of a Country Priest', 'An inexperienced, sickly priest shows up in the rural French community of Ambricourt, where he joins the community''s clergy. But the locals don''t take kindly to the priest, and his ascetic ways and unsociable demeanor make him an outcast. During Bible studies at the nearby girls school, he is continually mocked by his students. Then his attempt to intervene in a family feud backfires into a scandal. His failures, compounded with his declining health, begin to erode his faith.', '1951-02-07', 7.47, 'https://image.tmdb.org/t/p/w500/mft7ZJqHxUyFaLL3ZYXX1MN2Gro.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43388, 'King Solomon''s Mines', 'Fortune hunter Allan Quatermain teams up with a resourceful woman to help her find her missing husband lost in the wilds of 1900s Africa while being pursued by hostile tribes and a rival German explorer.', '1950-11-09', 6.50, 'https://image.tmdb.org/t/p/w500/s5T4Da7d3f255YRyaWfhMWfoBKK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43423, 'The Wind Will Carry Us', 'Irreverent city engineer Behzad comes to a rural Kurdish village in Iran to keep vigil for a dying relative. In the meanwhile the film follows his efforts to fit in with the local community and how he changes his own attitudes as a result.', '1999-09-23', 7.10, 'https://image.tmdb.org/t/p/w500/tzrqZungDYA3Djp61NWUm7DtxNI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42888, 'How Do You Know', 'After being cut from the USA softball team and feeling a bit past her prime, Lisa finds herself evaluating her life and in the middle of a love triangle, as a corporate guy in crisis competes with her current, baseball-playing beau.', '2010-12-17', 5.33, 'https://image.tmdb.org/t/p/w500/jbOnp79eUZxQHgcdnTIRlxel1dE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43430, 'The Irony of Fate, or Enjoy Your Bath!', 'A group of old friends have a tradition of going to a public bathing house on New Year''s Eve. Occasionally too much vodka and beer makes two of them unconscious. The problem is that one of them (Sasha) has to go to Leningrad but another one (Zhenya) goes. Zhenya wakes up at Leningrad airport. Believing that he is still in Moscow he takes a taxi and goes home. The street name, building and even apartment number, the way an apartment complex looks the same and the key coincide completely - just typical Soviet-type ''economy'' architecture. Imagine the surprise of Nadya when she enters her apartment and finds a man without trousers in her bed. What''s more - Nadya''s fiancé also finds him there...', '1976-01-01', 7.25, 'https://image.tmdb.org/t/p/w500/zlkG0yVVamCyBnLLbD2zOaHMJEz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43442, 'I Remember Mama', 'Norwegian immigrant Marta Hanson keeps a firm but loving hand on her household of four children, a devoted husband and a highly-educated lodger who reads great literature to the family every evening. Through financial crises, illnesses and the small triumphs of everyday life, Marta maintains her optimism and sense of humor, traits she passes on to her aspiring-author daughter, Katrin.', '1948-03-09', 7.22, 'https://image.tmdb.org/t/p/w500/oqiq3Zm6NeiVvd08gpUUu3WrihA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43436, 'Little Women', 'Four sisters come of age in America in the aftermath of the Civil War.', '1949-03-10', 7.37, 'https://image.tmdb.org/t/p/w500/qrshhX8dywIOljtITGHGNK6TJcB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42517, 'The Big Doll House', 'Female prisoners in a Philippine jail are being subjected to sadistic torture. Five of the women, along with the help of two men, plot an escape.', '1971-04-30', 5.63, 'https://image.tmdb.org/t/p/w500/yVze9LOqMkCg0RfYmFJwk5MgLm2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42424, 'Zeus & Roxanne', 'Mary Beth is a marine biologist that gets annoyed when a dog called Zeus stows aboard her research boat. Nevertheless she is intrigued when the intrusive canine makes best-friends with her captive dolphin, Roxanne. She falls in love with Zeus''s owner, Terry, a musician who rides a bike.', '1997-01-24', 5.24, 'https://image.tmdb.org/t/p/w500/igyTJ9cFwjcuzMM5oa0lknRyvYv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43466, 'The Farmer''s Daughter', 'After leaving her family''s farm to study nursing in the city, a young woman finds herself on an unexpected path towards politics.', '1947-03-26', 7.12, 'https://image.tmdb.org/t/p/w500/k6RlWveQEKiVY7vFAPCi70Zisv0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43490, 'Objective, Burma!', 'A group of men parachute into Japanese-occupied Burma with a dangerous and important mission: to locate and blow up a radar station. They accomplish this well enough, but when they try to rendezvous at an old air-strip to be taken back to their base, they find Japanese waiting for them, and they must make a long, difficult walk back through enemy-occupied jungle.', '1945-02-17', 6.87, 'https://image.tmdb.org/t/p/w500/3hq4VhEMseKMZuNUaSExDyqGhja.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43485, 'Night and Day', 'When his first stage show fails, songwriter Cole Porter goes off to fight in WWI until, injured, he lands in a hospital. He impresses nurse Linda Lee with his creativity, but their budding romance must wait as Cole heads home. Back in New York, he mounts a series of popular shows, and when his work brings him back to Europe, he eventually marries Linda. But success doesn''t spare him from marital complications or bad news about a beloved relative.', '1946-07-02', 5.99, 'https://image.tmdb.org/t/p/w500/mrlKsBUxPwxGr8M8xupI96qrA8j.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43535, 'A Simple Twist of Fate', 'When Michael McCann is thrown over by the woman he loves, he becomes something of a misanthrope and a miser, spending all of his spare money on collectible gold coins. Living in the same town is an affluent family with two sons: John and Tanny. Tanny''s a wild boy, whom John cannot control, and one night he breaks into McCann''s house, and steals the gold and disappears, which nearly confirms McCann''s distrust of mankind. But then, a mysterious young woman dies in the snow outside McCann''s house, and her small daughter makes her way to McCann''s house and into McCann''s life and heart.', '1994-09-02', 6.14, 'https://image.tmdb.org/t/p/w500/2Jorj80Y4EVEAPDRVVdDXKSVUTw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43516, 'The Song of Bernadette', 'In 1858 Lourdes, France, adolescent peasant Bernadette has a vision of "a beautiful lady" in the Massabielle grotto - the townspeople assume this lady to be the Virgin Mary. Pompous government officials think the girl is insane, doing their best to suppress her and her followers, while the church wants nothing to do with the matter. But as Bernadette attracts wider and wider attention, the phenomenon overtakes everyone in the town, ultimately transforming their lives.', '1943-12-21', 7.10, 'https://image.tmdb.org/t/p/w500/kRZItSgFaSDnHePwxX5PfZvu5M8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43539, 'The Next Three Days', 'Life seems perfect for John Brennan until his wife, Lara, is arrested for a murder she says she didn’t commit. Three years into her sentence, John is struggling to hold his family together, raising their son and teaching at college while he pursues every means available to prove her innocence. With the rejection of their final appeal, Lara becomes suicidal and John decides there is only one possible, bearable solution: to break his wife out of prison.', '2010-11-18', 7.09, 'https://image.tmdb.org/t/p/w500/wBaRZ3aHa7qoYTSY0ONbXrXYk4B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43593, 'Piranha 3D', 'Each year the population of sleepy Lake Victoria, Arizona explodes from 5,000 to 50,000 residents for the annual Spring Break celebration. But then, an earthquake opens an underwater chasm, releasing an enormous swarm of ancient Piranha that have been dormant for thousands of years, now with a taste for human flesh. This year, there''s something more to worry about than the usual hangovers and complaints from locals, a new type of terror is about to be cut loose on Lake Victoria.', '2010-08-20', 5.42, 'https://image.tmdb.org/t/p/w500/lMLS2OFBbNYMSB1ZbVp4q2S4zTU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43566, 'Before and After', 'Two parents deal with the effects when their son is accused of murdering his girlfriend.', '1996-02-23', 5.92, 'https://image.tmdb.org/t/p/w500/oK8UKDrjFS14OFoihaQPfmmMOyI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43004, 'Long Day''s Journey Into Night', 'An Irish miser, his morphine addicted wife, their debauched older son, and a gravely ill younger son. A quiet Connecticut vacation home on one foggy day in August 1912 becomes the backdrop for domestic decline.', '1962-10-09', 6.90, 'https://image.tmdb.org/t/p/w500/b7cu92b2sAJix1WFiLZiHSkZY1r.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43634, 'Boys', 'Fed up with boarding school and frustrated with the way others have planned his life, John Baker Jr. wants a change -- anything to shake up his staid routine. The moment arrives when he stumbles upon a woman, Patty Vare, unconscious in a field. Deciding to risk it, John takes her to his dorm to look after her, much to the disapproval of his friends. John''s decision proves fateful as he and Patty grow close to one another. However, she may be keeping secrets from him.', '1996-05-10', 5.40, 'https://image.tmdb.org/t/p/w500/kxpLUlvqptToQbLZJbQ7YO4MUAe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43772, 'Secret Ballot', 'A female election agent and a gun-toting soldier try to collect votes among the local islanders with mixed success.', '2001-09-04', 6.00, 'https://image.tmdb.org/t/p/w500/nirVNVYtwxG3wkH7klpEYDq0Gvb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42518, 'Gulliver''s Travels', 'Gulliver washes ashore on Lilliput and attempts to prevent war between that tiny kingdom and its equally-miniscule rival, Blefiscu, as well as smooth the way for the romance between the Princess and Prince of the opposing lands. In this he is alternately aided and hampered by the Lilliputian town crier and general fussbudget, Gabby. A life-threatening situation develops when the bumbling trio of Blefiscu spies, Sneak, Snoop, and Snitch, manage to steal Gulliver''s pistol.', '1939-11-10', 6.20, 'https://image.tmdb.org/t/p/w500/fiwAJIAnSqWbU3JphqN8Y80mFM6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43802, 'The Little Foxes', 'In 1900, a clan attempts to strike a deal with a Chicago industrialist to get him to build cotton mills in their Deep South town.', '1941-08-29', 7.51, 'https://image.tmdb.org/t/p/w500/hahHchjsnx62Ry7qmv2apYmlPX8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43239, 'Silk Stockings', 'After three bumbling Soviet agents fail in their mission to retrieve a straying Soviet composer from Paris, the beautiful, ultra-serious Ninotchka is sent to complete their mission and to retrieve them. She starts out condemning the decadent West, but gradually falls under its spell—with the help of an American movie producer.  A remake of Ninotchka  (1939).', '1957-07-18', 6.86, 'https://image.tmdb.org/t/p/w500/kuV34rCOrcDt6Ii3149AlJs9bpM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43805, 'Northwest Passage', 'Based on the Kenneth Roberts novel of the same name, this film tells the story of two friends who join Rogers'' Rangers, as the legendary elite force engages the enemy during the French and Indian War. The film focuses on their famous raid at Fort St. Francis and their marches before and after the battle.', '1940-02-23', 6.60, 'https://image.tmdb.org/t/p/w500/d1J3K23jhEEt2uezEvYY0YtatWi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42441, 'Tifosi', 'Four different stories about italian football team’s supporter.', '1999-10-01', 5.58, 'https://image.tmdb.org/t/p/w500/jKXjLxy7aZ7bpn55TDJeVoQon2o.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43650, 'The Legend of Sleepy Hollow', 'Washington Irving''s tale of Ichabod Crane and the headless horseman is brought to life, narrated by Bing Crosby.', '1949-10-08', 7.43, 'https://image.tmdb.org/t/p/w500/6bt8qmhxVsgbxFLQCoAcekdCFiw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43258, 'Friendly Persuasion', 'The story of a family of Quakers in Indiana in 1862. Their religious sect is strongly opposed to violence and war. It''s not easy for them to meet the rules of their religion in everyday life but when Southern troops pass the area they are in real trouble. Should they fight, despite their peaceful attitude?', '1956-10-30', 6.64, 'https://image.tmdb.org/t/p/w500/mhsdObvFHoOfgaKAVJUOeK3LiOP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43074, 'Ghostbusters', 'Following a ghost invasion of Manhattan, paranormal enthusiasts Erin Gilbert and Abby Yates, nuclear engineer Jillian Holtzmann, and subway worker Patty Tolan band together to stop the otherworldly threat.', '2016-07-14', 5.34, 'https://image.tmdb.org/t/p/w500/wJmWliwXIgZOCCVOcGRBhce7xPS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43832, 'Only Angels Have Wings', 'A traveling performer arrives at a remote South American port town where the head of an air freight service must risk his pilots'' lives to earn a major contract.', '1939-05-15', 7.30, 'https://image.tmdb.org/t/p/w500/lqcwiWancAkjtAQPHr9V3SfJjBM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42521, 'Idiots and Angels', 'Angel, a selfish rotter is hanging around in a local bar, groping the wife of the barman and dealing with weapons. One morning he wakes up finding a pair of wings growing at his back. These wings do good deeds against his nature. But suddenly he finds himself fighting those who want these wings for their own dark plans.', '2008-04-26', 6.73, 'https://image.tmdb.org/t/p/w500/z1cKsKMfjl5n1TNcfnk2rQ20wM0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43739, 'Love Affair', 'A French playboy and an American former nightclub singer fall in love aboard a ship. They arrange to reunite six months later, if neither has changed their mind.', '1939-04-07', 6.97, 'https://image.tmdb.org/t/p/w500/2bKxlYgwKRQidS8S9DSPjpITPlv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42541, 'From the Terrace', 'Alfred Eaton, an ambitious young executive, climbs to the top of New York''s financial world as his marriage crumbles. At the brink of attaining his career goals, he is forced to choose between business success, married to the beautiful, but unfaithful Mary and starting over with his true love, the much younger Natalie.', '1960-07-15', 6.60, 'https://image.tmdb.org/t/p/w500/nG0CavLX9OXhtUVX0a3Nj9pLsA6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42580, 'Life with Mikey', 'Michael Chapman, a former child TV star, runs a struggling talent agency specilizing in child acts. When a young girl off the street puts on a real performance after he catches her picking his pocket, he may have just found the next big thing.', '1993-06-04', 5.70, 'https://image.tmdb.org/t/p/w500/dKsvF5t5xsm17HG3GJzQQGJpJzP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43774, 'Baran', 'On a building site in present-day Tehran, Lateef, a 17-year-old Turkish worker is irresistibly drawn to Rahmat, a young Afghan worker. The revelation of Rahmat''s secret changes both their lives.', '2001-01-31', 7.50, 'https://image.tmdb.org/t/p/w500/mcsAug8npYWQ21W0Adv5ghpJuSk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43103, 'Room at the Top', 'An ambitious young accountant schemes to wed a wealthy factory owner''s daughter, despite falling in love with a married older woman.', '1958-12-29', 6.91, 'https://image.tmdb.org/t/p/w500/uuyruoqh7oBtjwN1mJyOF04CPjO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43881, 'San Francisco', 'A beautiful singer and a battling priest try to reform a Barbary Coast saloon owner in the days before the great earthquake and subsequent fires in 1906.', '1936-06-26', 6.57, 'https://image.tmdb.org/t/p/w500/zQF1UDB0ck4dRfKAn4XixGrCkjx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43886, 'Alice Adams', 'In the lower-middle-class Adams family, father and son are happy to work in a drugstore, but mother and daughter Alice try every possible social-climbing stratagem despite snubs and embarrassment. When Alice finally meets her dream man Arthur, mother nags father into a risky business venture and plans to impress Alice''s beau with an "upscale" family dinner. Will the excruciating results drive Arthur away?', '1935-08-23', 6.70, 'https://image.tmdb.org/t/p/w500/rjhJDaC7025umyBKvKHyOsocKDp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43892, 'Gold Diggers of 1935', 'Romance strikes when a vacationing millionairess and her daughter and son spend their vacation at a posh New England resort.', '1935-03-15', 6.50, 'https://image.tmdb.org/t/p/w500/utP30vhi3le9X3STgoUIKaOLIqG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43904, 'L''Atalante', 'Newly married couple Juliette and ship captain Jean struggle through marriage as they travel on the L''Atalante along with the captain''s first mate and a cabin boy.', '1934-04-24', 7.48, 'https://image.tmdb.org/t/p/w500/yDTHSZGk1G33Q3nBNqhnpgmkyk7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43905, 'Of Human Bondage', 'A young man finds himself attracted to a cold and unfeeling waitress who may ultimately destroy them both.', '1934-07-20', 6.50, 'https://image.tmdb.org/t/p/w500/cpGAPsHnCpifmLKeiLnwNgT157y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (42566, 'An Eye for an Eye', 'Sean Kane is forced to resign from the San Francisco Police Department''s Narcotics Division when he goes berserk after his partner is murdered. He decides to fight alone and follows a trail of drug traffickers into unexpected high places.', '1981-08-14', 5.26, 'https://image.tmdb.org/t/p/w500/389JSntj1J7LtTjUxvKCy3JJfuj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43919, 'Hatchet II', 'Picking up right where the original ended, Marybeth escapes the clutches of the swamp-dwelling killer Victor Crowley. After learning the truth about her family’s connection to the hatchet-wielding madman, Marybeth returns to the Louisiana swamps along with an army of hunters to recover the bodies of her family and exact the bloodiest revenge against the bayou butcher.', '2010-10-01', 5.53, 'https://image.tmdb.org/t/p/w500/k1lzmRZUGDejyV11JnD79yrEHiE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43923, 'It''s Kind of a Funny Story', 'A clinically depressed teenager gets a new start after he checks himself into an adult psychiatric ward.', '2010-10-08', 6.94, 'https://image.tmdb.org/t/p/w500/hQE4q8Szeaae4davgB7o8MTLmwr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43933, 'Monsters', 'Six years ago NASA discovered the possibility of alien life within our solar system. A probe was launched to collect samples, but crashed upon re-entry over Central America. Soon after, new life forms began to appear and half of Mexico was quarantined as an infected zone. Today, the American and Mexican military still struggle to contain "the creatures," while a journalist agrees to escort a shaken tourist through the infected zone in Mexico to the safety of the U.S. border.', '2010-06-18', 6.19, 'https://image.tmdb.org/t/p/w500/qpJyTxR33KG9qFmXoCD5AUTToPl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43939, 'I''m Still Here', 'I''m Still Here is a portrayal of a tumultuous year in the life of actor Joaquin Phoenix. With remarkable access, the film follows the Oscar-nominee as he announces his retirement from a successful film career in the fall of 2008 and sets off to reinvent himself as a hip-hop musician. The film is a portrait of an artist at a crossroads and explores notions of courage and creative reinvention, as well as the ramifications of a life spent in the public eye.', '2010-09-10', 5.95, 'https://image.tmdb.org/t/p/w500/h8c53OPv2miF6vzpVXQZX8jw1pJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43680, 'Heart of a Dog', 'In 1920s Moscow, shortly after the October Revolution, a stray dog named Sharik is taken in by Professor Preobrazhensky, a wealthy and respected surgeon. The professor performs a daring medical experiment on the dog that changes him into a human being. As the newly transformed Sharikov begins to navigate life in the professor’s apartment, his crude behavior and revolutionary ideas turn the household upside down.', '1988-11-11', 7.94, 'https://image.tmdb.org/t/p/w500/2kG3DWJ5OIaUZ0RtFEz6O9hEYDf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43947, 'I Spit on Your Grave', 'A beautiful woman from the city, Jennifer Hills, rents an isolated cabin in the country to write her latest novel. Soon, a group of local lowlifes subject her to a nightmare of degradation, rape, and violence.', '2010-06-17', 6.51, 'https://image.tmdb.org/t/p/w500/sD5mBllYcBR5sQTyR2VGYhpHf6B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43949, 'Flipped', 'When Juli meets Bryce in the second grade, she knows it''s true love. After spending six years trying to convince Bryce the same, she''s ready to give up - until he starts to reconsider.', '2010-08-06', 8.01, 'https://image.tmdb.org/t/p/w500/6zDYFigohwncqFL00MKbFV01dWb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43950, 'Amer', 'Ana is confronted with body and desire at three key moments of her life. As a young girl, she brings her dead grandpa back to life. In her puberty, she discovers the power of decay and sexuality. Finally, she wrestles with loss and loneliness when she returns to her parental home, now derelict.', '2009-09-23', 6.22, 'https://image.tmdb.org/t/p/w500/3O3F28FVnle4CgZM0i324wntxZU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44015, 'The Prime Gig', 'Pendelton "Penny" Wise is a smooth-talking con-artist who scams people with phoney travel comp vacations over the phone when, desperate for more fast cash, he''s called to work for a shady, veteran con businessman Kelly Grant. The situation takes a turn for the worst when Penny begins a relationship with Grant''s mistress, Caitlin.', '2001-04-24', 5.98, 'https://image.tmdb.org/t/p/w500/gJTeDkT6zYfUlSQFlSiBKfpibwA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43978, 'The Apple', 'After twelve years of imprisonment by their own parents, two Iranian sisters are finally released by social workers to face the outside world for the first time.', '1998-05-27', 6.40, 'https://image.tmdb.org/t/p/w500/5QC5xzyWIkGK2NcnpZUXThZYK66.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44018, 'Vagabond', 'Mona Bergeron is dead, her frozen body found in a ditch in the French countryside. From this, the film flashes back to the weeks leading up to her death. Through these flashbacks, Mona gradually declines as she travels from place to place, taking odd jobs and staying with whomever will offer her a place to sleep. Mona is fiercely independent, craving freedom over comfort, but it is this desire to be free that will eventually lead to her demise.', '1985-12-04', 7.37, 'https://image.tmdb.org/t/p/w500/2KFfwiPct1hwqi9dkKqoom0BenC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43959, 'Soul Surfer', 'The true story of teen surfer Bethany Hamilton, who lost her arm in a shark attack and courageously overcame all odds to become a champion again, through her sheer determination and unwavering faith.', '2011-04-08', 7.02, 'https://image.tmdb.org/t/p/w500/cvgRxrEupUFeJ0xzUExJo4dMXbL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44092, 'Reign of Assassins', 'Set in ancient China, Zeng Jing is a skilled assassin who finds herself in possession of a mystical Buddhist monk''s remains. She begins a quest to return the remains to its rightful resting place, and thus places herself in mortal danger because a team of assassins is in a deadly pursuit to possess the remains which holds an ancient power-wielding secret.', '2010-09-01', 6.87, 'https://image.tmdb.org/t/p/w500/jIQAm7YlBoZqllu4gbnagRlO9NY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44048, 'Unstoppable', 'When a massive, unmanned locomotive roars out of control, the threat is more ominous than just a derailment. The train is laden with toxic chemicals, and an accident would decimate human life and cause an environmental disaster. The only hope of bringing the train to a safe stop is in the hands of veteran engineer Frank Barnes, and young conductor Will Colson, who must risk their lives to save those in the runaway''s path. Inspired by true events.', '2010-11-04', 6.62, 'https://image.tmdb.org/t/p/w500/zKvHwL0GqLOear8rTnUPSTRYY0r.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44026, 'Mr. Arkadin', 'Claiming that he doesn''t know his own past, a rich man enlists an ex-con with an odd bit of detective work. Gregory Arkadin says he can''t remember anything before the late 1920s, and convict Guy Van Stratten is happy to take the job of exploring his new acquaintance''s life story. Guy''s research turns up stunning details about his employer''s past, and as his work seems linked to untimely deaths, the mystery surrounding Mr. Arkadin deepens.', '1955-06-27', 6.81, 'https://image.tmdb.org/t/p/w500/hoBfh3jmA3XDDx9tGgMwdGd37GE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44098, 'Undercurrent', 'After a rapid engagement, a dowdy daughter of a chemist weds an industrialist, knowing little of his family or past. He transforms her into an elegant society wife, but becomes enraged whenever she asks about Michael, his mysterious long-lost brother.', '1946-11-11', 5.94, 'https://image.tmdb.org/t/p/w500/7IyNoYoHcV5a52FhWj6QPxR8cBV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44113, 'Stone', 'Parole officer Jack Mabry has only a few weeks left before retirement and wishes to finish out the cases he''s been assigned. One such case is that of Gerald ''Stone'' Creeson, a convicted arsonist who is up for parole. Jack is initially reluctant to indulge Stone in the coarse banter he wishes to pursue and feels little sympathy for the prisoner''s pleads for an early release. Seeing little hope in convincing Jack himself, Stone arranges for his wife to seduce the officer, but motives and intentions steadily blur amidst the passions and buried secrets of the corrupted players in this deadly game of deception.', '2010-10-07', 5.32, 'https://image.tmdb.org/t/p/w500/mcdN6DntOAOtKNQKcRKnfFayFis.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44129, 'The Company Men', 'Bobby Walker lives the proverbial American dream: great job, beautiful family, shiny Porsche in the garage. When corporate downsizing leaves him and two co-workers jobless, the three men are forced to re-define their lives as men, husbands and fathers.', '2010-10-21', 6.54, 'https://image.tmdb.org/t/p/w500/tKX6E1nOf4vZN903YbkjQe7x1fv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44115, '127 Hours', 'The true story of mountain climber Aron Ralston''s remarkable adventure to save himself after a fallen boulder crashes on his arm and traps him in an isolated canyon in Utah.', '2010-11-12', 7.09, 'https://image.tmdb.org/t/p/w500/h0RMdn0rfl9l5hWXz3tUh6QVkhi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44040, 'Devil', 'A group of people are trapped in an elevator high above Philadelphia, and one of them is the Devil.', '2010-09-16', 6.10, 'https://image.tmdb.org/t/p/w500/aivXPSi53H95BoUa5njEYso389s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44154, 'A Touch of Zen', 'Yang Hui-zhen, a mysterious princess on the run from corrupt government officials, is joined in her endeavors by skilled Buddhist monks and an unambitious painter named Gu Sheng-zhai.', '1970-07-10', 7.61, 'https://image.tmdb.org/t/p/w500/pgveqayMFUIZbFqN87ghiKmmxt3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44181, 'National Lampoon''s Gold Diggers', 'Calvin and Leonard, two broke losers, are arrested for trying to rob rich old sisters Doris and Betty. The women have a change of heart, drop the charges and invite the the boys over to their mansion. Calvin decides he and Leonard should marry the women, and, when they soon die, live off the inheritance. The ladies, however, have run into their own financial troubles and wed the boys with plans of murdering them for insurance money.', '2003-06-15', 3.24, 'https://image.tmdb.org/t/p/w500/mOCAfLSo6hkAIdWRCvNwquwsPwy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44214, 'Black Swan', 'A committed dancer struggles to maintain her sanity after winning the lead role in a production of Tchaikovsky''s "Swan Lake."', '2010-12-03', 7.70, 'https://image.tmdb.org/t/p/w500/viWheBd44bouiLCHgNMvahLThqx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44258, 'The Persecution and Assassination of Jean-Paul Marat as Performed by the Inmates of the Asylum of Charenton Under the Direction of the Marquis de Sade', 'In Charenton Asylum, the Marquis de Sade directs a play about Jean Paul Marat''s death, using the patients as actors. Based on ''The Persecution and Assassination of Jean-Paul Marat as Performed by the Inmates of the Asylum of Charenton Under the Direction of the Marquis de Sade'', a 1963 play by Peter Weiss.', '1967-02-22', 6.16, 'https://image.tmdb.org/t/p/w500/7aucmdXXvqB4uW63K6t7P9sTc1f.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44238, 'World of Glory', 'The narrative portrays a plain man who guides the viewer through his life in a bleakly stylised world.', '1991-11-08', 7.14, 'https://image.tmdb.org/t/p/w500/AkmArVfTaXS9SPqOjWe80TY0vCC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43795, 'Penny Serenade', 'Julie and Roger are a love-struck married couple who desperately want to have a child. Tragedy after tragedy gets in their way, as the two attempt to rise above their troubles and fulfill their dreams of parenthood.', '1941-04-24', 6.60, 'https://image.tmdb.org/t/p/w500/7MC1fE5FSEIP9xf0N2VD68zRKv2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44340, 'Wendigo', 'A family from the city decide to spend a weekend away at a friend''s country farmhouse. But a fluke accident sets off a chain of events that alters their lives forever and conjures up the ferocious spirit of the Wendigo.', '2002-02-15', 4.95, 'https://image.tmdb.org/t/p/w500/cPtteHPYzO0ZBgr94Bx0a87zmzy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43128, 'Sons of the Desert', 'Ollie and Stan deceive their wives into thinking they are taking a medically necessary cruise when they are really going to a lodge convention.', '1933-12-29', 7.07, 'https://image.tmdb.org/t/p/w500/4ojrxP6qiyDOQ5jHQlh7Yn59wJt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43864, 'Stage Door', 'A spirited heiress wishing to break into theatre on her own merit arrives at a boardinghouse where aspiring young actresses and showgirls are brought together through their cynicism and disappointments.', '1937-10-08', 7.15, 'https://image.tmdb.org/t/p/w500/p4zqAKoJAtmkK71IyeWHc6spEKB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43742, 'Love Affair', 'Ex-football star Mike Gambril meets Terry McKay on a flight to Sydney, which is forced to land on a small atoll. They become romantic on board a ship sent to take them to a larger island. They agree to meet in New York three months later to see if the attraction is real. One shows up but the other doesn''t. However, a chance meeting brings them together again.', '1994-10-21', 5.51, 'https://image.tmdb.org/t/p/w500/uPEh48HZN9qqewkF2Hsi9BD6oz7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43874, 'Camille', 'Life in 1847 Paris is as spirited as champagne and as unforgiving as the gray morning after. In gambling dens and lavish soirees, men of means exert their wills and women turned courtesans exult in pleasure. One such woman is Marguerite Gautier, who begins a sumptuous romance with Armand Duval.', '1936-12-26', 6.96, 'https://image.tmdb.org/t/p/w500/78p9egiU16QpJNvmSVa4Vnr0JUK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43236, 'Peyton Place', 'In the outwardly respectable New England community of Peyton Place, shopkeeper Constance McKenzie tries to make up for a past indiscretion -- which resulted in her illegitimate daughter Allison  -- by adopting a chaste, prudish attitude towards all things sexual.  In spite of herself, Constance can''t help but be attracted to handsome new teacher Michael Rossi. Meanwhile, the restless Allison, who''d like to be as footloose and fancy-free as the town''s "fast girl" Betty Anderson, falls sincerely in love with mixed-up mama''s boy Norman Page.', '1957-12-13', 6.76, 'https://image.tmdb.org/t/p/w500/pSANpoBLMbejWTtiKz630eSaDpi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44379, 'The Gleaners and I', 'Varda focuses her eye on gleaners: those who scour already-reaped fields for the odd potato or turnip. Her investigation leads from forgotten corners of the French countryside to off-hours at the green markets of Paris, following those who insist on finding a use for that which society has cast off, whether out of necessity or activism.', '2000-07-07', 7.70, 'https://image.tmdb.org/t/p/w500/6IdCTKi4Eu7i897jpe59wIDGCri.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44251, 'Dragon Ball Z: Broly - Second Coming', 'A Saiyan Space pod crash-lands on Earth out of which a wounded Saiyan crawls: Broly, the Legendary Super Saiyan. The wounded Broly shouts out in frustration and turns into normal form. The place soon freezes, trapping him in it and he falls into a coma.', '1994-03-12', 6.77, 'https://image.tmdb.org/t/p/w500/Apnw8FWoPOIsu14d5dvaNZzFSJE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43807, 'All This, and Heaven Too', 'When lovely and virtuous governess Henriette Deluzy comes to educate the children of the debonair Duc de Praslin, a royal subject to King Louis-Philippe and the husband of the volatile and obsessive Duchesse de Praslin, she instantly incurs the wrath of her mistress, who is insanely jealous of anyone who comes near her estranged husband. Though she saves the duchess''s little son from a near-death illness and warms herself to all the children, she is nevertheless dismissed by the vengeful duchess as the attraction between the duke and Henriette continues to grow.', '1940-07-05', 7.23, 'https://image.tmdb.org/t/p/w500/j4KbLsCLnJVALXuV3djKOI8sUfc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43810, 'Down Argentine Way', 'The story—in which an American heiress on holiday in South America falls in love with an Argentine horse breeder against the wishes of their families—takes a backseat to the spectacular location shooting and parade of extravagant musical numbers, which include the larger-than-life Carmen Miranda singing the hit “South American Way” and a showstopping dance routine by the always amazing Nicholas Brothers.', '1940-10-11', 6.34, 'https://image.tmdb.org/t/p/w500/gg3DgplgKq8ZBFnMwMfgGuhSZCs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44326, 'Extremities', 'A woman escapes from the man who is about to rape her, but leaves her purse behind. Afraid that her attacker might come after her, she goes to the police, but with no proof of the incident, they can do nothing. In fact, the man does use the information in her bag and comes to her apartment with the intent of rape, but she sprays him in the face with insect repellent, and then holds him captive. She is then faced with deciding whether to go to the police who might not believe her and release him, or to kill him.', '1986-08-22', 6.18, 'https://image.tmdb.org/t/p/w500/AnzuqWIL840oE2vgtW81q1p1CAL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43277, 'The Great Ziegfeld', 'At the 1893 Chicago World''s Fair, sideshow barker Florenz Ziegfeld turns the tables on his more-successful neighbor Billings, and also steals his girlfriend. This pattern repeats throughout their lives, as Ziegfeld makes and loses many fortunes putting on ever-bigger, more spectacular shows', '1936-04-08', 6.27, 'https://image.tmdb.org/t/p/w500/rhF6vYFVCaPCs7CgDqg3n4mNod3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44564, 'The Dilemma', 'Longtime friends Ronny and Nick are partners in an auto-design firm. They are hard at work on a presentation for a dream project that would really launch their company. Then Ronny spots Nick''s wife out with another man, and in the process of investigating the possible affair, he learns that Nick has a few secrets of his own. As the presentation nears, Ronny agonizes over what might happen if the truth gets out.', '2011-01-13', 5.35, 'https://image.tmdb.org/t/p/w500/a7EVBTqeh6NoCFDW24qIp11kyi9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44585, 'Attack of the Puppet People', 'A deranged scientist creates a ray that can shrink people down to doll size.', '1958-04-01', 5.10, 'https://image.tmdb.org/t/p/w500/tN8lARzROe06PIOFhEyB6nyT1D3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43278, 'The Life of Emile Zola', 'A fictionalized account of famous French writer Emile Zola and his involvement in the Dreyfus Affair. After struggling to establish himself, Zola wins success writing about the unsavory side of Paris and settles into a comfortable upper-class life. However, Zola''s complacency is shaken when Jewish officer Alfred Dreyfus is imprisoned for being a spy. Realizing that Dreyfus is an innocent victim of anti-Semitism, Zola boldly pens a newspaper article exposing the truth, is charged with libel and must defend himself in a dramatic courtroom testimony.', '1937-09-09', 6.72, 'https://image.tmdb.org/t/p/w500/gsEa6ZU1zHhjTYneNNBQApzl8Vu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44603, 'Hereafter', 'Three people — a blue-collar American, a French journalist and a London school boy — are touched by death in different ways.', '2010-10-22', 6.14, 'https://image.tmdb.org/t/p/w500/nOy0X8XSmSDOuwV8pqT70WoWHwT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44639, 'Inside Job', 'A film that exposes the shocking truth behind the economic crisis of 2008. The global financial meltdown, at a cost of over $20 trillion, resulted in millions of people losing their homes and jobs. Through extensive research and interviews with major financial insiders, politicians and journalists, Inside Job traces the rise of a rogue industry and unveils the corrosive relationships which have corrupted politics, regulation and academia.', '2010-10-08', 7.70, 'https://image.tmdb.org/t/p/w500/7yXXIWec24htucjsZS1sDuPLqw8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44664, 'Reckless Kelly', 'A satirical take on a modern day Ned Kelly who is forced to Hollywood in order to make enough money to save his family''s land. As it goes against his belief, he cannot simply rob banks for his own benefit (all money goes to the poor). Ned is forced to find another way to come up with the $1 million required to save his family island.', '1993-04-08', 4.64, 'https://image.tmdb.org/t/p/w500/ufTt0YqzlZvNjht4YVEqzXWtaXK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44716, 'In a Better World', 'The lives of two Danish families cross each other, and an extraordinary but risky friendship comes into bud. But loneliness, frailty and sorrow lie in wait.', '2010-08-26', 7.15, 'https://image.tmdb.org/t/p/w500/dJpPpgf2z5lNw6xVxvfWm0lexNH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44705, 'Twelfth Night', 'Shakespeare''s comedy of gender confusion, in which a girl disguises herself as a man to be near the count she adores, only to be pursued by the woman he loves.', '1996-10-25', 7.00, 'https://image.tmdb.org/t/p/w500/uMvHIh50LqWJxUK26eYWV10epdq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44718, 'Get Low', 'A movie spun out of equal parts folk tale, fable and real-life legend about the mysterious, 1930s Tennessee hermit who famously threw his own rollicking funeral party... while he was still alive.', '2010-07-30', 6.71, 'https://image.tmdb.org/t/p/w500/6uUaQ5zn9neK1VLqO2sGClbJrb9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44363, 'Frozen', 'When three skiers find themselves stranded on a chair lift at a New England ski resort that has closed for the next week, they are forced to make life or death choices that prove to be more perilous than staying put and freezing to death.', '2010-02-05', 6.00, 'https://image.tmdb.org/t/p/w500/2J3URUnDrIpNvh0uVqINQvr4HhW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44754, 'Margaret', '17-year-old Lisa feels certain that she inadvertently played a role in causing a traffic accident that claimed a woman''s life. In her attempts to set things right, she meets with opposition at every step. Torn apart with frustration, she begins emotionally brutalizing her family, her friends, her teachers, and, most of all, herself. She has been confronted quite unexpectedly with a basic truth: that her youthful ideals are on a collision course with the realities and compromises of the adult world.', '2011-09-30', 6.37, 'https://image.tmdb.org/t/p/w500/zqBao8uRH6TQAJd13tqC22vPB76.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43818, 'Pride and Prejudice', 'In early 19th century England, Mr and Mrs Bennet''s five unmarried daughters vie for the affections of rich and eligible Mr Bingley and his status-conscious friend, Mr Darcy, who have moved into their neighbourhood. While Bingley takes an immediate liking to eldest daughter Jane, Darcy has difficulty adapting to local society and repeatedly clashes with second-eldest Elizabeth.', '1940-07-26', 6.90, 'https://image.tmdb.org/t/p/w500/yoWwsLkuY5tMxUqkKMOHAJlImTs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43860, 'King Solomon''s Mines', 'White hunter Allan Quartermain and his enigmatic guide help a young Irish woman locate her missing father in unexplored Darkest Africa.', '1937-06-17', 5.40, 'https://image.tmdb.org/t/p/w500/lbOgmmA5K32joQvmDpvAs5Dzfqh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44756, 'Daria in ''Is It Fall Yet?''', 'Daria is a 16-year-old girl who is a little too smart and funny to fit in with the crowd. It’s summertime and the livin'' is hard. Daria finds herself forced into volunteering at the OK To Cry Corral, a summer camp for the overly sensitive and those who''d like to be.', '2000-08-27', 7.39, 'https://image.tmdb.org/t/p/w500/KCRALQVraaSSfK9STb7lrnbwmS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44826, 'Hugo', 'Orphaned and alone except for an uncle, Hugo Cabret lives in the walls of a train station in 1930s Paris. Hugo''s job is to oil and maintain the station''s clocks, but to him, his more important task is to protect a broken automaton and notebook left to him by his late father. Accompanied by the goddaughter of an embittered toy merchant, Hugo embarks on a quest to solve the mystery of the automaton and find a place he can call home.', '2011-11-22', 7.17, 'https://image.tmdb.org/t/p/w500/1dxRq3o3l3bVWNRvvSb7rRf68qp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44772, 'No Small Affair', 'A 16-year-old aspiring photographer pursues a beautiful "older woman" of 22, a down-on-her-luck rock singer.', '1984-11-09', 5.47, 'https://image.tmdb.org/t/p/w500/vwtsHfe7zrkGFD10K7AkhEQk5cE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44490, 'Chuck & Buck', 'Chuck and Buck are childhood best friends whose lives have taken very different paths. While Chuck moved away and now has a real life, Buck stayed behind and developed a dangerous fixation—on Chuck''s life.', '2000-07-14', 6.03, 'https://image.tmdb.org/t/p/w500/k0GY9haWiwZtBOf2T7winwNcsep.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44833, 'Battleship', 'When mankind beams a radio signal into space, a reply comes from ‘Planet G’, in the form of several alien crafts that splash down in the waters off Hawaii. Lieutenant Alex Hopper is a weapons officer assigned to the USS John Paul Jones, part of an international naval coalition which becomes the world''s last hope for survival as they engage the hostile alien force of unimaginable strength. While taking on the invaders, Hopper must also try to live up to the potential that his brother, and his fiancée''s father—an Admiral—expect of him.', '2012-04-11', 5.93, 'https://image.tmdb.org/t/p/w500/9b0Im7SfedHiajTwzSL9zGyBI7M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44853, 'The Claim', 'A prospector sells his wife and daughter to another gold miner for the rights to a gold mine. Twenty years later, the prospector is a wealthy man who owns much of the old west town named Kingdom Come. But changes are brewing and his past is coming back to haunt him. A surveyor and his crew scouts the town as a location for a new railroad line and a young woman suddenly appears in the town and is evidently the man''s daughter.', '2000-12-29', 6.00, 'https://image.tmdb.org/t/p/w500/drpLBTmnMOzDUVAd3jqeLjdolcf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44835, 'Hesher', 'A young boy has lost his mother and is losing touch with his father and the world around him. Then he meets Hesher who manages to make his life even more chaotic.', '2010-01-22', 6.80, 'https://image.tmdb.org/t/p/w500/dD03azf3h1hUHVzVkkqJs96Kkay.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44859, 'Mortuary', 'A young woman investigates the seemingly accidental death of her father, revealing many unsettling secrets and putting her in mortal danger.', '1982-05-07', 5.21, 'https://image.tmdb.org/t/p/w500/lFjv4XTWRW1Q84A42ACzkQgBIDR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44865, 'The Grandmaster', 'The fall of China''s last dynasty, a time of chaos, division and war, is the golden age of Chinese martial arts. Legendary kung fu master Ip Man, who will eventually train Bruce Lee, finds his peaceful life interrupted by vengeance.', '2013-01-10', 6.60, 'https://image.tmdb.org/t/p/w500/ydBVVIscL6TsX5hYztA5YpBCwJ3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44896, 'Rango', 'When Rango, a lost family pet, accidentally winds up in the gritty, gun-slinging Western town of Dirt, the theater-loving lizard suddenly finds himself the newly appointed sheriff. Welcomed as the last hope the town has been waiting for, Rango is forced to play his new role to the hilt and uncover the truth behind a looming water crisis—before his act catches up with him.', '2011-03-02', 6.92, 'https://image.tmdb.org/t/p/w500/A5MP1guV8pbruieG0tnpPIbaJtt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44912, 'Green Lantern', 'For centuries, a small but powerful force of warriors called the Green Lantern Corps has sworn to keep intergalactic order. Each Green Lantern wears a ring that grants him superpowers. But when a new enemy called Parallax threatens to destroy the balance of power in the Universe, their fate and the fate of Earth lie in the hands of the first human ever recruited.', '2011-06-14', 5.19, 'https://image.tmdb.org/t/p/w500/fj21HwUprqjjwTdkKC1XZurRSpV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44943, 'Battle: Los Angeles', 'When once distant UFOs become a terrifying threat and an alien invasion force begins attacking Earths major costal and riverside cities, a U.S Marine staff sergeant and his team are sent into battle only to find they must take it upon themselves to defeat an unknown enemy and protect what remains of Los Angeles.', '2011-03-08', 5.83, 'https://image.tmdb.org/t/p/w500/jloyGeVYZSxM9zsLFvVOWuj2ey4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45019, 'Washington Square', 'In 1870s New York, spinster heiress Catherine Sloper is courted by the much younger, penniless Morris Townsend, much to the chagrin of her overprotective father. Catherine must decide whether to spend the rest of her life alone, or marry a man interested in her solely for her inheritence.', '1997-10-10', 6.21, 'https://image.tmdb.org/t/p/w500/3LIn7bskDwsmyxMWTNWRIPSCm2X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45096, 'Eve of Destruction', 'Eve is a military robot made to look exactly like her creator, Dr. Eve Simmons. When she is damaged during a bank robbery, the robot becomes an unstoppable killing machine. Colonel Jim McQuade is assigned to stop the robot and with the help from Dr. Simmons they have to predict where she will go next.', '1991-01-18', 4.73, 'https://image.tmdb.org/t/p/w500/lssgv86oGv5zMvfRV0bxcZN9Yuk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45227, 'A Man from the Boulevard des Capucines', 'Mr. Johnny First goes to the Wild West to present the art of the Cinematograph, and the lives of everyone in the frontier town of Santa Carolina change as a result of this.', '1987-06-23', 7.12, 'https://image.tmdb.org/t/p/w500/oj501hxty4iZCUUiV6GLPCdYw3M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43828, 'Destry Rides Again', 'Tom Destry, son of a legendary frontier peacekeeper, doesn’t believe in gunplay. Thus he becomes the object of widespread ridicule when he rides into the wide-open town of Bottleneck, the personal fiefdom of the crooked Kent.', '1939-11-30', 7.20, 'https://image.tmdb.org/t/p/w500/zEycmpHvzi60EJpbZCKbTc32AT7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45269, 'The King''s Speech', 'The King''s Speech tells the story of the man who became King George VI, the father of Queen Elizabeth II. After his brother abdicates, George (''Bertie'') reluctantly assumes the throne. Plagued by a dreaded stutter and considered unfit to be king, Bertie engages the help of an unorthodox speech therapist named Lionel Logue. Through a set of unexpected techniques, and as a result of an unlikely friendship, Bertie is able to find his voice and boldly lead the country into war.', '2010-11-26', 7.73, 'https://image.tmdb.org/t/p/w500/pVNKXVQFukBaCz6ML7GH3kiPlQP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (43875, 'Mary of Scotland', 'The recently widowed Mary Stuart returns to Scotland to reclaim her throne but is opposed by her half-brother and her own Scottish lords.', '1936-07-28', 6.22, 'https://image.tmdb.org/t/p/w500/AKInVpVxnGQLSrmnOUoqTlCtdm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44932, 'Without Warning', 'When a mountain town is besieged by aliens, stranded teens Sandy and Greg team up with a local hunter as a paranoid war vet becomes convinced they''re the enemy.', '1980-09-19', 5.20, 'https://image.tmdb.org/t/p/w500/q25eMSP4T8g9BNA0XdNyVllWtBN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45132, 'Super', 'After his wife falls under the influence of a drug dealer, an everyday guy transforms himself into Crimson Bolt, a superhero with the best intentions, though he lacks for heroic skills.', '2010-11-26', 6.52, 'https://image.tmdb.org/t/p/w500/jZrRMGSajZQehg8mz74A5A00L3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44510, 'The Grandmother', 'To escape neglect and abuse from his parents, a young boy plants some strange seeds and they grow into a grandmother.', '1970-07-01', 6.61, 'https://image.tmdb.org/t/p/w500/llhiY0rV6RWU1LOdy9Zljhf7cXm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44412, 'Company Man', 'In the 1960''s, a school teacher pretends to be a CIA spy to get his nagging wife off his back. He helps a Russian ballet dancer defect and is then sent to Cuba to locate "Agent X" for the CIA.', '2000-03-09', 5.12, 'https://image.tmdb.org/t/p/w500/qtHajQHigcU44j5DEgOdLbQev8u.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45129, 'Salaam Bombay!', 'When a revengeful Krishna destroys his brother''s motorbike, his mother asks him to return home only when he earns INR 500 to repair it. In a turn of events, he finds himself in a Bombay slum.', '1988-08-24', 7.26, 'https://image.tmdb.org/t/p/w500/405GFXA7NKwVxqP9WHD5RaKZ84C.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45317, 'The Fighter', 'Boxer "Irish" Micky Ward''s unlikely road to the world light welterweight title. His Rocky-like rise was shepherded by half-brother Dicky, a boxer-turned-trainer who rebounded in life after nearly being KO''d by drugs and crime.', '2010-12-10', 7.38, 'https://image.tmdb.org/t/p/w500/xfsFerGhO1h6rLk8vwLgMyQ8WVJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44539, 'An Amazing Couple', 'A woman, concerned by her husband''s eccentric behavior, hires a detective to follow his every move -- which yields unexpected results.', '2002-09-12', 5.70, 'https://image.tmdb.org/t/p/w500/gCfNIZuDMcKQTzcNDSCP4DkL3KK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45569, 'Red Hill', 'Young police officer Shane Cooper''s first day on duty, after relocating to the small town of Red Hill, rapidly turns into a nightmare. News of a prison break, involving convicted murderer Jimmy Conway, sends the local law enforcement officers - led by the town''s ruling presence, Old Bill - into a panic and leads to a terrifying and bloody confrontation.', '2010-11-05', 6.08, 'https://image.tmdb.org/t/p/w500/fLELMBUdDoqJvPDE7CcYn0Ny6y8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45576, 'Last Train Home', 'A family embarks on an annual tormenting journey along with 130 million other peasant workers to reunite with their distant family, and to revive their love and dignity as China soars as the world''s next super power.', '2009-06-06', 7.43, 'https://image.tmdb.org/t/p/w500/eFcySm0GE2JGw6524aSS0tRtJes.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45578, 'A Letter to Three Wives', 'A letter is addressed to three wives from their ''best friend'', announcing that she''s running away with one of their husbands – but she doesn''t specify which one.', '1949-01-20', 7.20, 'https://image.tmdb.org/t/p/w500/bSfwTLt2K8IeEeppsiDq7svikbV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45243, 'The Hangover Part II', 'The Hangover crew heads to Thailand for Stu''s wedding. After the disaster of a bachelor party in Las Vegas last year, Stu is playing it safe with a mellow pre-wedding brunch. However, nothing goes as planned and Bangkok is the perfect setting for another adventure with the rowdy group.', '2011-05-25', 6.51, 'https://image.tmdb.org/t/p/w500/cKZu0Fdkj7dmwbfMpgDqVVCkLJQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45612, 'Source Code', 'When decorated soldier Captain Colter Stevens wakes up in the body of an unknown man, he discovers he''s part of a mission to find the bomber of a Chicago commuter train.', '2011-03-30', 7.31, 'https://image.tmdb.org/t/p/w500/nTr0lvAzeQmUjgSgDEHTJpnrxTz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45649, 'Rubber', 'In the California desert, the adventures of a telepathic killer-tire, mysteriously attracted by a very pretty girl, as witnessed by incredulous onlookers.', '2010-11-09', 5.92, 'https://image.tmdb.org/t/p/w500/mWgCORI5IC5vOvB2cDVQe0YNtXZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45609, 'The Wings of the Dove', 'Kate is secretly betrothed to a struggling journalist, Merton Densher. But she knows her Aunt Maude will never approve of the match, since Kate''s deceased mother has lost all her money in a marriage to a degenerate opium addict. When Kate meets a terminally ill American heiress named Millie traveling through Europe, she comes up with a conniving plan to have both love and wealth.', '1997-09-04', 6.60, 'https://image.tmdb.org/t/p/w500/eb1ZnIEC8LMmMgwD2fIAmQOkcd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45658, 'Everything Must Go', 'When an alcoholic relapses, causing him to lose his wife and his job, he holds a yard sale on his front lawn in an attempt to start over. A new neighbor might be the key to his return to form.', '2011-05-13', 6.17, 'https://image.tmdb.org/t/p/w500/n4wMD3LHyo3nYZNWEOGLzgdyWjX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45671, 'Rough Magic', 'In the 1950s, a pretty magician''s apprentice travels to Mexico to escape her boyfriend, a wealthy politician, and to find a Mayan shaman who will teach her the ancient principles of magic.', '1995-09-07', 5.70, 'https://image.tmdb.org/t/p/w500/1ihrS8fbHnIvkcruSWBJSGiayh7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45697, 'A Christmas Carol', 'Miser Ebenezer Scrooge is awakened on Christmas Eve by spirits who reveal to him his own miserable existence, what opportunities he wasted in his youth, his current cruelties, and the dire fate that awaits him if he does not change his ways. Scrooge is faced with his own story of growing bitterness and meanness, and must decide what his own future will hold: death or redemption.', '1977-12-24', 6.65, 'https://image.tmdb.org/t/p/w500/sAqIotgXveaOjNFGd3MCwzCjHat.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45706, 'Tokyo Drifter', 'After yakuza boss Kurata dissolves his own criminal empire, a rival kingpin offers a position to Kurata''s top operative, Tetsuya "Phoenix Tetsu" Hondo. When the fiercely loyal Tetsu declines, Otsuka taps unstoppable Tatsuzo the "Viper", a ruthless gun-for-hire, to assassinate him. As the Viper trails his target through the countryside, the agile Phoenix Tetsu grows concerned that one of his former associates has betrayed him.', '1966-04-10', 7.09, 'https://image.tmdb.org/t/p/w500/dkscSldTB6FGUMMLnInUfKYLfPR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44494, 'Zero for Conduct', 'In a repressive boarding school with rigid rules of behavior, four boys decide to rebel against the director on a celebration day.', '1933-04-07', 6.88, 'https://image.tmdb.org/t/p/w500/oQcGB9BGj9LPTWcEdij47McotKY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45708, 'Play the Game', 'When ladies'' man David Mitchell (Paul Campbell) gives his lonely grandfather, Joe (Andy Griffith), some pointers on dating, Joe becomes a big hit with the women in his retirement community. But David strikes out with his own tricks when he tries to woo a girl named Julie (Marla Sokoloff). Now it''s up to Joe to teach his grandson how to win at love without playing games. Doris Roberts and Liz Sheridan co-star in this award-winning comedy.', '2009-02-27', 5.80, 'https://image.tmdb.org/t/p/w500/48vqo9NZ6SyPohEepFiQNnYvnOg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45745, 'Sintel', 'A wandering warrior finds an unlikely friend in the form of a young dragon. The two develop a close bond, until one day the dragon is snatched away. She then sets out on a relentless quest to reclaim her friend, finding in the end that her quest exacts a far greater price than she had ever imagined.', '2010-09-30', 7.30, 'https://image.tmdb.org/t/p/w500/2hwMOwcyyYWlHBldhonipg09kRm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45736, 'Shaolin Temple', 'There is no place more hallowed in the martial art world than China''s Shaolin Temple. This special place deserves a special epic, which is what the martial arts maestro delivers in this battle between a brave brand of Chinese boxers and literally thousands of Qing troops - complete with betrayals, intrigues, and such novel fighting machines as 108 wooden robots. The conflicts grow in complexity, intensity and even suspense as monks struggle to stay alive in the face of overwhelming odds.', '1976-12-22', 6.18, 'https://image.tmdb.org/t/p/w500/f6IALg4S0qujZha9xbFBLnELksZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45759, 'Helter Skelter', 'The rise of Charles Manson and his "family," who are responsible for a series of famous murders in the late 1960s. Manson, a magnetic and mysterious man, attracts road-weary single mother Linda Kasabian to join his collection of outcasts on a ranch outside of Los Angeles. After murdering actress Sharon Tate, Manson and his followers are investigated by district attorney Vincent Bugliosi.', '2004-07-23', 5.75, 'https://image.tmdb.org/t/p/w500/qunKvPx1m2VuuMELKIMqPKjkwbT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45772, 'Gnomeo & Juliet', 'A version of Shakespeare''s play, set in the world of warring indoor and outdoor gnomes. Garden gnomes Gnomeo and Juliet have as many obstacles to overcome as their quasi namesakes when they are caught up in a feud between neighbors. But with plastic pink flamingos and lawnmower races in the mix, can this young couple find lasting happiness?', '2011-01-13', 5.90, 'https://image.tmdb.org/t/p/w500/vVQwgfS9gSFviVT4gS7tZAmhRFc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45864, 'Extreme Days', 'As four lifelong friends, Will, Bryan, Matt, and Corey, are on the road trip they''ve been planning their whole lives, Corey''s beloved grandfather unexpectedly dies. When going to claim Corey''s inheritance, the gang meets Matt''s beautiful cousin Jessie and embark on a hilarious, extreme sports-filled adventure.', '2001-09-28', 5.25, 'https://image.tmdb.org/t/p/w500/yZG7XdvaGHivmjZ5UKYl6zFuSd3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45928, 'Incognito', 'Harry Donovan is an art forger who paints fake Rembrandt picture for $500,000. The girl he meets and gets into bed with in Paris, Marieke, turns out to be an arts expert Harry''s clients are using to check the counterfeit picture he painted.', '1997-11-14', 5.79, 'https://image.tmdb.org/t/p/w500/45idl65SLCipP1G1RMRVfkF4ldw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45929, 'Titanica', 'Titanica is a fascinating non-fiction drama which tells the story of the 1991 expedition to the wreck of the Titanic, the "unsinkable" luxury liner which collided with an iceberg and sank on April 15, 1912, losing 1,522 lives. Viewers experience the adventure, drama and danger of deep sea exploration through the activities of an international expedition team composed of unique and colourful characters, each with their own personal interest in the legendary wreck. Combining spectacular life-size images of the shattered remains on the ocean floor with recollections by survivor Eva Hart and computer-enhanced archival photographs, Titanica brings to life a remarkable tale of history, science and human ambition. IMAX', '1992-10-12', 6.10, 'https://image.tmdb.org/t/p/w500/z5WIS8QcnmccIeVzKiYLK9X2aUK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45964, 'When a Stranger Calls', 'A student babysitter has her evening disturbed when the phone rings. So begins a series of increasingly terrifying and threatening calls that lead to a shocking revelation.', '1979-08-24', 6.22, 'https://image.tmdb.org/t/p/w500/mdhpKVuuNZcc9noZzYXruxeIxdJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44264, 'True Grit', 'Following the murder of her father by a hired hand, a 14-year-old farm girl sets out to capture the killer. To aid her, she hires the toughest U.S. Marshal she can find—a man with ''true grit''—Reuben J. ''Rooster'' Cogburn.', '2010-12-22', 7.31, 'https://image.tmdb.org/t/p/w500/tCrB8pcjadZjsDk7rleGJaIv78k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45153, 'Eve''s Bayou', 'Summer heats up in rural Louisiana beside Eve’s Bayou, 1962, as the Batiste family tries to survive the secrets they’ve kept and the betrayals they’ve endured.', '1997-11-07', 6.45, 'https://image.tmdb.org/t/p/w500/33yTPcGSv7eo3FVlb7XKACHl1M8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45267, 'Boccaccio ''70', 'An anthology of four comic moral tales about the hypocrisies surrounding sex in 1960s Italy: frothy young love and office politics in the big city; milk advertisements that begin to haunt an aging prude; a trophy wife enduring her husband''s very public affairs; a lucky ticket-holder at a small town fair.', '1962-02-23', 6.90, 'https://image.tmdb.org/t/p/w500/7ZkRvQr0HspqEDBDVBHs16noFxd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46029, 'Two Much', 'A struggling Miami art gallerist incurs the wrath of a mobster when he becomes accidentally engaged to his flighty ex-wife, but he falls in love with the woman''s sister, so he invents a twin brother and plays both parts to satisfy the women.', '1995-12-01', 5.46, 'https://image.tmdb.org/t/p/w500/65WB70Jhi3G2c5C41PyL5pl9L9p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46063, 'Last Dance', 'Upon taking a new job, young lawyer Rick Hayes is assigned to the clemency case of Cindy Liggett, a woman convicted of first degree murder and sentenced to death. As Hayes investigates the background for her case, the two begin to form a deep friendship, while the date for her execution draws nearer.', '1996-05-02', 5.68, 'https://image.tmdb.org/t/p/w500/hsMe9TYfPs1VfpZs9xVLZBVGcES.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46094, 'The Air Up There', 'Jimmy Dolan is a college basketball coach who wants a big promotion. To get it, he needs to make a dramatic find. He ends up deep in Africa, hoping to recruit Saleh, a huge basketball prodigy Jimmy glimpsed in a home movie. But Saleh is the chief''s son and has responsibilities at home, since the tribe''s land is threatened by a mining company with its own hotshot basketball team.', '1994-01-07', 6.20, 'https://image.tmdb.org/t/p/w500/lY1yhtg0DRaMTzclYCXo0sP1kAV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46119, 'Crime + Punishment in Suburbia', 'Roseanne looks forward to her high school graduation and leaving her dysfunctional home life behind -- until a brutal act brings doom to all involved.', '2000-08-25', 5.74, 'https://image.tmdb.org/t/p/w500/gA6FiAOm8De8v0RFOrdUPn9mgXX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46138, 'Made in Dagenham', 'A dramatization of the 1968 strike at the Ford Dagenham car plant, where female workers walked out in protest against sexual discrimination.', '2010-10-01', 6.67, 'https://image.tmdb.org/t/p/w500/lcQGPxuk0fclp9UrFevI2lhDi1l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44297, 'Besieged', 'While in exile in Italy, an African woman finds herself trying to get back home and free her imprisoned husband. But the only man that can help her do so is in love with her.', '1998-02-05', 6.66, 'https://image.tmdb.org/t/p/w500/ZV18CMRVkUT119mmkGCz6mj6AD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44338, 'Balance', 'The setting is on a floating platform where a group of evenly and carefully placed men live. Each man is aware that the platform is not stable and in order not to fall to their deaths, they maintain a careful balance of weight to prevent the platform from tipping too far and cause them all to fall.', '1989-05-25', 7.47, 'https://image.tmdb.org/t/p/w500/4GgliKAlzR0W5Xo96nfbZjesQQD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45565, 'I Love You, I Love You Not', 'A school student and her European-born grandmother share sad stories of their lives.', '1996-08-28', 5.26, 'https://image.tmdb.org/t/p/w500/aesZ94JtQFiVdvNFNbO5CSeWms2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44497, 'Hustler White', 'Reminiscent of Sunset Boulevard, the action is transposed from the silver screen''s old backlots to contemporary male prostitution and the pornographic industry.', '1996-10-30', 5.50, 'https://image.tmdb.org/t/p/w500/1LI4muqdd7iWS6I63CDB0A9y1RV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44321, 'Our Lady of the Assassins', 'World-weary author Fernando has returned to his native Colombia to live out his days in peace. But Fernando''s once-quiet hometown has become a hotbed of violence, drugs, and corruption. On the brink of despair, Fernando meets Alexis, a beautiful but hardened street kid who lives by the rule of the gun. Together, they forge an unlikely relationship.', '2000-09-20', 7.15, 'https://image.tmdb.org/t/p/w500/q5jT6BBCIWIysr712UIZY7BOGje.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44470, 'Ice Cream Man', 'Young Gregory Tudor sees his local ice cream man murdered and later grows up to inherit his business, opting to inject gruesome ingredients—including human body parts—into his frozen confections. When one of the neighborhood boys goes missing, the local kids suspect Gregory and band together to get to the bottom of things.', '1995-05-09', 5.50, 'https://image.tmdb.org/t/p/w500/c6ZouvwSkBPnmKVjeBDwdA44Tx8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46146, 'Troll Hunter', 'A group of students investigates a series of mysterious bear killings, but learns that there are much more dangerous things going on. They start to follow a mysterious hunter, learning that he is actually a troll hunter.', '2010-10-29', 6.71, 'https://image.tmdb.org/t/p/w500/v2W5NEz0p9jPFzbbYt0dP86gsOX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44351, 'Rabbits', 'A story of a group of humanoid rabbits and their depressive, daily life. The plot includes Suzie ironing, Jane sitting on a couch, Jack walking in and out of the apartment, and the occasional solo singing number by Suzie or Jane. At one point the rabbits also make contact with their “leader”.', '2002-06-09', 6.70, 'https://image.tmdb.org/t/p/w500/8LHeas839avkylUmw1Q4uutZeR4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45958, 'Biutiful', 'This is a story of a man in free fall. On the road to redemption, darkness lights his way. Connected with the afterlife, Uxbal is a tragic hero and father of two who''s sensing the danger of death. He struggles with a tainted reality and a fate that works against him in order to forgive, for love, and forever.', '2010-10-20', 7.25, 'https://image.tmdb.org/t/p/w500/4BLshBMp8INRDhvfuKwxMlHDIIt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45523, 'Louis C.K.: Hilarious', 'In this unique and dynamic live concert experience, Louis C.K.''s exploration of life after 40 destroys politically correct images of modern life with thoughts we have all had...but would rarely admit to.', '2010-01-26', 7.79, 'https://image.tmdb.org/t/p/w500/8mJMrrT4tkfZLMFvKQ0Hq6jlXbp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46010, 'Old Men: Robbers', 'An old detective does not want to retire. The only way out is to prove to his boss that he still can catch criminals. The problem is that there were no crimes recently to work on. Together with his retired friend he decides to commit a perfect crime himself and then quickly solve it. Real problems start when a real criminal steals money he has stolen.', '1972-08-07', 7.20, 'https://image.tmdb.org/t/p/w500/hCoon0OCV0eT3MKRrnEOkU4j0JH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45324, 'Casino Jack', 'Based on a true story, a hot shot Washington DC lobbyist and his protégé go down hard as their schemes to peddle influence lead to corruption and murder.', '2010-09-16', 5.87, 'https://image.tmdb.org/t/p/w500/3Dpicp6VEtCSj39XBG5mnbe5TQ9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46187, 'The Thief', 'Katya and her 6-year-old son Sanya, who, in 1952, meet a veteran Soviet officer named Tolyan. Katya falls in love with Tolyan, who turns out to be a small time criminal, but who also becomes a father figure to Sanya ...', '1997-10-13', 7.00, 'https://image.tmdb.org/t/p/w500/rnHqDzKmnrm47dzhQvLJtZKRVK8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46195, 'Rio', 'Captured by smugglers when he was just a hatchling, a macaw named Blu never learned to fly and lives a happily domesticated life in Minnesota with his human friend, Linda. Blu is thought to be the last of his kind, but when word comes that Jewel, a lone female, lives in Rio de Janeiro, Blu and Linda go to meet her. Animal smugglers kidnap Blu and Jewel, but the pair soon escape and begin a perilous adventure back to freedom -- and Linda.', '2011-04-03', 6.77, 'https://image.tmdb.org/t/p/w500/4nJxhUknKV8Gqdhov8pU1YWDYfb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (44535, 'Somebody to Love', 'Mercedes is a taxi dancer who wants to be an actress. She''s involved with the married Harry, who considers himself a respected actor. Ernesto is in love with Mercedes, but he doesn''t dance or have money.', '1994-09-27', 5.20, 'https://image.tmdb.org/t/p/w500/9ShSfdYCbDoPtgZpZ1MbkrexuIQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45325, 'Tom and Huck', 'A mischievous young boy, Tom Sawyer, witnesses a murder by the deadly Injun Joe. Tom becomes friends with Huckleberry Finn, a boy with no future and no family. Tom has to choose between honoring a friendship or honoring an oath because the town alcoholic is accused of the murder. Tom and Huck go through several adventures trying to retrieve evidence.', '1995-12-22', 5.31, 'https://image.tmdb.org/t/p/w500/bMY31ikEOIPOHqQwhPhII8UVBln.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46836, 'Willy/Milly', 'Milly is annoyed whenever her mom tells her to behave more appropriate for a girl. She''s just not interested in fancy dresses or prom dances. Some day her best friend''s little brother offers her a potion which can make her deepest wish come true during a solar eclipse. She goes through with it and ends up with male genitals, additionally. So she has to decide if she wants to live as a boy or a girl. Her father, who always wanted a son, supports her in checking out life as a boy. Hence Milly changes school and starts out as Willy.', '1986-11-14', 5.40, 'https://image.tmdb.org/t/p/w500/p0nGwLpUYRDIuKck4XXbIn8YTk7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46261, 'Don''t Be Afraid of the Dark', 'A young girl sent to live with her father and his new girlfriend discovers creatures in her new home who want to claim her as one of their own.', '2010-11-06', 5.83, 'https://image.tmdb.org/t/p/w500/jMBMm1jwqvILV8p1K44brBnmwLK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46838, 'Tucker and Dale vs. Evil', 'Two hillbillies are suspected of being killers by a group of paranoid college kids camping near the duo''s West Virginian cabin. As the body count climbs, so does the fear and confusion as the college kids try to seek revenge against the pair.', '2010-01-22', 7.40, 'https://image.tmdb.org/t/p/w500/8shwLEDzajJGSfLgbpac8x8xn1U.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46878, 'The Swarm', 'Scientist Dr. Bradford Crane and army general Thalius Slater join forces to fight an almost invisible enemy threatening America; killer bees that have deadly venom and attack without reason. Disaster movie-master Irwin Allen''s film contains spectacular special effects, including a train crash caused by the eponymous swarm.', '1978-06-26', 5.03, 'https://image.tmdb.org/t/p/w500/pO5qEEpjxdQ40ScLcFOowyziNiT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46889, 'Living Out Loud', 'Judith Moore is suddenly single after discovering her husband of fifteen years, a successful doctor, has been having an affair with a younger woman. Judith stews, plans, plots and fantasizes, but she can''t decide what to do with her life until she goes out to a night club to see singer Liz Bailey, who is full of advice on life and love. While out on the town, Judith is suddenly kissed by a total stranger, which opens her eyes to new possibilities... which is when she notices Pat, the elevator operator in her building.', '1998-10-30', 6.00, 'https://image.tmdb.org/t/p/w500/uegG68vP7leUDQbG8fP4ihgTo0i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46917, 'Sword of the Beast', 'Legendary swordplay filmmaker Hideo Gosha''s Sword of the Beast chronicles the flight of the low-level swordsman Gennosuke, who kills one of his ministers as part of a reform plot. His former comrades then turn on him, and this betrayal so shakes his sense of honor that he decides to live in the wild, like an animal. There he joins up with a motley group who are illegally mining the shogun’s gold, and, with the aid of another swordsman, gets a chance not just at survival but to recover his name and honor.', '1965-09-18', 7.48, 'https://image.tmdb.org/t/p/w500/8CoqruUTwDldSP8iNSKvmhq2sOC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46924, 'Being Human', 'One man must learn the meaning of courage across four lifetimes centuries apart.', '1994-05-06', 5.12, 'https://image.tmdb.org/t/p/w500/1OJilNyyJPH3es0HZzebJjuPJua.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46967, 'Bill Burr: Let It Go', 'It’s always been a dream of mine to do a show at the Fillmore. The name itself is synonymous with legendary performances. Countless iconic musicians and comedians have been on that stage. To be a part of that history was something I’ll never forget. As much as I was trying to keep my head together before the show, I couldn’t help but feel like a tourist or just some random dude who won a contest. LET IT GO represents the culmination of material I developed on the road from 2008-2009. As always thanks to everyone who came out to my shows, laughed at the funny stuff and stared during the bombing. I hope you enjoy it. – Bill Burr', '2010-09-18', 7.72, 'https://image.tmdb.org/t/p/w500/9DKunkJiOxInOXZsk22bULt1428.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46989, 'Blue Car', 'Meg is a gifted but emotionally scarred 18-year-old who finds solace in writing poetry. Mr. Auster, her English teacher, recognizes her talent and encourages her to enter a national poetry contest. As tension at home escalates and Meg struggles to find a way to get to the poetry finals in Florida, Auster''s role in her life becomes increasingly complex.', '2003-04-25', 6.30, 'https://image.tmdb.org/t/p/w500/6xld6dA6rlctR9mUtcVRigZTfu5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46991, 'An Affair of Love', 'A man and a woman meet to fulfill her sexual fantasy.', '1999-09-04', 6.30, 'https://image.tmdb.org/t/p/w500/kTI6I2knV8uejV7O8VFDD8cTMOg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46992, 'Hilary and Jackie', 'The tragic story of world-renowned cellist Jacqueline du Pré, as told from the point of view of her sister, flautist Hilary du Pré-Finzi.', '1998-12-30', 6.60, 'https://image.tmdb.org/t/p/w500/aE2NJH2sllQTmbpN6laKuM7NXYy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46435, 'Topsy-Turvy', 'For nearly a decade, Gilbert and Sullivan’s collaborations have delighted the English people. But in 1884, as a London heat wave cuts into the theater trade, their latest work, "Princess Ida", receives lukewarm press. In an effort to reconcile their creative differences and drawing inspiration from Japanese culture, they went on to create the hit opera "The Mikado", one of the duo''s greatest successes.', '1999-12-15', 6.59, 'https://image.tmdb.org/t/p/w500/nxHjVAVOFgWbD2RptBBCLVO6SIR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47045, 'She''s Out of Control', 'A Los Angeles radio-station manager''s girlfriend shows his teenage daughter how to be sexy.', '1989-04-14', 5.20, 'https://image.tmdb.org/t/p/w500/wTQ4FIz8D0YsSSpcgGjR6EWFvhs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47003, 'The Deadly Bees', 'Pop singer Vicki Robbins collapses from exhaustion while shooting ta music video; her physician prescribes a respite on Seagull Island with beekeeper Ralph Hargrove. Initially finding the Hargroves'' bitter marital strife oddly relaxing, the arrival of specially-bred attack bees pushes Vicki to her survival instinct.', '1966-12-23', 4.39, 'https://image.tmdb.org/t/p/w500/ePWorn3mWFdZNSlQbjBbymrAzFC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47095, 'House of Cards', 'When Ruth Matthews''s husband is killed in a fall at an archaeological dig, her daughter Sally handles her father''s death in a very odd manner. As Sally''s condition worsens, Ruth takes her to see Jake, an expert in childhood autism. Jake attempts to bring Sally out of her mental disarray through traditional therapy methods, but Ruth takes a different route. She risks her own sanity by attempting to enter her daughter''s mind and make sense of the seemingly bizarre things that Sally does, including building a wondrous house of cards', '1993-06-25', 6.20, 'https://image.tmdb.org/t/p/w500/cmZTyKkjlchMjhgzvnpfkxIglqJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45397, 'My Left Eye Sees Ghosts', 'A car accident gives a spoiled, troubled young woman the ability to see ghosts, including one of a former classmate.', '2002-07-13', 6.30, 'https://image.tmdb.org/t/p/w500/hqg4I0EXEd1cb2SGngyZ8e6vaTk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47199, 'The Secret Agent', 'In 1880s London, pornographic bookseller Verloc is a double agent for the Russian government, providing information to Chief Inspector Heat about a lazy anarchist organization. In order for the anarchists to be arrested, an act of terrorism must occur. So Verloc decides to set up bombs – which leads to tragedy – not only for himself but also for his family, including wife Winnie and brother-in-law, Stevie.', '1996-11-08', 5.62, 'https://image.tmdb.org/t/p/w500/tPHoV5WGQROGQmbSw4h8NGWB22c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47333, 'Jane Eyre', 'After a bleak childhood, Jane Eyre goes out into the world to become a governess. As she lives happily in her new position at Thornfield Hall, she meets the dark, cold, and abrupt master of the house, Edward Rochester. Jane and her employer grow close in friendship and she soon finds herself falling in love with him. Happiness seems to have found Jane at last, but could Rochester''s terrible secret be about to destroy it forever?', '1996-01-20', 6.93, 'https://image.tmdb.org/t/p/w500/2vyt97wy8dEJYILoDoiPwTzLnzK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47327, 'Drive Angry', 'Milton is a hardened felon who has broken out of Hell, intent on finding the vicious cult who brutally murdered his daughter and kidnapped her baby. He joins forces with a sexy, tough-as-nails waitress, who''s also seeking redemption of her own. Caught in a deadly race against time, Milton has three days to avoid capture, avenge his daughter''s death, and save her baby before she''s mercilessly sacrificed by the cult.', '2011-02-24', 5.55, 'https://image.tmdb.org/t/p/w500/nx2pChi41Xv4dsXsfSG3gnKcWaY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46105, 'American: The Bill Hicks Story', 'American: The Bill Hicks Story is a biographical documentary film on the life of comedian Bill Hicks.', '2010-04-10', 7.36, 'https://image.tmdb.org/t/p/w500/8YGb2712WLwfcV6ZagNaolNfeYv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46420, 'The Loved Ones', 'When Brent turns down his classmate Lola''s invitation to the prom, she concocts a wildly violent plan for revenge.', '2010-11-04', 6.72, 'https://image.tmdb.org/t/p/w500/ydsLYdSiPSIL1LOWWYu7VCvDTT8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47475, 'Mr. Wrong', 'A single and lonely woman finds the seemingly perfect man to date, but soon regrets it when his deranged and possessive other personality emerges and worst still, she cannot convince anyone else of his Jekyll/Hyde true nature.', '1996-02-16', 4.12, 'https://image.tmdb.org/t/p/w500/csSkKS6rcGjG8jjpwKZPVCD7Kiq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46492, 'Sound of the Mountain', 'An ingratiating bride develops warm ties to her father-in-law while her cold husband blithely slights her for another woman.', '1954-01-15', 7.42, 'https://image.tmdb.org/t/p/w500/mzdKn2Eo5rZCV3fzBjVdxAI0KM8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47585, 'The Five Senses', 'Interconnected stories examine situations involving the five senses. Touch is represented by a massage therapist who is treating a woman, while her daughter accidentally loses the woman''s pre-school daughter in the park. The older daughter meets a voyeur (vision), a professional house-cleaner has an acute sense of smell, a cake maker has lost her sense of taste, and an older man is losing his hearing.', '1999-05-18', 5.71, 'https://image.tmdb.org/t/p/w500/y4UjdQJYxQEhenI7DFIM301Df7d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47288, 'The King and I', 'Widowed Welsh mother Anna Loenowens becomes a governess and English tutor to the wives and many children of the stubborn King Mongkut of Siam. Anna and the King have a clash of personalities as she works to teach the royal family about the English language, customs and etiquette, and rushes to prepare a party for a group of European diplomats who must change their opinions about the King.', '1999-03-19', 5.41, 'https://image.tmdb.org/t/p/w500/kbEA2LEFh1MX9EraNQSiq9ajs24.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (45408, 'The Protector', 'Billy Wong is a New York City cop whose partner is gunned down during a robbery. Billy and his new partner, Danny Garoni, are working security at a fashion show when a wealthy man''s daughter, Laura Shapiro, is kidnapped. The Federal authorities suspect that Laura''s father is involved with Mr. Ko, a Hong Kong drug kingpin, so the NYC police commissioner sends the two cops to Hong Kong to investigate.', '1985-06-15', 5.94, 'https://image.tmdb.org/t/p/w500/ri2yctGQr4DPLBODZZ2Ky2yqBoL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47608, 'Mad Love', 'Matt falls for Casey, the new girl in school. She''s fun-loving and eccentric, but there''s a darkness to her whimsy that Matt can''t begin to comprehend. When Casey attempts to commit suicide, her parents place her in a mental institution. Matt springs her out, and together the young lovers head on a road trip. They believe their love can "cure" Casey''s problems. Matt starts to wonder, though, if are they inspired or misguided.', '1995-05-26', 5.18, 'https://image.tmdb.org/t/p/w500/glhctWoYw1jg8z0FUSwFD4UTNi4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47653, 'The Immigrant', 'A European immigrant endures a challenging voyage only to get into trouble as soon as he arrives in New York.', '1917-06-17', 7.27, 'https://image.tmdb.org/t/p/w500/dbBrtc3mPCEVUIv8QKMcMcaOiZ1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47596, 'Let It Snow', 'Two young lovers meet on a series of snowy days in high school.', '1999-10-01', 4.57, 'https://image.tmdb.org/t/p/w500/4BcnaOBwXifEXF9NRXo9ERdE2KE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46785, 'The White Balloon', 'Several people try to take advantage of a little girl''s innocence to hustle money her mom gave to her to buy a goldfish with.', '1995-01-02', 7.48, 'https://image.tmdb.org/t/p/w500/bamJR4MwtQDMdWkjVAPojfwOjY4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47676, 'Bodies, Rest & Motion', 'Rebelling against his dreary life in a small Arizona town, salesman Nick abandons his girlfriend, Beth, and strikes out onto the highway in search of... something else. Encouraged by her best friend, Carol, Beth reluctantly accepts the romantic attentions of Sid, a local housepainter.', '1993-04-09', 5.71, 'https://image.tmdb.org/t/p/w500/46HAxDyb5Xqljse9Ata9ftqOxbK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47684, 'Man of Aran', 'A documentary on the life of the people of  the Aran Islands, who were believed to contain the essence of the ancient Irish life, represented by a pure uncorrupted peasant existence centred around the struggle between man and his hostile but magnificent surroundings. A blend of documentary and fictional narrative, the film captures the everyday trials of life on Ireland''s unforgiving Aran Islands.', '1934-05-06', 7.30, 'https://image.tmdb.org/t/p/w500/A67tl48MWZM8bxEYxJZhFGGth9A.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47692, 'Felicia''s Journey', 'Seventeen and pregnant, Felicia travels to England in search of her lover and is found instead by Joseph Ambrose Hilditch, a helpful catering manager whose kindness masks an unsettling secret.', '1999-10-08', 6.31, 'https://image.tmdb.org/t/p/w500/itqEwiINuYvaqvFKw5YWitnqAUc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46503, 'All Good Things', 'Newly-discovered facts, court records and speculation are used to elaborate the true love story and murder mystery of the most notorious unsolved murder case in New York history.', '2010-12-03', 6.06, 'https://image.tmdb.org/t/p/w500/3RM8SyB0yHanJbYeHdgi5eLv21C.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46529, 'I Am Number Four', 'A teenage fugitive with an incredible secret races to stay one step ahead of the mysterious forces seeking destroy him. With three dead and one on the run, the race to find the elusive Number Four begins. Outwardly normal teen John Smith never gets too comfortable in the same identity, and along with his guardian, Henri, he is constantly moving from town to town. With each passing day, John gains a stronger grasp on his extraordinary new powers, and his bond to the beings that share his fantastic fate grows stronger.', '2011-02-18', 6.21, 'https://image.tmdb.org/t/p/w500/2NrP3h3GEsrPXX60bmjKuYWAvl9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46797, 'Tom & Viv', 'The story of the marriage of the poet T. S. Eliot to socialite Vivienne Haigh-Wood, which had to cope with her gynaecological and emotional problems and his growing fame.', '1994-04-15', 6.12, 'https://image.tmdb.org/t/p/w500/iw4ofGbX2AbJ4p17CixwnMjuoJ0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47295, 'Better Living Through Circuitry', 'A documentary about rave culture and the Electronic Dance movement of the ''90s. It is the first such full-length documentary on the topic. It was produced by Cleopatra Pictures and Entertainment Group, presided by Cleopatra Records founder Brian Perera. The film features interviews with BT, The Crystal Method, Electric Skychurch, Genesis P-Orridge, Frankie Bones, DJ Spooky, Roni Size, and DJ Keoki.', '1999-08-14', 5.80, 'https://image.tmdb.org/t/p/w500/3UUdjElayMyi6pSYq6SBLBRIKvG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47762, 'Scenes from a Mall', 'A comedy about a married couple -- he''s a sports lawyer, she''s a psychologist -- which takes place on their 16th wedding anniversary, when they make some startling confessions.', '1991-02-22', 5.18, 'https://image.tmdb.org/t/p/w500/roF5MQlNBFSV0K3s9ThBPIBglO5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47817, '1969', 'Two rebellious youths, Ralph and Scott, find themselves struggling with adulthood as the Vietnam War rages. Feeling trapped in their small town, Scott battles with his conservative veteran father, Cliff, and Ralph deals with his desperately sexual mother, Ev. When tragic news arrives from overseas, the entire town, inspired by Ralph and Scott''s antiwar efforts, reevaluates its attitude toward the war.', '1988-08-18', 5.61, 'https://image.tmdb.org/t/p/w500/lM8B5gsF28UNKMJY3ZVSkpy5Ie.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47819, 'Americathon', 'In a story told in narrative flashbacks, a young TV consultant is hired by the President of a bankrupt USA to organize a telethon in order to prevent the country from being repossessed by wealthy Native Americans.', '1979-08-10', 3.60, 'https://image.tmdb.org/t/p/w500/1GlEFedxZecTLRkl0Naesikn4KR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47818, 'A Night in the Life of Jimmy Reardon', 'A recent high school graduate is faced with two options, either go to a business school where his father wants him to go to, or get a full time job. However he decides to defy his father and go to Hawaii. Trouble is he has no money. Along the way he comes to understand his parents and eventually bonds with his father.', '1988-02-26', 5.01, 'https://image.tmdb.org/t/p/w500/2hBR9hq45QvMnTD9via4duMhyDi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47423, 'Once a Thief', 'Three orphans grow up to become art thieves under the tutelage of a crime boss. Romance complicates matters when the trio are double-crossed.', '1991-02-02', 6.85, 'https://image.tmdb.org/t/p/w500/xCm4qIID3oyhBxRNKsYo3TpDivF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47850, 'Orchestra Rehearsal', 'An orchestra assembles for a rehearsal in an ancient chapel under the inquisitive eyes of a TV documentary crew, but an uprising breaks out.', '1979-02-22', 6.64, 'https://image.tmdb.org/t/p/w500/rtspkCHNKoDJxJnozzfoPY1qAct.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47866, 'Gas Food Lodging', 'Nora, a single mother raising two teenage daughters, Shade and Trudi, waits tables at a truck-stop diner in a small New Mexico town. The beautiful and rebellious Trudi drops out of school and gets a job alongside Nora, while the younger Shade whittles away her time at Spanish movie matinees. Their lives are turned upside down when Trudi becomes pregnant and the girls'' absent father returns.', '1992-07-10', 6.30, 'https://image.tmdb.org/t/p/w500/4klEYvGDHmv89NQRfAaDc8qHncs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47867, 'Gordy', 'A talking pig named Gordy becomes involved in a quest to save his family from the slaughterhouse.', '1995-05-12', 5.37, 'https://image.tmdb.org/t/p/w500/4sLmghaiAIYXh320qCvZWY4avVT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47697, 'Othello', 'Manipulated by his jealous ensign Iago, the Moorish general Othello is driven to believe that his new wife Desdemona is unfaithful, setting in motion a chain of deception, jealousy, and violence that leads to tragedy.', '1951-11-28', 7.39, 'https://image.tmdb.org/t/p/w500/61A7EJqfMsrQO0YWsUWq8gbgbu0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47907, 'The Spitfire Grill', 'Percy, upon being released from prison, goes to the small town of Gillead, to find a place where she can start over again. She is taken in by Hannah, to help out at her place, the Spitfire Grill. Percy brings change to the small town, stirring resentment and fear in some, and growth in others.', '1996-08-23', 6.48, 'https://image.tmdb.org/t/p/w500/dXxsqE22C6X72O1g8abO3kSIkpy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47889, 'Ruby in Paradise', 'Reeling from her mother''s recent death, Ruby Lee Gissing relocates to Florida to start anew. After finding a job at a souvenir store, Ruby becomes friends with the shop''s owner, Mildred Chambers, and slowly acclimates to her new surroundings. Before long, she''s juggling the affections of Mildred''s Lothario son, Ricky, and the good-natured Mike. As she wavers between Ricky and Mike, Ruby also tries to come to terms with her past.', '1993-10-08', 5.97, 'https://image.tmdb.org/t/p/w500/gk0vbIVYwpXxSf1wQbS2r9IsBoV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47881, 'My Giant', 'Sammy, an agitated agent lost in the forest of the modern world, happens upon a gentle giant with a tall talent for friendship named Max.', '1998-04-10', 5.37, 'https://image.tmdb.org/t/p/w500/49ylsG7JJFjNRlKTOdMQTgcI7om.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47876, 'Little Miss Marker', 'Sorrowful Jones is a cheap bookie in the 1930s. When a gambler leaves his daughter as a marker for a bet, he gets stuck with her. His life changes a great deal with her arrival and he finds sudden love for a woman also involved in gambling operations.', '1980-03-21', 6.60, 'https://image.tmdb.org/t/p/w500/clqmOwegCW2YeIxxl6Aoo1omQMq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46528, 'The Warrior''s Way', 'A warrior-assassin is forced to hide in a small town in the American Badlands after refusing a mission.', '2010-12-01', 6.61, 'https://image.tmdb.org/t/p/w500/otjBqNDpZ3C9mzfDOI4kaiib3Qd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47694, 'Temptress Moon', 'Set in the decadent 1920s, Temptress Moon tells the very complicated story of a wealthy family living on the outskirts of Shanghai. Their youngest daughter, Ruyi, is brought up as a servant to her opium-addicted father and brother. Meanwhile, her brother-in-law Zhongliang has a successful, if illegal, career seducing and blackmailing married women in the city. When he comes to Ruyi''s home the two fall in love, and trouble ensues.', '1996-05-09', 6.70, 'https://image.tmdb.org/t/p/w500/48KhZT4wwioPjAYz2LwX8nXt4UN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47939, 'Three Wishes', 'While Jane Holman is driving with her two sons, she accidentally runs into a drifter, Jack McCloud, who breaks his leg. Being responsible, Jane invites Jack, and his dog, to stay at her home until his leg has healed. Jack struggles to adapt their lifestyle, and finds himself loved by the family.', '1995-10-27', 6.21, 'https://image.tmdb.org/t/p/w500/8uzNbDH1b90DTsy38NPLqVIVpAH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47908, 'The Trip to Bountiful', 'Carrie Watts is living the twilight of her life trapped in an apartment in 1940s Houston, Texas with a controlling daughter-in-law and a hen-pecked son. Her fondest wish – just once before she dies – is to revisit Bountiful, the small Texas town of her youth which she still refers to as "home."', '1985-12-20', 7.20, 'https://image.tmdb.org/t/p/w500/qJ6A6fvp8PLFxxLVPLveFUmTOCG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47933, 'Independence Day: Resurgence', 'We always knew they were coming back. Using recovered alien technology, the nations of Earth have collaborated on an immense defense program to protect the planet. But nothing can prepare us for the aliens’ advanced and unprecedented force. Only the ingenuity of a few brave men and women can bring our world back from the brink of extinction.', '2016-06-22', 5.37, 'https://image.tmdb.org/t/p/w500/9S50foUIYGwiNPWOxi1WJF6IPwI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47941, 'Under the Rainbow', 'In World War II era Los Angeles, the manager of the Culver Hotel leaves his nephew in charge for a weekend. The nephew changes the name to the Hotel Rainbow and overbooks with royalty, assassins, secret agents, Japanese tourists, and munchkins. Secret Service agent Bruce Thorpe and casting director Annie Clark find romance amidst the intrigue and confusion.', '1981-07-31', 5.10, 'https://image.tmdb.org/t/p/w500/mCdXzpghn4tPz6hbQcvS2UwOh1C.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47931, 'Elite Squad: The Enemy Within', 'After a bloody invasion of the BOPE in the High-Security Penitentiary Bangu 1 in Rio de Janeiro to control a rebellion of interns, the Lieutenant-Colonel Roberto Nascimento and the second in command Captain André Matias are accused by the Human Right Aids member Diogo Fraga of execution of prisoners. Matias is transferred to the corrupted Military Police and Nascimento is exonerated from the BOPE by the Governor.', '2010-10-08', 7.85, 'https://image.tmdb.org/t/p/w500/c7yCrf3PTSdp6RMGktZQhzFcFFM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47943, 'With a Friend Like Harry...', 'While fixing up their summer cottage, Michel and his family run into a man who claims to have gone to high school with Michel.', '2000-08-15', 6.81, 'https://image.tmdb.org/t/p/w500/tQ6Ut3kPOpo3lRhPrW5QfkBDwGk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47955, 'White Dog', 'Samuel Fuller’s throat-grabbing exposé on American racism was misunderstood and withheld from release when it was made in the early eighties.Today, the notorious film is lauded for its daring metaphor and gripping pulp filmmaking. Kristy McNichol stars as a young actress who adopts a lost German shepherd, only to discover through a series of horrifying incidents that the dog has been trained to attack black people, and Paul Winfield plays the animal trainer who tries to cure him. A snarling, uncompromising vision, White Dog is a tragic portrait of the evil done by that most corruptible of all animals; the human being.', '1982-07-07', 6.61, 'https://image.tmdb.org/t/p/w500/2oU700G9pDwFt7px5GxOqDHFPfR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47951, 'The Adventures of Milo and Otis', 'When Milo the cat and Otis the dog are separated, they each set off on an adventurous and often perilous quest across mountains, plains, and snow-covered lands to reunite with one another.', '1986-06-27', 6.52, 'https://image.tmdb.org/t/p/w500/imHIqEfWRZuJ2vLow0UJ9aqjyEO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47947, 'Young Doctors in Love', 'An ''Airplane!''-style spoof of hospital soap operas—a brilliant young trainee can''t stand the sight of blood; a doctor romances the head nurse in order to get the key to the drugs cabinet; and there''s a mafioso on the loose disguised as a woman.', '1982-07-16', 5.30, 'https://image.tmdb.org/t/p/w500/9JTPSVDEFilY09hqtWPHrCDFneV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47959, 'Callas Forever', 'Aging opera singer Maria Callas tries to make a comeback by performing in a production of Bizet''s "Carmen."', '2002-09-18', 6.50, 'https://image.tmdb.org/t/p/w500/oDtTHHmwZPDI9f9NQJ7NS5GAli0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47979, 'Vincent Wants to Sea', 'Vincent, a young man who suffers from Tourette''s syndrome, has just lost his mother. His father, a successful politician, does not want to take care of him and therefore places him into a mental institution. He is put into a room with Alexander, a guy with a compulsive disorder, and is shown around by Marie, an anorectic girl.', '2010-04-21', 6.72, 'https://image.tmdb.org/t/p/w500/lGJUOYiOLrhk4p9SmQNT6qIX155.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47964, 'A Good Day to Die Hard', 'Iconoclastic, take-no-prisoners cop John McClane, finds himself for the first time on foreign soil after traveling to Moscow to help his wayward son Jack - unaware that Jack is really a highly-trained CIA operative out to stop a nuclear weapons heist. With the Russian underworld in pursuit, and battling a countdown to war, the two McClanes discover that their opposing methods make them unstoppable heroes.', '2013-02-06', 5.33, 'https://image.tmdb.org/t/p/w500/qJ0csDXAVFMsNn0cRcjy6W6PxAK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48132, 'Kevin Smith: Too Fat For 40', 'Poking fun at his much-publicized brouhaha with Southwest Airlines, writer, director, actor and ardent podcaster Kevin Smith declares himself too fat for his 40th birthday in a hilarious Q-and-A session with his rabidly loyal fans. Filmed at the Count Basie Theater in Smith''s hometown of Red Bank, New Jersey, this two-hour comedy special spotlights not only Smith''s self-deprecating sense of humor, but also his fondness (and true gift) for spinning a good yarn.', '2010-10-22', 6.50, 'https://image.tmdb.org/t/p/w500/6pyliHh44dOQM476EnSGuuP4Fht.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46702, 'Why Do Fools Fall In Love', 'In the mid-80s, three women (each with an attorney) arrive at the office of New York entertainment manager, Morris Levy. One is an L.A. singer, formerly of the Platters; one is a petty thief from Philly; one teaches school in a small Georgia town. Each claims to be the widow of long-dead doo-wop singer-songwriter Frankie Lyman, and each wants years of royalties due to his estate, money Levy has never shared. During an ensuing civil trial, flashbacks tell the story of each one''s life with Lyman, a boyish, high-pitched, dynamic performer, lost to heroin. Slowly, the three wives establish their own bond.', '1998-08-28', 6.39, 'https://image.tmdb.org/t/p/w500/tSj2g6VdJ2UXeWk9wRa19SsxRFg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47715, 'Intervista', 'Federico Fellini welcomes us into his world of film making with a mockumentary about his life in film, as a Japanese film crew follows him around.', '1987-10-01', 6.77, 'https://image.tmdb.org/t/p/w500/laP2XdPEPrpTgv0ZjS8c9f47X2t.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47449, 'Denise Calls Up', 'A group of friends in New York, working away at their PCs and laptops, keep in touch exclusively by phone and fax. They are all too busy to meet face to face. Gale plays matchmaker, by phone, to Jerry and Barbara who, in turn, hit it off beautifully – via phone and fax. Martin gets a telephone call from someone he''s never met. It''s Denise, with some extraordinary news. Tapping away at his computer all the while, he develops a sort of friendship with Denise – via phone. And so it goes as the friends, tap, tap, tapping away, share news, hopes, and dreams – via phone and fax. Finally Gale has an unfortunate encounter with a phone, Denise has some more news for Martin, and Frank plans a gala New Year''s Eve party, but will he answer the door?', '1995-05-17', 6.00, 'https://image.tmdb.org/t/p/w500/ab8iYcRfEAFwzcrkYP8tJBISX1E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46738, 'Incendies', 'A mother''s last wishes send twins Jeanne and Simon on a journey to Middle East in search of their tangled roots. Adapted from Wajdi Mouawad''s acclaimed play, Incendies tells the powerful and moving tale of two young adults'' voyage to the core of deep-rooted hatred, never-ending wars and enduring love.', '2010-09-17', 8.10, 'https://image.tmdb.org/t/p/w500/yH6DAQVgbyj72S66gN4WWVoTjuf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47759, 'The Monkey King: Uproar in Heaven', 'Sun Wukong, the King of the Monkeys, sets off on his first adventure to gain a worthy weapon. This earns the attention of the Jade Emperor of Heaven.', '1961-07-25', 7.75, 'https://image.tmdb.org/t/p/w500/vBHI9QjQyCyJP7EtqoGweahTU8S.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46632, 'Long Live Ghosts!', 'A trespassing gang of boys encounter a ghost in the ruins of a castle. When they rescue the ghost who is caught in a trapset, they become allies in a fight to prevent ruins from being turned into mushroom farm by the city authorities.', '1977-11-11', 7.07, 'https://image.tmdb.org/t/p/w500/kHSWQuSh846LTNykbatsp6No2Nu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48129, 'Run', 'When a law student accidentally kills the son of a mob boss in a fight, he finds himself relentlessly pursued by the mob and the police.', '1991-02-01', 6.02, 'https://image.tmdb.org/t/p/w500/w4sxXgXpALEDFexRZE9cb3j8bb2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48213, 'The Ogre', 'Frenchman Abel Tiffauges is a naive man who lives a simple life working as a mechanic. Falsely accused of being a child abuser, he is recruited as a soldier when World War II begins, but is captured soon and taken to the heart of Nazi Germany.', '1996-09-12', 6.40, 'https://image.tmdb.org/t/p/w500/ybLzxBiB9qiiqyANLj8RGs2Dkp3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47452, 'Love and Death on Long Island', 'Curmudgeonly author Giles De''Ath, a widower with a marked distaste for modern popular culture, attempts to buy a ticket for a film adaptation of an E.M. Forster novel, but instead finds himself watching a tacky teen sex comedy. Yet when the beautiful Ronnie Bostock appears on the movie screen, Giles finds himself caught in a whirlwind of unanswered questions about both his own sexuality and his place in late 20th-century society.', '1998-03-06', 6.31, 'https://image.tmdb.org/t/p/w500/2jCmP9j43QXy48oQFpzM4oaYRc7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48035, 'Ordet', 'The three sons of devout Danish farmer Morten have widely disparate religious beliefs. Youngest son Anders shares his father''s religion, but eldest son Mikkel has lost his faith, while middle child Johannes has become delusional and proclaims that he is Jesus Christ himself. When Mikkel''s wife, Inger goes into a difficult childbirth, everyone''s beliefs are put to the test.', '1955-01-09', 7.90, 'https://image.tmdb.org/t/p/w500/c9Oef9uQEuadZlnvv8hphRmTIgx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46705, 'Blue Valentine', 'Dean and Cindy live a quiet life in a modest neighborhood. They appear to have the world at their feet at the outset of the relationship. However, his lack of ambition and her retreat into self-absorption cause potentially irreversible cracks in their marriage.', '2010-12-26', 6.97, 'https://image.tmdb.org/t/p/w500/dc8BdKnDY5Iy28KzUGtHIXuqqFK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48138, 'Unknown', 'A man awakens from a coma, only to discover that someone has taken on his identity and that no one, (not even his wife), believes him. With the help of a young woman, he sets out to prove who he is.', '2011-02-16', 6.69, 'https://image.tmdb.org/t/p/w500/aXBQD515okXQZmYA89ntXMvSJSd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46774, 'Chapayev', 'An account of the peasant turned mythical military hero Vasily Chapayev, charting his campaign in the Red Army during the Russian Civil War.', '1934-11-07', 5.88, 'https://image.tmdb.org/t/p/w500/va7mzdH8qu1qa5KYmWAczrTz5FA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46788, 'Trash Humpers', 'Follow a small group of elderly “Peeping Toms” through the shadows and margins of an unfamiliar world. Crudely documented by the participants themselves, we follow the debased and shocking actions of a group of true sociopaths the likes of which have never been seen before. Inhabiting a world of broken dreams and beyond the limits of morality, they crash against a torn and frayed America.', '2010-05-07', 5.20, 'https://image.tmdb.org/t/p/w500/sNMA5i8w6MsyTKPULhJuLUHB2Wd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (46829, 'Barney''s Version', 'The picaresque and touching story of the politically incorrect, fully lived life of the impulsive, irascible and fearlessly blunt Barney Panofsky.', '2010-10-26', 6.96, 'https://image.tmdb.org/t/p/w500/vdsSaFbBWl8N6RV2XJuPBFyKeV8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48217, 'The Widow of Saint-Pierre', 'In 1850, on the isolated French island of Saint-Pierre, a murder shocks the natives. Two fishermen are arrested. One of them, Louis Ollivier, dies in custody. The other, Neel Auguste, is sentenced to death by the guillotine. The island is so small that it has neither a guillotine nor an executioner. While those are sent for Auguste is placed under the supervision of an army Captain.', '2000-04-19', 6.61, 'https://image.tmdb.org/t/p/w500/dFQ2kQA9JlAIO0uL2KkrsmI4o2O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48395, 'Rare Exports: A Christmas Tale', 'Young Pietari lives with his reindeer-herding father in arctic Finland. On the eve of Christmas, a nearby excavation makes a frightening discovery and an evil Santa Claus is unleashed…', '2010-12-03', 6.21, 'https://image.tmdb.org/t/p/w500/jzaweEESl54ejxo3EE5uNL8lgTn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48463, 'Incident at Loch Ness', 'When renowned director Werner Herzog and fellow filmmaker Zak Penn set off to explore the legend of Scotland''s Loch Ness monster, they uncover much more than they bargained for. Unexplained sightings of the creature and chaos among the crew create an uneasy feeling that things aren''t what they seem.', '2004-12-17', 5.86, 'https://image.tmdb.org/t/p/w500/hsBmbcL4KiZerEwFJO4BHlvnbA8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48572, 'Red State', 'Set in Middle America, a group of teens receive an online invitation for sex, though they soon encounter Christian fundamentalists with a much more sinister agenda.', '2011-08-19', 6.04, 'https://image.tmdb.org/t/p/w500/mbukOgivZWGNAxEQVt4hLUVME2P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48585, 'Ward 13', 'After a car accident, Ben wakes up in hospital. Not knowing where he is or what is going on, he starts exploring the corridors...only to find that the staff don''t have his health in mind! The hapless patient must pull himself together and do everything he can to escape. It''s an action/horror/comedy — ending with the wheelchair chase from hell!', '2003-06-06', 7.70, 'https://image.tmdb.org/t/p/w500/mT505ts2fpLMzhBSlqUvxp9NxGG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48610, 'Bunny', 'Bunny, an elderly rabbit who uses a walker, is in her kitchen one night baking a cake. A pesky and persistent moth bangs about the kitchen. Nothing is what it seems.', '1998-11-02', 6.61, 'https://image.tmdb.org/t/p/w500/9CApdJg7tPwLMp2EJy7JudHWMYN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48660, 'The Kindred', 'Amanda''s deathbed request to her son, John, was for him to destroy all the lab notes etc. from her last experiment. She also blurts out he had a brother. At the funeral John meets Melissa, who claims to be his mother''s biggest fan. Together with some of John''s friends they go to Amanda''s house, but none are prepared for what they find there.', '1987-01-09', 6.06, 'https://image.tmdb.org/t/p/w500/bDMUr5IQWAwUpFZFFxltLuAIb7N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48650, 'Room in Rome', 'A hotel room in the center of Rome serves as the setting for Alba and Natasha, two sexy and recently acquainted women, to have a physical adventure that touches their very souls.', '2010-05-07', 6.41, 'https://image.tmdb.org/t/p/w500/w90ItYf9qagQKVEBr1uFxPomAtf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48677, 'Cloak & Dagger', 'Davey Osborne is an average 11-year-old boy with an overactive imagination. He spends his days playing video games and pretending to be a spy with his imaginary father-figure, Jack Flack - a substitute for his real father, who is struggling with the recent death of Davey''s mother. However, fantasy becomes reality for Davey after he witnesses the murder of an FBI agent, who in his dying breath, gives Davey a mysterious video game cartridge called Cloak & Dagger, which in actuality contains top-secret government information. With the help of his younger friend Kim, the tech savvy Morris, and even a little help from his fictional secret agent mentor, Davey must stay one step ahead of pursuers as he tries to survive a real-life game of espionage in the streets of San Antonio, Texas.', '1984-06-01', 6.37, 'https://image.tmdb.org/t/p/w500/v42bfxsJwujF8L892RXXqiYslZ1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48678, 'Falling Angels', 'The wickedly funny story of three sisters'' coming of age in a wildly dysfunctional family, set against the backdrop of the 60''s, free love, the Cold War, LSD and the dawn of feminism. Affectionately dubbed "Little Women on acid", this is a story about the destructive effects of secrecy and the bonds of duty between parents and their children.', '2003-11-13', 5.96, 'https://image.tmdb.org/t/p/w500/k4jG2E1C5ER9YQIEVIYhcIWyh5Q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48750, 'Les Miserables', 'In WWII France, poor and illiterate Henri Fortin is introduced to Victor Hugo''s classic novel Les Misérables and begins to see parallels between the book and his own life.', '1995-03-22', 6.65, 'https://image.tmdb.org/t/p/w500/toQ6BJCiKVSnklpsma2GnJ6KKah.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48686, 'Assassination', 'Jay Killon is the bodyguard of the recently elected US president, but he is assigned to the first lady (Lara Royce). Lara hates Killon so she does all she can to escape. The story complicates when someone tries to kill Lara.', '1987-01-09', 5.62, 'https://image.tmdb.org/t/p/w500/5wGAfVATbWAL6g91XMnMZeMKz5F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48787, 'Mute Witness', 'When a mute makeup/special effects artist working on a low-budget slasher film gets locked in a dilapidated Moscow movie studio late one night, she thinks she witnesses the making of a snuff film. Thus begins a night of terror.', '1995-09-15', 6.50, 'https://image.tmdb.org/t/p/w500/kfCIZNpb2bWspnQNkIQftQlksCU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48834, 'Liam', 'A morality tale of xenophobia, religious prejudice, mob violence, poverty, and their effect on two children in Liverpool during the Depression. When a shipyard closes, Liam and Teresa''s dad loses his job. Liam, who''s about 8, making his first Holy Communion, gets a regular dose of fire and brimstone at church. Teresa, about 13, has a job as a maid to the Jewish family that owns the closed shipyard. The lady of that house is having an affair, and Teresa becomes an accomplice. Liam stutters terribly, especially when troubled. Dad comes under the sway of the Fascists, who blame cheap Irish labor and Jewish owners. A Molotov cocktail brings things to a head.', '2001-01-23', 6.30, 'https://image.tmdb.org/t/p/w500/asM4LPB6VYUXxifG3jgUk5rPHwH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48874, 'A Flintstones Christmas Carol', 'Fred is cast as Ebenezer Scrooge in a stage adaption of the classic Christmas story, but is acting a bit stingy in real life.', '1994-11-24', 6.81, 'https://image.tmdb.org/t/p/w500/e0KbZdRvxuki9nrXqRtpkgcj3Vt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48838, 'London Boulevard', 'A parolee falls for a reclusive movie star while trying to evade a ruthless gangster.', '2010-11-10', 5.89, 'https://image.tmdb.org/t/p/w500/naQKmThKMtlur92CDgCP6b9aoQE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48988, 'Hall Pass', 'When best buds Rick and Fred begin to show signs of restlessness at home, their wives take a bold approach to revitalize their marriages, they grant the guys a ''hall pass''—one week of freedom to do whatever they want. At first, it seems like a dream come true, but they quickly discover that their expectations of the single life—and themselves—are completely and hilariously out of sync with reality.', '2011-02-25', 5.75, 'https://image.tmdb.org/t/p/w500/eol3uD6whQKOKCmmhF7z39fq2Pe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48992, 'I Like It Like That', 'After her husband is arrested for looting, Lisette struggles for independence while dealing with her transgender sibling, her critical mother-in-law and assorted neighborhood eccentrics.', '1994-10-14', 6.26, 'https://image.tmdb.org/t/p/w500/aCxh21UPLHi7Pxm9ykH1GNx39OW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49010, 'Hobo with a Shotgun', 'A vigilante homeless man pulls into a new city and finds himself trapped in urban chaos, a city where crime rules and where the city''s crime boss reigns. Seeing an urban landscape filled with armed robbers, corrupt cops, abused prostitutes and even a pedophile Santa, the Hobo goes about bringing justice to the city the best way he knows how - with a 20-gauge shotgun. Mayhem ensues when he tries to make things better for the future generation. Street justice will indeed prevail.', '2011-05-06', 5.90, 'https://image.tmdb.org/t/p/w500/xxMaO7VoN2BnZit79PedVHnTjcO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49009, 'The Way Back', 'A small band of multicultural convicts stages a daring escape from a WWII-era Siberian gulag, and embarks on a treacherous journey across five countries in a desperate race for freedom and survival.', '2010-11-22', 7.00, 'https://image.tmdb.org/t/p/w500/xQ6hxfpD5XQGJz0ekVle5zegam7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49012, 'Arthur', 'A drunken playboy stands to lose a wealthy inheritance when he falls for a woman that his family doesn''t like.', '2011-04-08', 5.56, 'https://image.tmdb.org/t/p/w500/foUTAJurvnbUoIUbnuUk5dyHx7M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49017, 'Dracula Untold', 'Vlad Tepes is a great hero, but when he learns the Sultan is preparing for battle and needs to form an army of 1,000 boys, he vows to find a way to protect his family. Vlad turns to dark forces in order to get the power to destroy his enemies and agrees to go from hero to monster as he''s turned into the mythological vampire, Dracula.', '2014-10-01', 6.46, 'https://image.tmdb.org/t/p/w500/m5h3NtZ2ZfryIHl1MvatmANvIqQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49013, 'Cars 2', 'Star race car Lightning McQueen and his pal Mater head overseas to compete in the World Grand Prix race. But the road to the championship becomes rocky as Mater gets caught up in an intriguing adventure of his own: international espionage.', '2011-06-11', 6.19, 'https://image.tmdb.org/t/p/w500/okIz1HyxeVOMzYwwHUjH2pHi74I.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49018, 'Insidious', 'A family discovers that dark spirits have invaded their home after their son inexplicably falls into an endless sleep. When they reach out to a professional for help, they learn things are a lot more personal than they thought.', '2011-03-31', 6.95, 'https://image.tmdb.org/t/p/w500/1egpmVXuXed58TH2UOnX1nATTrf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49020, 'Submarine', '15-year-old deep-thinking Welsh schoolboy Oliver Tate struggles to initiate and maintain a relationship with Jordana, his devilish, dark-haired classmate at their Swansea high school. As his parents'' marriage begins to fall apart, similar problems arise in his relationship with Jordana.', '2011-03-18', 7.36, 'https://image.tmdb.org/t/p/w500/nbzXX3CYtKUBrPeMcG7PVoLQHXB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49026, 'The Dark Knight Rises', 'Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent''s crimes to protect the late attorney''s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham''s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.', '2012-07-17', 7.80, 'https://image.tmdb.org/t/p/w500/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48259, 'Crimes of the Heart', 'Three sisters try to come to grips with the meaning of their mother''s suicide.', '1986-12-12', 6.10, 'https://image.tmdb.org/t/p/w500/lg8npIjYrO0f4UsuNwWwd1TQhW6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49040, 'The Bourne Legacy', 'New CIA operative Aaron Cross experiences life-or-death stakes that have been triggered by the previous actions of Jason Bourne.', '2012-08-08', 6.25, 'https://image.tmdb.org/t/p/w500/1aExL5DTGHj25ZfIC3dDwS84RWi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48150, 'A Heart in Winter', 'Beautiful violin virtuoso Camille has two obsessions: the music of Ravel, and a friend of her husband''s who crafts violins. But his heart seems to be as cold as her playing is passionate.', '1992-09-02', 7.27, 'https://image.tmdb.org/t/p/w500/nwYKkV2SbrAfZEFOfafnPYZiFr1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47533, 'Scooby-Doo! Curse of the Lake Monster', 'Scooby-Doo and the gang are on the case when a mysterious lake monster starts scaring the guests at a summer resort in Erie Point, where Fred, Daphne, Velma and Shaggy have taken on seasonal jobs to pay for a barn they accidentally burned down. But in addition to sneaking suspicions, there''s some romance in the air.', '2010-10-16', 6.15, 'https://image.tmdb.org/t/p/w500/q67pApjezoE8x2XE92MRMhcXr5P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48233, 'The Terrorist', 'A young female terrorist goes on a suicide assassination mission, but her resolve to complete it is put to the test.', '1998-09-12', 6.90, 'https://image.tmdb.org/t/p/w500/5h3Kuoi5dBdh99aSGr7D1tktXeY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48297, 'Invincible Shaolin', 'Three North Shaolin teachers are called on by the Manchus to teach their soldiers and are urged to challenge the current South Shaolin teachers. They defeat the South Shaolin teachers and, that night, the head general kills the South Shaolin teachers and blames their death on the North Shaolin teachers. The South Shaolin master sends more of his pupils, who are killed accidentally by the North Shaolin teachers. He finally sends two more of his students to train with old masters and trains one student himself with the goal of finally defeating the North Shaolin experts.', '1978-11-19', 6.46, 'https://image.tmdb.org/t/p/w500/gZ9KLwe4dKDWI0S83n0uk3nAG4D.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47714, 'The Stolen Children', 'Antonio, a policeman (carabiniere), has an order to take two children (Rosetta and her brother Luciano) from Milan to Sicily to an orphanage. Their mother has been arrested for forcing Rosetta (11 years old) to work as a prostitute. First the relation between Antonio and the children is tough, but it relaxes so they become temporary friends.', '1992-04-10', 7.63, 'https://image.tmdb.org/t/p/w500/fkFYNR4iCz5n1j5Drf0jejKmNVb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48231, 'A Dangerous Method', 'Seduced by the challenge of an impossible case, the driven Dr. Carl Jung takes the unbalanced yet beautiful Sabina Spielrein as his patient. Jung’s weapon is the method of his master, the renowned Sigmund Freud. Both men fall under Sabina’s spell.', '2011-09-30', 6.35, 'https://image.tmdb.org/t/p/w500/7TPYtzq9ABkfED1JB0tRASamL4z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49022, 'Something Borrowed', 'Though Rachel is a successful attorney and a loyal, generous friend, she is still single. After one drink too many at her 30th-birthday celebration, Rachel unexpectedly falls into bed with her longtime crush, Dex -- who happens to be engaged to her best friend, Darcy. Ramifications of the liaison threaten to destroy the women''s lifelong friendship, while Ethan, Rachel''s confidant, harbors a potentially explosive secret of his own.', '2011-05-05', 6.23, 'https://image.tmdb.org/t/p/w500/66VZu75VeLGc6tcAypqyGzWcPeN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49047, 'Gravity', 'Dr Ryan Stone, an engineer on her first space mission, and Matt Kowalski, an astronaut on his final expedition, have to survive in space after they are hit by debris while spacewalking.', '2013-10-03', 7.17, 'https://image.tmdb.org/t/p/w500/kZ2nZw8D681aphje8NJi8EfbL1U.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48300, 'Return of the One-Armed Swordsman', 'After the events of The One-Armed Swordsman (1967), a retired Fang Gang is drawn back into the jianghu to protect various young apprentices whose swordsmanship schools have been terrorized by 8 evil swordsmen seeking to rule the jianghu.', '1969-02-28', 6.60, 'https://image.tmdb.org/t/p/w500/qupi6LGWSMSTaZHWPYUyAyVplLx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (47724, 'Up at the Villa', 'Superficial people are revealed and drastically changed by circumstance or luck in this a tale of death, seduction, blackmail and theft among British and Americans in Florence in the turbulent days just before World War II.', '2000-04-14', 5.34, 'https://image.tmdb.org/t/p/w500/hkjBOhbNVCk6zbnC8Xo1cNYMmuA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48347, 'The Old Lady and the Pigeons', 'A starving gendarme, wasting away from hunger, is reduced to grabbing castoff snacks from fat American tourists. When he sees as old woman feeding pigeons, in desperation he hits on the bizarre idea of dressing up as one...', '1997-05-27', 7.66, 'https://image.tmdb.org/t/p/w500/cr9Qsgv2IoEnlbT12WGDEOxQW5G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48287, 'The Baby-Sitters Club', 'Seven junior-high-school girls organize a daycare camp for children while at the same time experiencing classic adolescent growing pains.', '1995-08-18', 5.45, 'https://image.tmdb.org/t/p/w500/cdICP1AzQPgBWsEHwKTZH9ziNyE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49453, 'Fast Food Fast Women', 'How important is the truth when falling in love? Bella is a Manhattan café waitress, about to turn 35, stuck in a long-term affair going nowhere. Paul is a widower, facing old age alone. Bella''s mother sets her up with Bruno, a novelist/cabbie who likes to bed-hop and whose ex-wife expects their two children to stay with him for awhile. While Bruno learns some maturity from his young daughter, Paul answers a personals ad placed by a "widow, 60." The two couples - along with one of Paul''s older pals and a Jungian stripper - sort out how to initiate a relationship these days, what to do when someone you like disappoints you, and when to tell the truth.', '2000-07-27', 6.25, 'https://image.tmdb.org/t/p/w500/bJuz51a3Whsh8mTRxXnaSzuXrRQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49021, 'Killer Elite', 'Based on a shocking true story, Killer Elite pits two of the world’s most elite operatives—Danny, an ex-special ops agent and Hunter, his longtime mentor—against the cunning leader of a secret military society. Covering the globe from Australia to Paris, London and the Middle East, Danny and Hunter are plunged into a highly dangerous game of cat and mouse—where the predators become the prey.', '2011-09-22', 6.27, 'https://image.tmdb.org/t/p/w500/7O2U0WPFPSvNSUYZlhbnV081lBF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49462, 'Career Girls', 'A young college student in London moves into a flat and becomes best friends with a flatmate; the former moves into her own flat 4 years later but 6 years after their parting, the former returns to London to pay the latter a visit.', '1997-06-01', 6.60, 'https://image.tmdb.org/t/p/w500/bV6ezK5Qcqv9ul9B6yGiKcfA0pG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49471, 'Get on the Bus', 'Fifteen Black men gather in South Central LA to take a cross-country bus trip to attend the Million Man March in Washington, DC in October 1995. Among the attendees are an eclectic set of characters, including a laid-off aircraft worker, a man whose at-risk son is handcuffed to him, a Black Republican, a former gangsta, a Hollywood actor, a cop of mixed racial background, and a white bus driver. All make the trek discussing issues surrounding the March, including manhood, religion, politics, sexuality, and race.', '1996-10-16', 6.38, 'https://image.tmdb.org/t/p/w500/7p8FvHMSr11LQw9Xv6dPJdrBeU2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49051, 'The Hobbit: An Unexpected Journey', 'Bilbo Baggins, a hobbit enjoying his quiet life, is swept into an epic quest by Gandalf the Grey and thirteen dwarves who seek to reclaim their mountain home from Smaug, the dragon.', '2012-12-12', 7.38, 'https://image.tmdb.org/t/p/w500/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49494, 'The Eagle', 'In 140 AD, twenty years after the unexplained disappearance of the entire Ninth Legion in the mountains of Scotland, young centurion Marcus Aquila arrives from Rome to solve the mystery and restore the reputation of his father, the commander of the Ninth. Accompanied only by his British slave Esca, Marcus sets out across Hadrian''s Wall into the uncharted highlands of Caledonia - to confront its savage tribes, make peace with his father''s memory, and retrieve the lost legion''s golden emblem, the Eagle of the Ninth.', '2011-02-08', 6.24, 'https://image.tmdb.org/t/p/w500/mbsdwO4lfIARqt35VVTM0UlYkhZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49517, 'Tinker Tailor Soldier Spy', 'George Smiley, the aging master spy of the Cold War and once heir apparent to Control, is brought back out of retirement to flush out a top level mole within the Circus. Smiley must travel back through his life and murky workings of the Circus to unravel the net spun by his nemesis Karla ''The Sandman'' of the KGB and reveal the identity of the mole before he disappears.', '2011-09-16', 6.62, 'https://image.tmdb.org/t/p/w500/e0dZ7TapGY9HtJ9xk1TUHPEOccl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49049, 'Dredd', 'In the future, America is a dystopian wasteland. The latest scourge is Ma-Ma, a prostitute-turned-drug pusher with a dangerous new drug and aims to take over the city. The only possibility of stopping her is an elite group of urban police called Judges, who combine the duties of judge, jury and executioner to deliver a brutal brand of swift justice. But even the top-ranking Judge, Dredd, discovers that taking down Ma-Ma isn’t as easy as it seems in this explosive adaptation of the hugely popular comic series.', '2012-09-07', 6.86, 'https://image.tmdb.org/t/p/w500/wLx65gtGVnUFCxceHWGszcruCZj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49519, 'The Croods', 'The prehistoric Croods family live in a particularly dangerous moment in time. Patriarch Grug, his mate Ugga, teenage daughter Eep, son Thunk, and feisty Gran gather food by day and huddle together in a cave at night. When a more evolved caveman named Guy arrives on the scene, Grug is distrustful, but it soon becomes apparent that Guy is correct about the impending destruction of their world.', '2013-03-15', 6.95, 'https://image.tmdb.org/t/p/w500/27zvjVOtOi5ped1HSlJKNsKXkFH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49520, 'The Change-Up', 'Lifelong friends Dave and Mitch are envious of the other''s life. Mitch thinks Dave has it all: a beautiful, loving family and a high-paying job at a prestigious law firm. But Dave thinks Mitch’s stress-free playboy life without obligation or consequence is the real dream come true. One fateful drunken night, they both admit that they wish they had the other’s life while peeing in a fountain when lightning strikes. The next morning, they wake up, hungover, in each other’s bodies! With time not on their side, Mitch and Dave comically struggle to avoid completely destroying each other’s lives before they can find a way to get their old ones back.', '2011-08-05', 6.16, 'https://image.tmdb.org/t/p/w500/iV6ARQZyGpjygtzFMdWH9U1Lj9x.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49521, 'Man of Steel', 'A young boy learns that he has extraordinary powers and is not of this earth. As a young man, he journeys to discover where he came from and what he was sent here to do. But the hero in him must emerge if he is to save the world from annihilation and become the symbol of hope for all mankind.', '2013-06-12', 6.66, 'https://image.tmdb.org/t/p/w500/8GFtkImmK0K1VaUChR0n9O61CFU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49524, 'R.I.P.D.', 'A recently slain cop joins a team of undead police officers working for the Rest in Peace Department and tries to find the man who murdered him.', '2013-07-18', 5.86, 'https://image.tmdb.org/t/p/w500/rS0kByPD4YF8pQ85KjzMdGiu7Xf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49527, 'Man on a Ledge', 'An ex-cop turned con threatens to jump to his death from a Manhattan hotel rooftop. The NYPD dispatch a female police psychologist to talk him down. However, unbeknownst to the police on the scene, the suicide attempt is a cover for the biggest diamond heist ever pulled.', '2012-01-13', 6.44, 'https://image.tmdb.org/t/p/w500/pziTpiYy5dtVdvXctYIZv09r5Nk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49529, 'John Carter', 'John Carter is a war-weary, former military captain who''s inexplicably transported to the mysterious and exotic planet of Barsoom (Mars) and reluctantly becomes embroiled in an epic conflict. It''s a world on the brink of collapse, and Carter rediscovers his humanity when he realizes the survival of Barsoom and its people rests in his hands.', '2012-03-07', 6.38, 'https://image.tmdb.org/t/p/w500/lCxz1Yus07QCQQCb6I0Dr3Lmqpx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49526, 'Premium Rush', 'In Manhattan, a bike messenger picks up an envelope that attracts the interest of a dirty cop, who pursues the cyclist throughout the city.', '2012-08-24', 6.36, 'https://image.tmdb.org/t/p/w500/gHnGhJmE0LByOd4RS2mOASmUqQu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49530, 'In Time', 'In the not-too-distant future, the aging gene has been switched off. To avoid overpopulation, time has become the currency and the way people pay for luxuries and necessities. The rich can live forever, while the rest struggle to negotiate for their immortality. A poor young man who suddenly comes into a fortune of time finds himself on the run from a corrupt police force known as the "time keepers".', '2011-10-27', 6.97, 'https://image.tmdb.org/t/p/w500/3Mwj2sIONQckOZP3YwsUXF7U5I4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49538, 'X-Men: First Class', 'Before Charles Xavier and Erik Lensherr took the names Professor X and Magneto, they were two young men discovering their powers for the first time. Before they were arch-enemies, they were closest of friends, working together with other mutants (some familiar, some new), to stop the greatest threat the world has ever known.', '2011-06-01', 7.30, 'https://image.tmdb.org/t/p/w500/hNEokmUke0dazoBhttFN0o3L7Xv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49565, 'The Man Who Planted Trees', 'The story of one shepherd''s single-handed quest to re-forest a desolate valley in the foothills of the French Alps throughout the first half of the 20th century.', '1987-05-13', 7.98, 'https://image.tmdb.org/t/p/w500/tEzdXghDipM4b8Qs1mzt4mvXT6l.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49680, 'Late Marriage', 'Zaza is a 31-year old Israeli bachelor, handsome and intelligent, and his family wants to see him married. But tradition dictates that Zaza has to choose a young virgin. She must be beautiful and from a good family, preferably rich. Zaza''s parents, Yasha and Lily drag Zaza to meet potential brides and their families. Zaza has no choice. He plays along with his family, advocates of the suffocating traditions of their Georgian Jewish heritage. But Zaza always manages to somehow get out of being engaged. What his parents don''t know is that Zaza is already in love. Judith is sensuous, strong and intriguing. She''s also a divorcée with a 6-year-old daughter. So Zaza has kept Judith a secret from his family. He will have to choose between respect of the strict confines of family and tradition, or the love of his life.', '2001-10-24', 6.30, 'https://image.tmdb.org/t/p/w500/9IcQsfhjfQamVvRgtpYkwdIKilw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49636, 'Master of the Flying Guillotine', 'A one-armed martial arts master is being stalked by an Imperial assassin, the master of two fighters  killed in the previous film. When the One-Armed Boxer is invited to attend a martial arts tournament, his efforts to lay low are unsuccessful, and the assassin soon tracks him down with the help of his three subordinates: a Thai boxer, a yoga master, and a kobojutsu user.', '1976-04-24', 6.70, 'https://image.tmdb.org/t/p/w500/upa8qI25kJrrQHgYz66IO2ccvoH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49689, 'Broken Wings', 'Daphne and her four children try to cope with the abrupt death of husband/father. As the family seems to fall apart, a sudden incident gives them a chance to heal their ''broken wings''.', '2002-10-24', 6.69, 'https://image.tmdb.org/t/p/w500/somDluLofBXeIu2y55mlG6Wc5JA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49721, 'Me Myself I', 'Pamela Drury is unhappy, and alone. On her birthday she stumbles across a photo of Robert Dickson, and wonders what would''ve happened had she said yes to his proposal. A freak accident causes Pamela to live out the life she could''ve had, but is the grass on the other side always greener?', '1999-10-06', 5.71, 'https://image.tmdb.org/t/p/w500/sI8AjPZMeRKn5mQ7LD4uYTStTMc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48289, 'The Debt', 'Rachel Singer is a former Mossad agent who tried to capture a notorious Nazi war criminal – the Surgeon of Birkenau – in a secret Israeli mission that ended with his death on the streets of East Berlin. Now, 30 years later, a man claiming to be the doctor has surfaced, and Rachel must return to Eastern Europe to uncover the truth. Overwhelmed by haunting memories of her younger self and her two fellow agents, the still-celebrated heroine must relive the trauma of those events and confront the debt she has incurred.', '2010-09-30', 6.55, 'https://image.tmdb.org/t/p/w500/zlavkPAIzIIQppcU9vcQrKZjfmb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49730, 'Red Riding Hood', 'Valerie is in love with a brooding outsider, Peter, but her parents have arranged for her to marry another man. Unwilling to lose each other, Valerie and Peter plan to run away together when Valerie''s older sister is killed by a werewolf that prowls the dark forest surrounding their village. Panic grips the town as Valerie discovers that she has a unique connection to the beast--one that inexorably draws them together, making her both suspect ... and bait.', '2011-03-10', 5.97, 'https://image.tmdb.org/t/p/w500/ixQYkLeLlTTnAoT32dukndyObB6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49797, 'I Saw the Devil', 'Kyung-chul is a dangerous psychopath who kills for pleasure. Soo-hyeon, a top-secret agent, decides to track down the murderer himself. He promises himself that he will do everything in his power to take vengeance against the killer, even if it means that he must become a monster himself.', '2010-08-12', 7.81, 'https://image.tmdb.org/t/p/w500/zp5NrmYp80axIGiEiYPmm1CW6uH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49806, 'The Daytrippers', 'Eliza D''Amico thinks her marriage to Louis is going great until she finds a mysterious love note to her husband. Concerned, she goes to her mother for advice. Eliza, her parents, her sister Jo, and Jo''s boyfriend all pile into the station wagon and go to the city to confront Louis with the letter. On the way, the five explore their relations with each other and meet many interesting people.', '1997-03-05', 6.62, 'https://image.tmdb.org/t/p/w500/bDmconT9Fj0dnXdV5LaGAxXrVFN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49809, 'Serving in Silence - The Margarethe Cammermeyer Story', 'After serving in the military for more than twenty years, including a tour of duty in Vietnam, Colonel Margarethe Cammermeyer (Glenn Close) had seen her share of battles. But nothing could prepare her for the fight ahead: an intensely personal struggle against the U.S. Army when she becomes the highest ranking officer ever to be discharged for being a lesbian. With the support of her partner Diane (Judy Davis), Cammermeyer undertakes an against-all-odds battle against the Army''s policy. But to do so, she must risk everything – her career, her privacy and even the love of her family.', '1995-01-23', 5.71, 'https://image.tmdb.org/t/p/w500/mHkVybbJ77ZNzEvsISQZypBSmE4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49849, 'Cowboys & Aliens', 'A stranger stumbles into the desert town of Absolution with no memory of his past and a futuristic shackle around his wrist. With the help of mysterious beauty Ella and the iron-fisted Colonel Dolarhyde, he finds himself leading an unlikely posse of cowboys, outlaws, and Apache warriors against a common enemy from beyond this world in an epic showdown for survival.', '2011-07-29', 5.70, 'https://image.tmdb.org/t/p/w500/9uZsGCP4rvOHVGCpMpYq5gNCuNI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49802, 'The Secret of the Third Planet', 'At the end of the 22nd century Alisa Seleznyova, her father Professor Seleznyov and pilot Zelyony go on a space expedition to find rare animals for Moscow Zoo. On the way they seem to encounter a mysterious conspiracy led by Doctor Verhovtsev against legendary Two Captains Kim and Buran. The only clue is a talking bird Сhatterer [Govorun] that our heroes accidentally took possession of.', '1981-07-31', 7.42, 'https://image.tmdb.org/t/p/w500/c34bVzr6akMEJ7j2yrzRfgPJlVO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49126, 'Audrey Rose', 'A man is convinced that 11-year old girl, Ivy, is the reincarnation of his own daughter Audrey Rose, who died in a fiery car accident, along with his wife, two minutes before Ivy was born.', '1977-04-06', 5.70, 'https://image.tmdb.org/t/p/w500/omtHuaCwKRX20x5R8xnqxWYq8Xp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49805, 'The Browning Version', 'Andrew Crocker-Harris is an embittered and disliked teacher of Greek and Latin at a British prep school. After nearly 20 years of service, he is being forced to retire for ''health reasons'', and perhaps may not even be given a pension. The boys regard him as a Hitler, with some justification. His unfaithful wife Laura tries to hurt him in any way she can. Andrew must come to terms with his failed life and at least regain his own self-esteem.', '1994-06-08', 6.35, 'https://image.tmdb.org/t/p/w500/8My9Wnzu1zasVVzGdDj5y2dItuM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49934, 'Do You Remember Dolly Bell?', 'Growing up in 1960s Sarajevo, a young man comes of age under the shadow of his good, but ailing father, but is attracted by the world of small-time criminals. He''s hired to hide a young prostitute, whom he falls in love with.', '1981-04-10', 7.38, 'https://image.tmdb.org/t/p/w500/mkH1PigvNINeYQxi07RsdzSuTDB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49943, 'Sisters', 'A movie about two sisters - thirteen year old Sveta, poor and abandoned by her father, who longs to go off and be a sniper in the army, and spoilt eight-year old Dina, doted on by her gangster father...', '2001-05-10', 6.79, 'https://image.tmdb.org/t/p/w500/5pWGgE8RbiaNm95PsdKd6YEOYHS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48303, 'Certified Copy', 'In Tuscany to promote his latest book, a middle-aged English writer meets a French woman who leads him to the village of Lucignano.', '2010-05-19', 7.01, 'https://image.tmdb.org/t/p/w500/soBvtCR33Gv1j6gXwXOIc3JTlNc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49037, 'Hellevator: The Bottled Fools', 'Luchino''s routine morning elevator ride up from her subterranean home on level 138 to her school many stories above turns horrific when the elevator operator is ordered to pick up two passengers from floor 99, the maximum security level. What starts as psychological manipulation soon turns wholly physical as both the cruel convicts and Luchino''s own dysfunctional past are unleashed. And then every passenger must fight for his or her survival.', '2004-02-28', 5.40, 'https://image.tmdb.org/t/p/w500/1dr7hmURza1r2Dxhit2wraeFkJX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49365, 'Lady in White', 'Locked in a school closet during Halloween 1962, young Frank witnesses the ghost of a young girl and the man who murdered her years ago.', '1988-04-22', 6.12, 'https://image.tmdb.org/t/p/w500/AevfLQ5c0ZGtO3clHawg9L2XAQ2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48311, 'Parasite', 'Paul Dean has created a deadly parasite that is now attached to his stomach. He and his female companion, Patricia Welles, must find a way to destroy it while also trying to avoid Ricus & his rednecks, and an evil government agent named Merchant.', '1982-03-12', 4.88, 'https://image.tmdb.org/t/p/w500/4DGPORlVIDIQvsuSDnM4uXKMjWS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50004, 'Paper Birds', 'At the end of the Spanish Civil War, the members of a group of vaudeville performers have been stripped of everything: all they have left is hunger and the instinct to survive. Day after day, agonizingly, lost and helpless between the victors and the vanquished, the musician Jorge, the ventriloquist Enrique, the couplet singer Rocío and the orphan Miguel search tirelessly for something to eat and a safe place to live.', '2010-03-12', 6.63, 'https://image.tmdb.org/t/p/w500/xgdLPEiHr4HqtNYuzBhmY9nE4Aa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49133, 'Lamerica', 'Fiore, an Italian conman, arrives in post Communist Albania with Gino, his young apprentice, to set up a shoe factory that will never open. The con requires a native Albanian, so they designate Spiro, an impoverished and confused former political prisoner as chairman of the board. When Fiore returns to Italy to get government funds for the project, Spiro unexpectedly disappears and Gino sets out on a journey to find him. The search leads him to discover Spiro''s tragic personal history and witness Albanian poverty firsthand.', '1994-09-09', 7.16, 'https://image.tmdb.org/t/p/w500/nnLpA4mqb3gvhNJQZ00cOyBmeq3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48365, 'Boudu Saved from Drowning', 'Michel Simon gives one of the most memorable performances in screen history as Boudu, a Parisian tramp who takes a suicidal plunge into the Seine and is rescued by a well-to-do bookseller, Edouard Lestingois. The Lestingois family decides to take in the irrepressible bum, and he shows his gratitude by shaking the household to its foundations. With Boudu Saved from Drowning, legendary director Jean Renoir takes advantage of a host of Parisian locations and the anarchic charms of his lead actor to create an effervescent satire of the bourgeoisie.', '1932-11-11', 6.94, 'https://image.tmdb.org/t/p/w500/hCRUtli9TCrekxSysHJ15QhMk44.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49314, 'Dominick and Eugene', 'Dominick and Eugene are twins, but Dominick is a little bit slow due do an accident in his youth. They live together, with Dominick working as garbage man to put Eugene through medical school. Their relationship becomes strained when Eugene must decide between his devotion to his brother, or his need to go away to complete his training. Things are also not helped by Dominick''s co-worker, or Eugene''s budding romance.', '1988-03-18', 6.85, 'https://image.tmdb.org/t/p/w500/uSxAr4qqJmLOZz3hhgGa54LShx5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50204, 'Burke & Hare', 'Two 19th-century opportunists become serial killers so that they can maintain their profitable business supplying cadavers to an anatomist.', '2010-10-29', 6.09, 'https://image.tmdb.org/t/p/w500/3VY3gKHPc9dRq8FshSXWbXtgD9B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50285, 'Siam Sunset', 'A British design executive, who seemingly has everything going for him has his life totally changed when a refrigerator falls from an aircraft and lands on his wife...', '1999-09-09', 6.14, 'https://image.tmdb.org/t/p/w500/iGFjTOA5DoU3uqzzjhYXsDHEHQS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49184, 'West Beirut', 'In 1975, the long slog of civil war has recently begun in Beirut. Two friends, Tarek and Omar, suffer during the Lebanese civil war. Conflicts arise when they decide to cross from West to East, crossing the Muslim-Christian line that divides Beirut.', '1998-10-30', 7.03, 'https://image.tmdb.org/t/p/w500/djx4ceoh6o5kdLKRuPsMULNWvDl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50314, 'My Architect: A Son''s Journey', 'World-famous architect Louis Kahn (Exeter Library, Salk Institute, Bangladeshi Capitol Building) had two illegitimate children with two different women outside of his marriage. Son Nathaniel always hoped that someday his father would come and live with him and his mother, but Kahn never left his wife. Instead, Kahn was found dead in a men''s room in Penn Station when Nathaniel was only 11.', '2003-11-12', 6.88, 'https://image.tmdb.org/t/p/w500/flpuP2Y2qUkVGghsOYkxj0HkgB9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50321, 'Mars Needs Moms', 'When Martians suddenly abduct his mom, mischievous Milo rushes to the rescue and discovers why all moms are so special.', '2011-03-09', 5.99, 'https://image.tmdb.org/t/p/w500/yZBrpe4bxwDIDKBxPeJYrlyDK5R.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50327, 'To Grandmother''s House We Go', 'When precocious twins Sarah and Julie feel like Mom is tired of them, they take off on an exciting adventure to their grandmother''s house and encounter a pair of villains along the way.', '1992-12-06', 6.49, 'https://image.tmdb.org/t/p/w500/muzQuNYEQfZEPIN7G5shtKKT3fP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50348, 'The Lincoln Lawyer', 'Mick Haller is a charismatic defense attorney who does business out of his Lincoln Continental sedan. Mick spends most of his time defending petty crooks and other bottom-feeders, so it comes as quite a surprise when he lands the case of a lifetime: defending a Beverly Hills playboy who is accused of attempted murder. However, what Mick initially thinks is an open-and-shut case with a big monetary reward develops into something more sinister.', '2011-03-17', 7.21, 'https://image.tmdb.org/t/p/w500/gOn8Ve9Yi8fxjRkmLr5BZoOc7KV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (48385, 'Indestructible Man', 'A scientific experiment involving subjecting a corpse to an extreme charge of electricity accidentally revives an executed criminal and makes him impervious to harm, allowing him to seek revenge on his former partners, and deal similarly with anyone else who gets in his way.', '1956-03-24', 4.37, 'https://image.tmdb.org/t/p/w500/kcD0kG86GK2mUHjNf6QoDfwtnxd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50350, 'And Now... Ladies and Gentlemen...', 'A jazz singer and a British jewel thief are brought together by their mutual desire to forget the past.', '2002-05-29', 5.82, 'https://image.tmdb.org/t/p/w500/qYq5muglnhTj7VjGAklqayGTvN8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49963, 'Walking and Talking', 'Just as Amelia thinks she''s over her anxiety and insecurity, her best friend announces her engagement, bringing her anxiety and insecurity right back.', '1996-07-17', 6.08, 'https://image.tmdb.org/t/p/w500/m8JMJQUfGwGt7gse8aoduAcTYE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50357, 'Apollo 18', 'Officially, Apollo 17 was the last manned mission to the moon. But a year later in 1973, three American astronauts were sent on a secret mission to the moon funded by the US Department of Defense. What you are about to see is the actual footage which the astronauts captured on that mission. While NASA denies its authenticity, others say it''s the real reason we''ve never gone back to the moon.', '2011-07-20', 5.31, 'https://image.tmdb.org/t/p/w500/4bLqU6YncqvKETzvPZPPoVrLUYM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50359, 'Hop', 'E.B., the Easter Bunny''s teenage son, heads to Hollywood, determined to become a drummer in a rock ''n'' roll band. In L.A., he''s taken in by Fred after the out-of-work slacker hits E.B. with his car.', '2011-03-30', 5.80, 'https://image.tmdb.org/t/p/w500/2FrDmwXWjRE1zpNP288YncRt5RF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50456, 'Hanna', 'Raised by her father, an ex-CIA agent, in the wilds of Finland, Hanna''s upbringing has been geared to making her the perfect assassin. Sent into the world by her father on a mission, Hanna journeys across Europe, eluding agents dispatched after her by a ruthless intelligence operative. As she nears her ultimate target, Hanna faces startling revelations about her existence.', '2011-04-07', 6.58, 'https://image.tmdb.org/t/p/w500/6QDeHwBXDHbCbuzStgUpuUAqnap.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50512, 'Anna Karenina', 'In Imperial Russia, Anna, wife of the officer Karenin, goes to Moscow to visit her brother. On the way, she meets charming cavalry officer Vronsky, to whom she''s immediately attracted. But in St. Petersburg’s high society, a relationship like this could destroy a woman’s reputation.', '1997-04-04', 6.10, 'https://image.tmdb.org/t/p/w500/6YWh035E2jhiWs57A2LMg1c9mv4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50541, 'Ice Castles', 'Alexis is on top of the world until a tragic accident dashes her hopes and dreams of becoming a world-class figure skater. Only with the help of those who love her can she prove to the world — and herself — that she still has the potential to realize her dreams.', '1978-12-31', 7.36, 'https://image.tmdb.org/t/p/w500/5iS3EJD286IYkJ83L5pEVoNF3xn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50544, 'Friends with Benefits', 'Dylan is done with relationships. Jamie decides to stop buying into the Hollywood clichés of true love. When the two become friends they decide to try something new and take advantage of their mutual attraction - but without any emotional attachment.', '2011-07-21', 6.64, 'https://image.tmdb.org/t/p/w500/nKhhDFCdzxeJ3GUunQ570LDpUkz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50562, 'Porn Star: The Legend of Ron Jeremy', 'Porn Star: The Legend of Ron Jeremy offers audiences a penetrating look inside the world of Ron Jeremy, America''s most unlikely sex star and hero to millions. With nearly 25 years in the adult film industry and over 1,600 films to his credit, Ron Jeremy is huge. In his world, Ron reigns supreme-he''s made millions of dollars and slept with thousands of beautiful women, and is indisputably the industry''s biggest star. And everyone who''s anyone knows Ron-a pop icon to millions, he is a beacon of hope for many American male, since he stands as living proof that pretty much anyone can get some. So how did such a classically unhandsome, big and hairy guy ever get to be suchia super stud? In one of the most fascinating and entertaining comedies of the last year, audiences finally get a chance to get inside the life and times of Ron Jeremy, and find out what''s really behind the hardest working man in show business.', '2001-01-20', 5.94, 'https://image.tmdb.org/t/p/w500/a5eOBUs5TtLraJpfJMMDehIwnDp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49935, 'Thieves', 'In the middle of the night, someone brings Ivan''s body home to his wife and his young son. Flashbacks reveal the relationships among Ivan and his brother Alex, a cop with a cleanliness fetish; siblings Juliette and Jimmy, Ivan''s partners in a seedy nightclub; the love triangle of Alex, Juliette, and Marie, a professor of philosophy; and of Alex and his nephew, Ivan''s dour, stoic son. Ivan''s death changes every relationship.', '1996-08-21', 6.14, 'https://image.tmdb.org/t/p/w500/meeBmnlkMP8UhrPvZKv83jjhd2E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50619, 'The Twilight Saga: Breaking Dawn - Part 1', 'Bella Swan and Edward Cullen''s honeymoon phase is abruptly disrupted by betrayals and unforeseen tragedies that endanger their world.', '2011-11-16', 6.20, 'https://image.tmdb.org/t/p/w500/qs8LsHKYlVRmJbFUiSUhhRAygwj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50546, 'Just Go with It', 'While romancing Palmer, a much younger schoolteacher, plastic surgeon Danny Maccabee enlists his loyal assistant Katherine to pretend to be his soon to be ex-wife, in order to cover up a careless lie. When more lies backfire, Katherine''s kids become involved, and everyone heads off for a weekend in Hawaii that will change all their lives.', '2011-02-10', 6.71, 'https://image.tmdb.org/t/p/w500/3rz7bfGsPGcI6cfY002n9VrUgao.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50646, 'Crazy, Stupid, Love.', 'Cal Weaver is living the American dream. He has a good job, a beautiful house, great children and a beautiful wife, named Emily. Cal''s seemingly perfect life unravels, however, when he learns that Emily has been unfaithful and wants a divorce. Over 40 and suddenly single, Cal is adrift in the fickle world of dating. Enter, Jacob Palmer, a self-styled player who takes Cal under his wing and teaches him how to be a hit with the ladies.', '2011-07-29', 7.30, 'https://image.tmdb.org/t/p/w500/p4RafgAPk558muOjnBMHhMArjS2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50725, 'Take Me Home Tonight', 'Recent MIT grad Matt Franklin should be well on his way to a successful career at a Fortune 500 company, but instead he rebels against maturity by taking a job at a video store. Matt rethinks his position when his unrequited high-school crush, Tori, walks in and invites him to an end-of-summer party. With the help of his twin sister and his best friend, Matt hatches a plan to change the course of his life.', '2011-03-04', 5.97, 'https://image.tmdb.org/t/p/w500/nInduPOusI1alDIC0UttFjDIKsO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50698, 'Grave Encounters', 'A crew from a paranormal reality television show lock themselves in a haunted psychiatric hospital. They search for evidence of paranormal activity as they shoot what ends up becoming their final episode.', '2011-09-09', 6.33, 'https://image.tmdb.org/t/p/w500/8vnsB3Rg9Gb91UOaecXRb7dYB37.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49381, 'Jimmy Carr: Making People Laugh', 'Jimmy Carr: Making People Laugh features over two hours of material that''s too rude for TV.', '2010-11-08', 7.57, 'https://image.tmdb.org/t/p/w500/bPsHHpT1oN6awwzbI71Bzzwm9mB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50794, 'The Even Stevens Movie', 'The Stevens think that they''ve won an all-expenses-paid trip to an island halfway around the world. When their house is destroyed, their food stolen, and their bacon eaten, the Stevens family crumbles, unaware that their family vacation is in fact a hidden camera reality show!', '2003-06-13', 5.83, 'https://image.tmdb.org/t/p/w500/xFDvO48Gq7putBBJmvjZAXARHQW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50789, 'Sympathy for the Devil', 'While The Rolling Stones rehearse "Sympathy for the Devil" in the studio, an alternating narrative reflects on 1968 society, politics and culture through five different vignettes.', '1968-12-01', 6.29, 'https://image.tmdb.org/t/p/w500/wxfNcj87BORjRYYKhY1jGMnVPLo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50797, 'Burnt by the Sun', 'Russia, 1936: revolutionary hero Colonel Kotov is spending an idyllic summer in his dacha with his young wife and six-year-old daughter Nadia and other assorted family and friends. Things change dramatically with the unheralded arrival of Cousin Dmitri from Moscow, who charms the women and little Nadia with his games and pianistic bravura. But Kotov isn''t fooled: this is the time of Stalin''s repression, with telephone calls in the middle of the night spelling doom - and he knows that Dmitri isn''t paying a social call...', '1994-05-01', 6.93, 'https://image.tmdb.org/t/p/w500/jcpvnPSuRrynrgY7menuyZe7X4r.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49370, 'Perfect', 'A female aerobics instructor meets a male reporter doing a story on health clubs, but it isn''t love at first sight.', '1985-05-15', 5.62, 'https://image.tmdb.org/t/p/w500/tb1jZGi23w2pIittaBBdaN6CGRI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51052, 'Arthur Christmas', 'For hundreds of years, the Claus family has delegated the title "Santa" to a chosen few of its members, which can be passed down upon retirement. Each Christmas, Santa and his vast army of highly trained elves produce gifts and distribute them around the world in a one-night high-tech operation. However, when one of 600 million children to receive a gift from Santa on Christmas Eve is missed, it is deemed ‘acceptable’ to all but one—Arthur Claus, the current Santa’s misfit son deemed ineligible for the title, who executes an unauthorised rookie mission to get the last present halfway around the globe before dawn on Christmas morning.', '2011-11-10', 6.77, 'https://image.tmdb.org/t/p/w500/brELZkSbkLrcCXJ0xt5hQUMXhut.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50071, 'Sweetgrass', 'An unsentimental elegy to the American West, Sweetgrass follows the last modern-day cowboys to lead their flocks of sheep up into Montana''s breathtaking and often dangerous Absaroka-Beartooth mountains for summer pasture, revealing a world in which nature and culture, animals and humans, vulnerability and violence are all intimately meshed.', '2009-11-18', 6.76, 'https://image.tmdb.org/t/p/w500/xTQ7URCmLBWkMJeT4G8uyvpciqU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51120, 'Peter Pan', 'In this magical tale about the boy who refuses to grow up, Peter Pan and his mischievous fairy sidekick Tinkerbell visit the nursery of Wendy, Michael and John Darling. With a sprinkling of pixie dust, Peter and his new friends fly out the nursery window and over London to Never-Never Land. The children experience many wonderful and exciting adventures with the Lost Boys, Tiger Lily''s Indian tribe, and Peter''s arch enemy the dastardly pirate Captain Hook.', '1960-12-08', 6.60, 'https://image.tmdb.org/t/p/w500/qCQ42aTmU4cuHwzfu8rCvYQuCyx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49950, 'The Roommate', 'When Sara, a young design student from Iowa, arrives for college in Los Angeles, she is eager to fit in and get to know the big city. Her wealthy roommate, Rebecca, is more than eager to take Sara under her wing and show her the ropes. The two become close, but when Sara begins to branch out and make more friends on campus, Rebecca becomes resentful. Alarmed, Sara moves in with her new boyfriend, causing Rebecca''s behavior to take a violent turn.', '2011-02-04', 5.39, 'https://image.tmdb.org/t/p/w500/kQZcOn5rDuwpbQTluC4Wm0amYmR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50620, 'The Twilight Saga: Breaking Dawn - Part 2', 'After the birth of Renesmee, the Cullens gather other vampire clans in order to protect the child from a false allegation that puts the family in front of the Volturi.', '2012-11-13', 6.45, 'https://image.tmdb.org/t/p/w500/7IGdPaKujv0BjI0Zd0m0a4CzEjJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49948, 'Fantasia 2000', 'Blending lively music and brilliant animation, this sequel to the original ''Fantasia'' restores ''The Sorcerer''s Apprentice'' and adds seven new shorts.', '2000-01-01', 6.98, 'https://image.tmdb.org/t/p/w500/5rwAtUaKEK48CPUijVfVU0IPKPZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49980, 'Ladybird Ladybird', 'Maggie has had four children, by four different fathers, removed by social services because of a previous violent relationship. When she meets Jorge, a gentle Latin American refugee, she gradually sees her chance for happiness, but her past still haunts her.', '1994-02-18', 7.21, 'https://image.tmdb.org/t/p/w500/14sAtrim0RpkI1eZSZ3m5etp5Wz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51145, 'Spring Forward', 'Trying to put himself back together after serving prison time for robbery, Paul takes a job as a parks employee in a small Connecticut town. His co-worker, Murph, a generation older than Paul, is dealing with his own issues, chiefly the the impending death of his very ill gay son. After the men have a run-in with local snob Frederickson, Murph''s age and experience starts to temper Paul''s fiery nature, as the younger man begins to embrace his new life.', '2000-12-10', 6.53, 'https://image.tmdb.org/t/p/w500/id2pAgtG5dNS7lguTpXbhCq9l3g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51036, 'MadHouse', 'The luxurious villa of Mark and Jessie Bannister, a yuppie couple, is overrun by loads of uninvited guests who turn the house up side down.', '1990-02-16', 5.35, 'https://image.tmdb.org/t/p/w500/l8BBcinqXq50PeKObT2lvLdTkYb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50647, 'Wanderlust', 'Rattled by sudden unemployment, a Manhattan couple surveys alternative living options, ultimately deciding to experiment with living on a rural commune where free love rules.', '2012-02-23', 5.50, 'https://image.tmdb.org/t/p/w500/hH1Bla0W4YIn9sdd9NwODzDCcE4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49418, 'Treasure Island', 'Young Jim Hawkins finds himself serving with pirate captain Long John Silver in search of a buccaneer''s treasure, in this Soviet Ukrainian animated adaptation of Robert Louis Stevenson''s classic tale', '1989-03-24', 7.66, 'https://image.tmdb.org/t/p/w500/5MkJspGYDwPB7QsFGi35sfBQoNJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49444, 'Kung Fu Panda 2', 'Po is finally living the dream as the Dragon Warrior—until a shadow from his past comes roaring back. When the ruthless peacock Lord Shen unleashes a devastating new weapon used to wipe out kung fu masters across the land, Po and the Furious Five race across China to put an end to his plans. But if Po is to have any hope of stopping him, he must first confront the truth of his origins—and find inner peace before his past tears him apart.', '2011-05-25', 7.10, 'https://image.tmdb.org/t/p/w500/mtqqD00vB4PGRt20gWtGqFhrkd0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51352, 'Anne Frank Remembered', 'Using previously unreleased archival material in addition to contemporary interviews, this Academy Award-winning documentary tells the story of the Frank family and presents the first fully-rounded portrait of their brash and free-spirited daughter Anne, perhaps the world''s most famous victim of the Holocaust.', '1995-06-08', 7.60, 'https://image.tmdb.org/t/p/w500/6nyhzrSGimCbdxiY8DEO7kI7xx4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (49981, 'Goodbye Lover', 'Police investigate when a man having an affair with his brother''s wife disappears suddenly.', '1999-04-16', 5.63, 'https://image.tmdb.org/t/p/w500/fE4wFIX2GUrhTkK0VuQ88Kd6ew6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51391, 'Murder on a Sunday Morning', '2001 French documentary about the murder trial of a 15 year old black teen accused of murder in Jacksonville, Florida. Winner of 2002 Academy Award for Best Documentary.', '2001-09-14', 7.40, 'https://image.tmdb.org/t/p/w500/vFl8G6VSVcStLLKbH0KzipYjISe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50839, 'Margin Call', 'Set in the high-stakes world of the financial industry, involving the key players at an investment firm during one perilous 24-hour period in the early stages of the 2008 financial crisis. An entry-level analyst unlocks information that could prove to be the downfall of the firm.', '2011-09-28', 6.86, 'https://image.tmdb.org/t/p/w500/qtO57obCJuUBS0en3HLgFgZ19Xk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51497, 'Fast Five', 'Former cop Brian O''Conner partners with ex-con Dom Toretto on the opposite side of the law. Since Brian and Mia Toretto broke Dom out of custody, they''ve blown across many borders to elude authorities. Now backed into a corner in Rio de Janeiro, they must pull one last job in order to gain their freedom.', '2011-04-20', 7.24, 'https://image.tmdb.org/t/p/w500/gEfQjjQwY7fh5bI4GlG0RrBu7Pz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51533, 'Let the Bullets Fly', 'When circumstances force an outlaw to impersonate a county governor and clean up a corrupt town, the Robin Hood figure finds himself in a showdown with the local godfather.', '2010-12-20', 7.80, 'https://image.tmdb.org/t/p/w500/pkwBO3XkQLhgb31vl5ZwmGC5meT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51521, 'My Demon Lover', 'Denny has yet again been left by her thug boyfriend Chip. It seems as if she is doomed to be stuck with awful guys, this time she has to choose between nerdy Charles and the strange Kaz, who turns into a monster when sexually aroused.', '1987-04-24', 5.32, 'https://image.tmdb.org/t/p/w500/hKUZUfy8rnNTJYRysMG21lpK5oc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51540, 'Horrible Bosses', 'For Nick, Kurt and Dale, the only thing that would make the daily grind more tolerable would be to grind their intolerable bosses into dust. Quitting is not an option, so, with the benefit of a few-too-many drinks and some dubious advice from a hustling ex-con, the three friends devise a convoluted and seemingly foolproof plan to rid themselves of their respective employers... permanently.', '2011-07-08', 6.57, 'https://image.tmdb.org/t/p/w500/uQkUwgyFHAm0jGQERPG6Z9o9Zbj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51608, 'The Man from Nowhere', 'A reclusive pawnshop owner goes on a brutal rampage to rescue a young girl kidnapped by a criminal organization.', '2010-08-04', 7.70, 'https://image.tmdb.org/t/p/w500/9QJ3cPpYgoPfhRnRPxpQUfx790r.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51620, 'Death Race 2', 'In the world''s most dangerous prison, a new game is born: Death Race. The rules of this adrenaline-fueled blood sport are simple, drive or die. When repentant convict Carl Lucas discovers there''s a price on his head, his only hope is to survive a twisted race against an army of hardened criminals and tricked-out cars.', '2010-11-12', 5.86, 'https://image.tmdb.org/t/p/w500/80mBFNVvak2bA9TJN1MD0yM7Lfi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51679, 'The Source', 'Traces the Beats from Allen Ginsberg and Jack Kerouac''s meeting in 1944 at Columbia University to the deaths of Ginsberg and William S. Burroughs in 1997. Three actors provide dramatic interpretations of the work of these three writers, and the film chronicles their friendships, their arrival into American consciousness, their travels, frequent parodies, Kerouac''s death, and Ginsberg''s politicization. Their movement connects with bebop, John Cage''s music, abstract expressionism, and living theater. In recent interviews, Ginsberg, Burroughs, Kesey, Ferlinghetti, Mailer, Jerry Garcia, Tom Hayden, Gary Snyder, Ed Sanders, and others measure the Beats'' meaning and impact.', '1999-01-23', 5.59, 'https://image.tmdb.org/t/p/w500/cVWKNCnosCBfEmSDVNoxtrI8px0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51739, 'The Secret World of Arrietty', '14-year-old Arrietty and the rest of the Clock family live in peaceful anonymity as they make their own home from items "borrowed" from the house''s human inhabitants. However, life changes for the Clocks when a human boy discovers Arrietty.', '2010-07-16', 7.70, 'https://image.tmdb.org/t/p/w500/3lSRaSjDp2nkXMQkzzjpRi3035O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51763, 'The Long Walk Home', 'Two women, black and white, in 1955 Montgomery Alabama, must decide what they are going to do in response to the famous bus boycott led by Martin Luther King.', '1990-12-21', 7.60, 'https://image.tmdb.org/t/p/w500/7T2oVjLHHIDY6FQH9e04oOgPWQa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51802, 'Of Mice and Men', 'An intellectually disabled giant and his level headed guardian find work at a sadistic cowboy''s ranch in depression era America.', '1939-12-24', 7.31, 'https://image.tmdb.org/t/p/w500/ihgGS9K8pCYdgb9SpanxoKcJ0Al.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51828, 'One Day', 'After spending the night together on the eve of their college graduation, Dexter and Emma are shown each year on the same date to see where they are in their lives. They are sometimes together, and sometimes not.', '2011-03-02', 7.42, 'https://image.tmdb.org/t/p/w500/n9jMwSg4IavdD8wqdYnyW5w3Mvp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51863, 'Seven Up!', 'A group of British children aged 7 from widely ranging backgrounds are interviewed about a range of subjects. The filmmakers plan to re-interview them at 7 year intervals to track how their lives and attitudes change as they age.', '1964-05-05', 7.19, 'https://image.tmdb.org/t/p/w500/pgxBgde0VpbbdpN6bL05gpMtlC9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50008, 'RKO 281', 'In 1939, boy-wonder Orson Welles leaves New York, where he has succeeded in radio and theater, and, hired by RKO Pictures, moves to Hollywood with the purpose of making his first film.', '1999-11-20', 6.45, 'https://image.tmdb.org/t/p/w500/v8Z4ENMOAT5OpiMeS1PBNPui3X0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51876, 'Limitless', 'The life of an unsuccessful writer is transformed by a top-secret ''smart drug'' that allows him to use 100% of his brain and become a perfect version of himself. His enhanced abilities soon attract shadowy forces that threaten his new life.', '2011-03-17', 7.20, 'https://image.tmdb.org/t/p/w500/kCokPP4WCQRrrAuZ7FcpIyHr8b2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51875, 'Miss Nobody', 'A mild-mannered secretary discovers that she has a talent for murder as she ascends the corporate ladder.', '2010-06-10', 5.20, 'https://image.tmdb.org/t/p/w500/mDrQ2rRdmlKAOeSUvSFZi0Rt5op.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51927, 'Stevie', 'In 1995 Director Steve James (Hoop Dreams) returned to rural Southern Illinois to reconnect with Stevie Fielding, a troubled young boy he had been an ''Advocate Big Brother'' to ten years earlier.', '2003-04-11', 7.01, 'https://image.tmdb.org/t/p/w500/67TAylTWoysC2ffqVO18do0rwEE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51945, 'Not on the Lips', 'A musical drawing room farce set in Paris circa October, 1925. Middle-aged Gilberte flirts with men but loves her husband Georges, wishing he were more demonstrative. He''s negotiating a deal with American Eric Thomson, who turns out to be Gilberte''s first husband from an annulled and secret stateside marriage. Along with her sister Arlette, Gilberte begs Eric not to tell Georges about their past. Meanwhile, a young artist, Charly, pursues Gilberte while Arlette tries to match him with the young Huguette, who loves him. Will Eric play along or try to re-win Gilberte''s affection? Can Gilberte play one off against another? And who will manage to kiss whom on the lips?', '2003-12-03', 5.70, 'https://image.tmdb.org/t/p/w500/aLDY62kgrEWrD4ll9ChS5JAGEQJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51038, 'The Last Wedding', 'Pekka arrives back to his home village of Jerusalem to celebrate the last wedding of the village. His own marriage seems to have reached a dead end. The people of the village gather to prepare for the event, and the bitter spectrum of all human life, with its joys and sorrows, is condensed into one summer''s day.', '1995-02-17', 6.08, 'https://image.tmdb.org/t/p/w500/21y2esavPVdSgPGtew5vn8GyGDM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51993, 'Terri', 'Terri, a pajama-clad, disaffected high school student learns how to engage the world with the help of Mr. Fitzgerald, his assistant principal.', '2011-07-01', 6.36, 'https://image.tmdb.org/t/p/w500/ng3K9EeuBFn82kN4XgpOKQgx6Fd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51999, 'Perfect Sense', 'In Glasgow, Scotland, while a mysterious pandemic begins to spread around the world, Susan, a brilliant epidemiologist, falls in love with Michael, a skillful cook.', '2011-09-29', 6.87, 'https://image.tmdb.org/t/p/w500/2UuuO6MX1AzD61zX6NHiHQODoI1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50014, 'The Help', 'Aibileen Clark is a middle-aged African-American maid who has spent her life raising white children and has recently lost her only son; Minny Jackson is an African-American maid who has often offended her employers despite her family''s struggles with money and her desperate need for jobs; and Eugenia "Skeeter" Phelan is a young white woman who has recently moved back home after graduating college to find out her childhood maid has mysteriously disappeared. These three stories intertwine to explain how life in Jackson, Mississippi revolves around "the help"; yet they are always kept at a certain distance because of racial lines.', '2011-08-09', 8.20, 'https://image.tmdb.org/t/p/w500/3kmfoWWEc9Vtyuaf9v5VipRgdjx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52015, 'Stake Land', 'Martin was a normal teenage boy before the country collapsed in an empty pit of economic and political disaster. A vampire epidemic has swept across what is left of the nation''s abandoned towns and cities, and it''s up to Mister, a death dealing, rogue vampire hunter, to get Martin safely north to Canada, the continent''s New Eden.', '2010-09-30', 6.19, 'https://image.tmdb.org/t/p/w500/q5Cq3svR0XPEb9VkVBHPowT1Bxf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50837, 'Martha Marcy May Marlene', 'After several years of living with a cult, Martha finally escapes and calls her estranged sister, Lucy, for help. Martha finds herself at the quiet Connecticut home Lucy shares with her new husband, Ted, but the memories of what she experienced in the cult make peace hard to find. As flashbacks continue to torment her, Martha fails to shake a terrible sense of dread, especially in regard to the cult''s manipulative leader.', '2011-10-21', 6.58, 'https://image.tmdb.org/t/p/w500/bgB4sa9UfCyGdamfKAZXyEWuAwR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51209, 'Kill the Irishman', 'Over the summer of 1976, thirty-six bombs detonate in the heart of Cleveland while a turf war raged between Irish mobster Danny Greene and the Italian mafia. Based on a true story, Kill the Irishman chronicles Greene''s heroic rise from a tough Cleveland neighborhood to become an enforcer in the local mob.', '2011-03-10', 6.78, 'https://image.tmdb.org/t/p/w500/yjDvqAMyFlesBtWNUUZMgglo78y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52067, 'Cedar Rapids', 'A naive Midwesterner insurance salesman travels to a big-city convention in an effort to save the jobs of his co-workers.', '2011-02-11', 5.94, 'https://image.tmdb.org/t/p/w500/udHprtPPfDHdcR1ijoY24mt9OB1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52258, 'The Emperor''s New Clothes', 'Napoleon, exiled, devises a plan to retake the throne. He''ll swap places with commoner Eugene Lenormand, sneak into Paris, then Lenormand will reveal himself and Napoleon will regain his throne. Things don''t go at all well; first, the journey proves more difficult than expected, but more disastrously, Lenormand enjoys himself too much to reveal the deception. Napoleon adjusts somewhat uneasily to the life of a commoner while waiting, while Lenormand gorges on rich food.', '2001-08-11', 6.80, 'https://image.tmdb.org/t/p/w500/iTonTn91U4X1px7KXAHTFnIA4ud.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51985, 'An All Dogs Christmas Carol', 'Charlie, Itchy and Sasha itch and scratch their way through everything and anything in an effort to save Christmas from the wicked hellhound Belladonna, who wants to use dogs from all over the world to ruin Christmas.', '1998-11-17', 6.10, 'https://image.tmdb.org/t/p/w500/7J8qq1O1kAjVdpDJnxuzNC5tH3H.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51239, 'Paradox', 'Homicide detective Sean Nault is a cop on a parallel Earth whose technology is powered exclusively by magic. Sean investigates a baffling series of murders committed by a means he''s never seen before: science. With the aid of Lenoir, a member of the ridiculed subculture of "pragmatists" who believe science is more than the stuff of myths & children''s stories, and the 130-year-old sorcerer Winston Churchill, Sean uncovers an ominous plot that will lead him to another dimension and the realization that, unless he prevents it, both earths could well be destroyed.', '2010-11-19', 4.30, 'https://image.tmdb.org/t/p/w500/aYR9jDH3fFTdPVreFKfaavTCscn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50116, 'Simpatico', 'As youths in Azusa, Vinnie, Carter, and Rosie pull off a racing scam, substituting winners for plodders and winning big bucks on long odds. When an official uncovers the scam, they set him up for blackmail. Jump ahead twenty years, Carter and Rosie are married, successful racers in Kentucky about to sell their prize stallion, Simpatico. Vinnie is a drunk in Pomona. Vinnie decides to make a play for Rosie, lures Carter to California, steals his wallet and heads for Kentucky with the original blackmail material. Carter begs Vinnie''s friend, a grocery clerk named Cecilia, to follow Vinnie and get the stuff back that he has in a box. Will she succeed?', '1999-09-15', 4.87, 'https://image.tmdb.org/t/p/w500/p6JglpvM6ERbZAYEW31gwvNprVZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52038, 'A Man of No Importance', 'Alfie Byrne is a middle-aged bus conductor in Dublin in 1963. He would appear to live a life of quiet desperation: he''s gay, but firmly closeted, and his sister is always trying to find him "the right girl". His passion is Oscar Wilde, his hobby is putting on amateur theatre productions in the local church hall. We follow him as he struggles with temptation, friendship, disapproval, and the conservative yet oddly lyrical world of Ireland in the early 1960s.', '1994-12-24', 6.20, 'https://image.tmdb.org/t/p/w500/zKHmxia0cdXMmNu5LUEwiJQJQoa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51980, 'Germinal', 'It''s mid 19th century, north of France. The story of a coal miner''s town. They are exploited by the mine''s owner. One day the decide to go on strike, and then the authorities repress them.', '1993-09-29', 6.72, 'https://image.tmdb.org/t/p/w500/cizv23RUxcpTrQt4kcOz7Sv6YJl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50035, 'Lovely & Amazing', 'An intimate family portrait of four hapless but resilient women and the bittersweet lessons they learn in keeping up with the hectic demands of their individual neuroses. Each of the women seeks redemption in her own haphazard way, but whatever salvation they find is illusory and short-lived.', '2002-08-02', 6.05, 'https://image.tmdb.org/t/p/w500/4HZ7Y7N4KHapO5ylOY8BePQYC5X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51162, 'Winnie the Pooh', 'During an ordinary day in Hundred Acre Wood, Winnie the Pooh sets out to find some honey. Misinterpreting a note from Christopher Robin, Owl convinces Pooh, Tigger, Rabbit, Piglet, Kanga, Roo, and Eeyore that their young friend has been captured by a creature named "Backson" and they set out to rescue him.', '2011-04-06', 6.91, 'https://image.tmdb.org/t/p/w500/xlFs85nq62jeR4a9iHNGB113m6x.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50183, 'The Ascent', 'During a freezing WWII winter, two Soviet partisans on a mission to gather food contend with the temperature, the occupying Germans, and their own psyches.', '1977-04-02', 7.90, 'https://image.tmdb.org/t/p/w500/hJOju5XZfmq4Lg5dPa8IPVY3mDt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51230, 'Cinemania', 'This documentary about the culture of intense cinephilia in New York City reveals the impassioned world of five obsessed movie buffs. These human encyclopedias of cinema see two to five films a day, and from 600 to 2,000 films per year. This is the story of their lives, their memories, their unbending habits and the films they love.', '2002-07-06', 6.80, 'https://image.tmdb.org/t/p/w500/yDxDCCxuyDx6MrJkLqZwcvPWamq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52263, 'Amityville: Dollhouse', 'Bill Martin has just finished construction on a picturesque new home for his family, but unknown to him, the previously barren property was once the site of the infamous Amityville murder house, which contains demonic entities with murderous sights on the family.', '1996-10-02', 4.54, 'https://image.tmdb.org/t/p/w500/c6DVwjJ71jzk3DXqrkuvuM6BxW1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (50162, '964 Pinocchio', 'A memory-wiped and defective cyborg sex slave is tossed onto the streets and taken in by a homeless woman while his corporate creators hunt him down.', '1991-09-14', 5.99, 'https://image.tmdb.org/t/p/w500/99iOoaDyFElUA5ihgBYKmGRhPJs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51179, 'Circus', 'Bruno, a sadistic criminal, wants clever con man Leo out of the way. Leo and his equally clever wife, Lily, are up to something. So too is Julius: he hires Leo to kill Gloria, Julius''s wife. Leo does it, but then Julius shows up with the murder on tape, saying Gloria isn''t his wife - it''s blackmail. Leo''s bookie, Troy, is also closing in, wanting to be paid. Bruno and Lily as well as Bruno and Julius have their own scams running, and Leo is their target. Maybe Leo can get Troy off his back, avoid Moose (Bruno''s huge enforcer), send Gloria''s corpse out of England, turn the tables on Bruno''s murderous brother Caspar, and outfox Lily. Or is Lily his fox? It''s a three-ring circus.', '2000-05-05', 4.97, 'https://image.tmdb.org/t/p/w500/ttXgT8IspCtnJhRsqS6wtJBBRGM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52780, 'The Glass Menagerie', 'An aging Southern Belle complicates life for her ambitious son and crippled daughter because of her own warped views of what life should be.', '1987-05-27', 6.24, 'https://image.tmdb.org/t/p/w500/zF02disLmOSyb3BSS4c50MC7xNo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52794, 'Baxter', 'A white Bull Terrier named Baxter is given to an elderly woman by her daughter. As time passes, the dog develops aggressive and murderous behavior in order to be adopted by another family.', '1989-01-18', 6.39, 'https://image.tmdb.org/t/p/w500/c77bDsP7jfMiEeRM5wd0UV0Aine.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52844, 'It Happened on Fifth Avenue', 'A New Yorker hobo moves into a mansion and along the way he gathers friends to live in the house with him. Before he knows it, he is living with the actual home owners.', '1947-04-17', 7.06, 'https://image.tmdb.org/t/p/w500/4iYAKgBIh8fKY7fdzSKee2t2VIa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52855, 'Dangerous Ground', 'Vusi Madlazi returns to the South African village he left as a young boy to bury his father. He meets up with his brother Ernest, who tells him their other brother Stephen couldn''t be contacted. Vusi goes to Johannesburg to find him, but at first can only find his neighbor/girlfriend, Karin, a stripper. Vusi proceeds to learn how conditions have changed since the end of apartheid, not always for the better for black men.', '1997-02-12', 4.36, 'https://image.tmdb.org/t/p/w500/3oFap1KH6zTTP1w0iQ6uQZrzKU4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52856, 'Unstrung Heroes', 'Steven Lidz, unhappy with his home life since his mother became sick, moves in with his two eccentric uncles. As Steven grows closer to his uncles, he learns how to cope with his emotions and to value his own uniqueness.', '1995-09-15', 6.10, 'https://image.tmdb.org/t/p/w500/twnqc80AL55WYnCVz4nMGEGcL7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52903, 'Steam of Life', 'Finnish men in sauna, speaking straight from the heart.', '2010-03-26', 7.10, 'https://image.tmdb.org/t/p/w500/e7h7G7p7teeMYAMX3YWO4FfwmEH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52906, 'Goodbye Charlie', 'When a cavorting Hollywood writer is killed by the angry husband of a woman he was having an affair with, he comes back as a spirit in the form of a beautiful woman and moves in with his/her best friend as a base operation for enacting sweet revenge.', '1964-11-18', 5.84, 'https://image.tmdb.org/t/p/w500/tA7MNMfk1BQdEMM8aJhQSLP4fA5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53021, 'Kiss Me, Stupid', 'While traveling home from Vegas, an amorous lounge singer named Dino gets conned by a local mechanic/songwriter into staying in town for the night. The mechanic''s songwriting partner, Orville, offers Dino his home for overnight lodging and enlists a local waitress/call girl to pose as his wife in order to placate Dino''s urges.', '1964-12-22', 6.98, 'https://image.tmdb.org/t/p/w500/sbMILWDfzwQI8ZBIn42zGNU4xqg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51241, 'Heartbeats', 'Francis is a young gay man, Marie is a young straight woman and the two of them are best friends -- until the day the gorgeous Nicolas walks into a Montreal coffee shop. The two friends, instantly and equally infatuated, compete for Nicolas'' indeterminate affections, a conflict that climaxes when the trio visit the vacation home of Nicolas'' mother. The frothy comedy unfolds through narrative, fantasy sequences and confessional monologues.', '2010-06-11', 7.09, 'https://image.tmdb.org/t/p/w500/kBGbvzrP4lNV4BZc2wscmglNno2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53027, 'Mystery Date', 'Tom McHugh quickly learns that his perfect big brother Craig isn''t all he''s cracked up to be while on a night on the town with the girl next door, during which Tom is harassed by unpleasant strangers, threatened by mobsters, pursued by police, attacked by an irate florist, accused of murder, and has his date kidnapped—all because everyone thinks he''s Craig...and the classic 1959 DeSoto Firesweep he borrowed off his brother has two dead bodies in the trunk.', '1991-08-16', 5.84, 'https://image.tmdb.org/t/p/w500/vof40ryhBNTEvtjHl1somhdrXm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53048, 'Bartleby', 'An adaptation of Herman Melville''s short story "Bartleby, the Scrivener" told in the setting of a modern office.', '2001-03-10', 5.82, 'https://image.tmdb.org/t/p/w500/swYfLGplXAle5CenmWVYpRSomCp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53113, 'One True Thing', 'A career woman reassesses her parents'' lives after she is forced to care for her cancer-stricken mother.', '1998-09-18', 6.53, 'https://image.tmdb.org/t/p/w500/hOYQIMtrqVeHUBe999V1KIqO7Gf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53116, 'Between Your Legs', 'A radio-show assistant meets a budding screenwriter during a group-therapy session for sex addicts.', '1999-01-14', 5.34, 'https://image.tmdb.org/t/p/w500/3RwzIMMaZEmvGWzvOrZZfWctdvx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53172, 'Henry''s Crime', 'An aimless man is sent to prison for a crime he did not commit, an ex-con targets the same bank he was sent away for robbing.', '2010-01-14', 5.82, 'https://image.tmdb.org/t/p/w500/1i1sDWOZecbUZ4Yp9DG5UiTBBRl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53168, 'King of Comedy', 'Wan Tin-Sau is an actor who cannot seem to catch a break, since his only professional jobs are limited to being a movie extra. As well as being an actor, he is also the head of his village''s community center.', '1999-02-08', 7.40, 'https://image.tmdb.org/t/p/w500/dmJWvKNgeCrIwJH6AapdSMiZHop.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53179, 'The School Teacher', 'After having lost his job for having saved a child accused of shop lifting, Frédéric Barbier decides to become a school teacher with some funny results.The great comedy actor Coluche is excellent as a simple school teacher.', '1981-10-28', 6.00, 'https://image.tmdb.org/t/p/w500/2ToezxqfIvCcuFzVmGp82FOBkQy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53182, '300: Rise of an Empire', 'Greek general Themistocles attempts to unite all of Greece by leading the charge that will change the course of the war. Themistocles faces the massive invading Persian forces led by mortal-turned-god, Xerxes and Artemesia, the vengeful commander of the Persian navy.', '2014-03-05', 6.12, 'https://image.tmdb.org/t/p/w500/wYDdWN1McB1Sio4z1dPSkb40Z78.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53190, 'The Two Escobars', 'Pablo Escobar was the richest, most powerful drug kingpin in the world, ruling the Medellin Cartel with an iron fist. Andres Escobar was the biggest soccer star in Colombia. The two were not related, but their fates were inextricably-and fatally-intertwined. Pablo''s drug money had turned Andres'' national team into South American champions, favored to win the 1994 World Cup in Los Angeles. It was there, in a game against the U.S., that Andres committed one of the most shocking mistakes in soccer history, scoring an "own goal" that eliminated his team from the competition and ultimately cost him his life. The Two Escobars is a riveting examination of the intersection of sports, crime, and politics.', '2010-06-22', 7.36, 'https://image.tmdb.org/t/p/w500/qYnslGb1D0JgYLQYiwPqQ2ojQDv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53198, 'My Voyage to Italy', 'World-renowned director Martin Scorsese narrates this journey through his favorites in Italian cinema.', '1999-09-11', 7.59, 'https://image.tmdb.org/t/p/w500/hygBynLFPb4YWStH6ha3vbU7pAM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
