INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53210, 'Duck Amuck', 'The short-tempered Daffy Duck must improvise madly as the backgrounds, his costumes, the soundtrack, even his physical form, shifts and changes at the whim of the animator.', '1953-02-28', 8.11, 'https://image.tmdb.org/t/p/w500/bKF3kDYLjt5X3YsntmydkLJHK9I.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53287, 'The Super', 'Louie Kritski is a heartless landlord who has been so negligent in keeping up his ghetto apartment that he is threatened with jail time. The judge gives him another option -- he must live in his rat-infested hell hole until he brings it up to liveable standards.', '1991-10-04', 5.93, 'https://image.tmdb.org/t/p/w500/grkfopMr14odyBGTZQFiBXZ6K5Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
