INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53596, 'Even the Rain', 'As a director and his crew shoot a controversial film about Christopher Columbus in Cochabamba, Bolivia, local people rise up against plans to privatize the water supply.', '2011-01-05', 6.99, 'https://image.tmdb.org/t/p/w500/nXjLFjC1nZUycdO273kV4sV3XqL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
