INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51333, 'Love''s Labour''s Lost', 'A scholarly king and his three companions swear off the society of women for three years, only to have a diplomatic visit from a French princess and her three ladies-in-waiting thwart their intentions.', '2000-03-31', 5.50, 'https://image.tmdb.org/t/p/w500/7rJr9b0Mc8wEAqzuDUkz0zg1BX7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52449, 'Bad Teacher', 'A lazy, incompetent middle school teacher who hates her job and her students is forced to return to her job to make enough money for a boob job after her rich fiancé dumps her.', '2011-05-16', 5.60, 'https://image.tmdb.org/t/p/w500/zpIY4qUSX91J9XpPgr0hFrk1eKr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54054, 'One for the Money', 'An unemployed lingerie buyer convinces her bail bondsman cousin to give her a shot as a bounty hunter. Her first assignment is to track down a former cop on the run for murder – the same man who broke her heart years before. With the help of some friends and the best bounty hunter in the business, she slowly learns what it takes to be a true bounty hunter.', '2012-01-26', 5.55, 'https://image.tmdb.org/t/p/w500/eeltLl5jLUl9d96tpKkCAWu4JWu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52013, 'Marwencol', 'After a vicious attack leaves him brain-damaged and broke, Mark Hogancamp seeks recovery in "Marwencol", a 1/6th scale World War II-era town he creates in his backyard.', '2010-03-12', 7.24, 'https://image.tmdb.org/t/p/w500/bdlOAvKrHe4jLO9LUCxjqOqST4X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (51242, 'Bread and Chocolate', 'An Italian immigrant tries to make a new life in Switzerland, taking on a series of increasingly menial jobs in order to do it. He attempts to fit into his new home and society but fails at every turn. Unable to go home again, will his tenacity and optimism be enough to live on?', '1974-05-05', 7.20, 'https://image.tmdb.org/t/p/w500/24D3e6xBPEvqlFoq4tSMVqVQ3TO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52470, 'My Man Godfrey', 'The eccentric Bullock household again need a new butler. Daughter Irene encounters bedraggled Godfrey Godfrey at the docks and, fancying him and noticing his obviously good manners, gets him the job. He proves a great success, but keeps his past to himself. When an old flame turns up Irene''s sister Cordelia starts making waves.', '1957-10-11', 6.50, 'https://image.tmdb.org/t/p/w500/9qXWyhDDoQH2WEc3KecjRmu6QC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54087, 'Mr. Saturday Night', 'Buddy Young was the comic''s comic, beloved by everyone. Now, playing to miniscule crowds in nursing homes, it seems like everybody but Buddy realizes that he should retire. As Buddy looks for work in show business, he realizes that the rest of the world has forgotten the golden days of Buddy Young, and that there just may not be room in the business for an old comic like himself.', '1992-09-23', 5.86, 'https://image.tmdb.org/t/p/w500/tDAJzffAZyhpEsRiRCH3J9abTbZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
