INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52520, 'Underworld: Awakening', 'Having escaped years of imprisonment, vampire warrioress Selene finds herself in a changed world where humans have discovered the existence of both Vampire and Lycan clans and are conducting an all-out war to eradicate both immortal species. Now Selene must battle the humans and a frightening new breed of super Lycans to ensure the death dealers'' survival.', '2012-01-19', 6.33, 'https://image.tmdb.org/t/p/w500/jN0uuc8U6M3sTg9zEaliJV60Stf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52036, 'The Company', 'Ensemble drama centered around a group of ballet dancers, with a focus on one young dancer who''s poised to become a principal performer.', '2003-12-25', 5.20, 'https://image.tmdb.org/t/p/w500/kZpURQjJuGvl2a0xI01J8uocCWW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52077, 'Nothing to Declare', 'During the elimination of the Belgian/French border in the 90s, a Belgian customs officer is forced to team up with one of his French counterparts.', '2010-12-20', 5.89, 'https://image.tmdb.org/t/p/w500/vqJmmfVavVX9F9De3LQLDlGPc6D.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53862, 'Trippin''', 'Greg is near the end of his senior year in high school, wanting to go to the prom, eyeing Cinny (the school''s beauty with brains) from afar, and regularly trippin'', daydreaming about being a big success as a poet, a student, a lover. His mom wants him to apply to colleges, but Greg hasn''t a clue. One of his teachers, Mr. Shapic, tries to inspire him, too. He finally figures out he can get close to Cinny if he asks her for help with college applications. But friendship isn''t enough, he wants romance and a prom date. So, he tells a few lies and, for awhile, it seems to be working. Then, things fall apart and Greg has to figure out how to put the trippin aside and get real.', '1999-05-12', 5.18, 'https://image.tmdb.org/t/p/w500/gKdbdPg6Ye8TOpGGDFQ0NeVVSSI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53765, 'Mr. Jealousy', 'After his first date at age 15 ended with the girl making out with another man at a party, aspiring writer Lester Grimm has treated all his girlfriends with jealousy and suspicion. While dating Ramona Ray, paranoia gets the best of him when he discovers that her most recent ex is successful novelist Dashiell Frank. Lester begins attending the same group therapy sessions as Dashiell to learn about Ramona''s past with him.', '1998-06-05', 5.87, 'https://image.tmdb.org/t/p/w500/eHKAQTwZOIzUvqz4pZ3Tj6JX3K1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54527, 'Into Eternity: A Film for the Future', 'Every day, the world over, large amounts of high-level radioactive waste created by nuclear power plants is placed in interim storage, which is vulnerable to natural disasters, man-made disasters, and to societal changes. In Finland the world’s first permanent repository is being hewn out of solid rock – a huge system of underground tunnels - that must last 100,000 years as this is how long the waste remains hazardous.', '2010-11-12', 7.16, 'https://image.tmdb.org/t/p/w500/hzINyIeovFPMwtwMteSuXdByCby.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53928, 'Adam and Eve', 'Adam is a typical college-aged guy... which is to say he wants sex 24 hours a day. But when he meets - and falls for - Eve, a scorchingly hot coed who''s still very attached to her virginity, the waiting game is on! While his college buddies score left and right, and campus hotties make tempting passes, Adam ponders an explosive question: Will Eve say "It''s the right time"... before he completely goes out of his mind?', '2005-11-04', 3.98, 'https://image.tmdb.org/t/p/w500/jtf60tNMJQ6Jbman4Fi43rnSIVA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52560, 'Book of Love', 'John Twiller takes down his high school yearbook and begins to reminiscence about that time he first moved into the neighborhood in 1956. His teenage self, Jack is obsessed with Lily one of the more popular girls around. The sole obstacle is Angelo, her bullying boyfriend. With the help of his pals Crutch, Floyd, and Spider, he makes every attempt possible to change her mind.', '1990-08-03', 5.50, 'https://image.tmdb.org/t/p/w500/euB7qu0yqFWqWlPfgNeOTjEIZCD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54146, 'Pitfall', 'A man wanders into a seemingly deserted town with his young son in search of work. But after a bit of bad luck, he joins the town''s population of lost souls.', '1962-07-01', 7.34, 'https://image.tmdb.org/t/p/w500/KIRFXDuELVg86zDqDH0ESd9QoV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52705, 'The Carabineers', 'During a war in an imaginary country, unscrupulous soldiers recruit poor farmers with promises of an easy and happy life. Two of these farmers write to their wives of their exploits.', '1963-05-31', 6.48, 'https://image.tmdb.org/t/p/w500/oBL7ragSWtX8rHswM25BkdzQzWZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54568, 'To Each His Own', 'During World War I, small-town girl Josephine Norris has an illegitimate son by an itinerant pilot. After a scheme to adopt him ends up giving him to another family, she devotes her life to loving him from afar.', '1946-03-12', 7.00, 'https://image.tmdb.org/t/p/w500/jDk2Y8U2C7KupYv4GKmMfgx0y2s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54546, 'China Blue', '"China Blue" is an engrossing documentary that tells the story of 3 teenage girls who leave their rural homes in China to come work for a factory that makes blue jeans.', '2011-01-03', 5.75, 'https://image.tmdb.org/t/p/w500/507KwY23hbOtz5UwPlrODlZsger.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54580, 'Mondays in the Sun', 'After the closure of their shipyard in Northern Spain, a few former workers: Santa, José, Lino, Amador, Sergei and Reina keep in touch. They meet mainly at a bar owned by their former colleague Rico. Santa is the most superficially confident and unofficial leader of the group. A court case hangs over him relating to a shipyard lamp he smashed during a protest against the closure. José is bitter that his wife, Ana, is employed when he is not.', '2002-09-27', 7.24, 'https://image.tmdb.org/t/p/w500/4BlI5weSiYUU1YnjqdaPLnOzc3Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54714, 'The Trials of Henry Kissinger', 'This riveting documentary depicts former Secretary of State Henry Kissinger as a warmonger responsible for military cover-ups in Vietnam, Cambodia and East Timor, as well as the assassination of a Chilean leader in 1970. Based on a book by journalist Christopher Hitchens, the film includes interviews with historians, political analysts and such journalists as New York Times writer William Safire, a former Nixon speechwriter.', '2002-09-25', 6.91, 'https://image.tmdb.org/t/p/w500/hTzpmKT6w14A33L4ZQElLaZxPvM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54825, 'Creature Comforts', 'A humorous and thought-provoking view of what animals in zoos might be thinking about their captivity and surroundings.', '1989-07-15', 7.20, 'https://image.tmdb.org/t/p/w500/Ap8XavPP8AyvW9TDQDAZzEGT200.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54898, 'The Green Ray', 'A lonely Parisian woman comes to terms with her isolation and anxieties during a long summer vacation.', '1986-08-29', 7.50, 'https://image.tmdb.org/t/p/w500/1E3pliSC7lXWw6zJhMvG6ba0UNX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55146, 'Hearts & Minds', 'In the final days of the pro-apartheid government, bigoted policeman and assassin Andries Fourie is assigned an undercover job. His task is to pose as a political progressive to infiltrate the African National Congress and assassinate one of the party’s leaders.', '1995-08-29', 7.00, 'https://image.tmdb.org/t/p/w500/74CK1qibFcIR45SAwLZ32cQjAZ6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55106, 'Butterflies Are Free', 'Striving to be independent, the blind but determined Don Baker moves away from his overprotective mother. After settling into his new San Francisco digs, Don meets kooky neighbor Jill Tanner. Don''s quick wit and good looks disarm the free-spirited Jill, and before long they''re more than just friends. Will Mrs. Baker''s incessant meddling destroy Don and Jill''s budding relationship?', '1972-07-06', 6.76, 'https://image.tmdb.org/t/p/w500/qCBy94qp7D6tGspX3M0ZbkGPQ1g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55244, 'Bill Cunningham New York', 'Doubling as a cartography of the ever-changing city, Bill Cunningham New York portrays the secluded pioneer of street fashion with grace and heart.', '2011-03-16', 7.56, 'https://image.tmdb.org/t/p/w500/ex1m4lIAcdxJLBojN90fD3HoxlU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55177, 'Touch of Pink', 'Alim is a gay man living in London to escape the domineering eye of his conservative Muslim mother, Nuru, back in Canada. Alim keeps his homosexuality secret from his mother, so when she comes for a surprise visit, he and his boyfriend, Giles, must put on a straight facade to hide the truth.', '2004-07-16', 6.10, 'https://image.tmdb.org/t/p/w500/8FIovz3tPvxXvBY0bySbuo6cbwD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55306, 'Ulee''s Gold', 'Third-generation Florida beekeeper Ulee Jackson may have gotten out of Vietnam alive, but he left a part of himself behind. Now he methodically tends his bees, carefully provides for his two grandchildren and keeps his emotions at bay. But when a long-buried secret threatens Ulee''s business and family, he is forced to break through his emotional walls and confront the terror of his wounded spirit.', '1997-06-13', 6.51, 'https://image.tmdb.org/t/p/w500/wMpZ7U7A0QHJptR9L573V3Y7SI0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55301, 'Alvin and the Chipmunks: Chipwrecked', 'Playing around while aboard a cruise ship, the Chipmunks and Chipettes accidentally go overboard and end up marooned in a tropical paradise. They discover their new turf is not as deserted as it seems.', '2011-12-14', 5.71, 'https://image.tmdb.org/t/p/w500/npOXWVoZyl8UrF2wtByHtfmsWSX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55347, 'Beginners', 'Oliver meets the irreverent and unpredictable Anna only months after his father Hal Fields has passed away. This new love floods Oliver with memories of his father, who, following the death of his wife of 44 years, came out of the closet at age 75 to live a full, energized, and wonderfully tumultuous gay life – which included a younger boyfriend.', '2011-06-03', 6.84, 'https://image.tmdb.org/t/p/w500/mAquHAmoBgZ1omUNdNsnGVNX74c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55370, 'The Thief of Paris', 'In turn-of-the-century Paris, Georges Randal is brought up by his wealthy uncle, who steals his inheritance. Georges hopes to marry his cousin Charlotte, but his uncle arranges for her to marry a rich neighbour. In retaliation, Georges steals the fiancé''s family jewels, and enjoys the experience so much that he embarks upon a lifetime of burglary.', '1967-02-22', 6.70, 'https://image.tmdb.org/t/p/w500/tPEDn3u2q8q82kREjiGKmfA7rPm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55420, 'Another Earth', 'On the night a duplicate Earth is discovered in the solar system, the lives of a young woman and an accomplished composer become tragically connected after a fatal accident.', '2011-07-22', 6.71, 'https://image.tmdb.org/t/p/w500/qvGJK3lFzpifAdyIupMNdWNX0qr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55465, 'A Very Harold & Kumar Christmas', 'Six years have elapsed since Guantanamo Bay, leaving Harold and Kumar estranged from one another with very different families, friends and lives. But when Kumar arrives on Harold''s doorstep during the holiday season with a mysterious package in hand, he inadvertently burns down Harold''s father-in-law''s beloved Christmas tree. To fix the problem, Harold and Kumar embark on a mission through New York City to find the perfect Christmas tree, once again stumbling into trouble at every single turn.', '2011-11-04', 5.99, 'https://image.tmdb.org/t/p/w500/cncxLilRHKayn8VKhzjAMHkbN4f.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53879, 'Love Is a Many-Splendored Thing', 'A widowed doctor of both Chinese and European descent falls in love with a married American correspondent in Hong Kong during China''s Communist revolution.', '1955-08-18', 6.05, 'https://image.tmdb.org/t/p/w500/a9aqlitzVeo5fq6UX5Ekl5kopco.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55495, 'Noin 7 veljestä', 'The greedy lord of the manor, von Wurstburg, lives lavishly on his estate, heavily taxing the local peasants, when the official heir to the estate, the noble Sir William, arrives. At the same time, the mysterious outlaw Robin Hood, who helps the poor, sets up camp in the nearby woods. When the estate threatens to fall into Sir William''s hands and the peasants rise up against von Wurstburg''s excesses in Robin Hood''s footsteps, the lord finds himself in a double bind.', '1968-08-23', 6.30, 'https://image.tmdb.org/t/p/w500/ae8uVEoQlk7nK6fhpFykVIeeHcM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55551, 'Lumumba', 'The true story of the rise to power and brutal assassination of the formerly vilified and later redeemed leader of the independent Congo, Patrice Lumumba. Using newly discovered historical evidence, Haitian-born and later Congo-raised writer and director Raoul Peck renders an emotional and tautly woven account of the mail clerk and beer salesman with a flair for oratory and an uncompromising belief in the capacity of his homeland to build a prosperous nation independent of its former Belgian overlords. Lumumba emerges here as the heroic sacrificial lamb dubiously portrayed by the international media and led to slaughter by commercial and political interests in Belgium, the United States, the international community, and Lumumba''s own administration; a true story of political intrigue and murder where political entities, captains of commerce, and the military dovetail in their quest for economic and political hegemony.', '2000-09-27', 6.79, 'https://image.tmdb.org/t/p/w500/evopdRBKjj85zttxMcrZ5xujaS8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54287, 'Hangar 18', 'During a Space Shuttle mission a satellite rams a unidentified flying object. The UFO afterwards performs an emergency landing in the deserts of Arizona. However the White House denies its existence because of the near presidential elections. The UFO is brought to the secret Hangar 18 and the accident is blamed on the incompetence of the astronauts Bancroff and Price. But the two fight against this and try to hunt down the UFO.', '1980-07-01', 5.18, 'https://image.tmdb.org/t/p/w500/kORjGwOggAmJb0r5l8xoapXiBTW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52451, 'The Three Musketeers', 'The hot-headed young D''Artagnan along with three former legendary but now down on their luck Musketeers must unite and defeat a beautiful double agent and her villainous employer from seizing the French throne and engulfing Europe in war.', '2011-08-31', 5.79, 'https://image.tmdb.org/t/p/w500/woCADkkDIIKrOMEokbFOEsAYtUa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (53961, 'Brainstorm', 'Neto is a middle class teenager living a normal life. After his father finds a marijuana cigarette on his pocket, he is sent to a mental institution, where he gets to know a completely absurd and inhumane reality in which people are devoured by a corrupt and cruel system.', '2001-06-22', 7.90, 'https://image.tmdb.org/t/p/w500/x6NXI2jvi9iKbzjjHRMtZ7mCPjB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55741, 'Sacrifice', 'For generations the Zhao family has wielded power, until their mortal enemy TU’AN GU slaughters the entire clan, determined to wipe out their influence forever. But one Zhao baby survives hidden by CHENG YING the doctor who delivered him. When Tu’an Gu learns of the baby’s escape he seizes every infant in the city, vowing to kill them all unless the Zhao baby is surrendered. As the tyrant’s soldiers arrive at Cheng Ying’s home the frantic doctor hides his wife with their own baby whilst surrendering the Zhao child as his own. But his family is discovered; his baby is presumed to be the Zhao heir and murdered along with his wife for harboring the infant. Now set on revenge Cheng Ying enrolls the Zhao orphan into the service of the Tu’an Gu household, plotting to use him as an instrument of vengeance when he comes of age.', '2010-12-17', 6.00, 'https://image.tmdb.org/t/p/w500/36HScOStUVBOydrQwofZwrG3CUE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55504, 'Go Figure', 'Katelin Kingsford, an Olympic hopeful figure skater wants to train with a Russian figure skating coach. In order to go to go to the school that Natasha is at, Katelin gets a scholarship playing on the girls hockey team.', '2005-06-10', 6.04, 'https://image.tmdb.org/t/p/w500/3ngHrgIt33g0IEjl7rvzGLQ8wpj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54138, 'Star Trek Into Darkness', 'When the crew of the Enterprise is called back home, they find an unstoppable force of terror from within their own organization has detonated the fleet and everything it stands for, leaving our world in a state of crisis.  With a personal score to settle, Captain Kirk leads a manhunt to a war-zone world to capture a one man weapon of mass destruction. As our heroes are propelled into an epic chess game of life and death, love will be challenged, friendships will be torn apart, and sacrifices must be made for the only family Kirk has left: his crew.', '2013-05-05', 7.32, 'https://image.tmdb.org/t/p/w500/Aim3kVNh1MPIxPEFeJrl9e9Uf1a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55785, 'Neds', 'NEDs (Non Educated Delinquents) is the story of a young man’s journey from prize-winning schoolboy to knife-carrying teenager. Struggling against the low expectations of those around him, John McGill changes from victim to avenger, scholar to NED, altar boy to glue sniffer. When he attempts to change back again, his new reality and recent past make conformity near impossible and violent self determination near inevitable.', '2010-10-08', 6.74, 'https://image.tmdb.org/t/p/w500/a964EBCChUHims8RxfU1LC0rws0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52454, 'Mega Shark vs. Crocosaurus', 'When the prehistoric warm-water beast the Crocosaurus crosses paths with that cold-water monster the Mega Shark, all hell breaks loose in the oceans as the world''s top scientists explore every option to halt the aquatic frenzy. Swallowing everything in their paths -- including a submarine or two -- Croc and Mega lead an explorer and an oceanographer on a wild chase. Eventually, the desperate men turn to a volcano for aid.', '2010-12-21', 3.91, 'https://image.tmdb.org/t/p/w500/Y2nVRQWMjmtdqZ6zzo3CuvVDFa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55787, 'Water for Elephants', 'In this captivating Depression-era melodrama, impetuous veterinary student Jacob Jankowski joins a celebrated circus as an animal caretaker but faces a wrenching dilemma when he''s transfixed by angelic married performer Marlena.', '2011-04-15', 6.93, 'https://image.tmdb.org/t/p/w500/8T7Hvb9trKvCAmbSI8cEIU0Sl2T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55892, 'Mezzo Forte', 'The target of hitgirl Mikura is a wealthy baseball team owner, but he turns out to be a powerful underworld boss. Mikura and her team are beset by countless heavily armed bodyguards and the boss'' vicious daughter.', '2000-05-25', 6.51, 'https://image.tmdb.org/t/p/w500/f8VfbivexOy6ZUZTrqZsHz2vRPU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55561, 'Clockwatchers', 'Four female temps working for a credit company find their friendship threatened by the arrival of a new hire, who lands a permanent position one of the women was vying for.', '1997-06-12', 6.20, 'https://image.tmdb.org/t/p/w500/s6Gm06rGhopHumkAiYkJ4DsdaK8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54178, 'The One-Armed Swordsman', 'A noble swordsman, whose arm had been chopped off, returns to his former teacher to defend him from a villainous gang of rival swordsmen.', '1967-07-26', 6.88, 'https://image.tmdb.org/t/p/w500/5uUwl2cB4O7NmDFsKCmZkYTtVGO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52758, 'You Only Live Once', 'Based partially on the story of Bonnie and Clyde, Eddie Taylor is an ex-convict who cannot get a break after being released from prison. When he is framed for murder, Taylor is forced to flee with his wife Joan Graham and baby. While escaping prison after being sentenced to death, Taylor becomes a real murderer, condemning himself and Joan to a life of crime and death on the road.', '1937-01-23', 7.08, 'https://image.tmdb.org/t/p/w500/v8LSkezS7MvSk88SD6JbPO6VobD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (52654, 'The Luzhin Defence', 'Based upon the novel by Vladimir Nabokov, a chess grandmaster travels to Italy in the 1920s to play in a tournament and falls in love.', '2000-08-21', 6.33, 'https://image.tmdb.org/t/p/w500/tVV3PhTO58R0CAsvWhsUkYDzIEZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56179, 'Triumph of the Spirit', 'During World War II, Salamo Arouch, a passionate boxer, is arrested and sent to a concentration camp. Soon, he is forced to box against his fellow prisoners for the sake of entertainment.', '1989-12-08', 6.50, 'https://image.tmdb.org/t/p/w500/dxaSARmpCiFOCaxwGvjYAXMYPE4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54271, 'The Big Bang', 'A private detective is hired to find a missing stripper but the job turns complicated when everyone he questions ends up dead. From the mean streets of Los Angeles to the desolate desert of New Mexico, Cruz must contend with a brutal Russian Boxer, three brash LAPD detectives, an aged billionaire looking for the Big Bang, and the billionaire''s stunningly gorgeous wife. The solution to the mystery will cost ten lives, net $30 million and just might explain - well - everything.', '2011-02-03', 5.30, 'https://image.tmdb.org/t/p/w500/hDBDk1wWOQ7PYSaGKbv8dEsFVYB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56235, 'Return with Honor', 'The story of U.S. fighter pilots shot down over North Vietnam who became POWs for up to 8 and a half years.', '1999-06-11', 7.14, 'https://image.tmdb.org/t/p/w500/89289dPlOMOIWTZtIhy4qHhBQpb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56272, 'Elektra Luxx', 'A favor for a woman from her past throws the life of a pregnant, retired porn star into chaos.', '2011-03-11', 4.76, 'https://image.tmdb.org/t/p/w500/eLv57AjGugpx2shfaq9crEBVioL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56292, 'Mission: Impossible - Ghost Protocol', 'Ethan Hunt and his team are racing against time to track down a dangerous terrorist named Hendricks, who has gained access to Russian nuclear launch codes and is planning a strike on the United States. An attempt to stop him ends in an explosion causing severe destruction to the Kremlin and the IMF to be implicated in the bombing, forcing the President to disavow them. No longer being aided by the government, Ethan and his team chase Hendricks around the globe, although they might still be too late to stop a disaster.', '2011-12-07', 7.11, 'https://image.tmdb.org/t/p/w500/eRZTGx7GsiKqPch96k27LK005ZL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54293, 'Zeitgeist: Moving Forward', 'A presentation of a case for a needed transition out of the current socioeconomic monetary paradigm which governs the entire world society. This subject matter will transcend the issues of cultural relativism and traditional ideology and move to relate the core, empirical ''life ground'' attributes of human and social survival, extrapolating those immutable natural laws into a new sustainable social paradigm called a ''Resource-Based Economy''.', '2011-01-15', 7.02, 'https://image.tmdb.org/t/p/w500/i4zMQlaVc4NCTj5RQTR4AhppPoC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56428, 'Beyond Bedlam', 'An experiment gone awry places a neurologist and a homicide detective in a psychopath''s nightmarish world.', '1994-04-22', 5.10, 'https://image.tmdb.org/t/p/w500/hUmcO6Co4Vl3AFwg5fSnng9xnF5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56590, 'All Star Superman', 'Lex Luthor enacts his plan to rid the world of Superman, once and for all. Succeeding with solar radiation poisoning, the Man of Steel is slowly dying. With what little times remains, the Last Son of Krypton must confront the revealing of his secret identity to Lois Lane and face Luthor in a final battle.', '2011-01-01', 6.88, 'https://image.tmdb.org/t/p/w500/cfVEMf0JgFEIG5i4gKHVac0CA2y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56715, 'Just Visiting', 'A knight and his valet are plagued by a witch, and to repair the damage they make use of the services of a wizard. However, something goes wrong and they are transported from the 12th century to the year 2000. There the knight meets some of his family and slowly learns what this new century is like. However, he still needs to get back to the 12th century to deal with the witch, so he starts looking for a wizard. Remake of  1993 French film Les Visiteurs (The Visitors).', '2001-04-06', 4.77, 'https://image.tmdb.org/t/p/w500/7KqzbefXjADSUE8j2ZsrudvAArY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56780, 'Atlas Shrugged: Part I', 'A powerful railroad executive, Dagny Taggart, struggles to keep her business alive while society is crumbling around her. Based on the 1957 novel by Ayn Rand.', '2011-04-14', 5.47, 'https://image.tmdb.org/t/p/w500/tYfZIQb6ZabSUy1s1TRqSrYaAoM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56831, 'The Sunset Limited', 'A deeply religious black ex-con thwarts the suicide attempt of an asocial white college professor who tries to throw himself in front of an oncoming subway train, ''The Sunset Limited.'' As the one attempts to connect on a rational, spiritual and emotional level, the other remains steadfast in his hard-earned despair. Locked in a philosophical debate, both passionately defend their personal credos and try to convert the other.', '2011-02-12', 7.22, 'https://image.tmdb.org/t/p/w500/8cwqylJVbCfMflcjXQ71CwsXdpf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56909, 'The Immature', 'Six high school friends in their 40s who haven''t seen each other in nearly 20 years rekindle their younger selves after a court cancels their diploma, forcing them to repeat the final high school exam.', '2011-01-21', 6.20, 'https://image.tmdb.org/t/p/w500/n97HpLLs6flPoxK1VVPMKN2Bc32.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57022, 'Sunshine State', 'A woman and her new husband returns to her hometown roots in coastal northern Florida, and must deal with family, business, and encroaching real estate development.', '2002-06-21', 6.42, 'https://image.tmdb.org/t/p/w500/8OsgdG53vzF5uC8pCE61SA1tiNF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57157, 'Young Adult', 'A divorced writer from the Midwest returns to her hometown to reconnect with an old flame, who''s now married with a family.', '2011-11-11', 5.80, 'https://image.tmdb.org/t/p/w500/4tGMz5xUs9sk8X9B28G6UalHK1d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57165, 'Wrath of the Titans', 'Perseus tries to live a quieter life as a village fisherman while – dangerously weakened by humanity''s lack of devotion – the gods are losing control of the long-imprisoned Titans and their ferocious leader, Kronos.', '2012-03-28', 5.77, 'https://image.tmdb.org/t/p/w500/b9n2R3xZWQ8MVZgndQoV34stS0h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55596, 'Christmas in Connecticut', 'Elizabeth is the star of a successful cooking show and author of several cookbooks. But when her manager, Alexander sees forest ranger Jefferson, who lost his cabin in a fire, comment on TV about wishing he could get a home-cooked Christmas dinner, he arranges for a special live show on Christmas, for Elizabeth to cook him Christmas Dinner. Only Elizabeth can''t cook, and trying to keep Jefferson and the viewing public from finding out on a live show may be a little difficult.', '1992-12-22', 4.72, 'https://image.tmdb.org/t/p/w500/Alwn4aKfVwqHPNYcUMNuuvZSlE6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54186, 'Confessions', 'Devastated at the death of her four-year-old daughter, a grieving middle school teacher is horrified to discover that her students aren''t as innocent as she thinks.', '2010-06-04', 7.58, 'https://image.tmdb.org/t/p/w500/xn98VCLMcF6TulxsKJq2EQ8WYL2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57158, 'The Hobbit: The Desolation of Smaug', 'The Dwarves, Bilbo and Gandalf have successfully escaped the Misty Mountains, and Bilbo has gained the One Ring. They all continue their journey to get their gold back from the Dragon, Smaug.', '2013-12-11', 7.58, 'https://image.tmdb.org/t/p/w500/xQYiXsheRCDBA39DOrmaw1aSpbk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57201, 'The Lone Ranger', 'The Texas Rangers chase down a gang of outlaws led by Butch Cavendish, but the gang ambushes the Rangers, seemingly killing them all. One survivor is found, however, by an American Indian named Tonto, who nurses him back to health. The Ranger, donning a mask and riding a white stallion named Silver, teams up with Tonto to bring the unscrupulous gang and others of that ilk to justice.', '2013-07-03', 6.13, 'https://image.tmdb.org/t/p/w500/yDuJGq8biNMW7zM3w95UaDJv0KG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57212, 'War Horse', 'On the brink of the First World War, Albert''s beloved horse Joey is sold to the Cavalry by his father. Against the backdrop of the Great War, Joey begins an odyssey full of danger, joy, and sorrow, and he transforms everyone he meets along the way. Meanwhile, Albert, unable to forget his equine friend, searches the battlefields of France to find Joey and bring him home.', '2011-12-25', 7.30, 'https://image.tmdb.org/t/p/w500/3aRHhvvngFPJFy5uAjo7GVr3PhL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57214, 'Project X', 'Three high school seniors throw a party to make a name for themselves. As the night progresses, things spiral out of control as word of the party spreads.', '2012-03-01', 6.92, 'https://image.tmdb.org/t/p/w500/lUPDGT3lyRrq8SvWuNWG2DP64bR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55931, 'The Animatrix', 'Straight from the creators of the groundbreaking Matrix trilogy, this collection of short animated films from the world''s leading anime directors fuses computer graphics and Japanese anime to provide the background of the Matrix universe and the conflict between man and machines. The shorts include Final Flight of the Osiris, The Second Renaissance, Kid''s Story, Program, World Record, Beyond, A Detective Story and Matriculated.', '2003-05-09', 7.22, 'https://image.tmdb.org/t/p/w500/eDjIG2hAeMU5cxLrd6oiQqdqoZt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57361, 'The Yellow Sea', 'A Korean man in China takes an assassination job in South Korea to make money and find his missing wife. But when the job is botched, he is forced to go on the run from the police and the gangsters who paid him.', '2010-12-22', 7.34, 'https://image.tmdb.org/t/p/w500/yPJMDxam5HP0DAc1rMk0aNRpSc5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57243, 'The Women on the 6th Floor', 'Paris, in the early 1960s. Jean-Louis Joubert is a serious but uptight stockbroker, married to Suzanne, a starchy class-conscious woman and father of two arrogant teenage boys, currently in a boarding school. The affluent man lives a steady yet boring life. At least until, due to fortuitous circumstances, Maria, the charming new maid at the service of Jean-Louis'' family, makes him discover the servants'' quarter on the sixth floor of the luxury building he owns and lives in. There live a crowd of lively Spanish maids who will help Jean-Louis to open to a new civilization and a new approach of life. In their company - and more precisely in the company of beautiful Maria - Jean-Louis will gradually become another man, a better man.', '2011-02-16', 6.75, 'https://image.tmdb.org/t/p/w500/88875SqNHpwslXXa5WtDA3VnOvn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57834, 'Blue Sky', 'Hank Marshall is a tough, square-jawed, straitlaced Army engineer and nuclear science expert, assigned to help conduct weapons testing in 1950s America. Hank has become a thorn in the side of the Army, though, for a couple of very different reasons. He is an outspoken opponent of atmospheric testing, though his superiors hold contrary views and want to squelch his concerns...and his reports. The other problem is his wife, Carly. She is voluptuous and volatile, wreaking havoc in his personal life and stirring up intrigue at each new Army base.', '1994-09-16', 6.07, 'https://image.tmdb.org/t/p/w500/zG40OnO4Y98lo1iDHyFo5TaZyP1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57800, 'Ice Age: Continental Drift', 'Manny, Diego, and Sid embark upon another adventure after their continent is set adrift. Using an iceberg as a ship, they encounter sea creatures and battle pirates as they explore a new world.', '2012-06-27', 6.39, 'https://image.tmdb.org/t/p/w500/dfp1BZF7FxbBUyzHvMOI9t8NWDD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55955, 'My Son the Fanatic', 'Pakistani taxi-driver Parvez and prostitute Bettina find themselves trapped in the middle when Islamic fundamentalists decide to clean up their local town.', '1997-10-21', 5.00, 'https://image.tmdb.org/t/p/w500/34rfjIEVqmzjN7HMZhrrPgPaHuE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57976, 'Little Dieter Needs to Fly', 'Three decades after German-American pilot Dieter Dengler was shot down over Laos, he returns to the places where he was held prisoner during the early years of the Vietnam War. Accompanied by director Werner Herzog, Dengler describes in unusually candid detail his captivity, the friendships he made, and his daring escape. Not willing to stop there, Herzog even persuades his subject to re-enact certain tortures, with the help of some willing local villagers.', '1997-12-01', 7.47, 'https://image.tmdb.org/t/p/w500/2sLpyYytu0Dbymzs3skxOCRHKkl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54302, 'Royal Flash', 'Cowardly rogue Harry Flashman''s (Malcolm McDowell) schemes to gain entry to the royal circles of 19th-century Europe go nowhere until he meets a pair of devious nobles with their own agenda. At their urging, Flashman agrees to re-create himself as a bogus Prussian nobleman to woo a beautiful duchess. But the half-baked plan quickly comes unraveled, and he''s soon on the run from several new enemies who are all calling for the rapscallion''s head.', '1975-10-10', 5.80, 'https://image.tmdb.org/t/p/w500/rx5DYndn3ua5Pe3yz492kqERH19.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55721, 'Bridesmaids', 'Annie''s life is a mess. But when she finds out her lifetime best friend is engaged, she simply must serve as Lillian''s maid of honor. Though lovelorn and broke, Annie bluffs her way through the expensive and bizarre rituals. With one chance to get it perfect, she’ll show Lillian and her bridesmaids just how far you’ll go for someone you love.', '2011-05-13', 6.51, 'https://image.tmdb.org/t/p/w500/gJtA7hYsBMQ7EM3sPBMUdBfU7a0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58048, 'Shanghai Surprise', 'Glendon Wasey is a fortune hunter looking for a fast track out of China. Gloria Tatlock is a missionary nurse seeking the curing powers of opium for her patients. Fate sets them on a hectic, exotic, and even romantic quest for stolen drugs. But they are up against every thug and smuggler in Shangai.', '1986-08-29', 4.29, 'https://image.tmdb.org/t/p/w500/8zsU3Vq9FG9Q0kTEYrl0CWDlvX2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58062, 'Into the Arms of Strangers: Stories of the Kindertransport', 'In the nine months prior to World War II, 10.000 innocent children left behind their families, their homes, their childhood, and took the journey... to Britain to escape the Nazi Holocaust.', '2000-09-15', 7.43, 'https://image.tmdb.org/t/p/w500/9vNRpMYT5H9L9UYf6Yq17isnQem.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54405, 'Hear My Song', 'Singer Josef Locke fled to Ireland 25 years ago to escape the clutches of the tax man and police Chief Jim Abbott. What he also left behind was the love of his life Cathleen Doyle. Now, Micky O’Neill is desperate to save both his ailing Liverpool nightclub ‘Heartly’s’ and his failing relationship with the beautiful Nancy, Cathleen’s daughter. The solution? Book the infamous Josef Locke.', '1991-12-27', 5.86, 'https://image.tmdb.org/t/p/w500/xD8hh10Atodan4tzYg3K2QFCrJ1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55667, 'Carnosaur 3: Primal Species', 'International terrorists get a surprise when their cargo turns out to contain living dinosaurs. The army commando team now have to think fast, if they want to prevent the extinction of the human species, instead of the reptiles.', '1996-11-21', 4.04, 'https://image.tmdb.org/t/p/w500/lPyp6ukHtpsOr4S0R4Pphgpp1IB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57978, 'Meantime', 'A working-class family in London''s East End is struggling to stay afloat during the recession under Prime Minister Margaret Thatcher''s premiership. Only the mother Mavis is working; father Frank and the couple''s two sons Colin, a timid, chronically shy individual and Mark, an outspoken, headstrong young man, are on the dole. This situation is contrasted by the presence of Mavis''s sister Barbara, and her husband John, whose financial and social loftiness appears to be a comfortable facade over the unspoken soreness of a lackluster marriage.', '1983-10-16', 6.72, 'https://image.tmdb.org/t/p/w500/aYeCvrkgUCylSQwmMFcqXV27WvD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58151, 'Fright Night', 'A teenager suspects his new neighbour is a vampire. Unable to convince anyone, he tries to enlist the help of a self-proclaimed vampire hunter and magician.', '2011-08-18', 6.25, 'https://image.tmdb.org/t/p/w500/ySQ3v4Fzpy3fePs86eoLiDzwLYM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (56137, 'I Know Where I''m Going!', 'Plucky Englishwoman Joan Webster travels to the remote islands of the Scottish Hebrides in order to marry a wealthy industrialist. Trapped by inclement weather on the Isle of Mull and unable to continue to her destination, Joan finds herself charmed by the straightforward, no-nonsense islanders around her, and becomes increasingly attracted to naval officer Torquil MacNeil, who holds a secret that may change her life forever.', '1945-11-16', 7.09, 'https://image.tmdb.org/t/p/w500/woAOLgYVUmLBtWNxTJgAnqGwyuL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57431, 'The Sitter', 'Noah, is not your typical entertain-the-kids-no-matter-how-boring-it-is kind of sitter. He''s reluctant to take a sitting gig; he''d rather, well, be doing anything else, especially if it involves slacking. When Noah is watching the neighbor''s kid he gets a booty call from his girlfriend in the city. To hook up with her, Noah takes to the streets, but his urban adventure spins out of control as he finds himself on the run from a maniacal drug lord.', '2011-12-09', 5.57, 'https://image.tmdb.org/t/p/w500/jlGzZ8McDp73PAaWMeYCHWeHiM4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55725, 'Win Win', 'When down-on-his-luck part-time high school wrestling coach Mike agrees to become legal guardian to an elderly man, his ward''s troubled grandson turns out to be a star grappler, sparking dreams of a big win -- until the boy''s mother retrieves him.', '2011-03-18', 6.82, 'https://image.tmdb.org/t/p/w500/xX0Ryq5J2weFF5BPYb80giKUL02.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57586, 'African Cats', 'African Cats captures the real-life love, humor and determination of the majestic kings of the savanna. The story features Mara, an endearing lion cub who strives to grow up with her mother’s strength, spirit and wisdom; Sita, a fearless cheetah and single mother of five mischievous newborns; and Fang, a proud leader of the pride who must defend his family from a once banished lion.', '2011-04-21', 7.32, 'https://image.tmdb.org/t/p/w500/nERPMF2kHjc1slLHZYZGwcWX9kg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (54318, 'The Water Horse', 'A lonely boy discovers a mysterious egg that hatches a sea creature of Scottish legend.', '2007-12-25', 6.54, 'https://image.tmdb.org/t/p/w500/h9DV6KItNutJmrPzT1xrAO6fIzy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58428, 'The Innkeepers', 'During the final days at the Yankee Pedlar Inn, two employees determined to reveal the hotel''s haunted past begin to experience disturbing events as old guests check in for a stay.', '2012-02-03', 5.37, 'https://image.tmdb.org/t/p/w500/aC9XHtf0Opw2IJDVjSkL8eO71An.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57778, 'Unbelievable Adventures of Italians in Russia', 'In Italy, a dying woman tells her granddaughter that she hid her treasure many years ago in Russia, in the city of Leningrad. As more people learn about it, they head to Leningrad to find the lion where it is rumoured to be buried.', '1974-01-31', 7.25, 'https://image.tmdb.org/t/p/w500/51iIpaPeoVj8yCo92GpWzUnPIiM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58429, 'La Ciénaga', 'Amid the sweltering summer heat in northern Argentina, two middle-class families retreat to a crumbling country estate and a modest townhouse, where strained relationships, simmering tensions, and the presence of children and servants quietly expose the fractures of family life. Between idle days, gossip, and unspoken desires, the boundaries of class, tradition, and faith are reflected in their everyday interactions.', '2001-04-12', 6.85, 'https://image.tmdb.org/t/p/w500/fcgRKfCRudyWggyHIT9LOPgU3qW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58431, 'Pride and Prejudice and Zombies', 'A zombie outbreak has fallen upon the land in this reimagining of Jane Austen''s classic tale of the tangled relationships between lovers from different social classes in 19th century England. Feisty heroine Elizabeth Bennet is a master of martial arts and weaponry and the handsome Mr. Darcy is a fierce zombie killer, yet the epitome of upper class prejudice. As the zombie outbreak intensifies, they must swallow their pride and join forces on the blood-soaked battlefield in order to conquer the undead once and for all.', '2016-02-04', 6.17, 'https://image.tmdb.org/t/p/w500/jsJlOhVHiz1xXr36616EI8tJ4b2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58496, 'Senna', 'The remarkable story of Brazilian racing driver Ayrton Senna, charting his physical and spiritual achievements on the track and off, his quest for perfection, and the mythical status he has since attained, is the subject of Senna, a documentary feature that spans the racing legend''s years as an F1 driver, from his opening season in 1984 to his untimely death a decade later.', '2010-10-07', 8.11, 'https://image.tmdb.org/t/p/w500/nZbLCbRoP6iJq5sr8daHQzjnzFh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58447, 'Three Giant Men', 'Istanbul is being terrorized by a crime wave, and the police call in American superhero Captain America and Mexican wrestler Santo to put a stop to it.', '1973-11-01', 4.40, 'https://image.tmdb.org/t/p/w500/wAwzuwe5BGglw4WEdSViSKx02wZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58547, '10 Years', 'A group of friends reunite ten years after their high-school graduation.', '2012-09-14', 5.83, 'https://image.tmdb.org/t/p/w500/AuCM5jU751cMLKOtHybzUoL6RaX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58574, 'Sherlock Holmes: A Game of Shadows', 'There is a new criminal mastermind at large (Professor Moriarty) and not only is he Holmes’ intellectual equal, but his capacity for evil and lack of conscience may give him an advantage over the detective.', '2011-11-22', 7.15, 'https://image.tmdb.org/t/p/w500/2HsHurlnTOyU6yUS14gY6BQCyRs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58595, 'Snow White and the Huntsman', 'After the Evil Queen marries the King, she performs a violent coup in which the King is murdered and his daughter, Snow White, is taken captive. Almost a decade later, a grown Snow White is still in the clutches of the Queen. In order to obtain immortality, The Evil Queen needs the heart of Snow White. After Snow escapes the castle, the Queen sends the Huntsman to find her in the Dark Forest.', '2012-05-30', 5.98, 'https://image.tmdb.org/t/p/w500/8HUa5kRubYbnAD5UVpnhTGGgMTW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58102, 'Some Mother''s Son', 'Based on the true story of the 1981 hunger strike in a British prison, in which IRA prisoner Bobby Sands led a protest against the treatment of IRA prisoners as criminals rather than as prisoners of war. The film focuses on the mothers of two of the strikers, and their struggle to save the lives of their sons.', '1996-09-13', 6.77, 'https://image.tmdb.org/t/p/w500/ngy7zafrXEDCUOPfolcbFofMDmI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58699, 'Bellflower', 'Two friends spend all their free time building flame-throwers and weapons of mass destruction in hopes that a global apocalypse will occur and clear the runway for their imaginary gang "Mother Medusa".', '2011-04-16', 5.88, 'https://image.tmdb.org/t/p/w500/4bGB2k4JngWLVABKIw1S7cnlh5h.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58704, 'The Wonderful World of Puss ''n Boots', 'His goal is to help the weak and defenseless, but his saving a mouse makes him the most wanted in all the land. On the run from incessant, dim-witted mice, Perro befriends a young miller''s boy, Pierre; together, they decide to seek fame and fortune. When they cross paths with the lovely Princess Rosa, Perro determines to get Pierre hitched to Her Royal Highness.', '1969-03-18', 7.00, 'https://image.tmdb.org/t/p/w500/6TM68raRJOgfdyrlmToIjh8lHRs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58857, '13 Assassins', 'A bravado period action film set at the end of Japan''s feudal era in which a group of unemployed samurai are enlisted to bring down a sadistic lord and prevent him from ascending to the throne and plunging the country into a war-torn future.', '2010-09-25', 7.30, 'https://image.tmdb.org/t/p/w500/yUsVsiVXUwClk4vSCx80vrdO6MV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58770, 'The Trigger Effect', 'A blackout leaves those affected to consider what is necessary, what is legal, and what is questionable, in order to survive in a predatory environment.', '1996-08-30', 5.85, 'https://image.tmdb.org/t/p/w500/9LZLXVwhhmkdye4JXoLP06fm5G2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58878, 'Three Outlaw Samurai', 'Shiba, a wandering ronin, encounters a band of peasants who have kidnapped the daughter of their dictatorial magistrate, in hopes of coercing from him a reduction in taxes. Shiba takes up their fight, joined by two renegades from the magistrate''s guard, Sakura and Kikyo. The three outlaws find themselves in a battle to the death.', '1964-05-13', 7.46, 'https://image.tmdb.org/t/p/w500/5gHucIqPYxKzOhQxyEshbDtuU4m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58886, 'Everybody''s Famous!', 'Jean is a family man and factory worker who dreams of becoming a songwriter. Pinning his hopes on his teenage daughter, Marva, he takes her to singing contests in which the awkward and overweight girl struggles to belt out a tune. When Jean is suddenly fired because of cut backs, he is ashamed and even more desperate to have his daughter succeed. In a chance meeting Jean kidnaps the most famous pop star in the country and holds her hostage demanding to be heard by the music industry. Catching the attention of the media and the eyes of the nation, Jean and Marva realize that the show must go on until everyone is famous.', '2000-04-12', 5.50, 'https://image.tmdb.org/t/p/w500/iPVRGoOQ6N9sMYYJW8OLT2CqDnO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58985, 'Grace of My Heart', 'Philadelphia teenager Edna Buxton wins a talent contest during the early rock ''n'' roll era, changes her name to Denise Waverly and moves to New York City to make it big. Though she flops as a recording artist, fast-talking record producer Joel Millner recognizes her songwriting talent and teams her with struggling songsmith Howard Caszatt.', '1996-09-13', 6.04, 'https://image.tmdb.org/t/p/w500/fkgVjmbN9VdBxguNi6tz6lb3sDu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59006, 'Girl Walks Into a Bar', 'A sharp-witted comedy that follows a group of apparent strangers in interlocking stories taking place in ten different bars during the course of one evening throughout Los Angeles.', '2011-03-07', 5.13, 'https://image.tmdb.org/t/p/w500/t6Mr51fTqha0bVFUS8b8YAhxhyJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59045, 'Ro.Go.Pa.G.', 'Four short films by four different directors dealing with the principles of modern life. "Illibatezza" (Rossellini): The hostess Anna Maria, to dissuade an aggressive suitor who prefers maternal tendencies, assumes an unscrupulous attitude, obeying the suggestions of her distant boyfriend. "The New World" (Godard): The deflagration of an atomic bomb causes strange effects on the inhabitants of a city. "La ricotta" (Pasolini): During the filming of a film about a religious subject, the extra Stracci dies hanging on the cross due to an indigestion of ricotta. "Il pollo spante" (Gregoretti): While an expert illustrates to a board of merchants the most modern techniques to increase sales through the discovery of the secret self of the average consumer, the human story of a bourgeois who, following these suggestions, focuses on the purchase of a plot of land in the countryside.', '1963-02-19', 7.20, 'https://image.tmdb.org/t/p/w500/AjZgOidGeYN6ZGDHlwx1RZ9UFXV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59199, 'World Traveler', 'After hitting the road a man encounters characters that make him realize the importance of family.', '2002-04-19', 4.10, 'https://image.tmdb.org/t/p/w500/24d6LPAYXhudU8HAlxohPaVPRuL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59108, 'Tower Heist', 'A luxury condo manager leads a staff of workers to seek payback on the Wall Street swindler who defrauded them. With only days until the billionaire gets away with the perfect crime, the unlikely crew of amateur thieves enlists the help of petty crook Slide to steal the $20 million they’re sure is hidden in the penthouse.', '2011-11-02', 6.12, 'https://image.tmdb.org/t/p/w500/jQrroNwP8hbFiUlNMs20emauwPE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55728, 'Plain Clothes', 'To prove his brother''s innocence, undercover officer Nick enrolls in high school again, dealing with crushes, bullies, humiliations, popularity swings, and quirky teachers and staff to find the real murderer.', '1988-04-15', 5.76, 'https://image.tmdb.org/t/p/w500/coCA0gZObtGySSVLOPb784650ep.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59401, 'The Red Badge of Courage', 'Henry Fleming is a young Union soldier in the American Civil War. During his unit''s first engagement, Henry flees the battlefield in fear. When he learns that the Union actually won the battle, shame over his cowardice leads him to lie to his friend Tom and the other soldiers, saying that he had been injured in battle. However, when he learns that his unit will be leading a charge against the enemy, Henry takes the opportunity to face his fears and redeem himself.', '1951-09-27', 6.46, 'https://image.tmdb.org/t/p/w500/RKomX6ExUYMvlNcv2HjgupVKdS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59436, 'Midnight in Paris', 'While on a trip to Paris with his fiancée''s family, a nostalgic screenwriter finds himself mysteriously going back to the 1920s every day at midnight.', '2011-05-11', 7.51, 'https://image.tmdb.org/t/p/w500/4wBG5kbfagTQclETblPRRGihk0I.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59440, 'Warrior', 'The youngest son of an alcoholic former boxer returns home, where he''s trained by his father for competition in a mixed martial arts tournament – a path that puts the fighter on a collision course with his estranged, older brother.', '2011-09-09', 7.84, 'https://image.tmdb.org/t/p/w500/iM8n4nZJPR2abpnyZ36FUgHiRjr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58233, 'Johnny English Reborn', 'The most prominent heads of state in the world begin gathering for a conference that could have a major impact on global politics. When MI-7 receives word that the Chinese premier has become the target of some high-powered killers, it falls on Johnny English to save the day. Armed with the latest high-tech weaponry and gadgets that would make even James Bond jealous, the once-disgraced agent uncovers evidence of a massive conspiracy involving some of the world''s most powerful organisations, and vows to redeem his tarnished reputation by stopping the killers before they can strike.', '2011-09-15', 6.25, 'https://image.tmdb.org/t/p/w500/zDbrU0eSnRGh5gHc1iqTACTNNyT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59533, 'The Secret Policeman''s Other Ball', 'Following the success of the 1979 show and the financial benefits accruing to Amnesty from the spin-off movie, TV special and record albums – Cleese, Lewis and Walker planned the next show to be a more spectacular event. Cleese focused on broadening the comedic talent to be presented at the show. In addition to the Amnesty show stalwarts drawn from the Oxbridge/Monty Python/Beyond The Fringe orbit, he invited newcomers such as Rowan Atkinson’s colleagues from the BBC TV show Not the Nine O''Clock News including Pamela Stephenson and Griff Rhys Jones; comedian Victoria Wood and regional comic Jasper Carrott. Lewis secured a return appearance by Billy Connolly and a debut appearance by "alternative" comedian Alexei Sayle who Lewis had recently discovered and was managing. Building on the success of Pete Townshend''s 1979 appearance Lewis recruited other rock musicians to perform at the 1981 show including Sting, Phil Collins, Eric Clapton, Jeff Beck, Donovan and Bob Geldof.', '1982-03-01', 6.33, 'https://image.tmdb.org/t/p/w500/rUVxU66v4d8JrKoD41sVHbmIhsQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59678, 'Attack the Block', 'A South London teen gang must team up with the other residents of their housing estate to protect the neighbourhood from a terrifying alien invasion.', '2011-05-11', 6.46, 'https://image.tmdb.org/t/p/w500/wzCMnA6NDruLzgWeqMcLPDrGAdF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57825, 'Bride & Prejudice', 'Mrs. Bakshi is eager to find suitors for her four unmarried daughters when a family friend introduces them to handsome American Will Darcy. A Bollywood-style modern adaptation of Jane Austen''s classic novel.', '2004-02-11', 6.48, 'https://image.tmdb.org/t/p/w500/yqqo00GZqyG0dijKCqBbdQLUvht.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59820, 'Come See the Paradise', 'In this drama from director Alan Parker, on-the-lam Jack McGurn flees to Los Angeles and takes a job as a projectionist at a movie theater owned by a Japanese-American man. Jack falls for the owner''s daughter, Lily, but they are forced to elope to Seattle when her father forbids the relationship. The couple marry and have a daughter, but when World War II breaks out, Jack is powerless to stop his new family''s forced internment.', '1990-08-17', 6.25, 'https://image.tmdb.org/t/p/w500/uBdJXVfcQkhKBg2SfydhoTqtcBr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58224, 'Mr. Popper''s Penguins', 'Tom Popper is a successful businessman who’s clueless when it comes to the really important things in life...until he inherits six “adorable” penguins, each with its own unique personality. Soon Tom’s rambunctious roommates turn his swank New York apartment into a snowy winter wonderland — and the rest of his world upside-down.', '2011-06-17', 5.97, 'https://image.tmdb.org/t/p/w500/jGwZ1QI5DaL7mHQ2ZsMV1p8xvPS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59852, 'Blinky™', 'A story about a boy, his robot and the consequences of his anger at the disintegration of his parents marriage.', '2011-03-21', 6.80, 'https://image.tmdb.org/t/p/w500/7txYBBSjOHgGUi1CX9eaB7R4ppg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59859, 'Kick-Ass 2', 'After Kick-Ass'' insane bravery inspires a new wave of self-made masked crusaders, he joins a patrol led by the Colonel Stars and Stripes. When these amateur superheroes are hunted down by Red Mist — reborn as The Mother Fucker — only the blade-wielding Hit-Girl can prevent their annihilation.', '2013-07-17', 6.41, 'https://image.tmdb.org/t/p/w500/1go2A3gdQjaMuHWquybgoJlQRcX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55727, 'Making the Grade', 'Lazy preppie Palmer Woodrow hires street-smart Eddie Keaton to go to school for him while he lives it up in Europe. Eddie falls in love with preppie gal Tracey, upsetting Biff, the Hoover Academy bully. When his bookie from the old neighborhood, Dice, comes to collect on Eddie''s gambling debts and Palmer returns early from Europe, the scheme slowly starts to unravel. Soon, Eddie can''t even tell whose side he''s really on.', '1984-05-18', 5.10, 'https://image.tmdb.org/t/p/w500/mihPxIkGvGPzDgi1fMrE6cx5Ykq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57946, 'Margaret Cho: Notorious C.H.O.', 'A film of Margaret Cho''s one-woman stand-up show, in which she presents her take on modern sexual topics and minority issues. Filmed live.', '2002-06-29', 5.65, 'https://image.tmdb.org/t/p/w500/o3aHEzVZ16Vm8jMs4lcuAlVGdo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55779, 'Final Destination 5', 'Death is just as omnipresent as ever, and is unleashed after one man’s premonition saves a group of coworkers from a terrifying suspension bridge collapse. But this group of unsuspecting souls was never supposed to survive, and, in a terrifying race against time, the ill-fated group frantically tries to discover a way to escape Death’s sinister agenda.', '2011-08-12', 6.16, 'https://image.tmdb.org/t/p/w500/Akx1Po4ZLetOWfYJhQf75tbhTtK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58244, 'Upside Down', 'In an alternate universe where twinned worlds have opposite gravities, a young man battles interplanetary prejudice and the laws of physics in his quest to reunite with the long-lost girl of his dreams in this visually stunning romantic adventure that poses the question: what if love was stronger than gravity?', '2012-09-27', 6.28, 'https://image.tmdb.org/t/p/w500/wImo0dC72HRoI5QO85dGavmxW6q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55773, 'Man on the Flying Trapeze', 'Hard-working, henpecked Ambrose Ambrose Wolfinger takes off from work to go to a wrestling match with catastrophic consequences.', '1935-08-03', 6.24, 'https://image.tmdb.org/t/p/w500/aWpVoEuVxW6DvbRW03AAULAvB2e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59861, 'Larry Crowne', 'When he suddenly finds himself without his long-standing blue-collar job, Larry Crowne enrolls at his local college to start over. There, he becomes part of an eclectic community of students and develops a crush on his teacher.', '2011-06-30', 6.00, 'https://image.tmdb.org/t/p/w500/8GDM7RqM6J1vNUdlU94rmtlNa3e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59968, 'Our Idiot Brother', 'Everybody has one—the sibling who is always just a little bit behind the curve when it comes to getting his life together. For sisters Liz, Miranda and Natalie, that person is their perennially upbeat brother, Ned. But as each of their lives begins to unravel, Ned''s family comes to realise that Ned isn''t such an idiot after all.', '2011-08-26', 6.12, 'https://image.tmdb.org/t/p/w500/2HahJCcUEduvMUTQhsqRwutpFw1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (57855, 'Charlie, the Lonesome Cougar', 'A heartwarming Disney classic in which a cougar, who was rescued as a cub and raised by a group of loggers in the Pacific Northwest, reverts back to his natural instincts, leading to hilarious (and dangerous) consequences.', '1967-10-18', 5.95, 'https://image.tmdb.org/t/p/w500/7Nx00VscGdcPsa1PmjmwwMxLe3F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60033, 'This World, Then the Fireworks', 'In 1950s, two incestuous lovers, a depraved suave journalist and his equally depraved prostitute sister, plan to get rich through seduction and murder.', '1997-07-11', 5.20, 'https://image.tmdb.org/t/p/w500/vXO9T4rbJFVRF6BbABHe7VKJdj9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60243, 'A Separation', 'A married couple are faced with a difficult decision – to improve the life of their child by moving to another country or to stay in Iran and look after a deteriorating parent who has Alzheimer''s disease.', '2011-02-15', 7.91, 'https://image.tmdb.org/t/p/w500/xQadpnoLokxzN3hRpCPbBGpxsiz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55846, 'Blitz', 'A tough cop is dispatched to take down a serial killer who has been targeting police officers.', '2011-05-20', 6.17, 'https://image.tmdb.org/t/p/w500/qjqmhhc7uLub22mhu4V6DjOBwXM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60276, 'Scenes from the Class Struggle in Beverly Hills', 'A wealthy Beverly Hills resident who has just become a widow, Clare Lipkin temporarily takes on her friend Lisabeth as a house guest. As the two women deal with their upper-class woes, Clare''s driver, Frank, and Lisabeth''s servant, Juan, make a wager to see who can be the first to seduce the other''s boss.', '1989-06-09', 5.40, 'https://image.tmdb.org/t/p/w500/4Q8yE7ijikNXWItWnAJkjt9yWvn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60285, 'Alvarez Kelly', 'In 1864, during the American Civil War, Mexican cattleman Alvarez Kelly supplies the Union with cattle until unexpected circumstances force him to change his customers.', '1966-10-06', 6.16, 'https://image.tmdb.org/t/p/w500/6kIcuVMyJJKmxy7bFbI9q1DWByR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (55903, 'Betty Fisher and Other Stories', 'When bestselling novelist Betty Fisher loses her young son in a tragic accident, her unstable mother resorts to unusual actions to alleviate Betty''s grief, actions which set off a chain reaction among a promiscuous waitress and her criminal associates.', '2001-09-01', 6.13, 'https://image.tmdb.org/t/p/w500/ebo9Tgo8IYMmV7evHKEPXeKa7PQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60293, 'Tom and Jerry: Shiver Me Whiskers', 'Dueling cat-and-mouse team Tom and Jerry hit the high seas on a hunt for buried treasure in this pirate adventure. The tale begins when crew member Tom sets sail with an infamous pirate and finds a treasure map along with stowaway Jerry. The furry swashbucklers race to a deserted island where X marks the spot, but along with battling each other, they must outwit ruthless buccaneers, angry monkeys and a giant octopus to strike it rich.', '2006-08-21', 6.88, 'https://image.tmdb.org/t/p/w500/8kJT2PQXBdLvT7jimzgxQFWXPBK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60304, 'Hansel & Gretel: Witch Hunters', 'After getting a taste for blood as children, Hansel and Gretel have become the ultimate vigilantes, hell-bent on retribution. Now, unbeknownst to them, Hansel and Gretel have become the hunted, and must face an evil far greater than witches... their past.', '2013-01-17', 6.11, 'https://image.tmdb.org/t/p/w500/j343Rpj3WeNvP0SV80zveve70io.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60307, 'Diary of a Wimpy Kid: Rodrick Rules', 'Wimpy Greg Heffley, now in seventh grade, thinks he has it all together. He has mastered middle school and gotten rid of the Cheese Touch. However, Greg''s older brother, Rodrick, is itching to cut him down to size. He gets the perfect opportunity when their mother tries to force the boys to bond. Rodrick may be Greg''s chief tormentor, but he feels his constant pranks are just what his little brother needs to prepare him for life''s hard knocks.', '2011-03-25', 6.70, 'https://image.tmdb.org/t/p/w500/w77ZoDmHNf6lnk8NWsXqWYOQqnp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60308, 'Moneyball', 'The story of Oakland Athletics general manager Billy Beane''s successful attempt to put together a baseball team on a budget, by employing computer-generated analysis to draft his players.', '2011-09-23', 7.30, 'https://image.tmdb.org/t/p/w500/4yIQq1e6iOcaZ5rLDG3lZBP3j7a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60420, 'Like Crazy', 'A British college student falls for an American student, only to be separated from him when she''s banned from the U.S. after overstaying her visa.', '2011-10-28', 6.36, 'https://image.tmdb.org/t/p/w500/8eIhNKnRfayRwWChx0atZh4vGua.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59961, 'Safe House', 'A dangerous CIA renegade resurfaces after a decade on the run. When the safe house he''s remanded to is attacked by mercenaries, a rookie operative escapes with him. Now, the unlikely allies must stay alive long enough to uncover who wants them dead.', '2012-02-08', 6.49, 'https://image.tmdb.org/t/p/w500/7SYBPjv5ywF6cI4BSFFtlDyChT2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60670, 'The Crimson Rivers', 'Two French policemen, one investigating a grisly murder at a remote mountain college, the other working on the desecration of a young girl''s grave by skinheads, are brought together by the clues from their respective cases. Soon after they start working together, more murders are committed, and the pair begin to discover just what dark secrets are behind the killings.', '2000-09-27', 6.92, 'https://image.tmdb.org/t/p/w500/npvDhiKkpQBuTaQ8cbWRT2iEfkE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60672, 'Crimson Rivers II: Angels of the Apocalypse', 'No one is safe when seemingly random killings emerge as a deadly pattern intended to usher in the end of the world.  A murder victim with the same DNA as Christ. A serial killer mimicking the deaths of the 12 Apostles. Inspector Niemans and a young, rebellious detective team up with a beautiful expert in religion to crack the case before their elusive suspect completes the cycle of terror, paving the way to an even bigger bloody catastrophe.', '2004-02-18', 6.08, 'https://image.tmdb.org/t/p/w500/hvQZKLVzW3cYfR5bjgGTGZuCuHs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60678, 'Princess', 'Princess tells the true story of former cabaret dancer Anna Lappalainen''s redemptive struggle with insanity, who checked in to Finland''s Kellokoski Psychiatric Hospital in 1945.', '2010-09-10', 5.77, 'https://image.tmdb.org/t/p/w500/dcn8Fzr4QXXr32hf7MPIdJDv3AE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59930, 'The Inkwell', 'The Inkwell is about a 16-year-old boy coming of age on Martha''s Vineyard in the summer of 1976.', '1994-04-22', 5.58, 'https://image.tmdb.org/t/p/w500/b5qUq9l6ci9KzzAqYhpdxzjY7qi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60747, 'Red Dawn', 'A city in Washington state awakens to the surreal sight of foreign paratroopers dropping from the sky—shockingly, the U.S. has been invaded and their hometown is the initial target. Quickly and without warning, the citizens find themselves prisoners and their town under enemy occupation. Determined to fight back, a group of young patriots seek refuge in the surrounding woods, training and reorganizing themselves into a guerrilla group of fighters.', '2012-03-15', 5.72, 'https://image.tmdb.org/t/p/w500/pwOcFK1hFZ5NJybBGfvzU6UHCPg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60843, 'Nasu: Summer in Andalusia', 'Pepe Benengeli is a second-class cyclist, only there to support the star member of the team. This summer he is participating in the Tour of Spain, which passes through the streets of his hometown of Andalusia. In a coincidence, his brother and ex-girlfriend are getting married on the same day as the climax of the race. Pepe, who left his hometown after suffering a breakdown, is determined to achieve something special on this day.', '2003-06-26', 7.13, 'https://image.tmdb.org/t/p/w500/xcwIb5YEfTeVqCRJXNL8Ai1RcEj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60935, 'The Thing', 'When paleontologist Kate Lloyd travels to an isolated outpost in Antarctica for the expedition of a lifetime, she joins an international team that unearths a remarkable discovery. Their elation quickly turns to fear as they realize that their experiment has freed a mysterious being from its frozen prison. Paranoia spreads like an epidemic as a creature that can mimic anything it touches will pit human against human as it tries to survive and flourish in this spine-tingling thriller.', '2011-10-12', 6.26, 'https://image.tmdb.org/t/p/w500/dmn2nVo8h7LMnk694JxCRIwK06p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60855, 'Double Happiness', 'Jade Li is a feisty, 20-something Chinese Canadian, trying to achieve that happy medium between giving in to her parent''s wishes and fulfilling her own needs and desires - double happiness. Naturally, something''s got to give and when love beckons in the shape of Mark, a white university student, the facade of the perfect Chinese daughter begins to slip.', '1994-09-07', 6.47, 'https://image.tmdb.org/t/p/w500/5sbnCdiFoZLe4G27ERS7wtj1lCY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (60994, 'Guinevere', 'A young girl from an affluent family rebels and becomes involved with a much older photographer.', '1999-09-12', 5.74, 'https://image.tmdb.org/t/p/w500/1isgjzl3mwVoxlRd7sqJ7COzwZw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61012, 'Silent Hill: Revelation 3D', 'Heather Mason and her father have been on the run, always one step ahead of dangerous forces that she doesn''t fully understand. Now on the eve of her 18th birthday, plagued by horrific nightmares and the disappearance of her father, Heather discovers she''s not who she thinks she is. The revelation leads her deeper into a demonic world that threatens to trap her forever.', '2012-10-10', 5.55, 'https://image.tmdb.org/t/p/w500/rkAh9cPkb5PoTzEGWfBkhdFNIsf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61054, 'Children of the Night', 'In the quiet little town of Allburg, friends Lucy and Cindy are on the verge of going away to college when they partake in a cleansing ritual by swimming in an abandoned church crypt. After Lucy accidentally drops her crucifix in the water, it drifts down and awakens the ancient vampire Czakyr, who becomes thirsty for Lucy''s virgin blood.', '1991-09-06', 4.33, 'https://image.tmdb.org/t/p/w500/hvXqvntgMKFxhwxt18sD7R0tuLq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61225, 'The Babe', 'A chronicle of Babe Ruth''s phenomenal story--from his hard knock beginnings at a Baltimore orphanage, to his meteoric rise to baseball superstardom and his poignant retirement from the game. His amazing career included seven American League pennants, four World Series championships, two tempestuous marriages and a wild lifestyle that earned him numerous suspensions.', '1992-04-17', 5.66, 'https://image.tmdb.org/t/p/w500/lso2f5jbglHtGke2A8NwRkcfxF6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61178, 'Nadine', 'Hairdresser Nadine Hightower wants to retrieve the risqué photos she once posed for, but when she visits the photographer at his office, he''s murdered by an intruder. Nadine talks her estranged husband, Vernon, into going along when she returns to the office, where they stumble across plans for a less than legal construction project. But when Vernon tries to turn the documents into a cash windfall, he and Nadine are pursued by goons with guns.', '1987-08-07', 5.42, 'https://image.tmdb.org/t/p/w500/mim8TLLXmD3ui03f9jVmOXGACv8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61337, 'Critical Care', 'Werner Ernst is a young hospital resident who becomes embroiled in a legal battle between two half-sisters who are fighting over the care of their comatose father. But are they really fighting over their father''s care, or over his $10 million estate? Meanwhile, Werner must contend with his nutty supervisor, who insists that he only care for patients with full insurance. Can Werner sidestep the hospital''s legal team and do what''s best for the patient?', '1997-10-31', 6.25, 'https://image.tmdb.org/t/p/w500/p4UPT3vvdKHsv6PbhvvtFm8w5Zx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61280, 'The Turning Point', 'As young dancers, they were best friends and fierce rivals. Deedee left the stage for marriage and motherhood, while Emma would become an international ballet icon. But when Deedee''s teenage daughter is invited to join Emma''s dance company and begins an affair with a young Russian star, the two women are forced to confront the choices they''ve made, the resentments they''ve hidden and the emotional truths they must face at the turning point.', '1977-11-14', 6.56, 'https://image.tmdb.org/t/p/w500/6CD90BQEDexEIMqIwMSnbJStF5x.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61752, 'Girl 6', 'A struggling actress in New York City takes a job as a phone sex operator.', '1996-03-22', 5.04, 'https://image.tmdb.org/t/p/w500/1SSYCOTrHucd9aBCyTfbLWcJ2zD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61563, 'Touch', 'At the discovery of his ability to work miracles, Juvenal becomes a media sensation, but now he''s prone to those who want to exploit him.', '1997-02-14', 5.56, 'https://image.tmdb.org/t/p/w500/4KEkCiId2lhKgSM6sAGSuG9BjdH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61791, 'Rise of the Planet of the Apes', 'A highly intelligent chimpanzee named Caesar has been living a peaceful suburban life ever since he was born. But when he gets taken to a cruel primate facility, Caesar decides to revolt against those who have harmed him.', '2011-08-03', 7.35, 'https://image.tmdb.org/t/p/w500/oqA45qMyyo1TtrnVEBKxqmTPhbN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61418, 'The Waterdance', 'Author Joel Garcia breaks his neck while hiking, and finds himself in a rehab center with Raymond, an exaggerating ladies man, and Bloss, a racist biker. Considerable tension builds as each character tries to deal with his new found handicap and the problems that go with it, especially Joel, whose lover Anna is having as difficult a time as he is.', '1992-05-13', 6.00, 'https://image.tmdb.org/t/p/w500/6fLc2xBZ3lK6AToG7iO1v1UAeqJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61461, 'The Children Are Watching Us', 'In his first collaboration with renowned screenwriter and longtime partner Cesare Zavattini, Vittorio De Sica examines the cataclysmic consequences of adult folly on an innocent child. Heralding the pair’s subsequent work on some of the masterpieces of Italian neorealism, The Children Are Watching Us is a vivid, deeply humane portrait of a family’s disintegration.', '1943-10-27', 7.61, 'https://image.tmdb.org/t/p/w500/vEkp2FoxUFpCGeioWdUS4wb7ezh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58232, 'Chalet Girl', 'While working a job at an exclusive ski resort to support her Dad, Kim learns to snowboard and is so good at it that she enters a competition with a huge cash prize. She has to dig deep to overcome her fears, but her life gets more complicated through her spoken-for boss, Jonny.', '2011-02-02', 6.39, 'https://image.tmdb.org/t/p/w500/uzHIG8nXums3sCAiO4w5heZi3Hc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58372, 'Reckless', 'On Christmas Eve, a relentlessly cheerful woman escapes from the killers hired by her husband, and embarks on a series of strange encounters.', '1995-11-17', 6.60, 'https://image.tmdb.org/t/p/w500/edNTtl2UuKcU8vXEaYgu76vISXw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59255, 'The Unintentional Kidnapping of Mrs. Elfriede Ott', 'Horst receives the monthly pension from his grandmother. The only problem is, that she is dead. As a local politician wants to congratulate the grandmother to her birthday Horst "borrows" an old lady from a hospital nearby, not recognizing that he just kidnapped actress Elfriede Ott.', '2010-10-01', 6.80, 'https://image.tmdb.org/t/p/w500/3iuuvMNa3SxqAd3jrlLKhXEdW9a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61984, 'Space Battleship Yamato', 'In 2199, five years after the Gamilons began an invasion of Earth, the planet has been ravaged by the aliens'' bombs. The remnants of humanity have fled underground to escape the irradiated surface. One day, former pilot Susumu Kodai discovers a capsule sent from the planet Iscandar that tells of a device that can remove the radiation from the Earth''s surface. The Earth Defense Force rebuilds the battleship Yamato with a new type of propulsion system to make the 148,000 light year trip to Iscandar in hopes of saving the Earth. Within one year, the radiation will drive the rest of humanity to extinction.', '2010-12-01', 6.44, 'https://image.tmdb.org/t/p/w500/qlRJcIFiVwA6X58LOGNuMP1io2H.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62204, 'Quest for Fire', 'In the prehistoric world, a Cro-Magnon tribe depends on an ever-burning source of fire, which eventually extinguishes. Lacking the knowledge to start a new fire, the tribe sends three warriors on a quest for more. With the tribe''s future at stake, the warriors make their way across a treacherous landscape full of hostile tribes and monstrous beasts. On their journey, they encounter Ika, a woman who has the knowledge they seek.', '1981-12-16', 7.00, 'https://image.tmdb.org/t/p/w500/tyzW1M00xfHKNtmTlT6wJ3F4pNr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62206, '30 Minutes or Less', 'Two fledgling criminals kidnap a pizza delivery guy, strap a bomb to his chest, and advise him that he has mere hours to rob a bank or else...', '2011-08-11', 5.77, 'https://image.tmdb.org/t/p/w500/12VgS5G6OG7ANKrSbhtUD2POHb8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62213, 'Dark Shadows', 'Vampire Barnabas Collins is inadvertently freed from his tomb and emerges into the very changed world of 1972. He returns to Collinwood Manor to find that his once-grand estate and family have fallen into ruin.', '2012-05-09', 6.11, 'https://image.tmdb.org/t/p/w500/fd9Ck4cxVlmtXsbeGtQW7WFuUFI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62211, 'Monsters University', 'A look at the relationship between Mike and Sulley during their days at Monsters University — when they weren''t necessarily the best of friends.', '2013-06-19', 7.06, 'https://image.tmdb.org/t/p/w500/y7thwJ7z5Bplv6vwl6RI0yteaDD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (58383, 'Hands Over the City', 'Prior to a city council election, the collapse of a building leaves a land developer and his political backers defending themselves against a scandal.', '1963-10-11', 7.39, 'https://image.tmdb.org/t/p/w500/zR9uj0dtm5osrrpM7zwO5ndAtbh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62214, 'Frankenweenie', 'When a car hits young Victor''s pet dog Sparky, Victor decides to bring him back to life the only way he knows how. But when the bolt-necked "monster" wreaks havoc and terror in the hearts of Victor''s neighbors, he has to convince them that Sparky''s still the good, loyal friend he was.', '2012-10-04', 7.01, 'https://image.tmdb.org/t/p/w500/yGjVbLVdZRBlZTTQVBsj2KUjL1s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62215, 'Melancholia', 'Two sisters find their already strained relationship challenged as a mysterious new planet threatens to collide with Earth.', '2011-03-16', 7.15, 'https://image.tmdb.org/t/p/w500/fMneszMiQuTKY8JUXrGGB5vwqJf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62320, 'Home', 'In 200,000 years of existence, man has upset the balance on which the Earth had lived for 4 billion years. Global warming, resource depletion, species extinction: man has endangered his own home. But it is too late to be pessimistic: humanity has barely ten years left to reverse the trend, become aware of its excessive exploitation of the Earth''s riches, and change its consumption pattern.', '2009-06-03', 7.81, 'https://image.tmdb.org/t/p/w500/2Ph0vzTiORSSlYjsXLFM1OZHkI8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62395, 'The Miracle of Marcelino', 'Left on the doorstep of a monastery as an infant, Marcelino was raised by the monks. He was well-cared for but lonely and missed having a mother. One day he found a special friend in the forbidden attic, hanging on a cross. A friend that would repay Marcelino''s kindness by granting him one heart-felt wish.', '1955-02-24', 7.40, 'https://image.tmdb.org/t/p/w500/3kC93MPfNxFGqATbRDQ4fFh6TSW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59387, 'The Powerpuff Girls Movie', 'After destroying the city of Townsville in a game of tag, a trio of superpowered little girls must redeem themselves by stopping a vengeful monkey''s plot for world domination.', '2002-07-03', 6.80, 'https://image.tmdb.org/t/p/w500/yAFalW8UtdJg1z1gPjXx8C1sXZq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62422, 'Year of the Horse', 'A document of Neil Young and Crazy Horse''s 1996 concert tour. Director Jarmusch conducts interviews about the band''s long history, interspersed with backstage footage from the 1970s and 1980s.', '1997-10-08', 6.42, 'https://image.tmdb.org/t/p/w500/kLO7UAx8OalCeW2JqTAispzNBJr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62463, 'Raining Stones', 'Proud, though poor, Bob wants his little girl to have a beautiful (and costly) brand-new dress for her First Communion. His stubbornness and determination get him into trouble as he turns to increasingly questionable measures, in his desperation to raise the needed money. This tragic flaw leads him to risk all that he loves and values, his beloved family, indeed even his immortal soul and salvation, in blind pursuit of that goal.', '1993-09-09', 6.92, 'https://image.tmdb.org/t/p/w500/tkkfaTOTgeQ8iq0yQn4y8MvGkG8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62694, 'The Snake Pit', 'Virginia Cunningham is confused upon finding herself in a mental hospital, with no memory of her arrival at the institution. Tormented by delusions and unable to even recognize her husband, Robert, she is treated by Dr. Mark Kik, who is determined to get to the root of her mental illness. As her treatment progresses, flashbacks depict events in Virginia''s life that may have contributed to her instability.', '1948-11-04', 7.11, 'https://image.tmdb.org/t/p/w500/wLO2TVjM4UUQUwOq7RqfS8PCdMC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62488, 'Destiny Turns on the Radio', 'Johnny Destiny burns into Las Vegas in his hot Plymouth RoadRunner, stopping only to pick up a stranger stranded in the desert. But then, things aren''t always as they seem. Anything can happen in that town of many possibilities...especially since there''s been some weird electrical disturbances. As the stranger, fresh out of prison, tries to put his life back together--to recover his money from an old bank heist and the girl he lost in doing the job--something keeps interfering with his plans. Is it fate...or just Destiny?', '1995-04-28', 5.00, 'https://image.tmdb.org/t/p/w500/kd04IvuW1wvgGoB2HxSuFVIU9rU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62676, 'Limbo', 'Traumatized by a fishing boat accident many years before, Joe Gastineau has given up his hopes for a life beyond the odd jobs he takes to support himself. That quickly changes when nomadic club singer Donna de Angelo and her troubled teen-age daughter enter Joe’s life. Both mother and daughter fall for Joe, increasing the friction between them. The tension continues to build when Joe invites them on a pleasure cruise up the Alaskan coast, discovering too late that the trip may cost them their lives.', '1999-06-04', 6.61, 'https://image.tmdb.org/t/p/w500/1ytI3G3dT6j888ySOwYhpJHz8ED.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62764, 'Mirror Mirror', 'After she spends all her money, an evil enchantress queen schemes to marry a handsome, wealthy prince. There''s just one problem - he''s in love with a beautiful princess, Snow White. Now, joined by seven rebellious dwarves, Snow White launches an epic battle of good vs. evil...', '2012-03-15', 5.92, 'https://image.tmdb.org/t/p/w500/gzTSQUUuFrm5ndkIbOVibT797os.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62835, 'Colombiana', 'After witnessing her parents’ murder as a child in Bogota, Cataleya Restrepo grows up to be a stone-cold assassin. She works for her uncle as a hitman by day, but her personal time is spent engaging in vigilante murders that she hopes will lead her to her ultimate target: the mobster responsible for her parents'' death.', '2011-07-27', 6.65, 'https://image.tmdb.org/t/p/w500/rEdGDgRB3gducezNSIyx2lbKQy4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62838, 'New Year''s Eve', 'The lives of several couples and singles in New York intertwine over the course of New Year''s Eve.', '2011-12-08', 5.88, 'https://image.tmdb.org/t/p/w500/TroWD1BdcLEL7Ycqv4kkCRw7KJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63020, 'The Perez Family', 'In the midst of the Mariel boat lift -- a hurried exodus of refugees from Cuba going to America -- an immigration clerk accidentally presumes that dissident Juan Raul Perez and Dorita Evita Perez are married. United by their last name and a mutual resolve to emigrate, Dorita and Juan agree to play along. But it gets complicated when the two begin falling for each other just as Juan reunites with his wife, Carmela, whom he hasn''t seen in decades.', '1995-05-12', 6.09, 'https://image.tmdb.org/t/p/w500/jxi3UDHf86kDk5hqJxnpEMzVch2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62994, 'Dog Park', 'A young man, whose girlfriend has just left him and taken their dog, falls for another woman who is also on the rebound, but who prefers the company of her dog to the company of men.', '1998-09-14', 5.50, 'https://image.tmdb.org/t/p/w500/9B5ZKG8Ht1xacz61x3sRovY6glG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63193, 'Front of the Class', 'A boy with Tourette''s syndrome overcomes criticism and discrimination to achieve his dream of becoming a teacher.', '2008-12-07', 8.02, 'https://image.tmdb.org/t/p/w500/w7UolFxzPi7ZA7LkglRotQ84g1g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63311, 'The Skin I Live In', 'A brilliant plastic surgeon creates a synthetic skin that withstands any kind of damage. His guinea pig: a mysterious and volatile woman who holds the key to his obsession.', '2011-08-17', 7.48, 'https://image.tmdb.org/t/p/w500/xa7uCwGYykrf8MMI8iF5dZvNlrG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63418, 'Boy Meets Girl', 'In Paris at night, a young aspiring filmmaker grapples with heartbreak after his girlfriend leaves him for his best friend. After a failed attempt to confront his friend, he wanders the streets and encounters a girl who has just been abandoned. Their paths cross at a party, bringing together two tormented souls.', '1984-11-21', 6.71, 'https://image.tmdb.org/t/p/w500/xTKs2ztBMnwHog8hnzS65gKLmli.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63076, 'Heidi Fleiss: Hollywood Madam', 'A documentary crew from the BBC arrives in L.A. intent on interviewing Heidi Fleiss, a year after her arrest for running a brothel but before her trial. Several months elapse before the interview, so the crew searches for anyone who''ll talk about the young woman. Two people have a lot to say to the camera: a retired madam named Alex for whom Fleiss once worked and Fleiss''s one-time boyfriend, Ivan Nagy, who introduced her to Alex. Alex and Nagy don''t like each other, so the crew shuttles between them with "she said" and "he said." When they finally interview Fleiss, they spend their time reciting what Alex and Nagy have had to say and asking her reaction.', '1995-12-27', 6.73, 'https://image.tmdb.org/t/p/w500/laPSb9I8TuYslOh1OcgaTByWKnw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63492, 'What''s Your Number?', 'Ally Darling is realizing she''s a little lost in life. Her latest romance has just fizzled out, and she''s just been fired from her marketing job. Then she reads an eye-opening magazine article that warns that 96 percent of women who''ve been with 20 or more lovers are unlikely to find a husband. Determined to turn her life around and prove the article wrong, Ally embarks on a mission to find the perfect mate from among her numerous ex-boyfriends.', '2011-09-30', 6.46, 'https://image.tmdb.org/t/p/w500/eqn3UeXMY9W1Ow3jIZ6COqbjUWX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63441, 'Masked Avengers', 'Philip Kwok plays a repentant killer who vows to destroy the masked gang of which he was a member. A young fighter and his martial arts brothers come to the town to catch the killers, but one of them is not to be trusted!', '1981-05-15', 6.90, 'https://image.tmdb.org/t/p/w500/vr54E7RjvMLE4rFgb1NPgZdnpj6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59437, 'Beautiful Boy', 'A married couple on the verge of separation are leveled by the news their 18-year-old son committed a mass-shooting at his college, then took his own life.', '2011-06-03', 6.00, 'https://image.tmdb.org/t/p/w500/7puPuSeje8315Pbdxzo8bxHD6EB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61416, 'Beautiful People', 'In London, during October 1993, England is playing Holland in the preliminaries of the World Cup. The Bosnian War is at its height, and refugees from the ex-Yugoslavia are arriving. Football rivals, and political adversaries from the Balkans all precipitate conflict and amusing situations. Meanwhile, the lives of four English families are affected in different ways by encounter with the refugees.', '1999-09-16', 6.20, 'https://image.tmdb.org/t/p/w500/t5s6oSCyA2tGf7J5ZJHii4eb2J2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59490, 'Cave of Forgotten Dreams', 'Werner Herzog gains exclusive access to film inside the Chauvet caves of Southern France, capturing the oldest known pictorial creations of humankind in their astonishing natural setting.', '2010-11-03', 7.08, 'https://image.tmdb.org/t/p/w500/7qBfQ2x3FnbB7uRaHQOBjfWFBpc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62000, 'Johnny Belinda', 'A small-town doctor helps a deaf-mute farm girl learn to communicate.', '1948-09-14', 6.87, 'https://image.tmdb.org/t/p/w500/lIkYFx7ZaU56iG507lgLoSh1GNR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63493, 'The Ledge', 'A thriller in which a battle of philosophies between a fundamentalist Christian and an atheist who shares an apartment with a gay friend escalates into a lethal battle of wills.', '2011-05-06', 6.18, 'https://image.tmdb.org/t/p/w500/cTaDS6CTIfZ5MH189ub6oE1FATk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63956, 'Two Family House', 'Buddy Visalo (Michael Rispoli) is a factory worker, a frustrated crooner who once had a shot at the big time. Buddy''s dreams of greatness have been reduced to an endless series of failed moneymaking schemes. His latest is buying a two-family house for him and his wife, Estelle (Katherine Narducci) and converting the ground floor into a neighborhood bar where he can perform. The wrench in the works is that he also inherits the upstairs tenants, Mary,a pregnant Irish girl fresh off the boat (Kelly Macdonald) and her abusive, alcoholic husband, Jim (Kevin Conway). As Buddy''s gang of Italians tries to handle the situation, the girl goes into labor, and a baby is born, forcing them all to confront the limits of their tolerance and compassion.', '2000-01-21', 6.26, 'https://image.tmdb.org/t/p/w500/g4U84VFQDvJeTwiQDhpI6bHWtGT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64246, 'Colorful', 'Upon reaching the train station to death, a dejected soul is informed that he is lucky and will have another chance at life. He is placed in the body of a 14-year-old boy named Kobayashi Makoto, who has just committed suicide. Watched over by a neutral spirit named Purapura, the soul must figure out what his greatest sin and mistake in his former life was, before his time limit in Makoto''s body runs out. He also has a number of other lesser duties he must complete, such as understanding what led Makoto to commit suicide in the first place and learning how to enjoy his second chance at life.', '2010-08-21', 7.22, 'https://image.tmdb.org/t/p/w500/aSM1ki4WSEgvPYMZ9K28aylImFF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59468, 'The Way', 'When his son dies while hiking the famed Camino de Santiago pilgrimage route in the Pyrenees, Tom flies to France to claim the remains. Looking for insights into his estranged child’s life, he decides to complete the 500-mile mountain trek to Spain. Tom soon joins up with other travelers and realizes they’re all searching for something.', '2010-09-10', 7.09, 'https://image.tmdb.org/t/p/w500/uaRfG7n92IiuYcKLl7LJo2gr6qO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59860, 'Monte Carlo', 'Three young women vacationing in Paris find themselves whisked away to Monte Carlo after one of the girls is mistaken for a British heiress.', '2011-07-01', 6.81, 'https://image.tmdb.org/t/p/w500/dcbqyycrWA56HXq5lm41HYuED8Y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61487, 'Mayor of the Sunset Strip', 'A look at the history of fame in the world through the eyes of pop star impresario, Rodney Bingenheimer', '2003-06-17', 6.93, 'https://image.tmdb.org/t/p/w500/1vRVeVhozMozvQSubTlcmQlHKK0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62127, 'The Fantasticks', 'Widowers Amos and Ben plot to romantically unite Amos'' daughter Luisa and Ben''s son Matt by pretending to feud and forbidding the teens to associate, knowing they will resist their fathers'' interference. As the youngsters fall in love, the fathers plot to end the ''feud'' by hiring a travelling showman to fake an abduction and allow Matt to ''rescue'' Luisa.', '2000-09-22', 5.50, 'https://image.tmdb.org/t/p/w500/hfO64mXz3DgUxkBVU7no2UWRP7x.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59965, 'Abduction', 'For many years, Nathan Harper has had the uneasy feeling that life with his family isn''t quite what it seems. As he draws closer to uncovering the truth, he is hunted by assassins, forcing him to flee with his neighbor, Karen, the only person he can trust.', '2011-09-22', 5.83, 'https://image.tmdb.org/t/p/w500/d0TIDrwnMFVjg2EO4LsXQn1mbbc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59963, 'Dark Tide', 'A traumatized shark expert must battle her own fears to lead a thrill-seeking businessman on a dive into a dangerous section of water known as "Shark Alley."', '2012-03-28', 4.72, 'https://image.tmdb.org/t/p/w500/gx56ZanaWd4pG930Z44eDLvnQ8N.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63574, 'Joyful Noise', 'G.G. Sparrow faces off with her choir''s newly appointed director, Vi Rose Hill, over the group''s direction as they head into a national competition.', '2012-01-13', 6.40, 'https://image.tmdb.org/t/p/w500/pIgrIGFMZ7CslGPCWI7JHV3R96H.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59962, 'This Means War', 'Two top CIA operatives wage an epic battle against one another after they discover they are dating the same woman.', '2012-02-14', 6.18, 'https://image.tmdb.org/t/p/w500/7d1hwECRc1NZlGfAeYE42ki7Fem.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (59967, 'Looper', 'In the year 2044, time travel has not yet been invented but in 30 years it will have been. When the mob wants to get rid of someone, they will send their target into the past where a looper, a hired gun, like Joe is waiting to mop up. Joe is getting rich and life is good until the day the mob decides to close the loop, sending back Joe''s future self for assassination.', '2012-09-26', 6.91, 'https://image.tmdb.org/t/p/w500/sNjL6SqErDBE8OUZlrDLkexfsCj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64720, 'Take Shelter', 'Plagued by a series of apocalyptic visions, a young husband and father questions whether to shelter his family from a coming storm, or from himself.', '2011-09-30', 7.06, 'https://image.tmdb.org/t/p/w500/9YDnwmjGYkw1r9EKys33Wf95DAZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64780, 'Upside Down: The Creation Records Story', 'Over a quarter of a century since it began and a decade after it folded, this is the definitive film about Creation Records, one of the world''s most successful and colorful independent labels. This is the story of the rock n roll dream and its accompanying nightmares. Millions of sales on both sides of the Atlantic, near bankruptcy, pills, thrills, spats, prats, success, excess, pick me ups, breakdowns and of course some of THE defining music of the late 20th Century. This is the definitive and fully authorised story of the UK''s most inspired and dissolute label, from the Jesus &amp; Mary Chain at the Living Room to Oasis at Knebworth.', '2010-10-19', 6.91, 'https://image.tmdb.org/t/p/w500/jV4USc1ivMeaaD0vMrfVfWiWmWb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64807, 'Grudge Match', 'A pair of aging boxing rivals are coaxed out of retirement to fight one final bout -- 30 years after their last match.', '2013-12-25', 6.10, 'https://image.tmdb.org/t/p/w500/jTq9jYTKKo6EhQPso4xTMpPYYXW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64328, 'The Muppets', 'When Kermit the Frog and the Muppets learn that their beloved theater is slated for demolition, a sympathetic human, Gary, and his felt-faced brother, Walter, swoop in to help the gang put on a telethon show and raise the $10 million they need to save the day.', '2011-11-23', 6.67, 'https://image.tmdb.org/t/p/w500/h5N6x5gS45wAALt5fsWVn0oCYQR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64847, 'Belladonna of Sadness', 'An evil feudal lord rapes a village girl on her wedding night and proceeds to ruin her and her husband''s lives. After she''s eventually banished from her village, the girl makes a pact with the devil to gain magical ability and take revenge.', '1973-06-30', 7.30, 'https://image.tmdb.org/t/p/w500/2okYZVVw7RdMwlOKcAJsQ7Nsrpr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63581, 'Louis Theroux: The Most Hated Family in America', 'Louis meets the Phelps family — the people at the heart of the controversial Westboro Baptist Church. The Phelps have rabid anti-homosexual beliefs, and often campaign at the funerals of American soldiers. They believe that every tragedy in the world is God''s punishment for homosexuality.', '2007-04-24', 7.30, 'https://image.tmdb.org/t/p/w500/yniNmsxw0xcgpNZW2EmfsrgzGuU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64968, 'Marius and Jeannette', 'Jeannette is a single mother living in a working-class community in Marseilles; she tries to support herself and her two kids on her salary as a check-out girl at a supermarket and lives in an apartment complex where everyone is thrown into close proximity with everyone else. Marius is working as a security guard at a cement factory that has gone out of business; he''s also squatting in the building, since the plant is soon to be demolished and he''ll be needing his money later on. One day, Jeannette happens by the factory, and spotting several cans of paint, tries to take two of them home with her. Marius spots her and tries to chase her away, while she rails at him with curses against the capitalist system. The next day, an apologetic Marius appears at her doorstep, cans of paint in hand; the two soon become friendly, and a romance begins to bloom, though it quickly becomes obvious that Jeannette''s romance novel fantasies are a bit off the mark from what Marius has in mind.', '1997-11-19', 6.83, 'https://image.tmdb.org/t/p/w500/6avoR3mDjg2UN5BGVrkpe5M94RF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (61807, 'Ethan Frome', 'Married couple, Ethan and Zeena, are in need an extra hand around the house due to Zeena''s debilitated body and constant illness. The young woman who joins them is a beautiful, spirited person. She and Ethan fall in love much to the dismay of Zeena.', '1993-03-12', 5.58, 'https://image.tmdb.org/t/p/w500/wsXL08E4gQHWW5pRX4qpIyyeBfs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65015, 'Sweetie', 'The buttoned-down, superstitious Kay is attempting to lead a normal existence with her new boyfriend Louis. That’s until Sweetie, her rampaging, devil-may-care sister, returns home after an absence, exposing the rotten roots of their family and placing a strain on Kay and Louis’ relationship.', '1989-09-28', 6.10, 'https://image.tmdb.org/t/p/w500/25lpQtxNWXzOimnXmbwF0Y0GYej.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65012, 'This Property Is Condemned', 'Owen Legate, a railroad official,  comes to Dodson, Mississippi to shut down the local railway - the town''s main income. But Owen unexpectedly finds love with Dodson''s flirt and main attraction, Alva Starr.', '1966-08-03', 6.42, 'https://image.tmdb.org/t/p/w500/lLiyBhKER2N1vi3xedBwf2YvwAY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65034, 'Too Big to Fail', 'An intimate look at the epochal financial crisis of 2008 and the powerful men and women who decided the fate of the world''s economy in a matter of a few weeks.', '2011-11-25', 6.93, 'https://image.tmdb.org/t/p/w500/pcrCKELIeNFfFrAoVFpMTpzTqVx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65046, 'Love Serenade', 'Two sisters in an Australian country town develop a fierce and competitive crush on their new neighbour, a brooding and self-centred radio personality.', '1996-10-10', 6.00, 'https://image.tmdb.org/t/p/w500/fXBWYmK9MybKhqvmyj57KyFEcq3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65066, 'Going in Style', 'Three kindly old men decide to light up the dimming twilight of their lives with a last blaze of glory – by sticking up a Manhattan bank in broad daylight.', '1979-12-25', 6.96, 'https://image.tmdb.org/t/p/w500/4TYdgaA6FV6PoKsJ34vQpzMlzMv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65055, 'Shark Night 3D', 'A weekend at a lake house in the Louisiana Gulf turns into a nightmare for seven vacationers as they are subjected to fresh-water shark attacks.', '2011-09-02', 5.07, 'https://image.tmdb.org/t/p/w500/cjfRqUXtNc2iJHfP60HTq9nFs0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65057, 'The Descendants', 'With his wife Elizabeth on life support after a boating accident, Hawaiian land baron Matt King takes his daughters on a trip from Oahu to Kauai to confront a young real estate broker, who was having an affair with Elizabeth before her misfortune.', '2011-09-09', 6.83, 'https://image.tmdb.org/t/p/w500/8cDq5UlOPYeKm39okALCEOsZPxk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65075, 'Keep the River on Your Right: A Modern Cannibal Tale', 'In 1955, Tobias Schneebaum disappeared into the depths of the Peruvian Amazon. He had no guide, no map, and only the vaguest of instructions: Keep the river on your right. A year later Schneebaum emerged from the jungle…naked, covered in body paint, and a modern-day cannibal.  Titled after Schneebaum’s 1969 cult classic memoir about his formative experiences living in the Amazon, Keep The River On Your Right is the extraordinary stranger-than-fiction story of Schneebaum’s return to the jungle, 45 years after his original visit, to reunite with the very tribesmen he loved and who gave him nightmares for nearly half a century. A deeply affecting and searing portrait, sibling filmmakers Laurie and David Shapiro capture a man in utter conflict, a fearless adventurer, and one of the most charming, enigmatic, and perplexing men ever captured on screen.', '2000-04-15', 6.05, 'https://image.tmdb.org/t/p/w500/547BjvhpThD8QXpGB7UnKi33ox2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65137, 'Father Hood', 'Deadbeat dad kidnaps his kids from the bus to an abusive foster home and they go on a run. The cops are after them, they bicker constantly and his idea of a way out is grim, yet this dangerous ride might just turn them into a family.', '1993-08-27', 5.81, 'https://image.tmdb.org/t/p/w500/xHndTwPS3CNjct7aE20dBa6764e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65086, 'The Woman in Black', 'The story follows a young lawyer, Arthur Kipps, who is ordered to travel to a remote village and sort out a recently deceased client’s papers. As he works alone in the client’s isolated house, Kipps begins to uncover tragic secrets, his unease growing when he glimpses a mysterious woman dressed only in black. Receiving only silence from the locals, Kipps is forced to uncover the true identity of the Woman in Black on his own, leading to a desperate race against time when he discovers her true identity.', '2012-02-03', 6.14, 'https://image.tmdb.org/t/p/w500/peKkO5lYyyZ7flxeFuXoZPXArXo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65203, 'The Broadway Melody', 'The vaudeville act of Harriet and Queenie Mahoney comes to Broadway, where their friend Eddie Kerns needs them for his number in one of Francis Zanfield''s shows. When Eddie meets Queenie, he soon falls in love with  her—but she is already being courted by Jock Warriner, a member of New York high society. Queenie eventually recognizes that, to Jock, she is nothing more than a toy, and that Eddie is in love with her.', '1929-02-08', 5.12, 'https://image.tmdb.org/t/p/w500/giq8GJs8YGMzHxeKxNSuwzAdd1c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65215, 'Stewie Griffin: The Untold Story', 'The maniacal baby of the Griffin family, Stewie, meets his future self. In doing this he discovers that his future image is not what he has anticipated because of a near death experience.', '2005-07-23', 6.92, 'https://image.tmdb.org/t/p/w500/pgbMydwYuHlGcaASQMA963qpSH3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65460, 'Carnosaur 2', 'A team of scientists go to a nuclear mining facility to investigate a possible meltdown and instead find a large amount of cloned dinosaurs.', '1995-02-23', 4.30, 'https://image.tmdb.org/t/p/w500/8dzRgDdbmEEolKPLpuScsMofHD3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65599, 'The Woman', 'A lawyer puts his family in jeopardy when he captures the last member of a violent clan and tries to forcibly tame her.', '2011-10-14', 6.06, 'https://image.tmdb.org/t/p/w500/zOGqKcuApM1Js4C0n4luv9rctBH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65632, 'The 10th Victim', 'In the near future, big wars are avoided by giving individuals with violent tendencies a chance to kill in the Big Hunt. The Hunt is the most popular form of entertainment in the world and also attracts participants who are looking for fame and fortune. It includes ten rounds for each competitor, five as the hunter and five as the victim.', '1965-12-02', 6.64, 'https://image.tmdb.org/t/p/w500/qwXXxwnN1yj5XiZBUrdazBRMqw1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65759, 'Happy Feet Two', 'Mumble the penguin has a problem: his son Erik, who is reluctant to dance, encounters the Mighty Sven — a penguin who can fly! Things get worse for Mumble when the world is shaken by powerful forces, causing him to bring together the penguin nations and their allies to set things right.', '2011-11-17', 6.21, 'https://image.tmdb.org/t/p/w500/2gWiQ4mn85jcXtREVePlVViupeV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64484, 'Playing the Victim', 'A young man drops out of university and goes to the police. He''s done nothing wrong he just wants a job. A particular job. Playing the victim in murder reconstructions. Maybe by getting close to death he can manage to cheat on his own.', '2006-06-08', 6.50, 'https://image.tmdb.org/t/p/w500/nmeKDPvieULQZecpRBeToxQB4qk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65796, 'Wild Bill', 'Biopic about famous gunslinger Wild Bill Hickock. The early career of legendary lawman is telescoped and culminates in his relocation in Deadwood and a reunion with Calamity Jane.', '1995-12-01', 5.70, 'https://image.tmdb.org/t/p/w500/g5sQTDwc4BcvRCBAhnujhBPIEO1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65760, 'The Whistleblower', 'Nebraska cop Kathryn Bolkovac discovers a deadly sex trafficking ring while serving as a U.N. peacekeeper in post-war Bosnia. Risking her own life to save the lives of others, she uncovers an international conspiracy that is determined to stop her, no matter the cost.', '2010-09-13', 6.73, 'https://image.tmdb.org/t/p/w500/iIVcea2BHHi7RJgucGEmpt3zkED.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63375, 'Generation P', 'Set in the ground zero of gangster globalism and driven by a truly manic energy, Generation P is at once a comedy, a tragedy and a  fantasy about the rise of a poet-turned-adman through Russia’s nascent advertising business during the Moscow roaring 1990s.', '2011-04-14', 6.41, 'https://image.tmdb.org/t/p/w500/c7aMcRsKSU3oOhEdrfcR04iZEMS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63945, 'Bliss', 'On his wedding day, Joseph nervously admits that his wife is not quite like other women. But his beautiful bride is more than just the "impulsive, compulsive, obsessive" woman he thinks he knows. And when Joseph discovers she is hiding troubling secrets, it sends them both on a sexual odyssey that will either destroy or redeem their relationship.', '1997-04-14', 6.44, 'https://image.tmdb.org/t/p/w500/zGdGINvf9oSysprbWnu85dIM7rc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (62177, 'Brave', 'In the mystical Scottish Highlands, Merida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Merida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Merida seeks out an eccentric old Wise Woman and is granted an ill-fated wish. Also figuring into Merida''s quest — and serving as comic relief — are the kingdom''s three lords: the enormous Lord MacGuffin, the surly Lord Macintosh, and the disagreeable Lord Dingwall.', '2012-06-21', 7.03, 'https://image.tmdb.org/t/p/w500/1XAuDtMWpL0sYSFK0R6EZate2Ux.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65229, 'Tomboy', 'Ten-year-old Laure isn''t like most girls. She prefers football to dolls and sweaters to dresses. When Laure and her family move to a new neighbourhood, local girl Lisa mistakes Laure for a boy. Indulging in this exciting new identity, Laure becomes Mickaël, and so begins a summer of long sunny afternoons, playground games and first kisses. Yet with the school term fast approaching, and with suspicions arising amongst friends and family, Laure must face up to an uncertain future.', '2011-04-20', 7.30, 'https://image.tmdb.org/t/p/w500/plEV1Q5u5caYASlG3pq3ON7acN7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (63578, 'The Trip', 'When Steve Coogan is asked by The Observer to tour the country''s finest restaurants, he envisions it as the perfect getaway with his beautiful girlfriend. But, when she backs out on him, he has no one to accompany him but his best friend and source of eternal aggravation, Rob Brydon.', '2011-04-24', 6.67, 'https://image.tmdb.org/t/p/w500/tjGrjHNjsR0klih0bkGBHbukMdX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65550, 'The Rose Tattoo', 'A grieving widow embarks on a new romance when she discovers her late husband had been cheating on her.', '1955-12-12', 6.89, 'https://image.tmdb.org/t/p/w500/3W3dgP2l24JJWq6sVEl6TddLwbe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64686, '47 Ronin', 'Kai—an outcast—joins Oishi, the leader of 47 outcast samurai.  Together they seek vengeance upon the treacherous overlord who killed their master and banished their kind.  To restore honour to their homeland, the warriors embark upon a quest that challenges them with a series of trials that would destroy ordinary warriors.', '2013-12-06', 6.21, 'https://image.tmdb.org/t/p/w500/xDHnmcroujCRG0ysYQaiswjbyHd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64635, 'Total Recall', 'Factory worker Doug Quaid takes a virtual mind-trip vacation with the Rekall company, opting for implanted memories of being a spy. When the procedure goes wrong, Quaid becomes a wanted man by the police and joins forces with a rebel fighter to stop the evil Chancellor Cohaagen.', '2012-08-02', 6.03, 'https://image.tmdb.org/t/p/w500/hVUxVVzZ0WvvPIpKwsMPMDOQyqi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64029, 'Rollo and the Spirit of the Woods', 'Hairy and rowdy creatures called rolleys sail to a land inhabited by more peace-loving elves. When the rolleys arrive to the elf village, they scare the elves away and settle down in the village. One of the elves, Milli, a brave elf girl, returns to the village to make a peace with the rolleys. The rolleys do not warm to Milli''s peace proposal, but she becomes friends with a rolley called Rölli. It becomes their mission to solve the conflict between the elves and the rolleys.', '2001-12-21', 6.90, 'https://image.tmdb.org/t/p/w500/v8bRR4s5i3qTgHyNDTONJmP5H6i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (66092, 'I Never Promised You a Rose Garden', 'A disturbed and institutionalized 16-year-old girl struggles between fantasy and reality.', '1977-07-14', 5.94, 'https://image.tmdb.org/t/p/w500/AcumdxTlCtFBQXDjsIsiy1VyjpX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (67067, 'Zone 39', 'In a time of misery and fear two enemies come together to prevent an apocalypse conspired by their leaders. 40 years of war between the Federated Republics and the New Territories Union has taken its toll. The cities are overcrowded, farming land is riddled with unexploded mines -- and still there is no hope of peace. In this hostile, decaying world of the future on thing remains constant for Lieutenant Leo Megaw; his love for his pregnant wife. Her access to classified information makes her an increasing liability for the government. When she''s ambushed, Leo is forced into exile. As a border patrolman on the isolated outpost of Zone 39, ordered to kill anyone that tries to cross the border, he comes to understand that ultimate catastrophe forced upon his world by his government. The real enemy is not looming across the border but standing right behind him. Now he must reach across the border into enemy territory and form an alliance to save his world.', '1996-05-04', 5.57, 'https://image.tmdb.org/t/p/w500/3Hful9RfqJm4M4swEnAAW89iZKt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (67109, 'Delhi Belly', 'Three unsuspecting, average guys find themselves on the hit list of one of India''s most-powerful crime syndicates.', '2011-07-01', 7.07, 'https://image.tmdb.org/t/p/w500/hGmjlOFPaqwxAxR3XDvalExTlXd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (67166, 'Runaway Brain', 'In an attempt to convince Minnie that he hasn''t forgotten to buy her an anniversary present, Mickey Mouse ends up promising to take her to Hawaii. Funds being short, he applies for a job as lab assistant to the sinister Dr. Frankenollie, who happens to be searching for a donor to provide his monstrous creation with a brain.', '1995-08-11', 6.75, 'https://image.tmdb.org/t/p/w500/cEB4K6YavRvrfiAp83cJCgg91Df.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (66194, 'Deadtime Stories', 'A babysitting uncle tells his charges three horror stories: about a killer witch; Little Red Riding Hood and a werewolf; and Goldi Lox and the three bears.', '1986-04-13', 4.90, 'https://image.tmdb.org/t/p/w500/wlpPBlg5YqVxEqlF4ZsGwaO9OLZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (67323, 'The Adventures of Sebastian Cole', 'Hank marries the divorced Joan, who''s the mother of teens Sebastian and Jessica. After living with his new family for years, Hank announces that he''s getting a sex change operation. The family deserts Hank, with Jessica going her own way and Sebastian staying with his mom. But Joan becomes an alcoholic, so Sebastian moves back in with Hank — now Henrietta — who turns out to be far more supportive than anyone else.', '1998-09-11', 5.26, 'https://image.tmdb.org/t/p/w500/isgUjJ9dlDyUJqEWtFrNeQe1wMg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (67660, 'Think Like a Man', 'The balance of power in four couples’ relationships is upset when the women start using the advice in Steve Harvey’s book, Act Like A Lady, Think Like A Man, to get more of what they want from their men. When the men realize that the women have gotten a hold of their relationship “playbook,” they decide that the best defense is a good offense and come up with a plan to use this information to their advantage.', '2012-04-20', 6.80, 'https://image.tmdb.org/t/p/w500/kfIrKVPDzXJDBzPnFEuoatlaZPW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65749, 'Tango', 'A dangerous love affair inspires a director to create the most spectacular and boldly seductive dance film ever made.', '1998-08-06', 6.62, 'https://image.tmdb.org/t/p/w500/87Ze0JLbWYuYbWc1qf6aGxHipnI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (67385, 'The Town Is Quiet', 'A dark tale of working-class life in Marseilles, a city in crisis. Interesting characters include a hard-bitten but compassionate fish market worker with a drug addicted daughter and a moody bartender with a shocking secret life.', '2000-08-30', 6.40, 'https://image.tmdb.org/t/p/w500/8d2NBr4in07pEQgO1PwENJH0IO1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (67748, 'Snowtown', 'Based on true events, 16 year-old Jamie falls in with his mother''s new boyfriend and his crowd of self-appointed neighborhood watchmen, a relationship that leads to a spree of torture and murder.', '2011-05-19', 6.30, 'https://image.tmdb.org/t/p/w500/5LW1vPLa8ueVwdOgR8w5xYkSQGv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (67913, 'The Guard', 'When a small-town Irish cop with a crass personality is partnered with a straight-laced FBI agent to bust an international drug-trafficking ring, they must settle their differences in order to take down a dangerous gang.', '2011-07-07', 6.97, 'https://image.tmdb.org/t/p/w500/dtQiStID0le2EMTmJXupPRybARB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68098, 'One-Way Ticket to Mombasa', 'Pete loses his consciousness while playing in a pop band. The diagnosis is harsh and the doctor cannot say for sure whether Pete will celebrate his 18th birthday. One night, encouraged by the vodka on Jusa''s 18th birthday, Pete confesses his love to Kata, his dream girl. Together with Jusa, they go to Lapland where Kata has her summer job. In Jusa''s wild company, Pete experiences something which he never felt before as they decide to take a trip to Mombasa via Lapland.', '2002-09-06', 6.10, 'https://image.tmdb.org/t/p/w500/mDhfS9JmPpLz1LrCrbvT7eIT2JS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68064, 'Flash Gordon Conquers the Universe', 'A mysterious plague, the Purple Death, ravages the earth. Dr. Zarkov, investigating in his spaceship, finds a ship from planet Mongo seeding the atmosphere with dust. Sure enough, Ming the Merciless is up to his old tricks. So it''s back to Mongo for Flash, Dale, and Zarkov.', '1940-03-03', 5.80, 'https://image.tmdb.org/t/p/w500/5vT3VkTpdLQ2Me1WWbLHA7QCLr4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68341, 'Cold Fish', 'When fish shop owner Shamoto''s teenage daughter Mitsuko is caught stealing, a generous middle-aged man named Murata helps resolve the situation. The man and his wife offer to have Mitsuko work at their opposing fish store. Shamoto soon discovers that something far more sinister lives behind Murata''s friendly demeanor.', '2011-01-29', 6.92, 'https://image.tmdb.org/t/p/w500/669GmEZsyMlPliURX5myHTStslv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
