INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68179, 'Escape from Planet Earth', 'Astronaut Scorch Supernova finds himself caught in a trap when he responds to an SOS from a notoriously dangerous alien planet.', '2013-02-14', 5.78, 'https://image.tmdb.org/t/p/w500/9la0CSCJqwh6io3yk4Xv3aEZxEA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68427, 'Daughters of the Dust', 'In 1902, a Gullah family on the Sea Islands off South Carolina decide whether to migrate to the mainland, risking their unique cultural heritage.', '1991-01-24', 6.28, 'https://image.tmdb.org/t/p/w500/sk5qednzLeDZMIhto6Oa9QFKOon.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
