INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68440, 'Watch on the Rhine', 'On the eve of World War II, the German Kurt Müller, his American-born wife Sara, and their three children, having lived in Europe for years, visit Sara''s wealthy mother near Washington, DC. Kurt secretly works for the anti-Nazi resistance. A visiting Romanian count, becoming aware of this, seeks to blackmail him.', '1943-08-27', 6.86, 'https://image.tmdb.org/t/p/w500/6ZeyGqZEmK4JUbV0o5nBglEODoC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68569, 'Invincible', 'A Jewish strongman performs in Berlin as the blond Aryan hero Siegfried.', '2001-12-02', 6.21, 'https://image.tmdb.org/t/p/w500/vvNDQO2izNk6ytDxFtTr1BP5CxL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65754, 'The Girl with the Dragon Tattoo', 'Disgraced journalist Mikael Blomkvist investigates the disappearance of a weary patriarch''s niece from 40 years ago. He is aided by the pierced, tattooed, punk computer hacker named Lisbeth Salander. As they work together in the investigation, Blomkvist and Salander uncover immense corruption beyond anything they have ever imagined.', '2011-12-14', 7.39, 'https://image.tmdb.org/t/p/w500/8bokS83zGdhaXgN9tjidUKmAftW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64682, 'The Great Gatsby', 'Nick Carraway arrives in New York in 1922, an era of loose morals, glittering jazz and bootleg kings. Chasing his own American Dream, Nick encounters the mysterious millionaire Gatsby and his bewitching cousin Daisy. Soon, Nick is drawn into the captivating world of the super-rich, their illusions, loves and deceits. Bearing witness to this new world, Nick pens a tale of impossible love, incorruptible dreams and unforgettable tragedy -- mirroring our own times and struggles.​', '2013-05-09', 7.35, 'https://image.tmdb.org/t/p/w500/nimh1rrDDLhgpG8XAYoUZXHYwb6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64353, 'The Hitch Hikers Guide to the Galaxy', 'An Earth Man and his alien friend escape an exploding Earth, and set forth on an odd adventure across the universe with a known fugitive.', '1981-02-09', 7.26, 'https://image.tmdb.org/t/p/w500/paOaEgnRu6eWraEwrpaE4yggpj5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68730, 'Silence', 'In the 17th century, two Portuguese Jesuit priests travel to Japan in an attempt to locate their mentor, who is rumored to have committed apostasy, and to propagate Catholicism.', '2016-12-23', 7.12, 'https://image.tmdb.org/t/p/w500/x5T0cQDYws0xRBVG4Q3wpcrcmax.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (66918, 'Beginning of the End', 'An attractive reporter investigating the mysterious destruction of an Illinois town stumbles upon a secret government laboratory conducting radiation experiments on vegetables. The lead scientist is eager to help find out what happened. Together they discover that giant grasshoppers are behind the devastation. Worse yet, thousands of them are headed toward Chicago! Can they be stopped... or is this the BEGINNING OF THE END?', '1957-06-28', 3.98, 'https://image.tmdb.org/t/p/w500/oYwpYmUWUsbQq13lwoU6rUeNraC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
