INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68721, 'Iron Man 3', 'When Tony Stark''s world is torn apart by a formidable terrorist called the Mandarin, he starts an odyssey of rebuilding and retribution.', '2013-04-18', 6.93, 'https://image.tmdb.org/t/p/w500/qhPtAc1TKbMPqNvcdXSOn9Bn7hZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (66600, 'Sweet Liberty', 'Michael Burgess is an academic who has written a scholarly book on the American Revolution which Hollywood has bought the film rights to. The arrival of the film crew seriously disrupts him as actors want to change their characters, directors want to re-stage battles, and he becomes infatuated with Faith who will play the female lead in the movie. At the same time, he is fighting with his crazy mother who thinks the Devil lives in her kitchen, and his girlfriend who is talking about commitment.', '1986-05-16', 5.34, 'https://image.tmdb.org/t/p/w500/asLW0DZYI0BFc1o4IiMVmgV9i1P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68806, 'The Escort', 'The film shows the difficulties of an honest, imperiled judge and his bodyguard of four men, trying to clean up a Sicilian town. Corrupt local politicians, working hand-in-hand with the Mafia, will stop at nothing to prevent exposure of their rackets.', '1993-04-15', 6.57, 'https://image.tmdb.org/t/p/w500/bhUUl8DosoGRDiGuSGu5GXDdGzT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68812, 'The Iceman', 'The true story of Richard Kuklinski, the notorious contract killer and family man.', '2012-09-01', 6.55, 'https://image.tmdb.org/t/p/w500/3edygPSm9XdISHza8zqHUVAQHAD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68817, 'Footloose', 'Ren MacCormack is transplanted from Boston to the small southern town of Bomont where loud music and dancing are prohibited. Not one to bow to the status quo, Ren challenges the ban, revitalizing the town and falling in love with the minister’s troubled daughter Ariel in the process.', '2011-10-06', 6.58, 'https://image.tmdb.org/t/p/w500/cDUW5RWmyHcTxu7eg9eMqhBQy2J.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64678, 'The Art of Getting By', 'George, a lonely and fatalistic teen who''s made it all the way to his senior year without ever having done a real day of work, is befriended by Sally, a popular but complicated girl who recognizes in him a kindred spirit.', '2011-06-17', 6.60, 'https://image.tmdb.org/t/p/w500/3ahdKyzHbYhvqJdtpsEWipEai98.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64685, 'Extremely Loud & Incredibly Close', 'A year after his father''s death, Oskar, a troubled young boy, discovers a mysterious key he believes was left for him by his father and embarks on a scavenger hunt to find the matching lock.', '2011-12-25', 6.99, 'https://image.tmdb.org/t/p/w500/6pszViNvKr1r31pP7gJNYDHEx5P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65851, 'Jackass 3.5', 'Johnny Knoxville of ''Jackass'' releases unused material of stunts, tricks, antics and shenanigans shot during the production of ''Jackass 3D'' that didn''t make it into the film, as well as the hilarious outtakes.', '2011-04-01', 6.37, 'https://image.tmdb.org/t/p/w500/o0cILOYbqfppTLAhkI2tzA2BWtX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68728, 'Oz the Great and Powerful', 'Oscar Diggs, a small-time circus illusionist and con-artist, is whisked from Kansas to the Land of Oz where the inhabitants assume he''s the great wizard of prophecy, there to save Oz from the clutches of evil.', '2013-03-07', 5.94, 'https://image.tmdb.org/t/p/w500/tkzfAUEKoUp4YFNbZV9hfpZOz0z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (65889, 'Roseanna''s Grave', 'Roseanna is dying of a heart condition, and all she wants is to be buried next to her daughter, in a cemetery that is getting full fast. The cemetery can''t expand because Capestro, the man who owns the land next to the cemetery, won''t sell. While Marcello is doing good deeds to make sure no one dies, Roseanna thinks of Marcello''s future.', '1997-03-06', 6.56, 'https://image.tmdb.org/t/p/w500/6xIGYIjTUt9Ew2sBJS57W1NKSP2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (69605, 'Written on the Wind', 'Mitch Wayne is a geologist working for the Hadleys, an oil-rich Texas family. While the patriarch, Jasper, works hard to establish the family business, his irresponsible son, Kyle, is an alcoholic playboy, and his daughter, Marylee, is the town tramp. Mitch harbors a secret love for Kyle''s unsatisfied wife, Lucy -- a fact that leaves him exposed when the jealous Marylee accuses him of murder.', '1956-10-04', 6.96, 'https://image.tmdb.org/t/p/w500/paeBU70fHsFAOooWM5V35q562f2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68722, 'The Master', 'Freddie, a volatile, heavy-drinking veteran who suffers from post-traumatic stress disorder, finds some semblance of a family when he stumbles onto the ship of Lancaster Dodd, the charismatic leader of a new "religion" he forms after World War II.', '2012-09-14', 7.10, 'https://image.tmdb.org/t/p/w500/rUSjbyvYWN9H4az8xt0tDtU7I6v.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (69735, 'Batman: Year One', 'A wealthy playboy named Bruce Wayne and a Chicago cop named Jim Gordon both return to Gotham City where their lives unexpectedly intersect.', '2011-09-27', 7.25, 'https://image.tmdb.org/t/p/w500/mLZRhulJcDsxZWTdfx0trtk6y07.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (69798, 'The Inbetweeners Movie', 'High school graduation just wouldn’t be complete without an unchaperoned, uninhibited and unforgettable final holiday. At least that’s what Will, Jay, Simon and Neil think when they book a two-week stay on an exotic Greek island. As their dreams of sun-drenched days and booze-filled nights are left hopelessly unfulfilled, the lads fight their way into the party scene with hilariously humiliating results.', '2011-08-19', 6.20, 'https://image.tmdb.org/t/p/w500/nePYsVp0qU8EbSXeUdr3xEkHlzN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70042, 'Theremin: An Electronic Odyssey', 'After escaping Russia''s communist revolution, Léon Theremin travels to New York, where he pioneers the field of electronic music with his synthesizer. But at the height of his popularity, Soviet agents kidnap and force him to develop spy technology.', '1995-08-24', 5.85, 'https://image.tmdb.org/t/p/w500/cM6poC7pjCXTJAqZA630xI2GCg7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64690, 'Drive', 'Driver is a skilled Hollywood stuntman who moonlights as a getaway driver for criminals. Though he projects an icy exterior, lately he''s been warming up to a pretty neighbor named Irene and her young son, Benicio. When Irene''s husband gets out of jail, he enlists Driver''s help in a million-dollar heist. The job goes horribly wrong, and Driver must risk his life to protect Irene and Benicio from the vengeful masterminds behind the robbery.', '2011-09-15', 7.58, 'https://image.tmdb.org/t/p/w500/602vevIURmpDfzbnv5Ubi6wIkQm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70061, 'On the Trail of the Bremen Town Musicians', 'The King, wanting for his daughter to be found and returned to his castle, hires Detective to carry out the task. He successfully kidnaps and returns Princess back to the kingdom, but Troubadour and his animal friends Bremen Town Musicians hurry to release her.', '1973-02-02', 7.12, 'https://image.tmdb.org/t/p/w500/qSBftaHwuK3VdEiGqaK4OQfhKe7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70074, 'Bullet to the Head', 'After watching their respective partners die, a cop and a hitman form an alliance in order to bring down their common enemy.', '2012-11-14', 5.61, 'https://image.tmdb.org/t/p/w500/arJfxShfuZPhqfBZZU6DkPZfnjn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70160, 'The Hunger Games', 'In a dystopian society where the Capitol forces each district to send two young tributes to fight to the death in a televised spectacle, a girl volunteers to take her sister’s place, setting the stage for a struggle of survival and defiance.', '2012-03-12', 7.22, 'https://image.tmdb.org/t/p/w500/apa5G43Hha7kH7wJG0gkkHT7FA9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64689, 'Killing Them Softly', 'Jackie Cogan is an enforcer hired to restore order after three dumb guys rob a Mob protected card game, causing the local criminal economy to collapse.', '2012-07-30', 6.03, 'https://image.tmdb.org/t/p/w500/heaz45kpFa4Oa7iLis0OBas68ls.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70193, 'Hazard', 'Shin is a Japanese university student living a boring and meaningless life. One day, he spots a book titled Dangerous Ways to Walk the World, in which he finds a page written about hazards in New-York. Eager to get out, he jets off to New-York to find this inspiration.', '2005-11-11', 6.56, 'https://image.tmdb.org/t/p/w500/37UiCE8LyyRLlg9p50LL2QvBmzz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70282, 'The Visit', 'A young man dying in prison brings his family together for a fateful visit, and proceeds to put his life back together.', '2001-04-20', 7.93, 'https://image.tmdb.org/t/p/w500/9QRMhaGelf9JImcaAntbCqXumhh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70435, 'Haywire', 'A black ops soldier seeks payback after she is betrayed and left for dead.', '2011-11-01', 5.71, 'https://image.tmdb.org/t/p/w500/c9fJ0dYC30NnE9k2p61c0dqlZqW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70670, 'Headhunters', 'An accomplished headhunter risks everything to obtain a valuable painting owned by a former mercenary.', '2011-08-26', 7.23, 'https://image.tmdb.org/t/p/w500/k5DQqsb9T8djkTAOdwNCBBBHrtK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70801, 'Daddy-Long-Legs', 'Wealthy Jarvis Pendleton acts as benefactor for orphan Judy Abbott, anonymously sponsoring her in her boarding school. But as she grows up, he finds himself falling in love with her, and she with him, though she does not know that the man she has fallen for is her benefactor.', '1919-05-11', 6.68, 'https://image.tmdb.org/t/p/w500/m3CF9lgC1mH1NWft43tgmyyOEdm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70436, 'The Raven', 'A fictionalized account of the last days of Edgar Allan Poe''s life, in which the poet is in pursuit of a serial killer whose murders mirror those in the writer''s stories.', '2012-03-09', 6.30, 'https://image.tmdb.org/t/p/w500/boE0JFhZRpWLLrKOQE6bCBZGerP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70862, 'American Grindhouse', 'This documentary explores the hidden history of the American Exploitation Film. The movie digs deep into this often overlooked category of U.S. cinema and unearths the shameless and occasionally shocking origins of this popular entertainment.', '2011-02-04', 6.74, 'https://image.tmdb.org/t/p/w500/1vysYoEj5XFrfcSBrJyWQ4YeHks.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70868, 'I Don''t Know How She Does It', 'As an employee at a Boston-based financial firm, Kate Reddy struggles daily to balance the demands of her high-powered career with the needs of her husband, Richard, and their two children. When she gets an account that requires frequent trips to New York and her husband gets a new job, Kate finds herself spread even thinner. Complicating Kate''s life even more is her new business associate Jack Abelhammer, who throws temptation into the mix.', '2011-09-16', 5.17, 'https://image.tmdb.org/t/p/w500/eUQfE21WB0qKfUx6yUAhmsCWTmX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70881, 'Anna Karenina', 'In Imperial Russia, Anna, wife of the officer Karenin, goes to Moscow to visit her brother. On the way, she meets charming cavalry officer Vronsky, to whom she''s immediately attracted. But in St. Petersburg’s high society, a relationship like this could destroy a woman’s reputation.', '1935-08-30', 6.57, 'https://image.tmdb.org/t/p/w500/39bSsAvMGOgN8I5lt2rOQgAXsj7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70981, 'Prometheus', 'A team of explorers discover a clue to the origins of mankind on Earth, leading them on a journey to the darkest corners of the universe. There, they must fight a terrifying battle to save the future of the human race.', '2012-05-30', 6.61, 'https://image.tmdb.org/t/p/w500/qsYQflQhOuhDpQ0W2aOcwqgDAeI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (70966, 'Messenger Boy', 'Ivan Mirosnikov, a cheeky young man in the Gorbachev era, is trying to figure out what to do with his life (he''s not in college, and the 2-year mandatory military service is looming large ahead of him). Meanwhile, he lives with his divorced mother, and works as a courier at a Russian newspaper. Through his job, he meets patronizing Professor Kuznetzov and his rebellious daughter Katya. To annoy the professor, Ivan claims to have an affair with Katya. To his surprise, Katya backs his story up.', '1986-06-06', 7.38, 'https://image.tmdb.org/t/p/w500/tme4oPYFDiW6HWonNlcmx8Ukevs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71469, 'The Darkest Hour', 'In Moscow, five young people lead the charge against an alien race which has attacked Earth via our power supply.', '2011-12-22', 5.30, 'https://image.tmdb.org/t/p/w500/iUrtHcc8rn7iX31Id3MYOT1rbyw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71172, 'Gintama: The Movie', 'Odd Jobs Gin has taken on a lot of odd work in the past, and when you''re a Jack of All Trades agency based in a feudal Japan that''s been conquered and colonized by aliens, the term "Odd Jobs" means REALLY ODD jobs. But when some more than slightly suspicious secrets from the shadows of Gintoki Sakata''s somewhat shady former samurai past and a new pair of odd jobs collide, the action is bound to get so wild and demented that only a feature film will do it justice!', '2010-04-24', 7.40, 'https://image.tmdb.org/t/p/w500/E3RT3f8oOuPS2pMhgH47TKBPgu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (64688, '21 Jump Street', 'When cops Schmidt and Jenko join the secret Jump Street unit, they use their youthful appearances to go undercover as high school students. They trade in their guns and badges for backpacks, and set out to shut down a dangerous drug ring. But, as time goes on, Schmidt and Jenko discover that high school is nothing like it was just a few years earlier -- and, what''s more, they must again confront the teenage terror and anxiety they thought they had left behind.', '2012-03-14', 6.88, 'https://image.tmdb.org/t/p/w500/8v3Sqv9UcIUC4ebmpKWROqPBINZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71552, 'American Reunion', 'The characters we met a little more than a decade ago return to East Great Falls for their high school reunion. In one long-overdue weekend, they will discover what has changed, who hasn’t, and that time and distance can’t break the bonds of friendship.', '2012-04-04', 6.32, 'https://image.tmdb.org/t/p/w500/de5QBIdVR4dnkBZ4a0zjkS4lTg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68727, 'Trance', 'A violent gang enlists the help of a hypnotherapist in an attempt to locate a painting which somehow vanished in the middle of a heist.', '2013-03-27', 6.62, 'https://image.tmdb.org/t/p/w500/rR3F4fIn0JUJa1hlq2focd2W3zH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71676, 'Ghost Rider: Spirit of Vengeance', 'When the devil resurfaces with aims to take over the world in human form, Johnny Blaze reluctantly comes out of hiding to transform into the flame-spewing supernatural hero Ghost Rider -- and rescue a 10-year-old boy from an unsavory end.', '2011-12-10', 5.02, 'https://image.tmdb.org/t/p/w500/xEoBT6lYfQNpSpTm8gJMTrQytiw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71688, 'The Iron Lady', 'A look at the life of Margaret Thatcher, the former Prime Minister of the United Kingdom, with a focus on the price she paid for power.', '2011-12-26', 6.35, 'https://image.tmdb.org/t/p/w500/fx7wpKXOht7WOkeOslvErbrf69Q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68724, 'Elysium', 'In the year 2159, two classes of people exist: the very wealthy who live on a pristine man-made space station called Elysium, and the rest, who live on an overpopulated, ruined Earth. Secretary Rhodes, a hard line government official, will stop at nothing to enforce anti-immigration laws and preserve the luxurious lifestyle of the citizens of Elysium. That doesn’t stop the people of Earth from trying to get in, by any means they can. When unlucky Max is backed into a corner, he agrees to take on a daunting mission that, if successful, will not only save his life, but could bring equality to these polarized worlds.', '2013-08-07', 6.53, 'https://image.tmdb.org/t/p/w500/aRjuJuPXHtVs6YegfeeQWXGRs1E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (69315, 'Battlestar Galactica: Razor', 'The history and adventures of the Battlestar Pegasus, from shortly before the Cylon invasion to shortly after Lee Adama is made commander. The story is told through the eyes of and largely focuses on one particular member of Pegasus''s crew, Kendra Shaw.', '2007-11-12', 7.18, 'https://image.tmdb.org/t/p/w500/tO3EoFJj0FJjKelDW5SUtquDIy2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68726, 'Pacific Rim', 'Using massive piloted robots to combat the alien threat, earth''s survivors take the fight to the invading alien force lurking in the depths of the Pacific Ocean. Nearly defenseless in the face of the relentless enemy, the forces of mankind have no choice but to turn to two unlikely heroes who now stand as earth''s final hope against the mounting apocalypse.', '2013-07-11', 6.94, 'https://image.tmdb.org/t/p/w500/8wo4eN8dWKaKlxhSvBz19uvj8gA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (69324, 'Rain', 'Janey is on vacation with her family at their beach house on the Mahurangi Peninsula in New Zealand. Her parents, Ed and Kate, are on the verge of divorce and sit around drinking whiskey all day, while Janey and Jim are left to their own devices. Cady, a local boaty who is having an affair with Kate, catches Janey''s pubescent eye.', '2001-09-01', 5.70, 'https://image.tmdb.org/t/p/w500/56TiWd7pdzYuFzObofLbKhFff7T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71679, 'Resident Evil: Retribution', 'The Umbrella Corporation’s deadly T-virus continues to ravage the Earth, transforming the global population into legions of the flesh eating Undead. The human race’s last and only hope, Alice, awakens in the heart of Umbrella’s most clandestine operations facility and unveils more of her mysterious past as she delves further into the complex. Without a safe haven, Alice continues to hunt those responsible for the outbreak; a chase that takes her from Tokyo to New York, Washington, D.C. and Moscow, culminating in a mind-blowing revelation that will force her to rethink everything that she once thought to be true. Aided by new found allies and familiar friends, Alice must fight to survive long enough to escape a hostile world on the brink of oblivion. The countdown has begun.', '2012-09-12', 5.83, 'https://image.tmdb.org/t/p/w500/ohdUDWVlcbuWphaLu6wS91xdJ73.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68734, 'Argo', 'As the Iranian revolution reaches a boiling point, a CIA ''exfiltration'' specialist concocts a risky plan to free six Americans who have found shelter at the home of the Canadian ambassador.', '2012-10-11', 7.29, 'https://image.tmdb.org/t/p/w500/m5gPWFZFIp4UJFABgWyLkbXv8GX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (66091, 'Ruthless Romance', 'In the town of Bryakhimov, noble but poor widow Harita Ignatyevna Ogudalova seeks to arrange marriages for her three daughters. She maintains an “open house”, hoping to attract gentlemen well-off enough to marry a dowry-less girl for love.', '1984-06-06', 7.20, 'https://image.tmdb.org/t/p/w500/q8On932TIIuOspcZnD9bu6jahbF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71723, 'Take Aim at the Police Van', 'A sniper kills two prisoners in a police van, and the driver sets out to find the killer.', '1960-01-27', 6.15, 'https://image.tmdb.org/t/p/w500/9lkQJVzUh0FWiOnoQWGhJ39vHCO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72105, 'Ted', 'John Bennett, a man whose childhood wish of bringing his teddy bear to life came true, now must decide between keeping the relationship with the bear or his girlfriend, Lori.', '2012-06-29', 6.45, 'https://image.tmdb.org/t/p/w500/1QVZXQQHCEIj8lyUhdBYd2qOYtq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71668, 'Piranha 3DD', 'After the events at Lake Victoria, the prehistoric school of blood-thirsty piranhas make their way into swimming pools, plumbing, and a newly opened water park.', '2012-05-11', 4.34, 'https://image.tmdb.org/t/p/w500/eOLA3IrZATSz5FQ6fmG0Q6sSVyq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71689, 'Phineas and Ferb the Movie: Across the 2nd Dimension', 'Phineas and Ferb get trapped in an alternate dimension where the evil Doofenshmirtz rules the tri-state area. They must find a way back home with the help of their pet platypus named Perry, who they discover is a secret agent.', '2011-08-05', 7.10, 'https://image.tmdb.org/t/p/w500/updMFSOZwEftfkJRpozwBlRlYI2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72215, 'Once Upon a Time, There Lived a Dog', 'Based on the Ukrainian folktale, the old dog of a village family is not as keen as he once was, and is sent away after he fails to guard their house during a robbery. In the woods, he meets the wolf he protected his masters against long ago, who decides to pay a favor to get his old enemy''s rightful place back in the doghouse.', '1982-11-10', 7.96, 'https://image.tmdb.org/t/p/w500/7YbdqmDM9h2VmkelGYDKLYbuC5y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72277, 'The Last Wave', 'A Sydney lawyer defends five Aboriginal people in a ritualised taboo murder and in the process learns disturbing truths about himself and premonitions.', '1977-12-15', 6.67, 'https://image.tmdb.org/t/p/w500/7UwdJ0EMXirUuNFaohfK023Nuyr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (66588, 'A Thousand Acres', 'The lives of an Iowa farmer''s three daughters are shattered when he suddenly decides to bequeath them the family''s fertile farm.', '1997-09-19', 5.73, 'https://image.tmdb.org/t/p/w500/p7tsW4oUi7hHbpNtFZdMQEBj42g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68737, 'Seventh Son', 'John Gregory, who is a seventh son of a seventh son and also the local spook, has protected the country from witches, boggarts, ghouls and all manner of things that go bump in the night. However John is not young anymore, and has been seeking an apprentice to carry on his trade. Most have failed to survive. The last hope is a young farmer''s son named Thomas Ward. Will he survive the training to become the spook that so many others couldn''t?', '2014-12-12', 5.53, 'https://image.tmdb.org/t/p/w500/7Q8DfXSjcFSSQDOxz1Sk865wNqI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71864, 'The Odd Life of Timothy Green', 'A childless couple bury a box in their backyard, containing all of their wishes for an infant. Soon, a child is born, though Timothy Green is not all that he appears.', '2012-08-15', 7.01, 'https://image.tmdb.org/t/p/w500/24HWf4QBnEbNYDJfNFR1CmwtST5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72331, 'Abraham Lincoln: Vampire Hunter', 'President Lincoln''s mother is killed by a supernatural creature, which fuels his passion to crush vampires and their slave-owning helpers.', '2012-06-20', 5.77, 'https://image.tmdb.org/t/p/w500/qv8deK0ZmutAuEpejruQKApIy6r.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68735, 'Warcraft', 'The peaceful realm of Azeroth stands on the brink of war as its civilization faces a fearsome race of invaders: orc warriors fleeing their dying home to colonize another. As a portal opens to connect the two worlds, one army faces destruction and the other faces extinction. From opposing sides, two heroes are set on a collision course that will decide the fate of their family, their people, and their home.', '2016-05-25', 6.41, 'https://image.tmdb.org/t/p/w500/eGi5aoxaZveqNLtE7BZJCuWwR3G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72358, 'A Thousand Words', 'Jack McCall is a fast-talking literary agent, who can close any deal, any time, any way. He has set his sights on New Age guru Dr. Sinja for his own selfish purposes. But Dr. Sinja is on to him, and Jack’s life comes unglued after a magical Bodhi tree mysteriously appears in his backyard. With every word Jack speaks, a leaf falls from the tree and he realizes that when the last leaf falls, both he and the tree are toast. Words have never failed Jack McCall, but now he’s got to stop talking and conjure up some outrageous ways to communicate or he’s a goner.', '2012-03-07', 6.13, 'https://image.tmdb.org/t/p/w500/hSxVSMHrW3epffELvi2CC5XdFXb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72387, 'Safe', 'After a former elite agent rescues a 12-year-old Chinese girl who''s been abducted, they find themselves in the middle of a standoff between Triads, the Russian Mafia and high-level corrupt New York City politicians and police.', '2012-04-16', 6.50, 'https://image.tmdb.org/t/p/w500/kOCpkoMUVae9UIf85gO71SyjLbW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72432, 'Puncture', 'Based on a true story. Mike Weiss (Chris Evans) is a brilliant but self-destructive Houston attorney whose drug addiction threatens to destroy his career. When he and his law partner Paul Danziger (Mark Kassen) take on a case involving a nurse injured by a contaminated needle, they uncover a $130 billion medical supply monopoly that has been blocking a life-saving safety', '2011-09-23', 6.66, 'https://image.tmdb.org/t/p/w500/sQD8NLW8ZsKHZMx9n7dLHSDgseH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72431, 'Red Tails', 'The story of the Tuskegee Airmen, the first African-American pilots to fly in a combat squadron during World War II.', '2012-01-19', 6.67, 'https://image.tmdb.org/t/p/w500/dXmhYTdeMiuQFW4VpiWbfjtxtl9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72525, 'Syrup', 'A slacker hatches a million-dollar idea. But, in order to see it through, he has to learn to trust his attractive corporate counterpart. Based on Max Barry''s novel.', '2013-06-07', 5.52, 'https://image.tmdb.org/t/p/w500/l3HSd4Nj6YKKUiE6q9WGow94f45.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72545, 'Journey 2: The Mysterious Island', 'Sean Anderson partners with his mom''s boyfriend on a mission to find his grandfather, who is thought to be missing on a mythical island.', '2012-01-19', 6.14, 'https://image.tmdb.org/t/p/w500/uFm2vnp9LhHx5MNo1Ego6O3vUhl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72559, 'G.I. Joe: Retaliation', 'Framed for crimes against the country, the G.I. Joe team is terminated by Presidential order. This forces the G.I. Joes into not only fighting their mortal enemy Cobra; they are forced to contend with threats from within the government that jeopardize their very existence.', '2013-03-27', 5.66, 'https://image.tmdb.org/t/p/w500/3rWIZMzTKcCtV0eHJ70Z4Ru659f.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72570, 'The Vow', 'Happy young married couple Paige and Leo are, well, happy. Then a car accident puts Paige into a life-threatening coma. Upon awakening she has lost the previous five years of memories, including those of her beloved Leo, her wedding, a confusing relationship with her parents, or the ending of her relationship with her ex-fiance. Despite these complications, Leo endeavors to win her heart again and rebuild their marriage.', '2012-02-05', 7.23, 'https://image.tmdb.org/t/p/w500/y5GUXzTvt7kSQbdQrSvbYNoa8HB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72185, 'Winnie the Pooh and Tigger Too', 'Rabbit is tired of Tigger always bouncing him, so he gets Pooh and Piglet together to come up with an idea to get the bounce out of Tigger. Then, Tigger and little Roo go out for a bounce and get caught in a tree.', '1974-12-20', 7.69, 'https://image.tmdb.org/t/p/w500/4DUGoHzZHxD22AL4OIGTkkBpqm9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72571, 'Paranormal Activity 3', 'In 1988, young sisters Katie and Kristi befriend an invisible entity who resides in their home.', '2011-10-19', 5.93, 'https://image.tmdb.org/t/p/w500/9nYranPiWdNmbD5PRPPSL7VUFTS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72585, 'Why Man Creates', 'A 1968 animation/documentary that criticises the industrial system.', '1968-09-24', 6.71, 'https://image.tmdb.org/t/p/w500/5w7A4i3vIZXKbkpvLIxOzwAlXtk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72784, 'The Loft', 'For five men, the opportunity to share a penthouse in the city -- in which to carry on extramarital affairs -- is a dream come true, until the dead body of an unknown woman turns up. Realizing that her killer must be one of their group, the men are gripped by paranoia as each one suspects another.', '2014-10-14', 6.40, 'https://image.tmdb.org/t/p/w500/msHg4MRKZBcGwIakhMEaYRSdYag.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72744, 'Pearl Jam Twenty', 'Carved from over 1,200 hours of footage spanning the band’s career, Pearl Jam: Twenty is the definitive portrait of Pearl Jam. Part concert film, part intimate insider-hang, and part testimonial to the power of music.', '2011-09-20', 7.80, 'https://image.tmdb.org/t/p/w500/d38PBlEsj5W9Od581GuWLeTuy4F.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72710, 'The Host', 'A parasitic alien soul is injected into the body of Melanie Stryder. Instead of carrying out her race''s mission of taking over the Earth, "Wanda" (as she comes to be called) forms a bond with her host and sets out to aid other free humans.', '2013-03-22', 6.29, 'https://image.tmdb.org/t/p/w500/1mfIZw6WgkCX310eoe0Ys14c3Fi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72867, 'Hellboy: The Seeds of Creation', 'A comprehensive look at the history of the Hellboy character from his comic book roots through to his movie debut.', '2004-07-27', 6.91, 'https://image.tmdb.org/t/p/w500/4qg5u2mLRMaTIs1rClhpjlcv7qc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72842, 'Albatross', 'Beth, a bookish teenager, befriends Emilia, an aspiring novelist who has just arrived in town. Emilia soon begins an affair with Beth''s father that threatens to have devastating consequences.', '2011-10-14', 6.03, 'https://image.tmdb.org/t/p/w500/5t8UtFxxdf0QtwUZZ5vF3ei91mO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72886, 'Mortal Kombat: The Journey Begins', 'As the three chosen defenders of Earth travel to Shang Tsung''s island, Rayden teaches them how to become the masters of their destinies, overcome their foes, and control their powers. Liu Kang, Sonya Blade and Johnny Cage must defeat Shang Tsung, Sub Zero, Scorpion and Goro in a tournament of Mortal Kombat if they are to survive and save the fate of the earth.', '1995-08-28', 3.90, 'https://image.tmdb.org/t/p/w500/11IzPcxoq22dqrftKgt5CZPHjhM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72976, 'Lincoln', 'The revealing story of the 16th US President''s tumultuous final months in office. In a nation divided by war and the strong winds of change, Lincoln pursues a course of action designed to end the war, unite the country and abolish slavery. With the moral courage and fierce determination to succeed, his choices during this critical moment will change the fate of generations to come.', '2012-11-09', 6.84, 'https://image.tmdb.org/t/p/w500/7mUYEkv9W3ek61eetZCfMQYVoi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (73183, 'The Haunted World of Edward D. Wood, Jr.', 'Often called the worst director in the history of cinema, Ed Wood is nevertheless a beloved figure among cult-film aficionados for his oddball productions. This documentary takes a look back at Wood''s unique career at the margins of 1950s Hollywood, speaking to those who loved him and hated him. Bela Lugosi Jr. discusses his father''s work in the abysmal "Plan 9 From Outer Space," while a Baptist reverend recalls how he was tricked into financing the film.', '1996-05-01', 7.77, 'https://image.tmdb.org/t/p/w500/gWbwYJIRisTiur9aqMQKSHkiGTB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (73079, 'Clara''s Heart', 'David is a teenager whose parents are in a deteriorating marriage after their infant daughter dies. Clara is a chambermaid at a Jamaican resort who''s hired to be a housekeeper. She and David develop a close bond, opening his eyes and heart to new experiences, and eventually leading to a disturbing secret in Clara''s past.', '1988-10-07', 5.51, 'https://image.tmdb.org/t/p/w500/sb5fGw0l8PVFPL14lu2UN7Ibed0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (73265, 'Campus Man', 'Todd Barret is an aspiring businessman. He''s got what it takes, but what he doesn''t have is enough money to stay in college. So he cooks up a plan to make the first ever all male sports calendar. He eventually convinces Cactus Jack, a very shadowy and tough loan shark, to give him enough money to make the deal. Todd makes enough to pay for his education, but what about the money he owes Cactus Jack?', '1987-04-10', 4.44, 'https://image.tmdb.org/t/p/w500/cb5QF2UKeP6z6oEp0c0nIwl36sw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (73499, 'The Double', 'The mysterious murder of a US senator bearing the distinctive trademark of the legendary Soviet assassin ''Cassius'', forces retired CIA operative, Paul Shepherson to team with rookie FBI agent, Ben Geary  to solve the crime. Having spent his career chasing Cassius, Shepherdson is convinced his nemesis is long dead, but is pushed to take on the case by his former supervisor, Tom Highland. Geary, who wrote his Master''s thesis on Shepherdson''s pursuit of the Soviet killer, is certain that Cassius has resurfaced.', '2011-10-27', 5.83, 'https://image.tmdb.org/t/p/w500/t4W10sjJSDAWRUDn2Kb8DQKxiZv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (73567, 'Killer Joe', 'A cop who moonlights as a hit man agrees to kill the hated mother of a desperate drug dealer in exchange for a tumble with the young man''s virginal sister.', '2012-06-07', 6.52, 'https://image.tmdb.org/t/p/w500/6Tt1TQeOI4TpXu1cBUgNGNGeznW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (73642, 'The Closer You Get', 'Irish lads send an ad to the Miami Herald inviting fit and enticing women, between the ages of 20 and 21, to live in their isolated Donegal village. The whole town knows about the ad, and it sharpens everyone''s sense of the opportunities for happiness already at hand. Kate, a publican with a young daughter, is separating from her husband and catches the eye of a bachelor sheep farmer. Kieran the butcher realizes that his assistant Siobhan is comely, and then he discovers she''s fiery as well. Ollie sends off for Dutch skin magazines that the village postmistress won''t release to him. The men, and women, find counsel in their movie-loving priest. Will anyone answer the ad?', '2000-12-27', 5.70, 'https://image.tmdb.org/t/p/w500/xeENuqgJtRcum0hJCrmUJ8HA4k8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (73861, 'A Serbian Film', 'Retired porn star Milos leads a normal family life trying to make ends meet. Presented with the opportunity of a lifetime to financially support his family for the rest of their lives, Milos must participate in one last mysterious film. From then on, Milos is drawn into a maelstrom of unbelievable cruelty and mayhem.', '2010-01-06', 5.45, 'https://image.tmdb.org/t/p/w500/yIQqiw3Az5QYNHLCUoCTtxXH24G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71859, 'We Need to Talk About Kevin', 'After her son Kevin commits a horrific act, troubled mother Eva reflects on her complicated relationship with her disturbed son as he grew from a toddler into a teenager.', '2011-09-28', 7.53, 'https://image.tmdb.org/t/p/w500/AtdYbs1SqYwFOLyi2v6ldVTawbn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71883, 'Redline', 'A daredevil driver is determined to compete in Redline, the most popular race in the galaxy. The race only occurs every five years, but in order to participate he must overcome the mafia, the government and even love.', '2009-08-14', 7.54, 'https://image.tmdb.org/t/p/w500/yUkH0y9OsY7J08Dvfzi1P0di559.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74336, 'The Quiet Family', 'A family decides to buy a lodge in a remote hiking area. Their first customer commits suicide and the distraught family buries his body to avoid the bad publicity. But their luck gets worse, the bodies start piling up, and the family becomes frantic to rectify the situation.', '1998-04-25', 7.04, 'https://image.tmdb.org/t/p/w500/6sCTGLgqcqHyXGgX9KFUKASIj8q.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74340, 'Amazing Grace and Chuck', 'Average American boy Chuck Murdock goes on a school outing to a nuclear weapons facility, where he learns about the destructive power that sits at the fingertips of the military. Knowing that the world could end with the push of a button, he protests against nuclear war by walking out on his Little League team during a game. Chuck''s stunt ends up in the local paper, and as the story snowballs, basketball star "Amazing Grace" Smith decides to boycott sports, too.', '1987-05-22', 5.88, 'https://image.tmdb.org/t/p/w500/uEp2ZuH22RN4uPXRX6Y40XCcqWF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68924, 'The Ice Storm', 'In the weekend after thanksgiving 1973 the Hood family is skidding out of control. Then an ice storm hits, the worst in a century.', '1997-09-27', 6.88, 'https://image.tmdb.org/t/p/w500/3a6uLta7K8Dzojps4RoJAPHD0km.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (71880, 'Jack and Jill', 'Jack Sadelstein, a successful advertising executive in Los Angeles with a beautiful wife and kids, dreads one event each year: the Thanksgiving visit of his twin sister Jill. Jill''s neediness and passive-aggressiveness is maddening to Jack, turning his normally tranquil life upside down.', '2011-11-11', 4.39, 'https://image.tmdb.org/t/p/w500/p6xV65iiz9agN2IAtf7cgbZC3YF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74387, 'Goon', 'Doug Glatt, a slacker who discovers he has a talent for brawling, is approached by a minor league hockey coach and invited to join the team as the "muscle." Despite the fact that Glatt can''t skate, his best friend, Pat, convinces him to give it a shot, and Glatt becomes a hero to the team and their fans, until the league''s reigning goon becomes threatened by Glatt''s success and decides to even the score.', '2012-01-06', 6.43, 'https://image.tmdb.org/t/p/w500/xLmZCfJici1SdT6zmhDtGVWsXXi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (68927, 'Born to Be Wild', 'Rick Heller is a juvenile delinquent who keeps getting himself into trouble. To keep him out of trouble his mother puts him to work cleaning the cage of a gorilla named Katie which she is teaching to communicate through the use of sign language. When the owner of the gorilla takes her back to become a flea market freak Rick takes it upon himself to break Katie out and take her on an adventurous journey to get her out of the country.', '1995-03-31', 5.34, 'https://image.tmdb.org/t/p/w500/n5SyB9589EQrkyPxdQJhN1pl6xn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72203, 'Karlson Returns', 'The Kid didn''t have to miss Carlson for long - one day he landed in his room again. This means that there will be new adventures and pranks! With Carlson''s help, the harsh and bossy Freken Bock will be re-educated and become very kind. And then the friends will all put on a costume show with dancing and drink tea with buns.', '1970-10-18', 7.10, 'https://image.tmdb.org/t/p/w500/utLLi3IYWiqjBiepXnqXsUYRCE1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74306, 'God Bless America', 'Fed up with the cruelty and stupidity of American culture, an unlikely duo goes on a killing spree, killing reality TV stars, bigots and others they find repugnant.', '2012-05-11', 6.96, 'https://image.tmdb.org/t/p/w500/jEyiGve8BLOCvi8R2tL8H52aLp4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74461, 'Knights of Badassdom', 'Three best friends and dedicated roleplayers take to the woods to reenact a dungeons and dragons-like scenario as a live action role-playing game. Trouble arises when a prop spellbook purchased from the internet ends up being a genuine grimoire and they unwittingly conjure up a blood-lusting succubus from hell.', '2014-01-21', 5.55, 'https://image.tmdb.org/t/p/w500/7hxpi2Y7JNGHmETL2VAPONhvHGZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72083, 'Death of a Cyclist', 'A couple having an affair strike a bicyclist with their car and do not offer aid out of fear of their relationship being exposed.', '1955-09-07', 7.12, 'https://image.tmdb.org/t/p/w500/trjTovQqGyImjieaQPBEtf5jHLF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74777, 'Absentia', 'Tricia''s husband has been missing for seven years. Her younger sister Callie comes to live with her as the pressure mounts to finally declare him ''dead in absentia''. Tricia is reluctant, always holding out hope, but Callie is practical and wants her to move on. As Tricia sifts through the wreckage and tries to move on with her life, Callie finds herself drawn to an ominous tunnel near the house.', '2011-03-03', 5.83, 'https://image.tmdb.org/t/p/w500/imUIPWoe0Yma5UhZVl6bqX5lF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74836, 'Idaho Transfer', 'During a time of waning global resources, a crew of young researchers travel into the future to escape an apocalypse before the shutdown of their time transfer project. They find that some type of disaster has de-populated the Idaho region and, by implication, the nation or perhaps the world.', '1973-06-15', 4.91, 'https://image.tmdb.org/t/p/w500/lH7Yhx25msadOP3vbftdD8TXNS3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74849, 'The Star Wars Holiday Special', 'Luke Skywalker and Han Solo battle evil Imperial forces to help Chewbacca reach his imperiled family on the Wookiee planet - in time for Life Day, their most important day of the year!', '1978-11-17', 3.38, 'https://image.tmdb.org/t/p/w500/lGJDx7RCgyMMa3owtp150umMnnJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75174, 'The Grey', 'After their plane crashes in Alaska, six oil workers are led by a skilled huntsman to survival, but a pack of merciless wolves haunts their every step.', '2012-01-26', 6.58, 'https://image.tmdb.org/t/p/w500/a0Vt3wx8ciKmPt4iXPx9sH4HBVU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74998, 'Seeking Justice', 'After his wife is assaulted, a husband enlists the services of a vigilante group to help him settle the score.', '2011-09-02', 5.93, 'https://image.tmdb.org/t/p/w500/lN3O0j1DKVnwhO1h5J3utrmrBF2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (72207, 'The Five-Year Engagement', 'Exactly one year after Tom meets Violet, he surprises her with a wedding ring. By all accounts, Tom and Violet are destined for their happily ever after. However, this engaged couple just keep getting tripped up on the long walk down the aisle.', '2012-04-27', 5.85, 'https://image.tmdb.org/t/p/w500/4Bj6pw3ZCo1f2DXP4k7AUDwMTFX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75386, 'Haiku Tunnel', 'Josh is the consummate temp employee, avoiding all long-term connections and responsibilities, both at work and in his personal life. However, by the time his agency places him at the Schuyler &amp; Mitchell law firm, Josh is tired of his temporary life and agrees to take a permanent position at the firm. Josh has difficulty adapting to his new lifestyle, which manifests in his inability to complete his simple initial task: mailing seventeen important letters.', '2001-09-07', 6.46, 'https://image.tmdb.org/t/p/w500/9xVw4EtCcNcI9RmRdH4WRPZkwcJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75301, 'Being Elmo: A Puppeteer''s Journey', 'Beloved by children of all ages around the world, Elmo is an international icon. Few people know his creator, Kevin Clash, who dreamed of working with his idol, master puppeteer Jim Henson. Displaying his creativity and talent at a young age, Kevin ultimately found a home on Sesame Street. Narrated by Whoopi Goldberg, this documentary includes rare archival footage, interviews with Frank Oz, Rosie O’Donnell, Cheryl Henson, Joan Ganz Cooney and others and offers a behind-the-scenes look at Sesame Street and the Jim Henson Workshop.', '2011-10-21', 7.21, 'https://image.tmdb.org/t/p/w500/7W2jIcJoWyMaYNiSkCxhZQX3OQF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75491, 'The Rabbi''s Cat', 'The story of a rabbi and his talking cat, a sharp-tongued feline philosopher brimming with scathing humor and a less than pure love for the rabbi''s teenage daughter.', '2011-05-31', 7.02, 'https://image.tmdb.org/t/p/w500/pcjwhq6hF3z2Wir0ZcKHTxmtRsH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75629, 'Evangelion: 3.0 You Can (Not) Redo', 'Fourteen years after Third Impact, Shinji Ikari awakens to a world he does not remember. He hasn''t aged. Much of Earth is laid in ruins, NERV has been dismantled, and people who he once protected have turned against him. Befriending the enigmatic Kaworu Nagisa, Shinji continues the fight against the angels and realizes the fighting is far from over, even when it could be against his former allies. The characters'' struggles continue amidst the battles against the angels and each other, spiraling down to what could inevitably be the end of the world.', '2012-11-17', 7.20, 'https://image.tmdb.org/t/p/w500/d0s1xvykzl0kz7fP5S2ROYqphdz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75612, 'Oblivion', 'Jack Harper is one of the last few drone repairmen stationed on Earth. Part of a massive operation to extract vital resources after decades of war with a terrifying threat known as the Scavs, Jack’s mission is nearly complete. His existence is brought crashing down when he rescues a beautiful  stranger from a downed spacecraft. Her arrival triggers a chain of events that  forces him to question everything he knows and puts the fate of humanity in his hands.', '2013-04-10', 6.69, 'https://image.tmdb.org/t/p/w500/bYLM3GpNUZnoFElPXp1zlhDPdtv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75674, 'Act of Valor', 'When a covert mission to rescue a kidnapped CIA operative uncovers a chilling plot, an elite, highly trained U.S. SEAL team speeds to hotspots around the globe, racing against the clock to stop a deadly terrorist attack.', '2012-02-24', 6.56, 'https://image.tmdb.org/t/p/w500/1Xcd5ci69pVXMPP02DU11Ffq0yY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75725, 'A Christmas Tale', 'Cubelles, Tarragona, Spain, Christmas 1985. Five friends make an unexpected discovery in the forest: a woman disguised as Santa Claus trapped in a deep hole dug in the middle of nowhere.', '2005-10-27', 6.36, 'https://image.tmdb.org/t/p/w500/xQyNqN5coVrmUCPgmrOMmMg53Ba.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75656, 'Now You See Me', 'An FBI agent and an Interpol detective track a team of illusionists who pull off bank heists during their performances and reward their audiences with the money.', '2013-05-29', 7.33, 'https://image.tmdb.org/t/p/w500/tWsNYbrqy1p1w6K9zRk0mSchztT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75761, 'John Dies at the End', 'A new drug promises out-of-body experiences, but users are coming back changed forever, and an otherworldly invasion of Earth is underway.', '2013-01-25', 6.25, 'https://image.tmdb.org/t/p/w500/1IsviP0Tb05xUAFWz5b7FJ0qIHP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75736, 'Catch.44', 'The lives of three female assassins take a sudden turn when their charming boss lures them into one last job. They soon find themselves thrust into a bizarre situation involving a psychotic hit man, a grizzled trucker and a delusional line cook.', '2011-12-08', 5.04, 'https://image.tmdb.org/t/p/w500/mbDQA2a3H9CbEHr7bDkaqxAGDO1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (75780, 'Jack Reacher', 'One morning in an ordinary town, five people are shot dead in a seemingly random attack. All evidence points to a single suspect: an ex-military sniper who is quickly brought into custody. The interrogation yields one written note: ''Get Jack Reacher!''. Reacher, an enigmatic ex-Army investigator, believes the authorities have the right man but agrees to help the sniper''s defense attorney. However, the more Reacher delves into the case, the less clear-cut it appears. So begins an extraordinary chase for the truth, pitting Jack Reacher against an unexpected enemy, with a skill for violence and a secret to keep.', '2012-12-20', 6.68, 'https://image.tmdb.org/t/p/w500/uQBbjrLVsUibWxNDGA4Czzo8lwz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
