INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (76696, 'Sidewalls', 'Martin is a neurotic web designer taking baby steps out of the isolation of his one-room apartment and his virtual reality. Mariana is an artist fresh out of a long relationship. They are perfect for each other, live on the same street, in opposite buildings, but they never meet. Can the movement of a modern city of three million people bring them together?', '2011-06-01', 7.50, 'https://image.tmdb.org/t/p/w500/4LkufGzat0GMRDEr88w0oHQM2CD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
