INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77067, 'DeadHeads', 'Two inexplicably coherent zombies awake amidst a zombie attack and decide to take a road trip to find the one''s lost love, unaware they are being chased by the agents of a ruthless company with its own agenda.', '2011-04-29', 5.07, 'https://image.tmdb.org/t/p/w500/uDhZDedBv9eRDkuJSTbM77EmHI1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
