INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77294, 'Three from Prostokvashino', 'Little Fedor brings a cat to home despite his mother''s distaste for cats. He runs away with his talking cat, to make more friends on the way.', '1978-06-06', 7.34, 'https://image.tmdb.org/t/p/w500/wA46TGkU7lz7QvkiemrwvpN0A29.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77223, 'Paradise Road', 'A group of English, American, Dutch and Australian women creates a vocal orchestra while being imprisoned in a Japanese POW camp on Sumatra during World War II.', '1997-02-11', 6.35, 'https://image.tmdb.org/t/p/w500/mEA7Iv1e6HqpSGMfVUdUfYOusNU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77304, 'Junior and Karlson', 'A Soviet cult cartoon, so untypical for a Western viewer, especially, a little one. A boy named Malysh ("A Little One") suffers from solitude being the youngest of the three children in a Swedish family. The acute sense of solitude makes him desperately want a dog, but before he gets one, he "invents" a friend - the very Karlson who lives upon the roof. So typical for the Russian culture spirit of mischief, which is, actually, never punished, and the notion that relative welfare not necessarily means happiness made the book by Astrid Lindgren and its TV adaptations tremendously popular in the Soviet Union and nowadays Russia and vice versa - somewhat alienated to the Western reader and viewer (see User''s comments below). However, both the book and the cartoon are truly universal - entertaining and funny for the children and thought-provoking and somewhat sad for grownups.', '1968-10-09', 6.96, 'https://image.tmdb.org/t/p/w500/H4WHAm4yHcTUMvPgupZ5OcV4nc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (73884, 'My Life as McDull', 'McDull is not the brightest kid on the block, but he continuously tries to do his best to please his mother. Still it seems he may not be destined for great things like she wishes, but McDull strives to try anyway.', '2001-12-15', 7.04, 'https://image.tmdb.org/t/p/w500/iyMQFIzidWRnjSjpPps1y5nFOPj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77338, 'The Intouchables', 'A true story of two men who should never have met – a quadriplegic aristocrat who was injured in a paragliding accident and a young man from the projects.', '2011-11-02', 8.30, 'https://image.tmdb.org/t/p/w500/1QU7HKgsQbGpzsJbJK4pAVQV9F5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
