INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77469, 'Your Friends & Neighbors', 'Restless and unhappy, two couples get caught up in infidelity and deception. Barry is a sullen businessman married to Mary, a writer who is unsatisfied with their relationship. Mary begins an affair with Jerry, a smug theater professor and husband of her friend, Terri, who is also a writer. Adding to the adulterous mix are Cary, a callous doctor, and Cheri, an art-gallery assistant.', '1998-08-19', 5.82, 'https://image.tmdb.org/t/p/w500/g8u6Hx7F7V2gFr5ddyLQPzQ8f3t.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77365, 'Into the Abyss', 'We do not know when and how we will die. Death Row inmates do. Werner Herzog embarks on a dialogue with Death Row inmates, asks questions about life and death and looks deep into these individuals, their stories, their crimes.', '2011-11-11', 6.90, 'https://image.tmdb.org/t/p/w500/omYLK5w7N5YeWi4gFcNTylgvL8j.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
