INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (73937, 'The Big Year', 'Three fanatical bird-watchers spend an entire year competing to spot the highest number of species as El Nino sends an extraordinary variety of rare breeds flying up into the U.S., but they quickly discover that there are more important things than coming out on top of the competition.', '2011-10-13', 5.99, 'https://image.tmdb.org/t/p/w500/q6Pr8fWKh664seri2MaQeIJ6eSI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (76494, 'What to Expect When You''re Expecting', 'Challenges of impending parenthood turn the lives of five couples upside down. Two celebrities are unprepared for the surprise demands of pregnancy; hormones wreak havoc on a baby-crazy author, while her husband tries not to be outdone by his father, who''s expecting twins with his young trophy wife; a photographer''s husband isn''t sure about his wife''s adoption plans; a one-time hook-up results in a surprise pregnancy for rival food-truck owners.', '2012-05-17', 6.00, 'https://image.tmdb.org/t/p/w500/dHLN64hvTtbqVqeJI67Ali5XSBE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
