INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77950, 'Turbo', 'The tale of an ordinary garden snail who dreams of winning the Indy 500.', '2013-07-11', 6.28, 'https://image.tmdb.org/t/p/w500/inTKQni4YW8syrfgnXHwzmNeSo4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
