INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77561, 'EVA', 'In 2041, humans live side-by-side with robots and androids. A well-known cybernetic engineer, Alex Garel, returns to his hometown to create a new model of robot child.', '2011-10-06', 6.39, 'https://image.tmdb.org/t/p/w500/9GH6VRhwI5SrD178aqPCI1Xpf4P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (76338, 'Thor: The Dark World', 'Thor fights to restore order across the cosmos… but an ancient race led by the vengeful Malekith returns to plunge the universe back into darkness. Faced with an enemy that even Odin and Asgard cannot withstand, Thor must embark on his most perilous and personal journey yet, one that will reunite him with Jane Foster and force him to sacrifice everything to save us all.', '2013-10-30', 6.51, 'https://image.tmdb.org/t/p/w500/wp6OxE4poJ4G7c0U2ZIXasTSMR7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77759, 'Vacations in Prostokvashino', 'The continuation of the adventures of Fyodor and his friends from the Prostokvashino village.', '1980-06-06', 7.49, 'https://image.tmdb.org/t/p/w500/1bBh1oQF2FznRkcudz7NcCiHSE9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74535, 'Adventures of Captain Vrungel', 'An old sea captain and his student decide to take part in the international regatta. At the same time an amateur thief steals a statue of Aphrodite from Louvre and boards their yacht by mistake. A long, fun adventure is ahead.', '1980-03-24', 7.64, 'https://image.tmdb.org/t/p/w500/mTKUENSIX7Ylam8XTHw05Ec67Uw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (76543, 'Tyrannosaur', 'The story of Joseph, a man plagued by violence and a rage that is driving him to self-destruction. As Joseph''s life spirals into turmoil a chance of redemption appears in the form of Hannah, a Christian charity shop worker. Their relationship develops to reveal that Hannah is hiding a secret of her own with devastating results on both of their lives.', '2011-10-07', 7.25, 'https://image.tmdb.org/t/p/w500/p6PJGuO6K94YylUcAsTTn7Q4cQn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74692, 'Rare Birds', 'A down-and-out restaurateur and his neighbor hatch a plan to lure bird watchers to their small Newfoundland town and increase tourism by announcing the presence of a rare duck.', '2001-09-09', 5.33, 'https://image.tmdb.org/t/p/w500/z0tTXhUzG9mwKVliv74LBe7gGdy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (79216, 'The Magic Ring', 'Vanya has no money at all, and he gave away his last piece of clothing to save some poor animals. Now he has a cat, a dog, and a snake living in his house. But it turns out that the snake is the king''s daughter, so she gave him a magic ring as a gift for saving her. Now Vanya can wish for anything he wants, and his wish will come true!', '1979-01-01', 7.80, 'https://image.tmdb.org/t/p/w500/3JI7Brdc1wNMUqWXlZBIs2i7m40.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (79218, 'Ice Age: A Mammoth Christmas', 'When Sid accidentally destroys Manny''s heirloom Christmas rock and ends up on Santa''s naughty list, he leads a hilarious quest to the North Pole to make things right and ends up making things much worse. Now it''s up to Manny and his prehistoric posse to band together and save Christmas for the entire world!', '2011-11-24', 6.45, 'https://image.tmdb.org/t/p/w500/ue5417HaDcvgMDusryenwwwZARq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77762, 'Winter in Prostokvashino', 'A third movie about Fyodor and his friends from the Prostokvashino village and their adventures - this time during the winter.', '1984-06-06', 7.62, 'https://image.tmdb.org/t/p/w500/npVjTdinip4kvViCjLpBIY44jXB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (79406, 'Samurai Assassin', 'Japan, 1860. The men of the Mito clan, victims of the Ansei purge, anxiously prowl around the Sakurada Gate of Edo Castle with the intention of assassinating Naosuke Ii of Hikone, tairō of the Tokugawa shogunate and responsible for their misfortune.', '1965-01-03', 7.30, 'https://image.tmdb.org/t/p/w500/p4Z3hIghFiJZdr9fIVMzRn8Rxgu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (74534, 'The Best Exotic Marigold Hotel', 'British retirees travel to India to take up residence in what they believe is a newly restored hotel. Less luxurious than its advertisements, the Marigold Hotel nevertheless slowly begins to charm in unexpected ways as the residents find new purpose in their old age.', '2012-02-23', 7.00, 'https://image.tmdb.org/t/p/w500/gNWiOKTWDvPTpr7QfPWk18gLftz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (79515, 'Black Tar Heroin: The Dark End of the Street', 'The film follows a simple structure, and shows the drug-related degradation of five youths (Jake, Tracey, Jessica, Alice, Oreo) during the course of three years. The film depicts drug-related crimes and diseases: prostitution, male prostitution, AIDS, and lethal overdoses.', '2000-03-17', 6.78, 'https://image.tmdb.org/t/p/w500/vbJuchlaqKwGtkHKe5QL7Sm2CfV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (79548, 'Gone', 'Jill Conway is trying to rebuild her life after escaping a terrifying kidnapping. Though she is having a difficult time, she takes small steps toward normalcy by starting a new job and inviting her sister, Molly, to move in with her. Returning home from work one morning, Jill discovers that Molly has vanished, and she is certain that the same man who previously abducted her has returned for revenge.', '2012-02-23', 6.24, 'https://image.tmdb.org/t/p/w500/5GcbQhm0Qbbf1qt24spUpqX5tfP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (79698, 'The Lovers', 'The Lovers is an epic romance time travel adventure film. Helmed by Roland Joffé from a story by Ajey Jhankar, the film is a sweeping tale of an impossible love set against the backdrop of the first Anglo-Maratha war across two time periods and continents and centred around four characters — a British officer in 18th century colonial India, the Indian woman he falls deeply in love with, an American present-day marine biologist and his wife.', '2015-03-13', 4.78, 'https://image.tmdb.org/t/p/w500/6esL8UH2sXXqbfbaV6bFEUBCDOr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (79896, 'The Revenant', 'A horror movie/buddy comedy about Joey and his undead friend Bart who comes back from the dead as a revenant: an articulate zombie that needs to drink blood to arrest the decomposition of his body.', '2009-08-16', 6.20, 'https://image.tmdb.org/t/p/w500/bECzzYkRFlCZZAjQ9wboMGyWFcL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77780, 'Twister', 'An oddball family on a Kansas farm are trapped in their farmhouse by an impending storm. The patriarch of the clan is a retired soda pop tycoon. He is currently dating a children''s TV evangelist. Also living at the farm is his layabout daughter and her precocious 8 year old daughter, his would-be artist son, the son''s fiancée, and the black maid. Also thrown into the mix is the daughter''s ex-husband, a ne-er-do-well who is seeking to get back in his ex-wife''s good graces.', '1989-06-30', 5.63, 'https://image.tmdb.org/t/p/w500/f3Wf4mR6SmqzLae7extudBfpL4b.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (79723, 'New Kids Nitro', 'Gerrie, Richard, Rikkert, Robbie and Barry from Maaskantje are in a big fight with the village of Schijndel. When a zombie kills someone from Brabant, things get out of hand.', '2011-12-07', 6.07, 'https://image.tmdb.org/t/p/w500/2NyrICtZIlDvJjzcau2tUkqdhGw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80035, 'The Watch', 'Four everyday suburban guys come together as an excuse to escape their humdrum lives one night a week. But when they accidentally discover that their town has become overrun with aliens posing as ordinary suburbanites, they have no choice but to save their neighborhood – and the world – from total extermination.', '2012-07-26', 5.60, 'https://image.tmdb.org/t/p/w500/gwfgYA9wGpV4QLB0LrcexwfwC19.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80038, 'Friends with Kids', 'In the wake of their friends'' marriages and eventual offspring, longtime pals Julie and Jason decide to have a child together without becoming a couple. By becoming "time-share" parents, they reason, they can experience the joys of parenthood without significantly curbing their personal freedom. However, when Julie and Jason both become involved with others, they discover that they secretly harbor romantic feelings for each other.', '2012-03-09', 5.93, 'https://image.tmdb.org/t/p/w500/cA6putv2ND8snBBa0t9WhlW1TfG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (79701, 'Gena the Crocodile', 'First animation about Gena and Cheburashka. Gena the Crocodile works as a zoo animal at an urban zoo. Every evening, he returns home to his lonely apartment. Gena gets very tired of playing chess against himself and decides to find some friends to play with. Animals and people respond to advertisements that he posts all around the city. First, a girl named Galya comes with a homeless puppy, who is then followed by Cheburashka. They decide to build a house for all the lonely citizens of the city, but a mischievous old lady, Shapoklyak, tries to stop them in different ways.', '1969-12-30', 7.69, 'https://image.tmdb.org/t/p/w500/kw6UmmvqYnaPIdw24WoD83Akfod.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (76406, 'Tokyo-Ga', 'German director Wim Wenders tries to explore the Tokyo that was depicted in the films of Yasujiro Ozu and finds a very different city.', '1985-04-24', 7.08, 'https://image.tmdb.org/t/p/w500/uNH1TqJPFuoxW0YZmwBuiZqSBU1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80125, 'Woman in Love', 'An actor''s career takes a "Tootsie"-like turn when he lets himself be cast as a woman in a movie.', '2011-12-15', 5.89, 'https://image.tmdb.org/t/p/w500/9SmlwvWXuGU0OdrN78Cp9Tg2PTd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80215, 'Indie Game: The Movie', 'Follows the dramatic journeys of video game developers as they create and release their games to the world. It''s about making video games, but at its core, it''s about the creative process, and exposing yourself through your work.', '2012-05-18', 7.50, 'https://image.tmdb.org/t/p/w500/2B1IqPg97ZhpEov4Fg3si4hI1Kw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80271, 'LOL', 'In a world connected by YouTube, iTunes, and Facebook, Lola and her friends navigate the peer pressures of high school romance and friendship while dodging their sometimes overbearing and confused parents. When Lola''s mom, Anne, "accidentally" reads her teenage daughter''s racy journal, she realizes just how wide their communication gap has grown.', '2012-02-10', 6.10, 'https://image.tmdb.org/t/p/w500/AlnBUoKzzPnczrzzxuh0SYwDa3Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80274, 'Ender''s Game', 'Based on the classic novel by Orson Scott Card, Ender''s Game is the story of the Earth''s most gifted children training to defend their homeplanet in the space wars of the future.', '2013-10-24', 6.59, 'https://image.tmdb.org/t/p/w500/pVcRI5YKnkkgaAD876jBeKb189d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80278, 'The Impossible', 'In December 2004, close-knit family Maria, Henry and their three sons begin their winter vacation in Thailand. But the day after Christmas, the idyllic holiday turns into an incomprehensible nightmare when a terrifying roar rises from the depths of the sea, followed by a wall of black water that devours everything in its path. Though Maria and her family face their darkest hour, unexpected displays of kindness and courage ameliorate their terror.', '2012-09-09', 7.38, 'https://image.tmdb.org/t/p/w500/k0DLCiDbnYywOHiISALbl2EH2NE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80287, 'Rent-a-Cop', 'Detective Tony Church is forced to retire and become a store rent-a-cop when his drug sting operation comes to a tragic end by a masked killer. He joins forces with a prostitute, the only one able to identify the killer, to bring him to justice.', '1987-11-28', 4.69, 'https://image.tmdb.org/t/p/w500/q7nRrivfDnCiUJru7A6ZYNXnOe0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80321, 'Madagascar 3: Europe''s Most Wanted', 'Animal pals Alex, Marty, Melman, and Gloria are still trying to make it back to New York''s Central Park Zoo. They are forced to take a detour to Europe to find the penguins and chimps who broke the bank at a Monte Carlo casino. When French animal-control officer Capitaine Chantel DuBois picks up their scent, Alex and company are forced to hide out in a traveling circus.', '2012-06-06', 6.65, 'https://image.tmdb.org/t/p/w500/ekraj4ksvIKeuvQVEevEJkuybZd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80379, 'Louis C.K.: Live at the Beacon Theater', 'Recorded November 10th, 2011 as part of the New York Comedy Festival, and only available for purchase online, Louis C.K. follows up his 2010 concert film Hilarious with a new hour’s worth of shrewdly observed and periodically profane material. He starts with making his own kind of please-turn-off-your-cell-phone announcement, as well as a warning not to text or tweet during the show: “Just live your life,” he asks. Whether he’s talking about a unique way to drop a rental car off at an airport or describing why a man in his 40s should not smoke dope, it’s terrific, humane, carried-to-crazed-extremes stuff.', '2011-12-10', 7.81, 'https://image.tmdb.org/t/p/w500/bGntW92XqJ66EIQdBeseee1Q7Um.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80280, '[REC]³ Genesis', 'A pair of newlyweds must fight to survive when their wedding reception descends into chaos and carnage when their guests become infected by a virus that turns them into hungry zombies.', '2012-03-30', 5.34, 'https://image.tmdb.org/t/p/w500/tI1534q0Up7PBcLdXdFerLmIXn3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (78373, 'Dancer, Texas Pop. 81', 'Four guys, best friends, have grown up together in DANCER, TEXAS POP. 81, a tiny town in West Texas. Years ago, they made a solemn vow to leave town together as soon as they graduate. Now, it''s that weekend and the time has come to "put up or shut up." The clock is ticking and as all 81 people in the town watch, comment, offer advice and place bets, these four very different boys with unique backgrounds struggle with the biggest decision of their lives... whether to stay or leave home.', '1998-05-01', 6.97, 'https://image.tmdb.org/t/p/w500/khV9zPcvgOjrqwlk3dI1lGojZib.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80468, 'Some Guy Who Kills People', 'A former mental patient''s repressed anger reaches the boiling point, leading him to embark on a mission of revenge against the thugs who once subjected him to severe physical and mental trauma.', '2011-04-14', 6.07, 'https://image.tmdb.org/t/p/w500/m6sqWQDcg7er0dg7LomMQGeVBMO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80389, 'Get the Gringo', 'A career criminal nabbed by Mexican authorities is placed in a tough prison where he learns to survive with the help of a 9-year-old boy.', '2012-03-15', 6.61, 'https://image.tmdb.org/t/p/w500/sLzL1xG6JgVEEQ4DqSJpnJw3D2A.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80708, 'The Divorcee', 'When a woman discovers that her husband has been unfaithful, she decides to pay him back in kind.', '1930-04-19', 6.23, 'https://image.tmdb.org/t/p/w500/zzu6IW9ilkUt6L4DL9SoNnwtAfy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80767, 'Jiro Dreams of Sushi', 'Revered sushi chef Jiro Ono strives for perfection in his work, while his eldest son, Yoshikazu, has trouble living up to his father''s legacy.', '2011-06-11', 7.73, 'https://image.tmdb.org/t/p/w500/iVrkM4jSJw1IsOpW5jTtY5QxVqj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77875, 'Playing for Keeps', 'A former sports star who''s fallen on hard times starts coaching his son''s soccer team in an attempt to get his life together.', '2012-11-29', 5.65, 'https://image.tmdb.org/t/p/w500/jYv6MqOoAIpxZd6ydJ4S5S2QHDZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77877, 'The Lucky One', 'A Marine travels to Louisiana after serving three tours in Iraq and searches for the unknown woman he believes was his good luck charm during the war.', '2012-04-19', 7.17, 'https://image.tmdb.org/t/p/w500/vF1ZuIkF9Z71VzVvG265xJUawb0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (76516, 'Meet the Applegates', 'Modelling themselves after an idyllic cookie-cutter suburban 1950s family, a colony of insects move from South America into the United States with the intent of getting access to the nation''s nuclear resources.', '1990-06-06', 5.59, 'https://image.tmdb.org/t/p/w500/j79gY4zUgtpcDNpYh8esIer2aWS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80518, 'Fullmetal Alchemist: The Sacred Star of Milos', 'A fugitive alchemist with mysterious abilities leads the Elric brothers to a distant valley of slums inhabited by the Milos, a proud people struggling against bureaucratic exploitation. Ed and Al quickly find themselves in the middle of a rising rebellion, as the exiled Milos lash out against their oppressors. At the heart of the conflict is Julia, a young alchemist befriended by Alphonse. She''ll stop at nothing to restore the Milos to their former glory – even if that means harnessing the awful power of the mythical Philosopher''s Stone.', '2011-07-02', 6.80, 'https://image.tmdb.org/t/p/w500/7RvBQOTZGhCoPvLiF3Ugp2Q94Ux.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77801, 'Miss Representation', 'The film MISS REPRESENTATION exposes how American youth are being sold the concept that women and girls’ value lies in their youth, beauty and sexuality. Explores the under-representation of women in positions of power and influence in America, and challenges the media''s limited portrayal of what it means to be a powerful woman. It’s time to break that cycle of mistruths.', '2011-01-20', 6.93, 'https://image.tmdb.org/t/p/w500/98owJxMsoARozljBXpQXH93v2fF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (79159, 'Tilt', 'TILT is a love story set against the backdrop of the changing political and social environment in Europe in the late 80''s and early 90''s. Can this love survive the challenges of emigration, a violent homeland and immoral social atmosphere thanks to a gang of adventurous friends?', '2011-01-28', 5.97, 'https://image.tmdb.org/t/p/w500/32A3d2Qvky7C7Ey83mCEelb3jB1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80919, 'Game 6', 'Combining real and fictional events, this movie centers around the historic 1986 World Series, and a day in the life of a playwright who skips opening night to watch the momentous game.', '2006-03-10', 4.55, 'https://image.tmdb.org/t/p/w500/nwXLO5SWMt7xTIPhPMcM1qBZJxg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77866, 'Contraband', 'When his brother-in-law runs afoul of a drug lord, family man Chris Farraday turns to a skill he abandoned long ago—smuggling—to repay the debt. But the job goes wrong, and Farraday finds himself wanted by cops, crooks and killers alike.', '2012-01-12', 6.35, 'https://image.tmdb.org/t/p/w500/c9NQDANheSz887myHeMocUKQ5Je.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80965, 'Blind Date', 'A man goes blind when remembering his lost girlfriend, but the doctors can''t find anything wrong with his eyes. They fit him with an experimental device which allows him to see with the aid of a computer interface and brain electrodes. Meanwhile, a taxi driver is taking young women up to their apartments, giving them gas, and performing a little fatal amateur surgery on them. Their paths inevitably converge, and the blind man must try to stop the psychopath.', '1984-03-15', 4.30, 'https://image.tmdb.org/t/p/w500/totM9TbQJ31X2qfp0D5G7baccXm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77915, 'The Sandpiper', 'A free-spirited single mother forms a connection with the wedded headmaster of an Episcopalian boarding school in Monterey, California.', '1965-06-23', 6.40, 'https://image.tmdb.org/t/p/w500/cOEIl9QjFe6Pt5W7hbkt2Hy7EfX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80585, 'Rock of Ages', 'A small town girl and a city boy meet on the Sunset Strip, while pursuing their Hollywood dreams.', '2012-06-13', 6.19, 'https://image.tmdb.org/t/p/w500/oVeE2QTUb14jPU2lYEGPE3s8T9j.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81796, 'Lockout', 'Set in the near future, Lockout follows a falsely convicted ex-government agent , whose one chance at obtaining freedom lies in the dangerous mission of rescuing the President''s daughter from rioting convicts at an outer space maximum security prison.', '2012-04-12', 5.94, 'https://image.tmdb.org/t/p/w500/i5QfNIcg6hc327IWUerea0EczP4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81895, 'MacGyver: Lost Treasure of Atlantis', 'Hunting artifacts attributed to Zenon (an ancient scientist from Atlantis), MacGyver and his old professor end up searching for the lost city.', '1994-05-14', 6.30, 'https://image.tmdb.org/t/p/w500/hcmocdC6Rp0w6C8M4i1yvewmgNL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81836, 'To Rome with Love', 'Four tales unfold in the Eternal City: While vacationing in Rome, architect John encounters a young man whose romantic woes remind him of a painful incident from his own youth; retired opera director Jerry discovers a mortician with an amazing voice, and he seizes the opportunity to rejuvenate his own flagging career; a young couple have separate romantic interludes; a spotlight shines on an ordinary man.', '2012-04-20', 5.79, 'https://image.tmdb.org/t/p/w500/sMmYRgvFRk5Ginhytx7ciU7UwVs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81001, 'Kiss Me Goodbye', 'Not until three years after the death of her husband Jolly, Kay dares to move back into their former home, persuaded by her new fiancée Rupert. But soon her worst expectations come true, when not only her old memories haunt her, but also Jolly''s ghost, who doesn''t approve of her new mate. Invisible to anyone but Kay, he tries to prevent the wedding.', '1982-12-22', 5.90, 'https://image.tmdb.org/t/p/w500/jUhCiZb4iqG5xZgy66ewCLBd1lv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81949, 'An Unforgettable Summer', 'In 1925 Romania, young Marie-Therese Von Debretsy refuses the flirtatious advances of her husband''s commanding officer. As a result, the cosmopolitan family is reassigned to a brutally bleak and dangerous outpost on the Bulgarian/Romanian frontier where both their relationship and humanity are severely tested.', '1994-06-15', 6.21, 'https://image.tmdb.org/t/p/w500/aQeuQzrl1bU4lSz7qklkJEnZTAx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82507, 'Sinister', 'True-crime writer Ellison Oswalt is in a slump; he hasn''t had a best seller in more than 10 years and is becoming increasingly desperate for a hit. So, when he discovers the existence of a snuff film showing the deaths of a family, he vows to solve the mystery. He moves his own family into the victims'' home and gets to work. However, when old film footage and other clues hint at the presence of a supernatural force, Ellison learns that living in the house may be fatal.', '2012-10-04', 6.87, 'https://image.tmdb.org/t/p/w500/nzx10sca3arCeYBAomHan4Q6wa1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82505, 'House at the End of the Street', 'A mother and daughter move to a new town and find themselves living next door to a house where a young girl murdered her parents. When the daughter befriends the surviving son, she learns the story is far from over.', '2012-09-21', 5.79, 'https://image.tmdb.org/t/p/w500/bgHeZ5g7YyxKcwWw1tgyAMy0czy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82525, 'Savages', 'Pot growers Ben and Chon face off against the Mexican drug cartel that kidnapped their shared girlfriend.', '2012-07-06', 6.35, 'https://image.tmdb.org/t/p/w500/joyiyBwYY5QCpldqT1FzrTqsTJK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82533, 'Damsels in Distress', 'A trio of beautiful girls set out to revolutionize life at a grungy American university: the dynamic leader Violet Wister, principled Rose and sexy Heather. They welcome transfer student Lily into their group which seeks to help severely depressed students with a program of good hygiene and musical dance numbers.', '2012-04-06', 5.50, 'https://image.tmdb.org/t/p/w500/kF5kdsQbRh1U8Bvjyu6iIxOAsEx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82532, 'Jeff, Who Lives at Home', 'Dispatched from his basement room on an errand for his mother, slacker Jeff might discover his destiny (finally) when he spends the day with his brother as he tracks his possibly adulterous wife.', '2012-03-16', 6.23, 'https://image.tmdb.org/t/p/w500/9zn7I5dmZ7IGng87gWVk9K37eq7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82633, 'Lawless', 'In 1931, the Bondurant brothers of Franklin County, Virginia, run a multipurpose backwoods establishment that hides their true business — bootlegging. Middle brother Forrest is the brain of the operation; older Howard is the brawn, and younger Jack, the lookout. Though the local police have taken bribes and left the brothers alone, a violent war erupts when a sadistic lawman from Chicago arrives and tries to shut down the Bondurants operation.', '2012-08-29', 7.07, 'https://image.tmdb.org/t/p/w500/Ahtzwts22ayviD3LEVslfL4nRWB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82623, 'T-Rex: Back to the Cretaceous', 'Dinosaurs are very much alive -- at least in the mind of teenager Ally Hayden who shares her father''s passion for paleontology. When a museum accident transports Ally on a surreal adventure back in time, she encounters people and makes discoveries that might help her solve the mystery of her father''s newest fossil... and even comes face to face with the most dangerous apex predator on earth.', '1998-10-23', 4.60, 'https://image.tmdb.org/t/p/w500/o4dmpoHm48TpcXD4Zu96LW0QV1V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82650, 'Diary of a Wimpy Kid: Dog Days', 'It''s summertime, and Greg Heffley is looking forward to playing video games and spending time with his friends. However, Greg''s dad has other plans: He''s decided that some father-son bonding time is in order. Desperate to prevent his dad from ruining summer vacation, Greg pretends he has a job at a ritzy country club. But Greg''s plan backfires, leaving him in the middle of embarrassing mishaps and a camping trip gone wrong.', '2012-08-02', 6.40, 'https://image.tmdb.org/t/p/w500/7pTvjELxw0f0E6sUPGtPEl4WD0S.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80662, 'Guilty of Romance', 'While police investigate a woman found dead in a derelict love hotel, a romance novelist''s wife lives a life that seems simply a daily repetition without romance. To escape the loveless monotony, she follows her desires and becomes a nude model. Soon, she meets a mentor and begins selling her body to strangers, while at home, she hides behind the façade of the doting wife.', '2011-09-30', 6.90, 'https://image.tmdb.org/t/p/w500/9Yc6ip8cBDbkfy5K8Ob401PjlJa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81005, 'Jack the Giant Slayer', 'The story of an ancient war that is reignited when a young farmhand unwittingly opens a gateway between our world and a fearsome race of giants. Unleashed on the Earth for the first time in centuries, the giants strive to reclaim the land they once lost, forcing the young man, Jack into the battle of his life to stop them. Fighting for a kingdom, its people, and the love of a brave princess, he comes face to face with the unstoppable warriors he thought only existed in legend–and gets the chance to become a legend himself.', '2013-02-27', 5.91, 'https://image.tmdb.org/t/p/w500/9jSI7saUX9Qz0JLh19jX2ulEwL7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82675, 'Taken 2', 'In Istanbul, retired CIA operative Bryan Mills and his wife are taken hostage by the father of a kidnapper Mills killed while rescuing his daughter.', '2012-09-27', 6.37, 'https://image.tmdb.org/t/p/w500/yzAlcuJhpnxRPjaj7AHBRbNPQCJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82654, 'Warm Bodies', 'After a zombie becomes involved with the girlfriend of one of his victims, their romance sets in motion a sequence of events that might transform the entire lifeless world.', '2013-01-31', 6.47, 'https://image.tmdb.org/t/p/w500/pvVpl38YOBDOANb0pWbXFb8X3iZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82682, 'Gangster Squad', 'Los Angeles, 1949. Ruthless, Brooklyn-born mob king Mickey Cohen runs the show in this town, reaping the ill-gotten gains from the drugs, the guns, the prostitutes and — if he has his way — every wire bet placed west of Chicago. And he does it all with the protection of not only his own paid goons, but also the police and the politicians who are under his control. It’s enough to intimidate even the bravest, street-hardened cop… except, perhaps, for the small, secret crew of LAPD outsiders led by Sgt. John O’Mara and Jerry Wooters who come together to try to tear Cohen’s world apart.', '2013-01-09', 6.38, 'https://image.tmdb.org/t/p/w500/wAuQNTBFBu2yXZsX6yLhUPiwTlW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82687, 'The Guilt Trip', 'An inventor and his mom hit the road together so he can sell his latest invention.', '2012-12-19', 5.61, 'https://image.tmdb.org/t/p/w500/55JqWqocsMNx5uanELDRDFqu40J.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77936, 'The School of Flesh', 'Fashion executive Dominique''s obsession for Quentin, a young bisexual hustler, fills her desire for physical love but leaves her taxed emotionally. Twists and turns in the relationship, along with the man''s violent and abusive nature, force Dominique to reconcile the conflicts created by her passion. In this quest, Dominique is aided, and sometimes hindered, by friends, clients, and Quentin''s former and current acquaintances.', '1998-11-18', 5.42, 'https://image.tmdb.org/t/p/w500/esyIrOG6cjRYIAfjI3Sj9ijA8LQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82693, 'Silver Linings Playbook', 'After losing his job and wife, and spending time in an institution, a former teacher winds up living with his parents. He wants to rebuild his life and reconcile with his wife, but his father would be happy if he shared his obsession with the Philadelphia Eagles. Things get complicated when he meets Tiffany Maxwell who offers to help him reconnect with his wife if he will do something very important for her in exchange.', '2012-11-16', 7.15, 'https://image.tmdb.org/t/p/w500/fhHB1uvfFKKFbj6bTKE8xdtsjKi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82690, 'Wreck-It Ralph', 'Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game''s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero''s Duty, a first-person shooter where he helps the game''s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.', '2012-11-01', 7.36, 'https://image.tmdb.org/t/p/w500/nrEupcBwf4O1zihCM34NoXusZDq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82696, 'Hope Springs', 'After thirty years of marriage, a middle-aged couple attends an intense, week-long counseling session to work on their relationship.', '2012-08-07', 6.26, 'https://image.tmdb.org/t/p/w500/mHEca5NntVHtUPfBiQ3ZVFBRixe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82695, 'Les Misérables', 'An adaptation of the successful stage musical based on Victor Hugo''s classic novel set in 19th-century France. Jean Valjean, a man imprisoned for stealing bread, must flee a relentless policeman named Javert. The pursuit consumes both men''s lives, and soon Valjean finds himself in the midst of the student revolutions in France.', '2012-12-18', 7.30, 'https://image.tmdb.org/t/p/w500/6CuzBs2Lb8At7qQr64mLXg2RYRb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82700, 'After Earth', 'One thousand years after cataclysmic events forced humanity''s escape from Earth, Nova Prime has become mankind''s new home. Legendary General Cypher Raige returns from an extended tour of duty to his estranged family, ready to be a father to his 13-year-old son, Kitai. When an asteroid storm damages Cypher and Kitai''s craft, they crash-land on a now unfamiliar and dangerous Earth. As his father lies dying in the cockpit, Kitai must trek across the hostile terrain to recover their rescue beacon. His whole life, Kitai has wanted nothing more than to be a soldier like his father. Today, he gets his chance.', '2013-05-30', 5.18, 'https://image.tmdb.org/t/p/w500/iXMvYIlzzJBs352CfeiQcBvovZt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82702, 'How to Train Your Dragon 2', 'Five years after uniting the dragons and Vikings of Berk, Hiccup and Toothless soar beyond their homeland, charting the vast unknown. During one of their adventures, the pair discover a secret cave that houses hundreds of wild dragons -- and a mysterious dragon rider with a startling connection to Hiccup. And as the ruthless dragon conqueror Drago Bludvist rises to seize control of both dragons and people alike, Hiccup must step into his role as a true leader and, alongside his friends and Toothless, protect Berk from a devastating war.', '2014-06-05', 7.68, 'https://image.tmdb.org/t/p/w500/d13Uj86LdbDLrfDoHR5aDOFYyJC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82703, 'Mr. Peabody & Sherman', 'A young boy and his dog, who happens to have a genius-level IQ, spring into action when their time-machine is stolen and moments in history begin to be changed.', '2014-02-07', 6.73, 'https://image.tmdb.org/t/p/w500/hPcImYndWESKHzT2GHVCDsUxzYg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82881, 'Tangled Ever After', 'The kingdom is in a festive mood as everyone gathers for the royal wedding of Rapunzel and Flynn. However, when Pascal and Maximus, as flower chameleon and ring bearer, respectively, lose the gold bands, a frenzied search and recovery mission gets underway. As the desperate duo tries to find the rings before anyone discovers that they’re missing, they leave behind a trail of comical chaos that includes flying lanterns, a flock of doves, a wine barrel barricade and a very sticky finale. Will Maximus and Pascal save the day and make it to the church in time? And will they ever get Flynn’s nose right?', '2012-01-13', 7.14, 'https://image.tmdb.org/t/p/w500/5IeMW79OxftIUoR5duxyQ4LW5Iy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82992, 'Fast & Furious 6', 'Hobbs has Dominic and Brian reassemble their crew to take down a team of mercenaries; Dominic unexpectedly gets sidetracked with facing his presumed deceased girlfriend, Letty.', '2013-05-21', 6.82, 'https://image.tmdb.org/t/p/w500/thSmnRdrzPBBospIOJjLZBReqzo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83389, 'From Up on Poppy Hill', 'Yokohama, 1963. Japan is picking itself up from the devastation of World War II and preparing to host the 1964 Olympics—and the mood is one of both optimism and conflict as the young generation struggles to throw off the shackles of a troubled past. Against this backdrop of hope and change, a friendship begins to blossom between high school students Umi and Shun—but a buried secret from their past emerges to cast a shadow on the future and pull them apart.', '2011-07-16', 7.50, 'https://image.tmdb.org/t/p/w500/rRLYX4RZIyloHSJwvZKAhphAjiB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83403, 'Conception', 'Conception is a clever, romantic comedy that proves it takes more than sex to make a baby. From a couple fighting the odds of fertility to young teenagers losing their virginity, the film follows nine very different couples on the night they conceive, showing that sex can sometimes be more neurotic than erotic. The hilarious ensemble cast includes Emmy-winner Julie Bowen and Sarah Hyland (“Modern Family”), Connie Britton (“Friday Night Lights”), David Arquette (Never Been Kissed), Jason Mantzoukas (“The League”), and Alan Tudyk (Dodgeball).', '2011-04-28', 4.55, 'https://image.tmdb.org/t/p/w500/jUBEmGU3f3ItMInVkCfdWE4NMJJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77931, 'The Smurfs 2', 'The evil wizard Gargamel creates a couple of mischievous Smurf-like creatures called the Naughties that he hopes will let him harness the all-powerful, magical Smurf-essence. But when he discovers that only a real Smurf can give him what he wants, and only a secret spell that Smurfette knows can turn the Naughties into real Smurfs, Gargamel kidnaps Smurfette and brings her to Paris, where he has been winning the adoration of millions as the world¹s greatest sorcerer. It''s up to Papa, Clumsy, Grouchy, and Vanity to return to our world, reunite with their human friends Patrick and Grace Winslow, and rescue her! Will Smurfette, who has always felt different from the other Smurfs, find a new connection with the Naughties Vexy and Hackus or will the Smurfs convince her that their love for her is True Blue?', '2013-07-30', 5.75, 'https://image.tmdb.org/t/p/w500/tmjvgbEH4BKYFfHmWXjXrHgi8wT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80713, 'Alone', 'Maria has just moved into a decaying flat in a poor neighbourhood. She left her family in the countryside because she could no longer stand her father''s authority. Pregnant by a man who refuses to see her, Maria gets by as a cleaning-woman. When her father is brought to the city for an operation, her mother moves into her flat.', '1999-03-05', 7.05, 'https://image.tmdb.org/t/p/w500/1ovtyHHDjyCXtf46w2Yv3yPeUDY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81025, 'Salmon Fishing in the Yemen', 'A fisheries expert is approached by a consultant to help realize a sheik''s vision of bringing the sport of fly-fishing to the desert and embarks on an upstream journey of faith and fish to prove the impossible possible.', '2012-03-09', 6.42, 'https://image.tmdb.org/t/p/w500/tSmZAKh1H80AGERgMOvXAWTwbVQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81188, 'Rise of the Guardians', 'When an evil spirit known as Pitch lays down the gauntlet to take over the world, the immortal Guardians must join forces for the first time to protect the hopes, beliefs and imagination of children all over the world.', '2012-11-21', 7.38, 'https://image.tmdb.org/t/p/w500/yfzmfWGjcmyugH6FZ13WcsUGiNj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (77953, 'The Campaign', 'Two rival politicians compete to win an election to represent their small North Carolina congressional district in the United States House of Representatives.', '2012-08-09', 5.83, 'https://image.tmdb.org/t/p/w500/jMWjJ13sFTT07DwjNlqh8VY4sK6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (80985, 'Oblivion 2: Backlash', 'In the alien-western world of Oblivion, a suave, yet lethal bounty hunter named Sweeney arrives to arrest the seductive outlaw Lash on multiple charges, including murder. Lash, who just "inherited" a mine of Derconium (the most valuable mineral in the universe) from Crowley in a game of cards, meets up with Redeye''s brother, Jaggar, who wants the mine for himself to rule the galaxy. It''s a fight over Lash between the sheriff of Oblivion, Jaggar, and Sweeney. But who will emerge victorious?', '1996-04-02', 4.35, 'https://image.tmdb.org/t/p/w500/nC88F3tNp1MKSFWMPGEixjqvhu9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83201, 'Puss in Boots: The Three Diablos', 'Puss in Boots is on a mission to recover the Princess'' stolen ruby from the notorious French thief, Whisperer. Reluctantly accompanied by three little kittens, Three Diablos, Puss must tame them before they endanger the mission.', '2012-02-07', 6.54, 'https://image.tmdb.org/t/p/w500/ptvbHUWpU8Nh6vrmSvjx4ESDgfC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (78248, 'Adanggaman', 'In West Africa during the late 17th century, King Adanggaman leads a war against his neighboring tribes, ordering his soldiers to torch enemy villages, kill the elderly and capture the healthy tribesmen to sell to the European slave traders. When his village falls prey to one of Adanggaman''s attacks, Ossei manages to escape, but his family is murdered except for his captured mother. Chasing after the soldiers in an effort to free her, Ossei is befriended by a fierce warrior named Naka.', '2000-08-31', 6.89, 'https://image.tmdb.org/t/p/w500/grO1ifXULhZvpMhfyGG6k4991Ul.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83456, 'What Men Still Talk About', 'A year later the men are still talking, but this time on the 31st of December and still about the women, football, children, and, of course, about the approaching New Year’s celebration. But what can they do, if their beloved wives and girls are waiting for them at Kamil’s, busy with New Year tree decoration and cooking, and the husbands are accidentally got stuck in the advertising agency office? Will they manage to get home in time to celebrate the New Year together?', '2011-12-29', 6.38, 'https://image.tmdb.org/t/p/w500/9T3bl4c3mM2MYM4BL8TefSQEOB2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (78140, 'Billy Jack Goes to Washington', 'After a senator suddenly dies after completing (and sealing) an investigation into the nuclear power industry, the remaining senator and the state governor must decide on a person who will play along with their shady deals and not cause any problems. They decide on Billy Jack, currently sitting in prison after being sent to jail at the end of his previous film, as they don''t expect him to be capable of much, and they think he will attract young voters to the party.', '1977-04-16', 6.54, 'https://image.tmdb.org/t/p/w500/a6wvKVuxfm2P4Tw7QUXso3tLvwa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (78480, 'Monsieur Lazhar', 'During a harsh Montréal winter, an elementary-school class is left reeling after its teacher commits suicide. Bachir Lazhar, a charismatic Algerian immigrant, steps in as the substitute teacher for the classroom of traumatized children. All the while, he must keep his personal life tucked away: the fact that he is seeking political refuge in Québec – and that he, like the children, has suffered an appalling loss.', '2011-09-10', 7.20, 'https://image.tmdb.org/t/p/w500/qcSXbOP1iv859kgQgqZ4Ib9yqKG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81310, 'Winnie the Pooh and the Blustery Day', 'Winnie the Pooh and his friends experience high winds, heavy rains, and a flood in Hundred Acre Wood.', '1968-12-20', 7.33, 'https://image.tmdb.org/t/p/w500/5kNFx8GW0zgtLDkhfNBOMMVmJTX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81540, 'Teknolust', 'Anxious to use artificial life to improve the world, Rosetta Stone, a bio-geneticist, creates a Recipe for Cyborgs and uses her own DNA in order to breed three Self Replicating Automatons, part human, part computer named Ruby, Olive and Marine.', '2002-01-10', 4.49, 'https://image.tmdb.org/t/p/w500/bd3xzqCTVKkR0i8eZSwCkaxF9VA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84214, 'Come Back, Little Sheba', 'A mismatched couple''s marital problems come to the surface when the husband develops an interest in their pretty boarder.', '1953-03-06', 7.26, 'https://image.tmdb.org/t/p/w500/3hg3c6TVFVGuoqmHi0Yw25qvpRu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83501, 'Comedy of the Strict Regime', 'The action is set in 1970 as the Soviet Union (and the entire progressive world) are preparing to celebrate Lenin''s centenary. Not to be outdone, the camp commander decides to have the prisoners put on a play about Lenin''s life. However, the ensuing preparations turn everything upside down and seem to offer a God-given chance to plot an escape.', '1992-11-07', 5.07, 'https://image.tmdb.org/t/p/w500/psJJKzF7WX2lSvNzw1LgidTArvw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84254, 'The Adventures of Sherlock Holmes and Dr. Watson: The Hound of the Baskervilles - Part 1', 'The Hound of the Baskervilles  is a 1981 Soviet film adaptation of Arthur Conan Doyle''s novel The Hound of the Baskervilles. It was the third installment in the TV series about adventures of Sherlock Holmes and Doctor Watson. A potent streak of humour ran through the film as concerns references to traditional British customs and stereotypes, ensuring the film''s popularity with several generations of Russophone viewers. Other features of this best entry in the series include excellent exterior shots which closely match the novel''s setting in the Dartmoor marshland, as well as an all-star cast: in addition to the famous Livanov -Solomin duo as Holmes and Watson, the film stars the internationally acclaimed actor/director Nikita Mikhalkov as Sir Henry Baskerville and the Russian movie legend Oleg Yankovsky as the villain Stapleton.', '1981-07-25', 7.30, 'https://image.tmdb.org/t/p/w500/5W1OR1Tv7JAbphYNYrUgWvkL24I.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83666, 'Moonrise Kingdom', 'Set on an island off the coast of New England in the summer of 1965, Moonrise Kingdom tells the story of two twelve-year-olds who fall in love, make a secret pact, and run away together into the wilderness. As various authorities try to hunt them down, a violent storm is brewing off-shore – and the peaceful island community is turned upside down in more ways than anyone can handle.', '2012-05-16', 7.68, 'https://image.tmdb.org/t/p/w500/y4SXcbNl6CEF2t36icuzuBioj7K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84287, 'The Imposter', 'In 1994, a 13-year-old boy disappeared without a trace from his home in San Antonio, Texas. Three-and-a-half years later, he is found alive in a village in southern Spain with a horrifying story of kidnap and torture. His family is overjoyed to bring him home. But all is not quite as it seems.', '2012-07-13', 7.32, 'https://image.tmdb.org/t/p/w500/bhdGcqZqPju3KEaT9J6lMxRO0TI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84306, 'Liberal Arts', 'Newly single, 35, and uninspired by his job, Jesse Fisher worries that his best days are behind him. But no matter how much he buries his head in a book, life keeps pulling Jesse back. When his favorite college professor invites him to campus to speak at his retirement dinner, Jesse jumps at the chance.', '2012-09-14', 6.46, 'https://image.tmdb.org/t/p/w500/yEEEQoJQ1fGT11faLPBfHXkds9E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84319, 'An Oversimplification of Her Beauty', 'A quixotic artist hypothesizes about why he feels bad when a mystery girl stands him up. The event prompts him to ask: what''s the content of a momentary feeling? Is it the sum of your experiences? And perhaps more importantly, are your experiences the sum of you?', '2012-01-30', 5.45, 'https://image.tmdb.org/t/p/w500/igSjDMaviTLS3mrq3r9CzNC46uw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (78406, 'Steal Big Steal Little', 'Ruben and Robby are twin brothers, adopted by Mona, one of the wealthiest - and most eccentric - women in Santa Barbara. Ruben is devoted to Mona, but Robby is more devoted to her money. So when Mona leaves her fortune and estate to Ruben it starts a battle between brothers that soon leads to madness, mayhem, and even attempted murder. On Ruben''s side is Lou Perilli an ex-Chicago cop and used car dealer who knows the law - and how to get around it. On Robby''s side is ruthless businessman Reed Tyler, who is out to turn a swift profit on Mona''s property. Walking a shifty line between them is Eddie Agopian, the family lawyer, who doesn''t care which side wins as long as he''s on the winner''s side. But whether they''re stealing big or stealing little, they''re all stealing in this hilarious comedy about greed, power... and brotherly love.', '1995-09-29', 4.50, 'https://image.tmdb.org/t/p/w500/83TvBaWt8wZHUZo8MKwE2cLRBiT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84327, 'The Queen of Versailles', 'With the epic dimensions of a Shakespearean tragedy, The Queen of Versailles follows billionaires Jackie and David’s rags-to-riches story to uncover the innate virtues and flaws of their American dream. We open on the triumphant construction of the biggest house in America, a sprawling, 90,000-square-foot mansion inspired by Versailles. Since a booming time-share business built on the real-estate bubble is financing it, the economic crisis brings progress to a halt and seals the fate of its owners. We witness the impact of this turn of fortune over the next two years in a riveting film fraught with delusion, denial, and self-effacing humor.', '2012-07-06', 6.90, 'https://image.tmdb.org/t/p/w500/eFMRyapxD7XP5Boj6CLaDtQ1m3o.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84332, 'Safety Not Guaranteed', 'Three magazine employees head out on an assignment to interview a guy who placed a classified ad seeking a companion for time travel.', '2012-06-08', 6.78, 'https://image.tmdb.org/t/p/w500/vgP1ikT5tYv2pAlkpAN1SjGZmsh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84329, 'Robot & Frank', 'Curmudgeonly old Frank lives by himself. His routine involves daily visits to his local library, where he has a twinkle in his eye for the librarian. His grown children are concerned about their father’s well-being and buy him a caretaker robot. Initially resistant to the idea, Frank soon appreciates the benefits of robotic support – like nutritious meals and a clean house – and eventually begins to treat his robot like a true companion. With his robot’s assistance, Frank’s passion for his old, unlawful profession is reignited, for better or worse.', '2012-08-24', 6.90, 'https://image.tmdb.org/t/p/w500/602vUwe1GPmaRvcrT3OQWqH1Nm1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84334, 'Searching for Sugar Man', 'Two South Africans set out to discover what happened to their unlikely musical hero, the mysterious 1970s rock ''n'' roller, Rodriguez.', '2012-06-30', 7.88, 'https://image.tmdb.org/t/p/w500/ucM98HuBHSWmn44oiE83hIDc6VB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84336, 'Shadow Dancer', 'In 1990s Belfast, a woman is forced to betray all she believes in for the sake of her son.', '2012-02-12', 5.95, 'https://image.tmdb.org/t/p/w500/ihkceEMJK4XtHXgw97ggsrE3ExP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84341, 'Smashed', 'Kate and Charlie like to have a good time. Their marriage thrives on a shared fondness for music, laughter… and getting smashed. When Kate’s partying spirals into hard-core asocial behavior, compromising her job as an elementary schoolteacher, something’s got to give. But change isn’t exactly a cakewalk. Sobriety means she will have to confront the lies she’s been spinning at work, her troubling relationship with her mother, and the nature of her bond with Charlie.', '2012-01-22', 6.46, 'https://image.tmdb.org/t/p/w500/d4b2k3bB5C6AC9s3FFZhjZw7rB1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84348, 'V/H/S', 'When a group of misfits is hired by an unknown third party to burglarize a desolate house and acquire one rare VHS tape, they discover more found footage than they had bargained for.', '2012-07-28', 6.10, 'https://image.tmdb.org/t/p/w500/xVGfCaTwVdZt3lFqtOVhTDqmG58.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84355, 'Your Sister''s Sister', 'Iris invites her friend Jack to stay at her family''s island getaway after the death of his brother. At their remote cabin, Jack''s drunken encounter with Hannah, Iris'' sister, kicks off a revealing stretch of days.', '2011-09-11', 6.47, 'https://image.tmdb.org/t/p/w500/yEyoOzOEUBMSofsTticDWBOOsv7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84575, 'Tooth Fairy 2', 'Larry Guthrie, who loses his first love to the town hot shot, decides to win her back by volunteering with the children at her after-school program. When Larry accidentally tells the kids the Tooth Fairy is make-believe, he soon is transformed into a tutu-clad fairy with the "sentence" of collecting teeth.', '2012-03-06', 4.88, 'https://image.tmdb.org/t/p/w500/oIkcTCUdvc5fDyG2IxdCd26hRQ7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84892, 'The Perks of Being a Wallflower', 'Pittsburgh, Pennsylvania, 1991. High school freshman Charlie is a wallflower, always watching life from the sidelines, until two senior students, Sam and her stepbrother Patrick, become his mentors, helping him discover the joys of friendship, music and love.', '2012-09-20', 7.80, 'https://image.tmdb.org/t/p/w500/aKCvdFFF5n80P2VdS7d8YBwbCjh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84404, 'Bully', 'This year, over 5 million American kids will be bullied at school, online, on the bus, at home, through their cell phones and on the streets of their towns, making it the most common form of violence young people in this country experience. The Bully Project is the first feature documentary film to show how we''ve all been affected by bullying, whether we''ve been victims, perpetrators or stood silent witness. The world we inhabit as adults begins on the playground. The Bully Project opens on the first day of school. For the more than 5 million kids who''ll be bullied this year in the United States, it''s a day filled with more anxiety and foreboding than excitement. As the sun rises and school busses across the country overflow with backpacks, brass instruments and the rambunctious sounds of raging hormones, this is a ride into the unknown.', '2011-04-23', 7.17, 'https://image.tmdb.org/t/p/w500/gFYEYUEvXsWzf5cDH64YjibMzpp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84954, 'Secrets of a Soul', 'Scientist Martin Fellmann is tormented by an irrational fear of knives and the irresistible compulsion to murder his wife. Driven to the brink of madness by fantastic nightmares, he encounters a psychoanalyst who offers to treat the perplexing malady.', '1926-05-12', 6.30, 'https://image.tmdb.org/t/p/w500/j4aEY255ZGw0V65DrblT0kGmnzv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83660, 'Paradise Lost 3: Purgatory', 'A further investigation into the arrest of three teenagers convicted of killing three young boys in Arkansas who spent nearly 20 years in prison before being released after new DNA evidence indicated they may be innocent.', '2012-10-13', 7.38, 'https://image.tmdb.org/t/p/w500/5Ix8SvMu5MllsXLtD0dvZR0vDi2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85242, 'Underworld', 'A crook sets out to get revenge on the thugs who hurt his father in this bloody noir-style crime drama. After being released from prison, Johnny Crown goes after Frank, one of the mobsters involved in a series of Father''s Day killings. But Johnny isn''t certain Frank is responsible for his father''s injuries and seeks help from a sex therapist to make sure he''s got the right man.', '1996-06-01', 5.35, 'https://image.tmdb.org/t/p/w500/3kPjFZaGrxalI21CeFUNpNqjXpH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85058, 'First Monday in October', 'For the first time in history a woman is appointed to the U.S. Supreme Court, where she becomes a friendly rival to a liberal associate.', '1981-08-21', 6.16, 'https://image.tmdb.org/t/p/w500/8a4K7e83WoCTOwje4LEhTwtOu0a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85350, 'Boyhood', 'The film tells a story of a divorced couple trying to raise their young son. The story follows the boy for twelve years, from first grade at age 6 through 12th grade at age 17-18, and examines his relationship with his parents as he grows.', '2014-06-05', 7.49, 'https://image.tmdb.org/t/p/w500/2BvtvDUyxiMJ4dmKfiQf4qdOHQN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85414, 'Brake', 'A Secret Service Agent is held captive in the trunk of a car and endures high-speed mental and physical torture as terrorists attempt to extract needed information for their sinister plot.', '2012-03-22', 5.81, 'https://image.tmdb.org/t/p/w500/qKDoK8hUt8fGGXKpvAnt3AQVUvy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85439, 'Snowflake, the White Gorilla', 'Snowflake is special, he''s the only white gorilla in the world. He is the zoo''s main attraction, children love him, but the other gorillas don''t see what''s so charming about this weirdo being the center of attention. With the help of Ailur, a Buddhist black panther reincarnated into the body of a red panda, and Paula, a smart little girl, Snowflake plans a sneak visit to the witch at the circus. She can help him be a normal gorilla. But outside the safety of the zoo''s walls, the three friends are in danger. Thomas, a total jinx, is convinced that the white gorilla is the amulet he needs to counter his bad luck. This cruel and superstitious man is prepared to do whatever it takes to capture Snowflake.', '2011-12-23', 5.22, 'https://image.tmdb.org/t/p/w500/khcQB7EDZUbo0AVqFORK9pWkZrJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85444, 'Wrinkles', 'At an elder-care facility, a geriatric con artist tries to prevent his new friend with early Alzheimer''s symptoms from being transferred to the ''lost causes'' floor.', '2011-09-19', 7.61, 'https://image.tmdb.org/t/p/w500/9aamZ9pJpWnPjYvQz68dsX15YwZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81530, 'Blackrock', 'In New South Wales, Jared surfs with his mates and has a first girl. He hosts a beach party for his older pal, Ricko, and witnesses four of his mates gang-rape a 15 year old. He does nothing, and the next day, she''s found murdered. At school, the boys and the girls react: the girls with anger at the perpetrators, the boys with jeering at the dead girl''s morality. The students'' parents have their own responses. Jared retreats into angry silence, disgusted that he did nothing to help the dead girl. Meanwhile, his mother wants to talk to him about her impending cancer surgery, the police want to know what he saw, and his friend Ricko wants an alibi. Jared''s cracking under the pressure.', '1997-05-01', 5.50, 'https://image.tmdb.org/t/p/w500/36EyDOPw8tvGhvVqi3msNPDYSoY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (81003, 'Kung Fu Panda: Secrets of the Masters', 'Po and the Furious Five uncover the legend of three of kung fu''s greatest heroes: Master Thundering Rhino, Master Storming Ox, and Master Croc.', '2011-12-12', 6.50, 'https://image.tmdb.org/t/p/w500/xON7QZ6yHYt1S1Aji0wfGQ1a7ml.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85689, 'The Son of the Sheik', 'Ahmed, son of Diana and Sheik Ahmed Ben Hassan, falls in love with Yasmin, a dancing girl who fronts her father''s gang of mountebanks. She and Ahmed meet secretly until one night when her father and the gang capture the son of the sheik, torture him, and hold him for ransom.', '1926-09-05', 6.10, 'https://image.tmdb.org/t/p/w500/yZib8tHbOHrSTSszif728VwU2L6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83686, 'The Words', 'The Words follows young writer Rory Jansen who finally achieves long sought after literary success after publishing the next great American novel. There''s only one catch - he didn''t write it. As the past comes back to haunt him and his literary star continues to rise, Jansen is forced to confront the steep price that must be paid for stealing another man''s work, and for placing ambition and success above life''s most fundamental three words.', '2012-09-07', 6.70, 'https://image.tmdb.org/t/p/w500/aJtPLZS7tlpiQl6pEr8H42K565x.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86282, 'Tie Xi Qu: West of the Tracks', 'A detailed look at the gradual decline of Shenyang’s industrial Tiexi district, an area that was once a vibrant example of China’s socialist economy. But industry is changing, and the factories of Tiexi are closing. Director Wang Bing introduces us to some of the workers affected by the closures, and to their families.', '2004-06-09', 7.79, 'https://image.tmdb.org/t/p/w500/hRH0ToR9tgCtNpyzOpqzYv1G47W.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85692, 'A Man Vanishes', 'A Man Vanishes examines the concept of Johatsu, tackling the phenomenon of people missing in Japan over the years. It picks one such person from the list, someone who had seemed to disappear from the face of the earth due to embezzlement from his company, and the filmmakers begin an investigative documentary into the reasons behind and attempt at tracking him down.', '1967-07-08', 6.90, 'https://image.tmdb.org/t/p/w500/wxj8qnBwBAe6JpRfIqM1jaLWewj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85328, 'The Pompatus of Love', 'Four guys sit around drinking beer and talking, trying to figure out the meaning of "the pompatus of love" (from the Steve Miller song "Joker") and analyzing their relationships with women.', '1996-07-26', 4.07, 'https://image.tmdb.org/t/p/w500/i94UXzKj8OF1hUyXlT4BHvfgJZI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (82990, 'Paranormal Activity 4', 'It has been five years since the disappearance of Katie and Hunter, and a suburban family witness strange events in their neighborhood when a woman and a mysterious child move in.', '2012-10-17', 5.40, 'https://image.tmdb.org/t/p/w500/na5tAslm1kGNcft083AIXMTOsYR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83718, 'What Happened Was...', 'Jackie and Michael are coworkers at a large law firm. They decide to meet at Jackie''s for dinner one night.', '1994-09-09', 7.18, 'https://image.tmdb.org/t/p/w500/mke5aNX5cT6JIWk2ER4ng9dGNNL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85860, 'The FP', 'Two rival gangs fight for control of Frazier Park -- a deadly arena in competitive dance-fight video game "Beat-Beat Revolution."', '2011-03-13', 4.96, 'https://image.tmdb.org/t/p/w500/nmo8R1FpBEsC80qYOaXtx2vMrSa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83186, 'Wrong', 'Dolph Springer wakes up one morning to realize he has lost the love of his life, his dog, Paul. During his quest to get Paul (and his life) back, Dolph radically changes the lives of others -- risking his sanity all the while.', '2012-09-05', 6.25, 'https://image.tmdb.org/t/p/w500/k6IvmVvfsoIL8HNVusb4oAQr6Rk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86812, 'Sound of My Voice', 'A journalist and his girlfriend get pulled in while they investigate a cult whose leader claims to be from the future.', '2011-01-22', 6.32, 'https://image.tmdb.org/t/p/w500/6wStc532wuBrW2NZM3TicEWDmaL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86825, 'Stoker', 'Following her father Richard''s death in an unexplained road accident, reclusive teenager India Stoker withdraws further into the quiet rural life she shares with her emotionally disturbed mother Evie. But her curiosity is stirred when her mysterious uncle Charlie, who she has never met, suddenly arrives unannounced. Told that the darkly charismatic Charlie will now be staying at the house, India''s initial well-founded distrust of her uncle''s motivations begins to waver as she finds herself becoming ever more deeply entranced by his sinister charms.', '2013-02-28', 6.64, 'https://image.tmdb.org/t/p/w500/o0giW5oasaef5m9sgBuq0C7IkIa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84204, 'Grabbers', 'Something sinister has come to the shores of Erin Island, unbeknownst to the quaint population of this sleepy fishing village resting somewhere off Ireland’s coast. First, some fishermen go missing. Then there is the rash of whale carcasses suddenly washing up on the beach. When the murders start, it’s up to two mismatched cops – an irresponsible alcoholic and his new partner, a by-the-book woman from the mainland – to protect the townsfolk from the giant, bloodsucking, tentacled aliens that prey upon them. Their only weapon, they discover, is booze. If they want to survive the creatures’ onslaught, everyone will have to get very, very drunk!', '2012-08-10', 6.09, 'https://image.tmdb.org/t/p/w500/n1CkFfuDCh4NDZgaXmyna3V0Hxc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86828, 'Absolutely Anything', 'Eccentric aliens give a man the power to do anything he wants to determine if Earth is worth saving.', '2015-02-13', 5.91, 'https://image.tmdb.org/t/p/w500/8tkhYdm324iCX1LaUc1EmY2Pth7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86834, 'Noah', 'A man who suffers visions of an apocalyptic deluge takes measures to protect his family from the coming flood.', '2014-03-07', 5.68, 'https://image.tmdb.org/t/p/w500/vVLkHabnF5lVpCpqyhZBI5iCYMA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86829, 'Inside Llewyn Davis', 'In Greenwich Village in the early 1960s, gifted but volatile folk musician Llewyn Davis struggles with money, relationships, and his uncertain future.', '2013-10-18', 7.18, 'https://image.tmdb.org/t/p/w500/nNxK3pC3DMpPpWKMvo2p3liREVT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86838, 'Seven Psychopaths', 'A struggling screenwriter inadvertently becomes entangled in the Los Angeles criminal underworld after his oddball friends kidnap a gangster''s beloved Shih Tzu.', '2012-10-12', 6.82, 'https://image.tmdb.org/t/p/w500/4ukEYAxlSivFcDG6vLxJB6PjTjg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85735, 'Love Lasts Three Years', 'A heartbroken literary critic turns his despair into creativity following a bitter divorce, only to encounter an enchanting beauty who poses a major challenge to his newfound cynicism. Marc Marronnier thought his marriage was going well until his wife deemed him immature, and left him for a high-profile writer. Devastated, he began filtering all of his heartache into a misanthropic manuscript decrying the virtues of true love. But later, when Marc falls hard for his cousin''s radiant and gorgeous wife, his entire life is turned upside down. Louise Bourgoin and Gaspard Proust star in a film by actor and author-turned-director Frederic Beigbeder.', '2011-12-10', 5.73, 'https://image.tmdb.org/t/p/w500/eO8O5SwT1bQMHtW6kqEPteMVeiX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86843, 'With Great Power: The Stan Lee Story', 'At 89 years old, Stan Lee''s name appears on more than one BILLION comics in 75 countries in 25 languages. Arguably the most recognized name in comics, Stan Lee has co-created over 500 legendary pop culture characters including Spider-Man, Fantastic Four, X-Men, Iron Man, Thor and The Hulk. Stan continues to create new material and entertain fans of all ages with fantastic stories and characters in all areas of entertainment.  With Great Power: the Stan Lee Story, explores the vivid life and imagination of Stan Lee, from the early days of his Depression-era upbringing through the Marvel Age of Comics and beyond! The film uncovers original transcripts, illustrations, photographs and stories of Lee''s fascinating journey from his early years at Timely Comics and World War Two, the comic book industry''s censorship battle of the 1950''s led by Dr. Fredric Wertham, the dawn of Marvel Comics and the legendary characters Stan co-created, to his current company POW! Entertainment.', '2010-07-24', 6.81, 'https://image.tmdb.org/t/p/w500/36OgSOnBYoqJWwtY1VX5tc2f1iG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87078, 'Suture', 'A man named Clay  flies into Phoenix for a reunion with his long-lost half-brother Vincent.', '1993-09-14', 6.45, 'https://image.tmdb.org/t/p/w500/8lbOpuNaJBNT1gXbIDDyYnDIYut.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83542, 'Cloud Atlas', 'A set of six nested stories spanning time between the 19th century and a distant post-apocalyptic future. Cloud Atlas explores how the actions and consequences of individual lives impact one another throughout the past, the present and the future. Action, mystery and romance weave through the story as one soul is shaped from a killer into a hero and a single act of kindness ripples across centuries to inspire a revolution in the distant future.  Based on the award winning novel by David Mitchell. Directed by Tom Tykwer and the Wachowskis.', '2012-10-26', 6.90, 'https://image.tmdb.org/t/p/w500/8naVv2Xu3rWI5JKHz0vCujx6GaJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87093, 'Big Eyes', 'In the late 1950s and early ''60s, artist Walter Keane achieves unbelievable fame and success with portraits of saucer-eyed waifs. However, no one realizes that his wife, Margaret, is the real painter behind the brush. Although Margaret is horrified to learn that Walter is passing off her work as his own, she is too meek to protest too loudly. It isn''t until the Keanes'' marriage comes to an end and a lawsuit follows that the truth finally comes to light.', '2014-12-24', 6.97, 'https://image.tmdb.org/t/p/w500/203HAjJcLMl7xThcTqZx4zmEGcV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87101, 'Terminator Genisys', 'The year is 2029. John Connor, leader of the resistance continues the war against the machines. At the Los Angeles offensive, John''s fears of the unknown future begin to emerge when TECOM spies reveal a new plot by SkyNet that will attack him from both fronts; past and future, and will ultimately change warfare forever.', '2015-06-23', 5.96, 'https://image.tmdb.org/t/p/w500/oZRVDpNtmHk8M1VYy1aeOWUXgbC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87421, 'Riddick', 'Betrayed by his own kind and left for dead on a desolate planet, Riddick fights for survival against alien predators and becomes more powerful and dangerous than ever before. Soon bounty hunters from throughout the galaxy descend on Riddick only to find themselves pawns in his greater scheme for revenge. With his enemies right where he wants them, Riddick unleashes a vicious attack of vengeance before returning to his home planet of Furya to save it from destruction.', '2013-09-02', 6.34, 'https://image.tmdb.org/t/p/w500/pUul9pGWOKT7X0smkTvsIEIQxcP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87428, 'That''s My Boy', 'While in his teens, Donny fathered a son, Todd, and raised him as a single parent up until Todd''s 18th birthday. Now, after not seeing each other for years, Todd''s world comes crashing down when Donny resurfaces just before Todd''s wedding.', '2012-06-14', 5.81, 'https://image.tmdb.org/t/p/w500/oaLhdRsZ5Mq8VfZtA4Wlvjzzn0X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87436, 'The ABCs of Death', 'An ambitious anthology film featuring segments directed by over two dozen of the world''s leading talents in contemporary genre film. Inspired by children''s educational ABC books, the film comprises 26 individual chapters, each helmed by a different director assigned a letter of the alphabet. The directors were then given free reign in choosing a word to create a story involving death.', '2013-03-08', 4.95, 'https://image.tmdb.org/t/p/w500/k3TcTGCgvvvhAiW9pkyWNz9CoNN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87516, 'Oldboy', 'A man has only three and a half days and limited resources to discover why he was imprisoned in a nondescript room for 20 years without any explanation.', '2013-11-14', 5.92, 'https://image.tmdb.org/t/p/w500/iX93YdBrZA1EpGbphmjf4ARj1Za.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87502, 'Flight', 'Commercial airline pilot Whip Whitaker has a problem with drugs and alcohol, though so far he''s managed to complete his flights safely. His luck runs out when a disastrous mechanical malfunction sends his plane hurtling toward the ground. Whip pulls off a miraculous crash-landing that results in only six lives lost. Shaken to the core, Whip vows to get sober -- but when the crash investigation exposes his addiction, he finds himself in an even worse situation.', '2012-02-22', 6.86, 'https://image.tmdb.org/t/p/w500/tFsHDNclXoCKy2xMxskzXXMaFJS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87504, 'Hyde Park on Hudson', 'The story of the love affair between FDR and his distant cousin Margaret Stuckley, centered around the weekend in 1939 when the King and Queen of the United Kingdom visited upstate New York.', '2012-12-07', 5.29, 'https://image.tmdb.org/t/p/w500/fPqQ4lM1f4bkbpJ9J5Gt8QJRY5D.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87729, 'Jefferson in Paris', 'His wife having recently died, Thomas Jefferson accepts the post of United States ambassador to pre-revolutionary France, though he finds it difficult to adjust to life in a country where the aristocracy subjugates an increasingly restless peasantry. In Paris, he becomes smitten with cultured artist Maria Cosway, but, when his daughter visits from Virginia accompanied by her attractive slave, Sally Hemings, Jefferson''s attentions are diverted.', '1995-03-31', 5.13, 'https://image.tmdb.org/t/p/w500/vcZCvsm920LoNDb7pMibJkxIE4n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85778, 'Maya Lin: A Strong Clear Vision', 'A film about the work of the artist most famous for her monuments such as the Vietnam Memorial Wall and the Civil Rights Fountain Memorial.', '1995-11-10', 7.11, 'https://image.tmdb.org/t/p/w500/fqYvHdWNV84yF7zPV3ENHOZ2Jow.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87818, 'Movie 43', 'A series of interconnected short films are the backdrop for a maniac screenwriter who pitches insane storylines featuring some of Hollywood''s biggest and brightest.  In some countries, like the United Kingdom and the Netherlands, the structure differs. Instead of a pitch, the films are connected by a group of three teenagers searching for the most banned film in the world, Movie 43, which will ultimately lead to the destruction of civilization.', '2013-01-24', 4.66, 'https://image.tmdb.org/t/p/w500/uYa06GxHsCsELx9vOQ11vsT0Aa6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87827, 'Life of Pi', 'The story of an Indian boy named Pi, a zookeeper''s son who finds himself in the company of a hyena, zebra, orangutan, and a Bengal tiger after a shipwreck sets them adrift in the Pacific Ocean.', '2012-11-20', 7.41, 'https://image.tmdb.org/t/p/w500/iLgRu4hhSr6V1uManX6ukDriiSc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87826, 'Here Comes the Boom', 'A high school biology teacher moonlights as a mixed-martial arts fighter in an effort to raise money to save the school''s music program.', '2012-10-10', 6.22, 'https://image.tmdb.org/t/p/w500/g3ZjNkQP4M7Cs0clPD9q7EO2P1g.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (87852, 'Microwave Massacre', 'Construction worker Donald is having a hard time getting anything good to eat since his wife has decided to only cook gourmet foods. That and her constant harping causes him to snap, so he whacks her. Somewhere in the confusion he comes up with a new use for the microwave oven, and begins to eat much better. Soon he''s experimenting with different recipes. And different meats.', '1983-08-31', 4.30, 'https://image.tmdb.org/t/p/w500/saPYOf3E92zNy6eM0aA738JN75X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (88005, 'Seeking a Friend for the End of the World', 'As an asteroid nears Earth, a man finds himself alone after his wife leaves in a panic. He decides to take a road trip to reunite with his high school sweetheart. Accompanying him is a neighbor who inadvertently puts a wrench in his plan.', '2012-06-22', 6.57, 'https://image.tmdb.org/t/p/w500/rBbCwFLyt7Q25yaw2bEOQh7RMG1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (88042, 'Parental Guidance', 'Artie and Diane agree to look after their three grandkids when their type-A helicopter parents need to leave town for work. Problems arise when the kids'' 21st-century behavior collides with Artie and Diane''s old-school methods.', '2012-12-25', 5.95, 'https://image.tmdb.org/t/p/w500/815zxi87kTUvleFHjnE5SNzWmVZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (88107, 'Double Trouble', 'Two beefed-up twins operating on opposing sides of the law, team up to stop a nefarious crook in this actioner. Peter Jade is a notoriously arrogant burglar who ends up with the key to an enormous underground cache of diamonds. David Jade is a cop who joins forces with Peter after greedy Philip Chamberlain, wanting the diamonds for himself, kills David''s partner', '1992-02-14', 4.73, 'https://image.tmdb.org/t/p/w500/c9Q0zxjCPBS84y2akpowbnNcnOQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (88573, 'Headshot', 'A hitman named Tul is shot in the head during an assignment. When he wakes up from a two month coma Tul discovers that he literally sees everything upside down.', '2011-11-24', 6.15, 'https://image.tmdb.org/t/p/w500/wuZ6uVkuaKfehCSKMKb5SznEkpc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (88673, 'April Morning', 'A teenager grows up during the onset of the American revolution.', '1988-04-24', 5.70, 'https://image.tmdb.org/t/p/w500/lRAKBACw4h85ltnDIuETTYlsPr2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (88435, 'Tattooed Life', 'After his own gang sets him up to kill a rival mobster, a hit man is forced to flee with his younger brother.', '1965-11-13', 7.22, 'https://image.tmdb.org/t/p/w500/yhJ6fISn8H7NVxEBANb8RKdWhd2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (88751, 'Journey to the Center of the Earth', 'On a quest to find out what happened to his missing brother, a scientist, his nephew and their mountain guide discover a fantastic and dangerous lost world in the center of the earth.', '2008-07-10', 6.10, 'https://image.tmdb.org/t/p/w500/kL55wY0s2H9JdwfjoWIp9plvYnl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (88794, 'J. Edgar', 'As the face of law enforcement in the United States for almost 50 years, J. Edgar Hoover was feared and admired, reviled and revered. But behind closed doors, he held secrets that would have destroyed his image, his career, and his life.', '2011-11-09', 6.23, 'https://image.tmdb.org/t/p/w500/gltciP2dIaEQmm4JeYfB088k40n.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (88818, 'The Object of Beauty', 'American couple Jake and Tina are living in an expensive London hotel above their means, incurring a sizeable debt. When they are asked to pay a lavish dinner bill and Jake''s card is declined, he suggests they sell Tina''s tiny, expensive Henry Moore sculpture to cover the debt. After they hatch a scheme to claim the sculpture was stolen in order to collect insurance on it, the sculpture mysteriously goes missing.', '1991-04-12', 5.25, 'https://image.tmdb.org/t/p/w500/vtxTzSrjCDH7Ray4RK8FPUrrlSy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84175, 'Beasts of the Southern Wild', 'Hushpuppy, an intrepid six-year-old girl, lives with her father, Wink, in ''the Bathtub'', a southern Delta community at the edge of the world. Wink’s tough love prepares her for the unraveling of the universe—for a time when he’s no longer there to protect her. When Wink contracts a mysterious illness, nature flies out of whack—temperatures rise and the ice caps melt, unleashing an army of prehistoric creatures called aurochs. With the waters rising, the aurochs coming, and Wink’s health fading, Hushpuppy goes in search of her lost mother.', '2012-06-29', 6.84, 'https://image.tmdb.org/t/p/w500/nQJmWekGYlXhezGUb21xFfEfwhH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86541, 'Ghost Graduation', 'A teacher with paranormal abilities helps a group of ghosts graduate high school.', '2012-02-03', 6.59, 'https://image.tmdb.org/t/p/w500/oduJ7jj5DsVuvIctPxHRcb88vfr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84199, 'The First Time', 'A spark of attraction smolders, then ignites, between two teens from different high schools who meet by chance at a party.', '2012-10-19', 6.99, 'https://image.tmdb.org/t/p/w500/tG6jUndWd9FRuvI4j5Z2bhTuq0V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85872, 'Le Chef', 'A veteran chef faces off against his restaurant group''s new CEO, who wants to the establishment to lose a star from its rating in order to bring in a younger chef who specializes in molecular gastronomy.', '2012-03-07', 6.17, 'https://image.tmdb.org/t/p/w500/752BCNz9uFiym29bqIsyOaPAln5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83714, 'Angie', 'Angie lives in Bensonhurst, Brooklyn, and dreams of a better life. When she finds out she''s pregnant by her boyfriend, Vinnie, she decides she''ll have the baby; but not Vinnie as a husband. This turns the entire close-knit neighborhood upside-down and starts Angie on a journey of self-discovery.', '1994-03-04', 5.82, 'https://image.tmdb.org/t/p/w500/A7B8snyynp1iOBYiGx76V3TOdKq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86555, 'Take This Waltz', 'Twenty-eight-year-old Margot is happily married to Lou, a good-natured cookbook author. But when Margot meets Daniel, a handsome artist who lives across the street, their mutual attraction is undeniable.', '2011-11-25', 6.40, 'https://image.tmdb.org/t/p/w500/tjE6XUPNNaG6VGPyq1SdCghoMos.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86369, 'Mina Tannenbaum', 'The film tells the story of two girls who are of totally different character. They know each other since their childhood and were friends until they became teenagers. But growing up and becoming adults they go different ways.', '1994-03-02', 6.47, 'https://image.tmdb.org/t/p/w500/hx9ocZaXDjXyo5VkPaSvtiTmIlL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (85889, 'Filth', 'A bigoted junkie cop suffering from borderline personality disorder and drug addiction manipulates and hallucinates his way in a bid to secure promotion.', '2013-09-23', 6.83, 'https://image.tmdb.org/t/p/w500/tzTKDgF6GcGaxKvRHR5J4MeWJ7b.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84200, 'For a Good Time, Call...', 'College "frenemies" Lauren and Katie move in together after losing a relationship and rent control, respectively. Sharing Katie''s late grandmother''s apartment in New York City, the girls bicker with each other until one fateful night, when Katie''s noisy bedroom activities make Lauren barge in and discover a dirty little secret. This revelation brings them closer together, and Lauren (the brains) and Katie (the talent) concoct a wildly successful business venture. As profits swell, the girls reevaluate their hopes and dreams and realize that just because someone pees in your hair in college doesn''t mean she won''t be your best friend 10 years later.', '2012-08-31', 5.85, 'https://image.tmdb.org/t/p/w500/9eIlVo8lvk9fmfP05JGFKlPha80.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (89492, 'This Is 40', 'Pete and Debbie are both about to turn 40, their kids hate each other, both of their businesses are failing, they''re on the verge of losing their house, and their relationship is threatening to fall apart.', '2012-12-20', 5.90, 'https://image.tmdb.org/t/p/w500/mzUuOIFoVkRTHACRb58vm6mkbBN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (89247, 'Daddy, I''m a Zombie', 'The misadventures of a teenager girl in her new life as zombie.', '2012-01-10', 7.16, 'https://image.tmdb.org/t/p/w500/7lWYTb3g0VdbwPYD1HG6AzHF74M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84111, 'You Are the Apple of My Eye', 'A group of close friends who attend a private school all have a debilitating crush on the sunny star pupil, Shen Chia-yi. The only member of the group who claims not to is Ko Ching-teng, but he ends up loving her as well.', '2011-08-19', 7.40, 'https://image.tmdb.org/t/p/w500/mQ07Y4KlYZlJjVSEp2AFTYZA9i.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (83899, 'You''re Next', 'When the Davison family comes under attack during their wedding anniversary getaway, the gang of mysterious killers soon learns that one of their victims harbors a secret talent for fighting back.', '2013-08-22', 6.60, 'https://image.tmdb.org/t/p/w500/l163jakfKvchUTVTtBi0KA7ZhIc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (84165, '2 Days in New York', 'Marion and Mingus both come from failed relationships but, by bringing their children together, they''ve managed to form a small yet happy family. Tensions in their household soon begin to spike when Marion''s jovial father shows up on their doorstep with his randy daughter and her peculiar boyfriend in tow. As the motor-mouthed houseguests shatter every taboo imaginable, the happy couple begin to question their commitment.', '2012-03-28', 5.61, 'https://image.tmdb.org/t/p/w500/tK6G639JfQV36WRr9wTu1D9iZRg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (92060, 'Michael Jackson''s Thriller', 'A night at the movies turns terrifying when Michael and his date are attacked by zombies. Released at the height of Thriller’s success, the short film redefined the music video, broke racial barriers, and became the first inducted into the U.S. National Film Registry.', '1983-11-21', 8.25, 'https://image.tmdb.org/t/p/w500/tVd95TdfXybhhzGBHSlPiuaHs1y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (92171, 'The Thing: Terror Takes Shape', 'An in-depth look at the making of John Carpenter''s cult classic sci-fi horror The Thing, telling the story of a group of researchers in Antarctica who encounter a parasitic extra-terrestrial life-form that assimilates, then imitates other organisms.', '1998-09-08', 7.45, 'https://image.tmdb.org/t/p/w500/enqYQR24eOAvdtFKyoWGkK3dV3s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (86705, 'John Mulaney: New in Town', 'Stand-up comedian John Mulaney tackles such red-hot topics as quicksand, Motown singers and an elderly man he once met in a bathroom.', '2012-01-31', 7.93, 'https://image.tmdb.org/t/p/w500/ufE8KAkLQT9u91AgDSc5Oxa3DjW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (92321, 'Hotarubi no Mori e', 'One hot summer day a little girl gets lost in an enchanted forest of the mountain god where spirits reside. A young boy appears before her, but she cannot touch him for fear of making him disappear. And so a wondrous adventure awaits...', '2011-09-17', 8.26, 'https://image.tmdb.org/t/p/w500/mDqzHV8UXWWNpZkoAbKmKX1ZxEE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (92499, 'Spellbound', 'A magician meets a weird girl and offers her to work together in his magic show. It''s only until a year later that he starts to know her personally and develops a feeling towards her despite her own problems.', '2011-12-01', 7.50, 'https://image.tmdb.org/t/p/w500/5kiUh29bcQe66Mjs98O31vGwlUr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (92591, 'Bernie', 'In small-town Texas, affable and popular mortician Bernie Tiede strikes up a friendship with Marjorie Nugent, a wealthy widow well known for her sour attitude. When she becomes controlling and abusive, Bernie goes to great lengths to remove himself from her grasp.', '2011-06-16', 6.60, 'https://image.tmdb.org/t/p/w500/rW5CetooG545jpkPNpD4FjFAXfe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (92769, 'Relative Fear', 'Linda and Peter Pratman''s son Adam is autistic, but they still love him and hope that he''ll at least start talking some day. However he''s teased and abused by the kids of the neighborhood and his grandpa . When several people around Adam die an unexpected death, his parents start to suspect Adam - is he just simulating to be so ignorant about his environment?', '1994-12-16', 5.20, 'https://image.tmdb.org/t/p/w500/wG6wdsB9lqCwxsRycnzzXZDSo6m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (93456, 'Despicable Me 2', 'Gru is recruited by the Anti-Villain League to help deal with a powerful new super criminal.', '2013-06-26', 6.95, 'https://image.tmdb.org/t/p/w500/5Fh4NdoEnCjCK9wLjdJ9DJNFl2b.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (93858, 'Tabu', 'Lisbon, Portugal, 2010. Pilar, a pious woman devoted to social causes, maintains a peculiar relationship with her neighbor Aurora, a temperamental old woman obsessed with gambling who lives tormented by a mysterious past.', '2012-04-05', 7.00, 'https://image.tmdb.org/t/p/w500/mtr1ztUkJs6jsYdzK3gBLsuffr4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (89874, 'First Position', 'A documentary that follows six young dancers from around the world as they prepare for the Youth America Grand Prix, one of the most prestigious ballet competitions in the world.', '2011-09-11', 7.23, 'https://image.tmdb.org/t/p/w500/lxbjoxnIlwZuvFw9WcRIgiVvBPp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (89326, '96 Minutes', 'The story of 4 lives slammed together in a shocking moment. Intercutting between a carjacking and the separate stories of the 4 kids, we watch as they hurtle toward a life-changing end.', '2011-10-14', 5.70, 'https://image.tmdb.org/t/p/w500/39FwN8IVp8y46KJ6VjA8oFY8e1o.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (94329, 'The Raid', 'Deep in the heart of Jakarta''s slums lies an impenetrable safe house for the world''s most dangerous killers and gangsters. Until now, the run-down apartment block has been considered untouchable to even the bravest of police. Cloaked under the cover of pre-dawn darkness and silence, an elite swat team is tasked with raiding the safe house in order to take down the notorious drug lord that runs it.  But when a chance encounter with a spotter blows their cover and news of their assault reaches the drug lord, the building''s lights are cut and all the exits blocked. Stranded on the sixth floor with no way out, the unit must fight their way through the city''s worst to survive their mission. Starring Indonesian martial arts sensation Iko Uwais.', '2012-03-22', 7.41, 'https://image.tmdb.org/t/p/w500/Abnm1Ws3JH0ReCfEhLMPwPcMcGO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (94348, 'Alex Cross', 'Alex Cross, a genius homicide detective/psychologist is trying to clean up the mean streets of Detroit while keeping his family out of the line of fire. As he mulls over accepting a job with the FBI, he is told that a friend has been murdered and he vows to track down the killer. Soon, he and his team are forced to match wits with a psychotic contract killer, who displays a disturbing commitment towards seeing his job through.', '2012-10-18', 5.13, 'https://image.tmdb.org/t/p/w500/bQYXid9o6nunJBgmmjo6JFIQe1p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (90125, 'Marley', 'Bob Marley''s universal appeal, impact on music history and role as a social and political prophet is both unique and unparalleled. Directed by Academy Award-winning director Kevin Macdonald (The Last King of Scotland), MARLEY is the definitive life story of the musician, revolutionary, and legend, from his early days to his rise to international superstardom. Made with the support of the Marley family, the film features rare footage, incredible performances and revelatory interviews with the people that knew him best.', '2012-04-20', 7.53, 'https://image.tmdb.org/t/p/w500/1UQM8zsQ4HhUr4dMgDDDMBrsq5d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (94706, 'Dream of Light', 'Filmmaker Victor Erice follows Spanish artist Antonio Lopez in his painstaking attempt to paint the image of a tree.', '1992-10-01', 7.32, 'https://image.tmdb.org/t/p/w500/wH3VuGHcf0jTzeRGLZlPfqTIHS1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (95682, 'Long Night''s Journey into Day', 'This documentary tells four stories of Apartheid in South Africa, as seen through the eyes of the Truth and Reconciliation commission', '2000-01-29', 6.50, 'https://image.tmdb.org/t/p/w500/iC80ZNpFRuaL8BwzjoD1Zm02Inm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (95610, 'Bridget Jones''s Baby', 'After breaking up, Bridget Jones'' happily-ever-after hasn''t quite gone according to plan. Fortysomething and single again, she decides to focus on her job and surround herself with old friends and new. For once, Bridget has everything completely under control. Then her love life takes a turn when she meets Jack. A week later, she runs into Mark before she finds herself pregnant, but with one hitch - she''s not sure of the identity of her baby''s father - Mark or Jack.', '2016-09-14', 6.40, 'https://image.tmdb.org/t/p/w500/5hHomngoPZrNoXOPlyaHV6eXaQW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (95516, 'Cleanskin', 'While working undercover as a bodyguard to arms dealer Harry, former-soldier-turned-secret-service-agent Ewan survives a bloody shootout with a member of an Islamic terrorist cell who steals Harry''s briefcase full of Semtex explosives and escapes. Ewan''s spymasters task Ewan with hunting down the cell members and retrieving the briefcase.', '2012-03-08', 5.63, 'https://image.tmdb.org/t/p/w500/dgHAFprnEkdD8vFZTFnjoWgmucP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (95963, 'The Walking Dead', 'Five young marines on a suicide mission in Vietnam, struggle for survival in a jungle minefield. The mean streets of home did not prepare them for this.', '1995-02-24', 5.90, 'https://image.tmdb.org/t/p/w500/c0RtcIN4oSzSZoNs0nJMevfGYS4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
