INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (96724, 'Anna Karenina', 'In Imperial Russia, Anna, wife of the officer Karenin, goes to Moscow to visit her brother. On the way, she meets charming cavalry officer Vronsky, to whom she''s immediately attracted. But in St. Petersburg’s high society, a relationship like this could destroy a woman’s reputation.', '2012-09-06', 6.69, 'https://image.tmdb.org/t/p/w500/b9mvt1kKqDuveD1AJuGSkBEuagU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (96936, 'The Bling Ring', 'Lured by stardom, a crew of aimless teens breaks into celebrity homes for a string of high-profile robberies and fame by appropriation.', '2013-06-12', 5.43, 'https://image.tmdb.org/t/p/w500/6yh55qCcdgPRJweDWM2CiEubJCL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
