INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (97614, 'Deadfall', 'A thriller that follows two siblings who decide to fend for themselves in the wake of a botched casino heist, and their unlikely reunion during another family''s Thanksgiving celebration.', '2012-11-08', 5.96, 'https://image.tmdb.org/t/p/w500/5ZM6uKhuEzWZD3xklmqKPuvq1Nj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (88953, 'The Ear', 'Government bureaucrat Ludvik becomes suspicious after several colleagues disappear and he overhears something strange at a cocktail party. Returning home with his wife, Anna, he finds their house under surveillance and spends a fraught night worrying about his possible arrest in the morning. Marital difficulties come to light as Ludvik and his wife attempt to act normal in front of the cameras while dredging up their problems out of sight.', '1990-01-01', 7.25, 'https://image.tmdb.org/t/p/w500/tvLMBdTZPxMvWoBis5Sel05lDB6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
