INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (91314, 'Transformers: Age of Extinction', 'As humanity picks up the pieces after the battle of Chicago, a shadowy group reveals itself in an attempt to control the direction of history…while an ancient, powerful new menace sets Earth in its crosshairs. With help from Cade Yeager, Optimus Prime and the Autobots rise to meet their most fearsome challenge yet.', '2014-06-25', 5.97, 'https://image.tmdb.org/t/p/w500/jyzrfx2WaeY60kYZpPYepSjGz4S.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
