INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (89292, 'Hard Promises', 'A man who doesn''t like stable work environments has been away for too many years, and finds out his wife has divorced him and is planning to remarry. He comes home to confront her, trying to convince her not to get married, aided by the daughter, who loves him despite his wandering ways. The couple finds out they still have feelings for each other but must decide how best to handle the contradiction of their lifestyles.', '1992-01-31', 5.80, 'https://image.tmdb.org/t/p/w500/kPfXplEnUW2OIsOCydTmuxu2lw5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
