INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (89704, 'Happy People: A Year in the Taiga', 'In the center of the story is the life of the indigenous people of the village Bakhtia at the river Yenisei in the Siberian Taiga. The camera follows the protagonists in the village over a period of a year. The natives, whose daily routines have barely changed over the last centuries, keep living their lives according to their own cultural traditions.', '2010-09-03', 7.28, 'https://image.tmdb.org/t/p/w500/wSDdllenxdsPiMONxEQEBfiLvio.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
