INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (99479, 'Entertaining Angels: The Dorothy Day Story', 'The firebrand reporter, feminist and philanthropist Dorothy Day co-founds The Catholic Worker with Peter Maurin, an eccentric philosopher.', '1996-09-27', 5.36, 'https://image.tmdb.org/t/p/w500/jYDSEJYcvSI0LzwIEP1JWMMAbWh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
