INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109414, 'This Is the End', 'While attending a party at James Franco''s house, Seth Rogen, Jay Baruchel and many other celebrities are faced with the apocalypse.', '2013-06-12', 6.23, 'https://image.tmdb.org/t/p/w500/tNIW0NhX1hKvUsy6PQ80DOKUhkD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109418, 'Grown Ups 2', 'Lenny has relocated his family back to the small town where he and his friends grew up. This time around, the grown ups are the ones learning lessons from their kids on a day notoriously full of surprises—the last day of school.', '2013-07-11', 6.19, 'https://image.tmdb.org/t/p/w500/hT6ijOtjtYrnyDhN7VA2QWyGFAm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109421, 'Side Effects', 'A woman turns to prescription medication as a way of handling her anxiety concerning her husband''s upcoming release from prison.', '2013-02-07', 6.61, 'https://image.tmdb.org/t/p/w500/dk10bwGyj8aRdOTl3EkgATEefh2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109428, 'Evil Dead', 'Mia, a drug addict, is determined to kick the habit. To that end, she asks her brother, David, his girlfriend, Natalie and their friends Olivia and Eric to accompany her to their family''s remote forest cabin to help her through withdrawal. Eric finds a mysterious Book of the Dead at the cabin and reads aloud from it, awakening an ancient demon. All hell breaks loose when the malevolent entity possesses Mia.', '2013-04-05', 6.66, 'https://image.tmdb.org/t/p/w500/1gDV0Lm9y8ufIKzyf0h0GBgb9Zj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109424, 'Captain Phillips', 'The true story of Captain Richard Phillips and the 2009 hijacking by Somali pirates of the US-flagged MV Maersk Alabama, the first American cargo ship to be hijacked in two hundred years.', '2013-10-10', 7.54, 'https://image.tmdb.org/t/p/w500/8Td0kkocW6sD3uRpzwfMfkqMWhx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109439, 'The Hangover Part III', 'This time, there''s no wedding. No bachelor party. What could go wrong, right? But when the Wolfpack hits the road, all bets are off.', '2013-05-23', 6.21, 'https://image.tmdb.org/t/p/w500/vtxuPWkdllLNLVyGjKYa267ntuH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109431, 'Identity Thief', 'When a mild-mannered businessman learns his identity has been stolen, he hits the road in an attempt to foil the thief -- a trip that puts him in the path of a deceptively harmless-looking woman.', '2013-02-07', 5.85, 'https://image.tmdb.org/t/p/w500/lIliJCGoWT6tEVaDivLpXEf038w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109443, 'Anchorman 2: The Legend Continues', 'With the 70s behind him, San Diego''s top rated newsman, Ron Burgundy, returns to take New York''s first 24-hour news channel by storm.', '2013-12-18', 6.15, 'https://image.tmdb.org/t/p/w500/BAdmxMdCqzjs6hx3KuEtnoWP8d.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109445, 'Frozen', 'Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She''s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.', '2013-11-20', 7.25, 'https://image.tmdb.org/t/p/w500/itAKcobTYGpYT8Phwjd8c9hleTo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109491, 'Beautiful Creatures', 'Ethan Wate just wants to get to know Lena Duchannes better, but unbeknownst to him, Lena has strange powers.  As Lena''s 16th birthday approaches she might decide her fate, to be good or evil.  A choice which will impact her relationship forever.', '2013-02-13', 6.05, 'https://image.tmdb.org/t/p/w500/t7PWQHpJHb2ozALCfaPaC5aHxBs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109560, 'New York Undercover Cop', 'Allegedly based on a true story, this film follows the life of Toshi, a Japanese man living in America and working with the New York City police. After being recommended for undercover work, Toshi decides to go after a gang lead by Hawk. Hawk and Toshi soon become friends, although Hawk''s second-in-command, Tito, is suspicious of the newcomer. Will Toshi be able to bring the gang down, or will his cover be blown before he can finish the assignment?', '1993-08-14', 3.80, 'https://image.tmdb.org/t/p/w500/5kXO783UrTaKZE3wn0KZv3RubZc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109479, 'Buddy Boy', 'An introvert relieves the tedium of caring for his invalid mother by spying on his neighbor.', '2000-03-24', 4.86, 'https://image.tmdb.org/t/p/w500/3hLdv9aGXDTs95c0st9wBmaKpZR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109584, 'Broken', 'Three suburban English families'' lives intertwine with tragic consequences.', '2012-08-22', 6.88, 'https://image.tmdb.org/t/p/w500/cNeDPyJdeV4Gzs3TcVthM8AJYHW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (110390, 'A Pigeon Sat on a Branch Reflecting on Existence', 'An absurdist, surrealistic and shocking pitch-black comedy, which moves freely from nightmare to fantasy to hilariously deadpan humour as it muses on man’s perpetual inhumanity to man.', '2014-10-24', 6.80, 'https://image.tmdb.org/t/p/w500/h2uRIr0fNpZbTGH5youi7MDRL2T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (106143, 'I''ll Do Anything', 'Matt Hobbs is a talented but unsuccessful actor. When estranged (and strange) ex-wife Beth dumps their daughter Jeannie on Matt, father and daughter have a lot of adjusting to do. His budding relationship with attractive production assistant Cathy Breslow is made complicated, while the precocious child is overly accustomed to getting her own way. Matt eventually faces the choice of family vs career in a particularly difficult way.', '1994-02-04', 5.60, 'https://image.tmdb.org/t/p/w500/oroT4oMzldeKglEAnMT94o3KN66.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (103732, 'GLOW: The Story of The Gorgeous Ladies of Wrestling', 'The year is 1986. Gorgeous Ladies of Wrestling (GLOW) is about to burst onto the scene as the first ever all-female wrestling show on television. By 1989, the GLOW girls were an international phenomenon, attracting over seven million viewers worldwide, touring the nation and making big bank for the show''s producers. One year later, GLOW was gone. GLOW: THE STORY OF THE GORGEOUS LADIES OF WRESTLING chronicles the rise and fall of this hit television show through the stories of those who lived it. For some, the show was a brief foray into acting and a short-lived adventure. For others, their time in GLOW would impact and influence their lives for years to follow. For all of the women, working on GLOW was a unique and exciting experience that will bond them forever.', '2012-08-21', 6.49, 'https://image.tmdb.org/t/p/w500/gu6dd3SkfOJ37be5h8UDnoy1WKp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (110354, 'Side by Side', 'Since the invention of cinema, the standard format for recording moving images has been film. Over the past two decades, a new form of digital filmmaking has emerged, creating a groundbreaking evolution in the medium. Keanu Reeves explores the development of cinema and the impact of digital filmmaking via in-depth interviews with Hollywood masters, such as James Cameron, David Fincher, David Lynch, Christopher Nolan, Martin Scorsese, George Lucas, Steven Soderbergh, and many more.', '2012-08-19', 7.26, 'https://image.tmdb.org/t/p/w500/qeeQ7rfTAXNYh4EqqdolFLkNwKM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (109451, 'Cloudy with a Chance of Meatballs 2', 'After the disastrous food storm in the first film, Flint and his friends are forced to leave the town. Flint accepts the invitation from his idol Chester V to join The Live Corp Company, which has been tasked to clean the island, and where the best inventors in the world create technologies for the betterment of mankind. When Flint discovers that his machine still operates and now creates mutant food beasts like living pickles, hungry tacodiles, shrimpanzees and apple pie-thons, he and his friends must return to save the world.', '2013-09-26', 6.46, 'https://image.tmdb.org/t/p/w500/ss5NcK2NWFg2YcKKYXLrk8q1myS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (103747, 'The Angels'' Share', 'Robbie is a Glasgow boy locked in a family feud who just wants a way out. On community service, he meets Rhino, Albert and Mo. Little did Robbie imagine that turning to drink might change their lives, leading them to the distilleries of the Scottish Highlands and the biggest gamble of his life.', '2012-06-01', 6.93, 'https://image.tmdb.org/t/p/w500/bt9kJ8gwTMaDcmL0INlJYIZ887t.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (110420, 'Wolf Children', 'After her werewolf lover unexpectedly dies in an accident, a woman must find a way to raise the son and daughter that she had with him. However, their inheritance of their father''s traits prove to be a challenge for her.', '2012-07-21', 8.21, 'https://image.tmdb.org/t/p/w500/vHMvBkr42Gh3OORcnmfCFfqJ1E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (104301, 'The Good Mother', 'After finding a sexually liberated boyfriend, a divorced woman gets sued over daughter''s custody, by her ex, who claims that her lover has a bad influence on the kid.', '1988-11-04', 5.73, 'https://image.tmdb.org/t/p/w500/13AsjChBPvhefDsAazSqukmNCSu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (104515, 'The Lord''s Lantern in Budapest', 'In the Kerepesi Street cemetery, three grave diggers contemplate the fate of the world, then they step out of this role and in a sequence of episodes they play the typical figures of contemporary Hungarian reality, the fat cat, the swashbuckler, the victim, underworld chieftains, and present little absurd dramas of love, marriage, friendship, public order and legal safety. The author and the film director walk among them all the time, contemplating, laughing at their plays. The stories starting from the graveyard and returning there warn of the inevitability of death. The author and the director (Gyula Hernádi and Miklós Jancsó) wisely make friends with death.', '1999-01-28', 6.40, 'https://image.tmdb.org/t/p/w500/pXEJRDIbFdXbtNSSLQLB5xIzorZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (111969, 'Stuck in Love', 'An acclaimed writer, his ex-wife, and their teenaged children come to terms with the complexities of love in all its forms over the course of one tumultuous year.', '2013-06-14', 7.38, 'https://image.tmdb.org/t/p/w500/byic4VFVrpPyjDWK54CcsxYWW85.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (112205, 'The Family', 'After ratting out his Mafia cohorts, Giovanni Manzoni and his family enter the Witness Protection Program and relocate to a sleepy town in France. Despite the best efforts of their handler to keep them in line, Giovanni (now called Fred Blake), his wife and children can''t help but resort to doing things the "family" way. However, their dependence on such old habits places everyone in danger from vengeful mobsters.', '2013-09-13', 6.36, 'https://image.tmdb.org/t/p/w500/x2arN02JFsZcDKmBb0SIjG8Smc8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (112336, 'Hitchcock', 'Following his great success with "North by Northwest," director Alfred Hitchcock makes a daring choice for his next project: an adaptation of Robert Bloch''s novel "Psycho." When the studio refuses to back the picture, Hitchcock decides to pay for it himself in exchange for a percentage of the profits. His wife, Alma Reville, has serious reservations about the film but supports him nonetheless. Still, the production strains the couple''s marriage.', '2012-11-22', 6.56, 'https://image.tmdb.org/t/p/w500/zlG4QzB00VM6QHUmRkKaboCOgat.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (112454, 'Clown', 'A loving father finds a clown suit for his son''s birthday party, only to realize the suit is part of an evil curse that turns its wearer into a killer.', '2014-11-13', 5.80, 'https://image.tmdb.org/t/p/w500/gp5QyaU49utfWVVL698BzlN2vMh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (112949, 'Safe Haven', 'A young woman with a mysterious past lands in Southport, North Carolina where her bond with a widower forces her to confront the dark secret that haunts her.', '2013-02-07', 7.23, 'https://image.tmdb.org/t/p/w500/2CbJ3HTb6SFbMeguYH52UQSHOwY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (113096, 'The Brandon Teena Story', 'Documentary about Brandon Teena, a transgender man who was murdered along with two others in 1993 in rural Nebraska.', '1998-09-23', 6.40, 'https://image.tmdb.org/t/p/w500/2VUVDdbInXCTn4X2ViCkIYE33r5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (110392, 'A Liar''s Autobiography: The Untrue Story of Monty Python''s Graham Chapman', 'John Cleese, Michael Palin, Terry Jones and Terry Gilliam pay tribute to their late Monty Python colleague Graham Chapman in this hilarious, 3-D animated adaptation of Chapman''s brazenly fictionalized life story.', '2012-11-02', 5.92, 'https://image.tmdb.org/t/p/w500/b8AKAb65f0CyuYM9FBkFYxePAlu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (113273, 'On the Ropes', 'The story of three young boxers and their coach who is determined to guide them in a positive direction in and out of the ring.', '1999-01-01', 7.00, 'https://image.tmdb.org/t/p/w500/yy4fFWLigLn6MKCqFIFMCjQJ7Ab.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (113279, 'Regret to Inform', 'In this film made over ten years, filmmaker Barbara Sonneborn goes on a pilgrimage to the Vietnamese countryside where her husband was killed. She and translator (and fellow war widow) Xuan Ngoc Nguyen explore the meaning of war and loss on a human level. The film weaves interviews with Vietnamese and American widows into a vivid testament to the legacy of war.', '1999-07-22', 7.86, 'https://image.tmdb.org/t/p/w500/iXXj1IIQ1rqFiFHdbpOkvNU9MvN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (110416, 'Song of the Sea', 'The story of the last Seal Child’s journey home. After their mother’s disappearance, Ben and Saoirse are sent to live with Granny in the city. When they resolve to return to their home by the sea, their journey becomes a race against time as they are drawn into a world Ben knows only from his mother’s folktales. But this is no bedtime story; these fairy folk have been in our world far too long. It soon becomes clear to Ben that Saoirse is the key to their survival.', '2014-06-23', 7.98, 'https://image.tmdb.org/t/p/w500/16LQC6zpqB0l74mVWb93a2oMFnX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (113286, 'Dancemaker', 'A look at Paul Taylor and his dance company over several months in 1997. Preparation of Taylor''s piece, "Piazzolla Caldera," from conception and rehearsals to opening night at City Center, frames the film. The troupe''s trip to India falls in the middle. Included are black and white footage of rehearsals, and, in color, interviews with Taylor, his dancers, dance critics and scholars, and those who manage the business side. There is also footage of a younger Taylor dancing and film of the troupe performing a dozen Taylor pieces. His genius, his roots, his method of working with dancers, and his sometimes difficult nature draw the attention of those who comment.', '1998-12-01', 5.00, 'https://image.tmdb.org/t/p/w500/iR6z334jcMEv2hQoEu2xX0JzJMy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (104755, 'The Lords of Salem', 'Heidi, a radio DJ, is sent a box containing a record - a "gift from the Lords". The sounds within the grooves trigger flashbacks of her town''s violent past. Is Heidi going mad, or are the Lords back to take revenge on Salem, Massachusetts?', '2013-04-18', 5.43, 'https://image.tmdb.org/t/p/w500/nqZ6CGGZpQWt139YioekSYHvvkU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (113739, 'Ring of Terror', 'A group of medical students undertake some silly and frightening endeavors in order to pledge a fraternity.', '1961-06-11', 1.92, 'https://image.tmdb.org/t/p/w500/hVuVppiIntAR5Sf01nWCBinnWHL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (113916, 'The General Died at Dawn', 'China, 1930s, during the ravaging civil war. General Pen entrusts O''Hara, an intrepid American adventurer, with the mission of providing a large sum of money to Mr. Wu with the task of buying weapons in Shanghai to help end General Yang''s tyranny that keeps an entire province under his ruthless iron boot.', '1936-11-17', 6.48, 'https://image.tmdb.org/t/p/w500/mpt6AyISPBYesV8lFxED7PoHxZD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (114150, 'Pitch Perfect', 'College student Beca knows she does not want to be part of a clique, but that''s exactly where she finds herself after arriving at her new school. Thrust in among mean gals, nice gals and just plain weird gals, Beca finds that the only thing they have in common is how well they sing together. She takes the women of the group out of their comfort zone of traditional arrangements and into a world of amazing harmonic combinations in a fight to the top of college music competitions.', '2012-09-28', 7.30, 'https://image.tmdb.org/t/p/w500/gsFoJk9g8W3zgaipRrrURk7LbiF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (113947, 'The Sessions', 'Though a childhood bout with polio left him dependent on an iron lung, Mark O''Brien maintains a career as a journalist and poet. A writing assignment dealing with sex and the disabled piques Mark''s curiosity, and he decides to investigate the possibility of experiencing sex himself. When his overtures toward a caregiver scare her away, he books an appointment with sex surrogate Cheryl Cohen-Greene to lose his virginity.', '2012-05-02', 6.89, 'https://image.tmdb.org/t/p/w500/57o1DBc5DfJXVc8wArAblSbZ8sD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (104522, 'My Love', 'In nineteenth-century Russia, a teenage boy in search of love is drawn to two very different women.', '2006-04-08', 7.10, 'https://image.tmdb.org/t/p/w500/pFy7fz3P7TDb0XTHjLF7zkQzCLM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (114719, 'Friends & Lovers', 'Friends for ten years, a group of twenty-somethings head for the ski slopes as guests of Ian''s father. (Ian and dad are estranged because dad worked too many hours when Ian was a lad.) Dad has something to say, but Ian won''t listen. Meanwhile, David is gay and virginal; Ian''s business partner, Keaton, is unhappy that his sister Jane is pregnant with no plans to tell the father; Lisa is everybody''s pal and no one''s lover; John, stuck in adolescence, is always on the make. He brings German-born stunner, Carla, and promptly loses her affection to Hans, a fast-talking ski instructor. David meets Manny: they have chess in common. Soon, surprises abound as relationships take new turns.', '1999-04-16', 4.94, 'https://image.tmdb.org/t/p/w500/5zh1PQPN7dl8BX2zdaEYyiNRNXp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (110428, 'Camille Claudel 1915', 'Winter, 1915. Confined by her family to an asylum in the South of France - where she will never sculpt again - the chronicle of Camille Claudel''s reclusive life, as she waits for a visit from her brother, Paul Claudel.', '2013-03-13', 5.89, 'https://image.tmdb.org/t/p/w500/eR17us7fSvuleDSW7Hi0AXP8Gwv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (105538, 'Codependent Lesbian Space Alien Seeks Same', 'The adventures of lesbian space aliens on the planet Earth, and the story of the romance between Jane, a shy greeting card store employee, and Zoinx, the woman Jane does not realize is from outer-space. Meanwhile, two government agents, or ''Men In Black,'' are closely tracking Jane and the aliens while harboring their own secrets.', '2012-01-06', 4.50, 'https://image.tmdb.org/t/p/w500/jrc4kyKjTnXj6P8LNCqekXGjAuQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (114735, 'Kenny & Company', 'A coming-of-age story about the lives of a teenage boy and his friends as they traverse the highs and lows of boyhood in the run-up to Halloween.', '1976-11-01', 6.84, 'https://image.tmdb.org/t/p/w500/ovwEWbDo4Zb6Kpm43HdeyiIssXM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (116149, 'Paddington', 'A young Peruvian bear travels to London in search of a home. Finding himself lost and alone at Paddington Station, he meets the kindly Brown family, who offer him a temporary haven.', '2014-11-24', 7.12, 'https://image.tmdb.org/t/p/w500/wpchRGhRhvhtU083PfX2yixXtiw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (116440, 'Maggie Simpson in "The Longest Daycare"', 'Maggie must navigate an eventful first day in daycare. At the Ayn Rand School for Tots, Maggie is diagnosed with average intelligence. Barred from the gifted children, she longs to escape from her glue-guzzling classmates. But when a lonely caterpillar befriends her, she makes it her mission to save it from a ruthless butterfly smashing toddler.', '2012-07-03', 6.95, 'https://image.tmdb.org/t/p/w500/6db4Dzg3GmlQxbUrJCDhcbMvMxN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (105077, 'Battlestar Galactica: The Plan', 'When the initial Cylon attack against the Twelve Colonies fails to achieve complete extermination of human life as planned, twin Number Ones (Cavils) embedded on Galactica and Caprica must improvise to destroy the human survivors.', '2009-10-27', 6.73, 'https://image.tmdb.org/t/p/w500/vwtHIRwwASCiX0Ku487DY7YZrag.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (116745, 'The Secret Life of Walter Mitty', 'A timid magazine photo manager who lives life vicariously through daydreams embarks on a true-life adventure when a negative goes missing.', '2013-12-18', 7.23, 'https://image.tmdb.org/t/p/w500/iAo1hlzsPV9XpYcLQp6Ud065tGO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (116844, 'Drunks', 'At the beginning of a nightly Alcoholics Anonymous meeting, Jim seems particularly troubled. His sponsor encourages him to talk that night, the first time in seven months, so he does - and leaves the meeting right after. As Jim wanders the night, searching for some solace in his old stomping grounds, bars and parks where he bought drugs, the meeting goes on, and we hear the stories of survivors and addicts - some, like Louis, who claim to have wandered in looking for choir practice, who don''t call themselves alcoholic, and others, like Joseph, whose drinking almost caused the death of his child - as they talk about their lives at the meeting', '1997-03-14', 3.20, 'https://image.tmdb.org/t/p/w500/lY5E0rjsgzlxUyMtUZRlzwHqLTA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (117251, 'White House Down', 'Capitol Policeman John Cale has just been denied his dream job with the Secret Service protecting President James Sawyer. Not wanting to let down his little girl with the news, he takes her on a tour of the White House, when the complex is overtaken by a heavily armed paramilitary group. Now, with the nation''s government falling into chaos and time running out, it''s up to Cale to save the president, his daughter, and the country.', '2013-06-27', 6.46, 'https://image.tmdb.org/t/p/w500/6TeIVKPw7nXXWy2zKmDmlnSwzb7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (110415, 'Snowpiercer', 'In a future where a failed global-warming experiment kills off most life on the planet, a class system evolves aboard the Snowpiercer; a train that travels around the globe via a perpetual-motion engine.', '2013-08-01', 6.91, 'https://image.tmdb.org/t/p/w500/kw6YQudA0TMcNmGUGy5XIw7zbnV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (117259, 'Soft Fruit', 'For the first time in 15 years, all four siblings in a family show up to care for their dying mother, who is only given a couple of weeks to live. One comes from America with her two children. A divorced sister also comes with her child and sneaks off regularly to meet a mystery man who may be her ex-husband. The third & youngest daughter is an unmarried nurse aware of her ticking biological clock. The only son chases after his grumpy father who seems to not care a whit about his wife''s circumstances. The four are also faced my their mother''s dreams to accomplish a few things before she dies - to visit a beach she had visited in the past, to see her youngest married, and to visit Paris. She also wants to be embalmed and be honored with a 21 gun salute. Thus the whole group has to set off in the quest to fulfill their mother''s wishes.', '1999-10-28', 5.00, 'https://image.tmdb.org/t/p/w500/eaOehKsttNGjoaUwVRvn7c6HMQ8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (105554, 'The Forgotten Space', 'Details the catastrophic effects globalization has wrought on the ship, truck and train industries. We visit displaced farmers and villagers in Holland and Belgium, underpaid truck drivers in Los Angeles, seafarers aboard mega-ships shuttling between Asia and Europe, and factory workers in China, whose low wages are the fragile key to the whole puzzle. At a moment when collective bargaining rights are under attack in the United States, and China continues to bow to foreign pressures to prevent such rights from being granted at all, this film asks: Is capitalism the Trojan horse that turns on its inventors?', '2010-12-31', 5.50, 'https://image.tmdb.org/t/p/w500/f7Dg4t7hOFsRRNfmVM9ebEomYdM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (117974, 'Sightseers', 'Chris wants to show girlfriend Tina his world, but events soon conspire against the couple and their dream caravan holiday takes a very wrong turn.', '2012-11-30', 6.30, 'https://image.tmdb.org/t/p/w500/l52cpdZcVkEVTaLqga6xxSQoaKX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (105024, 'Stone Reader', 'Filmmaker Mark Moskowitz finally reads a critically acclaimed novel he bought back in 1972, and discovers that both the book and the author have long since vanished. STONE READER documents Moskowitz''s quest to find out why. As he solves the mystery, the twists and turns of the journey reveal something more-the singular bond literature can create among strangers.', '2002-01-11', 7.00, 'https://image.tmdb.org/t/p/w500/iimqHbKjtFxObekC6bJwjDHtRZa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (115782, 'Jobs', 'The story of Steve Jobs'' ascension from college dropout into one of the most revered creative entrepreneurs of the 20th century.', '2013-08-15', 6.13, 'https://image.tmdb.org/t/p/w500/mOyZ0UAWaOJartFq2G3Cv0soFtQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (106646, 'The Wolf of Wall Street', 'A New York stockbroker refuses to cooperate in a large securities fraud case involving corruption on Wall Street, corporate banking world and mob infiltration. Based on Jordan Belfort''s autobiography.', '2013-12-25', 8.03, 'https://image.tmdb.org/t/p/w500/kW9LmvYHAaS9iA0tHmZVq8hQYoq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (106747, 'Machete Kills', 'Ex-Federale agent Machete is recruited by the President of the United States for a mission which would be impossible for any mortal man – he must take down a madman revolutionary and an eccentric billionaire arms dealer who has hatched a plan to spread war and anarchy across the planet.', '2013-09-12', 5.62, 'https://image.tmdb.org/t/p/w500/uAl0YzUf2NHm7PqjsilmeCDbQNb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
