INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (120292, 'Not Suitable For Children', 'A young playboy who learns he has one month until he becomes infertile sets out to procreate as much as possible.', '2012-07-12', 5.29, 'https://image.tmdb.org/t/p/w500/wYxr14jTu02noGxXRqPDJgK37wC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (120328, 'Out Cold', 'Sunny is married to the butcher, Ernie, and their marriage is about to end as both of them have affairs. Thus Sunny hires Lester Atlas as private investigator in order to collect proof for the divorce. One evening drunken Ernie and his partner Dave have a fight in the butcher shop with Ernie getting knocked out in the fridge where he dies during the night. But it was not Dave''s fault but intentional murder by Sunny. Only Lester has proof so Sunny kills him, too. Thus she only has to kill Dave to get rid of all witnesses, but he can free himself out of the fridge and wants to take revenge.', '1989-03-03', 5.95, 'https://image.tmdb.org/t/p/w500/hNZHSsF7HPzldLv5SJnRD2BLpAF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (120467, 'The Grand Budapest Hotel', 'The Grand Budapest Hotel tells of a legendary concierge at a famous European hotel between the wars and his friendship with a young employee who becomes his trusted protégé. The story involves the theft and recovery of a priceless Renaissance painting, the battle for an enormous family fortune and the slow and then sudden upheavals that transformed Europe during the first half of the 20th century.', '2014-02-26', 8.00, 'https://image.tmdb.org/t/p/w500/eWdyYQreja6JGCzqHWXpWHDrrPo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (115199, 'The History of Future Folk', 'An alien intending to claim Earth for his people before their homeworld is destroyed by a comet decides not to eliminate humanity when he hears their music. Instead, he lives among them until another alien is sent to find and kill him.', '2012-06-15', 6.61, 'https://image.tmdb.org/t/p/w500/cJHq7n8fl6p5tY0Jr6GQ2uoO0rR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (121676, 'Inescapable', 'Twenty-five years ago Adib, a promising young officer in the Syrian military police, suddenly left Damascus under suspicious circumstances. Abandoning the love of his life Fatima, he made his way to Canada and wiped the slate clean. When his daughter Muna suddenly disappears in Damascus, his past threatens to violently catch up to him. Teaming up with a Canadian emissary, Adib must now confront the turmoil he thought he left behind in order to find Muna.', '2012-09-14', 5.17, 'https://image.tmdb.org/t/p/w500/gCeZGBFcxjyGdvFncJqCGffBCpw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
