INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (121606, 'Resolution', 'A man imprisons his estranged junkie friend in an isolated cabin in the boonies of San Diego to force him through a week of sobriety, but the events of that week are being mysteriously manipulated.', '2013-01-25', 6.34, 'https://image.tmdb.org/t/p/w500/gTZTCMmU7N0qTWJrSUOVBI70ZlA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (107569, 'Memories of Me', 'After a heart attack, Abbie Polin (Crystal), a New York doctor, goes to Los Angeles to see his father, Abe (King), who works in Hollywood as the "king of the extras." Their relationship has been strained for several years. Lisa, the romantic interest in Abbie''s life, bonds with Abe, who gets along famously with everyone but his son. Abe begins having memory loss and eventually is diagnosed with a brain aneurysm. He and his son grow closer in time and, before it''s too late, Abbie tries to get Abe a speaking role in a film.', '1988-09-28', 5.40, 'https://image.tmdb.org/t/p/w500/sveCOcLBNrUPzcgEGrcRzdqfCvH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (121824, 'Stand Up Guys', 'After serving 28 years in prison for accidentally killing the son of a crime boss, newly paroled gangster Val reunites with his former partners in crime, Doc and Hirsch, for a night on the town. As the three men revisit old haunts, reflect on their glory days and try to make up for lost time, one wrestles with a terrible quandary: Doc has orders to kill Val, and time is running out for him to figure out a way out of his dilemma.', '2012-12-14', 6.03, 'https://image.tmdb.org/t/p/w500/pOXmX1rldFQv3rFkWwe4uqbPWPJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (121856, 'Assassin''s Creed', 'Through a technology that unlocks the genetic memories of his ancestor in 15th century Spain, Callum Lynch discovers he is a descendant of an ancient line of Assassins and amasses lethal skills to take on the oppressive Templar Order.', '2016-12-21', 5.44, 'https://image.tmdb.org/t/p/w500/kDXewoEcvbn0pUvJ8W3vfkuWgHw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (121870, 'Patti Rocks', 'It''s Christmas time in the twin cities. Billy''s working a lot of overtime, running barges on the Mississippi. He calls his friend Eddie, whom he hasn''t seen in six months, and asks a favor: to drive with him to see his pregnant girlfriend, Patti, because Billy hasn''t told her he''s married and already has two children. The road trip of guy talk becomes a night of truths exchanged between men and women.', '1988-01-15', 3.40, 'https://image.tmdb.org/t/p/w500/cvi8hjUgDeBaE1wP4WPVdzyBNoo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (122796, 'Bad Karma', 'Jack Malloy is a hardcore career criminal until a near-death experience causes him to turn his world around. But when his former partner Drake is released from prison, he tracks Jack down to blackmail him into one last job. Jack is a new man determined to lead an honest life. Drake is a charming psycho intent on vengeance. Sometimes, old friends can carry some extreme baggage. And for one of them, coming to terms with the past is going to be murder. Vanessa Gray and Andy McPhee co-star in this taut action/drama about good intentions, dark secrets and the harsh consequences of BAD KARMA.', '2012-09-12', 4.53, 'https://image.tmdb.org/t/p/w500/Am8zDtxkWlqtY5nVn7TKgsgw6C7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (122857, 'Universal Soldier: Day of Reckoning', 'After his wife and daughter are murdered in a home invasion, a widower named John now finds himself up against an army of Universal Soldiers in relentless pursuit, led by a mysterious leader who promises to set UniSols free from their conditioning.', '2012-10-04', 5.57, 'https://image.tmdb.org/t/p/w500/4pefZa0U5h0avmdvRwWB4xjMFl6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (123047, 'Turtle Diary', 'Two separate people, a man and a woman, find something very stirring about the sea turtles in their tank at the London Zoo. They meet and form an odd, but sympathetic camaraderie as they plan to steal two of the turtles and free them into the ocean.', '1985-12-06', 6.27, 'https://image.tmdb.org/t/p/w500/tY9j8r1dVVrATeThyro02ALmWwF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
