INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (123723, 'Gigi', 'Gilberte is a sixteen year old girl raised by her aunt and grandmother to be a demimondaine. But she''s not ready for that yet, and spends her days in lessons and in teasing Mamita''s old friend, the rich playboy Gaston LaChaille, and following his affairs from afar. But when Gaston throws off his latest mistress, it looks as if Gigi just might be ready to begin her destined career.', '1949-10-05', 6.10, 'https://image.tmdb.org/t/p/w500/devLzCOnSjKKXNZmXxVB8Rd86bA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (118628, 'English Vinglish', 'In the United States for the first time, an Indian housewife with a limited command of English turns Manhattan into her personal language school.', '2012-09-21', 7.25, 'https://image.tmdb.org/t/p/w500/ccEVR8sf18psGH5daio9y7OGu93.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (121986, 'Frances Ha', 'An aspiring dancer moves to New York City and becomes caught up in a whirlwind of flighty fair-weather friends, diminishing fortunes and career setbacks.', '2013-05-17', 7.30, 'https://image.tmdb.org/t/p/w500/jrq1NoKvsxWCcffVOjegiYwloFN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (123757, 'All the Vermeers in New York', 'A parable of the missteps of life enacted in the hothouse world of late 1980’s New York, in which the art market and the stock market each boomed, and in process spawned a smorgasbord of “yuppie” delusions which still persist. Anna, a French actress studying in New York, crosses paths with a successful stock-broker, Mark, standing before a Vermeer portrait at the Metropolitan, thence ensues a peculiar romance of missed meanings and connections, with tangential asides to the steaming arts world and stock market, loft-mate conflicts, and, perhaps, love. Wrapped up in their blindered worlds, Anna and Mark deflect away from their chances, leaving at the conclusion the wistful face of Vermeer’s portrait enigmatically asking questions. All the Vermeers in New York is a comedy of manners which, as gently as a Vermeer, looks beneath the skin of this time and place, and of these characters.', '1992-05-01', 5.54, 'https://image.tmdb.org/t/p/w500/sQmBGBIjDvX2nMwUHI3yQv4YAJ9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
