INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (124626, 'Nico Icon', 'A look into the many lives of Christa Päffgen, otherwise known as Nico; from cutie German mädchen to the first of the supermodels, to glamorous diva of the Velvet Underground, to cult item, junkie and hag. Many faces for the same woman, whom, you realize, just couldn''t bring herself to care enough to live.', '1995-09-08', 8.10, 'https://image.tmdb.org/t/p/w500/w3oiJZTB1UP3lj0uSVLdsYfsBbC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (116776, 'Dragon Ball: Mystical Adventure', 'Master Roshi has succeeded at the one mission he valued most: to train Goku and Krillin to become ultimate fighters. So, he arranges for them to test their mettle at a competition hosted by Emperor Chiaotzu. Not everyone''s playing by the rules, however, as a member of the ruler''s household schemes to use the Dragonballs to extort money and power from the royal.', '1988-07-09', 6.68, 'https://image.tmdb.org/t/p/w500/4uPs9rjKkGWOmc5QO4VV08YdLpV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (124829, 'The Line King: The Al Hirschfeld Story', 'The childhood, adolescence, and incredible adult years of Al Hirschfeld, celebrated creator of thousands of line drawings of famous people - many in the entertainment industry - over a span of more than sixty years. He is still drawing in his nineties. His interesting domestic life, political, and cultural views are highlights. In addition, he talks about himself a bit - seriously and lightly.(At one point he he claims that his only form of exercise has been to live in his Manhattan townhouse: stairs). He drives his car around Manhattan - an adventure in itself. Brief interviews with, and reminiscences of many friends and associates.', '1996-09-27', 7.20, 'https://image.tmdb.org/t/p/w500/msLmn8QJLKpG8GHwbSbvX6iYmoB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (118677, 'Why Stop Now?', 'When a college piano prodigy tries to check his mother into rehab, he is taken hostage by her drug dealer and swept along on a wild adventure.', '2012-08-17', 5.39, 'https://image.tmdb.org/t/p/w500/xEaVD2RJADGWUhlBkhGV0vQoHrP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (124117, 'Pixel Perfect', 'Samantha''s band, the Zettabytes, is meeting with little success, so her friend Roscoe uses his knowledge of technology designed by his father to create a holographic lead singer, Loretta Modern. The band instantly becomes successful, but Samantha begins to feel alienated, Roscoe discovers feelings for Samantha, and Loretta struggles with individuality.', '2004-11-13', 5.27, 'https://image.tmdb.org/t/p/w500/Apz1iXuiAUNArN7CLXGHNCuVeSn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (125052, 'Hurricane Streets', 'Marcus is a New York City street kid torn between his friends'' criminal activities and a girl trying to keep him out of trouble.', '1997-01-21', 5.25, 'https://image.tmdb.org/t/p/w500/kI8WAtPfjiPygfdKcwYJUkMZyh4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (122917, 'The Hobbit: The Battle of the Five Armies', 'Following Smaug''s attack on Laketown, Bilbo and the dwarves try to defend Erebor''s mountain of treasure from others who claim it: the men of the ruined Laketown and the elves of Mirkwood. Meanwhile an army of Orcs led by Azog the Defiler is marching on Erebor, fueled by the rise of the dark lord Sauron. Dwarves, elves and men must unite, and the hope for Middle-Earth falls into Bilbo''s hands.', '2014-12-10', 7.34, 'https://image.tmdb.org/t/p/w500/xT98tLqatZPQApyRmlPL12LtiWp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (122906, 'About Time', 'The night after another unsatisfactory New Year''s party, Tim''s father reveals to him that the men in their family have the ability to travel through time. They can''t change history, but they can change what happens and has happened in their own lives. Thus begins the start of a lesson in learning to appreciate life itself as it is, as it comes, and most importantly, the people living alongside us.', '2013-09-04', 7.90, 'https://image.tmdb.org/t/p/w500/ls6zswrOZVhCXQBh96DlbnLBajM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (125124, 'The Best Man', 'Incredibly, the bride at the altar falls in love with the best man on first sight, and even though he makes efforts to avoid her infatuation with him, she is determined to annul her marriage and marry the best man. And although she is able to dissolve her marriage, because she has never consummated it, the best man leaves... only to return to her many months later.', '1997-10-28', 7.41, 'https://image.tmdb.org/t/p/w500/it3TqsjG19roZJTM1zbogEj10Mg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (125464, 'A Cosmic Christmas', 'Three aliens from an unknown planet, who bear a strong resemblance to the Biblical Magi, visit earth to know the true meaning of Christmas. Peter, a young boy, and Lucy, his goose, are the first to encounter them. Unable to find the true meaning of Christmas in town, Peter takes them to his family''s house in the woods. While Peter''s grandmother tells the aliens about her memories of Christmas, Marvin, one of the town''s bullies, steals Lucy. In the chase to rescue Lucy, Marvin falls through the ice in a lake. Peter attempts to rescue him but falls into the lake as well. The townsfolk, who were out searching for the aliens, attempt to save the boys but their human chain isn''t long enough to reach them. The three aliens, who had sworn not to interfere with events on earth, decide to help in order to learn the meaning of Christmas.', '1977-12-04', 5.82, 'https://image.tmdb.org/t/p/w500/HEHGkQM1dIep8JURqfHNYIn2O9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (125587, 'Nothing Personal', 'A raw depiction of the Belfast ''troubles'' as savage tribal warfare. Set shortly after the 1975 cease fire, the film focuses on the tribulations of Kenny, Protestant leader of a group of Shankill Road Loyalists, and his one-time friend Liam, a Catholic.', '1996-10-18', 4.85, 'https://image.tmdb.org/t/p/w500/yEv3mKU7TMQJDUnPoIDsO0QTts2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (125537, 'Smiling Fish & Goat On Fire', 'Two brothers share a house in LA''s Fairfax district: Tony''s a feckless actor, Chris is an accountant. Both are in relationships on rocky ground. As these emotions swirl, Tony meets his US Postal Service letter carrier, a single mom named Kathy who''s come to LA from Wyoming with her daughter, a budding actress. Chris meets Anna, an Italian beauty working in the States for a few months wrangling animals on movie sets. Chris also befriends Clive, an aging and crusty man whose longing for his recently-deceased wife is a portrait of true love. Can Clive''s example help Chris sort out his love life, and can Tony grow up enough to see the possibilities with Kathy and her daughter?', '1999-09-16', 5.17, 'https://image.tmdb.org/t/p/w500/cGCNG3Md9t0Zvhksr27aqXa1AI9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (125709, 'Joe Gould''s Secret', 'Around 1940, New Yorker staff writer Joe Mitchell meets Joe Gould, a Greenwich Village character who cadges meals, drinks, and contributions to the Joe Gould Fund and who is writing a voluminous Oral History of the World, a record of 20,000 conversations he''s overheard. Mitchell is fascinated with this Harvard grad and writes a 1942 piece about him, "Professor Seagull," bringing Gould some celebrity and an invitation to join the Greenwich Village Ravens, a poetry club he''s often crashed. Gould''s touchy, querulous personality and his frequent dropping in on Mitchell for hours of chat lead to a breakup, but the two Joes stay in touch until Gould''s death and Mitchell''s unveiling of the secret.', '2000-01-21', 6.00, 'https://image.tmdb.org/t/p/w500/n7X4jmmRIRtqNQWXJt8LxZcS1Ja.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (111794, '20 Dates', 'Myles is divorced in L.A. He wants a love life and a film career. So he decides to go on 20 dates and find true love in front of a camera, making his first feature. His patient agent, Richard, finds a $60,000 investor, the shadowy Elie. Myles starts his search, sometimes telling his date she''s being filmed, sometimes not. Elie wants sex and titillation, Myles wants it "real." Myles regularly talks with his old film teacher, Robert McKee, who wonders if love is possible in modern life. Half-way through the 20 dates, Myles meets Elisabeth; she''s everything he desires and she likes him. Can he finish the 20 dates, satisfy Elie, and complete his film without losing Elisabeth?', '1998-01-01', 5.33, 'https://image.tmdb.org/t/p/w500/79TTGQZrOAzwuWxcOy8y6k6Ldm0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (126117, 'This So-Called Disaster', 'Director Michael Almereyda''s documentary on the weeks just prior to Sam Shepard''s stage production of his play "The Late Henry Moss."', '2003-01-01', 5.25, 'https://image.tmdb.org/t/p/w500/AbuKSyMOWOh3Yw1GOC454EAZD6K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (126148, 'Lightning in a Bottle', 'On February 7th, 2003, renowned artists across multiple music genres and generations commandeered the stage at New York City''s Radio City Music Hall to pay tribute to their common heritage and passion - the blues. Shared with thousands of fans in attendance, legendary performers from roots, rock, jazz and rap joined forces for a once-in-a-lifetime "Salute To The Blues" benefit concert whose proceeds went to musical education.', '2004-02-12', 7.57, 'https://image.tmdb.org/t/p/w500/w029ZDkxyi8Lf0Hps3loJ8857Qt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (126644, 'By the Law', 'After a man kills two members of his Yukon gold prospecting team, the other two surviving members struggle to keep him subdued for the next several months until they can turn him over to the law.', '1926-12-03', 6.60, 'https://image.tmdb.org/t/p/w500/en5KODxMeWO5KgFDFh8974mfSgS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (126319, 'Ernest & Celestine', 'Celestine is a little mouse trying to avoid a dental career while Ernest is a big bear craving an artistic outlet. When Celestine meets Ernest, they overcome their natural enmity by forging a life of crime together.', '2012-12-12', 7.76, 'https://image.tmdb.org/t/p/w500/iJPbRASktYW0I009Ktc2zUE6Fvg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (111440, 'The Pact', 'After their mother passes away, sisters Nicole and Annie reluctantly return to their childhood home to pay their last respects. While staying overnight in the house, the sisters sense a mysterious presence in their midst: noises startling them in the night, objects moving about, a fallen picture of an unknown woman posed next to their mother. Annie begins experiencing a series of intense and disturbing dreams - visions that lead her to uncover something terrible about her mother''s past that is finally revealing itself.', '2012-05-25', 5.67, 'https://image.tmdb.org/t/p/w500/o0a4iSc5yKEiV15NCTI5GwrZudc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (126797, 'Mental', 'A charismatic, crazy hothead transforms a family''s life when she becomes the nanny of five girls.', '2012-10-04', 5.60, 'https://image.tmdb.org/t/p/w500/dIPAKUCtvLPrVauQwA0tdsPJo2w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (126846, 'The Adventures of Sherlock Holmes and Dr. Watson: King of Blackmailers', 'Mycroft Holmes hands Sherlock Holmes the case of the Master Blackmailer.', '1980-09-08', 7.58, 'https://image.tmdb.org/t/p/w500/uSVz0PDiOpwMN475oVcNz7vB4W0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (117098, 'Cloudburst', 'When Dot''s granddaughter puts her into a nursing home, Stella stages a breakout, and takes Dot to Canada so they can get married. They pick up a hitchhiker along the way.', '2011-09-23', 6.35, 'https://image.tmdb.org/t/p/w500/x4vlDX1xc0ZPRYnzyiGMpUOBSPv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (126963, 'Dragon Ball Z: Battle of Gods', 'After the defeat of Majin Buu, a powerful God of Destruction known as Beerus searches for the Saiyan warrior who defeated Frieza. Realizing the threat Beerus poses to Earth, the Z-fighters must stop him. Only Goku, humanity’s last hope, can ascend to the level of a legendary Super Saiyan God and save the planet, and possibly the entire universe!', '2013-03-30', 6.80, 'https://image.tmdb.org/t/p/w500/nxZEdYcHMuD8SSuwusDnK9CD2H1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (124459, 'The Incredible Burt Wonderstone', 'After breaking up with his longtime stage partner, a famous but jaded Vegas magician fights for relevance when a new, "hip" street magician appears on the scene.', '2013-03-14', 5.75, 'https://image.tmdb.org/t/p/w500/Bl95sg5Ljo3Hu9SSL0JOvLerLh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (126889, 'Alien: Covenant', 'The crew of the colony ship Covenant, bound for a remote planet on the far side of the galaxy, discovers what they think is an uncharted paradise but is actually a dark, dangerous world.', '2017-05-09', 6.18, 'https://image.tmdb.org/t/p/w500/zecMELPbU5YMQpC81Z8ImaaXuf9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (127517, 'Disconnect', 'A hard-working lawyer, attached to his cell phone, can''t find the time to communicate with his family. An estranged couple uses the internet as a means to escape from their lifeless marriage. A widowed ex-cop struggles to raise a mischievous son who cyber-bullies a classmate. An ambitious journalist sees a career-making story in a teen that performs on an adult-only site. They are strangers, neighbors and colleagues and their stories collide as ordinary people struggling to connect in today''s wired world.', '2013-04-12', 7.08, 'https://image.tmdb.org/t/p/w500/mAStXq4ncbLBnujd3LG4KDd7Z3a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (127585, 'X-Men: Days of Future Past', 'The ultimate X-Men ensemble fights a war for the survival of the species across two time periods as they join forces with their younger selves in an epic battle that must change the past – to save our future.', '2014-05-15', 7.54, 'https://image.tmdb.org/t/p/w500/tYfijzolzgoMOtegh1Y7j2Enorg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (127867, 'The Brass Teapot', 'When a couple discovers that a brass teapot makes them money whenever they hurt themselves, they must come to terms with how far they are willing to go.', '2012-09-08', 6.13, 'https://image.tmdb.org/t/p/w500/6txTmb8OIimrQezgD8ERMmrrbnT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (127602, 'Happy Go Lovely', 'Rich bachelor B.G. Bruno, the head of a successful greeting-card company in Scotland, is essentially a kind man but respectable to the point of stodginess and extreme stuffiness. An American troupe visiting Edinburgh wants to produce a musical in town but has trouble getting financiers. Bruno meets several leading ladies; through a misunderstanding, he doesn''t correct their impression that he''s a newspaper reporter.', '1951-03-06', 6.10, 'https://image.tmdb.org/t/p/w500/alnkjFvq0DC7IaS6QKJTYRlanQV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (127380, 'Finding Dory', 'Dory is reunited with her friends Nemo and Marlin in the search for answers about her past. What can she remember? Who are her parents? And where did she learn to speak Whale?', '2016-06-16', 7.04, 'https://image.tmdb.org/t/p/w500/3UVe8NL1E2ZdUZ9EDlKGJY5UzE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (127608, 'The Adventures of Sherlock Holmes and Dr. Watson: The Treasures of Agra', 'Holmes and Dr. Watson help a young lady who is receiving anonymous letters 10 years after her father passed away under shady circumstances. They find themselves in an enigma involving a treasure, murder and a love interest for Watson.', '1983-06-25', 7.50, 'https://image.tmdb.org/t/p/w500/1WXKw7sR2ZlBtOAWY2IXdmc2fEa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (128190, 'The Pervert''s Guide to Ideology', 'A journey into the labyrinthine heart of ideology, which shapes and justifies both collective and personal beliefs and practices: with an infectious zeal and voracious appetite for popular culture, Slovenian philosopher and psychoanalyst Slavoj Žižek analyzes several of the most important films in the history of cinema to explain how cinematic narrative helps to reinforce prevailing ethics and political ideas.', '2012-11-15', 7.32, 'https://image.tmdb.org/t/p/w500/tGmLQzLuok7qB0xVLv7s6rvUdl3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (128767, 'God Loves Caviar', 'The true-life, stranger-than-fiction tale of eighteenth-century Greek pirate turned merchant Ioannis Varvakis, who rose from humble beginnings to become the head of one of the largest mercantile empires in Europe.', '2012-08-04', 5.42, 'https://image.tmdb.org/t/p/w500/owFV0qujjF1l3TdD3ZJCp6pW5og.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (129112, 'Wadjda', 'An enterprising Saudi girl signs on for her school''s Quran recitation competition as a way to raise the remaining funds she needs in order to buy the green bicycle that has captured her interest.', '2012-12-06', 7.22, 'https://image.tmdb.org/t/p/w500/w4iCIZ1kWSOCt0yELjfUMNAToUF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (129229, 'A Plasticine Crow', 'Short animation of a Russian folk tale, made in 1981. A parody of the fable by Ivan Krylov "The Crow and the Fox".', '1981-12-31', 7.29, 'https://image.tmdb.org/t/p/w500/80QaOskAV7IWlqZw4orrw0bjQVZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (130739, 'A Coffee in Berlin', 'Niko, a twenty-something college dropout, lives for the moment as he drifts through the streets of Berlin, curiously observing everyone around him and oblivious to his growing status as an outsider. Then on one fateful day, through a series of absurdly amusing encounters, everything changes.', '2012-11-01', 7.20, 'https://image.tmdb.org/t/p/w500/gy58pmCztFrpxaRM9rGhv93LgCP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (130824, 'As I Was Moving Ahead Occasionally I Saw Brief Glimpses of Beauty', 'A compilation of over 30 years of private home movie footage shot by Lithuanian-American avant-garde director Jonas Mekas, assembled by Mekas "purely by chance", without concern for chronological order.', '2000-11-05', 7.75, 'https://image.tmdb.org/t/p/w500/tDaxB5juEGwXD7oZwh8IXsnisar.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (123025, 'Batman: The Dark Knight Returns, Part 1', 'Batman has not been seen for ten years. A new breed of criminal ravages Gotham City, forcing 55-year-old Bruce Wayne back into the cape and cowl. But, does he still have what it takes to fight crime in a new era?', '2012-09-25', 7.74, 'https://image.tmdb.org/t/p/w500/rVr2Tdp2LcL3DheXUrVN345Myhg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (124472, 'A Great Day in Harlem', 'Art Kane, now deceased, coordinated a group photograph of all the top jazz musicians in NYC in the year 1958, for a piece in Esquire magazine. Just about every jazz musician at the time showed up for the photo shoot which took place in front of a brownstone near the 125th street station. The documentary compiles interviews of many of the musicians in the photograph to talk about the day of the photograph, and it shows film footage taken that day by Milt Hinton and his wife.', '1994-09-27', 6.60, 'https://image.tmdb.org/t/p/w500/606IorDjRMQZYaEdPBvjM8uI6qm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (117263, 'Olympus Has Fallen', 'When the White House (Secret Service Code: "Olympus") is captured by a terrorist mastermind and the President is kidnapped, disgraced former Presidential guard Mike Banning finds himself trapped within the building. As the national security team scrambles to respond, they are forced to rely on Banning''s inside knowledge to help retake the White House, save the President and avert an even bigger disaster.', '2013-03-20', 6.42, 'https://image.tmdb.org/t/p/w500/u3GTFGwesNBNd0t1hiLaEk1iqZU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (131634, 'The Hunger Games: Mockingjay - Part 2', 'As the war between the Capitol and the districts reaches its peak, Katniss Everdeen embarks on a perilous mission to liberate Panem and confront President Snow. Joined by a team of trusted allies, she navigates deadly traps, shifting loyalties, and the heavy cost of rebellion, determined to bring freedom to her people and end the Hunger Games once and for all.', '2015-11-18', 6.90, 'https://image.tmdb.org/t/p/w500/lImKHDfExAulp16grYm8zD5eONE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (131244, 'Bliss', 'Two young people in Berlin, a refugee and a homeless punk, form a relationship.', '2012-02-22', 5.43, 'https://image.tmdb.org/t/p/w500/rwV9C36GHI1PrCvTAKOtvlcQWjM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (117553, 'Calendar Girl', 'Three young men go on an end of the summer trip to Hollywood, California. Their quest: to fulfill the fantasy of meeting Marilyn Monroe.', '1993-09-03', 5.18, 'https://image.tmdb.org/t/p/w500/ljSqZTl5oophHsH1Qtyv7AF2BW6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (118098, 'Madame Sousatzka', 'In London, eccentric piano instructor Madame Sousatzka takes on a new prize protégé, Manek, a teenage Bengali immigrant who displays incredible talent. Manek forms a close bond with his teacher, but soon discovers that she expects her pupils to become disciplined in all areas of life, and not just behind the piano. As he struggles to meet the challenges, Manek must also deal with his mother, who vies with his teacher for his attention.', '1988-10-14', 6.90, 'https://image.tmdb.org/t/p/w500/iXBUkgTfFzT9OC9B4egsF0rSAPr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (123105, 'The Bay', 'Chaos breaks out in a small Maryland town after an ecological disaster occurs.', '2012-09-13', 5.81, 'https://image.tmdb.org/t/p/w500/fnmYgr4AOOE09zKa7omPW1FWT8K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (131631, 'The Hunger Games: Mockingjay - Part 1', 'After surviving the Quarter Quell, Katniss finds herself in the hidden stronghold of District 13, where the rebellion against the Capitol is gaining momentum. Struggling with the weight of becoming the symbol of resistance, she must navigate fragile alliances while trying to protect those she loves. As propaganda battles rage and Panem moves closer to full-scale war, Katniss is forced to confront the true cost of revolution.', '2014-11-19', 6.82, 'https://image.tmdb.org/t/p/w500/4FAA18ZIja70d1Tu5hr5cj2q1sB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (131957, 'Nina Takes a Lover', 'When Nina''s husband goes out of town for several weeks on a business trip, Nina hooks up with a photographer. Told from a reporter''s point of view, his interviews with Nina and the photographer provide comic insights.', '1995-03-03', 5.57, 'https://image.tmdb.org/t/p/w500/ouiE82bOuBl4IeEnY2gJe8teQFT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (118340, 'Guardians of the Galaxy', 'Light years from Earth, 26 years after being abducted, Peter Quill finds himself the prime target of a manhunt after discovering an orb wanted by Ronan the Accuser.', '2014-07-30', 7.91, 'https://image.tmdb.org/t/p/w500/r7vmZjiyZw9rpJMQJdXpjgiCOk9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (123107, 'Hellbenders', 'An exorcism comedy which follows the Order of Hellbound Saints (Brooklyn Parish), a highly secretive and profoundly blasphemous men of God, as they battle demonic forces too terrible to be cast out by traditional Vatican-approved methods.', '2013-10-18', 5.37, 'https://image.tmdb.org/t/p/w500/sWgCQPypdN9jFaUSjItPn9htW9p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (124680, 'Broken English', 'Ivan is the fierce patriarch of a family of Croatian refugees living in Auckland during the Yugoslav wars. Nina is his daughter, ready to live on her own, despite his angry objections. Eddie is the Maori she takes as her lover. Nina works at the restaurant where Eddie cooks. For a price, she agrees to marry another restaurant employee, a Chinese man, so that he can establish permanent residency. The money gives her the independence she needs to leave her parents'' house and move in with Eddie. Complications arise when Eddie realizes the depth of her father''s fury and the strength of Nina''s family ties.', '1996-09-09', 5.64, 'https://image.tmdb.org/t/p/w500/137yYXxYLGvm6UrkQfkpdWCV83k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (134411, 'Snitch', 'Construction company owner John Matthews learns that his estranged son, Jason, has been arrested for drug trafficking. Facing an unjust prison sentence for a first time offender courtesy of mandatory minimum sentence laws, Jason has nothing to offer for leniency in good conscience. Desperately, John convinces the DEA and the opportunistic DA Joanne Keeghan to let him go undercover to help make arrests big enough to free his son in return. With the unwitting help of an ex-con employee, John enters the narcotics underworld where every move could be his last in an operation that will demand all his resources, wits and courage to survive.', '2013-02-21', 6.13, 'https://image.tmdb.org/t/p/w500/1suKSCm8gVUIIOh4MgtWAtzkMe4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (134374, 'Pain & Gain', 'Daniel Lugo, manager of the Sun Gym in 1990s Miami, decides that there is only one way to achieve his version of the American dream: extortion. To achieve his goal, he recruits musclemen Paul and Adrian as accomplices. After several failed attempts, they abduct rich businessman Victor Kershaw and convince him to sign over all his assets to them. But when Kershaw makes it out alive, authorities are reluctant to believe his story.', '2013-04-18', 6.29, 'https://image.tmdb.org/t/p/w500/9WqA0Ry9wmTzFvom8mNbcyKZQgP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (118430, 'The Forbidden Dance', 'A princess in the Amazon rain forests tries to fight a conglomerate threatening the forests by going to Los Angeles. There she links up with a rich kid who tells her that she must get on television to succeed with her mission. Quick as a wink, the two come up with the idea of winning a lambada dance contest.', '1990-03-16', 6.10, 'https://image.tmdb.org/t/p/w500/2qdAXHzx1VLmBsS3TvPbHg4RnO7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (135397, 'Jurassic World', 'Twenty-two years after the events of Jurassic Park, Isla Nublar now features a fully functioning dinosaur theme park, Jurassic World, as originally envisioned by John Hammond.', '2015-06-06', 6.70, 'https://image.tmdb.org/t/p/w500/rhr4y79GpxQF9IsfJItRXVaoGs4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (135708, 'Nature Calls', 'Polar-opposite brothers Randy and Kirk never saw eye-to-eye, but their rivalry is taken to a new level when Randy hijacks Kirk''s son''s sleepover, taking the boys on a Scout Trip to remember.', '2012-03-10', 4.04, 'https://image.tmdb.org/t/p/w500/xq20qo5gj5eMnDY0bdZDktrLyrl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (135921, 'Everything or Nothing', 'The story of three men with a shared dream: James Bond franchise producers Albert R. Broccoli and Harry Saltzman, and Bond creator and author Ian Fleming. It’s the thrilling and inspiring narrative behind the longest running film franchise in cinema history, which began in 1962.', '2012-10-05', 7.23, 'https://image.tmdb.org/t/p/w500/j7ibOc2uYDZbIr7T0aaFMdIi6Ud.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (136386, 'The Knot', 'A couple endures a series of mishaps right before their wedding day.', '2012-10-05', 4.30, 'https://image.tmdb.org/t/p/w500/AsH7mCK965PxxRuN7ut9tpLxFez.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (136400, '2 Guns', 'A DEA agent and an undercover Naval Intelligence officer who have been tasked with investigating one another find they have been set up by the mob -- the very organization the two men believe they have been stealing money from.', '2013-08-02', 6.54, 'https://image.tmdb.org/t/p/w500/ptURGAFktibhk7DEAbMazlmNqWa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (136418, 'Hummingbird', 'Homeless and on the run from a military court martial, a damaged ex-special forces soldier navigating London''s criminal underworld seizes an opportunity to assume another man''s identity, transforming into an avenging angel in the process.', '2013-05-07', 6.17, 'https://image.tmdb.org/t/p/w500/m1EVOMMeCD75bBUPTfejSPzGDrb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (136795, 'The Heat', 'Uptight and straight-laced, FBI Special Agent Sarah Ashburn is a methodical investigator with a reputation for excellence--and hyper-arrogance. Shannon Mullins, one of Boston P.D.''s "finest," is foul-mouthed and has a very short fuse, and uses her gut instinct and street smarts to catch the most elusive criminals. Neither has ever had a partner, or a friend for that matter. When these two wildly incompatible law officers join forces to bring down a ruthless drug lord, they become the last thing anyone expected: buddies.', '2013-06-27', 6.59, 'https://image.tmdb.org/t/p/w500/yERBa1y5zNUOTRKQPiDCPIc2fuv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (136797, 'Need for Speed', 'The film revolves around a local street-racer who partners with a rich and arrogant business associate, only to find himself framed by his colleague and sent to prison. After he gets out, he joins a New York-to-Los Angeles race to get revenge. But when the ex-partner learns of the scheme, he puts a massive bounty on the racer''s head, forcing him to run a cross-country gauntlet of illegal racers in all manner of supercharged vehicles.', '2014-03-12', 6.45, 'https://image.tmdb.org/t/p/w500/4ktdbrhCnAoDGLW36afjB717Sa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (137093, 'Last Vegas', 'Aging pals Billy, Paddy, Archie, and Sam have been best friends since childhood. When Billy finally proposes to his much-younger girlfriend, all four friends go to Las Vegas to celebrate the end of Billy''s longtime bachelorhood and relive their glory days. However, the four quickly realize that the intervening decades have changed Sin City and tested their friendship in ways they had not imagined.', '2013-10-31', 6.40, 'https://image.tmdb.org/t/p/w500/9Aht200Eu2jYiE9cEQdFfNDtHl6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (137094, 'Jack Ryan: Shadow Recruit', 'Jack Ryan, as a young covert CIA analyst, uncovers a Russian plot to crash the U.S. economy with a terrorist attack.', '2014-01-15', 6.12, 'https://image.tmdb.org/t/p/w500/m7HcLUodrD4lM4s0Hui1tzO2pjO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (137106, 'The Lego Movie', 'An ordinary Lego mini-figure, mistakenly thought to be the extraordinary MasterBuilder, is recruited to join a quest to stop an evil Lego tyrant from conquering the universe.', '2014-02-06', 7.43, 'https://image.tmdb.org/t/p/w500/lbctonEnewCYZ4FYoTZhs8cidAl.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (137113, 'Edge of Tomorrow', 'Major Bill Cage is an officer who has never seen a day of combat when he is unceremoniously demoted and dropped into combat. Cage is killed within minutes, managing to take an alpha alien down with him. He awakens back at the beginning of the same day and is forced to fight and die again... and again - as physical contact with the alien has thrown him into a time loop.', '2014-05-27', 7.64, 'https://image.tmdb.org/t/p/w500/nBM9MMa2WCwvMG4IJ3eiGUdbPe6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (123678, 'The Act of Killing', 'In this chilling and groundbreaking documentary, former Indonesian death squad leaders reenact their real-life mass killings in the style of various film genres. As they recreate their past atrocities, the line between reality and performance blurs, exposing the lingering impact of Indonesia''s 1965-66 anti-communist purge and the unsettling psychology of its perpetrators.', '2012-11-08', 7.67, 'https://image.tmdb.org/t/p/w500/sp5B7Tz5ttsgOLnIlCP5uEhtesI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (137321, 'Winter''s Tale', 'A burglar falls for an heiress as she dies in his arms. When he learns that he has the gift of reincarnation, he sets out to save her.', '2014-02-13', 6.28, 'https://image.tmdb.org/t/p/w500/sdmHGy9c92SjAhz1h05TSLfnnAj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (137347, 'Closer to the Moon', 'A Romanian police officer teams up with a small crew of bank robbers to pull off a heist by convincing everyone at the scene of the crime that they are only filming a movie.', '2014-03-07', 6.49, 'https://image.tmdb.org/t/p/w500/pBqnSEkLMZoEFgOCQLxM7wKmmS0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (137698, 'The Dance of Reality', '''Having broken away from my illusory self, I was desperately seeking a path and a meaning to life.'' This phrase perfectly sums up Alejandro Jodorowsky’s biographical project: reconstituting the incredible adventure of his life. He was born in 1929 Tocopilla, a coastal town on edge of the Chilean desert, where he discovered the fundamentals of reality, as he underwent an unhappy and alienated childhood as part of an uprooted family.', '2013-06-19', 7.21, 'https://image.tmdb.org/t/p/w500/2qbsG9t943DciYTHITISzXQltqt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (124905, 'Godzilla', 'Ford Brody, a Navy bomb expert, has just reunited with his family in San Francisco when he is forced to go to Japan to help his estranged father, Joe. Soon, both men are swept up in an escalating crisis when an ancient alpha predator arises from the sea to combat malevolent adversaries that threaten the survival of humanity. The creatures leave colossal destruction in their wake, as they make their way toward their final battleground: San Francisco.', '2014-05-14', 6.37, 'https://image.tmdb.org/t/p/w500/z0CpCYiaUikJrcftPnb0jYCYmoo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (138832, 'We''re the Millers', 'A veteran pot dealer creates a fake family as part of his plan to move a huge shipment of weed into the U.S. from Mexico.', '2013-08-07', 6.80, 'https://image.tmdb.org/t/p/w500/qF2LJ0jwWrtXSuT4AFD5OS2IqaT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (138843, 'The Conjuring', 'Paranormal investigators Ed and Lorraine Warren work to help a family terrorized by a dark presence in their farmhouse. Forced to confront a powerful entity, the Warrens find themselves caught in the most terrifying case of their lives.', '2013-07-18', 7.54, 'https://image.tmdb.org/t/p/w500/wVYREutTvI2tmxr6ujrHT704wGF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (132344, 'Before Midnight', 'It has been nine years since we last met Jesse and Celine, the French-American couple who once met on a train in Vienna. They now live in Paris with twin daughters but have spent a summer in Greece at the invitation of an author colleague of Jesse''s. When the vacation is over and Jesse must send his teenage son off to the States, he begins to question his life decisions, and his relationship with Celine is at risk.', '2013-04-05', 7.49, 'https://image.tmdb.org/t/p/w500/qbGKJmNUroDz75kh5Oafoall89e.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (133694, 'Promised Land', 'A salesman for a natural gas company experiences life-changing events after arriving in a small town, where his corporation wants to tap into the available resources.', '2012-09-23', 6.29, 'https://image.tmdb.org/t/p/w500/5C0b6Wu4Z0V4NuA1cD8SZU7FCkb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (132363, 'The Butler', 'Cecil Gaines was a sharecropper''s son who grew up in the 1920s as a domestic servant for the white family who casually destroyed his. Eventually striking out on his own, Cecil becomes a hotel valet of such efficiency and discreteness in the 1950s that he becomes a butler in the White House itself. There, Cecil would serve numerous US Presidents over the decades as a passive witness of history with the American Civil Rights Movement gaining momentum even as his family has troubles of its own. As his wife, Gloria, struggles with alcoholism and his defiant eldest son, Louis, strives for a just world, Cecil must decide whether he should take action in his own way.', '2013-08-16', 7.32, 'https://image.tmdb.org/t/p/w500/pAi8Bl3ZKX6pANPVhNwbhbQANop.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (140420, 'Paperman', 'An urban office worker finds that paper airplanes are instrumental in meeting a girl in ways he never expected.', '2012-11-02', 7.98, 'https://image.tmdb.org/t/p/w500/9tvF744hwTm2Bn9hkDjMfEsysKz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (140554, 'Fraktus', 'German mockumentary about the history of the techno band of the same name. Fraktus were once considered the pioneers of techno. Now, after 25 years, they are planning their big comeback. The band is supported by their manager Roger Dettner, who used a trick to get the band back together.', '2012-11-06', 6.80, 'https://image.tmdb.org/t/p/w500/2pThyBOA43DS9YUxHDDUcWiF7EU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (137312, 'Red Flag', 'Writer/director/star Alex Karpovsky, a familiar face to indie filmgoers, reveals his sterling comic chops in this close-to-the-bone comedy. Teasing the line between fiction and reality, he plays an indie filmmaker named Alex Karpovsky who, dumped by a longtime girlfriend fed up with his refusal to marry, takes to the road with a reluctant old pal for a misbegotten mini tour screening his movie on college campuses and independent cinemas.', '2013-02-22', 4.40, 'https://image.tmdb.org/t/p/w500/rVuLdqIO2AWzciwFEv4mEjsfObG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (128756, 'Porky in Wackyland', 'Porky Pig travels to a surreal land in order to hunt and catch the elusive Do-Do bird, reportedly the last of its kind.', '1938-09-24', 6.98, 'https://image.tmdb.org/t/p/w500/uq1BO4DmBMTM1PPULLoy4yIpsD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
