INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (129139, 'The To Do List', 'Feeling pressured to become more sexually experienced before she goes to college, Brandy Klark makes a list of things to accomplish before hitting campus in the fall.', '2013-07-24', 5.76, 'https://image.tmdb.org/t/p/w500/vSVYCcvDJljrESZo1jJyXPVvwfk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (137968, 'Drift', 'In the 70s two brothers battle killer waves, conservative society and ruthless bikers to kick-start the modern surf industry.', '2013-05-02', 5.81, 'https://image.tmdb.org/t/p/w500/wAQsxWn82CXsFxrItzzSfYJdSd3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (141819, 'Unforgiven', 'An old swordsman, his former comrade and a young braggart are hired by prostitutes to track down bandits who mutilated one of the women.', '2013-09-13', 6.98, 'https://image.tmdb.org/t/p/w500/a2ycBMY051QCYoNp5YLDYLpOdS8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (142061, 'Batman: The Dark Knight Returns, Part 2', 'Batman has stopped the reign of terror that The Mutants had cast upon his city.  Now an old foe wants a reunion and the government wants The Man of Steel to put a stop to Batman.', '2013-01-03', 7.92, 'https://image.tmdb.org/t/p/w500/d1TqoVkyL4x0dlu9w3F9Ah4LjNv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (142132, 'Sugar Town', 'A look at the lives of  several struggling L.A. musicians. Gwen, a singer-songwriter, is on a quest for the big-time. Working as an assistant to a film production designer, Gwen tries to steal her boss'' boyfriend, a veteran rock producer. The producer, meanwhile, is trying to orchestrate a comeback for an ''80s band.', '1999-09-17', 4.60, 'https://image.tmdb.org/t/p/w500/9VpZ9apNn5uym9TYEtYEhMYOTEX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (143634, 'The Electric Hotel', 'An enthusiastic young couple is astounded with modern technology''s giant leaps in the fascinating field of electricity.', '1908-11-14', 6.17, 'https://image.tmdb.org/t/p/w500/bDFG4dCpIkyBFU3oKuuA8tiSPcR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (124837, 'A Perfect Candidate', 'The filmmakers follow Oliver North''s unsuccessful 1994 bid for a Virginia Senate seat, focusing on North''s campaign strategist, Mark Goodin, and a Washington Post reporter. Mudslinging ensues.', '1996-06-19', 6.10, 'https://image.tmdb.org/t/p/w500/91XMadgfU6scOPYsDW8v4VJuJF3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (133805, 'Carrie', 'An awkward, telekinetic teenage girl is the object of relentless bullying at school and an oppressively religious mother at home.', '2013-10-16', 6.06, 'https://image.tmdb.org/t/p/w500/kloXz9qwO23z9Kbt3z3MgnjF4xO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (144953, 'Where''s Marlowe?', 'After making a disastrous 3-hour documentary on New York City''s water supply, two young filmmakers focus on the goings-on of life in the LA offices of Boone and Murphy, private investigators. Cheating husbands and missing dogs fail to bring in the big bucks, however, and after sleeping with the wife of one of their clients, Murphy leaves. To stop Boone from having to close down the business, the filmmakers must resort to a more hands-on approach in the investigations to ensure the completion of their movie.', '1998-10-01', 5.46, 'https://image.tmdb.org/t/p/w500/lBYQEQidyOkL5VI59FRHVmoMC4z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (145135, 'Dark Skies', 'From the producers of Paranormal Activity, Insidious, and Sinister comes Dark Skies: a supernatural thriller that follows a young family living in the suburbs. As husband and wife Daniel and Lacey Barret witness an escalating series of disturbing events involving their family, their safe and peaceful home quickly unravels. When it becomes clear that the Barret family is being targeted by an unimaginably terrifying and deadly force, Daniel and Lacey take matters in their own hands to solve the mystery of what is after their family.', '2013-02-21', 6.37, 'https://image.tmdb.org/t/p/w500/euLgEo2kvuLjYxbfOekWF3l82t6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (144340, 'Admission', 'Straitlaced Princeton University admissions officer Portia Nathan is caught off-guard when she makes a recruiting visit to an alternative high school overseen by her former classmate, the freewheeling John Pressman. Pressman has surmised that Jeremiah, his gifted yet very unconventional student, might well be the son that Portia secretly gave up for adoption many years ago.', '2013-03-21', 5.60, 'https://image.tmdb.org/t/p/w500/f3HoCikJxypRtLJptBwvs7L7etE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
