INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (141489, 'Hamlet', 'A stage production of Hamlet filmed at the Lunt-Fontanne Theatre in New York. It was deliberately staged in the style of a "dress rehearsal", but performed in front of a live audience.', '1964-09-23', 6.90, 'https://image.tmdb.org/t/p/w500/bPH2UXKNwfr8lIjUDTMuaa0Dsjq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (147129, 'Maria Bamford: The Special Special Special!', 'Welcome to the special special special comedy special.  It''s very good.  I love comedy. And who do I want to make laugh more than Marilyn and Joel Bamford, my parents?  So, we''ve cut out the middle man of 200 strangers in a tv studio and gone right to the source.  With some paid audiences, the feigned enthusiasm can be a little uncomfortable to watch, but I genuinely rock the house.  My parents only wish they could be there with you when you watch this with your parents.', '2012-11-28', 6.15, 'https://image.tmdb.org/t/p/w500/x3oMuJQdkOMVzkS6FoJd6BDa1G7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (147773, 'The Way Way Back', 'Shy 14-year-old Duncan goes on summer vacation with his mother, her overbearing boyfriend, and her boyfriend''s daughter. Having a rough time fitting in, Duncan finds an unexpected friend in Owen, manager of the Water Wizz water park.', '2013-06-06', 7.13, 'https://image.tmdb.org/t/p/w500/4DgA0EDDVv37C8xISc3Vv0rhxlL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (138103, 'The Expendables 3', 'Barney, Christmas and the rest of the team comes face-to-face with Conrad Stonebanks, who years ago co-founded The Expendables with Barney. Stonebanks subsequently became a ruthless arms trader and someone who Barney was forced to kill… or so he thought. Stonebanks, who eluded death once before, now is making it his mission to end The Expendables -- but Barney has other plans. Barney decides that he has to fight old blood with new blood, and brings in a new era of Expendables team members, recruiting individuals who are younger, faster and more tech-savvy. The latest mission becomes a clash of classic old-school style versus high-tech expertise in the Expendables’ most personal battle yet.', '2014-08-07', 6.20, 'https://image.tmdb.org/t/p/w500/utS5euWHlEdKBNnEFwjpZ2oGuhF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (148184, 'Who Killed Chea Vichea?', 'WHO KILLED CHEA VICHEA? is a highly charged murder mystery, a political thriller, and a documentary like no other.  In 2004, Cambodian union president Chea Vichea was assassinated in broad daylight at a newsstand in Phnom Penh. As international pressure mounted, two men were swiftly arrested and convicted of the crime, each sentenced to twenty years in prison. Filmmaker Bradley Cox’s five-year investigation reveals an elaborate cover-up that reaches the highest echelons of Cambodian society.  Winner of a 2011 Peabody Award among many other honors and banned by the Cambodian government, WHO KILLED CHEA VICHEA? uncovers the face of dictatorship behind the mask of democracy.', '2010-01-01', 0.00, NULL) ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (148435, 'Pekka ja Pätkä Suezilla', 'Pekka Puupää and Pätkä involuntarily end up in Suez as peacekeepers. After saving the Caliph''s daughter Suleiman from kidnappers on two occasions, the Caliph magically reunites the friends with Justiina.', '1958-04-25', 5.70, 'https://image.tmdb.org/t/p/w500/Aoq5Wf508TcfoTtK6T2qoMDJMJx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (133919, 'Scenes from a Marriage', 'Johan and Marianne are married and seem to have it all. Their happiness, however, is a façade for a troubled relationship, which becomes even rockier when Johan admits that he''s having an affair. Before long, the spouses separate and move towards finalizing their divorce, but they make attempts at reconciling. Even as they pursue other relationships, Johan and Marianne realize that they have a significant bond, but also many issues that hinder that connection.', '1974-09-15', 8.04, 'https://image.tmdb.org/t/p/w500/ArKEdvJesIktFX8OAhcdKAOLl6I.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
