INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (152601, 'Her', 'In the not so distant future, Theodore, a lonely writer, purchases a newly developed operating system designed to meet the user''s every need. To Theodore''s surprise, a romantic relationship develops between him and his operating system. This unconventional love story blends science fiction and romance in a sweet tale that explores the nature of love and the ways that technology isolates and connects us all.', '2013-12-18', 7.84, 'https://image.tmdb.org/t/p/w500/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
