INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (152760, 'The Monuments Men', 'Based on the true story of the greatest treasure hunt in history, The Monuments Men is an action drama focusing on seven over-the-hill, out-of-shape museum directors, artists, architects, curators, and art historians who went to the front lines of WWII to rescue the world’s artistic masterpieces from Nazi thieves and return them to their rightful owners.  With the art hidden behind enemy lines, how could these guys hope to succeed?', '2014-01-24', 6.06, 'https://image.tmdb.org/t/p/w500/wiWAg4mKV2S4vImPxsPRIdj2R2B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
