INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (157360, 'In a World...', 'An underachieving vocal coach is motivated by her father, the king of movie-trailer voice-overs, to pursue her aspirations of becoming a voice-over star. Amidst pride, sexism and family dysfunction, she sets out to change the voice of a generation.', '2013-08-09', 6.30, 'https://image.tmdb.org/t/p/w500/xbuiPYXOk1aHaNf7o2mAQxeDs7s.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
