INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (157851, 'Maps to the Stars', 'Driven by an intense need for fame and validation, members of a dysfunctional Hollywood family chase celebrity, one another, and the relentless ghosts of their pasts. Their fragile ecosystem is disrupted by the arrival of Agatha, the scarred and estranged pyromaniac daughter.', '2014-05-21', 6.17, 'https://image.tmdb.org/t/p/w500/aoMNfiaMmT7o7wY8oXWCLErZtah.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
