INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (157375, 'The Lifeguard', 'Leigh, feeling unfulfilled, quits her reporter job in New York and returns to the place she last felt happy: her childhood home in Connecticut. She takes a job as a lifeguard, regresses into adolescent behavior, and begins a dangerous relationship with a troubled teenager, leading to consequences for everyone involved.', '2013-08-30', 5.44, 'https://image.tmdb.org/t/p/w500/ecArdkI6uDNBZ59482pv7lDqVzY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (146837, 'Jim Jefferies: Fully Functional', 'There''s something magical about an Australian accent that seems to make even the most caustic wit come off with good-natured charm. And that delicate blend of deviant behavior and good intentions has skyrocketed Aussie comic Jim Jefferies to international acclaim with critics and fans alike. In this new hour-long special, the man hailed by Q Magazine as "Britain''s most offensive stand-up comedian" shares fresh tales from his life on the edge, including a menage a trois in Montreal and attending a party where God is on the guest list.', '2012-10-30', 7.71, 'https://image.tmdb.org/t/p/w500/ospzpJrBaCorNQlZC6VFBqwwUjk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
