INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (160085, 'Break Up Man', 'BREAK UP MAN is an odd couple road movie and tells the story of Henri, who works for a break up agency in Berlin and on behalf of those who want to separate themselves from their future “ex”-partners. To complete his most important mission he is confronted with an unwanted partner, Toto, who spoils more or less everything and makes Henri’s life a nightmare.', '2013-01-10', 5.88, 'https://image.tmdb.org/t/p/w500/3b9tQFCfnCGFcM7kRKWJAZcw2qA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
