INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (161080, 'Secret Society', 'Daisy is the love of Ken''s life - she is also large... and very pretty... and on the dole. But Ken is a dreamer, all his dreams to make a fast buck ending up where they started - as dreams. With the rent unpaid, the bailiffs at the door and Ken''s dreams in tatters, Daisy sets out to bring home the bacon and gets a job in the local factory. There she meets Marlene and half a dozen other large women who are all united in a secret passion - Sumo wrestling! Ken doesn''t know what''s hit him.', '2000-10-29', 4.75, 'https://image.tmdb.org/t/p/w500/sZ4HeEoyOkzmv6848exsbDfsNVJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
