INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (168530, 'Ride Along', 'For the past two years, high-school security guard Ben has been trying to show decorated APD detective James that he''s more than just a video-game junkie who''s unworthy of James'' sister, Angela. When Ben finally gets accepted into the academy, he thinks he''s earned the seasoned policeman''s respect and asks for his blessing to marry Angela. Knowing that a ride along will demonstrate if Ben has what it takes to take care of his sister, James invites him on a shift designed to scare the hell out of the trainee. But when the wild night leads them to the most notorious criminal in the city, James will find that his new partner''s rapid-fire mouth is just as dangerous as the bullets speeding at it.', '2014-01-07', 6.25, 'https://image.tmdb.org/t/p/w500/qrt65VVaP5DEEBZgB5XYctA82Qv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
