INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (147729, 'Animals Are Beautiful People', 'Animals Are Beautiful People (also called Beautiful People) is a 1974 South African nature documentary written, produced, directed, filmed and edited by Jamie Uys, about the wildlife in Southern Africa, presented with comedic elements. It was filmed in the Namib Desert, the Kalahari Desert and at the Okavango River and Okavango Delta. It was the recipient of the 1974 Golden Globe Award for Best Documentary Film. The film, a critical and commercial success, was independently made by Uys, also known for his later African comedy The Gods Must Be Crazy (1980).', '1974-01-31', 7.50, 'https://image.tmdb.org/t/p/w500/bhEihEf39CRycWUK6l49hhRO35Y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
