INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (159117, 'V/H/S/2', 'Inside a darkened house looms a column of TVs littered with VHS tapes, a pagan shrine to forgotten analog gods. The screens crackle and pop endlessly with monochrome vistas of static white noise permeating the brain and fogging concentration. But you must fight the urge to relax: this is no mere movie night. Those obsolete spools contain more than just magnetic tape. They are imprinted with the very soul of evil.', '2013-06-06', 6.20, 'https://image.tmdb.org/t/p/w500/o4hcWsHaHaNQ9BBReOxLvYJNRhA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
