INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (170261, 'The Legend of Sleepy Hollow', 'A TV adaptation of Washington Irving''s classic ghost story. Humor is the drawing card in this version, with Jeff Goldblum a nerdish Ichabod Crane, Dick Butkus an appropriately nasty Brom Bones, and Meg Foster as spirited Katrina van Tassel. Angered that Katrina has grown fond of schoolmaster Crane, Brom Bones determines to scare off the interloper by filling his head with spooky tales of a Headless Horseman. Crane pooh-poohs the legends, until one fateful ride home in the dark of night.', '1980-10-31', 6.84, 'https://image.tmdb.org/t/p/w500/zmXqrb2dalZieCdbof5qY6KQKuC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
