INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (191874, 'Stranger in the House', 'A botched diamond burglary and a dead publishing company executive set off a string of murders and betrayal.', '1997-01-01', 6.80, 'https://image.tmdb.org/t/p/w500/iWD7fxQZpBw1AVfk0AOyqou1x26.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (173495, 'UnHung Hero', 'When Patrick Moote''s girlfriend rejects his marriage proposal at a UCLA basketball game on the jumbotron, it unfortunately goes viral and hits TV networks worldwide. Days after the heartbreaking debacle, she privately reveals why she can’t be with him forever: Patrick’s small penis size. "Unhung Hero" follows the real life journey of Patrick as he boldly sets out to expose this extremely personal chapter of his life confronting ex-girlfriends, doctors, anthropologists and even adult film stars. From Witch-Doctors in Papua New Guinea to sex museums in Korea, Patrick has a lot of turf to cover on his globe trotting adventure to finally answer the age old question: Does size matter?', '2013-12-06', 5.21, 'https://image.tmdb.org/t/p/w500/et7jpooiP4K7eawUhmbYJmRyI7J.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (192102, '3 Days to Kill', 'A dangerous international spy is determined to give up his high stakes life to finally build a closer relationship with his estranged wife and daughter. But first, he must complete one last mission - even if it means juggling the two toughest assignments yet: hunting down the world''s most ruthless terrorist and looking after his teenage daughter for the first time in ten years, while his wife is out of town.', '2014-02-14', 6.10, 'https://image.tmdb.org/t/p/w500/paDgMlfQIrK6PCG5g7UYv9YOdmK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (184098, 'Think Like a Man Too', 'All the couples are back for a wedding in Las Vegas, but plans for a romantic weekend go awry when their various misadventures get them into some compromising situations that threaten to derail the big event.', '2014-06-20', 6.40, 'https://image.tmdb.org/t/p/w500/yKI9Nof9MH3dNHM469hEfCjCbjJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (192133, 'Jimi: All Is by My Side', 'A drama based on Jimi Hendrix''s life as he left New York City for London, where his career took off.', '2013-09-07', 5.59, 'https://image.tmdb.org/t/p/w500/dsNU5nwOy30WfTet32cLiOsFkkN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (192126, 'Revenge for Jolly!', 'Harry is having a very, very bad day. He returns home from an all-night drinking binge with his cousin Cecil, to discover that his little dog Jolly...Harry''s one true love and the source of light in his dark, solitary life-has been murdered. Brokenhearted and beyond consolation, he vows to track down the dog''s murderer at any cost. Armed with a stockpile of firepower in the trunk of his car, he and Cecil embark on a frenzied, alcohol-fueled wild-goose chase, leaving a bloody path of destruction in their wake.', '2012-07-17', 4.58, 'https://image.tmdb.org/t/p/w500/3LDh44NHhTa27TfO0ntWiilogKo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (192136, 'Mandela: Long Walk to Freedom', 'A chronicle of Nelson Mandela''s life journey from his childhood in a rural village through to his inauguration as the first democratically elected president of South Africa.', '2013-11-28', 6.86, 'https://image.tmdb.org/t/p/w500/nzjwDSwLbalv7bCXnFbkAuIxXLx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (192623, 'White Frog', 'When Nick, who has Asperger''s syndrome, struggles to carry on after the death of his brother Chaz, Chaz''s best friend Randy takes Nick under his wing.', '2013-05-10', 5.85, 'https://image.tmdb.org/t/p/w500/9T3BQSIuw7OkvWndcr306tC2ybR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (185567, 'Zulu', 'As a child, Ali Neuman narrowly escaped being murdered by Inkhata, a militant political party at war with Nelson Mandela''s African National Congress. Only he and his mother survived the carnage of those years. But as with many survivors, the psychological scars remain.', '2013-12-04', 6.68, 'https://image.tmdb.org/t/p/w500/h5OZD7pVkIKR5jf4lGFzQQrLmLc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (192712, 'Kite', 'When Sawa''s mother and policeman father are found victims of a grisly double homicide, she begins a ruthless pursuit for the man who murdered them. With the help of her father''s ex-partner, Karl Aker, and a mysterious friend from her past, she becomes a merciless teen assassin, blasting her way through the dark world of human trafficking only to uncover a devastating truth', '2014-06-13', 4.33, 'https://image.tmdb.org/t/p/w500/twNC3WumNZvTk5TGvLY8okhXDaB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (193756, 'Lone Survivor', 'Four Navy SEALs on a covert mission to neutralize a high-level Taliban operative must make an impossible moral decision in the mountains of Afghanistan that leads them into an enemy ambush. As they confront unthinkable odds, the SEALs must find reserves of strength and resilience to fight to the finish.', '2013-12-24', 7.43, 'https://image.tmdb.org/t/p/w500/zaBIrloyhGK7iNTZMb3f9SARsl8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
