INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (193216, 'Adventure of an Ant', 'A 1983 short film directed by Eduard Nazarov about an ant who gets blown away with the wind from its home and the adventures it goes through in desperately trying to find its way back.', '1983-01-01', 7.10, 'https://image.tmdb.org/t/p/w500/5zcjEIb72gkLp3K9PoW5i0LAXYe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (193893, 'Let''s Be Cops', 'Best pals Ryan and Justin are stalled in their respective careers -- a fact that is painfully driven home when they go to a college reunion. Dressed as police in the mistaken belief that they were to attend a costume party, Ryan and Justin find that the uniforms earn them much respect and attention. Although Justin is uncomfortable with the idea, Ryan decides to continue with the charade, putting them both in increasingly dangerous situations. When these newly-minted “heroes” get tangled in a real life web of mobsters and dirty detectives, they must put their fake badges on the line.', '2014-08-13', 6.47, 'https://image.tmdb.org/t/p/w500/pf4FoUr2phn5WyZjU7rLXSiW1Ve.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
