INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (194310, 'Iron Man', 'Prizefighter Mason loses his opening fight so wife Rose leaves him for Hollywood. Without her around Mason trains and starts winning. Rose comes back and wants Mason to dump his manager Regan and replace him with her secret lover Lewis.', '1931-04-29', 5.70, 'https://image.tmdb.org/t/p/w500/l66ZkItJmi4er0I0mGe4mksjfB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
