INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (194662, 'Birdman or (The Unexpected Virtue of Ignorance)', 'A fading actor best known for his portrayal of a popular superhero attempts to mount a comeback by appearing in a Broadway play. As opening night approaches, his attempts to become more altruistic, rebuild his career, and reconnect with friends and family prove more difficult than expected.', '2014-10-17', 7.43, 'https://image.tmdb.org/t/p/w500/rHUg2AuIuLSIYMYFgavVwqt1jtc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
