INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (174321, 'The English Teacher', 'Small-town Pennsylvania schoolteacher Linda Sinclair balances her staid home life with an incredible passion for her subject. Then a former star pupil reenters her life after failing as a playwright in New York City. Seeing in his script the inspiration that she has always longed to instill in her students, this dyed-in-the-wool romantic enlists the help of long-suffering drama teacher Carl to mount the work as the high school’s next and riskiest production.', '2013-05-16', 5.60, 'https://image.tmdb.org/t/p/w500/mF14chZNzgDRZffs8Wk8lPwdNQA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (185574, 'Louis C.K.: Oh My God', 'Filmed at the Celebrity Theatre in Phoenix, AZ on February 15th and 16th, 2013, Oh My God is Louis C.K.''s fifth stand-up special, his first for HBO since 2007''s Shameless, and his first since winning a Emmy Award for writing on his acclaimed show on FX, Louie.  Performed in the round in front of a live audience, he discusses such topics as the food chain, animals, divorce, strange anecdotes, broken morality, murder and mortality.', '2013-04-13', 7.60, 'https://image.tmdb.org/t/p/w500/uMiRDSnFRpKicYbikKa8aO1QKbU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
