INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (186759, 'Get a Job', 'Life after college graduation is not exactly going as planned for Will and Jillian who find themselves lost in a sea of increasingly strange jobs. But with help from their family, friends and coworkers they soon discover that the most important (and hilarious) adventures are the ones that we don''t see coming.', '2016-03-17', 5.30, 'https://image.tmdb.org/t/p/w500/eElBXTTBBy9xgnJh6rMQcXm17En.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (174598, 'Snow White', 'Snow White, a beautiful girl, is despised by a wicked queen who tries to destroy her. With the aid of dwarfs in the woods, Snow White overcomes the queen.', '1916-12-24', 5.85, 'https://image.tmdb.org/t/p/w500/lejbiFj0Vg5bGWZSLWvvj8zSdK4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (174323, 'G.B.F.', 'The bitter fight for supremacy between the three most popular girls at North Gateway High takes an unexpected turn when their classmate, Tanner, is outed and becomes the school’s first openly gay student. The trio races to bag the big trend in fashion accessories, the Gay Best Friend, while Tanner must decide whether his skyrocketing popularity is more important than the friendships he is leaving behind.', '2014-01-17', 5.95, 'https://image.tmdb.org/t/p/w500/f4fR1WMgSv7K93ZPoJlPyvaApdE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
