INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (194722, 'At Middleton', 'George is an uptight surgeon with a rebellious teenage son. Edith is a free spirit with an overachieving teenage daughter. When they meet during an admissions tour with their kids at the small, idyllic Middleton University, they decide to ditch the group. Though adversaries at first, they soon discover that the only thing better than the college tour, is the detour.', '2013-10-09', 6.27, 'https://image.tmdb.org/t/p/w500/6hhXewoxobQ0C6sWFmvnsslvZOB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (195862, 'O Amor Natural', 'O AMOR NATURAL is a documentary film about the erotic poetry of one of the greatest Latin American poets of the 20th century, the Brazilian Carlos Drummond de Andrade (1902-1987).  The erotic poems of Carlos Drummond de Andrade, a household name in Brazil, remained unpublished during his lifetime, as he feared they would be deemed pornographic. In this celebration of his poetry and sensual vision, elderly residents of Rio read his poems and comment on their graphic, voluptuous imagery with tremendous candor and enthusiasm.', '1996-12-05', 7.30, 'https://image.tmdb.org/t/p/w500/wy0V2Ddac3vkVXxrLMIXVPA6qhs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (174337, 'The Pretty One', 'When her idolized twin sister Audrey dies in a car accident, Laurel decides to take her place. But, as she eases into the life she has always wanted, she must decide between continuing the lie or revealing herself.', '2014-02-07', 6.11, 'https://image.tmdb.org/t/p/w500/rIYgspS4xulnonEUG2Xh3VXfDt0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
