INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (204810, 'Hunting Elephants', 'In this hilarious crime comedy, a gifted 12-year-old boy and three elderly men plan a bank robbery in order to seek revenge on the institution for cheating the youngster after the death of his father.', '2013-07-03', 5.90, 'https://image.tmdb.org/t/p/w500/su3Jt6PTVjyfbE8f2FVSHxVWksM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (205220, 'Philomena', 'A woman searches for her adult son, who was taken away from her decades ago when she was forced to live in a convent.', '2013-11-01', 7.34, 'https://image.tmdb.org/t/p/w500/eBUv2GmGdXmCk1AaSOmyiu70hN8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (205321, 'Sharknado', 'A freak hurricane hits Los Angeles, causing man-eating sharks to be scooped up in tornadoes and flooding the city with shark-infested seawater. Surfer and bar-owner Fin sets out with his friends Baz and Nova to rescue his estranged wife April and teenage daughter Claudia.', '2013-07-11', 3.92, 'https://image.tmdb.org/t/p/w500/atEmHkVFTSGRYt2PeCiziQqbZnI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
