INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (205596, 'The Imitation Game', 'Based on the real life story of legendary cryptanalyst Alan Turing, the film portrays the nail-biting race against time by Turing and his brilliant team of code-breakers at Britain''s top-secret Government Code and Cypher School at Bletchley Park, during the darkest days of World War II.', '2014-11-14', 7.98, 'https://image.tmdb.org/t/p/w500/zSqJ1qFq8NXFfi7JeIYMlzyR0dx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (205775, 'In the Heart of the Sea', 'In the winter of 1820, the New England whaling ship Essex is assaulted by something no one could believe—a whale of mammoth size and will, and an almost human sense of vengeance.', '2015-12-03', 6.79, 'https://image.tmdb.org/t/p/w500/weVvNPfk6FM9vBg3BXtRtNAmiYM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (206296, 'The Last Five Years', 'In New York, a struggling actress and a successful writer sing about their failed marriage from two perspectives.', '2014-11-03', 5.90, 'https://image.tmdb.org/t/p/w500/dxTLKSTyGb5IXB64iNgU9AWAsXT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (206408, 'Chinese Puzzle', 'Xavier is a 40-year-old father of two who still finds life very complicated. When the mother of his children moves to New York, he can''t bear them growing up far away from him and so he decides to move there as well.', '2013-12-04', 6.58, 'https://image.tmdb.org/t/p/w500/urOhy4mkGTcRHjXBotanF6zyBJw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (206487, 'Predestination', 'Predestination chronicles the life of a Temporal Agent sent on an intricate series of time-travel journeys designed to prevent future killers from committing their crimes. Now, on his final assignment, the Agent must stop the one criminal that has eluded him throughout time and prevent a devastating attack in which thousands of lives will be lost.', '2014-08-28', 7.42, 'https://image.tmdb.org/t/p/w500/38Xr1JnV1ZcLQ55zmdSp6n475cZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (206647, 'Spectre', 'A cryptic message from Bond’s past sends him on a trail to uncover a sinister organization. While M battles political forces to keep the secret service alive, Bond peels back the layers of deceit to reveal the terrible truth behind SPECTRE.', '2015-10-26', 6.57, 'https://image.tmdb.org/t/p/w500/zj8ongFhtWNsVlfjOGo8pSr7PQg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (207932, 'Inferno', 'After waking up in a hospital with amnesia, professor Robert Langdon and a doctor must race against time to foil a deadly global plot.', '2016-10-13', 6.10, 'https://image.tmdb.org/t/p/w500/smaWxdIMH24gD96lKNe1a036LVG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (206821, 'The Longest Week', 'Left broke and homeless by his wealthy parents'' divorce, a young man moves in with an old friend and finally meets the woman of his dreams -- only to discover she''s already dating his friend.', '2014-09-05', 5.14, 'https://image.tmdb.org/t/p/w500/nXWsjQefKVsJdQQsu5NZT1Zk1rv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
