INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (188222, 'Entourage', 'Movie star Vincent Chase, together with his boys, Eric, Turtle and Johnny, are back…and back in business with super agent-turned-studio head Ari Gold. Some of their ambitions have changed, but the bond between them remains strong as they navigate the capricious and often cutthroat world of Hollywood.', '2015-06-03', 6.24, 'https://image.tmdb.org/t/p/w500/28dqsx1jCxhR05DfH35ui13ywNZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (197467, 'Captain America', 'Artist Steve Rogers is nearly murdered by spies, seeking his late father''s national secrets. He is saved during surgery via a secret formula; this serum not only heals him but also gives him fantastic strength and lightning reflexes.  To help solve the mystery behind his father’s murder and bring those guilty to justice, a government agency equips him with a special motorcycle loaded with gadgets and an indestructible shield. Now armed, he battles against the nation''s enemies as the Sentinel of Liberty, Captain America.', '1979-01-19', 3.94, 'https://image.tmdb.org/t/p/w500/gNGq4u0cymxZqGADZrx7AWrSB5m.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (197481, 'Captain America II: Death Too Soon', 'Crimefighting Captain America rights more wrongs by doing battle with a fanatical terrorist who uses his deadly drug that causes accelerated aging to finance his world revolution.', '1979-11-23', 3.80, 'https://image.tmdb.org/t/p/w500/pocmh0P8Ddf5w33pP3Vuqm0JRP9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
