INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (210860, 'Mortdecai', 'An art dealer, Charles Mortdecai, searches for a stolen painting rumored to contain a secret code that gains access to hidden Nazi gold.', '2015-01-21', 5.52, 'https://image.tmdb.org/t/p/w500/zIRDhdAuMevOuY2vs3s1HNcqDq7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (210947, 'Afflicted', 'Two friends'' tour of Europe takes a dark turn when one of them contracts a mysterious illness. They race to find out what it is and how to cure it before the sickness consumes him completely.', '2014-04-04', 6.43, 'https://image.tmdb.org/t/p/w500/iDbdxDHFtBZ8gnGsrinB7atE26P.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (210937, 'Pursuit of Happiness', 'An advertising executive fails to realize that the woman of his dreams is his best friend since first grade, now married to his cheating co-worker.', '2001-01-17', 5.40, 'https://image.tmdb.org/t/p/w500/9JT1wMRI3SToncVwhSLg4negF0V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (211005, 'Sex, Drugs & Taxation', 'Maybe the best thing to come out of Scandinavia during the hippie years was, in fact, the story of a radical libertarian and a hedonist capitalist. Their friendship, forged by being outsiders in a conformist country, took them through years of adulation and success, with slight detours into the welcoming arms of vilification and imprisonment. A joyride through taxation, mass travel, hookers and politics. Not feeling too constrained by historical facts, director Christoffer Boe''s story of Simon Spies and Mogens Glistrup covers just a few of their decades in a tale of warmth and humour, defiance and eccentricity.', '2013-08-29', 6.11, 'https://image.tmdb.org/t/p/w500/f1aHVJQKflibJQhjCN8jZCobLyW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (211067, 'The Sacrament', 'Two journalists set out to document their friend''s journey to reunite with his estranged sister. They track her to an undisclosed location where they are welcomed into the remote world of "Eden Parish," a self-sustained rural utopia composed of nearly two hundred members and overseen by a mysterious leader known only as "Father." It quickly becomes evident to the newcomers that this paradise may not be as it seems. Eden Parish harbors a twisted secret. What started as just another documentary shoot soon becomes a fight for survival.', '2014-05-01', 5.96, 'https://image.tmdb.org/t/p/w500/thdioQOYqqusDUfT6trgwMIoNaQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (211387, 'Marvel One-Shot: Agent Carter', 'Agent Peggy Carter is relegated to a desk job and frustrated at her male boss and comrades'' sexist dismissal of her place in the SSR. Ordered to work late one night, Carter gets an alert that the villain Zodiac has been spotted and decides to take care of it herself.', '2013-10-04', 7.25, 'https://image.tmdb.org/t/p/w500/4vFKKWPvCVDJTOWiwReBfpAMScP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (211672, 'Minions', 'Minions Stuart, Kevin and Bob are recruited by Scarlet Overkill, a super-villain who, alongside her inventor husband Herb, hatches a plot to take over the world.', '2015-06-17', 6.42, 'https://image.tmdb.org/t/p/w500/dr02BdCNAUPVU07aOodwPYv6HCf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (212063, 'Tim''s Vermeer', 'Tim Jenison, a Texas based inventor, attempts to solve one of the greatest mysteries in all art: How did Dutch Master Johannes Vermeer manage to paint so photo-realistically 150 years before the invention of photography? Spanning a decade, Jenison''s adventure takes him to Holland, on a pilgrimage to the North coast of Yorkshire to meet artista David Hockney, and eventually even to Buckingham Palace. The epic research project Jenison embarques on is as extraordinary as what he discovers.', '2013-12-06', 7.25, 'https://image.tmdb.org/t/p/w500/vEF0f8dktdp4NbUbpi0xSzwUAY8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (209232, 'Dampfnudelblues', 'After the forcible transfer to his Bavarian home village, an ex-criminal cop investigates the death of a school principal who he thinks had lots to hide.', '2013-07-31', 6.82, 'https://image.tmdb.org/t/p/w500/mlE9wNxyzGQPJm26Fn8eBr1H1gx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (212716, 'What If', 'Medical-school dropout Wallace has been repeatedly burned by bad relationships. So while everyone around him, including his roommate Allan, seems to be finding the perfect partner, Wallace decides to put his love life on hold. It is then that he meets Chantry, an animator who lives with her longtime boyfriend Ben. Wallace and Chantry form an instant connection, striking up a close friendship. Still, there is no denying the chemistry between them, leading the pair to wonder, what if the love of your life is actually your best friend?', '2013-09-07', 6.74, 'https://image.tmdb.org/t/p/w500/67x9NJyjK4u02NpISnChDMKzCUr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (212168, 'Ghost in the Shell: Arise - Border 2: Ghost Whispers', 'Freed of her responsibilities with the 501 Organization, Motoko Kusanagi must now learn how to take orders from Aramaki. Someone hacks the Logicomas, and Batou enlists the help of former army intelligence officer Ishikawa and former air artillery expert Borma. Kusanagi also seeks to enlist ace sniper Saito and undercover cop Paz into the new Public Security Section 9.', '2013-11-29', 7.01, 'https://image.tmdb.org/t/p/w500/eC8babU050Nwnss5CnAJyymGkB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (198277, 'Begin Again', 'Gretta, a budding songwriter, finds herself alone after her boyfriend Dave ditches her. Her life gains purpose when Dan, a record label executive, notices her talent.', '2014-06-27', 7.23, 'https://image.tmdb.org/t/p/w500/qx4HXHXt528hS4rwePZbZo20xqZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (212778, 'Chef', 'When Chef Carl Casper suddenly quits his job at a prominent Los Angeles restaurant after refusing to compromise his creative integrity for its controlling owner, he is left to figure out what''s next. Finding himself in Miami, he teams up with his ex-wife, his friend and his son to launch a food truck. Taking to the road, Chef Carl goes back to his roots to reignite his passion for the kitchen -- and zest for life and love.', '2014-05-08', 7.11, 'https://image.tmdb.org/t/p/w500/hyp8EXDmO4dSC8V6Q5jU7gD1kcg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (198663, 'The Maze Runner', 'A teenager with no memory of his past finds himself among a group of boys living in a walled enclosure surrounded by a massive, ever-changing maze. As he struggles to adapt to their rules and society, he begins to uncover clues that may lead to escape and the truth behind their confinement.', '2014-09-10', 7.19, 'https://image.tmdb.org/t/p/w500/ode14q7WtDugFDp78fo9lCsmay9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (198185, 'Million Dollar Arm', 'In a last-ditch effort to save his career, sports agent JB Bernstein dreams up a wild game plan to find Major League Baseball’s next great pitcher from a pool of cricket players in India. He soon discovers two young men who can throw a fastball but know nothing about the game of baseball. Or America. It’s an incredible and touching journey that will change them all — especially JB, who learns valuable lessons about teamwork, commitment and family.', '2014-05-09', 6.72, 'https://image.tmdb.org/t/p/w500/6OgA9x6jvwBIj8e7x8LANTbVvR2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (213110, 'The Amazing Screw-On Head', 'Based on the award-winning comic book by Mike Mignola (creator of Hellboy), The Amazing Screw-On Head chronicles the adventures of a Civil War-era secret agent with an extraordinary special power who serves under president Abraham Lincoln.', '2006-08-20', 6.83, 'https://image.tmdb.org/t/p/w500/gTANNf43FKKxN5bEGNGIhBF9Wg2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
