INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (214030, 'Fading Gigolo', 'Fioravante decides to become a professional Don Juan as a way of making money to help his cash-strapped friend, Murray. With Murray acting as his "manager", the duo quickly finds themselves caught up in the crosscurrents of love and money.', '2013-09-07', 5.80, 'https://image.tmdb.org/t/p/w500/bThnmRhh0d3oKcmte2w0aArm8Lq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
