INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (215032, 'Watermark', 'Following their triumph with Manufactured Landscapes, photographer Edward Burtynsky and filmmaker Jennifer Baichwal reunite to explore the ways in which humanity has shaped, manipulated and depleted one of its most vital and compromised resources: water.', '2013-10-11', 6.50, 'https://image.tmdb.org/t/p/w500/ggHgV6OfSAkCZeUbQtMK1sNWq9G.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (217412, 'Quality Time', 'You can’t choose your family – which is why Conrad limits his visits with his parents to an absolute minimum. When venomous, irritable Carl injures himself seriously in a fall, his reluctant son Conrad and the butt-of-all-jokes Jonas has no choice but to move back into his old childhood room. Three generations under one roof: a chance for reconciliation – or a total disaster?', '2013-09-12', 6.30, 'https://image.tmdb.org/t/p/w500/xpzJezYGChp6Wchj5eh1VQ9Dvua.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
