INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (221902, 'Two Days, One Night', 'Sandra is a young woman who has only one weekend to convince her colleagues they must give up their bonuses in order for her to keep her job — not an easy task in this economy.', '2014-05-21', 6.91, 'https://image.tmdb.org/t/p/w500/2qpZZ5a5Axpk8OeCtrvNTQfJiB2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (198375, 'The Garden of Words', 'Takao, who is training to become a shoemaker, skipped school and is sketching shoes in a Japanese-style garden. He meets a mysterious woman, Yukino, who is older than him. Then, without arranging the times, the two start to see each other again and again, but only on rainy days. They deepen their relationship and open up to each other. But the end of the rainy season soon approaches.', '2013-05-31', 7.58, 'https://image.tmdb.org/t/p/w500/mXUCVq3HMtS4Y9IQ8vmEOPyN0vH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (209269, 'Felony', 'Three detectives become embroiled in a tense struggle after a tragic accident that leaves a child in critical condition. One is guilty of a crime, one will try to cover it up, and the other attempts to expose it. How far will these men go to disguise and unravel the truth?', '2014-08-28', 5.70, 'https://image.tmdb.org/t/p/w500/b36OAp2q5m0oZ4oUcwg2B0cTHrV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (213321, 'Investigation Held by Kolobki', 'Two crazy brothers-detectives from a weird provincial town are searching for a rare striped elephant stolen by a suspicious foreigner.', '1986-04-05', 6.94, 'https://image.tmdb.org/t/p/w500/capVKIin7nWwRMWVM2TUOUcTKXo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (216015, 'Fifty Shades of Grey', 'When college senior Anastasia Steele steps in for her sick roommate to interview prominent businessman Christian Grey for their campus paper, little does she realize the path her life will take. Christian, as enigmatic as he is rich and powerful, finds himself strangely drawn to Ana, and she to him. Though sexually inexperienced, Ana plunges headlong into an affair -- and learns that Christian''s true sexual proclivities push the boundaries of pain and pleasure.', '2015-02-11', 5.86, 'https://image.tmdb.org/t/p/w500/63kGofUkt1Mx0SIL4XI4Z5AoSgt.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (207703, 'Kingsman: The Secret Service', 'The story of a super-secret spy organization that recruits an unrefined but promising street kid into the agency''s ultra-competitive training program just as a global threat emerges from a twisted tech genius.', '2015-01-24', 7.62, 'https://image.tmdb.org/t/p/w500/17i5YPTfHOjXoieArpATWGRhLj1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (200727, 'Love, Rosie', 'Since the moment they met at age 5, Rosie and Alex have been best friends, facing the highs and lows of growing up side by side. A fleeting shared moment, one missed opportunity, and the decisions that follow send their lives in completely different directions. As each navigates the complexities of life, love, and everything in between, they always find their way back to each other - but is it just friendship, or something more?', '2014-10-16', 7.81, 'https://image.tmdb.org/t/p/w500/2HOd431LX9ggqSpBIJ7qyYhATyo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (216553, 'Jim Norton: American Degenerate', 'In the follow-up to his first EPIX comedy special Please Be Offended, caustic comedian Jim Norton continues to push every hot button he can find... all in the name of a good laugh, of course. With his trademark self-deprecating brand of humor, Norton outrageously covers a wide range of topics that somehow all lead back to sex.', '2013-08-23', 6.10, 'https://image.tmdb.org/t/p/w500/nwRE4yenVnThmFPtOdy7nJza7sq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (208134, 'Jackass Presents: Bad Grandpa', '86-year-old Irving Zisman is on a journey across America with the most unlikely companion: his 8 year-old grandson, Billy.', '2013-10-22', 6.18, 'https://image.tmdb.org/t/p/w500/dDSMzBEaM0LYSy9Muo0zsCo77Vh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (198469, 'Otello', 'Based on Shakespeare''s play, Verdi''s opera depicts the devastating effects of jealousy, "...the green-eyed monster which doth mock the meat it feeds upon". Believing Otello has promoted the fast-rising Cassio over himself, Iago plots to destroy both Cassio and Otello. Iago convinces the jealous Otello that his beautiful wife Desdemona is unfaithful, and that Cassio is her lover. Jealousy is followed by tragedy, then retribution, "Has Heaven no more thunderbolts?"', '1986-09-04', 6.20, 'https://image.tmdb.org/t/p/w500/emPz3c9jQdH5oJbpSUN7zwXLkin.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (221917, 'The Run of the Country', 'An Irish lad who fled from his oppressive, widowed father falls for a girl from an affluent family.', '1995-09-22', 6.42, 'https://image.tmdb.org/t/p/w500/ArlhiYSVjDeJKSl1qfCNdQH3DMW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (225574, 'Non-Stop', 'Bill Marks is a Federal Air Marshall for whom every day is the same until this one. On this plane ride, he starts receiving text messages from someone claiming to be on the flight and threatening to kill passengers. In a race against the clock, he must identify and stop the killer to save everyone on board.', '2014-02-26', 6.81, 'https://image.tmdb.org/t/p/w500/Nkgaj3X0W2jHQ1TzHEgWFpN3kJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (215875, 'Violets Are Blue', 'After fifteen years of traveling around the world, Gussie, a famous photographer, returns to the Maryland coastal resort where she grew up. She meets her high school sweetheart, Henry, who is now married and running the local newspaper he inherited from his father. An awkward and tension-filled romance ensues.', '1986-04-04', 4.74, 'https://image.tmdb.org/t/p/w500/lszTi2XNnUfXgVg96ILSGxJqfaJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (225728, 'Macbeth', 'Macbeth, the Thane of Glamis, receives a prophecy from a trio of witches that one day he will become King of Scotland. Consumed by ambition and spurred to action by his wife, Macbeth murders his king and takes the throne for himself.', '2015-09-22', 6.43, 'https://image.tmdb.org/t/p/w500/a5NEpil29Uns1wEYF8k99qVgj1T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (209112, 'Batman v Superman: Dawn of Justice', 'Fearing the actions of a god-like Super Hero left unchecked, Gotham City’s own formidable, forceful vigilante takes on Metropolis’s most revered, modern-day savior, while the world wrestles with what sort of hero it really needs. And with Batman and Superman at war with one another, a new threat quickly arises, putting mankind in greater danger than it’s ever known before.', '2016-03-23', 6.01, 'https://image.tmdb.org/t/p/w500/5UsK3grJvtQrtzEgqNlDljJW96w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (225745, 'Steins;Gate: The Movie - Load Region of Déjà Vu', 'One year after the events of the anime, Rintarou begins to feel the repercussions of extensive time travel, and eventually completely fades from reality. Kurisu, being the only companion to remember him, now must find a way to bring him back.', '2013-04-20', 7.57, 'https://image.tmdb.org/t/p/w500/bXhogkZCR0aOQ077rfMULYbDmtH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (225886, 'Sex Tape', 'When Jay and Annie first got together, their romantic connection was intense – but ten years and two kids later, the flame of their love needs a spark.  To kick things up a notch, they decide – why not? – to make a video of themselves trying out every position in The Joy of Sex in one marathon three-hour session.  It seems like a great idea – until they discover that their most private video is no longer private.  With their reputations on the line, they know they’re just one click away from being laid bare to the world... but as their race to reclaim their video leads to a night they''ll never forget, they''ll find that their video will expose even more than they bargained for.', '2014-07-17', 5.40, 'https://image.tmdb.org/t/p/w500/u2h7UnSHrbAA5WBoKhdH1rlDZfz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (226486, 'Tammy', 'For burger-joint employee Tammy, a bad day keeps getting worse. She wrecks her car, loses her job, and finds that her husband has been unfaithful. It''s time to hit the road, but without money or transportation, Tammy''s options are limited. Her only choice is a road trip with her hard-drinking grandmother Pearl, who has a car, cash, and an itch to see Niagara Falls. It''s not the escape Tammy had in mind, but it may be what she needs.', '2014-07-02', 5.34, 'https://image.tmdb.org/t/p/w500/efsVMziwE9BNTDX5fNmYVA5oAzJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
