INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (209451, 'Jersey Boys', 'A musical biopic of the Four Seasons—the rise, the tough times and personal clashes, and the ultimate triumph of a group of friends whose music became symbolic of a generation. Far from a mere tribute concert, it gets to the heart of the relationships at the centre of the group, with a special focus on frontman Frankie Valli, the small kid with the big falsetto.', '2014-06-18', 6.76, 'https://image.tmdb.org/t/p/w500/kz956Y83YtT6vTyg0Q40mzRe2UM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (230779, 'Cesar Chavez', 'A biography of the civil-rights activist and labor organizer Cesar Chavez.  Chronicling the birth of a modern American labour movement, Cesar Chavez tells the story of the famed civil rights leader and labour organiser torn between his duties as a husband and father and his commitment to securing a living wage for farm workers. Passionate but soft-spoken, Chavez embraced non-violence as he battled greed and prejudice in his struggle to bring dignity to working people.', '2014-03-28', 6.22, 'https://image.tmdb.org/t/p/w500/cyEpCV8nLfhloAkwNxel4OjIhAA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
