INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (238215, 'The Cobbler', 'Max Simkin repairs shoes in the same New York shop that has been in his family for generations. Disenchanted with the grind of daily life, Max stumbles upon a magical heirloom that allows him to step into the lives of his customers and see the world in a new way. Sometimes walking in another man''s shoes is the only way one can discover who they really are.', '2014-09-11', 5.87, 'https://image.tmdb.org/t/p/w500/oMgBX4uqF1VIz95tD4iJggz6Ceh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (238302, 'Saving Santa', 'A lowly stable elf finds that he is the only one who can stop an invasion of the North Pole by using the secret of Santa''s Sleigh, a TimeGlobe, to travel back in time to Save Santa - twice.', '2013-11-05', 5.19, 'https://image.tmdb.org/t/p/w500/luIe2Qe7dYmlJ37CvDaLp2sKxc1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (238615, 'Self/less', 'An extremely wealthy elderly man dying from cancer undergoes a radical medical procedure that transfers his consciousness to the body of a healthy young man but everything may not be as good as it seems when he starts to uncover the mystery of the body''s origins and the secret organization that will kill to keep its secrets.', '2015-07-10', 6.42, 'https://image.tmdb.org/t/p/w500/hCqXcAMeBiPVnLUU8PNsKUYi6Gn.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (238628, 'Tangerines', 'War in Abkhazia, 1992. An Estonian man Ivo has stayed behind to harvest his crops of tangerines. In a bloody conflict at his door, a wounded man is left behind, and Ivo is forced to take him in.', '2013-10-17', 7.70, 'https://image.tmdb.org/t/p/w500/jNKUXcwZr1vpgq7sGTCEqdngo4Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (238636, 'The Purge: Anarchy', 'One night per year, the government sanctions a 12-hour period in which citizens can commit any crime they wish -- including murder -- without fear of punishment or imprisonment. Leo, a sergeant who lost his son, plans a vigilante mission of revenge during the mayhem. However, instead of a death-dealing avenger, he becomes the unexpected protector of four innocent strangers who desperately need his help if they are to survive the night.', '2014-07-17', 6.62, 'https://image.tmdb.org/t/p/w500/qwqHHZLZSUvMkAMQ47ymtfjEifY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (238713, 'Spy', 'A desk-bound CIA analyst volunteers to go undercover to infiltrate the world of a deadly arms dealer, and prevent diabolical global disaster.', '2015-05-06', 6.83, 'https://image.tmdb.org/t/p/w500/vPBmfMHxQvRRNGYD5S5ko2KnX56.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (239563, 'St. Vincent', 'A young boy whose parents just divorced finds an unlikely friend and mentor in the misanthropic, bawdy, hedonistic, war veteran who lives next door.', '2014-10-09', 7.14, 'https://image.tmdb.org/t/p/w500/1bb7MTHCIPhpKZFysDpxNaNrdMk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (239566, 'Get On Up', 'A chronicle of James Brown''s rise from extreme poverty to become one of the most influential musicians in history.', '2014-08-01', 6.77, 'https://image.tmdb.org/t/p/w500/dVbGeU5agxFGcJnL5hk4uO8W7i2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (239568, 'Search Party', 'Two oafs must rescue their stranded pal in Mexico.', '2014-10-30', 5.33, 'https://image.tmdb.org/t/p/w500/qnhMdtcbZnzcA9cMuZttwosaXji.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (230896, 'Iron Man & Hulk: Heroes United', 'The Invincible Iron Man and the Incredible Hulk must join forces to save the Earth from its greatest threat yet! When two Hydra scientists try to supercharge a Stark Arc Reactor with Hulk''s Gamma Energy, they unleash a being of pure electricity called Zzzax - and he''s hungry for destruction. Together, Iron Man and Hulk are the only force that stands in the way of the Zzzax''s planetary blackout. But first, the super heroic duo will have to get through snarling Wendigos, deadly robots and the scaly powerhouse, Abomination.  Can two of Marvel''s mightiest heroes find a way to work together without smashing each other before time runs out?', '2013-12-03', 5.94, 'https://image.tmdb.org/t/p/w500/xCBBQMPxXsqIlZUAbpeSo1SVj6R.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (239678, 'This Is Where I Leave You', 'When their father passes away, four grown, world-weary siblings return to their childhood home and are requested -- with an admonition -- to stay there together for a week, along with their free-speaking mother and a collection of spouses, exes and might-have-beens. As the brothers and sisters re-examine their shared history and the status of each tattered relationship among those who know and love them best, they reconnect in hysterically funny and emotionally significant ways.', '2014-09-10', 6.64, 'https://image.tmdb.org/t/p/w500/rVUI2267FdetVWz9UBQbqTmRVhQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (240566, 'Tokyo Tribe', 'In an alternate Japan, territorial street gangs form opposing factions collectively known as the Tokyo Tribes. Merra, leader of the Wu-Ronz tribe of Bukuro, joins forces with heavy-hitting gangster Buppa of Buppa Town. With Buppa''s support, Merra aims to initiate a gang war between the Wu-Ronz and the Musashino Saru, and in a confrontation between the two attempts to kill Kai of the Musashino Saru. The inadvertent murder of Kai''s friend Tera (a Musashino Saru member beloved by all Tribes since before their formation) leads to the joining of forces between all of the Tribes in an all-out war against Merra and Buppa.', '2014-08-30', 6.54, 'https://image.tmdb.org/t/p/w500/cpvQrnZwGvzG0moL4oMdmKMYKDB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (240832, 'Lucy', 'A woman, accidentally caught in a dark deal, turns the tables on her captors and transforms into a merciless warrior evolved beyond human logic.', '2014-07-25', 6.48, 'https://image.tmdb.org/t/p/w500/kRbpUTRNm6QbLQFPFWUcNC4czEm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (239573, 'Unfinished Business', 'A hard-working small business owner and his two associates travel to Europe to close the most important deal of their lives.  But what began as a routine business trip goes off the rails in every imaginable – and unimaginable – way, including unplanned stops at a massive sex fetish event and a global economic summit.', '2015-03-05', 5.44, 'https://image.tmdb.org/t/p/w500/eVWVZf3fkx9eNqbHyn9xNlmC2h4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
