INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (222899, 'About Last Night', 'Bernie and Joan are two fiery flirters who are passionate about everything from hookups to breakups and each other. When he sets up his best friend, Danny, with her roommate, Debbie, the sparks soon fly as they try to navigate the relationship minefields from the bar to the bedroom and are eventually put to the test in the real world.', '2014-02-14', 5.98, 'https://image.tmdb.org/t/p/w500/z3dVYQtxXldDawz7d15wqt2PQLe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
