INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (243531, 'Freezer', 'New York city mechanic Robert Saunders is knocked unconscious at his birthday dinner by Russian thugs and wakes up to find himself locked inside the restaurant''s industrial freezer. This ruthless gang demand he return the $8 million he has stolen from them. The only problem Robert has no idea what they are talking about. But as the temperature drops and the terror grows, the shocking truth begins to emerge as Robert struggles to survive.', '2014-01-17', 5.25, 'https://image.tmdb.org/t/p/w500/kxtp9hqHK22x9DUVsQE58rrpJvz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (243684, 'Men, Women & Children', 'Follows the story of a group of high school teenagers and their parents as they attempt to navigate the many ways the internet has changed their relationships, their communication, their self-image, and their love lives.', '2014-10-17', 6.50, 'https://image.tmdb.org/t/p/w500/dzFHIxCcvq2CZVFCsgz7n1z5oIM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (243938, 'Hot Tub Time Machine 2', 'After their first adventure with the Hot Tub Time Machine, Lou and Nick are living very well off their ill-gotten gains, while Jacob still cannot rely on Lou to be a positive role model. When an unknown assailant breaks into Lou''s mansion and shoots him, Nick and Jacob take him for another trip in the hot tub. They emerge in the year 2025, where they must figure out who shot Lou and prevent it from happening again.', '2015-02-20', 5.18, 'https://image.tmdb.org/t/p/w500/lBroHetSm8RMI8zp7ThpFJsw9E1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (244264, 'Laggies', 'Overeducated and underemployed, 28 year old Megan is in the throes of a quarterlife crisis. Squarely into adulthood with no career prospects, no particular motivation to think about her future and no one to relate to, Megan is comfortable lagging a few steps behind - while her friends check off milestones and celebrate their new grown-up status. When her high-school sweetheart proposes, Megan panics and- given an unexpected opportunity to escape for a week - hides out in the home of her new friend, 16-year old Annika and Annika''s world-weary single dad Craig.', '2014-09-25', 6.12, 'https://image.tmdb.org/t/p/w500/kL2ccASO8O6v92gGTaaY5gOCAI4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
