INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (232672, 'Blended', 'Recently divorced mom Lauren and widowed dad Jim let their friends push them into a blind date, which goes disastrously wrong. Unsurprisingly, neither wants to see the other ever again. However, fate intervenes when both Jim and Lauren, unbeknownst to each other, purchase one-half of the same vacation package at a South African resort for families, during spring break. They and their children are forced to share the same romantic suite and participate in a slew of family activities together.', '2014-05-21', 6.89, 'https://image.tmdb.org/t/p/w500/o2YrH9jS7CAfWjETHFeL0tth79E.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
