INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (223702, 'Sausage Party', 'Hot dog Frank leads a group of supermarket products on a quest to discover the truth about their existence and what really happens when they''re chosen to leave the grocery store.', '2016-07-11', 5.75, 'https://image.tmdb.org/t/p/w500/vNgdPJQ5CI60oEiiHLKRNrsDhMy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (244688, 'The Hungover Games', 'Each year, drunk people are selected to participate in torturous games the morning after a big night out. There''s no sunglasses, no water, and no headache medicine. "The Hungover Games," a film that manages to merge the premises of both "The Hunger Games" and "The Hangover" and throw in references to "Ted," "Django Unchained," "The Lord of the Rings," "Carrie," "The Real Housewives of Beverly Hills" and whatever else crossed the writers'' fevered brains during the probably very drunken "development process."', '2014-02-01', 4.07, 'https://image.tmdb.org/t/p/w500/sOqB812jWYgcHCyT2PVEk3RBtSm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (234200, 'Pride', 'In 1984, a group of LGBT activists decide to raise money to support the National Union of Mineworkers during their lengthy strike. There is only one problem: the Union seems embarrassed to receive their support.', '2014-09-12', 7.69, 'https://image.tmdb.org/t/p/w500/Kc3vbqO0X4VRnjACGNoWLNQvHo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (225565, 'That Awkward Moment', 'Best pals Jason and Daniel indulge in casual flings and revel in their carefree, unattached lives. After learning that the marriage of their friend Mikey is over, they gladly welcome him back into their circle. The three young men make a pact to have fun and avoid commitment. However, when all three find themselves involved in serious relationships, they must keep their romances secret from one another.', '2014-01-29', 6.14, 'https://image.tmdb.org/t/p/w500/tjDAdesZNYFyRNnZvLT0osc7S2t.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (234862, 'Mr Hublot', 'Mr Hublot is a withdrawn, idiosyncratic character with OCD, scared of change and the outside world. Robot Pet''s arrival turns his life upside down: he has to share his home with this very invasive companion.', '2013-10-14', 6.96, 'https://image.tmdb.org/t/p/w500/cUDszLzmJ8SoB9ls4NyyTdfkdVY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (245917, 'Gintama: The Final Chapter - Be Forever Yorozuya', 'What would have happened if the Shiroyasha never existed?  Edo is thrown to chaos by a mysterious cause. Sakata Gintoki, now lives in a world where the future has changed, without him. What has happened to the Yorozuya?  Gintoki, who is now a ghost of the past, must once again carry the burden in order to save his friends. He must finish the biggest job ever, which may be the final job of Yorozuya.', '2013-07-04', 8.01, 'https://image.tmdb.org/t/p/w500/1wEl5WHQO2SdWQ6S3gLBaaobf4c.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (237756, 'Kill Me Three Times', 'While on a seemingly routine job, a jaded hit man discovers that he''s not the only one with his target in the crosshairs.', '2015-04-10', 5.62, 'https://image.tmdb.org/t/p/w500/dfsDkaWN8jhoa4przuvP1S3woqm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (246080, 'Black Sea', 'A rogue submarine captain pulls together a misfit crew to go after a sunken treasure rumored to be lost in the depths of the Black Sea. As greed and desperation take control on-board their claustrophobic vessel, the increasing uncertainty of the mission causes the men to turn on each other to fight for their own survival.', '2014-12-05', 6.27, 'https://image.tmdb.org/t/p/w500/oqOXFP35a2DjxjdpmEaOTIfI5TS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (246355, 'Saw', 'David, an orderly at a hospital, tells his horrific story of being kidnapped and forced to play a vile game of survival.', '2003-10-16', 7.04, 'https://image.tmdb.org/t/p/w500/2dfaedyVvHli1pmm9HHcoVTDOCH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (246400, '20,000 Days on Earth', 'A semi-fictionalized documentary about a day in the life of Australian musician Nick Cave''s persona.', '2014-07-05', 7.06, 'https://image.tmdb.org/t/p/w500/pUmYsh07P2Bq6ip2RZmOq6mr2vF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (244786, 'Whiplash', 'Under the direction of a ruthless instructor, a talented young drummer begins to pursue perfection at any cost, even his humanity.', '2014-10-10', 8.38, 'https://image.tmdb.org/t/p/w500/7fn624j5lj3xTme2SgiLCeuedmO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (246655, 'X-Men: Apocalypse', 'After the re-emergence of the world''s first mutant, world-destroyer Apocalypse, the X-Men must unite to defeat his extinction level plan.', '2016-05-18', 6.53, 'https://image.tmdb.org/t/p/w500/ikA8UhYdTGpqbatFa93nIf6noSr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (246403, 'Tusk', 'When his best friend and podcast co-host goes missing in the backwoods of Canada, a young guy joins forces with his friend''s girlfriend to search for him.', '2014-09-19', 5.54, 'https://image.tmdb.org/t/p/w500/pA2SgITmH0lzet9Nn5cxeinRKMv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (248212, 'Lilting', 'A young man of Chinese-Cambodian descent dies, leaving behind his isolated mother and his lover of four years. Though the two don''t share a language, they grow close through their grief.', '2014-08-08', 6.95, 'https://image.tmdb.org/t/p/w500/4u0iIdNdaTtTg0xY3If9HRZfPYR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (248574, 'Barely Lethal', 'A 16-year-old international assassin yearning for a "normal" adolescence fakes her own death and enrolls as a senior in a suburban high school. She quickly learns that being popular can be more painful than getting water-boarded.', '2015-04-23', 5.71, 'https://image.tmdb.org/t/p/w500/8emz9dKW8KKIqG8WcFG1lJbr2ub.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (246741, 'What We Do in the Shadows', 'Vampire housemates try to cope with the complexities of modern life and show a newly turned hipster some of the perks of being undead.', '2014-06-19', 7.54, 'https://image.tmdb.org/t/p/w500/a2rD3i3DBMeYbA34rBv6z3B9S3a.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (248933, 'The Dark Valley', 'The Alps, late 19th century. Greider, a mysterious lone rider who claims to be a photographer, arrives at an isolated lumber village, despotically ruled by a family clan, asking for winter accommodation.', '2014-02-13', 7.00, 'https://image.tmdb.org/t/p/w500/8s59L4YCmDNyQAkSrlkvc3Vc3fp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (235260, 'Son of God', 'In the Holy Land, the Roman occupation has produced a cauldron of oppression, anxiety and excessive taxes levied upon the Jewish people. Fearing the wrath of Roman governor Pontius Pilate , Jewish high priest Caiaphas tries to keep control of his people. That control is threatened when Jesus arrives in Jerusalem, performing miracles and spreading messages of love and hope. Those who fear that Jesus will inspire a revolution decide that he must die.', '2014-02-28', 6.83, 'https://image.tmdb.org/t/p/w500/ayqHV0rHuAdMv8PS497W2OByGWk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (249070, 'Hitman: Agent 47', 'An assassin teams up with a woman to help her find her father and uncover the mysteries of her ancestry.', '2015-08-20', 5.91, 'https://image.tmdb.org/t/p/w500/cx9AOBOv9Qf5ufZYQMbfTV7w7VY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (249164, 'If I Stay', 'Mia Hall, a talented young cellist, thought the most difficult decision she would ever have to make would be whether to pursue her musical dreams at prestigious Juilliard or follow her heart to be with the love of her life, Adam, a rock singer/guitarist. However, a car wreck changes everything in an instant, and now Mia''s life hangs in the balance. Suspended between life and death, Mia faces a choice that will decide her future.', '2014-08-21', 7.34, 'https://image.tmdb.org/t/p/w500/7Twh8h3Wh7GC9npTAEUThgkxkWL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (249397, 'Nymphomaniac: Vol. II', 'The continuation of Joe''s sexually dictated life delves into the darker aspects of her adult life and what led to her being in Seligman''s care.', '2013-12-25', 6.71, 'https://image.tmdb.org/t/p/w500/iLUNqgNKuWn667kXCKztSxYbT3k.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (249660, 'God''s Not Dead', 'After he refuses to disavow his faith, a devout Christian student must prove the existence of God or else his college philosophy professor will fail him.', '2014-03-21', 5.97, 'https://image.tmdb.org/t/p/w500/yKUzBolWrwyByevBtDPfy3kIumv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (249688, 'The End of the Tour', 'The story of the five-day interview between Rolling Stone reporter David Lipsky and acclaimed novelist David Foster Wallace, which took place right after the 1996 publication of Wallace''s groundbreaking epic novel, ''Infinite Jest.''', '2015-07-31', 7.00, 'https://image.tmdb.org/t/p/w500/3fEuVd8Xorwtk5kFVvyiNlOtcIw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (249923, 'Someone Marry Barry', 'A trio of friends scheme to find a wife for their socially inappropriate friend Barry, and end up finding a girl just like him.', '2014-02-07', 5.63, 'https://image.tmdb.org/t/p/w500/4fwVknJ86F6pAXWGOKItWABb1yp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (250225, 'The Duke of Burgundy', 'Day in and day out, lovers Cynthia and Evelyn enact an elaborate sadomasochistic fantasy as mistress and maid. But as their ritual of domination and submission begins to turn stale, Cynthia yearns for something more conventional, while Evelyn tries to push their taboos even further.', '2015-02-20', 6.32, 'https://image.tmdb.org/t/p/w500/72ctjjts0j8OFQkIFODT6RnYbBK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (250066, 'American Heist', 'Two brothers, both with troubled paths, find themselves in the middle of one last bank job.', '2014-09-11', 4.80, 'https://image.tmdb.org/t/p/w500/526uxanwv4mMK0YTxjVrsmMXXo2.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (250556, 'Trevor Noah: African American', 'Internationally acclaimed comedian Trevor Noah challenges the status quo through his unique perspective, breaking down cultural flaws on all sides and finding our mutual connections with laughter. Born a mixed-race child in South Africa under Apartheid, ''Trevor Noah: African American'' is Noah¿s search for identity in a world obsessed with labels.', '2013-07-05', 7.00, 'https://image.tmdb.org/t/p/w500/8z255VNqrNaBhh6MwKAABOKx9K4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (250574, 'Creep', 'Looking for work, Aaron comes across a cryptic online ad: “$1,000 for the day. Filming service. Discretion is appreciated.” Low on cash and full of naiveté, he decides to go for it. He drives to a cabin in a remote mountain town where he meets Josef, his cinematic subject for the day. Josef is sincere and the project seems heartfelt, so Aaron begins to film. But as the day goes on, it becomes clear that Josef is not who he says, and his intentions are not at all pure.', '2014-03-08', 6.40, 'https://image.tmdb.org/t/p/w500/qn53D574tT0YRyLgirEFHQwGUXw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (250658, 'The Internet''s Own Boy: The Story of Aaron Swartz', 'Programming prodigy and information activist Aaron Swartz achieved groundbreaking work in social justice and political organizing. His passion for open access ensnared him in a legal nightmare that ended with the taking of his own life at the age of 26.', '2014-06-27', 7.88, 'https://image.tmdb.org/t/p/w500/6yfXtkVPWxeU3OonoKDem4Hrdbb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (251016, 'Patton Oswalt: Tragedy Plus Comedy Equals Time', 'Performing for a packed house at Spreckels Theater in San Diego, comedian Patton Oswalt delivers a blistering stand-up set in his trademark blend of acerbic wit and unabashed silliness. His topics include a wide array of modern issues, from the future of our nation to daddy/daughter outings gone wrong.', '2014-01-17', 6.80, 'https://image.tmdb.org/t/p/w500/wAqRKiJfL7GlUbo10JNvHdJEL41.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (236737, 'Spanish Affair', 'Rafael, a Seville citizen who has never left the Spanish region of Andalucia, decides to leave his homeland to follow Amaia, a Basque girl unlike other women he has known.', '2014-03-14', 6.64, 'https://image.tmdb.org/t/p/w500/vUbn2Dy9qWWV8VnktvuGn9YiCRL.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (252171, 'A Girl Walks Home Alone at Night', 'In the Iranian ghost-town Bad City, a place that reeks of death and loneliness, the townspeople are unaware they are being stalked by a lonesome vampire.', '2014-11-21', 6.81, 'https://image.tmdb.org/t/p/w500/cd2rCE1nun7CESjBI8PGNEof1tb.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (251516, 'Kung Fury', 'During an unfortunate series of events, a friend of Kung Fury is assassinated by the most dangerous kung fu master criminal of all time, Adolf Hitler, a.k.a Kung Führer.  Kung Fury decides to travel back in time to Nazi Germany in order to kill Hitler and end the Nazi empire once and for all.', '2015-05-22', 7.48, 'https://image.tmdb.org/t/p/w500/f1QpIlCqlFXp1hjnLplXb5irxip.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (244506, 'Camp X-Ray', 'A young woman joins the military to be part of something bigger than herself and her small-town roots. Instead, she ends up as a new guard at Guantanamo Bay, where her mission is far from black and white. Surrounded by hostile jihadists and aggressive squadmates, she strikes up an unusual friendship with one of the detainees.', '2014-10-17', 6.72, 'https://image.tmdb.org/t/p/w500/aqNzRiaEsfv567Ji9njJofblRBE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (250798, 'The Green Prince', 'This real-life thriller tells the story of one of Israel’s prized intelligence sources, recruited to spy on his own people for more than a decade. Focusing on the complex relationship with his handler, The Green Prince is a gripping account of terror, betrayal, and unthinkable choices, along with a friendship that defies all boundaries.', '2014-01-16', 7.06, 'https://image.tmdb.org/t/p/w500/xeUxtEDEA4AXWg7pV5oen0rn4EX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (250546, 'Annabelle', 'A couple begins to experience terrifying supernatural occurrences involving a vintage doll shortly after their home is invaded by satanic cultists.', '2014-10-01', 5.79, 'https://image.tmdb.org/t/p/w500/yLsuU2P2SpDYFwtZQ7dtfVAf6TE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (245698, 'Pawn Sacrifice', 'During the height of the Cold War, American chess prodigy Bobby Fischer finds himself caught between two superpowers when he challenges the Soviet Empire.', '2015-09-16', 6.74, 'https://image.tmdb.org/t/p/w500/5vcLstd2hYn0XhyuEKaPbBZAqSh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (237584, 'Mojave', 'A suicidal artist goes into the desert, where he finds his doppelgänger, a homicidal drifter.', '2016-01-22', 5.00, 'https://image.tmdb.org/t/p/w500/eZLpBNG84wAI5c9XCQBa7w78ElX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (253235, 'And So It Goes', 'Nobody likes self-centered realtor Oren Little, and he prefers it that way. He''s deliberately mean to anyone who crosses his path and wants nothing more than to sell one final house and retire. His life turns upside-down when his estranged son drops off a granddaughter he never knew existed. Suddenly left in charge of her and with no idea how to take care of a child, he pawns the girl off on his neighbor, Leah -- but he eventually learns how to open his heart.', '2014-07-10', 6.04, 'https://image.tmdb.org/t/p/w500/bJoWtA8OAIqavlb5mbx3EzvxFUA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (253255, 'Fort Tilden', 'Twenty-something Brooklynites Allie and Harper are directionless, privileged, and just a tiny bit damaged. All they want is to get to the beach, where a drug-fueled afternoon with cute boys awaits them. Alas, the journey becomes needlessly complicated, as the girls’ bike ride from Williamsburg to Fort Tilden Beach is littered with a barrage of unfriendly circumstances and the realization that their life skills are more limited than they should be.', '2014-03-08', 5.60, 'https://image.tmdb.org/t/p/w500/fhm3SFtrcyzA1rGT00OnOeZ4WDF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (252360, 'In the Name of the King III', 'Hazen Kaine, an American contract killer living in Sofia, Bulgaria, gets more than he bargains for when he enters into a contract with the mob. One last job before he gets out and starts a new life for himself. The targets: the three children of royal billionaire Andon Dupont. Seems simple enough, or so he thought. Hazen apprehends the children, and before he can blink an eye, a simple necklace worn by one of the children sends his life spiraling back to medieval times. Now completely out of his element, Hazen fights for his life as he tries to escape a medieval army and a fierce fire-breathing dragon.', '2014-02-05', 3.86, 'https://image.tmdb.org/t/p/w500/yetbsCuB6fmzI4lpJMvqwJcehti.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (253303, 'Buzzard', 'Paranoia forces small-time scam artist Marty to flee his hometown and hide out in a dangerous Detroit. With nothing but a pocket full of bogus checks, his Power Glove, and a bad temper, the horror metal slacker lashes out.', '2015-03-06', 5.35, 'https://image.tmdb.org/t/p/w500/ziImW5nB2AENKBjSo5oEZBUGYOw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (253272, 'The Mule', 'In 1983, a naive man is detained by Australian Federal Police with lethal narcotics hidden in his stomach. After being apprehended, ‘The Mule’ makes a desperate choice... to defy his bodily functions and withhold the evidence – literally.', '2014-03-10', 6.26, 'https://image.tmdb.org/t/p/w500/qwMZYSkLofFC27oBeZ1hZWgliXw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (253412, 'Everest', 'Inspired by the incredible events surrounding a treacherous attempt to reach the summit of the world''s highest mountain, "Everest" documents the awe-inspiring journey of two different expeditions challenged beyond their limits by one of the fiercest snowstorms ever encountered by mankind. Their mettle tested by the harshest of elements found on the planet, the climbers will face nearly impossible obstacles as a lifelong obsession becomes a breathtaking struggle for survival.', '2015-09-10', 6.83, 'https://image.tmdb.org/t/p/w500/2jKOu2bjpLP6NXJcm7Ep14bDGtA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (253344, 'Some Kind of Beautiful', 'By day, Richard Haig is a successful and well-respected English professor at renowned Trinity College in Cambridge.  By night, Richard indulges his own romantic fantasies with a steady stream of beautiful undergraduates.  But Richard has grown tired of the  game and is looking for something more meaningful and lasting.  So when Kate, Richard’s tanned, athletic, 25-year-old American girlfriend tells him that she is pregnant, Richard is thrilled.  He looks forward to having a family of his own,  being a father his children could be proud of, not some sex-fueled bobcat.  There is only one problem.  Richard’s not in love with Kate.  Richard is in love with Kate’s sister, Olivia. He had been in love with her ever since he first saw her.', '2014-11-06', 5.63, 'https://image.tmdb.org/t/p/w500/ubuc8fRcT0I5lF4Q5P5lnyrZJJg.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (253306, 'Housebound', 'When Kylie Bucknell is sentenced to home detention, she''s forced to come to terms with her unsociable behaviour, her blabbering mother and a hostile spirit who seems less than happy about the new living arrangement.', '2014-09-04', 6.57, 'https://image.tmdb.org/t/p/w500/jPKEeHmUuoDnIaRs6VUqSr4qRGR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (253414, 'Rock the Kasbah', 'A washed-up music producer finds one last shot at redemption with a golden-voiced young girl in Afghanistan. However, when jealousy gets the better of a disgruntled ex-boyfriend, he decides to oppose the young star with talent of his own.', '2015-10-22', 5.38, 'https://image.tmdb.org/t/p/w500/jGNOsJjpsJ4yWe3InuiXgYk8VuW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (251232, 'Copenhagen', 'After weeks of traveling through Europe, the immature William finds himself in Copenhagen, the place of his father’s birth. He befriends the youthful Effy, who works in William’s hotel as part of an internship program, and they set off to find William’s last living relative. Effy’s mix of youthful exuberance and wisdom challenges William unlike any  woman ever has. As the attraction builds, he must come to grips with destabilizing elements of his family’s sordid past.', '2014-10-03', 6.59, 'https://image.tmdb.org/t/p/w500/1MSFfjvgf9auNANWcaGTvzf1TcW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (253622, 'That Demon Within', 'By a strange twist of fate, dutiful Hong Kong policeman Dan saves the life of the leader of a violent gang of armed robbers.  When they commit another crime, Dan is determined to put an end to their activities.  He works with the leader, whom the gang had betrayed, to engineer a plan to wreak havoc within the gang and let the gangsters kill one another.  But it becomes increasingly obvious to Dan and to his colleagues that Dan is suffering from a severe mental disorder, and Dan finds that instead of upholding the law as a righteous police officer, he has now become a fugitive wanted for murder.', '2014-04-17', 5.60, 'https://image.tmdb.org/t/p/w500/mzZv8NGmQMeM8WGCXqXXK0Fo3Oz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (254024, 'The Face of an Angel', 'Both a journalist and a documentary filmmaker chase the story of a murder and its prime suspect.', '2014-09-06', 5.00, 'https://image.tmdb.org/t/p/w500/100pHE252kgwxwVNbiflYV9j1yi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (254128, 'San Andreas', 'In the aftermath of a massive earthquake in California, a rescue-chopper pilot makes a dangerous journey across the state in order to rescue his estranged daughter.', '2015-05-27', 6.25, 'https://image.tmdb.org/t/p/w500/2Gfjn962aaFSD6eST6QU3oLDZTo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (244509, 'Cold in July', 'While investigating noises in his house one balmy Texas night in 1989, Richard Dane puts a bullet in the brain of a low-life burglar. Although he’s hailed as a small-town hero, Dane soon finds himself fearing for his family’s safety when Freddy’s ex-con father rolls into town, hell-bent on revenge.', '2014-05-23', 6.54, 'https://image.tmdb.org/t/p/w500/gzHS4ehNU6wapLt9UpA1rNnljiO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
