INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (258363, 'Desierto', 'A group of Mexican emigrants attempts to cross the Mexican-US border. What begins as a hopeful journey becomes a harrowing, bloody and primal fight for survival when a deranged, rifle-toting vigilante and his loyal Belgian Malinois dog chase the group of unarmed men and women through the treacherous borderland. In the harsh, unforgiving desert terrain, the odds are stacked firmly against them as they discover there’s nowhere to hide from the unrelenting, merciless killer.', '2015-04-12', 6.17, 'https://image.tmdb.org/t/p/w500/67Ue5or6ZPScqkagC3EJSOYuzyR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
