INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (259985, 'Just Eat It: A Food Waste Story', 'We all love food. As a society, we devour countless cooking shows, culinary magazines and foodie blogs. So how could we possibly be throwing nearly 50% of it in the trash? Filmmakers and food lovers Jen and Grant dive into the issue of waste from farm, through retail, all the way to the back of their own fridge. After catching a glimpse of the billions of dollars of good food that is tossed each year in North America, they pledge to quit grocery shopping and survive only on discarded food. What they find is truly shocking.', '2014-04-27', 6.92, 'https://image.tmdb.org/t/p/w500/eVQ3XX6MJELZOLIuWuCv1lpM1MW.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
