INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (261392, 'American Ultra', 'Mike is an unmotivated stoner whose small-town life with his live-in girlfriend, Phoebe, is suddenly turned upside down.  Unbeknownst to him, Mike is actually a highly trained, lethal sleeper agent. In the blink of an eye, as his secret past comes back to haunt him, Mike is thrust into the middle of a deadly government operation and is forced to summon his inner action-hero in order to survive.', '2015-08-19', 6.10, 'https://image.tmdb.org/t/p/w500/g9JX6RZQoTInDJhbrKItnOr47qr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (261037, 'Miss Meadows', 'Miss Meadows is a school teacher with impeccable manners and grace. However, underneath the candy-sweet exterior hides a ruthless gun-toting vigilante who takes it upon herself to right the wrongs in the world by whatever means necessary. For Miss Meadows, bad behavior is simply unforgivable.', '2014-09-12', 5.89, 'https://image.tmdb.org/t/p/w500/fpYXvWGKPwk51UTk8hqo0qE13qk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (261414, 'Larry David: Curb Your Enthusiasm', 'Mock documentary about Seinfeld writer Larry David featuring contributions from his friends and colleagues. Larry makes a return to stand-up comedy and prepares to film a television special for HBO.  This is the original special that gave birth to the long-running award-winning HBO series.', '1999-10-17', 7.53, 'https://image.tmdb.org/t/p/w500/oAPbSMOWJCXXJbRYNBfzojE8Lql.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (262481, 'An Honest Liar', 'An Honest Liar tells the incredible story of the world-famous magician, escape artist, and world-renowned enemy of deception, James ''The Amazing'' Randi. The film brings to life Randi''s intricate investigations that publicly exposed psychics, faith healers, and con-artists with quasi-religious fervor. A master deceiver who came out of the closet at the age of 81, Randi created fictional characters, fake psychics, and even turned his partner of 25 years, Jose Alvarez, into a sham guru named Carlos.', '2014-04-18', 7.09, 'https://image.tmdb.org/t/p/w500/sXgXPtynmZnLLISonrrc7XtrLKv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (262500, 'Insurgent', 'Beatrice Prior must confront her inner demons and continue her fight against a powerful alliance which threatens to tear her society apart.', '2015-03-18', 6.36, 'https://image.tmdb.org/t/p/w500/dP5Fb6YRfzmCQtRbHOr2kO7tJW9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (262543, 'Automata', 'Jacq Vaucan, an insurance agent of ROC robotics corporation, routinely investigates the case of manipulating a robot. What he discovers will have profound consequences for the future of humanity.', '2014-10-09', 5.90, 'https://image.tmdb.org/t/p/w500/h7SEtIWOfLsuCWhQgflev7ppRPq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (263105, 'Boy Meets Girl', 'In Kentucky, a transgender woman and her best male friend lament the lack of eligible partners and step across old boundaries of love and romance.', '2014-06-28', 6.65, 'https://image.tmdb.org/t/p/w500/sxgQDPNkky07l1bv9g8AyoB4jJp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (263029, 'Late Night with Conan O''Brien: The Best of Triumph the Insult Comic Dog', 'A hilarious collection of some of the best Triumph the Insult Comic Dog segments from "Late Night with Conan O''Brien."', '2004-08-10', 6.62, 'https://image.tmdb.org/t/p/w500/tpktkKnhl9zeQd1gpiQxaBHw1BY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (263109, 'Shaun the Sheep Movie', 'When Shaun decides to take the day off and have some fun, he gets a little more action than he bargained for. A mix up with the Farmer, a caravan and a very steep hill lead them all to the Big City and it''s up to Shaun and the flock to return everyone safely to the green grass of home.', '2015-02-05', 6.99, 'https://image.tmdb.org/t/p/w500/1GMvKNy2Ht5QwI0oV0ycYnxzWdC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (263115, 'Logan', 'In the near future, a weary Logan cares for an ailing Professor X in a hideout on the Mexican border. But Logan''s attempts to hide from the world and his legacy are upended when a young mutant arrives, pursued by dark forces.', '2017-02-28', 7.82, 'https://image.tmdb.org/t/p/w500/fnbjcRDYn6YviCcePDnGdyAkYsB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (263472, 'Knock Knock', 'When a devoted husband and father is left home alone for the weekend, two stranded young women unexpectedly knock on his door for help. What starts out as a kind gesture results in a dangerous seduction and a deadly game of cat and mouse.', '2015-06-26', 5.39, 'https://image.tmdb.org/t/p/w500/cUC4rUb1Cs2KMaZ6RD4uYUEEwls.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (263614, 'Virunga', 'Virunga in the Democratic Republic of the Congo is Africa’s oldest national park, a UNESCO world heritage site, and a contested ground among insurgencies seeking to topple the government that see untold profits in the land. Among this ongoing power struggle, Virunga also happens to be the last natural habitat for the critically endangered mountain gorilla. The only thing standing in the way of the forces closing in around the gorillas: a handful of passionate park rangers and journalists fighting to secure the park’s borders and expose the corruption of its enemies. Filled with shocking footage, and anchored by the surprisingly deep and gentle characters of the gorillas themselves, Virunga is a galvanizing call to action around an ongoing political and environmental crisis in the Congo.', '2014-11-07', 7.90, 'https://image.tmdb.org/t/p/w500/7ULqkiqpxWfQxNHRq5PeZjJQ3f6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (264644, 'Room', 'Held captive for 7 years in an enclosed space, a woman and her young son finally gain their freedom, allowing the boy to experience the outside world for the first time.', '2015-10-16', 7.99, 'https://image.tmdb.org/t/p/w500/2hHDMeYyZjbGWn0BeNH1cTMxuM7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (245916, 'Kill the Messenger', 'A reporter becomes the target of a vicious smear campaign that drives him to the point of suicide after he exposes the CIA''s role in arming Contra rebels in Nicaragua and importing cocaine into California. Based on the true story of journalist Gary Webb.', '2014-10-09', 6.62, 'https://image.tmdb.org/t/p/w500/8gaNZiKZHvKCqMDByY00dUIV0YC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (264660, 'Ex Machina', 'Caleb, a coder at the world''s largest internet company, wins a competition to spend a week at a private mountain retreat belonging to Nathan, the reclusive CEO of the company. But when Caleb arrives at the remote location he finds that he will have to participate in a strange and fascinating experiment in which he must interact with the world''s first true artificial intelligence, housed in the body of a beautiful robot girl.', '2015-01-21', 7.57, 'https://image.tmdb.org/t/p/w500/dmJW8IAKHKxFNiUnoDR7JfsK7Rp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (264999, 'Magic Mike XXL', 'Three years after Mike bowed out of the stripper life at the top of his game, he and the remaining Kings of Tampa hit the road to Myrtle Beach to put on one last blow-out performance.', '2015-07-01', 6.10, 'https://image.tmdb.org/t/p/w500/jkuCNd3wOmf4sDlZ89HEt8jmsqr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
