INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (256740, 'Wicked Blood', 'Hannah and Amber Baker are trapped in a dark Southern underworld of violence, drugs and bikers. Both live in fear of their "Uncle Frank" Stinson, the ruthless leader of a crime organization.', '2014-03-04', 5.50, 'https://image.tmdb.org/t/p/w500/dTxOsk0wVG1EgyCbWbaNxQXZLxy.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (256876, 'Red Army', 'A documentary highlighting the Soviet Union''s legendary and enigmatic hockey training culture and world-dominating team through the eyes of the team''s Captain Slava Fetisov, following his shift from hockey star and celebrated national hero to political enemy.', '2015-01-23', 7.34, 'https://image.tmdb.org/t/p/w500/y2e6I7A8AgNTfB1MeNZfhh9Q4ES.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (266285, 'The Salvation', 'In 1870s America, a peaceful American settler kills his family''s murderer which unleashes the fury of a notorious gang leader. His cowardly fellow townspeople then betray him, forcing him to hunt down the outlaws alone.', '2014-05-22', 6.49, 'https://image.tmdb.org/t/p/w500/xQsv3OI8UT6s9Rn3C0WxO24bnEx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
