INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (269963, 'The Way South', 'Johan van der Keuken went against the grain in 1980: from Amsterdam (on April 30 with the coronation riots and squatting actions) via Paris, southern France and Italy to Egypt. He made his personal travelogue in three parts for VPRO television. Later, he fused the three parts into one long movie.', '1981-01-01', 5.86, 'https://image.tmdb.org/t/p/w500/8RHmX8qLya7hloxdOBzyzKDySH5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
