INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (272693, 'The DUFF', 'Bianca''s universe turns upside down when she learns that her high school refers to her as a ‘DUFF'' (Designated Ugly Fat Friend). Hoping to erase that label, she enlists the help of a charming jock and her favorite teacher. Together they''ll face the school''s mean girl and remind everyone that we are all someone''s DUFF… and that''s totally fine.', '2015-02-20', 6.76, 'https://image.tmdb.org/t/p/w500/A6ScveWmIPL9vSYyULD8ObqyHDQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (273248, 'The Hateful Eight', 'Bounty hunters seek shelter from a raging blizzard and get caught up in a plot of betrayal and deception.', '2015-12-25', 7.76, 'https://image.tmdb.org/t/p/w500/jIywvdPjia2t3eKYbjVTcwBQlG8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (257091, 'Get Hard', 'When millionaire hedge fund manager James is convicted of fraud and sentenced to a stretch in San Quentin, the judge gives him one month to get his affairs in order. Knowing that he won''t survive more than a few minutes in prison on his own, James desperately turns to Darnell-- a black businessman who''s never even had a parking ticket -- for help. As Darnell puts James through the wringer, both learn that they were wrong about many things, including each other.', '2015-03-26', 6.01, 'https://image.tmdb.org/t/p/w500/rJPbS2cYOYhDCjT5NmW1Fm6gFl3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (266647, 'Pan', 'Living a bleak existence at a London orphanage, 12-year-old Peter finds himself whisked away to the fantastical world of Neverland. Adventure awaits as he meets new friend James Hook and the warrior Tiger Lily. They must band together to save Neverland from the ruthless pirate Blackbeard. Along the way, the rebellious and mischievous boy discovers his true destiny, becoming the hero forever known as Peter Pan.', '2015-09-24', 5.96, 'https://image.tmdb.org/t/p/w500/w8i0mZR7MEL7c3bXSsuYg7VJsew.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (273477, 'Scouts Guide to the Zombie Apocalypse', 'Three scouts and lifelong friends join forces with one badass cocktail waitress to become the world’s most unlikely team of heroes.  When their peaceful town is ravaged by a zombie invasion, they’ll fight for the badge of a lifetime and put their scouting skills to the test to save mankind from the undead.', '2015-10-23', 6.59, 'https://image.tmdb.org/t/p/w500/lUKvvSnjFlazrdh6wyHxHrdMknD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (270946, 'Penguins of Madagascar', 'Skipper, Kowalski, Rico and Private join forces with undercover organization The North Wind to stop the villainous Dr. Octavius Brine from destroying the world as we know it.', '2014-11-22', 6.54, 'https://image.tmdb.org/t/p/w500/dXbpNrPDZDMEbujFoOxmMNQVMHa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (257445, 'Goosebumps', 'After moving to a small town, Zach Cooper finds a silver lining when he meets next door neighbor Hannah, the daughter of bestselling Goosebumps series author R.L. Stine. When Zach unintentionally unleashes real monsters from their manuscripts and they begin to terrorize the town, it’s suddenly up to Stine, Zach and Hannah to get all of them back in the books where they belong.', '2015-08-05', 6.31, 'https://image.tmdb.org/t/p/w500/aeZT9pqEgrmXOGdESFkAuVjX6kw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (273899, 'Stonewall', 'Kicked out by his parents, a gay teenager leaves small-town Indiana for New York''s Greenwich Village, where growing discrimination against the gay community leads to riots on June 28, 1969.', '2015-09-18', 5.96, 'https://image.tmdb.org/t/p/w500/jkUKuPK0dJwP9o47npgLipp83D0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (257344, 'Pixels', 'Video game experts are recruited by the military to fight 1980s-era video game characters who''ve attacked New York.', '2015-07-16', 5.79, 'https://image.tmdb.org/t/p/w500/d26S5EfVXLNxRXqyFy1yyl3qRq3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (273404, 'I''ll Follow You Down', 'After the disappearance of a young scientist on a business trip, his son and wife struggle to cope, only to make a bizarre discovery years later – one that may bring him home.', '2013-07-28', 6.03, 'https://image.tmdb.org/t/p/w500/3osrKXIz5OkSrpnEt1hqHAAyvbd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (272548, 'Moonwalkers', 'What if Apollo 11 never actually made it? What if, in reality, Stanley Kubrick secretly shot the famous images of the moon landing in a studio, working for the US administration? This is the premise of a totally plausible conspiracy theory that takes us to swinging sixties London, where a stubborn CIA agent will never find Kubrick but is forced to team up with a lousy manager of a seedy rock band to develop the biggest con of all time.', '2015-03-14', 6.12, 'https://image.tmdb.org/t/p/w500/pkeHSbyBslHOUBTTWkkPFTyVvQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (258099, 'Just Before I Go', 'Ted Morgan has been treading water for most of his life. After his wife leaves him, Ted realizes he has nothing left to live for.  Summoning the courage for one last act, Ted decides to go home and face the people he feels are responsible for creating the shell of a person he has become.  But life is tricky.  The more determined Ted is to confront his demons, to get closure, and to withdraw from his family, the more Ted is yanked into the chaos of their lives. So, when Ted Morgan decides to kill himself, he finds a reason to live.', '2015-04-24', 6.39, 'https://image.tmdb.org/t/p/w500/rEwXZIOh3CLVA5JJmxT5kaYY6ff.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (267192, 'Genius', 'New York in the 1920s. Max Perkins, a literary editor is the first to sign such subsequent literary greats as Ernest Hemingway and F. Scott Fitzgerald. When a sprawling, chaotic 1,000-page manuscript by an unknown writer falls into his hands, Perkins is convinced he has discovered a literary genius.', '2016-06-10', 6.48, 'https://image.tmdb.org/t/p/w500/f3KG63zvQGvakfwOTUb8ODgHEnP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (258284, 'Every Secret Thing', 'One clear summer day in a Baltimore suburb, a baby goes missing from her front porch. Two young girls serve seven years for the crime and are released into a town that hasn''t fully forgiven or forgotten. Soon, another child is missing, and two detectives are called in to investigate the mystery in a community where everyone seems to have a secret.', '2014-04-20', 6.15, 'https://image.tmdb.org/t/p/w500/jR3rrAtFhK6MufgJIlNYoo0Iyfd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (258096, 'Alpha and Omega 3: The Great Wolf Games', 'Join the pack in this wild, warmhearted and totally pawsome adventure starring everyone''s favorite alphas and omegas! It''s time for "The Great Wolf Games," when all the alphas in the packs set aside their differences for some friendly competition. When an unexpected accident puts many of our pack''s star alpha wolves out of commission, a new team is assembled that includes forest friends not in the pack. Can Coach Humphrey lead his ragtag group of "underdogs" to victory? Find out in this thrilling movie that will leave you howling for more!', '2014-03-25', 5.25, 'https://image.tmdb.org/t/p/w500/nHNjwY0C2OAWqGDAq6roJk3Hn5O.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (276907, 'Legend', 'Suave, charming and volatile, Reggie Kray and his unstable twin brother Ronnie start to leave their mark on the London underworld in the 1960s. Using violence to get what they want, the siblings orchestrate robberies and murders while running nightclubs and protection rackets. With police Detective Leonard "Nipper" Read hot on their heels, the brothers continue their rapid rise to power and achieve tabloid notoriety.', '2015-09-09', 7.05, 'https://image.tmdb.org/t/p/w500/4shf5Alq4KWCKqrAAQe0JGJHYp5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (274504, 'The Adderall Diaries', 'Writer and Adderall enthusiast Stephen Elliott reaches a low point when his estranged father resurfaces, claiming that Stephen has fabricated much of the dark childhood that that fuels his writing. Adrift in the precarious gray area of memory, Stephen is led by three sources of inspiration: a new romance, the best friend who shares his history, and a murder trial that reminds him more than a little of his own story. Based on the memoir of the same name.', '2016-04-15', 5.28, 'https://image.tmdb.org/t/p/w500/8tkGOlNtKyqQO3esZQRlnkSTANY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (277546, 'The Runner', 'In the aftermath of the BP oil spill, an idealistic but imperfect New Orleans politician (Nicolas Cage) finds his plans of restoration unraveling as his own life becomes contaminated with corruption, scandal and deceit.', '2015-08-07', 4.90, 'https://image.tmdb.org/t/p/w500/2fPnVkWueayfbqk2g66fSTLoyWu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (277216, 'Straight Outta Compton', 'In 1987, five young men, using brutally honest rhymes and hardcore beats, put their frustration and anger about life in the most dangerous place in America into the most powerful weapon they had: their music.  Taking us back to where it all began, Straight Outta Compton tells the true story of how these cultural rebels—armed only with their lyrics, swagger, bravado and raw talent—stood up to the authorities that meant to keep them down and formed the world’s most dangerous group, N.W.A.  And as they spoke the truth that no one had before and exposed life in the hood, their voice ignited a social revolution that is still reverberating today.', '2015-08-11', 7.77, 'https://image.tmdb.org/t/p/w500/1CiLJx8Xtv3TbbFj6k7BboSmKgC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (258357, 'The Whole Shebang', 'After a series of catastrophically failed marriages, Apple is single again. Blame on Apple''s attachment is in her opinion, her mother Ingrid. Because this Apple has punished not only with her hippie name, but was in every way a raven mother. When Ingrid spends an All Inclusive vacation in Spain, her mother and daughter are confronted with a dramatic event from their past.', '2014-03-06', 4.58, 'https://image.tmdb.org/t/p/w500/wH44amLQxrcFFeqr3y4JAQ54utk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (277547, 'Playing It Cool', 'A young man meets and instantly falls in love with an engaged woman.', '2014-09-26', 5.85, 'https://image.tmdb.org/t/p/w500/96htqghZlKctNJqDLo2DuC9PEap.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (265195, 'Wild Tales', 'Injustice and the demands of the world can cause stress for many people. Some of them, however, explode. This includes a waitress serving a grouchy loan shark, an altercation between two motorists, an ill-fated wedding reception, and a wealthy businessman who tries to buy his family out of trouble.', '2014-08-21', 7.87, 'https://image.tmdb.org/t/p/w500/vmeCDuWJ6B2cqi9f3QFyIwRKqFV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (277834, 'Moana', 'In Ancient Polynesia, when a terrible curse incurred by Maui reaches an impetuous Chieftain''s daughter''s island, she answers the Ocean''s call to seek out the demigod to set things right.', '2016-10-13', 7.57, 'https://image.tmdb.org/t/p/w500/m5MDZOIFEFlxGiLuAzWzFSsWcye.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (273197, 'The Great Hypnotist', 'The famous psychologist Xu Ruining has a raising career, when he met the troublesome patient Ren Xiaoyan. The meeting is not easy as feeble-looking Ren is point by point against him.', '2014-04-29', 6.70, 'https://image.tmdb.org/t/p/w500/hqfKwoVMe3WCtTWWv2rIW6Oe05X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (277967, 'Life Eternal', 'Brenner returns to Graz, the city where he grew up. When confronted with his old friends, his former girlfriend and the major sin he committed when he was young, murders and a fateful gunshot to the head result. After Brenner comes out of a coma, he begins to search for the person who tried to kill him - however, everybody claims that he himself is responsible. In the beginning Brenner was at the end of his rope, but he could face a new beginning in the end.', '2015-03-05', 7.08, 'https://image.tmdb.org/t/p/w500/lSQ9fgPwhZfcFKxChHjHrbEiDLm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (278154, 'Ice Age: Collision Course', 'Set after the events of Continental Drift, Scrat''s epic pursuit of his elusive acorn catapults him outside of Earth, where he accidentally sets off a series of cosmic events that transform and threaten the planet. To save themselves from peril, Manny, Sid, Diego, and the rest of the herd leave their home and embark on a quest full of thrills and spills, highs and lows, laughter and adventure while traveling to exotic new lands and locations.', '2016-06-23', 6.12, 'https://image.tmdb.org/t/p/w500/tFzUkdhPOForVrEfvxydXfPLrZR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (278316, 'Da Sweet Blood of Jesus', 'Dr. Hess Green becomes cursed by a mysterious ancient African artifact and is overwhelmed with a newfound thirst for blood. Soon after his transformation he enters into a dangerous romance with Ganja Hightower that questions the very nature of love, addiction, sex, and status.', '2015-02-13', 4.74, 'https://image.tmdb.org/t/p/w500/dUqIwSKX9cEkahmv1lsolT8ouE9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (278348, 'The Maid''s Room', 'Drina, a young immigrant working as a live-in maid for a wealthy Long Island family, finds herself entangled in the family''s web of dark secrets once she begins to suspect her employer''s son has committed a terrible crime.', '2014-08-08', 4.65, 'https://image.tmdb.org/t/p/w500/jKqWJh3w88vxUwy0obaanuOej4L.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (278632, 'Julia', 'After suffering a brutal trauma, Julia uses an unorthodox form of therapy to restore herself.', '2015-01-03', 4.79, 'https://image.tmdb.org/t/p/w500/56W0KP6xEpvAjVf3Ofc0yyhfuNk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (278927, 'The Jungle Book', 'After a threat from the tiger Shere Khan, Mowgli, a man-cub fostered by wolves, is forced to flee the jungle, and he embarks on a journey of self-discovery with the help of the panther, Bagheera, and the free-spirited bear, Baloo.', '2016-04-07', 6.88, 'https://image.tmdb.org/t/p/w500/2Epx7F9X7DrFptn4seqn4mzBVks.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
