INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (279229, 'Sapphire Blue', 'Gwen has just discovered, that she''s the final member of the secret time-traveling Circle of Twelve. Now she has to juggle with constant trips to the past, her relationships with Gideon and figuring out dark secrets surrounding the Circle.', '2014-08-14', 7.09, 'https://image.tmdb.org/t/p/w500/kxRqokSkj6HWuwVCbnddPFg73CM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (279641, 'Whiskey Tango Foxtrot', 'Stuck in a rut, reporter Kim Baker decides to shake things up by leaving her desk job in New York and taking a dangerous assignment in Afghanistan. Far from home and completely out of her comfort zone, a culture-shocked Kim befriends an adventurous reporter Tanya Vanderpoel, a stern Colonel, and a charming photojournalist to help her navigate this crazy new world.', '2016-03-04', 6.32, 'https://image.tmdb.org/t/p/w500/wAxhQsY63VY6eF3EilXTkX0YRoU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (274167, 'Daddy''s Home', 'The story of a mild-mannered radio executive who strives to become the best stepdad ever to his wife''s two children, but complications ensue when their freewheeling, freeloading real father arrives, forcing stepdad to compete for the affection of the kids.', '2015-12-25', 6.29, 'https://image.tmdb.org/t/p/w500/fB9lALk9zKsMYWvf0bJSkJN219Z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (279690, 'He Never Died', 'When Jack learns his long-lost daughter was taken by a crime syndicate, he confronts his demons and wages a brutal fight to save her.', '2015-12-18', 6.21, 'https://image.tmdb.org/t/p/w500/vzqwe4uuINJhbPqvlbVShBnCvHv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (279714, 'OT: Our Town', 'Against all odds, the first theatrical production in over 20 years at Dominguez High School is going to be Thornton Wilder''s American classic Our Town. The kids at this Compton school are about to experience more than a culture clash, as they embark on a rich journey and discover the educational and social value of theater. OT: Our Town tells the story of human spirit and its strength against the stereotypes holding them down. Where Thornton Wilder wrote about little Grover''s Corners, this documentary exemplifies how Our Town is every town. Our Town is Compton.', '2002-05-09', 5.80, 'https://image.tmdb.org/t/p/w500/8V261ENcng8kBBuWsE7hnBVwAJd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (279972, 'Digging Up the Marrow', 'A documentary filmmaker turns his lens on an enigmatic conspiracy theorist who claims he''s found the entrance to a vast underground city populated entirely by monsters.', '2015-02-20', 5.45, 'https://image.tmdb.org/t/p/w500/xCE04zhX6TSQF1VvViyVTBVqvkr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (279828, 'Delirium', 'Set in a world where love is deemed illegal and can be eradicated with a special procedure. With 95 days to go until her scheduled treatment, Lena Holoway does the unthinkable, she falls in love.', '2014-06-20', 6.20, 'https://image.tmdb.org/t/p/w500/mJXHsvyg1SlxtIFg5yO38ODjdwx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (281957, 'The Revenant', 'In the 1820s, a frontiersman, Hugh Glass, sets out on a path of vengeance against those who left him for dead after a bear mauling.', '2015-12-25', 7.54, 'https://image.tmdb.org/t/p/w500/ji3ecJphATlVgWNY0B0RVXZizdf.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (282035, 'The Mummy', 'Though safely entombed in a crypt deep beneath the unforgiving desert, an ancient queen whose destiny was unjustly taken from her is awakened in our current day, bringing with her malevolence grown over millennia, and terrors that defy human comprehension.', '2017-06-06', 5.52, 'https://image.tmdb.org/t/p/w500/zxkY8byBnCsXodEYpK8tmwEGXBI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (281979, 'Doctor Who: The Waters of Mars', 'In a Mars base, the inhabitants are being infected by a mysterious water creature which takes over its victims. The Doctor is thrust into the middle of this catastrophe, knowing a larger one is waiting around the corner.', '2009-11-15', 7.92, 'https://image.tmdb.org/t/p/w500/ikb6cZI8RXUqcxApMJmIdimAJ1X.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (265208, 'Wild Card', 'When a Las Vegas bodyguard with lethal skills and a gambling problem gets in trouble with the mob, he has one last play… and it''s all or nothing.', '2015-01-14', 5.71, 'https://image.tmdb.org/t/p/w500/zN80Tlly8oMpKbVJv2TfRIj8dHG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (267573, 'Man on High Heels', 'Ji-wook is a virile detective with a reputation, but deep down in his heart, he always considered himself as a woman and finally decides to get a transsexual operation. However, his plan falls apart as vicious gang members start their revenge on him.', '2014-06-01', 6.88, 'https://image.tmdb.org/t/p/w500/u45gBnx1FBgMccThUAFpoqOMBms.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (266396, 'The Gunman', 'Eight years after fleeing the Congo following his assassination of that country''s minister of mining, former assassin Jim Terrier is back, suffering from PTSD and digging wells to atone for his violent past. After an attempt is made on his life, Terrier flies to London to find out who wants him dead -- and why. Terrier''s search leads him to a reunion with Annie, a woman he once loved, who is now married to an oily businessman with dealings in Africa.', '2015-02-16', 5.76, 'https://image.tmdb.org/t/p/w500/lnUozDnDANTsDYEdsNsHC6b8IiS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (266856, 'The Theory of Everything', 'Once a healthy, active young man, Hawking received an earth-shattering diagnosis at 21 years of age. With Jane fighting tirelessly by his side, Stephen embarks on his most ambitious scientific work, studying the very thing he now has precious little of – time.', '2014-11-07', 7.83, 'https://image.tmdb.org/t/p/w500/7kwcLFNt887saoQAL7EY0XnW7VI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (280092, 'Insidious: Chapter 3', 'A prequel set before the haunting of the Lambert family that reveals how gifted psychic Elise Rainier reluctantly agrees to use her ability to contact the dead in order to help a teenage girl who has been targeted by a dangerous supernatural entity.', '2015-05-28', 6.29, 'https://image.tmdb.org/t/p/w500/iDdGfdNvY1EX0uDdA4Ru77fwMfc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (273271, 'Time Lapse', 'Three friends discover a mysterious machine that takes pictures 24 hours into the future and conspire to use it for personal gain, until disturbing and dangerous images begin to develop.', '2014-05-18', 6.54, 'https://image.tmdb.org/t/p/w500/wzdtagMTNao7l4zuJ1i8usSfEwz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (274854, 'The Last Witch Hunter', 'The modern world holds many secrets, but by far the most astounding is that witches still live among us; vicious supernatural creatures intent on unleashing the Black Death upon the world and putting an end to the human race once and for all. Armies of witch hunters have battled this unnatural enemy for centuries, including Kaulder, a valiant warrior who many years ago slayed the all-powerful Witch Queen, decimating her followers in the process. In the moments right before her death, the Queen cursed Kaulder with immortality, forever separating him from his beloved wife and daughter. Today, Kaulder is the last living hunter who has spent his immortal life tracking down rogue witches, all the while yearning for his long-lost family.', '2015-10-21', 6.01, 'https://image.tmdb.org/t/p/w500/dS9YdnJkxtKE2PKCSsxTaO7Jpf5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (267193, 'Grimsby', 'Wrongfully accused and on the run, a top MI6 assassin joins forces with his long-lost, football hooligan brother to save the world from a sinister plot.', '2016-02-24', 5.95, 'https://image.tmdb.org/t/p/w500/2jQGFmShpdflApc5oidJZ97m1d1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (283350, 'Before We Go', 'A chance encounter between two strangers in Grand Central Terminal sparks a life-changing, nighttime sojourn through New York City. They grow into each other''s most trusted confidants when an evening of unexpected adventure forces them to confront their fears and take control of their lives.', '2014-09-04', 6.74, 'https://image.tmdb.org/t/p/w500/qBnkNKjbJV0E8GvEPidBS1nIRWD.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (280276, 'Turtle Power: The Definitive History of the Teenage Mutant Ninja Turtles', 'In the spring of 1984, a strange new comic book sat beside cash registers in select shops, too big to fit in the racks, and too weird to ignore. Eastman and Laird''s Teenage Mutant Ninja Turtles presented a completely original breed of super hero. It was too bizarre, too crazy. It broke all the rules and should never have worked. Until it sold out. Again and again and again. For 30 years. Now, peek under the shell and see how this so-called "happy accident" defied every naysayer to become one of the most popular and beloved franchises in the world.', '2014-08-12', 7.43, 'https://image.tmdb.org/t/p/w500/8O4Y6fNxHaHwiI8SQpQekCJlnfz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (274855, 'Geostorm', 'After an unprecedented series of natural disasters threatened the planet, the world''s leaders came together to create an intricate network of satellites to control the global climate and keep everyone safe. But now, something has gone wrong: the system built to protect Earth is attacking it, and it becomes a race against the clock to uncover the real threat before a worldwide geostorm wipes out everything and everyone along with it.', '2017-10-12', 6.12, 'https://image.tmdb.org/t/p/w500/nrsx0jEaBgXq4PWo7SooSnYJTv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (283366, 'Miss Peregrine''s Home for Peculiar Children', 'A teenager finds himself transported to an island where he must help protect a group of orphans with special powers from creatures intent on destroying them.', '2016-09-28', 6.84, 'https://image.tmdb.org/t/p/w500/CIlbMFOfYDj0MP23hsIYhFGrL6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (273481, 'Sicario', 'An idealistic FBI agent is enlisted by a government task force to aid in the escalating war against drugs at the border area between the U.S. and Mexico.', '2015-09-17', 7.40, 'https://image.tmdb.org/t/p/w500/lz8vNyXeidqqOdJW9ZjnDAMb5Vr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (284276, 'Cake', 'After having visions of a member of her support group who killed herself, a woman who also suffers with chronic pain seeks out the widower of the suicide.', '2014-09-07', 6.28, 'https://image.tmdb.org/t/p/w500/5GJEZovjtKisJxNMG6fBTCxNzZi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (282848, 'Doctor Who: The Time of the Doctor', 'Orbiting a quiet backwater planet, the massed forces of the universe''s deadliest species gather, drawn to a mysterious message that echoes out to the stars. And amongst them, the Doctor. Rescuing Clara from a family Christmas dinner, the Time Lord and his best friend must learn what this enigmatic signal means for his own fate and that of the universe.', '2013-12-25', 8.07, 'https://image.tmdb.org/t/p/w500/8GSVpMPlvymndYheKMtQb1aLDBh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (284293, 'Still Alice', 'Alice Howland, happily married with three grown children, is a renowned linguistics professor who starts to forget words. When she receives a devastating diagnosis, Alice and her family find their bonds tested.', '2014-12-05', 7.46, 'https://image.tmdb.org/t/p/w500/jJiGGbuLW8IkEnh5073maEmIr7V.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (284296, 'Top Five', 'Though he began in stand-up comedy, Andre Allen hit the big-time as the star of a trilogy of action-comedies about a talking bear but now he wants to be taken seriously. His passion project about the Haitian Revolution, a movie called Uprize, was panned by the NY Times film critic. A couple days before the wedding to his reality star fiancée, he''s forced to spend the day with Chelsea Brown, a profile writer for the New York Times. Unexpectedly, he opens up to her, and as they wind their way across New York, he tries to get back in touch with his comedic roots.', '2014-12-12', 6.07, 'https://image.tmdb.org/t/p/w500/hNFhzLpg3A34p9qFXXIBJfQIMoK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (284303, 'Goodnight Mommy', 'In the heat of the summer lays a lonesome house in the countryside where nine year old twin brothers await their mother’s return.  When she comes home, bandaged after cosmetic surgery, nothing is like before and the children start to doubt whether this woman is actually who she says she is.', '2015-01-08', 6.68, 'https://image.tmdb.org/t/p/w500/u3G2gF7M9dmH4Vcs54PUjieOi0C.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (284427, 'Who Am I', 'Benjamin, a young German computer whiz, is invited to join a subversive hacker group that wants to be noticed on the world''s stage.', '2014-09-25', 7.56, 'https://image.tmdb.org/t/p/w500/oR3tbNzJMJmCKS5O5fanU9yxIOk.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (284514, 'Spy Time', 'Adolfo, a thirty something security guard, is going through a bad patch. Not only his lifetime girlfriend has just to finished with him to be a guy with no ambition but, moreover, he becomes the target of a series of thugs led by Vázquez, a dangerous criminal who has just escaped from jail. Also he discovers that his father has a double identity. He is not a farmer engaged in the production of cold meat – as Adolfo has believed all his life, but Anacleto, a secret agent who is a bit down and the man who locked Vázquez up in jail thirty years ago. Adolfo will have to leave his comfort zone and work with his father, the person that Adolfo get on worse with in the world to survive the revenge of Vazquez and while, between shootouts and chases, trying to get his girlfriend back.', '2015-09-04', 5.70, 'https://image.tmdb.org/t/p/w500/fRAlUIsJ0yfcAslfMIZOPm6ftUS.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (284536, 'The Gambler', 'Literature professor Jim Bennett leads a secret life as a high-stakes gambler. Always a risk-taker, Bennett bets it all when he borrows from a gangster and offers his own life as collateral. Staying one step ahead, he pits his creditor against the operator of an illicit gambling ring while garnering the attention of Frank, a paternalistic loan shark. As his relationship with a student deepens, Bennett must risk everything for a second chance.', '2014-12-25', 6.05, 'https://image.tmdb.org/t/p/w500/hIgU3cxn7Y87joQGM3srofnXOm5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
