INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (285700, 'The Fool', 'The Fool is a movie about a simple plumber. An honest man, he is up against an entire system of corrupted bureaucrats. At stake are the lives of 800 inhabitants of an old dorm that is at risk of collapsing within the span of the night.', '2014-08-09', 7.80, 'https://image.tmdb.org/t/p/w500/jJOuPUrkpUDETHqfZU0hXWvuWU0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
