INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (286217, 'The Martian', 'During a manned mission to Mars, Astronaut Mark Watney is presumed dead after a fierce storm and left behind by his crew. But Watney has survived and finds himself stranded and alone on the hostile planet. With only meager supplies, he must draw upon his ingenuity, wit and spirit to subsist and find a way to signal to Earth that he is alive.', '2015-09-30', 7.71, 'https://image.tmdb.org/t/p/w500/fASz8A0yFE3QB6LgGoOfwvFSseV.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (286532, 'A Merry Friggin'' Christmas', 'Boyd Mitchler and his family must spend Christmas with his estranged family of misfits. Upon realizing that he left all his son''s gifts at home, he hits the road with his dad in an attempt to make the 8-hour round trip before sunrise.', '2014-11-07', 5.30, 'https://image.tmdb.org/t/p/w500/yiBwooPaWWPI0Q3B8XqvY6AJn3L.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (286554, 'Two Night Stand', 'After an extremely regrettable one night stand, two strangers wake up to find themselves snowed in after sleeping through a blizzard that put all of Manhattan on ice. They''re now trapped together in a tiny apartment, forced to get to know each other way more than any one night stand should.', '2014-09-26', 6.41, 'https://image.tmdb.org/t/p/w500/rz0YnlHieXP9SBuJU4ANBW8ttIw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (286565, 'Paper Towns', 'Quentin Jacobsen has spent a lifetime loving the magnificently adventurous Margo Roth Spiegelman from afar. So when she cracks open a window and climbs back into his life dressed like a ninja and summoning him for an ingenious campaign of revenge, he follows. After their all-nighter ends and a new day breaks, Quentin arrives at school to discover that Margo, always an enigma, has now become a mystery. But Quentin soon learns that there are clues, and they''re for him. Urged down a disconnected path, the closer Quentin gets, the less he sees of the girl he thought he knew.', '2015-06-18', 6.16, 'https://image.tmdb.org/t/p/w500/lVW67w7eWwmBhbBCc4f983pO8m6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
