INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (287903, 'Krampus', 'When his dysfunctional family clashes over the holidays, young Max is disillusioned and turns his back on Christmas.  Little does he know, this lack of festive spirit has unleashed the wrath of Krampus: a demonic force of ancient evil intent on punishing non-believers.', '2015-11-26', 6.21, 'https://image.tmdb.org/t/p/w500/sAolMRD9rFSTU7tssfFuLEJJa7w.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (288171, 'Blue Mountain State: The Rise of Thadland', 'With Blue Mountain State football star Thad Castle recently signing a multi-million dollar NFL contract, his teammates and college life seem like a distant memory. However, when a new school dean threatens to clean up the BMS image by auctioning off the infamous Goat House, Alex, Sammy and the boys must find a way to convince him to get involved. Despite his new fortune and fame, there is one small favor that Thad needs done before he saves the day: the biggest booze-and-sloot fest in BMS history. Welcome to Thadland!', '2016-02-02', 5.57, 'https://image.tmdb.org/t/p/w500/rZz8AmDvFqUY4tBcD69ou3OfiWx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (289333, 'Jim Jefferies: Bare', 'Smart, crude, and in-your-face, Australian comic/actor/equal-opportunity-offender Jim Jefferies is not for the faint of heart. Whether he is lampooning gun control, auditioning disabled actors, or over-sharing sexual experiences, the FXX "Legit" star proves nothing is out of bounds and even less, off limits. Filmed during the Boston run of his recent stand up tour.', '2014-08-29', 7.55, 'https://image.tmdb.org/t/p/w500/pqGtStSCU0F3cZyEItCaqol24Mi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
