INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (273895, 'Selma', '"Selma," as in Alabama, the place where segregation in the South was at its worst, leading to a march that ended in violence, forcing a famous statement by President Lyndon B. Johnson that ultimately led to the signing of the Voting Rights Act.', '2014-12-25', 7.37, 'https://image.tmdb.org/t/p/w500/2QyUcitU0hrxy6B2zkyJ0EhNlqm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
