INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (282069, 'Parasyte: Part 1', 'Humanity is suffering from a series of mysterious murders across the globe, known as the ''Mincemeat murders''. High school student Izumi Shinichi has a parasite living off him, having replaced his right hand, and he might be the discoverer of truth.', '2014-11-29', 7.04, 'https://image.tmdb.org/t/p/w500/lNzCFguC8wEyJWP89ewQYK8d2nJ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
