INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (282070, 'Parasyte: Part 2', 'Humanity is under attack by human-mimicking flesh-eating alien parasites. One parasite bonds with his young high school student host, and he convinces the parasite to help him stop the others.', '2015-04-25', 7.00, 'https://image.tmdb.org/t/p/w500/qO8zQ9dSADWiwRnR7oCOsPDuOom.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (294016, 'Trumbo', 'The career of screenwriter Dalton Trumbo is halted by a witch hunt in the late 1940s when he defies the anti-communist HUAC committee and is blacklisted.', '2015-10-27', 7.17, 'https://image.tmdb.org/t/p/w500/2RERIRnZkROSeHZAIf8PSxhzOqs.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (294254, 'Maze Runner: The Scorch Trials', 'Thomas and his fellow Gladers face their greatest challenge yet: searching for clues about the mysterious and powerful organization known as WCKD. Their journey takes them to the Scorch, a desolate landscape filled with unimaginable obstacles. Teaming up with resistance fighters, the Gladers take on WCKD’s vastly superior forces and uncover its shocking plans for them all.', '2015-09-09', 6.73, 'https://image.tmdb.org/t/p/w500/mYw7ZyejqSCPFlrT2jHZOESZDU3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (294272, 'Pete''s Dragon', 'For years, old wood carver Mr. Meacham has delighted local children with his tales of the fierce dragon that resides deep in the woods of the Pacific Northwest. To his daughter, Grace, who works as a forest ranger, these stories are little more than tall tales... until she meets Pete, a mysterious 10-year-old with no family and no home who claims to live in the woods with a giant, green dragon named Elliott. And from Pete''s descriptions, Elliott seems remarkably similar to the dragon from Mr. Meacham''s stories. With the help of Natalie, an 11-year-old girl whose father Jack owns the local lumber mill, Grace sets out to determine where Pete came from, where he belongs, and the truth about this dragon.', '2016-08-10', 6.39, 'https://image.tmdb.org/t/p/w500/A9x4Ogk8KUXTfU649NS6lS9TCmu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (294538, 'Hit by Lightning', 'Ricky Miller, a 40-something restaurant manager and aspiring writer is desperately looking for love. Danita is looking for someone to kill her celebrity husband. When their worlds collide on an online dating site, Ricky is ecstatic he has found the woman of his dreams. Now all that stands between him and true love is how to get away with murder.', '2014-10-31', 4.70, 'https://image.tmdb.org/t/p/w500/9jveY5ak0bmEWpJaQTLFPB2dUwu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (294652, 'Son of a Gun', 'Locked up for a minor crime, 19 year old JR quickly learns the harsh realities of prison life. Protection, if you can get it, is paramount. JR soon finds himself under the watchful eye of Australia''s most notorious criminal, Brendan Lynch, but protection comes at a price.', '2014-10-16', 6.43, 'https://image.tmdb.org/t/p/w500/yRLVyhQfkW2hn15e8NIqarswLAr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (294963, 'Bone Tomahawk', 'During a shootout in a saloon, Sheriff Hunt injures a suspicious stranger. The doctor''s assistant, wife of the local foreman, tends to him in prison. That night, the town is attacked and they both disappear—only the arrow of a cannibal tribe is found. Hunt and a few of his men go in search of the prisoner and the foreman''s wife.', '2015-10-23', 6.89, 'https://image.tmdb.org/t/p/w500/4MmTHpn2Y8emqvBgvOjufImUmKZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (274870, 'Passengers', 'A spacecraft traveling to a distant colony planet and transporting thousands of people has a malfunction in its sleep chambers. As a result, two passengers are awakened 90 years early.', '2016-12-21', 6.96, 'https://image.tmdb.org/t/p/w500/jK9S6HANSf2no64v1x1HxfcpmcA.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (295315, 'Sex Ed', 'Eddie lands his first teaching gig at an inner city middle school and finds his highly pubescent pupils are receiving no form of sexual education. Eddie isn''t really equipped to teach them...he''s not exactly experienced romantically.', '2014-11-07', 5.26, 'https://image.tmdb.org/t/p/w500/wDPjTT14pIbKs5r1ZJazRsDwTRQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (295693, 'The Boss Baby', 'A story about how a new baby''s arrival impacts a family, told from the point of view of a delightfully unreliable narrator, a wildly imaginative 7 year old named Tim.', '2017-03-23', 6.45, 'https://image.tmdb.org/t/p/w500/9MsQJKe4cUAGxc7R2NGaFQLqOPc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
