INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (298533, 'Corner Gas: The Movie', 'It’s been a few years, and there’s still not a lot going on 40 kilometers from nowhere. But that’s all about to change as the fine folks of Dog River, Saskatchewan face their biggest crisis ever. Brent and the gang discover that the town’s been badly mismanaged, leaving residents with little choice but to pack up and leave. As residents make one last rally to save Dog River as they know it, they discover a devious plan by a corporate chain that would change life for Dog Riverites forever.', '2014-12-03', 6.11, 'https://image.tmdb.org/t/p/w500/3Foy86VCs8MZhTieDsglSTm4xMU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (293299, 'Feast', 'This Oscar-winning animated short film tells the story of one man''s love life as seen through the eyes of his best friend and dog, Winston, and revealed bite by bite through the meals they share.', '2014-10-25', 7.83, 'https://image.tmdb.org/t/p/w500/6hAgSxgd2YIK5pYhwowtnlGpwbe.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (297725, 'The Man Who Killed Don Quixote', 'Toby, a cynical film director finds himself trapped in the outrageous delusions of an old Spanish shoe-maker who believes himself to be Don Quixote. In the course of their comic and increasingly surreal adventures, Toby is forced to confront the tragic repercussions of a film he made in his idealistic youth.', '2018-05-19', 6.73, 'https://image.tmdb.org/t/p/w500/4o4zw2c9sfHvszIb5xpuFagnouR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (298718, 'Dane Cook: Troublemaker', 'Comedian Dane Cook knows how to stir it up with his patented brand of observational humor, skewering aspects of modern life, from our hidden Internet selves to gender taboos and everything in between, in this exclusive comedy event.', '2014-10-17', 7.00, 'https://image.tmdb.org/t/p/w500/rXJHq7yQ92IuTAIxAYKUILvjVLU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
