INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (301566, 'Too Many Cooks', '"Too Many Cooks" is a humorous parody of US sitcoms of the 1970s and the 1980s, meanwhile what seems like an interminable opening theme, a mysterious killer makes his way and kills (preparing a lunch with their limbs) various members of the Cook Family.', '2014-10-28', 7.65, 'https://image.tmdb.org/t/p/w500/mloofB4SaWLJCh1eGHb0dPvVybE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
