INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (301748, 'The Opposite Sex', 'The story of Vince, New England''s most successful divorce attorney. To Vince, life is one big competition, and losing is unacceptable. This also applies in his dating life with his love ''em and leave ''em approach. Then Vince meets Jane, who is beautiful, successful and also extremely driven. Together they enter into a series of entertaining wagers with each other where the winner gets to decide the fate of the loser.', '2015-01-22', 4.49, 'https://image.tmdb.org/t/p/w500/4OGyobNioLlo1aj4ioxxmsssSCj.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (302026, 'Garm Wars: The Last Druid', 'In a world where clone soldiers from three military tribes are locked in a perpetual battle of air, land and technology, one clone is separated from the battle and finds herself on the run with a group of unlikely companions.', '2014-10-24', 4.64, 'https://image.tmdb.org/t/p/w500/cz3tMdY7XPjzhEWH7hdKOn3doJ1.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
