INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (302699, 'Central Intelligence', 'Calvin Joyner, a mild-mannered accountant whose high school glory days are long behind him, reconnects with an awkward pal from high school through Facebook. After meeting up, Calvin’s mundane life takes an unexpectedly thrilling turn when he''s thrust into the world of international espionage.', '2016-06-15', 6.42, 'https://image.tmdb.org/t/p/w500/hXQVMbRNpf7c93e8clMY4W5DRm6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
