INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (303623, 'Hello Ladies: The Movie', 'When Stuart learns that his British ex-girlfriend is planning to visit Los Angeles with her husband, he sets out to impress them with his glamorous lifestyle, enlisting a flaky Russian model he’s just met to play the role of his beautiful girlfriend. What could go wrong?', '2014-11-22', 6.46, 'https://image.tmdb.org/t/p/w500/7O41oM6Va5wffkIjunwqAoseNs9.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (290595, 'The Huntsman: Winter''s War', 'As two evil sisters prepare to conquer the land, two renegades—Eric the Huntsman, who aided Snow White in defeating Ravenna in Snowwhite and the Huntsman, and his forbidden lover, Sara—set out to stop them.', '2016-04-06', 6.29, 'https://image.tmdb.org/t/p/w500/ekHPrneEoa1EoDclWdillOKznqM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (303854, 'Front Cover', 'One man does all he can to veil his Asian heritage; the other takes great pains to hide his sexual orientation. Both of these things begin to change when Ryan is hired to prepare film star Ning for a fashion shoot, and the men develop a bond.', '2016-08-05', 5.84, 'https://image.tmdb.org/t/p/w500/be0a79Xhbhmik12AYmYITz39zxN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (303857, 'Dragon Ball Z: Resurrection ''F''', 'One peaceful day on Earth, two remnants of Frieza''s army named Sorbet and Tagoma arrive searching for the Dragon Balls with the aim of reviving Frieza. They succeed, and Frieza subsequently seeks revenge on the Saiyans.', '2015-04-18', 6.89, 'https://image.tmdb.org/t/p/w500/soq3AxjALdBfdPAm8H7yuMmNL5Y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
