INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (304357, 'Woman in Gold', 'Maria Altmann, an octogenarian Jewish refugee, takes on the government to recover artwork she believes rightfully belongs to her family.', '2015-03-20', 7.27, 'https://image.tmdb.org/t/p/w500/6eoj6bozvgwNuDV3vOrqlvrCrX.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (290999, 'Wyrmwood: Road of the Dead', 'Barry is a talented mechanic and family man whose life is torn apart on the eve of a zombie apocalypse. His sister, Brooke, is kidnapped by a sinister team of gas-mask wearing soldiers and experimented on by a psychotic doctor. While Brooke plans her escape Barry goes out on the road to find her and teams up with Benny, a fellow survivor – together they must arm themselves and prepare to battle their way through hordes of flesh-eating monsters in a harsh Australian bushland.', '2014-09-19', 6.07, 'https://image.tmdb.org/t/p/w500/8UYcvCYMFRYFzmW1LVm3S9RGCfN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (304372, 'The Perfect Guy', 'With a fulfilling career and a loving relationship, lobbyist Leah Vaughn seems to have it all. Things come crashing down when Dave, her long-term boyfriend, disagrees with her future plans for marriage and a family. The resulting painful breakup leaves Leah heartbroken, until she meets the charming and handsome Carter Duncan. Soon, the budding romance turns dangerous as Carter reveals his volatile nature, forcing Leah to break up with the man she thought was Mr. Right. She soon realizes that Carter doesn''t want to let her go.', '2015-09-11', 5.73, 'https://image.tmdb.org/t/p/w500/k1U3ROFFCVbu9H63lKYMbXEHeJI.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (306482, 'Partisan', 'On the edge of a crumbling city, 11-year-old Alexander lives in a sequestered commune alongside other children, their mothers, and charismatic leader, Gregori. Gregori teaches the children how to raise livestock, grow vegetables, work as a community - and how to kill. With the birth of a new baby brother weighing on his mind, Alexander begins to question Gregori’s overpowering influence on the children and their training to become assassins. Threatened by his increasing unwillingness to fall in line, Gregori’s behavior turns erratic and adversarial toward the child he once considered a son. With the two set dangerously at odds and the commune’s way of life disintegrating, the residents fear a violent resolution is at hand.', '2015-04-29', 6.11, 'https://image.tmdb.org/t/p/w500/4x7gzun1Llfgt9AtMj9Jx8druIF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (300669, 'Don''t Breathe', 'A group of teens break into a blind man''s home thinking they''ll get away with the perfect crime. They''re wrong.', '2016-06-08', 7.02, 'https://image.tmdb.org/t/p/w500/dSxHyPZ2nipSfvdft4IhQKjk5eZ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (293670, 'The Wailing', 'A stranger arrives in a little village and soon after a mysterious sickness starts spreading. A policeman is drawn into the incident and is forced to solve the mystery in order to save his daughter.', '2016-05-12', 7.38, 'https://image.tmdb.org/t/p/w500/lWE9ih9qgjx8HatYboP7fG0nri.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (291870, 'Dirty Grandpa', 'Jason Kelly is one week away from marrying his boss''s uber-controlling daughter, putting him on the fast track for a partnership at the law firm. However, when the straight-laced Jason is tricked into driving his foul-mouthed grandfather, Dick, to Daytona for spring break, his pending nuptials are suddenly in jeopardy. Between riotous frat parties, bar fights, and an epic night of karaoke, Dick is on a quest to live his life to the fullest and bring Jason along for the ride.', '2016-01-20', 5.94, 'https://image.tmdb.org/t/p/w500/k0Lz1TfSlbcQthQKYGwE7blDfwN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
