INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (307081, 'Southpaw', 'Billy "The Great" Hope, the reigning junior middleweight boxing champion, has an impressive career, a loving wife and daughter, and a lavish lifestyle. However, when tragedy strikes, Billy hits rock bottom, losing his family, his house and his manager. He soon finds an unlikely savior in Tick Willis, a former fighter who trains the city''s toughest amateur boxers. With his future on the line, Hope fights to reclaim the trust of those he loves the most.', '2015-07-22', 7.36, 'https://image.tmdb.org/t/p/w500/kSQ49Fi3NVTqGGXILmxV2T2pdkG.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
