INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (298382, 'The Dressmaker', 'In 1950s Australia, beautiful, talented dressmaker Tilly returns to her tiny hometown to right wrongs from her past. As she tries to reconcile with her mother, she starts to fall in love while transforming the fashion of the town.', '2015-10-29', 7.00, 'https://image.tmdb.org/t/p/w500/5Loofmo5GTt1Qe2Dz5ERLVlN98T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (305470, 'Power Rangers', 'Five ordinary teens must become something extraordinary when they learn that their small town of Angel Grove — and the world — is on the verge of being obliterated by an alien threat. Chosen by destiny, our heroes quickly discover they are the only ones who can save the planet. But to do so, they will have to overcome their real-life issues and before it’s too late, band together as the Power Rangers.', '2017-03-23', 6.25, 'https://image.tmdb.org/t/p/w500/bKYKyyIv5YnisxjZtDreWtYA386.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (303991, 'Demolition', 'An emotionally desperate investment banker finds hope through a woman he meets.', '2016-04-06', 6.85, 'https://image.tmdb.org/t/p/w500/4t56LZ1KbOOxgKfqMKN6truBDVc.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (305091, 'That Sugar Film', 'One man''s journey to discover the bitter truth about sugar. Damon Gameau embarks on a unique experiment to document the effects of a high sugar diet on a healthy body, consuming only foods that are commonly perceived as ''healthy''. Through this entertaining and informative journey, Damon highlights some of the issues that plague the sugar industry, and where sugar lurks on supermarket shelves.', '2014-07-31', 6.86, 'https://image.tmdb.org/t/p/w500/qF1fDtJ1vU3hrLDNJCgRoQekFmM.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
