INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (309503, 'Zipper', 'Sam Ellis is a man on the rise — a hot-shot federal prosecutor on the cusp of a bright political future. But what was meant to be a one-time experience with an escort turns into a growing addiction — a new demon threatening to destroy his life, family, and career.', '2015-08-28', 5.50, 'https://image.tmdb.org/t/p/w500/qHQbXfdYhh3CRtIufoiD4AxPWi0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (309809, 'The Little Prince', 'Based on the best-seller book ''The Little Prince'', the movie tells the story of a little girl that lives with resignation in a world where efficiency and work are the only dogmas. Everything will change when accidentally she discovers her neighbor that will tell her about the story of the Little Prince that he once met.', '2015-07-29', 7.62, 'https://image.tmdb.org/t/p/w500/je5Z7gbFTzrs3FPHINo9yGiHoVo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (306819, 'The Danish Girl', 'When Gerda Wegener asks her husband Einar to fill in as a portrait model, Einar discovers the person she''s meant to be and begins living her life as Lili Elbe. Having realized her true self and with Gerda''s love and support, Lili embarks on a groundbreaking journey as a transgender pioneer.', '2015-11-27', 7.54, 'https://image.tmdb.org/t/p/w500/kiJTZ5oFRO961wWn7mLxjUcRlf3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
