INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (310131, 'The Witch', 'In 1630, a farmer relocates his family to a remote plot of land on the edge of a forest where strange, unsettling things happen. With suspicion and paranoia mounting, each family member''s faith, loyalty and love are tested in shocking ways.', '2016-02-19', 7.00, 'https://image.tmdb.org/t/p/w500/zap5hpFCWSvdWSuPGAQyjUv2wAC.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
