INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (309887, 'Bad Asses on the Bayou', 'The third installment in the successful Bad Ass action-comedy franchise. Bad Asses on the Bayou reunites the dynamic duo, Frank Vega and Bernie Pope, as they travel to Louisiana to attend the wedding of their dear friend Carmen Gutierrez. What was pictured as a wedding weekend escape to the south turns violently ugly as madness and mayhem ensue, pressing our senior heroes to once again serve justice.', '2015-03-06', 6.00, 'https://image.tmdb.org/t/p/w500/moZSQaD6GPRELWZO9qbRJjzq7re.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
