INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (300668, 'Annihilation', 'A biologist signs up for a dangerous, secret expedition into a mysterious zone where the laws of nature don''t apply.', '2018-02-22', 6.45, 'https://image.tmdb.org/t/p/w500/4YRplSk6BhH6PRuE9gfyw9byUJ6.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
