INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (330764, 'The Brand New Testament', 'God lives in Brussels. On Earth though, God is a coward, morally pathetic and odious to his family. His daughter, Ea, is bored at home and can''t stand being locked up in a small apartment in ordinary Brussels, until the day she decides to revolt against her dad...', '2015-09-02', 6.65, 'https://image.tmdb.org/t/p/w500/eRKgcuXSP9KiGlh2tlS85oh6ceN.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
