INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (325173, 'Close Range', 'A rogue soldier turned outlaw is thrust into a relentless fight with a corrupt sheriff, his obedient deputies, and a dangerous drug cartel in order to protect his sister and her young daughter.', '2015-11-19', 6.50, 'https://image.tmdb.org/t/p/w500/pzE3dfnmiNqjqLygS4HbMADFKa8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (333287, 'Slow Learners', 'High school guidance counselor Jeff and his platonic friend and co-worker Anne are responsible, well intentioned, kind… and boring. They frustratingly watch on as their peers find love and companionship, while they continue to fail in spectacular fashion when it comes to romance. As they reach their loneliness breaking point, they make a pact to forgo their familiar, vanilla personas in exchange for their unexplored, confident alter egos. They wave goodbye to Jeff’s awkward all-male book club and Anne’s flailing attempts to catch the eye of Jeff’s sexy neighbor Max, and say hello to raucous summer nights filled with booze, dancing, and sex. Naturally things don’t exactly go according to plan.', '2015-08-19', 5.76, 'https://image.tmdb.org/t/p/w500/rDxDSABzncDluXgqCQjjMjYej96.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
