INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (337154, 'The Meddler', 'With a new iPhone, an apartment near the Grove, and a comfortable bank account left to her by her beloved late husband, Marnie Minervini has happily relocated from New Jersey to Los Angeles to be near her daughter Lori, a successful (but still single) screenwriter, and smother her with motherly love. But when the dozens of texts, unexpected visits, and conversations dominated by unsolicited advice force Lori to draw strict personal boundaries, Marnie finds ways to channel her eternal optimism and forceful generosity to change the lives of others - as well as her own - and find a new purpose in life.', '2016-04-05', 5.95, 'https://image.tmdb.org/t/p/w500/rzj9ZSleGgsKkY3q6sDDoAxjSu0.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
