INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (327536, 'Bakuman', 'Moritaka Mashiro doesn''t want to follow in the path of his uncle who worked as a manga artist, but ultimately died because of exhaustion. Moritaka Mashiro figures he will graduate from school and work at an office. Things change though when falls in love with a girl at school. The girl, who hopes to become a voice actress, tells Moritaka they can marry, but only after they both achieve their dreams. Moritaka then teams up with fellow classmate Akito Takagi to publish their first manga.', '2015-10-03', 6.40, 'https://image.tmdb.org/t/p/w500/kaf6zS27Oll9ja55PYMC7OpB8oa.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
