INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (326423, 'Barbershop: The Next Cut', 'To survive harsh economic times, Calvin and Angie have merged the barbershop and beauty salon into one business. The days of male bonding are gone as Eddie and the crew must now contend with sassy female co-workers and spirited clientele. As the battle of the sexes rages on, a different kind of conflict has taken over Chicago. Crime and gangs are on the rise, leaving Calvin worried about the fate of his son. Together, the friends come up with a bold plan to take back their beloved neighborhood.', '2016-04-15', 6.29, 'https://image.tmdb.org/t/p/w500/9mwzidlGgWfr2hcMWUKM86lOqdo.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
