INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (339396, 'True Memoirs of an International Assassin', 'After a publisher changes a writer''s debut novel about a deadly assassin from fiction to nonfiction, the author finds himself thrust into the world of his lead character, and must take on the role of his character for his own survival.', '2016-11-11', 5.76, 'https://image.tmdb.org/t/p/w500/hPoSSqDqkKSIP2l3t6pyre9u5Ze.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
