INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (341174, 'Fifty Shades Darker', 'When a wounded Christian Grey tries to entice a cautious Ana Steele back into his life, she demands a new arrangement before she will give him another chance. As the two begin to build trust and find stability, shadowy figures from Christian’s past start to circle the couple, determined to destroy their hopes for a future together.', '2017-02-08', 6.47, 'https://image.tmdb.org/t/p/w500/w3qa274gvca9t8pkUoG8nfQgTU3.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
