INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (343611, 'Jack Reacher: Never Go Back', 'Years after resigning command of an elite military police unit, the nomadic, righter-of-wrongs Reacher is drawn back into the life he left behind when his friend and successor, Major Susan Turner is framed for espionage. Reacher will stop at nothing to prove her innocence and to expose the real perpetrators behind the killings of his former soldiers.', '2016-10-19', 6.03, 'https://image.tmdb.org/t/p/w500/cOg3UT2NYWHZxp41vpxAnVCOC4M.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
