INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (333377, 'Requiem for the American Dream', 'Through interviews filmed over four years, Noam Chomsky unpacks the principles that have brought us to the crossroads of historically unprecedented inequality – tracing a half-century of policies designed to favor the most wealthy at the expense of the majority – while also looking back on his own life of activism and political participation. He provides penetrating insight into what may well be the lasting legacy of our time – the death of the middle class, and swan song of functioning democracy.', '2015-04-18', 7.71, 'https://image.tmdb.org/t/p/w500/z30fIUchddu5RPUN8JWFiDhk2yp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
