INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (359025, 'Camino', 'A photojournalist gets more than she bargained for when she snaps a photo of a shadowy religious figure in the jungles of Colombia, triggering a flight – and fight – for her life.', '2016-03-04', 4.86, 'https://image.tmdb.org/t/p/w500/4DOzp5Rx8roC9YvvDgmoZAGeiGF.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (351065, 'Zoom', 'A multi-dimensional interface between a comic book artist, a novelist, and a film director. Each lives in a separate reality but authors a story about one of the others.', '2016-03-31', 5.85, 'https://image.tmdb.org/t/p/w500/gbyJSsrJyIOyr9o12B5A2Zsix4T.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (359364, 'Human', 'A collection of stories about and images of our world, offering an immersion to the core of what it means to be human. Through these stories full of love and happiness, as well as hatred and violence, it brings us face to face with the Other, making us reflect on our lives. From stories of everyday experiences to accounts of the most unbelievable lives, these poignant encounters share a rare sincerity and underline who we are – our darker side, but also what is most noble in us, and what is universal. Our Earth is shown at its most sublime through never-before-seen aerial images accompanied by soaring music, resulting in an ode to the beauty of the world, providing a moment to draw breath and for introspection. This film is a politically engaged work which allows us to embrace the human condition and to reflect on the meaning of our existence.', '2015-09-12', 8.43, 'https://image.tmdb.org/t/p/w500/l02W63OGQKYugJrs3Uw8nA9gii4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (357786, 'Kizumonogatari Part 1: Tekketsu', 'One day, Koyomi Araragi encounters the horrifying vampire, Kiss-shot Acerola-orion Heart-under-blade A.K.A. the "King of Apparitions." He saves the fatally wounded Kiss-shot by offering his blood at the expense of his own life as a human. Now Koyomi has to face the vampire hunters to retrieve Kiss-shot’s limbs which were taken by these hunters...', '2016-01-08', 7.70, 'https://image.tmdb.org/t/p/w500/vftYhVOdvMCmb0dQIRIKmUYG9TU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
