INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (359871, 'My Scientology Movie', 'After being denied access to the Church of Scientology''s headquarters, documentarian Louis Theroux teams up with ex-Scientology official Marty Rathbun to stage re-enactments of alleged abuses within the organization. Theroux soon discovers that the church is watching his every move.', '2016-05-05', 6.58, 'https://image.tmdb.org/t/p/w500/mTAZFb79cum6bfU41C96DwMCp6Y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
