INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (339964, 'Valerian and the City of a Thousand Planets', 'In the 28th century, Valerian and Laureline are special operatives charged with keeping order throughout the human territories. On assignment from the Minister of Defense, the two undertake a mission to Alpha, an ever-expanding metropolis where species from across the universe have converged over centuries to share knowledge, intelligence, and cultures. At the center of Alpha is a mysterious dark force which threatens the peaceful existence of the City of a Thousand Planets, and Valerian and Laureline must race to identify the menace and safeguard not just Alpha, but the future of the universe.', '2017-07-19', 6.65, 'https://image.tmdb.org/t/p/w500/vlc95gl3PtrjxSEuM8RhTtSm2xU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
