INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (377448, 'The Rocky Horror Picture Show: Let''s Do the Time Warp Again', 'After getting a flat tire in the middle of nowhere, newly engaged couple Brad and Janet encounter the eerie mansion of the flamboyant, seductive Dr. Frank-N-Furter and a variety of eccentric characters. Through elaborate dance and rock music, the mad scientist unveils his latest creation: a perfect, muscular man.', '2016-10-20', 5.10, 'https://image.tmdb.org/t/p/w500/56KEpnJWe5KvpiPu5XmK14L7Wyr.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (377462, 'O.J.: Made in America', 'A chronicle of the rise and fall of O.J. Simpson, whose high-profile murder trial exposed the extent of American racial tensions, revealing a fractured and divided nation.', '2016-05-20', 8.40, 'https://image.tmdb.org/t/p/w500/nFmg2G4IJ0x9mALXkYFN8Gw0Dw5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (377492, 'Dirty 30', 'On the eve of a Kate''s 30th birthday, she agrees to let her two lifelong friends, Evie and Charlie, throw her a party. But what''s supposed to be a simple celebration becomes a wild who''s who of past and present, and things quickly spiral out of control.', '2016-09-23', 5.80, 'https://image.tmdb.org/t/p/w500/rRDdvaJsiZimm1enx2ApkCxaee4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (378018, 'The Void', 'In the middle of a routine patrol, officer Daniel Carter happens upon a blood-soaked figure limping down a deserted stretch of road. He rushes the young man to a nearby rural hospital staffed by a skeleton crew, only to discover that patients and personnel are transforming into something inhuman. As the horror intensifies, Carter leads the other survivors on a hellish voyage into the subterranean depths of the hospital in a desperate bid to end the nightmare before it''s too late.', '2016-09-22', 6.01, 'https://image.tmdb.org/t/p/w500/xY6DmuBP6xSxs2TtPXkcP9wIXdd.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (378064, 'A Silent Voice: The Movie', 'Shouya Ishida starts bullying the new girl in class, Shouko Nishimiya, because she is deaf. But as the teasing continues, the rest of the class starts to turn on Shouya for his lack of compassion. When they leave elementary school, Shouko and Shouya do not speak to each other again... until an older, wiser Shouya, tormented by his past behaviour, decides he must see Shouko once more. He wants to atone for his sins, but is it already too late...?', '2016-09-17', 8.40, 'https://image.tmdb.org/t/p/w500/tuFaWiqX0TXoWu7DGNcmX3UW7sT.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
