INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (380111, 'Flight Crew', 'A story about bravery, self-sacrifice and human dignity put on trial by the merciless power of nature. A young pilot is fired from military air force after disobeying an absurd order. He gets a job as a co-pilot with a civil airline. Being brutally honest and direct, he is not on best terms with his new colleagues. During a flight to Asia his crew receives a distress message from a volcanic island and makes a decision to attempt a rescue mission. Will it be a success? Will they survive the disaster? They have a single chance to find that out: by being a team and sticking up for one another.', '2016-04-21', 6.92, 'https://image.tmdb.org/t/p/w500/nL1WhzLiD2nZ7ixQcp5K0z4eEB7.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (379990, 'Anything for Love', 'Katherine, a high-powered executive who believes men are intimidated by her career, is persuaded by her friend to create an internet dating profile claiming she is an executive assistant.', '2016-02-14', 6.02, 'https://image.tmdb.org/t/p/w500/jvKECIiRF6qSp6LOXKfkuw1XpIO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (380254, 'Sori: Voice from the Heart', 'While desperately searching for his missing daughter, Hae-kwan comes across an AI satellite robot that remembers sounds from all over the world. Rejuvenated by the robot''s abilities, Hae-kwan begins to track down his daughter''s voice. As they continue their journey, they form an unforgettable bond.', '2016-01-27', 6.70, 'https://image.tmdb.org/t/p/w500/ssSm8ZpOdKffynphV0z2ENYUNwm.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
