INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (353609, 'Santa''s Little Helper', 'After getting fired from his job, a slick, fast-talking businessman is thrown into an elf competition to become Santa¹s next second-in-command. Put through a series of rigorous training exercises to prepare for the contest, The Miz and another aspiring elf go head-to-head in the hopes of becoming Santa¹s Little Helper.', '2015-11-17', 5.40, 'https://image.tmdb.org/t/p/w500/dtycBCVRO4elSb0umqJm8PTXIla.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (381064, 'American Fable', 'When 11-year-old Gitty discovers that her father, Abe, a good and beloved farmer, is holding a wealthy man hostage in their abandoned silo in order to save their suffering farm, she befriends the captive in secret. As the truth unfolds about who he is and what will happen if he escapes, Gitty chooses to confront the thin line between reality and fiction.', '2017-02-17', 6.05, 'https://image.tmdb.org/t/p/w500/5D1dsGCh09cJlla924hnVYror6z.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
