INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (381284, 'Hidden Figures', 'The untold story of Katherine G. Johnson, Dorothy Vaughan and Mary Jackson – brilliant African-American women working at NASA and serving as the brains behind one of the greatest operations in history – the launch of astronaut John Glenn into orbit. The visionary trio crossed all gender and race lines to inspire generations to dream big.', '2016-12-10', 8.05, 'https://image.tmdb.org/t/p/w500/9lfz2W2uGjyow3am00rsPJ8iOyq.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
