INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (371759, 'Doctor Who: The Husbands of River Song', 'It’s Christmas Day on a remote human colony and the Doctor is hiding from Christmas Carols and Comedy Antlers. But when a crashed spaceship calls upon the Doctor for help, he finds himself recruited into River Song’s squad and hurled into a fast and frantic chase across the galaxy. King Hydroflax is furious, and his giant Robot bodyguard is out-of-control and coming for them all! Will Nardole survive? And when will River Song work out who the Doctor is? All will be revealed on a starliner full of galactic super-villains and a destination the Doctor has been avoiding for a very long time.', '2015-12-25', 7.97, 'https://image.tmdb.org/t/p/w500/ettlSCoR5YhEoXx5b7JWwzstASz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
