INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (393764, 'The African Doctor', '1975. When Seyolo Zantoko, a doctor from the Congo who has managed, along with his family, to flee tyranny, is hired by the mayor of a small town in northern France, he begins a struggle to adapt to a new life and gain the trust of the prejudiced villagers.', '2016-06-08', 6.80, 'https://image.tmdb.org/t/p/w500/7I7AxQAlvufEg2aWFd2HbS4f47B.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (392820, 'Gimme Danger', 'No other band in rock''n''roll history has rivaled The Stooges'' combination of heavy primal throb, spiked psychedelia, blues-a-billy grind, complete with succinct angst-ridden lyrics, and a snarling, preening leopard of a frontman who somehow embodies Nijinsky, Bruce Lee, Harpo Marx, and Arthur Rimbaud all rolled into one. There is no precedent for The Stooges, while those inspired by them are now legion.  The film will present the context of their emergence musically, culturally, politically, historically, and relate their adventures and misadventures while charting their inspirations and the reasons behind their initial commercial challenges, as well as their long-lasting legacy.', '2016-08-05', 6.87, 'https://image.tmdb.org/t/p/w500/8YHqUETRBIFza756s8kcuU8XhEQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
