INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (397422, 'Rough Night', 'Five best friends from college reunite 10 years later for a wild bachelorette weekend in Miami. Their hard partying takes a hilariously dark turn when they accidentally kill a male stripper. Amidst the craziness of trying to cover it up, they''re ultimately brought closer together when it matters most.', '2017-06-15', 5.70, 'https://image.tmdb.org/t/p/w500/i66xbL1C6FEWDm2KoX11DHmP4Rz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
