INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (398818, 'Call Me by Your Name', 'In the summer of 1983, a 17-year-old Elio spends his days in his family''s villa in Italy. One day Oliver, a graduate student, arrives to assist Elio''s father, a professor of Greco-Roman culture. Soon, Elio and Oliver discover a summer that will alter their lives forever.', '2017-10-01', 8.08, 'https://image.tmdb.org/t/p/w500/mZ4gBdfkhP9tvLH1DO4m4HYtiyi.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (389053, 'The Do-Over', 'The life of a bank manager is turned upside down when a friend from his past manipulates him into faking his own death and taking off on an adventure.', '2016-05-27', 5.71, 'https://image.tmdb.org/t/p/w500/z9VCm2E6gCAwbM2SELRawfqdXBO.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (371859, 'The Death of Louis XIV', 'August 1715. After going for a walk, Louis XIV feels a pain in his leg. The next days, the king keeps fulfilling his duties and obligations, but his sleep is troubled and he has a serious fever. He barely eats and weakens increasingly. This is the start of the slow agony of the greatest king of France, surrounded by his relatives and doctors.', '2016-11-02', 6.53, 'https://image.tmdb.org/t/p/w500/uEgmmAnz5qlW43XFeGbcjI1wrAz.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (386891, 'Kicking Off', 'Kicking Off starts with the most important game of the season. Loyal fans Wigsy and Cliff watch in trepidation as their football team score the goal that will save them from relegation. Victory is bliss as a chorus of supporters chant and cry with elation. However, this frenzy of happiness quickly turns ugly as the referee disallows the deciding goal. With their hearts and fists pumping, adrenalin running and fury racing through their bloodstream, the fans take matters into their own hands and Cliff makes the fatal mistake of planning while intoxicated. Wigsy, a confirmed idiot, follows through with the said plan and in the darkest hours of the night he commits a crime that will cause chaos and catastrophe for him and his best mate Cliff. Kicking Off is cleverly filmed with split screen shots and slow motion montages. The characters are lovable thugs who will leave you laughing and grimacing at their lack of common sense.  The beautiful game just got ugly.', '2015-09-30', 3.50, 'https://image.tmdb.org/t/p/w500/pHzVWzyyBHNil44ge1aMYqGlcSx.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (371645, 'Hunt for the Wilderpeople', 'Ricky is a defiant young city kid who finds himself on the run with his cantankerous foster uncle in the wild New Zealand bush. A national manhunt ensues, and the two are forced to put aside their differences and work together to survive.', '2016-01-22', 7.64, 'https://image.tmdb.org/t/p/w500/hkmz9rxgcweizXNElozGeKwmAJE.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
