INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (398854, 'A Midsummer Night''s Dream', 'At the tyrannical court of Athens, pitiless dictator Theseus plans his wedding to Hippolyta, a prisoner of war, while young Hermia is sentenced to death by her own father for loving the wrong man. Meanwhile, in the town below, an amateur theatre group rehearses. And beyond Athens, in the wild woods, dark forces are stirring...', '2016-05-30', 5.24, 'https://image.tmdb.org/t/p/w500/8IcjnuBXAbmS75wqcGb9WYqSTY.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
