INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (403232, 'Vigilante Diaries', 'The Vigilante Diaries is a high octane action-adventure film featuring 90''s movie heroes, explosive action, and international espionage. The film revolves around a team of black-ops agents turned crime-fighters, led by a brooding anti-hero, known only as "The Vigilante." These jam-packed missions of rescue and revenge take us from the mega-mansions and underbelly of Los Angeles to far away places like Iraq, Armenia, Russia, and The United Kingdom to introduce us to a cast of colorful, dangerous, and hilarious characters. From Beverly Hills filmmaker Mike Hanover, to a trio of Asian femme fatales, to ruthless Armenian mobsters, and at the top, a pair of deep cover super spies hell bent on throwing the world into chaos.', '2016-09-01', 4.28, 'https://image.tmdb.org/t/p/w500/g3Cvy8zoa1GIvin213cAvPaXlHw.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
