INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (413362, 'Roman J. Israel, Esq.', 'Hard-nosed liberal lawyer Roman J. Israel has been fighting the good fight forever while others take the credit. When his partner – the firm''s frontman – has a heart attack, Israel suddenly takes on that role. He soon discovers some unsettling truths about the firm – truths that conflict with his values of helping the poor and dispossessed – and finds himself in an existential crisis that leads to extreme actions.', '2017-11-17', 6.34, 'https://image.tmdb.org/t/p/w500/epTCHVcyLkT8Aqt08Ki3PWC2sUh.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (413279, 'Team Thor', 'Discover what Thor was up to during the events of Captain America: Civil War.', '2016-08-28', 7.20, 'https://image.tmdb.org/t/p/w500/hpHvGuMc46pppwpcW0Xk7eys3L4.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (390734, 'Kingsglaive: Final Fantasy XV', 'The magical kingdom of Lucis is home to the world’s last remaining Crystal, and the menacing empire of Niflheim is determined to steal it. King Regis of Lucis commands an elite force of soldiers called the Kingsglaive. Wielding their king’s magic, they fight to protect Lucis. As the overwhelming military might of the empire bears down, King Regis is faced with an impossible ultimatum – to marry his son, Prince Noctis to Princess Lunafreya of Tenebrae, captive of Niflheim, and surrender his lands to Niflheim rule.  Although the king concedes, it becomes clear that the empire will stop at nothing to achieve their devious goals, with only the Kingsglaive standing between them and world domination.', '2016-07-09', 6.77, 'https://image.tmdb.org/t/p/w500/xGMgspge6uYoypRiasAmlluDlXH.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (399174, 'Isle of Dogs', 'In the future, an outbreak of canine flu leads the mayor of a Japanese city to banish all dogs to an island used as a garbage dump. The outcasts must soon embark on an epic journey when a 12-year-old boy arrives on the island to find his beloved pet.', '2018-03-23', 7.84, 'https://image.tmdb.org/t/p/w500/c0nUX6Q1ZB0P2t1Jo6EeFSVnOGQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (390410, 'Shadow World', 'A detailed investigation into the political and economic interests that, since the beginning of the 20th century, have pulled the strings of the arms trade, hidden in the shadows, feeding the shameful corruption of politicians and government officials and promoting a state of permanent war throughout the world, while they cynically asked for a lasting and universal peace.', '2016-10-14', 7.60, 'https://image.tmdb.org/t/p/w500/xPbgP2Ii8SJkxnTWl3QBn7pgEgR.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (390587, 'Tiger Raid', 'While on a covert mission, two cold blooded mercenaries form an unlikely bond as they race across the desert in the dead of night. When their violent and desperate world implodes, past atrocities come to the surface threatening to tear each of them apart.', '2016-10-07', 4.47, 'https://image.tmdb.org/t/p/w500/V61ycPJYjdYadFVVK51xaWYvr8.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (399404, 'Darkest Hour', 'In May 1940, the fate of World War II hangs on Winston Churchill, who must decide whether to negotiate with Adolf Hitler or fight on knowing that it could mean the end of the British Empire.', '2017-11-22', 7.35, 'https://image.tmdb.org/t/p/w500/xa6G3aKlysQeVg9wOb0dRcIGlWu.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (419831, 'I Kill Giants', 'Sophia, a new high school student, tries to make friends with Barbara, who tells her that “she kills giants,” protecting this way her hometown and its inhabitants, who do not understand her strange behavior.', '2017-11-15', 6.17, 'https://image.tmdb.org/t/p/w500/cvit6HDbXHE6W5kGPd47jd0wthQ.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (420707, 'Cage Dive', 'Three friends from California are filming an audition tape for an extreme reality game show. They document their journey to Australia where they will be doing their most dangerous activity: Shark Cage Diving. A catastrophic turn of events leaves them in baited water full of Great White Sharks, turning their recording into a blood chilling diary of survival...And death.', '2017-08-11', 4.59, 'https://image.tmdb.org/t/p/w500/3uUO9eDxHeDREIX77BaQiI88ajp.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
