INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (429189, 'Wonder Wheel', 'The story of four characters whose lives intertwine amid the hustle and bustle of the Coney Island amusement park in the 1950s: Ginny, an emotionally volatile former actress now working as a waitress in a clam house; Humpty, Ginny’s rough-hewn carousel operator husband; Mickey, a handsome young lifeguard who dreams of becoming a playwright; and Carolina, Humpty’s long-estranged daughter, who is now hiding out from gangsters at her father’s apartment.', '2017-12-01', 6.37, 'https://image.tmdb.org/t/p/w500/gKYpAL1A01T9a1taGXAyfqXjI5x.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
