INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (429733, 'Mayhem', 'A virus spreads through an office complex causing white collar workers to act out their worst impulses.', '2017-11-10', 6.45, 'https://image.tmdb.org/t/p/w500/yFmzgX2YLWnsCi1csyKPNBHPVYB.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (427641, 'Rampage', 'Primatologist Davis Okoye shares an unshakable bond with George, the extraordinarily intelligent, silverback gorilla who has been in his care since birth.  But a rogue genetic experiment gone awry mutates this gentle ape into a raging creature of enormous size.  To make matters worse, it’s soon discovered there are other similarly altered animals.  As these newly created alpha predators tear across North America, destroying everything in their path, Okoye teams with a discredited genetic engineer to secure an antidote, fighting his way through an ever-changing battlefield, not only to halt a global catastrophe but to save the fearsome creature that was once his friend.', '2018-04-11', 6.47, 'https://image.tmdb.org/t/p/w500/MGADip4thVSErP34FAAfzFBTZ5.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (400411, 'Satanic', 'Four friends on their way to Coachella stop off in Los Angeles to tour true-crime occult sites, only to encounter a mysterious young runaway who puts them on a terrifying path to ultimate horror.', '2016-07-01', 4.30, 'https://image.tmdb.org/t/p/w500/me74BRzuDvzD5LuAPU4EZOJtsyU.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (413594, 'Sword Art Online the Movie: Ordinal Scale', 'In 2026, a new machine called the Augma is developed to compete against the NerveGear and its successor, the Amusphere. A next-gen wearable device, the Augma doesn''t have a full-dive function like its predecessors. Instead, it uses Augmented Reality to get players into the game. It is safe, user-friendly and lets users play while they are conscious, making it an instant hit on the market. The most popular game on the system is “Ordinal Scale” an ARMMORPG developed exclusively for the Augma. Asuna and the gang have already been playing OS for a while, by the time Kirito decides to join them. They’re about to find out that Ordinal Scale isn’t all fun and games…', '2017-02-18', 7.70, 'https://image.tmdb.org/t/p/w500/2szdEK0Mr0RG0nWGFVTseNQHbnP.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (430214, 'Night Is Short, Walk On Girl', 'As a group of university students go out for a night on the town, a sophomore known only as "The Girl with Black Hair" experiences a series of surreal encounters with the local nightlife – all the while unaware of the romantic longings of "Senpai", a senior student who has been creating increasingly fantastic and contrived reasons to run into her in an effort to win her heart.', '2017-04-07', 7.40, 'https://image.tmdb.org/t/p/w500/cDp45WZNqgAli3u4GTnUhsqFn5K.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
