INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (433410, 'Self-Criticism of a Bourgeois Dog', 'The story of the dog from the title, who in a frame narrative explains how he came to be transformed from an unemployed communist filmmaker into a canine with a philosophical bent.  Unable to finance his new project, young Berlin-based director Julian tells foreign exchange student Camille that his job in the countryside is research for an upcoming film. When Camille offers to help, he is forced to uphold the lie. The plantation isn’t the proletarian idyll he had hoped for, but fortunately the reincarnation of Francis of Assisi provides spiritual insight and a new aim in life.', '2017-01-29', 6.47, 'https://image.tmdb.org/t/p/w500/uAW4PUgiafKGPXUfn0gr3Qr096p.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
