INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (445030, 'No Game No Life: Zero', 'Six thousand years before Sora and Shiro were even a blink in the history of Disboard, war consumed the land, tearing apart the heavens, destroying stars, and even threatening to wipe out the human race. Amid the chaos and destruction, a young man named Riku leads humanity toward the tomorrow his heart believes in. One day, in the ruins of an Elf city, he meets Schwi, a female exiled "Ex Machina" android who asks him to teach her what it means to have a human heart.', '2017-07-15', 7.83, 'https://image.tmdb.org/t/p/w500/cCBB6BGRj5nCTaEgogDtkHfjOLK.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (483455, 'Bungo Stray Dogs: Dead Apple', 'A large scale catastrophe is occurring across the planet. Ability users are discovered after the appearance of a mysterious fog, apparently having committed suicide, so the Armed Detective Agency sets out to investigate these mysterious deaths. The case seems to involve an unknown ability user referred to as "Collector," a man who could be the mastermind behind the incident.INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (487156, 'Judd Apatow: The Return', 'Renowned producer, director and writer Judd Apatow makes his long-awaited return to stand-up comedy with this new special shot in Montreal.', '2017-12-12', 6.26, 'https://image.tmdb.org/t/p/w500/h83KVdM6UMJplVA8jgXWk60Kk1Y.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
INSERT INTO movies (tmdb_id, title, description, release_date, average_rating, poster_url) VALUES (445571, 'Game Night', 'Max and Annie''s weekly game night gets kicked up a notch when Max''s brother Brooks arranges a murder mystery party -- complete with fake thugs and federal agents. So when Brooks gets kidnapped, it''s all supposed to be part of the game. As the competitors set out to solve the case, they start to learn that neither the game nor Brooks are what they seem to be. The friends soon find themselves in over their heads as each twist leads to another unexpected turn over the course of one chaotic night.', '2018-02-15', 6.85, 'https://image.tmdb.org/t/p/w500/85R8LMyn9f2Lev2YPBF8Nughrkv.jpg') ON CONFLICT (tmdb_id) DO NOTHING;
